const CHAPTERS = [{"number": 1, "title": "霧の中の名前", "scenes": [{"scene": 1, "title": "朝霧の目覚め", "wordCount": "約4,800字"}, {"scene": 2, "title": "黙祷の鐘", "wordCount": "約5,500字"}, {"scene": 3, "title": "食堂の光", "wordCount": "約6,200字"}, {"scene": 4, "title": "機構室の氷", "wordCount": "約5,200字"}, {"scene": 5, "title": "着任の日", "wordCount": "約4,200字"}, {"scene": 6, "title": "天蓋の間の少女", "wordCount": "約6,200字"}]}, {"number": 2, "title": "灯籠通りの声", "scenes": [{"scene": 1, "title": "共鳴者訓練棟の前で", "wordCount": "約5,000字"}, {"scene": 2, "title": "親友の影", "wordCount": "約4,000字"}, {"scene": 3, "title": "記録室の少女", "wordCount": "約6,000字"}, {"scene": 4, "title": "残響の集い", "wordCount": "約6,000字"}, {"scene": 5, "title": "歌と問い", "wordCount": "約4,000字"}]}, {"number": 3, "title": "記録と忘却", "scenes": [{"scene": 1, "title": "消えた人々のリスト", "wordCount": "約6,100字"}, {"scene": 2, "title": "差し入れの味", "wordCount": "約5,200字"}, {"scene": 3, "title": "残響祭の準備", "wordCount": "約5,900字"}, {"scene": 4, "title": "桜の下の弁当", "wordCount": "約4,100字"}, {"scene": 5, "title": "記録室の夕暮れ", "wordCount": "約5,100字"}]}, {"number": 4, "title": "残響祭の灯り", "scenes": [{"scene": 1, "title": "祭りの朝", "wordCount": "約4,100字"}, {"scene": 2, "title": "記録展示と静かな手", "wordCount": "約4,000字"}, {"scene": 3, "title": "舞台裏の千歳", "wordCount": "約4,000字"}, {"scene": 4, "title": "歌声の奇跡", "wordCount": "約5,000字"}, {"scene": 5, "title": "鐘鋳塔の明かり", "wordCount": "約4,000字"}, {"scene": 6, "title": "残響桜のライトアップ", "wordCount": "約5,000字"}, {"scene": 7, "title": "楽しかった、のだろうか", "wordCount": "約4,000字"}]}, {"number": 5, "title": "夏の入り口", "scenes": [{"scene": 1, "title": "梅雨の機構室", "wordCount": "約6,000字"}, {"scene": 2, "title": "知っている気がする人", "wordCount": "約6,200字"}, {"scene": 3, "title": "雨の図書館", "wordCount": "約4,200字"}, {"scene": 4, "title": "灯里村の名前", "wordCount": "約5,100字"}, {"scene": 5, "title": "過去への問い", "wordCount": "約5,200字"}]}, {"number": 6, "title": "鐘の音の下で", "scenes": [{"scene": 1, "title": "共鳴室", "wordCount": "約6,000字"}, {"scene": 2, "title": "いろはの視線", "wordCount": "約4,000字"}, {"scene": 3, "title": "せかいのおわり", "wordCount": "約5,000字"}, {"scene": 4, "title": "夏期研修の知らせ", "wordCount": "約4,000字"}, {"scene": 5, "title": "夕焼けの訓練棟", "wordCount": "約6,000字"}]}, {"number": 7, "title": "夏の残響", "scenes": [{"scene": 1, "title": "夏の海", "wordCount": "約5,200字"}, {"scene": 2, "title": "灯篭に書く名前", "wordCount": "約6,000字"}, {"scene": 3, "title": "思い出せない名前", "wordCount": "約6,100字"}, {"scene": 4, "title": "蓮さん", "wordCount": "約5,500字"}, {"scene": 5, "title": "ありがとうございます", "wordCount": "約4,100字"}, {"scene": 6, "title": "夏の終わりのモノローグ", "wordCount": "約3,900字"}]}, {"number": 8, "title": "秋風と距離", "scenes": [{"scene": 1, "title": "体育祭の風", "wordCount": "約5,500字"}, {"scene": 2, "title": "燈花", "wordCount": "約5,200字"}, {"scene": 3, "title": "人事ファイル", "wordCount": "約5,000字"}, {"scene": 4, "title": "深入りするな", "wordCount": "約5,000字"}, {"scene": 5, "title": "秋の空気", "wordCount": "約5,000字"}]}, {"number": 9, "title": "記録室の静寂", "scenes": [{"scene": 1, "title": "消えた人々の声", "wordCount": "約5,800字"}, {"scene": 2, "title": "ルミエラ島", "wordCount": "約5,200字"}, {"scene": 3, "title": "秋の収穫", "wordCount": "約4,800字"}, {"scene": 4, "title": "無理させないで", "wordCount": "約5,100字"}, {"scene": 5, "title": "記録室の約束", "wordCount": "約5,000字"}]}, {"number": 10, "title": "霜月の技師", "scenes": [{"scene": 1, "title": "深夜の点検", "wordCount": "約5,800字"}, {"scene": 2, "title": "晶さん", "wordCount": "約4,200字"}, {"scene": 3, "title": "とおいしまの音", "wordCount": "約5,200字"}, {"scene": 4, "title": "観測データの異常", "wordCount": "約5,100字"}, {"scene": 5, "title": "月と鐘", "wordCount": "約5,100字"}]}, {"number": 11, "title": "歌と命の天秤", "scenes": [{"scene": 1, "title": "選抜公演", "wordCount": "約5,200字"}, {"scene": 2, "title": "楽屋の崩壊", "wordCount": "約5,100字"}, {"scene": 3, "title": "いろはの告白", "wordCount": "約6,200字"}, {"scene": 4, "title": "蓮の怒り", "wordCount": "約5,200字"}, {"scene": 5, "title": "アナザービュー：いろはの祈り", "wordCount": "約4,000字"}, {"scene": 6, "title": "眠れない夜", "wordCount": "約5,200字"}]}, {"number": 12, "title": "冬の足音", "scenes": [{"scene": 1, "title": "消えた農家", "wordCount": "約5,100字"}, {"scene": 2, "title": "消滅した場所", "wordCount": "約6,200字"}, {"scene": 3, "title": "燈花の涙", "wordCount": "約5,200字"}, {"scene": 4, "title": "5年前と同じ", "wordCount": "約5,100字"}, {"scene": 5, "title": "追悼祭の名簿", "wordCount": "約4,200字"}]}, {"number": 13, "title": "鐘が揺れる夜", "scenes": [{"scene": 1, "title": "鐘の異変", "wordCount": "約6,200字"}, {"scene": 2, "title": "共鳴者への要請", "wordCount": "約5,200字"}, {"scene": 3, "title": "すみれの苦痛", "wordCount": "約5,400字"}, {"scene": 4, "title": "果樹園の記憶", "wordCount": "約5,200字"}, {"scene": 5, "title": "アナザービュー：すみれの祈り", "wordCount": "約4,200字"}]}, {"number": 14, "title": "境界の向こう", "scenes": [{"scene": 1, "title": "第一監視哨", "wordCount": "約6,200字"}, {"scene": 2, "title": "晶の告白", "wordCount": "約6,100字"}, {"scene": 3, "title": "アナザービュー：晶の守護", "wordCount": "約4,800字"}, {"scene": 4, "title": "崩れる外円区", "wordCount": "約5,200字"}, {"scene": 5, "title": "二つの嵐", "wordCount": "約4,400字"}]}, {"number": 15, "title": "縁蝕波", "scenes": [{"scene": 1, "title": "世界が震える", "wordCount": "約6,100字"}, {"scene": 2, "title": "千歳の歌、命の炎", "wordCount": "約6,200字"}, {"scene": 3, "title": "外円区の灯", "wordCount": "約5,100字"}, {"scene": 4, "title": "透ける手", "wordCount": "約5,200字"}, {"scene": 5, "title": "氷華の反逆、すみれの告知", "wordCount": "約5,300字"}, {"scene": 6, "title": "アナザービュー群：それぞれの嵐", "wordCount": "約3,000字"}]}, {"number": 16, "title": "誰の側に", "scenes": [{"scene": 1, "title": "嵐の後", "wordCount": "約4,200字"}, {"scene": 2, "title": "千歳の決意", "wordCount": "約5,200字"}, {"scene": 3, "title": "雫の揺らぎ", "wordCount": "約5,900字"}, {"scene": 4, "title": "燈花の帰還", "wordCount": "約5,100字"}, {"scene": 5, "title": "氷華の宣言", "wordCount": "約5,000字"}, {"scene": 6, "title": "蓮の覚醒", "wordCount": ""}, {"scene": 7, "title": "アナザービュー群：5つの声", "wordCount": "約3,800字"}, {"scene": 8, "title": "分岐点――誰の側に", "wordCount": "約6,200字"}]}];

const SCENES = [{"chapter": 1, "chapterTitle": "霧の中の名前", "scene": 1, "sceneTitle": "朝霧の目覚め", "wordCount": "約4,800字", "paragraphs": [{"id": "ch01-s01-p001", "type": "text", "text": "目が覚める、という感覚がある。"}, {"id": "ch01-s01-p002", "type": "text", "text": "まぶたの裏に張りついていた闇が薄くなって、窓ガラスの向こうの白い光がじわりと滲んでくる。布団の中。温もり。体温の残りかすのような熱が、首筋から肩のあたりを包んでいる。"}, {"id": "ch01-s01-p003", "type": "text", "text": "出たくない、と思った。"}, {"id": "ch01-s01-p004", "type": "text", "text": "たぶん、そう思うのが正しいから。四月の朝は暖かくなりかけていて、けれど布団の外はまだ少し冷える。だから出たくない。理屈としては合っている。合っているはずだ。"}, {"id": "ch01-s01-p005", "type": "text", "text": "ただ、本当に温かいと感じているのか。それとも「温かいはずだ」と判断しているだけなのか。その境目が、いつも曖昧だった。"}, {"id": "ch01-s01-p006", "type": "text", "text": "体を起こす。肩が布団から出ると、冷えた空気が肌に触れた。四月上旬の朝の空気は、こういうものだろう。背筋を伸ばし、足を床に下ろす。木の床板は冷たい。足の裏がそれを報告してくる。冷たいですよ、と。"}, {"id": "ch01-s01-p007", "type": "text", "text": "窓の外は、白かった。"}, {"id": "ch01-s01-p008", "type": "text", "text": "霧だ。アルケミラ島の春の朝霧。白い霧が地表を這い、向かいの教室棟の屋根をぼんやりとした輪郭に変えている。残響桜の枝が霧に溶けかけて、花弁の薄紫だけが色を持って浮かんでいた。花弁のいくつかが風もないのにゆっくりと落ちる。霧の中に紫の点が散って、消えた。"}, {"id": "ch01-s01-p009", "type": "text", "text": "朝霧。"}, {"id": "ch01-s01-p010", "type": "text", "text": "俺はその言葉を、頭の中で転がした。"}, {"id": "ch01-s01-p011", "type": "text", "text": "朝霧蓮。それが俺の名前だ。二年前に外円区の縁際で目を覚ました時、最初に見たのが朝の霧だった。名前はなかった。記憶がなかったから。顔も、年齢も、どこから来たのかも。何も持っていなかった。"}, {"id": "ch01-s01-p012", "type": "text", "text": "だから自分でつけた。朝霧蓮。縁際の監視哨で書類に名前を書く欄があって、空白のまま出すわけにもいかず、あの朝の霧のことを思い出した。意味があってつけたわけではない。霧はただそこにあっただけだ。名前も、ただここに書いただけだ。"}, {"id": "ch01-s01-p013", "type": "text", "text": "蓮の字は、監視哨の備品室にあった植物図鑑から取った。ぱらぱらとめくって、最初に止まったページに載っていた花。泥の中から茎を伸ばして咲く、あの花。泥の中でもきれいに咲く、と説明に書いてあったのを覚えている。そういう意味で選んだのかと聞かれたことがあるが、そうではない。ただ、字の形が目に入った。それだけだった。"}, {"id": "ch01-s01-p014", "type": "text", "text": "洗面台の鏡に顔が映る。"}, {"id": "ch01-s01-p015", "type": "text", "text": "暗い灰青色の短髪。寝癖が右のこめかみのあたりに一房跳ねている。直そうとして、濡らした手で押さえた。前髪が額に貼りつく。水に濡れた髪の隙間から、額の左側に薄い線が覗いた。傷跡。いつからあるのかわからない。二年前に発見された時には既にこうだった。痛みはない。触れても何も感じない。"}, {"id": "ch01-s01-p016", "type": "text", "text": "鏡の中の目は、濃い紺色をしている。光の加減で黒にも見える。自分の目だとわかっている。わかっているが、それ以上の何かがあるべきだという気がして、いつもつい長く見てしまう。何を探しているのか、自分でもわからないまま。"}, {"id": "ch01-s01-p017", "type": "text", "text": "手を拭いて、制服に袖を通す。"}, {"id": "ch01-s01-p018", "type": "text", "text": "濃紺のジャケット。灰色のシャツ。黒いスラックス。鐘守補佐の制服。左腕にバッジを留める。今日が聖鐘学院の鐘守補佐としての初出勤になる。縁際監視哨からの異動。配属辞令をもらった日のことを思い返してみるが、嬉しかったのか、不安だったのか、よく覚えていない。覚えていないのではなく、たぶん、どちらでもなかったのだと思う。辞令は紙の一枚で、俺はそれを受け取り、頷いた。それだけだった。"}, {"id": "ch01-s01-p019", "type": "text", "text": "ジャケットのボタンを留めながら、左手首に視線が落ちた。"}, {"id": "ch01-s01-p020", "type": "text", "text": "革のブレスレット。細い革紐が三本、編み込みの模様を作っている。使い込まれて色が濃くなり、ところどころ毛羽立っている。発見された時から身につけていた。俺が持っていた唯一のもの。名前も記憶もなかった俺の手首に、これだけが巻かれていた。"}, {"id": "ch01-s01-p021", "type": "text", "text": "外す理由がない。そう思っている。外す気にならない、と言うほうが正確だろうか。理由という言葉にすると何か足りない。けれど、それが何なのかはわからない。"}, {"id": "ch01-s01-p022", "type": "text", "text": "指先で編み目に触れる。一瞬だけ。それから手を離す。毎朝やっている。なぜ触れるのかも、なぜ一瞬で手を離すのかも、考えたことがなかった。"}, {"id": "ch01-s01-p023", "type": "text", "text": "窓の外の霧が、薄くなっていた。"}, {"id": "ch01-s01-p024", "type": "text", "text": "残響桜の輪郭がはっきりしてきた。薄紫の花が枝に重たげに咲いている。花弁が霧の水気を吸って、少し透けている。その奥に、鐘鋳塔のシルエットが見えた。"}, {"id": "ch01-s01-p025", "type": "text", "text": "白い石と、青みがかった金属。島の中心に立つ120メートルの円筒。上に向かって僅かに細くなっていくその形は、霧の中だと地面から天に向かって伸びる一本の柱のようだった。外壁の残響紋が朝の光を受けて、まだ発光はしていないのに、どこか生きているような質感を帯びている。"}, {"id": "ch01-s01-p026", "type": "text", "text": "俺は今日から、あの塔で働く。"}, {"id": "ch01-s01-p027", "type": "text", "text": "靴を履き、補佐官舎の玄関を出た。"}, {"id": "ch01-s01-p028", "type": "text", "text": "官舎は教室棟の裏にある小さな平屋で、一人で住むには十分な広さがある。十分、という感覚が正しいかどうかは別として。基準がないから。前の住まいは監視哨の共同宿舎で、二段ベッドの上段と、ロッカーひとつ分のスペースだった。それと比べれば広い。比べなければ、ただの部屋だ。"}, {"id": "ch01-s01-p029", "type": "text", "text": "外に出ると、霧が足元に纏わりついた。"}, {"id": "ch01-s01-p030", "type": "text", "text": "四月の朝の空気には湿気が含まれていて、吸い込むと鼻腔の奥にかすかな土の匂いがした。残響桜の花の匂いもある。甘い、のだろうか。嗅覚は匂いを検出しているが、それを「甘い」と分類すべきなのか、「優しい」と呼ぶべきなのか、うまく言葉にならない。匂いは名前をつけるのが難しい。"}, {"id": "ch01-s01-p031", "type": "text", "text": "煉瓦舗装の道を歩く。靴底が濡れた煉瓦を踏む音が、霧に吸われて遠くまで届かない。自分の足音だけが、近い。"}, {"id": "ch01-s01-p032", "type": "text", "text": "道の両側に灯籠型の街灯が並んでいた。夜には灯るのだろうが、今は消えている。ガラスの中に油灯の燃え残りが見える。誰かが毎晩火を入れているのだ。そういう仕事をしている人がいて、そういう日常がここにはある。"}, {"id": "ch01-s01-p033", "type": "text", "text": "中円区の街並みが霧の中に浮かんでいた。洗濯物が軒先に干してある家。二階の窓がわずかに開いている家。煉瓦塀の上を猫が歩いている。その猫は俺を一瞬だけ見て、興味を失ったように塀の向こうに消えた。"}, {"id": "ch01-s01-p034", "type": "text", "text": "歩く。背筋は伸びている。監視哨にいた頃の癖が抜けない。蝕域を見張る勤務で身についた姿勢。視線が時折、遠くに飛ぶ。霧の向こうの景色を見透かそうとする。何を探しているわけでもないのに。ただ、遠くを見る目になってしまう。縁際にいた二年間で、俺の目はそういう形になった。"}, {"id": "ch01-s01-p035", "type": "text", "text": "鐘鋳塔が近づいてくる。"}, {"id": "ch01-s01-p036", "type": "text", "text": "霧が少し晴れて、塔の下半分が見えた。残響紋の彫りの深さがわかる。指の腹で触れたら、きっとざらりとした感触がある。あの紋様が鐘の音を増幅して島中に届ける。俺はそれを知識として知っている。知識と、実感のあいだに、いつも隙間がある。"}, {"id": "ch01-s01-p037", "type": "text", "text": "塔の前の道を歩いている時だった。"}, {"id": "ch01-s01-p038", "type": "text", "text": "鐘が、鳴った。"}, {"id": "ch01-s01-p039", "type": "text", "text": "六時半。朝の最初の鐘。"}, {"id": "ch01-s01-p040", "type": "text", "text": "低い音が、空気を震わせた。腹の底に響くような振動。それが一拍遅れて高い倍音に分かれ、空に広がっていく。音の粒が霧の中を走り、水滴に当たるたびに細かく屈折して、どこまでも拡がっていく。鐘鋳塔の外壁の残響紋が、淡い、本当に淡い光を灯した。朝霧の白に、蒼白い光の線が走る。"}, {"id": "ch01-s01-p041", "type": "text", "text": "足が止まった。"}, {"id": "ch01-s01-p042", "type": "text", "text": "鐘の音は五分間続く。一日八回。蝕域の侵食を基準速度に抑える最低限の防衛ライン。そういうものだと頭では理解している。"}, {"id": "ch01-s01-p043", "type": "text", "text": "けれど。"}, {"id": "ch01-s01-p044", "type": "text", "text": "音が、体の中を通り過ぎていく。耳から入るだけではない。胸骨が振動している。指先が微かに痺れる。足の裏から地面を伝って、鐘の残響が全身に染みていくような感覚。"}, {"id": "ch01-s01-p045", "type": "text", "text": "心地よい。"}, {"id": "ch01-s01-p046", "type": "text", "text": "そう感じていた。なぜだかわからない。鐘の音を心地よいと感じる理由が、俺にはない。監視哨で聴いていた鐘の音は遠く、薄く、ほとんど聞こえないこともあった。こんなに近くで聴くのは、もしかしたら初めてかもしれない。初めてなのに、懐かしいと思うのはおかしい。"}, {"id": "ch01-s01-p047", "type": "text", "text": "……懐かしい。"}, {"id": "ch01-s01-p048", "type": "text", "text": "その言葉が、不意に浮かんで消えた。鐘の二打目が鳴る。音が重なり、空気が厚くなる。霧の中の残響桜の花弁が、音の振動で僅かに揺れた。薄紫の点がいくつか舞い上がり、鐘の音に乗って漂っていく。"}, {"id": "ch01-s01-p049", "type": "text", "text": "懐かしい、と思った理由は、自分でもわからなかった。記憶にないものを懐かしいと思えるのか。思えるのだとしたら、それは記憶ではなく、もっと深いどこかにある何かが反応しているのか。"}, {"id": "ch01-s01-p050", "type": "text", "text": "考えても答えは出ない。"}, {"id": "ch01-s01-p051", "type": "text", "text": "鐘の三打目。四打目。音の層が積み重なって、世界が音で満ちている。霧が光を含んで白く輝く。残響紋の光が塔の外壁を細い線となって駆け上がっていく。その光の筋を、俺は見上げていた。"}, {"id": "ch01-s01-p052", "type": "text", "text": "首筋が鈍く痛む。見上げ続けたせいだろう。"}, {"id": "ch01-s01-p053", "type": "text", "text": "五分間の鐘打ちが終わった。最後の打音の残響が、長い尾を引いて霧の中に溶けていく。音が消えると、世界は静かになった。残響紋の光が薄れ、朝の光だけが残る。霧が再びゆっくりと地面を這い始める。"}, {"id": "ch01-s01-p054", "type": "text", "text": "呼吸を、していなかった。"}, {"id": "ch01-s01-p055", "type": "text", "text": "鐘が鳴っている間、息を止めていたことに気づく。意識してやったことではない。体が勝手にそうした。鐘の音を、一粒も逃したくないとでもいうように。"}, {"id": "ch01-s01-p056", "type": "text", "text": "息を吐いた。白い息が霧と混ざった。"}, {"id": "ch01-s01-p057", "type": "text", "text": "……そうか。"}, {"id": "ch01-s01-p058", "type": "text", "text": "心地よかったのか。そうかもしれない。"}, {"id": "ch01-s01-p059", "type": "text", "text": "確信は持てない。持てないが、さっきまでの「温かいかどうかわからない」布団の中の感覚より、ほんの少しだけ明瞭な何かがあった。鐘の音は確かにそこに在って、俺の体を通り抜けていった。それは否定しようのない事実で、その事実に紐づいた何かの感覚が、たぶん、心地よさだった。"}, {"id": "ch01-s01-p060", "type": "text", "text": "たぶん。"}, {"id": "ch01-s01-p061", "type": "text", "text": "歩き出す。鐘鋳塔はもうすぐそこにある。白い石壁の表面の残響紋に、朝日が斜めに当たって影を作っている。塔の正面に続く道は、霧の中でも迷いようがない。島の全てが、この塔を中心に作られているから。"}, {"id": "ch01-s01-p062", "type": "text", "text": "今日から、ここで働く。鐘を守る仕事。鐘の機構を整備し、音が途切れないようにする。蝕域の侵食を遅らせる音を、支える側の人間になる。"}, {"id": "ch01-s01-p063", "type": "text", "text": "そのことに、何かを感じるべきなのだろう。誇りとか、使命感とか、緊張とか。感じているのかもしれない。感じていないのかもしれない。どちらにしても、足は前に進んでいる。歩幅は一定で、靴底が煉瓦を踏む音は規則正しい。"}, {"id": "ch01-s01-p064", "type": "text", "text": "霧が晴れ始めていた。"}, {"id": "ch01-s01-p065", "type": "text", "text": "残響桜の花弁が、また一枚、風に乗って俺の前を横切った。薄紫。その色だけが、白い朝の中で唯一、確かな色をしていた。"}]}, {"chapter": 1, "chapterTitle": "霧の中の名前", "scene": 2, "sceneTitle": "黙祷の鐘", "wordCount": "約5,500字", "paragraphs": [{"id": "ch01-s02-p001", "type": "text", "text": "管理室に入ったのは、六時四十分だった。"}, {"id": "ch01-s02-p002", "type": "text", "text": "鐘の余韻が、まだ指先に残っていた。さっき塔の前で聴いた朝鐘の振動。それが爪の先から抜けきらないまま、俺は鐘鋳塔の正面入口で身分証を提示し、受付の記録簿に名前を書き、一階の管理室に通された。"}, {"id": "ch01-s02-p003", "type": "text", "text": "管理室は、塔の基部にあたる円形の空間を仕切った一画だった。石壁に沿って並ぶ計器類。真鍮の文字盤と、硝子管に封じられた青い液体と、針が微かに揺れ続けるメーター。壁面には塔の断面図が掛けられていて、各層の残響紋の配置が細い線で描き込まれている。机が二つ。椅子が三つ。棚に分厚いファイルが並び、背表紙には年号と系統番号が書かれている。"}, {"id": "ch01-s02-p004", "type": "text", "text": "配属初日の手続きは、拍子抜けするほど簡素だった。管理局の事務員が業務マニュアルと鍵を渡してくれて、基本的な計器の読み方を説明し、「あとは霜月技師の指示に従って」とだけ言って出ていった。それだけだった。"}, {"id": "ch01-s02-p005", "type": "text", "text": "マニュアルを開く。鐘鋳塔管理局補佐官業務規程。四章構成。勤務概要に始まり、運行監視、計器の読み取り、異常時の対応フロー。"}, {"id": "ch01-s02-p006", "type": "text", "text": "読み進める。計器の読み方のページで、手が止まった。"}, {"id": "ch01-s02-p007", "type": "text", "text": "真鍮の文字盤に刻まれた目盛り。音圧出力、残響紋導通率、位相差。文字を追う目が、意味を理解する前に、指がページの図解をなぞっていた。この配置は知っている。知っている、というのは正確ではない。マニュアルを今初めて読んでいるのだから。けれど、指が図解の上を滑る感触に、どこか馴染んだものがあった。歯車の噛み合わせの図。軸受けの断面。金属部品の配列。"}, {"id": "ch01-s02-p008", "type": "text", "text": "手を止める。"}, {"id": "ch01-s02-p009", "type": "text", "text": "知っている、のではない。ただ、読みやすい。機械の図面を読み解くことに、抵抗がない。監視哨でも簡単な機械の整備はやっていた。観測機器の清掃、部品の交換。そのたびに「手が先に動く」感覚があった。頭で考える前に指が正しい位置に伸びる。誰かに教わった記憶はない。二年前より前の記憶はないのだから、教わったとしてもわからない。"}, {"id": "ch01-s02-p010", "type": "text", "text": "気にしても仕方がないことだった。"}, {"id": "ch01-s02-p011", "type": "text", "text": "マニュアルを最後まで読み終え、計器の前に座った。ここが俺の定位置になる。真鍮の文字盤が六つ並ぶ監視パネル。一番左が第一系統、順に右へ。六系統まで。それぞれの針が、わずかな振幅で揺れ続けている。鐘が止まっている時間帯でも、残響紋には微弱な振動が残っている。その振動を拾って、針が動く。"}, {"id": "ch01-s02-p012", "type": "text", "text": "数値を読み取り、記録用紙に書き写す。第一系統、正常。第二系統、正常。第三系統。"}, {"id": "ch01-s02-p013", "type": "text", "text": "針の位置を読む。基準値の範囲内ではある。ただ、他の系統と比べて、振幅がわずかに小さい。0.3パーセント程度。誤差の範囲と言えなくもない。記録用紙に数値をそのまま書いた。判断は上に任せる。初日に余計なことを言う必要はない。"}, {"id": "ch01-s02-p014", "type": "text", "text": "七時を回った頃、管理室の小窓から外を見た。霧はほとんど晴れていた。鐘鋳塔から南西の方角に、聖鐘学院の校舎が見える。丘陵の中腹に建つ煉瓦造りの教室棟。壁面をツタが覆い、朝日を受けた葉が濡れた緑を光らせている。屋根の赤褐色と壁の煉瓦色が朝の光に温められて、遠くから見ると丘の上に暖かい色の塊が載っているように見えた。"}, {"id": "ch01-s02-p015", "type": "text", "text": "今日は始業式だと、事務員が言っていた。四月上旬。新年度。生徒約八百名が講堂に集まり、式典を行う。鐘鋳塔の朝鐘に合わせた黙祷が恒例だと。"}, {"id": "ch01-s02-p016", "type": "text", "text": "ただし、八時には定時の鐘打ちはない。六時半の次は九時半。始業式の黙祷は、六時半の鐘の残響に捧げる形式をとっている。朝鐘の音は既に消えているが、残響紋が記憶した振動は塔の石壁に微かに残り続ける。その「残った響き」に対して黙祷する。だから「残響への黙祷」と呼ばれている。"}, {"id": "ch01-s02-p017", "type": "text", "text": "残響。残った響き。"}, {"id": "ch01-s02-p018", "type": "text", "text": "六時半に聴いた鐘の音のことを、また思い出す。あの音が塔の壁に残っているのだと言われれば、否定はできない。俺の指先にも、まだ何かが残っている気がするのだから。"}, {"id": "ch01-s02-p019", "type": "text", "text": "八時が近づくにつれて、小窓の外の景色が変わった。学院の校門から生徒たちが中庭に出てくるのが見える。距離があるから顔は判別できないが、制服の色でわかる。濃紺のジャケット、灰色のシャツ。俺が着ているのと同じ型の制服。ただし鐘守補佐のバッジはない。"}, {"id": "ch01-s02-p020", "type": "text", "text": "中庭の中央に、残響桜の老木が一本立っていた。"}, {"id": "ch01-s02-p021", "type": "text", "text": "管理室の窓からでも、その大きさがわかる。幹が太い。枝が四方に広がって、中庭の半分近くを覆っている。薄紫の花が枝を重たくしていて、朝の光を受けた花弁が、白に近い薄紫から濃い藤色まで、微妙に色を変えている。学院に来てからこの木を見るのは初めてだったが、何年そこに立っているのかは、幹の太さが教えていた。百年か。もっとか。"}, {"id": "ch01-s02-p022", "type": "text", "text": "生徒たちが中庭に整列し始めた。列が作られていく。教員らしい人物が前に立ち、何かを話している。声はここまでは届かない。八百人が中庭に並ぶと、煉瓦の地面がほとんど見えなくなった。制服の紺色が地面を覆い、その上に残響桜の薄紫が覆い被さっている。"}, {"id": "ch01-s02-p023", "type": "text", "text": "八時になった。"}, {"id": "ch01-s02-p024", "type": "text", "text": "中庭の動きが、止まった。"}, {"id": "ch01-s02-p025", "type": "text", "text": "生徒たちが一斉に目を閉じた。全員ではないかもしれない。この距離からでは、まぶたの開閉までは見えない。けれど、八百の体が同時に静止する瞬間は、はっきりとわかった。さっきまでざわついていた中庭が、一枚の絵のように動かなくなる。"}, {"id": "ch01-s02-p026", "type": "text", "text": "黙祷。残響への黙祷。"}, {"id": "ch01-s02-p027", "type": "text", "text": "六時半の朝鐘の、もう聴こえない音に対して、八百人が目を閉じている。"}, {"id": "ch01-s02-p028", "type": "text", "text": "俺は管理室の窓越しにその光景を見ていた。目は開いたまま。黙祷に参加する義務は、管理局職員にはない。鐘の監視が業務だから。俺の仕事は祈ることではなく、計器の数値を見ることだ。そういう理屈で、目を開けている。"}, {"id": "ch01-s02-p029", "type": "text", "text": "理屈は合っている。"}, {"id": "ch01-s02-p030", "type": "text", "text": "窓の外の八百人は動かない。残響桜の枝先から花弁が一枚落ちた。誰の肩にも当たらず、整列した生徒たちの足元に落ちた。風がない。空気が止まっている。鐘鋳塔の壁面に残る振動だけが、計器の針を微かに揺らし続けている。"}, {"id": "ch01-s02-p031", "type": "text", "text": "みんな、何を祈っているのだろう。"}, {"id": "ch01-s02-p032", "type": "text", "text": "その疑問が浮かんで、消えなかった。"}, {"id": "ch01-s02-p033", "type": "text", "text": "祈る、という行為には対象がいる。誰かのために。何かのために。もう会えない人のために。まだ見ぬ未来のために。島を蝕域から守る鐘の音のために。そういう「ために」が、あの八百人の一人ひとりにあるのだろう。家族。友人。自分の将来。好きな人。失った人。"}, {"id": "ch01-s02-p034", "type": "text", "text": "俺の中には、ない。"}, {"id": "ch01-s02-p035", "type": "text", "text": "祈る対象がない。記憶がないから。誰かを思い浮かべて、その人のために何かを願う。そういう回路が、俺の中で繋がっていない。名前のない人のために祈ることはできない。顔のわからない誰かのために目を閉じても、まぶたの裏はただ暗いだけだ。"}, {"id": "ch01-s02-p036", "type": "text", "text": "今朝の鐘の音を思い出す。心地よかった、のだと思う。あの音は確かに俺の体を通った。けれど、あれが祈りに繋がるのかどうかはわからない。心地よい音を聴いたことと、誰かのために祈ることは、たぶん別のことだ。"}, {"id": "ch01-s02-p037", "type": "text", "text": "計器に目を戻す。針は揺れている。第三系統の振幅は、さっきと同じだった。数値は変わっていない。"}, {"id": "ch01-s02-p038", "type": "text", "text": "数値は変わらない。数値は祈らない。数値はただそこにある。"}, {"id": "ch01-s02-p039", "type": "text", "text": "その明瞭さに、安堵に似た何かを覚えた。数値は読み取れる。読み取って、記録できる。正常か異常かを判別できる。そこに曖昧さはない。祈りの意味がわからなくても、計器の前には座れる。針の動きは読める。それが俺の仕事で、仕事は俺に場所を与えてくれる。"}, {"id": "ch01-s02-p040", "type": "text", "text": "管理室の机の上に、自分が書いた記録用紙が並んでいた。六時五十分から三十分おきに記録した数値の列。筆跡は均一で、数字はまっすぐ並んでいる。監視哨で観測記録をつけていた頃と同じ書き方をしている。指が覚えている書き方。"}, {"id": "ch01-s02-p041", "type": "text", "text": "ここが、俺の場所だ。"}, {"id": "ch01-s02-p042", "type": "text", "text": "そう思ったのか。思ったことにしたのか。区別はつかない。ただ、椅子の座面の硬さと、机の角に触れた肘の感触と、計器の針の揺れが、確かにここに在った。"}, {"id": "ch01-s02-p043", "type": "text", "text": "窓の外で、生徒たちが目を開けた。黙祷が終わったのだろう。列が崩れ始め、ざわめきが遠くから聞こえてくる。教員が何か話している。拍手の音。始業式が進んでいく。俺のいない場所で、俺の知らない日常が動いている。"}, {"id": "ch01-s02-p044", "type": "text", "text": "通信機が鳴った。"}, {"id": "ch01-s02-p045", "type": "text", "text": "管理室の机の端に置かれた、黒い筐体の無線機。赤いランプが点滅している。受話器を取る。"}, {"id": "ch01-s02-p046", "type": "text", "text": "「朝霧」"}, {"id": "ch01-s02-p047", "type": "text", "text": "声。低い。落ち着いている。一語がはっきりと区切られていて、感情の色がない。水面に波紋が立たないような声だった。声だけで、話している人間の姿勢の良さがわかる。"}, {"id": "ch01-s02-p048", "type": "text", "text": "「はい」"}, {"id": "ch01-s02-p049", "type": "text", "text": "「霜月です。着任の報告は受けています。業務に入っていますね」"}, {"id": "ch01-s02-p050", "type": "text", "text": "質問の形をしているが、質問ではなかった。確認だった。答えを求めているのではなく、事実を述べているだけだ。"}, {"id": "ch01-s02-p051", "type": "text", "text": "「はい。六時五十分から計器の記録を開始しています」"}, {"id": "ch01-s02-p052", "type": "text", "text": "「記録用紙は旧式のF-12ですか、改訂版のF-12Rですか」"}, {"id": "ch01-s02-p053", "type": "text", "text": "「F-12Rです」"}, {"id": "ch01-s02-p054", "type": "text", "text": "「結構。旧式の用紙がまだ棚にあるはずですが、使わないでください。項目が一つ足りない」"}, {"id": "ch01-s02-p055", "type": "text", "text": "指示が的確だった。必要なことだけを、最短の言葉で伝えている。余計な挨拶もなければ、初日への配慮のようなものもない。それが不快かと問われれば、不快ではない。むしろわかりやすかった。"}, {"id": "ch01-s02-p056", "type": "text", "text": "「第三系統の出力を確認しましたか」"}, {"id": "ch01-s02-p057", "type": "text", "text": "「……はい。基準値内ですが、他の系統と比較して振幅が0.3パーセント低い。記録には数値をそのまま残してあります」"}, {"id": "ch01-s02-p058", "type": "text", "text": "受話器の向こうが、わずかに沈黙した。一秒か、二秒か。"}, {"id": "ch01-s02-p059", "type": "text", "text": "「初日で気づきましたか」"}, {"id": "ch01-s02-p060", "type": "text", "text": "声の調子は変わらなかった。評価しているのか、単に事実を確認しているのか、判別できない。どちらでもいいことだった。"}, {"id": "ch01-s02-p061", "type": "text", "text": "「午後に点検します。それまでに第三系統の過去三ヶ月分の出力記録を棚から出しておきなさい。ファイル番号はTK-3の2026年1月から3月。グラフ化する必要はありません。生数値で構いません」"}, {"id": "ch01-s02-p062", "type": "text", "text": "「わかりました」"}, {"id": "ch01-s02-p063", "type": "text", "text": "「八時の黙祷は見ましたか」"}, {"id": "ch01-s02-p064", "type": "text", "text": "予想しなかった問いだった。業務に関係があるのだろうか。"}, {"id": "ch01-s02-p065", "type": "text", "text": "「窓から。計器の監視をしながら」"}, {"id": "ch01-s02-p066", "type": "text", "text": "「……問題ない」"}, {"id": "ch01-s02-p067", "type": "text", "text": "それだけ言って、通信が切れた。赤いランプが消える。受話器を元に戻す。"}, {"id": "ch01-s02-p068", "type": "text", "text": "「問題ない」が何に対する評価だったのか、考えても結論は出なかった。黙祷を見ていたことが問題ないのか。計器の監視を続けていたことが問題ないのか。あるいは、その両方か。"}, {"id": "ch01-s02-p069", "type": "text", "text": "霜月さんの声が頭に残っている。水面に波紋が立たない声。感情を排除しているのか、元々ないのか。どちらにしても、指示の内容に曖昧さがない。この人の下で働くことは、たぶん、俺に合っている。「たぶん」を使わずに済むくらいには。"}, {"id": "ch01-s02-p070", "type": "text", "text": "棚に向かい、TK-3のファイルを探す。2026年1月。2月。3月。三冊。背表紙の番号を確認し、机の上に並べた。午後の点検までに、霜月さんが何を見ようとしているのかは、データを見ればわかるだろう。あの低下が今日だけの話なのか、傾向として続いているのか。"}, {"id": "ch01-s02-p071", "type": "text", "text": "ファイルを開く。数字の羅列。日付と時刻と出力値。それだけの記録が、三ヶ月分。"}, {"id": "ch01-s02-p072", "type": "text", "text": "読める。数字は読める。数字には、祈る必要がない。"}, {"id": "ch01-s02-p073", "type": "text", "text": "窓の外では始業式が続いていた。拍手の音が時折聞こえる。誰かの声が風に乗って断片的に届く。聞き取れない言葉。俺はそれを背景音として聞きながら、過去の出力記録に目を通していた。"}, {"id": "ch01-s02-p074", "type": "text", "text": "第三系統の出力値は、一月中旬から微減傾向にあった。グラフ化するまでもない。数値を追えばわかる。0.1パーセント。0.15パーセント。0.2パーセント。そして今日の0.3パーセント。ゆっくりと、しかし確実に下がっている。"}, {"id": "ch01-s02-p075", "type": "text", "text": "記録用紙の余白に、日付と数値を書き出した。霜月さんに見せるための整理。指示されたのは「生数値」だが、時系列に並べておけば傾向は一目でわかる。余計なことかもしれない。初日に出過ぎた真似をしていると思われるかもしれない。"}, {"id": "ch01-s02-p076", "type": "text", "text": "けれど、手が先に動いていた。"}, {"id": "ch01-s02-p077", "type": "text", "text": "数値を並べ、線を引き、傾向を可視化する。そういう作業に、手が慣れている。誰に教わったのでもなく。二年前より前の、何も覚えていない時間の中で、俺の手はこういう動きを覚えた。今はそれを使って、ここにいる。"}, {"id": "ch01-s02-p078", "type": "text", "text": "記録用紙の束を揃え、ファイルの上に置いた。"}, {"id": "ch01-s02-p079", "type": "text", "text": "管理室は静かだった。計器の針が揺れる音。かすかな、金属と金属が触れ合う音。窓の外の遠い拍手。それだけ。"}, {"id": "ch01-s02-p080", "type": "text", "text": "これが俺の日常だ。"}, {"id": "ch01-s02-p081", "type": "text", "text": "……そうか。"}, {"id": "ch01-s02-p082", "type": "text", "text": "頷いた。誰に向けたものでもない。自分に向けたものですらないかもしれない。ただ、首が小さく動いた。計器の前で。数値の前で。祈れない代わりに、俺は数字を読む。それが、俺のここにいる理由になる。"}, {"id": "ch01-s02-p083", "type": "text", "text": "窓の外で、残響桜の花弁が風に巻かれて舞い上がった。始業式の拍手が、ひときわ大きくなった。新入生の紹介だろうか。あの中の誰かの名前も、誰かの顔も、俺は知らない。"}, {"id": "ch01-s02-p084", "type": "text", "text": "計器の針が、揺れている。"}, {"id": "ch01-s02-p085", "type": "text", "text": "第三系統の針だけが、他より少し振幅が小さい。その差を読み取れる自分がいる。読み取って、記録する自分がいる。"}, {"id": "ch01-s02-p086", "type": "text", "text": "それだけで、十分だった。十分、という言葉が正しいかはわからない。けれど、足りないという感覚もなかった。ここに椅子があり、机があり、計器があり、数字がある。霜月さんの指示があり、午後にやるべき仕事がある。"}, {"id": "ch01-s02-p087", "type": "text", "text": "足りない、と思う日が来るのかもしれない。来ないのかもしれない。"}, {"id": "ch01-s02-p088", "type": "text", "text": "通信機の赤いランプは消えたままだった。霜月さんの声が頭の中にまだ残っている。「問題ない」。あの言葉の意味を、午後に会えば確かめられるだろうか。確かめる必要があるのかどうかも、まだわからない。"}, {"id": "ch01-s02-p089", "type": "text", "text": "計器の針が揺れている。第三系統の針だけが、他より振幅が小さい。"}, {"id": "ch01-s02-p090", "type": "text", "text": "俺はそれを見ている。見ていることが、今の俺の全部だった。"}]}, {"chapter": 1, "chapterTitle": "霧の中の名前", "scene": 3, "sceneTitle": "食堂の光", "wordCount": "約6,200字", "paragraphs": [{"id": "ch01-s03-p001", "type": "text", "text": "午前中は、数字の中にいた。"}, {"id": "ch01-s03-p002", "type": "text", "text": "第三系統の過去三ヶ月分の出力記録。一月十五日、導通率98.7パーセント。一月二十日、98.65パーセント。二月三日、98.5パーセント。数値が並ぶファイルのページを繰るたびに、微減の傾向線が頭の中に引かれていく。グラフ化するまでもなく、指が数値を追うだけで見えてくる。下がっている。ゆっくりと、しかし止まらずに。"}, {"id": "ch01-s03-p003", "type": "text", "text": "九時半の鐘が鳴った。管理室の壁が震え、計器の針が跳ね、そして収まった。"}, {"id": "ch01-s03-p004", "type": "text", "text": "十一時。始業式の後、学院に日常が戻っていた。小窓の外を制服姿の生徒が行き来する。教室棟と食堂を繋ぐ渡り廊下に人の流れが見え始めていた。"}, {"id": "ch01-s03-p005", "type": "text", "text": "午後の点検までに、もう一度記録を見直す。霜月さんが何を確認したいのかは、おおよそわかった。第三系統の微減が機械的な劣化なのか、それとも外因――残響紋そのものの変質なのか。原因の切り分けに必要なデータを手元に揃えておく。"}, {"id": "ch01-s03-p006", "type": "text", "text": "十二時に近い頃、管理室の小窓から見える渡り廊下の人影が密度を増した。昼食の時間だった。"}, {"id": "ch01-s03-p007", "type": "text", "text": "ファイルを閉じ、棚に戻す。立ち上がると、膝の裏が痺れていた。長く座りすぎた。椅子を押し込み、管理室を出て鍵をかける。"}, {"id": "ch01-s03-p008", "type": "text", "text": "食堂は、教室棟の一階にあった。"}, {"id": "ch01-s03-p009", "type": "text", "text": "鐘鋳塔から南西に歩いて五分ほど。煉瓦造りの建物の正面入口を抜けると、天井の高いホールが開けた。アーチ状の窓が南面に並び、四月の日差しが斜めに射し込んでいる。埃が光の帯の中を漂っていた。木製の長テーブルが縦に何列も並び、両側に長椅子が付いている。長テーブルの天板は使い込まれて飴色になっていて、ところどころ表面が磨り減って木目が浮いている。"}, {"id": "ch01-s03-p010", "type": "text", "text": "食堂の入口近くにある受付で、配膳台にトレイを受け取った。定食。白米、味噌汁、焼き魚、漬物。学院職員は生徒と同じメニューが支給される。配属時の書類にそう書いてあった。"}, {"id": "ch01-s03-p011", "type": "text", "text": "トレイを持って席を探す。テーブルの大半は空いていた。まだ授業中の学年があるらしく、食堂にいるのは上級生が中心だった。三人、四人のかたまりで座って話している。声が天井に反射して、輪郭の丸まった音の塊になって食堂全体を覆っている。何を話しているかまでは聞き取れない。笑い声がする。"}, {"id": "ch01-s03-p012", "type": "text", "text": "食堂の一番奥、窓際の長テーブルの端に座った。向かいには誰もいない。"}, {"id": "ch01-s03-p013", "type": "text", "text": "食堂の中で、俺は端と端の間にいた。制服は生徒と同じ濃紺のジャケットだが、胸元に鐘守補佐のバッジが付いている。小さな真鍮の円盤で、中央に鐘のレリーフが彫られている。このバッジを見れば、俺が生徒ではないことはわかる。だが、教員の腕章もない。生徒より年上で、教員より若い。配膳台で受付の職員が一瞬だけ俺のバッジに目をやって、すぐに視線を戻した。区分がわからなかったのだろう。俺にもわからない。"}, {"id": "ch01-s03-p014", "type": "text", "text": "箸を手に取り、焼き魚を一口。"}, {"id": "ch01-s03-p015", "type": "text", "text": "舌の上に塩味が広がる。身はほぐれやすく、脂が少ない。白身魚。鯖か鰺か――たぶん鰺だ。監視哨にいた頃、外円区から届く配給に似た味がした。覚えている。二年前からの記憶は、ちゃんとある。"}, {"id": "ch01-s03-p016", "type": "text", "text": "味噌汁を啜る。出汁は昆布だ。塩気が強い。食堂の大鍋で炊く味噌汁は、どうしても味が濃くなるのだろう。"}, {"id": "ch01-s03-p017", "type": "text", "text": "おいしい、のだと思う。"}, {"id": "ch01-s03-p018", "type": "text", "text": "魚の身は崩れすぎず、米は粒が立っている。味噌汁の温度も適正だった。事実として、食事の品質に問題はない。けれど「おいしい」と自分の中で言うとき、その言葉と舌の感覚の間に、紙一枚ぶんの隙間がある。おいしい、と言える。たぶん正しい。ただ、その「おいしい」が俺の体の底から出ているのか、それとも「こういう味は普通おいしいと判断するものだ」という知識が先に来て、口がそれに追従しているのか。"}, {"id": "ch01-s03-p019", "type": "text", "text": "区別がつかない。"}, {"id": "ch01-s03-p020", "type": "text", "text": "区別がつかないまま、食べ続けた。白米を一口。漬物を挟む。味噌汁をもう一口。"}, {"id": "ch01-s03-p021", "type": "text", "text": "「ねえ」"}, {"id": "ch01-s03-p022", "type": "text", "text": "声がした。"}, {"id": "ch01-s03-p023", "type": "text", "text": "箸が止まった。"}, {"id": "ch01-s03-p024", "type": "text", "text": "顔を上げると、トレイを両手で持った女子生徒が立っていた。俺のいるテーブルの向かい側、長椅子の端。赤みがかった茶色の髪をポニーテールにまとめていて、高い位置でゴムが留めてある。黄色のゴム。後れ毛が頬のあたりに数本かかっていて、窓からの光を受けて金茶色に透けていた。"}, {"id": "ch01-s03-p025", "type": "text", "text": "目が合った。"}, {"id": "ch01-s03-p026", "type": "text", "text": "明るい色の瞳だった。はしばみ色、と呼ぶのが近い。窓からの日差しの中で、金色に寄った色に見えた。大きな目。まつげが長い。そしてその目の中に、遠慮のようなものが一切なかった。"}, {"id": "ch01-s03-p027", "type": "text", "text": "「一人で食べてるの？」"}, {"id": "ch01-s03-p028", "type": "text", "text": "質問だった。語尾が上がっている。けれど返事を待っている間合いが短い。質問しておいて、答えが来る前にもう次を考えている人間の、その速度。"}, {"id": "ch01-s03-p029", "type": "text", "text": "「……はい」"}, {"id": "ch01-s03-p030", "type": "text", "text": "「そうなんだ！ あたし、天城燈花。よろしくね」"}, {"id": "ch01-s03-p031", "type": "text", "text": "そう言いながら、もう向かいの長椅子にトレイを置いていた。着席の許可を求める動作はなかった。トレイが木の天板に軽くぶつかる音。味噌汁が少し揺れた。"}, {"id": "ch01-s03-p032", "type": "text", "text": "「あ、ここ座っていい？ って、もう座っちゃった。ごめんね」"}, {"id": "ch01-s03-p033", "type": "text", "text": "順番が逆だった。謝っているが、立ち上がる気配はない。ポニーテールが動くたびに左右に揺れている。制服のブラウスの袖がまくられていて、手首から先が見えていた。手は細いが、指の関節がしっかりしている。かすかに荒れた手。"}, {"id": "ch01-s03-p034", "type": "text", "text": "「……天城さん」"}, {"id": "ch01-s03-p035", "type": "text", "text": "「え、もう覚えてくれたの？ うれしい！ ――あ、あなたは？ ここの先生？ 生徒？ ……でもバッジが違うね」"}, {"id": "ch01-s03-p036", "type": "text", "text": "俺の胸元のバッジを見ていた。"}, {"id": "ch01-s03-p037", "type": "text", "text": "「鐘守補佐です。朝霧蓮」"}, {"id": "ch01-s03-p038", "type": "text", "text": "「あさぎり、れん」"}, {"id": "ch01-s03-p039", "type": "text", "text": "復唱された。名前を音に分解して確かめるような言い方だった。"}, {"id": "ch01-s03-p040", "type": "text", "text": "「れん。蓮くん、だ」"}, {"id": "ch01-s03-p041", "type": "text", "text": "「……はい」"}, {"id": "ch01-s03-p042", "type": "text", "text": "自分の名前が「蓮くん」という音に変換されるのを聞いた。監視哨では「朝霧」と名字で呼ばれていた。霜月さんにも「朝霧」と呼ばれた。名前で呼ばれるのは、二年前に発見されてから何回目だろう。片手で足りるかもしれない。"}, {"id": "ch01-s03-p043", "type": "text", "text": "天城さんのトレイを見た。定食に加えて、大きなおにぎりが一つ。小鉢に煮物。別の小鉢に胡麻和え。俺の倍近い量がある。"}, {"id": "ch01-s03-p044", "type": "text", "text": "「鐘守補佐って、鐘鋳塔の？」"}, {"id": "ch01-s03-p045", "type": "text", "text": "「はい」"}, {"id": "ch01-s03-p046", "type": "text", "text": "「すごい。あの塔で働いてるんだ」"}, {"id": "ch01-s03-p047", "type": "text", "text": "すごいかどうかはわからない。けれど天城さんの声には本気の感嘆があった。目を少し見開いて、箸を持った手を止めて俺を見ている。"}, {"id": "ch01-s03-p048", "type": "text", "text": "「……すごいかは、わかりません。今日が初日なので」"}, {"id": "ch01-s03-p049", "type": "text", "text": "「初日！ じゃあ、ここのご飯も初めて？」"}, {"id": "ch01-s03-p050", "type": "text", "text": "「はい」"}, {"id": "ch01-s03-p051", "type": "text", "text": "「どう？ おいしい？」"}, {"id": "ch01-s03-p052", "type": "text", "text": "その質問に、答えが少し遅れた。"}, {"id": "ch01-s03-p053", "type": "text", "text": "焼き魚の味を思い出す。味噌汁の塩気を思い出す。おいしいのだと思う。たぶん。さっき自分の中で言ったのと同じ結論。"}, {"id": "ch01-s03-p054", "type": "text", "text": "「……おいしい、と思います」"}, {"id": "ch01-s03-p055", "type": "text", "text": "「思います？」天城さんは箸で自分のおにぎりを指しながら首をかしげた。「おいしいかおいしくないか、どっちかでしょ！」"}, {"id": "ch01-s03-p056", "type": "text", "text": "「おいしいです」"}, {"id": "ch01-s03-p057", "type": "text", "text": "言い直した。言い直した自分の声が、さっきより早かった。天城さんの声につられたのか、それとも、「おいしい」と断言する方が正しいと判断したから修正したのか。"}, {"id": "ch01-s03-p058", "type": "text", "text": "「よし。なら合格！ ここのご飯ね、味噌汁は日によって当たり外れあるんだけど、焼き魚は安定しておいしいの。あと、金曜日のカレーは絶対食べた方がいい。おばちゃんが本気出すから」"}, {"id": "ch01-s03-p059", "type": "text", "text": "天城さんは自分のおにぎりを割って食べ始めていた。中身は鮭だった。米粒が指に付いて、それを気にする様子もなく次の一口を頬張っている。食べ方に遠慮がない。体全体で食事をしている感じがする。"}, {"id": "ch01-s03-p060", "type": "text", "text": "「蓮くん、それだけ？」"}, {"id": "ch01-s03-p061", "type": "text", "text": "俺のトレイを見ていた。定食一式。白米の量は標準だったと思う。"}, {"id": "ch01-s03-p062", "type": "text", "text": "「足りないでしょ、もっと食べなよ。背、あたしより高いのに」"}, {"id": "ch01-s03-p063", "type": "text", "text": "「……これで足りてます」"}, {"id": "ch01-s03-p064", "type": "text", "text": "「足りてるって、そんな細いのに？ あたしなんかこれ食べてもまだおやつ食べるよ？」"}, {"id": "ch01-s03-p065", "type": "text", "text": "天城さんは自分のトレイの量を示しながら笑った。歯を見せて笑う。目が細くなって、頬が上がって、顔の造作が全部動く。制服の胸ポケットに小さな花が挿してあるのが見えた。白い花弁の、小さな花。何の花かはわからない。"}, {"id": "ch01-s03-p066", "type": "text", "text": "「蓮くんって、記憶喪失なの？」"}, {"id": "ch01-s03-p067", "type": "text", "text": "唐突だった。"}, {"id": "ch01-s03-p068", "type": "text", "text": "「……なぜ、そう思うんですか」"}, {"id": "ch01-s03-p069", "type": "text", "text": "「さっき、名前を言う時の感じ。『朝霧蓮』って言った時に、自分の名前を説明してるみたいだったから。持ってる名前じゃなくて、選んだ名前、って感じの」"}, {"id": "ch01-s03-p070", "type": "text", "text": "俺は箸を膝の上に下ろした。"}, {"id": "ch01-s03-p071", "type": "text", "text": "観察力の問題ではないのだろう。天城さんの指摘は精密な分析ではなく、直感に近いものだった。声の調子の中に、好奇心と、それからもう一つ、何か別のものが混ざっていた。"}, {"id": "ch01-s03-p072", "type": "text", "text": "「……はい。記憶がありません。二年前に発見されました。名前は自分で選んだものです」"}, {"id": "ch01-s03-p073", "type": "text", "text": "言った後に、自分の声が思ったより平坦だったことに気づいた。記憶喪失。事実。俺にとっては、もう二年間そうだった事実。特別な痛みはない。痛みがあるかどうかを判断する材料が、そもそもない。"}, {"id": "ch01-s03-p074", "type": "text", "text": "天城さんの表情が一瞬、止まった。"}, {"id": "ch01-s03-p075", "type": "text", "text": "笑顔が消えたのではない。目が同じ位置に留まり、口元が同じ形を保ち、でも顔全体にあった動きの勢いが一拍だけ途切れた。ちょうど風が止んでポニーテールが垂直に落ちるときのような、そういう静止。一秒か、それ未満。"}, {"id": "ch01-s03-p076", "type": "text", "text": "その止まり方が気になった。"}, {"id": "ch01-s03-p077", "type": "text", "text": "天城さんの視線が俺のどこを見ていたのか、正確にはわからない。目か。額の傷跡か。それともどこも見ていなかったのか。"}, {"id": "ch01-s03-p078", "type": "text", "text": "「……そっか」"}, {"id": "ch01-s03-p079", "type": "text", "text": "声が低かった。さっきまでの弾むような速度が、半拍だけ遅くなっていた。"}, {"id": "ch01-s03-p080", "type": "text", "text": "「自分で選んだんだ。名前」"}, {"id": "ch01-s03-p081", "type": "text", "text": "「はい。発見された時、朝霧が出ていたので。蓮は、植物図鑑から」"}, {"id": "ch01-s03-p082", "type": "text", "text": "「植物図鑑から？」"}, {"id": "ch01-s03-p083", "type": "text", "text": "「病院に置いてあった図鑑を見て、蓮の写真が目に入って。泥の中で咲いている花の写真でした。特別な理由は、ありません」"}, {"id": "ch01-s03-p084", "type": "text", "text": "「あるよ」"}, {"id": "ch01-s03-p085", "type": "text", "text": "天城さんは断定した。さっきの静止が嘘のように、声が元の速度に戻っていた。"}, {"id": "ch01-s03-p086", "type": "text", "text": "「名前なんて、理由がなくても自分で選んだ時点でかっこいいじゃん。あたしの名前は親が付けたからさ、自分で選んだことないし。蓮くんの蓮、いい名前だと思う」"}, {"id": "ch01-s03-p087", "type": "text", "text": "俺は何か言おうとして、すぐには言葉が出なかった。"}, {"id": "ch01-s03-p088", "type": "text", "text": "かっこいい、と言われた。名前を褒められた。適切な反応は「ありがとう」だろう。わかっている。わかっているのに、口が動くまでに時間がかかる。"}, {"id": "ch01-s03-p089", "type": "text", "text": "「……ありがとう、ございます」"}, {"id": "ch01-s03-p090", "type": "text", "text": "「あ、敬語！ あたしのほうが年下でしょ？ 蓮くん何歳？」"}, {"id": "ch01-s03-p091", "type": "text", "text": "「二十二です」"}, {"id": "ch01-s03-p092", "type": "text", "text": "「やっぱり。あたし十九。三つ上じゃん。敬語やめてよ、話しにくい」"}, {"id": "ch01-s03-p093", "type": "text", "text": "「……癖なので」"}, {"id": "ch01-s03-p094", "type": "text", "text": "「じゃあ、ゆっくり直していこう。急がなくていいから」"}, {"id": "ch01-s03-p095", "type": "text", "text": "天城さんは味噌汁を一口飲んで「うん、今日はちょっとしょっぱいね」と眉を寄せた。さっき俺も思ったのと同じ感想だった。"}, {"id": "ch01-s03-p096", "type": "text", "text": "「ねえ蓮くん、午後もお仕事？」"}, {"id": "ch01-s03-p097", "type": "text", "text": "「はい。鐘鋳塔の点検です」"}, {"id": "ch01-s03-p098", "type": "text", "text": "「そっか。大変だね、初日から」"}, {"id": "ch01-s03-p099", "type": "text", "text": "「大変かどうかは……やってみないとわかりません」"}, {"id": "ch01-s03-p100", "type": "text", "text": "「あはは、蓮くんって正直だね。普通は『大変です』って言うところじゃん」"}, {"id": "ch01-s03-p101", "type": "text", "text": "「そう、なんですか」"}, {"id": "ch01-s03-p102", "type": "text", "text": "「そうだよ。で、相手が『頑張ってね』って言って、『ありがとう』って返す。そういうやつ」"}, {"id": "ch01-s03-p103", "type": "text", "text": "天城さんは自分で実演するように両手を使って「会話の型」を説明した。箸を持ったままなので、箸が指揮棒のように振られている。"}, {"id": "ch01-s03-p104", "type": "text", "text": "「……覚えておきます」"}, {"id": "ch01-s03-p105", "type": "text", "text": "言ってから、口癖が出たことに気づいた。覚えておく。何かを聞いたとき、俺はいつもそう言う。忘れたくないのだと思う。何を忘れたくないのか、正確にはわからないけれど。"}, {"id": "ch01-s03-p106", "type": "text", "text": "天城さんの煮物はジャガイモと人参の甘煮だった。大きめに切った芋を箸で割り、口に放り込んでいる。「これ、おばちゃんに教えてもらった味付け。甘めでしょ。あたし、甘い煮物好きなの」"}, {"id": "ch01-s03-p107", "type": "text", "text": "その時、俺のトレイの隅にある漬物の小鉢を見て、天城さんが「あ」と声を上げた。"}, {"id": "ch01-s03-p108", "type": "text", "text": "「蓮くん、漬物食べないの？」"}, {"id": "ch01-s03-p109", "type": "text", "text": "手を付けていなかった。"}, {"id": "ch01-s03-p110", "type": "text", "text": "「……食べます」"}, {"id": "ch01-s03-p111", "type": "text", "text": "「嫌いなの？ 嫌いなら無理しなくていいよ」"}, {"id": "ch01-s03-p112", "type": "text", "text": "「嫌い、ではないと思います」"}, {"id": "ch01-s03-p113", "type": "text", "text": "「また『思います』だ」天城さんは笑った。「蓮くんって、全部に『思います』つけるよね」"}, {"id": "ch01-s03-p114", "type": "text", "text": "言われて、自分の癖に気づいた。おいしいと思う。嫌いではないと思う。大変かどうかはわからない。断定を避けている。自分の感覚に確証が持てないから、常に一歩引いた言い方をしている。"}, {"id": "ch01-s03-p115", "type": "text", "text": "漬物を口に入れた。大根の浅漬け。塩味と酢の酸味。歯ごたえがある。"}, {"id": "ch01-s03-p116", "type": "text", "text": "「しゃきしゃきしてる」"}, {"id": "ch01-s03-p117", "type": "text", "text": "言ったのは天城さんだった。俺が噛んだ音を聞いて、横から感想を言っている。"}, {"id": "ch01-s03-p118", "type": "text", "text": "「……はい」"}, {"id": "ch01-s03-p119", "type": "text", "text": "「ね、おいしいでしょ」"}, {"id": "ch01-s03-p120", "type": "text", "text": "「はい」"}, {"id": "ch01-s03-p121", "type": "text", "text": "今度は「思います」をつけなかった。天城さんの問いかけに巻き込まれるようにして、断定が口から出た。おいしいかどうか、本当のところはわからない。でも天城さんが「おいしいでしょ」と言って、俺が「はい」と答えた。その応答の形が、不快ではなかった。"}, {"id": "ch01-s03-p122", "type": "text", "text": "食堂の窓から入る光が、テーブルの天板を暖色に染めていた。飴色の木目の上に日差しが重なって、光の温度が見える。天城さんのポニーテールの先端が、光の帯にかかっている。栗色の髪が、光を受けた部分だけ赤銅色に変わっていた。"}, {"id": "ch01-s03-p123", "type": "text", "text": "天城さんは、食べ終わった茶碗を見下ろしながら何か考えている顔をしていた。"}, {"id": "ch01-s03-p124", "type": "text", "text": "「ねえ蓮くん。あたしさ、一人でご飯食べてる人見ると放っておけないの」"}, {"id": "ch01-s03-p125", "type": "text", "text": "「……そうなんですか」"}, {"id": "ch01-s03-p126", "type": "text", "text": "「うん。なんでかな。一人が悪いわけじゃないんだけど。食堂でぽつんとしてる人見ると、なんか、ほっとけなくて」"}, {"id": "ch01-s03-p127", "type": "text", "text": "天城さんは自分の言葉を不思議そうに眺めていた。自分でもその衝動の正体を掴みきれていない、という表情。けれどすぐに「まあいいや」と片付けて、俺を見た。"}, {"id": "ch01-s03-p128", "type": "text", "text": "「だから蓮くんが一人で端っこに座ってるの見えた時、こっち来ちゃった。迷惑だった？」"}, {"id": "ch01-s03-p129", "type": "text", "text": "「いえ」"}, {"id": "ch01-s03-p130", "type": "text", "text": "「ほんと？ 無理してない？」"}, {"id": "ch01-s03-p131", "type": "text", "text": "「無理は、してないです」"}, {"id": "ch01-s03-p132", "type": "text", "text": "してない、と言ったのは正確だったと思う。天城さんがいることで食事が不快になったかと聞かれれば、なっていない。不快の反対が快なのかどうかはわからないが、少なくとも不快ではない。天城さんが話している間、俺は焼き魚を食べ終え、米を半分以上食べ、味噌汁を飲み干した。食事は進んでいた。一人で食べていた時よりわずかに速く。"}, {"id": "ch01-s03-p133", "type": "text", "text": "「よかった。また明日も来ていい？」"}, {"id": "ch01-s03-p134", "type": "text", "text": "「……俺は、ここにいると思います」"}, {"id": "ch01-s03-p135", "type": "text", "text": "「じゃあ決まり！」"}, {"id": "ch01-s03-p136", "type": "text", "text": "天城さんはトレイを持って立ち上がった。おにぎりの米粒が一つだけ指に残っていて、それを口に入れてから「ごちそうさま」と手を合わせた。"}, {"id": "ch01-s03-p137", "type": "text", "text": "「蓮くん、午後の点検がんばってね」"}, {"id": "ch01-s03-p138", "type": "text", "text": "「……」"}, {"id": "ch01-s03-p139", "type": "text", "text": "さっき天城さんが教えてくれた「会話の型」を思い出した。大変です。頑張ってね。ありがとう。そういうやつ。"}, {"id": "ch01-s03-p140", "type": "text", "text": "「……ありがとう」"}, {"id": "ch01-s03-p141", "type": "text", "text": "敬語が抜けた。自分でも意図したものか、それとも天城さんの「敬語やめてよ」に引っ張られたのか、わからない。"}, {"id": "ch01-s03-p142", "type": "text", "text": "天城さんは一瞬だけ目を丸くして、それからにっと笑った。"}, {"id": "ch01-s03-p143", "type": "text", "text": "「どういたしまして！ またね、蓮くん」"}, {"id": "ch01-s03-p144", "type": "text", "text": "ポニーテールが揺れながら遠ざかっていく。足取りが大きい。背筋がまっすぐで、前を向いている。食堂を出ていく背中が他の生徒たちの間に紛れて、栗色の尻尾だけがしばらく見えていて、やがてそれも見えなくなった。"}, {"id": "ch01-s03-p145", "type": "text", "text": "食堂が静かになった。"}, {"id": "ch01-s03-p146", "type": "text", "text": "静かになった、というのは正確ではない。周囲のざわめきは変わっていない。生徒たちが食事を続けている。食器がぶつかる音。笑い声。誰かが「おかわり」と叫ぶ声。"}, {"id": "ch01-s03-p147", "type": "text", "text": "静かになったのは、俺の周囲ではなく、俺の中だった。"}, {"id": "ch01-s03-p148", "type": "text", "text": "天城さんがいた時間。十五分か、二十分か。その間に起きたことを振り返ってみる。名前を名乗った。記憶がないと言った。漬物を食べた。おいしいと言った。ありがとうと言った。"}, {"id": "ch01-s03-p149", "type": "text", "text": "一つずつ思い出して、確認する。"}, {"id": "ch01-s03-p150", "type": "text", "text": "天城さんが笑った時、頬の筋肉が上がって目が細くなって、顔の全部が動いていた。あの動き方。あの速度。あの光の中で栗色の髪が赤銅色に変わっていた色。胸ポケットの白い花。黄色いヘアゴム。"}, {"id": "ch01-s03-p151", "type": "text", "text": "それらを見て、俺の中に何かがあった。"}, {"id": "ch01-s03-p152", "type": "text", "text": "何か。名前がつけられない。つけていいのかもわからない。温かいと言えば温かいのかもしれない。でもその「温かい」は、今朝感じた布団の「温かいはずだ」とは少しだけ違う気がする。紙一枚ぶんの隙間が、半枚ぶんに狭まったような。あるいは、隙間の幅は変わらないのに、隙間を気にしている自分がいるような。"}, {"id": "ch01-s03-p153", "type": "text", "text": "たぶん、温かい。"}, {"id": "ch01-s03-p154", "type": "text", "text": "たぶん。"}, {"id": "ch01-s03-p155", "type": "text", "text": "漬物の小鉢が空になっていた。いつの間にか全部食べていた。味は、覚えている。しゃきしゃきしていた。天城さんがそう言ったから、その音を覚えている。"}, {"id": "ch01-s03-p156", "type": "text", "text": "トレイを持って立ち上がった。返却口にトレイを戻し、食堂を出た。"}, {"id": "ch01-s03-p157", "type": "text", "text": "渡り廊下を歩いて鐘鋳塔に向かう。四月の風が渡り廊下を抜けて、首筋に触れた。暖かくも冷たくもない風。残響桜の花弁が一枚、風に乗って俺の肩の上を通り過ぎて、煉瓦の地面に落ちた。"}, {"id": "ch01-s03-p158", "type": "text", "text": "足が止まりかけて、止まらなかった。"}, {"id": "ch01-s03-p159", "type": "text", "text": "午後の点検がある。第三系統のデータは揃えてある。霜月さんが来る。やるべきことがある。"}, {"id": "ch01-s03-p160", "type": "text", "text": "やるべきことがある、という事実。朝からずっとそれに支えられてきた。計器を読む。数値を記録する。ファイルを整理する。それだけが俺をこの場所に繋ぎ止めていた。"}, {"id": "ch01-s03-p161", "type": "text", "text": "でも今、もう一つ、別のものが加わった気がする。"}, {"id": "ch01-s03-p162", "type": "text", "text": "明日もここにいると言った。天城さんが「また来ていい？」と聞いて、俺が「ここにいると思います」と答えた。それは事実の報告だった。仕事があるから食堂に来る。食堂に来れば定食を食べる。それだけのこと。"}, {"id": "ch01-s03-p163", "type": "text", "text": "それだけのことが、さっきまでと違う色をしている。"}, {"id": "ch01-s03-p164", "type": "text", "text": "たぶん。"}, {"id": "ch01-s03-p165", "type": "text", "text": "鐘鋳塔の石壁が見えてきた。入口で身分証を提示し、一階の管理室に戻った。椅子に座り、計器の前に着く。針は揺れている。第三系統の振幅は、午前中と変わっていなかった。"}, {"id": "ch01-s03-p166", "type": "text", "text": "記録用紙を開き、午後の数値を書き始めた。"}, {"id": "ch01-s03-p167", "type": "text", "text": "天城燈花。十九歳。おにぎりと煮物と胡麻和え。一人で食べてる人を放っておけない性格。ポニーテール。黄色のゴム。笑い方。"}, {"id": "ch01-s03-p168", "type": "text", "text": "覚えている。"}, {"id": "ch01-s03-p169", "type": "text", "text": "ただ——一つだけ、うまく整理できないものがあった。"}, {"id": "ch01-s03-p170", "type": "text", "text": "天城さんの表情が止まった、あの一瞬。笑顔の形を保ったまま、顔全体の動きの勢いだけが途切れた瞬間。あの沈黙の底に、何があったのか。"}, {"id": "ch01-s03-p171", "type": "text", "text": "聞けなかった。聞くべきだったのかもしれない。"}]}, {"chapter": 1, "chapterTitle": "霧の中の名前", "scene": 4, "sceneTitle": "機構室の氷", "wordCount": "約5,200字", "paragraphs": [{"id": "ch01-s04-p001", "type": "text", "text": "十三時四十分。管理室の計器を確認して、記録用紙を棚に戻す。午後の数値は午前と変わらない。第三系統、0.3パーセント低下のまま。針は同じ幅で揺れている。"}, {"id": "ch01-s04-p002", "type": "text", "text": "鍵束を腰に留め、管理室を出た。廊下を奥に進む。鐘鋳塔の一階から地下一階への階段は、管理室を通り過ぎた先の石壁の裏にあった。鉄製の扉を開けると、下に降りる階段が目に入る。壁面に残響灯が二つ。青白い光。残響エネルギーで点灯する灯りだとマニュアルに書いてあった。灯りの色は鐘の音の周波数に依存するらしい。だから青白い。"}, {"id": "ch01-s04-p003", "type": "text", "text": "十四時に霜月さんと合流して、第三系統の点検を行う。それが午後の業務だった。霜月さんからの無線連絡があったのは今朝の八時過ぎで、第三系統の計器を確認しろと言われた。それきり連絡はない。点検場所は機構室。地下一階。"}, {"id": "ch01-s04-p004", "type": "text", "text": "階段を降りていく。石段は踏面が広く、靴底に伝わる感触が硬い。空気が変わった。一階の石壁と木の匂いが消えて、金属と潤滑油と、もっと古いもの——湿った石の奥の、時間の堆積したような匂いが鼻に届く。温度が下がる。四月の午後だが、地下に降りるにつれて空気が冷えていく。背中に薄い緊張が走った。冷たい空気に肌が反応しただけだ。"}, {"id": "ch01-s04-p005", "type": "text", "text": "階段を降りきると、通路がまっすぐ延びていた。天井は高い。石造りのアーチが等間隔に並び、壁面の残響灯が青白い光を落としている。足音が通路に反響して、自分の歩幅の間隔がそのまま音の間隔になっている。他に人の気配はなかった。"}, {"id": "ch01-s04-p006", "type": "text", "text": "通路の突き当たりに、大きな鉄扉があった。"}, {"id": "ch01-s04-p007", "type": "text", "text": "扉の表面に刻まれた文字。「第三機構室」。鍵束から該当する鍵を選ぶ。マニュアルの図面では真鍮の丸頭鍵、番号C-03。指先で鍵の刻印を確かめて差し込み、回す。錠前の噛み合わせが外れる音。重い鉄扉を押し開けた。"}, {"id": "ch01-s04-p008", "type": "text", "text": "機構室は、歯車で出来ていた。"}, {"id": "ch01-s04-p009", "type": "text", "text": "壁面を覆う大小の歯車。最も大きなものは直径が俺の背丈ほどあり、最も小さなものは親指の爪くらいだった。それらが噛み合い、連結し、壁一面に組み上がっている。一つの歯車が動けば隣の歯車が回り、その回転が次に伝わり、部屋全体が一つの機構として繋がっている。今は鐘打ちの時間ではないから、ほとんどの歯車は止まっていた。けれど完全には止まっていない。残響紋の微弱な振動を拾って、最も小さな歯車群がかすかに回っている。耳を澄ますと、金属が擦れる微細な音が聞こえた。息をしている、と思った。機械が呼吸しているような、そういう音。"}, {"id": "ch01-s04-p010", "type": "text", "text": "天井から共鳴管が吊り下がっていた。金属製の管が何本も垂直に降り、途中で分岐し、壁面の歯車群と接続している。管の径も太さも一本ずつ違う。音響増幅器が床に四基、固定されていた。残響金属の箱型の装置で、共鳴管から下りてきた振動を増幅して鐘に送る。その構造がマニュアルの図面と一致しているのを確認する。"}, {"id": "ch01-s04-p011", "type": "text", "text": "確認する。確認しながら、自分の手が先に動いていることに気づく。"}, {"id": "ch01-s04-p012", "type": "text", "text": "最も近い歯車の歯面に指を当てる。潤滑油の薄い膜。粘度は適正。指を離して、隣の歯車との噛み合わせの隙間を見る。バックラッシュ。0.1ミリ前後。正常だと思う。思う、というのは、基準値をまだマニュアルで確認していないからだ。けれど指先が「これでいい」と言っている。"}, {"id": "ch01-s04-p013", "type": "text", "text": "この感覚は、前にもあった。"}, {"id": "ch01-s04-p014", "type": "text", "text": "今朝、管理室のマニュアルを読んだ時。機械の図面を目で追う前に、指が図解の上を滑った。監視哨でも同じだった。観測機器の部品を交換する時、マニュアルを開く前に手が工具を選んでいる。教わった記憶はない。二年前以前の記憶がないのだから。"}, {"id": "ch01-s04-p015", "type": "text", "text": "けれどここに立っていると、妙な安心感がある。歯車と共鳴管と、金属の匂いと、冷たい空気。それらが混ざった空間の中に身を置くと、思考の速度が落ち着く。食堂で天城さんと話している時とは違う種類の安定。食堂のあれは、人に引っ張られて生まれたもの。ここにあるのは、もっと古い。もっと自分の中の深いところで、何かが反応している。"}, {"id": "ch01-s04-p016", "type": "text", "text": "何に反応しているのかはわからない。わからないが、指先が歯車の歯面を撫でる感触は、嫌ではなかった。"}, {"id": "ch01-s04-p017", "type": "text", "text": "工具箱を開ける。マニュアルの点検手順を確認し、第三系統の歯車列から作業を始めた。まず目視点検。歯面の摩耗、亀裂、異物の噛み込み。一つずつ確認していく。残響灯の青白い光だけでは暗い。携帯灯を歯車の隙間に差し入れて照らすと、金属の表面に微細な傷が浮かび上がった。運用に伴う通常の摩耗痕。問題はない。"}, {"id": "ch01-s04-p018", "type": "text", "text": "次に、共鳴管の接合部。接合リングの締まりを確認する。レンチを当てて、規定トルクに達しているか。一本目、正常。二本目、正常。三本目。わずかに緩い。レンチが八分の一回転ほど回った。記録する。"}, {"id": "ch01-s04-p019", "type": "text", "text": "三本目の接合部を増し締めしながら、視界の端に共鳴管の内壁が映った。携帯灯で照らす。管の内側に薄い膜状のものが付着している。残響金属の酸化膜か。それとも残響紋の微弱な堆積か。指では触れられない位置だった。記録に残す。後で霜月さんに報告する。"}, {"id": "ch01-s04-p020", "type": "text", "text": "作業に没頭していた。"}, {"id": "ch01-s04-p021", "type": "text", "text": "どのくらいの時間が経ったのか。たぶん十五分ほどだと思うが、時計を見ていなかった。五本目の共鳴管の接合部にレンチを当てている時、背後の空気が変わった。"}, {"id": "ch01-s04-p022", "type": "text", "text": "足音ではなかった。足音はしなかった。ただ、機構室の空気のどこかに、それまでなかった圧が加わった。薄い、けれど確かな何か。温度が一度下がったような、そういう気配。"}, {"id": "ch01-s04-p023", "type": "text", "text": "振り返った。"}, {"id": "ch01-s04-p024", "type": "text", "text": "鉄扉の前に、人が立っていた。"}, {"id": "ch01-s04-p025", "type": "text", "text": "長い銀色の髪が、残響灯の青白い光を吸って銀よりも冷たい色に見えていた。ハーフアップにまとめられた髪が肩の下まで流れ、毛先が白いコートの襟にかかっている。白いロングコート。防蝕処理の特殊素材——というのはマニュアルの機構室安全規程に記載されていた装備だ。生地が硬そうだった。皺がほとんどない。着慣れているのか、あるいは常に同じ状態を維持しているのか。体の線を覆い隠すその白さが、機構室の金属群の中に置かれると、壁のように見えた。入り口を塞ぐ白い壁。"}, {"id": "ch01-s04-p026", "type": "text", "text": "「朝霧。遅刻は困る」"}, {"id": "ch01-s04-p027", "type": "text", "text": "声。"}, {"id": "ch01-s04-p028", "type": "text", "text": "今朝の無線で聞いた声だった。低い。落ち着いている。一語がはっきりと区切られていて、語尾に感情の色がない。無線越しで聞いた時は通信のざらつきがあったが、直接聞くと、声の輪郭がもっとはっきりしていた。"}, {"id": "ch01-s04-p029", "type": "text", "text": "「十三時五十分に到着しています。点検開始は十四時の指示でしたので」"}, {"id": "ch01-s04-p030", "type": "text", "text": "そう答えながら、相手の顔を見た。"}, {"id": "ch01-s04-p031", "type": "text", "text": "青紫色の瞳。ラベンダー、という色名が近いと思った。けれど花の色の柔らかさはなく、もっと硬質だった。鉱石を薄く切り出した断面のような。その目が俺を見ていた。俺を、ではない。俺の手元を見ていた。レンチを握った右手と、共鳴管の接合部と、その周囲の工具の配置を。"}, {"id": "ch01-s04-p032", "type": "text", "text": "「……」"}, {"id": "ch01-s04-p033", "type": "text", "text": "霜月氷華。二十歳。鐘鋳塔技師。俺の直属上司。人事書類の情報はそれだけだった。実物は書類より背が高い。168センチとあったが、白いコートが縦のラインを強調していて、もう少し高く見えた。"}, {"id": "ch01-s04-p034", "type": "text", "text": "左耳に、光るものがあった。"}, {"id": "ch01-s04-p035", "type": "text", "text": "青い石のピアス。一つだけ。右耳にはない。残響灯の光を受けて、石の中に小さな青い影が揺れていた。何の石かは知らない。装飾品に詳しくない。ただ、石の青と、髪の銀と、コートの白が、全部冷たい色をしていた。暖色がない。"}, {"id": "ch01-s04-p036", "type": "text", "text": "「十分前に到着するのが標準です」"}, {"id": "ch01-s04-p037", "type": "text", "text": "霜月さんはそれだけ言って、機構室に入ってきた。足音が小さい。靴底が石の床に当たる音はするが、最小限に抑えられている。歩き方に無駄がなかった。まっすぐ歯車の壁面に向かい、俺の隣を通り過ぎる時、白いコートの裾が俺の腕に触れそうになって、触れなかった。"}, {"id": "ch01-s04-p038", "type": "text", "text": "潤滑油と石の匂いの中に、別の匂いが一瞬だけ混ざった。何の匂いかわからない。香水ではないと思う。もっと淡い。紙の、あるいは金属洗浄剤の、そういう無機質な匂い。"}, {"id": "ch01-s04-p039", "type": "text", "text": "「作業経過を」"}, {"id": "ch01-s04-p040", "type": "text", "text": "「第三系統の歯車列、目視点検完了。摩耗は運用範囲内。共鳴管の接合部を順次確認中です。三本目に規定トルクより僅かに緩い箇所があり、増し締めを行いました。五本目の内壁に薄い膜状の付着物を確認しています」"}, {"id": "ch01-s04-p041", "type": "text", "text": "報告しながら、霜月さんの反応を観察した。表情が動かない。目が共鳴管の接合部を追っている。報告の内容を聞きながら、同時に自分の目で確認している。信用していないのではなく、そういう手順なのだろう。データを自分で確認する人だ。「データを示しなさい」——朝の無線で、そういう口調だった。"}, {"id": "ch01-s04-p042", "type": "text", "text": "「膜状の付着物。場所は」"}, {"id": "ch01-s04-p043", "type": "text", "text": "「五本目の内壁、接合部から約15センチ下方です」"}, {"id": "ch01-s04-p044", "type": "text", "text": "霜月さんは携帯灯を受け取り——俺が差し出す前に、自分の工具袋から別のものを出した。細い検査灯だった。それを共鳴管の中に差し入れ、覗き込む。銀色の髪が共鳴管の縁にかかった。"}, {"id": "ch01-s04-p045", "type": "text", "text": "「残響紋の微弱堆積。第三系統の出力低下と相関がある可能性がある。記録は」"}, {"id": "ch01-s04-p046", "type": "text", "text": "「記録済みです」"}, {"id": "ch01-s04-p047", "type": "text", "text": "「……」"}, {"id": "ch01-s04-p048", "type": "text", "text": "霜月さんは検査灯を引き抜き、工具袋に戻した。それから俺の作業記録に目を落とした。記録用紙に書いた数値と所見を、上から順に読んでいる。読む速度が速い。目の動きでわかる。視線が行の端から端まで一定のリズムで移動して、途中で止まらない。"}, {"id": "ch01-s04-p049", "type": "text", "text": "「手際は悪くない」"}, {"id": "ch01-s04-p050", "type": "text", "text": "声に抑揚がなかった。評価なのか、事実の確認なのか、区別がつかない。返す言葉を探していると、霜月さんはもう視線を記録用紙から外していた。歯車の壁面に向かい直し、目視点検を始めている。"}, {"id": "ch01-s04-p051", "type": "text", "text": "俺はレンチを手に取り直して、六本目の共鳴管に向かった。"}, {"id": "ch01-s04-p052", "type": "text", "text": "並行して作業を続けた。俺が共鳴管の接合部を確認し、霜月さんが歯車列の軸受け部を検査する。会話はなかった。指示は最小限で、必要な時だけ出た。「八番歯車のグリスを確認しなさい」「音響増幅器の第二ユニット、出力波形を記録しなさい」。主語がない。敬語もない。業務の言語だけが機構室の冷えた空気の中を行き来した。"}, {"id": "ch01-s04-p053", "type": "text", "text": "霜月さんの作業を横目で見ていた。白いコートの袖を折らずに、そのまま機械に触れている。防蝕処理素材だから油で汚れない、ということだろうか。歯車の軸受けに検査器具を当てる手つきが正確だった。一つの動作に迷いがなく、次の動作との間に隙間がない。"}, {"id": "ch01-s04-p054", "type": "text", "text": "鎧だ、と思った。"}, {"id": "ch01-s04-p055", "type": "text", "text": "白いコートが、という意味ではなく。霜月さんの動作の全体が、そう見えた。感情を通さない、仕事だけを通す構造物。言葉の選び方も、歩き方も、作業の手順も、全部が同じ密度で固められている。冷たさすら必要としていない。温度という概念そのものが、業務の外に追い出されている。"}, {"id": "ch01-s04-p056", "type": "text", "text": "怖い、とは思わなかった。怖いと思うほどの感情の出力が自分にあるのかどうか怪しいし、そもそも霜月さんは怖いことをしていない。業務の指示を出し、機械を点検し、記録を確認している。ただそれだけだ。"}, {"id": "ch01-s04-p057", "type": "text", "text": "そういう人なのだろう、と思った。そういう人がいる。それ以上の判断は必要ない。"}, {"id": "ch01-s04-p058", "type": "text", "text": "作業は一時間半ほど続いた。最後に音響増幅器の出力波形を記録して、霜月さんに提出した。"}, {"id": "ch01-s04-p059", "type": "text", "text": "霜月さんは記録用紙の束を受け取り、一枚ずつ確認している。機構室の残響灯の光が記録用紙の白い面を青白く照らしていた。"}, {"id": "ch01-s04-p060", "type": "text", "text": "「明日の九時に、共鳴管の内壁洗浄を行います。必要な資機材のリストを今日中に管理室の机に置いておきなさい」"}, {"id": "ch01-s04-p061", "type": "text", "text": "「わかりました」"}, {"id": "ch01-s04-p062", "type": "text", "text": "「……以上」"}, {"id": "ch01-s04-p063", "type": "text", "text": "霜月さんは記録用紙を工具袋にしまい、機構室の出口に向かった。鉄扉の前で、一度だけ振り返った。振り返ったのではないかもしれない。機構室の全体を最後に目視確認しただけかもしれない。"}, {"id": "ch01-s04-p064", "type": "text", "text": "そのまま通路に出た。俺も工具箱を片付けて後に続く。"}, {"id": "ch01-s04-p065", "type": "text", "text": "通路を歩いていると、前方に階段があった。地下一階から地下二階へ降りる階段。通路の途中から右に折れて下に続いている。入口に標識がかかっていた。「地下二階 記憶の間」。そしてその下に「関係者以外立入禁止」の赤い札。"}, {"id": "ch01-s04-p066", "type": "text", "text": "霜月さんの足が、止まった。"}, {"id": "ch01-s04-p067", "type": "text", "text": "一歩分。それだけの停滞だった。白いコートの裾が揺れかけて、止まって、また動いた。視線が階段の入口に向いていたかどうかは、俺の位置からは確認できなかった。後ろ姿しか見えていない。ただ、歩行のリズムの中に一拍だけ空白が入った。"}, {"id": "ch01-s04-p068", "type": "text", "text": "それだけのことだった。"}, {"id": "ch01-s04-p069", "type": "text", "text": "霜月さんはそのまま通路を進み、地下一階から一階への階段を上った。俺も上った。管理室の前で、霜月さんが足を止めた。"}, {"id": "ch01-s04-p070", "type": "text", "text": "「資機材リスト。今日中に」"}, {"id": "ch01-s04-p071", "type": "text", "text": "「はい」"}, {"id": "ch01-s04-p072", "type": "text", "text": "霜月さんは頷きもせず、通路の奥へ歩いていった。白いコートの背中が残響灯の光の中を遠ざかって、通路の角を曲がるところで見えなくなった。"}, {"id": "ch01-s04-p073", "type": "text", "text": "管理室に入る。椅子に座る。計器の前に着く。針は揺れている。"}, {"id": "ch01-s04-p074", "type": "text", "text": "作業記録の控えを開き、資機材のリストを書き始めた。内壁洗浄用のブラシ、洗浄液、保護手袋、検査灯の替え電池。一つずつ書き出していく。"}, {"id": "ch01-s04-p075", "type": "text", "text": "指先に、まだ歯車の油膜の感触が残っていた。"}, {"id": "ch01-s04-p076", "type": "text", "text": "霜月氷華。二十歳。銀髪。白いコート。左耳の青い石。声に感情の色がない。「手際は悪くない」。表情を変えずに言う評価。あの一拍の空白。地下二階への階段の前で、コートの裾が止まった一瞬。"}, {"id": "ch01-s04-p077", "type": "text", "text": "天城さんを思い出すときと、霜月さんを思い出すとき。覚え方が違う。"}, {"id": "ch01-s04-p078", "type": "text", "text": "天城さんの笑い方やポニーテールや黄色のゴムを思い出すと、名前のつかない温かさがある。霜月さんの白いコートや一拍の空白を思い出すと、何もない。何もない——はずなのに、同じ「何もない」が俺の中にもある、という認識だけが残る。"}, {"id": "ch01-s04-p079", "type": "text", "text": "俺は感情がないから空白なのだ。何を感じていいかわからないから。でも霜月さんは違う。あの人は空白ではなく、凍っている。何かがあった上で、全部を氷の下に沈めている。そういう密度がある。俺の空白には密度がない。"}, {"id": "ch01-s04-p080", "type": "text", "text": "その違いがわかることに、自分で驚いている。"}, {"id": "ch01-s04-p081", "type": "text", "text": "資機材リストを書き終えた。記録用紙を管理室の机に置き、計器の午後の最終記録を取る。第三系統の針は朝から動いていない。"}, {"id": "ch01-s04-p082", "type": "text", "text": "けれど明日の洗浄で、共鳴管の内壁の付着物を除去すれば、数値が変わるかもしれない。変わるかどうかは、やってみないとわからない。"}, {"id": "ch01-s04-p083", "type": "text", "text": "やってみないとわからないこと。"}, {"id": "ch01-s04-p084", "type": "text", "text": "そういうものは、嫌いではない。たぶん。"}]}, {"chapter": 1, "chapterTitle": "霧の中の名前", "scene": 5, "sceneTitle": "着任の日", "wordCount": "約4,200字", "paragraphs": [{"id": "ch01-s05-p001", "type": "text", "text": "十七時の鐘が鳴った。"}, {"id": "ch01-s05-p002", "type": "text", "text": "管理室の壁面が共鳴して、計器の針が跳ね、すぐに戻る。今日四回目の鐘打ちだった。六時半、九時半、十二時半、十七時。鐘の音を聞くたびに、体のどこかが反応する。動悸でも緊張でもない。もっと深いところ、骨の内側あたりが鐘の周波数と一緒に振動しているような。"}, {"id": "ch01-s05-p003", "type": "text", "text": "計器の最終数値を記録用紙に書き込んだ。第三系統、0.3パーセント低下。朝から変わらない数字の横に、時刻を入れる。ペンを置いた。"}, {"id": "ch01-s05-p004", "type": "text", "text": "鍵束を確認し、管理室の消灯。戸締まり。手順はマニュアル通り。朝この手順を読んだのが今日の出来事とは思えないくらい、手が迷わなかった。一日で覚えたのか、それとも手がもともと知っていたのか。"}, {"id": "ch01-s05-p005", "type": "text", "text": "鐘鋳塔の正面入口を出る。"}, {"id": "ch01-s05-p006", "type": "text", "text": "空が赤い。西の方角、空の低い位置に太陽が落ちかけていた。朝来た時は霧が出ていた。昼は日差しがあった。今は夕焼けで、空の色が朝と昼と全部違う。一日の中でこれだけ空の色が変わるのは——いや、監視哨にいた頃も同じだったはずだ。ただ、あの頃は空を見る余裕がなかった。計器と蝕域の境界杭を見ていた。空は背景で、色は情報ではなかった。"}, {"id": "ch01-s05-p007", "type": "text", "text": "教室棟の裏手にある補佐官舎に向かう。学院の南門を抜けて、煉瓦舗装の通りに出た。灯籠通り。今朝、マニュアルと一緒に渡された学院周辺の地図に載っていた名前。中円区の住宅街を南北に貫くメインストリート。"}, {"id": "ch01-s05-p008", "type": "text", "text": "通りの両側に灯籠型の街灯が並んでいた。石の台座に木の枠。枠の中に油灯が収まっている。まだ全部は灯っていない。南側の灯籠から順に、点灯係らしい男が一本ずつ火を入れていくのが見えた。長い棒の先に灯芯がついていて、それを灯籠の中に差し入れる。橙色の火が一つ灯る。男が二歩進む。次の灯籠にまた火を入れる。もう一つ灯る。等間隔に、ゆっくりと。"}, {"id": "ch01-s05-p009", "type": "text", "text": "通りを歩いた。煉瓦の感触が靴底に伝わる。鐘鋳塔の石段や管理室の石床とは違う。角が丸く、踏むたびにわずかな弾力がある。使い込まれた煉瓦。"}, {"id": "ch01-s05-p010", "type": "text", "text": "左右の建物の間から路地が伸びていて、洗濯物が干してあった。白いシーツが夕風に膨らんでいる。その向こうに台所の窓が見え、中で誰かが動いている影。油の匂い。魚を焼いているのか、醤油が焦げる匂いも混じっている。子供が二人、路地から飛び出してきて、俺の前を横切って反対側の路地に消えた。追いかけっこらしい。笑い声が煉瓦の壁に跳ね返って残った。"}, {"id": "ch01-s05-p011", "type": "text", "text": "灯籠通りは、音が多かった。"}, {"id": "ch01-s05-p012", "type": "text", "text": "商店街の呼び込みの声。魚屋の店先で氷が砕ける音。八百屋のおばさんが段ボール箱を積む音。食堂の暖簾をくぐる人の足音。そして灯籠の火が風に揺れて、油がぱちりと弾ける音。"}, {"id": "ch01-s05-p013", "type": "text", "text": "監視哨にはなかった密度。鐘鋳塔の管理室にもなかった。人の暮らしが重なり合って出す音は、計器の針の揺れとは全く違うもので、不規則で、うるさくて、でも——"}, {"id": "ch01-s05-p014", "type": "text", "text": "嫌ではなかった。"}, {"id": "ch01-s05-p015", "type": "text", "text": "たぶん。"}, {"id": "ch01-s05-p016", "type": "text", "text": "灯籠が一つまた一つと灯っていく通りを歩きながら、補佐官舎への道筋を思い出していた。灯籠通りをまっすぐ南に進んで、三つ目の角を左に——"}, {"id": "ch01-s05-p017", "type": "text", "text": "「蓮くーん！」"}, {"id": "ch01-s05-p018", "type": "text", "text": "背中に声がぶつかった。"}, {"id": "ch01-s05-p019", "type": "text", "text": "振り返る前に、足音が聞こえた。煉瓦を蹴る、大股の、速い足音。走ってきている。"}, {"id": "ch01-s05-p020", "type": "text", "text": "「蓮くん、待って！ ちょっと待って！」"}, {"id": "ch01-s05-p021", "type": "text", "text": "栗色のポニーテールが視界に飛び込んできた。夕焼けの光を受けて、髪の先端が赤銅色に燃えている。天城さん。制服のブラウスの袖がまくられたまま、胸ポケットの白い花が走る振動でぴょこぴょこ揺れていた。"}, {"id": "ch01-s05-p022", "type": "text", "text": "「はあ、はあ。……よかった、追いついた。蓮くん歩くの速い」"}, {"id": "ch01-s05-p023", "type": "text", "text": "天城さんは俺の二歩前で止まり、両手を膝に着いて息を整えていた。ポニーテールが垂れて背中で揺れている。"}, {"id": "ch01-s05-p024", "type": "text", "text": "「……天城さん」"}, {"id": "ch01-s05-p025", "type": "text", "text": "「放課後、南門から出るの見えたの。でもあたし掃除当番で。終わってから追いかけた」"}, {"id": "ch01-s05-p026", "type": "text", "text": "息が落ち着いてきたらしく、顔を上げた。はしばみ色の目が真っ直ぐこっちを見ていた。"}, {"id": "ch01-s05-p027", "type": "text", "text": "「ねえ蓮くん、このまま帰る？」"}, {"id": "ch01-s05-p028", "type": "text", "text": "「……補佐官舎に戻るつもりでした」"}, {"id": "ch01-s05-p029", "type": "text", "text": "「つまんない！ 初日でしょ、もったいないよ。ねえ、こっちにいい喫茶店あるんだよ！」"}, {"id": "ch01-s05-p030", "type": "text", "text": "言い終わる前に歩き始めていた。いや、正確には俺の腕を掴んで引っ張りながら歩き始めていた。右の手首の上あたり。天城さんの指は細いが、関節がしっかりしていて、握る力に躊躇がなかった。"}, {"id": "ch01-s05-p031", "type": "text", "text": "「天城さん」"}, {"id": "ch01-s05-p032", "type": "text", "text": "「あ、引っ張っちゃった。ごめん。嫌だった？」"}, {"id": "ch01-s05-p033", "type": "text", "text": "手を離された。"}, {"id": "ch01-s05-p034", "type": "text", "text": "「……いえ」"}, {"id": "ch01-s05-p035", "type": "text", "text": "嫌ではなかった。嫌だったら止めていたと思う。止めなかったのだから、嫌ではなかったのだろう。その判断で合っているのかはわからないけれど。"}, {"id": "ch01-s05-p036", "type": "text", "text": "「じゃあ行こ！ すぐそこだから」"}, {"id": "ch01-s05-p037", "type": "text", "text": "天城さんは俺の半歩先を歩いた。ポニーテールが左右に振れるリズムが、灯籠通りの灯りと交互に重なっていた。灯、髪、灯、髪。橙色と赤銅色。"}, {"id": "ch01-s05-p038", "type": "text", "text": "灯籠通りの中ほどで、天城さんが足を止めた。"}, {"id": "ch01-s05-p039", "type": "text", "text": "「ここ！」"}, {"id": "ch01-s05-p040", "type": "text", "text": "木造二階建ての古い建物だった。一階の入口に小さな看板がかかっている。「残響」。木の板に黒い文字で、それだけ。ドアは木製で、磨りガラスがはめ込まれていた。中から暖色の光が漏れている。"}, {"id": "ch01-s05-p041", "type": "text", "text": "天城さんがドアを開けた。カウベルが鳴った。低い、丸い音。"}, {"id": "ch01-s05-p042", "type": "text", "text": "中は狭かった。カウンターが奥に一本、手前にテーブル席が三つ。テーブルは四人がけの小さなもので、天板が飴色に光っている。食堂のテーブルと同じ色だったが、もっと年季が入っていた。壁面に古い写真が何枚か飾られていて、天井には裸電球が二つ。裸電球の光は残響灯の青白さとは違い、黄色味があって、影が柔らかかった。"}, {"id": "ch01-s05-p043", "type": "text", "text": "コーヒーの匂いがした。"}, {"id": "ch01-s05-p044", "type": "text", "text": "苦い、温かい匂い。監視哨ではコーヒーを飲まなかった。配給にコーヒー豆は含まれていたが、淹れ方を知らなかったし、知る理由もなかった。"}, {"id": "ch01-s05-p045", "type": "text", "text": "カウンターの向こうに人がいた。六十代の男性。白髪交じりの短髪、頬のあたりに深い皺。エプロンを腰に巻いて、カウンターの上にカップを並べている。手つきがゆっくりだが、正確だった。カップの間隔が均等で、取っ手の向きが全部同じ方向を向いている。"}, {"id": "ch01-s05-p046", "type": "text", "text": "「マスター、こんにちはー！ 二人でーす」"}, {"id": "ch01-s05-p047", "type": "text", "text": "天城さんが手を上げた。"}, {"id": "ch01-s05-p048", "type": "text", "text": "マスターは顔を上げ、天城さんを見て、それから俺を見た。"}, {"id": "ch01-s05-p049", "type": "text", "text": "「おや、天城さん。今日は珍しい連れだね」"}, {"id": "ch01-s05-p050", "type": "text", "text": "低い声。穏やかだが、声の芯がしっかりしている。"}, {"id": "ch01-s05-p051", "type": "text", "text": "「新しく来た鐘守補佐の蓮くん！ 今日着任したばっかり」"}, {"id": "ch01-s05-p052", "type": "text", "text": "「ほう。鐘守補佐か」マスターの目が俺の胸元のバッジに止まった。「久しぶりだな、若い補佐は」"}, {"id": "ch01-s05-p053", "type": "text", "text": "「……朝霧蓮です」"}, {"id": "ch01-s05-p054", "type": "text", "text": "「吉岡。この店のマスターだ。昔はわしも鐘鋳塔にいた。もう三十年以上前の話だがね」"}, {"id": "ch01-s05-p055", "type": "text", "text": "元鐘守。学院周辺の案内図に書いてあった。喫茶「残響」のマスターは元鐘守。"}, {"id": "ch01-s05-p056", "type": "text", "text": "「何にする？ うちはコーヒーが売りだ。豆は中円市場の専門店から仕入れてる。ハーブティーもあるが、若い人にはコーヒーを勧めるよ」"}, {"id": "ch01-s05-p057", "type": "text", "text": "「コーヒーで」"}, {"id": "ch01-s05-p058", "type": "text", "text": "「あたしも！ マスター、あたしのはミルク多めでお願い」"}, {"id": "ch01-s05-p059", "type": "text", "text": "天城さんは窓際のテーブル席に先に座っていた。俺も向かいに座った。昼の食堂と同じ配置。天城さんが向かいにいる。"}, {"id": "ch01-s05-p060", "type": "text", "text": "テーブルの上に小さな灯りが置いてあった。ガラスの器に油を入れて芯を浮かべたもの。灯籠通りの灯籠と同じ油灯の仕組み。小さな火が、テーブルの天板の上で揺れていた。"}, {"id": "ch01-s05-p061", "type": "text", "text": "天城さんはテーブルの油灯を覗き込むようにして、火を見ていた。"}, {"id": "ch01-s05-p062", "type": "text", "text": "「ここね、あたし学院に来てすぐ見つけたの。放課後に灯籠通りふらふら歩いてたら、看板が目に入って。入ったらマスターがいて、コーヒー出してくれて。それから通ってる」"}, {"id": "ch01-s05-p063", "type": "text", "text": "「……そうですか」"}, {"id": "ch01-s05-p064", "type": "text", "text": "「蓮くん、敬語」"}, {"id": "ch01-s05-p065", "type": "text", "text": "「……そうか」"}, {"id": "ch01-s05-p066", "type": "text", "text": "天城さんが笑った。口を開けて、歯を見せて。食堂の時と同じ笑い方。顔の全部が動く。"}, {"id": "ch01-s05-p067", "type": "text", "text": "マスターがコーヒーを運んできた。白い陶器のカップが二つ。天城さんの方はミルクが入って薄茶色、俺の方は黒い液面が揺れていた。カップの取っ手が右側に揃えてある。さっきカウンターで見たのと同じ配置。"}, {"id": "ch01-s05-p068", "type": "text", "text": "「どうぞ。ゆっくりしていきなさい」"}, {"id": "ch01-s05-p069", "type": "text", "text": "マスターはそれだけ言って、カウンターに戻った。"}, {"id": "ch01-s05-p070", "type": "text", "text": "コーヒーを見た。黒い液面に、天井の裸電球の光が小さな点になって映っている。湯気が立っている。苦い匂いの中に、甘い匂いが混じっていた。焦がした砂糖のような。"}, {"id": "ch01-s05-p071", "type": "text", "text": "カップを持ち上げた。唇に縁が触れる。熱い。一口だけ啜った。"}, {"id": "ch01-s05-p072", "type": "text", "text": "舌の上に広がった味は、これまで食べたどの食べ物とも違った。焼き魚でもなく、味噌汁でもなく、漬物でもない。苦い。苦いが、苦いだけではない。苦味の奥に何かある。酸味に近いような。あるいはもっと別の、舌の奥と鼻の間を通り抜けていく、名前のわからない味。"}, {"id": "ch01-s05-p073", "type": "text", "text": "もう一口飲んだ。"}, {"id": "ch01-s05-p074", "type": "text", "text": "味が変わった。二口目は一口目より苦味が薄くなっていた。舌が慣れたのか、温度が下がって味の層が変わったのか。わからない。味の変化に名前がつけられない。焼き魚は「おいしい」と言えた。味噌汁も、漬物も。でもコーヒーは、言葉にする前に味が通り過ぎていく。"}, {"id": "ch01-s05-p075", "type": "text", "text": "天城さんが、両手でカップを包むようにして俺を見ていた。"}, {"id": "ch01-s05-p076", "type": "text", "text": "「どう？」"}, {"id": "ch01-s05-p077", "type": "text", "text": "「……おいしい……のだと思います」"}, {"id": "ch01-s05-p078", "type": "text", "text": "「何その感想！」"}, {"id": "ch01-s05-p079", "type": "text", "text": "天城さんが噴き出した。テーブルの油灯の火が、笑い声の振動で揺れた。"}, {"id": "ch01-s05-p080", "type": "text", "text": "「昼もそうだったじゃん。『思います』って！ おいしいかおいしくないか、どっち！」"}, {"id": "ch01-s05-p081", "type": "text", "text": "「……おいしい、と思う。味の名前がわからなくて」"}, {"id": "ch01-s05-p082", "type": "text", "text": "「味の名前？」"}, {"id": "ch01-s05-p083", "type": "text", "text": "「焼き魚はおいしいとわかった。でもコーヒーは、おいしいかどうかの前に、何の味かが整理できなくて」"}, {"id": "ch01-s05-p084", "type": "text", "text": "自分でも不思議な説明だった。天城さんは目を丸くして、それからまた笑った。今度は声を出さずに、肩が揺れるだけの笑い方。"}, {"id": "ch01-s05-p085", "type": "text", "text": "「蓮くん、変な人だね」"}, {"id": "ch01-s05-p086", "type": "text", "text": "「……よく言われるかは、わからないけど」"}, {"id": "ch01-s05-p087", "type": "text", "text": "「褒めてるんだよ。変って、面白いってこと」"}, {"id": "ch01-s05-p088", "type": "text", "text": "天城さんはコーヒーを一口飲んで、「うん、今日のもおいしい」と小さく頷いた。それからテーブルの油灯の火を指で指して、"}, {"id": "ch01-s05-p089", "type": "text", "text": "「ねえ蓮くん。ここ、みんなの集合場所にしない？」"}, {"id": "ch01-s05-p090", "type": "text", "text": "「みんな」"}, {"id": "ch01-s05-p091", "type": "text", "text": "「うん。蓮くんと、あたしと、あと……まだあんまり友達いないけど、これから増えるでしょ。学院でできた友達とか、蓮くんの同僚の人とか。放課後にここに来て、コーヒー飲んで、だらだらして。そういうの」"}, {"id": "ch01-s05-p092", "type": "text", "text": "天城さんの顔は、提案しているというより、もう決めた後の顔だった。食堂で向かいに座った時と同じ。許可を取るより行動が先にある。"}, {"id": "ch01-s05-p093", "type": "text", "text": "「あたし、一人だとさ、あんまり——」"}, {"id": "ch01-s05-p094", "type": "text", "text": "言いかけて、天城さんは自分でその先を飲み込んだ。ミルク入りのコーヒーを一口含んで、「うん」とだけ言って、笑顔に戻った。"}, {"id": "ch01-s05-p095", "type": "text", "text": "何を言いかけたのか。わからなかった。けれど昼の食堂でも、同じ種類の一瞬があった。表情が動いて、止まって、すぐに笑顔が被さる。"}, {"id": "ch01-s05-p096", "type": "text", "text": "聞くべきなのかもしれない。聞かないべきなのかもしれない。どちらが正しいのか、判断がつかない。"}, {"id": "ch01-s05-p097", "type": "text", "text": "だから、別のことを言った。"}, {"id": "ch01-s05-p098", "type": "text", "text": "「……ここが、集合場所だって。覚えておく」"}, {"id": "ch01-s05-p099", "type": "text", "text": "天城さんの目が丸くなった。それから、口元がゆっくりと上がった。さっきの噴き出す笑い方とは違う。食堂で「ありがとう」と言った時に返ってきた「にっ」に近い顔。"}, {"id": "ch01-s05-p100", "type": "text", "text": "「うん！ じゃあ約束ね、蓮くん」"}, {"id": "ch01-s05-p101", "type": "text", "text": "窓の外で、灯籠通りの灯籠がもう全部灯っていた。煉瓦の通りが橙色の光で満ちている。その光が磨りガラス越しに店内に入ってきて、テーブルの油灯の光と混じり合っていた。"}, {"id": "ch01-s05-p102", "type": "text", "text": "コーヒーはまだ半分残っていた。三口目を飲む。苦い。苦いけれど、さっきより味の輪郭が見えてきた。この味は嫌ではない。たぶん。"}, {"id": "ch01-s05-p103", "type": "text", "text": "喫茶「残響」。灯籠通りの中ほどにある、古い木造の店。コーヒー一杯十五ベル。"}, {"id": "ch01-s05-p104", "type": "text", "text": "悪くない。"}, {"id": "ch01-s05-p105", "type": "text", "text": "たぶん、悪くない場所だと思う。"}]}, {"chapter": 1, "chapterTitle": "霧の中の名前", "scene": 6, "sceneTitle": "天蓋の間の少女", "wordCount": "約6,200字", "paragraphs": [{"id": "ch01-s06-p001", "type": "text", "text": "補佐官舎に戻り、着替え、湯を沸かして顔を洗い直した。夕食は官舎の台所にあった乾麺を茹でた。醤油をかけて食べた。味はわかった。塩味と小麦の味。コーヒーよりずっと簡単な味だった。"}, {"id": "ch01-s06-p002", "type": "text", "text": "食べ終えて、時計を見た。十九時十五分。"}, {"id": "ch01-s06-p003", "type": "text", "text": "明日の共鳴管洗浄の資機材リストは管理室の机に置いてある。霜月さんの指示は今日中に。それは済ませた。けれど、もう一つ。翌日の洗浄作業に先立って、夜間の計器数値を確認しておきたかった。第三系統の低下傾向が夜間にどう推移するか。鐘が鳴らない時間帯の残響紋の振動が計器にどう反映されるか。"}, {"id": "ch01-s06-p004", "type": "text", "text": "マニュアルには夜間巡回点検の記載があった。補佐官の裁量で実施可能。義務ではない。義務ではないが、初日に夜間のデータを一度見ておくのは、悪くない判断だと思った。"}, {"id": "ch01-s06-p005", "type": "text", "text": "上着を羽織り、鍵束をポケットに入れて、補佐官舎を出た。"}, {"id": "ch01-s06-p006", "type": "text", "text": "夜の灯籠通りは、夕方とは違う顔をしていた。"}, {"id": "ch01-s06-p007", "type": "text", "text": "灯籠が全部灯っている。橙色の火が等間隔に並んで、煉瓦の通りを照らしている。商店の大半は閉まっていて、暖簾がたたまれ、看板の文字だけが灯籠の光に浮かんでいた。通りを歩く人は少ない。夕方の喧騒が嘘のように、灯籠の油がぱちりと弾ける音だけが耳に届く。"}, {"id": "ch01-s06-p008", "type": "text", "text": "喫茶「残響」の前を通り過ぎた。磨りガラスの向こうに灯りが見えた。まだ開いている。マスターがカウンターに立っているのだろう。今朝初めて会った人の姿が、ガラス越しの光の中にぼんやり浮かぶ。"}, {"id": "ch01-s06-p009", "type": "text", "text": "通り過ぎる。"}, {"id": "ch01-s06-p010", "type": "text", "text": "鐘鋳塔に向かう道を歩く。灯籠通りを北に折れて、学院の南門を抜けると、教室棟の裏手に出る。そこから渡り廊下を通って鐘鋳塔の正面入口に着くまで、およそ七分。夜の渡り廊下は残響灯が壁に嵌め込まれていて、青白い光が石の床に帯のように落ちていた。足音が響く。昼間より音がよく通る。空気が冷えている分だけ、音の輪郭が硬い。"}, {"id": "ch01-s06-p011", "type": "text", "text": "正面入口で鍵を使い、管理室に入った。"}, {"id": "ch01-s06-p012", "type": "text", "text": "計器の針を読む。第三系統の数値は昼間と変わっていない。記録用紙に時刻と数値を書き入れた。十九時四十五分。"}, {"id": "ch01-s06-p013", "type": "text", "text": "これで夜間の基準点は取れた。翌朝の数値と比較すれば、夜間の推移がわかる。"}, {"id": "ch01-s06-p014", "type": "text", "text": "記録用紙を机に置き、ペンを棚に戻す。管理室を出ようとして、ふと足が止まった。"}, {"id": "ch01-s06-p015", "type": "text", "text": "鐘鋳塔は十一階建てだ。一階が管理室。地下一階に機構室。地下二階に記憶の間。二階から九階が残響紋の刻まれた構造壁。十階に大鐘。そして十一階——最上階が天蓋の間。"}, {"id": "ch01-s06-p016", "type": "text", "text": "マニュアルの塔の断面図を思い出す。天蓋の間。ガラス張りの天蓋を持つ展望空間。大鐘の直上に位置し、鐘の振動を天蓋から外に放出する構造になっている。夜間巡回点検の範囲には含まれていないが、立入禁止でもない。鍵束にも天蓋の間の鍵は含まれていなかった。鍵が不要ということは、常時開放されているのだろう。"}, {"id": "ch01-s06-p017", "type": "text", "text": "行ってみようと思った。"}, {"id": "ch01-s06-p018", "type": "text", "text": "理由は明確ではない。初日だから塔の全体を把握しておきたい、という理屈は後からつけたもので、足が階段に向かったのが先だった。"}, {"id": "ch01-s06-p019", "type": "text", "text": "螺旋階段を上る。鐘鋳塔の内部は中空の円筒で、壁に沿って石の階段が螺旋状に伸びている。壁面の残響灯が一定間隔で青白い光を落としていた。朝、一階の管理室で見た光と同じ色。けれど、上に行くにつれて光の色がわずかに変わっていた。青白さの中に、もう少し深い色が混じっている。紫に近い。"}, {"id": "ch01-s06-p020", "type": "text", "text": "五階を過ぎたあたりで、空気が変わった。"}, {"id": "ch01-s06-p021", "type": "text", "text": "温度はさほど変わらない。空気の密度が、違う。下の階ではただの空気だったものが、ここでは少し重い。体に纏わりつくような。歩くたびに、空気の層を一枚一枚めくっている感覚があった。"}, {"id": "ch01-s06-p022", "type": "text", "text": "八階。九階。石段を踏む足音が自分の上から返ってくる。残響灯の光が、壁面に刻まれた残響紋に落ちて、紋様の彫りの中に影を作っていた。紋様は階によって違う。下の階は幾何学的な直線の組み合わせだったが、上に行くほど曲線が増えていく。水の流れのような。植物の蔓のような。"}, {"id": "ch01-s06-p023", "type": "text", "text": "十階。"}, {"id": "ch01-s06-p024", "type": "text", "text": "大鐘があった。"}, {"id": "ch01-s06-p025", "type": "text", "text": "螺旋階段が広い踊り場に出て、その中央に鐘が据えられている。直径約五メートル。残響金属の青みがかった表面に、外壁と同じ残響紋が全面に刻まれていた。鐘の下に音響増幅器と打鐘機構が組み込まれている。朝の六時半に鳴ったのがこの鐘だ。あの音は、ここから生まれた。"}, {"id": "ch01-s06-p026", "type": "text", "text": "鐘の表面に手を伸ばしかけて、止めた。触れていいものかわからなかった。今は鐘打ちの時間ではないが、残響紋には微弱な振動が残っているはずだ。管理室の計器がそれを拾っている。触れれば、その振動を感じるのかもしれない。"}, {"id": "ch01-s06-p027", "type": "text", "text": "止めた。手を下ろした。"}, {"id": "ch01-s06-p028", "type": "text", "text": "鐘の脇を通り過ぎ、さらに上の階段に足をかける。最後の一層。十一階。天蓋の間。"}, {"id": "ch01-s06-p029", "type": "text", "text": "石段が途切れた。"}, {"id": "ch01-s06-p030", "type": "text", "text": "足の下が石から木に変わった。磨かれた木の床。踏むと、石段にはなかった微かな弾力があった。靴底を通して、木の繊維の柔らかさが伝わってくる。"}, {"id": "ch01-s06-p031", "type": "text", "text": "そして、上を見た。"}, {"id": "ch01-s06-p032", "type": "text", "text": "天蓋が、あった。"}, {"id": "ch01-s06-p033", "type": "text", "text": "ガラスの天蓋。円形の部屋の天井すべてがガラスで出来ていて、その向こうに夜の空があった。"}, {"id": "ch01-s06-p034", "type": "text", "text": "星が見えた。"}, {"id": "ch01-s06-p035", "type": "text", "text": "一つ、二つではなく、無数に。黒い空の全面に、白い点が散っていた。鐘鋳塔は島で最も高い建物で、十一階ともなれば周囲に遮るものは何もない。ガラスの天蓋を通して、空がそのまま部屋の天井になっていた。"}, {"id": "ch01-s06-p036", "type": "text", "text": "残響灯の光は、この階にはなかった。灯りがない。代わりに、星の光だけがある。ガラスを透過した微かな光が、木の床に淡い模様を落としていた。目が慣れるにつれて、部屋の輪郭が浮かび上がってくる。円形の壁面。壁に沿って低い棚がいくつか。棚の上に何かが置いてある。暗くてよく見えない。部屋の中央には何もなかった。木の床があるだけ。"}, {"id": "ch01-s06-p037", "type": "text", "text": "天蓋を見上げた。"}, {"id": "ch01-s06-p038", "type": "text", "text": "星が、多い。こんなに多いものだったか。監視哨でも夜空は見えた。蝕域の観測を行う時、双眼鏡を下ろして空を見上げることがあった。けれど、あの頃は空を見る目的は天候の確認で、星の数を数えたことはなかった。"}, {"id": "ch01-s06-p039", "type": "text", "text": "ここでは、数えたくなる。"}, {"id": "ch01-s06-p040", "type": "text", "text": "なぜかはわからない。ガラスの天蓋越しに見上げる星空には、計器の数値を読む時とは違う明瞭さがあった。星の一つ一つが、位置と明るさという情報を持って、そこに在る。読み取れる。読み取れるが、計器と違って意味を求められていない。正常か異常かを判断する必要がない。ただ在って、ただ光っている。"}, {"id": "ch01-s06-p041", "type": "text", "text": "安心する、と思った。"}, {"id": "ch01-s06-p042", "type": "text", "text": "理由はない。理由のない安心。朝の鐘の音を聴いた時に「懐かしい」と感じたのと同じ種類の、記憶にない感覚。星を見上げて安心する理由が、俺にはないはずだ。監視哨で星が安心材料だった覚えはない。夜は蝕域の動きが活発になる時間帯で、星空は緊張の背景だった。"}, {"id": "ch01-s06-p043", "type": "text", "text": "なのに。"}, {"id": "ch01-s06-p044", "type": "text", "text": "木の床に足を投げ出して、天蓋を見上げた。座る場所を探す必要はなかった。床が乾いていて、埃もほとんどない。誰かが掃除しているのか。"}, {"id": "ch01-s06-p045", "type": "text", "text": "しばらく、そのままでいた。"}, {"id": "ch01-s06-p046", "type": "text", "text": "どのくらいの時間が経ったのかわからない。星は動いていない。いや、動いているはずだが、肉眼でわかるほどの速度ではない。時計を見なかった。見る気にならなかった。ここでは時間が、少し遠い。"}, {"id": "ch01-s06-p047", "type": "text", "text": "足音が聞こえた。"}, {"id": "ch01-s06-p048", "type": "text", "text": "——いや。足音では、なかった。"}, {"id": "ch01-s06-p049", "type": "text", "text": "足音がしていない、ということに気づいた。気づいた時には、もう気配があった。背後の、螺旋階段の方向。誰かがいる。視界に入る前に、空気の変化でわかった。地下の機構室で霜月さんが現れた時とは質が違う。あの時は「圧が加わった」感覚だった。今は逆だ。空気がわずかに軽くなった。何かが減ったのではなく、空気の一部が入れ替わったような。"}, {"id": "ch01-s06-p050", "type": "text", "text": "振り返った。"}, {"id": "ch01-s06-p051", "type": "text", "text": "少女が、立っていた。"}, {"id": "ch01-s06-p052", "type": "text", "text": "螺旋階段の最上段。木の床との境目に、裸足の足先が覗いていた。白い。小さい。足の甲に青い血管が透けていた。裸足のまま石段を上ってきたのだろうか。"}, {"id": "ch01-s06-p053", "type": "text", "text": "視線を上げる。白いワンピース。袖がなく、鎖骨と肩が露出している。華奢な体。鎖骨の下に細い銀の鎖がかかっていて、鎖の先に小さな鍵の形をした飾りが揺れていた。"}, {"id": "ch01-s06-p054", "type": "text", "text": "髪は長かった。腰まで。色が——残響灯の光のない部屋で、星の光だけで見ているのに、色がわかった。淡い紫。濃い紫ではなく、薄い。白に近い紫。残響桜の花弁の色に似ている。その髪が風もないのにわずかに揺れていた。"}, {"id": "ch01-s06-p055", "type": "text", "text": "目が合った。"}, {"id": "ch01-s06-p056", "type": "text", "text": "薄い紫色の瞳。星の光を映して、瞳の中に小さな白い点がいくつも浮かんでいた。人間の目だ。人間の目のはずだ。虹彩があり、瞳孔があり、白目がある。ただ、目の中の光の散り方が、普通と違っていた。何が普通かの基準を俺は持っていないのだけれど。"}, {"id": "ch01-s06-p057", "type": "text", "text": "少女は俺を見ていた。"}, {"id": "ch01-s06-p058", "type": "text", "text": "表情が動いた。口元がわずかに上がって、その動きが目に届くまでに、わずかな間があった。口が先に微笑の形を作り、目はまだ動かずにいて、それから遅れて目尻が下がる。0.5秒か、もう少し短いか。人がする微笑みとは、何かが違う。けれど、不自然とも言い切れない。微笑むという動作を、一つずつ順番に組み立てているような。"}, {"id": "ch01-s06-p059", "type": "text", "text": "「……れん」"}, {"id": "ch01-s06-p060", "type": "text", "text": "声が聞こえた。"}, {"id": "ch01-s06-p061", "type": "text", "text": "高い声だった。高いが、細い。糸を指で弾いたような、輪郭の薄い音。声量が小さく、天蓋の間の広い空間の中ですぐに消えそうだったが、不思議と聞き取れた。反響がない。石壁の部屋なら声は壁に当たって返ってくるが、ここは天蓋がガラスで、壁も上半分がガラスだから、音が逃げていく。その逃げていく音の中に、名前があった。"}, {"id": "ch01-s06-p062", "type": "text", "text": "蓮。"}, {"id": "ch01-s06-p063", "type": "text", "text": "俺の名前。"}, {"id": "ch01-s06-p064", "type": "text", "text": "「……何で、俺の名前を」"}, {"id": "ch01-s06-p065", "type": "text", "text": "言葉が出た。驚いているのだと思う。足はまだ床に投げ出したままで、立ち上がれていない。初対面の人間が、自己紹介もなく名前を呼んだ。"}, {"id": "ch01-s06-p066", "type": "text", "text": "少女は螺旋階段から木の床に足を踏み出した。足音がしない。裸足の足が木の床に触れているのは見えた。踏んでいる。けれど音がない。体重が極端に軽いのか、床に触れる力が弱いのか。"}, {"id": "ch01-s06-p067", "type": "text", "text": "「かねが、おしえてくれた」"}, {"id": "ch01-s06-p068", "type": "text", "text": "「鐘が」"}, {"id": "ch01-s06-p069", "type": "text", "text": "「うん。れんがきょう、ここにくるって。かねがそういってた。すみれ、まってた」"}, {"id": "ch01-s06-p070", "type": "text", "text": "すみれ。名前なのだろう。自分のことを自分の名前で呼んでいる。子供のような話し方だった。見た目は——十五歳くらいか。俺より二つか三つ下に見える。けれど話し方はもっと幼い。"}, {"id": "ch01-s06-p071", "type": "text", "text": "俺はゆっくり立ち上がった。少女——すみれは、俺の三歩ほど前に立って、こちらを見上げていた。身長は俺の肩のあたりまでしかない。小さい。"}, {"id": "ch01-s06-p072", "type": "text", "text": "「……すみれ」"}, {"id": "ch01-s06-p073", "type": "text", "text": "名前を言ってみた。「さん」はつけなかった。すみれ、と名乗ったから。敬称を求めている口調ではなかった。というより、敬称という概念がない話し方だった。天城さんが「天城燈花！ よろしくね」と名乗った時とは違う。あれは省略で、これは不在だ。"}, {"id": "ch01-s06-p074", "type": "text", "text": "すみれは「うん」と頷いた。頷く動作も、やはりどこかゆっくりだった。首が傾いて、戻るまでの間隔が長い。"}, {"id": "ch01-s06-p075", "type": "text", "text": "「ここ、すみれのおうち」"}, {"id": "ch01-s06-p076", "type": "text", "text": "「……おうち」"}, {"id": "ch01-s06-p077", "type": "text", "text": "「うん。すみれ、ずっとここにいるの。てんがいのま」"}, {"id": "ch01-s06-p078", "type": "text", "text": "天蓋の間が、この子の家。住んでいるのか。塔の最上階に。学院の関係者だろうか。マニュアルにも人事書類にも、この場所に住人がいるとは書かれていなかった。"}, {"id": "ch01-s06-p079", "type": "text", "text": "「……ここに住んでいるのか」"}, {"id": "ch01-s06-p080", "type": "text", "text": "「うん」"}, {"id": "ch01-s06-p081", "type": "text", "text": "「学院の生徒？」"}, {"id": "ch01-s06-p082", "type": "text", "text": "すみれは首を傾げた。傾げたまま、しばらく戻らなかった。考えているのか。質問の意味がわからないのか。"}, {"id": "ch01-s06-p083", "type": "text", "text": "「がくいん……すみれは、すみれだよ」"}, {"id": "ch01-s06-p084", "type": "text", "text": "答えになっていない。なっていないが、すみれ自身にとってはそれが答えなのだろう。学院とか生徒とか、そういう枠組みの外にいる口振りだった。"}, {"id": "ch01-s06-p085", "type": "text", "text": "追及しなかった。初日に、塔の最上階で裸足の少女に会った。それだけのことだ。不審に思うべきかもしれない。霜月さんに報告すべきかもしれない。けれど、不審者を前にした時の緊張が、自分の中にない。機構室で霜月さんの気配に気づいた時は背中に緊張が走った。今はそれがない。すみれの気配には重さがなかった。"}, {"id": "ch01-s06-p086", "type": "text", "text": "すみれが天蓋を見上げた。俺もつられて見上げた。星空は変わっていない。"}, {"id": "ch01-s06-p087", "type": "text", "text": "「ねえ、れん。かねのおと、きこえる？」"}, {"id": "ch01-s06-p088", "type": "text", "text": "「鐘の音？ 今は鳴っていないけど」"}, {"id": "ch01-s06-p089", "type": "text", "text": "「ならしてないときも、のこってるの。ここは、ずっときこえるの」"}, {"id": "ch01-s06-p090", "type": "text", "text": "残響。鐘が鳴っていない時間帯でも、残響紋に微弱な振動が残っている。計器の針はそれを拾っている。すみれが言っているのはそのことだろうか。"}, {"id": "ch01-s06-p091", "type": "text", "text": "耳を澄ませた。静かだった。自分の呼吸の音と、遠くの風の音だけ。鐘の音は聞こえない。"}, {"id": "ch01-s06-p092", "type": "text", "text": "「……俺には聞こえない」"}, {"id": "ch01-s06-p093", "type": "text", "text": "「そう」"}, {"id": "ch01-s06-p094", "type": "text", "text": "すみれは残念そうにはしなかった。淡々と受け止めた。それから、ゆっくりと俺の左手に視線を移した。"}, {"id": "ch01-s06-p095", "type": "text", "text": "左手首。ブレスレットのあたり。"}, {"id": "ch01-s06-p096", "type": "text", "text": "すみれの目が止まった。星の光を映した薄紫の瞳が、細い革紐の編み込み模様をじっと見ている。瞬きをしない。五秒か。もっとか。長い。"}, {"id": "ch01-s06-p097", "type": "text", "text": "「……それ、たいせつなもの？」"}, {"id": "ch01-s06-p098", "type": "text", "text": "声が小さくなった。さっきよりさらに細い。糸の先端のような声。"}, {"id": "ch01-s06-p099", "type": "text", "text": "左手首のブレスレットを見た。三本の革紐。使い込まれて色が濃くなった編み目。毛羽立ち。今朝も、いつものように指先で一瞬だけ触れた。毎朝触れている。理由はわからない。"}, {"id": "ch01-s06-p100", "type": "text", "text": "「……わからない。大切かどうかは、わからない。でも外す気にならない」"}, {"id": "ch01-s06-p101", "type": "text", "text": "正直に答えた。大切なもの、という感覚があるのかどうか。大切とはどういう状態のことを言うのか。わからない。わからないが、外さない。外す気にならない。この二年間、一度も外さなかった。入浴の時も、寝る時も。外す理由がない。外さない理由もない。ただ、ここにある。"}, {"id": "ch01-s06-p102", "type": "text", "text": "すみれの口元が動いた。さっきと同じ微笑み。口が先に形を作って、目が遅れて追いかける。けれど今回は、遅れが少し短かった気がする。"}, {"id": "ch01-s06-p103", "type": "text", "text": "「……うん」"}, {"id": "ch01-s06-p104", "type": "text", "text": "すみれはそう言って、俺の手首にほんの少し顔を寄せた。鼻先が革紐の近くで止まる。匂いを嗅いでいるのだと、一拍遅れて気づいた。"}, {"id": "ch01-s06-p105", "type": "text", "text": "「……なつかしいにおいが、する」"}, {"id": "ch01-s06-p106", "type": "text", "text": "匂い。使い込まれた革紐の匂いだろうか。汗と日光と、二年分の時間が染み込んだ匂い。俺自身はもう慣れてしまって感じない。"}, {"id": "ch01-s06-p107", "type": "text", "text": "「知ってる匂いなのか」"}, {"id": "ch01-s06-p108", "type": "text", "text": "すみれは答えなかった。顔を離して、首を傾げたまましばらくブレスレットを見ていた。瞳の中の星の光が、ゆっくりと揺れている。"}, {"id": "ch01-s06-p109", "type": "text", "text": "何を納得したのか。匂いの何を知っていたのか。聞くべきだったかもしれない。けれど、天城さんの表情が止まった時と同じだ。聞くべきかどうかの判断がつかない。"}, {"id": "ch01-s06-p110", "type": "text", "text": "すみれは俺から離れて、天蓋の間の壁際に歩いていった。裸足の足が木の床の上を滑るように進む。音がない。低い棚の前にしゃがんで、棚の上に置いてあるものに手を伸ばした。暗くて見えなかったが、すみれが持ち上げたのは小さなノートのようなものだった。"}, {"id": "ch01-s06-p111", "type": "text", "text": "「すみれね、ほしをかぞえてるの」"}, {"id": "ch01-s06-p112", "type": "text", "text": "「星を」"}, {"id": "ch01-s06-p113", "type": "text", "text": "「うん。てんがいからみえるほし。ぜんぶかぞえるの。でもね、おなじほしをなんどもかぞえちゃうの。どれがどれか、わかんなくなって」"}, {"id": "ch01-s06-p114", "type": "text", "text": "ノートを開いて、俺に見せた。星の光だけでは読めない。目を凝らすと、ページに小さな丸が無数に描かれていて、丸の横に数字が書いてあった。1、2、3……途中で数字が飛んで、また1から始まっている。同じ星を何度も数え直しているのだろう。"}, {"id": "ch01-s06-p115", "type": "text", "text": "「さっき、って言ったのがいつのことかもわかんない。すみれ、ときどきわかんなくなるの。きのうのことだったのか、まえのまえのまえのことだったのか」"}, {"id": "ch01-s06-p116", "type": "text", "text": "時間の感覚がずれている。子供の感覚とも違う。子供は「昨日」と「三日前」を混同するが、すみれの言い方はもっと大きなずれを示唆していた。「さっき」が何年も前のことだったりするのか。"}, {"id": "ch01-s06-p117", "type": "text", "text": "不思議な子だった。"}, {"id": "ch01-s06-p118", "type": "text", "text": "裸足で石段を上り、足音がせず、鐘の声が聞こえると言い、俺の名前を知っていて、星を数えて同じ星を何度も数え、時間の感覚があやふやで、微笑む時に口と目がずれる。"}, {"id": "ch01-s06-p119", "type": "text", "text": "不気味ではなかった。怖くもなかった。霜月さんの時と同じだ——「そういう人なのだろう」と思えばいい。ただ、霜月さんの時に感じた「何もない」ともまた違う。すみれの前では、何かある。何かあるが、名前がつかない。"}, {"id": "ch01-s06-p120", "type": "text", "text": "不思議。"}, {"id": "ch01-s06-p121", "type": "text", "text": "その言葉が一番近い気がした。"}, {"id": "ch01-s06-p122", "type": "text", "text": "すみれがノートを閉じて、天蓋を見上げた。銀の鎖のペンダントが鎖骨の上で小さく揺れた。鍵の形の飾り。お守り、と呼ぶのだろうか。"}, {"id": "ch01-s06-p123", "type": "text", "text": "「れん、あのね」"}, {"id": "ch01-s06-p124", "type": "text", "text": "「何」"}, {"id": "ch01-s06-p125", "type": "text", "text": "「また、きてね。ここ」"}, {"id": "ch01-s06-p126", "type": "text", "text": "すみれの声は、相変わらず細かった。けれど、その一言だけかすかに太くなった気がする。気がしただけかもしれない。星の光の中で、すみれの薄紫の髪が淡く光っていた。"}, {"id": "ch01-s06-p127", "type": "text", "text": "遠くで——鐘の余韻が聞こえた気がした。鳴っていないはずの鐘。残響紋に残った振動の、そのまた残響。聞こえた気がしただけだ。計器の前なら確認できるが、ここでは耳しかない。耳では判別できない。"}, {"id": "ch01-s06-p128", "type": "text", "text": "「……覚えておく」"}, {"id": "ch01-s06-p129", "type": "text", "text": "口から出ていた。天城さんに「集合場所だって」と言ったのと同じ言葉。それが、俺のできる応答の形らしい。"}, {"id": "ch01-s06-p130", "type": "text", "text": "すみれは頷いた。今度は頷きの動きが早かった。小さく、一度だけ。"}, {"id": "ch01-s06-p131", "type": "text", "text": "俺は天蓋の間を出た。螺旋階段を降りていく。石段の冷たさが、木の床との違いを靴底に伝えてくる。残響灯の青白い光が壁面に戻ってきた。十階の大鐘の脇を通り過ぎる。触れなかった鐘の表面が、青白い光の中で静かに在った。"}, {"id": "ch01-s06-p132", "type": "text", "text": "九階。八階。七階。"}, {"id": "ch01-s06-p133", "type": "text", "text": "降りるにつれて、天蓋の間の空気が遠くなっていく。あの軽さ。星の光だけの暗さ。裸足の足音のしない少女。紫の髪と、薄紫の瞳の中の星の光。"}, {"id": "ch01-s06-p134", "type": "text", "text": "今日一日で、何人かの人に会った。"}, {"id": "ch01-s06-p135", "type": "text", "text": "天城さんは眩しかった。ポニーテールが揺れるリズムと、許可を取らない笑い方と、腕を掴む躊躇のない手。灯籠の橙色が似合う人。"}, {"id": "ch01-s06-p136", "type": "text", "text": "霜月さんは冷たかった。白いコートと感情のない声と、一拍の空白。残響灯の青白さの中で動く壁のような人。"}, {"id": "ch01-s06-p137", "type": "text", "text": "すみれは——不思議だった。裸足で足音がしなくて、鐘の声が聞こえると言って、俺の名前を知っていて、星を数えて迷子になる。星の光の中にいる人。"}, {"id": "ch01-s06-p138", "type": "text", "text": "どれも、俺にとっては初めての感覚だった。"}, {"id": "ch01-s06-p139", "type": "text", "text": "感覚、と呼んでいいのなら。"}, {"id": "ch01-s06-p140", "type": "text", "text": "眩しい、冷たい、不思議。それぞれが違う。それぞれが違うということがわかること自体が、たぶん、何かの変化なのだと思う。昨日までの俺は——監視哨にいた頃の俺は、人と人を区別して、それぞれに別の名前をつけることをしなかった。人は人だった。上官と、同僚と、たまに来る補給係。区別はあったが、感覚の違いはなかった。"}, {"id": "ch01-s06-p141", "type": "text", "text": "今日は違った。"}, {"id": "ch01-s06-p142", "type": "text", "text": "一階の管理室に着いた。計器の針を最後にもう一度確認する。第三系統の針は朝と同じ振幅で揺れている。変わらない。"}, {"id": "ch01-s06-p143", "type": "text", "text": "数字は変わらないが、俺の中の何かは、朝とは少し違う場所にある。"}, {"id": "ch01-s06-p144", "type": "text", "text": "管理室の消灯。施錠。鐘鋳塔の正面入口を出る。"}, {"id": "ch01-s06-p145", "type": "text", "text": "夜空を見上げた。天蓋の間ほどではないが、星は見えた。あの子が今も上で星を数えているのか。同じ星を何度も数えて、「さっき」がいつだったかわからなくなりながら。"}, {"id": "ch01-s06-p146", "type": "text", "text": "天蓋の間。星の光。裸足の少女。すみれ。"}, {"id": "ch01-s06-p147", "type": "text", "text": "悪くない。……いや、違う。悪い悪くないではなく、あの場所は、そういう尺度の外にあった。喫茶「残響」が「悪くない場所」だったのとは違う。天蓋の間は、判断がつかない場所だった。判断がつかないのに、また行ってもいいと思った。"}, {"id": "ch01-s06-p148", "type": "text", "text": "それを何と呼ぶのか。"}, {"id": "ch01-s06-p149", "type": "text", "text": "わからない。わからないけれど、覚えておく。"}]}, {"chapter": 2, "chapterTitle": "灯籠通りの声", "scene": 1, "sceneTitle": "共鳴者訓練棟の前で", "wordCount": "約5,000字", "paragraphs": [{"id": "ch02-s01-p001", "type": "text", "text": "共鳴管の洗浄に三日かかった。"}, {"id": "ch02-s01-p002", "type": "text", "text": "第三系統の内壁に堆積していた膜状物質は、霜月さんの予測通り残響紋の微弱堆積だった。共鳴管の内側に、鐘の振動が年月をかけて薄い層を形成していたのだ。マニュアルには堆積の除去手順が細かく書かれていて、俺はそれに従って一本ずつ洗浄した。作業が終わった翌日の朝、計器の針が0.1%戻った。0.3%の低下が0.2%になった。完全には戻っていないが、方向としては正しい。"}, {"id": "ch02-s01-p003", "type": "text", "text": "霜月さんは記録用紙を見て「次は第五系統」とだけ言った。"}, {"id": "ch02-s01-p004", "type": "text", "text": "あれから何日か経った。何日か、という曖昧さは、日数を数えていなかったからではない。六日だ。着任から六日。曖昧なのは、六日という時間の重さが実感として掴めないからで、日数そのものは管理室の記録用紙に毎日書き入れているから正確にわかる。"}, {"id": "ch02-s01-p005", "type": "text", "text": "朝の点検を終えて、管理室の机に今日の業務指示書を広げた。"}, {"id": "ch02-s01-p006", "type": "text", "text": "共鳴者適性試験の補助業務。試験会場となる共鳴者訓練棟に音響計測機材を搬入し、設営する。八時三十分までに訓練棟の一階講義室に機材を運び込むこと。機材は管理室の倉庫に保管してある。台車一台分。"}, {"id": "ch02-s01-p007", "type": "text", "text": "倉庫から台車に機材を積む。音響測定器が二台、記録装置が一台、接続ケーブルが束になったもの。機材は重くはなかったが、嵩があった。台車の上で測定器がぐらつかないようにベルトで固定する。ベルトの締め方に手が迷わなかった。こういう作業には慣れがある。道具の固定、運搬、設置。監視哨にいた頃も同じようなことをしていた。"}, {"id": "ch02-s01-p008", "type": "text", "text": "鐘鋳塔を出て、渡り廊下を通り、教室棟の脇を抜ける。朝の八時を過ぎていて、教室棟の窓の向こうから授業の声が微かに聞こえた。始業式から数日が経ち、学院には日常の輪郭が戻っていた。着任の初日には目に映るものすべてが初めてだったが、今は教室棟の煉瓦壁の色も、中庭の残響桜の老木の枝ぶりも、見覚えのあるものになっている。見覚えがある、ということの意味を、俺はまだよく噛めていない。"}, {"id": "ch02-s01-p009", "type": "text", "text": "教室棟の北側を回り込んで、丘の斜面を上る小道に入った。"}, {"id": "ch02-s01-p010", "type": "text", "text": "共鳴者訓練棟は学院の敷地の最上部にある。教室棟や図書館よりも高い場所。石畳の小道が丘の斜面に沿って緩やかに登っていく。台車の車輪が石畳の目地に引っかかるたびに、荷台の機材がかちゃりと鳴った。"}, {"id": "ch02-s01-p011", "type": "text", "text": "朝の空気は澄んでいた。四月中旬。霧はもう出ない日が増えた。着任初日の朝は霧に包まれていたが、ここ数日は晴れが続いている。空の青さが深い。残響桜はまだ咲いている。薄紫の花弁が丘の斜面の植え込みにも散っていて、石畳の隙間に入り込んでいた。踏まないように、というほどの注意は払っていない。ただ目には入る。"}, {"id": "ch02-s01-p012", "type": "text", "text": "小道を五分ほど登ると、訓練棟が見えてきた。"}, {"id": "ch02-s01-p013", "type": "text", "text": "厚い石造りの建物だった。教室棟が赤い煉瓦なのに対して、訓練棟の外壁は灰色の石を積み上げた重厚な構造をしている。窓が少ない。あるにはあるが、小さく、壁の厚みの分だけ奥まっている。防音構造。この建物の中で共鳴者が声を発しても、外には漏れない設計になっている。マニュアルの建物仕様書にそう書いてあった。"}, {"id": "ch02-s01-p014", "type": "text", "text": "訓練棟の正面入口まであと二十歩ほどのところで、台車を押す手が止まった。"}, {"id": "ch02-s01-p015", "type": "text", "text": "音が聞こえた。"}, {"id": "ch02-s01-p016", "type": "text", "text": "いや——音、と呼んでいいのかわからない。空気の振動を耳が拾っている。それは確かだ。けれど音量が極端に小さい。聞こえているのか、聞こえている気がしているだけなのか、その判別がつかないくらいに小さい。"}, {"id": "ch02-s01-p017", "type": "text", "text": "歌だった。"}, {"id": "ch02-s01-p018", "type": "text", "text": "人の声。旋律がある。歌詞は聞き取れない。声の輪郭だけが、薄い石壁を透過して、外の空気に滲み出ている。"}, {"id": "ch02-s01-p019", "type": "text", "text": "完全防音の建物から、音が漏れている。"}, {"id": "ch02-s01-p020", "type": "text", "text": "俺はその矛盾に足を止めた。マニュアルの記述が正しいなら——正しいはずだ、数値で裏づけされた防音性能が記載されていた——この建物の外壁を声が通過するのは、通常では起こらない。声が防音構造の遮音限界を超えているということになる。"}, {"id": "ch02-s01-p021", "type": "text", "text": "台車から手を離した。"}, {"id": "ch02-s01-p022", "type": "text", "text": "静かにしている方が、よく聞こえる。"}, {"id": "ch02-s01-p023", "type": "text", "text": "歌声は途切れない。低い音から始まって、ゆっくりと上がっていく。音程が変わるたびに、空気の質が変わった。今までただの空気だったものが、歌声に触れた部分だけ密度を持つ。肌の上をなぞられるような感覚があった。腕の、袖の下。制服の布地を通して。"}, {"id": "ch02-s01-p024", "type": "text", "text": "鳩尾のあたりが、緩んだ。"}, {"id": "ch02-s01-p025", "type": "text", "text": "何の前触れもなかった。腹の筋肉が緊張を解く感覚。力を入れていたわけではないのに、力が抜けた。監視哨にいた頃から体の芯に張っていた、自分では気づいていなかった硬さが、歌声のたびに少しずつほどけていく。"}, {"id": "ch02-s01-p026", "type": "text", "text": "鐘の音を聴いた時と、似ている。"}, {"id": "ch02-s01-p027", "type": "text", "text": "着任初日の朝。六時半の鐘。あの時も体の中を音が通り過ぎた。胸骨が振動して、指先が痺れた。心地よいと感じた。懐かしいと思った。"}, {"id": "ch02-s01-p028", "type": "text", "text": "今の歌声は、鐘の音よりもさらに深いところに届いていた。鐘の振動は骨を通ったが、この声は骨の内側——骨髄、とでも言うのか。体の構造の、もっと奥。名前をつけられない場所。"}, {"id": "ch02-s01-p029", "type": "text", "text": "目の奥が、熱くなった。"}, {"id": "ch02-s01-p030", "type": "text", "text": "泣く。泣きそうだと思った。まぶたの裏側に熱が溜まって、溢れ出す手前で止まっている。涙は出なかった。出る仕組みが動いていない。蛇口は開いているのに水が来ないような。管は繋がっているが、何かが詰まっている。"}, {"id": "ch02-s01-p031", "type": "text", "text": "なぜ泣くのか。泣く理由がない。知らない人の歌声を聴いて泣く理由が、俺の中にはないはずだ。ないはずなのに、体が泣こうとしている。体が先に動いて、理由が追いつかない。初日に天蓋の間に行こうと思った時の、足が先に動いた感覚に近い。"}, {"id": "ch02-s01-p032", "type": "text", "text": "歌声は続いていた。"}, {"id": "ch02-s01-p033", "type": "text", "text": "俺は訓練棟の外壁の前に立ったまま、動けなかった。動く必要がなかった。機材の搬入には時間の余裕がある。ここに立っていても、誰に咎められることもない。"}, {"id": "ch02-s01-p034", "type": "text", "text": "歌が、止んだ。"}, {"id": "ch02-s01-p035", "type": "text", "text": "最後の音が伸びて、薄くなって、朝の空気に溶けた。溶けた後に、静寂が来た。さっきまでの静寂とは違う静寂だった。歌声がそこにあった分だけ、消えた後の空白が深い。"}, {"id": "ch02-s01-p036", "type": "text", "text": "鳩尾の緩みが残っていた。体の芯がまだ柔らかい。ほどけたものが、元に戻りきっていない。"}, {"id": "ch02-s01-p037", "type": "text", "text": "訓練棟の正面入口の扉が開いた。"}, {"id": "ch02-s01-p038", "type": "text", "text": "人が出てきた。"}, {"id": "ch02-s01-p039", "type": "text", "text": "最初に見えたのは髪だった。亜麻色。肩甲骨の下あたりまでの長さ。毛先が自然にカールしていて、朝の日差しが当たったところだけ金色に透けた。前髪は眉にかかる程度で、右側に薄桃色のリボンが留めてある。リボンの色が髪の亜麻色と合っていた。"}, {"id": "ch02-s01-p040", "type": "text", "text": "顔。目元が少し下がっていて、それが穏やかな印象を作っている。瞳の色は——琥珀。茶色よりも明るく、日差しの角度によっては蜂蜜のように見える。朝の光がまっすぐ差す今の時間帯では、琥珀色の中に金が混じっていた。"}, {"id": "ch02-s01-p041", "type": "text", "text": "白いブラウスに淡いブルーのスカート。紺のリボン。学院の制服だ。肩にカーディガンをかけている。左耳に小さな真珠のイヤリングが一つ。歩くたびに揺れた。"}, {"id": "ch02-s01-p042", "type": "text", "text": "背筋が自然に伸びていた。歩幅は小さい。石段を一段ずつ降りてくる足運びに急ぎがない。扉を閉めて、小道に出て、数歩進んだところで、こちらに気づいた。"}, {"id": "ch02-s01-p043", "type": "text", "text": "目が合った。"}, {"id": "ch02-s01-p044", "type": "text", "text": "琥珀色の瞳が俺を捉えた。瞳の色が——さっき、建物の中から聞こえた歌声のことを考えた。今出てきたのがこの人だとすれば、歌っていたのはこの人だ。その瞳の色が、ほんの少しだけ薄く見えた。琥珀の奥にある色の密度が、通常よりも低いような。確信はない。人の瞳の色の「通常」の濃さを、俺は基準として持っていないから。"}, {"id": "ch02-s01-p045", "type": "text", "text": "口元が動いた。微笑んでいる。"}, {"id": "ch02-s01-p046", "type": "text", "text": "「あ、おはようございます」"}, {"id": "ch02-s01-p047", "type": "text", "text": "声が聞こえた。高い声ではない。低い声でもない。声帯を通って唇から出る音が、出た瞬間に丸みを帯びている。角がない。歌声が防音壁を透過するほどの力を持っていたのと同じ声帯から出ている音なのに、今は力が抜けていて、穏やかで、けれど美しかった。"}, {"id": "ch02-s01-p048", "type": "text", "text": "歌っていない時でも、美しい声だった。"}, {"id": "ch02-s01-p049", "type": "text", "text": "その認識が浮かんだ。美しい、という言葉を俺が使うことは少ない。物事を評価する語彙の中に、普段それは含まれていない。けれど今、それ以外の言葉が見つからなかった。"}, {"id": "ch02-s01-p050", "type": "text", "text": "「新しい鐘守補佐の方ですか？」"}, {"id": "ch02-s01-p051", "type": "text", "text": "そう聞かれた。俺が台車の横に立っていて、制服の左腕にバッジをつけているのを見たのだろう。"}, {"id": "ch02-s01-p052", "type": "text", "text": "「……はい。朝霧蓮です」"}, {"id": "ch02-s01-p053", "type": "text", "text": "名乗った。声が少しだけ掠れていた。さっきまで歌声を聴いていた喉が、自分の声を出すことに違和感を覚えている。そんなことがあるのか。"}, {"id": "ch02-s01-p054", "type": "text", "text": "「朝霧さん。わたし、鳴海千歳です。共鳴者の候補生をしています」"}, {"id": "ch02-s01-p055", "type": "text", "text": "鳴海千歳。共鳴者候補生。歌を歌う人。"}, {"id": "ch02-s01-p056", "type": "text", "text": "「今日は適性試験の補助で、機材をお届けに」"}, {"id": "ch02-s01-p057", "type": "text", "text": "俺は台車に視線を向けた。鳴海さんも台車を見て、それから俺に視線を戻した。"}, {"id": "ch02-s01-p058", "type": "text", "text": "「ああ、試験の準備をしてくださるんですね。ありがとうございます」"}, {"id": "ch02-s01-p059", "type": "text", "text": "微笑みが深くなった。目元が柔らかくなる。その微笑み方を俺は観察していた。すみれの微笑みとは違う。すみれは口元が先に形を作って、目が遅れた。鳴海さんは、目と口がほぼ同時に動く。ほぼ同時だが、目の方がわずかに先だ。目が笑いの形を作ってから、口角が上がる。"}, {"id": "ch02-s01-p060", "type": "text", "text": "けれど——微笑みの奥に、何かがある。何があるのかは読めない。ただ、微笑みがすべてではないという印象が残った。俺の観察力がそう判断しているだけで、合っているかはわからない。"}, {"id": "ch02-s01-p061", "type": "text", "text": "「……さっき、歌声が聞こえました。この建物の外で」"}, {"id": "ch02-s01-p062", "type": "text", "text": "言うべきかどうか迷った。迷ったが、口から出ていた。歌声のことを黙っている理由もなかった。"}, {"id": "ch02-s01-p063", "type": "text", "text": "鳴海さんの表情が、ほんの一瞬だけ変わった。琥珀色の瞳が微かに見開かれて、すぐに元に戻った。"}, {"id": "ch02-s01-p064", "type": "text", "text": "「……外まで聞こえていましたか。すみません、朝の自主練習をしていたんですけど……防音のはずなんですが」"}, {"id": "ch02-s01-p065", "type": "text", "text": "「防音です。建物の仕様書にそう書いてあります」"}, {"id": "ch02-s01-p066", "type": "text", "text": "「ふふ、そうですよね。少し力が入りすぎてしまったのかもしれません。ご迷惑でしたか？」"}, {"id": "ch02-s01-p067", "type": "text", "text": "迷惑。その言葉と、さっきの鳩尾の緩みと、目の奥の熱を並べてみた。合わない。迷惑とは正反対の場所にある何かだった。"}, {"id": "ch02-s01-p068", "type": "text", "text": "「いいえ。迷惑では——」"}, {"id": "ch02-s01-p069", "type": "text", "text": "言葉を探した。「よかった」と言えばいいのだろうか。「きれいでした」と言えばいいのだろうか。どちらも合っている気がして、どちらもうまく嵌まらなかった。"}, {"id": "ch02-s01-p070", "type": "text", "text": "「……迷惑ではないです」"}, {"id": "ch02-s01-p071", "type": "text", "text": "それだけになった。不器用だと思う。たぶん、この場面ではもう少し気の利いたことを言うべきだったのだろう。燈花なら「すっごくよかったよ！」と言うし、マスターなら穏やかに「いい歌だったね」と言うのだろう。俺は、否定しか言えなかった。迷惑では、ない。"}, {"id": "ch02-s01-p072", "type": "text", "text": "鳴海さんは俺の返答を受けて、首を少し傾げた。困った時にそうする癖なのかもしれない。傾げたまま微笑んでいる。"}, {"id": "ch02-s01-p073", "type": "text", "text": "「ふふ、ありがとうございます。それなら、よかったです」"}, {"id": "ch02-s01-p074", "type": "text", "text": "声に安堵が混じっていた。安堵の形がわかったのは、声の張りがわずかに緩んだからだ。さっきまでの「丁寧な応対」の声に比べて、一段だけ力が抜けた。"}, {"id": "ch02-s01-p075", "type": "text", "text": "「あ、機材の搬入、お手伝いしましょうか？」"}, {"id": "ch02-s01-p076", "type": "text", "text": "「大丈夫です。台車一台分なので」"}, {"id": "ch02-s01-p077", "type": "text", "text": "「そうですか。……それでは、わたしはこれで。次の講義があるので」"}, {"id": "ch02-s01-p078", "type": "text", "text": "鳴海さんは軽く頭を下げた。カーディガンが肩からずれかけて、片手でそっと押さえた。その動作の途中で——ほんの一瞬だけ、指先に力が入ったのが見えた。カーディガンを押さえる力が、必要以上に強い。体を支えるように。"}, {"id": "ch02-s01-p079", "type": "text", "text": "見間違いかもしれない。歩き出した鳴海さんの足取りは変わらず穏やかで、歩幅も小さく、急いでいる様子はなかった。振り返って「朝霧さん、機材の設営、よろしくお願いしますね」と微笑んだ。"}, {"id": "ch02-s01-p080", "type": "text", "text": "俺は頷いた。"}, {"id": "ch02-s01-p081", "type": "text", "text": "鳴海さんの亜麻色の髪が、丘を下る小道の向こうに消えていくのを見ていた。カーディガンの白と、スカートの淡いブルーが、残響桜の薄紫の中を遠ざかっていく。日差しが髪の毛先を金色に縁取っていた。"}, {"id": "ch02-s01-p082", "type": "text", "text": "きれいだ、と思った。"}, {"id": "ch02-s01-p083", "type": "text", "text": "その思考が浮かんで、俺は台車のハンドルに手を戻した。きれいだ。誰に対しても使わなかった言葉を、今使った。天城さんは「眩しい」人で、霜月さんは「冷たい」人で、すみれは「不思議」な人だった。それぞれに違う名前をつけた。鳴海千歳は——きれいだ、と思った。"}, {"id": "ch02-s01-p084", "type": "text", "text": "でも、それが本当に俺の感想なのかは、わからない。"}, {"id": "ch02-s01-p085", "type": "text", "text": "歌声を聴いた時の鳩尾の緩み。目の奥の熱。あの身体反応が先にあって、その反応に引っ張られて「きれい」という言葉が出てきたのだとしたら。体が先に動いて、思考が後から名前をつけただけなのだとしたら。「きれいだ」は俺の感想ではなく、体の反応に貼った事後的なラベルということになる。"}, {"id": "ch02-s01-p086", "type": "text", "text": "合っているかは、わからない。"}, {"id": "ch02-s01-p087", "type": "text", "text": "台車を押して、訓練棟の入口に向かった。扉を開けて、一階の講義室に機材を運び入れる。測定器を所定の位置に設置する。ケーブルを這わせる。固定する。手が動く。機材の設営には迷いがない。"}, {"id": "ch02-s01-p088", "type": "text", "text": "作業をしながら、鳴海さんの声を思い出していた。歌声ではなく、「おはようございます」と言った時の声。「ふふ、ありがとうございます」と言った時の声。歌っていない声の方が、記憶に残っていた。歌声は体に届いたが、話し声は耳に残った。"}, {"id": "ch02-s01-p089", "type": "text", "text": "違いがある。歌声と話し声の違い。鐘の音と鳴海さんの歌声の違い。天城さんの「眩しい」と鳴海さんの「きれい」の違い。すみれの微笑みと鳴海さんの微笑みの違い。違いがわかる。わかることが増えている。着任初日から六日しか経っていないのに、俺の中の分類表は項目が増え続けている。"}, {"id": "ch02-s01-p090", "type": "text", "text": "それが何を意味するのかは、まだわからない。"}, {"id": "ch02-s01-p091", "type": "text", "text": "測定器の電源を入れた。画面に数字が並ぶ。正常値。機材は問題なく動いている。"}, {"id": "ch02-s01-p092", "type": "text", "text": "歌声はもう聞こえない。鳴海さんはもうここにいない。講義室には俺と機材だけがある。"}, {"id": "ch02-s01-p093", "type": "text", "text": "鳩尾の緩みだけが、まだ少し残っていた。"}]}, {"chapter": 2, "chapterTitle": "灯籠通りの声", "scene": 2, "sceneTitle": "親友の影", "wordCount": "約4,000字", "paragraphs": [{"id": "ch02-s02-p001", "type": "text", "text": "機材の設営が終わった。"}, {"id": "ch02-s02-p002", "type": "text", "text": "測定器二台、記録装置一台、ケーブル類。所定の位置に配置し、電源を入れ、正常値を確認した。やるべきことはやった。あとは試験の担当者が来るまで、この講義室に用はない。"}, {"id": "ch02-s02-p003", "type": "text", "text": "台車を押して講義室を出た。"}, {"id": "ch02-s02-p004", "type": "text", "text": "廊下を戻り、入口ロビーに出る。ロビーは訓練棟の正面扉を入ってすぐの、小さな空間だった。石の床。石の壁。天井が高く、壁面の上方に細い窓が一つだけある。朝の光がそこから斜めに差し込んで、石の床の一部を白く照らしていた。"}, {"id": "ch02-s02-p005", "type": "text", "text": "人がいた。"}, {"id": "ch02-s02-p006", "type": "text", "text": "光の当たらない壁際に、一人。立っている。壁に背中を預けて、片足を少し引いた姿勢。腕を組んでいる。顔がこちらを向いた。"}, {"id": "ch02-s02-p007", "type": "text", "text": "髪は短かった。明るい栗色。後ろが首の線で短く刈り上がっていて、前髪とサイドが軽くはねている。動きのある髪型。鳴海さんの亜麻色のウェーブとは、ほとんど対極にある。"}, {"id": "ch02-s02-p008", "type": "text", "text": "瞳の色が見えた。緑。鮮やかな緑。光の加減か、翡翠を磨いたような澄み方をしている。その緑色の目が俺を捉えた瞬間、目の形が変わった。細くなった。"}, {"id": "ch02-s02-p009", "type": "text", "text": "警戒。"}, {"id": "ch02-s02-p010", "type": "text", "text": "そう判断するまでに時間はかからなかった。監視哨で人の表情を見てきた。怒りとは違う。好奇心とも違う。相手を「測っている」時の目だ。自分にとっての危険度を査定している。"}, {"id": "ch02-s02-p011", "type": "text", "text": "制服を着ている。学院の生徒だ。白いブラウスに淡いブルーのスカート。ただし、リボンが少し緩い。足元はスニーカー。右手首に、編み込みのミサンガが巻かれている。色は――複数の色が交差した、手作りのもの。"}, {"id": "ch02-s02-p012", "type": "text", "text": "身長は低い。俺より頭一つ分は低い。小柄だが、腕を組んでいる姿勢に緩みがない。体幹が据わっている。運動をしている人間の立ち方だ。"}, {"id": "ch02-s02-p013", "type": "text", "text": "「……あんた、誰？」"}, {"id": "ch02-s02-p014", "type": "text", "text": "声が飛んできた。高めの声。はっきりした輪郭がある。語尾が上がらない。問いかけだが、質問というよりは、確認。この場所にいる理由を出せ、という要求。"}, {"id": "ch02-s02-p015", "type": "text", "text": "「ちーちゃんに何か用？」"}, {"id": "ch02-s02-p016", "type": "text", "text": "ちーちゃん。"}, {"id": "ch02-s02-p017", "type": "text", "text": "その呼び方で、この人が誰を待っていたのかがわかった。鳴海さんだ。鳴海千歳を「ちーちゃん」と呼ぶ人物。俺に用があるのではなく、鳴海さんの練習が終わるのを待っていた。そこに知らない人間が訓練棟の中から台車を押して出てきたから、声をかけた。"}, {"id": "ch02-s02-p018", "type": "text", "text": "「鐘守補佐です。機材の搬入に来ました」"}, {"id": "ch02-s02-p019", "type": "text", "text": "左腕のバッジを見せた。彼女の緑色の目がバッジに移り、文字を読み、俺の顔に戻った。"}, {"id": "ch02-s02-p020", "type": "text", "text": "「……鐘守補佐」"}, {"id": "ch02-s02-p021", "type": "text", "text": "繰り返した。声のトーンが一段だけ落ちた。攻撃性が引いている。ただし、完全にではない。目はまだ俺を見ている。視線の質が「何者だ」から「どういう人間だ」に変わっただけだ。"}, {"id": "ch02-s02-p022", "type": "text", "text": "「朝霧蓮です」"}, {"id": "ch02-s02-p023", "type": "text", "text": "名乗った。鳴海さんに名乗った時と同じ名前、同じ言い方。"}, {"id": "ch02-s02-p024", "type": "text", "text": "「ふうん」"}, {"id": "ch02-s02-p025", "type": "text", "text": "彼女は壁から背中を離した。腕組みを解いた。一歩、こちらに近づいた。近づいたが、距離はまだある。二歩分ほどの間隔を保っている。"}, {"id": "ch02-s02-p026", "type": "text", "text": "「朝霧さん、ね」"}, {"id": "ch02-s02-p027", "type": "text", "text": "さん付け。「あんた」から「朝霧さん」に切り替わった。切り替わったが、声の温度は変わらない。丁寧さは距離の表明だ。近づけるつもりがない、という意思表示。"}, {"id": "ch02-s02-p028", "type": "text", "text": "「ちーちゃんの練習見に来たわけじゃないなら、いいけど」"}, {"id": "ch02-s02-p029", "type": "text", "text": "「機材の搬入だけです」"}, {"id": "ch02-s02-p030", "type": "text", "text": "「そ」"}, {"id": "ch02-s02-p031", "type": "text", "text": "短い返事。それ以上は聞かなかった。俺にそれ以上の興味がないのか、あるいは十分な情報を得たのか。判別がつかない。"}, {"id": "ch02-s02-p032", "type": "text", "text": "彼女は壁際に戻らず、入口の扉の方を向いた。外を見ている。扉は閉まっているが、扉の上にある細い窓から外の光が入っている。その光の方を見ながら、待っている。鳴海さんを。"}, {"id": "ch02-s02-p033", "type": "text", "text": "俺は台車のハンドルを握ったまま、ロビーに立っていた。台車を外に出すには、彼女の横を通って正面扉に向かう必要がある。動けない理由はないのに、動かなかった。この人の態度の奥にあるものが、引っかかっていた。"}, {"id": "ch02-s02-p034", "type": "text", "text": "鳴海さんに対する「ちーちゃん」という呼び方。俺に対する「あんた、誰？」の鋭さ。その落差。"}, {"id": "ch02-s02-p035", "type": "text", "text": "正面扉が開いた。"}, {"id": "ch02-s02-p036", "type": "text", "text": "光が入ってきた。朝の光。石のロビーが一瞬だけ明るくなった。扉の向こうに人の輪郭が見えて、それが中に入ってくる。"}, {"id": "ch02-s02-p037", "type": "text", "text": "亜麻色の髪。薄桃色のリボン。カーディガンを肩にかけた、さっき別れたばかりの人。"}, {"id": "ch02-s02-p038", "type": "text", "text": "鳴海さんだった。"}, {"id": "ch02-s02-p039", "type": "text", "text": "「あ、いろは。待っててくれたの？」"}, {"id": "ch02-s02-p040", "type": "text", "text": "鳴海さんの声が聞こえた。その声に、さっきまでの丁寧さとは微かに違う色が混じっていた。ほんの少しだけ砕けている。「いろは」と呼ぶ時の声。「朝霧さん」と呼ぶ時よりも、一段分、壁が低い。"}, {"id": "ch02-s02-p041", "type": "text", "text": "「当たり前じゃん。ちーちゃんの練習終わるの待ってたんだよ」"}, {"id": "ch02-s02-p042", "type": "text", "text": "彼女の声が変わった。"}, {"id": "ch02-s02-p043", "type": "text", "text": "変わった、という認識が先に来て、何がどう変わったのかを後から確認した。声の高さは同じだ。輪郭のはっきりした声質も同じ。けれど、角が取れている。俺に向けた時の「あんた、誰？」の声は刃物だった。今の声は刃を収めている。同じ金属だが、鞘に入っている。"}, {"id": "ch02-s02-p044", "type": "text", "text": "「朝の自主練、声出しすぎてない？ 外まで聞こえてたら恥ずかしいよ」"}, {"id": "ch02-s02-p045", "type": "text", "text": "「ふふ、大丈夫だよ。防音だから」"}, {"id": "ch02-s02-p046", "type": "text", "text": "鳴海さんが笑った。さっき俺の前で見せた微笑みよりも、もう一段階、自然な笑みだった。目と口が同時に動くのは同じだが、口の開き方が少しだけ大きい。歯が見える。"}, {"id": "ch02-s02-p047", "type": "text", "text": "「あ、朝霧さん」"}, {"id": "ch02-s02-p048", "type": "text", "text": "鳴海さんが俺に気づいた。ロビーに俺がまだいたことに少し驚いた顔をして、すぐにいつもの微笑みに戻った。いつもの微笑み――と呼ぶには、まだ二度目だが。"}, {"id": "ch02-s02-p049", "type": "text", "text": "「いろは、この人は朝霧さんって言って、新しい鐘守補佐の方だよ」"}, {"id": "ch02-s02-p050", "type": "text", "text": "「知ってる。さっき聞いた」"}, {"id": "ch02-s02-p051", "type": "text", "text": "彼女――いろはが答えた。腕を組み直さなかった。鳴海さんのそばにいる時は、腕を組まない。体の力の入れ方が違う。"}, {"id": "ch02-s02-p052", "type": "text", "text": "「あたし、風祭いろは。ちーちゃんの幼馴染」"}, {"id": "ch02-s02-p053", "type": "text", "text": "風祭いろは。幼馴染。"}, {"id": "ch02-s02-p054", "type": "text", "text": "名乗る時に俺を見たが、その目は最初の鋭さから少し丸くなっていた。鳴海さんの隣に立っているからだろうか。鳴海さんの存在が、風祭さんの表情を柔らかくしている。"}, {"id": "ch02-s02-p055", "type": "text", "text": "「朝霧蓮です。よろしくお願いします」"}, {"id": "ch02-s02-p056", "type": "text", "text": "「うん」"}, {"id": "ch02-s02-p057", "type": "text", "text": "返事はそれだけだった。「よろしく」とは言わなかった。"}, {"id": "ch02-s02-p058", "type": "text", "text": "風祭さんの立ち位置を見た。鳴海さんの左側。半歩後ろ。正面に並ぶのではなく、わずかに後ろに下がった位置に立っている。その立ち方には意図があるように見えた。あるいは意図がないのかもしれない。体が勝手にそこに収まるのかもしれない。"}, {"id": "ch02-s02-p059", "type": "text", "text": "「ちーちゃん、次の練習の時間でしょ。行こ」"}, {"id": "ch02-s02-p060", "type": "text", "text": "風祭さんが鳴海さんの肩を軽く叩いた。叩く、というより、触れた。指先が肩の布地に当たって、すぐに離れた。その一瞬の接触に、慣れがあった。何百回、何千回と繰り返した動作の手つき。"}, {"id": "ch02-s02-p061", "type": "text", "text": "「うん。朝霧さん、機材の設営ありがとうございました」"}, {"id": "ch02-s02-p062", "type": "text", "text": "鳴海さんが俺に向かって軽く頭を下げた。カーディガンがまた少しずれて、片手で押さえた。さっきと同じ動作。今度は指先に余分な力は見えなかった。休憩を挟んで、回復したのかもしれない。"}, {"id": "ch02-s02-p063", "type": "text", "text": "「……はい」"}, {"id": "ch02-s02-p064", "type": "text", "text": "二人が正面扉から出ていった。"}, {"id": "ch02-s02-p065", "type": "text", "text": "風祭さんが先に扉を開け、鳴海さんを通し、自分は後から出た。扉を押さえる手の動き。鳴海さんが通り抜けるのを確認してから、自分が続く。その手順が淀みない。"}, {"id": "ch02-s02-p066", "type": "text", "text": "扉が閉まった。"}, {"id": "ch02-s02-p067", "type": "text", "text": "ロビーに俺だけが残った。石の床。石の壁。細い窓からの光。さっきまで二人がいた場所の空気が、二人がいなくなった後も、わずかに違う密度を保っている気がした。"}, {"id": "ch02-s02-p068", "type": "text", "text": "台車を押して、正面扉に向かった。扉を開けて外に出ると、朝の光と空気が戻ってくる。"}, {"id": "ch02-s02-p069", "type": "text", "text": "丘を下る小道の先に、二人の後ろ姿が見えた。"}, {"id": "ch02-s02-p070", "type": "text", "text": "鳴海さんの亜麻色の長い髪と、風祭さんの栗色の短い髪。カーディガンの白と、スニーカーの動き。並んで歩いている。並んでいるが、風祭さんの方が半歩後ろだ。ロビーで見た立ち位置と同じ。歩いている時もその距離を保っている。"}, {"id": "ch02-s02-p071", "type": "text", "text": "風祭さんが何か言った。遠くて聞き取れない。鳴海さんが顔を横に向けて笑った。風祭さんも笑った。風祭さんの笑い方は、口を大きく開けて、声を出して笑うもので、俺の前で見せた表情とは全く違った。"}, {"id": "ch02-s02-p072", "type": "text", "text": "二人の後ろ姿を見ていた。"}, {"id": "ch02-s02-p073", "type": "text", "text": "二人の間にあるものの名前がわからなかった。友情。幼馴染。言葉としてはそうだろう。鳴海さんが「幼馴染」と紹介し、風祭さん自身もそう名乗った。けれど言葉の輪郭の内側に、言葉には収まらない何かがあった。風祭さんが鳴海さんの肩に触れた時の手つき。鳴海さんの前で変わる声。半歩後ろの立ち位置。"}, {"id": "ch02-s02-p074", "type": "text", "text": "俺には、それが何なのかを正確に読む力がない。"}, {"id": "ch02-s02-p075", "type": "text", "text": "わかるのは、風祭さんにとって鳴海さんが大切な人であるということだけだ。大切さの形は、燈花が俺に見せる距離の詰め方とも、霜月さんが業務に徹する冷たさとも、すみれが天蓋の間にいる静けさとも違う。風祭さんの大切さには、守る、という輪郭がある。"}, {"id": "ch02-s02-p076", "type": "text", "text": "そして俺は、その守りの外側にいる。"}, {"id": "ch02-s02-p077", "type": "text", "text": "外側にいることが不快なのかどうか、自分でもわからなかった。不快とは違う。不満でもない。ただ、二人の間にある距離と、俺とその距離との間にある距離を、測っていた。測ることしかできなかった。"}, {"id": "ch02-s02-p078", "type": "text", "text": "丘を下る二人の姿が、残響桜の薄紫の中に小さくなっていく。"}, {"id": "ch02-s02-p079", "type": "text", "text": "俺は台車のハンドルを握ったまま、しばらくそこに立っていた。"}, {"id": "ch02-s02-p080", "type": "text", "text": "風祭さんの緑色の目を思い出した。俺を見た時の鋭さ。鳴海さんを見た時の柔らかさ。同じ目で、あれほど違う光を出せることに、名前をつけられなかった。天城さんは「眩しい」。霜月さんは「冷たい」。すみれは「不思議」。鳴海さんは「きれい」。"}, {"id": "ch02-s02-p081", "type": "text", "text": "風祭さんは――何だろう。"}, {"id": "ch02-s02-p082", "type": "text", "text": "答えが出ないまま、台車を押して丘を下り始めた。石畳の目地に車輪が引っかかって、荷台の空になった台車が、かたん、と軽い音を立てた。"}]}, {"chapter": 2, "chapterTitle": "灯籠通りの声", "scene": 3, "sceneTitle": "記録室の少女", "wordCount": "約6,000字", "paragraphs": [{"id": "ch02-s03-p001", "type": "text", "text": "台車を倉庫に戻し、午前の業務を片付けた。"}, {"id": "ch02-s03-p002", "type": "text", "text": "管理室に戻ってからは、第三系統の計器を二度確認し、霜月さんへの日報を書いた。共鳴管洗浄から三日が経過し、第三系統の出力は0.2%低下のまま安定している。改善はしたが、基準値には届いていない。残りの0.2%が機械的な問題なのか、別の原因なのか。霜月さんは「原因の切り分けを続けろ」としか言わなかった。"}, {"id": "ch02-s03-p003", "type": "text", "text": "切り分けるなら、過去の記録が要る。"}, {"id": "ch02-s03-p004", "type": "text", "text": "管理室にあるファイルは直近三ヶ月分だった。それより前の点検記録は、図書館に保管されていると日報の返信に書かれていた。霜月さんの筆跡。短い文。「図書館2階。棚番号は受付で訊け。」"}, {"id": "ch02-s03-p005", "type": "text", "text": "十二時の鐘が鳴った。昼休みに入る。管理室を出て鍵をかけた。"}, {"id": "ch02-s03-p006", "type": "text", "text": "図書館は教室棟の東隣にあった。"}, {"id": "ch02-s03-p007", "type": "text", "text": "教室棟の煉瓦と石の壁面とは違い、図書館の外壁には木が多く使われていた。煉瓦の基礎の上に、濃い褐色の木材が組まれている。窓枠も木製で、ガラスがはめ込まれた縦長の窓が等間隔に並んでいる。屋根は瓦ではなく板葺きで、軒先に雨樋が銅の緑青を帯びて走っていた。"}, {"id": "ch02-s03-p008", "type": "text", "text": "学院の建物は大半が石と煉瓦だった。鐘鋳塔は言うまでもなく、教室棟も訓練棟も食堂も、壁は石か煉瓦で出来ている。硬い。冷たい。どれも似た手触りの建物が並ぶ中で、図書館だけが、別の素材で出来ているように見えた。"}, {"id": "ch02-s03-p009", "type": "text", "text": "正面扉は木の両開き。真鍮の取っ手を引くと、蝶番が小さく軋んだ。"}, {"id": "ch02-s03-p010", "type": "text", "text": "中に入った。"}, {"id": "ch02-s03-p011", "type": "text", "text": "一階は閲覧室だった。天井が高い。二階分の吹き抜けになっている。壁の三方が書架で、残りの一方が窓。窓から入る光が読書机の天板を白く照らしている。木の床。石ではない。足を踏み出すと、革靴の底が木に当たる音がした。鐘鋳塔の管理室とも、訓練棟のロビーとも、食堂とも違う音だった。"}, {"id": "ch02-s03-p012", "type": "text", "text": "空気が違う。"}, {"id": "ch02-s03-p013", "type": "text", "text": "紙の匂い。古い木の匂い。それと、かすかに、何か甘いもの。蜜蝋だろうか。書架の棚板を磨く時に使うものかもしれない。暖かい匂いだった。この島に来てから嗅いだどの匂いとも重ならない。"}, {"id": "ch02-s03-p014", "type": "text", "text": "受付は入口の右手にあった。カウンターの向こうに中年の女性が座っていて、俺のバッジに目をやり、「ああ、鐘守補佐の方ですね」と言った。鐘鋳塔の過去の点検記録がどこにあるか訊くと、「二階の奥です。棚番号は——ちょっと待ってくださいね」と言いかけて、受付の後ろの棚から台帳を引き出した。指でページを辿り、「2-C-7。二階の書架の一番奥の列です」と教えてくれた。"}, {"id": "ch02-s03-p015", "type": "text", "text": "礼を言って、階段を上がった。"}, {"id": "ch02-s03-p016", "type": "text", "text": "二階は一般書籍の書架だった。一階の吹き抜けに面した手摺りの内側に、書架が整然と並んでいる。天井は一階より低い。通路は狭く、書架と書架の間を一人が通れるだけの幅しかなかった。窓からの光が書架の隙間を横切って、背表紙の金文字がところどころ光っている。"}, {"id": "ch02-s03-p017", "type": "text", "text": "棚番号を追って奥に進んだ。2-A、2-B。通路を一本越えるごとに、窓から遠ざかる。光が減る。その代わり、書架の端に取り付けられた残響灯——小さなものが、淡い青白い光を灯していた。鐘鋳塔の残響灯とは違って、ここのは光が弱い。手元が見える程度。目に優しい、と言えばそうだった。"}, {"id": "ch02-s03-p018", "type": "text", "text": "2-C列の書架に着いた。7番。棚の前に立ち、背表紙を読む。「鐘鋳塔設備点検記録」と金文字で押された冊子が、年度ごとに並んでいる。十年分以上あった。二年前、三年前、五年前——順に手に取って、必要な期間の冊子を抜き出す。"}, {"id": "ch02-s03-p019", "type": "text", "text": "三冊を抱えて、近くの閲覧机に向かおうとした。"}, {"id": "ch02-s03-p020", "type": "text", "text": "奥に、光があった。"}, {"id": "ch02-s03-p021", "type": "text", "text": "書架の列が終わる場所、二階のいちばん奥に、扉があった。木の扉。閉まっていない。十センチほど開いていて、そこから光が漏れていた。窓の光ではない。色が違う。白っぽく、やわらかい。"}, {"id": "ch02-s03-p022", "type": "text", "text": "扉の上に、小さな札がかかっている。手書きの文字。「記録室」。"}, {"id": "ch02-s03-p023", "type": "text", "text": "中から音が聞こえた。かりかりという、硬い音。ペン先が紙を引っ掻く音だった。一定の間隔で続いている。書いている。誰かが、書き続けている。"}, {"id": "ch02-s03-p024", "type": "text", "text": "棚番号の「2-C-7」は、この記録室のすぐ手前だった。通り過ぎるだけなら、扉を気にする必要はない。けれどペンの音が途切れなかった。間を置かず、ページをめくる気配もなく、ただ書いている。"}, {"id": "ch02-s03-p025", "type": "text", "text": "鐘鋳塔の点検記録について、記録室の人間なら何か知っているかもしれない。"}, {"id": "ch02-s03-p026", "type": "text", "text": "扉の前に立った。ノックするか迷って、開いている隙間からそのまま声をかけた。"}, {"id": "ch02-s03-p027", "type": "text", "text": "「すみません。ここに鐘鋳塔の点検記録は——」"}, {"id": "ch02-s03-p028", "type": "text", "text": "ペンの音が止まった。"}, {"id": "ch02-s03-p029", "type": "text", "text": "小さな部屋だった。四畳半ほどの広さ。壁の二面が棚で埋まっていて、残りの一面に小さな窓がある。窓から昼の光が差し込んでいた。さっき見えた、白っぽくやわらかい光。木の机が一つ。その前に、椅子が一脚。"}, {"id": "ch02-s03-p030", "type": "text", "text": "椅子に、人がいた。"}, {"id": "ch02-s03-p031", "type": "text", "text": "顔を上げた。"}, {"id": "ch02-s03-p032", "type": "text", "text": "黒い髪。ボブカット。顎の線で正確に切り揃えられた髪が、顔を上げる動作に合わせてわずかに揺れた。前髪は眉の上で水平に切られている。一本の乱れもない。"}, {"id": "ch02-s03-p033", "type": "text", "text": "瞳が見えた。黒に近い、深い色。墨色。光を吸い込むような色だった。燈花の赤銅色とも、霜月さんのラベンダーとも、すみれの薄紫とも、鳴海さんの琥珀とも、風祭さんの翡翠とも違う。色の名前に迷わない、はっきりとした黒。"}, {"id": "ch02-s03-p034", "type": "text", "text": "表情がなかった。"}, {"id": "ch02-s03-p035", "type": "text", "text": "怒っているのではない。驚いているのでもない。ただ、顔を上げて、俺を見ている。それだけだった。口元が動かない。眉も動かない。目の開き具合も変わらない。一枚の写真のように、表情の要素が全て静止していた。"}, {"id": "ch02-s03-p036", "type": "text", "text": "「……なにか御用ですか」"}, {"id": "ch02-s03-p037", "type": "text", "text": "声が聞こえた。静かな声。平坦。抑揚がほとんどない。音量は、この小さな部屋で聞き取れる最低限に調節されている。図書館の中で発する声として、正確だった。"}, {"id": "ch02-s03-p038", "type": "text", "text": "「鐘守補佐の朝霧です。鐘鋳塔の過去の点検記録を探しているのですが、受付で二階の奥だと聞いて」"}, {"id": "ch02-s03-p039", "type": "text", "text": "左腕のバッジを見せた。少女の視線がバッジに移った。視線の動き方が正確だった。俺の顔からバッジへ。バッジの文字を読み、バッジから俺の顔に戻る。その間、首も体も動かない。目だけが動いた。"}, {"id": "ch02-s03-p040", "type": "text", "text": "「鐘鋳塔の点検記録は、この部屋の外です。2-C列の棚の7番。年度ごとに製本されています。第一系統から第七系統まで、系統別の索引は各冊子の巻末に」"}, {"id": "ch02-s03-p041", "type": "text", "text": "迷いのない返答だった。俺が何を探しているか、どこにあるか、どう引けばいいかまでを、一度の回答で過不足なく伝えている。"}, {"id": "ch02-s03-p042", "type": "text", "text": "「ありがとうございます。棚は見つけました。三冊ほど抜き出してあります」"}, {"id": "ch02-s03-p043", "type": "text", "text": "「閲覧は自由です。貸出は受付で手続きを」"}, {"id": "ch02-s03-p044", "type": "text", "text": "それだけ言って、少女は視線を手元に戻した。ペンを持ち直し、書き始めた。かりかりという音が再開する。"}, {"id": "ch02-s03-p045", "type": "text", "text": "会話は終わった。用件は済んだ。"}, {"id": "ch02-s03-p046", "type": "text", "text": "けれど、俺はまだ扉の前にいた。"}, {"id": "ch02-s03-p047", "type": "text", "text": "手元が見えた。少女の前の机に、小さなメモ帳が開かれている。メモ帳は手のひらよりやや大きいくらいのサイズで、使い込まれて表紙の角が丸くなっていた。ペンが走っている。細いペン先。インクは黒。"}, {"id": "ch02-s03-p048", "type": "text", "text": "文字が見えた。"}, {"id": "ch02-s03-p049", "type": "text", "text": "小さな文字が、行をはみ出さずに整列している。几帳面な字だった。横書き。一行ずつ、同じ幅で並んでいる。"}, {"id": "ch02-s03-p050", "type": "text", "text": "その内容が、目に入った。"}, {"id": "ch02-s03-p051", "type": "text", "text": "名前。年齢。日付。場所。"}, {"id": "ch02-s03-p052", "type": "text", "text": "名前と年齢が一組になって一行を占め、その横に日付と場所が添えられている。何人分もの記録が、ページを埋めていた。"}, {"id": "ch02-s03-p053", "type": "text", "text": "「高瀬 三郎（67）2023.11.14 / 外円区 東ノ浜」\n「高瀬 チヨ（64）2023.11.14 / 外円区 東ノ浜」\n「片桐 真一（41）2023.11.14 / 外円区 東ノ浜」"}, {"id": "ch02-s03-p054", "type": "text", "text": "同じ日付。同じ場所。家族か、あるいは同じ地域の住人。全員が同じ日に記録されている。"}, {"id": "ch02-s03-p055", "type": "text", "text": "「最後に確認された日時」。"}, {"id": "ch02-s03-p056", "type": "text", "text": "そうだと思った。名前の横の日付は、その人が最後に誰かに見られた日だ。そしてその後、この記録に載っている人たちは、いなくなった。蝕域の浸食によって。町ごと、あるいは島ごと。"}, {"id": "ch02-s03-p057", "type": "text", "text": "消滅した人々の記録だった。"}, {"id": "ch02-s03-p058", "type": "text", "text": "少女がそれを書いている。この小さな部屋で、一人で、昼休みに。メモ帳に。"}, {"id": "ch02-s03-p059", "type": "text", "text": "ペンの動きを見ていた。几帳面な字。行間が揃っている。文字の大きさも均一。けれど、一つだけ均一でないものがあった。"}, {"id": "ch02-s03-p060", "type": "text", "text": "筆跡が震えている。"}, {"id": "ch02-s03-p061", "type": "text", "text": "文字そのものは正確だった。「高」の横線も「瀬」の点画も、崩れてはいない。ただ、線の端に微かな揺れがあった。書き始めの一画目ではなく、書き終わりの最後の画で起きている。ペンを紙から離す直前の、ほんの一瞬。力の入れ方が乱れている。"}, {"id": "ch02-s03-p062", "type": "text", "text": "指先ではなく、手の奥のほう。手首か、あるいはもっと内側。"}, {"id": "ch02-s03-p063", "type": "text", "text": "体が震えているのではなかった。文字を書く動作の、最後の最後だけが震えている。書き始めは正確で、途中も正確で、書き終わりだけが乱れる。"}, {"id": "ch02-s03-p064", "type": "text", "text": "見てはいけないものを見ている。"}, {"id": "ch02-s03-p065", "type": "text", "text": "そう思ったのに、目が離せなかった。離せない理由を探す前に、少女が顔を上げた。"}, {"id": "ch02-s03-p066", "type": "text", "text": "墨色の瞳が、俺を見ていた。"}, {"id": "ch02-s03-p067", "type": "text", "text": "「……まだ、なにか」"}, {"id": "ch02-s03-p068", "type": "text", "text": "声は平坦のままだった。怒りはない。苛立ちもない。ただ、事実の確認。俺がまだここにいるという事実の。"}, {"id": "ch02-s03-p069", "type": "text", "text": "「いえ——」"}, {"id": "ch02-s03-p070", "type": "text", "text": "言いかけて、止まった。"}, {"id": "ch02-s03-p071", "type": "text", "text": "指摘はしない。筆跡が震えていることを、口にする理由がなかった。俺はこの人が誰かを知らない。この記録が何のためかも、正確にはわからない。監視哨の二年間で覚えたことがある。見たものを全て口にすることが正しいとは限らない。黙っていたほうがいい場面は、確かにある。"}, {"id": "ch02-s03-p072", "type": "text", "text": "けれど、別のことが口から出た。"}, {"id": "ch02-s03-p073", "type": "text", "text": "「たくさん、書いているんですね」"}, {"id": "ch02-s03-p074", "type": "text", "text": "少女の瞬きが止まった。"}, {"id": "ch02-s03-p075", "type": "text", "text": "止まった、と認識できるほどの時間。一秒か、二秒か。瞬きをしないまま、俺を見ていた。それから、ゆっくりと視線をメモ帳に落とした。"}, {"id": "ch02-s03-p076", "type": "text", "text": "「……23冊目です」"}, {"id": "ch02-s03-p077", "type": "text", "text": "「23冊」"}, {"id": "ch02-s03-p078", "type": "text", "text": "「はい。1冊が約200ページです。1ページに、おおよそ8名から10名分の記録が入ります」"}, {"id": "ch02-s03-p079", "type": "text", "text": "数字がすぐに出た。暗算ではなく、すでに計算してあるのだろう。この人は自分が何冊目のメモ帳に書いているか、1ページに何人分の記録が入るか、正確に把握している。"}, {"id": "ch02-s03-p080", "type": "text", "text": "23冊。1冊200ページ。1ページ8名として——3,680人。"}, {"id": "ch02-s03-p081", "type": "text", "text": "消滅した3,680人の名前と年齢と、最後に確認された日時と場所。"}, {"id": "ch02-s03-p082", "type": "text", "text": "「……それだけの人の記録を」"}, {"id": "ch02-s03-p083", "type": "text", "text": "「全員ではありません」"}, {"id": "ch02-s03-p084", "type": "text", "text": "少女が言った。声のトーンが変わった。変わった、というほどの変化ではない。音量は同じ。速度も同じ。ただ、語尾の処理が違った。さっきまでの返答は「です」で終わっていた。この一言は、「ません」で終わっている。否定形。自分の記録が「全て」ではないことを、この人は正確に認識していた。"}, {"id": "ch02-s03-p085", "type": "text", "text": "「確認できた範囲だけです。確認できなかった人は、もっと多い」"}, {"id": "ch02-s03-p086", "type": "text", "text": "ペンを持つ手が、机の上で止まっていた。ペン先がメモ帳の上に置かれたまま、動かない。"}, {"id": "ch02-s03-p087", "type": "text", "text": "「……あの」"}, {"id": "ch02-s03-p088", "type": "text", "text": "少女が言った。間があった。「あの」の後、二秒ほどの沈黙。それから視線が俺に戻った。"}, {"id": "ch02-s03-p089", "type": "text", "text": "「篠宮雫と言います。図書館の、司書助手です」"}, {"id": "ch02-s03-p090", "type": "text", "text": "名乗った。名乗り方は丁寧だったが、声の温度は変わらなかった。事実の報告。自分が何者であるかの、正確な伝達。"}, {"id": "ch02-s03-p091", "type": "text", "text": "「朝霧蓮です」"}, {"id": "ch02-s03-p092", "type": "text", "text": "「朝霧さん」"}, {"id": "ch02-s03-p093", "type": "text", "text": "俺の名前を繰り返した。それから、ペンを手に取り、メモ帳の余白に何かを書いた。一行。短い。"}, {"id": "ch02-s03-p094", "type": "text", "text": "俺の名前を書いたのだろう。"}, {"id": "ch02-s03-p095", "type": "text", "text": "「……鐘鋳塔の点検記録をお探しということは、計器の管理を担当されているのですか」"}, {"id": "ch02-s03-p096", "type": "text", "text": "「はい。第三系統の出力低下の原因を調べています。過去の記録で、同じ傾向があったかどうか確認するために」"}, {"id": "ch02-s03-p097", "type": "text", "text": "「第三系統」"}, {"id": "ch02-s03-p098", "type": "text", "text": "篠宮さんはメモ帳から顔を上げなかった。ペンが動いている。俺の話した内容を記録しているのだろうか。"}, {"id": "ch02-s03-p099", "type": "text", "text": "「過去の異常記録でしたら、三階にもあります。蝕域活動と連動した設備異常の報告書が、三階の研究資料棚に。3-A列の2番から4番です。霜月技師が三年前に整理したものがそこにあるはずです」"}, {"id": "ch02-s03-p100", "type": "text", "text": "棚番号まで暗記している。俺が探しているものの周辺に何があるかまで、把握している。"}, {"id": "ch02-s03-p101", "type": "text", "text": "「助かります」"}, {"id": "ch02-s03-p102", "type": "text", "text": "「いいえ」"}, {"id": "ch02-s03-p103", "type": "text", "text": "短い否定。礼に対する反応としては素っ気なかった。けれど、悪意のある素っ気なさではなかった。「いいえ」が「どういたしまして」の代わりなのだと、言い方の正確さから推測できた。"}, {"id": "ch02-s03-p104", "type": "text", "text": "篠宮さんはペンを置いた。メモ帳を閉じ、表紙を手のひらで一度撫でた。手のひらの動き方が丁寧だった。物に触れる時の力加減を知っている手つき。本を扱う人間の手。"}, {"id": "ch02-s03-p105", "type": "text", "text": "「閲覧机は、この部屋の外の通路沿いにもあります。奥の方は人が少ないので、集中しやすいかと」"}, {"id": "ch02-s03-p106", "type": "text", "text": "立ち上がった。椅子を引く音がしなかった。椅子を少しだけ持ち上げて引いている。床に脚を擦らせない。図書館で働く人間の動作だった。"}, {"id": "ch02-s03-p107", "type": "text", "text": "篠宮さんの全体が見えた。"}, {"id": "ch02-s03-p108", "type": "text", "text": "小柄だった。152センチほどだろうか。俺より頭二つ分は低い。華奢な体に制服を着て、その上に薄い灰色のエプロンをつけている。エプロンの紐が背中で結ばれて、小さな蝶結びになっていた。首から銀色の鍵が一本、細い鎖で下がっている。古い鍵だった。装飾はない。実用的な形。"}, {"id": "ch02-s03-p109", "type": "text", "text": "腰に、メモ帳。今閉じたものとは別の——いや、同じものだった。机の上のメモ帳を手に取り、腰のポーチに収めた。メモ帳はポーチの幅にぴったり収まった。このサイズのメモ帳を、このポーチに、23冊分収めてきたのだろう。"}, {"id": "ch02-s03-p110", "type": "text", "text": "篠宮さんは俺の横を通って記録室を出た。"}, {"id": "ch02-s03-p111", "type": "text", "text": "足音がしなかった。"}, {"id": "ch02-s03-p112", "type": "text", "text": "風祭さんの足取りは、体幹が据わった運動部の歩き方だった。鳴海さんの歩き方は、カーディガンが揺れるくらいの自然な歩幅だった。すみれは足音がしなかったが、それは地面との接触そのものが不確かだったからだった。"}, {"id": "ch02-s03-p113", "type": "text", "text": "篠宮さんの場合は、違った。靴の底を床に下ろす動作が、意図的に制御されている。足を上げて、つま先から着地し、踵を最後に下ろす。図書館で音を立てないための歩き方を、体に染み込ませている。"}, {"id": "ch02-s03-p114", "type": "text", "text": "書架の間の通路を、篠宮さんが歩いていく。小柄な背中。灰色のエプロン。黒い髪の輪郭が書架の暗がりに溶けそうになって、残響灯の青白い光を横切るたびに、輪郭が一瞬だけ戻る。"}, {"id": "ch02-s03-p115", "type": "text", "text": "「こちらです」"}, {"id": "ch02-s03-p116", "type": "text", "text": "通路の途中で立ち止まった。書架と書架の間の壁際に、小さな閲覧机が一つあった。椅子も一脚。窓から離れているが、上の棚に取り付けられた残響灯が手元を照らしている。"}, {"id": "ch02-s03-p117", "type": "text", "text": "「ここなら、棚の記録もすぐに取りに行けます」"}, {"id": "ch02-s03-p118", "type": "text", "text": "俺が三冊の点検記録を持っていることを覚えていた。閲覧机の位置と棚の距離を計算して、この場所を選んでいる。"}, {"id": "ch02-s03-p119", "type": "text", "text": "「ありがとうございます、篠宮さん」"}, {"id": "ch02-s03-p120", "type": "text", "text": "篠宮さんは小さく頷いた。頷き方も微細だった。顎が一センチほど下がって、戻る。それだけ。"}, {"id": "ch02-s03-p121", "type": "text", "text": "「……記録のことで何かわからないことがあれば、記録室にいます。大体、いつも」"}, {"id": "ch02-s03-p122", "type": "text", "text": "「大体、いつも」を繰り返しそうになった。昼休みも。放課後も。この小さな記録室で、メモ帳を開いて、消滅した人々の名前を書き続けている。"}, {"id": "ch02-s03-p123", "type": "text", "text": "「わかりました」"}, {"id": "ch02-s03-p124", "type": "text", "text": "篠宮さんは踵を返した。来た時と同じ、音のない歩き方で書架の奥へ戻っていく。灰色のエプロンの背中が、残響灯の光を横切り、横切り、書架の影の中に消えた。"}, {"id": "ch02-s03-p125", "type": "text", "text": "記録室の扉が閉まる音はしなかった。閉めなかったのか、閉める音を立てなかったのか。"}, {"id": "ch02-s03-p126", "type": "text", "text": "閲覧机に座った。三冊の点検記録を開いた。"}, {"id": "ch02-s03-p127", "type": "text", "text": "文字を目で追いながら、手が勝手にページをめくっていく。第三系統の出力記録を年度ごとに比較する。三年前。五年前。七年前。微減の傾向は過去にもあった。ただし、いずれも原因が特定されて修繕されている。潤滑油の劣化、共鳴管接合部の経年緩み、歯車軸の偏摩耗。どれも機械的な原因だった。今回の微減が同じ種類のものかどうかは、これだけではわからない。"}, {"id": "ch02-s03-p128", "type": "text", "text": "ページをめくる。数値を記録帳に写す。"}, {"id": "ch02-s03-p129", "type": "text", "text": "手を止めた。"}, {"id": "ch02-s03-p130", "type": "text", "text": "ペンの音が聞こえていた。書架の奥、記録室の方角から。かりかり。かりかり。一定の間隔。さっきと同じ音。篠宮さんが、記録の続きを書いている。"}, {"id": "ch02-s03-p131", "type": "text", "text": "3,680人。"}, {"id": "ch02-s03-p132", "type": "text", "text": "23冊のメモ帳に書かれた、消滅した人々の名前。篠宮さんはそれを「全員ではない」と言った。確認できなかった人は、もっと多い。その言い方に含まれていたもの——後悔か、無力感か、あるいはもっと別の何か。俺には判断がつかなかった。"}, {"id": "ch02-s03-p133", "type": "text", "text": "わかったのは、あのメモ帳の記録が、篠宮さんにとって業務ではないということだった。司書助手の仕事として消滅者の名簿を作っているのではない。灰色のエプロンの下の、個人の意思で書いている。小さな窓からの光の下で、一人で、昼休みに。"}, {"id": "ch02-s03-p134", "type": "text", "text": "筆跡が震えていた。"}, {"id": "ch02-s03-p135", "type": "text", "text": "文字は正確だった。行間も均一だった。けれど、書き終わりの一画だけが、毎回、微かに乱れていた。その乱れの理由を、俺は知らない。知る必要も、今のところない。"}, {"id": "ch02-s03-p136", "type": "text", "text": "ただ、あの震えを見た。"}, {"id": "ch02-s03-p137", "type": "text", "text": "「忘れないように、です」"}, {"id": "ch02-s03-p138", "type": "text", "text": "篠宮さんはそうは言わなかった。まだ。俺は「たくさん書いている」と言っただけで、なぜ書いているのかは訊いていない。けれど、23冊のメモ帳と、几帳面な字と、ペンを離す直前の震えが、答えの輪郭をすでに描いている。"}, {"id": "ch02-s03-p139", "type": "text", "text": "忘れないために、書いている。"}, {"id": "ch02-s03-p140", "type": "text", "text": "そのことが、俺の中に落ちてきた。"}, {"id": "ch02-s03-p141", "type": "text", "text": "俺には記憶がない。二年より前のことは、何一つ覚えていない。自分の名前すら自分で選んだものだ。朝霧の中で見つかったから、朝霧。植物図鑑をめくって、蓮。それだけ。"}, {"id": "ch02-s03-p142", "type": "text", "text": "覚えていないことへの感情を、俺は持っていなかった。あるべき記憶がないことに対して、喪失感があるのかどうか、自分でもわからない。ない、と言えばないのだと思う。ないものを失ったとは感じられない。"}, {"id": "ch02-s03-p143", "type": "text", "text": "篠宮さんは、逆だ。"}, {"id": "ch02-s03-p144", "type": "text", "text": "篠宮さんは、忘れることを恐れている。だから書く。3,680人の名前と年齢と、最後に確認された日付と場所を、メモ帳に刻み続ける。忘れないために。自分が忘れないために。あるいは、世界が忘れないために。"}, {"id": "ch02-s03-p145", "type": "text", "text": "忘れることを恐れる人と、覚えていない人。"}, {"id": "ch02-s03-p146", "type": "text", "text": "その二つの間に、何か通じるものがあるのかどうかは、わからなかった。"}, {"id": "ch02-s03-p147", "type": "text", "text": "点検記録に目を戻した。数値を読む。ページをめくる。ペンの音が書架の奥から聞こえてくる。"}, {"id": "ch02-s03-p148", "type": "text", "text": "かりかり。"}, {"id": "ch02-s03-p149", "type": "text", "text": "かりかり。"}, {"id": "ch02-s03-p150", "type": "text", "text": "その音を聞きながら、点検記録の数値を写していた。篠宮さんのペンの音と、俺のペンの音が、二階の奥で重なっている。どちらも記録を書いている。篠宮さんは消滅した人の記録を。俺は計器の数値の記録を。"}, {"id": "ch02-s03-p151", "type": "text", "text": "同じ図書館の二階で、違うものを記録している。"}, {"id": "ch02-s03-p152", "type": "text", "text": "十二時四十五分。昼休みの残り時間を使って、三冊分の比較表を仕上げた。貸出手続きが必要な冊子を一冊、棚に残す二冊に分けて、一冊を持って一階の受付に降りた。"}, {"id": "ch02-s03-p153", "type": "text", "text": "受付で手続きをしている間に、ペンの音が聞こえなくなった。二階の奥は、一階の受付からは遠い。音が届くはずがない。聞こえなくなったのではなく、最初からここでは聞こえない。"}, {"id": "ch02-s03-p154", "type": "text", "text": "それなのに、耳が探していた。"}, {"id": "ch02-s03-p155", "type": "text", "text": "図書館を出た。木の扉を閉め、外の空気に触れた。四月の昼の日差し。石畳の反射。教室棟の方から生徒たちの声が聞こえてくる。昼休みの喧騒が、図書館の静けさとの境界線を引いている。"}, {"id": "ch02-s03-p156", "type": "text", "text": "点検記録の冊子を小脇に抱えて、鐘鋳塔に向かって歩き始めた。"}, {"id": "ch02-s03-p157", "type": "text", "text": "篠宮さんの墨色の瞳を思い出した。表情が動かない顔。ペンを走らせる手。首から下がった銀色の鍵。腰のポーチに収まるメモ帳。音のない足取り。"}, {"id": "ch02-s03-p158", "type": "text", "text": "燈花は「眩しい」。霜月さんは「冷たい」。すみれは「不思議」。鳴海さんは「きれい」。風祭さんには、まだ名前がつけられていない。"}, {"id": "ch02-s03-p159", "type": "text", "text": "篠宮さんは——"}, {"id": "ch02-s03-p160", "type": "text", "text": "何だろう。"}, {"id": "ch02-s03-p161", "type": "text", "text": "「静か」では足りない。「正確」でもない。どちらも事実だが、あの記録室で見たものの全体を覆う言葉にはならなかった。"}, {"id": "ch02-s03-p162", "type": "text", "text": "23冊のメモ帳。3,680人の名前。書き終わりだけが震えるペン。"}, {"id": "ch02-s03-p163", "type": "text", "text": "あの震えの中に、何かがあった。正確な文字の、正確でない部分に。几帳面な記録の、几帳面でない箇所に。それが何であるかを、まだ掴めない。"}, {"id": "ch02-s03-p164", "type": "text", "text": "名前は保留にした。保留にして、覚えておくことにした。"}, {"id": "ch02-s03-p165", "type": "text", "text": "鐘鋳塔が近づいてくる。石の外壁。残響紋の刻まれた壁面。管理室の小窓が見える。午後の業務に戻る。第三系統の比較表を霜月さんに提出し、三階の研究資料棚を明日確認する計画を立てる。やることがある。"}, {"id": "ch02-s03-p166", "type": "text", "text": "やることがあるのは、悪くない。"}, {"id": "ch02-s03-p167", "type": "text", "text": "管理室の扉を開けた。鍵を差し込み、回す。中に入り、点検記録の冊子を机に置いた。椅子に座り、比較表を広げた。"}, {"id": "ch02-s03-p168", "type": "text", "text": "ペンを手に取った瞬間、篠宮さんの声が浮かんだ。"}, {"id": "ch02-s03-p169", "type": "text", "text": "「忘れないように、です」"}, {"id": "ch02-s03-p170", "type": "text", "text": "篠宮さんがそう言ったのではなかった。あのメモ帳の全ページが、あの23冊の全てが、言っていた。"}, {"id": "ch02-s03-p171", "type": "text", "text": "覚えておく。"}, {"id": "ch02-s03-p172", "type": "text", "text": "それだけを、記録帳の余白に書かなかった。書く必要がなかった。"}, {"id": "ch02-s03-p173", "type": "text", "text": "覚えている。たぶん。"}]}, {"chapter": 2, "chapterTitle": "灯籠通りの声", "scene": 4, "sceneTitle": "残響の集い", "wordCount": "約6,000字", "paragraphs": [{"id": "ch02-s04-p001", "type": "text", "text": "十七時の鐘が鳴って、管理室の壁が震えた。"}, {"id": "ch02-s04-p002", "type": "text", "text": "計器の針が跳ねて戻る。その動きを確認してから、最終数値を記録用紙に書き込んだ。第三系統、0.2パーセント低下。変わらない。三階の研究資料棚は明日確認する。今日やれることは終わった。"}, {"id": "ch02-s04-p003", "type": "text", "text": "消灯。戸締まり。鍵をかけて、鐘鋳塔を出た。"}, {"id": "ch02-s04-p004", "type": "text", "text": "正面の石段を降りたところで、声が飛んできた。"}, {"id": "ch02-s04-p005", "type": "text", "text": "「蓮くーん！」"}, {"id": "ch02-s04-p006", "type": "text", "text": "灯籠通りに向かう石畳の道の途中に、天城さんが立っていた。ポニーテールが夕風に揺れている。もう一週間になるのに、この人の声の大きさには慣れない。鐘鋳塔の石壁に反響して、二度聞こえた。"}, {"id": "ch02-s04-p007", "type": "text", "text": "「蓮くん、今日ね、みんな集めたの！ 残響行こ！」"}, {"id": "ch02-s04-p008", "type": "text", "text": "「みんな」"}, {"id": "ch02-s04-p009", "type": "text", "text": "「うん！ ちーちゃんと、いろはちゃんと、あと雫ちゃんも！ 四人に声かけたら、三人来てくれた。蓮くん入れて五人！ ね、すごくない？」"}, {"id": "ch02-s04-p010", "type": "text", "text": "すごいかどうかの判断がつかなかった。天城さんは俺の反応を待たず、「こっちこっち」と手を振って歩き始めた。大股の速い歩調。ポニーテールが、歩くたびに左右に振れる。"}, {"id": "ch02-s04-p011", "type": "text", "text": "灯籠通りに入った。点灯係が南側から火を入れていくのが見えた。天城さんは灯籠の一つ一つに「こんにちはー」と声をかけながら歩いていた。灯籠に挨拶する人を初めて見た。"}, {"id": "ch02-s04-p012", "type": "text", "text": "「残響」の磨りガラスの向こうに、暖色の光が透けている。天城さんがドアを引いた。カウベルが鳴った。低い、丸い音。一週間前に聞いたのと同じ音だった。"}, {"id": "ch02-s04-p013", "type": "text", "text": "「到着でーす！」"}, {"id": "ch02-s04-p014", "type": "text", "text": "天城さんが声を上げて店内に入った。俺はその後ろに続いた。"}, {"id": "ch02-s04-p015", "type": "text", "text": "奥のテーブル席に、三人がいた。"}, {"id": "ch02-s04-p016", "type": "text", "text": "鳴海さんが窓際に座っていた。亜麻色のウェーブがカーディガンの肩に流れている。テーブルの油灯の火が琥珀の瞳に映って、小さな橙が二つ揺れていた。俺に気づいて、微笑んだ。"}, {"id": "ch02-s04-p017", "type": "text", "text": "その隣に、風祭さん。椅子を鳴海さんに寄せるように座っている。栗色のショートヘアが肩のあたりではねている。俺を見た。目が一瞬だけ鋭くなって、すぐに元に戻った。訓練棟の前で見た目つきと同じだったが、持続する時間が短くなっている。"}, {"id": "ch02-s04-p018", "type": "text", "text": "テーブルの端、壁際の椅子に、篠宮さんがいた。"}, {"id": "ch02-s04-p019", "type": "text", "text": "黒髪のボブカット。灰色のエプロン。腰のポーチにメモ帳。昼に記録室で見た姿と変わらない。ただ、メモ帳はポーチの中ではなく、テーブルの上に開かれていた。右手にペン。左手が軽くメモ帳の端を押さえている。"}, {"id": "ch02-s04-p020", "type": "text", "text": "四人がけのテーブルに三人。窓際の二席に鳴海さんと風祭さん、壁際に篠宮さん。残りの二席が空いている。"}, {"id": "ch02-s04-p021", "type": "text", "text": "「ほら蓮くん、座って座って！」"}, {"id": "ch02-s04-p022", "type": "text", "text": "天城さんが壁際の篠宮さんの隣を指した。俺はそこに座った。天城さんは向かいの椅子——鳴海さんの正面——に、どさっと腰を下ろした。四人がけのテーブルに五人。椅子を足した分、天城さんと風祭さんが肩が触れそうなくらい近い。"}, {"id": "ch02-s04-p023", "type": "text", "text": "テーブルの上に油灯が一つ。飴色の天板に橙色の火が映っている。"}, {"id": "ch02-s04-p024", "type": "text", "text": "「よーし、全員集合！ マスター、メニューお願いしまーす！」"}, {"id": "ch02-s04-p025", "type": "text", "text": "カウンターの向こうで、吉岡さんが顔を上げた。白髪交じりの短髪に、深い皺の頬。俺のことを覚えているのか、視線がバッジに止まって「おや」と口の端が動いた。"}, {"id": "ch02-s04-p026", "type": "text", "text": "「若い子が来てくれると、店が明るくなるねえ」"}, {"id": "ch02-s04-p027", "type": "text", "text": "穏やかな声が、狭い店内に広がった。声の芯がしっかりしている。元鐘守の声。"}, {"id": "ch02-s04-p028", "type": "text", "text": "天城さんがメニューの板を取って、テーブルの中央に置いた。木の板に手書きの品書き。コーヒー、ハーブティー、ミルクティー、ジンジャーエール。トースト、サンドイッチ、焼き菓子。値段は全部一桁のベルで収まっている。"}, {"id": "ch02-s04-p029", "type": "text", "text": "「あたしはミルクコーヒー！ ちーちゃんは？」"}, {"id": "ch02-s04-p030", "type": "text", "text": "「ミルクティーをいただきます」"}, {"id": "ch02-s04-p031", "type": "text", "text": "鳴海さんが微笑んで答えた。声が穏やかだった。歌声ではないのに、言葉の音が丁寧に並んでいる。"}, {"id": "ch02-s04-p032", "type": "text", "text": "「いろはちゃんは？」"}, {"id": "ch02-s04-p033", "type": "text", "text": "「あたしもミルクティー。ちーちゃんと同じやつで」"}, {"id": "ch02-s04-p034", "type": "text", "text": "風祭さんが鳴海さんを見て言った。声の角が、訓練棟の時とは違っていた。柔らかくはないが、刃物でもない。天城さんの前では、鞘に収まったまま普通に話している。"}, {"id": "ch02-s04-p035", "type": "text", "text": "「雫ちゃんも何か飲みなよ」"}, {"id": "ch02-s04-p036", "type": "text", "text": "天城さんが篠宮さんの方を向いた。篠宮さんはメモ帳にペンを走らせていた。顔を上げるまでに、一行書き終えるだけの間があった。"}, {"id": "ch02-s04-p037", "type": "text", "text": "「……コーヒーを」"}, {"id": "ch02-s04-p038", "type": "text", "text": "小さな声。昼に記録室で聞いたのと同じ音量。店内の会話に合わせた音量ではなく、記録室の静けさに合わせた音量のまま来ている。"}, {"id": "ch02-s04-p039", "type": "text", "text": "「蓮くんは？」"}, {"id": "ch02-s04-p040", "type": "text", "text": "「コーヒーで」"}, {"id": "ch02-s04-p041", "type": "text", "text": "天城さんが指を折りながら「ミルクコーヒー、ミルクティー二つ、コーヒー二つ」と復唱し、カウンターに向かって注文を叫んだ。吉岡さんが手を上げて応じた。"}, {"id": "ch02-s04-p042", "type": "text", "text": "五人がテーブルを囲んでいる。"}, {"id": "ch02-s04-p043", "type": "text", "text": "俺は、この状況に名前がつけられなかった。複数の人間と同じテーブルに座って、飲み物を頼んで、待つ。食堂では天城さんと二人だった。喫茶店でも天城さんと二人だった。五人で座っている、というのは——記憶上、初めてだった。"}, {"id": "ch02-s04-p044", "type": "text", "text": "何をすればいいのか、わからなかった。"}, {"id": "ch02-s04-p045", "type": "text", "text": "天城さんが話し始めた。"}, {"id": "ch02-s04-p046", "type": "text", "text": "「ねえねえ、今日の午後の授業さ、先生がチョーク折ったの見た？ 二時間目」"}, {"id": "ch02-s04-p047", "type": "text", "text": "「見た見た。折れたチョーク拾おうとしてまた折ったんだよね」"}, {"id": "ch02-s04-p048", "type": "text", "text": "風祭さんが口を開けて笑った。訓練棟の前で見た、口を閉じた鋭い顔とは全く別の表情だった。笑うと目尻が下がって、翡翠の目が丸くなる。"}, {"id": "ch02-s04-p049", "type": "text", "text": "「いろは、あの時すごい声で笑ったでしょう。先生に怒られてた」"}, {"id": "ch02-s04-p050", "type": "text", "text": "鳴海さんが風祭さんの肩に手を置いて、少し砕けた口調で言った。「いろは」。さん付けも、ちゃん付けもない。幼馴染の距離。"}, {"id": "ch02-s04-p051", "type": "text", "text": "「だって面白かったんだもん。ちーちゃんだって笑ってたじゃん」"}, {"id": "ch02-s04-p052", "type": "text", "text": "「私は、口を押さえてたから……」"}, {"id": "ch02-s04-p053", "type": "text", "text": "「押さえてても肩揺れてた。バレバレ」"}, {"id": "ch02-s04-p054", "type": "text", "text": "鳴海さんが小さく笑った。口の開き方が、訓練棟の前で俺に見せた微笑みよりも大きかった。歯が見える。風祭さんが「ほらー」と得意げに指を向けた。"}, {"id": "ch02-s04-p055", "type": "text", "text": "俺はその二人を見ていた。鳴海さんと風祭さんの間にある空気は、他のどの組み合わせとも違った。長い時間をかけて作られた近さ。"}, {"id": "ch02-s04-p056", "type": "text", "text": "「朝霧さん」"}, {"id": "ch02-s04-p057", "type": "text", "text": "鳴海さんが俺に目を向けた。琥珀の瞳。油灯の火が映っている。"}, {"id": "ch02-s04-p058", "type": "text", "text": "「この島に来てどのくらいですか？」"}, {"id": "ch02-s04-p059", "type": "text", "text": "「一週間です」"}, {"id": "ch02-s04-p060", "type": "text", "text": "「まだ一週間なんですね。島の生活には、もう慣れましたか？」"}, {"id": "ch02-s04-p061", "type": "text", "text": "「……慣れた、と思います。仕事はあるので」"}, {"id": "ch02-s04-p062", "type": "text", "text": "「鐘鋳塔のお仕事、大変ですか？」"}, {"id": "ch02-s04-p063", "type": "text", "text": "「大変かどうかは、比較する対象がないのでわかりません。やることがあるのは、悪くないです」"}, {"id": "ch02-s04-p064", "type": "text", "text": "自分でも不思議な答え方だった。鳴海さんは驚いた顔をせず、「そうですか」と穏やかに頷いた。その頷き方が自然だった。俺の不器用な返答を、そのまま受け取っている。"}, {"id": "ch02-s04-p065", "type": "text", "text": "風祭さんが鳴海さんと俺の間を見ていた。翡翠の目が、横目で俺を測っている。警戒ではなかった。もう少し低い温度の、様子見の視線。"}, {"id": "ch02-s04-p066", "type": "text", "text": "吉岡さんが盆にカップを五つ載せて持ってきた。白い陶器。取っ手の向きが全て右に揃っている。一週間前と同じ配り方。"}, {"id": "ch02-s04-p067", "type": "text", "text": "「はいどうぞ。ゆっくりしていきなさい」"}, {"id": "ch02-s04-p068", "type": "text", "text": "天城さんのミルクコーヒーが最初に置かれ、次に鳴海さんと風祭さんのミルクティー、俺と篠宮さんのコーヒー。"}, {"id": "ch02-s04-p069", "type": "text", "text": "天城さんがカップを両手で包んだ。"}, {"id": "ch02-s04-p070", "type": "text", "text": "「いただきまーす！」"}, {"id": "ch02-s04-p071", "type": "text", "text": "一人だけ、声を出して言った。その声に引っ張られるように、風祭さんが「いただきます」と小さく続け、鳴海さんが微笑んでカップを持ち上げた。篠宮さんはペンを置いて、右手でカップの取っ手に指をかけた。"}, {"id": "ch02-s04-p072", "type": "text", "text": "俺もカップを持ち上げた。コーヒーの黒い液面に、裸電球の光が二つ映っている。一口飲んだ。苦い。一週間前より、味の輪郭がわかるようになっている。苦味の奥にある、焦がした砂糖のような甘さ。"}, {"id": "ch02-s04-p073", "type": "text", "text": "「蓮くんさ、お昼はいつもどこで食べてるの？」"}, {"id": "ch02-s04-p074", "type": "text", "text": "天城さんが聞いた。"}, {"id": "ch02-s04-p075", "type": "text", "text": "「食堂か、管理室で」"}, {"id": "ch02-s04-p076", "type": "text", "text": "「管理室で一人で？ だめだよ、ちゃんと食堂来なよ。あたしだいたい十二時には行ってるから」"}, {"id": "ch02-s04-p077", "type": "text", "text": "「天城さん、朝霧さんにもお昼を用意する気でしょう」"}, {"id": "ch02-s04-p078", "type": "text", "text": "鳴海さんが柔らかい声で指摘した。天城さんが「えへへ、バレた？」と笑った。"}, {"id": "ch02-s04-p079", "type": "text", "text": "「燈花ちゃん、世話焼きすぎ。朝霧さんだって困るでしょ」"}, {"id": "ch02-s04-p080", "type": "text", "text": "風祭さんが言った。「朝霧さん」の呼び方に、訓練棟の時の刺がない。天城さんを介しているせいか、あるいは場所の空気のせいか。"}, {"id": "ch02-s04-p081", "type": "text", "text": "「困ってないよね、蓮くん？」"}, {"id": "ch02-s04-p082", "type": "text", "text": "天城さんが俺に振った。"}, {"id": "ch02-s04-p083", "type": "text", "text": "「……困ってはいない」"}, {"id": "ch02-s04-p084", "type": "text", "text": "「ほら！」"}, {"id": "ch02-s04-p085", "type": "text", "text": "天城さんが風祭さんに向かって勝ち誇った顔をした。風祭さんが「はいはい」と口の端を上げた。"}, {"id": "ch02-s04-p086", "type": "text", "text": "その会話の間、篠宮さんはコーヒーを一口飲み、カップを置き、またペンを持った。メモ帳に何かを書いている。視線はメモ帳に落ちたままだが、耳は会話を拾っているようだった。天城さんが「チョーク」と言った時に、ペンの速度が変わった。話題を記録しているのかもしれない。"}, {"id": "ch02-s04-p087", "type": "text", "text": "「篠宮さんは、いつもメモを取ってるんですか？」"}, {"id": "ch02-s04-p088", "type": "text", "text": "鳴海さんが篠宮さんに話しかけた。声が一段落とされていた。篠宮さんの音量に合わせたのだと思った。"}, {"id": "ch02-s04-p089", "type": "text", "text": "篠宮さんがペンを止めた。顔を上げるまでの間が、やはり一行分あった。"}, {"id": "ch02-s04-p090", "type": "text", "text": "「……はい。記録する癖が、あるので」"}, {"id": "ch02-s04-p091", "type": "text", "text": "「何を記録しているんですか？」"}, {"id": "ch02-s04-p092", "type": "text", "text": "「いろいろです」"}, {"id": "ch02-s04-p093", "type": "text", "text": "短い返答だった。それ以上は話さなかった。鳴海さんは深追いせず、「そうですか」と微笑んだ。さっき俺の不器用な返答を受け取った時と同じ頷き方。この人は、相手の返答の長さに合わせるのが上手い。"}, {"id": "ch02-s04-p094", "type": "text", "text": "天城さんがサンドイッチを注文した。「みんなで分けよ！」と言って、吉岡さんが切り分けたサンドイッチの皿をテーブルの真ん中に置いた。天城さんが一切れ取り、風祭さんが一切れ取り、鳴海さんが一切れ取った。"}, {"id": "ch02-s04-p095", "type": "text", "text": "「雫ちゃんも食べなよ。お腹空いてない？」"}, {"id": "ch02-s04-p096", "type": "text", "text": "天城さんが篠宮さんにサンドイッチの皿を寄せた。篠宮さんはメモ帳から目を上げ、皿を見て、小さく頷いた。指先でサンドイッチの端を摘んだ。摘み方が丁寧だった。本を扱うのと同じ力加減。"}, {"id": "ch02-s04-p097", "type": "text", "text": "俺も一切れ取った。パンと卵とレタス。噛むと、マヨネーズの酸味が広がった。"}, {"id": "ch02-s04-p098", "type": "text", "text": "五人がサンドイッチを食べている。テーブルの上に皿が一つ、カップが五つ、油灯が一つ。天城さんが「おいしー」と声を上げ、風祭さんが「口閉じて食べなよ」と突っ込み、鳴海さんが笑い、篠宮さんがサンドイッチをゆっくり咀嚼しながらメモ帳に何かを書き足した。"}, {"id": "ch02-s04-p099", "type": "text", "text": "テーブルの下で、俺の手が膝の上に置かれていた。"}, {"id": "ch02-s04-p100", "type": "text", "text": "居心地が悪いのかと自分に聞いた。悪い、とは違う。慣れていないだけだ。四人の会話が俺の周りを流れていて、俺はその流れの中にいるのか外にいるのか、まだ判断がつかない。"}, {"id": "ch02-s04-p101", "type": "text", "text": "「蓮くん」"}, {"id": "ch02-s04-p102", "type": "text", "text": "天城さんの声。"}, {"id": "ch02-s04-p103", "type": "text", "text": "「ぼーっとしてるよ。何考えてたの？」"}, {"id": "ch02-s04-p104", "type": "text", "text": "「……何も。みんなが話しているのを聞いていた」"}, {"id": "ch02-s04-p105", "type": "text", "text": "「聞いてるだけじゃつまんないでしょ。蓮くんも何か話しなよ」"}, {"id": "ch02-s04-p106", "type": "text", "text": "何を話せばいいのかわからなかった。話の在庫がない。天城さんは俺の顔を見て、「あ、無理しなくていいよ」と付け足した。声のトーンが変わった。さっきの勢いとは違う、一段落とした声。"}, {"id": "ch02-s04-p107", "type": "text", "text": "「いるだけでいいから。ね」"}, {"id": "ch02-s04-p108", "type": "text", "text": "天城さんがにっと笑った。食堂で「ありがとう」と言った時に返ってきたのと同じ顔。"}, {"id": "ch02-s04-p109", "type": "text", "text": "窓の外で、灯籠通りの灯りが全部灯っていた。磨りガラス越しに橙色の光が差し込んで、テーブルの油灯と混じっている。一週間前と同じ光景のはずだが、テーブルの上のカップが二つから五つに増えている。"}, {"id": "ch02-s04-p110", "type": "text", "text": "風祭さんが鳴海さんの肩に手を置いて、何か耳元で話した。鳴海さんが小さく頷いた。二人の間にある距離は、他の誰にも入れない場所だった。"}, {"id": "ch02-s04-p111", "type": "text", "text": "篠宮さんがメモ帳のページをめくった。新しいページの上部に日付を書いた。今日の日付。それから、何かを書き始めた。ペンの動きが昼に見たものと違っていた。記録室でのペンは、速度が一定だった。ここでは、天城さんの声が上がるとペンが止まり、会話が途切れるとまた動く。"}, {"id": "ch02-s04-p112", "type": "text", "text": "この人も、この場所にいる。"}, {"id": "ch02-s04-p113", "type": "text", "text": "鳴海さんがカップを両手で包んで、窓の外を見ていた。琥珀の瞳に灯籠の灯りが映っている。穏やかな横顔。この人の穏やかさには厚みがある。表面だけではない、もっと奥のほうまで通っている穏やかさ。"}, {"id": "ch02-s04-p114", "type": "text", "text": "天城さんが「もう一杯飲むひとー」と手を挙げた。風祭さんが「あたしもー」と手を挙げ、鳴海さんが「私も」と控えめに手を挙げた。篠宮さんはペンを止めて、二秒ほど間を置いてから、右手を少しだけ持ち上げた。手を挙げた、と呼ぶには控えめすぎる動作だったが、天城さんは見逃さなかった。"}, {"id": "ch02-s04-p115", "type": "text", "text": "「雫ちゃんも！ よし、全員おかわり！ マスター！」"}, {"id": "ch02-s04-p116", "type": "text", "text": "五人分のおかわりが来た。吉岡さんがカップを並べる手つきが、さっきよりゆっくりだった。テーブルの五人を順番に見て、「いいねえ」と呟いた。"}, {"id": "ch02-s04-p117", "type": "text", "text": "コーヒーの二杯目を飲んだ。一杯目より温度が低く感じた。味は同じはずだが、舌が覚えた分だけ、苦味の輪郭がはっきりしている。"}, {"id": "ch02-s04-p118", "type": "text", "text": "十八時過ぎ。天城さんが「そろそろ帰ろっか」と言った。"}, {"id": "ch02-s04-p119", "type": "text", "text": "会計は一人ずつ。コーヒー二杯で三十ベル。カウンターでベルを数えていると、吉岡さんが「また来なさい」と言った。"}, {"id": "ch02-s04-p120", "type": "text", "text": "磨りガラスのドアを開けてカウベルが鳴った。五人が灯籠通りに出た。煉瓦の通りが橙色の灯りで満ちている。夜風が吹いて、天城さんのポニーテールが揺れた。"}, {"id": "ch02-s04-p121", "type": "text", "text": "「また来ようね！ 毎週——ううん、週に何回でも！」"}, {"id": "ch02-s04-p122", "type": "text", "text": "天城さんが全員に向かって宣言した。鳴海さんが「そうですね」と微笑み、風祭さんが「毎日はさすがにきつい」と返し、篠宮さんはメモ帳に何かを書いた。"}, {"id": "ch02-s04-p123", "type": "text", "text": "鳴海さんと風祭さんが南の方へ歩いていった。並んで歩く二人の後ろ姿。風祭さんが鳴海さんの左側、半歩後ろ。前に見たのと同じ位置。"}, {"id": "ch02-s04-p124", "type": "text", "text": "篠宮さんは「失礼します」と小さく言って、灯籠通りを北に歩いていった。足音がしなかった。つま先から着地し、踵を最後に下ろす歩き方。灯籠の光を横切るたびに、灰色のエプロンの背中が一瞬だけ浮かび上がって、また暗がりに溶けた。"}, {"id": "ch02-s04-p125", "type": "text", "text": "天城さんと俺が残った。"}, {"id": "ch02-s04-p126", "type": "text", "text": "「蓮くん、楽しかった？」"}, {"id": "ch02-s04-p127", "type": "text", "text": "天城さんが聞いた。はしばみ色の目が、灯籠の火を受けて金色に近く見える。"}, {"id": "ch02-s04-p128", "type": "text", "text": "楽しかったか。"}, {"id": "ch02-s04-p129", "type": "text", "text": "楽しい、の判定基準が俺の中にまだない。食堂で「おいしい」と言った時と同じ種類の問題だった。味に名前がなかったように、この時間にも名前がない。"}, {"id": "ch02-s04-p130", "type": "text", "text": "ただ、悪くはなかった。"}, {"id": "ch02-s04-p131", "type": "text", "text": "五人で座って、コーヒーを飲んで、サンドイッチを食べて、天城さんが笑って、風祭さんが突っ込んで、鳴海さんが微笑んで、篠宮さんがメモ帳にペンを走らせていた。俺はその中にいた。何を話すでもなく、ただ座っていた。それだけの時間だった。"}, {"id": "ch02-s04-p132", "type": "text", "text": "「……悪くなかった」"}, {"id": "ch02-s04-p133", "type": "text", "text": "「出た、蓮くんの『悪くなかった』！ いつかちゃんと『楽しかった』って言ってもらうからね」"}, {"id": "ch02-s04-p134", "type": "text", "text": "天城さんが人差し指を立てて、俺の顔の前に突きつけた。"}, {"id": "ch02-s04-p135", "type": "text", "text": "「覚えておく」"}, {"id": "ch02-s04-p136", "type": "text", "text": "「約束ね！」"}, {"id": "ch02-s04-p137", "type": "text", "text": "天城さんが手を振って、南の方に走っていった。ポニーテールが灯籠の光の中で跳ねている。大股の速い足音が煉瓦に響いて、角を曲がって消えた。"}, {"id": "ch02-s04-p138", "type": "text", "text": "一人になった。"}, {"id": "ch02-s04-p139", "type": "text", "text": "灯籠通りに立って、磨りガラスの向こうの暖色の光を見ていた。喫茶「残響」。木の板に黒い文字の看板。コーヒー一杯十五ベル。"}, {"id": "ch02-s04-p140", "type": "text", "text": "テーブルの上に五つのカップがあった。"}, {"id": "ch02-s04-p141", "type": "text", "text": "その光景を思い出していた。飴色の天板、油灯の揺れる火、白い陶器のカップが五つ。天城さんの笑い声、風祭さんの突っ込み、鳴海さんの微笑み、篠宮さんのペンの音、吉岡さんの「いいねえ」。"}, {"id": "ch02-s04-p142", "type": "text", "text": "あの時間に、名前はまだつけられない。"}, {"id": "ch02-s04-p143", "type": "text", "text": "ただ——"}, {"id": "ch02-s04-p144", "type": "text", "text": "補佐官舎に向かって歩き始めた。煉瓦の踏み心地が靴底に伝わる。灯籠の灯りが一つずつ過ぎていく。"}, {"id": "ch02-s04-p145", "type": "text", "text": "また行ってもいい場所が、一つ増えた。"}, {"id": "ch02-s04-p146", "type": "text", "text": "覚えておく。たぶん。"}]}, {"chapter": 2, "chapterTitle": "灯籠通りの声", "scene": 5, "sceneTitle": "歌と問い", "wordCount": "約4,000字", "paragraphs": [{"id": "ch02-s05-p001", "type": "text", "text": "三日が経った。"}, {"id": "ch02-s05-p002", "type": "text", "text": "この三日間で、第五系統の予備点検と、残響桜の落花が排水溝に詰まった件の応急対応と、管理室の記録用紙の補充を行った。どれも手順通りに終わった。手順がある仕事は、迷わなくていい。"}, {"id": "ch02-s05-p003", "type": "text", "text": "十七時の鐘が鳴ってから、鐘鋳塔の夕方点検を済ませた。第三系統、0.2パーセント低下。数字は動かない。記録用紙に書き込んで、消灯。戸締まり。鍵をかけた。"}, {"id": "ch02-s05-p004", "type": "text", "text": "管理室を出て、鐘鋳塔の石段を降りた。空が赤と紫の間の色をしている。西の空に雲が細く伸びていて、その縁だけが橙色に光っていた。"}, {"id": "ch02-s05-p005", "type": "text", "text": "補佐官舎に戻るには、教室棟の北側を回って灯籠通りに出るのが近い。いつもの帰り道。渡り廊下を通り、教室棟の脇を抜けて——"}, {"id": "ch02-s05-p006", "type": "text", "text": "足が止まった。"}, {"id": "ch02-s05-p007", "type": "text", "text": "共鳴者訓練棟の横を通る小道に差しかかったところだった。"}, {"id": "ch02-s05-p008", "type": "text", "text": "聞こえた。"}, {"id": "ch02-s05-p009", "type": "text", "text": "前と同じだった。薄い石壁を透過して、空気の中に滲み出てくる声。歌声。旋律の輪郭だけが届いている。歌詞は判別できない。音量が小さい——のではない。建物の防音構造を通り抜けてなお届くほどの声が、外の空気に触れて薄まっているだけだ。"}, {"id": "ch02-s05-p010", "type": "text", "text": "鳩尾のあたりが、ほどけた。"}, {"id": "ch02-s05-p011", "type": "text", "text": "前にもこれがあった。着任六日目の朝、機材を運んでいた時。あの時と同じ場所が、同じように緩んでいる。体の芯に張っていた何かが——張っていたことにさえ気づかなかった硬さが——歌声に触れたところから融けていく。"}, {"id": "ch02-s05-p012", "type": "text", "text": "前は足が止まった理由がわからなかった。防音の建物から音が漏れている矛盾に足が止まったのだと、あの時は思った。今は違う。矛盾は知っている。鳴海さんの声がこの壁を通り抜けることは、もう知っている。"}, {"id": "ch02-s05-p013", "type": "text", "text": "知っていて、それでも止まった。"}, {"id": "ch02-s05-p014", "type": "text", "text": "歌を、最後まで聴いていたかった。理由は——理由を考える前に、足がそう決めていた。"}, {"id": "ch02-s05-p015", "type": "text", "text": "小道の脇にある石積みの低い壁に、背を預けた。訓練棟の灰色の壁面が左手に見える。小さな窓が一つ、壁の厚みの奥にある。そこから声が漏れているわけではない。声は窓を通らず、壁そのものを通っている。"}, {"id": "ch02-s05-p016", "type": "text", "text": "歌声は低い音域を巡っていた。暗い曲ではなかった。水が流れているような旋律。川底の石を滑る水の、あの丸い音に似ている。音程が上がっていく。水が高い場所から落ちて、下の水面を叩くように、声がひとつ跳ねた。"}, {"id": "ch02-s05-p017", "type": "text", "text": "目の奥に熱が来た。前と同じだった。泣くほうに引っ張られる何か。蛇口は開いているが水は出ない。あの時と同じ詰まり方。"}, {"id": "ch02-s05-p018", "type": "text", "text": "違うのは、今はそれが何なのか知らないまま受け止めていられること。前は戸惑った。今も戸惑ってはいるが、戸惑いの底に「これは嫌ではない」という判断がある。嫌ではない。だからここにいる。"}, {"id": "ch02-s05-p019", "type": "text", "text": "旋律が高い音に届いた。声の密度が変わった。空気が一段、重くなる。重いのに苦しくない。水の中にいるのに呼吸ができるような、そういう矛盾した感覚。"}, {"id": "ch02-s05-p020", "type": "text", "text": "歌が、終わった。"}, {"id": "ch02-s05-p021", "type": "text", "text": "最後の音が空気に溶けていく過程を、俺は立ったまま聴いていた。溶けきった後の沈黙が、前と同じように深かった。歌があった分だけ、消えた後の空白が広い。"}, {"id": "ch02-s05-p022", "type": "text", "text": "鳩尾の緩みが残っている。もう慣れた——いや、慣れたのではない。二回目だから知っている、というだけだ。"}, {"id": "ch02-s05-p023", "type": "text", "text": "訓練棟の正面扉が開く音がした。"}, {"id": "ch02-s05-p024", "type": "text", "text": "蝶番が軋む低い音。石段を降りる小さな足音。歩幅の狭い、急がない足取り。"}, {"id": "ch02-s05-p025", "type": "text", "text": "小道の角を曲がったところで、鳴海さんが俺を見つけた。"}, {"id": "ch02-s05-p026", "type": "text", "text": "亜麻色のウェーブが肩に流れている。カーディガンを両腕の前で押さえていた。夕焼けの光が髪の毛先を赤銅色に染めている。朝の日差しでは金色に透けた髪が、夕方の光では違う色になる。"}, {"id": "ch02-s05-p027", "type": "text", "text": "琥珀の瞳。前に見た時よりも、ほんの少し薄い。蜂蜜色の中にある琥珀の密度が、一段落ちている。前回もそうだった。歌った後は、瞳の色が薄くなる。二回目だからわかる。"}, {"id": "ch02-s05-p028", "type": "text", "text": "鳴海さんが微笑んだ。"}, {"id": "ch02-s05-p029", "type": "text", "text": "「朝霧さん、また聴いてくれていたんですか？」"}, {"id": "ch02-s05-p030", "type": "text", "text": "また。その一語に、前回のことが含まれていた。訓練棟の前で歌声が聞こえたと伝えた朝のことを、この人は覚えている。"}, {"id": "ch02-s05-p031", "type": "text", "text": "「……はい」"}, {"id": "ch02-s05-p032", "type": "text", "text": "「ふふ、ありがとうございます。防音のはずなんですけどね」"}, {"id": "ch02-s05-p033", "type": "text", "text": "前と同じ台詞だった。「防音のはず」。前回は困ったように首を傾げた。今回は傾げていない。微笑みの角度が違う。困惑ではなく、少しだけ——嬉しそうに見えた。"}, {"id": "ch02-s05-p034", "type": "text", "text": "カーディガンを押さえる指先に力が入っているのが見えた。肩に掛けたカーディガンがずれないように、ではなく、体を支えるように。前回もこの動作があった。歌った後に出る、疲労を隠す仕草。"}, {"id": "ch02-s05-p035", "type": "text", "text": "「お帰りですか？」"}, {"id": "ch02-s05-p036", "type": "text", "text": "鳴海さんが聞いた。"}, {"id": "ch02-s05-p037", "type": "text", "text": "「はい。夕方点検を終えたところです」"}, {"id": "ch02-s05-p038", "type": "text", "text": "「わたしも練習を終えたところなので……よかったら、途中までご一緒しませんか？」"}, {"id": "ch02-s05-p039", "type": "text", "text": "断る理由がなかった。頷いた。"}, {"id": "ch02-s05-p040", "type": "text", "text": "丘の小道を並んで下りた。鳴海さんは俺の左側を歩いていた。歩幅が小さい。俺が自然に歩くと先に行ってしまうので、歩幅を縮めた。鳴海さんはそれに気づいたのか気づかなかったのか、何も言わなかった。"}, {"id": "ch02-s05-p041", "type": "text", "text": "灯籠通りに出た。点灯係が北側から火を入れている途中で、南半分はまだ暗かった。灯りのない灯籠と、灯りの入った灯籠が交互に並んでいる。煉瓦の道に橙色の光が点々と続いていた。"}, {"id": "ch02-s05-p042", "type": "text", "text": "「今日は長く練習されていたんですか」"}, {"id": "ch02-s05-p043", "type": "text", "text": "俺が聞いた。何か聞くべきだと思ったのか、本当に知りたかったのか、自分でもわからなかった。口を開いたら出ていた。"}, {"id": "ch02-s05-p044", "type": "text", "text": "「はい。新しい曲をひとつ、通しで歌えるようになりたくて」"}, {"id": "ch02-s05-p045", "type": "text", "text": "「さっき聴こえた曲は、新しいものですか」"}, {"id": "ch02-s05-p046", "type": "text", "text": "「ふふ、そうです。まだ荒いんですけど……聴こえてしまいましたか」"}, {"id": "ch02-s05-p047", "type": "text", "text": "「壁の向こうからなので、細かいところはわかりません。ただ——」"}, {"id": "ch02-s05-p048", "type": "text", "text": "言葉を探した。何を言おうとしているのか、自分でも定まらなかった。"}, {"id": "ch02-s05-p049", "type": "text", "text": "「水が流れているような曲だと思いました」"}, {"id": "ch02-s05-p050", "type": "text", "text": "鳴海さんが足を止めた。俺も止まった。灯籠の灯りが一つ、鳴海さんの横にあった。琥珀の瞳に橙色の火が映っている。"}, {"id": "ch02-s05-p051", "type": "text", "text": "「水、ですか」"}, {"id": "ch02-s05-p052", "type": "text", "text": "「はい。川の音に似ていた。石の上を滑る水の、丸い音」"}, {"id": "ch02-s05-p053", "type": "text", "text": "鳴海さんは数秒、黙っていた。それから口を開いた。"}, {"id": "ch02-s05-p054", "type": "text", "text": "「……嬉しいです。あの曲は、雨の日に思いついたものなので。雨が屋根を叩く音を聴いていて、旋律が浮かんだんです」"}, {"id": "ch02-s05-p055", "type": "text", "text": "雨と水。俺が聴いた「水」は、鳴海さんの中にあった「雨」だった。聴いた側と歌った側で、水の形が違っていた。けれどどちらも水だった。"}, {"id": "ch02-s05-p056", "type": "text", "text": "「歌うことが、好きなんです」"}, {"id": "ch02-s05-p057", "type": "text", "text": "鳴海さんが言った。声が穏やかだった。穏やかだが、ただの相槌や挨拶の声とは重みが違う。自分の中の確かなものに触れて、それをそのまま口に出した声。"}, {"id": "ch02-s05-p058", "type": "text", "text": "「共鳴者としての訓練とか、そういうことではなくて。ただ、歌うこと自体が」"}, {"id": "ch02-s05-p059", "type": "text", "text": "灯籠の火が風に揺れて、鳴海さんの影が煉瓦の上で動いた。"}, {"id": "ch02-s05-p060", "type": "text", "text": "「鳴海さんの歌を聴くと、胸の奥が温かくなる気がします」"}, {"id": "ch02-s05-p061", "type": "text", "text": "言ってしまってから、自分の言葉を聞いた。"}, {"id": "ch02-s05-p062", "type": "text", "text": "胸の奥が温かくなる。そう言った。本当にそうなのかを確かめる間がなかった。鳩尾の緩みは事実だった。目の奥の熱も事実だった。それを「温かい」と呼んでいいのかは、わからない。ただ、「温かい」以外の言葉が見つからなかったから、そう言った。"}, {"id": "ch02-s05-p063", "type": "text", "text": "鳴海さんの目がわずかに見開かれた。琥珀の瞳の中で灯籠の火が揺れた。それから——口元が緩んで、目が細くなった。歯が少しだけ見えた。風祭さんの前で見せていた笑い方に近い。訓練棟の前で俺に向けた微笑みよりも、一段壁が低い。"}, {"id": "ch02-s05-p064", "type": "text", "text": "「ふふ、ありがとうございます」"}, {"id": "ch02-s05-p065", "type": "text", "text": "声が柔らかかった。前に訓練棟の前で聞いた「ありがとうございます」よりも、力が抜けている。丁寧な応対の声ではなく、喜びが先に来て言葉がその後を追いかけている声。"}, {"id": "ch02-s05-p066", "type": "text", "text": "「そう言ってもらえると……本当に嬉しいです。歌って、上手とか下手とかではなくて、聴いてくれた人がどう感じたかを教えてもらえるのが、一番……」"}, {"id": "ch02-s05-p067", "type": "text", "text": "言いかけて、鳴海さんは小さく首を振った。"}, {"id": "ch02-s05-p068", "type": "text", "text": "「すみません、変なことを」"}, {"id": "ch02-s05-p069", "type": "text", "text": "「変ではないです」"}, {"id": "ch02-s05-p070", "type": "text", "text": "反射的に出た。否定だけの返答。訓練棟の前で「迷惑ではないです」と言った時と同じ形だった。肯定を言えず、否定を返す。不器用だと思う。"}, {"id": "ch02-s05-p071", "type": "text", "text": "鳴海さんがまた微笑んだ。今度は首を傾げる微笑みではなく、まっすぐにこちらを見ている微笑みだった。"}, {"id": "ch02-s05-p072", "type": "text", "text": "灯籠通りの分岐点に着いた。南に行けば鳴海さんの寮の方角、北に折れれば補佐官舎。"}, {"id": "ch02-s05-p073", "type": "text", "text": "「朝霧さん、今日はありがとうございました。また……聴いてくれたら、嬉しいです」"}, {"id": "ch02-s05-p074", "type": "text", "text": "「はい」"}, {"id": "ch02-s05-p075", "type": "text", "text": "鳴海さんが軽く頭を下げて、南に歩いていった。カーディガンを押さえる手は、さっきよりわずかに力が弱まっているように見えた。歩く速度は変わらない。小さな歩幅。灯籠の光を一つずつ横切りながら遠ざかっていく。"}, {"id": "ch02-s05-p076", "type": "text", "text": "亜麻色の髪が夕闇に溶えて見えなくなるまで、俺はそこに立っていた。"}, {"id": "ch02-s05-p077", "type": "text", "text": "一人になった。"}, {"id": "ch02-s05-p078", "type": "text", "text": "灯籠通りの分岐点。北の方角。煉瓦を踏んで歩き始めた。"}, {"id": "ch02-s05-p079", "type": "text", "text": "さっき言ったことを反芻していた。「胸の奥が温かくなる気がします」。本心だったのか。それとも、あの場面で言うべきことを選んで口にしただけなのか。"}, {"id": "ch02-s05-p080", "type": "text", "text": "鳴海さんの歌を聴いた時の鳩尾の緩みは本当だった。目の奥の熱も本当だった。体の反応は嘘をつかない。けれど、体の反応と「温かい」という言葉が正しく対応しているかは、別の問題だ。体が先に動いて、言葉が後から貼りついた。六日目の朝に「きれいだ」と思った時と、同じ順序。"}, {"id": "ch02-s05-p081", "type": "text", "text": "ただ——"}, {"id": "ch02-s05-p082", "type": "text", "text": "鳴海さんの顔を思い出した。目が細くなって、歯が見えた、あの表情。あの微笑みは、俺の言葉を聞いてから生まれたものだった。俺が「温かくなる」と言ったことに対して、鳴海さんは嬉しそうだった。"}, {"id": "ch02-s05-p083", "type": "text", "text": "その嬉しそうな顔を見た時、俺の中に何かがあった。何と呼べばいいかわからない。悪い感じではなかった。"}, {"id": "ch02-s05-p084", "type": "text", "text": "だから——少なくとも嘘ではなかったのだと思う。本心と呼べるほど確かなものかはわからない。でも、嘘を言った時の後味ではなかった。嘘の後味がどういうものかも知らないのだが。"}, {"id": "ch02-s05-p085", "type": "text", "text": "灯籠の灯りが一つずつ過ぎていく。"}, {"id": "ch02-s05-p086", "type": "text", "text": "鳴海さんは、歌うことが好きだと言った。訓練や使命ではなく、歌うこと自体が。あの声には、確かさがあった。自分の中の動かないものに触れている人の声だった。"}, {"id": "ch02-s05-p087", "type": "text", "text": "俺の中に、あれと同じ確かさがあるのかは、わからない。"}, {"id": "ch02-s05-p088", "type": "text", "text": "わからないが、覚えておく。あの歌を聴いた時の鳩尾の緩みと、「温かい」と言った時の鳴海さんの微笑みと、それが嘘ではなかったという小さな手応え。"}, {"id": "ch02-s05-p089", "type": "text", "text": "覚えておく。"}]}, {"chapter": 3, "chapterTitle": "記録と忘却", "scene": 1, "sceneTitle": "消えた人々のリスト", "wordCount": "約6,100字", "paragraphs": [{"id": "ch03-s01-p001", "type": "text", "text": "第三系統の微減が止まらなかった。"}, {"id": "ch03-s01-p002", "type": "text", "text": "共鳴管洗浄後、0.3%から0.2%に改善した出力は、そのまま二週間動かない。霜月さんは「誤差の範囲」とも「原因不明」とも言わず、ただ「データを積め」とだけ言った。"}, {"id": "ch03-s01-p003", "type": "text", "text": "データを積む。そのためには、過去の記録が要る。"}, {"id": "ch03-s01-p004", "type": "text", "text": "管理室に保管されている直近三ヶ月の点検記録では足りなかった。三年分、五年分の蓄積がなければ、この0.2%が正常な範囲内の揺らぎなのか、何かの兆候なのか判断がつかない。図書館の二階に年度別の記録冊子があることは、前に確認した。2-C列、7番。篠宮さんに教えてもらった棚。"}, {"id": "ch03-s01-p005", "type": "text", "text": "十六時の鐘が鳴り終わってから、管理室を出た。"}, {"id": "ch03-s01-p006", "type": "text", "text": "図書館までの道は覚えている。教室棟の東隣。木の外壁。濃い褐色の木材と煉瓦の基礎。緑青を帯びた銅の雨樋。この島の建物は石と煉瓦が多いが、図書館だけが別の手触りをしている。"}, {"id": "ch03-s01-p007", "type": "text", "text": "真鍮の取っ手を引くと、蝶番が前と同じ低い音を立てた。"}, {"id": "ch03-s01-p008", "type": "text", "text": "中に入った。"}, {"id": "ch03-s01-p009", "type": "text", "text": "紙と蜜蝋の匂い。木の床。この匂いは二回目だが、前回と同じ場所が緩む。肩のあたり。管理室の石壁とは違う、空気の密度が違う場所に入った時の、体の反応。"}, {"id": "ch03-s01-p010", "type": "text", "text": "受付の前を通り、階段を上がった。二階の書架の間を奥へ進む。残響灯の淡い青白い光が棚の端に灯っている。2-A、2-B、2-C。前回と同じ順番で通路を抜けていく。"}, {"id": "ch03-s01-p011", "type": "text", "text": "2-C列の7番。棚の前に立った。前回は三冊を抜いた。今回は別の年度のものが要る。八年前と十年前。背表紙の金文字を読み、該当する冊子を二冊抜き出した。"}, {"id": "ch03-s01-p012", "type": "text", "text": "記録室の扉が見えた。"}, {"id": "ch03-s01-p013", "type": "text", "text": "前回と同じ場所。書架の列が終わる二階の奥。木の扉。「記録室」の手書きの札。扉は前回と同じく、十センチほど開いていた。"}, {"id": "ch03-s01-p014", "type": "text", "text": "かりかり。"}, {"id": "ch03-s01-p015", "type": "text", "text": "ペンの音。前回と同じ間隔。"}, {"id": "ch03-s01-p016", "type": "text", "text": "俺は二冊の冊子を抱えたまま、扉の前で立ち止まった。立ち止まったのは——前回は棚の場所を聞くために声をかけた。今回はその必要がない。棚は知っている。用件は済んでいる。"}, {"id": "ch03-s01-p017", "type": "text", "text": "それでも、足が止まっていた。"}, {"id": "ch03-s01-p018", "type": "text", "text": "ペンの音が途切れた。"}, {"id": "ch03-s01-p019", "type": "text", "text": "「……朝霧さん」"}, {"id": "ch03-s01-p020", "type": "text", "text": "扉の隙間から声が聞こえた。静かな声。前回と同じ音量。図書館の中で発する声として調節された、正確な音。"}, {"id": "ch03-s01-p021", "type": "text", "text": "扉が数センチ広がった。篠宮さんが立っていた。黒髪のボブカット。灰色のエプロン。墨色の瞳が俺を見ている。前回と同じ顔。表情の要素がどれも動いていない。"}, {"id": "ch03-s01-p022", "type": "text", "text": "「点検記録ですか」"}, {"id": "ch03-s01-p023", "type": "text", "text": "「はい。八年前と十年前のものを。前の比較表に追加するために」"}, {"id": "ch03-s01-p024", "type": "text", "text": "篠宮さんの視線が俺の手元の冊子に移った。背表紙の年度を確認している。"}, {"id": "ch03-s01-p025", "type": "text", "text": "「十年前の記録は、一部欠落があります。当時の記録係が退職した期間と重なっていて、三ヶ月分ほど空白があったはずです。補完が必要でしたら、三階の蝕域活動報告書に対応するデータがあります」"}, {"id": "ch03-s01-p026", "type": "text", "text": "暗記している。前回と同じだった。俺が何を探しているか、その記録にどんな欠陥があるか、代替手段が何か。一度の返答で全て渡してくる。"}, {"id": "ch03-s01-p027", "type": "text", "text": "「ありがとうございます」"}, {"id": "ch03-s01-p028", "type": "text", "text": "「いいえ」"}, {"id": "ch03-s01-p029", "type": "text", "text": "短い否定。前回と同じ応答。"}, {"id": "ch03-s01-p030", "type": "text", "text": "篠宮さんが椅子に戻ろうとした。その時、机の上が見えた。"}, {"id": "ch03-s01-p031", "type": "text", "text": "前回は小さなメモ帳が一冊、開かれていた。今回は違った。メモ帳の横に、別の書類が広がっていた。大判の用紙が三枚。手書きの表が引かれている。列の見出しが読めた。"}, {"id": "ch03-s01-p032", "type": "text", "text": "「地名」「最終確認日」「推定住民数」「記録の残存状況」。"}, {"id": "ch03-s01-p033", "type": "text", "text": "島のリストだった。"}, {"id": "ch03-s01-p034", "type": "text", "text": "蝕域に消えた島々のリスト。人ではなく、島。場所そのものの消滅記録。"}, {"id": "ch03-s01-p035", "type": "text", "text": "「……それは」"}, {"id": "ch03-s01-p036", "type": "text", "text": "篠宮さんが振り返った。俺の視線の先を追い、机の上の書類を見た。"}, {"id": "ch03-s01-p037", "type": "text", "text": "「消滅した島嶼の記録です。管理局の中央記録館に保管されている情報を、私が転記しています」"}, {"id": "ch03-s01-p038", "type": "text", "text": "声は平坦だった。前回の消滅者の記録について話した時と、同じ温度。"}, {"id": "ch03-s01-p039", "type": "text", "text": "「島の記録も、書いているんですか」"}, {"id": "ch03-s01-p040", "type": "text", "text": "「人だけでは足りないので。人を記録しても、その人がどこに住んでいたか、どんな場所だったかが残らなければ……記録としては不完全です」"}, {"id": "ch03-s01-p041", "type": "text", "text": "ペンが机の上に置かれた。篠宮さんの手が書類の端を押さえている。几帳面な字が並んでいる。列ごとに線が引かれ、文字の大きさが均一で、行間が揃っている。前回のメモ帳と同じ精度。"}, {"id": "ch03-s01-p042", "type": "text", "text": "リストに目が行った。島の名前が並んでいる。"}, {"id": "ch03-s01-p043", "type": "text", "text": "「瀬合島」「久遠浜」「片鐘島」「——」"}, {"id": "ch03-s01-p044", "type": "text", "text": "四行目は空欄だった。地名の列に、何も書かれていない。"}, {"id": "ch03-s01-p045", "type": "text", "text": "「——この空欄は」"}, {"id": "ch03-s01-p046", "type": "text", "text": "「名前が残っていない島です」"}, {"id": "ch03-s01-p047", "type": "text", "text": "篠宮さんが言った。"}, {"id": "ch03-s01-p048", "type": "text", "text": "「蝕域に消された島の中には、名前ごと失われたものがあります。記録が消え、住民の記憶も薄れ、やがて誰もその島の名前を思い出せなくなる。中央記録館の台帳にも、管理番号だけが残っていて、対応する地名が空白になっている島が——23あります」"}, {"id": "ch03-s01-p049", "type": "text", "text": "23。メモ帳と同じ数字。23冊のメモ帳に約3,680人。23の名前のない島。偶然の一致だろうが、数字が同じことに引っかかった。"}, {"id": "ch03-s01-p050", "type": "text", "text": "「島が消えると、島のことも忘れられるんですか」"}, {"id": "ch03-s01-p051", "type": "text", "text": "口から出ていた。"}, {"id": "ch03-s01-p052", "type": "text", "text": "篠宮さんの瞬きが止まった。"}, {"id": "ch03-s01-p053", "type": "text", "text": "前回と同じだった。一秒か、二秒か。瞬きをしないまま、俺を見ている。あの時は「たくさん書いているんですね」と言った後に起きた反応。今回も、何かに触れた。"}, {"id": "ch03-s01-p054", "type": "text", "text": "「……はい」"}, {"id": "ch03-s01-p055", "type": "text", "text": "間があった。"}, {"id": "ch03-s01-p056", "type": "text", "text": "「蝕域に消されたものは、物理的に失われるだけではなく、それに関する記憶も薄れていきます。近しい人ほど早く、遠い人はゆっくりと。最終的には、誰もその島のことを思い出さなくなる」"}, {"id": "ch03-s01-p057", "type": "text", "text": "「だから記録するのです」"}, {"id": "ch03-s01-p058", "type": "text", "text": "最後の一文だけ、語尾の処理が違った。「です」の前に、息を吸う間がなかった。普段の篠宮さんは句読点の後に正確な間を置く。この一文だけ、間がなかった。"}, {"id": "ch03-s01-p059", "type": "text", "text": "俺はリストをもう一度見た。空欄の行。名前のない島。名前があったはずの場所。誰かが暮らし、朝が来て、夜が来て、生活があった場所。それが今は、管理番号だけになっている。"}, {"id": "ch03-s01-p060", "type": "text", "text": "「手伝いましょうか」"}, {"id": "ch03-s01-p061", "type": "text", "text": "言ってしまった。"}, {"id": "ch03-s01-p062", "type": "text", "text": "言う前に考えなかった。考えたのは、口から音が出た後だった。"}, {"id": "ch03-s01-p063", "type": "text", "text": "篠宮さんの瞬きが、また止まった。"}, {"id": "ch03-s01-p064", "type": "text", "text": "今度の静止は長かった。二秒では済まない。三秒。墨色の瞳が俺を見ている。顔の筋肉はどこも動いていない。口元も眉も変わらない。けれど瞬きだけが止まっている。"}, {"id": "ch03-s01-p065", "type": "text", "text": "何に驚いたのか。手伝うと言われたこと自体に、だろうか。"}, {"id": "ch03-s01-p066", "type": "text", "text": "「……よろしいのですか」"}, {"id": "ch03-s01-p067", "type": "text", "text": "声の音量が、いつもより細かった。"}, {"id": "ch03-s01-p068", "type": "text", "text": "「何をすればいいですか」"}, {"id": "ch03-s01-p069", "type": "text", "text": "篠宮さんは数秒黙ったまま俺を見ていた。それから、視線を机の上に戻した。"}, {"id": "ch03-s01-p070", "type": "text", "text": "「……転記をお願いしてもいいですか。中央記録館の台帳から書き写した下書きを、清書用の用紙に転記する作業です。字は——読みやすければ大丈夫です」"}, {"id": "ch03-s01-p071", "type": "text", "text": "「わかりました」"}, {"id": "ch03-s01-p072", "type": "text", "text": "記録室に入った。"}, {"id": "ch03-s01-p073", "type": "text", "text": "前回は扉の前で立ち止まっただけで、中に入らなかった。四畳半ほどの小部屋。壁の二面が棚。小さな窓から夕方の光が差し込んでいる。橙色に近い白。太陽が傾き始めた時間帯の光。"}, {"id": "ch03-s01-p074", "type": "text", "text": "椅子は一脚しかなかった。篠宮さんが棚の横に積まれた本の束の上に座っている予備の木箱を引き出して、机の向かい側に置いた。木箱を床に下ろす時、音がしなかった。持ち上げて、置いた。"}, {"id": "ch03-s01-p075", "type": "text", "text": "「すみません、椅子がこれしか……」"}, {"id": "ch03-s01-p076", "type": "text", "text": "「大丈夫です」"}, {"id": "ch03-s01-p077", "type": "text", "text": "木箱に座った。高さがやや低いが、机に手が届く。篠宮さんが下書きの束と清書用の用紙とペンを俺の前に置いた。ペンはインク壺付きのつけペン。メモ帳に使っているものと同じ種類に見えた。"}, {"id": "ch03-s01-p078", "type": "text", "text": "下書きを見た。篠宮さんの字。小さくて正確。前回見た消滅者の記録と同じ筆跡。名前、年齢、最終確認日時、場所。それに加えて、職業、家族構成、備考欄。"}, {"id": "ch03-s01-p079", "type": "text", "text": "備考欄に書かれた内容を読んだ。"}, {"id": "ch03-s01-p080", "type": "text", "text": "「東ノ浜の漁師。妻と二人暮らし。最終確認日の朝、隣家の住民が物干し竿に洗濯物が干されているのを見た。それが最後の目撃情報」"}, {"id": "ch03-s01-p081", "type": "text", "text": "洗濯物。"}, {"id": "ch03-s01-p082", "type": "text", "text": "消滅した人間の最後の痕跡が、物干し竿に干された洗濯物だった。"}, {"id": "ch03-s01-p083", "type": "text", "text": "もう一行。"}, {"id": "ch03-s01-p084", "type": "text", "text": "「片桐 真一。外円区 東ノ浜。建具職人。独身。最終確認日の前日、中円市場で木材を購入した記録がある。購入伝票が残っている」"}, {"id": "ch03-s01-p085", "type": "text", "text": "購入伝票。木材を買った記録。それを買った人間はもういない。"}, {"id": "ch03-s01-p086", "type": "text", "text": "ペンを取った。インクをつけて、清書用紙に最初の一行を書き始めた。"}, {"id": "ch03-s01-p087", "type": "text", "text": "俺の字は篠宮さんの字とは違う。大きくはないが、几帳面でもない。筆圧が均一ではなく、画の太さにばらつきがある。篠宮さんの字の隣に並べると、差が目立つだろう。"}, {"id": "ch03-s01-p088", "type": "text", "text": "かりかり。"}, {"id": "ch03-s01-p089", "type": "text", "text": "二つのペンの音が記録室に落ちた。"}, {"id": "ch03-s01-p090", "type": "text", "text": "前回は書架を挟んで離れた場所で、二人の音が重なっていた。今回は同じ机の上で重なっている。距離が近い。篠宮さんのペン先が紙を引っ掻く音と、俺のペン先が紙を引っ掻く音。どちらも記録を書いている。"}, {"id": "ch03-s01-p091", "type": "text", "text": "しばらく、会話がなかった。"}, {"id": "ch03-s01-p092", "type": "text", "text": "ペンの音と、窓の外から届く遠い生徒の声と、紙のめくれる音だけが記録室を満たしていた。"}, {"id": "ch03-s01-p093", "type": "text", "text": "三人分を清書し終えたところで、下書きの次のページをめくった。"}, {"id": "ch03-s01-p094", "type": "text", "text": "島のリストだった。"}, {"id": "ch03-s01-p095", "type": "text", "text": "さっき見た大判の用紙とは別の、手のひらサイズのメモ帳のページに書かれた島の名前。字がいつもより小さい。行間も詰まっている。一ページに可能な限り多くの島を記録しようとしている。"}, {"id": "ch03-s01-p096", "type": "text", "text": "ページの中ほどに、ひとつの島の記録があった。"}, {"id": "ch03-s01-p097", "type": "text", "text": "「——島（名称不明）。推定住民数：200〜300名。消滅時期：3年前の大規模縁蝕波。備考：外円区に隣接する小島。住民の多くが外円区に親族を持っていた。縁蝕波の直前に避難勧告が出されたが、波の速度が想定を超え、避難は間に合わなかった」"}, {"id": "ch03-s01-p098", "type": "text", "text": "3年前。"}, {"id": "ch03-s01-p099", "type": "text", "text": "このページの記述が詳しかった。他の島の記録は二行、三行で終わっているのに、この島だけ半ページを使っている。住民の推定数、隣接する区域との関係、避難勧告の経緯、波の到達速度。数値と事実が、密に詰め込まれている。"}, {"id": "ch03-s01-p100", "type": "text", "text": "ページをめくった。次のページも3年前の縁蝕波に関する記録だった。消滅した集落の数、被害の範囲、中央記録館が確認した死者・行方不明者の概数。"}, {"id": "ch03-s01-p101", "type": "text", "text": "そのさらに次のページも。"}, {"id": "ch03-s01-p102", "type": "text", "text": "3年前の記録だけが、他の年代の記録と比べて、量が違う。情報の密度が違う。書いた人間の手が、このページだけ止まらなかった——止められなかったように見えた。"}, {"id": "ch03-s01-p103", "type": "text", "text": "篠宮さんのペンの音が変わったことに気づいた。"}, {"id": "ch03-s01-p104", "type": "text", "text": "いつもの均一な間隔ではなかった。ペン先が紙に触れる時の力が、わずかに増している。音が硬い。かりかり、ではなく、かり、かり。一画ごとに力が入っている。"}, {"id": "ch03-s01-p105", "type": "text", "text": "俺は目を上げなかった。"}, {"id": "ch03-s01-p106", "type": "text", "text": "3年前の記録が詳しい理由は、いくつか考えられる。大規模な縁蝕波だったから、情報量が多いのは当然だろう。中央記録館の資料も豊富だっただろう。それだけかもしれない。"}, {"id": "ch03-s01-p107", "type": "text", "text": "ただ——筆跡が、このページだけ違う。"}, {"id": "ch03-s01-p108", "type": "text", "text": "文字の形は同じだ。大きさも行間も変わらない。けれど、線の引き方が変わっている。前回見た「書き終わりの震え」とは違う種類の変化。今回は線の始まりに力が入っている。書き始めの一画が、他のページより深い。"}, {"id": "ch03-s01-p109", "type": "text", "text": "深追いはしなかった。"}, {"id": "ch03-s01-p110", "type": "text", "text": "篠宮さんが3年前の記録に何かを持っていることは、読み取れた。けれどそれが何かを問う理由が、今の俺にはなかった。篠宮さんは自分が書いているものの重みを知っている。それは前回会った時にわかった。知っている上で書いている。その事実を、横から触るべきではない。"}, {"id": "ch03-s01-p111", "type": "text", "text": "清書を続けた。"}, {"id": "ch03-s01-p112", "type": "text", "text": "島のリストを書き写しながら、考えていた。"}, {"id": "ch03-s01-p113", "type": "text", "text": "俺にも消えた記録があるのだろうか。"}, {"id": "ch03-s01-p114", "type": "text", "text": "二年前、外円区の縁際で発見された。それ以前の記録は何もない。名前も、住所も、家族も。「朝霧蓮」は俺が選んだ名前で、それ以前に俺を呼んでいた名前があったのかどうかも知らない。"}, {"id": "ch03-s01-p115", "type": "text", "text": "中央記録館の台帳のどこかに、俺に対応する空欄があるのかもしれない。名前が消えた島と同じように。管理番号だけが残っていて、対応する人間の情報が白紙になっている行。"}, {"id": "ch03-s01-p116", "type": "text", "text": "それを怖いとは思わなかった。怖さの手前で、何かが詰まっている。感情の蛇口と水の間にある、あの詰まり。鳴海さんの歌を聴いた時と同じ場所が反応しているが、鳴海さんの時とは形が違う。あの時は涙に引っ張られた。今回は涙ではなく、もっと平たい何か。底の方で動かないもの。"}, {"id": "ch03-s01-p117", "type": "text", "text": "清書を続けた。"}, {"id": "ch03-s01-p118", "type": "text", "text": "「篠宮さん」"}, {"id": "ch03-s01-p119", "type": "text", "text": "ペンの音が止まった。篠宮さんが顔を上げた。"}, {"id": "ch03-s01-p120", "type": "text", "text": "「この転記、明日も来てよいですか」"}, {"id": "ch03-s01-p121", "type": "text", "text": "また、瞬きが止まった。"}, {"id": "ch03-s01-p122", "type": "text", "text": "三度目だった。今日だけで三回、篠宮さんの瞬きを止めている。"}, {"id": "ch03-s01-p123", "type": "text", "text": "「……はい」"}, {"id": "ch03-s01-p124", "type": "text", "text": "声が小さかった。"}, {"id": "ch03-s01-p125", "type": "text", "text": "篠宮さんはそれだけ言って、視線を手元に戻した。ペンを持ち直した。かりかりという音が再開する。"}, {"id": "ch03-s01-p126", "type": "text", "text": "けれど、再開した音は、さっきまでとわずかに違っていた。"}, {"id": "ch03-s01-p127", "type": "text", "text": "力が抜けた。3年前の記録を書いていた時の硬い音ではなく、最初に俺が部屋に入った時と同じ、均一な間隔の音に戻っていた。"}, {"id": "ch03-s01-p128", "type": "text", "text": "窓の外の光が変わっていた。橙色が濃くなっている。太陽が建物の屋根の高さまで降りてきた。夕日が窓から斜めに差し込んで、机の上の紙を照らしている。篠宮さんの黒い髪の輪郭が、逆光で縁取られていた。"}, {"id": "ch03-s01-p129", "type": "text", "text": "小さな記録室に、二つのペンの音が重なっている。"}, {"id": "ch03-s01-p130", "type": "text", "text": "消滅した人々の名前と、消滅した島々の名前。どちらも、ここに書かなければ忘れられるもの。篠宮さんは23冊のメモ帳を埋めて、まだ足りないと言っていた。全員ではない、と。"}, {"id": "ch03-s01-p131", "type": "text", "text": "俺がここで清書している分は、その「足りない」の一部を埋めることになるのだろうか。わからない。一人分の手が増えたところで、消滅の速度には追いつけないのかもしれない。"}, {"id": "ch03-s01-p132", "type": "text", "text": "ただ、ペンの音が二つあることは——一つの時とは違った。"}, {"id": "ch03-s01-p133", "type": "text", "text": "何が違うのかはうまく言えない。音量は二倍にはならない。狭い部屋で、二つの音が混ざって、一つの連続した音のようになっている。篠宮さんのペンが止まった隙間に俺のペンの音が入り、俺のペンが止まった隙間に篠宮さんの音が入る。"}, {"id": "ch03-s01-p134", "type": "text", "text": "隙間がない。"}, {"id": "ch03-s01-p135", "type": "text", "text": "一人で記録帳を書いている時は、ペンを止めると沈黙が来る。ここでは沈黙が来ない。篠宮さんが書いているから。"}, {"id": "ch03-s01-p136", "type": "text", "text": "その事実を、悪くないと思った。"}, {"id": "ch03-s01-p137", "type": "text", "text": "前回、図書館を出た時、耳がペンの音を探していた。聞こえるはずのない距離で、耳が探した。あれは——この音を、もう少し聴いていたかったからかもしれない。"}, {"id": "ch03-s01-p138", "type": "text", "text": "十七時の鐘が鳴った。"}, {"id": "ch03-s01-p139", "type": "text", "text": "鐘鋳塔の方角から、低い響きが届いてくる。図書館の木の壁を通り抜けて、記録室の中まで届く。残響が長く伸びて、やがて消えた。"}, {"id": "ch03-s01-p140", "type": "text", "text": "篠宮さんがペンを置いた。"}, {"id": "ch03-s01-p141", "type": "text", "text": "「十七時です」"}, {"id": "ch03-s01-p142", "type": "text", "text": "時計を見ずに鐘の音で時刻を判断していた。鐘守補佐の俺と同じことを、篠宮さんも当然のようにしている。"}, {"id": "ch03-s01-p143", "type": "text", "text": "「今日はここまでにしましょう。閉館が十七時半ですので」"}, {"id": "ch03-s01-p144", "type": "text", "text": "「わかりました」"}, {"id": "ch03-s01-p145", "type": "text", "text": "ペンをインク壺の横に置いた。清書した用紙を揃える。十二人分と、島のリスト四行分。一時間弱で書けたのはそれだけだった。"}, {"id": "ch03-s01-p146", "type": "text", "text": "篠宮さんが用紙を受け取った。俺の字を確認している。視線が一行ずつ下に移動していく。"}, {"id": "ch03-s01-p147", "type": "text", "text": "「……丁寧に書いてくださっています」"}, {"id": "ch03-s01-p148", "type": "text", "text": "声が、いつもより半拍遅れた。言葉を選んでいた、のかもしれない。"}, {"id": "ch03-s01-p149", "type": "text", "text": "「字が上手いわけではないですが」"}, {"id": "ch03-s01-p150", "type": "text", "text": "「正確であれば、十分です」"}, {"id": "ch03-s01-p151", "type": "text", "text": "篠宮さんが用紙を棚の引き出しに収めた。メモ帳を閉じ、腰のポーチに収める。首から下がった銀色の鍵が、動作に合わせてかすかに揺れた。"}, {"id": "ch03-s01-p152", "type": "text", "text": "俺は木箱から立ち上がり、冊子を二冊抱えた。"}, {"id": "ch03-s01-p153", "type": "text", "text": "「では、また明日」"}, {"id": "ch03-s01-p154", "type": "text", "text": "篠宮さんが小さく頷いた。前回と同じ。顎が一センチほど下がって、戻る。"}, {"id": "ch03-s01-p155", "type": "text", "text": "記録室を出た。書架の間を通り、階段を降り、一階の受付で冊子の貸出手続きをした。"}, {"id": "ch03-s01-p156", "type": "text", "text": "図書館を出た。"}, {"id": "ch03-s01-p157", "type": "text", "text": "夕方の空が広がっていた。橙と紫の境目。雲の縁が光っている。前に鐘鋳塔の石段を降りた時に見た空と、同じ色の範囲にある。"}, {"id": "ch03-s01-p158", "type": "text", "text": "冊子を小脇に抱えて歩き始めた。"}, {"id": "ch03-s01-p159", "type": "text", "text": "記録室の中で清書した内容を思い返していた。名前。年齢。最終確認日時。場所。職業。家族構成。物干し竿の洗濯物。木材の購入伝票。消えた人間の、消えなかった痕跡。"}, {"id": "ch03-s01-p160", "type": "text", "text": "あの記録室で、篠宮さんは毎日あれを書いている。一人で。"}, {"id": "ch03-s01-p161", "type": "text", "text": "今日は二人だった。明日も、俺が行けば二人になる。"}, {"id": "ch03-s01-p162", "type": "text", "text": "それが篠宮さんにとってどういう意味を持つのかは、俺にはわからない。手伝いを申し出た時の、あの瞬きの静止が何を表していたのか。驚きだったのか。困惑だったのか。それとも、もっと別の何か。"}, {"id": "ch03-s01-p163", "type": "text", "text": "わからないが、あの部屋でペンの音が二つ重なっている時間は——体が楽だった。"}, {"id": "ch03-s01-p164", "type": "text", "text": "楽。正確な言葉かどうかはわからない。肩の力が抜けていた。管理室で一人で計器を読んでいる時とも、食堂で燈花と話している時とも違う。静かで、やるべきことがあって、隣に同じことをしている人がいる。その三つが揃っている状態が、体にとって負荷の低い状態だった。"}, {"id": "ch03-s01-p165", "type": "text", "text": "安堵、と呼ぶのかもしれない。たぶん。"}, {"id": "ch03-s01-p166", "type": "text", "text": "鐘鋳塔が見えてきた。石の外壁。残響紋。管理室の小窓。冊子を持って中に入り、八年前と十年前の記録を比較する。第三系統のデータを積む。やるべきことがある。"}, {"id": "ch03-s01-p167", "type": "text", "text": "それと——明日の十六時に、図書館の二階に行くこと。"}, {"id": "ch03-s01-p168", "type": "text", "text": "覚えておく。"}]}, {"chapter": 3, "chapterTitle": "記録と忘却", "scene": 2, "sceneTitle": "差し入れの味", "wordCount": "約5,200字", "paragraphs": [{"id": "ch03-s02-p001", "type": "text", "text": "補佐官舎に帰ったのは十七時半を過ぎた頃だった。"}, {"id": "ch03-s02-p002", "type": "text", "text": "鐘鋳塔の管理室で八年前と十年前の記録を照合し、第三系統の出力推移を時系列に並べた。0.2%の微減は過去十年のデータの中で前例がない——少なくとも記録が残っている範囲では。三ヶ月の欠落期間を除けば、第三系統の導通率は十年前から昨年末まで99.0%を割ったことがない。今年の一月中旬に始まった低下は、新しい事象だった。"}, {"id": "ch03-s02-p003", "type": "text", "text": "結論は出なかった。データが足りない。霜月さんは「データを積め」と言った。正しい。"}, {"id": "ch03-s02-p004", "type": "text", "text": "鐘鋳塔の正面扉を閉め、鍵をかけ、教室棟の裏手に回った。補佐官舎は教室棟の背面に張り付くように建っている。煉瓦の二階建て。外壁が教室棟と同じ色なので、遠目では一体の建物に見える。一階の端に俺の部屋がある。割り当てられた時は鍵と一枚の書類だけ渡された。間取り図はなかった。六畳ほどの四角い部屋。それだけ知っていれば足りた。"}, {"id": "ch03-s02-p005", "type": "text", "text": "鍵を開け、中に入った。"}, {"id": "ch03-s02-p006", "type": "text", "text": "寝台。小さな机。収納棚。調理台。壁面に備え付けの油灯が二つ。窓が一つ。寝台の上に毛布が折り畳んであり、机の上に記録用紙と筆記具がある。収納棚には着替えの制服と、替えのブレスレットの紐。調理台には鍋と椀が一つずつ。"}, {"id": "ch03-s02-p007", "type": "text", "text": "私物と呼べるものは、左手首のブレスレットと、今日図書館から借りてきた冊子二冊。それだけだった。"}, {"id": "ch03-s02-p008", "type": "text", "text": "窓の外が暗くなり始めていた。油灯に火を入れた。黄色い光が壁に揺れる。壁は白い漆喰で、染みも飾りもない。何もない壁を、何もない光が照らしている。"}, {"id": "ch03-s02-p009", "type": "text", "text": "手を洗い、調理台の前に立った。乾麺が棚にある。昨日も一昨日もこれを茹でた。湯を沸かそうとして、鍋を取った。"}, {"id": "ch03-s02-p010", "type": "text", "text": "その時、扉が鳴った。"}, {"id": "ch03-s02-p011", "type": "text", "text": "二回。こんこん。ノックの間隔が短い。叩いてから返事を待つ速度の人間と、叩きながら次の動作に移っている人間がいる。この叩き方は後者だった。"}, {"id": "ch03-s02-p012", "type": "text", "text": "「蓮くーん、いる？」"}, {"id": "ch03-s02-p013", "type": "text", "text": "声が先に来ていた。ノックの音より声の方が早い。"}, {"id": "ch03-s02-p014", "type": "text", "text": "扉を開けた。"}, {"id": "ch03-s02-p015", "type": "text", "text": "天城さんが立っていた。"}, {"id": "ch03-s02-p016", "type": "text", "text": "ポニーテールが夕風に揺れている。黄色のゴム。制服のブラウスの袖がまくられていて、前腕が見えている。両手で大きな布包みを抱えていた。白い布に、湯気が染みて湿った跡がある。左手の薬指に、細い布のリングが巻かれていた。布の端が少しほつれている。"}, {"id": "ch03-s02-p017", "type": "text", "text": "「蓮くん、ちゃんとご飯食べてる？」"}, {"id": "ch03-s02-p018", "type": "text", "text": "問いかけの形だが、答えを待つ間合いがない。天城さんの声には質問と断定が同居していて、今のは断定の方が強かった。食べていないだろう、という確信がある口調。"}, {"id": "ch03-s02-p019", "type": "text", "text": "「……乾麺を茹でようとしていました」"}, {"id": "ch03-s02-p020", "type": "text", "text": "「乾麺って、毎日？」"}, {"id": "ch03-s02-p021", "type": "text", "text": "「はい」"}, {"id": "ch03-s02-p022", "type": "text", "text": "天城さんの眉が寄った。目が細くなり、口がへの字になった。怒りではない。怒りの手前の、呆れと心配が混ざった形。"}, {"id": "ch03-s02-p023", "type": "text", "text": "「だめだよそれ。ほら、あたし作ってきたの」"}, {"id": "ch03-s02-p024", "type": "text", "text": "布包みを俺に向かって差し出した。差し出すというより、押しつけるに近い。受け取ると、ずしりと重い。そして温かい。布越しに、鍋の底の丸みが手のひらに伝わった。"}, {"id": "ch03-s02-p025", "type": "text", "text": "天城さんは俺が受け取るのを確認するより先に、靴を脱いで上がり框に足をかけていた。"}, {"id": "ch03-s02-p026", "type": "text", "text": "「入っていいでしょ？ ちょっとだけ」"}, {"id": "ch03-s02-p027", "type": "text", "text": "「……はい」"}, {"id": "ch03-s02-p028", "type": "text", "text": "天城さんが部屋の中に入った。"}, {"id": "ch03-s02-p029", "type": "text", "text": "一歩で止まった。"}, {"id": "ch03-s02-p030", "type": "text", "text": "部屋の中を見回している。視線が壁から机へ、机から収納棚へ、棚から寝台へ。窓の方も見た。調理台の上の鍋と椀も見た。"}, {"id": "ch03-s02-p031", "type": "text", "text": "「……蓮くん」"}, {"id": "ch03-s02-p032", "type": "text", "text": "「はい」"}, {"id": "ch03-s02-p033", "type": "text", "text": "「ここ、殺風景だね」"}, {"id": "ch03-s02-p034", "type": "text", "text": "言い方に配慮がなかった。思ったことがそのまま口から出ている。天城さんの正直さは、こういう場面で表面に出る。"}, {"id": "ch03-s02-p035", "type": "text", "text": "「何もないね。本当に何も。写真とかも飾ってないし、花もないし」"}, {"id": "ch03-s02-p036", "type": "text", "text": "写真は持っていない。花を置くという発想は、今この瞬間まで頭に浮かんだことがなかった。部屋に花を置く。花を置くためには、花を選ぶ。花を選ぶためには、どの花がいいかを考える。考えるためには、好みがいる。好みが——"}, {"id": "ch03-s02-p037", "type": "text", "text": "「花でも置いたら？ この窓のとこに。小さい鉢で全然いいからさ」"}, {"id": "ch03-s02-p038", "type": "text", "text": "天城さんは窓際を指差した。確かに窓枠の幅は、小さな鉢が一つ置ける程度にはある。"}, {"id": "ch03-s02-p039", "type": "text", "text": "「……考えたことがなかったです」"}, {"id": "ch03-s02-p040", "type": "text", "text": "「でしょ。だから言ってるの」天城さんは腕を組んで、得意そうに顎を上げた。「あたし、こういうの得意だから！ 今度持ってきてあげる」"}, {"id": "ch03-s02-p041", "type": "text", "text": "俺は返事をする前に、手の中の布包みが冷めることの方が気になった。天城さんもそれに思い当たったらしく、「あ、先にご飯だご飯」と自分で話を切り替えた。"}, {"id": "ch03-s02-p042", "type": "text", "text": "机の上の記録用紙を脇に寄せ、天城さんが布包みを開いた。"}, {"id": "ch03-s02-p043", "type": "text", "text": "鍋が一つ。蓋付きの土鍋で、持ち手が布で巻いてある。別の包みにおにぎりが三つ。三角形に握られていて、海苔が巻かれている。もう一つの小さな包みは漬物だった。茄子と大根。紫と白が交互に並んでいる。"}, {"id": "ch03-s02-p044", "type": "text", "text": "鍋の蓋を開けた。"}, {"id": "ch03-s02-p045", "type": "text", "text": "味噌汁だった。"}, {"id": "ch03-s02-p046", "type": "text", "text": "湯気が立ち上がって、狭い部屋の空気が変わった。出汁の匂いが壁に触れる。昆布と、もう一つ、甘みのある匂い。煮干しだろうか。味噌は白味噌に近い色をしている。具は豆腐と油揚げとわかめ。豆腐が大きく切られていて、崩れずに浮いている。"}, {"id": "ch03-s02-p047", "type": "text", "text": "天城さんが椀を一つ取り、お玉で味噌汁をよそった。"}, {"id": "ch03-s02-p048", "type": "text", "text": "「はい、座って座って」"}, {"id": "ch03-s02-p049", "type": "text", "text": "寝台に座るよう促された。机が小さいので二人分の食器が載らない。天城さんは調理台の端に腰をかけた。"}, {"id": "ch03-s02-p050", "type": "text", "text": "椀を受け取った。両手で包むと、熱が手のひらを通って腕まで伝わった。この熱さは乾麺を茹でた湯の熱さとは違う。温度は同じはずなのに、椀越しに伝わる熱と、鍋から立ち上る蒸気の熱は、体の受け取り方が違っていた。"}, {"id": "ch03-s02-p051", "type": "text", "text": "一口、啜った。"}, {"id": "ch03-s02-p052", "type": "text", "text": "味噌の塩気が舌に触れた。その奥に出汁の甘さ。食堂の味噌汁より塩気が抑えてあって、出汁の味が前に出ている。豆腐を舌で押すと、柔らかく崩れた。油揚げが味噌汁を吸って、噛むと汁がじわりと出てきた。"}, {"id": "ch03-s02-p053", "type": "text", "text": "二口目。"}, {"id": "ch03-s02-p054", "type": "text", "text": "味が舌に広がっている。それは事実。食堂の味噌汁を飲んだ時と同じ場所が反応している。でも同じ反応かと聞かれれば、違う。食堂では大鍋から注がれた味噌汁を一人で飲んだ。今は目の前で天城さんがおにぎりを一つ手に取って齧っている。椀の温度と、味噌汁を作った人間がこの部屋にいるという事実が、舌の上の味に何かを加えている。何を加えているのかは、わからない。"}, {"id": "ch03-s02-p055", "type": "text", "text": "天城さんが俺を見ていた。"}, {"id": "ch03-s02-p056", "type": "text", "text": "「どう？」"}, {"id": "ch03-s02-p057", "type": "text", "text": "間があった。"}, {"id": "ch03-s02-p058", "type": "text", "text": "おいしい、と言おうとした。口が開いて、言葉になる前に止まった。止まったのは、ためらいではなかった。確認していた。今自分の舌にある感覚と、「おいしい」という音が対応しているか。体の底から出てきた感覚なのか、「作ってくれた相手においしいと言うべきだ」という判断が先に来ているのか。"}, {"id": "ch03-s02-p059", "type": "text", "text": "区別がつかない。"}, {"id": "ch03-s02-p060", "type": "text", "text": "食堂の焼き魚の時と、同じ場所にいる。紙一枚ぶんの隙間。ただ、隙間の幅が前と同じかどうかもわからなくなっている。味噌汁の温度と出汁の甘さは確かにここにあるのに、それを「おいしい」という一語に束ねる瞬間に、信号が一拍遅れる。"}, {"id": "ch03-s02-p061", "type": "text", "text": "「……おいしい」"}, {"id": "ch03-s02-p062", "type": "text", "text": "言えた。間があったことは自覚していた。"}, {"id": "ch03-s02-p063", "type": "text", "text": "天城さんはその間を気にした様子がなかった。"}, {"id": "ch03-s02-p064", "type": "text", "text": "「よかった！ もっと食べて。おにぎりも、梅と鮭と昆布。どれがいい？」"}, {"id": "ch03-s02-p065", "type": "text", "text": "「……どれでも」"}, {"id": "ch03-s02-p066", "type": "text", "text": "「じゃあ鮭。あたしのお母さんが鮭のおにぎりだけは誰にも負けないって言ってたの。あたしの再現度はまだ七割くらいなんだけどね」"}, {"id": "ch03-s02-p067", "type": "text", "text": "天城さんが鮭のおにぎりを手渡してきた。海苔が少し湿っていて、指に張りつく。かじると、米の粒が立っていた。握り方が固すぎず、箸で崩せるほど柔らかくもない。鮭の塩焼きがほぐされて中心にある。米と鮭と海苔。三つの味が一度に舌に来た。"}, {"id": "ch03-s02-p068", "type": "text", "text": "天城さんは残りのおにぎり——梅の方を手に取って、半分に割って食べ始めた。"}, {"id": "ch03-s02-p069", "type": "text", "text": "「あたしの実家、外円区の灯里村ってところでね」"}, {"id": "ch03-s02-p070", "type": "text", "text": "自然に出てきた言葉だった。おにぎりを食べながら、昔話をする流れ。"}, {"id": "ch03-s02-p071", "type": "text", "text": "「お母さんが畑やってて、お父さんも畑やってて。あたしも手伝って。朝から晩まで土いじり。お米もね、自分たちで作ってたんだ。だからおにぎりは小さい頃から握ってて——」"}, {"id": "ch03-s02-p072", "type": "text", "text": "天城さんの声が途切れた。"}, {"id": "ch03-s02-p073", "type": "text", "text": "目が変わっていた。"}, {"id": "ch03-s02-p074", "type": "text", "text": "はしばみ色の瞳の奥に、影が差した。食堂で記憶喪失の話をした時の「表情の静止」とは違う。あの時は動きの勢いが途切れた。今回は目の色そのものが変わった。瞳の中の光が、一段暗くなった。窓からの夕光は変わっていない。油灯の光も変わっていない。光源は同じなのに、天城さんの目の中だけ、何かが翳った。"}, {"id": "ch03-s02-p075", "type": "text", "text": "一秒。"}, {"id": "ch03-s02-p076", "type": "text", "text": "天城さんの左手が、髪を結ぶ黄色のゴムに触れた。無意識の動作だった。指先がゴムの結び目のあたりに当たって、すぐに離れた。"}, {"id": "ch03-s02-p077", "type": "text", "text": "「まあ、いろいろあってこっちに来たんだけどね！」"}, {"id": "ch03-s02-p078", "type": "text", "text": "声が戻っていた。速度も音量も、さっきまでと同じ明るさ。顔も笑っている。頬が上がり、目が細くなっている。さっきの一秒がなかったかのように。"}, {"id": "ch03-s02-p079", "type": "text", "text": "三回目だった。"}, {"id": "ch03-s02-p080", "type": "text", "text": "食堂で記憶喪失の話をした時。喫茶「残響」で「一人だとさ、あんまり——」と言いかけた時。そして今。天城さんの表情が止まるパターンは三回目で、今回のものが最も深かった。前の二回は動きの途切れだった。今回は光の翳り。筋肉の変化ではなく、目の奥の変化。"}, {"id": "ch03-s02-p081", "type": "text", "text": "「いろいろ」の中身は聞かなかった。"}, {"id": "ch03-s02-p082", "type": "text", "text": "聞くべき場面ではないと判断したのか、聞く言葉が見つからなかったのか。記録室で篠宮さんの3年前の記録に気づいた時も、深追いしなかった。あの時と同じ判断をしている。ただ、あの時と違うのは、天城さんの翳りが消えた後の笑顔が、翳りの前と全く同じ形をしていること。篠宮さんはペンの音が硬くなった後、柔らかく戻るまでに時間がかかった。天城さんは一秒で切り替える。"}, {"id": "ch03-s02-p083", "type": "text", "text": "切り替えが速すぎることが、何かを意味しているのかもしれない。"}, {"id": "ch03-s02-p084", "type": "text", "text": "俺はおにぎりの残りを口に入れた。鮭の塩味が舌に残った。"}, {"id": "ch03-s02-p085", "type": "text", "text": "天城さんは漬物の包みを開けて、茄子の漬物を俺の前に置いた。"}, {"id": "ch03-s02-p086", "type": "text", "text": "「これもあたしが漬けたの。食べてみて」"}, {"id": "ch03-s02-p087", "type": "text", "text": "茄子を一切れ、口に運んだ。酸味と塩味。歯を入れると、皮がしゃくりと鳴った。茄子の中の水分が舌に触れる。"}, {"id": "ch03-s02-p088", "type": "text", "text": "「うまくできた方。前に作った時は塩入れすぎてしょっぱくなっちゃって、弟に『姉ちゃん、これ塩だよ』って言われたの」"}, {"id": "ch03-s02-p089", "type": "text", "text": "天城さんが笑った。弟の話をする時の笑い方は、俺に向ける笑い方と少しだけ違った。口の開き方が同じで、目の形も同じだけれど、声のどこかに重みがある。弟を思い出す時に声に乗る重み。"}, {"id": "ch03-s02-p090", "type": "text", "text": "「弟さんがいるんですか」"}, {"id": "ch03-s02-p091", "type": "text", "text": "「うん、灯馬ってね。十四歳。今は中円区の親戚のとこにいるの。生意気だけどいいやつ。蓮くんに会わせたいなあ」"}, {"id": "ch03-s02-p092", "type": "text", "text": "天城さんは味噌汁のおかわりを俺の椀に注いだ。聞いていないのに注いだ。"}, {"id": "ch03-s02-p093", "type": "text", "text": "窓の外が暗くなっていた。夕方の橙色はとうに消え、藍色の空に灯籠の明かりが点々と並んでいる。油灯の光が天城さんの横顔を照らしている。ポニーテールの影が壁に伸びていた。黄色のゴムの結び目に、油灯の光が当たって小さく光っていた。"}, {"id": "ch03-s02-p094", "type": "text", "text": "あのゴム。"}, {"id": "ch03-s02-p095", "type": "text", "text": "初めて会った食堂の時から、天城さんの髪にはあの黄色いゴムがあった。制服のブラウスの白に、ポニーテールの赤茶色に、あの黄色だけが配色の中で浮いている。学院の購買にも似たようなゴムは売っているだろうが、天城さんのゴムは少し色あせていた。新しいものではない。長く使っている。左手薬指の布のリングと同じ年季がある。"}, {"id": "ch03-s02-p096", "type": "text", "text": "さっき「灯里村」と言った時に、天城さんの指がそのゴムに触れた。故郷の話と、黄色のゴム。触れたのは無意識だったはずだ。天城さん自身はその動作に気づいていない。"}, {"id": "ch03-s02-p097", "type": "text", "text": "「ねえ蓮くん」"}, {"id": "ch03-s02-p098", "type": "text", "text": "「はい」"}, {"id": "ch03-s02-p099", "type": "text", "text": "「ちゃんと食べなきゃだめだよ。乾麺ばっかりじゃ体もたないから。あたし、また持ってくるね」"}, {"id": "ch03-s02-p100", "type": "text", "text": "「……それは、悪いです」"}, {"id": "ch03-s02-p101", "type": "text", "text": "「悪くないよ。あたし、こういうの得意だから。一人分作るのも二人分作るのも手間は一緒だし」"}, {"id": "ch03-s02-p102", "type": "text", "text": "天城さんは立ち上がって、空になった鍋を布で包み直した。動作が手馴れている。布の端を結ぶ手つき、鍋の持ち手を布の中に収める角度。何度もやってきた動きだった。"}, {"id": "ch03-s02-p103", "type": "text", "text": "「よし、じゃあ片付けて帰るね。明日の鍋は、あたしのじゃなくて蓮くんの鍋に入れてくるから、返す手間なくていいでしょ」"}, {"id": "ch03-s02-p104", "type": "text", "text": "「……ありがとうございます」"}, {"id": "ch03-s02-p105", "type": "text", "text": "「だから敬語！」"}, {"id": "ch03-s02-p106", "type": "text", "text": "天城さんが指を一本立てて俺を指した。食堂で初めて会った日にも同じことを言われた。"}, {"id": "ch03-s02-p107", "type": "text", "text": "「……ありがとう」"}, {"id": "ch03-s02-p108", "type": "text", "text": "「うん。どういたしまして」"}, {"id": "ch03-s02-p109", "type": "text", "text": "天城さんが靴を履いて、扉を開けた。夜の空気が流れ込んできた。灯籠の灯りが通路を照らしている。"}, {"id": "ch03-s02-p110", "type": "text", "text": "「蓮くん」"}, {"id": "ch03-s02-p111", "type": "text", "text": "振り返った。ポニーテールが肩の上で跳ねた。"}, {"id": "ch03-s02-p112", "type": "text", "text": "「ちゃんと寝るんだよ。あと、明日の味噌汁は豚汁にしようかな。蓮くん、豚肉食べられる？」"}, {"id": "ch03-s02-p113", "type": "text", "text": "「食べられます」"}, {"id": "ch03-s02-p114", "type": "text", "text": "「じゃ、決まり！ おやすみ、蓮くん」"}, {"id": "ch03-s02-p115", "type": "text", "text": "手を振って、天城さんが去っていった。足音が通路に響いて、角を曲がって、消えた。"}, {"id": "ch03-s02-p116", "type": "text", "text": "扉を閉めた。"}, {"id": "ch03-s02-p117", "type": "text", "text": "部屋の中が静かになった。"}, {"id": "ch03-s02-p118", "type": "text", "text": "味噌汁の匂いがまだ残っていた。壁に染みた出汁の匂い。油灯の光が、さっきまで天城さんが座っていた調理台の端を照らしている。人がいた痕跡は、匂いと、机の上に残された漬物の包みだけ。"}, {"id": "ch03-s02-p119", "type": "text", "text": "椀を洗った。水が冷たかった。"}, {"id": "ch03-s02-p120", "type": "text", "text": "洗い終えて、椀を伏せて、寝台に腰を下ろした。"}, {"id": "ch03-s02-p121", "type": "text", "text": "「おいしい」と言った時の間を、思い返していた。"}, {"id": "ch03-s02-p122", "type": "text", "text": "あの間は何だったのか。味噌汁の味は舌に残っている。出汁の甘さ。豆腐の柔らかさ。鮭のおにぎりの塩味。茄子の漬物の酸味。全部、体は受け取った。受け取った上で、「おいしい」という言葉を出す瞬間に一拍の空白があった。"}, {"id": "ch03-s02-p123", "type": "text", "text": "食堂の焼き魚を食べた時、「おいしい、と思います」と言った。天城さんに巻き込まれて「おいしいです」に修正した。喫茶「残響」のコーヒーでは「おいしい……のだと思います」に後退した。"}, {"id": "ch03-s02-p124", "type": "text", "text": "今日は、「おいしい」とだけ言った。「思います」はつかなかった。後退もしなかった。でも、間があった。"}, {"id": "ch03-s02-p125", "type": "text", "text": "間の正体が、自分でもわからない。"}, {"id": "ch03-s02-p126", "type": "text", "text": "味噌汁はおいしかったのだと思う。たぶん。体は温まったし、二杯目も飲んだ。でもその「おいしい」は、体の感覚が先にあって言葉がそれを追いかけたのか、天城さんが目の前で「どう？」と聞いている状況が先にあって言葉を選んだのか。"}, {"id": "ch03-s02-p127", "type": "text", "text": "区別がつかない。つかないまま、味噌汁の温度だけが、体の中に残っている。"}, {"id": "ch03-s02-p128", "type": "text", "text": "油灯の光が窓枠を照らしていた。天城さんが「花でも置いたら」と言った場所。何もない窓枠。何もない壁。何もない部屋。"}, {"id": "ch03-s02-p129", "type": "text", "text": "天城さんが入ってきた十五分間だけ、この部屋は匂いと声と熱を持っていた。天城さんが去って、匂いが薄れて、また元の四角い箱に戻ろうとしている。"}, {"id": "ch03-s02-p130", "type": "text", "text": "記録室で篠宮さんと並んで清書をしていた時間のことを思い出した。あの時は「安堵」と呼べるかもしれない体の状態があった。静かで、やるべきことがあって、隣に同じことをしている人がいた。"}, {"id": "ch03-s02-p131", "type": "text", "text": "天城さんとの時間は、あれとは違う。静かではなかった。やるべきことは特になかった。味噌汁を飲んで、おにぎりを食べて、漬物を食べた。天城さんが喋り、俺が短く返した。記録室のペンの音のような均質な時間ではなく、天城さんの声の速度に引っ張られて、時間の流れ方が不均一だった。"}, {"id": "ch03-s02-p132", "type": "text", "text": "でも体は楽だったか。"}, {"id": "ch03-s02-p133", "type": "text", "text": "わからない。楽とは違う。記録室で感じた「負荷の低い状態」とは別の何かがあった。味噌汁が温かくて、天城さんの声が大きくて、部屋の空気が動いていた。楽、とは呼べない。もっと賑やかで、もっと雑多で、でも嫌ではなかった。"}, {"id": "ch03-s02-p134", "type": "text", "text": "嫌ではない、の先に何があるのかは、まだわからない。"}, {"id": "ch03-s02-p135", "type": "text", "text": "寝台に横になった。天井を見上げた。白い漆喰。染みも飾りもない。"}, {"id": "ch03-s02-p136", "type": "text", "text": "天城さんの目の翳り。灯里村の話をした時の、一秒の暗転。三回目のあの反応。今回が一番深かった。そして今回が一番速く消えた。"}, {"id": "ch03-s02-p137", "type": "text", "text": "深いものほど速く隠す。"}, {"id": "ch03-s02-p138", "type": "text", "text": "その推測が正しいかはわからない。ただ、天城さんの笑顔の切り替え速度と、翳りの深さの間に、何かの比例関係がある気がした。"}, {"id": "ch03-s02-p139", "type": "text", "text": "目を閉じた。"}, {"id": "ch03-s02-p140", "type": "text", "text": "味噌汁の匂いが、まだかすかに鼻の奥に残っていた。"}]}, {"chapter": 3, "chapterTitle": "記録と忘却", "scene": 3, "sceneTitle": "残響祭の準備", "wordCount": "約5,900字", "paragraphs": [{"id": "ch03-s03-p001", "type": "text", "text": "講堂の空気が埃っぽかった。"}, {"id": "ch03-s03-p002", "type": "text", "text": "床に敷かれた養生布の上を、資材を載せた台車が何往復もしている。ステージの骨組みが講堂の奥に立ち上がりかけていて、木材と金具が組み合わさる音が天井の梁に反射して戻ってくる。五月の残響祭まで二週間を切っていた。"}, {"id": "ch03-s03-p003", "type": "text", "text": "俺は音響機器の搬入を担当していた。鐘守補佐の業務範囲に「学院行事の音響設営」が含まれていることは、霜月さんから渡された補足指示書に記されていた。鐘鋳塔の音響技術と講堂の拡声設備は同じ系統の残響紋回路を使っている。管理室の計器を読める人間は、講堂の音響盤も読める。理屈としてはわかる。"}, {"id": "ch03-s03-p004", "type": "text", "text": "ただ、音響盤の配線図は管理室のものより古かった。回路の記号体系が一世代前のもので、銅線の接続端子が手作業の半田付けで留められていた。マニュアルには載っていない継ぎ足しの改修跡が三箇所。誰かが過去に自分の判断で配線を変えている。記録はない。"}, {"id": "ch03-s03-p005", "type": "text", "text": "端子の一つに触れた時、また手が先に動いた。指先が端子の締め具合を確かめ、ペンチの角度を調節して増し締めする。その動作を頭が追いかけている。鐘鋳塔の歯車に触れた時と同じだった。知らないはずのことを、手が知っている。"}, {"id": "ch03-s03-p006", "type": "text", "text": "増し締めを終えて、接続を一つずつ確認した。音響盤の隣に積まれた拡声器を台車に載せ、ステージの袖に設置する場所を確認する。ステージの図面が壁に貼り出されていて、拡声器の位置が赤い丸で示されている。左右二基、中央一基。三基とも方向を調整して固定する必要がある。"}, {"id": "ch03-s03-p007", "type": "text", "text": "「——蓮くん、そっち重くない？ 手伝おうか！」"}, {"id": "ch03-s03-p008", "type": "text", "text": "声が講堂の入口から飛んできた。"}, {"id": "ch03-s03-p009", "type": "text", "text": "天城さんが台車を押してこちらに向かっている。台車の上には折り畳み椅子が積まれている。ポニーテールが歩くたびに跳ね、黄色のゴムが光を受けている。袖はいつもの通りまくられていた。前腕が日焼けで少し赤い。"}, {"id": "ch03-s03-p010", "type": "text", "text": "「大丈夫です。重さはそれほどでも——」"}, {"id": "ch03-s03-p011", "type": "text", "text": "「だから敬語！ もう何回目？」"}, {"id": "ch03-s03-p012", "type": "text", "text": "天城さんが台車を押しながら笑った。何回目かは数えていなかった。ただ、天城さんの指摘が来ることは予測できるようになっていた。予測できるのに直せないのは、癖なのか、それとも直す理由がまだ体の中に降りてきていないのか。"}, {"id": "ch03-s03-p013", "type": "text", "text": "「……重くはない。ありがとう」"}, {"id": "ch03-s03-p014", "type": "text", "text": "「うん、よし。あ、椅子はどこに並べるの？」"}, {"id": "ch03-s03-p015", "type": "text", "text": "「ステージの前に五列。図面だと——」"}, {"id": "ch03-s03-p016", "type": "text", "text": "壁の貼り出しを指差そうとした時、講堂の正面扉が開いて、人が増えた。"}, {"id": "ch03-s03-p017", "type": "text", "text": "実行委員の生徒が数人、資材を抱えて入ってくる。その後ろに、亜麻色の髪が見えた。"}, {"id": "ch03-s03-p018", "type": "text", "text": "鳴海さんが歩いてきた。"}, {"id": "ch03-s03-p019", "type": "text", "text": "カーディガンを肩にかけている。白いブラウス。薄桃色のリボンが右の前髪を留めている。隣に風祭さんがいた。短い栗色の髪。緑の瞳。鳴海さんの左側、半歩後ろ。いつもの距離。"}, {"id": "ch03-s03-p020", "type": "text", "text": "鳴海さんが俺たちに気づいて、小さく頭を下げた。"}, {"id": "ch03-s03-p021", "type": "text", "text": "「朝霧さん、お疲れさまです。音響の設営ですか？」"}, {"id": "ch03-s03-p022", "type": "text", "text": "「はい。拡声器の設置と、音響盤の調整を」"}, {"id": "ch03-s03-p023", "type": "text", "text": "「ありがとうございます。歓迎公演で使わせていただくことになるので、助かります」"}, {"id": "ch03-s03-p024", "type": "text", "text": "歓迎公演。鳴海さんが歌う。残響祭のメインプログラムに、共鳴者候補生による歓迎の歌が組まれていることは知っていた。掲示板に貼り出された進行表で読んだ。候補生の名前は一つだけ書かれていた。鳴海千歳。"}, {"id": "ch03-s03-p025", "type": "text", "text": "「歓迎公演、鳴海さんが歌うんですね」"}, {"id": "ch03-s03-p026", "type": "text", "text": "「はい。実行委員会から依頼を受けて……わたしが歌うことで、皆さんが少しでも安心してくださるなら」"}, {"id": "ch03-s03-p027", "type": "text", "text": "鳴海さんの微笑みは穏やかだった。口元と目がほぼ同時に動く、あの微笑み。ただ——「皆さんが安心してくださるなら」という言葉の中に、鳴海さん自身が歌いたいかどうかが含まれていなかった。"}, {"id": "ch03-s03-p028", "type": "text", "text": "前に灯籠通りで二人で歩いた時、鳴海さんは「歌うことが、好きなんです」と言った。あの時の声は今の声と違っていた。あの時は鳴海さんの中から出てきた声だった。今は、依頼と期待に応える声をしていた。"}, {"id": "ch03-s03-p029", "type": "text", "text": "風祭さんが口を開いた。"}, {"id": "ch03-s03-p030", "type": "text", "text": "「ちーちゃん、練習のスケジュール組まなきゃ。あたし今日から毎日付き添うからね」"}, {"id": "ch03-s03-p031", "type": "text", "text": "「いろは、いつもありがとう。でも無理しないで——」"}, {"id": "ch03-s03-p032", "type": "text", "text": "「無理してるのはちーちゃんの方でしょ」"}, {"id": "ch03-s03-p033", "type": "text", "text": "風祭さんの声は軽かった。冗談の形をしている。けれど、その軽さの下に刃の鈍い光がある。前に訓練棟のロビーで会った時の鋭さとは違う。鳴海さんの前だから鞘に入っている——だが、刃が見えないわけではない。"}, {"id": "ch03-s03-p034", "type": "text", "text": "風祭さんの視線がこちらに来た。"}, {"id": "ch03-s03-p035", "type": "text", "text": "「朝霧さん」"}, {"id": "ch03-s03-p036", "type": "text", "text": "「はい」"}, {"id": "ch03-s03-p037", "type": "text", "text": "「音響、ちゃんとやってくれるんでしょ。ちーちゃんの歌、ちゃんと届くようにしてよね」"}, {"id": "ch03-s03-p038", "type": "text", "text": "命令の形だった。口調は明るく、語尾に笑いが混じっている。けれど目は笑っていなかった。目は査定の目をしていた。蓮がこの仕事をきちんとやるかどうかを、ここで見ている。"}, {"id": "ch03-s03-p039", "type": "text", "text": "「……やります」"}, {"id": "ch03-s03-p040", "type": "text", "text": "「うん。頼んだよ」"}, {"id": "ch03-s03-p041", "type": "text", "text": "風祭さんが鳴海さんの肩に軽く手を置いた。その手つきに何百回の繰り返しがある。鳴海さんが自然に受け入れている。鳴海さんにとって風祭さんの手は、いつもそこにあるものなのだろう。"}, {"id": "ch03-s03-p042", "type": "text", "text": "鳴海さんと風祭さんがステージの方へ歩いていった。実行委員の一人が鳴海さんに進行表を見せている。鳴海さんが頷き、風祭さんがその進行表を覗き込んでいる。"}, {"id": "ch03-s03-p043", "type": "text", "text": "天城さんが俺の隣に立っていた。"}, {"id": "ch03-s03-p044", "type": "text", "text": "「いろはちゃん、ちーちゃんのこと大事にしてるよね」"}, {"id": "ch03-s03-p045", "type": "text", "text": "「そう見えます」"}, {"id": "ch03-s03-p046", "type": "text", "text": "「あたしにはあんなに厳しくないのに。朝霧——じゃなくて、蓮くんには結構ぴりってしてたね。ちーちゃんの歌のこと、本気なんだよ」"}, {"id": "ch03-s03-p047", "type": "text", "text": "天城さんは腕を組んで、ステージの方を見ていた。風祭さんが鳴海さんの横で進行表を指差しながら何か言っている。鳴海さんが笑った。風祭さんも笑った。俺の前では見せない笑い方をしている。口が大きく開いて、声が出ている。"}, {"id": "ch03-s03-p048", "type": "text", "text": "午後の残りを音響盤の調整に費やした。接続の確認、各拡声器の出力テスト。テスト音が講堂に響いた時、天井の梁が低く震えた。残響紋が刻まれた梁が音を拾い、反射して返す。講堂の音響は鐘鋳塔とは違う柔らかさがあった。石ではなく木と漆喰の壁が音を吸う。"}, {"id": "ch03-s03-p049", "type": "text", "text": "テスト中に、ステージの奥から声が聞こえた。鳴海さんが進行表の確認のために軽く声を出していた。歌ではなく、音の確認程度の短い発声。それでも拡声器を通すと、声が講堂の空気を変えた。空気の粒が細かくなったような、そういう変化。"}, {"id": "ch03-s03-p050", "type": "text", "text": "風祭さんが鳴海さんの横でメモを取っていた。マネージャーの動きだった。進行時間、立ち位置、照明のタイミング。鳴海さんが歌に集中できるように、それ以外の全てを風祭さんが引き受けている。"}, {"id": "ch03-s03-p051", "type": "text", "text": "「ちーちゃんの邪魔しないでね」"}, {"id": "ch03-s03-p052", "type": "text", "text": "風祭さんの声が、背後から聞こえた。"}, {"id": "ch03-s03-p053", "type": "text", "text": "振り返ると、風祭さんが音響盤の横に立っていた。いつの間に来たのか気づかなかった。"}, {"id": "ch03-s03-p054", "type": "text", "text": "「練習が増えるから、朝霧さんと顔を合わせることも増えると思うけど。ちーちゃんが集中できるようにしてあげてほしいの」"}, {"id": "ch03-s03-p055", "type": "text", "text": "声が柔らかかった。さっきの査定の目ではなかった。頬の筋肉が少しだけ緩んでいて、口元に笑みの痕跡がある。鳴海さんの歌を近くで聴いた後の顔。音が硬さを溶かしたのかもしれない。"}, {"id": "ch03-s03-p056", "type": "text", "text": "「邪魔はしません」"}, {"id": "ch03-s03-p057", "type": "text", "text": "「うん。信じとく」"}, {"id": "ch03-s03-p058", "type": "text", "text": "風祭さんが踵を返してステージに戻っていった。"}, {"id": "ch03-s03-p059", "type": "text", "text": "「信じとく」。前に会った時は「よろしく」すら言わなかった。今日は「信じとく」と言った。距離は変わっていない。けれど壁の材質が変わった気がした。石の壁が、木の壁になった。厚さは同じでも、叩いた時の音が違う。"}, {"id": "ch03-s03-p060", "type": "divider", "text": "---"}, {"id": "ch03-s03-p061", "type": "text", "text": "講堂の作業を終えたのは十五時過ぎだった。"}, {"id": "ch03-s03-p062", "type": "text", "text": "中庭を通って鐘鋳塔に戻る。中庭の中央に残響桜がある。この島にしかない品種だと聞いた。花の色が薄紫で、花弁の縁が白い。五月に入って盛りは過ぎていたが、まだ花弁が残っていた。散りかけの花弁が地面に薄い紫の層を作っている。風が吹くと、枝の先から数枚が離れて、ゆっくり落ちた。"}, {"id": "ch03-s03-p063", "type": "text", "text": "残響桜の下のベンチに天城さんが座っていた。飲み物を二つ持っている。"}, {"id": "ch03-s03-p064", "type": "text", "text": "「蓮くん、お疲れ！ はい、これ」"}, {"id": "ch03-s03-p065", "type": "text", "text": "冷たい麦茶の瓶を手渡された。受け取ると、瓶の表面に結露がついていて、指が滑った。天城さんが「あぶない」と言って、俺の手の上から瓶を押さえた。天城さんの手のひらが俺の指に触れた。一秒か二秒。天城さんがすぐに手を離した。"}, {"id": "ch03-s03-p066", "type": "text", "text": "ベンチに並んで座った。天城さんが麦茶を飲みながら、中庭を見渡している。"}, {"id": "ch03-s03-p067", "type": "text", "text": "「残響祭、楽しみだね！ 蓮くんも一緒に回ろうよ」"}, {"id": "ch03-s03-p068", "type": "text", "text": "天城さんが言った。笑っている。はしばみ色の瞳が中庭の光を映している。残響桜の薄紫の花弁が、天城さんの赤茶色の髪の上に一枚乗っている。本人は気づいていない。"}, {"id": "ch03-s03-p069", "type": "text", "text": "「一緒に、ですか」"}, {"id": "ch03-s03-p070", "type": "text", "text": "「うん！ 屋台とか出るし、出し物もあるし。一人で回ってもつまんないでしょ。みんなで行こうよ。ちーちゃんも、いろはちゃんも、雫ちゃんも」"}, {"id": "ch03-s03-p071", "type": "text", "text": "天城さんの「みんな」には、天城さんが知っている全員が入る。遠慮なく名前を並べる。天城さんのその巻き込み方は、食堂で初めて会った日からずっと同じだった。"}, {"id": "ch03-s03-p072", "type": "text", "text": "「鳴海さんは出演があるのでは——」"}, {"id": "ch03-s03-p073", "type": "text", "text": "言いかけた時、後ろから声がした。"}, {"id": "ch03-s03-p074", "type": "text", "text": "「朝霧さん、天城さん。お疲れさまです」"}, {"id": "ch03-s03-p075", "type": "text", "text": "鳴海さんが中庭に出てきていた。カーディガンを羽織っている。講堂の中では肩にかけていたが、外に出て袖を通したらしい。風祭さんが半歩後ろにいる。"}, {"id": "ch03-s03-p076", "type": "text", "text": "天城さんが身を乗り出した。"}, {"id": "ch03-s03-p077", "type": "text", "text": "「ちーちゃん！ 残響祭、みんなで回ろうって話してたの！」"}, {"id": "ch03-s03-p078", "type": "text", "text": "鳴海さんが微笑んだ。穏やかな微笑みの中に、少しだけ困った色が混じっている。首をわずかに傾けた。"}, {"id": "ch03-s03-p079", "type": "text", "text": "「わたしは出演があるので……でも、終わったら皆さんと合流できたら嬉しいです」"}, {"id": "ch03-s03-p080", "type": "text", "text": "「じゃあ決まり！ 歌が終わったらすぐ合流ね！」"}, {"id": "ch03-s03-p081", "type": "text", "text": "天城さんが拳を握った。右腕を上げて、ガッツポーズ。残響桜の花弁が天城さんの頭から落ちた。風が運んでいった。"}, {"id": "ch03-s03-p082", "type": "text", "text": "風祭さんが腕を組んでいた。天城さんの勢いに呆れた顔をしているが、口元は曲がっていない。「嫌だ」とは言っていなかった。"}, {"id": "ch03-s03-p083", "type": "text", "text": "「いろはちゃんも来るでしょ！」"}, {"id": "ch03-s03-p084", "type": "text", "text": "「まあ、ちーちゃんの出番が終わってからなら。あたしは本番中はステージ袖にいるけど」"}, {"id": "ch03-s03-p085", "type": "text", "text": "「よし、全員参加！ 蓮くんも、いいよね？」"}, {"id": "ch03-s03-p086", "type": "text", "text": "天城さんが俺を見た。はしばみ色の瞳。期待が声に乗っている。瞳の中に「断るはずがない」という確信がある。天城さんのその確信は、俺が断る人間ではないことを知っているからではなく、断る理由がないと思っているからだ。天城さんにとって、みんなで祭りを回ることは自然なことで、誘われた側が断る状況を想定していない。"}, {"id": "ch03-s03-p087", "type": "text", "text": "鳴海さんもこちらを見ていた。琥珀色の瞳。穏やかで、静かな目。天城さんの期待とは違う温度で、俺の返事を待っている。"}, {"id": "ch03-s03-p088", "type": "text", "text": "「……はい」"}, {"id": "ch03-s03-p089", "type": "text", "text": "天城さんが「敬語！」と言うかと思ったが、今度は言わなかった。代わりに「やった！」と声を上げた。"}, {"id": "ch03-s03-p090", "type": "text", "text": "風祭さんが鳴海さんの肩に手を置いた。「ほら、ちーちゃん。練習の時間」。鳴海さんが頷いて、「では、また」と軽く会釈した。二人がステージのある講堂の方へ戻っていく。風祭さんが何か言い、鳴海さんが笑った。声は聞こえなかったが、肩が揺れていた。"}, {"id": "ch03-s03-p091", "type": "text", "text": "天城さんが麦茶を飲み干した。"}, {"id": "ch03-s03-p092", "type": "text", "text": "「蓮くん、残響祭楽しみでしょ？」"}, {"id": "ch03-s03-p093", "type": "text", "text": "楽しみ。"}, {"id": "ch03-s03-p094", "type": "text", "text": "その言葉が耳に残った。"}, {"id": "ch03-s03-p095", "type": "text", "text": "楽しみ、とは何だろう。まだ来ていない出来事に対して、今の体が反応する。それが「楽しみ」の構造だとすれば——今、俺の体に何か反応はあるか。"}, {"id": "ch03-s03-p096", "type": "text", "text": "天城さんが「みんなで回ろう」と言った時、嫌だとは思わなかった。鳴海さんが「合流できたら嬉しいです」と言った時も、悪くないと思った。風祭さんが「まあ」と言って断らなかったことにも、何かが安堵に似た。"}, {"id": "ch03-s03-p097", "type": "text", "text": "嫌ではない。悪くない。断る理由がない。その三つが「楽しみ」と呼べるのかどうかは、わからない。"}, {"id": "ch03-s03-p098", "type": "text", "text": "でも、二週間後にあの講堂で鳴海さんが歌い、ステージの袖で風祭さんがメモを取り、終演後に天城さんが「こっちこっち」と手を振って、たぶん篠宮さんも静かにどこかにいて——その光景が頭に浮かんだ。まだ起きていないことの像が浮かぶ。監視哨にいた頃は、明日の像は浮かばなかった。明日も同じ景色が来るとわかっていたから、浮かべる必要がなかった。"}, {"id": "ch03-s03-p099", "type": "text", "text": "今は違う。二週間後の像が浮かんで、その像が「悪くないもの」として体の中に収まっている。"}, {"id": "ch03-s03-p100", "type": "text", "text": "「……悪くない、と思う」"}, {"id": "ch03-s03-p101", "type": "text", "text": "「またそれ！ いつかちゃんと『楽しみ』って言ってもらうからね」"}, {"id": "ch03-s03-p102", "type": "text", "text": "天城さんが笑った。以前にも似たやり取りがあった。喫茶「残響」の帰り道。「いつかちゃんと『楽しかった』って言ってもらうからね」。あの時は過去形を求められた。今回は未来形。天城さんは俺の語彙を一段ずつ上げようとしている。"}, {"id": "ch03-s03-p103", "type": "text", "text": "残響桜の花弁が風に飛ばされて、ベンチの上を横切った。薄紫の一枚。麦茶の瓶の縁にぶつかって、地面に落ちた。"}, {"id": "ch03-s03-p104", "type": "text", "text": "「蓮くん、髪に花びらついてるよ」"}, {"id": "ch03-s03-p105", "type": "text", "text": "天城さんの手が伸びてきた。俺の前髪に触れ、花弁を指先で摘み取った。天城さんの指先が額の近くを通過した。触れてはいない。花弁だけを取って、手を引いた。"}, {"id": "ch03-s03-p106", "type": "text", "text": "摘み取った花弁を、天城さんが手のひらに載せて見ている。"}, {"id": "ch03-s03-p107", "type": "text", "text": "「きれいだね、この桜。普通の桜と色が違うんだよね。紫っぽくて」"}, {"id": "ch03-s03-p108", "type": "text", "text": "薄紫の花弁。残響桜。天城さんの手のひらの上で、風に乗って飛ぼうとしている。天城さんが手を開いた。花弁が風に攫われて、中庭の上を舞い上がった。"}, {"id": "ch03-s03-p109", "type": "text", "text": "天城さんが立ち上がった。"}, {"id": "ch03-s03-p110", "type": "text", "text": "「あたし、椅子並べの続きやってくるね。蓮くん、音響の方は大丈夫？」"}, {"id": "ch03-s03-p111", "type": "text", "text": "「問題ない。午後の分は終わった」"}, {"id": "ch03-s03-p112", "type": "text", "text": "「さすが。じゃあまた後でね！」"}, {"id": "ch03-s03-p113", "type": "text", "text": "手を振って、講堂の方へ走っていった。ポニーテールが揺れている。黄色のゴムが、五月の日差しの中で明るく見えた。"}, {"id": "ch03-s03-p114", "type": "text", "text": "一人になった。"}, {"id": "ch03-s03-p115", "type": "text", "text": "ベンチに座ったまま、残響桜を見上げた。花弁がまだ枝に残っている。散りかけている。あと数日で全て落ちるだろう。残響祭の頃には、葉桜になっているかもしれない。"}, {"id": "ch03-s03-p116", "type": "text", "text": "講堂の方から、かすかに声が聞こえた。鳴海さんの発声練習。拡声器は通していない。壁越しに漏れてくる、素の声。遠くて、旋律は聞き取れない。ただ声が空気を震わせているのがわかる。"}, {"id": "ch03-s03-p117", "type": "text", "text": "風祭さんはあの声の一番近くにいる。鳴海さんの歌を、毎日聴いている。鳴海さんの声の変化に、誰よりも早く気づく場所にいる。「ちーちゃんの邪魔しないでね」は、その場所から出た言葉だった。"}, {"id": "ch03-s03-p118", "type": "text", "text": "音響盤は調整した。拡声器の位置も、出力も、反響の角度も確認した。二週間後に鳴海さんが歌う時、この講堂の音が正しく届くようにする。それが俺の仕事だった。"}, {"id": "ch03-s03-p119", "type": "text", "text": "仕事だから、やる。それだけのはずだった。"}, {"id": "ch03-s03-p120", "type": "text", "text": "でも——仕事だから、以外の何かが混じっているかもしれない。鳴海さんの声を聴いた時の鳩尾の緩みを、二週間後にまた感じるかもしれないということ。天城さんが「こっち」と手を振っている像が、体の中で「悪くないもの」として収まっていること。風祭さんが「信じとく」と言ったこと。"}, {"id": "ch03-s03-p121", "type": "text", "text": "全部、まだ名前がつかない。"}, {"id": "ch03-s03-p122", "type": "text", "text": "楽しみ、という一語が、それら全部を束ねる言葉なのかもしれない。"}, {"id": "ch03-s03-p123", "type": "text", "text": "まだわからない。でも、悪くはない。たぶん。"}, {"id": "ch03-s03-p124", "type": "text", "text": "残響桜の花弁が、もう一枚落ちた。"}]}, {"chapter": 3, "chapterTitle": "記録と忘却", "scene": 4, "sceneTitle": "桜の下の弁当", "wordCount": "約4,100字", "paragraphs": [{"id": "ch03-s04-p001", "type": "text", "text": "残響桜の花が減っていた。"}, {"id": "ch03-s04-p002", "type": "text", "text": "一週間前に講堂の作業を終えてベンチに座った時は、枝の先にまだ花弁の房が残っていた。今日は葉の方が多い。緑の合間に薄紫がまばらに散っている。風が吹くと、残った花弁が一枚ずつ落ちる。地面の薄紫の層は乾いて色が褪せていた。"}, {"id": "ch03-s04-p003", "type": "text", "text": "五月の中旬。昼の十二時半。残響祭まであと十日ほど。"}, {"id": "ch03-s04-p004", "type": "text", "text": "「蓮くーん、こっちこっち！」"}, {"id": "ch03-s04-p005", "type": "text", "text": "中円公園のベンチに天城さんがすでに座っていた。膝の上に風呂敷の包みを載せている。紺色の布。両手でしっかり抱えている。ポニーテールが風に揺れて、黄色のゴムに日差しが当たっていた。"}, {"id": "ch03-s04-p006", "type": "text", "text": "「天城さん、先に来てたんですか」"}, {"id": "ch03-s04-p007", "type": "text", "text": "「だから敬語」"}, {"id": "ch03-s04-p008", "type": "text", "text": "開口一番だった。座る前に指摘された。天城さんの敬語の検知速度は上がっている。以前は二言目で来たが、最近は一言目に反応する。"}, {"id": "ch03-s04-p009", "type": "text", "text": "「……先に来てたんだ」"}, {"id": "ch03-s04-p010", "type": "text", "text": "「うん。場所取り。ここのベンチ、昼休みは取り合いになるんだよ。桜の真下だし」"}, {"id": "ch03-s04-p011", "type": "text", "text": "天城さんの隣に座った。ベンチの木が日差しで温められていて、座面が熱かった。"}, {"id": "ch03-s04-p012", "type": "text", "text": "天城さんが風呂敷を膝の上で開いた。二段の重ね箱が出てきた。蓋は木製で、角が丸く削られている。天城さんが上の段の蓋を取った。"}, {"id": "ch03-s04-p013", "type": "text", "text": "おにぎりが六つ。三角に握られ、海苔が巻かれている。その横に玉子焼きが五切れ。黄色い断面が行儀よく並んでいる。下の段は漬物ときんぴらごぼうと、胡瓜の浅漬け。"}, {"id": "ch03-s04-p014", "type": "text", "text": "「二人分作ってきた。蓮くんの分もちゃんとあるから」"}, {"id": "ch03-s04-p015", "type": "text", "text": "「……こんなに」"}, {"id": "ch03-s04-p016", "type": "text", "text": "「だって蓮くん、一人だと乾麺でしょ。昼も食堂の定食だけでしょ。足りてないよ絶対」"}, {"id": "ch03-s04-p017", "type": "text", "text": "反論の材料がなかった。天城さんの推測は正しかった。"}, {"id": "ch03-s04-p018", "type": "text", "text": "「はい、おにぎり。梅と鮭と昆布。今日は鮭が自信作」"}, {"id": "ch03-s04-p019", "type": "text", "text": "天城さんが鮭のおにぎりを差し出した。受け取ると、米の重みが手のひらに乗った。握り方が前に補佐官舎で食べた時と同じ——固すぎず、柔らかすぎない。海苔の端が少し湿っていた。"}, {"id": "ch03-s04-p020", "type": "text", "text": "かじった。"}, {"id": "ch03-s04-p021", "type": "text", "text": "鮭の塩気が米の甘みの中に入ってくる。海苔の風味が追いかけてくる。前に補佐官舎で食べた時の鮭のおにぎりと同じ味だった。同じ人が、同じ手つきで握ったもの。当たり前のことなのに、同じ味がもう一度来ることに妙な安堵があった。"}, {"id": "ch03-s04-p022", "type": "text", "text": "天城さんが梅のおにぎりを持って、大きく口を開けてかじった。頬が膨らんだ。"}, {"id": "ch03-s04-p023", "type": "text", "text": "「んー、やっぱ外で食べるとおいしいね！」"}, {"id": "ch03-s04-p024", "type": "text", "text": "天城さんは食べながら喋る。口の中のものを飲み込む前に次の言葉が始まる。行儀が良いとは言えない。けれど、その食べ方には迷いがなかった。食べることに対する真っ直ぐさ。天城さんの「食べることは生きること」が、おにぎりを頬張る姿にそのまま出ていた。"}, {"id": "ch03-s04-p025", "type": "text", "text": "玉子焼きを一切れ取った。甘い。砂糖と出汁の味がする。卵の黄色が濃くて、端が少し焦げている。"}, {"id": "ch03-s04-p026", "type": "text", "text": "「玉子焼き、ちょっと焦げちゃったんだけど」"}, {"id": "ch03-s04-p027", "type": "text", "text": "「気にならない。甘い」"}, {"id": "ch03-s04-p028", "type": "text", "text": "「蓮くん、甘い玉子焼き派？ しょっぱい派？」"}, {"id": "ch03-s04-p029", "type": "text", "text": "「わからない。これしか食べたことがない」"}, {"id": "ch03-s04-p030", "type": "text", "text": "天城さんが一瞬きょとんとした顔をして、それから笑った。"}, {"id": "ch03-s04-p031", "type": "text", "text": "「じゃあ、今度しょっぱいのも作ってくるね。比べてみよ」"}, {"id": "ch03-s04-p032", "type": "text", "text": "風が吹いた。残響桜の枝が揺れて、薄紫の花弁が三枚ほど落ちた。一枚が天城さんの肩に乗った。天城さんは気づかずに昆布のおにぎりに手を伸ばしている。もう一枚がベンチと俺の腿の間に落ちた。花弁の縁が白い。中心に向かって薄紫が濃くなっている。"}, {"id": "ch03-s04-p033", "type": "text", "text": "「蓮くんって、前はどこにいたの？」"}, {"id": "ch03-s04-p034", "type": "text", "text": "天城さんが言った。"}, {"id": "ch03-s04-p035", "type": "text", "text": "おにぎりを持ったまま、こちらを見ていた。はしばみ色の瞳。好奇心がある。けれど、それだけではない。何か別のものが混じっている。前のめりの好奇心ではなく、もっと静かな——知りたい、というより、確かめたい、に近い目。"}, {"id": "ch03-s04-p036", "type": "text", "text": "唐突な問いかけではなかった。天城さんの中では、ここまでの会話の流れの中に位置づけられているのだろう。食堂で初めて会った日に「自分で選んだ名前」だと知った。補佐官舎の部屋に何もないことを見た。乾麺しか食べていないことを知った。断片がある。ただ、それがどこから来た人間なのかは聞いていなかった。"}, {"id": "ch03-s04-p037", "type": "text", "text": "「……覚えていない」"}, {"id": "ch03-s04-p038", "type": "text", "text": "口から出た言葉はそれだった。"}, {"id": "ch03-s04-p039", "type": "text", "text": "「二年前に縁際で見つかった。それ以前のことは、何も」"}, {"id": "ch03-s04-p040", "type": "text", "text": "天城さんがおにぎりを膝の上に置いた。"}, {"id": "ch03-s04-p041", "type": "text", "text": "視線が変わった。"}, {"id": "ch03-s04-p042", "type": "text", "text": "同情ではなかった。目が潤んだり、眉が下がったりはしなかった。天城さんの顔にあったのは、もっと別の反応だった。口元の力が抜けて、目がわずかに見開かれた。驚きでもない。何か——自分の中にある感覚と、今聞いた言葉が重なった時の、あの反応。他人の話なのに、自分の体が反応してしまった時の顔。"}, {"id": "ch03-s04-p043", "type": "text", "text": "共感、というのが一番近い。"}, {"id": "ch03-s04-p044", "type": "text", "text": "一秒か、二秒。"}, {"id": "ch03-s04-p045", "type": "text", "text": "「そっか」"}, {"id": "ch03-s04-p046", "type": "text", "text": "天城さんの声が、さっきまでより低かった。音量は同じ。けれどトーンが違う。いつもの跳ねるような声ではなく、地面に近い声。"}, {"id": "ch03-s04-p047", "type": "text", "text": "「あたしもね……」"}, {"id": "ch03-s04-p048", "type": "text", "text": "天城さんが膝の上のおにぎりを見ていた。視線が落ちている。ポニーテールが風に揺れたが、天城さんの目は動かなかった。"}, {"id": "ch03-s04-p049", "type": "text", "text": "「忘れたくないことがあるんだけど、忘れちゃいそうで怖い時がある」"}, {"id": "ch03-s04-p050", "type": "text", "text": "声が静かだった。"}, {"id": "ch03-s04-p051", "type": "text", "text": "天城さんの声が静かになること自体が珍しかった。食堂で、喫茶「残響」で、補佐官舎で、講堂で——天城さんの声はいつも部屋を満たす大きさがあった。今の声は、ベンチの上だけに留まっている。風が少し強ければ散ってしまうような音量。"}, {"id": "ch03-s04-p052", "type": "text", "text": "左手の指先が、黄色のヘアゴムに触れていた。結び目のあたり。前に補佐官舎で灯里村の話をした時と同じ動作。無意識。天城さんは自分の指がゴムに触れていることに気づいていない。"}, {"id": "ch03-s04-p053", "type": "text", "text": "左薬指の布のリング。少しほつれている。"}, {"id": "ch03-s04-p054", "type": "text", "text": "「天城さんにも、そういうことがあるんですか」"}, {"id": "ch03-s04-p055", "type": "text", "text": "聞いていた。"}, {"id": "ch03-s04-p056", "type": "text", "text": "敬語が戻っていることには、天城さんは何も言わなかった。"}, {"id": "ch03-s04-p057", "type": "text", "text": "間があった。桜の花弁が一枚、天城さんの膝の上のおにぎりの横に落ちた。薄紫の小さな花弁。"}, {"id": "ch03-s04-p058", "type": "text", "text": "天城さんが顔を上げた。"}, {"id": "ch03-s04-p059", "type": "text", "text": "笑っていた。"}, {"id": "ch03-s04-p060", "type": "text", "text": "目が細くなり、頬が上がり、口の端が持ち上がっている。いつもの天城さんの笑顔。さっきまでの静かな声から、切り替わるまでの時間は——"}, {"id": "ch03-s04-p061", "type": "text", "text": "一秒なかった。"}, {"id": "ch03-s04-p062", "type": "text", "text": "四回目。食堂の時。喫茶「残響」の時。補佐官舎の時。そして今。翳りが出て、笑顔に戻る。毎回速くなっている。今回が最も速かった。"}, {"id": "ch03-s04-p063", "type": "text", "text": "「ま、誰にでもあるよね！ ほら、おにぎり食べて食べて！ 鮭もう一個あるよ」"}, {"id": "ch03-s04-p064", "type": "text", "text": "声の高さが戻っていた。手が動いている。おにぎりを一つ取って、俺の方に差し出している。包みを開いた時と同じ速度、同じ明るさ。何もなかったかのように。"}, {"id": "ch03-s04-p065", "type": "text", "text": "俺はおにぎりを受け取った。"}, {"id": "ch03-s04-p066", "type": "text", "text": "追及しなかった。"}, {"id": "ch03-s04-p067", "type": "text", "text": "天城さんが自分から戻した以上、俺がそこに踏み込む理由がない。記録室で篠宮さんの筆跡の震えに気づいた時も、補佐官舎で天城さんの目の翳りを見た時も、俺は同じ判断をしている。見えたものを記録して、そのままにしておく。"}, {"id": "ch03-s04-p068", "type": "text", "text": "ただ、今回は一つだけ違うことがあった。"}, {"id": "ch03-s04-p069", "type": "text", "text": "天城さんは「忘れちゃいそうで怖い」と言った。"}, {"id": "ch03-s04-p070", "type": "text", "text": "俺には覚えていないことがある。二年前より前の全部。それに対して、天城さんには覚えていたいのに忘れていくものがある。"}, {"id": "ch03-s04-p071", "type": "text", "text": "俺は——忘れたことを悲しいとも悔しいとも思えない。忘れた記憶がそもそもないのだから、喪失の実感がない。天城さんは違う。忘れたくないのに忘れていく。その過程を、体が知っている。"}, {"id": "ch03-s04-p072", "type": "text", "text": "「忘れたくないことがある」という言葉の重さは、忘れていく痛みを知っている人間にしか出せない。"}, {"id": "ch03-s04-p073", "type": "text", "text": "天城さんが何を忘れたくないのかは聞かなかった。でも、天城さんの指がヘアゴムに触れたこと。左薬指の布のリングのほつれ。灯里村の名前を出した時の目の翳り。三回目、四回目と重なるたびに深くなり、切り替えが速くなる。"}, {"id": "ch03-s04-p074", "type": "text", "text": "全部、繋がっている。"}, {"id": "ch03-s04-p075", "type": "text", "text": "鮭のおにぎりを一口かじった。さっきと同じ味だった。同じ人が握った同じ味。二個目のおにぎりを食べながら、俺は天城さんの言葉を体の中に収めていた。"}, {"id": "ch03-s04-p076", "type": "text", "text": "「天城さんにも、忘れたくないことがある」。"}, {"id": "ch03-s04-p077", "type": "text", "text": "覚えておく。"}, {"id": "ch03-s04-p078", "type": "text", "text": "天城さんが玉子焼きの最後の一切れを箸で取って、俺の方に向けた。"}, {"id": "ch03-s04-p079", "type": "text", "text": "「蓮くん、最後の一個食べなよ」"}, {"id": "ch03-s04-p080", "type": "text", "text": "「天城さんが食べたらいい」"}, {"id": "ch03-s04-p081", "type": "text", "text": "「あたしはもう充分。蓮くんの方が足りてないもん」"}, {"id": "ch03-s04-p082", "type": "text", "text": "押し問答する気力はなかった。玉子焼きを受け取って口に入れた。甘い。端の焦げた部分がわずかに苦い。甘さと苦さ。"}, {"id": "ch03-s04-p083", "type": "text", "text": "風が吹いた。残響桜の枝から、花弁がまとめて散った。五枚、六枚。薄紫の花弁がベンチの周りに舞い落ちる。天城さんの肩に乗っていた一枚が、風に攫われて飛んでいった。"}, {"id": "ch03-s04-p084", "type": "text", "text": "天城さんが空を見上げた。"}, {"id": "ch03-s04-p085", "type": "text", "text": "「来週にはもう葉桜だね。残響祭の時はもう花ないかも」"}, {"id": "ch03-s04-p086", "type": "text", "text": "「散りかけている」"}, {"id": "ch03-s04-p087", "type": "text", "text": "「うん。でもね、あたし葉桜も好きだよ。緑が濃くてさ。花が散った後も木はちゃんとあるでしょ」"}, {"id": "ch03-s04-p088", "type": "text", "text": "天城さんが立ち上がって、風呂敷で重ね箱を包み直した。手際が良い。布の端を結ぶ動作に何百回の繰り返しがある。"}, {"id": "ch03-s04-p089", "type": "text", "text": "「よし、午後も頑張ろ！ 蓮くん、今日は音響の最終チェックだよね？」"}, {"id": "ch03-s04-p090", "type": "text", "text": "「拡声器の出力調整が残っている」"}, {"id": "ch03-s04-p091", "type": "text", "text": "「さすが。あたしは看板の仕上げ。ペンキ塗りだよ。蓮くんも手伝う？」"}, {"id": "ch03-s04-p092", "type": "text", "text": "「拡声器が先だ」"}, {"id": "ch03-s04-p093", "type": "text", "text": "「ちぇー。じゃあ終わったら手伝いに来てよ。ペンキ、二色だけだから簡単だよ」"}, {"id": "ch03-s04-p094", "type": "text", "text": "天城さんが風呂敷包みを抱えてベンチから離れた。二歩ほど歩いて、振り返った。"}, {"id": "ch03-s04-p095", "type": "text", "text": "「蓮くん」"}, {"id": "ch03-s04-p096", "type": "text", "text": "「うん」"}, {"id": "ch03-s04-p097", "type": "text", "text": "「ありがと、食べてくれて。あたし、作る人がいると張り切っちゃうんだよね」"}, {"id": "ch03-s04-p098", "type": "text", "text": "天城さんが笑った。さっきの切り替え後の笑顔とは違う。これは——玉子焼きの焦げ具合を気にしていた時の顔に近い。自分がやったことに対する素直な反応。張り切ったことが嬉しいのだと、顔が言っていた。"}, {"id": "ch03-s04-p099", "type": "text", "text": "「ごちそうさまでした」"}, {"id": "ch03-s04-p100", "type": "text", "text": "「敬語！ ……まあ、ごちそうさまは許す」"}, {"id": "ch03-s04-p101", "type": "text", "text": "天城さんが手を振って歩いていった。ポニーテールが揺れている。黄色のゴムが日差しの中で光った。風呂敷包みを片手に持ち替えて、もう片方の手を大きく振っている。"}, {"id": "ch03-s04-p102", "type": "text", "text": "一人になった。"}, {"id": "ch03-s04-p103", "type": "text", "text": "ベンチに座ったまま、残響桜を見上げた。花弁がまた一枚落ちた。地面に着く前に風に攫われて、公園の芝生の上を転がっていった。"}, {"id": "ch03-s04-p104", "type": "text", "text": "花が散った後も木はちゃんとある。"}, {"id": "ch03-s04-p105", "type": "text", "text": "天城さんの言葉を思い返していた。散った花弁は戻らない。けれど木は残る。枝があり、幹があり、根がある。花が散ることと、木がなくなることは違う。"}, {"id": "ch03-s04-p106", "type": "text", "text": "忘れたくないことがある。忘れちゃいそうで怖い。"}, {"id": "ch03-s04-p107", "type": "text", "text": "天城さんの静かな声が、耳の中に残っている。あの声は、いつもの天城さんの声と同じ喉から出ていた。同じ人間の中に、あの大きな声とあの静かな声が両方ある。普段は大きい方が外に出ている。静かな方は、内側に収まっている。"}, {"id": "ch03-s04-p108", "type": "text", "text": "今日、ほんの数秒だけ、内側のものが外に漏れた。そして天城さんは自分でそれを押し戻した。"}, {"id": "ch03-s04-p109", "type": "text", "text": "俺には記憶がない。失ったものの輪郭を知らない。だから忘れる怖さも持っていない。"}, {"id": "ch03-s04-p110", "type": "text", "text": "天城さんは違う。輪郭を知っている。知っているから、その輪郭が薄れていくことが怖い。"}, {"id": "ch03-s04-p111", "type": "text", "text": "同じ「忘却」でも、位置が違う。俺は忘却の先にいる。天城さんは忘却の途中にいる。"}, {"id": "ch03-s04-p112", "type": "text", "text": "覚えておく。天城さんが今日この桜の下で漏らした言葉と、あの静かな声と、ヘアゴムに触れた指先を。"}, {"id": "ch03-s04-p113", "type": "text", "text": "残響桜の花弁が、もう一枚落ちた。薄紫。風に乗って、ゆっくり地面に着いた。"}]}, {"chapter": 3, "chapterTitle": "記録と忘却", "scene": 5, "sceneTitle": "記録室の夕暮れ", "wordCount": "約5,100字", "paragraphs": [{"id": "ch03-s05-p001", "type": "text", "text": "拡声器の出力調整は十六時半に終わった。"}, {"id": "ch03-s05-p002", "type": "text", "text": "講堂の左右に設置された四基の拡声器を順に鳴らし、残響祭当日の音量設定を記録帳に書き込む。最後の一基の調整ネジが固かったが、工具を変えて対処した。講堂の作業を終えて外に出ると、日差しが傾いていた。午前中の真上からの白い光ではなく、斜めに差す橙の光。影が伸びている。"}, {"id": "ch03-s05-p003", "type": "text", "text": "図書館に向かった。"}, {"id": "ch03-s05-p004", "type": "text", "text": "木の外壁。煉瓦の基礎。緑青の雨樋。何度目かの景色だった。何度目か、を正確に数えられる。三度目ではない。四度でもない。もう少し多い。数えることをやめた回数。日課になりつつある、というのはそういうことだろう。数えるのをやめた時点で、日課に近い。"}, {"id": "ch03-s05-p005", "type": "text", "text": "真鍮の取っ手を引いた。蝶番が鳴った。"}, {"id": "ch03-s05-p006", "type": "text", "text": "一階の受付で軽く頭を下げた。受付の女性は何も言わず、視線だけで応じた。最初の数回は「鐘守補佐の方ですね」と確認が入ったが、今日はなかった。顔を覚えられている。"}, {"id": "ch03-s05-p007", "type": "text", "text": "階段を上がった。二階の書架の間を抜ける。2-A、2-B、2-C。残響灯の青白い光が通路を照らす。奥へ。"}, {"id": "ch03-s05-p008", "type": "text", "text": "記録室の扉が、十センチほど開いていた。"}, {"id": "ch03-s05-p009", "type": "text", "text": "かりかり。"}, {"id": "ch03-s05-p010", "type": "text", "text": "この音は変わらない。毎回同じ場所で、同じ間隔の音が聞こえる。扉の前に立つと音が止まる、ということも——最近はなくなった。最初の頃、篠宮さんは俺の気配で書く手を止めていた。今は止まらない。扉の隙間から中に入っても、ペンの音が途切れない。"}, {"id": "ch03-s05-p011", "type": "text", "text": "俺が来ることを、前提にしている。"}, {"id": "ch03-s05-p012", "type": "text", "text": "扉を開けた。音を立てずに。この扉の蝶番は左側を持ち上げるようにすると鳴らない。三回目に気づいた。"}, {"id": "ch03-s05-p013", "type": "text", "text": "「朝霧さん」"}, {"id": "ch03-s05-p014", "type": "text", "text": "篠宮さんが顔を上げずに言った。声だけ。ペンは動いたまま。"}, {"id": "ch03-s05-p015", "type": "text", "text": "「こんにちは」"}, {"id": "ch03-s05-p016", "type": "text", "text": "木箱に座った。いつもの木箱。記録室に入って左側、机の角に近い位置。最初は篠宮さんが棚の横から引き出してきた木箱だった。今は定位置になっている。朝来ると木箱が机の前に出ている。篠宮さんが先に出しておいているのか、最初から戻さなくなったのか。どちらかは聞いていない。"}, {"id": "ch03-s05-p017", "type": "text", "text": "座面の高さにも体が慣れた。椅子より低い。腰の角度が少し深い。机に手を置くと、肘がわずかに上がる。その角度で字を書くことに、手が適応している。"}, {"id": "ch03-s05-p018", "type": "text", "text": "机の上に、今日の分の下書きが置かれていた。"}, {"id": "ch03-s05-p019", "type": "text", "text": "篠宮さんの字。小さくて正確。清書用紙とペンがその横に並べてある。インク壺の位置も決まっている。俺の木箱の前、机の右寄り。篠宮さんのインク壺は左寄り。二人分の道具が、机の上で領域を分けている。誰が決めたわけでもなく、数日の作業の中で自然に定まった配置。"}, {"id": "ch03-s05-p020", "type": "text", "text": "ペンを取った。インクをつけた。"}, {"id": "ch03-s05-p021", "type": "text", "text": "かりかり。"}, {"id": "ch03-s05-p022", "type": "text", "text": "二つのペンの音が記録室に落ちた。"}, {"id": "ch03-s05-p023", "type": "text", "text": "窓から夕方の光が差し込んでいた。西向きの小さな窓。夕日が低い位置から入り込んで、机の端を橙色に染めている。俺の手元は橙の光の中にあり、篠宮さんの手元は光の境目にあった。ペンを持つ指の先だけが橙に触れていて、手の甲から先は影の中にある。"}, {"id": "ch03-s05-p024", "type": "text", "text": "清書を進めた。"}, {"id": "ch03-s05-p025", "type": "text", "text": "下書きの束は五枚。消滅者の記録。名前、年齢、最終確認日、場所、備考。一枚目から順に転記していく。今日の分は外円区南部の記録が中心だった。漁村の名前が並んでいる。同じ日付が続く行が何組かあった。同じ日に、同じ場所で、複数の人が消えている。"}, {"id": "ch03-s05-p026", "type": "text", "text": "三枚目の下書きに差しかかった時、リストの形式が変わった。"}, {"id": "ch03-s05-p027", "type": "text", "text": "人名ではなかった。消滅者リストの中に、別の種類の項目が挟まっていた。人名と年齢の列の代わりに、短い記述が並んでいる。"}, {"id": "ch03-s05-p028", "type": "text", "text": "「出身不明。縁際第七監視区域にて発見。推定年齢14〜16。身元照合不一致。管理番号のみ付与」"}, {"id": "ch03-s05-p029", "type": "text", "text": "出身不明。"}, {"id": "ch03-s05-p030", "type": "text", "text": "ペンを止めた。"}, {"id": "ch03-s05-p031", "type": "text", "text": "その二行下にも同じ記載があった。"}, {"id": "ch03-s05-p032", "type": "text", "text": "「出身不明。外円区東端にて保護。推定年齢30前後。所持品なし。本人の申告する出身地は蝕域消滅済。照合不能」"}, {"id": "ch03-s05-p033", "type": "text", "text": "出身地が、蝕域に消えている。消えた場所から来た人間は、出身を証明できない。場所そのものがないのだから、記録と照合する先がない。"}, {"id": "ch03-s05-p034", "type": "text", "text": "「こういう人もいるんですね」"}, {"id": "ch03-s05-p035", "type": "text", "text": "声に出ていた。"}, {"id": "ch03-s05-p036", "type": "text", "text": "篠宮さんのペンが止まった。"}, {"id": "ch03-s05-p037", "type": "text", "text": "顔を上げた。墨色の瞳が俺を見ている。俺の手元の下書き——三枚目の記述に視線が移った。何を見ているか確認して、視線が戻った。"}, {"id": "ch03-s05-p038", "type": "text", "text": "「出身地が蝕域に消滅した場合、記録を照合できないため『出身不明』となります」"}, {"id": "ch03-s05-p039", "type": "text", "text": "声は平坦だった。いつもの篠宮さんの説明の口調。事実を過不足なく伝える声。"}, {"id": "ch03-s05-p040", "type": "text", "text": "「中央記録館の台帳に出身地の情報があっても、その地名が現存しなければ照合が成立しません。蝕域に消された町や島の住民が、後になって別の場所で見つかった場合……出身を証明する手段がなくなります」"}, {"id": "ch03-s05-p041", "type": "text", "text": "篠宮さんのペンが机の上に置かれた。指先がペン軸の上で止まっている。"}, {"id": "ch03-s05-p042", "type": "text", "text": "「記録上は、その人がどこから来たのか、わからない状態になります」"}, {"id": "ch03-s05-p043", "type": "text", "text": "どこから来たのか、わからない。"}, {"id": "ch03-s05-p044", "type": "text", "text": "窓の光が少し傾いた。机の上の橙色の帯が、数センチ移動していた。篠宮さんの指先が光の中に入った。"}, {"id": "ch03-s05-p045", "type": "text", "text": "俺は下書きの「出身不明」の文字を見ていた。"}, {"id": "ch03-s05-p046", "type": "text", "text": "二年前。外円区の縁際で発見された。それ以前の記録は何もない。名前も、住所も、家族構成も。「朝霧蓮」は俺がつけた名前だ。中央記録館の台帳に俺に対応する行があったとしても、出身地の欄は——空白だろう。照合する先がない。"}, {"id": "ch03-s05-p047", "type": "text", "text": "場所が消えたのか、最初からなかったのか。どちらなのかすら、わからない。"}, {"id": "ch03-s05-p048", "type": "text", "text": "このリストの「出身不明」の人々と、俺の間に線を引けるのかどうか。引けるかもしれない。引けないかもしれない。確かめる方法がない。"}, {"id": "ch03-s05-p049", "type": "text", "text": "篠宮さんのペンの音は止まったままだった。"}, {"id": "ch03-s05-p050", "type": "text", "text": "記録室が静かだった。二つのペンの音がない時、この部屋はこんなに静かになる。窓の外から微かに風の音が聞こえる。書架の木が軋む音。それだけ。"}, {"id": "ch03-s05-p051", "type": "text", "text": "「朝霧さんも……」"}, {"id": "ch03-s05-p052", "type": "text", "text": "篠宮さんが言った。"}, {"id": "ch03-s05-p053", "type": "text", "text": "間があった。声の始まりと、その先の言葉の間に、二秒ほどの隙間があった。篠宮さんの話し方はいつも句読点の後に正確な間を置く。今の間は、句読点の間ではなかった。言葉を選んでいる間だった。"}, {"id": "ch03-s05-p054", "type": "text", "text": "「出身は、不明なのですか」"}, {"id": "ch03-s05-p055", "type": "text", "text": "声が小さかった。いつもの篠宮さんの音量——記録室で聞き取れる最低限の音量——よりもさらに小さかった。壁に届かない声。俺と篠宮さんの間の空気だけを振動させる音量。"}, {"id": "ch03-s05-p056", "type": "text", "text": "篠宮さんは俺の出自を知らないはずだった。鐘守補佐として着任したことは知っている。名前は記録した。けれど、俺がどこから来たのか、それ以前に何をしていたのか、記憶があるのかないのか——そこまでは聞いていない。今まで一度も。"}, {"id": "ch03-s05-p057", "type": "text", "text": "昼に天城さんに話したばかりだった。「覚えていない」と。「二年前に縁際で見つかった」と。今日二度目の告白になる。"}, {"id": "ch03-s05-p058", "type": "text", "text": "頷いた。"}, {"id": "ch03-s05-p059", "type": "text", "text": "「二年前に、外円区の縁際で見つかりました。それ以前のことは覚えていません」"}, {"id": "ch03-s05-p060", "type": "text", "text": "篠宮さんの瞬きが止まった。"}, {"id": "ch03-s05-p061", "type": "text", "text": "何度も見た反応だった。初めて記録室に来た時。手伝いを申し出た時。明日も来ていいかと聞いた時。そのたびに、篠宮さんの瞬きは止まった。今回も同じ——いや、同じではなかった。止まっている時間が長い。三秒。四秒。墨色の瞳が動かない。顔のどの筋肉も動いていない。"}, {"id": "ch03-s05-p062", "type": "text", "text": "けれど、唇の端に変化があった。"}, {"id": "ch03-s05-p063", "type": "text", "text": "かすかに——本当にかすかに、内側に引かれていた。唇を噛んでいるのではない。力が入っているのでもない。ただ、唇の端の線が、ほんの少しだけ深くなっていた。何かを飲み込んだ後の、口元。"}, {"id": "ch03-s05-p064", "type": "text", "text": "窓の光がまた動いた。橙が濃くなっている。赤みが混じり始めていた。夕日が沈んでいく途中の色。机の上の清書用紙が赤橙に染まっている。"}, {"id": "ch03-s05-p065", "type": "text", "text": "「……でしたら」"}, {"id": "ch03-s05-p066", "type": "text", "text": "篠宮さんの声が出た。"}, {"id": "ch03-s05-p067", "type": "text", "text": "低かった。いつもの平坦な声とは、周波数が違った。高さが半音ほど下がっている。それだけの変化だが、篠宮さんの声でそれが起きるのは——初めて聞いた。"}, {"id": "ch03-s05-p068", "type": "text", "text": "「いつか、記録が見つかるかもしれません」"}, {"id": "ch03-s05-p069", "type": "text", "text": "間。"}, {"id": "ch03-s05-p070", "type": "text", "text": "「私は、諦めません」"}, {"id": "ch03-s05-p071", "type": "text", "text": "語尾に力があった。"}, {"id": "ch03-s05-p072", "type": "text", "text": "篠宮さんの話し方は、どの語尾も同じ力で終わる。「です」も「ます」も「ません」も、音量も力も均一に処理される。それが篠宮さんの声の特徴だった。"}, {"id": "ch03-s05-p073", "type": "text", "text": "今の「諦めません」は違った。「ません」の「ん」で、声が落ちなかった。通常なら語尾は自然に下降する。この「ん」は下降しなかった。水平のまま終わった。わずかな力が、最後の音を持ち上げていた。"}, {"id": "ch03-s05-p074", "type": "text", "text": "記録係としての発言ではなかった。"}, {"id": "ch03-s05-p075", "type": "text", "text": "消滅者を記録し、消滅した島を記録し、出身不明の人々を記録する——それは篠宮さんの使命だ。23冊のメモ帳が証明している。けれど、この「諦めません」は、リストの中の一行に向けた言葉ではなかった。"}, {"id": "ch03-s05-p076", "type": "text", "text": "俺に向けていた。"}, {"id": "ch03-s05-p077", "type": "text", "text": "朝霧蓮という、出身不明の、記憶のない人間に対して、篠宮雫が個人として何かを約束している。記録が見つかるかもしれない。私は諦めない。その言葉の宛先が、台帳の空白欄ではなく、今この机の向かいに座っている人間に向いている。"}, {"id": "ch03-s05-p078", "type": "text", "text": "窓の外で、鳥が一羽鳴いた。遠い声だった。"}, {"id": "ch03-s05-p079", "type": "text", "text": "篠宮さんは視線を手元に戻していた。ペンを取り直し、メモ帳を開いた。けれど、ペン先はまだ紙に触れていなかった。持っているだけ。書く体勢だけを整えて、書き始めていない。"}, {"id": "ch03-s05-p080", "type": "text", "text": "俺は「ありがとう」を言おうとしていた。"}, {"id": "ch03-s05-p081", "type": "text", "text": "口の中に言葉があった。舌の上に、音の形がある。「あ」「り」「が」「と」「う」。五つの音。それを外に出すだけだった。"}, {"id": "ch03-s05-p082", "type": "text", "text": "出なかった。"}, {"id": "ch03-s05-p083", "type": "text", "text": "遅れた。"}, {"id": "ch03-s05-p084", "type": "text", "text": "音の形はあるのに、喉から空気が出るまでに、何かが挟まった。感情を込めようとした。込めたかった。篠宮さんの「諦めません」に対して、形式的な礼ではなく、何か——温度のある応答を返したかった。"}, {"id": "ch03-s05-p085", "type": "text", "text": "けれど、温度の込め方がわからなかった。「ありがとう」をどう発音すれば感謝になるのか。音量を変えるのか。速度を変えるのか。どこに力を入れるのか。わからなかった。"}, {"id": "ch03-s05-p086", "type": "text", "text": "三秒、遅れた。たぶん、三秒。"}, {"id": "ch03-s05-p087", "type": "text", "text": "「——ありがとう」"}, {"id": "ch03-s05-p088", "type": "text", "text": "出た。"}, {"id": "ch03-s05-p089", "type": "text", "text": "出た時の声は、自分の耳には普段と同じに聞こえた。音量も速度も変わっていない。込めようとしたものが込められたのか、ただの「ありがとう」になったのか、判定できなかった。"}, {"id": "ch03-s05-p090", "type": "text", "text": "篠宮さんのペンが動いた。紙の上をペン先が走る音。かりかり。再開。"}, {"id": "ch03-s05-p091", "type": "text", "text": "俺も清書に戻った。三枚目の下書きの続き。「出身不明」の行を、清書用紙に転記する。自分と同じかもしれない境遇の人の記録を、自分の手で書き写している。"}, {"id": "ch03-s05-p092", "type": "text", "text": "窓の光が赤くなっていた。橙から赤へ。夕日が沈みかけている。机の上の紙が赤く染まり、インクの黒い文字が浮き上がって見えた。"}, {"id": "ch03-s05-p093", "type": "text", "text": "二つのペンの音が記録室を満たしている。"}, {"id": "ch03-s05-p094", "type": "text", "text": "篠宮さんのペンの音は、さっきまでと変わっていないように聞こえた。均一な間隔。硬すぎない筆圧。いつもの音。けれど、俺の耳が正確かどうかは自信がなかった。さっきの「諦めません」の後で、俺の耳は——普段通りに聴けているのか。"}, {"id": "ch03-s05-p095", "type": "text", "text": "五枚目の清書を終えた頃、窓の光が暗くなり始めていた。赤が褪せて、紫がかった灰色に変わっていく。机の上の橙の帯が消えた。残響灯の青白い光だけが、紙の上を照らしている。"}, {"id": "ch03-s05-p096", "type": "text", "text": "十七時半の鐘が鳴った。"}, {"id": "ch03-s05-p097", "type": "text", "text": "遠い鐘の音が図書館の壁を通り抜けて、記録室に届いた。残響が長く伸びる。"}, {"id": "ch03-s05-p098", "type": "text", "text": "篠宮さんがペンを置いた。"}, {"id": "ch03-s05-p099", "type": "text", "text": "「閉館です」"}, {"id": "ch03-s05-p100", "type": "text", "text": "俺もペンを置いた。清書した用紙を揃え、篠宮さんに渡した。篠宮さんの指が用紙の端に触れた時、指先が一瞬だけ止まった。俺の字を見ている。一行ずつ。確認している。"}, {"id": "ch03-s05-p101", "type": "text", "text": "用紙が引き出しに収められた。メモ帳が腰のポーチに入った。首の鍵が揺れた。"}, {"id": "ch03-s05-p102", "type": "text", "text": "立ち上がった。木箱から腰を上げる。この木箱を元の場所に戻すかどうか、最初の頃は迷った。今は戻さない。明日もここに座る。"}, {"id": "ch03-s05-p103", "type": "text", "text": "「では、また明日」"}, {"id": "ch03-s05-p104", "type": "text", "text": "篠宮さんが頷いた。顎が一センチほど下がって、戻る。いつもと同じ頷き。"}, {"id": "ch03-s05-p105", "type": "text", "text": "記録室を出た。書架の間を歩く。階段を降りる。受付の前を通り、図書館の扉を開けた。"}, {"id": "ch03-s05-p106", "type": "text", "text": "外は夕暮れだった。空が紫と灰色の中間にある。西の端だけがまだ赤い。建物の影が長く伸びて、石畳の上に暗い帯を引いている。"}, {"id": "ch03-s05-p107", "type": "text", "text": "歩き始めた。"}, {"id": "ch03-s05-p108", "type": "text", "text": "「私は、諦めません」"}, {"id": "ch03-s05-p109", "type": "text", "text": "篠宮さんの声が、頭の中で繰り返された。あの低い声。語尾の力。下降しなかった「ん」の音。"}, {"id": "ch03-s05-p110", "type": "text", "text": "篠宮さんは記録する人だ。消えた人を記録し、消えた島を記録し、消えた記憶を記録する。それが篠宮さんのやっていることで、23冊のメモ帳はその証だった。"}, {"id": "ch03-s05-p111", "type": "text", "text": "「諦めません」は、その延長にあるのかもしれない。記録係として、出身不明の人間の記録を探すことを諦めない。記録の空白を埋めることが篠宮さんの仕事なのだから、俺の記録の空白も対象に含まれる。それだけのことかもしれない。"}, {"id": "ch03-s05-p112", "type": "text", "text": "かもしれない。"}, {"id": "ch03-s05-p113", "type": "text", "text": "ただ、篠宮さんの声のあの変化——半音低くなった声と、語尾の力——は、いつもの説明の声とは違っていた。島のリストを説明する時の声とも、閲覧机の場所を教える時の声とも。篠宮さんの声域の中で、あの音が鳴ったのは初めてだった。"}, {"id": "ch03-s05-p114", "type": "text", "text": "「ありがとう」が遅れた理由を、まだ考えていた。"}, {"id": "ch03-s05-p115", "type": "text", "text": "感情を込めたかった。込められたかどうかわからない。五つの音を喉から出すだけのことに、三秒を要した。その三秒の中で何が起きていたのか。蛇口と水の間の詰まり。感情はあった。たぶん。あったのに形にならなかった。形にしようとして、形がわからなかった。"}, {"id": "ch03-s05-p116", "type": "text", "text": "鐘鋳塔が見えてきた。石の外壁。残響紋。管理室の小窓。"}, {"id": "ch03-s05-p117", "type": "text", "text": "今朝からの一日を振り返っていた。桜の下で天城さんが「忘れちゃいそうで怖い」と言い、記録室で篠宮さんが「諦めません」と言った。天城さんは忘却の途中にいて、忘れることを恐れている。篠宮さんは記録の側にいて、忘れられることに抗っている。"}, {"id": "ch03-s05-p118", "type": "text", "text": "俺は、その両方の間に立っている。忘却の先にいて、記録の中に自分の空白を持っている。"}, {"id": "ch03-s05-p119", "type": "text", "text": "篠宮さんがその空白を埋めると言った。個人的な約束のように聞こえた。"}, {"id": "ch03-s05-p120", "type": "text", "text": "管理室の扉を開けた。鍵を回して中に入った。机の上に点検記録帳を広げた。"}, {"id": "ch03-s05-p121", "type": "text", "text": "椅子に座った。ペンを取った。"}, {"id": "ch03-s05-p122", "type": "text", "text": "今日の点検記録を書き始めた。数値を記入する。第三系統の出力。第五系統の温度。歯車回転数。"}, {"id": "ch03-s05-p123", "type": "text", "text": "手が動いている間、耳が記録室のペンの音を探していた。ここでは聞こえない。わかっている。管理室と図書館は離れている。音が届くはずがない。"}, {"id": "ch03-s05-p124", "type": "text", "text": "それでも探していた。二回目だった。前にもこの管理室で、同じことが起きた。図書館を出た後、耳がペンの音を探す。聞こえるはずのない音を。"}, {"id": "ch03-s05-p125", "type": "text", "text": "覚えておく。"}, {"id": "ch03-s05-p126", "type": "text", "text": "篠宮さんの「諦めません」と、俺の「ありがとう」の三秒の遅れを。"}]}, {"chapter": 4, "chapterTitle": "残響祭の灯り", "scene": 1, "sceneTitle": "祭りの朝", "wordCount": "約4,100字", "paragraphs": [{"id": "ch04-s01-p001", "type": "text", "text": "中庭が、違う場所になっていた。"}, {"id": "ch04-s01-p002", "type": "text", "text": "昨日まで石畳と芝生しかなかった空間に、木の柱が立ち、布が張られ、色とりどりの提灯が吊るされている。朝の九時。設営は夜のうちに終わっていたらしい。俺が管理室で計器の夜間値を記録していた時間に、中庭はこうなっていた。"}, {"id": "ch04-s01-p003", "type": "text", "text": "出店が左右に並んでいる。まだ開いていないものもある。火を入れたばかりの炭が、白い煙を細く上げている。油と炭の匂い。木材の匂い。花の匂い。匂いの種類が多すぎて、分けられない。"}, {"id": "ch04-s01-p004", "type": "text", "text": "人も多い。"}, {"id": "ch04-s01-p005", "type": "text", "text": "聖鐘学院の制服が行き交い、制服でない服装もある。中円区の住民だろう。子供の声が高い位置から落ちてきて、低い位置で笑い声が返る。普段の学院は人の動きに規則性がある。授業の開始と終わりで人が動き、昼食の時間に食堂へ流れ、夕方に散る。今日はその規則が崩れている。人がどこからでも湧き、どこへでも散らばる。"}, {"id": "ch04-s01-p006", "type": "text", "text": "俺は中庭の端にいた。"}, {"id": "ch04-s01-p007", "type": "text", "text": "鐘守補佐として、残響祭の音響に関する連絡待機が業務だった。拡声器の不具合があれば出向く。講堂の音響盤に問題があれば対処する。それまでは待機。やるべきことが「待つ」である時間は、居場所に困る。"}, {"id": "ch04-s01-p008", "type": "text", "text": "人の流れを見ていた。流れの中にいるのに、流れに乗っていない。水に浸かっているのに流されない石。そういう感覚は監視哨にいた頃と同じだった。あの頃は霧の中で何時間も動かず、周囲の変化だけを目で追っていた。今は霧ではなく人間だが、やっていることの構造は変わらない。観察している。混ざれていない。"}, {"id": "ch04-s01-p009", "type": "text", "text": "残響桜が目に入った。"}, {"id": "ch04-s01-p010", "type": "text", "text": "中庭の中央に立つ大木。一ヶ月前に薄紫の花をつけていた枝は、今は緑に覆われている。葉桜。ところどころ、散り残った花弁がまばらに見えた。桜の幹に、金色の布が巻かれていた。残響祭の飾りだろう。枝の間に小さな残響灯が吊るされている。まだ点いていない。夜になったら点くのだろう。"}, {"id": "ch04-s01-p011", "type": "text", "text": "「蓮くーん！」"}, {"id": "ch04-s01-p012", "type": "text", "text": "声。左後方。距離は十メートルほど。"}, {"id": "ch04-s01-p013", "type": "text", "text": "振り向く前に、足音で誰か判った。大股で、踵から地面を踏む音。この足音を聞いた回数は、もう数えていない。"}, {"id": "ch04-s01-p014", "type": "text", "text": "天城さんが走ってきた。"}, {"id": "ch04-s01-p015", "type": "text", "text": "ポニーテールが左右に揺れている。制服のブラウスの袖はいつも通りまくってあり、胸ポケットに花が挿してある。今日の花は黄色い小花だった。普段は白や薄紫が多い。祭りだから変えたのかもしれない。"}, {"id": "ch04-s01-p016", "type": "text", "text": "「もう、待ってたのに全然来ないから探しちゃった。どこにいるの、こんな端っこで」"}, {"id": "ch04-s01-p017", "type": "text", "text": "「待機場所がここなので」"}, {"id": "ch04-s01-p018", "type": "text", "text": "「待機って何、仕事？ 音響の？」"}, {"id": "ch04-s01-p019", "type": "text", "text": "「はい。不具合があった場合に——」"}, {"id": "ch04-s01-p020", "type": "text", "text": "「蓮くん」"}, {"id": "ch04-s01-p021", "type": "text", "text": "天城さんの声が平坦になった。目が据わっている。"}, {"id": "ch04-s01-p022", "type": "text", "text": "「敬語」"}, {"id": "ch04-s01-p023", "type": "text", "text": "「……すみません」"}, {"id": "ch04-s01-p024", "type": "text", "text": "「今のも敬語」"}, {"id": "ch04-s01-p025", "type": "text", "text": "その通りだった。天城さんの前で敬語を使うと指摘される。何度目かわからない。予測できるのに直らない。口が勝手に丁寧語を選ぶ。天城さんの前でだけ、なぜかそうなる。理由は不明のままだった。"}, {"id": "ch04-s01-p026", "type": "text", "text": "「不具合があったら行く。それまでは待機」"}, {"id": "ch04-s01-p027", "type": "text", "text": "「よし。じゃあ今は暇なんだね」"}, {"id": "ch04-s01-p028", "type": "text", "text": "暇かどうかの判定は正確ではない。待機は業務だ。ただ、天城さんの質問に正確な定義を返すと会話が長くなることは学習済みだった。"}, {"id": "ch04-s01-p029", "type": "text", "text": "「まあ、そうなる」"}, {"id": "ch04-s01-p030", "type": "text", "text": "「じゃあ、一緒に回ろう！」"}, {"id": "ch04-s01-p031", "type": "text", "text": "天城さんの手が俺の手首に触れた。左手首。ブレスレットの上。指が手首を掴むのではなく、手首の横に添えられる。引く力は弱い。けれど方向がある。天城さんの体が先に動いていて、俺の手首に添えた指がその動きを伝えている。"}, {"id": "ch04-s01-p032", "type": "text", "text": "「行こ行こ！ まず灯籠通りのほう。焼き菓子の出店があるんだよ、あっちのクラスの子たちが出してるやつ」"}, {"id": "ch04-s01-p033", "type": "text", "text": "断る理由がなかった。連絡が来れば対応する。来るまでは待機。待機の場所が中庭の端から灯籠通りに移動しても、業務に支障はない。"}, {"id": "ch04-s01-p034", "type": "text", "text": "歩き出した。天城さんの手は、三歩目で離れた。"}, {"id": "ch04-s01-p035", "type": "text", "text": "灯籠通りに入った。石畳の通りの両側に、普段は灯籠だけが並んでいる道に、布張りの屋台が連なっている。焼き菓子、串焼き、甘い飴、果実の砂糖漬け。それぞれの屋台から違う匂いがする。通りの上に色とりどりの三角旗が渡してあり、朝の風に揺れている。"}, {"id": "ch04-s01-p036", "type": "text", "text": "天城さんの歩く速度が少し上がった。"}, {"id": "ch04-s01-p037", "type": "text", "text": "「あ、あった！ ほら蓮くん、これこれ！」"}, {"id": "ch04-s01-p038", "type": "text", "text": "焼き菓子の屋台の前で立ち止まった。湯気が上がっている。丸い形の菓子が鉄板の上に並んでいた。きつね色の表面。中から甘い匂い。餡が入っている、と看板に書いてあった。"}, {"id": "ch04-s01-p039", "type": "text", "text": "天城さんが二つ買った。俺の分と、自分の分。財布は天城さんのものだった。払うと言う前に支払いが終わっていた。"}, {"id": "ch04-s01-p040", "type": "text", "text": "「はい、蓮くんの」"}, {"id": "ch04-s01-p041", "type": "text", "text": "紙に包まれた焼き菓子が手の中に来た。温かい。紙越しに、指の腹に熱が届く。"}, {"id": "ch04-s01-p042", "type": "text", "text": "天城さんが自分の分を一口噛んだ。目が細くなった。咀嚼しながら、「ん——」と声を出す。それから俺を見た。"}, {"id": "ch04-s01-p043", "type": "text", "text": "「どう？ おいしい？」"}, {"id": "ch04-s01-p044", "type": "text", "text": "まだ食べていなかった。天城さんの視線が俺の手元にある焼き菓子と、俺の顔を交互に見ている。催促。"}, {"id": "ch04-s01-p045", "type": "text", "text": "噛んだ。"}, {"id": "ch04-s01-p046", "type": "text", "text": "外側が薄く硬い。歯が通ると中が柔らかい。餡の甘さが舌に広がった。小麦の香りと、甘さと、焼けた表面のわずかな苦み。食堂の焼き魚とも、喫茶のコーヒーとも、補佐官舎の味噌汁とも、桜の下の弁当とも違う。知らない味だった。"}, {"id": "ch04-s01-p047", "type": "text", "text": "口の中で味を追いかけた。"}, {"id": "ch04-s01-p048", "type": "text", "text": "甘い。それは判る。温かい。それも判る。おいしいかどうか。"}, {"id": "ch04-s01-p049", "type": "text", "text": "天城さんが俺の顔を覗き込んでいた。はしばみ色の瞳が、朝の日差しの中で金色に近く見えた。首を少し傾けている。"}, {"id": "ch04-s01-p050", "type": "text", "text": "「おいしい……」"}, {"id": "ch04-s01-p051", "type": "text", "text": "出た。間があった。"}, {"id": "ch04-s01-p052", "type": "text", "text": "新しい味だった。舌の上で名前を探している時間があった。コーヒーの時と似ている。知らない味が来ると、体が判定を保留する。保留している間に「おいしい」の音が先に口から出る。体が覚えた手順で出てくる。手順が先で、実感が追いかけている。"}, {"id": "ch04-s01-p053", "type": "text", "text": "天城さんの表情が変わった。"}, {"id": "ch04-s01-p054", "type": "text", "text": "「間、あったね」"}, {"id": "ch04-s01-p055", "type": "text", "text": "見抜かれていた。"}, {"id": "ch04-s01-p056", "type": "text", "text": "天城さんの口元が笑っていた。けれど責めている声ではなかった。確認している声だった。毎回、俺の「おいしい」を聞いて、その手前の時間を測っている。間があったか、なかったか。天城さんはそれを見ている。"}, {"id": "ch04-s01-p057", "type": "text", "text": "「新しい味だった」"}, {"id": "ch04-s01-p058", "type": "text", "text": "「うん、知ってる。蓮くん、初めての味だと一回止まるんだよね」"}, {"id": "ch04-s01-p059", "type": "text", "text": "知っている。天城さんは、俺の反応のパターンを。"}, {"id": "ch04-s01-p060", "type": "text", "text": "「大丈夫。いっぱい食べれば慣れるから。ほら、次行こう！」"}, {"id": "ch04-s01-p061", "type": "text", "text": "天城さんの足が動いた。背中を追う。ポニーテールの先が肩甲骨の間で跳ねている。黄色のヘアゴム。少し色褪せた黄色。"}, {"id": "ch04-s01-p062", "type": "text", "text": "灯籠通りを歩いた。出店を一軒ずつ覗いていく。天城さんは各屋台の前で足を止め、商品を見て、店番の生徒と二言三言交わした。「がんばってね」と声をかけ、手を振り、次の屋台に向かう。どの屋台でも天城さんの声は同じ温度だった。明るくて、真っ直ぐで、相手の方を向いている。"}, {"id": "ch04-s01-p063", "type": "text", "text": "串焼きの屋台の前で天城さんが立ち止まった。"}, {"id": "ch04-s01-p064", "type": "text", "text": "「蓮くん、これも食べよ」"}, {"id": "ch04-s01-p065", "type": "text", "text": "鶏肉の串焼きだった。塩味。炭火の香りが立っている。天城さんが二本買い、一本を渡してきた。"}, {"id": "ch04-s01-p066", "type": "text", "text": "噛んだ。肉汁が口の中に広がった。塩と、脂と、炭の匂い。"}, {"id": "ch04-s01-p067", "type": "text", "text": "「おいしい？」"}, {"id": "ch04-s01-p068", "type": "text", "text": "「おいしい」"}, {"id": "ch04-s01-p069", "type": "text", "text": "間がなかった。"}, {"id": "ch04-s01-p070", "type": "text", "text": "串焼きは知っている味だった。正確には、食堂で似た味を食べたことがある。鶏肉と塩。組み合わせが既知だから、体が迷わなかった。"}, {"id": "ch04-s01-p071", "type": "text", "text": "天城さんが笑った。顔全体で。目が弧を描き、口が開いて歯が見える。"}, {"id": "ch04-s01-p072", "type": "text", "text": "「今の、間なかったね」"}, {"id": "ch04-s01-p073", "type": "text", "text": "声が弾んでいた。"}, {"id": "ch04-s01-p074", "type": "text", "text": "「食べたことある味だと速いんだ。面白いね、蓮くん」"}, {"id": "ch04-s01-p075", "type": "text", "text": "面白い。俺の反応が、天城さんにとっては観察対象になっている。俺が人を観察するように、天城さんも俺を観察している。ただし、天城さんの観察には楽しさが混じっている。俺の観察にはそれがない。あるのかもしれないが、まだ特定できない。"}, {"id": "ch04-s01-p076", "type": "text", "text": "教室棟の前を通りかかった時、生徒たちの集団が走り抜けていった。模擬店の準備だろう。段ボール箱を抱えた生徒の横を避けて、天城さんが俺の袖を引いた。"}, {"id": "ch04-s01-p077", "type": "text", "text": "「危ないよ、こっち」"}, {"id": "ch04-s01-p078", "type": "text", "text": "避けた先は中庭の芝生だった。残響桜の根元のベンチ。天城さんが座り、隣を手で叩いた。座れ、という意味。"}, {"id": "ch04-s01-p079", "type": "text", "text": "座った。"}, {"id": "ch04-s01-p080", "type": "text", "text": "ベンチの高さは木箱より高い。腰の角度が記録室の木箱とは違う。背中が少しだけ楽な位置。"}, {"id": "ch04-s01-p081", "type": "text", "text": "残響桜を見上げた。葉桜の緑。枝に吊るされた小さな残響灯がぶら下がっている。風が吹くと、灯の硝子が互いに触れて、かちかちと音を出した。"}, {"id": "ch04-s01-p082", "type": "text", "text": "「ねえ蓮くん」"}, {"id": "ch04-s01-p083", "type": "text", "text": "天城さんが隣で言った。串焼きの竹串をくるくると指で回している。"}, {"id": "ch04-s01-p084", "type": "text", "text": "「楽しい？」"}, {"id": "ch04-s01-p085", "type": "text", "text": "二度目の問い。前回は「楽しかった？」だった。過去形。喫茶「残響」の帰りに聞かれた。あの時は「悪くなかった」と答えた。今度は現在進行形。今、この時間を。"}, {"id": "ch04-s01-p086", "type": "text", "text": "焼き菓子の甘い後味が、まだ舌の奥に残っていた。串焼きの塩味はもう薄れている。灯籠通りの三角旗の色。屋台の湯気。天城さんが屋台の店番に「がんばってね」と声をかけた時の、相手の顔のほころび。走り抜けていった生徒たちの靴音。"}, {"id": "ch04-s01-p087", "type": "text", "text": "賑やかだった。多くの人が笑っている。"}, {"id": "ch04-s01-p088", "type": "text", "text": "俺も笑うべきなのだろうか。"}, {"id": "ch04-s01-p089", "type": "text", "text": "答えが出なかった。「楽しい」と言えるかどうか。嫌ではない。それは確かだった。嫌ではない、は「楽しい」とイコールではない。間に何かがある。焼き菓子の「おいしい」の前に入った間と、たぶん同じもの。"}, {"id": "ch04-s01-p090", "type": "text", "text": "「悪くない」"}, {"id": "ch04-s01-p091", "type": "text", "text": "天城さんは笑わなかった。予想通りの答えだったのか、頷いてから小さく息を吐いた。"}, {"id": "ch04-s01-p092", "type": "text", "text": "「うん。知ってた。蓮くん、まだそこだよね」"}, {"id": "ch04-s01-p093", "type": "text", "text": "「そこ」がどこを指すのか、正確にはわからなかった。ただ、天城さんの声には落胆がなかった。観測結果を確認した声。距離を測っている声。今日はここ。まだここ。次はもう少し先に行けるかもしれないし、行けないかもしれない。そのどちらでも、天城さんは同じ声で確認するのだろう。"}, {"id": "ch04-s01-p094", "type": "text", "text": "「いつか言ってもらうからね。楽しいって」"}, {"id": "ch04-s01-p095", "type": "text", "text": "前にも聞いた台詞だった。残響祭の準備の日、中庭のベンチで。あの時は「楽しみ」だった。今度は「楽しい」。天城さんは一語ずつ、順番に、俺の語彙を上げようとしている。"}, {"id": "ch04-s01-p096", "type": "text", "text": "残響桜の枝が揺れた。葉の隙間から朝の光が落ちて、ベンチの上に白い斑点を作った。天城さんの髪にも光の点が散った。赤みがかった茶色の髪に、白い光。ポニーテールの先端が肩の上で揺れている。"}, {"id": "ch04-s01-p097", "type": "text", "text": "鳩尾の下のあたりが、ほんの少し緩んでいた。"}, {"id": "ch04-s01-p098", "type": "text", "text": "いつから緩んでいたのか。灯籠通りを歩き始めた時か。焼き菓子を食べた時か。串焼きの「おいしい」が間なく出た時か。特定できない。気づいた時にはもう、その状態だった。"}, {"id": "ch04-s01-p099", "type": "text", "text": "天城さんが立ち上がった。"}, {"id": "ch04-s01-p100", "type": "text", "text": "「よし。次、講堂のほう見に行こう。ちーちゃんの公演の準備がどうなってるか気になるし」"}, {"id": "ch04-s01-p101", "type": "text", "text": "手が伸びてきた。今度は手首ではなく、袖の端を指先で摘んでいた。引く力は焼き菓子の時よりさらに弱い。けれど方向はある。"}, {"id": "ch04-s01-p102", "type": "text", "text": "立ち上がった。袖が指から離れた。"}, {"id": "ch04-s01-p103", "type": "text", "text": "天城さんの背中を追って歩き出す。中庭を横切る。生徒たちの間を縫って、講堂の方へ。天城さんが誰かに手を振った。振り返された。天城さんが笑った。"}, {"id": "ch04-s01-p104", "type": "text", "text": "人の間を歩いている。人の流れの中にいる。さっきまで俺は流れの外にいた。中庭の端で、石のように。今は流れの中にいる。天城さんの後ろについて歩いているだけだが、流れの外ではない。"}, {"id": "ch04-s01-p105", "type": "text", "text": "参加している、のかもしれない。"}, {"id": "ch04-s01-p106", "type": "text", "text": "天城さんが振り返った。"}, {"id": "ch04-s01-p107", "type": "text", "text": "「蓮くん、遅い！ ほら、こっちこっち」"}, {"id": "ch04-s01-p108", "type": "text", "text": "歩幅を少しだけ広げた。"}]}, {"chapter": 4, "chapterTitle": "残響祭の灯り", "scene": 2, "sceneTitle": "記録展示と静かな手", "wordCount": "約4,000字", "paragraphs": [{"id": "ch04-s02-p001", "type": "text", "text": "講堂の横で、天城さんが足を止めた。"}, {"id": "ch04-s02-p002", "type": "text", "text": "「あ、そうだ。蓮くん、図書館に雫ちゃんの展示があるんだよ」"}, {"id": "ch04-s02-p003", "type": "text", "text": "「展示」"}, {"id": "ch04-s02-p004", "type": "text", "text": "「うん。消えちゃった場所の記録を展示してるの。地図とか写真とか。行ってあげてよ、たぶん人少ないから」"}, {"id": "ch04-s02-p005", "type": "text", "text": "天城さんは笑っていたが、声にはいつもの弾みとは別のものが混じっていた。「人少ないから」の部分だけ、音量がほんの少し下がった。"}, {"id": "ch04-s02-p006", "type": "text", "text": "「行ってくる」"}, {"id": "ch04-s02-p007", "type": "text", "text": "「うん！ あたしはちーちゃんの準備の手伝いしてるから、また後でね！」"}, {"id": "ch04-s02-p008", "type": "text", "text": "手を振って、天城さんは講堂の中に消えた。ポニーテールの先端が扉の陰に吸い込まれるのが最後に見えた。"}, {"id": "ch04-s02-p009", "type": "text", "text": "中庭を横切った。"}, {"id": "ch04-s02-p010", "type": "text", "text": "祭りの音が背中から追いかけてくる。出店の呼び声。笑い声。足音の群れ。炭が爆ぜる音。それらが重なって一つの塊になっている。祭りの音。名前をつけるなら、そうなる。"}, {"id": "ch04-s02-p011", "type": "text", "text": "図書館の外壁が見えた。木の壁。煉瓦の基礎。緑青の雨樋。何度も見た景色だった。"}, {"id": "ch04-s02-p012", "type": "text", "text": "扉の前に立った時、背中の音が一段遠くなった。扉を引いた。蝶番が鳴った。"}, {"id": "ch04-s02-p013", "type": "text", "text": "中に入った瞬間、音が落ちた。"}, {"id": "ch04-s02-p014", "type": "text", "text": "祭りの喧騒が壁に遮断されて、残ったのは紙の匂いと蜜蝋の匂いと、静けさだった。足元が石畳から木の床に変わり、靴底から伝わる振動の質が変わった。硬いものの上を歩く感触から、わずかに沈む感触へ。空気の温度も違う。外は五月の日差しで温まっていたが、図書館の中は涼しかった。壁と天井の木材が熱を吸っているのだろう。"}, {"id": "ch04-s02-p015", "type": "text", "text": "受付の女性が視線だけで頷いた。声を出さなかった。"}, {"id": "ch04-s02-p016", "type": "text", "text": "一階の閲覧室は普段は机と椅子が並んでいる。今日は違っていた。"}, {"id": "ch04-s02-p017", "type": "text", "text": "机が壁際に寄せられ、椅子が片づけられている。その代わりに、木の衝立が三面立てられていて、衝立の表面に紙が貼られていた。写真。地図。文字の書かれた紙片。残響灯の光がそれらを青白く照らしている。"}, {"id": "ch04-s02-p018", "type": "text", "text": "衝立の手前に、小さな看板が立っていた。"}, {"id": "ch04-s02-p019", "type": "text", "text": "「消滅した場所の記録展示——忘れないために」"}, {"id": "ch04-s02-p020", "type": "text", "text": "篠宮さんの字だった。小さくて正確な字。清書用のペンで書かれている。インクの色は黒。行間が均等で、一文字ごとの大きさが揃っている。看板の右下に「聖鐘学院図書館 記録係 篠宮雫」と署名があった。"}, {"id": "ch04-s02-p021", "type": "text", "text": "閲覧室には俺以外、誰もいなかった。"}, {"id": "ch04-s02-p022", "type": "text", "text": "衝立の横に、篠宮さんが立っていた。"}, {"id": "ch04-s02-p023", "type": "text", "text": "左端の衝立の前。背筋を伸ばし、両手を前で組んでいる。腰のメモ帳。首の鍵。いつもの姿。ただし今日は図書館のエプロンの代わりに、制服だけだった。祭りの日だから、か。スカートの丈は膝丈。紺のハイソックス。規定通り。"}, {"id": "ch04-s02-p024", "type": "text", "text": "篠宮さんの瞬きが止まった。"}, {"id": "ch04-s02-p025", "type": "text", "text": "「朝霧さん」"}, {"id": "ch04-s02-p026", "type": "text", "text": "声は静かだった。いつもの音量。図書館で発する声として正確に調節された音量。しかし声の立ち上がりが——いつもより速かった。「あ」の音が口から出るまでの時間が、記録室で名前を呼ばれる時より短い。"}, {"id": "ch04-s02-p027", "type": "text", "text": "「こんにちは」"}, {"id": "ch04-s02-p028", "type": "text", "text": "頷かれた。顎が一センチほど下がって、戻る。いつもの頷き。"}, {"id": "ch04-s02-p029", "type": "text", "text": "展示に目を向けた。"}, {"id": "ch04-s02-p030", "type": "text", "text": "左端の衝立から見ていった。"}, {"id": "ch04-s02-p031", "type": "text", "text": "一枚目は地図だった。島の輪郭が丁寧に描かれている。海岸線、港、集落の位置、道。インクの線は細く、正確で、篠宮さんの字と同じ筆圧で引かれていた。地図の右下に「外円区南部 第七島嶼群 名称消失」と注記がある。名前が消えている。島はあった。島に名前があった。けれど名前が蝕域に消されて、今はもう誰も呼べない。"}, {"id": "ch04-s02-p032", "type": "text", "text": "地図の隣に、写真が一枚。"}, {"id": "ch04-s02-p033", "type": "text", "text": "白黒の写真だった。桟橋と小舟。桟橋の上に人影が小さく写っている。後ろに低い山が見える。写真の下にキャプションがあった。"}, {"id": "ch04-s02-p034", "type": "text", "text": "「消滅前の港風景。撮影日不明。記録室保管庫より」"}, {"id": "ch04-s02-p035", "type": "text", "text": "キャプションの字は篠宮さんの字だった。同じ字。同じインク。同じ間隔。"}, {"id": "ch04-s02-p036", "type": "text", "text": "二枚目の衝立に移った。"}, {"id": "ch04-s02-p037", "type": "text", "text": "消滅した集落の記録が並んでいた。写真が三枚。建物の写真、畑の写真、祭りらしい写真。どれも白黒か、色が褪せた写真だった。集落の名前がキャプションに書かれている。いくつかの名前には「現存せず」の付記があった。"}, {"id": "ch04-s02-p038", "type": "text", "text": "その下に、手書きの模写があった。古い地図の模写。港の形、建物の配置、井戸の位置まで描き込まれている。模写の端に「原本：中央記録館蔵 第43次蝕域調査記録附図」と書かれていた。原本がある場所の名前が記してあることの意味を、考えた。原本がまだあるということは、記録は残っている。記録が残っていても場所は消えた。"}, {"id": "ch04-s02-p039", "type": "text", "text": "三枚目の衝立の前で、足が止まった。"}, {"id": "ch04-s02-p040", "type": "text", "text": "消滅者のリストだった。"}, {"id": "ch04-s02-p041", "type": "text", "text": "名前が縦に並んでいる。名前、年齢、最終確認日、場所。一行ごとに一人の人間。行の間隔は均等で、字は丁寧に清書されている。"}, {"id": "ch04-s02-p042", "type": "text", "text": "見覚えがあった。"}, {"id": "ch04-s02-p043", "type": "text", "text": "字に見覚えがあった。"}, {"id": "ch04-s02-p044", "type": "text", "text": "篠宮さんの字ではなかった。リストの上半分は篠宮さんの字で——小さくて正確な、筆跡の震えのない清書体だった。下半分の字は違った。少し大きくて、少し角ばっていて、横画の入りが篠宮さんより強い。"}, {"id": "ch04-s02-p045", "type": "text", "text": "俺の字だった。"}, {"id": "ch04-s02-p046", "type": "text", "text": "記録室で清書した消滅者リスト。あの木箱に座って、篠宮さんの下書きを転記した字。インク壺の位置が右寄りで、肘がわずかに上がる角度で書いた字。それが、三枚目の衝立の下半分に貼られていた。"}, {"id": "ch04-s02-p047", "type": "text", "text": "篠宮さんを見た。"}, {"id": "ch04-s02-p048", "type": "text", "text": "篠宮さんは衝立の横に立ったまま、俺を見ていた。墨色の瞳が動かない。表情は変わっていない。変わっていないように見える。"}, {"id": "ch04-s02-p049", "type": "text", "text": "「これ、俺が清書したやつですね」"}, {"id": "ch04-s02-p050", "type": "text", "text": "篠宮さんの瞬きが一回入った。"}, {"id": "ch04-s02-p051", "type": "text", "text": "「はい。朝霧さんに清書していただいた分も、展示に含まれています」"}, {"id": "ch04-s02-p052", "type": "text", "text": "声は平坦だった。説明の声。事実を過不足なく伝える声。"}, {"id": "ch04-s02-p053", "type": "text", "text": "「使ってよかったのですか、と聞かれるのでしたら——記録は記録です。清書した方が誰であっても、記録の価値は同じです」"}, {"id": "ch04-s02-p054", "type": "text", "text": "言葉は正確だった。篠宮さんの言葉はいつも正確だ。句読点の後に間を置き、次の文を始める。ただ、「記録の価値は同じです」の後に来るはずの間が、来なかった。続きがあるように見えた。唇が動きかけて、止まった。"}, {"id": "ch04-s02-p055", "type": "text", "text": "「すごいですね。これ全部、篠宮さんが」"}, {"id": "ch04-s02-p056", "type": "text", "text": "篠宮さんの唇の端が、かすかに引かれた。否定の動き。"}, {"id": "ch04-s02-p057", "type": "text", "text": "「全部ではありません。先代の記録係の方々の仕事も含まれています。写真や地図の原本は、何十年も前から図書館に保管されていたものです。私が行ったのは、整理と、模写と、展示の構成だけです」"}, {"id": "ch04-s02-p058", "type": "text", "text": "正確な答えだった。篠宮さんは「全部」という言葉を受け入れない。自分の仕事の範囲を正確に限定する。先人の記録を引き継いでいること、自分だけの成果ではないことを、きちんと区分する。"}, {"id": "ch04-s02-p059", "type": "text", "text": "「でも、これを続けているのは篠宮さんだ」"}, {"id": "ch04-s02-p060", "type": "text", "text": "言ってから、気づいた。敬語が落ちていた。"}, {"id": "ch04-s02-p061", "type": "text", "text": "篠宮さんの瞬きが止まった。"}, {"id": "ch04-s02-p062", "type": "text", "text": "二秒。三秒。墨色の瞳が動かない。"}, {"id": "ch04-s02-p063", "type": "text", "text": "それから、表情が変わった。"}, {"id": "ch04-s02-p064", "type": "text", "text": "変わった、と言えるかどうか。顔の筋肉がどこか一箇所動いたのかもしれない。唇の端か、眉の角度か、目元の影の深さか。どこが変わったのか正確に特定できない。けれど、全体の印象が——ほんのわずかに、緩んだ。"}, {"id": "ch04-s02-p065", "type": "text", "text": "「……ありがとうございます」"}, {"id": "ch04-s02-p066", "type": "text", "text": "声が小さかった。いつもの図書館の音量よりも小さい。記録室で「諦めません」と言った時の声よりも小さい。壁にも天井にも届かない。俺と篠宮さんの間の一メートルほどの空気だけを振動させる音量。"}, {"id": "ch04-s02-p067", "type": "text", "text": "篠宮さんの視線が展示に戻った。"}, {"id": "ch04-s02-p068", "type": "text", "text": "俺も展示に戻った。"}, {"id": "ch04-s02-p069", "type": "text", "text": "三枚目の衝立をもう一度見た。消滅者リスト。篠宮さんの字と俺の字が一枚の中に並んでいる。上半分と下半分。字の大きさが違う。角度が違う。けれどインクは同じ黒で、紙は同じ清書用紙で、書かれている情報は同じ形式のリストだった。"}, {"id": "ch04-s02-p070", "type": "text", "text": "この名前の人たちは、もういない。場所もない。写真に写っている港も、地図に描かれた集落も、消えた。残っているのは記録だけ。紙の上のインクの線だけ。"}, {"id": "ch04-s02-p071", "type": "text", "text": "来場者は俺一人だった。"}, {"id": "ch04-s02-p072", "type": "text", "text": "祭りの日に、この展示を見に来る人は少ないのだろう。外では出店が並び、焼き菓子の甘い匂いがして、三角旗が揺れている。楽しい場所が他にたくさんある。消えた場所の記録を見ることは楽しいことではない。"}, {"id": "ch04-s02-p073", "type": "text", "text": "篠宮さんはそれを知っていて、ここに立っている。"}, {"id": "ch04-s02-p074", "type": "text", "text": "衝立の間を歩き直した。一枚目の地図の前に戻り、もう一度見た。海岸線の曲がり方。港の位置。道の太さ。篠宮さんがこの地図を模写した時間を想像した。原本を見ながら、ペンで一本ずつ線を引いていく。島の形を紙の上に写し取る。もうない島の形を。"}, {"id": "ch04-s02-p075", "type": "text", "text": "二枚目の写真の前に立った。祭りの写真を見た。写真の中の人々は笑っていた。遠くて顔は判別できないが、体の角度や腕の位置が「楽しんでいる」形をしていた。この人たちの名前が、三枚目のリストの中にあるのかもしれない。"}, {"id": "ch04-s02-p076", "type": "text", "text": "三枚目の前に戻った。"}, {"id": "ch04-s02-p077", "type": "text", "text": "俺の字で書かれた名前を読んだ。一行ずつ。清書した時は一行ごとにペン先をインク壺に浸し、紙の上に文字を置いていった。名前の意味も、その人がどんな顔をしていたかも知らなかった。ただ字を書いた。篠宮さんの下書きを、清書用紙に写した。"}, {"id": "ch04-s02-p078", "type": "text", "text": "今、その字が展示されている。誰かに見てもらうために。来場者が少なくても、ここに貼ってある。消えた人の名前を、誰かが目にする可能性があるかぎり。"}, {"id": "ch04-s02-p079", "type": "text", "text": "篠宮さんが衝立の横にいた。立ち位置が変わっていなかった。来場者が俺一人でも、展示の横に立ち続けている。"}, {"id": "ch04-s02-p080", "type": "text", "text": "「篠宮さん」"}, {"id": "ch04-s02-p081", "type": "text", "text": "「はい」"}, {"id": "ch04-s02-p082", "type": "text", "text": "「この展示、祭りの間ずっとやっているんですか」"}, {"id": "ch04-s02-p083", "type": "text", "text": "「はい。今日と明日の二日間、開館時間中は展示しています」"}, {"id": "ch04-s02-p084", "type": "text", "text": "「篠宮さんもずっとここに」"}, {"id": "ch04-s02-p085", "type": "text", "text": "「はい。記録の説明が必要な場合がありますので」"}, {"id": "ch04-s02-p086", "type": "text", "text": "二日間。開館時間の間、この場所に立ち続ける。来場者が一人も来ない時間があっても、ここにいる。それが篠宮さんの仕事だと、篠宮さんは思っている。"}, {"id": "ch04-s02-p087", "type": "text", "text": "外から祭りの音がかすかに聞こえた。壁越しに。遠い。笑い声か、呼び声か、区別がつかないほどの距離。図書館の中は静かだった。残響灯の青白い光と、木の壁と、紙の匂い。"}, {"id": "ch04-s02-p088", "type": "text", "text": "「また来ます」"}, {"id": "ch04-s02-p089", "type": "text", "text": "篠宮さんの瞬きが一回止まった。短い停止。一秒もなかった。"}, {"id": "ch04-s02-p090", "type": "text", "text": "「……お待ちしています」"}, {"id": "ch04-s02-p091", "type": "text", "text": "声の音量が、さっきの「ありがとうございます」よりわずかに大きかった。図書館の声に戻っていた。けれど、語尾の「す」が少しだけ長く伸びた。待つことを選んでいる声だった。"}, {"id": "ch04-s02-p092", "type": "text", "text": "扉に向かった。真鍮の取っ手を引いた。蝶番が鳴った。"}, {"id": "ch04-s02-p093", "type": "text", "text": "外に出た瞬間、音が戻ってきた。祭りの音。人の声。足音。炭の音。甘い匂い。温かい空気。五月の日差し。さっきまでの静けさが嘘のように、全部が一度に押し寄せてきた。"}, {"id": "ch04-s02-p094", "type": "text", "text": "背中の後ろで、図書館の扉が閉まった。"}, {"id": "ch04-s02-p095", "type": "text", "text": "あの中に、篠宮さんがいる。衝立の横に立って、次の来場者を待っている。消えた場所の記録の隣で、一人で。"}, {"id": "ch04-s02-p096", "type": "text", "text": "俺の字が展示されていた。記録室で清書した字が。篠宮さんの字の隣に並んで。"}, {"id": "ch04-s02-p097", "type": "text", "text": "記録は記録だと篠宮さんは言った。清書した人が誰でも、記録の価値は同じだと。それは正しい。正しいけれど、篠宮さんがあのリストを展示に選んだことの中に、正しさだけではない何かがあったのかもしれない。"}, {"id": "ch04-s02-p098", "type": "text", "text": "わからない。"}, {"id": "ch04-s02-p099", "type": "text", "text": "覚えておく。篠宮さんの展示と、俺の字がそこにあったことと、「お待ちしています」の語尾が少しだけ長かったことを。"}]}, {"chapter": 4, "chapterTitle": "残響祭の灯り", "scene": 3, "sceneTitle": "舞台裏の千歳", "wordCount": "約4,000字", "paragraphs": [{"id": "ch04-s03-p001", "type": "text", "text": "響弦館の裏口は、表とは別の建物のようだった。"}, {"id": "ch04-s03-p002", "type": "text", "text": "表は飴色の木枠に真鍮の取っ手。中円区の住民が晴れ着で通る場所だ。裏口は灰色の鉄の扉。塗装が剥げている。搬入用の通路に面していて、足元に台車の轍が薄く残っている。"}, {"id": "ch04-s03-p003", "type": "text", "text": "扉を押した。重かった。"}, {"id": "ch04-s03-p004", "type": "text", "text": "中に入ると、空気が変わった。祭りの匂いが鉄の扉一枚で遮断され、代わりに木材と蜜蝋と埃の匂い。響弦館は元が富裕層の邸宅だから、壁も天井も木だ。その匂いが裏口側にも染みている。"}, {"id": "ch04-s03-p005", "type": "text", "text": "舞台裏は暗かった。"}, {"id": "ch04-s03-p006", "type": "text", "text": "残響灯が壁際に三つだけ灯っていて、青白い光が床を薄く照らしている。天井は高いが、舞台の裏側だから梁が何本も横に走っていて、その梁から滑車と綱が下がっている。幕を上げ下げするための装置。綱の端が壁のクリートに巻かれて固定されている。"}, {"id": "ch04-s03-p007", "type": "text", "text": "足元にケーブルが這っていた。"}, {"id": "ch04-s03-p008", "type": "text", "text": "音響盤から拡声器まで、三本の信号線が床を這い、養生テープで固定されている。二週間前に俺が配線した線だった。端子の増し締めをした時の手触りを指先が覚えている。テープの上を踏まないように歩いた。"}, {"id": "ch04-s03-p009", "type": "text", "text": "音響盤の前に立った。"}, {"id": "ch04-s03-p010", "type": "text", "text": "木製の筐体。つまみが五つ。切り替えスイッチが二つ。左端に出力計器。右側面の銅製レバーを上げると、内部で小さな唸りが立ち上がった。残響紋回路に電流が通り、計器の針がゼロの位置で一度揺れ、止まった。"}, {"id": "ch04-s03-p011", "type": "text", "text": "つまみを一つずつ回し、拡声器三基への出力を確認した。左袖、右袖、天吊り。三基とも正常範囲。二週間前の設定値から変わっていない。"}, {"id": "ch04-s03-p012", "type": "text", "text": "天吊り拡声器の角度だけ、微調整が要る。座席配置図が変わったので、客席に向ける角度を修正する。脚立が要る。"}, {"id": "ch04-s03-p013", "type": "text", "text": "脚立を取りに舞台裏の資材置き場へ向かおうとした時、声が聞こえた。"}, {"id": "ch04-s03-p014", "type": "text", "text": "「——大丈夫。ちーちゃん、大丈夫だよ」"}, {"id": "ch04-s03-p015", "type": "text", "text": "風祭さんの声だった。楽屋に繋がる通路の向こうから聞こえてくる。通路が開いているから音がそのまま届く。声は小さいが、舞台裏が静かなので輪郭がはっきり残っている。"}, {"id": "ch04-s03-p016", "type": "text", "text": "「いつも通りに歌えば、絶対大丈夫だよ」"}, {"id": "ch04-s03-p017", "type": "text", "text": "足を止めた。"}, {"id": "ch04-s03-p018", "type": "text", "text": "二週間前の「音響、ちゃんとやってくれるんでしょ」とは違う声だった。角が取れている。柔らかいが、中に硬いものがある。「大丈夫」と言い切れる硬さ。"}, {"id": "ch04-s03-p019", "type": "text", "text": "別の声が応じた。"}, {"id": "ch04-s03-p020", "type": "text", "text": "「……うん。ありがとう、いろは」"}, {"id": "ch04-s03-p021", "type": "text", "text": "鳴海さんの声。"}, {"id": "ch04-s03-p022", "type": "text", "text": "いつもと違っていた。声の立ち上がりが遅い。息を吸ってから声になるまでに空白がある。その空白に何が入っているのか、ここからは見えない。"}, {"id": "ch04-s03-p023", "type": "text", "text": "「ハンカチ、持ってきたから。はい」"}, {"id": "ch04-s03-p024", "type": "text", "text": "「ありがとう……」"}, {"id": "ch04-s03-p025", "type": "text", "text": "「手、冷たいね。大丈夫？」"}, {"id": "ch04-s03-p026", "type": "text", "text": "「うん。緊張してるだけだと思う」"}, {"id": "ch04-s03-p027", "type": "text", "text": "「思う、じゃなくて、緊張してるんだよ。ちーちゃんは自分のこと『思う』で済ませすぎ」"}, {"id": "ch04-s03-p028", "type": "text", "text": "風祭さんの声に笑いが混じった。けれどその笑いの下に、別の観察がある。「手が冷たい」を確認している。冷たいことを知ったうえで「大丈夫」と言った。鳴海さんの体の変化を測る目が、励ましの言葉の裏側で動いている。"}, {"id": "ch04-s03-p029", "type": "text", "text": "俺は音響盤の前に戻った。"}, {"id": "ch04-s03-p030", "type": "text", "text": "二人の会話に割り込む理由がなかった。つまみの位置を指で確認しながら、通路の向こうから聞こえる声を耳の端に置いた。"}, {"id": "ch04-s03-p031", "type": "text", "text": "「……わたしが歌うことで、皆が安心してくれるなら」"}, {"id": "ch04-s03-p032", "type": "text", "text": "鳴海さんの声。"}, {"id": "ch04-s03-p033", "type": "text", "text": "二週間前にも聞いた言葉。使命の温度。灯籠通りで「歌うことが、好きなんです」と言った時の温度とは、やはり違う。"}, {"id": "ch04-s03-p034", "type": "text", "text": "「ちーちゃんは、歌いたいから歌うんでしょ？」"}, {"id": "ch04-s03-p035", "type": "text", "text": "風祭さんの声が低くなった。冗談の形が剥がれている。"}, {"id": "ch04-s03-p036", "type": "text", "text": "「……うん。歌いたい」"}, {"id": "ch04-s03-p037", "type": "text", "text": "鳴海さんの声が変わった。さっきまでの空白が消えている。息を吸ってから声になるまでの間が短くなった。「歌いたい」の三文字は、使命の温度ではなかった。"}, {"id": "ch04-s03-p038", "type": "text", "text": "「じゃあそれでいい。他の理由なんか、いらないよ」"}, {"id": "ch04-s03-p039", "type": "text", "text": "風祭さんは鳴海さんの言葉の中から「歌いたい」だけを拾い上げて、他の荷物を全部降ろした。"}, {"id": "ch04-s03-p040", "type": "text", "text": "音響盤の確認が終わった。"}, {"id": "ch04-s03-p041", "type": "text", "text": "脚立を取りに資材置き場へ行き、アルミの脚立を肩に担いでステージの中央に戻った。脚立を立て、天吊り拡声器の固定金具を緩めて角度を調整する。客席の中央最後列に向けて一度だけ傾ける。三ミリ。それだけで音の到達範囲が変わる。金具を締め直し、脚立を降りた。"}, {"id": "ch04-s03-p042", "type": "text", "text": "通路から足音が二つ聞こえた。"}, {"id": "ch04-s03-p043", "type": "text", "text": "鳴海さんと風祭さんが舞台裏に出てきた。楽屋通路の入口に、二つの影が並んでいる。残響灯の青白い光で、鳴海さんの亜麻色の髪が薄く光っていた。右前髪のリボンの色は暗い中でも判る。薄桃色。カーディガンを肩にかけている。両手を前で重ねている。指先が——カーディガンの裾を、きつく握っている。"}, {"id": "ch04-s03-p044", "type": "text", "text": "風祭さんはいつもの位置にいた。鳴海さんの左側、半歩後ろ。右手にハンカチを持っている。白いハンカチ。端に刺繍が入っている。手作りだろう。風祭さんの手芸の腕は講堂で聞いた。"}, {"id": "ch04-s03-p045", "type": "text", "text": "鳴海さんが俺に気づいた。"}, {"id": "ch04-s03-p046", "type": "text", "text": "カーディガンを握っていた指先が緩んだ。表情が変わる。穏やかな微笑みが浮かぶ。口元と目がほぼ同時に動く。いつもの微笑み。さっきの通路から聞こえた、緊張で声が遅くなっていた鳴海さんとは、表面の形が違っていた。"}, {"id": "ch04-s03-p047", "type": "text", "text": "「朝霧さん。音響の最終チェックですか？」"}, {"id": "ch04-s03-p048", "type": "text", "text": "「はい。拡声器の角度を一箇所調整しました。出力は正常です」"}, {"id": "ch04-s03-p049", "type": "text", "text": "「ありがとうございます。今日はよろしくお願いしますね」"}, {"id": "ch04-s03-p050", "type": "text", "text": "微笑みの裏に、カーディガンを握っていた力の痕がある。見えない場所に置いた緊張を、微笑みが覆っている。鳴海さんはそれを隠そうとしているのではなく、たぶん、見せるべきではないと判断しているのだと思う。歌い手が緊張を見せたら、聴く側も緊張する。だから笑う。それが鳴海さんの仕事の一部だと、鳴海さんは考えている。"}, {"id": "ch04-s03-p051", "type": "text", "text": "風祭さんの目が俺を見ていた。査定の目。二週間前に「信じとく」と言った時と同じ材質の目。ただし、目の奥の硬さが一段やわらかい。木の壁のまま。叩いた時の音が前より丸い。"}, {"id": "ch04-s03-p052", "type": "text", "text": "「朝霧さん」"}, {"id": "ch04-s03-p053", "type": "text", "text": "風祭さんの声。"}, {"id": "ch04-s03-p054", "type": "text", "text": "「はい」"}, {"id": "ch04-s03-p055", "type": "text", "text": "「ちーちゃんの歌、ちゃんと届けてよね」"}, {"id": "ch04-s03-p056", "type": "text", "text": "二週間前は「ちゃんとやってくれるんでしょ」だった。今は「届けてよね」。やる、ではなく、届ける。風祭さんの中で、俺に求めていることの精度が上がっている。"}, {"id": "ch04-s03-p057", "type": "text", "text": "「届けます」"}, {"id": "ch04-s03-p058", "type": "text", "text": "「うん」"}, {"id": "ch04-s03-p059", "type": "text", "text": "風祭さんが小さく頷いた。視線が俺から離れ、鳴海さんに戻った。戻る速度が速い。鳴海さんから一秒以上目を離さない。それが風祭さんの基本動作だった。"}, {"id": "ch04-s03-p060", "type": "text", "text": "鳴海さんが俺を見た。"}, {"id": "ch04-s03-p061", "type": "text", "text": "微笑みの形が変わっていた。どこが変わったのか特定できない。けれど、「届けます」を聞いた後の顔が、さっきの顔と違う。"}, {"id": "ch04-s03-p062", "type": "text", "text": "「朝霧さん」"}, {"id": "ch04-s03-p063", "type": "text", "text": "「はい」"}, {"id": "ch04-s03-p064", "type": "text", "text": "「音響のこと、お願いしますね」"}, {"id": "ch04-s03-p065", "type": "text", "text": "二度目の「お願いしますね」。一度目は業務の確認だった。二度目は——声が柔らかかった。微笑みの角度が変わらないまま、声だけが一段やわらかくなっている。"}, {"id": "ch04-s03-p066", "type": "text", "text": "「任せてください」"}, {"id": "ch04-s03-p067", "type": "text", "text": "言った後、自分の声が耳に残った。"}, {"id": "ch04-s03-p068", "type": "text", "text": "普段の声と違っていた。声の芯が太い。息の量が多い。いつもの俺なら業務報告の声で言う。平坦な声。今の声は平坦ではなかった。"}, {"id": "ch04-s03-p069", "type": "text", "text": "鳴海さんの微笑みが——止まった。"}, {"id": "ch04-s03-p070", "type": "text", "text": "止まったというのは正確ではない。微笑みの形は維持されている。口元も目元も動いていない。動いていないのに、目の奥に何かが通過した。俺の声を聞いて、鳴海さんの中で何かが反応していた。"}, {"id": "ch04-s03-p071", "type": "text", "text": "「……ふふ。頼もしいです」"}, {"id": "ch04-s03-p072", "type": "text", "text": "声が少し高かった。普段の鳴海さんの声の周波数より、わずかに上。嬉しい時の高さだった。灯籠通りで「温かくなる」と言った時に見せた笑顔の、ずっと手前にある高さ。歯は見えていない。壁が一段下がるほどではない。けれど、壁の向こうから、何かが覗いている。"}, {"id": "ch04-s03-p073", "type": "text", "text": "風祭さんの目がこちらを向いていた。俺の声を聞いていた。共鳴者訓練で鍛えられた聴覚は、声の変化に敏感だ。俺の声がいつもと違ったことに、気づいただろう。"}, {"id": "ch04-s03-p074", "type": "text", "text": "風祭さんの口が小さく動いた。言葉にはならなかった。"}, {"id": "ch04-s03-p075", "type": "text", "text": "「ちーちゃん、そろそろ声出ししよう。開演一時間前だよ」"}, {"id": "ch04-s03-p076", "type": "text", "text": "風祭さんが鳴海さんの肩に手を置いた。何百回と繰り返された角度と力加減。一瞬だけ力を込め、すぐに離れた。"}, {"id": "ch04-s03-p077", "type": "text", "text": "「うん。朝霧さん、本番もよろしくお願いしますね」"}, {"id": "ch04-s03-p078", "type": "text", "text": "鳴海さんが会釈した。亜麻色の髪が前に流れ、戻った。リボンが一瞬だけ揺れた。"}, {"id": "ch04-s03-p079", "type": "text", "text": "「はい」"}, {"id": "ch04-s03-p080", "type": "text", "text": "二人が楽屋通路に戻っていく。風祭さんが先に通路に入り、鳴海さんを通す。いつもと逆だった。本番前。鳴海さんの集中を守るための動線変更。"}, {"id": "ch04-s03-p081", "type": "text", "text": "通路の角を曲がる時、鳴海さんが一度だけ振り返った。"}, {"id": "ch04-s03-p082", "type": "text", "text": "振り返って、俺を見た。"}, {"id": "ch04-s03-p083", "type": "text", "text": "微笑みの形は変わっていなかった。穏やかで、丁寧で、壁のある微笑み。けれど、振り返ったこと自体が——いつもの鳴海さんにはない動作だった。"}, {"id": "ch04-s03-p084", "type": "text", "text": "一秒。目が合った。それだけだった。鳴海さんは前に戻り、通路の奥に消えた。"}, {"id": "ch04-s03-p085", "type": "text", "text": "舞台裏に俺一人が残った。"}, {"id": "ch04-s03-p086", "type": "text", "text": "音響盤の唸りが低く続いている。残響灯が青白い。脚立が舞台中央に立ったまま。片付けなければ。"}, {"id": "ch04-s03-p087", "type": "text", "text": "脚立を畳みながら、さっきの自分の声を再生した。「任せてください」。あの声には業務以外の何かが混じっていた。拡声器の角度を三ミリ調整したのと同じだ。届くように。鳴海さんの歌が、客席の最後列まで届くように。"}, {"id": "ch04-s03-p088", "type": "text", "text": "仕事だからやる。嘘ではない。けれど、仕事だけでは三ミリの調整をしない。マニュアルの許容範囲に収まっていれば動かさなくていい。動かしたのは、鳴海さんの歌が一番よく届く角度を出したかったからだ。"}, {"id": "ch04-s03-p089", "type": "text", "text": "その動機に名前がまだない。"}, {"id": "ch04-s03-p090", "type": "text", "text": "脚立を資材置き場に戻した。音響盤の前に戻り、つまみの位置を最終確認した。出力計器の針が正常範囲の中央で静止している。あと一時間。開演まで一時間。"}, {"id": "ch04-s03-p091", "type": "text", "text": "舞台裏の通路の奥から、かすかに声が聞こえた。鳴海さんの声出し。音階を一つずつ上がっていく声。まだ歌ではない。声の準備。筋肉を温めるように、声帯を温めている。"}, {"id": "ch04-s03-p092", "type": "text", "text": "その声を聴きながら、音響盤の横に座った。"}, {"id": "ch04-s03-p093", "type": "text", "text": "業務の一環として、音響盤の側で待機する。開演までの一時間、ここにいる理由がある。業務だから。"}, {"id": "ch04-s03-p094", "type": "text", "text": "通路の奥から聞こえてくる鳴海さんの声に、俺の鳩尾がほんの少しだけ緩んでいた。訓練棟の外で初めて歌声を聴いた時と同じ反応。あの時より弱い。歌ではなく声出しだから。けれど、同じ場所が反応している。"}, {"id": "ch04-s03-p095", "type": "text", "text": "通路の奥で鳴海さんの声が音階を上っていく。その声を聴きながら、俺の声がいつもと違ったことについて考えていた。「任せてください」。あの声には、三ミリの角度を動かしたのと同じものが入っていた。まだ名前がない。名前がないまま、開演を待った。"}]}, {"chapter": 4, "chapterTitle": "残響祭の灯り", "scene": 4, "sceneTitle": "歌声の奇跡", "wordCount": "約5,000字", "paragraphs": [{"id": "ch04-s04-p001", "type": "text", "text": "開演十五分前に、舞台裏から客席へ移った。"}, {"id": "ch04-s04-p002", "type": "text", "text": "音響盤の出力は安定している。計器の針は正常範囲の中央で動かない。ここからは客席側の残響灯の明滅で拡声器の状態を確認する。不具合が出れば客席の通路から裏に回れる。それが本番中の待機位置。"}, {"id": "ch04-s04-p003", "type": "text", "text": "響弦館の客席は扇形に広がっている。"}, {"id": "ch04-s04-p004", "type": "text", "text": "一階席が五百。二階の桟敷が三百。合わせて八百。木の座席が弧を描いて並び、正面にステージ。ステージの上には何もない。演台もマイクスタンドもない。拡声器が壁と天井に埋め込まれているから、歌い手はステージの中央に立つだけでいい。共鳴者の公演は、声と人しか要らない。"}, {"id": "ch04-s04-p005", "type": "text", "text": "八百席の大半が埋まっていた。"}, {"id": "ch04-s04-p006", "type": "text", "text": "中円区の住民が多い。正装に近い服。紺のジャケット、白い襟。外円区から来た人もいる。布の質が違う。けれど、座った後の姿勢は同じだった。背筋が伸びている。これから始まるものへの敬意が、体を縦にしている。"}, {"id": "ch04-s04-p007", "type": "text", "text": "俺は右側通路に面した端の席にいた。不具合時にすぐ動ける位置。通路に近い分、人の体温が左の客よりも薄い。隣は空席。その向こうに天城さんが座っていた。"}, {"id": "ch04-s04-p008", "type": "text", "text": "天城さんは三つ隣。間に一席だけ空席を挟んで、もう一席。その向こう。ポニーテールが揺れるのが視界の端に見える。前のめりの姿勢。膝の上に手を置いているが、指先がスカートの布を掴んでいる。"}, {"id": "ch04-s04-p009", "type": "text", "text": "楽しみにしている人の体だった。"}, {"id": "ch04-s04-p010", "type": "text", "text": "天城さんの右隣に篠宮さんがいた。背筋が真っ直ぐ。膝の上にメモ帳。ペンを持った右手が定位置にある。記録する準備。公演中に何を記録するのかはわからない。けれど篠宮さんの手にペンがあることは、呼吸と同じ前提だった。"}, {"id": "ch04-s04-p011", "type": "text", "text": "残響灯が一段落ちた。"}, {"id": "ch04-s04-p012", "type": "text", "text": "客席の灯りが絞られ、八百人の呼吸が一つ浅くなった。音が減った。会話が止まり、衣擦れが消え、木の座席の軋みだけが残り、それも消えた。静寂が落ちてきた。天井から、壁から、床から、静寂が染み出してくる。響弦館の木材が音を吸い、吐かない。"}, {"id": "ch04-s04-p013", "type": "text", "text": "ステージの残響灯だけが白く灯っている。"}, {"id": "ch04-s04-p014", "type": "text", "text": "幕が上がった。"}, {"id": "ch04-s04-p015", "type": "text", "text": "鳴海さんが、いた。"}, {"id": "ch04-s04-p016", "type": "text", "text": "ステージの中央。白いブラウスに淡いブルーのスカート。カーディガンはない。腕が出ている。右前髪に薄桃色のリボン。亜麻色の髪が肩甲骨の下まで流れ、毛先のカールが残響灯の白い光を受けて、わずかに金色に透けている。"}, {"id": "ch04-s04-p017", "type": "text", "text": "立っているだけだった。"}, {"id": "ch04-s04-p018", "type": "text", "text": "腕を体の横に下ろし、背筋を伸ばし、正面を向いている。八百人を見ている。八百人に見られている。あの舞台裏でカーディガンの裾を握っていた指先は、今はどこにも触れていない。手が開いている。掌が見えた。"}, {"id": "ch04-s04-p019", "type": "text", "text": "穏やかな微笑みではなかった。"}, {"id": "ch04-s04-p020", "type": "text", "text": "表情がない——ではない。表情はあった。だがそれは俺が知っている鳴海さんの表情のどれでもなかった。朝霧さん、と微笑む時の壁がない。緊張でカーディガンを握る時の翳りもない。何もない。何もないのに、目が離せない。ステージの上の鳴海さんは、控え室から出てきた鳴海さんとは別の形をしていた。"}, {"id": "ch04-s04-p021", "type": "text", "text": "鳴海さんが息を吸った。"}, {"id": "ch04-s04-p022", "type": "text", "text": "客席から見てもわかった。肩が上がり、胸が膨らみ、止まった。八百人の視線がその呼吸に集まっている。俺の呼吸も止まっていた。"}, {"id": "ch04-s04-p023", "type": "text", "text": "歌が始まった。"}, {"id": "ch04-s04-p024", "type": "text", "text": "最初の一音で、空気が変わった。"}, {"id": "ch04-s04-p025", "type": "text", "text": "訓練棟の壁越しに聴いたものとは、違った。防音壁を透過して漏れてきた音は、水面に落ちた雨粒の波紋のようだった。本物は——雨そのものだった。"}, {"id": "ch04-s04-p026", "type": "text", "text": "音が降ってきた。"}, {"id": "ch04-s04-p027", "type": "text", "text": "天吊り拡声器から、左袖から、右袖から。三方向の音が客席の中央で重なり、融け、一つになった。三ミリ。あの角度が、効いていた。天吊りからの音が客席後方まで届いている。前列も後列も同じ密度で音に浸かっている。鳴海さんの声が、届いていた。"}, {"id": "ch04-s04-p028", "type": "text", "text": "声は高くなかった。低い音から始まった。胸の底に触れる振動。座席の木材が震えている——気のせいかもしれない。けれど、尻の下の木が微かに動いた、と感じた。響弦館は木でできている。壁も天井も床も木だ。鳴海さんの声が、建物ごと鳴らしている。"}, {"id": "ch04-s04-p029", "type": "text", "text": "旋律が上がっていく。"}, {"id": "ch04-s04-p030", "type": "text", "text": "低い音から中音域へ。音階を一段ずつ上がるのではなく、川が河口から遡るように滑らかに上昇する。声出しで聴いた音階練習とは構造が違う。あれは筋肉の準備だった。今は——歌だった。声が意味を持っている。言葉がある。歌詞がある。けれど、言葉の意味よりも先に、音の形が体に入ってくる。"}, {"id": "ch04-s04-p031", "type": "text", "text": "鳩尾が緩んだ。"}, {"id": "ch04-s04-p032", "type": "text", "text": "一回目に訓練棟の外で聴いた時と同じ場所。二回目に意識的に留まって聴いた時と同じ場所。三回目の今は——緩み方が違った。前の二回は、鳩尾の筋肉がほどける感覚だった。今回は、鳩尾の奥にある何かが溶けている。筋肉ではない。もっと深い場所。肋骨の内側、横隔膜の裏。名前のない場所に、名前のない反応が起きている。"}, {"id": "ch04-s04-p033", "type": "text", "text": "目の奥が熱くなった。"}, {"id": "ch04-s04-p034", "type": "text", "text": "一回目の時も、二回目の時も、この熱はあった。涙に変わらない熱。蛇口の手前で止まっている水。今回もそうだった。目の奥が熱い。視界が滲みかける。けれど、滲みきらない。涙の形にならない。"}, {"id": "ch04-s04-p035", "type": "text", "text": "——出ない。"}, {"id": "ch04-s04-p036", "type": "text", "text": "自分の目に手を当てようとして、止めた。拭くものがない。出てもいないものを拭おうとした。体が涙を知っている。出し方がわからない。"}, {"id": "ch04-s04-p037", "type": "text", "text": "旋律が高音域に入った。"}, {"id": "ch04-s04-p038", "type": "text", "text": "鳴海さんの声が変わった。中音域までは水だった。高音域に入った瞬間、水が光になった。声が光に聞こえる——意味がわからない。耳で聴いているのに、目の奥に白い線が走る。残響灯の光ではない。音が生んだ光。そんなものがあるのか。わからない。けれど体がそう受け取っている。"}, {"id": "ch04-s04-p039", "type": "text", "text": "客席の空気が澄んでいた。"}, {"id": "ch04-s04-p040", "type": "text", "text": "公演前の空気とは密度が違う。八百人が座っている空間なのに、息苦しさがない。むしろ呼吸が楽になっている。胸の重苦しさが薄くなっている。残響祭の人混みの中で蓄積していた圧迫感が、歌声に洗われて減っていく。"}, {"id": "ch04-s04-p041", "type": "text", "text": "色が変わった、と思った。"}, {"id": "ch04-s04-p042", "type": "text", "text": "残響灯の色は変わっていない。白いままだ。けれど、ステージの上の白が、さっきより澄んで見える。鳴海さんの髪の金色がより鮮やかに見える。薄桃色のリボンが、遠くからでも判る。色の精度が上がった。歌声が空気を澄ませ、光の通り道を掃除し、色をより正確に目に届けている。"}, {"id": "ch04-s04-p043", "type": "text", "text": "蝕域が後退するというのは、こういうことなのかもしれない。"}, {"id": "ch04-s04-p044", "type": "text", "text": "共鳴者の力。音で蝕域を押し返す。それが千歳の——鳴海さんの仕事だ。訓練棟で鍛え、響弦館で歌い、島を覆う蝕域を後退させる。俺はその仕組みを頭で知っていた。書類で読んだ。数字で理解した。"}, {"id": "ch04-s04-p045", "type": "text", "text": "今、体で理解している。"}, {"id": "ch04-s04-p046", "type": "text", "text": "鳴海さんの顔が見えた。"}, {"id": "ch04-s04-p047", "type": "text", "text": "ステージの中央。残響灯の白い光。遠くからでも表情は読める。穏やかな微笑みではなかった。目が見開かれている。口が大きく開いている。首の筋が浮いている。腕が——歌い始めた時は体の横に下がっていた腕が、いつの間にか少し持ち上がっている。掌が客席の方を向いている。"}, {"id": "ch04-s04-p048", "type": "text", "text": "命を燃やしている、と思った。"}, {"id": "ch04-s04-p049", "type": "text", "text": "鉄を叩いて形を変える鍛冶場の炎ではない。蝋燭の炎だ。小さくて、静かで、消えかけそうなのに、目を離せない。鳴海さんの体が発光しているように見えた。残響灯の反射ではない。内側から出ている光。そんなものは物理的にあり得ない。あり得ないが、見えた。"}, {"id": "ch04-s04-p050", "type": "text", "text": "きれいだ。"}, {"id": "ch04-s04-p051", "type": "text", "text": "そう思った。"}, {"id": "ch04-s04-p052", "type": "text", "text": "一回目に歌声を聴いた時も思った。あの時は「そう言うべきだからそう思ったのか、本当にそう感じたのか」が区別できなかった。二回目も同じだった。体の反応が先にあり、思考がラベルを貼る。ラベルが正しいか確かめる方法がなかった。"}, {"id": "ch04-s04-p053", "type": "text", "text": "今は——違った。"}, {"id": "ch04-s04-p054", "type": "text", "text": "きれいだと思った。体の反応と思考の間に隙間がなかった。鳩尾が緩み、目の奥が熱くなり、「きれいだ」が同時に立ち上がった。ラベルを貼ったのではなかった。鳩尾の緩みと目の奥の熱と「きれいだ」が全部同じものだった。分けられない。一つの反応が三つの場所に同時に出ている。"}, {"id": "ch04-s04-p055", "type": "text", "text": "そう感じた。"}, {"id": "ch04-s04-p056", "type": "text", "text": "「そう言うべきだから」ではなく、そう感じた。"}, {"id": "ch04-s04-p057", "type": "text", "text": "区別がついた。初めてだった。"}, {"id": "ch04-s04-p058", "type": "text", "text": "左の方で、小さな音がした。"}, {"id": "ch04-s04-p059", "type": "text", "text": "天城さんが泣いていた。"}, {"id": "ch04-s04-p060", "type": "text", "text": "三つ隣。ポニーテールが揺れていない。前のめりの姿勢が少し丸くなっている。右手がスカートから離れ、目元に当たっている。音を立てずに泣いていた。左手が膝を握っている。指が白い。肩が揺れていた。"}, {"id": "ch04-s04-p061", "type": "text", "text": "天城さんは泣ける人だった。"}, {"id": "ch04-s04-p062", "type": "text", "text": "歌声を聴いて、きれいだと感じて、それが涙になって出る。蛇口から水までの管が通っている。感覚が体の反応に直結する。俺にはそれができない。きれいだと感じている。鳩尾は緩んでいる。目の奥は熱い。なのに涙は出ない。管の途中に何か詰まっている。"}, {"id": "ch04-s04-p063", "type": "text", "text": "天城さんの隣で、篠宮さんのペンが止まっていた。"}, {"id": "ch04-s04-p064", "type": "text", "text": "メモ帳は膝の上にある。ペンは右手に握られている。けれど、ペンの先がメモ帳に触れていない。一センチほど浮いている。篠宮さんの目がステージを見ている。焦点が合っている。記録するためではなく、ただ見ている。"}, {"id": "ch04-s04-p065", "type": "text", "text": "篠宮さんの手が止まった。"}, {"id": "ch04-s04-p066", "type": "text", "text": "記録室で会ってから何度も隣で作業してきた。篠宮さんのペンは、呼吸のように動き続ける。止まっているのを見たことがない。ペンが止まるのは篠宮さんが篠宮さんでなくなる瞬間だ。そんな瞬間が来るとは思っていなかった。"}, {"id": "ch04-s04-p067", "type": "text", "text": "鳴海さんの歌が、篠宮さんの手を止めた。"}, {"id": "ch04-s04-p068", "type": "text", "text": "ステージの左袖。暗がりの中に人影が見えた。客席からは見えない角度。俺の席は右端だから、ステージの左奥まで視線が通る。"}, {"id": "ch04-s04-p069", "type": "text", "text": "風祭さんがいた。"}, {"id": "ch04-s04-p070", "type": "text", "text": "袖幕の影に立っている。腕を体の前で組んでいる。いつもは千歳の隣にいる。今は離れている。ステージに出られない。客席にも座っていない。袖幕の向こうから、千歳の背中を見ている。"}, {"id": "ch04-s04-p071", "type": "text", "text": "風祭さんの表情は——暗くて読めなかった。距離もある。けれど、体の形は見えた。腕を組んだ手が、自分の肘を握っている。祈っている、と思った。組んだ腕の形が祈りに見えた。千歳が最後まで歌いきることを、袖幕の向こうで祈っている。"}, {"id": "ch04-s04-p072", "type": "text", "text": "歌が佳境に入った。"}, {"id": "ch04-s04-p073", "type": "text", "text": "旋律が頂点に向かっている。鳴海さんの声が細くなっていく。細くなるのに、密度が増していく。糸が一本になるほど細いのに、その一本が鋼鉄のように硬い。客席の空気が張り詰めた。八百人が呼吸を忘れている。"}, {"id": "ch04-s04-p074", "type": "text", "text": "俺も忘れていた。"}, {"id": "ch04-s04-p075", "type": "text", "text": "いつから息を止めていたかわからない。四月の最初の日、鐘の音を聴いた時と同じだ。あの時は五分間、無意識に息を止めていた。今も同じことが起きている。体が呼吸より歌を優先している。"}, {"id": "ch04-s04-p076", "type": "text", "text": "最後の一音が響いた。"}, {"id": "ch04-s04-p077", "type": "text", "text": "長かった。どれくらいの長さだったか、正確にはわからない。十秒か、二十秒か。時間の感覚が壊れていた。最後の一音が響弦館の木材に染み込み、壁を伝い、天井を伝い、床を伝い、客席の座席を通じて体に届いた。尻の下の木が震えている。今度は気のせいではなかった。"}, {"id": "ch04-s04-p078", "type": "text", "text": "音が消えた。"}, {"id": "ch04-s04-p079", "type": "text", "text": "消えたのに、残っていた。"}, {"id": "ch04-s04-p080", "type": "text", "text": "残響。鳴海さんの声の残響が、響弦館の空間に薄く留まっている。音が終わった後の静寂は、音が始まる前の静寂とは別のものだった。前は空っぽだった。今は満ちている。"}, {"id": "ch04-s04-p081", "type": "text", "text": "拍手が来た。"}, {"id": "ch04-s04-p082", "type": "text", "text": "一人が始め、隣が続き、波が広がり、八百人の拍手が重なった。木の壁と天井に拍手が反射し、増幅され、響弦館が震えた。俺の手も動いていた。いつから叩いていたか覚えていない。掌が熱い。"}, {"id": "ch04-s04-p083", "type": "text", "text": "鳴海さんがステージの中央で頭を下げた。"}, {"id": "ch04-s04-p084", "type": "text", "text": "顔を上げた時、微笑んでいた。穏やかな微笑み。口元と目がほぼ同時に動く。いつもの鳴海さん。さっきまでの、命を燃やすような表情は消えていた。ステージの上の鳴海さんと、頭を下げた後の鳴海さんは、やはり別の形をしている。歌い終わると、鳴海さんは鳴海さんに戻る。"}, {"id": "ch04-s04-p085", "type": "text", "text": "微笑んだまま、鳴海さんが一歩後ろに下がった。"}, {"id": "ch04-s04-p086", "type": "text", "text": "右足が揺れた。"}, {"id": "ch04-s04-p087", "type": "text", "text": "小さな揺れだった。客席からは見えなかっただろう。靴の底が床を擦った音は拍手にかき消されていた。けれど俺は見た。鳴海さんの右膝が内側に折れかけた。体が右に傾いた。一秒もなかった。半秒。"}, {"id": "ch04-s04-p088", "type": "text", "text": "左袖から影が動いた。"}, {"id": "ch04-s04-p089", "type": "text", "text": "風祭さんだった。"}, {"id": "ch04-s04-p090", "type": "text", "text": "袖幕の向こうから走り出ていなかった。走ってはいなかった。歩いていた。速い歩き。けれど走りではない。膝を曲げず、腰から上を動かさず、足だけが速い。ステージの端から鳴海さんの横まで四歩。四歩で到着し、鳴海さんの左腕を取った。"}, {"id": "ch04-s04-p091", "type": "text", "text": "自然だった。"}, {"id": "ch04-s04-p092", "type": "text", "text": "鳴海さんを支えている、ようには見えなかった。隣に立って腕を取っただけに見えた。公演を終えた歌い手に寄り添う幼馴染。そういう絵に見える。けれど、風祭さんの右手は鳴海さんの肘を支えていた。体重を受け止めている。鳴海さんの膝が再び折れかけたのを、腕一本で止めていた。"}, {"id": "ch04-s04-p093", "type": "text", "text": "慣れている。"}, {"id": "ch04-s04-p094", "type": "text", "text": "その動作に淀みがなかった。鳴海さんが倒れかけた位置と角度を、体が知っていた。何度もやったことがある動作だった。反射ではない。反射なら一瞬遅れる。風祭さんは遅れていなかった。鳴海さんが揺れた瞬間に、もう動いていた。"}, {"id": "ch04-s04-p095", "type": "text", "text": "予測していた。"}, {"id": "ch04-s04-p096", "type": "text", "text": "公演が終わったら鳴海さんが揺れることを、風祭さんは知っていた。だから袖幕の向こうで待っていた。祈るような腕の組み方は、祈りではなかったのかもしれない。あれは準備だった。"}, {"id": "ch04-s04-p097", "type": "text", "text": "客席の拍手が続いている。鳴海さんが微笑んだまま、もう一度頭を下げた。風祭さんが隣で頭を下げた。二人が下がっていく。袖幕の向こうに消えていく。最後に鳴海さんの亜麻色の髪が揺れて、見えなくなった。"}, {"id": "ch04-s04-p098", "type": "text", "text": "目の奥が、まだ熱かった。"}, {"id": "ch04-s04-p099", "type": "text", "text": "涙は出なかった。"}, {"id": "ch04-s04-p100", "type": "text", "text": "きれいだった。それは確かだった。鳩尾の緩みと目の奥の熱と「きれいだ」が一つのものだった。なのに涙にならない。天城さんは泣いていた。俺は泣けなかった。感じている。感じているのに出力されない。蛇口はある。水はある。管が詰まっている。"}, {"id": "ch04-s04-p101", "type": "text", "text": "悔しい——とは、少し違う。"}, {"id": "ch04-s04-p102", "type": "text", "text": "詰まっていることへの苛立ちはある。けれど「悔しい」と呼ぶには輪郭が足りない。ただ、出ない。出ない、という事実だけが、目の奥に残っている。"}, {"id": "ch04-s04-p103", "type": "text", "text": "天城さんが目元を拭いていた。赤くなっている。涙の跡が光を反射している。「すごかった……」と、小さな声で言った。誰にでもなく。独り言のように。声が震えていた。"}, {"id": "ch04-s04-p104", "type": "text", "text": "篠宮さんのペンが動き始めた。止まっていた右手が、メモ帳の上に降りた。ペンの先が紙に触れ、文字を刻み始めた。何を書いているのかは見えない。ただ、公演が終わってからペンが動くまでに、十秒以上の空白があった。篠宮さんがペンを持ったまま何も書かなかった十秒。それが、鳴海さんの歌の重さだった。"}, {"id": "ch04-s04-p105", "type": "text", "text": "客席が明るくなった。"}, {"id": "ch04-s04-p106", "type": "text", "text": "残響灯が元の光量に戻り、八百人が立ち上がり始めた。木の座席が軋む音。衣擦れ。会話が戻ってくる。「素晴らしかった」「今回も——」「去年より——」。"}, {"id": "ch04-s04-p107", "type": "text", "text": "俺は座ったままだった。"}, {"id": "ch04-s04-p108", "type": "text", "text": "立てなかった。膝が動かないのではなく、立つ必要を感じなかった。あるいは、立ったら目の奥の熱が消える気がした。消えてほしくなかった。この熱を、もう少しだけ持っていたかった。"}, {"id": "ch04-s04-p109", "type": "text", "text": "鳴海さんのふらつきが、頭の中に残っていた。"}, {"id": "ch04-s04-p110", "type": "text", "text": "右膝が折れかけた。半秒。風祭さんが支えた。慣れている動作。予測していた。袖幕の向こうで待っていた。——あれは初めてではない。何度もあったのだ。公演のたびに鳴海さんは揺れ、風祭さんがそれを受け止めてきた。"}, {"id": "ch04-s04-p111", "type": "text", "text": "使命だから歌う。歌いたいから歌う。どちらも本当だとして、歌うたびに体が削られているなら——。"}, {"id": "ch04-s04-p112", "type": "text", "text": "考えを途中で止めた。"}, {"id": "ch04-s04-p113", "type": "text", "text": "今の俺に判断できることではない。鳴海さんの体のことは、鳴海さんと風祭さんと、医療の専門家が判断すべきだ。俺は音響を担当しているだけだ。三ミリの角度を調整し、拡声器の出力を管理する。それが俺の仕事だ。"}, {"id": "ch04-s04-p114", "type": "text", "text": "ただ——三ミリの調整は、仕事だけではなかった。"}, {"id": "ch04-s04-p115", "type": "text", "text": "届いた。鳴海さんの歌が、八百席の最後列まで届いた。俺が調整した角度で、音が客席を満たした。その事実が胸の中にある。仕事として完了した。完了した、で終わるはずのものが、まだ胸の中で動いている。"}, {"id": "ch04-s04-p116", "type": "text", "text": "立ち上がった。"}, {"id": "ch04-s04-p117", "type": "text", "text": "客席を出る時、ステージを振り返った。もう誰もいない。残響灯が白く照らす空のステージ。木の床に傷がある。鳴海さんの靴の底が擦った跡か。ただの古い傷か。判別はつかない。"}, {"id": "ch04-s04-p118", "type": "text", "text": "通路を歩き、ホワイエに出た。人が多い。公演後の余韻を持った顔が並んでいる。その中を歩いた。"}, {"id": "ch04-s04-p119", "type": "text", "text": "風祭さんの動作が頭を離れなかった。四歩。膝を曲げない速い歩き。腕を取る角度。慣れている手。鳴海さんが揺れることを知っていた人の手。あの手が何度、鳴海さんを支えてきたのか。"}, {"id": "ch04-s04-p120", "type": "text", "text": "そしてその手は、客席に見えないように支えていた。鳴海さんのふらつきを、八百人の誰にも気づかせないように。それが風祭さんの仕事だ。音響が俺の仕事であるのと同じように。"}, {"id": "ch04-s04-p121", "type": "text", "text": "覚えておく。"}, {"id": "ch04-s04-p122", "type": "text", "text": "鳴海さんの歌と、目の奥の熱と、出なかった涙と、右膝が折れかけた半秒と、風祭さんの四歩を。"}]}, {"chapter": 4, "chapterTitle": "残響祭の灯り", "scene": 5, "sceneTitle": "鐘鋳塔の明かり", "wordCount": "約4,000字", "paragraphs": [{"id": "ch04-s05-p001", "type": "text", "text": "ホワイエを出ると、祭りの空気が戻ってきた。"}, {"id": "ch04-s05-p002", "type": "text", "text": "提灯の色。焼き物の油の匂い。笑い声が頭の上を通過していく。響弦館の中で凝縮されていた密度が一気に薄まり、広い空の下に拡散する。俺の中にある目の奥の熱は、まだ消えていなかった。"}, {"id": "ch04-s05-p003", "type": "text", "text": "鐘鋳塔に向かった。"}, {"id": "ch04-s05-p004", "type": "text", "text": "残響祭の間も定期点検は変わらない。霜月さんからの指示は朝のうちに来ていた。「十六時。第七層と第九層の残響管、接合部のトルク確認。祭りは関係ない」。霜月さんにとって残響祭は暦の上の一日でしかない。鐘鋳塔の歯車は祭りの日も同じ速度で回る。"}, {"id": "ch04-s05-p005", "type": "text", "text": "灯籠通りを北へ折れ、中庭を横切り、塔の正面に出た。出店の賑わいが背中の方に遠ざかっていく。鐘鋳塔の石壁に近づくにつれ、音が減った。祭りの声は塔に反射して散り、石の表面だけが残る。"}, {"id": "ch04-s05-p006", "type": "text", "text": "扉を開けた。"}, {"id": "ch04-s05-p007", "type": "text", "text": "管理室は暗かった。残響灯の青白い光だけが、計器盤の上に線を引いている。椅子の上に誰もいない。当然だった。祭りの日も霜月さんは管理室にいないだけで、塔のどこかにはいる。"}, {"id": "ch04-s05-p008", "type": "text", "text": "二階への階段を上がった。石段の冷たさが靴底を通して足に届く。祭りの空気は石段一つで断たれた。ここから先は鐘鋳塔の中だ。"}, {"id": "ch04-s05-p009", "type": "text", "text": "三階の研究区画に霜月さんがいた。"}, {"id": "ch04-s05-p010", "type": "text", "text": "作業台の上に図面が広がっている。共鳴管の断面図。定規と赤鉛筆が図面の横に置かれ、赤い線が何本か書き加えられている。霜月さんは立ったまま図面を見ていた。白いロングコートの裾が床に触れている。銀髪のハーフアップが残響灯の光を拾い、金属のように光っている。"}, {"id": "ch04-s05-p011", "type": "text", "text": "「朝霧。定時だ」"}, {"id": "ch04-s05-p012", "type": "text", "text": "俺が扉の前に立った瞬間に言った。こちらを見ずに。足音で判別したか、時刻で予測したか。おそらく後者だ。霜月さんの時間感覚には誤差がない。"}, {"id": "ch04-s05-p013", "type": "text", "text": "「第七層から始めます」"}, {"id": "ch04-s05-p014", "type": "text", "text": "「第九層を先にしなさい。七層は午前中に私が目視で確認した。異常なし。九層の3番管に微振動が出ている。そちらを先に」"}, {"id": "ch04-s05-p015", "type": "text", "text": "「了解しました」"}, {"id": "ch04-s05-p016", "type": "text", "text": "霜月さんが図面から目を上げた。青紫色の瞳がこちらを見る。光の角度で青寄りに見えた。表情は無い。あるいは、あるのかもしれないが、読める場所に出てこない。"}, {"id": "ch04-s05-p017", "type": "text", "text": "「公演は終わったか」"}, {"id": "ch04-s05-p018", "type": "text", "text": "予想しなかった問いだった。霜月さんが公演に関心を持つとは思っていなかった。"}, {"id": "ch04-s05-p019", "type": "text", "text": "「はい。鳴海さんの歌は——」"}, {"id": "ch04-s05-p020", "type": "text", "text": "「鳴海の歌か。音響データは取れたか」"}, {"id": "ch04-s05-p021", "type": "text", "text": "感想を聞いているのではなかった。"}, {"id": "ch04-s05-p022", "type": "text", "text": "「出力値は正常範囲でした。天吊り拡声器の角度調整後の反響パターンは、想定通りの——」"}, {"id": "ch04-s05-p023", "type": "text", "text": "「数値で出しなさい。主観はいらない」"}, {"id": "ch04-s05-p024", "type": "text", "text": "「報告書にまとめます」"}, {"id": "ch04-s05-p025", "type": "text", "text": "「今日中に」"}, {"id": "ch04-s05-p026", "type": "text", "text": "霜月さんの視線が図面に戻った。会話が終わった、という合図ではない。会話の中に入れるべき情報が尽きた、という判断だ。霜月さんの会話には、始まりと終わりではなく、情報の有無だけがある。"}, {"id": "ch04-s05-p027", "type": "text", "text": "工具を取り、九階へ向かった。"}, {"id": "ch04-s05-p028", "type": "text", "text": "螺旋階段を上りながら、霜月さんの「鳴海の歌か」という言い方が頭に残っていた。「鳴海さんの公演は」ではなく「鳴海の歌か」。名前の呼び方に距離がある。けれど、歌、という語を選んでいた。公演でも催しでもなく、歌。霜月さんにとって鳴海さんの活動は「歌」として認識されている。データを求めるのは霜月さんらしい。だが歌という語を使ったことは、たぶん、霜月さん自身は気にしていない。"}, {"id": "ch04-s05-p029", "type": "text", "text": "九階の第3番管の微振動は、接合部のボルトが0.2回転分緩んでいた。増し締めして振動が収まったことを確認し、記録用紙に書いた。第七層も念のため目視点検を行い、異常なしを確認した。"}, {"id": "ch04-s05-p030", "type": "text", "text": "点検を終えて、螺旋階段をさらに上がった。"}, {"id": "ch04-s05-p031", "type": "text", "text": "十階の大鐘を通過する。直径五メートルの青銅の鐘が、天井から吊るされている。鐘の表面に残響紋が刻まれ、残響灯の光を細い線で反射している。触れなかった。初日に手を伸ばしかけて止めた時と同じだ。触れていいのかどうか、まだ判断がつかない。"}, {"id": "ch04-s05-p032", "type": "text", "text": "十一階。天蓋の間。"}, {"id": "ch04-s05-p033", "type": "text", "text": "石の階段が木の床に変わる。足の裏の感触が硬質から柔質に切り替わる。残響灯がない。天蓋のガラスから午後の光が差し込んでいる。昼間の天蓋の間を見るのは初めてだった。初めて来た夜は星の光だけだった。今は西日が斜めに入り、円形の部屋を半分だけ照らしている。光の当たる側の木の床が蜂蜜色に光り、影の側は薄い灰色に沈んでいる。"}, {"id": "ch04-s05-p034", "type": "text", "text": "すみれが窓辺にいた。"}, {"id": "ch04-s05-p035", "type": "text", "text": "天蓋の間には壁面にいくつかの小窓がある。すみれはそのうちの一つ、南向きの窓の前に立っていた。窓枠に手を置いて、外を見ている。白いワンピースが窓からの光を受けて薄く透けている。淡い紫色の髪が背中の途中まで流れ、毛先が午後の光で少しだけ白く見えた。裸足。足音がしなかったから、俺が階段を上った音で振り返ったのだろう。"}, {"id": "ch04-s05-p036", "type": "text", "text": "すみれの顔がこちらを向いた。"}, {"id": "ch04-s05-p037", "type": "text", "text": "口元が先に動いた。唇の端が上がり、0.5秒遅れて目が細くなった。あのずれ。初日と同じ。"}, {"id": "ch04-s05-p038", "type": "text", "text": "「れん」"}, {"id": "ch04-s05-p039", "type": "text", "text": "名前を呼ぶ声。低くはない。高くもない。子供が親しい相手を呼ぶ時の、力の抜けた音。"}, {"id": "ch04-s05-p040", "type": "text", "text": "「すみれ。来たよ」"}, {"id": "ch04-s05-p041", "type": "text", "text": "「うん。……鐘が、おしえてくれた」"}, {"id": "ch04-s05-p042", "type": "text", "text": "窓の外を指さした。"}, {"id": "ch04-s05-p043", "type": "text", "text": "「きょう、した（下）がにぎやか」"}, {"id": "ch04-s05-p044", "type": "text", "text": "窓から見下ろすと、中庭の出店が小さく見えた。提灯の色。人の動き。焼き物の煙が白い筋になって上がっている。音は届かない。鐘鋳塔の石壁が全てを遮断している。祭りの風景が、音のない映像として窓枠に切り取られていた。"}, {"id": "ch04-s05-p045", "type": "text", "text": "すみれは、あの賑わいを窓越しに見ていた。"}, {"id": "ch04-s05-p046", "type": "text", "text": "「すみれも行きたかった？」"}, {"id": "ch04-s05-p047", "type": "text", "text": "聞いてから、質問の形が適切だったか迷った。行きたいかどうかを聞く前に、行けるかどうかの問題がある。"}, {"id": "ch04-s05-p048", "type": "text", "text": "すみれが首を振った。小さく、二回。"}, {"id": "ch04-s05-p049", "type": "text", "text": "「すみれはここがいい」"}, {"id": "ch04-s05-p050", "type": "text", "text": "間があった。窓の外を見る目が、遠くなった。"}, {"id": "ch04-s05-p051", "type": "text", "text": "「でも……れんがきてくれるから、さびしくない」"}, {"id": "ch04-s05-p052", "type": "text", "text": "声が静かだった。風が木の床を撫でるのと同じ高さで、部屋の端までは届かない音量。すみれは笑っていた。口元が先に動き、目が追いかける、あのずれた微笑みで。"}, {"id": "ch04-s05-p053", "type": "text", "text": "——出られないのか。"}, {"id": "ch04-s05-p054", "type": "text", "text": "塔の最上階。初日にすみれがいた場所。着任してから何度か来た。すみれはいつもここにいた。食堂にいたことはない。灯籠通りで見かけたこともない。中庭にも、図書館にも、講堂にも。すみれの姿は、常に鐘鋳塔の中だけにあった。"}, {"id": "ch04-s05-p055", "type": "text", "text": "当然のように受け入れていた。すみれは塔にいる。それが前提だった。疑問を持つ隙間がなかった。けれど今、窓の外の祭りを音のない映像として見ているすみれの横に立って、前提の形が変わった。すみれは塔にいるのではなく、塔から出ていない。"}, {"id": "ch04-s05-p056", "type": "text", "text": "「出られないのか？」"}, {"id": "ch04-s05-p057", "type": "text", "text": "すみれが俺を見た。薄い紫色の瞳が瞬きを一度した。"}, {"id": "ch04-s05-p058", "type": "text", "text": "「んー……すみれは、ここにいるのがしぜんだから」"}, {"id": "ch04-s05-p059", "type": "text", "text": "困っている声ではなかった。悲しんでいる声でもなかった。蛇口から水が出ることを説明するのと同じ温度で、すみれは自分の在り方を述べた。ここにいることが自然。そこに疑問はない。すみれの中には、出られないことへの不満がなかった。"}, {"id": "ch04-s05-p060", "type": "text", "text": "俺は追及しなかった。"}, {"id": "ch04-s05-p061", "type": "text", "text": "すみれが悲しんでいないことを、代わりに悲しむ資格が俺にあるかわからなかった。それに、すみれの「しぜん」は嘘には見えなかった。嘘をつける構造をしていない。すみれの言葉は、形を選ぶ前に出てくる。"}, {"id": "ch04-s05-p062", "type": "text", "text": "窓の前から離れ、持ってきたものを思い出した。"}, {"id": "ch04-s05-p063", "type": "text", "text": "コートの内ポケットから紙の包みを出した。灯籠通りの出店で買ったどら焼き。天城さんに「すみれちゃんにも何か買ってあげなよ」と言われたのは、午前中に出店を回っていた時だった。あの時、俺は自分では思いつかなかった。天城さんの声がなければ、手ぶらで塔に来ていた。"}, {"id": "ch04-s05-p064", "type": "text", "text": "「すみれ、これ」"}, {"id": "ch04-s05-p065", "type": "text", "text": "紙の包みを差し出した。すみれが両手で受け取った。指が細い。紙の包みがすみれの手には少し大きかった。"}, {"id": "ch04-s05-p066", "type": "text", "text": "「なに？」"}, {"id": "ch04-s05-p067", "type": "text", "text": "「どら焼き。祭りの出店で買った」"}, {"id": "ch04-s05-p068", "type": "text", "text": "すみれが包みを開けた。丸い生地の間に餡が挟まっている。すみれが鼻を近づけた。犬が未知の物の匂いを嗅ぐのに似ている。"}, {"id": "ch04-s05-p069", "type": "text", "text": "一口、かじった。"}, {"id": "ch04-s05-p070", "type": "text", "text": "すみれの咀嚼は遅い。口の中で味を確かめている。噛むたびに顎が小さく動き、首が微かに傾く。飲み込んだ。"}, {"id": "ch04-s05-p071", "type": "text", "text": "「あまい」"}, {"id": "ch04-s05-p072", "type": "text", "text": "間。"}, {"id": "ch04-s05-p073", "type": "text", "text": "「……おいしい」"}, {"id": "ch04-s05-p074", "type": "text", "text": "目が細くなった。口元はすでに上がっていた。今度は目の方が先だった。0.5秒のずれが消えている。目と口が同時に動いた。微笑みではなかった。笑顔だった。すみれの表情の中で、初めて見る速度の一致。"}, {"id": "ch04-s05-p075", "type": "text", "text": "「おいしい」の言い方が、耳に残った。"}, {"id": "ch04-s05-p076", "type": "text", "text": "俺が「おいしい」を言う時には間がある。食堂の焼き魚に「おいしい、と思います」と言った日から、その間は少しずつ縮まっている。けれど完全には消えない。味を受け取ってから「おいしい」が口に出るまでの間に、判定の手続きが挟まる。体が感じた、と、言葉にする、の間に一段ある。"}, {"id": "ch04-s05-p077", "type": "text", "text": "すみれの「おいしい」には、間がなかった。"}, {"id": "ch04-s05-p078", "type": "text", "text": "甘い。おいしい。感覚が言葉に直結している。間に挟まるものが何もない。判定がない。「言うべきか」の迷いがない。甘いことを感じ、おいしいと言った。それだけ。"}, {"id": "ch04-s05-p079", "type": "text", "text": "けれど、俺の「おいしい」とは理由が違う。"}, {"id": "ch04-s05-p080", "type": "text", "text": "俺は判定の手続きを持っている。手続きがあるから間が生まれる。すみれには手続きそのものがない。感覚が言語に変換される回路が、まだ太い線一本しかない。甘い→おいしい。間にフィルタがない。"}, {"id": "ch04-s05-p081", "type": "text", "text": "俺は間がある。すみれは間がない。似ているようで構造が逆だ。俺の「おいしい」は間の向こうにあり、すみれの「おいしい」は間のこちら側にある。"}, {"id": "ch04-s05-p082", "type": "text", "text": "どちらも、たどり着く場所は同じだった。"}, {"id": "ch04-s05-p083", "type": "text", "text": "すみれがどら焼きの二口目を食べた。同じように遅い咀嚼。同じように目が細くなった。餡が唇の端についている。すみれは気づいていない。"}, {"id": "ch04-s05-p084", "type": "text", "text": "「れん、これ、なんていうの」"}, {"id": "ch04-s05-p085", "type": "text", "text": "「どら焼き」"}, {"id": "ch04-s05-p086", "type": "text", "text": "「どらやき」"}, {"id": "ch04-s05-p087", "type": "text", "text": "繰り返した。音を口の中で転がすように。言葉を覚えている。"}, {"id": "ch04-s05-p088", "type": "text", "text": "「どらやき、おいしい。すみれ、覚えた」"}, {"id": "ch04-s05-p089", "type": "text", "text": "窓の外では、音のない祭りが続いていた。提灯が風に揺れ、人が行き交い、煙が立ち上っている。すみれは窓に背を向けて、どら焼きを食べていた。"}, {"id": "ch04-s05-p090", "type": "text", "text": "塔の中は静かだった。祭りの喧騒が石壁の向こうにある。ここは別の時間が流れている。天蓋のガラスから差し込む午後の光が、すみれの紫色の髪を透かしている。"}, {"id": "ch04-s05-p091", "type": "text", "text": "すみれがどら焼きを食べ終わった。紙の包みを丁寧に折り畳み、ワンピースのポケットに入れた。包みを捨てずに、しまった。葉っぱや石を宝物箱に入れるのと同じ動作。紙の包みも、すみれの収集品に加わったらしい。"}, {"id": "ch04-s05-p092", "type": "text", "text": "「れん」"}, {"id": "ch04-s05-p093", "type": "text", "text": "「うん」"}, {"id": "ch04-s05-p094", "type": "text", "text": "「また持ってきてね」"}, {"id": "ch04-s05-p095", "type": "text", "text": "「わかった」"}, {"id": "ch04-s05-p096", "type": "text", "text": "すみれが頷いた。小さく一回。窓の方に体を向け直し、また外を見た。音のない祭りの映像を、すみれは窓枠の中に眺めている。"}, {"id": "ch04-s05-p097", "type": "text", "text": "ここにいるのが自然だから。"}, {"id": "ch04-s05-p098", "type": "text", "text": "すみれの言葉が頭の中に残っている。悲しみのない言葉だった。けれど、悲しみがないことが正しいのかは、わからなかった。祭りの音が聞こえない場所で、窓の外だけを見ている。それを自然と呼ぶすみれの声に嘘はなかった。嘘がないことと、寂しくないことは、たぶん、同じではない。"}, {"id": "ch04-s05-p099", "type": "text", "text": "天城さんが「何か買ってあげなよ」と言ってくれなかったら、どら焼きは買っていなかった。あの声があったから、俺は今日ここに手土産を持ってきた。誰かのために何かを持っていく。それは天城さんの側にある行動だ。俺の中から自然に出てくるものではなかった。"}, {"id": "ch04-s05-p100", "type": "text", "text": "けれど、すみれが「おいしい」と言った時の、目と口が同時に動いた瞬間を見て、鳩尾の下がほんの少しだけ緩んでいた。天城さんの声がなくても、次は自分で思いつくかもしれない。たぶん。"}, {"id": "ch04-s05-p101", "type": "text", "text": "螺旋階段を降り始めた。石段の冷たさが靴底に戻る。すみれの足音はしない。十一階に、白い光の中に、すみれが立っている。"}, {"id": "ch04-s05-p102", "type": "text", "text": "祭りの音が近づいてくる。石壁が薄くなるにつれ、人の声と笑いと音楽が戻ってくる。塔の外は祭りの午後だった。塔の中は、いつもと同じだった。"}]}, {"chapter": 4, "chapterTitle": "残響祭の灯り", "scene": 6, "sceneTitle": "残響桜のライトアップ", "wordCount": "約5,000字", "paragraphs": [{"id": "ch04-s06-p001", "type": "text", "text": "十九時の鐘が鳴った。"}, {"id": "ch04-s06-p002", "type": "text", "text": "短い鐘だった。定時報知の二打。祭りの喧騒に紛れて、鐘の余韻が聞き取れない。いつもなら石壁を伝って消えていく最後の一筋まで耳が追いかけるのに、今夜はそうならなかった。焼き菓子の匂いと、弦楽器の即興演奏と、誰かの笑い声が空気を占有している。"}, {"id": "ch04-s06-p003", "type": "text", "text": "出店で買った串焼きと蒸し饅頭で夕食を済ませた。食堂は混んでいた。入口で人の密度を見て、出店に並ぶ方が早いと判断した。串焼きは昼にも食べた味で、蒸し饅頭は初めてだった。中の餡が甘かった。「おいしい」は間なく出た。二つとも。"}, {"id": "ch04-s06-p004", "type": "text", "text": "中庭に戻ったのは、残響桜のライトアップを見るためだった。"}, {"id": "ch04-s06-p005", "type": "text", "text": "朝、残響桜の枝に吊るされていた小さな残響灯。昼間は消えたままの丸いガラス玉で、風に揺れると枝にぶつかって乾いた音を出していた。それが今、全て点灯している。"}, {"id": "ch04-s06-p006", "type": "text", "text": "薄紫の光。"}, {"id": "ch04-s06-p007", "type": "text", "text": "残響桜はもう葉桜だった。春の終わりに花弁の大半が散り、今は青い葉が枝を覆っている。けれど散りきらなかった花弁がわずかに残っていた。五月の気温の中で生き延びた最後の薄紫が、残響灯の光に照らされ、薄く発光しているように見えた。葉の隙間から光の粒が落ちてくる。"}, {"id": "ch04-s06-p008", "type": "text", "text": "灯籠通りの灯籠にも全て火が入っていた。"}, {"id": "ch04-s06-p009", "type": "text", "text": "夕方に点灯係が一つずつ火を入れていくのを何度も見た。今夜は油灯の炎の上に、薄紫のガラスの笠が被せてある。祭り仕様。炎が笠を通り、煉瓦舗装の道に薄紫の影が落ちている。灯籠通り全体がぼんやりと紫がかった空気に包まれている。"}, {"id": "ch04-s06-p010", "type": "text", "text": "残響桜の光と灯籠通りの光が合流する場所が、中庭の南端だった。"}, {"id": "ch04-s06-p011", "type": "text", "text": "俺はそこに立っていた。"}, {"id": "ch04-s06-p012", "type": "text", "text": "人が多い。昼間の祭りより密度は落ちたが、夜のライトアップを見に来た人が中庭と灯籠通りの境目あたりに集まっている。カップルが多い。友人同士の集団が多い。一人で立っている人間は少なかった。俺はその少数に入っている。"}, {"id": "ch04-s06-p013", "type": "text", "text": "鐘鋳塔を出てから二時間が経った。すみれに「また持ってきてね」と言われたどら焼きの包みの感触がまだコートのポケットに残っている気がする。実際には包みはすみれのポケットに入っている。ここにあるのは記憶だけだ。"}, {"id": "ch04-s06-p014", "type": "text", "text": "中庭を歩いた。残響桜の老木の下を通り過ぎ、灯籠通りの入口に向かう。"}, {"id": "ch04-s06-p015", "type": "text", "text": "四人の姿が見えた。"}, {"id": "ch04-s06-p016", "type": "text", "text": "天城さんは灯籠通りの入口にいた。出店の一つ——わたあめの屋台の前に立ち、渡されたピンク色のわたあめを片手に持って、もう片方の手で口元を押さえて笑っている。隣にいた同級生らしい女子二人が何か言い、天城さんがさらに笑った。ポニーテールが揺れ、黄色のヘアゴムが灯籠の光を受けてわずかに光った。"}, {"id": "ch04-s06-p017", "type": "text", "text": "鳴海さんは灯籠通りの中ほどにいた。カーディガンを羽織っている。舞台の上のブラウス姿ではなく、紺のカーディガンで腕を覆っている。風祭さんが隣にいた。二人で何か話している。鳴海さんの歩幅がいつもより小さい。足を運ぶ間隔が長い。公演の後の疲労が体に残っている。"}, {"id": "ch04-s06-p018", "type": "text", "text": "篠宮さんの姿は見えなかった。喧騒の中にいないことはわかる。探すなら、人の少ない場所だ。"}, {"id": "ch04-s06-p019", "type": "text", "text": "霜月さんの白いコートが、鐘鋳塔の方角に見えた。塔の入口付近。灯籠通りの光も出店の灯りも届かない暗がりに、白い縦の線が一つ。上を向いている。"}, {"id": "ch04-s06-p020", "type": "text", "text": "四人。四つの場所。四つの距離。"}, {"id": "ch04-s06-p021", "type": "text", "text": "――誰のところへ行こうか。"}, {"id": "ch04-s06-p022", "type": "text", "text": "▶ 天城さんのところへ\n▶ 鳴海さんのところへ\n▶ 篠宮さんを探す\n▶ 霜月さんのところへ"}, {"id": "ch04-s06-p023", "type": "divider", "text": "---"}, {"id": "ch04-s06-p024", "type": "text", "text": "### 選択: 天城さんと歩く"}, {"id": "ch04-s06-p025", "type": "text", "text": "天城さんの方に足が向いた。"}, {"id": "ch04-s06-p026", "type": "text", "text": "わたあめの屋台の前。友人たちが「じゃあねー」と手を振って灯籠通りの方へ去っていった。天城さんが一人になった瞬間に、俺が視界に入ったらしい。"}, {"id": "ch04-s06-p027", "type": "text", "text": "「あ、蓮くん！」"}, {"id": "ch04-s06-p028", "type": "text", "text": "片手にわたあめ。もう片方の手を上げて振った。指の間に砂糖の糸が少しついている。"}, {"id": "ch04-s06-p029", "type": "text", "text": "「一人？ あたしも今ちょうど一人になったとこ！」"}, {"id": "ch04-s06-p030", "type": "text", "text": "灯籠通りを並んで歩いた。天城さんのわたあめが少しずつ減っていく。ちぎっては口に入れ、ちぎっては口に入れる。"}, {"id": "ch04-s06-p031", "type": "text", "text": "「食べる？」"}, {"id": "ch04-s06-p032", "type": "text", "text": "わたあめの塊がこちらに差し出された。"}, {"id": "ch04-s06-p033", "type": "text", "text": "「もらいます」"}, {"id": "ch04-s06-p034", "type": "text", "text": "指でつまんだ。砂糖の繊維が指先に張りつき、口の中で一瞬で溶けた。甘い。中身のない甘さ。舌の上で形を失う。"}, {"id": "ch04-s06-p035", "type": "text", "text": "「なんか不思議な顔してる」"}, {"id": "ch04-s06-p036", "type": "text", "text": "「溶けるのが早くて」"}, {"id": "ch04-s06-p037", "type": "text", "text": "「あはは、蓮くんってそういうところあるよね」"}, {"id": "ch04-s06-p038", "type": "text", "text": "灯籠の紫の光の中を歩いた。天城さんのポニーテールが灯りの下を通過するたびに、栗色の赤みが紫に染まり、通り過ぎると元に戻る。色が入れ替わる。天城さんの髪は昼間の太陽の下では金色に近い。今は灯りの色を拾って変わり続けていた。"}, {"id": "ch04-s06-p039", "type": "text", "text": "天城さんが残響桜の下で足を止めた。"}, {"id": "ch04-s06-p040", "type": "text", "text": "見上げた。枝の先に残った薄紫の花弁が、残響灯に照らされている。光が花弁を透かし、花弁が光を染め、区別がつかなくなっている。"}, {"id": "ch04-s06-p041", "type": "text", "text": "「きれいだね……」"}, {"id": "ch04-s06-p042", "type": "text", "text": "天城さんの声が低かった。昼間のあの声量ではない。灯籠の光に合わせたような音量。周りの人に聞かせるための声ではなく、隣にいる俺にだけ届く声。"}, {"id": "ch04-s06-p043", "type": "text", "text": "「きれいだ」"}, {"id": "ch04-s06-p044", "type": "text", "text": "俺の口から出た。考えて言ったのではなかった。天城さんの声に引っ張られたのかもしれない。残響桜の光がそう言わせたのかもしれない。どちらかはわからない。"}, {"id": "ch04-s06-p045", "type": "text", "text": "天城さんがこちらを向いた。黄褐色の瞳が灯籠の光を拾って琥珀色に沈んでいる。昼間の活発な光とは違う目だった。"}, {"id": "ch04-s06-p046", "type": "text", "text": "「今のは本心？」"}, {"id": "ch04-s06-p047", "type": "text", "text": "試している声だった。意地悪ではない。確かめている。蓮くんの「きれいだ」は、本物か。"}, {"id": "ch04-s06-p048", "type": "text", "text": "「……たぶん」"}, {"id": "ch04-s06-p049", "type": "text", "text": "天城さんが笑った。"}, {"id": "ch04-s06-p050", "type": "text", "text": "大きな笑いではなかった。口元だけが先に動いて、目が追いかけた。いつもは顔全体で笑う人だった。今は灯籠の光の中で、静かに笑っていた。"}, {"id": "ch04-s06-p051", "type": "text", "text": "「まだそこだよね」"}, {"id": "ch04-s06-p052", "type": "text", "text": "怒っていない。落胆もしていない。天城さんはその場所を知っている。俺がまだそこにいることを、観測し続けている。"}, {"id": "ch04-s06-p053", "type": "text", "text": "「でも、たぶんって言えるようになったじゃん」"}, {"id": "ch04-s06-p054", "type": "text", "text": "わたあめの棒が空になっていた。天城さんがそれをポケットにしまった。ゴミ箱が近くにあるのに、棒をしまった。わたあめの紙の包みをポケットにしまったすみれと、同じ動作だった。理由は違う。"}, {"id": "ch04-s06-p055", "type": "text", "text": "灯籠通りを戻りながら、鳩尾の下がゆるんでいた。悪くない、の一歩先。まだ名前はない。ないけれど、天城さんの静かな笑い方を覚えておこうと思った。昼間とは別の天城さん。灯籠の光の中にだけいる天城さん。"}, {"id": "ch04-s06-p056", "type": "divider", "text": "---"}, {"id": "ch04-s06-p057", "type": "text", "text": "### 選択: 鳴海さんと歩く"}, {"id": "ch04-s06-p058", "type": "text", "text": "鳴海さんの方に歩き出した。"}, {"id": "ch04-s06-p059", "type": "text", "text": "灯籠通りの中ほど。風祭さんが先に俺に気づいた。一瞬だけ目が鋭くなり、半秒で戻った。鳴海さんが振り返る。"}, {"id": "ch04-s06-p060", "type": "text", "text": "「あ、朝霧さん」"}, {"id": "ch04-s06-p061", "type": "text", "text": "穏やかな微笑み。けれど声の立ち上がりが遅かった。公演の後、まだ喉が戻りきっていない。"}, {"id": "ch04-s06-p062", "type": "text", "text": "風祭さんが鳴海さんの肩にぽんと手を置いた。「あたし、ちょっとお手洗い行ってくるね」。作った口実ではないのかもしれない。作った口実なのかもしれない。風祭さんの判断はいつも速い。"}, {"id": "ch04-s06-p063", "type": "text", "text": "鳴海さんと二人になった。灯籠通りを並んで歩いた。鳴海さんの歩幅がいつもより小さい。カーディガンの袖から指先だけが出ている。"}, {"id": "ch04-s06-p064", "type": "text", "text": "「今日、聴いてくれましたか？」"}, {"id": "ch04-s06-p065", "type": "text", "text": "鳴海さんの声が灯籠の光の中に落ちた。確認する声ではなかった。聴いていてほしかった、という声だった。"}, {"id": "ch04-s06-p066", "type": "text", "text": "「はい」"}, {"id": "ch04-s06-p067", "type": "text", "text": "間を空けた。"}, {"id": "ch04-s06-p068", "type": "text", "text": "「……きれいでした」"}, {"id": "ch04-s06-p069", "type": "text", "text": "言葉を選んだのではない。あの歌を聴いて体の中に残ったものを、出力できる語彙の中から探したら、それしかなかった。"}, {"id": "ch04-s06-p070", "type": "text", "text": "鳴海さんの足が止まった。"}, {"id": "ch04-s06-p071", "type": "text", "text": "微笑みの形が変わった。いつもの穏やかな微笑みには壁がある。口元と目が同時に動くけれど、その奥に何か一枚挟まっている。今、その一枚が下がった。口が開いた。歯が見えた。風祭さんの前で見せていた、あの一段壁が低い笑顔。"}, {"id": "ch04-s06-p072", "type": "text", "text": "「……ありがとうございます。それが、一番嬉しいです」"}, {"id": "ch04-s06-p073", "type": "text", "text": "声が震えていなかった。疲れは残っている。けれど嬉しい、という音は真っ直ぐだった。"}, {"id": "ch04-s06-p074", "type": "text", "text": "薄桃色のリボンが灯籠の紫の光を受けて、わずかに色を変えていた。桜色と紫の中間の、名前のない色になっていた。"}, {"id": "ch04-s06-p075", "type": "text", "text": "鳴海さんが歩き始めた。歩幅は変わらなかった。小さいまま。けれど一歩ごとの間隔がわずかに短くなっていた。"}, {"id": "ch04-s06-p076", "type": "text", "text": "並んで灯籠通りを歩いた。三ミリ。あの角度調整と同じ場所から、何かが来ていた。仕事ではない。仕事ではないものが、音響盤のつまみを回した時と同じ手の温度で、胸の中にある。言葉が見つからなかった。見つからないまま、灯籠の光が二人の影を煉瓦の上に落としていた。"}, {"id": "ch04-s06-p077", "type": "divider", "text": "---"}, {"id": "ch04-s06-p078", "type": "text", "text": "### 選択: 篠宮さんを探す"}, {"id": "ch04-s06-p079", "type": "text", "text": "篠宮さんの姿を探した。"}, {"id": "ch04-s06-p080", "type": "text", "text": "灯籠通りにはいない。出店の周囲にもいない。祭りの喧騒の中に篠宮さんの小柄な影を見つけるのは難しいが、そもそも篠宮さんがこの密度の中にいるとは思えなかった。"}, {"id": "ch04-s06-p081", "type": "text", "text": "図書館の方角に足を向けた。"}, {"id": "ch04-s06-p082", "type": "text", "text": "図書館は閉まっていた。正面扉に「残響祭期間中は閉館」の札。けれど建物の前にベンチがある。そこに、人影があった。"}, {"id": "ch04-s06-p083", "type": "text", "text": "篠宮さんだった。"}, {"id": "ch04-s06-p084", "type": "text", "text": "ベンチの右端に座っている。背筋は真っ直ぐ。膝の上にメモ帳が乗っている。ペンを右手に持っている。ただし、メモ帳は閉じていた。ペンの先は紙に触れていなかった。"}, {"id": "ch04-s06-p085", "type": "text", "text": "ここからでも残響桜のライトアップが見えた。中庭の老木の薄紫の光が、図書館の壁に淡い影を落としている。篠宮さんはそれを見ていた。メモ帳を膝に置いたまま、記録せずに。"}, {"id": "ch04-s06-p086", "type": "text", "text": "「篠宮さん」"}, {"id": "ch04-s06-p087", "type": "text", "text": "声をかけた。篠宮さんの瞬きが一度止まり、こちらを向いた。"}, {"id": "ch04-s06-p088", "type": "text", "text": "「朝霧さん」"}, {"id": "ch04-s06-p089", "type": "text", "text": "声に驚きはなかった。俺が来たことを意外とも思っていないようだった。"}, {"id": "ch04-s06-p090", "type": "text", "text": "「隣、いいですか」"}, {"id": "ch04-s06-p091", "type": "text", "text": "篠宮さんが小さく頷いた。ベンチの左端に座った。間に一人分の空間。"}, {"id": "ch04-s06-p092", "type": "text", "text": "ライトアップの光が静かに揺れていた。風が残響灯を揺らし、光の粒が動き、壁の影が波のように揺れる。祭りの音は遠い。図書館前は灯籠通りから一本奥に入った場所で、人の声は壁と距離に削られて輪郭を失っている。"}, {"id": "ch04-s06-p093", "type": "text", "text": "篠宮さんが口を開いた。"}, {"id": "ch04-s06-p094", "type": "text", "text": "「こういう時間も、記録すべきでしょうか」"}, {"id": "ch04-s06-p095", "type": "text", "text": "メモ帳に目を落としていた。閉じたメモ帳。ペンは右手にある。開けばすぐに書ける状態にしている。けれど開いていない。"}, {"id": "ch04-s06-p096", "type": "text", "text": "「記録しなくていい時間があってもいいんじゃないですか」"}, {"id": "ch04-s06-p097", "type": "text", "text": "篠宮さんの瞬きが長かった。二秒か三秒、目を閉じていた。開いた時、墨色の瞳の焦点がほんのわずか遠くにずれていた。ライトアップの光を見ている。記録するためではなく。"}, {"id": "ch04-s06-p098", "type": "text", "text": "篠宮さんの右手がゆっくり動き、ペンをメモ帳の横に置いた。膝の上から、ベンチの座面に。ペンが木の板に触れて、かすかな音を立てた。"}, {"id": "ch04-s06-p099", "type": "text", "text": "黙ったまま、二人でライトアップを見た。"}, {"id": "ch04-s06-p100", "type": "text", "text": "薄紫の光が図書館の白い壁に映り、ゆっくりと揺れている。風が通るたびに光の形が変わる。同じ形は二度来ない。記録できない。記録できないものを、篠宮さんは記録せずに見ていた。"}, {"id": "ch04-s06-p101", "type": "text", "text": "ペンを置いた篠宮さんの右手が、膝の上に戻っていた。指が組まれている。力は入っていない。"}, {"id": "ch04-s06-p102", "type": "text", "text": "ペンを持たない篠宮さんの手が、膝の上で静かに重なっていた。記録しない時間の中に二人で座っている。インクの匂いも紙の音もしない。ただ光が揺れている。その静けさの中に、記録室のペンの音が二つ重なっていた時と同じ種類の体の楽さがあった。"}, {"id": "ch04-s06-p103", "type": "divider", "text": "---"}, {"id": "ch04-s06-p104", "type": "text", "text": "### 選択: 霜月さんのところへ行く"}, {"id": "ch04-s06-p105", "type": "text", "text": "鐘鋳塔の方角に足を向けた。"}, {"id": "ch04-s06-p106", "type": "text", "text": "灯籠通りの光が背中に遠ざかる。出店の匂いが薄くなる。人の声が減る。石壁が近づくにつれて音が削られ、足音が自分のものだけになった。"}, {"id": "ch04-s06-p107", "type": "text", "text": "塔の入口付近。白いコートが見えた。"}, {"id": "ch04-s06-p108", "type": "text", "text": "霜月さんは入口の右側、石壁に背を預けて立っていた。腕は組んでいない。コートのポケットにも手を入れていない。両腕を体の横に下ろし、上を向いていた。"}, {"id": "ch04-s06-p109", "type": "text", "text": "夜空を見ていた。"}, {"id": "ch04-s06-p110", "type": "text", "text": "仕事の姿勢ではなかった。管理室で計器を見る時の霜月さんには、肩と首に力が入っている。今は力が抜けていた。白いコートの襟元が緩んでいて、首筋が見えていた。銀髪のハーフアップが夜風に微かに揺れている。"}, {"id": "ch04-s06-p111", "type": "text", "text": "「霜月さんも、祭りは見ないんですか」"}, {"id": "ch04-s06-p112", "type": "text", "text": "声をかけた。霜月さんの視線が降りてきた。青紫色の瞳が俺を見た。光の少ない場所だった。瞳の色が紫寄りに沈んでいる。"}, {"id": "ch04-s06-p113", "type": "text", "text": "「……見ている。ここから」"}, {"id": "ch04-s06-p114", "type": "text", "text": "短い返答。視線が再び空に戻った。"}, {"id": "ch04-s06-p115", "type": "text", "text": "俺も上を見た。鐘鋳塔の上方に夜空が広がっている。星が出ていた。祭りの灯りが届かないこの場所は、灯籠通りより星がよく見えた。"}, {"id": "ch04-s06-p116", "type": "text", "text": "遠くから祭りの音が聞こえる。弦楽器の旋律。人の声。笑い声。全てが石壁の向こうにある。ここは祭りの外だった。霜月さんは祭りの外から、夜空を見ていた。"}, {"id": "ch04-s06-p117", "type": "text", "text": "左耳の青い石のピアスが目に入った。残響灯の光が届かない場所なのに、星の光だけで石が微かに光っている。"}, {"id": "ch04-s06-p118", "type": "text", "text": "隣に立った。"}, {"id": "ch04-s06-p119", "type": "text", "text": "霜月さんは追い払わなかった。視線は空に向いたまま。俺の存在を許容している。それだけだった。拒絶しないことが、霜月さんの中では何かを意味しているのかもしれない。"}, {"id": "ch04-s06-p120", "type": "text", "text": "「星は予測通りに動く」"}, {"id": "ch04-s06-p121", "type": "text", "text": "霜月さんの声が低かった。夜の空気に溶ける声。"}, {"id": "ch04-s06-p122", "type": "text", "text": "「あの星座が今の位置にあることは、三ヶ月前に計算で出せた。祭りの人間は出店の灯りを見ている。私は計算通りの星を見ている。どちらも見上げている。それだけの違いだ」"}, {"id": "ch04-s06-p123", "type": "text", "text": "それだけの違い。霜月さんはそう言ったが、その声は計器の報告をする声とは質が違っていた。"}, {"id": "ch04-s06-p124", "type": "text", "text": "俺は何も言わなかった。霜月さんの隣に立って、同じ空を見た。星の名前はわからない。配置を計算で出すこともできない。ただ、鐘鋳塔の石壁の冷たさが背中に触れていて、遠くから祭りの音が聞こえていて、霜月さんが隣にいた。"}, {"id": "ch04-s06-p125", "type": "text", "text": "「朝霧」"}, {"id": "ch04-s06-p126", "type": "text", "text": "「はい」"}, {"id": "ch04-s06-p127", "type": "text", "text": "「……報告書は明日でいい」"}, {"id": "ch04-s06-p128", "type": "text", "text": "声が少しだけ柔らかかった。少しだけ。霜月さんの基準で。"}, {"id": "ch04-s06-p129", "type": "text", "text": "背中の石壁が冷たかった。冷たくて、硬くて、動かない。祭りの外にいる。それが今夜は正しい場所にいるという感覚だった。言葉にすると壊れそうな何かが、石壁と星空と霜月さんの沈黙の間にあった。"}, {"id": "ch04-s06-p130", "type": "divider", "text": "---"}, {"id": "ch04-s06-p131", "type": "text", "text": "灯籠通りの光が、遠くで揺れていた。"}, {"id": "ch04-s06-p132", "type": "text", "text": "中庭に戻り、残響桜の老木の下に立った。薄紫の光が上から降りてくる。散り残った花弁が残響灯に照らされ、ゆっくりと一枚、落ちてきた。掌の上に乗った。重さはない。紫がかった白。光が消えると、ただの花弁だった。"}, {"id": "ch04-s06-p133", "type": "text", "text": "祭りの一日が終わろうとしている。"}, {"id": "ch04-s06-p134", "type": "text", "text": "朝から出店を回り、串焼きを食べ、図書館で展示を見て、舞台裏で音響を確認し、響弦館で歌を聴き、鐘鋳塔ですみれにどら焼きを渡し、ライトアップの下を歩いた。"}, {"id": "ch04-s06-p135", "type": "text", "text": "「悪くない」と言える。"}, {"id": "ch04-s06-p136", "type": "text", "text": "まだそこか、と天城さんなら笑うだろう。けれど今日の「悪くない」は、昨日までの「悪くない」とは少し違う。違いの正体がまだ言葉になっていないだけで、体のどこかには既にある。鳩尾の下か。背骨の裏か。名前がない場所に、名前がないものがある。"}, {"id": "ch04-s06-p137", "type": "text", "text": "掌の上の花弁を、指で摘んでコートのポケットに入れた。理由はわからない。覚えておく。この夜のことを。"}]}, {"chapter": 4, "chapterTitle": "残響祭の灯り", "scene": 7, "sceneTitle": "楽しかった、のだろうか", "wordCount": "約4,000字", "paragraphs": [{"id": "ch04-s07-p001", "type": "text", "text": "補佐官舎の玄関を開けると、静寂が待っていた。"}, {"id": "ch04-s07-p002", "type": "text", "text": "祭りの音はここまで届かない。教室棟の裏の小さな平屋は、中庭とも灯籠通りとも石壁二枚ぶん離れている。扉を閉めた瞬間に、弦楽器の旋律も笑い声も断たれた。残ったのは自分の呼吸と、靴を脱ぐ音だけだった。"}, {"id": "ch04-s07-p003", "type": "text", "text": "靴を揃えて上がる。廊下の裸電球が黄色い光を落としている。台所は使っていない。朝、水を一杯飲んでそのまま出た。流しに置きっぱなしのコップが一つ。夕食は出店の串焼きと蒸し饅頭で済ませたから、今日は一度も台所の火を使わなかった。"}, {"id": "ch04-s07-p004", "type": "text", "text": "部屋に入った。六畳。ベッド。机。棚。窓。それだけの空間。監視哨の二段ベッドとロッカーひとつよりは広い。広いが、今夜はいつもより広く感じた。さっきまで人が多い場所にいたからだろう。人の密度が体に残っていて、この部屋の密度との差が壁の距離を引き延ばしている。"}, {"id": "ch04-s07-p005", "type": "text", "text": "制服のジャケットを脱いだ。椅子の背にかけた。シャツのボタンを上から順に外していく。コートのポケットに手を入れた時、指先に触れるものがあった。"}, {"id": "ch04-s07-p006", "type": "text", "text": "花弁だった。"}, {"id": "ch04-s07-p007", "type": "text", "text": "残響桜の、散り残った一枚。薄紫がかった白。ライトアップの下で掌に落ちてきたものを、ポケットに入れた。覚えている。なぜ入れたのかは、まだわからない。"}, {"id": "ch04-s07-p008", "type": "text", "text": "指の腹で花弁を挟んだ。薄い。重さがない。残響灯の光で発光して見えたのが嘘のように、裸電球の下ではただの乾きかけた花弁だった。机の上に置いた。明日になったら完全に乾いているだろう。"}, {"id": "ch04-s07-p009", "type": "text", "text": "寝間着に着替え、歯を磨き、顔を洗った。洗面台の鏡に自分の顔が映る。暗い灰青色の短髪。濃い紺色の目。額の左側の傷跡は前髪に隠れている。いつもと同じ顔だった。祭りの一日を過ごした顔と、昨日の顔の区別がつかない。"}, {"id": "ch04-s07-p010", "type": "text", "text": "ベッドに横になった。"}, {"id": "ch04-s07-p011", "type": "text", "text": "天井を見る。白い天井。塗り壁の凹凸が影を作っている。見慣れた天井だった。毎朝、ここから一日が始まる。四月の最初の朝、布団の中で目を覚ました時もこの天井を見ていた。"}, {"id": "ch04-s07-p012", "type": "text", "text": "あの朝、俺は思った。温かい布団から出たくない、と。たぶん、そう思うのが正しいから。温かいと感じているのか、温かいはずだと判断しているだけなのか。その境目が曖昧だった。"}, {"id": "ch04-s07-p013", "type": "text", "text": "今、同じ布団の中にいる。背中がシーツに触れている。五月下旬の夜は四月より暖かくなっていて、掛布団は薄い一枚に替えてある。暖かい。暖かいと判断しているのか、暖かいと感じているのか。"}, {"id": "ch04-s07-p014", "type": "text", "text": "どちらでもいい、と思った。"}, {"id": "ch04-s07-p015", "type": "text", "text": "考えても仕方がない、ではなかった。どちらでもいい。暖かいことに変わりがないから。四月の朝にはなかった結論が、体の中にあった。いつから変わったのか特定はできない。"}, {"id": "ch04-s07-p016", "type": "text", "text": "目を閉じた。まぶたの裏に、今日一日が再生され始めた。"}, {"id": "ch04-s07-p017", "type": "text", "text": "朝の中庭。出店の匂いの種類が多すぎて分けられなかった。天城さんに手首を引かれて灯籠通りに入った。指は三歩で離れた。焼き菓子を食べた。串焼きを食べた。天城さんが「楽しい？」と聞き、俺は「悪くない」と答えた。天城さんは「まだそこだよね」と笑った。怒ってはいなかった。落胆もしていなかった。観測の声だった。"}, {"id": "ch04-s07-p018", "type": "text", "text": "図書館に行った。篠宮さんの展示があった。三面の衝立。消滅した場所の記録。下半分のリストに俺が清書した字があった。篠宮さんの字より少し大きくて角ばっている。あの字が展示の中にあった。「お待ちしています」の語尾が長かった。"}, {"id": "ch04-s07-p019", "type": "text", "text": "響弦館の舞台裏で音響盤のつまみを確認した。天吊り拡声器の角度を三ミリ調整した。マニュアルの許容範囲内の調整。けれど、あの三ミリは仕事だからではなかった。鳴海さんの歌が一番よく届く角度を出したかった。"}, {"id": "ch04-s07-p020", "type": "text", "text": "鳴海さんが歌った。八百席の響弦館が水に沈んだ。音が空気を変えた。「きれいだ」と思った。体の反応と思考の隙間がなかった。涙は出なかった。目の奥が熱くなったのに、形にならなかった。天城さんは泣いていた。俺は泣けなかった。"}, {"id": "ch04-s07-p021", "type": "text", "text": "鐘鋳塔に行った。霜月さんと点検をした。第九層の3番管のボルトを増し締めした。業務報告の声で数値を伝え、霜月さんは図面から目を上げずに「問題ない」と言った。祭りの日も、塔の中は変わらなかった。"}, {"id": "ch04-s07-p022", "type": "text", "text": "天蓋の間ですみれに会った。窓の外の祭りを、音のない映像として見ていた。どら焼きを渡した。すみれが「おいしい」と言った。目と口が同時に動いた。紙の包みをポケットにしまった。「また持ってきてね」と言われた。"}, {"id": "ch04-s07-p023", "type": "text", "text": "夜。灯籠通りのライトアップ。残響灯の薄紫の光が散り残った花弁を照らしていた。灯籠の紫の笠が煉瓦に影を落としていた。誰かと歩いた。灯りの中で声を聞いた。鳩尾の下に何かがあった。悪くない、とは違う何か。名前がない。けれど体のどこかにはあった。"}, {"id": "ch04-s07-p024", "type": "text", "text": "花弁をポケットに入れた。理由はわからなかった。"}, {"id": "ch04-s07-p025", "type": "text", "text": "一日が巡り終わる。まぶたの裏の映像が止まった。"}, {"id": "ch04-s07-p026", "type": "text", "text": "——楽しかった、のだろうか。"}, {"id": "ch04-s07-p027", "type": "text", "text": "体に聞いてみる。"}, {"id": "ch04-s07-p028", "type": "text", "text": "鳩尾の下。今日、何度も反応した場所。朝、天城さんと出店を回っている時にいつの間にか緩んでいた。響弦館で鳴海さんの歌を聴いた時は奥の方が溶けた。鐘鋳塔ですみれが目と口を同時に動かして笑った時にも少し緩んだ。夜、灯りの中を歩いた時も。"}, {"id": "ch04-s07-p029", "type": "text", "text": "今は緩んでいない。今は布団の中にいるだけだ。けれど、緩んでいた記憶が体に残っている。筋肉がほどけた痕のようなもの。使った筋肉が翌日に疲労で報告してくるのと似ている。鳩尾の下が「今日は何度も動いた」と報告している。"}, {"id": "ch04-s07-p030", "type": "text", "text": "目の奥。鳴海さんの歌の時に熱くなった場所。涙にはならなかった。今も熱くはない。けれど、あの熱があったことは否定できない。音が体を通り抜けて、何かに触れた。触れたものが反応した。管は詰まったままだが、管の向こうに水があることだけは確認できた。"}, {"id": "ch04-s07-p031", "type": "text", "text": "背中。夜の空の下で石壁に預けた冷たさ。嫌ではなかった。祭りの外にいることが正しい場所にいる感覚だった。あれは誰かの隣にいたからそう思えたのか、場所自体がそうだったのか。分離できない。"}, {"id": "ch04-s07-p032", "type": "text", "text": "手。今日、手で触れたものが多かった。天城さんのわたあめの砂糖の繊維。串焼きの竹串。どら焼きの紙の包み。音響盤のつまみ。共鳴管のボルト。掌の上に落ちた花弁の薄さ。手は一日中、何かに触れていた。監視哨にいた頃の手は、双眼鏡の接眼レンズと銃の握りと記録用紙のクリップボードにしか触れなかった。触れるものの種類が増えている。"}, {"id": "ch04-s07-p033", "type": "text", "text": "左手首のブレスレットに指が触れた。"}, {"id": "ch04-s07-p034", "type": "text", "text": "毎晩やっている。朝も。理由はわからない。けれど今夜は、編み目の革の手触りの上に、今日触れたものの感触が重なった。砂糖の甘さが溶けた後の指先。紙の包みの角を折った時の指の腹。花弁を摘んだ時の親指と人差し指の距離。一日ぶんの感触が、ブレスレットの編み目の中に沈んでいくような気がした。"}, {"id": "ch04-s07-p035", "type": "text", "text": "革紐から指を離した。"}, {"id": "ch04-s07-p036", "type": "text", "text": "楽しかった、のだろうか。"}, {"id": "ch04-s07-p037", "type": "text", "text": "もう一度問う。体は何と答えているか。"}, {"id": "ch04-s07-p038", "type": "text", "text": "鳩尾の下は報告している。目の奥は報告している。背中は報告している。手は報告している。報告は全て受領した。報告の内容に矛盾はない。嫌だったもの、苦痛だったものは一つもない。全てが「悪くなかった」の上にある。"}, {"id": "ch04-s07-p039", "type": "text", "text": "ただ、「悪くなかった」では足りない。"}, {"id": "ch04-s07-p040", "type": "text", "text": "足りないことに気づいている。足りない、という感覚自体が新しい。四月の朝の俺は、「温かいはずだ」を「温かい」と呼べなかった。今の俺は、「悪くない」を「悪くない」のまま終わらせることに、何かが引っかかっている。もっと正確な言葉があるはずだ、と体が言っている。"}, {"id": "ch04-s07-p041", "type": "text", "text": "一日を分解しようとした。"}, {"id": "ch04-s07-p042", "type": "text", "text": "どの瞬間が楽しかったのか。天城さんと出店を回った時か。篠宮さんの展示を見た時か。鳴海さんの歌を聴いた時か。霜月さんと塔を点検した時か。すみれにどら焼きを渡した時か。夜、灯りの中を歩いた時か。"}, {"id": "ch04-s07-p043", "type": "text", "text": "分解できなかった。"}, {"id": "ch04-s07-p044", "type": "text", "text": "どこか一箇所を取り出して「ここが楽しかった」と指させない。一日が一つの塊になっていて、切り分けると意味が変わってしまう。串焼きだけを取り出しても「楽しい」にはならない。展示だけを取り出しても足りない。歌だけでも、点検だけでも、どら焼きだけでも。全部が繋がっていて、繋がったまま体の中にある。"}, {"id": "ch04-s07-p045", "type": "text", "text": "分解できないこと自体が、何かの証拠ではないか。"}, {"id": "ch04-s07-p046", "type": "text", "text": "「悪くない」は分解できる。串焼きは悪くない。展示は悪くない。歌は悪くない。個別に評価できる。けれど今日の一日を「悪くない」の集合体として処理しようとすると、合計が個別の総和を超えている。超えた分が何なのか。超えた分に名前がある。"}, {"id": "ch04-s07-p047", "type": "text", "text": "楽しかった。"}, {"id": "ch04-s07-p048", "type": "text", "text": "その言葉が、浮かんだ。"}, {"id": "ch04-s07-p049", "type": "text", "text": "考えて選んだのではなかった。鳩尾の下と目の奥と背中と手の報告を全て受領して、全体を眺めた時に、体の底から上がってきた。水面に浮かぶ泡のように。押し出したのではない。自然に上がってきた。"}, {"id": "ch04-s07-p050", "type": "text", "text": "楽しかった。たぶん。"}, {"id": "ch04-s07-p051", "type": "text", "text": "「たぶん」がつく。つくけれど、今までの「たぶん」とは違う。四月の朝の「たぶん」は、温かいかどうかわからなくて付けた「たぶん」だった。判断がつかないから保留する「たぶん」。今の「たぶん」は、楽しかったことはわかっている。わかった上で、それが本当に自分の感情なのか、最後の一歩だけ確認が取れない。否定する余地ではなく、確認の余地。壁はまだある。けれどあの四月の朝の壁より、ずいぶん薄くなっている。"}, {"id": "ch04-s07-p052", "type": "text", "text": "「楽しかった。たぶん」"}, {"id": "ch04-s07-p053", "type": "text", "text": "声に出した。布団の中で、天井に向かって。自分の声が部屋の壁に当たって消えた。誰も聞いていない。聞かせる相手もいない。けれど、口から出た音は確かに「楽しかった」の形をしていた。"}, {"id": "ch04-s07-p054", "type": "text", "text": "天城さんがいたら笑うだろう。「まだ『たぶん』がつくんだ」と。でも天城さんは怒らない。「言えたじゃん」と言うだろう。観測の声で。"}, {"id": "ch04-s07-p055", "type": "text", "text": "明日、天城さんに言うかどうかは、まだわからない。言わなくてもいい。言えたことが、今は十分だった。"}, {"id": "ch04-s07-p056", "type": "text", "text": "目を閉じた。"}, {"id": "ch04-s07-p057", "type": "text", "text": "まぶたの裏は暗かった。祭りの残像はもう消えていた。残響灯の紫の光も、灯籠通りの影も、残響桜の花弁も。全部消えて、暗い。けれど暗さが嫌ではなかった。明日もこの天井から一日が始まる。明日は祭りではない普通の日で、管理室の計器を見て、記録室でペンを持って、食堂で定食を食べる。それだけの日。"}, {"id": "ch04-s07-p058", "type": "text", "text": "それだけの日を、悪くないと思える。"}, {"id": "ch04-s07-p059", "type": "text", "text": "その先に、いつか、「たぶん」の取れた「楽しかった」がある。まだ遠い。遠いけれど、今夜、一歩だけ近づいた。"}, {"id": "ch04-s07-p060", "type": "text", "text": "布団の中が温かかった。五月の夜の温もり。体温と、シーツの繊維と、掛布団の薄い重みと。温かい。温かいと感じている。判断ではなく。"}, {"id": "ch04-s07-p061", "type": "text", "text": "机の上に、花弁が一枚、置いてある。"}, {"id": "ch04-s07-p062", "type": "text", "text": "目を閉じたまま、その花弁の場所がわかった。視界にはない。見えていない。けれど、あそこにある。今日の一日が凝縮された薄紫の一枚が。"}, {"id": "ch04-s07-p063", "type": "text", "text": "眠りが近づいてくる。意識の輪郭がゆっくりと曖昧になっていく。最後に残ったのは、鳩尾の下の、今日何度も動いた場所の、動いた痕だった。"}, {"id": "ch04-s07-p064", "type": "text", "text": "楽しかった。"}, {"id": "ch04-s07-p065", "type": "text", "text": "たぶん。"}]}, {"chapter": 5, "chapterTitle": "夏の入り口", "scene": 1, "sceneTitle": "梅雨の機構室", "wordCount": "約6,000字", "paragraphs": [{"id": "ch05-s01-p001", "type": "text", "text": "六月に入って、空気が重くなった。"}, {"id": "ch05-s01-p002", "type": "text", "text": "鐘鋳塔の地下一階に降りる階段を踏みながら、それを足裏で感じた。四月の冷えた石の感触ではなく、石の表面にうっすらと水気が乗っている。滑らないように踵から置く。壁面の残響灯が青白い光を落としている。その光が、普段より膨らんで見えた。湿気が光を散らしている。"}, {"id": "ch05-s01-p003", "type": "text", "text": "九時五十分。梅雨の定期点検。五月の残響祭が終わってから二週間と少し。鐘鋳塔の日常は変わらず続いていて、しかし季節だけが進んでいた。残響桜の花弁はとうに散り、中庭の木々は濃い緑に変わり、空は灰色の日が増えた。"}, {"id": "ch05-s01-p004", "type": "text", "text": "地下一階の通路に出る。空気が一段階、湿っている。金属と潤滑油と湿った石の匂い。四月に初めてここに降りた日と同じ匂いのはずだったが、水の気配が一つ加わっていた。石壁の継ぎ目に目を凝らすと、目に見えないほどの結露が表面にあった。指先で触れる。冷たく、わずかに濡れた。"}, {"id": "ch05-s01-p005", "type": "text", "text": "機構室の鉄扉を開ける。鍵はもう、手探りで選べるようになっていた。真鍮の丸頭鍵、C-03。回す。錠前が外れる音が通路に反響して消えた。"}, {"id": "ch05-s01-p006", "type": "text", "text": "扉を押し開ける。"}, {"id": "ch05-s01-p007", "type": "text", "text": "歯車が、呼吸していた。"}, {"id": "ch05-s01-p008", "type": "text", "text": "壁一面の歯車群。二ヶ月前と同じ配置。同じ大きさ。同じ噛み合わせ。けれど微細な回転音の中に、きしむような倍音が混じっていた。湿気だ。金属の表面に水分が付着すると、歯の噛み合いの摩擦が変わる。潤滑油の膜が水気を吸って粘度が上がり、歯車の回転が微妙に鈍くなる。数値にすれば0.01パーセント以下の変化だろう。けれど耳に届く音が違った。"}, {"id": "ch05-s01-p009", "type": "text", "text": "六月の機構室は、息が詰まっている。"}, {"id": "ch05-s01-p010", "type": "text", "text": "携帯灯を点ける。作業用の工具袋を肩にかけ直して、まず歯車の壁面を目視した。四月の着任から毎週繰り返してきた手順。しかし梅雨の時期は点検頻度が週二回に上がる。湿気は歯車の摩耗を早め、共鳴管の内壁に水滴を生じさせ、音響増幅器の出力を揺らす。マニュアルに「梅雨期特別対応」という章がある。最初に読んだ時、その章だけ紙が波打っていた。過去に何度も、湿った手で捲られた証拠。"}, {"id": "ch05-s01-p011", "type": "text", "text": "歯車のグリスアップから始めた。"}, {"id": "ch05-s01-p012", "type": "text", "text": "古いグリスを布で拭い、新しいグリスを塗る。歯面の一枚ずつに、薄く、均一に。厚すぎれば回転に抵抗が生まれ、薄すぎれば防錆の効果が落ちる。ちょうどいい量を、指先が知っていた。考えるのではなく、手が判断している。親指と人差し指の間に挟んだグリスの粘りを感じて、「これでいい」と手が言う。"}, {"id": "ch05-s01-p013", "type": "text", "text": "この感覚には慣れた。四月の頃は不思議だった。誰にも教わっていないのに手が先に動く。今は不思議さの輪郭が少し薄れて、代わりに安心がある。歯車に触れている時の安心は、食堂で天城さんの声を聞いている時の安心とも、記録室で篠宮さんの隣でペンを持っている時の安心とも違う。もっと古い。自分の奥の、名前のない場所に根を張っている。"}, {"id": "ch05-s01-p014", "type": "text", "text": "三番歯車のグリスアップを終えた時、機構室の空気に変化があった。"}, {"id": "ch05-s01-p015", "type": "text", "text": "温度が一度、下がった気がした。"}, {"id": "ch05-s01-p016", "type": "text", "text": "「朝霧。進捗は」"}, {"id": "ch05-s01-p017", "type": "text", "text": "振り返らずに答えた。声でわかる。"}, {"id": "ch05-s01-p018", "type": "text", "text": "「一番から三番歯車のグリスアップを完了しました。四番以降はこれからです」"}, {"id": "ch05-s01-p019", "type": "text", "text": "霜月さんの靴音が石の床を叩く。小さく、一定のリズムで。白いコートの裾が視界の端を横切った。潤滑油と石の匂いの中に、紙と金属洗浄剤の淡い匂いが一瞬混ざった。二ヶ月間ずっと同じ匂い。この人は香水を使わない。"}, {"id": "ch05-s01-p020", "type": "text", "text": "「共鳴管の結露を確認する。増幅器は後回し」"}, {"id": "ch05-s01-p021", "type": "text", "text": "「わかりました」"}, {"id": "ch05-s01-p022", "type": "text", "text": "霜月さんは共鳴管の列に向かった。天井から垂直に降りる金属管の接合部に検査灯を当て、内壁を覗き込む。銀色の髪が管の縁にかかる。四月にも同じ光景を見た。あの時と同じだ。動作に迷いがない。一つの管を確認して、次の管に移る。その間に言葉はない。"}, {"id": "ch05-s01-p023", "type": "text", "text": "俺は四番歯車の古いグリスを拭い始めた。"}, {"id": "ch05-s01-p024", "type": "text", "text": "並行作業。二ヶ月前と同じ構図。けれど二ヶ月前より、隣にいる人の呼吸の間隔がわかるようになっていた。霜月さんは検査灯を管の中に差し入れる時に息を止め、引き抜く時に静かに吐く。それを毎回繰り返す。精密な作業をする人の呼吸パターン。俺もグリスを塗る時に似た呼吸をしている。"}, {"id": "ch05-s01-p025", "type": "text", "text": "無言の作業が続いた。歯車の擦れる微細な音と、工具が金属に触れる音と、二人の呼吸だけが機構室を満たしていた。"}, {"id": "ch05-s01-p026", "type": "text", "text": "六番歯車まで進んだところで、共鳴管の接合部に取りかかった。梅雨期はボルトの緩みが起きやすい。金属の膨張収縮が日ごとの温度差で繰り返されるからだ。レンチを当て、規定トルクを確認していく。一本目、正常。二本目、正常。三本目——わずかに緩い。増し締め。締める時の手首の角度を、自分で意識していなかった。レンチを握った手が、締めすぎない角度で止まる。継手の素材がこの年代の残響金属であること、残響金属のボルトはトルクをかけすぎると微細な亀裂が入ること。それを知っている。知識としてではなく、手首と指先の感覚として。"}, {"id": "ch05-s01-p027", "type": "text", "text": "「朝霧」"}, {"id": "ch05-s01-p028", "type": "text", "text": "霜月さんの声が、作業の合間に落ちてきた。"}, {"id": "ch05-s01-p029", "type": "text", "text": "「はい」"}, {"id": "ch05-s01-p030", "type": "text", "text": "顔を上げた。霜月さんは二メートルほど離れた位置に立っていた。手には検査灯。青白い残響灯の光の中で、ラベンダーの瞳がこちらを見ていた。正確に言えば、俺の手元を見ていた。レンチを握った右手と、継手と、ボルトの締め具合を。"}, {"id": "ch05-s01-p031", "type": "text", "text": "「……その継手の締め方、誰に教わった」"}, {"id": "ch05-s01-p032", "type": "text", "text": "声に抑揚がなかった。質問の形をしているが、どこか確認のような響きがあった。数値を照合する時の声と同じ。"}, {"id": "ch05-s01-p033", "type": "text", "text": "「誰にも。手が覚えている、という感じです」"}, {"id": "ch05-s01-p034", "type": "text", "text": "正直に答えた。それ以外の答え方を知らない。教わった記憶がない。二年前以前の記憶がないのだから。"}, {"id": "ch05-s01-p035", "type": "text", "text": "霜月さんの目が、一瞬だけ鋭くなった。"}, {"id": "ch05-s01-p036", "type": "text", "text": "瞳の中の光が動いた。それは怒りではなかった。何かを検索している目だった。俺の答えと、霜月さんが持っている何かの知識を突き合わせようとしている。データの照合。霜月さんがいつもやっていること。"}, {"id": "ch05-s01-p037", "type": "text", "text": "その眼差しは二秒ほど続いて、消えた。"}, {"id": "ch05-s01-p038", "type": "text", "text": "「……問題ない。続けなさい」"}, {"id": "ch05-s01-p039", "type": "text", "text": "それだけだった。"}, {"id": "ch05-s01-p040", "type": "text", "text": "問題ない。霜月さんの語彙の中で、それが最高の評価だということを俺は知っている。二ヶ月間、この人の下で働いて覚えた。「手際は悪くない」が最初の評価だった。「問題ない」はその上にある。その上に何があるのかは、まだ知らない。"}, {"id": "ch05-s01-p041", "type": "text", "text": "けれど今、霜月さんが質問の形で俺の手際に言及したことは、「問題ない」とは別の何かだった。ただの作業確認ではなく、ただの評価でもなく——褒めていた、のかもしれない。質問の形で。それが霜月さんの不器用さなのだと、今の俺にはわかる。"}, {"id": "ch05-s01-p042", "type": "text", "text": "怖い人だと思ったことは一度もない。冷たい人だと思った。そういう人だと受け止めた。今は、もう少し別のものが見えている。冷たいのではなく、温度を外に出さないだけだ。温度はある。凍った氷の下に。"}, {"id": "ch05-s01-p043", "type": "text", "text": "俺はレンチを手に取り直して、四本目の共鳴管に向かった。"}, {"id": "ch05-s01-p044", "type": "text", "text": "残りの共鳴管の点検を終え、音響増幅器の出力波形を記録した。第三系統の数値はほぼ安定していた。四月に0.3パーセント低下していたものが、五月の洗浄と調整で0.2パーセントまで回復し、六月に入ってからはさらに改善して誤差の範囲に収まりつつある。針の揺れ幅が小さくなっている。"}, {"id": "ch05-s01-p045", "type": "text", "text": "作業記録を書き終えて、共鳴管の清掃に移る。梅雨期は管の内壁に水滴が溜まりやすい。細い清掃棒に布を巻き付け、管の中に差し入れて水気を拭き取る。一本ずつ。丁寧に。"}, {"id": "ch05-s01-p046", "type": "text", "text": "清掃棒を引き抜いた時、霜月さんが機構室の奥に向かって歩き出した。"}, {"id": "ch05-s01-p047", "type": "text", "text": "鉄扉を出て、地下一階の通路に入る。俺も清掃棒を片付けて後に続いた。"}, {"id": "ch05-s01-p048", "type": "text", "text": "通路を進む。残響灯の青白い光が等間隔に並んでいる。霜月さんの白いコートの背中が前方にある。二ヶ月前と同じ光景。"}, {"id": "ch05-s01-p049", "type": "text", "text": "右手に、階段があった。"}, {"id": "ch05-s01-p050", "type": "text", "text": "地下二階へ降りる階段。入口の標識。「地下二階 記憶の間」。その下の赤い札。「関係者以外立入禁止」。"}, {"id": "ch05-s01-p051", "type": "text", "text": "霜月さんの足が、変わった。"}, {"id": "ch05-s01-p052", "type": "text", "text": "四月のあの日は、一歩ぶんの空白だった。歩行リズムの中に一拍だけ挟まれた沈黙。今日は違った。足が止まらなかった。止まらなかったが、歩幅が一歩だけ広くなった。階段の入口を、一歩で通り過ぎようとしている。視線も動かなかった——と思う。俺は後ろにいるから、霜月さんの目がどこを見ていたかは確認できない。けれど首の角度が変わらなかった。意図的に見ないようにしている。"}, {"id": "ch05-s01-p053", "type": "text", "text": "「こちらは今日は不要だ」"}, {"id": "ch05-s01-p054", "type": "text", "text": "声が短かった。いつもより。"}, {"id": "ch05-s01-p055", "type": "text", "text": "霜月さんは階段の前を通過し、そのまま地下一階から一階への階段を上った。白いコートの裾が石段に触れかけて、触れなかった。"}, {"id": "ch05-s01-p056", "type": "text", "text": "俺はその背中を見ながら、四月のことを思い出していた。あの時も同じ場所で、同じような変化があった。一拍の空白。今日は空白ではなく、回避だった。空白より意図が見える。「不要だ」という言葉がそれを証明している。不要であることを、わざわざ口に出す必要はない。不要なら黙って通り過ぎればいい。言葉にしたのは、自分に言い聞かせているから——そう感じたが、根拠がない。推測にとどめる。"}, {"id": "ch05-s01-p057", "type": "text", "text": "一階に上がった。管理室を通り過ぎ、少し奥に進んだところに、小さな扉があった。"}, {"id": "ch05-s01-p058", "type": "text", "text": "鐘鋳塔の一階、管理室の裏手。給湯室と呼ぶには狭い空間だった。流しと、小さなコンロと、棚に並んだカップ。業務中の水分補給用。マニュアルには載っていないが、ずっと前から誰かが使っていた形跡がある。カップの縁の釉薬が一部剥げている。"}, {"id": "ch05-s01-p059", "type": "text", "text": "霜月さんがその狭い空間に入った。コートの裾が扉の枠にかかりそうになる。"}, {"id": "ch05-s01-p060", "type": "text", "text": "水を汲む音がした。コンロに火を点ける音。それから、豆を挽く小さな音。"}, {"id": "ch05-s01-p061", "type": "text", "text": "手動の小さなミルだった。棚の奥に置いてあるのを俺は知っている。管理室の夜間巡回の時に一度見た。使っている人がいるとは思わなかった。"}, {"id": "ch05-s01-p062", "type": "text", "text": "廊下で待っていた。特に指示がなかったから、次の業務の準備をしようと思っていた。午前中に増幅器の調整がもう一項目残っている。"}, {"id": "ch05-s01-p063", "type": "text", "text": "給湯室から、コーヒーの匂いが流れてきた。"}, {"id": "ch05-s01-p064", "type": "text", "text": "残響灯の青白い光と金属の匂いしかない鐘鋳塔の一階に、焙煎した豆の香りが混ざった。喫茶「残響」で吉岡さんが淹れてくれるコーヒーの匂いと似ているが、もう少し深い。焦げに近い苦味のある匂い。"}, {"id": "ch05-s01-p065", "type": "text", "text": "霜月さんが出てきた。"}, {"id": "ch05-s01-p066", "type": "text", "text": "両手にカップを持っていた。"}, {"id": "ch05-s01-p067", "type": "text", "text": "一つを、俺の前に差し出した。無言で。目も合わせなかった。差し出す手の角度だけが正確で、俺が受け取りやすい高さに調節されていた。"}, {"id": "ch05-s01-p068", "type": "text", "text": "「ありがとうございます、霜月さん」"}, {"id": "ch05-s01-p069", "type": "text", "text": "「業務中の水分補給だ。礼には及ばない」"}, {"id": "ch05-s01-p070", "type": "text", "text": "声が素っ気なかった。いつもの業務口調。カップを渡した後、霜月さんは自分のカップに口をつけた。壁に背を預けて、管理室の窓の向こうを見ている。窓の外は灰色だった。六月の空。雨は降っていないが、降りそうな重さがある。"}, {"id": "ch05-s01-p071", "type": "text", "text": "カップに口をつけた。"}, {"id": "ch05-s01-p072", "type": "text", "text": "苦い。吉岡さんのコーヒーよりだいぶ苦い。砂糖もミルクも入っていない。ブラック。霜月さんが自分用に淹れるコーヒーを、そのまま俺にも出した、ということだろう。俺の好みを聞く手順が、この人の中に存在しない。"}, {"id": "ch05-s01-p073", "type": "text", "text": "けれど温かかった。"}, {"id": "ch05-s01-p074", "type": "text", "text": "六月の地下一階は湿気で体が冷える。石壁と金属に囲まれた空間で二時間ほど作業した後の、手のひらに伝わるカップの温度。コーヒーの苦味の奥にある、豆の甘み。苦い。苦いけれど嫌ではない。喫茶「残響」で初めてコーヒーを飲んだ時にも似た感覚があった。あの時は天城さんに「どう？」と聞かれて「おいしい……のだと思います」と答えた。"}, {"id": "ch05-s01-p075", "type": "text", "text": "今日は聞かれていない。霜月さんは聞かない。感想を求めない人だ。"}, {"id": "ch05-s01-p076", "type": "text", "text": "カップの中の黒い液面に、残響灯の光が小さく映っていた。"}, {"id": "ch05-s01-p077", "type": "text", "text": "霜月さんは自分のカップを両手で包み、背中を壁に預けたまま黙っていた。白いコートの襟が、作業で少し乱れている。普段はぴったりと閉じている襟元がわずかに緩んで、首筋が覗いていた。視線は窓の外。灰色の空と、霧雨に煙る中庭の木々を見ている。"}, {"id": "ch05-s01-p078", "type": "text", "text": "仕事の姿勢ではなかった。"}, {"id": "ch05-s01-p079", "type": "text", "text": "残響祭の夜に、鐘鋳塔の入口で星空を見上げていた時と同じ——肩の力が抜けている。それを見たのは、あの夜が初めてだった。今日が二度目だ。二度目は、隣にいることが許されているのだと思えた。一度目は「追い払われなかった」。二度目は「いても構わない」。その差は小さいが、確かにある。"}, {"id": "ch05-s01-p080", "type": "text", "text": "コーヒーの二口目。舌の奥に苦味が残る。嫌な苦味ではない。温度が下がると甘みが出るタイプの豆だ、と手のひらが教えている。この知識もまた、誰に教わったものかわからない。"}, {"id": "ch05-s01-p081", "type": "text", "text": "霜月さんはコーヒーを淹れた。俺の分も。それは業務中の水分補給であって、それ以上の意味はないと霜月さんは言った。正しいのだろう。業務中の水分補給。合理的な行動。"}, {"id": "ch05-s01-p082", "type": "text", "text": "けれど、二人分の豆を挽く手間は合理性の外にある。"}, {"id": "ch05-s01-p083", "type": "text", "text": "一人分なら自分で飲む。二人分にしたのは——。"}, {"id": "ch05-s01-p084", "type": "text", "text": "「増幅器の調整が残っている。五分後に再開する」"}, {"id": "ch05-s01-p085", "type": "text", "text": "霜月さんの声で考えが切れた。カップの中のコーヒーはまだ半分残っていた。"}, {"id": "ch05-s01-p086", "type": "text", "text": "「はい」"}, {"id": "ch05-s01-p087", "type": "text", "text": "五分。それが霜月さんの休憩時間。五分間だけ壁に寄りかかり、コーヒーを飲み、窓の外を見る。それを俺に見せたことは、たぶん意図していない。俺がここにいることを忘れていたわけでもない。コーヒーを渡した時点で、俺がここにいることは織り込み済みだ。"}, {"id": "ch05-s01-p088", "type": "text", "text": "つまり、いてもいい場所なのだ。"}, {"id": "ch05-s01-p089", "type": "text", "text": "カップの残りを飲み干した。苦い。温かい。苦くて温かい。それが霜月さんのコーヒーだった。覚えておく。"}, {"id": "ch05-s01-p090", "type": "text", "text": "五分が経つ前に、霜月さんがカップを流しに置く音がした。俺も続いて流しにカップを置いた。霜月さんが先に廊下に出る。俺が後に続く。白いコートの背中が残響灯の光の中を進んでいく。"}, {"id": "ch05-s01-p091", "type": "text", "text": "地下一階への階段を降り始めた時、霜月さんの歩幅がいつもに戻っていた。あの一歩の広がりはもうない。地下二階への階段を通り過ぎる前に、コーヒーの五分間が挟まれて、何かがリセットされたのかもしれない。"}, {"id": "ch05-s01-p092", "type": "text", "text": "機構室の鉄扉を開ける。歯車が待っている。"}, {"id": "ch05-s01-p093", "type": "text", "text": "音響増幅器の前にしゃがみ込み、出力波形の微調整を始めた。霜月さんは別の増幅器に取りかかっている。二台を並行で。会話はない。工具の音と、歯車の微細な回転音と、石壁に反響する二人の呼吸だけがある。"}, {"id": "ch05-s01-p094", "type": "text", "text": "不器用な人だ、と思った。"}, {"id": "ch05-s01-p095", "type": "text", "text": "怖い人でも、冷たい人でもなく。不器用な人。コーヒーを黙って渡す。感想を聞かない。「業務中の水分補給」と説明する。質問の形でしか褒められない。地下二階の階段を、言葉で回避する。"}, {"id": "ch05-s01-p096", "type": "text", "text": "四月の「そういう人」から、二ヶ月で「不器用な人」に変わった。変わったのは霜月さんではなく、俺の目の方だろう。同じものを見ていて、見え方が変わった。歯車のバックラッシュと同じだ。基準値を知らなければただの隙間。基準値を知れば、適正か異常かがわかる。霜月さんの不器用さは、二ヶ月一緒に働いた今だからわかる。"}, {"id": "ch05-s01-p097", "type": "text", "text": "増幅器のつまみを八分の一回転だけ回した。出力波形が安定する。手が覚えている感覚で、ちょうどいい位置に止まった。"}, {"id": "ch05-s01-p098", "type": "text", "text": "窓の外で、雨が降り始めた音がした。灰色の空から落ちてくる水の音が、石壁を通して鐘鋳塔の中にまで届いている。機構室の歯車は変わらず回っている。湿気の中で、きしみながら。"}, {"id": "ch05-s01-p099", "type": "text", "text": "コーヒーの苦味が、まだ舌の奥に残っていた。"}]}, {"chapter": 5, "chapterTitle": "夏の入り口", "scene": 2, "sceneTitle": "知っている気がする人", "wordCount": "約6,200字", "paragraphs": [{"id": "ch05-s02-p001", "type": "text", "text": "午前の点検を終えて、鐘鋳塔を出た。"}, {"id": "ch05-s02-p002", "type": "text", "text": "十二時の鐘が鳴り始めている。六月の空は相変わらず灰色だったが、午前中の雨は上がっていた。石畳の表面に水が薄く残っている。靴底が立てる音がいつもと違う。乾いた石と濡れた石では、歩く時の音の周波数が変わる。そういうことに気づくようになったのは、鐘守補佐になってからだ。"}, {"id": "ch05-s02-p003", "type": "text", "text": "舌の奥に、まだ霜月さんのコーヒーの苦味が残っていた。"}, {"id": "ch05-s02-p004", "type": "text", "text": "食堂へ向かう。鐘鋳塔から教室棟の方向へ、中庭を横切る。残響桜の老木は完全に葉桜に変わっていた。濃い緑の葉が水滴を溜めて、風が吹くたびにぱらぱらと雫を落としている。四月の薄紫の花弁は、もうどこにもない。季節が進むというのはそういうことだ。残るのは色ではなく、色があったという記憶。"}, {"id": "ch05-s02-p005", "type": "text", "text": "中庭を抜けて、教室棟の前に出た。"}, {"id": "ch05-s02-p006", "type": "text", "text": "昼休みの喧騒が始まりかけている。教室棟の一階から生徒たちが出てくる。食堂に向かう人の流れ。声。笑い声。足音が石畳の上で重なって、輪郭を失う。俺はいつものように流れの端を歩いていた。"}, {"id": "ch05-s02-p007", "type": "text", "text": "視界の左端に、動いたものがあった。"}, {"id": "ch05-s02-p008", "type": "text", "text": "南門の方向。門の内側、石壁の柱に寄りかかるようにして立っている人影。"}, {"id": "ch05-s02-p009", "type": "text", "text": "濃い緑のジャケット。学院の制服ではない。黒いカーゴパンツに、ブーツ。腰にマルチツールと通信機器。左胸に金属の階級章が鈍く光っている。その上に、黒いハーフコートを羽織っている。六月にコートを着る人は少ない。しかし軍人の制服というのは季節で脱いだり着たりするものではなく、所属を示す記号のようなものだ。"}, {"id": "ch05-s02-p010", "type": "text", "text": "黒髪のセミロング。低い位置のポニーテール。前髪を左に流して、額を半分出している。"}, {"id": "ch05-s02-p011", "type": "text", "text": "足が止まった。"}, {"id": "ch05-s02-p012", "type": "text", "text": "理由がわからなかった。あの人を見たから止まったのか、止まったからあの人を見たのか。順序が不明だった。歯車の回転方向がわからないのと同じだ。結果から原因を辿ろうとすると、原因がさらにその先にある。"}, {"id": "ch05-s02-p013", "type": "text", "text": "知っている。"}, {"id": "ch05-s02-p014", "type": "text", "text": "その確信が、足裏から背骨を登ってきた。頭ではなく体が先に反応している。鐘鋳塔の地下で歯車に触れた時と同じ種類の反応。潤滑油の粘度を手が知っていたのと同じように、体があの人の輪郭を知っていた。肩の角度。立ち方の重心。壁に寄りかかる時に腕を組む癖。その一つ一つが、記憶にはないのに体の中に紋様として刻まれていた。"}, {"id": "ch05-s02-p015", "type": "text", "text": "深い琥珀色の瞳がこちらを見ていた。"}, {"id": "ch05-s02-p016", "type": "text", "text": "遠い。南門から教室棟の前まで二十メートルほどあった。その距離から、瞳の色がわかるはずはない。けれどわかった。知っていた。何故かはわからない。"}, {"id": "ch05-s02-p017", "type": "text", "text": "その人が壁から背を離した。"}, {"id": "ch05-s02-p018", "type": "text", "text": "姿勢が変わった。軍人の歩き方。背筋が完璧に伸び、歩幅が正確で、足音が規則的。俺の中の何かが、その歩き方のリズムを知っていた。何度も隣で聞いた音だと、耳の奥が言っている。記憶にはない。記憶にはないのに、耳が覚えていた。"}, {"id": "ch05-s02-p019", "type": "text", "text": "十歩。二十歩。近づいてくるにつれて、輪郭が鮮明になった。"}, {"id": "ch05-s02-p020", "type": "text", "text": "引き締まった体つき。長身。百七十センチは超えている。俺より少し低いが、佇まいから来る印象が大きかった。ジャケットの上のハーフコートが、歩くたびにわずかに揺れる。風はほとんどなかった。歩行の振動だけで裾が動いている。"}, {"id": "ch05-s02-p021", "type": "text", "text": "五メートル手前で、その人の表情が見えた。"}, {"id": "ch05-s02-p022", "type": "text", "text": "引き締まった顔。感情を外に出さない構造。霜月さんと似ている——と一瞬思ったが、違った。霜月さんの冷たさは氷の下に温度を沈めている構造だ。この人の引き締まりは、何かを堪えている構造だった。堪えているものの種類が、冷たさではなく、もっと別のもの。"}, {"id": "ch05-s02-p023", "type": "text", "text": "琥珀色の瞳が、俺を見ていた。"}, {"id": "ch05-s02-p024", "type": "text", "text": "二メートル。足が止まった。立ち止まったのは俺ではなく、その人の方だった。俺はもう少し手前で止まっている。向かい合っている。昼休みの生徒たちの流れが、俺たちの脇を通り過ぎていく。誰も気にしていない。"}, {"id": "ch05-s02-p025", "type": "text", "text": "その人の瞳の中に、何かが動いた。"}, {"id": "ch05-s02-p026", "type": "text", "text": "光ではなかった。光の手前にあるもの。認識。俺を見て、俺だとわかっている目。初対面の相手を見定める目ではなかった。知っている相手を見る目だった。確認ではなく、再確認。一度見たものをもう一度見る時の、確かめる動作。"}, {"id": "ch05-s02-p027", "type": "text", "text": "口が開いた。"}, {"id": "ch05-s02-p028", "type": "text", "text": "「——蓮」"}, {"id": "ch05-s02-p029", "type": "text", "text": "名前だった。呼び捨て。敬称なし。俺の名前を、まるで何百回も呼んだことがあるような声で。"}, {"id": "ch05-s02-p030", "type": "text", "text": "鳩尾の下が、動いた。"}, {"id": "ch05-s02-p031", "type": "text", "text": "鐘の音を聞いた時の反応でもなく、鳴海さんの歌声を聞いた時の鳩尾の緩みでもなかった。もっと深い場所。名前のない場所。歯車に触れた時に安心が来る場所と、同じ深さにあるもの。"}, {"id": "ch05-s02-p032", "type": "text", "text": "「……すみません。俺を、知っているんですか」"}, {"id": "ch05-s02-p033", "type": "text", "text": "声が出た。考えるより先に。出た声は敬語だった。自分でもそれが不自然だと感じた。敬語が正しいのか、正しくないのかがわからなかった。体は知っているのに頭が追いつかない。"}, {"id": "ch05-s02-p034", "type": "text", "text": "琥珀色の瞳が、一瞬だけ揺れた。"}, {"id": "ch05-s02-p035", "type": "text", "text": "瞬きではなかった。目の表面ではなく、目の奥で何かが揺れた。それは——"}, {"id": "ch05-s02-p036", "type": "text", "text": "切なさ、だったのかもしれない。"}, {"id": "ch05-s02-p037", "type": "text", "text": "鐘鋳塔の歯車のバックラッシュと同じだ。基準値を知らなければただの動き。基準値を知れば、意味がわかる。俺にはこの人の基準値がなかった。だから「切なさ」は推測でしかない。けれど、あの一瞬の揺れの中に、喜びと痛みが同時に存在していたことは、わかった。俺を見つけたことへの喜びと、俺に見つけてもらえないことへの痛み。"}, {"id": "ch05-s02-p038", "type": "text", "text": "その揺れは、一秒もなかった。"}, {"id": "ch05-s02-p039", "type": "text", "text": "引き締まった表情が戻った。顎が微かに上がり、肩が数ミリ後ろに引かれた。軍人の姿勢。感情を格納する動作。"}, {"id": "ch05-s02-p040", "type": "text", "text": "「……悪い。昔の癖だ」"}, {"id": "ch05-s02-p041", "type": "text", "text": "声が低かった。さっきの「蓮」とは別の声だった。制御された声。報告書を読む時の声に近い。"}, {"id": "ch05-s02-p042", "type": "text", "text": "「桐ヶ谷晶。縁際監視哨の隊長。お前が以前うちにいた時の上官だ」"}, {"id": "ch05-s02-p043", "type": "text", "text": "名乗り。所属。関係性の説明。三つの情報を過不足なく、短い文で。軍人の自己紹介だった。"}, {"id": "ch05-s02-p044", "type": "text", "text": "縁際監視哨。俺がかつて所属していた場所。二年前に聖鐘学院に異動するまでの二年間。その記憶はない。記憶がないのに、体がこの人を知っていた。"}, {"id": "ch05-s02-p045", "type": "text", "text": "「……桐ヶ谷さん」"}, {"id": "ch05-s02-p046", "type": "text", "text": "口から出た呼称は、それだった。名字にさん付け。記憶がないのだから、これが正しい呼び方だろう。初対面と同じ距離の言葉。"}, {"id": "ch05-s02-p047", "type": "text", "text": "桐ヶ谷さんの目が、一瞬だけ細くなった。"}, {"id": "ch05-s02-p048", "type": "text", "text": "笑ったのではない。痛みを薄く引き延ばしたような動きだった。まばたき一回ぶんの長さ。それから平坦な声が来た。"}, {"id": "ch05-s02-p049", "type": "text", "text": "「昔は晶さんと呼んでいたのに」"}, {"id": "ch05-s02-p050", "type": "text", "text": "軽い口調だった。責めてはいなかった。事実を述べているだけの声。風が石畳の水溜まりの表面を一瞬だけ揺らして、すぐに元に戻るような声。深追いしない声。"}, {"id": "ch05-s02-p051", "type": "text", "text": "けれど、「晶さん」という音の並びが、舌の上で転がった。口に出してはいない。頭の中で反芻しただけだ。晶さん。その呼び方を、かつて俺はしていた。口の形が覚えている——ような気がした。唇と舌と喉が、その音を作る順序を知っている。記憶にはない。記憶にはないのに。"}, {"id": "ch05-s02-p052", "type": "text", "text": "「覚えていなくて、すみません」"}, {"id": "ch05-s02-p053", "type": "text", "text": "それしか言えなかった。事実としてそうだから。覚えていない。覚えていないことに対して謝るのが正しいのかもわからないが、それ以外の言葉が見つからなかった。"}, {"id": "ch05-s02-p054", "type": "text", "text": "「謝る必要はない」"}, {"id": "ch05-s02-p055", "type": "text", "text": "桐ヶ谷さんの声が、わずかに柔らかくなった。ほんの少し。音量が下がったのではなく、声の輪郭の角が取れた。"}, {"id": "ch05-s02-p056", "type": "text", "text": "「管理局への定期報告の帰りだ。学院に寄った」"}, {"id": "ch05-s02-p057", "type": "text", "text": "説明。ここにいる理由の説明。報告の帰りに寄った。それだけの理由。合理的な行動。"}, {"id": "ch05-s02-p058", "type": "text", "text": "霜月さんのコーヒーを思い出した。「業務中の水分補給だ」。合理的な説明の形をした、別の何か。桐ヶ谷さんの「帰りに寄った」も、同じ構造をしていないか。管理局は内円区にある。学院は中円区だ。帰り道というには方向が違う。寄る理由が、報告以外にあるのではないか。"}, {"id": "ch05-s02-p059", "type": "text", "text": "推測にとどめる。根拠がない。"}, {"id": "ch05-s02-p060", "type": "text", "text": "「学院の仕事は合っているか」"}, {"id": "ch05-s02-p061", "type": "text", "text": "桐ヶ谷さんが聞いた。目が俺の全身を見ている。服装、姿勢、顔色。軍人が部下の状態を確認する目だった。しかしそれだけではなかった。確認の奥に、もう一つ別のものが透けていた。"}, {"id": "ch05-s02-p062", "type": "text", "text": "「はい。鐘守補佐の仕事は、手に合っています」"}, {"id": "ch05-s02-p063", "type": "text", "text": "手に合う。その言葉を選んだのは意図的だった。歯車に触れた時の感覚。共鳴管の継手を締める時の手首の角度。「手が覚えている」こと。それが鐘守補佐の仕事と合致していること。"}, {"id": "ch05-s02-p064", "type": "text", "text": "桐ヶ谷さんの目が、わずかに鋭くなった。"}, {"id": "ch05-s02-p065", "type": "text", "text": "霜月さんが俺の継手の締め方を見た時の目と似ていた。何かを照合している目。俺の答えと、桐ヶ谷さんの中にある情報を突き合わせようとしている。霜月さんのそれはデータの照合だった。桐ヶ谷さんのそれは——もう少し人間的な何かだった。記憶の照合。俺の今の姿と、桐ヶ谷さんが知っている過去の俺を重ねようとしている。"}, {"id": "ch05-s02-p066", "type": "text", "text": "「そうか」"}, {"id": "ch05-s02-p067", "type": "text", "text": "短い返答。桐ヶ谷さんは腕を組んだ。ハーフコートの下で、ジャケットの袖が皺を作る。"}, {"id": "ch05-s02-p068", "type": "text", "text": "「体調は問題ないか」"}, {"id": "ch05-s02-p069", "type": "text", "text": "二つ目の質問。仕事の次は体調。上官が部下に確認する項目の順番として、正しい。しかし声が一問目と微妙に違った。一問目は確認の声。二問目は、気にかけている声。違いは小さかった。声の高さが変わったのではなく、言葉と言葉の間に挟まれた空白が、一問目より長かった。"}, {"id": "ch05-s02-p070", "type": "text", "text": "「問題ありません」"}, {"id": "ch05-s02-p071", "type": "text", "text": "「食事は取れているか」"}, {"id": "ch05-s02-p072", "type": "text", "text": "三つ目。食事。質問が、上官の点検項目から離れ始めていた。仕事、体調、食事。三番目は部下への確認ではなく、人間への心配に近い。"}, {"id": "ch05-s02-p073", "type": "text", "text": "「はい。食堂で昼と夜を。朝は自分で」"}, {"id": "ch05-s02-p074", "type": "text", "text": "「……そうか」"}, {"id": "ch05-s02-p075", "type": "text", "text": "二回目の「そうか」は、一回目と音が違った。安堵に似た何かが混じっていた。俺が飯を食べていることに安堵する理由を、上官の責任だけでは説明しきれない。"}, {"id": "ch05-s02-p076", "type": "text", "text": "風が吹いた。六月の湿った風。雨上がりの空気は重いが、風だけは軽かった。桐ヶ谷さんの低いポニーテールが、風で一瞬だけ揺れた。黒い髪。硬そうな髪質。風に揺れにくい髪が揺れた。"}, {"id": "ch05-s02-p077", "type": "text", "text": "「桐ヶ谷さん」"}, {"id": "ch05-s02-p078", "type": "text", "text": "声が出た。また、考える前に。"}, {"id": "ch05-s02-p079", "type": "text", "text": "「俺は……あなたのことを、知っている気がします」"}, {"id": "ch05-s02-p080", "type": "text", "text": "言ってから、自分の言葉を聞いた。知っている気がする。気がする。断定できない。記憶にはないのだから。けれど体が知っている。歩き方のリズム、肩の角度、瞳の色。名前を呼ばれた時の鳩尾の反応。全部が、どこかで触れたことのある感触だった。"}, {"id": "ch05-s02-p081", "type": "text", "text": "桐ヶ谷さんの表情が、一瞬だけ——。"}, {"id": "ch05-s02-p082", "type": "text", "text": "崩れた、という言い方は正確ではない。固まった、でもない。表情の中にある壁が、一枚だけ薄くなった。風が抜ける隙間が生まれた。琥珀色の瞳の奥に、何かが灯って、消えた。"}, {"id": "ch05-s02-p083", "type": "text", "text": "蝋燭の炎が揺れるのを見たことがある。風が吹いて炎が傾き、消える寸前まで小さくなって、風が止むと元に戻る。桐ヶ谷さんの目の奥のそれは、消える寸前で戻った炎に似ていた。"}, {"id": "ch05-s02-p084", "type": "text", "text": "「……そうか」"}, {"id": "ch05-s02-p085", "type": "text", "text": "三回目の「そうか」。これが一番静かだった。声量が落ちたのではない。声の中に含まれる力が変わった。報告を受理する「そうか」でも、安堵の「そうか」でもなく、受け止めるだけの「そうか」だった。"}, {"id": "ch05-s02-p086", "type": "text", "text": "桐ヶ谷さんは腕を組み直した。視線が俺から外れた。南門の方を見ている。門柱の石壁と、その向こうの灯籠通り。灰色の空の下の、濡れた石畳。"}, {"id": "ch05-s02-p087", "type": "text", "text": "「俺が、監視哨にいた時のことを——」"}, {"id": "ch05-s02-p088", "type": "text", "text": "「深入りするな」"}, {"id": "ch05-s02-p089", "type": "text", "text": "声が鋭かった。"}, {"id": "ch05-s02-p090", "type": "text", "text": "一瞬だけ。刃物のような声が、教室棟の前の空気を横切った。昼休みの喧騒が遠くなった。桐ヶ谷さんの声だけが、耳に残った。"}, {"id": "ch05-s02-p091", "type": "text", "text": "しかし次の瞬間、桐ヶ谷さんの肩が小さく落ちた。力が抜けた、のではない。力を入れすぎたことに気づいて、戻した。そういう動きだった。"}, {"id": "ch05-s02-p092", "type": "text", "text": "「……悪い。言い方が悪かった」"}, {"id": "ch05-s02-p093", "type": "text", "text": "声が変わっていた。さっきの刃は消えて、低いが柔らかい声に戻っている。"}, {"id": "ch05-s02-p094", "type": "text", "text": "「お前の体のことだ。手が先に動くとか、知っているはずのないことを知っているとか。そういう感覚があるなら、それはそのままにしておけ。無理に掘り返す必要はない」"}, {"id": "ch05-s02-p095", "type": "text", "text": "具体的だった。「手が先に動く」。それは、俺がさっき「手に合っています」と言ったことへの応答だったのか。それとも、桐ヶ谷さんが以前から知っていたことなのか。"}, {"id": "ch05-s02-p096", "type": "text", "text": "知っている。この人は知っている。"}, {"id": "ch05-s02-p097", "type": "text", "text": "俺の「手が先に動く」感覚の出処を。鐘の音を聞いた時の反応の理由を。歯車に触れた時の安心の正体を。すみれが俺の名前を知っていた理由とは違う種類の知り方で、桐ヶ谷さんは俺の過去を知っている。"}, {"id": "ch05-s02-p098", "type": "text", "text": "聞きたかった。喉の奥まで言葉が来ていた。俺は何者だったんですか。二年前より前の記憶がない。あなたはそれを知っている。教えてほしい。"}, {"id": "ch05-s02-p099", "type": "text", "text": "言葉は、喉の奥で止まった。"}, {"id": "ch05-s02-p100", "type": "text", "text": "桐ヶ谷さんの目を見ていた。琥珀色の瞳の中に、堪えているものがあった。この人は何かを守っている。情報を隠しているのではなく、守っている。隠すことと守ることの違いは、目に出る。隠す人の目は逸らす。守る人の目は、真っ直ぐ見たまま口を閉じる。"}, {"id": "ch05-s02-p101", "type": "text", "text": "桐ヶ谷さんの目は、真っ直ぐだった。"}, {"id": "ch05-s02-p102", "type": "text", "text": "「……わかりました」"}, {"id": "ch05-s02-p103", "type": "text", "text": "聞けなかった。聞くべきではなかった、のかもしれない。判断の根拠は目の前の琥珀色の瞳だけだ。この人が口を閉じているなら、そこには理由がある。理由を知らずに信じるのは合理的ではない。けれど体が「この人は敵ではない」と言っていた。歯車を手が知っているのと同じ確かさで。"}, {"id": "ch05-s02-p104", "type": "text", "text": "桐ヶ谷さんの腕が解かれた。右手がハーフコートのポケットに入り、すぐに出てきた。何も持っていない。癖だろうか。何かを取り出そうとして、やめた動作に見えた。"}, {"id": "ch05-s02-p105", "type": "text", "text": "「鐘鋳塔の仕事を続けろ。あそこは悪くない場所だ」"}, {"id": "ch05-s02-p106", "type": "text", "text": "「はい」"}, {"id": "ch05-s02-p107", "type": "text", "text": "「霜月は厳しいが、悪い人間ではない」"}, {"id": "ch05-s02-p108", "type": "text", "text": "霜月さんの名前が出た。上官の名前を出すのは、申し送りの感覚だろうか。前の上官が、今の上司を評する。この人は俺の環境を把握している。"}, {"id": "ch05-s02-p109", "type": "text", "text": "「……知っています。不器用な人だと思っています」"}, {"id": "ch05-s02-p110", "type": "text", "text": "出た言葉に、自分で驚いた。不器用。今朝の機構室で得た結論を、桐ヶ谷さんに伝えていた。何故そんなことを言ったのかわからない。桐ヶ谷さんに対して、霜月さんのことを正確に伝えたかった。そう体が判断した。"}, {"id": "ch05-s02-p111", "type": "text", "text": "桐ヶ谷さんの口元が、わずかに動いた。"}, {"id": "ch05-s02-p112", "type": "text", "text": "笑った——と呼ぶには小さすぎた。唇の端が数ミリだけ上がり、すぐに戻った。しかし目が、一瞬だけ柔らかくなっていた。瞳の琥珀色が、温かい色だと初めて気づいた。"}, {"id": "ch05-s02-p113", "type": "text", "text": "「そうだな。あいつは昔から不器用だ」"}, {"id": "ch05-s02-p114", "type": "text", "text": "昔から。桐ヶ谷さんは霜月さんの「昔」を知っている。俺は知らない。俺の知らない時間が、この人の中にはある。霜月さんの昔と、俺の昔が、桐ヶ谷さんの中で交差している。"}, {"id": "ch05-s02-p115", "type": "text", "text": "「私はそろそろ戻る。縁際は人手が足りない」"}, {"id": "ch05-s02-p116", "type": "text", "text": "告げて、桐ヶ谷さんは南門の方を向いた。ハーフコートの裾が半回転した。歩き出す直前に、足が止まった。振り返りはしなかった。背中だけが、こちらを向いていた。"}, {"id": "ch05-s02-p117", "type": "text", "text": "「蓮」"}, {"id": "ch05-s02-p118", "type": "text", "text": "また、名前だった。"}, {"id": "ch05-s02-p119", "type": "text", "text": "「元気でいろ」"}, {"id": "ch05-s02-p120", "type": "text", "text": "低い声だった。命令でもなく、願いでもなく、その中間にある何か。報告書には書けない種類の声。"}, {"id": "ch05-s02-p121", "type": "text", "text": "背中が歩き出した。軍人の歩幅。正確で、規則的。南門の石柱の間を通り抜け、灯籠通りに出る。黒いハーフコートと低いポニーテールが、濡れた石畳の上を遠ざかっていく。"}, {"id": "ch05-s02-p122", "type": "text", "text": "俺は立ったまま、その背中を見ていた。"}, {"id": "ch05-s02-p123", "type": "text", "text": "鳩尾の奥で、名前のない反応が残っていた。歯車の安心とも、鐘の音の懐かしさとも違う。もっと人の形をした何かだった。あの人の輪郭を、体が覚えている。歩き方と、声の高さと、瞳の色と、名前を呼ばれた時の温度。"}, {"id": "ch05-s02-p124", "type": "text", "text": "「晶さん」"}, {"id": "ch05-s02-p125", "type": "text", "text": "口の中だけで転がした。声にはしなかった。"}, {"id": "ch05-s02-p126", "type": "text", "text": "舌と唇がその音を作れた。知っている。この呼び方を、かつて何度もした。口の筋肉が覚えている音だった。"}, {"id": "ch05-s02-p127", "type": "text", "text": "けれど声にする理由がなかった。記憶がない。記憶がない人間が、記憶の中の呼び方をするのは正しくない。正しくないから、「桐ヶ谷さん」でいい。それが今の俺にとっての正しい距離だ。"}, {"id": "ch05-s02-p128", "type": "text", "text": "桐ヶ谷さんの背中は、灯籠通りの角を曲がって見えなくなった。"}, {"id": "ch05-s02-p129", "type": "text", "text": "食堂に向かった。昼休みの人の流れに合流する。石畳の水気はだいぶ乾きかけていた。灰色の空は変わらない。"}, {"id": "ch05-s02-p130", "type": "text", "text": "教室棟の前を通り過ぎた時、足が一瞬だけ遅くなった。さっきまで桐ヶ谷さんが立っていた場所。南門の石柱。そこにはもう誰もいなかった。"}, {"id": "ch05-s02-p131", "type": "text", "text": "知っている気がする人。そう呼ぶしかない。記憶にはないのに体が覚えている人。名前を呼ばれた時に鳩尾の奥が動く人。「深入りするな」と言った声に、守っているものの重さがあった人。"}, {"id": "ch05-s02-p132", "type": "text", "text": "思い出せない。"}, {"id": "ch05-s02-p133", "type": "text", "text": "鐘の音の懐かしさも。歯車に触れた時の安心も。桐ヶ谷さんの声に体が反応することも。全部、同じ場所から来ているのかもしれない。俺の二年前より前の、空白の中にある何か。"}, {"id": "ch05-s02-p134", "type": "text", "text": "その何かに名前をつけることは、まだできない。"}, {"id": "ch05-s02-p135", "type": "text", "text": "食堂の扉を開けた。煉瓦造りの天井の高いホール。アーチ状の窓から、灰色の光が差し込んでいる。定食のトレイを受け取って、窓際の端に座った。"}, {"id": "ch05-s02-p136", "type": "text", "text": "白米。味噌汁。焼き魚。漬物。四月の初日と同じ並び。箸を持って、味噌汁を一口飲んだ。"}, {"id": "ch05-s02-p137", "type": "text", "text": "温かかった。"}, {"id": "ch05-s02-p138", "type": "text", "text": "霜月さんのコーヒーとは違う温かさ。苦くない。出汁の旨味が口の中に広がる。四月の頃は「おいしい」を言うのに間があった。今はない。味噌汁はおいしい。わかっている。知っている味だから。"}, {"id": "ch05-s02-p139", "type": "text", "text": "知らない味には、まだ間がある。桐ヶ谷さんは、知っているはずなのに知らない味だった。体は知っていて、頭は知らない。その食い違いに、名前がない。"}, {"id": "ch05-s02-p140", "type": "text", "text": "箸を置いた。焼き魚の身を崩しかけて、手が止まっていた。"}, {"id": "ch05-s02-p141", "type": "text", "text": "桐ヶ谷さんの最後の言葉。「元気でいろ」。あの声の温度は、命令ではなかった。「問題ない」の先にあるもの。霜月さんの「問題ない」は評価だった。桐ヶ谷さんの「元気でいろ」は、もっと古い場所から来ている声だった。"}, {"id": "ch05-s02-p142", "type": "text", "text": "覚えておく。桐ヶ谷さんの琥珀色の瞳と、「蓮」と呼ばれた時の鳩尾の反応と、「深入りするな」の声の鋭さと、その直後に肩の力を抜いた動作と、「元気でいろ」の温度を。"}, {"id": "ch05-s02-p143", "type": "text", "text": "焼き魚に箸を戻した。食堂の喧騒が耳に戻ってくる。窓の外は灰色のまま。六月は続いている。"}, {"id": "ch05-s02-p144", "type": "text", "text": "舌の奥のコーヒーの苦味は、もう消えていた。代わりに、味噌汁の温かさと、名前を呼ばれた時の温度が、同じ場所に並んで残っていた。"}]}, {"chapter": 5, "chapterTitle": "夏の入り口", "scene": 3, "sceneTitle": "雨の図書館", "wordCount": "約4,200字", "paragraphs": [{"id": "ch05-s03-p001", "type": "text", "text": "昼食を終えて鐘鋳塔に戻り、午後の点検を済ませた。"}, {"id": "ch05-s03-p002", "type": "text", "text": "共鳴管の結露拭き取り。湿気で膜が張った管の内壁に布を通して、一本ずつ水分を吸わせる。梅雨期の日課だった。十三時半に完了報告を管理室の机上に置いて、鐘鋳塔を出た。"}, {"id": "ch05-s03-p003", "type": "text", "text": "雨が降っていた。"}, {"id": "ch05-s03-p004", "type": "text", "text": "昼食の時に止んでいた雨が、再び始まっている。細い雨。真っ直ぐに落ちる種類ではなく、空気中に漂うような細かい粒が、視界の全体に散らばっていた。音がほとんどない。雨粒が石畳を叩く音は聞こえるが、それは連続した一つの音として聞こえていて、一粒ずつの着地は判別できなかった。空気中の水の密度が上がっているだけ、という印象。"}, {"id": "ch05-s03-p005", "type": "text", "text": "灰色の空。鐘鋳塔の屋根の先端が霞んで見えた。いつもなら塔頂の風見が確認できるが、今日は輪郭が曖昧だった。"}, {"id": "ch05-s03-p006", "type": "text", "text": "中庭を横切った。残響桜の老木の葉が雨を受けて、重そうに垂れている。幹に近い地面は少し乾いていた。葉が傘の代わりになっている範囲。そこを通り抜けた時、一瞬だけ雨粒が顔に当たらなくなった。"}, {"id": "ch05-s03-p007", "type": "text", "text": "図書館に向かっている。"}, {"id": "ch05-s03-p008", "type": "text", "text": "足がそう動いていた。午後の予定は特にない。霜月さんから追加の指示は出ていない。月曜の定例報告は提出済み。残っているのは明日の巡回ルートの確認だけで、それは今日でなくてもいい。"}, {"id": "ch05-s03-p009", "type": "text", "text": "足は図書館に向かっていた。理由を言葉にする必要はなかった。毎日この時間に向かっている。何曜日に行くかを考えなくなった時点で、日課になっている。"}, {"id": "ch05-s03-p010", "type": "text", "text": "木の外壁が見えた。煉瓦の基礎。緑青の雨樋から水が細い筋になって流れ落ちている。雨の日の図書館は外壁の色が暗くなる。木材が水を吸って、普段より深い茶色をしていた。"}, {"id": "ch05-s03-p011", "type": "text", "text": "真鍮の取っ手を引いた。蝶番が鳴った。"}, {"id": "ch05-s03-p012", "type": "text", "text": "中に入った瞬間、湿り気の種類が変わった。外の湿気は雨の水分だった。図書館の中の湿気は紙と木と蜜蝋を含んでいる。温度が少し低い。六月の外気より二度ほど。壁と天井の木材が温度を吸い、石の床が冷気を保っている。"}, {"id": "ch05-s03-p013", "type": "text", "text": "受付で頭を下げた。受付の女性は視線で応じた。もう何も言われない。"}, {"id": "ch05-s03-p014", "type": "text", "text": "階段を上がった。二階の書架の間を通る。2-A、2-B、2-C。残響灯の青白い光。靴底が木の床を踏む音だけが、書架の間を通り抜けていく。"}, {"id": "ch05-s03-p015", "type": "text", "text": "二階の閲覧室に差しかかった時、窓の外の音が変わった。"}, {"id": "ch05-s03-p016", "type": "text", "text": "雨脚が強くなっている。閲覧室の窓は南向きで、窓ガラスの表面を雨粒が斜めに走っている。音が増えた。さっきまでの静かな霧雨ではなく、粒の一つ一つが窓ガラスに当たって鳴っている。ぱら、ぱら、ぱら。不規則だが途切れない。"}, {"id": "ch05-s03-p017", "type": "text", "text": "閲覧室を通り過ぎて、奥へ。"}, {"id": "ch05-s03-p018", "type": "text", "text": "記録室の扉が、十センチほど開いていた。"}, {"id": "ch05-s03-p019", "type": "text", "text": "かりかり。"}, {"id": "ch05-s03-p020", "type": "text", "text": "ペンの音。途切れない。俺の足音を聞いても止まらない。この音が止まらなくなったのは、五月の末からだった。扉の前に立っても止まらない。扉を開けても止まらない。俺が来ることが、前提になっている。"}, {"id": "ch05-s03-p021", "type": "text", "text": "扉を開けた。左側を持ち上げるようにして。蝶番は鳴らなかった。"}, {"id": "ch05-s03-p022", "type": "text", "text": "「朝霧さん」"}, {"id": "ch05-s03-p023", "type": "text", "text": "顔を上げずに。声だけ。ペンは動いたまま。"}, {"id": "ch05-s03-p024", "type": "text", "text": "「こんにちは」"}, {"id": "ch05-s03-p025", "type": "text", "text": "木箱に座った。机の角に近い定位置。座面の硬さと、腰の角度と、肘が少し上がる感覚に、体が迷いなく収まった。"}, {"id": "ch05-s03-p026", "type": "text", "text": "机の上に今日の分の下書きが置かれている。清書用紙とペンとインク壺。俺のインク壺は右寄り、篠宮さんのは左寄り。配置は変わらない。誰が決めたわけでもなく定まった領域。"}, {"id": "ch05-s03-p027", "type": "text", "text": "ペンを取った。インクをつけた。"}, {"id": "ch05-s03-p028", "type": "text", "text": "かりかり。"}, {"id": "ch05-s03-p029", "type": "text", "text": "二つのペンの音が記録室に落ちた。窓の外で雨が鳴っている。ぱら、ぱら、ぱら。ペンの音と雨の音。二種類の連続する音が、同じ空間の中にある。"}, {"id": "ch05-s03-p030", "type": "text", "text": "清書を進めた。今日の下書きは外円区東部の消滅者記録。三枚。一枚目の人名を転記しながら、窓の方を見た。小さな窓。西向き。今日は曇天だから光の方向がわかりにくい。灰色の光が均一に入り込んでいて、机の上に影ができない。夕方の橙の帯がない。その代わり、紙の白が普段より柔らかく見えた。"}, {"id": "ch05-s03-p031", "type": "text", "text": "一枚目を終えた。二枚目に入った。"}, {"id": "ch05-s03-p032", "type": "text", "text": "篠宮さんのペンの間隔が均一だった。かりかり。かりかり。小さく正確な字を紙の上に並べていく音。俺のペンの間隔はそれより少し遅い。清書は丁寧にやる。篠宮さんの下書きの字を一字ずつ確認して、清書用紙に移す。二つのペンの間隔がずれている。同じリズムではない。けれど同じ部屋の中に二つの音があることの——それ自体の感触が、何かに似ていた。"}, {"id": "ch05-s03-p033", "type": "text", "text": "雨の音。"}, {"id": "ch05-s03-p034", "type": "text", "text": "雨粒が窓ガラスに当たる音も、不規則で、一定ではない。けれど途切れない。途切れないことが、静けさの中にいてもいい理由になっているような。"}, {"id": "ch05-s03-p035", "type": "text", "text": "二枚目を終えた。三枚目に入った。"}, {"id": "ch05-s03-p036", "type": "text", "text": "篠宮さんのペンが止まった。"}, {"id": "ch05-s03-p037", "type": "text", "text": "音の変化に気づいた。一つ減った。雨の音だけになった。"}, {"id": "ch05-s03-p038", "type": "text", "text": "顔を上げた。"}, {"id": "ch05-s03-p039", "type": "text", "text": "篠宮さんがメモ帳を閉じて、ペンを机の上に置いていた。手が膝の上にある。腰のメモ帳ではなく、記録用の大きな帳面の方を閉じた。区切りがついたのだろう。"}, {"id": "ch05-s03-p040", "type": "text", "text": "首の銀の鍵が、わずかに揺れた。呼吸に合わせて。"}, {"id": "ch05-s03-p041", "type": "text", "text": "「……あの」"}, {"id": "ch05-s03-p042", "type": "text", "text": "篠宮さんの声。「あの」の後に間が来る。この間は長い。三秒。四秒。窓の外の雨が鳴っている。ぱら、ぱら。"}, {"id": "ch05-s03-p043", "type": "text", "text": "「朝霧さんは」"}, {"id": "ch05-s03-p044", "type": "text", "text": "ペンを置いた。清書の途中だったが、手を止めた。篠宮さんの声に向き直る。"}, {"id": "ch05-s03-p045", "type": "text", "text": "墨色の瞳がこちらを見ていた。いつも通りの表情——表情の振幅が小さい篠宮さんの、いつも通りの顔。けれど眉の角度がほんのわずかに上がっていた。内側に寄る方向ではなく、外側に開く方向に。質問をする時の顔、だろうか。篠宮さんの質問は業務的な確認が多い。「この文字は何と読みますか」「第三系統の出力は何デシベルでしたか」。その時の眉はまっすぐだった。今の眉は、ほんの少しだけ形が違う。"}, {"id": "ch05-s03-p046", "type": "text", "text": "「雨の日は、何をしていますか」"}, {"id": "ch05-s03-p047", "type": "text", "text": "声は平坦だった。いつもの篠宮さんの音量。けれど、質問の種類が違った。"}, {"id": "ch05-s03-p048", "type": "text", "text": "業務ではない。記録でもない。「第三系統の出力」でも「この文字の読み方」でもなく、俺が雨の日に何をしているかを聞いている。俺個人の行動を。俺個人の時間を。"}, {"id": "ch05-s03-p049", "type": "text", "text": "篠宮さんがこの種の質問をするのは——五月のあの日の、「出身は、不明なのですか」以来だった。あの時の声は半音低かった。今の声は半音低くはない。平坦なまま。けれど、質問の構造が同じだった。業務の外にある質問。篠宮さんが記録係としてではなく、篠宮雫として何かを知りたがっている構造。"}, {"id": "ch05-s03-p050", "type": "text", "text": "窓の外で雨が鳴った。ぱら、ぱら、ぱら。"}, {"id": "ch05-s03-p051", "type": "text", "text": "「特に何も」"}, {"id": "ch05-s03-p052", "type": "text", "text": "答えた。事実だった。雨の日の俺の行動に特別なものはない。"}, {"id": "ch05-s03-p053", "type": "text", "text": "「雨を見ている」"}, {"id": "ch05-s03-p054", "type": "text", "text": "付け足した。これも事実だった。鐘鋳塔の管理室の小窓から外を見る。窓の外に灰色の空があって、水の粒が落ちていく。それを見ている。鐘の時間以外、手が空いている時に。何を考えているわけでもない。水が落ちるのを見ている。それだけ。"}, {"id": "ch05-s03-p055", "type": "text", "text": "篠宮さんの瞬きが入った。一回。それから間が来た。"}, {"id": "ch05-s03-p056", "type": "text", "text": "間。"}, {"id": "ch05-s03-p057", "type": "text", "text": "雨の音が記録室を満たしている。ペンの音は二つとも止まっているから、この部屋にある連続音は雨だけだった。窓ガラスを叩く水の粒と、屋根に当たる水の層と、雨樋を伝う水の流れが、壁越しに聞こえている。"}, {"id": "ch05-s03-p058", "type": "text", "text": "「私も」"}, {"id": "ch05-s03-p059", "type": "text", "text": "篠宮さんの声が出た。"}, {"id": "ch05-s03-p060", "type": "text", "text": "間。"}, {"id": "ch05-s03-p061", "type": "text", "text": "「雨を見るのは、嫌いではありません」"}, {"id": "ch05-s03-p062", "type": "text", "text": "声は平坦だった。語尾は均等に処理されている。けれど、「嫌いではありません」という言い方を選んでいる。「好きです」ではない。篠宮さんは「好きです」をほとんど使わない。否定の否定で肯定を表す。「嫌いではない」が、篠宮さんの語彙における好意の表現だった。"}, {"id": "ch05-s03-p063", "type": "text", "text": "間。"}, {"id": "ch05-s03-p064", "type": "text", "text": "この間は長かった。五秒。六秒。篠宮さんの視線が窓に移っていた。小さな西向きの窓。灰色の光。ガラスの表面を斜めに走る水の筋。その向こうに、霞んだ空がある。"}, {"id": "ch05-s03-p065", "type": "text", "text": "「雨は」"}, {"id": "ch05-s03-p066", "type": "text", "text": "篠宮さんの声。"}, {"id": "ch05-s03-p067", "type": "text", "text": "「……全てを、同じように濡らしますから」"}, {"id": "ch05-s03-p068", "type": "text", "text": "声が小さくなっていた。いつもの図書館の音量よりも小さい。壁に届かない音量。俺と篠宮さんの間の、この机の幅だけを振動させる声。"}, {"id": "ch05-s03-p069", "type": "text", "text": "全てを、同じように濡らす。"}, {"id": "ch05-s03-p070", "type": "text", "text": "その言葉を聞いた時、ペンを持っていない右手の指先が、わずかに動いた。何かを書き留めようとする動作ではなかった。何かに触れようとする動作でもなかった。ただ、言葉が入ってきた場所——鳩尾の少し上、胸骨の裏側あたりに、温度の変化があった。冷たくなったのでも熱くなったのでもない。温度が、あると感じた。普段は感じない場所に、温度があると知覚した。"}, {"id": "ch05-s03-p071", "type": "text", "text": "雨は全てを同じように濡らす。"}, {"id": "ch05-s03-p072", "type": "text", "text": "屋根も、石畳も、残響桜の葉も、中庭の端に落ちた紙切れも。城壁も、教室棟の窓も、食堂の煙突も。区別しない。選ばない。ただ降って、触れたものを等しく濡らす。"}, {"id": "ch05-s03-p073", "type": "text", "text": "篠宮さんが記録をする時の姿勢と似ていた。消滅者のリストは、名前の大きさを変えない。功績のある人間を大きく書き、そうでない人間を小さく書くことはしない。一行ごとに一人分の幅があり、字の大きさは均等で、インクの量も一定。誰のことも同じ丁寧さで記録する。"}, {"id": "ch05-s03-p074", "type": "text", "text": "雨と記録。全てを同じように扱うもの。篠宮さんが雨を嫌いではない理由が、そこにあった。"}, {"id": "ch05-s03-p075", "type": "text", "text": "篠宮さんの視線が窓から戻ってきた。墨色の瞳が俺を見ている。表情は変わっていない。変わっていないように見える。けれど、さっき質問をした時の眉の角度が元に戻っていた。質問の眉ではなく、いつもの眉に。言いたいことを言い終えた後の、静かな顔。"}, {"id": "ch05-s03-p076", "type": "text", "text": "「……そうですね」"}, {"id": "ch05-s03-p077", "type": "text", "text": "俺が言った。言ってから、言葉が足りないと思った。「そうですね」は何も伝えていない。篠宮さんの言葉を受け取ったことしか伝えていない。けれど、それ以上の言葉は浮かばなかった。"}, {"id": "ch05-s03-p078", "type": "text", "text": "篠宮さんがペンを取り直した。新しい帳面を開いた。ペン先がインクに触れて、紙の上に降りた。"}, {"id": "ch05-s03-p079", "type": "text", "text": "かりかり。"}, {"id": "ch05-s03-p080", "type": "text", "text": "俺も清書に戻った。三枚目の途中。インクをつけ直して、次の行を書いた。"}, {"id": "ch05-s03-p081", "type": "text", "text": "かりかり。"}, {"id": "ch05-s03-p082", "type": "text", "text": "二つのペンの音が戻ってきた。雨の音と共に、記録室を満たす。ペンの音。雨の音。それだけ。声はない。会話はもう終わっていた。"}, {"id": "ch05-s03-p083", "type": "text", "text": "篠宮さんは何も追加しなかった。俺も何も聞き返さなかった。"}, {"id": "ch05-s03-p084", "type": "text", "text": "窓の外の雨が続いている。ぱら、ぱら、ぱら。途切れない。ペンの音も途切れない。二種類の音と、もう二種類の音。合計四つの連続する音が、記録室の中で重なっている。"}, {"id": "ch05-s03-p085", "type": "text", "text": "静かだった。"}, {"id": "ch05-s03-p086", "type": "text", "text": "四つの音があるのに、静かだった。無音の静けさではない。音が満ちているのに、静かだった。雨の日の図書館の記録室。窓の外は灰色で、光は均一で、影ができない。ペンの音が途切れず、雨の音が途切れない。"}, {"id": "ch05-s03-p087", "type": "text", "text": "ここにいることに理由がいらなかった。"}, {"id": "ch05-s03-p088", "type": "text", "text": "記録の清書は日課だった。毎日来ている。けれど今、ここに座っていることに対して——日課だから、とも、清書のため、とも、少し違う理由が加わっていた。加わったのがいつからかは特定できない。たぶん、特定する必要もない。"}, {"id": "ch05-s03-p089", "type": "text", "text": "ペンを持つ手が動いている。三枚目の清書が進む。名前を書いた。年齢を書いた。最終確認日を書いた。消えた人の記録を、雨の日の記録室で書いている。向かい側で篠宮さんが同じことをしている。"}, {"id": "ch05-s03-p090", "type": "text", "text": "静かで、冷たくない場所。"}, {"id": "ch05-s03-p091", "type": "text", "text": "鐘鋳塔の管理室も静かだ。しかしあの静けさは一人の静けさだった。ここの静けさは二人の静けさだった。ペンの音が二つあるから、沈黙ではない。会話がなくても、音が交わされている。"}, {"id": "ch05-s03-p092", "type": "text", "text": "清書を終えた。用紙を揃えて篠宮さんに渡した。篠宮さんの指が紙の端に触れた。一行ずつ確認して、引き出しに収めた。"}, {"id": "ch05-s03-p093", "type": "text", "text": "立ち上がった。木箱を戻さない。"}, {"id": "ch05-s03-p094", "type": "text", "text": "「では、また明日」"}, {"id": "ch05-s03-p095", "type": "text", "text": "篠宮さんが頷いた。顎が一センチほど下がって、戻る。いつもの頷き。"}, {"id": "ch05-s03-p096", "type": "text", "text": "記録室を出た。書架の間を通り、階段を降り、受付の前を過ぎて、扉を開けた。"}, {"id": "ch05-s03-p097", "type": "text", "text": "雨が降っていた。"}, {"id": "ch05-s03-p098", "type": "text", "text": "入った時より、少し弱くなっている。霧雨に近い。顔に当たる粒が細かくて、濡れているのか湿っているのかの境目が曖昧だった。"}, {"id": "ch05-s03-p099", "type": "text", "text": "傘を持っていなかった。行きも持っていなかった。鐘鋳塔まで走れば二分。濡れる量は大したことない。"}, {"id": "ch05-s03-p100", "type": "text", "text": "歩いた。走らなかった。"}, {"id": "ch05-s03-p101", "type": "text", "text": "石畳の上を雨が均一に覆っている。俺の靴が踏む場所も、踏まない場所も、同じように濡れている。全てを同じように濡らす、と篠宮さんが言った。"}, {"id": "ch05-s03-p102", "type": "text", "text": "覚えておく。"}, {"id": "ch05-s03-p103", "type": "text", "text": "雨の日の記録室で、篠宮さんが俺に私的な質問をしたことを。雨は全てを同じように濡らすという言葉を。四つの音が重なった静けさを。静かなのに冷たくなかった温度を。"}, {"id": "ch05-s03-p104", "type": "text", "text": "鐘鋳塔の管理室に戻って、髪についた水滴をタオルで拭いた。窓の外は灰色のまま。雨は降り続けている。"}, {"id": "ch05-s03-p105", "type": "text", "text": "管理室は静かだった。ペンの音は一つしかない。"}]}, {"chapter": 5, "chapterTitle": "夏の入り口", "scene": 4, "sceneTitle": "灯里村の名前", "wordCount": "約5,100字", "paragraphs": [{"id": "ch05-s04-p001", "type": "text", "text": "雨が弱くなっていた。"}, {"id": "ch05-s04-p002", "type": "text", "text": "管理室の窓から見る空は灰色のままだったが、水滴がガラスに当たる間隔が広がっていた。午前中の雨粒は連続した膜のようだった。今は一粒ずつ落ちてくる。音が数えられるようになっている。ぽつ、ぽつ。途切れの方が長い。"}, {"id": "ch05-s04-p003", "type": "text", "text": "十六時半。計器の最終値を記録して、ペンを置いた。"}, {"id": "ch05-s04-p004", "type": "text", "text": "鐘鋳塔を出た。石段を降りた。中庭の石畳が濡れて光っている。残響桜の葉から水滴が落ちた。枝が重そうに垂れている。四月の花弁は記憶の中にしかない。今あるのは濃い緑と、その緑を伝う水だけだった。"}, {"id": "ch05-s04-p005", "type": "text", "text": "灯籠通りに出た。"}, {"id": "ch05-s04-p006", "type": "text", "text": "灯りはまだ点っていなかった。点灯係の姿も見えない。十七時の鐘が鳴ってから灯りが入る。今はその手前の時間で、通りは灰色の空の光だけで照らされていた。煉瓦舗装が水を吸って、普段より色が深い。踏むと靴底に湿気が伝わる。"}, {"id": "ch05-s04-p007", "type": "text", "text": "商店の軒先から湿った空気が流れてきた。八百屋のおばさんが店先の野菜に布をかけている。雨よけ。干物屋の暖簾は畳まれたまま。雨の日の灯籠通りは音が少ない。四月に初めて歩いた時は声と匂いで満ちていたが、梅雨の夕方の通りは人がまばらだった。"}, {"id": "ch05-s04-p008", "type": "text", "text": "磨りガラスのドアが見えた。"}, {"id": "ch05-s04-p009", "type": "text", "text": "喫茶「残響」。看板の木の板が雨に濡れて黒ずんでいる。文字の輪郭が滲んで見えた。ドアの向こうから暖色の光が漏れている。裸電球の黄色い光。四月から変わらない色。"}, {"id": "ch05-s04-p010", "type": "text", "text": "ドアを開けた。カウベルが鳴った。低い、丸い音。"}, {"id": "ch05-s04-p011", "type": "text", "text": "中は温かかった。温度ではなく、空気の質が。外の灰色の湿気が、ドアの内側で切り替わる。コーヒーの匂いが最初に来て、木の匂いが追いかけてくる。裸電球の光が壁と天板を同じ色に染めている。飴色。天井のシミが油灯の煤で黒くなっている。テーブルの上の小さな油灯がゆらゆら揺れていた。"}, {"id": "ch05-s04-p012", "type": "text", "text": "「おや、朝霧くん」"}, {"id": "ch05-s04-p013", "type": "text", "text": "マスターの声。カウンターの向こうから。布巾でカップを拭いている手が止まらなかった。視線だけがこちらに来て、すぐにカップに戻る。"}, {"id": "ch05-s04-p014", "type": "text", "text": "「一人かい」"}, {"id": "ch05-s04-p015", "type": "text", "text": "「はい」"}, {"id": "ch05-s04-p016", "type": "text", "text": "「天城さんも来るんじゃないかね。さっき連絡があった」"}, {"id": "ch05-s04-p017", "type": "text", "text": "窓際の席に座った。いつもの席。四月に天城さんに連れてこられた時と同じテーブル。向かいの椅子は空いていた。"}, {"id": "ch05-s04-p018", "type": "text", "text": "マスターがコーヒーを持ってきた。黒い液面に湯気が立っている。カップの取っ手は右側。四月と同じ配置。"}, {"id": "ch05-s04-p019", "type": "text", "text": "コーヒーを見た。一口飲んだ。"}, {"id": "ch05-s04-p020", "type": "text", "text": "苦い。苦いが、苦いだけではない。四月に初めて飲んだ時は「おいしいのだと思います」だった。二度目はもう少し味の輪郭が見えた。三度目、四度目と重ねるうちに、味の構造が少しずつ読めるようになっていた。苦味の下に酸味がある。酸味の下に甘みがある。層になっている。全部を同時には掴めない。一口ごとに見える層が変わる。"}, {"id": "ch05-s04-p021", "type": "text", "text": "コーヒーの味に完全な名前はまだ付けられない。けれど「おいしい」は出る。間が短くなっている。"}, {"id": "ch05-s04-p022", "type": "text", "text": "カウベルが鳴った。"}, {"id": "ch05-s04-p023", "type": "text", "text": "「マスター、こんにちはー！」"}, {"id": "ch05-s04-p024", "type": "text", "text": "声。肺から出ている声。喫茶店の壁を満たす声量。天城さんの声は部屋の大きさに合わせて変わらない。食堂でも喫茶店でも同じ大きさで入ってくる。"}, {"id": "ch05-s04-p025", "type": "text", "text": "「蓮くん！ やっぱいた！」"}, {"id": "ch05-s04-p026", "type": "text", "text": "天城さんがテーブルの前に来た。栗色のポニーテールが揺れている。制服のブラウスに細かい水滴がついていた。走ってきたのか。傘を持っていないのかもしれない。肩のあたりが少し濡れている。"}, {"id": "ch05-s04-p027", "type": "text", "text": "「隣、いいでしょ」"}, {"id": "ch05-s04-p028", "type": "text", "text": "向かいの椅子ではなく、横に来た。カウンターに向かって「ミルク多めー！」と手を上げ、座った。テーブルの油灯が近い位置に来る。天城さんの横顔が油灯の光に照らされて、はしばみ色の瞳の中に小さな炎が映っていた。"}, {"id": "ch05-s04-p029", "type": "text", "text": "「雨、だいぶ弱くなったね。朝はすごかったのに」"}, {"id": "ch05-s04-p030", "type": "text", "text": "「午後から弱くなった。図書館を出た時はまだ降っていたけど、今はほとんど止みかけている」"}, {"id": "ch05-s04-p031", "type": "text", "text": "「図書館って、篠宮さんのとこ？ 毎日行ってるんだっけ」"}, {"id": "ch05-s04-p032", "type": "text", "text": "「清書がある」"}, {"id": "ch05-s04-p033", "type": "text", "text": "「蓮くん、マジメ」"}, {"id": "ch05-s04-p034", "type": "text", "text": "天城さんがにっと笑った。歯を見せて。頬が上がって、目が弧になる。マスターがミルク入りのコーヒーを運んできた。天城さんが両手でカップを包んだ。四月の夕方と同じ仕草だった。"}, {"id": "ch05-s04-p035", "type": "text", "text": "一口飲んで、「うん」と小さく頷く。"}, {"id": "ch05-s04-p036", "type": "text", "text": "窓の外を見ていた。磨りガラスの向こうに灯籠通りの輪郭が灰色に透けている。人影がゆっくり通り過ぎていく。雨粒がガラスの表面を伝っている。店内の裸電球の光とガラスの水滴が重なって、外の景色がぼやけていた。"}, {"id": "ch05-s04-p037", "type": "text", "text": "「ここ好きだなあ」"}, {"id": "ch05-s04-p038", "type": "text", "text": "天城さんが言った。カップの縁に唇を当てたまま。"}, {"id": "ch05-s04-p039", "type": "text", "text": "「灯籠通りが見えるでしょ、この窓から。夕方に灯りが入るのがさ。一つずつ、ぽつぽつって。あれ見てると、なんか安心する」"}, {"id": "ch05-s04-p040", "type": "text", "text": "灯りが入る順番を、天城さんは覚えている。南から順に。点灯係が一本ずつ火を入れていくのを、この窓から何度も見ていたのだろう。"}, {"id": "ch05-s04-p041", "type": "text", "text": "「あたしの家もさ、こんな感じだったんだよね」"}, {"id": "ch05-s04-p042", "type": "text", "text": "声の調子が変わらなかった。そのまま続いている。コーヒーを飲みながら、窓を見ながら。自然な流れ。何かのきっかけで話し始めたのではなく、灯籠通りの景色が、天城さんの中にある別の景色を呼び出していた。"}, {"id": "ch05-s04-p043", "type": "text", "text": "「灯里村っていうの。外円区の南端。海が近くて、畑が広くて。家はそんなに多くないんだけど、夕方になると道沿いの灯りが一つずつ点くんだよ。灯籠じゃなくてランプなんだけどね、油の。おじさんが台に登ってカチカチって火打ち石で点けてくの」"}, {"id": "ch05-s04-p044", "type": "text", "text": "灯里村。初めて聞く地名だった。天城さんが出身地の名前を具体的に出したのは——いつだったか。補佐官舎で「外円区から来た」と言ったことはある。けれど村の名前は出なかった。"}, {"id": "ch05-s04-p045", "type": "text", "text": "「海が見えるんだ、畑の向こうに。段々畑になっててね、高いところに登ると水平線が見えるの。朝はきらきらしてて。夕方は赤くなって。あたしいつも畑の石垣の上に座って見てた」"}, {"id": "ch05-s04-p046", "type": "text", "text": "天城さんの視線が窓の向こうにあった。磨りガラス越しの灯籠通りを見ているのではない。その先にある、ここにはない景色を見ていた。目の焦点が遠い。"}, {"id": "ch05-s04-p047", "type": "text", "text": "「畑仕事、大変だった？」"}, {"id": "ch05-s04-p048", "type": "text", "text": "聞いた。天城さんの話に問いかけを挟むのは、数えるほどしかしたことがない。大抵は天城さんが喋り続けて、俺は聞いている。今は聞きたかった。声を出す理由が体の中にあった。"}, {"id": "ch05-s04-p049", "type": "text", "text": "「大変っていうか、楽しかったんだよね。あたし一人じゃなかったし。同い年の子がいてさ、いつも一緒に畑仕事してて」"}, {"id": "ch05-s04-p050", "type": "text", "text": "天城さんの声が弾んだ。カップをテーブルに置いた。両手が膝の上に来た。"}, {"id": "ch05-s04-p051", "type": "text", "text": "「その子がね、走るのめちゃくちゃ速くて。畑の畝の間を競争するとあたし絶対負けるの。悔しくてさ、毎日勝負挑んでた。でも勝てなくて」"}, {"id": "ch05-s04-p052", "type": "text", "text": "笑っていた。目が細くなって、口の端が上がっている。思い出の中にいる笑い方。今この場所にいない誰かのことを話す時の、距離のある笑い方。"}, {"id": "ch05-s04-p053", "type": "text", "text": "「海に潜るのも上手で。あたしより長く息止められるの。あたしが先に上がると、いつも笑ってて——」"}, {"id": "ch05-s04-p054", "type": "text", "text": "声が止まった。"}, {"id": "ch05-s04-p055", "type": "text", "text": "止まり方に音がなかった。文の途中で切れたのではない。声のつながりが、一文字の手前で消えた。「笑ってて」の「て」の後に来るはずの音が、喉のどこかで詰まったように。"}, {"id": "ch05-s04-p056", "type": "text", "text": "天城さんの左手が動いた。"}, {"id": "ch05-s04-p057", "type": "text", "text": "ポニーテールの根元。黄色のヘアゴム。指先がゴムの結び目に触れた。無意識の動作。桜の下の弁当の時と同じ。灯里村の話をする時に手がそこへ行く。天城さんは自分の指がゴムに触れていることを知らない。"}, {"id": "ch05-s04-p058", "type": "text", "text": "「あの子……」"}, {"id": "ch05-s04-p059", "type": "text", "text": "天城さんの声が低くなっていた。さっきまでの弾んだ音量とは違う。テーブルの油灯の揺れだけが届く範囲の声。"}, {"id": "ch05-s04-p060", "type": "text", "text": "「えーっと、あの子の名前、なんだっけ……」"}, {"id": "ch05-s04-p061", "type": "text", "text": "左手がヘアゴムから離れた。右手がカップに戻った。カップの取っ手を指でなぞっている。目線がテーブルの上に落ちていた。油灯の火が天城さんの瞳に映っているが、瞳はその火を見ていなかった。もっと奥の、カップの中でも油灯の中でもない場所を見ていた。"}, {"id": "ch05-s04-p062", "type": "text", "text": "間があった。"}, {"id": "ch05-s04-p063", "type": "text", "text": "三秒。四秒。コーヒーの湯気がまっすぐ上がっている。天城さんの指がカップの取っ手を往復している。親指の腹が白い陶器の表面を滑る音が、静かな店内で聞こえていた。"}, {"id": "ch05-s04-p064", "type": "text", "text": "左薬指の布のリングが目に入った。布の繊維がほつれている。前に見た時より少し長くなっている気がした。布の端がわずかにめくれている。"}, {"id": "ch05-s04-p065", "type": "text", "text": "天城さんの口元が動いた。何か言おうとして、止まった。もう一度動いた。"}, {"id": "ch05-s04-p066", "type": "text", "text": "「ああ、なんでもない！ ちょっと忘れちゃった！」"}, {"id": "ch05-s04-p067", "type": "text", "text": "声の高さが戻っていた。"}, {"id": "ch05-s04-p068", "type": "text", "text": "切り替わるまでの時間。今回は——二秒。あの桜の下では一秒なかった。今回は少し長かった。声のトーンが低いところから高いところに跳ぶまでに、二秒の助走があった。その二秒の中に、天城さんの指がヘアゴムから離れてカップに移動する動作と、目線がテーブルの上から持ち上がる動作が、順番に入っていた。"}, {"id": "ch05-s04-p069", "type": "text", "text": "「同い年の子でさ、一緒に遊んでて。名前ど忘れしちゃった。あはは、あたしってこういうの多いんだよねー」"}, {"id": "ch05-s04-p070", "type": "text", "text": "笑っていた。顔全体で。歯を見せて。目が弧を描いている。食堂で初めて会った時と同じ笑い方。いつもの天城さんの笑い方。何もなかったかのように。"}, {"id": "ch05-s04-p071", "type": "text", "text": "五回目だった。"}, {"id": "ch05-s04-p072", "type": "text", "text": "食堂。喫茶「残響」。補佐官舎。桜の下。そして今。翳りが出て、笑顔に戻る。切り替えが速くなっていたパターンが、今回は逆に遅くなった。二秒の助走。桜の下では一秒なかった時間が、二秒かかった。"}, {"id": "ch05-s04-p073", "type": "text", "text": "天城さんは名前を「忘れた」と言った。"}, {"id": "ch05-s04-p074", "type": "text", "text": "忘れちゃった。"}, {"id": "ch05-s04-p075", "type": "text", "text": "その言葉を聞いた時、体の中で何かが照合された。五月の、桜の下。「忘れたくないことがあるんだけど、忘れちゃいそうで怖い」。あの時の天城さんの静かな声。風があれば散ってしまうような音量。膝の上のおにぎりを見つめていた目。"}, {"id": "ch05-s04-p076", "type": "text", "text": "忘れたくない。忘れちゃいそう。忘れちゃった。"}, {"id": "ch05-s04-p077", "type": "text", "text": "三つの言葉が並んだ。時系列の中に並んだ。「忘れたくない」が先にあり、「忘れちゃいそう」がその隣にあり、「忘れちゃった」が今日ここに来た。"}, {"id": "ch05-s04-p078", "type": "text", "text": "天城さんは同い年の幼馴染の名前を——忘れた。"}, {"id": "ch05-s04-p079", "type": "text", "text": "忘れたのか。本当に忘れたのか。それとも、思い出せないだけなのか。「忘れた」と「思い出せない」は同じではない。忘れたなら、もう戻らない。思い出せないなら、まだどこかにある。天城さんのあの二秒の間は、どちらだったのか。"}, {"id": "ch05-s04-p080", "type": "text", "text": "判断がつかなかった。"}, {"id": "ch05-s04-p081", "type": "text", "text": "天城さんの笑顔を見ていた。いつもの笑い方。けれど、さっきまでの灯里村の話をしていた時の笑い方とは種類が違った。灯里村の話の時は、思い出の中にいる笑い方だった。今の笑い方は、思い出の外に出た後の笑い方。中と外の境目が、あの二秒の間にあった。"}, {"id": "ch05-s04-p082", "type": "text", "text": "追及しなかった。"}, {"id": "ch05-s04-p083", "type": "text", "text": "桜の下の弁当の時と同じ判断。天城さんが自分で笑顔に戻した以上、俺がそこに踏み込む根拠がない。見えたものを記録して、そのままにしておく。それが今の俺にできることで、それ以上のことが正しいのかはわからない。"}, {"id": "ch05-s04-p084", "type": "text", "text": "「蓮くん、コーヒーもう一杯いく？ あたしおかわりしよっかな」"}, {"id": "ch05-s04-p085", "type": "text", "text": "天城さんの声が通常の音量に戻っていた。手を上げてマスターを呼んでいる。"}, {"id": "ch05-s04-p086", "type": "text", "text": "「マスター、おかわりー！ ミルク多めで！ 蓮くんは？」"}, {"id": "ch05-s04-p087", "type": "text", "text": "「同じで」"}, {"id": "ch05-s04-p088", "type": "text", "text": "マスターが頷いた。"}, {"id": "ch05-s04-p089", "type": "text", "text": "窓の外に目を向けた。磨りガラスの向こうで、灯籠通りの灯籠に灯りが入り始めていた。十七時の鐘がいつの間にか鳴っていたらしい。南の端から一つずつ。橙色の灯りが磨りガラスを通して滲んで見える。天城さんがさっき言った通りの順番で。"}, {"id": "ch05-s04-p090", "type": "text", "text": "天城さんもそれを見ていた。"}, {"id": "ch05-s04-p091", "type": "text", "text": "「ほら、点き始めた」"}, {"id": "ch05-s04-p092", "type": "text", "text": "声は明るかった。灯籠通りの灯りを指差す指先が、油灯の光に照らされている。"}, {"id": "ch05-s04-p093", "type": "text", "text": "俺は天城さんの横顔を見ていた。灯りを見ている天城さんの目は、さっき灯里村の景色を見ていた目と同じ距離感を持っていた。ここにある灯りと、ここにない灯りの両方を見ている目。"}, {"id": "ch05-s04-p094", "type": "text", "text": "おかわりのコーヒーが来た。天城さんがカップを受け取って、「あったかい」と声を漏らした。六月の夕方の喫茶店。湿度が高い。温かい飲み物が合う気候ではない。けれど天城さんはカップを両手で包んでいた。手の温度がほしいのかもしれない。"}, {"id": "ch05-s04-p095", "type": "text", "text": "コーヒーを飲んだ。二杯目。一杯目と同じ味のはずだが、少し違った。冷めかけた一杯目の味が舌に残っていて、熱い二杯目がその上に重なる。層が一つ増える。"}, {"id": "ch05-s04-p096", "type": "text", "text": "天城さんが灯籠通りの灯りを数えていた。「一個、二個、三個……」。声に出して。子供のように。指を折っていた。灯りが一つ点くたびに指が一本折れる。"}, {"id": "ch05-s04-p097", "type": "text", "text": "「十三個。いつもと同じ。灯里村のは九個だったんだよね。こっちのほうが多い」"}, {"id": "ch05-s04-p098", "type": "text", "text": "何気ない声。比較。灯りの数の比較。天城さんにとって、この灯籠通りの灯りは灯里村の灯りの延長線上にあるのかもしれない。数が違うだけで、光の意味は同じ。夕方に一つずつ点く灯り。"}, {"id": "ch05-s04-p099", "type": "text", "text": "灯里村の九個の灯り。走るのが速くて海に潜るのが上手な同い年の子。名前が出てこなかった子。"}, {"id": "ch05-s04-p100", "type": "text", "text": "天城さんが「忘れちゃった」と言った事実が、体の中にある。桜の下の「忘れちゃいそうで怖い」と重なっている。二つの言葉の間に、二ヶ月の時間がある。二ヶ月前は「忘れちゃいそう」だったものが、今日「忘れちゃった」に変わっていた。"}, {"id": "ch05-s04-p101", "type": "text", "text": "進行している。忘却が。天城さんの中で。"}, {"id": "ch05-s04-p102", "type": "text", "text": "俺には忘却の速度がわからない。自分の忘却は一括で来た。二年前より前の全部が、一度に。天城さんの忘却は違う。一つずつ。名前が。顔が。声が。一つずつ、順番に遠くなっていく。"}, {"id": "ch05-s04-p103", "type": "text", "text": "どちらが重いのか。判断できない。"}, {"id": "ch05-s04-p104", "type": "text", "text": "天城さんが立ち上がった。"}, {"id": "ch05-s04-p105", "type": "text", "text": "「あ、もうこんな時間。蓮くん、ご飯行かない？ 食堂まだ開いてるよ」"}, {"id": "ch05-s04-p106", "type": "text", "text": "声はいつもの天城さんだった。明るくて、真っ直ぐで、相手の方を向いている。カップを持ってカウンターに返しに行く。「マスター、ごちそうさまー」。大きな声。"}, {"id": "ch05-s04-p107", "type": "text", "text": "俺もカップを持って立った。"}, {"id": "ch05-s04-p108", "type": "text", "text": "「ごちそうさまでした」"}, {"id": "ch05-s04-p109", "type": "text", "text": "マスターが布巾を動かしながら頷いた。"}, {"id": "ch05-s04-p110", "type": "text", "text": "ドアを開けた。カウベルが鳴った。外の空気は湿っていたが、雨はもう止んでいた。灯籠通りの灯りが、濡れた煉瓦の上に橙色の反射を作っている。水溜まりの表面に灯りが映って、地面にもう一つの灯籠通りがあった。"}, {"id": "ch05-s04-p111", "type": "text", "text": "天城さんが先に歩き出した。半歩先。ポニーテールが左右に揺れるリズム。四月の初日と同じ間隔。黄色のヘアゴムが灯籠の光を受けて光った。色褪せた黄色。"}, {"id": "ch05-s04-p112", "type": "text", "text": "「蓮くん、遅い。ほら、ご飯ご飯」"}, {"id": "ch05-s04-p113", "type": "text", "text": "天城さんが振り返った。笑っている。灯籠の光の中で。"}, {"id": "ch05-s04-p114", "type": "text", "text": "忘れない。"}, {"id": "ch05-s04-p115", "type": "text", "text": "天城さんが「忘れちゃった」と言ったことを。灯里村の名前と、九個の灯りと、同い年の幼馴染の話をしていた時の遠い目と、名前が出てこなかった二秒の間と、左手がヘアゴムに触れた動作と、布リングのほつれが前より長くなっていたことを。"}, {"id": "ch05-s04-p116", "type": "text", "text": "歩幅を広げた。天城さんの半歩後ろについた。灯籠通りの灯りが二人の影を煉瓦の上に落としていた。"}]}, {"chapter": 5, "chapterTitle": "夏の入り口", "scene": 5, "sceneTitle": "過去への問い", "wordCount": "約5,200字", "paragraphs": [{"id": "ch05-s05-p001", "type": "text", "text": "食堂を出た時、端末が鳴った。"}, {"id": "ch05-s05-p002", "type": "text", "text": "燈花と二人で夕食を終えたところだった。焼き魚定食。燈花はおかわりをした。俺は一膳で足りた。灯籠通りを歩いている間、燈花の声は通常の明るさに戻っていた。九個の灯りの話も、名前が出てこなかった二秒の間も、灯籠通りの橙色の光の中では遠くなっている。遠くなっているだけで、消えたわけではない。体の中に残っている。"}, {"id": "ch05-s05-p003", "type": "text", "text": "端末の画面を見た。短い文面。"}, {"id": "ch05-s05-p004", "type": "text", "text": "『南門から入って教室棟の屋上に上がれ。非常階段の3階踊り場、左の扉。鍵は壊れている。——桐ヶ谷』"}, {"id": "ch05-s05-p005", "type": "text", "text": "燈花に「用事ができた」とだけ告げた。燈花は「おっけー、また明日ね！」と手を振って寮の方へ走っていった。ポニーテールの揺れが灯籠の光に溶けて、角を曲がって見えなくなった。"}, {"id": "ch05-s05-p006", "type": "text", "text": "教室棟に向かった。"}, {"id": "ch05-s05-p007", "type": "text", "text": "十八時。空はまだ明るかった。梅雨の灰色が夕方になって割れ、西の低い位置にだけ色が出ていた。橙と紫の境目がにじんでいる。雲の下端が赤く燃えて、その上は薄い藍色。一日中降っていた雨の名残で空気が湿っていた。石畳の表面に残る水の膜が夕焼けを映して、足元にもう一つの空がある。"}, {"id": "ch05-s05-p008", "type": "text", "text": "教室棟の非常階段は建物の北側に付いていた。外付けの鉄骨階段。錆びた手すり。生徒の姿はなかった。授業がない時間帯だから当然だが、ここを日常的に使う人間がいない気配があった。踊り場の隅に枯れ葉が溜まっている。掃除の手が入っていない。"}, {"id": "ch05-s05-p009", "type": "text", "text": "三階の踊り場。左の扉。銀色のドアノブ。回してみた。"}, {"id": "ch05-s05-p010", "type": "text", "text": "引っかかりなく回った。鍵が壊れている、と桐ヶ谷さんは書いていた。壊れている箇所を知っている。この学院の構造を把握している。管理局への定期報告の帰りに寄った、と午前中に言っていた。帰り道にしては方向が違う——そう午前中にも思った。この人は「寄る」ための理由を用意する人だ。"}, {"id": "ch05-s05-p011", "type": "text", "text": "扉を押した。"}, {"id": "ch05-s05-p012", "type": "text", "text": "風が来た。"}, {"id": "ch05-s05-p013", "type": "text", "text": "湿った風。六月の夕方の、重くて温い風。顔の左側を通り抜けて、後ろへ流れていった。扉の向こうに広がっていたのは、教室棟の屋上だった。"}, {"id": "ch05-s05-p014", "type": "text", "text": "コンクリートの床面。排水溝に沿って水たまりが残っている。低いフェンスが屋上の縁を囲んでいたが、高さは腰の位置ほどしかない。学院の建物としては管理が甘い。だから立入禁止にしているのだろう。"}, {"id": "ch05-s05-p015", "type": "text", "text": "空が広かった。"}, {"id": "ch05-s05-p016", "type": "text", "text": "教室棟は三階建てで、鐘鋳塔や図書館より低い。それでも屋上に立つと視界の上半分が全部空になった。鐘鋳塔のシルエットが北東に見えた。塔の上部が夕焼けの光を受けて、輪郭だけが黒く切り取られている。灯籠通りの灯りが南の方角に点々と並んでいた。小さい。ここから見ると、地上の灯りは星と同じくらいの大きさだった。"}, {"id": "ch05-s05-p017", "type": "text", "text": "そして——東の空の、低い位置に。"}, {"id": "ch05-s05-p018", "type": "text", "text": "薄い靄が見えた。"}, {"id": "ch05-s05-p019", "type": "text", "text": "水平線の少し上。夕焼けの赤が届かない場所。灰白色の帯が、空と海の境目を滲ませている。霧ではなかった。霧はもっと均一に広がる。あの靄は形が不安定で、ゆっくりと脈打つように輪郭が変わっていた。"}, {"id": "ch05-s05-p020", "type": "text", "text": "蝕域。"}, {"id": "ch05-s05-p021", "type": "text", "text": "学院の中にいると見えない。鐘鋳塔の中にいても見えない。建物の壁と日常の距離が、あの靄を視界から遠ざけている。屋上に立つと、遠くにある。遠くに、確かにある。"}, {"id": "ch05-s05-p022", "type": "text", "text": "「来たか」"}, {"id": "ch05-s05-p023", "type": "text", "text": "声。背後ではなく、右手の方から。"}, {"id": "ch05-s05-p024", "type": "text", "text": "フェンスに背を預けて立っている人影があった。黒いハーフコート。低いポニーテール。濃い緑のジャケットの袖が、コートの裾から覗いている。腰のマルチツールが夕焼けの光を鈍く反射していた。"}, {"id": "ch05-s05-p025", "type": "text", "text": "桐ヶ谷さんは腕を組んでいた。午前中の南門と同じ姿勢。壁に寄りかかる時に腕を組む癖——体が知っていると、午前中に確認した情報。"}, {"id": "ch05-s05-p026", "type": "text", "text": "琥珀色の瞳がこちらを向いていた。"}, {"id": "ch05-s05-p027", "type": "text", "text": "夕焼けの光の中で、琥珀の色が深くなっていた。午前中の曇り空の下で見た時より、温かい色に見える。光の角度が変わると色が変わる。人の瞳はそういうものだ。けれど午前中の琥珀色が「引き締まった色」だとすれば、今の琥珀色は「力をふっと抜いた色」だった。"}, {"id": "ch05-s05-p028", "type": "text", "text": "「すみません、遅くなりましたか」"}, {"id": "ch05-s05-p029", "type": "text", "text": "「いや。時間は指定していない」"}, {"id": "ch05-s05-p030", "type": "text", "text": "声が低かった。午前中と同じ。しかし午前中の声は南門の前で、昼休みの人の流れの中にあった。今は屋上で、二人だけだった。声の背景が違うと、同じ声でも質感が変わる。壁のない場所で聞く声は、反響がない分、剥き出しに聞こえる。"}, {"id": "ch05-s05-p031", "type": "text", "text": "桐ヶ谷さんの視線が俺から離れた。東の方角を見ている。蝕域の靄がある方向。"}, {"id": "ch05-s05-p032", "type": "text", "text": "「ここからだと見えるな」"}, {"id": "ch05-s05-p033", "type": "text", "text": "俺も東を見た。靄はさっきと同じ場所にあった。脈打つ輪郭。夕焼けの赤が薄れるにつれて、靄の灰白色がはっきりしてきていた。暗くなると目立つ類のものらしい。"}, {"id": "ch05-s05-p034", "type": "text", "text": "「縁際では、もっと近くに見えるんですか」"}, {"id": "ch05-s05-p035", "type": "text", "text": "「近い、というか——そこにいる」"}, {"id": "ch05-s05-p036", "type": "text", "text": "桐ヶ谷さんの声が平坦だった。事実を述べる声。「ここから見える靄」と「そこにいる」の間にある距離を、声の温度は埋めなかった。"}, {"id": "ch05-s05-p037", "type": "text", "text": "「蓮」"}, {"id": "ch05-s05-p038", "type": "text", "text": "名前だった。二回目。午前中に続いて、今日二回目の名前呼び。"}, {"id": "ch05-s05-p039", "type": "text", "text": "午前中は、口をついて出たような呼び方だった。癖。昔の癖。今回は違った。意図的に呼んでいる。俺の名前を呼ぶことを選んで、呼んでいる。"}, {"id": "ch05-s05-p040", "type": "text", "text": "鳩尾の奥が動いた。午前中と同じ場所。歯車の安心とも鐘の懐かしさとも違う、人の形をした反応。"}, {"id": "ch05-s05-p041", "type": "text", "text": "「この島に来てからどうだ。何か思い出したか」"}, {"id": "ch05-s05-p042", "type": "text", "text": "桐ヶ谷さんの目が俺に戻っていた。"}, {"id": "ch05-s05-p043", "type": "text", "text": "質問。仕事でも体調でも食事でもない質問。午前中の三つの確認項目のどれとも違う。これは——もっと深い場所にある問いだった。"}, {"id": "ch05-s05-p044", "type": "text", "text": "午前中の桐ヶ谷さんは「深入りするな」と言った。過去を掘り返すなと。無理にそうする必要はないと。あの声には刃物のような鋭さがあった。"}, {"id": "ch05-s05-p045", "type": "text", "text": "今、同じ人が「何か思い出したか」と聞いている。"}, {"id": "ch05-s05-p046", "type": "text", "text": "矛盾しているわけではない。「深入りするな」は俺に向けた言葉だった。俺が能動的に過去を掘り返すことへの制止。今の質問は、桐ヶ谷さんから俺への問いかけだった。俺が掘り返したかどうかではなく、何かが勝手に浮かんできていないかの確認。"}, {"id": "ch05-s05-p047", "type": "text", "text": "「何も。記憶は——戻っていません」"}, {"id": "ch05-s05-p048", "type": "text", "text": "事実を述べた。二年前より前の記憶は空白のまま。鐘の音の懐かしさも、歯車に触れた時の安心も、桐ヶ谷さんの声に体が反応することも、全部「体が覚えている」だけであって、記憶として像を結んでいるわけではない。"}, {"id": "ch05-s05-p049", "type": "text", "text": "「でも……」"}, {"id": "ch05-s05-p050", "type": "text", "text": "声を止めた。止めたのは自分の判断ではなく、言葉の方が自分で速度を落とした感覚だった。喉の手前で、出るか出ないかを迷っている言葉。"}, {"id": "ch05-s05-p051", "type": "text", "text": "桐ヶ谷さんは待っていた。催促しなかった。腕を組んだまま、フェンスに背を預けたまま、俺が続きを出すのを待っている。午前中の「深入りするな」の人と同じ人が、今は黙って待っている。"}, {"id": "ch05-s05-p052", "type": "text", "text": "「時々、夢を見ます」"}, {"id": "ch05-s05-p053", "type": "text", "text": "出た。"}, {"id": "ch05-s05-p054", "type": "text", "text": "「知らない場所の夢を。機械の音がする。海の匂いがする。どこかの——工房のような場所で、歯車を触っている。指の感触がある。金属の温度がある。けれど目が覚めると、場所の名前も、そこにいた人の顔も、何も残っていない」"}, {"id": "ch05-s05-p055", "type": "text", "text": "言いながら、自分の言葉を聞いていた。夢の話を他人にしたのは初めてだった。篠宮さんにも、天城さんにも、霜月さんにも言っていない。言う理由がなかった。桐ヶ谷さんには——言う理由が、体の中にあった。"}, {"id": "ch05-s05-p056", "type": "text", "text": "桐ヶ谷さんの表情が動いた。"}, {"id": "ch05-s05-p057", "type": "text", "text": "動いた、というのは正確ではない。固まった。一瞬だけ。午前中に瞳の奥で灯が灯って消えた時と似ていたが、今回は目の奥ではなく、顔全体だった。口元の線が硬くなり、眉の間にわずかな力が入り、顎が引かれた。一秒にも満たない変化。機械の定点記録なら誤差として処理される程度の振幅。"}, {"id": "ch05-s05-p058", "type": "text", "text": "それから、表情が戻った。戻ったのではなく、戻した。午前中と同じ構造。感情を格納する動作。軍人の姿勢に感情を収める所作。"}, {"id": "ch05-s05-p059", "type": "text", "text": "「……無理に思い出そうとしなくていい」"}, {"id": "ch05-s05-p060", "type": "text", "text": "声が低かった。午前中の「深入りするな」とは違う低さだった。「深入りするな」は制止の声だった。今の声は——何かを押さえつけている声。押さえつけているのは俺ではなく、桐ヶ谷さん自身の中にあるものだった。"}, {"id": "ch05-s05-p061", "type": "text", "text": "「今の生活に集中しろ。鐘鋳塔の仕事。学院の人間関係。そっちに目を向けておけ」"}, {"id": "ch05-s05-p062", "type": "text", "text": "具体的だった。鐘鋳塔。学院。俺の「今」の構成要素を二つ挙げて、そこに留まれと言っている。"}, {"id": "ch05-s05-p063", "type": "text", "text": "ダブルミーニング、という言葉が頭の中を過ぎった。語学の概念だ。一つの文に二つの意味を載せること。桐ヶ谷さんの「無理に思い出そうとしなくていい」は、気遣いだった。夢の内容が不安なら無理に追わなくていい。それが表の意味。"}, {"id": "ch05-s05-p064", "type": "text", "text": "裏の意味があるのかどうかは、わからなかった。"}, {"id": "ch05-s05-p065", "type": "text", "text": "桐ヶ谷さんの声の中に、「思い出さないほうがいい」という音が含まれていた気がした。気がした、であって確信ではない。声の温度から推測するには情報が足りない。しかし午前中の「深入りするな」と、今の「無理に思い出そうとしなくていい」が同じ方角を向いていることは感じ取れた。"}, {"id": "ch05-s05-p066", "type": "text", "text": "この人は、俺の過去の中に、知られると困るものがあることを知っている。"}, {"id": "ch05-s05-p067", "type": "text", "text": "そして、それを俺に知らせまいとしている。"}, {"id": "ch05-s05-p068", "type": "text", "text": "隠しているのではない。守っている。午前中に瞳の中で確認したことと同じ結論に、もう一度たどり着いた。"}, {"id": "ch05-s05-p069", "type": "choice_header", "text": "---\n**【選択肢】**"}, {"id": "ch05-s05-p070", "type": "choice", "text": "**A: 「前の俺はどんな人間でしたか」と聞く** → 隠しフラグ（記憶への態度：積極的）"}, {"id": "ch05-s05-p071", "type": "text", "text": "沈黙があった。風が屋上を横切った。髪が揺れた。フェンスの向こうの蝕域の靄が、ゆっくりと形を変えている。"}, {"id": "ch05-s05-p072", "type": "text", "text": "「桐ヶ谷さん」"}, {"id": "ch05-s05-p073", "type": "text", "text": "声が出た。考えた末に出た声だった。体が先に動いたのではなく、頭が判断して出した声。"}, {"id": "ch05-s05-p074", "type": "text", "text": "「前の俺は——どんな人間でしたか」"}, {"id": "ch05-s05-p075", "type": "text", "text": "桐ヶ谷さんの肩が動いた。わずかに。腕を組んだまま、肩の筋肉が一瞬だけ緊張して、弛緩した。"}, {"id": "ch05-s05-p076", "type": "text", "text": "長い間があった。三秒。四秒。鐘鋳塔のシルエットが夕闇の中で黒さを増していた。"}, {"id": "ch05-s05-p077", "type": "text", "text": "「……真面目で、不器用で、手先が器用で」"}, {"id": "ch05-s05-p078", "type": "text", "text": "桐ヶ谷さんの声が、低いまま少しだけ柔らかくなった。午前中の「そうか」の三回目に近い声。受け止めるだけの声。"}, {"id": "ch05-s05-p079", "type": "text", "text": "「あと、妙に律儀な奴だった。今と変わらない」"}, {"id": "ch05-s05-p080", "type": "text", "text": "今と変わらない。その一言が、体の中に落ちた。二年前より前の自分と、今の自分が、一本の線でつながる感覚。記憶がなくても、性質は残っている。手が歯車の扱いを覚えているように、人格の輪郭も残っている。"}, {"id": "ch05-s05-p081", "type": "text", "text": "桐ヶ谷さんは、それ以上は言わなかった。問いの答えとして過不足のない分量。それ以上話すと、「深入り」の領域に入ることを知っている人の切り方だった。"}, {"id": "ch05-s05-p082", "type": "choice", "text": "**B: 聞かない** → 隠しフラグ（記憶への態度：受動的）"}, {"id": "ch05-s05-p083", "type": "text", "text": "聞きたかった。喉の途中まで言葉が来ていた。前の俺はどういう人間だったのか。桐ヶ谷さんはそれを知っている。"}, {"id": "ch05-s05-p084", "type": "text", "text": "けれど喉の途中で、言葉を止めた。"}, {"id": "ch05-s05-p085", "type": "text", "text": "午前中の琥珀色の瞳を思い出していた。真っ直ぐ見たまま口を閉じる目。隠す人の目は逸らす。守る人の目は、見たまま黙る。桐ヶ谷さんの目は真っ直ぐだった。今もそうだった。"}, {"id": "ch05-s05-p086", "type": "text", "text": "この人が口を閉じているなら、そこには理由がある。俺にはまだその理由が見えない。見えないものを、力ずくで開けるべきではない。"}, {"id": "ch05-s05-p087", "type": "text", "text": "「わかりました。今のことに集中します」"}, {"id": "ch05-s05-p088", "type": "text", "text": "そう答えた。桐ヶ谷さんの目がわずかに細くなった。安堵なのか、別の何かなのか。判別はつかなかった。"}, {"id": "ch05-s05-p089", "type": "divider", "text": "---"}, {"id": "ch05-s05-p090", "type": "text", "text": "風が吹いた。東からの風。蝕域の方角から来る風に匂いはなかった。六月の湿った空気と、コンクリートが吸った雨水の匂いだけが鼻に届いた。蝕域は遠い。遠いけれど、ある。"}, {"id": "ch05-s05-p091", "type": "text", "text": "桐ヶ谷さんがフェンスから背を離した。腕を解いた。ハーフコートの裾が風に揺れた。午前中と同じ、去り際の動作。この人は長居をしない。"}, {"id": "ch05-s05-p092", "type": "text", "text": "「蓮」"}, {"id": "ch05-s05-p093", "type": "text", "text": "三回目。今日三回目の名前。"}, {"id": "ch05-s05-p094", "type": "text", "text": "午前中の南門での一回目は、癖。呼び出した時の二回目は、意図的な呼びかけ。三回目は——どちらでもなかった。声の中に力が抜けていた。名前を呼ぶことそのものが目的の声。確認でも呼びかけでもなく、ただ名前を口にしたかっただけの声。"}, {"id": "ch05-s05-p095", "type": "text", "text": "桐ヶ谷さんは扉の方へ歩き出していた。軍人の歩幅。正確で、規則的。しかし午前中の南門での歩き方よりも、半歩だけ遅かった。"}, {"id": "ch05-s05-p096", "type": "text", "text": "扉に手をかけた。ドアノブを掴んだ指が、一瞬だけ止まった。振り返りはしなかった。背中だけがこちらを向いている。午前中の南門と同じ構図。"}, {"id": "ch05-s05-p097", "type": "text", "text": "「元気そうでよかった」"}, {"id": "ch05-s05-p098", "type": "text", "text": "小さい声だった。"}, {"id": "ch05-s05-p099", "type": "text", "text": "屋上の風があと少し強ければ聞こえなかっただろう。声量を制御している人の声ではなかった。制御を外した声。声の大きさを選ぶ余裕がなく、そのまま出てきた声。"}, {"id": "ch05-s05-p100", "type": "text", "text": "午前中の「元気でいろ」を思い出した。あれは命令でも願いでもない、その中間の声だった。低くて、まっすぐで、報告書には書けない種類の声。"}, {"id": "ch05-s05-p101", "type": "text", "text": "「元気でいろ」は、未来に向けた言葉だった。元気であれ、と。これからも。"}, {"id": "ch05-s05-p102", "type": "text", "text": "「元気そうでよかった」は、今を見た言葉だった。今の蓮を見て、元気だと確認して、それを喜んでいる。"}, {"id": "ch05-s05-p103", "type": "text", "text": "二つの言葉の間に、半日の時間がある。午前中に「元気でいろ」と言って去った人が、夕方にもう一度来て、「元気そうでよかった」と言っている。午前中の確認だけでは足りなかったのか。一度見ただけでは安心できなかったのか。"}, {"id": "ch05-s05-p104", "type": "text", "text": "そういうことなのだろう。"}, {"id": "ch05-s05-p105", "type": "text", "text": "桐ヶ谷さんの背中が扉の向こうに消えた。鉄の扉が閉まる音が、屋上の空気を一瞬だけ震わせた。足音が非常階段を降りていく。規則的な音。一段ずつ。遠くなっていく。"}, {"id": "ch05-s05-p106", "type": "text", "text": "一人になった。"}, {"id": "ch05-s05-p107", "type": "text", "text": "屋上のコンクリートの上に立って、東の空を見ていた。蝕域の靄は夕闇の中でぼんやりと光っていた。灰白色。脈打つ輪郭。あの向こうに何があるのか、俺は知らない。俺の夢の中の場所が、あの靄の向こうにあるのかどうかも。"}, {"id": "ch05-s05-p108", "type": "text", "text": "知らない場所の夢。機械の音。海の匂い。歯車を触る指。"}, {"id": "ch05-s05-p109", "type": "text", "text": "桐ヶ谷さんは、あの夢の場所を知っているのかもしれない。俺の過去を知っている人が、「無理に思い出そうとしなくていい」と言った。その言葉の奥にあるものを、今の俺には正確に読み取れない。"}, {"id": "ch05-s05-p110", "type": "text", "text": "けれど、信じている。"}, {"id": "ch05-s05-p111", "type": "text", "text": "体が信じている。歯車に触れた時に手が適正値を知っているのと同じ確かさで、桐ヶ谷さんは敵ではないと体が言っている。この人が黙っているなら、黙る理由がある。その理由は俺を傷つけるためではない。"}, {"id": "ch05-s05-p112", "type": "text", "text": "根拠は目の前の琥珀色の瞳だった。もう目の前にはないが、体の中に残っている。"}, {"id": "ch05-s05-p113", "type": "text", "text": "風が止んだ。"}, {"id": "ch05-s05-p114", "type": "text", "text": "鐘鋳塔のシルエットが完全に黒くなっていた。空の橙色は西の端に細い線だけ残して、あとは藍色に沈んでいた。灯籠通りの灯りが地上で列をなしている。十三個。天城さんが数えていた数と同じ。"}, {"id": "ch05-s05-p115", "type": "text", "text": "屋上の扉に手をかけた。ドアノブを回す。引っかかりなく回る。鍵が壊れている扉。桐ヶ谷さんはこの場所を知っていた。学院の構造だけではなく、「二人きりで話せる場所」を知っていた。以前も使ったことがあるのかもしれない。俺と。記憶の中の俺と。"}, {"id": "ch05-s05-p116", "type": "text", "text": "非常階段を降りた。鉄の手すりが冷たかった。六月なのに。金属は空気より早く冷える。歯車と同じ。金属の温度変化は空気に先行する。そういうことを、手が知っている。"}, {"id": "ch05-s05-p117", "type": "text", "text": "教室棟の裏に出た。中庭を横切って、補佐官舎に向かった。残響桜の葉が夜風に揺れていた。水滴が落ちて、石畳の上で弾けた。"}, {"id": "ch05-s05-p118", "type": "text", "text": "口の中で、桐ヶ谷さんの言葉を反芻していた。"}, {"id": "ch05-s05-p119", "type": "text", "text": "「元気そうでよかった」。"}, {"id": "ch05-s05-p120", "type": "text", "text": "あの声の温度は、午前中の「元気でいろ」と同じ場所から来ていた。命令でも願いでもない。もっと古い場所。俺の記憶にはないが、体が知っている場所。桐ヶ谷さんの声と、俺の体の記憶が、同じ場所を指している。"}, {"id": "ch05-s05-p121", "type": "text", "text": "その場所の名前を、俺はまだ知らない。"}, {"id": "ch05-s05-p122", "type": "text", "text": "知らないまま、体が覚えていることがある。"}, {"id": "ch05-s05-p123", "type": "text", "text": "屋上の夕焼けと、蝕域の靄と、桐ヶ谷さんの琥珀色の瞳と、「無理に思い出そうとしなくていい」の声の硬さと、「元気そうでよかった」の声の柔らかさと、扉に手をかけた時に指が一瞬止まった動作を。"}, {"id": "ch05-s05-p124", "type": "text", "text": "補佐官舎の鍵を開けた。暗い部屋に入った。机の上に、残響祭の夜にポケットに入れた花弁がまだ置いてある。乾燥して色が褪せていたが、形は残っていた。"}, {"id": "ch05-s05-p125", "type": "text", "text": "靴を脱いだ。ベッドに座った。窓の外は暗い。鐘鋳塔の灯りだけが、北東の空に青白く見えていた。"}, {"id": "ch05-s05-p126", "type": "text", "text": "夢を見るだろう。今夜も。知らない場所の夢を。"}, {"id": "ch05-s05-p127", "type": "text", "text": "けれど、夢の中の場所を知っている人がいるということは——あの場所は、本当にあるのだろう。"}]}, {"chapter": 6, "chapterTitle": "鐘の音の下で", "scene": 1, "sceneTitle": "共鳴室", "wordCount": "約6,000字", "paragraphs": [{"id": "ch06-s01-p001", "type": "text", "text": "共鳴者訓練棟の階段を降りると、空気が変わった。"}, {"id": "ch06-s01-p002", "type": "text", "text": "地上階の石と木の匂いが薄れ、もっと硬い、鉱物に近い匂いが鼻に届く。鐘鋳塔の地下とは種類が違う。あちらは歯車の潤滑油と古い石。こちらは——何と言えばいいか。金属を叩いた後に立つ匂いに似ている。残響金属。鐘鋳塔の大鐘と同じ材料で、この壁は覆われている。"}, {"id": "ch06-s01-p003", "type": "text", "text": "階段の幅は人二人分。手すりは磨かれた真鍮。残響灯が等間隔に壁に埋め込まれていた。青白い光が階段の段差に影を刻んでいる。七段降りるごとに踊り場があり、踊り場のたびに光の色がわずかに変わった。青白から、紫がかった白へ。鐘鋳塔の螺旋階段を上る時と逆の変化だった。あちらは上に行くほど紫が深くなる。ここは下に行くほど。"}, {"id": "ch06-s01-p004", "type": "text", "text": "地下二階。"}, {"id": "ch06-s01-p005", "type": "text", "text": "踊り場の壁に銅版のプレートが埋め込まれている。「共鳴室」。文字の下に記号がある。鐘鋳塔の壁面に刻まれた残響紋と同じ形。線が直線ではなく、緩やかに曲がっている。天蓋の間の壁紋に近い曲線。"}, {"id": "ch06-s01-p006", "type": "text", "text": "丸い扉があった。"}, {"id": "ch06-s01-p007", "type": "text", "text": "楕円ではなく、真円。扉の直径は二メートルほど。潜水艦のハッチに似ている。潜水艦を見たことはないが、図鑑の写真にあった。ハンドルを回す形式ではなく、壁面のレバーを引くと、扉が手前にスライドする。ゴム製のシールが見えた。気密。防音のための構造。"}, {"id": "ch06-s01-p008", "type": "text", "text": "扉の向こうに、球形の空間が広がっていた。"}, {"id": "ch06-s01-p009", "type": "text", "text": "直径十メートルほど。壁面が全て曲面。天井も床も、緩やかなカーブを描いている。立っている場所だけが平坦で、円形のステージのようにわずかに盛り上がっていた。壁面の全体が残響紋で覆われている。鐘鋳塔の壁面よりも細かい紋様。渦巻きと直線が交差し、幾何学模様が球面に沿って連なっている。材質は鐘鋳塔と同じ、あの灰色がかった白い金属。残響金属。"}, {"id": "ch06-s01-p010", "type": "text", "text": "残響灯が壁面の紋様の間に点在していた。淡い紫色の光。鐘鋳塔の地下と色が似ている。光源が一つではなく、壁面の至る所に散らばっているため、影がほぼない。自分の足元に影がない。それが少し落ち着かなかった。影のない場所は、体の輪郭を不確かにする。"}, {"id": "ch06-s01-p011", "type": "text", "text": "空気が密だった。"}, {"id": "ch06-s01-p012", "type": "text", "text": "防音の球形空間。外の音が一切入ってこない。自分の呼吸だけが聞こえる。吸って、吐いて。呼吸に混じって、鼓膜の内側の血流音が微かに感じ取れた。静寂の密度が高い場所では、体の中の音が外に聞こえるようになる。鐘鋳塔の管理室も静かだったが、計器の針の震動音や歯車の低い振動があった。ここにはそれがない。完全に、何もない。"}, {"id": "ch06-s01-p013", "type": "text", "text": "音響計測機器は球体の壁面に三か所、等間隔で設置されている。周波数分析器、音圧レベル計、残響波検出装置。どれも鐘鋳塔の管理室にあるものと同型だった。手が操作を覚えている。電源を入れ、初期校正を走らせ、記録用紙をセットした。計器の針がゼロ点で静止する。今日の気温と湿度を記入。七月上旬。地下だから地上より涼しいが、湿度は高めだった。"}, {"id": "ch06-s01-p014", "type": "text", "text": "丸い扉が開く音がした。ゴムシールが空気を噛む、くぐもった音。"}, {"id": "ch06-s01-p015", "type": "text", "text": "鳴海さんが入ってきた。"}, {"id": "ch06-s01-p016", "type": "text", "text": "白いブラウスに淡いブルーのスカート。制服のままだった。ただ一つ違うのは、首に細い銀のチョーカーがある。薄い金属の帯が首の正面で留められ、残響紋の小さな刻印が留め具の表面に見えた。訓練用の装具。共鳴の制御に使うものだと、業務資料で読んだことがある。"}, {"id": "ch06-s01-p017", "type": "text", "text": "カーディガンはなかった。腕が出ている。二の腕は細い。華奢、と呼ぶべき線の細さだった。"}, {"id": "ch06-s01-p018", "type": "text", "text": "右前髪に薄桃色のリボン。亜麻色の髪が残響灯の紫の光を受けて、いつもと違う色に見えた。灯籠通りの橙色の下では蜂蜜に近い色。響弦館の白い残響灯の下では金に透ける。ここでは——藤色がかった、柔らかい銀に近い。光で人の色が変わる。同じ人なのに、場所と光で別の形になる。"}, {"id": "ch06-s01-p019", "type": "text", "text": "「朝霧さん、今日もよろしくお願いします」"}, {"id": "ch06-s01-p020", "type": "text", "text": "鳴海さんが軽く頭を下げた。穏やかな微笑み。いつもの。口元と目がほぼ同時に動く。声が球形の壁に跳ね返り、わずかな残響を伴って耳に届いた。話し声ですらこの部屋は残響を生む。壁面の残響金属が声を拾い、増幅する。"}, {"id": "ch06-s01-p021", "type": "text", "text": "「こちらこそ。計器は準備できています」"}, {"id": "ch06-s01-p022", "type": "text", "text": "短い会話。業務上の挨拶。それだけのはずだった。"}, {"id": "ch06-s01-p023", "type": "text", "text": "けれど俺は、鳴海さんの目を見ていた。琥珀がかった茶色の瞳。今日はまだ歌っていない。瞳の色が濃い。響弦館の公演後に見た時は、色がわずかに薄く見えた。今は深い。琥珀の底まで光が通っている。"}, {"id": "ch06-s01-p024", "type": "text", "text": "歌う前と、歌った後で、色が変わる目。"}, {"id": "ch06-s01-p025", "type": "text", "text": "「少し広くなった気がします」"}, {"id": "ch06-s01-p026", "type": "text", "text": "鳴海さんが球形の壁面を見回しながら言った。微笑みが小さくなり、目が壁の紋様を辿っている。二回目の訪問ではないらしい。何度もこの部屋で歌っている人の目だった。それでも毎回、少し見回す。"}, {"id": "ch06-s01-p027", "type": "text", "text": "「では、始めますね」"}, {"id": "ch06-s01-p028", "type": "text", "text": "鳴海さんが球体の中央に立った。"}, {"id": "ch06-s01-p029", "type": "text", "text": "俺は壁面の計測器の横にいた。距離は四メートル。響弦館の客席は最前列でもステージまで五メートル以上あった。訓練棟の外壁越しは壁の厚さを含めて十メートル以上。灯籠通りで隣を歩いた時は一メートル弱だったが、あの時は歌っていなかった。"}, {"id": "ch06-s01-p030", "type": "text", "text": "四メートル。歌う鳴海さんとの距離としては、最も近い。"}, {"id": "ch06-s01-p031", "type": "text", "text": "鳴海さんが目を閉じた。"}, {"id": "ch06-s01-p032", "type": "text", "text": "背筋が伸びた。両手が体の横に下がり、指先が軽く開いた。呼吸が変わった。肩が上がり、胸が膨らみ——。"}, {"id": "ch06-s01-p033", "type": "text", "text": "響弦館で見た、あの準備と同じ動作。"}, {"id": "ch06-s01-p034", "type": "text", "text": "だが空気が違う。響弦館には八百人の視線と期待があった。ここには俺しかいない。八百人分の期待が消えた空間で、鳴海さんが呼吸を整えている。穏やかな微笑みは消えていた。目を閉じた顔は、何の表情もない。何もないのに——響弦館の時と同じだ——目が離せない。"}, {"id": "ch06-s01-p035", "type": "text", "text": "声が出た。"}, {"id": "ch06-s01-p036", "type": "text", "text": "最初の一音。"}, {"id": "ch06-s01-p037", "type": "text", "text": "空気が裂けた。裂けて、つながった。球形の壁面が一斉に鳴った。残響金属が声を拾い、反射し、増幅し、四方から音が戻ってきた。天井から。足元から。背後から。壁面の全ての点から、鳴海さんの声が反射して俺の体に当たった。"}, {"id": "ch06-s01-p038", "type": "text", "text": "響弦館とは違う。"}, {"id": "ch06-s01-p039", "type": "text", "text": "響弦館の音は三方向から来た。天吊りと左右の拡声器。方向があった。ここには方向がない。音がどこから来ているかわからない。全ての方向から同時に来る。鳴海さんの声が球体の内壁で無数に反射し、反射した声が反射して、さらに反射して、空間全体が声で満ちた。"}, {"id": "ch06-s01-p040", "type": "text", "text": "声の中にいる。"}, {"id": "ch06-s01-p041", "type": "text", "text": "水に浸かるのと似ていた。水は全身を同時に包む。方向がない。声も同じだった。前から聞こえる声と後ろから聞こえる声が融合して、体の表面を均等に包んでいる。耳だけで聴いていない。皮膚が聴いている。腕の産毛が震えている。"}, {"id": "ch06-s01-p042", "type": "text", "text": "旋律が立ち上がった。"}, {"id": "ch06-s01-p043", "type": "text", "text": "低い音。胸の底に触れる振動。響弦館の時と同じ始まり方。しかし密度が違う。四メートルの距離と球形の反射壁が、音の密度を何倍にも高めていた。一粒一粒の音が、重い。"}, {"id": "ch06-s01-p044", "type": "text", "text": "鳩尾が緩んだ。"}, {"id": "ch06-s01-p045", "type": "text", "text": "一回目——訓練棟の外壁越し。鳩尾の筋肉が緩む感覚。\n二回目——灯籠通りで隣を歩いた後。同じ場所の、少し深い緩み。\n三回目——響弦館の八百席。鳩尾の奥にあるものが溶けた。\n四回目。"}, {"id": "ch06-s01-p046", "type": "text", "text": "鳩尾ではなかった。"}, {"id": "ch06-s01-p047", "type": "text", "text": "胸の中央。鳩尾より上。心臓に近い場所。肋骨の内側で何かが震えている。鳴海さんの声と同じ周波数で——共振している。体の中に音叉がある。鳴海さんの声がその音叉を鳴らしている。"}, {"id": "ch06-s01-p048", "type": "text", "text": "鐘の音に似ている。"}, {"id": "ch06-s01-p049", "type": "text", "text": "そう感じた。四月の最初の朝に聴いた、鐘鋳塔の朝鐘。あの音に体が反応した。心地よいと感じた。懐かしいと感じた。鳴海さんの声にも、同じ反応が起きている。心地よさ。懐かしさ。その奥にある——名前のつかない何か。"}, {"id": "ch06-s01-p050", "type": "text", "text": "声が高音域に入った。"}, {"id": "ch06-s01-p051", "type": "text", "text": "光が見えた。響弦館でも同じことが起きた。音が光に聞こえる。耳で聴いているのに、目の奥に白い線が走る。球形の壁面の残響紋が——光っていた。紋様の溝に沿って、かすかな燐光が流れている。鳴海さんの声に呼応して、壁が発光していた。これが残響波の視覚的な現象なのか。計器を見た。残響波検出装置の針が大きく振れている。通常観測値の三倍以上。数値を記録用紙に書き込んだ。手が動いた。仕事だった。"}, {"id": "ch06-s01-p052", "type": "text", "text": "——仕事なのに、手が震えていた。"}, {"id": "ch06-s01-p053", "type": "text", "text": "胸が温かい。"}, {"id": "ch06-s01-p054", "type": "text", "text": "鐘の音を聴いた時と同じ温かさ。鳩尾ではなく胸の中央にある温かさ。血液がわずかに速く流れている感覚。指先が温い。冬ではないのに、指先の温度を自覚している。"}, {"id": "ch06-s01-p055", "type": "text", "text": "同時に——痛い。"}, {"id": "ch06-s01-p056", "type": "text", "text": "温かさの裏側に、痛みがある。鳩尾の緩みには痛みがなかった。三回とも。今回の胸の温かさには、薄い痛みが重なっている。釘が刺さっているのではない。もっと広い、もっとぼんやりした痛み。温かさと痛みが同じ場所にある。なぜ痛いのかわからない。体が知っていて、頭が追いつかない。"}, {"id": "ch06-s01-p057", "type": "text", "text": "鳴海さんの声が頂点に達した。"}, {"id": "ch06-s01-p058", "type": "text", "text": "球形の空間が震えていた。壁面の残響紋が明滅している。光の脈拍。鳴海さんの呼吸に合わせて、光が波打つ。この部屋自体が一つの楽器になっている。鳴海さんがそれを弾いている。弾いている、というのは正確ではない。鳴海さんが声を出し、部屋が応え、応えた音が鳴海さんの声に混ざり、混ざった声がまた壁に当たる。循環。終わりのない循環。鳴海さんと部屋が一つの系になっている。"}, {"id": "ch06-s01-p059", "type": "text", "text": "旋律が降りていった。"}, {"id": "ch06-s01-p060", "type": "text", "text": "高音域から中音域へ。川が山から平野に流れ出るように、声の勢いが変わった。急流から、深い淵へ。声量は落ちていない。密度が変わった。水平に広がるのではなく、垂直に沈んでいく声。体の中の深い場所まで届く声。"}, {"id": "ch06-s01-p061", "type": "text", "text": "最後の一音。"}, {"id": "ch06-s01-p062", "type": "text", "text": "長かった。十五秒か、二十秒か。時間の感覚が歪んでいた。最後の一音が球形の壁に吸い込まれ、反射し、弱まり、反射し、弱まり——完全に消えるまでに、さらに十秒以上かかった。残響が消えていく過程を、体の全面で聴いた。消えきった後、静寂が戻った。"}, {"id": "ch06-s01-p063", "type": "text", "text": "静寂の質が、歌の前と違っていた。"}, {"id": "ch06-s01-p064", "type": "text", "text": "歌の前の静寂は空だった。何もない空間。歌の後の静寂は——満ちていた。音は消えたのに、空気の中に何かが残っている。余韻、と呼ぶには実体がありすぎる。鳴海さんの声が空間に染みを残している。目に見えない染み。"}, {"id": "ch06-s01-p065", "type": "text", "text": "残響波検出装置の針がゆっくりとゼロに戻っていく。戻りきるまでに四十三秒。数字を記録した。手の震えは止まっていた。"}, {"id": "ch06-s01-p066", "type": "text", "text": "鳴海さんが目を開けた。"}, {"id": "ch06-s01-p067", "type": "text", "text": "目を開けた瞬間、表情が切り替わった。響弦館の時と同じ構造。歌っている間の「何もない」表情から、鳴海さんの顔に戻る。微笑みが浮かぶ。穏やかな微笑み——だが、響弦館の時より一段、壁が低かった。八百人の前に見せる微笑みではない。客席に向ける笑顔ではない。ここには俺しかいない。その事実が、微笑みの質を変えていた。"}, {"id": "ch06-s01-p068", "type": "text", "text": "口が少し開いている。歯が見えた。目が細くなっている。灯籠通りの分岐で「また……聴いてくれたら、嬉しいです」と言った時の顔に近い。壁を一段下げた笑顔。"}, {"id": "ch06-s01-p069", "type": "text", "text": "額に汗が浮いていた。髪の生え際に、小さな汗の粒。首筋にも。銀のチョーカーの縁に汗が光っている。歌った後の消耗。響弦館では舞台裏に下がってから拭いていたのだろう。ここでは隠す場所がない。"}, {"id": "ch06-s01-p070", "type": "text", "text": "鳴海さんがスカートのポケットからハンカチを出し、額を拭いた。白い布。端にレースの縁取り。拭く動作が丁寧だった。額、首筋、鎖骨の上。"}, {"id": "ch06-s01-p071", "type": "text", "text": "「……朝霧さんは、鐘の音が好きですか？」"}, {"id": "ch06-s01-p072", "type": "text", "text": "唐突だった。"}, {"id": "ch06-s01-p073", "type": "text", "text": "歌い終わって最初の言葉が、それだった。呼吸がまだ整いきっていなかった。声に僅かな揺れがある。喉が使い切られた後の掠れ。"}, {"id": "ch06-s01-p074", "type": "text", "text": "鳴海さんの目がこちらを見ていた。琥珀色の瞳。歌う前より色が薄い。深い琥珀から、明るい蜂蜜色に近づいている。光の加減ではない。毎回、歌った後はそうなる。響弦館の時も、訓練棟の外で初めて会った時も。歌った後は、瞳の色が薄くなる。"}, {"id": "ch06-s01-p075", "type": "text", "text": "質問の意図がわからなかった。なぜ鐘の音のことを聞くのか。俺が鐘守補佐だから——だとしても、歌い終わった直後に聞く内容ではない。歌と鐘の間に、鳴海さんの中では何かが繋がっている。"}, {"id": "ch06-s01-p076", "type": "choice_header", "text": "---\n**【選択肢】**"}, {"id": "ch06-s01-p077", "type": "choice", "text": "**A: 「好きです」** → 千歳好感度 +1"}, {"id": "ch06-s01-p078", "type": "text", "text": "考えた。三秒。鐘の音を聴いた時、体に起きること。心地よさ。懐かしさ。足が止まること。息を止めること。今の鳴海さんの歌を聴いた時にも、同じことが起きた。胸の温かさと、薄い痛みと。"}, {"id": "ch06-s01-p079", "type": "text", "text": "「好きです」"}, {"id": "ch06-s01-p080", "type": "text", "text": "言った。「思います」は付けなかった。鐘の音への反応は、体が教えてくれている。心地よいと感じる。懐かしいと感じる。それを「好き」と呼んでいいかはわからない。けれど、好きか嫌いかの二択なら、好きの側にある。体がそう言っている。"}, {"id": "ch06-s01-p081", "type": "text", "text": "鳴海さんの目が、少し見開かれた。"}, {"id": "ch06-s01-p082", "type": "text", "text": "唇が開き、閉じ、もう一度開いた。反応を想定していなかったのだと思う。あるいは「わかりません」という答えを想定していた。俺の返答が予測の外にあった。"}, {"id": "ch06-s01-p083", "type": "text", "text": "「……そうですか」"}, {"id": "ch06-s01-p084", "type": "text", "text": "声が柔らかかった。掠れた声の中に、温度があった。嬉しい、という温度。小さく目を伏せ、ハンカチを握っている指先が少しだけ緩んだ。"}, {"id": "ch06-s01-p085", "type": "text", "text": "「ふふ、うれしい」"}, {"id": "ch06-s01-p086", "type": "text", "text": "小さな声だった。独り言に近い音量。俺に聞かせるつもりがなかった声か、聞こえてもいいと思った声か。区別はつかない。"}, {"id": "ch06-s01-p087", "type": "choice", "text": "**B: 「わかりません」** → 好感度変動なし"}, {"id": "ch06-s01-p088", "type": "text", "text": "考えた。三秒。鐘の音を聴いた時、体に起きること。心地よさ。懐かしさ。足が止まること。それを「好き」と呼べるかどうか。"}, {"id": "ch06-s01-p089", "type": "text", "text": "「わかりません」"}, {"id": "ch06-s01-p090", "type": "text", "text": "正直に言った。嫌いではない。心地よいと感じる。けれど「好き」は、もっと確かな言葉だ。確かでないことを確かに言うのは、俺にはできない。"}, {"id": "ch06-s01-p091", "type": "text", "text": "「でも、心地よいと感じます」"}, {"id": "ch06-s01-p092", "type": "text", "text": "付け加えた。嘘ではない。鐘の音を聴くと胸の中が少し変わる。それは事実だった。"}, {"id": "ch06-s01-p093", "type": "text", "text": "鳴海さんが小さく笑った。困った顔ではなかった。口元と目が同時に動いた。壁の低い笑顔。"}, {"id": "ch06-s01-p094", "type": "text", "text": "「ふふ、正直な方ですね」"}, {"id": "ch06-s01-p095", "type": "text", "text": "声に責めの色はなかった。「わかりません」を受け取った上で、その答えの中にあるものを読み取っている。正直であることを、好ましいと思っている声。"}, {"id": "ch06-s01-p096", "type": "divider", "text": "---"}, {"id": "ch06-s01-p097", "type": "text", "text": "鳴海さんがハンカチを畳み、ポケットに戻した。"}, {"id": "ch06-s01-p098", "type": "text", "text": "「わたしは……好きです。鐘の音も、歌うことも」"}, {"id": "ch06-s01-p099", "type": "text", "text": "灯籠通りで聞いた言葉と同じだった。「歌うことが、好きなんです」。あの時と同じ確かさが声にあった。使命ではなく、訓練ではなく、適性でもなく。歌うこと自体が好き。鐘の音が好き。その二つを並べて口にする声は、学院の宝としての声ではなかった。鳴海千歳という一人の人間の声だった。"}, {"id": "ch06-s01-p100", "type": "text", "text": "残響祭の舞台裏で見た鳴海さん。八百席の拍手の中で微笑んだ鳴海さん。どちらにも「学院の宝」の輪郭があった。ここにはそれがない。球形の防音室に、俺と鳴海さんしかいない。見る人がいないと、鳴海さんの微笑みの形が変わる。"}, {"id": "ch06-s01-p101", "type": "text", "text": "——形が変わるのではなく、形を作る必要がなくなっている。"}, {"id": "ch06-s01-p102", "type": "text", "text": "「朝霧さんが見学に来てくださると、少し安心するんです」"}, {"id": "ch06-s01-p103", "type": "text", "text": "鳴海さんが言った。視線が壁面の残響紋を辿りながら。"}, {"id": "ch06-s01-p104", "type": "text", "text": "「一人で歌っていると、声がどこに行くのかわからなくなる時があって。聴いてくれる人がいると……ああ、届いているんだ、って」"}, {"id": "ch06-s01-p105", "type": "text", "text": "声が正直だった。穏やかな微笑みの裏にある、小さな不安の音がそのまま出ていた。共鳴室の完全防音がそうさせるのか。外に漏れない空間だから、声も漏れない。声も——漏れないはずの本音も。"}, {"id": "ch06-s01-p106", "type": "text", "text": "鳴海さんの右手が、首元に上がった。"}, {"id": "ch06-s01-p107", "type": "text", "text": "無意識の動作だった。会話の途中。言葉を探している間。右手の指先が首の右側——チョーカーの少し上の、首筋の肌に触れた。押さえた。二本の指で、軽く。押さえるというより、確かめる動作に近かった。自分の首がそこにあることを確かめるように。"}, {"id": "ch06-s01-p108", "type": "text", "text": "一秒。二秒。指が離れた。鳴海さんはその動作に気づいていなかった。右手がそのまま髪を耳にかける動作に流れた。"}, {"id": "ch06-s01-p109", "type": "text", "text": "記録した。"}, {"id": "ch06-s01-p110", "type": "text", "text": "頭の中に記録した。鳴海さんが歌った後に首元を押さえる。意識的な動作ではない。癖。何の癖かはわからない。歌った後の喉の疲労を確認しているのか。それとも——もっと別の何かか。"}, {"id": "ch06-s01-p111", "type": "text", "text": "わからない。保留する。"}, {"id": "ch06-s01-p112", "type": "text", "text": "「ありがとうございます、今日も。計測結果は後日お渡ししますね」"}, {"id": "ch06-s01-p113", "type": "text", "text": "鳴海さんが丸い扉に向かって歩き出した。足取りはしっかりしていた。響弦館の公演後のような、膝が折れかける揺れはなかった。訓練の一回分と公演の全力とでは負荷が違うのだろう。"}, {"id": "ch06-s01-p114", "type": "text", "text": "けれど、さっきの首元の動作が残っている。"}, {"id": "ch06-s01-p115", "type": "text", "text": "俺の胸の中に残っているのは二つ。温かさと痛み。鳴海さんの歌声が作った温かさは、まだ消えていなかった。球形の壁から残響が消えた後も、体の中の温かさは消えない。そしてその裏側にある痛み。温かければ温かいほど、痛みの輪郭が鮮明になる。"}, {"id": "ch06-s01-p116", "type": "text", "text": "なぜ痛いのかは、わからない。"}, {"id": "ch06-s01-p117", "type": "text", "text": "鳴海さんが扉の手前で振り返った。"}, {"id": "ch06-s01-p118", "type": "text", "text": "「また、聴いてくださいね」"}, {"id": "ch06-s01-p119", "type": "text", "text": "灯籠通りの分岐で聞いた言葉に似ていた。あの時は「また……聴いてくれたら、嬉しいです」。今は「聴いてくださいね」。語尾が違う。頼みではなく、約束を求める形。"}, {"id": "ch06-s01-p120", "type": "text", "text": "「はい」"}, {"id": "ch06-s01-p121", "type": "text", "text": "返事をした。計器の電源を落としながら。残響波検出装置のゼロ点を確認し、記録用紙を取り外し、鉛筆を胸ポケットに戻した。仕事の手順。手は仕事をしている。胸の中は、まだ鳴海さんの声が残っていた。"}, {"id": "ch06-s01-p122", "type": "text", "text": "丸い扉が閉まる音が、球形の空間に反響した。鳴海さんが出ていった後の共鳴室は、歌の前の静寂とは別の静寂で満ちていた。音は消えた。温かさは消えない。痛みも消えない。"}, {"id": "ch06-s01-p123", "type": "text", "text": "鐘の音と同じだった。"}, {"id": "ch06-s01-p124", "type": "text", "text": "鐘の余韻が体に残るのと、鳴海さんの声の余韻が体に残るのは、同じ場所で同じ形をしている。偶然の類似か。それとも——鐘と声に、本当に同じものが含まれているのか。"}, {"id": "ch06-s01-p125", "type": "text", "text": "答えは出ない。保留する。"}, {"id": "ch06-s01-p126", "type": "text", "text": "計測機器の片づけを終え、記録用紙を鞄に入れた。丸い扉を開け、階段を上った。地上に出ると、七月の夕方の空気が肌に触れた。湿っていた。地下の乾いた空気との差で、一瞬だけ眩暈のような揺れがあった。"}, {"id": "ch06-s01-p127", "type": "text", "text": "訓練棟の外に出た。夕焼けが始まりかけている。西の空が橙色に染まり始めていた。"}, {"id": "ch06-s01-p128", "type": "text", "text": "鳴海さんはもういなかった。先に出ていたのだろう。姿が見えない。灯籠通りの方へ歩いたか、寮の方へ向かったか。"}, {"id": "ch06-s01-p129", "type": "text", "text": "胸の中の温かさが、まだある。"}, {"id": "ch06-s01-p130", "type": "text", "text": "四回目。壁越しに聴いた一回目から数えて、四回目の歌声体験。一回目は鳩尾の緩み。二回目も鳩尾。三回目は鳩尾の奥。四回目は胸の中央。回を追うごとに、反応が浅い場所から深い場所へ、鳩尾から胸へ、移動している。"}, {"id": "ch06-s01-p131", "type": "text", "text": "そして四回目だけに、痛みがあった。"}, {"id": "ch06-s01-p132", "type": "text", "text": "距離が最も近かったからか。球形の共鳴室が音の密度を高めたからか。それとも——三回目までの蓄積が、四回目で閾値を越えたのか。"}, {"id": "ch06-s01-p133", "type": "text", "text": "わからない。"}, {"id": "ch06-s01-p134", "type": "text", "text": "わからないことを、覚えておく。鳴海さんの歌声と、胸の温かさと痛みと、「鐘の音が好きですか」という問いと、首元を押さえた二秒と、歌い終わった後の薄くなった琥珀色の瞳と。"}]}, {"chapter": 6, "chapterTitle": "鐘の音の下で", "scene": 2, "sceneTitle": "いろはの視線", "wordCount": "約4,000字", "paragraphs": [{"id": "ch06-s02-p001", "type": "text", "text": "訓練棟の出入口を出ると、夕方の空気が肌に貼りついた。"}, {"id": "ch06-s02-p002", "type": "text", "text": "七月の湿気。共鳴室の地下は乾いていたから、差が目立つ。額に薄く汗が浮いた。鞄の中に記録用紙がある。今日の残響波検出値、通常の三倍以上。その数字と、胸の中央にまだ残っている温かさと痛みが、同じ出来事の別の表出だった。"}, {"id": "ch06-s02-p003", "type": "text", "text": "教室棟に向かって歩いた。訓練棟と教室棟の間は石畳の連絡路で繋がっていて、途中に小さな中庭がある。残響桜は葉桜になっていた。七月の葉は濃い。枝の影が石畳に網目を落としている。"}, {"id": "ch06-s02-p004", "type": "text", "text": "夕焼けが石畳の色を変えていた。灰色の石が淡い橙に染まっている。影の部分だけが元の色を残していて、日向と日陰の境目が線を引いたように分かれている。"}, {"id": "ch06-s02-p005", "type": "text", "text": "胸の温かさが、まだ消えない。"}, {"id": "ch06-s02-p006", "type": "text", "text": "共鳴室から地上に出てきて——たぶん十五分は経っている。鳴海さんの声の余韻は球形の壁から四十三秒で消えた。記録した。けれど体の中の余韻には時間制限がないらしい。胸の中央にある温かさと、その裏側に貼りついた痛みが、歩くたびに揺れる。痛みの方が少しだけ重い。"}, {"id": "ch06-s02-p007", "type": "text", "text": "教室棟の昇降口が見えたところで、足が止まった。"}, {"id": "ch06-s02-p008", "type": "text", "text": "人がいた。"}, {"id": "ch06-s02-p009", "type": "text", "text": "昇降口の横の壁。柱と壁の間に、腕を組んで立っている人影。"}, {"id": "ch06-s02-p010", "type": "text", "text": "栗色のショートヘア。後ろが短く刈り上がっていて、前髪がはねている。学院の制服。リボンは少し緩い。足元はスニーカー。右手首にミサンガ。"}, {"id": "ch06-s02-p011", "type": "text", "text": "風祭さんだった。"}, {"id": "ch06-s02-p012", "type": "text", "text": "俺に気づいている。柱の影から、緑色の目がこちらを向いていた。翡翠に似た色。夕方の光が斜めに差して、瞳の中の色が深くなっている。昼間の光の下よりも、重い緑。"}, {"id": "ch06-s02-p013", "type": "text", "text": "目が合った。"}, {"id": "ch06-s02-p014", "type": "text", "text": "風祭さんの体が壁から離れた。腕組みを解いた。ここまでの動作は、四月に訓練棟のロビーで初めて会った時と同じだった。壁に背を預けて待ち、俺が出てきて、体を起こす。"}, {"id": "ch06-s02-p015", "type": "text", "text": "ただし目の形が違った。あの時は「何者だ」を測る目だった。今は——俺が何者かは知っている。名前も役職も知っている。知った上での、別の種類の硬さ。"}, {"id": "ch06-s02-p016", "type": "text", "text": "「……朝霧さん、ちょっといい？」"}, {"id": "ch06-s02-p017", "type": "text", "text": "声は静かだった。高めの声。輪郭がはっきりしている。けれど、音量が絞られていた。風祭さんの声にはいくつかの段階がある。鳴海さんの前で見せる、鞘に収まった声。天城さんに向ける、角のない声。俺に向ける声は、場面によって材質が変わる。"}, {"id": "ch06-s02-p018", "type": "text", "text": "今の声は——絞った刃、という形ではなかった。もっと平坦な声。用件がある人間の声。"}, {"id": "ch06-s02-p019", "type": "text", "text": "「はい」"}, {"id": "ch06-s02-p020", "type": "text", "text": "立ち止まって答えた。距離は三メートルほど。風祭さんは近づいてこなかった。石畳の上、夕方の橙と影の境界を挟んで、俺が日向に、風祭さんが柱の影にいた。"}, {"id": "ch06-s02-p021", "type": "text", "text": "「最近、ちーちゃんの訓練見学、よく行ってるよね」"}, {"id": "ch06-s02-p022", "type": "text", "text": "よく、ではなかった。四回目だった。正確に四回。壁越しの一回目を入れるかどうかで数が変わるが、共鳴室に入って直接歌声を聴いたのは今日が初めてだった。「よく」と呼ぶには頻度が足りない気がした。"}, {"id": "ch06-s02-p023", "type": "text", "text": "けれど、風祭さんの「よく」には別の尺度がある。鳴海さんの訓練に蓮が関わり始めたこと自体が、風祭さんの許容範囲を超えているのかもしれない。"}, {"id": "ch06-s02-p024", "type": "text", "text": "「計測業務で見学しています」"}, {"id": "ch06-s02-p025", "type": "text", "text": "「うん。仕事だってのはわかるよ」"}, {"id": "ch06-s02-p026", "type": "text", "text": "わかるよ、という言葉の後に間があった。一秒。風祭さんの口が開きかけ、閉じ、もう一度開いた。次の言葉を選んでいた。"}, {"id": "ch06-s02-p027", "type": "text", "text": "「あんまり、ちーちゃんを疲れさせないでほしいの」"}, {"id": "ch06-s02-p028", "type": "text", "text": "声が低くなっていた。平坦だった声に、初めて色が混じった。何色か。怒りではない。苛立ちとも違う。五月に桜の下で「ちーちゃんの邪魔しないでね」と言った時は、鳴海さんの歌を近くで聴いた後で、硬さが少し溶けていた。今はその溶けた分が元に戻っている。"}, {"id": "ch06-s02-p029", "type": "text", "text": "風祭さんの姿勢が硬い。腕組みは解いたままだが、肩が上がっている。百五十七センチの体が、自分を大きく見せようとしているのではなく、内側を閉じている。"}, {"id": "ch06-s02-p030", "type": "text", "text": "「訓練で疲れるのは、仕方ないのでは」"}, {"id": "ch06-s02-p031", "type": "text", "text": "言った。業務上の事実として言った。共鳴者の訓練は負荷がかかる。それは俺の計測値が示している。残響波の出力が上がるほど、終了後の鳴海さんの消耗も大きくなる。見学者がいるかいないかで訓練の負荷が変わるとは、データ上は確認されていない。"}, {"id": "ch06-s02-p032", "type": "text", "text": "「そういうことじゃなくて……」"}, {"id": "ch06-s02-p033", "type": "text", "text": "風祭さんの声が途切れた。"}, {"id": "ch06-s02-p034", "type": "text", "text": "途切れた、のではない。止めた。自分の口を。言葉が喉の手前まで来ていて、風祭さんがそれを押し戻した。目が一瞬だけ揺れた。翡翠色が縦に動いた。視線が俺の顔から外れて、石畳に落ちた。"}, {"id": "ch06-s02-p035", "type": "text", "text": "何を言いかけたのか。"}, {"id": "ch06-s02-p036", "type": "text", "text": "「そういうこと」ではない何か。訓練の物理的な疲労ではない何か。風祭さんは鳴海さんの訓練スケジュールを正確に知っている。残響祭の準備の時も、「練習のスケジュール組まなきゃ」と自分から言った。マネージャー。鳴海さんの予定を把握し、体調を観察し、進行を管理する。"}, {"id": "ch06-s02-p037", "type": "text", "text": "そして——俺の見学回数も知っている。「よく行ってるよね」。四回。数えている。数えているということは、鳴海さんの訓練に誰が立ち合っているかを、毎回確認しているということだ。"}, {"id": "ch06-s02-p038", "type": "text", "text": "風祭さんが顔を上げた。"}, {"id": "ch06-s02-p039", "type": "text", "text": "目が平坦に戻っていた。感情を表面に出す前の状態。鳴海さんの前にいる時の柔らかさでもなく、俺に対する査定の目でもない。何も映していない目。"}, {"id": "ch06-s02-p040", "type": "text", "text": "「忘れて。あたしが心配しすぎなだけ」"}, {"id": "ch06-s02-p041", "type": "text", "text": "声が軽かった。無理に軽くしている。口癖の形。風祭さんのキャラクター設計書に書いてあるわけではないが——「別に。なんでもない」に近い温度。なんでもなくない時の口調。"}, {"id": "ch06-s02-p042", "type": "text", "text": "風祭さんが踵を返しかけた。"}, {"id": "ch06-s02-p043", "type": "text", "text": "胸の中に、二つのものがあった。鳴海さんの歌声が残した温かさと痛み。その二つの上に、今、風祭さんの「そういうことじゃなくて……」が載っている。三つの重さが胸の同じ場所にある。"}, {"id": "ch06-s02-p044", "type": "choice_header", "text": "---\n**【選択肢】**"}, {"id": "ch06-s02-p045", "type": "choice", "text": "**A: 声をかける** → いろはフラグ ON"}, {"id": "ch06-s02-p046", "type": "text", "text": "「風祭さん」"}, {"id": "ch06-s02-p047", "type": "text", "text": "呼び止めた。なぜ呼び止めたのか、理由が言葉になる前に声が出ていた。"}, {"id": "ch06-s02-p048", "type": "text", "text": "風祭さんが足を止めた。振り返らなかった。背中がこちらを向いている。栗色の短い髪の後ろ。首の線。肩がこわばっている。"}, {"id": "ch06-s02-p049", "type": "text", "text": "「鳴海さんのことが、心配なんですね」"}, {"id": "ch06-s02-p050", "type": "text", "text": "言った。読み取れた範囲のことを、そのまま。風祭さんが俺に言いたかったことの中身は正確にはわからない。疲れさせるな。訓練に近づくな。計測だけやっていろ。どれかもしれないし、全部かもしれない。けれど、その全部の根にあるものは一つだった。"}, {"id": "ch06-s02-p051", "type": "text", "text": "風祭さんが振り返った。"}, {"id": "ch06-s02-p052", "type": "text", "text": "目が見開かれていた。一瞬だけ。翡翠色の虹彩が丸く広がった。驚いている——ではなく、見透かされた、という反応に近かった。自分が守っていた壁の中身を、外側から名指しされた人間の目。"}, {"id": "ch06-s02-p053", "type": "text", "text": "けれどその目は、すぐに戻った。見開かれた瞳が元の形に狭まり、風祭さんの表情が固まった。固まった、というのは不正確かもしれない。形を決めた。決めて、出した。"}, {"id": "ch06-s02-p054", "type": "text", "text": "「……当たり前でしょ」"}, {"id": "ch06-s02-p055", "type": "text", "text": "声が低かった。小さかった。けれど芯があった。石畳の上に転がしても割れない硬さ。"}, {"id": "ch06-s02-p056", "type": "text", "text": "「ちーちゃんは、あたしの一番大切な人だから」"}, {"id": "ch06-s02-p057", "type": "text", "text": "一番大切な人。"}, {"id": "ch06-s02-p058", "type": "text", "text": "その言葉を聞いた時、胸の温かさと痛みの上に、もう一つ何かが乗った。風祭さんの声に含まれていた重さ。「一番大切な人」は六文字だが、その六文字の後ろに何年分もの時間が積まれていた。千歳が八歳で母を亡くした時、毎日通った風祭さん。十歳で候補生になった時、隣にいた風祭さん。半歩後ろの距離。肩に触れる手。四歩で駆けつける足。ミサンガ。"}, {"id": "ch06-s02-p059", "type": "text", "text": "風祭さんの目が俺を見ていた。目の中にあるものを、俺は正確に読めなかった。怒りではない。警戒でもない。もっと複雑なものが混じっていた。嫉妬、という言葉が頭をかすめたが、それだけでは足りない。嫉妬の隣に心配があり、心配の下に恐れがあり、恐れの奥に——俺には見えない何かがある。"}, {"id": "ch06-s02-p060", "type": "text", "text": "「じゃあね」"}, {"id": "ch06-s02-p061", "type": "text", "text": "短い言葉を残して、風祭さんが背を向けた。今度は振り返らなかった。スニーカーが石畳を蹴る音が規則的に遠ざかっていく。小柄な体。姿勢は硬いまま。教室棟の角を曲がるまで、一度もこちらを見なかった。"}, {"id": "ch06-s02-p062", "type": "choice", "text": "**B: 声をかけない** → フラグなし"}, {"id": "ch06-s02-p063", "type": "text", "text": "声をかけなかった。"}, {"id": "ch06-s02-p064", "type": "text", "text": "かける言葉が見つからなかった。風祭さんの「そういうことじゃなくて」の先にあるものが読めないまま、読めないものに対して声を出すことは、俺にはできなかった。"}, {"id": "ch06-s02-p065", "type": "text", "text": "風祭さんが歩き出した。背中が遠ざかっていく。栗色の短い髪。スニーカーの白い底。夕方の橙の光が風祭さんの背中を照らし、影が石畳の上を長く伸びていた。"}, {"id": "ch06-s02-p066", "type": "text", "text": "その背中は硬かった。肩が少し上がっている。首が前に出ていない。背筋は伸びている。守る姿勢だと、初めて会った時に思った。半歩後ろの立ち位置。千歳の左側。今は千歳がいない。千歳がいない場所でも、風祭さんの体は守る形をしている。"}, {"id": "ch06-s02-p067", "type": "text", "text": "教室棟の角を曲がる直前、風祭さんの右手が上がった。ミサンガが巻かれた手首。髪を掻き上げる動作の途中で、手が止まった。二秒。手が降りた。そのまま角を曲がって見えなくなった。"}, {"id": "ch06-s02-p068", "type": "divider", "text": "---"}, {"id": "ch06-s02-p069", "type": "text", "text": "風祭さんの姿が消えた後、教室棟の昇降口の前に立っていた。"}, {"id": "ch06-s02-p070", "type": "text", "text": "夕焼けが一段進んでいた。橙が濃くなっている。石畳の影が長くなり、風祭さんが立っていた柱の影が俺の足元まで伸びていた。"}, {"id": "ch06-s02-p071", "type": "text", "text": "胸の中の温かさは薄れていた。共鳴室から持ち出した鳴海さんの歌声の余韻が、風祭さんとの会話で上書きされたのではない。消えたのでもない。温かさと痛みはまだある。ただ、その上に別の層ができていた。風祭さんの声と、目と、背中が、薄い膜のように重なっている。"}, {"id": "ch06-s02-p072", "type": "text", "text": "「あんまり、ちーちゃんを疲れさせないでほしいの」"}, {"id": "ch06-s02-p073", "type": "text", "text": "あの言葉を反芻した。訓練の物理的な疲労ではない、と風祭さんは言いかけて止めた。「そういうことじゃなくて」の先にあったもの。風祭さんが知っていて、俺が知らないこと。"}, {"id": "ch06-s02-p074", "type": "text", "text": "残響祭の響弦館で、風祭さんは鳴海さんが崩れることを予測して袖幕で待っていた。四歩で到達し、腕を取り、八百人に気づかせなかった。あれは一度や二度で身につく動作ではなかった。"}, {"id": "ch06-s02-p075", "type": "text", "text": "風祭さんは、鳴海さんの体に何が起きているかを——少なくとも俺よりは、深い場所で知っている。"}, {"id": "ch06-s02-p076", "type": "text", "text": "「疲れさせないで」の裏側にある意味がわかったわけではない。けれど、輪郭が見えた気がした。"}, {"id": "ch06-s02-p077", "type": "text", "text": "この人もまた、何かを守っている。"}, {"id": "ch06-s02-p078", "type": "text", "text": "鳴海さんの左側、半歩後ろ。あの距離を保ち続けることは、仕事ではない。友情だけでもない。俺がまだ名前をつけられないもので、風祭さんは動いている。その力の大きさだけは——「一番大切な人」という六文字の硬さだけは、測れた。"}, {"id": "ch06-s02-p079", "type": "text", "text": "鞄の中の記録用紙を手で確認した。紙の角が指先に当たる。今日の計測値。残響波の数字。鳴海さんの声の記録。それと一緒に、風祭さんの「そういうことじゃなくて」を頭の中に仕舞った。意味がわからないものを、意味がわからないまま持っておく。保留にする。"}, {"id": "ch06-s02-p080", "type": "text", "text": "風祭さんの緑色の目を思い出した。四月に初めて会った時、「何だろう」と思った。鳴海さんは「きれい」。天城さんは「眩しい」。霜月さんは「冷たい」。篠宮さんは「静か」。すみれは「不思議」。風祭さんには、まだ一語が見つからなかった。"}, {"id": "ch06-s02-p081", "type": "text", "text": "今も見つからない。ただ——「守っている」が一番近い、と思った。"}, {"id": "ch06-s02-p082", "type": "text", "text": "教室棟の昇降口を通り、廊下に入った。蛍光灯が白い。夕方の橙から切り替わる白が、一瞬だけ目に痛かった。"}]}, {"chapter": 6, "chapterTitle": "鐘の音の下で", "scene": 3, "sceneTitle": "せかいのおわり", "wordCount": "約5,000字", "paragraphs": [{"id": "ch06-s03-p001", "type": "text", "text": "夕方の業務は第三系統の配管洗浄だった。"}, {"id": "ch06-s03-p002", "type": "text", "text": "管理室で報告書を書き、食堂で夕食を取り、官舎に戻って着替えた。夜間メンテナンスの手順は三日前に霜月さんから指示されている。「第五層と第八層の残響管フランジ、締付トルク再測定。二十時から」。時計を見た。二十時十二分。メンテナンスは終わった。工具を管理室の棚に戻し、記録用紙に数値と時刻を書いた。二十時十四分。"}, {"id": "ch06-s03-p003", "type": "text", "text": "工具箱のロックを確認した。管理室の消灯スイッチの前で、手が止まった。"}, {"id": "ch06-s03-p004", "type": "text", "text": "螺旋階段が上に続いている。"}, {"id": "ch06-s03-p005", "type": "text", "text": "消灯せずに、階段に足をかけた。"}, {"id": "ch06-s03-p006", "type": "text", "text": "何度目か。着任初日の夜間巡回が最初で、残響祭の日にどら焼きを持っていったのが二回目。その後も何度か来ている。メンテナンス終わりに、螺旋階段をそのまま上る。下に降りて管理室を出るのではなく、上に行く。習慣、と呼ぶには回数が足りないかもしれない。けれど足が覚えている。階段を上る足が、管理室の方ではなく天蓋の間の方に向くことに、抵抗がない。"}, {"id": "ch06-s03-p007", "type": "text", "text": "石段の冷たさ。残響灯の青白い光が紫に近くなっていく。上の階ほど色が変わる。それも、もう知っている。"}, {"id": "ch06-s03-p008", "type": "text", "text": "十階。大鐘の脇を通り過ぎた。鐘の表面に残響灯の光が当たり、刻まれた紋様の溝が細い線になって浮かんでいる。触れなかった。初日から、触れたことがない。"}, {"id": "ch06-s03-p009", "type": "text", "text": "石段が木の床に変わった。靴底の感触が硬質から柔質に切り替わる。"}, {"id": "ch06-s03-p010", "type": "text", "text": "天蓋の間に入った。"}, {"id": "ch06-s03-p011", "type": "text", "text": "星が出ていた。"}, {"id": "ch06-s03-p012", "type": "text", "text": "ガラスの天蓋を通して、夜空が円形に切り取られている。七月の空。湿気のある夜だが、星は見えていた。春よりは少ない。水蒸気が光を散らして、低い位置の星はにじんでいる。けれど天頂に近い星は鮮明だった。白い点が、黒の上に刺さっている。"}, {"id": "ch06-s03-p013", "type": "text", "text": "残響灯はない。壁面の下半分から薄い紫色の光がにじんでいた。天蓋の間にだけある、壁面下部の間接照明。光源が見えない。石壁と木の床の境目あたりから紫の光が滲み出して、部屋の輪郭をぼんやりと描いている。初日は星の光しかなくて暗かった。今は慣れた。暗くはない。薄紫の光と星の光で、充分に見える。"}, {"id": "ch06-s03-p014", "type": "text", "text": "すみれがいた。"}, {"id": "ch06-s03-p015", "type": "text", "text": "部屋の中央。木の床に直接座っている。膝を抱えて、天蓋を見上げている。白いワンピースの裾が床に広がって、紫色の光を吸い込んでいる。淡い紫の長い髪が床に流れていた。裸足の足先が膝の前に出ている。"}, {"id": "ch06-s03-p016", "type": "text", "text": "小さなノートが膝の横に置いてあった。星を数えるためのノート。"}, {"id": "ch06-s03-p017", "type": "text", "text": "すみれが振り返った。振り返る、というより、首が自然にこちらを向いた。俺の足音を聞いていたのか。階段を上る音は石段の段階では響くが、木の床に変わった瞬間に弱まる。それでもわかったのだろう。鐘が教えたのか。すみれの感覚がそうなのか。"}, {"id": "ch06-s03-p018", "type": "text", "text": "口元が先に動いた。唇の端が上がる。目が追いかけて、0.5秒の遅延。あのずれは変わらない。"}, {"id": "ch06-s03-p019", "type": "text", "text": "「れん」"}, {"id": "ch06-s03-p020", "type": "text", "text": "「ああ」"}, {"id": "ch06-s03-p021", "type": "text", "text": "隣に座った。"}, {"id": "ch06-s03-p022", "type": "text", "text": "すみれとの距離が、最初の頃よりも近くなっている。初日は三歩の間隔があった。残響祭の日は二歩。今は一歩分もない。すみれの右肩と俺の左肩の間に、手のひら一つ分くらいの空間がある。すみれは近さを嫌がらない。そもそも距離という概念に対する反応が薄い。近くても遠くても、すみれはすみれのままでいる。距離を計測しているのは俺の方だ。"}, {"id": "ch06-s03-p023", "type": "text", "text": "「きょうも、きた」"}, {"id": "ch06-s03-p024", "type": "text", "text": "「メンテナンスの帰りだ」"}, {"id": "ch06-s03-p025", "type": "text", "text": "「うん」"}, {"id": "ch06-s03-p026", "type": "text", "text": "すみれが天蓋に顔を戻した。俺もつられて見上げた。ガラス越しの星空。鐘鋳塔は島で最も高い建物だから、天蓋の間からは空以外に何も見えない。遮るものがない。星と、夜の色だけ。"}, {"id": "ch06-s03-p027", "type": "text", "text": "「きょう、いちばんのほし、あれ」"}, {"id": "ch06-s03-p028", "type": "text", "text": "すみれの指が天蓋の一角を示した。北寄りの空。白く太い光点が一つ。周囲の星より明るい。"}, {"id": "ch06-s03-p029", "type": "text", "text": "「あれは星じゃないかもしれない。惑星かも」"}, {"id": "ch06-s03-p030", "type": "text", "text": "「わくせい」"}, {"id": "ch06-s03-p031", "type": "text", "text": "「太陽の周りを回っている星。自分では光らない。近いから明るく見える」"}, {"id": "ch06-s03-p032", "type": "text", "text": "「じぶんではひからないのに、あかるい」"}, {"id": "ch06-s03-p033", "type": "text", "text": "すみれがその言葉を口の中で転がしていた。音の形を確かめるように。どら焼きを「どらやき」と繰り返した時と同じ動作。"}, {"id": "ch06-s03-p034", "type": "text", "text": "「すみれ、すき。じぶんではひからないほし」"}, {"id": "ch06-s03-p035", "type": "text", "text": "理由は聞かなかった。すみれが好きだと言ったら、好きなのだろう。"}, {"id": "ch06-s03-p036", "type": "text", "text": "膝の横のノートに手を伸ばし、すみれが開いた。暗い。薄紫の光と星の光だけでは文字は読みにくい。けれどすみれの目は見えているらしい。ページの上を指が滑り、丸い印の横に数字を書き足していた。短い鉛筆。先端が丸くなっている。"}, {"id": "ch06-s03-p037", "type": "text", "text": "「さんじゅうに、さんじゅうさん、さんじゅう……あれ」"}, {"id": "ch06-s03-p038", "type": "text", "text": "指が止まった。"}, {"id": "ch06-s03-p039", "type": "text", "text": "「これ、さっきかぞえた」"}, {"id": "ch06-s03-p040", "type": "text", "text": "「また同じ星を数えたか」"}, {"id": "ch06-s03-p041", "type": "text", "text": "「うん。どれがどれか、わかんなくなる。ほし、にてるから」"}, {"id": "ch06-s03-p042", "type": "text", "text": "困っていない。困らない。初日にもこの光景を見た。同じ星を何度も数え直す。番号が飛ぶ。1に戻る。すみれはそれを失敗とは思っていない。繰り返すことが苦ではないのだろう。繰り返しと前進の区別が、すみれの中では曖昧だ。"}, {"id": "ch06-s03-p043", "type": "text", "text": "ノートを閉じて膝に置き、すみれが天蓋を見上げた。"}, {"id": "ch06-s03-p044", "type": "text", "text": "「ほし、きれい」"}, {"id": "ch06-s03-p045", "type": "text", "text": "静かな声。感想ではなく、確認に近い。空にあるものを見て、それが何であるかを言葉にした。甘い→おいしい、と同じ回路。きれい→きれい。フィルタがない。"}, {"id": "ch06-s03-p046", "type": "text", "text": "「ああ、きれいだ」"}, {"id": "ch06-s03-p047", "type": "text", "text": "俺の「きれい」には一段の手続きがある。星を見て、明るさと色を知覚して、それを「きれい」に変換する判定が挟まる。けれどその手続きが以前より速くなっている気がした。星を見て、きれいだと思った。たぶん、それでいい。"}, {"id": "ch06-s03-p048", "type": "text", "text": "しばらく黙って星を見ていた。天蓋の間では沈黙が自然だった。喫茶「残響」の沈黙は二人の間に通路がない状態で、天城さんとの沈黙は通路があるが今は通さない状態で、すみれとの沈黙は——通路も壁もない。何もない空間を共有している。"}, {"id": "ch06-s03-p049", "type": "text", "text": "すみれの呼吸の音が、微かに聞こえた。遅い。呼吸の間隔が、人間の安静時のそれよりも長い。以前から気づいていた。すみれの生理的な反応は、どれも少し遅い。瞬きの間隔。呼吸の間隔。食べ物を噛む速度。ゆっくりとした時間の中に、すみれは存在している。"}, {"id": "ch06-s03-p050", "type": "text", "text": "「れん」"}, {"id": "ch06-s03-p051", "type": "text", "text": "「うん」"}, {"id": "ch06-s03-p052", "type": "text", "text": "「このせかいは、いつかおわるよ」"}, {"id": "ch06-s03-p053", "type": "text", "text": "唐突だった。"}, {"id": "ch06-s03-p054", "type": "text", "text": "星を見上げたまま、すみれが言った。声の温度は変わっていなかった。「ほし、きれい」と同じ高さ、同じ細さ、同じ力の抜け方で、すみれは世界の終わりを口にした。"}, {"id": "ch06-s03-p055", "type": "text", "text": "脈絡がなかった。直前の話題は星の美しさだった。そこから世界の終わりへ、すみれの中でどういう接続が起きたのか、俺にはわからなかった。"}, {"id": "ch06-s03-p056", "type": "text", "text": "「……急だな」"}, {"id": "ch06-s03-p057", "type": "text", "text": "「きゅう？」"}, {"id": "ch06-s03-p058", "type": "text", "text": "すみれが首を傾げた。傾げたまま戻らない。俺の言葉の意味を測っている。急だという感覚が、すみれの中にない。星がきれいなことと、世界がいつか終わることは、すみれにとって同じ棚に並んでいる。"}, {"id": "ch06-s03-p059", "type": "text", "text": "「そうかもしれないな。でも今は、まだ終わってない」"}, {"id": "ch06-s03-p060", "type": "text", "text": "受け流した。すみれの言葉を深刻に受け止めなかった。世界がいつか終わる。それは哲学の教科書の一節か、詩の一行のようなものだ。すみれの口から出ると不思議に響くが、内容そのものは大きすぎて、実感に届かない。蝕域が世界を食んでいることは知っている。縁蝕が進行している。けれど「世界が終わる」とまでは、まだ誰も言っていない。"}, {"id": "ch06-s03-p061", "type": "text", "text": "すみれは違った。"}, {"id": "ch06-s03-p062", "type": "text", "text": "すみれはそれを、空に星があることと同じように述べた。事実。確認。報告。すみれの言葉はいつもそうだ。初日の「かねがおしえてくれた」も、「ここにいるのがしぜん」も、今の「せかいはおわる」も、同じ材質で出来ている。感情ではなく、記述。"}, {"id": "ch06-s03-p063", "type": "text", "text": "俺がそれをわかっていないだけかもしれない。あるいは、わかる必要がまだないのかもしれない。"}, {"id": "ch06-s03-p064", "type": "text", "text": "すみれの視線が星空から俺に移った。薄紫の瞳が、星の光を映している。白い小さな点が瞳の中に散っている。"}, {"id": "ch06-s03-p065", "type": "text", "text": "「れんは、おわりがこわくない？」"}, {"id": "ch06-s03-p066", "type": "text", "text": "目が合った。"}, {"id": "ch06-s03-p067", "type": "text", "text": "すみれの瞳は静かだった。質問しているのであって、試しているのではない。答えを聞きたいだけの目。俺がどう答えても、すみれの態度は変わらないだろう。"}, {"id": "ch06-s03-p068", "type": "text", "text": "「……わからない」"}, {"id": "ch06-s03-p069", "type": "text", "text": "正直に言った。嘘をつける相手ではない。すみれの言葉にフィルタがないのと同じように、すみれの前では俺の言葉からもフィルタが外れる。"}, {"id": "ch06-s03-p070", "type": "text", "text": "「怖いと感じるほど、まだ世界のことを知らないから」"}, {"id": "ch06-s03-p071", "type": "text", "text": "監視哨にいた頃、死の近くにはいた。蝕域の最前線で、同僚が戻らなかったことがあった。恐怖はあった。けれどあれは「終わり」への恐怖ではなく、「自分の体が損なわれること」への反射的な忌避だった。世界が終わるかもしれない。それを怖いと思うには、世界の中に失いたくないものがなければならない。二年前の俺には——いや、今の俺にも、それがどの程度あるのか、正確にはわからない。"}, {"id": "ch06-s03-p072", "type": "text", "text": "ただ、鳩尾の下が少しだけ重くなった。星空と、紫の光と、裸足の少女がいるこの場所が消えることを想像した時に、何かが体の底で動いた。名前がつかない。恐怖とも違う。ただ、重い。"}, {"id": "ch06-s03-p073", "type": "text", "text": "「れんは、しょうじきだね」"}, {"id": "ch06-s03-p074", "type": "text", "text": "すみれが小さく笑った。口と目が同時に動いた。0.5秒のずれがなかった。残響祭の日にどら焼きを食べて「おいしい」と言った時と同じ、ずれのない笑顔。すみれの笑顔が揃うのは稀だ。稀だから記録する。"}, {"id": "ch06-s03-p075", "type": "text", "text": "「すみれ、しょうじきなひと、すき」"}, {"id": "ch06-s03-p076", "type": "text", "text": "好きだと言う。嫌いだと言う。すみれの言語にはその二つが並列に存在していて、どちらにも遠慮がない。"}, {"id": "ch06-s03-p077", "type": "text", "text": "沈黙が戻った。"}, {"id": "ch06-s03-p078", "type": "text", "text": "天蓋のガラス越しに、星がゆっくりと位置を変えている。肉眼ではわからない速度。けれど時間が経てば星座の角度が傾く。鐘鋳塔の真上に見えていた星が、わずかに西へ寄っている。どのくらいの時間が経ったのか。時計を見なかった。天蓋の間では時計を見ない。ここの時間は、外の時間と流れ方が違う。すみれの時間に合わせると、時計の数字は意味を失う。"}, {"id": "ch06-s03-p079", "type": "text", "text": "すみれの右手が動いた。"}, {"id": "ch06-s03-p080", "type": "text", "text": "床の上に置いてあった俺の左手に、すみれの指が触れた。"}, {"id": "ch06-s03-p081", "type": "text", "text": "冷たかった。"}, {"id": "ch06-s03-p082", "type": "text", "text": "すみれの指先が、左手の甲に乗った。五本の指が、俺の手を包むように閉じていった。すみれの手は小さい。俺の手の半分くらいの面積しかない。包むというよりは、載せている。指先と手のひらの一部が俺の手の甲に接触している。"}, {"id": "ch06-s03-p083", "type": "text", "text": "冷たさが、指を通して伝わってきた。七月の夜だった。天蓋の間は窓が少なく、ガラスの天蓋は密閉されている。通気はあるが、風はない。外気温は下がっている時間帯だとしても、室温が極端に低いわけではない。"}, {"id": "ch06-s03-p084", "type": "text", "text": "なのにすみれの手は冷たかった。"}, {"id": "ch06-s03-p085", "type": "text", "text": "人間の指先が冷える理由はいくつかある。血行不良。低体温。末端冷え性。けれどすみれの冷たさは、それらとは質が違う気がした。根拠はない。手の温度だけでは体質の判別はできない。ただ、冷たさの中に生体の温かさが混じっていない。冷えた手が温まろうとしている感触がない。最初から冷たい。冷たいことがすみれの手の定常状態であるかのような——。"}, {"id": "ch06-s03-p086", "type": "text", "text": "「れんのて、あったかい」"}, {"id": "ch06-s03-p087", "type": "text", "text": "すみれの声が小さくなっていた。糸の先端のような声。初日にブレスレットを見つめた時の声に似ている。"}, {"id": "ch06-s03-p088", "type": "text", "text": "「すみれ、つめたい？」"}, {"id": "ch06-s03-p089", "type": "text", "text": "「うん。すみれのて、いつもつめたいの。でもれんのて、あったかいから、きもちいい」"}, {"id": "ch06-s03-p090", "type": "text", "text": "気持ちいい。すみれが俺の手の温度を受け取っている。体温の移動。俺の三十六度台から、すみれの——何度かわからない冷たさへ。"}, {"id": "ch06-s03-p091", "type": "text", "text": "すみれの手を見た。白い指。細い。爪が薄い。手の甲に血管が透けている。青い線。初日に裸足の足で見た、あの透け方と同じだ。"}, {"id": "ch06-s03-p092", "type": "text", "text": "指先から少しずつ温度が移っていく。すみれの冷たさが俺の手の甲を冷やし、俺の温度がすみれの指に伝わっていく。境界線で温度が混ざる。その混ざり方が不思議だった。普通なら、冷たい手と温かい手が触れれば、どちらも中間の温度に近づいていく。すみれの手は中間に来ない。冷たさが減らない。俺の温度を受け取っても、すみれの手はまだ冷たかった。"}, {"id": "ch06-s03-p093", "type": "text", "text": "「……冷えてるな。大丈夫か」"}, {"id": "ch06-s03-p094", "type": "text", "text": "「だいじょうぶ。すみれ、いつもこう」"}, {"id": "ch06-s03-p095", "type": "text", "text": "いつもこう。すみれはそれを異常だとは思っていない。冷たい手が自分の定常であると受け入れている。出られない塔を自然と呼ぶのと同じ構造。すみれの中では、自分の体の状態に疑問を持つ回路がない。"}, {"id": "ch06-s03-p096", "type": "text", "text": "けれど俺の中には疑問が生まれていた。"}, {"id": "ch06-s03-p097", "type": "text", "text": "すみれの手は、なぜこんなに冷たいのか。七月の夜に、室温がそこまで低くない場所で、ずっとここに座っていて、手がこの温度であること。足音がしないこと。呼吸が遅いこと。時間の感覚がずれていること。微笑む時に目と口が0.5秒ずれること。鐘の声が聞こえること。塔から出ないこと。"}, {"id": "ch06-s03-p098", "type": "text", "text": "一つ一つは不思議で済む。まとめて並べると、何かの輪郭が見える。見えるが、名前がつかない。俺が知っている分類のどこにも、すみれは収まらない。"}, {"id": "ch06-s03-p099", "type": "text", "text": "すみれの指が俺の手の上で動いた。人差し指の先端が、手の甲の皮膚を小さくなぞった。文字を書いているような動きではない。ただ触れている。温度を確かめている。"}, {"id": "ch06-s03-p100", "type": "text", "text": "「れん」"}, {"id": "ch06-s03-p101", "type": "text", "text": "「うん」"}, {"id": "ch06-s03-p102", "type": "text", "text": "「おわりがきたら、すみれのて、もっとつめたくなるかな」"}, {"id": "ch06-s03-p103", "type": "text", "text": "声は静かだった。さっきの「せかいはおわる」と同じ温度だった。怖がっていない。悲しんでいない。ただ、自分の手の冷たさと世界の終わりを、同じ文脈に置いている。"}, {"id": "ch06-s03-p104", "type": "text", "text": "「そうならないように、鐘が鳴ってるんじゃないのか」"}, {"id": "ch06-s03-p105", "type": "text", "text": "言った。残響の鐘。蝕域の進行を抑制する島の中核装置。鐘が鳴り続ける限り、島は残響を維持する。終わりは来ない。たぶん。"}, {"id": "ch06-s03-p106", "type": "text", "text": "すみれが小さく頷いた。頷きの動きが遅い。首が傾いて、戻るまでの間隔が長い。"}, {"id": "ch06-s03-p107", "type": "text", "text": "「うん。……かねが、なってるあいだは、だいじょうぶ」"}, {"id": "ch06-s03-p108", "type": "text", "text": "声が薄くなった。糸の先端より、もっと細い。聞き取れたことが不思議なくらいの音量だった。天蓋のガラスに吸い込まれて消えそうな声。"}, {"id": "ch06-s03-p109", "type": "text", "text": "すみれが俺の手を離した。"}, {"id": "ch06-s03-p110", "type": "text", "text": "離す直前、すみれの指が一瞬だけ強くなった。握るというほどではない。指の力が少し増えただけ。五本の指が俺の手の甲を押して、すぐに離れた。"}, {"id": "ch06-s03-p111", "type": "text", "text": "左手の甲に、冷たさの跡が残っている。すみれの指があった場所だけ、温度が低い。夜の空気がその跡を撫でていく。"}, {"id": "ch06-s03-p112", "type": "text", "text": "すみれが天蓋を見上げた。"}, {"id": "ch06-s03-p113", "type": "text", "text": "「さんじゅうよん。さんじゅうご。さんじゅうろく……」"}, {"id": "ch06-s03-p114", "type": "text", "text": "星を数え始めた。鉛筆の先がノートの上を走る。丸を描いて、横に数字を書く。小さな声で数を唱える。"}, {"id": "ch06-s03-p115", "type": "text", "text": "世界の終わりの話は、もう終わっている。すみれの中では、星の数と世界の終わりは同じ棚に並んでいて、一つを出して見せたら次の棚に移る。それだけのこと。"}, {"id": "ch06-s03-p116", "type": "text", "text": "俺は左手の甲を見た。すみれの冷たさは少しずつ薄れ、自分の体温が戻ってきている。温度が戻ると、さっきの冷たさが本当にあったのか、記憶が曖昧になる。体感は記録に残しにくい。数値化できない。"}, {"id": "ch06-s03-p117", "type": "text", "text": "立ち上がった。"}, {"id": "ch06-s03-p118", "type": "text", "text": "「帰る。また来る」"}, {"id": "ch06-s03-p119", "type": "text", "text": "「うん」"}, {"id": "ch06-s03-p120", "type": "text", "text": "すみれの声が返ってきた。振り返らなかった。ノートの上に視線を落として、星を数えている。三十七、三十八。鉛筆の音が木の床に微かに響いている。"}, {"id": "ch06-s03-p121", "type": "text", "text": "螺旋階段を降り始めた。石段の冷たさが靴底に戻る。木の床から石の階段に移る時の感触の切り替わり。天蓋の間を出るたびに、異なる時間の層を通過していく感覚がある。すみれの時間から、鐘鋳塔の時間へ、そして島の時間へ。"}, {"id": "ch06-s03-p122", "type": "text", "text": "十階の大鐘の脇を通った。"}, {"id": "ch06-s03-p123", "type": "text", "text": "鐘の表面に手を伸ばしかけて、止めた。初日と同じ。触れない。触れていいのかわからない。"}, {"id": "ch06-s03-p124", "type": "text", "text": "けれど今日は、鐘の表面を見つめる時間がいつもより長かった。"}, {"id": "ch06-s03-p125", "type": "text", "text": "鐘が鳴っている間は、大丈夫。"}, {"id": "ch06-s03-p126", "type": "text", "text": "すみれの声が頭の中で繰り返された。大丈夫の裏側にあるもの。鐘が鳴らなくなったら。すみれはそれを言わなかった。言う必要がなかったのか、言いたくなかったのか。"}, {"id": "ch06-s03-p127", "type": "text", "text": "わからない。わからないが、体の奥に引っ掛かりが残っている。鳩尾の下の、さっき重さを感じた場所。世界が終わることを想像した時に動いたもの。それがまだ消えていない。"}, {"id": "ch06-s03-p128", "type": "text", "text": "すみれの手の冷たさ。世界の終わり。鐘の音。"}, {"id": "ch06-s03-p129", "type": "text", "text": "三つの言葉を、意味がわからないまま、頭の中に仕舞った。保留。いつか意味がわかる日が来るかもしれないし、来ないかもしれない。"}, {"id": "ch06-s03-p130", "type": "text", "text": "管理室に降りた。消灯。施錠。正面入口を出た。"}, {"id": "ch06-s03-p131", "type": "text", "text": "夜風が頬に当たった。七月の夜風。湿気がある。温かい。天蓋の間のすみれの手とは正反対の温度。"}, {"id": "ch06-s03-p132", "type": "text", "text": "左手の甲を右手で包んだ。"}, {"id": "ch06-s03-p133", "type": "text", "text": "もう冷たさは消えていた。すみれの指の跡は、体温に上書きされていた。"}, {"id": "ch06-s03-p134", "type": "text", "text": "それが少しだけ惜しいと思った。惜しい、と感じたことを記録する。理由はわからない。わからないけれど、惜しいという感覚が体の中にあったことは、事実だった。"}]}, {"chapter": 6, "chapterTitle": "鐘の音の下で", "scene": 4, "sceneTitle": "夏期研修の知らせ", "wordCount": "約4,000字", "paragraphs": [{"id": "ch06-s04-p001", "type": "text", "text": "窓から入る光が白かった。"}, {"id": "ch06-s04-p002", "type": "text", "text": "七月の正午。食堂のアーチ窓を通して、夏の日差しがテーブルの上を切り取っている。四月に初めてここに来た時は、光が斜めに入って飴色の天板に筋を作っていた。七月の光は角度が高い。窓に近い席だけが白く照らされて、奥のテーブルには届かない。天井の梁に吊り下げられた残響灯は消えていた。昼は日差しだけで充分に明るい。"}, {"id": "ch06-s04-p003", "type": "text", "text": "煉瓦の壁に声が跳ね返っている。食堂は今日も混んでいた。配膳台の前に列ができ、トレイを持った生徒が席を探して歩いている。天井が高いから、声が上に抜けて丸くなる。個々の会話は聞き取れない。全体でひとつの音の層になっている。"}, {"id": "ch06-s04-p004", "type": "text", "text": "いつもの席に着いた。食堂の奥、窓際の長テーブル。着任初日に端の席に座って、天城さんが向かいに来た場所。今は端ではなく中ほどに座っている。いつの間にか移動した。五人で座る時に端だと全員の顔が見えないからだ。理由は実用的なものだった。"}, {"id": "ch06-s04-p005", "type": "text", "text": "トレイの上。白米、冷やし中華、冷奴、漬物。夏のメニューに変わっている。冷やし中華の麺に酢の匂いがする。胡瓜の千切りとハムと錦糸卵が乗っている。からしが小皿に添えてある。"}, {"id": "ch06-s04-p006", "type": "text", "text": "箸を手に取った。"}, {"id": "ch06-s04-p007", "type": "text", "text": "麺を一口。酸味が鼻に抜ける。冷たい。麺の温度と酢の酸味が舌を同時に刺激して、一瞬だけ食堂の暑さを忘れた。――おいしい。たぶん、ではなく、おいしい。四月に天城さんの前で「おいしいと思います」と言った時の紙一枚の隙間が、今はほとんどない。食事の味を味として受け取れている。"}, {"id": "ch06-s04-p008", "type": "text", "text": "「蓮くん、もう食べてるー！」"}, {"id": "ch06-s04-p009", "type": "text", "text": "天城さんの声が横から来た。声量が大きい。周囲のテーブルの生徒が二、三人こちらを見て、すぐに戻った。天城さんの声が食堂で響くことには、もうみんな慣れている。"}, {"id": "ch06-s04-p010", "type": "text", "text": "天城さんがトレイを俺の向かいに置いた。冷やし中華に加えて、おにぎりが二つとコロッケが一つ。相変わらず量が多い。ポニーテールが揺れて、黄色のゴムに窓からの光が当たった。"}, {"id": "ch06-s04-p011", "type": "text", "text": "「先に来てた。待ってたわけじゃない」"}, {"id": "ch06-s04-p012", "type": "text", "text": "「えー、待っててくれてもいいのに」"}, {"id": "ch06-s04-p013", "type": "text", "text": "天城さんが笑いながら座った。箸を割る音。すぐにコロッケをかじる。衣のさくさくという音が聞こえた。"}, {"id": "ch06-s04-p014", "type": "text", "text": "「おいしー。蓮くんもコロッケ取ればよかったのに。今日のコロッケ当たりだよ」"}, {"id": "ch06-s04-p015", "type": "text", "text": "「次にする」"}, {"id": "ch06-s04-p016", "type": "text", "text": "「ぜったいね」"}, {"id": "ch06-s04-p017", "type": "text", "text": "天城さんの後ろから、二人分の足音が来た。"}, {"id": "ch06-s04-p018", "type": "text", "text": "鳴海さんと風祭さんだった。並んで歩いている。いつもの配置。鳴海さんが右、風祭さんが左。半歩後ろ。"}, {"id": "ch06-s04-p019", "type": "text", "text": "「お待たせしました」"}, {"id": "ch06-s04-p020", "type": "text", "text": "鳴海さんの声は食堂の喧騒の中でも通る。柔らかいが、芯がある。周波数が喧騒の隙間を縫っているような、そういう声質。トレイを持つ手が白い。共鳴訓練用のチョーカーは外してある。首元が素のままだった。"}, {"id": "ch06-s04-p021", "type": "text", "text": "「ちーちゃん、こっちこっち」"}, {"id": "ch06-s04-p022", "type": "text", "text": "風祭さんが鳴海さんの隣の席を確保した。自分のトレイを置いてから、鳴海さんの椅子を引いている。鳴海さんが「ありがとう」と小さく笑った。風祭さんの目が一瞬だけ緩んだ。ミサンガの巻かれた手首が見えて、すぐにテーブルの下に入った。"}, {"id": "ch06-s04-p023", "type": "text", "text": "天城さんの向かいに鳴海さん。その隣に風祭さん。俺の斜向かい。"}, {"id": "ch06-s04-p024", "type": "text", "text": "風祭さんの視線が一瞬だけ俺に触れた。すぐに外れた。目の色は翡翠。昨日の夕方、教室棟の前で会った時の硬さは薄れていた。薄れていたが、消えてはいない。風祭さんの俺に対する態度は、場面ごとに層が重なっている。今の層は「全員でいる時の距離」だった。一対一の時とは違う。他のメンバーがいる空間では、風祭さんの輪郭は柔らかくなる。特に鳴海さんの隣にいる時は。"}, {"id": "ch06-s04-p025", "type": "text", "text": "「あ、篠宮さんも来た」"}, {"id": "ch06-s04-p026", "type": "text", "text": "天城さんが手を振った。"}, {"id": "ch06-s04-p027", "type": "text", "text": "篠宮さんがトレイを持って近づいてきた。足音がほとんどない。いつもそうだ。天城さんの声に導かれるようにして、テーブルの端に座った。俺の隣。長テーブルの一番奥の位置。壁に背中が近い。"}, {"id": "ch06-s04-p028", "type": "text", "text": "「こんにちは」"}, {"id": "ch06-s04-p029", "type": "text", "text": "篠宮さんの声は小さい。食堂の喧騒の中では聞き取りにくい。けれど俺の隣だから届いた。トレイの上は冷やし中華と冷奴だけ。量が少ない。銀縁の眼鏡のレンズに天井の光が反射して、一瞬だけ目が見えなくなった。"}, {"id": "ch06-s04-p030", "type": "text", "text": "五人。テーブルを囲んでいる。"}, {"id": "ch06-s04-p031", "type": "text", "text": "天城さんが正面。鳴海さんがその隣。風祭さんが鳴海さんの隣。篠宮さんが俺の隣。配置は毎回ほぼ同じだった。誰かが決めたのではなく、何度か食事をするうちに自然に固まった。天城さんを中心にして声が放射状に広がり、鳴海さんが受け止め、風祭さんが鳴海さんの隣を守り、篠宮さんが端で全体を見ている。俺は――たぶん、篠宮さんと似た位置にいる。ただし篠宮さんが記録者なら、俺は観察者だった。記録は残す。観察は残さない。"}, {"id": "ch06-s04-p032", "type": "text", "text": "「ねーねー、みんなもう聞いた？ 夏期研修の話」"}, {"id": "ch06-s04-p033", "type": "text", "text": "天城さんがコロッケの二口目を飲み込みながら言った。話題を食卓に投げ込む。天城さんの役割。"}, {"id": "ch06-s04-p034", "type": "text", "text": "「掲示板に出てましたね。八月の第二週からでしたか」"}, {"id": "ch06-s04-p035", "type": "text", "text": "鳴海さんが答えた。冷やし中華の麺を箸で丁寧に取り分けている。食べ方が几帳面だった。麺が一定の量ずつ箸に乗る。"}, {"id": "ch06-s04-p036", "type": "text", "text": "「蝕域研修ってやつ。二年生以上の鐘守候補生が外円区の監視哨で実地研修するんだって」"}, {"id": "ch06-s04-p037", "type": "text", "text": "天城さんが補足した。天城さんは候補生ではないが、情報の伝達が速い。掲示板を見たのか、誰かに聞いたのか。"}, {"id": "ch06-s04-p038", "type": "text", "text": "「蓮くんも行くんでしょ？」"}, {"id": "ch06-s04-p039", "type": "text", "text": "「引率補佐として参加する。霜月さんから昨日指示があった」"}, {"id": "ch06-s04-p040", "type": "text", "text": "「やっぱり。蓮くん、元々監視哨にいたんだもんね。適任じゃん」"}, {"id": "ch06-s04-p041", "type": "text", "text": "天城さんがそう言った時、鳴海さんの箸が一拍止まった。鳴海さんは蓮が監視哨にいたことを知っている。けれどその話題に触れる時、わずかに動きが遅くなる。質問はしない。待っている。俺が何を言うかを。"}, {"id": "ch06-s04-p042", "type": "text", "text": "「現地のことは覚えている。配管の配置や計器の型番は頭に入っている」"}, {"id": "ch06-s04-p043", "type": "text", "text": "「頼りになるー」"}, {"id": "ch06-s04-p044", "type": "text", "text": "「わたしたちは、訓練が続きます」"}, {"id": "ch06-s04-p045", "type": "text", "text": "鳴海さんが言った。声が穏やかだった。研修に参加しないことへの不満ではない。事実を述べている。共鳴者候補生の訓練は夏休み期間中も継続される。共鳴室での発声訓練と残響波の制御。鳴海さんの声は島の防衛に関わる。休みがない。"}, {"id": "ch06-s04-p046", "type": "text", "text": "「あたしもだよー。訓練漬け」"}, {"id": "ch06-s04-p047", "type": "text", "text": "風祭さんが言った。口調は軽い。けれど鳴海さんの「わたしたちは」に自分を含めた時の声には、いつもの半歩後ろの距離があった。鳴海さんと同じ場所にいること。それが風祭さんにとっての定位置だった。"}, {"id": "ch06-s04-p048", "type": "text", "text": "「研修期間中に緊急出動があったらどうするんですか」"}, {"id": "ch06-s04-p049", "type": "text", "text": "篠宮さんが言った。声が小さい。けれど内容は核心をついていた。食堂の喧騒に紛れそうな音量で、問いだけが鋭い。"}, {"id": "ch06-s04-p050", "type": "text", "text": "「島内の待機班が対応する。研修参加者は外円区の監視業務に専念する形だ」"}, {"id": "ch06-s04-p051", "type": "text", "text": "「そうですか」"}, {"id": "ch06-s04-p052", "type": "text", "text": "篠宮さんはそれだけ言って、冷やし中華の麺をひとつまみ口に運んだ。短い応答。篠宮さんの会話は常にこの密度だった。聞きたいことを聞き、答えを得たら、次の行動に移る。"}, {"id": "ch06-s04-p053", "type": "text", "text": "「あたしも何か手伝えることないかな」"}, {"id": "ch06-s04-p054", "type": "text", "text": "天城さんが言った。声のトーンが半段下がっていた。さっきまでのコロッケの報告とは違う声。"}, {"id": "ch06-s04-p055", "type": "text", "text": "俺は箸を止めた。天城さんは一般生徒だ。鐘守候補生でも共鳴者候補生でもない。研修への参加資格はない。"}, {"id": "ch06-s04-p056", "type": "text", "text": "「天城さんは一般生徒だから、研修には——」"}, {"id": "ch06-s04-p057", "type": "text", "text": "「うん、それはわかってる。でもあたし、外円区の出身でしょ。東漁港の辺りなら土地勘あるし。何かしら役に立てるかなって」"}, {"id": "ch06-s04-p058", "type": "text", "text": "天城さんの目がまっすぐだった。はしばみ色。遠慮がない目。けれど今の目には、四月に初めて食堂で会った時のような無防備な好奇心だけではないものが混じっていた。自分の出自を活かしたい。その意志が、目の色を一段深くしている。"}, {"id": "ch06-s04-p059", "type": "text", "text": "「上に確認してみる」"}, {"id": "ch06-s04-p060", "type": "text", "text": "言った。確約はできない。けれど天城さんの申し出を受け取ったことは伝えた。天城さんが外円区出身であることは、地形の把握や現地住民との連携で利点になり得る。霜月さんに報告する材料にはなる。"}, {"id": "ch06-s04-p061", "type": "text", "text": "「ありがと、蓮くん！」"}, {"id": "ch06-s04-p062", "type": "text", "text": "天城さんの声が元の音量に戻った。コロッケの最後のひとかけらを口に入れながら笑った。"}, {"id": "ch06-s04-p063", "type": "text", "text": "「外円区の記録を整理しておきます」"}, {"id": "ch06-s04-p064", "type": "text", "text": "篠宮さんが言った。視線はトレイの上だった。冷奴に醤油をかけている。その動作のまま、声だけがこちらに届いた。"}, {"id": "ch06-s04-p065", "type": "text", "text": "「記録？」"}, {"id": "ch06-s04-p066", "type": "text", "text": "「過去の蝕域観測データと、監視哨の設置経緯をまとめたものがあります。記録室の第七書架。研修前に参照できるようにしておきます」"}, {"id": "ch06-s04-p067", "type": "text", "text": "篠宮さんはそれだけ言うと、冷奴を一口食べた。表情は変わらない。淡々としている。けれど篠宮さんが「しておきます」と言う時、それは必ず実行される。記録室で過ごした時間が教えてくれたことの一つだった。"}, {"id": "ch06-s04-p068", "type": "text", "text": "「助かる。ありがとう、篠宮さん」"}, {"id": "ch06-s04-p069", "type": "text", "text": "「いいえ」"}, {"id": "ch06-s04-p070", "type": "text", "text": "短い。短いが、俺の礼を受け取った声だった。"}, {"id": "ch06-s04-p071", "type": "text", "text": "鳴海さんが冷やし中華を食べ終え、箸を揃えてトレイに置いた。所作が丁寧だった。最後まで麺が散らかっていなかった。"}, {"id": "ch06-s04-p072", "type": "text", "text": "「朝霧さん、外円区の気候は島の内側とだいぶ違うと聞きました。体調には気をつけてくださいね」"}, {"id": "ch06-s04-p073", "type": "text", "text": "「ああ。外円区は風が強い。海が近いから塩気もある」"}, {"id": "ch06-s04-p074", "type": "text", "text": "「塩気！」天城さんが反応した。「そうそう、洗濯物がすぐぱりぱりになるの。干した瞬間からもう塩味って感じ」"}, {"id": "ch06-s04-p075", "type": "text", "text": "天城さんの外円区の記憶が声に乗っていた。洗濯物。日常の手触り。候補生制度や蝕域研修とは別の層にある、天城さんの外円区。そこには海と塩と洗濯物と、たぶん漁港の匂いがある。"}, {"id": "ch06-s04-p076", "type": "text", "text": "「ねえ蓮くん、海行ったことある？」"}, {"id": "ch06-s04-p077", "type": "text", "text": "「……ない、と思う。記憶にはない」"}, {"id": "ch06-s04-p078", "type": "text", "text": "「えー、もったいない！ 東漁港の近くにいいビーチがあるんだよ。岩場の向こうの入り江になってて、波が穏やかなの。研修の合間に行こうよ！」"}, {"id": "ch06-s04-p079", "type": "text", "text": "天城さんのポニーテールが大きく揺れた。テーブルの上に身を乗り出している。はしばみ色の目が光っていた。夏の話をする時の天城さんは声が半音上がる。"}, {"id": "ch06-s04-p080", "type": "text", "text": "「研修は業務だ」"}, {"id": "ch06-s04-p081", "type": "text", "text": "「わかってるって。でも、合間の時間くらいあるでしょ。霜月さんだって鬼じゃないでしょ？」"}, {"id": "ch06-s04-p082", "type": "text", "text": "「鬼かどうかは判断を保留する」"}, {"id": "ch06-s04-p083", "type": "text", "text": "「あはは！ 蓮くん、それ面白い」"}, {"id": "ch06-s04-p084", "type": "text", "text": "天城さんが笑った。顔の全部が動く笑い方。四月の食堂と同じだった。食べて、笑って、声が大きくて、隣にいる人間を巻き込んでいく。"}, {"id": "ch06-s04-p085", "type": "text", "text": "鳴海さんが小さく笑っていた。口元だけ。穏やかな曲線。"}, {"id": "ch06-s04-p086", "type": "text", "text": "風祭さんは鳴海さんの笑顔を見て、自分も少し口角を上げた。鳴海さんが笑うと、風祭さんの輪郭が半段柔らかくなる。"}, {"id": "ch06-s04-p087", "type": "text", "text": "篠宮さんは何も言わなかった。けれど冷奴を食べる手が止まっていた。テーブルの会話を聞いている。篠宮さんの聞き方には重みがある。全体を受け取って、必要な時だけ言葉にする。"}, {"id": "ch06-s04-p088", "type": "text", "text": "食堂の窓から風が入った。七月の風。湿っていて、温かい。天城さんの髪が揺れた。"}, {"id": "ch06-s04-p089", "type": "text", "text": "夏になるんだな、と思った。"}, {"id": "ch06-s04-p090", "type": "text", "text": "四月に着任した。桜が散って、残響祭があって、梅雨が来て、梅雨が明けた。季節が進んでいる。季節の変化を体で感じ取れるようになったのはいつからだろう。四月には「暖かいはずだ」と知識で判断していた。六月の雨の冷たさを肌で知った。今、七月の風の温度を「温かい」と断定できる。"}, {"id": "ch06-s04-p091", "type": "text", "text": "季節を感じている。世界に触れている。"}, {"id": "ch06-s04-p092", "type": "text", "text": "夏が来る。外円区の風と、海と、塩と。天城さんの言うビーチと、蝕域の監視哨と。"}, {"id": "ch06-s04-p093", "type": "text", "text": "テーブルの五人が、それぞれの夏に向かっている。俺は引率補佐として外に出る。鳴海さんと風祭さんは訓練を続ける。篠宮さんは記録を整える。天城さんは手伝いたいと言った。"}, {"id": "ch06-s04-p094", "type": "text", "text": "夏になるんだな。"}, {"id": "ch06-s04-p095", "type": "text", "text": "食堂の天井を見上げた。アーチ窓から差し込む光の帯が、煉瓦の壁に白い矩形を描いていた。埃が光の中を漂っている。四月に見たのと同じ光景。けれど光の角度が違う。季節が違う。"}, {"id": "ch06-s04-p096", "type": "text", "text": "同じ場所にいて、季節だけが変わっていく。そのことが、不快ではなかった。"}]}, {"chapter": 6, "chapterTitle": "鐘の音の下で", "scene": 5, "sceneTitle": "夕焼けの訓練棟", "wordCount": "約6,000字", "paragraphs": [{"id": "ch06-s05-p001", "type": "text", "text": "訓練棟前の広場に、西日が斜めに差していた。"}, {"id": "ch06-s05-p002", "type": "text", "text": "十八時。夕方の計測業務が終わったところだった。音響到達距離テスト。共鳴室の内部ではなく、屋外で声がどこまで届くかを測る試験。訓練棟の正面広場に音圧レベル計を三台、十メートル間隔で設置し、共鳴者候補生の声を屋外環境で計測する。風向、気温、湿度を記録し、残響波の減衰率を距離ごとにプロットする。"}, {"id": "ch06-s05-p003", "type": "text", "text": "その三台を、一台ずつ回収していた。"}, {"id": "ch06-s05-p004", "type": "text", "text": "三脚を畳み、計器を緩衝材で包み、アルミケースに収める。アルミの蓋が夕日を反射して橙色に光った。七月の太陽はまだ高い位置にあるが、傾き始めていた。訓練棟の屋根の影が広場の石畳を半分ほど覆っている。影の縁が橙と灰色の境界線になっていた。"}, {"id": "ch06-s05-p005", "type": "text", "text": "二台目のケースの留め金を閉じた時、訓練棟の正面扉が開く音がした。"}, {"id": "ch06-s05-p006", "type": "text", "text": "重い木の扉。蝶番の軋む音は着任の頃に初めて聞いた時から変わっていない。油を差すべきだと当時思ったが、この扉には差さないのだと後で知った。残響金属を含む蝶番は、通常の潤滑油と反応して劣化する。専用の鉱物油が月に一度だけ使われる。"}, {"id": "ch06-s05-p007", "type": "text", "text": "鳴海さんが出てきた。"}, {"id": "ch06-s05-p008", "type": "text", "text": "白いブラウスに淡いブルーのスカート。制服のまま。カーディガンは畳んで左腕にかけていた。襟元にうっすらと汗の跡がある。共鳴室の訓練を終えた後の顔。額の生え際に汗の粒が残っている。亜麻色の髪が夕日の橙を吸って、蜂蜜に似た色に変わっていた。灯籠通りの下で見た色と近い。"}, {"id": "ch06-s05-p009", "type": "text", "text": "首元のチョーカーは外してあった。今日の訓練は地下の共鳴室ではなく、この屋外テストだけだったのか。それとも、チョーカーを外す余裕がある程度には回復しているのか。"}, {"id": "ch06-s05-p010", "type": "text", "text": "鳴海さんが俺に気づいた。"}, {"id": "ch06-s05-p011", "type": "text", "text": "「あ、朝霧さん。まだいらしたんですね」"}, {"id": "ch06-s05-p012", "type": "text", "text": "「機材の撤収が残っていました」"}, {"id": "ch06-s05-p013", "type": "text", "text": "「お疲れさまです」"}, {"id": "ch06-s05-p014", "type": "text", "text": "穏やかな微笑み。口元と目がほぼ同時に動く。いつもの形。だが、いつものよりも一段、力が抜けている。訓練後の微笑みには二種類あった。共鳴室の後の、消耗が滲む微笑み。屋外テストの後の、疲れてはいるが体の芯が残っている微笑み。今日は後者だった。声にかすれがない。瞳の琥珀色も濃いままだ。共鳴室ほどの負荷はかかっていなかったのだろう。"}, {"id": "ch06-s05-p015", "type": "text", "text": "鳴海さんが広場を見渡した。計器を片づけている俺と、アルミケースが二つ。三台目の音圧レベル計がまだ三脚の上にある。広場の最も遠い位置、三十メートル先。"}, {"id": "ch06-s05-p016", "type": "text", "text": "「手伝いましょうか？」"}, {"id": "ch06-s05-p017", "type": "text", "text": "「いえ、もう最後の一台です」"}, {"id": "ch06-s05-p018", "type": "text", "text": "「じゃあ、お待ちしてもいいですか。一緒に戻れたらと思って」"}, {"id": "ch06-s05-p019", "type": "text", "text": "一緒に戻る。灯籠通りの方角はこの広場から見て南東。鳴海さんの寮と、俺の官舎は途中まで同じ道だった。"}, {"id": "ch06-s05-p020", "type": "text", "text": "「わかりました」"}, {"id": "ch06-s05-p021", "type": "text", "text": "三台目を回収しに歩いた。鳴海さんは訓練棟の入口脇の石段に腰を下ろした。カーディガンを膝の上に広げている。背筋が伸びていた。座っていても姿勢が崩れない。体幹が強い。共鳴者の発声訓練は腹筋と背筋を使う。姿勢は訓練の副産物だと業務資料にあった。"}, {"id": "ch06-s05-p022", "type": "text", "text": "三台目の三脚を折り畳みながら、視界の端に鳴海さんが映っていた。夕日の中で石段に座っている鳴海さんは、訓練中の鳴海さんとも、食堂の鳴海さんとも違って見えた。何も待っていない人の座り方。膝の上のカーディガンに右手を乗せて、広場の石畳を何となく見ている。"}, {"id": "ch06-s05-p023", "type": "text", "text": "緩衝材で計器を包み、ケースに入れた。留め金を閉じる。三台のケースを台車に載せ、石段の前まで押していった。"}, {"id": "ch06-s05-p024", "type": "text", "text": "「お待たせしました」"}, {"id": "ch06-s05-p025", "type": "text", "text": "「いいえ。風が気持ちよかったので」"}, {"id": "ch06-s05-p026", "type": "text", "text": "鳴海さんが立ち上がった。スカートの裾を手で整える。石段の砂を払った。"}, {"id": "ch06-s05-p027", "type": "text", "text": "「朝霧さん、あの」"}, {"id": "ch06-s05-p028", "type": "text", "text": "「はい」"}, {"id": "ch06-s05-p029", "type": "text", "text": "「少し、お話ししながら帰ってもいいですか」"}, {"id": "ch06-s05-p030", "type": "text", "text": "台車を押す手が止まった。止まったのは一秒もなかったが、止まった。"}, {"id": "ch06-s05-p031", "type": "text", "text": "お話ししながら帰る。以前の灯籠通りでは鳴海さんから誘われた。あの時は「途中まで一緒に歩きませんか」だった。「お話ししながら帰る」は、歩くことよりも話すことに重心がある。"}, {"id": "ch06-s05-p032", "type": "text", "text": "「はい」"}, {"id": "ch06-s05-p033", "type": "text", "text": "答えた。台車を押し始めた。車輪が石畳の上を転がる音がする。鳴海さんが俺の左側を歩いた。半歩前。風祭さんが鳴海さんの半歩後ろにいるのとは逆の配置。鳴海さんの歩幅は小さい。俺が合わせている。灯籠通りで初めて並んで歩いた時と同じだった。"}, {"id": "ch06-s05-p034", "type": "text", "text": "広場を出て、連絡路に入った。訓練棟と教室棟を繋ぐ石畳の道。両脇に葉桜の残響桜が並んでいる。七月の葉は厚く、濃い緑で、影が重なって道の上に縞模様を作っていた。影の間から夕日が差し込み、石畳が橙と暗緑の交互になっている。"}, {"id": "ch06-s05-p035", "type": "text", "text": "「朝霧さん、最近すみれちゃんのところによく行ってるんですか？」"}, {"id": "ch06-s05-p036", "type": "text", "text": "鳴海さんの声が穏やかだった。世間話の温度。"}, {"id": "ch06-s05-p037", "type": "text", "text": "「メンテナンスの後に、天蓋の間に寄っています」"}, {"id": "ch06-s05-p038", "type": "text", "text": "「そうなんですね」"}, {"id": "ch06-s05-p039", "type": "text", "text": "鳴海さんが前を向いたまま小さく頷いた。リボンが揺れた。"}, {"id": "ch06-s05-p040", "type": "text", "text": "「すみれの名前を、どこで」"}, {"id": "ch06-s05-p041", "type": "text", "text": "「いろはが教えてくれました。鐘鋳塔の一番上に女の子がいるって。不思議な子がいるから気をつけてね、って」"}, {"id": "ch06-s05-p042", "type": "text", "text": "風祭さんが。鳴海さんにすみれの存在を伝えていたのか。風祭さんは鳴海さんの周辺情報を管理している。すみれの存在もその範囲に含まれている。"}, {"id": "ch06-s05-p043", "type": "text", "text": "「わたし、すみれちゃんとはあまりお話ししたことがないんです。訓練棟と鐘鋳塔は近いのに」"}, {"id": "ch06-s05-p044", "type": "text", "text": "「すみれは天蓋の間から降りてこないから、会う機会がないんだと思います」"}, {"id": "ch06-s05-p045", "type": "text", "text": "「ええ。でも一度だけ、すれ違ったことがあるんです。鐘鋳塔の入口の前で。わたしが訓練を終えて通りかかった時に、あの子が入口の脇に立っていて」"}, {"id": "ch06-s05-p046", "type": "text", "text": "鳴海さんの歩調が少し遅くなった。思い出しながら話している。"}, {"id": "ch06-s05-p047", "type": "text", "text": "「その時、すみれちゃんが、わたしの方を見て……こう言ったんです。『きれいなこえ』って」"}, {"id": "ch06-s05-p048", "type": "text", "text": "「すみれらしい」"}, {"id": "ch06-s05-p049", "type": "text", "text": "「ふふ。びっくりしました。初めて会ったのに、わたしの声を知っているみたいで」"}, {"id": "ch06-s05-p050", "type": "text", "text": "すみれは鐘の声を聞く。訓練棟で鳴海さんが歌えば、防音の壁を通しても——あるいは鐘を通じて——すみれの耳には届いているのかもしれない。"}, {"id": "ch06-s05-p051", "type": "text", "text": "「すみれちゃん、不思議な子ですよね」"}, {"id": "ch06-s05-p052", "type": "text", "text": "鳴海さんの声のトーンが変わった。半音、低くなったわけではない。音域は同じだった。響きの質が変わっている。表面の穏やかさの下に、もう一層、何かが混じった声。真剣さに近い。"}, {"id": "ch06-s05-p053", "type": "text", "text": "「でも……あの子の言葉には、何か真実がある気がします」"}, {"id": "ch06-s05-p054", "type": "text", "text": "真実。鳴海さんがその言葉を選んだことに、立ち止まりそうになった。台車を押す手はそのまま動いたが、頭の中に引っ掛かりが生まれた。"}, {"id": "ch06-s05-p055", "type": "text", "text": "すみれの言葉には真実がある。"}, {"id": "ch06-s05-p056", "type": "text", "text": "俺も感じていることだった。すみれは「せかいはおわる」と言った。詩の一行のようで、けれどすみれの口から出る言葉にはフィルタがない。事実を述べるように世界の終わりを語る。星がきれいなのと同じ棚に。その透明さを「真実」と呼ぶのなら、鳴海さんの言い方は正確だった。"}, {"id": "ch06-s05-p057", "type": "text", "text": "「鳴海さんも、そう感じますか」"}, {"id": "ch06-s05-p058", "type": "text", "text": "「はい。うまく言えないんですけど。共鳴の訓練をしていると、声を出した時に壁が応えるでしょう。残響金属が振動して、声が返ってくる。あの感覚に似ているんです。すみれちゃんの言葉は……壁に当てた声が、そのまま返ってくるような」"}, {"id": "ch06-s05-p059", "type": "text", "text": "共鳴者としての感覚で、すみれの言葉を受け取っている。俺はすみれの言葉を頭で処理して、意味を保留する。鳴海さんはすみれの言葉を体で受け取って、声の反射として理解する。同じものを別の回路で受信している。"}, {"id": "ch06-s05-p060", "type": "text", "text": "連絡路を抜けて、教室棟の横に出た。夕日が一段沈んでいた。空の色が橙から朱に移り始めている。雲の底が赤く染まっていた。鳴海さんの髪の色が変わった。蜂蜜から、薄い赤銅色に。光で人の色が変わる。共鳴室でもそう思った。"}, {"id": "ch06-s05-p061", "type": "text", "text": "「朝霧さん」"}, {"id": "ch06-s05-p062", "type": "text", "text": "「はい」"}, {"id": "ch06-s05-p063", "type": "text", "text": "「外円区の研修、いつからですか？」"}, {"id": "ch06-s05-p064", "type": "text", "text": "「八月の第二週からです。二週間の予定で」"}, {"id": "ch06-s05-p065", "type": "text", "text": "「二週間」"}, {"id": "ch06-s05-p066", "type": "text", "text": "鳴海さんがその数字を口の中で確かめるように繰り返した。声が小さくなっていた。"}, {"id": "ch06-s05-p067", "type": "text", "text": "「長いですね」"}, {"id": "ch06-s05-p068", "type": "text", "text": "「長い、ですか」"}, {"id": "ch06-s05-p069", "type": "text", "text": "「あ、いえ。大変だなと思って」"}, {"id": "ch06-s05-p070", "type": "text", "text": "鳴海さんが少し慌てた。頬の色が夕焼けのせいなのか、それ以外の理由なのか、判別できなかった。"}, {"id": "ch06-s05-p071", "type": "text", "text": "「その間、計測業務は別の人が代わるんですか？」"}, {"id": "ch06-s05-p072", "type": "text", "text": "「霜月さんが代理を手配すると言っていました」"}, {"id": "ch06-s05-p073", "type": "text", "text": "「そうですか」"}, {"id": "ch06-s05-p074", "type": "text", "text": "鳴海さんの声が、一拍の空白を挟んで戻った。穏やかな声に。けれど一拍の前と後では、声の密度が違った。何かが通り過ぎた後のような、軽い変化。"}, {"id": "ch06-s05-p075", "type": "text", "text": "言い換えれば——鳴海さんは、俺が二週間いなくなることについて、何か思うところがあった。それが何なのかを聞くのは、今ではないと判断した。"}, {"id": "ch06-s05-p076", "type": "text", "text": "「夏の外円区は暑いそうです。天城さんが、塩味の洗濯物の話をしていました」"}, {"id": "ch06-s05-p077", "type": "text", "text": "話題を動かした。意図的に。鳴海さんの顔に浮いた微細な揺れを、それ以上見ていると、俺の方が何かを感じそうだったから。"}, {"id": "ch06-s05-p078", "type": "text", "text": "「あ、燈花ちゃんは外円区のご出身でしたよね。塩味の洗濯物、面白いです」"}, {"id": "ch06-s05-p079", "type": "text", "text": "鳴海さんが笑った。小さな笑い。肩の力が抜けた。"}, {"id": "ch06-s05-p080", "type": "text", "text": "「天城さんはビーチに行こうと言っていました。研修の合間に」"}, {"id": "ch06-s05-p081", "type": "text", "text": "「あら、いいですね。わたし、海は見たことがあるんですけど、泳いだことはなくて」"}, {"id": "ch06-s05-p082", "type": "text", "text": "「俺も泳いだことはないです。記憶には」"}, {"id": "ch06-s05-p083", "type": "text", "text": "「そうですよね。朝霧さんは、記憶が——」"}, {"id": "ch06-s05-p084", "type": "text", "text": "言いかけて、鳴海さんが口を閉じた。記憶喪失の話題に踏み込みかけて、引いた。いつもそうだった。鳴海さんは俺の過去について聞かない。灯籠通りで歩いた時も聞かなかった。食堂でも聞かなかった。知っている。知っていて、自分からは触れない。"}, {"id": "ch06-s05-p085", "type": "text", "text": "「いいですよ。気にしません」"}, {"id": "ch06-s05-p086", "type": "text", "text": "「……ごめんなさい。でも」"}, {"id": "ch06-s05-p087", "type": "text", "text": "鳴海さんが右手でカーディガンの端を握った。白い布が皺になった。"}, {"id": "ch06-s05-p088", "type": "text", "text": "「朝霧さんが島に来てから、わたし、少し変わったと思うんです」"}, {"id": "ch06-s05-p089", "type": "text", "text": "変わった。誰が。鳴海さんが。"}, {"id": "ch06-s05-p090", "type": "text", "text": "「変わった、というのは」"}, {"id": "ch06-s05-p091", "type": "text", "text": "「訓練がね、前は……義務に近かったんです。候補生としてやるべきことだから、やる。それだけで。でも最近は、聴いてくれる人がいるから歌うっていう感覚が、前より強くて」"}, {"id": "ch06-s05-p092", "type": "text", "text": "共鳴室で言った言葉と繋がっていた。「聴いてくれる人がいると安心する」。あの言葉の続きが、ここに来ている。"}, {"id": "ch06-s05-p093", "type": "text", "text": "「共鳴室でもお話ししましたけど。一人で歌うと、声がどこに行くかわからなくなる。壁が応えてくれるけど、壁は聴いてくれるわけじゃない。人が聴いてくれると——ちゃんと、声が落ちる場所がある感じがして」"}, {"id": "ch06-s05-p094", "type": "text", "text": "声が落ちる場所。着地点。鳴海さんにとっての着地点が、俺になりつつある。そのことの重さを、俺はまだ正確に測れていない。"}, {"id": "ch06-s05-p095", "type": "text", "text": "「鳴海さんは、なぜ歌が好きなんですか」"}, {"id": "ch06-s05-p096", "type": "text", "text": "聞いた。唐突だったかもしれない。けれど鳴海さんが歌について語る時の声が好きだった——好き、ではない。正確ではない。鳴海さんが歌について語る声を聴いている時、俺の中のどこかが静かになる。水面が凪ぐような。その感覚が、悪くなかった。"}, {"id": "ch06-s05-p097", "type": "text", "text": "鳴海さんが足を止めた。"}, {"id": "ch06-s05-p098", "type": "text", "text": "俺も止まった。台車の車輪が石畳の上で止まり、沈黙が落ちた。教室棟の横の道。西日が建物の壁に遮られて、ここだけ薄暗い。日陰の中に二人で立っている。"}, {"id": "ch06-s05-p099", "type": "text", "text": "鳴海さんが空を見上げた。建物の屋根越しに見える空は朱から紫に変わり始めていた。"}, {"id": "ch06-s05-p100", "type": "text", "text": "「……母が、歌っていたんです」"}, {"id": "ch06-s05-p101", "type": "text", "text": "声が静かだった。普段の穏やかさとは違う静かさ。水面の下にあるものが、表面のすぐ近くまで上がってきている声。"}, {"id": "ch06-s05-p102", "type": "text", "text": "「八歳の時に、母は亡くなりました。病気で。共鳴者だったんです、母も」"}, {"id": "ch06-s05-p103", "type": "text", "text": "知っていた。業務資料に記載があった。前任の共鳴者候補生が体調不良で辞退し、その母親が先代の共鳴者だった。鳴海千歳の母、鳴海美弦。共鳴者として十五年間務め、三十二歳で死去。死因は非公開。"}, {"id": "ch06-s05-p104", "type": "text", "text": "けれど、鳴海さん本人の口から聞くのは初めてだった。"}, {"id": "ch06-s05-p105", "type": "text", "text": "「母が歌う時、わたしは隣で聴いていました。歌の意味はわからなかった。でも、母の声が部屋の中を満たす感じが好きで。声があると、空気が変わるんです。冷たい空気が温かくなるみたいに」"}, {"id": "ch06-s05-p106", "type": "text", "text": "鳴海さんの視線が空から降りて、カーディガンを握った右手に落ちた。"}, {"id": "ch06-s05-p107", "type": "text", "text": "「母が亡くなって、家の中から声が消えて。空気がずっと冷たいままで。わたしが歌い始めたのは——たぶん、あの温かさが欲しかったからだと思います」"}, {"id": "ch06-s05-p108", "type": "text", "text": "たぶん。鳴海さんがそう言った。断定ではない。自分の動機について、鳴海さん自身もまだ言い切れないものがある。それでも、こうして言葉にしたということは——俺に話してもいいと判断したということだった。"}, {"id": "ch06-s05-p109", "type": "text", "text": "「だから歌が好きなんです。使命とか、適性とか、それは後からついてきただけで。最初は、母の声が聞きたかった。自分の声で、母の声を作り直したかった。それが始まりです」"}, {"id": "ch06-s05-p110", "type": "text", "text": "鳴海さんが顔を上げた。琥珀色の瞳が、薄暗い日陰の中でも光を集めていた。夕焼けの反射光が瞳の底を照らしている。"}, {"id": "ch06-s05-p111", "type": "text", "text": "「こんな話、長くなってしまいましたね」"}, {"id": "ch06-s05-p112", "type": "text", "text": "「いいえ」"}, {"id": "ch06-s05-p113", "type": "text", "text": "言った。"}, {"id": "ch06-s05-p114", "type": "text", "text": "「聴けてよかったです」"}, {"id": "ch06-s05-p115", "type": "text", "text": "鳴海さんの目が一瞬だけ動いた。見開いたのではない。視線が俺の顔の上を走った。確かめている。俺の言葉が本心かどうかを。"}, {"id": "ch06-s05-p116", "type": "text", "text": "本心だった。鳴海さんの歌の理由を聞いた時、胸の中で何かが動いた。共鳴室で聴いた温かさと痛みとは違う動き。もっと静かで、もっと小さい。何かが正しい場所に収まるような感覚。パズルのピースが嵌まる——という比喩は大げさだ。もっと些細な。棚の上の本の向きが揃った程度の、小さな整理。"}, {"id": "ch06-s05-p117", "type": "text", "text": "鳴海さんが声を出して笑った。"}, {"id": "ch06-s05-p118", "type": "text", "text": "声を出して笑ったのを見るのは、初めてかもしれない。いつもは口元の微笑みか、小さな息の漏れか。今のは違った。「は」という音が一つ、喉から出た。短い笑い。けれど嘘がない笑いだった。"}, {"id": "ch06-s05-p119", "type": "text", "text": "「ありがとうございます。朝霧さんに話してよかったです」"}, {"id": "ch06-s05-p120", "type": "text", "text": "「よかった、ですか」"}, {"id": "ch06-s05-p121", "type": "text", "text": "「はい。朝霧さんは、聴いてくれるから」"}, {"id": "ch06-s05-p122", "type": "text", "text": "聴いてくれる。共鳴室の時も言っていた。俺は聴く側の人間として、鳴海さんの中に位置づけられている。歌を聴く。話を聴く。どちらも同じ動詞を使う。鳴海さんにとって、その二つは近い場所にあるのだろう。"}, {"id": "ch06-s05-p123", "type": "text", "text": "歩き始めた。台車がまた転がる。教室棟の影を抜けると、西日が戻ってきた。空の色が紫に近づいている。朱が褪せて、紫と紺の境界が空の高い位置まで伸びていた。"}, {"id": "ch06-s05-p124", "type": "text", "text": "「夕焼け、きれいですね」"}, {"id": "ch06-s05-p125", "type": "text", "text": "鳴海さんが言った。"}, {"id": "ch06-s05-p126", "type": "text", "text": "「ああ」"}, {"id": "ch06-s05-p127", "type": "text", "text": "きれい。鳴海さんの横顔に夕焼けの残光が当たっている。亜麻色の髪が赤銅から、紫がかった銀に変わり始めていた。共鳴室の残響灯の下で見た色に似ている。光で変わる。場所と時間で変わる。同じ人なのに。"}, {"id": "ch06-s05-p128", "type": "text", "text": "「朝霧さんは、夕焼け好きですか？」"}, {"id": "ch06-s05-p129", "type": "text", "text": "「……嫌いではないです」"}, {"id": "ch06-s05-p130", "type": "text", "text": "「ふふ。朝霧さんらしい答え」"}, {"id": "ch06-s05-p131", "type": "text", "text": "鳴海さんが微笑んだ。壁の低い微笑み。灯籠通りの分岐で見せたものに近い。歯が見えている。目が細くなっている。カーディガンを抱えた腕が緩んでいる。訓練後の疲労が残っているはずなのに、体の輪郭が柔らかかった。"}, {"id": "ch06-s05-p132", "type": "text", "text": "鳴海さんとの会話が——心地よかった。"}, {"id": "ch06-s05-p133", "type": "text", "text": "心地よい。着任初日の朝に鐘の音を聴いた時に感じた「心地よい」と同じ言葉を使うことに、抵抗がなかった。鐘の音の心地よさは体の深い場所から来る。鳴海さんとの会話の心地よさは、もっと表面に近い。皮膚の温度が一度上がるような、穏やかな変化。楽しい、と呼ぶにはまだ距離がある。けれど悪くないの先にある何かに、手が触れかけている。"}, {"id": "ch06-s05-p134", "type": "text", "text": "連絡路の残響桜の下を通り抜けた。葉桜の影が二人の上に重なった。"}, {"id": "ch06-s05-p135", "type": "text", "text": "その時——視界の端で、何かが動いた。"}, {"id": "ch06-s05-p136", "type": "text", "text": "訓練棟の角。今通り過ぎた建物の側面の向こう。栗色の短い髪が見えた。見えたと思った次の瞬間には消えていた。建物の影に紛れたのか、最初からいなかったのか。"}, {"id": "ch06-s05-p137", "type": "text", "text": "気のせいかもしれない。"}, {"id": "ch06-s05-p138", "type": "text", "text": "台車を押す手に力を戻した。鳴海さんは何も言わなかった。俺と同じ方向を見ていなかった。前を向いて、夕焼けの空を見ている。"}, {"id": "ch06-s05-p139", "type": "text", "text": "灯籠通りの入口が見えた。灯籠にはまだ火が入っていない。点灯係が来るのは十九時以降だったはずだ。夕方の薄暗さの中、灯籠の硝子が鈍く光っていた。"}, {"id": "ch06-s05-p140", "type": "text", "text": "「ここで」"}, {"id": "ch06-s05-p141", "type": "text", "text": "鳴海さんが足を止めた。灯籠通りの入口。ここから先は道が分かれる。鳴海さんの寮は南。俺の官舎は南東。"}, {"id": "ch06-s05-p142", "type": "text", "text": "「今日は、ありがとうございました。撤収、お疲れさまです」"}, {"id": "ch06-s05-p143", "type": "text", "text": "「こちらこそ。話を聞かせてくれて、ありがとうございました」"}, {"id": "ch06-s05-p144", "type": "text", "text": "敬語。仕事の挨拶。けれど声に含まれるものは、仕事の温度ではなかった。"}, {"id": "ch06-s05-p145", "type": "text", "text": "鳴海さんが一歩下がった。カーディガンを肩にかけた。白い布が夕暮れの中で薄紫に見えた。"}, {"id": "ch06-s05-p146", "type": "text", "text": "「また、お話ししましょうね」"}, {"id": "ch06-s05-p147", "type": "text", "text": "灯籠通りの分岐で聞いた言葉に似ていた。「また、聴いてくれたら嬉しいです」。「また、聴いてくださいね」。今度は「お話ししましょう」。聴くから、話すへ。一方向から、双方向に変わっている。"}, {"id": "ch06-s05-p148", "type": "text", "text": "「はい」"}, {"id": "ch06-s05-p149", "type": "text", "text": "返事をした。声が自然に出た。"}, {"id": "ch06-s05-p150", "type": "text", "text": "鳴海さんが南の道を歩いていった。背中が小さくなる。白いブラウスと淡いブルーのスカートが、夕闇に溶けていく。角を曲がる直前に、鳴海さんが振り返った。手を小さく振った。俺もわずかに手を上げた。それだけの動作に、間があった。長い間ではない。けれど何もない間ではなかった。"}, {"id": "ch06-s05-p151", "type": "text", "text": "鳴海さんの姿が消えた。"}, {"id": "ch06-s05-p152", "type": "text", "text": "台車を押して、南東の道を歩き始めた。車輪の音が夕暮れの静けさに響く。"}, {"id": "ch06-s05-p153", "type": "text", "text": "この島に来て、三ヶ月が過ぎようとしている。"}, {"id": "ch06-s05-p154", "type": "text", "text": "四月の霧の朝に着任した。桜が散った。残響祭があった。梅雨が来て、過ぎた。今、七月の夕焼けの中にいる。季節が三つ変わった。その間に、俺の中にも何かが変わった。何が変わったのかを正確に言い当てることは、まだできない。"}, {"id": "ch06-s05-p155", "type": "text", "text": "鳴海さんの歌声を聴いた時の、胸の温かさ。天城さんの笑い声が食堂に響く時の、鼓膜の振動。篠宮さんと記録室でペンの音を重ねている時の、体の楽さ。風祭さんの緑色の目が俺を見る時の、背筋の硬さ。すみれの冷たい手が触れた時の、左手の甲の記憶。"}, {"id": "ch06-s05-p156", "type": "text", "text": "一つ一つは名前のつかない感覚で、まとめて呼ぶ言葉も持っていない。けれどそれらが体の中に積もっていることだけは、わかる。四月にはなかったものが、今はある。"}, {"id": "ch06-s05-p157", "type": "text", "text": "鳴海さんとの今日の時間は、その積み重ねの中の一つだった。仕事の延長でも、偶然の遭遇でもなかった。鳴海さんが「お話ししながら帰りたい」と言い、俺が「はい」と答え、二人で歩いた。それだけのことが、今日という日の中で最も長い時間を占めている。"}, {"id": "ch06-s05-p158", "type": "text", "text": "心地よかった。"}, {"id": "ch06-s05-p159", "type": "text", "text": "その一語を、体が否定しなかった。"}, {"id": "ch06-s05-p160", "type": "text", "text": "灯籠通りの灯籠に、一つずつ火が入り始めていた。点灯係が来たらしい。橙色の光が硝子の中で揺れている。四月の夜にも見た光景。同じ光、同じ通り。けれど光の意味が少し変わっている。四月には「嫌ではない」だった。今は——嫌ではないの先に、もう少しだけ近づいた場所にいる。"}, {"id": "ch06-s05-p161", "type": "text", "text": "官舎の前で台車を止めた。アルミケースを下ろし、倉庫に運んだ。三台分の計測器を棚に戻し、記録用紙を鞄に入れた。明日、報告書にまとめる。"}, {"id": "ch06-s05-p162", "type": "text", "text": "官舎の部屋に入った。窓の外は紫と紺が混じり合った空だった。夕焼けは終わっていた。"}, {"id": "ch06-s05-p163", "type": "text", "text": "覚えておく。鳴海さんの声で聞いた、歌が好きな理由。母の声が作った温かさ。それを取り戻すために歌い始めたこと。聴いてくれる人がいることの意味。"}, {"id": "ch06-s05-p164", "type": "text", "text": "それと、鳴海さんと話している時間が心地よいということ。"}, {"id": "ch06-s05-p165", "type": "text", "text": "窓を細く開けた。七月の夜風が入ってきた。湿気を含んだ風。温かい風。"}, {"id": "ch06-s05-p166", "type": "text", "text": "鐘鋳塔の方角から、かすかに鐘の余韻が聞こえた気がした。鳴っていないはずの鐘。すみれの言う「ならしてないときも、のこっている」もの。"}, {"id": "ch06-s05-p167", "type": "text", "text": "耳を澄ませたが、聞こえなかった。いつも通りだった。"}]}, {"chapter": 7, "chapterTitle": "夏の残響", "scene": 1, "sceneTitle": "夏の海", "wordCount": "約5,200字", "paragraphs": [{"id": "ch07-s01-p001", "type": "text", "text": "砂が熱かった。"}, {"id": "ch07-s01-p002", "type": "text", "text": "裸足になったのは天城さんの指示だった。「靴脱いで！ 砂浜は裸足じゃないと意味ないんだよ」と言われ、サンダルを脱いだ。砂粒が足の裏に張りつく。表面は焼けるように熱く、三センチほど掘れば湿った冷たさがある。温度の境界が足の裏の皮膚一枚で切り替わる。"}, {"id": "ch07-s01-p003", "type": "text", "text": "七月の下旬。東漁港から十五分ほど歩いた先にある砂浜。天城さんがこの場所を見つけてきた。「あたし、ここ知ってんの。漁港のおじさんたちは昼から出てこないし、貸し切りだよ」。外円区で育った人間の情報だった。"}, {"id": "ch07-s01-p004", "type": "text", "text": "午前十時。太陽はすでに高い位置にある。空に雲はほとんどない。真上に近い角度から落ちてくる日差しが砂の表面を白く飛ばしている。目を細めても追いつかない明るさ。海面が光の粒を撒き散らしていて、水平線の手前が銀色に輝いていた。"}, {"id": "ch07-s01-p005", "type": "text", "text": "潮の匂い。塩と、藻と、魚の内臓を煮詰めたような、甘い腐敗に似た何か。嫌ではなかった。匂いが鼻腔の奥まで入ってくる。息を吸うたびに肺が海水で満たされるような錯覚がある。"}, {"id": "ch07-s01-p006", "type": "text", "text": "波の音は規則的だった。七秒から九秒の間隔で寄せては返す。遠くの波が砕ける低い音と、足元に届く泡の音が混ざっている。鐘鋳塔の共鳴管を通る空気の音に似ていた。周期があって、止まらない。"}, {"id": "ch07-s01-p007", "type": "text", "text": "海を見るのは初めてではないはずだった。島に渡る船に乗った。海は見ている。けれど「海を見に来た」のは——記憶の中では——これが初めてだった。"}, {"id": "ch07-s01-p008", "type": "text", "text": "六月の夕焼けの訓練棟から、二週間ほど過ぎていた。外円区研修の話が進み、八月第二週からの日程が正式に決まった。天城さんが「研修の前にさ、息抜きしない？」と言い出したのが三日前。鳴海さんが「いいですね」と頷き、風祭さんが「ちーちゃんが行くなら」と応じ、篠宮さんが「記録材を持参してもよいですか」と確認し、俺が「わかりました」と答えた。"}, {"id": "ch07-s01-p009", "type": "text", "text": "五人で海に来た。それだけのことだが、四月には想像しなかった光景だった。"}, {"id": "ch07-s01-p010", "type": "divider", "text": "---"}, {"id": "ch07-s01-p011", "type": "text", "text": "天城さんが水着に着替えて戻ってきた。白いビキニの上に薄いTシャツを羽織り、デニムの短パンを穿いている。髪をいつものポニーテールより高い位置で結んでいた。首の後ろが見える。日焼けの跡が肩甲骨の上まで伸びていた。外円区の夏を何度も通過した体だった。"}, {"id": "ch07-s01-p012", "type": "text", "text": "「蓮くん、泳ごう！」"}, {"id": "ch07-s01-p013", "type": "text", "text": "波打ち際に立って、手を振っている。Tシャツの裾が風に煽られていた。"}, {"id": "ch07-s01-p014", "type": "text", "text": "「泳いだことがないので、見ています」"}, {"id": "ch07-s01-p015", "type": "text", "text": "「見てるだけなんてもったいないじゃん。足だけでいいからさ」"}, {"id": "ch07-s01-p016", "type": "text", "text": "天城さんの声には拒否を受け付けない質がある。食堂で初めて会った時からそうだった。許可を求めず向かいに座り、コーヒーの味を訊き、喫茶店に引っ張っていく。あの時と同じ圧力が、砂浜の上でも変わらない。"}, {"id": "ch07-s01-p017", "type": "text", "text": "ハーフパンツの裾を膝の上まで折り、波打ち際まで歩いた。"}, {"id": "ch07-s01-p018", "type": "text", "text": "海水が足首を覆った。"}, {"id": "ch07-s01-p019", "type": "text", "text": "冷たい。七月なのに冷たい。砂の熱さとの温度差に、ふくらはぎの筋肉が一瞬収縮した。水は透明で、自分の足が水の中で少し白く見えた。砂粒が水流に巻き上げられて、足の甲の上を流れていく。"}, {"id": "ch07-s01-p020", "type": "text", "text": "「どう？」"}, {"id": "ch07-s01-p021", "type": "text", "text": "天城さんが膝まで海に入って、こちらを見ていた。"}, {"id": "ch07-s01-p022", "type": "text", "text": "「冷たい」"}, {"id": "ch07-s01-p023", "type": "text", "text": "「冷たいだけ？ もっとなんかあるでしょ」"}, {"id": "ch07-s01-p024", "type": "text", "text": "もっと。足の裏に波が当たっている。波が引く時に砂が足指の間から流れ出ていく。足が沈む。踏みしめる力と、波に抜かれる力が交互にかかる。不安定だった。不安定だが、倒れない。体が勝手にバランスを取っている。"}, {"id": "ch07-s01-p025", "type": "text", "text": "「足が沈む」"}, {"id": "ch07-s01-p026", "type": "text", "text": "「感想がそれ？」"}, {"id": "ch07-s01-p027", "type": "text", "text": "天城さんが笑った。口を大きく開けて笑う。白い歯が見える。目が細くなる。風で前髪が乱れている。整えない。太陽の下の天城さんは、食堂や喫茶店で見る天城さんよりも輪郭がくっきりしていた。光の量が多いから、影も濃い。"}, {"id": "ch07-s01-p028", "type": "text", "text": "天城さんはTシャツを脱いで砂浜に投げた。腰まで海に入って、両手で水を掬い上げた。海水が太陽に透けて、一瞬だけ虹の端のような色を作った。"}, {"id": "ch07-s01-p029", "type": "divider", "text": "---"}, {"id": "ch07-s01-p030", "type": "text", "text": "鳴海さんは波打ち際よりも手前にいた。"}, {"id": "ch07-s01-p031", "type": "text", "text": "白いワンピースの裾を両手で少し持ち上げ、足首まで海水に浸けている。麦わら帽子のつばが広く、顔の半分が日陰になっていた。帽子の下から覗く表情は穏やかだった。目を細めて、水面を見ている。"}, {"id": "ch07-s01-p032", "type": "text", "text": "「気持ちいいですね」"}, {"id": "ch07-s01-p033", "type": "text", "text": "俺の視線に気づいたのか、鳴海さんがこちらを向いて微笑んだ。壁の低い微笑み。訓練棟からの帰り道で見せてくれたものと同じ種類の笑顔だった。"}, {"id": "ch07-s01-p034", "type": "text", "text": "「ええ」"}, {"id": "ch07-s01-p035", "type": "text", "text": "鳴海さんの足が海水の中で白く光っていた。波が来るたびに、ワンピースの裾がわずかに濡れる。気にしていない。麦わら帽子を右手で押さえて、海の方を見た。亜麻色の髪が帽子の隙間から垂れて、風に揺れている。夕焼けの中で見た髪の色とは違う。太陽の下では、明るい金に近い色をしていた。"}, {"id": "ch07-s01-p036", "type": "divider", "text": "---"}, {"id": "ch07-s01-p037", "type": "text", "text": "風祭さんは鳴海さんの二歩後ろにいた。"}, {"id": "ch07-s01-p038", "type": "text", "text": "スポーティな黒いビキニにラッシュガードを羽織っている。足は海水に入れていない。砂浜に直接座り、膝を立てて、日焼け止めを腕に塗っていた。動作が手慣れている。両腕、首筋、耳の裏。チューブから出す量が毎回同じだった。"}, {"id": "ch07-s01-p039", "type": "text", "text": "鳴海さんが波打ち際にいるのを見ながら、風祭さんが声をかけた。"}, {"id": "ch07-s01-p040", "type": "text", "text": "「ちーちゃん、あんまり長く立ってると疲れるよ。こっち来て座りなよ」"}, {"id": "ch07-s01-p041", "type": "text", "text": "「もう少しだけ」"}, {"id": "ch07-s01-p042", "type": "text", "text": "「日差し強いから。帽子あっても」"}, {"id": "ch07-s01-p043", "type": "text", "text": "風祭さんが立ち上がり、自分のラッシュガードを脱いで鳴海さんの肩にかけた。鳴海さんが「ありがとう」と言って、ラッシュガードの襟を合わせた。風祭さんはそのまま鳴海さんの隣に立ち、海を見た。立ち位置は左側の半歩後ろ。いつもの配置だった。"}, {"id": "ch07-s01-p044", "type": "text", "text": "鳴海さんがゆっくりと砂浜に上がり、風祭さんが持ってきたレジャーシートの上に座った。麦わら帽子を膝の上に置いて、額の汗を拭いた。風祭さんがペットボトルの水を渡す。鳴海さんが一口飲んで、「ありがとう」と二回目を言った。"}, {"id": "ch07-s01-p045", "type": "text", "text": "風祭さんは日焼け止めのチューブを鳴海さんに差し出した。鳴海さんが腕に塗り始める。風祭さんはその横に座って、緑色の目で海を見ていた。天城さんが腰まで水に入っているのを見て、口の端が少し上がった。"}, {"id": "ch07-s01-p046", "type": "text", "text": "「燈花は元気だね」"}, {"id": "ch07-s01-p047", "type": "text", "text": "声に棘はなかった。観察の声。海に来ると、風祭さんの声から角が一つ減る。千歳のそばにいて、日差しがあって、天城さんが遠くで騒いでいる。その配置が風祭さんの輪郭をほのかに柔らかくしていた。"}, {"id": "ch07-s01-p048", "type": "divider", "text": "---"}, {"id": "ch07-s01-p049", "type": "text", "text": "篠宮さんはパラソルの下にいた。"}, {"id": "ch07-s01-p050", "type": "text", "text": "薄手の長袖シャツにロングスカート。帽子は被っていない。レジャーシートの上に正座に近い姿勢で座り、膝の上にメモ帳を開いていた。左手にメモ帳、右手にペン。日陰の中で、ペンが紙の上を走る音がかすかに聞こえる。"}, {"id": "ch07-s01-p051", "type": "text", "text": "パラソルの下に行った。"}, {"id": "ch07-s01-p052", "type": "text", "text": "「篠宮さん」"}, {"id": "ch07-s01-p053", "type": "text", "text": "「はい」"}, {"id": "ch07-s01-p054", "type": "text", "text": "顔を上げた。薄紫色の瞳が、パラソルの布を透過したオレンジ色の光に照らされていた。表情に変化はない。いつもの篠宮さんだった。"}, {"id": "ch07-s01-p055", "type": "text", "text": "メモ帳を覗くと、日付と時刻の下に、細かい文字が並んでいた。"}, {"id": "ch07-s01-p056", "type": "text", "text": "「海水温度——推定23℃。波高——30〜50cm。風向——南南西。風速——体感3〜4m/s」"}, {"id": "ch07-s01-p057", "type": "text", "text": "「休みの日にも記録するんですか」"}, {"id": "ch07-s01-p058", "type": "text", "text": "篠宮さんがペンを止めた。止めたのは一秒にも満たなかったが、止まった。それから、ペンの先をメモ帳に戻した。"}, {"id": "ch07-s01-p059", "type": "text", "text": "「習慣です」"}, {"id": "ch07-s01-p060", "type": "text", "text": "声は静かだった。説明でも弁解でもない。事実の報告。記録室でペンの音を重ねている時と同じ温度の声だった。"}, {"id": "ch07-s01-p061", "type": "text", "text": "篠宮さんの筆跡は、記録室で見るものと同じだった。小さく、正確で、行間が均等。砂浜の上でも、紙の上の文字は崩れない。"}, {"id": "ch07-s01-p062", "type": "text", "text": "「朝霧さんは、海を見てどう感じますか」"}, {"id": "ch07-s01-p063", "type": "text", "text": "篠宮さんが訊いた。顔は上げず、ペンを動かしながら。"}, {"id": "ch07-s01-p064", "type": "text", "text": "「広い」"}, {"id": "ch07-s01-p065", "type": "text", "text": "「広い、ですか」"}, {"id": "ch07-s01-p066", "type": "text", "text": "篠宮さんのペンが一画だけ長くなった。書きかけの文字の最後の線が、普段より二ミリほど伸びていた。"}, {"id": "ch07-s01-p067", "type": "text", "text": "それだけの変化だった。それ以上の反応はなかった。篠宮さんはペンを紙に戻し、風向きの記録の続きを書いた。"}, {"id": "ch07-s01-p068", "type": "divider", "text": "---"}, {"id": "ch07-s01-p069", "type": "text", "text": "海に戻った。"}, {"id": "ch07-s01-p070", "type": "text", "text": "天城さんが沖の方まで泳いでいた。腕を大きく回すクロール。水しぶきが白く上がる。泳ぎ慣れている。外円区の海で育った体が覚えている動きだった。"}, {"id": "ch07-s01-p071", "type": "text", "text": "俺は膝まで海に入ったところで立っていた。波が来るたびに体が揺れる。海水が肌に触れている面積が増えると、温度感覚が変わった。足首だけの時は冷たかった。膝まで入ると、冷たさの中に体温が混ざるような感覚がある。海水と皮膚の境界が曖昧になっていく。"}, {"id": "ch07-s01-p072", "type": "text", "text": "夏だ、と思った。"}, {"id": "ch07-s01-p073", "type": "text", "text": "頭で判断したのではなかった。砂の熱さが足の裏にあり、海水の冷たさが膝にあり、太陽の光が肩に当たっている。潮の匂いが肺を満たし、波の音が鼓膜を叩いている。五つの感覚が同時に入ってきて、処理が追いつく前に——体の中のどこかが、季節の名前を見つけた。"}, {"id": "ch07-s01-p074", "type": "text", "text": "夏だ。"}, {"id": "ch07-s01-p075", "type": "text", "text": "四月に島に着いた時は春だった。桜が散って、梅雨が来て、晴れた。それぞれの季節を通過した。通過した、という言い方は正確ではない。季節の中にいた。春の中に、梅雨の中に、今は夏の中にいる。体がそれを知っている。"}, {"id": "ch07-s01-p076", "type": "text", "text": "天城さんが泳いで戻ってきた。足が砂底に届く深さまで来ると立ち上がり、髪から海水をぼたぼたと垂らしながら歩いてきた。"}, {"id": "ch07-s01-p077", "type": "text", "text": "「蓮くん、突っ立ってないで——」"}, {"id": "ch07-s01-p078", "type": "text", "text": "言いながら、両手で海水を掬い上げた。"}, {"id": "ch07-s01-p079", "type": "text", "text": "掬い上げた水が、弧を描いて飛んできた。"}, {"id": "ch07-s01-p080", "type": "text", "text": "——顔に当たった。"}, {"id": "ch07-s01-p081", "type": "text", "text": "海水が額を伝って目に入りかけた。塩辛い。鼻から水が入った。反射的に顔をしかめ——"}, {"id": "ch07-s01-p082", "type": "text", "text": "その時、何が起きたのかを正確に再現するのは難しい。"}, {"id": "ch07-s01-p083", "type": "text", "text": "水が顔に当たった。冷たかった。目を閉じた。鼻が痛んだ。海水の塩辛さが口の端に触れた。そこまでは、体の反応として理解できる。問題はその次だった。"}, {"id": "ch07-s01-p084", "type": "text", "text": "顔を拭おうとした手が止まった。止まったのは、口が先に動いたからだった。"}, {"id": "ch07-s01-p085", "type": "text", "text": "口角が上がっていた。"}, {"id": "ch07-s01-p086", "type": "text", "text": "天城さんの声が聞こえた。"}, {"id": "ch07-s01-p087", "type": "text", "text": "「——蓮くん、今笑ってたよ」"}, {"id": "ch07-s01-p088", "type": "text", "text": "笑って。"}, {"id": "ch07-s01-p089", "type": "text", "text": "「笑って……？」"}, {"id": "ch07-s01-p090", "type": "text", "text": "「うん。今。水かけた時。笑ったよ」"}, {"id": "ch07-s01-p091", "type": "text", "text": "天城さんの琥珀色の目が、まっすぐ俺を見ていた。髪から水が垂れている。笑顔。けれどいつもの全力の笑顔ではない。目が少し大きく開いていた。驚きと、それから——何か別のもの。名前はつけられない。"}, {"id": "ch07-s01-p092", "type": "text", "text": "口元に手を当てた。"}, {"id": "ch07-s01-p093", "type": "text", "text": "口角が、まだ上がっていた。唇の端が持ち上がった状態で、顔の筋肉がその形を維持していた。意図していない形だった。「笑おう」と思って笑ったのではない。水が顔に当たって、冷たくて、塩辛くて——そこから先は、思考を経由しなかった。"}, {"id": "ch07-s01-p094", "type": "text", "text": "口の筋肉が動いた。頬の筋肉が引っ張られた。目の周りの皮膚が少し寄った。"}, {"id": "ch07-s01-p095", "type": "text", "text": "それが「笑い」だと、天城さんに言われるまでわからなかった。"}, {"id": "ch07-s01-p096", "type": "text", "text": "「……そう、みたいです」"}, {"id": "ch07-s01-p097", "type": "text", "text": "声が出た。自分の声が、いつもと少し違った。硬さが一段減っている。"}, {"id": "ch07-s01-p098", "type": "text", "text": "天城さんが笑った。今度はいつもの笑顔だった。口を大きく開けて、歯を見せて、目を細めて。"}, {"id": "ch07-s01-p099", "type": "text", "text": "「よかった」"}, {"id": "ch07-s01-p100", "type": "text", "text": "それだけ言った。天城さんはそれ以上何も言わなかった。「初めてだね」とも「珍しいね」とも言わない。「よかった」の一語で閉じた。"}, {"id": "ch07-s01-p101", "type": "text", "text": "天城さんが海の方を向いた。もう一度泳ぎに行く姿勢。Tシャツは脱いだままで、日差しが肩に当たっている。"}, {"id": "ch07-s01-p102", "type": "text", "text": "その時——天城さんの視線が、海の向こうの一点で止まった。"}, {"id": "ch07-s01-p103", "type": "text", "text": "水平線の少し上。南西の方角。外円区のある方角。天城さんの目がそこを見ていたのは二秒ほどだった。表情は変わらなかった。口角は上がったまま。けれど目だけが、遠い場所を探していた。"}, {"id": "ch07-s01-p104", "type": "text", "text": "天城さんが水に飛び込んだ。水しぶきが大きく上がった。クロールで沖に向かっていく背中を見た。"}, {"id": "ch07-s01-p105", "type": "divider", "text": "---"}, {"id": "ch07-s01-p106", "type": "text", "text": "砂浜に上がった。"}, {"id": "ch07-s01-p107", "type": "text", "text": "パラソルの陰に入ると、日差しの圧力が消えた。篠宮さんがメモ帳を書き続けている。風祭さんが鳴海さんの隣でペットボトルの水を飲んでいた。鳴海さんは麦わら帽子を被り直して、海を見ている。"}, {"id": "ch07-s01-p108", "type": "text", "text": "俺の顔を見て、鳴海さんが小さく首を傾げた。"}, {"id": "ch07-s01-p109", "type": "text", "text": "「朝霧さん、顔が濡れていますよ」"}, {"id": "ch07-s01-p110", "type": "text", "text": "「天城さんに水をかけられました」"}, {"id": "ch07-s01-p111", "type": "text", "text": "「あら」"}, {"id": "ch07-s01-p112", "type": "text", "text": "鳴海さんが口元を手で覆って笑った。息が漏れるような、控えめな笑い。"}, {"id": "ch07-s01-p113", "type": "text", "text": "風祭さんが立ち上がって、タオルを投げてきた。受け取った。顔を拭いた。タオルの繊維に海水の塩が残っている。"}, {"id": "ch07-s01-p114", "type": "text", "text": "「ありがとうございます」"}, {"id": "ch07-s01-p115", "type": "text", "text": "「ん」"}, {"id": "ch07-s01-p116", "type": "text", "text": "風祭さんの返事は短かった。けれど声に角がなかった。"}, {"id": "ch07-s01-p117", "type": "text", "text": "レジャーシートの端に座った。五人分の荷物が散らばっている。天城さんのサンダルと脱ぎ捨てたTシャツ。鳴海さんの麦わら帽子用の袋。風祭さんの日焼け止めのチューブ。篠宮さんのメモ帳の予備。俺のサンダル。"}, {"id": "ch07-s01-p118", "type": "text", "text": "それぞれの持ち物が、同じ砂浜の上にある。"}, {"id": "ch07-s01-p119", "type": "text", "text": "口元に手を当てた。もう口角は元に戻っていた。普段の形に。けれど、筋肉がさっきの形を覚えている。笑った時の、あの形を。"}, {"id": "ch07-s01-p120", "type": "text", "text": "考える前に、笑った。"}, {"id": "ch07-s01-p121", "type": "text", "text": "これまで笑ったことがなかったわけではない。鳴海さんの歌を聴いた後に「嫌ではない」と言い、天城さんの冗談に「悪くない」と答えた。それらは判断を経由した反応だった。「笑うべき場面だ」とは思わなかったが、「嫌ではない」「悪くない」を経て、顔の筋肉がわずかに動くことはあった。"}, {"id": "ch07-s01-p122", "type": "text", "text": "今日のは違った。"}, {"id": "ch07-s01-p123", "type": "text", "text": "水が飛んできた。冷たかった。それだけ。判断も、評価も、「嫌ではない」も「悪くない」もなかった。水が顔に当たって、体が勝手に反応した。その反応が「笑い」だった。"}, {"id": "ch07-s01-p124", "type": "text", "text": "模倣ではなかった。"}, {"id": "ch07-s01-p125", "type": "text", "text": "四月から、いろいろなものに名前をつけてきた。「温かいはずだ」から「心地よかった」まで。どの名前も、感覚が先にあって、思考が後から追いかけて、言葉を探して貼りつけた。今日は違う。感覚と反応の間に思考が入る隙間がなかった。"}, {"id": "ch07-s01-p126", "type": "text", "text": "体が笑った。"}, {"id": "ch07-s01-p127", "type": "text", "text": "それが何を意味するのか、まだ正確にはわからない。けれど——四月の俺には、起きなかったことだ。"}, {"id": "ch07-s01-p128", "type": "text", "text": "波の音が続いている。天城さんが沖で泳いでいる。鳴海さんが海を見ている。風祭さんが鳴海さんの横にいる。篠宮さんがメモ帳に何かを書いている。"}, {"id": "ch07-s01-p129", "type": "text", "text": "砂浜の上に、五人分の時間が並んでいた。"}, {"id": "ch07-s01-p130", "type": "text", "text": "海水で濡れたハーフパンツが砂を含んで重い。足の裏の砂粒が乾いてざらつく。太陽が肩を焼いている。潮の匂いが消えない。"}, {"id": "ch07-s01-p131", "type": "text", "text": "夏だった。体の全部で、夏だった。"}]}, {"chapter": 7, "chapterTitle": "夏の残響", "scene": 2, "sceneTitle": "灯篭に書く名前", "wordCount": "約6,000字", "paragraphs": [{"id": "ch07-s02-p001", "type": "text", "text": "池の水面に、空の色が溶けていた。"}, {"id": "ch07-s02-p002", "type": "text", "text": "八月。中円公園の池は東西に長い楕円形で、周囲に残響桜が植わっている。春には薄紫の花びらが水に浮かぶ場所だが、今は緑の葉が厚く茂り、池のほとりに低い影を落としていた。夕方の六時。太陽は西に傾き、空の半分が橙と薄紅に焼けている。池の表面がその色をそのまま映していた。風がないので水面は鏡に近い。空と池の境界が曖昧になって、地面の上に二つの夕焼けが重なっていた。"}, {"id": "ch07-s02-p003", "type": "text", "text": "池のほとりに灯篭が並んでいる。"}, {"id": "ch07-s02-p004", "type": "text", "text": "木と紙で組まれた四角い灯篭。高さは二十センチほど。底板の上に蝋燭が立ち、紙の壁で囲われている。紙は白い和紙で、上部に丸い通気口がある。蝋燭にはまだ火が入っていない。並べられた灯篭の数は百を超えていた。池のほとりの芝生の上に整列して置かれ、その前に人々が集まっている。"}, {"id": "ch07-s02-p005", "type": "text", "text": "市民が多かった。老人、子供、若い男女。服装は白を基調としたものが目立つ。追悼の色らしい。声は低い。笑い声は聞こえない。囁き声と足音と、時折すすり泣く声。池のほとりの空気は重くはないが、厚い。何かが沈殿しているような密度がある。"}, {"id": "ch07-s02-p006", "type": "text", "text": "年に一度の灯篭流し。蝕域に飲まれて消えた人々を追悼する行事。灯篭に消えた人の名前を書き、池に流す。この島ではそういう行事がある。管理局の広報で知ったのは先月のことだった。"}, {"id": "ch07-s02-p007", "type": "text", "text": "五人で来た。"}, {"id": "ch07-s02-p008", "type": "text", "text": "天城さんが「皆で行こうよ」と言い出したのは三日前だった。昼食の席で、天城さんの声はいつもの明るさから一段落ちていた。灯篭流しの話題を出す時だけ、声の温度が変わる。外円区で育った天城さんにとって、消えた人はもっと近い場所にいる。"}, {"id": "ch07-s02-p009", "type": "text", "text": "「蓮くんも行くでしょ？」"}, {"id": "ch07-s02-p010", "type": "text", "text": "問いかけではなく確認だった。俺は「はい」と答えた。"}, {"id": "ch07-s02-p011", "type": "divider", "text": "---"}, {"id": "ch07-s02-p012", "type": "text", "text": "池のほとりの受付で灯篭を受け取った。一人一つ。白い和紙の灯篭と、名前を書くための黒い油性ペン。受付の女性が「お名前は、灯篭の正面の紙にお書きください」と説明した。声は淡々としていたが、目の縁が赤かった。この人にも消えた誰かがいるのだろう。"}, {"id": "ch07-s02-p013", "type": "text", "text": "五つの灯篭を抱えて、池のほとりのベンチの前まで移動した。"}, {"id": "ch07-s02-p014", "type": "text", "text": "鳴海さんが灯篭を膝の上に置いた。白いブラウスに薄桃色のカーディガン。髪の亜麻色が夕焼けに染まって、赤銅に近い色になっている。六月の夕焼けの訓練棟で見た色と同じだった。光で色が変わる。鳴海さんの髪は時間帯を記録している。"}, {"id": "ch07-s02-p015", "type": "text", "text": "風祭さんが鳴海さんの左隣に立った。いつもの配置。半歩後ろ。栗色のショートヘアが夕風に跳ねていた。緑色の目が池の水面を見ている。表情は静かだった。海の日と同じで、声から角が減っている。"}, {"id": "ch07-s02-p016", "type": "text", "text": "天城さんは灯篭をまだ受け取っていなかった。ベンチの端に座り、両手を膝の上で握っている。ポニーテールの黄色いゴムに夕日が当たっている。目を閉じていた。何かを思い出そうとしている、というよりは、何かに備えている顔に見えた。"}, {"id": "ch07-s02-p017", "type": "text", "text": "篠宮さんはベンチには座らず、池の水際から二歩手前に立っていた。灯篭を左手に持ち、右手にいつものメモ帳。ペンが紙の上を滑る音が小さく聞こえる。灯篭流しの記録を取っているのだろう。参加人数、灯篭の数、開始時刻。篠宮さんは行事も記録する。"}, {"id": "ch07-s02-p018", "type": "text", "text": "蝋燭に火が入り始めた。"}, {"id": "ch07-s02-p019", "type": "text", "text": "点火係の人たちが長い蝋燭立てを持って歩き、一つずつ灯篭の中に火を入れていく。和紙を通した光が内側から灯篭を照らし、白い紙が薄い橙色に変わる。火が入るたびに、灯篭の中で蝋燭の炎が揺れ、光が和紙の表面に影を作った。影は風に合わせて動く。"}, {"id": "ch07-s02-p020", "type": "text", "text": "百を超える灯篭に火が入っていく。池のほとりに、小さな光の列が伸びていった。夕焼けの空と、灯篭の灯りが混ざり合う時間帯。太陽の光は赤く、灯篭の光は橙で、二つの光が水面の上で重なっている。"}, {"id": "ch07-s02-p021", "type": "text", "text": "静かだった。風が止まっていた。蝋燭の炎が真っ直ぐに立っている。人々の声が囁きになり、囁きが沈黙になっていく。池の周囲に集まった人々が、それぞれの灯篭を手に、それぞれの名前を書き始めた。"}, {"id": "ch07-s02-p022", "type": "divider", "text": "---"}, {"id": "ch07-s02-p023", "type": "text", "text": "鳴海さんが最初に書いた。"}, {"id": "ch07-s02-p024", "type": "text", "text": "ペンを灯篭の正面の和紙に当てた。背筋を伸ばし、膝の上の灯篭を安定させ、ゆっくりと二文字を書いた。"}, {"id": "ch07-s02-p025", "type": "text", "text": "美弦。"}, {"id": "ch07-s02-p026", "type": "text", "text": "鳴海美弦。六月の夕焼けの帰り道で聞いた名前。鳴海さんの母。共鳴者だった人。八歳の時に亡くなった。声が家の中を満たしていた。声が消えた後、空気がずっと冷たかった。あの温かさを取り戻すために歌い始めた。"}, {"id": "ch07-s02-p027", "type": "text", "text": "鳴海さんの手は震えていなかった。一画ずつ、丁寧に書いた。筆圧が均等で、文字の大きさも揃っている。練習したのかもしれない。あるいは、毎年この行事で同じ名前を書いているのかもしれない。"}, {"id": "ch07-s02-p028", "type": "text", "text": "書き終わった鳴海さんが灯篭を両手で持ち上げた。視線が文字の上に落ちている。穏やかな表情。目が少し細くなっている。口元は微笑みに近いが、口角の上がり方が浅い。笑っているのか、泣くのを堪えているのか、その中間のどこかにいる顔だった。"}, {"id": "ch07-s02-p029", "type": "text", "text": "「いろは」"}, {"id": "ch07-s02-p030", "type": "text", "text": "鳴海さんが風祭さんを呼んだ。声が柔らかかった。"}, {"id": "ch07-s02-p031", "type": "text", "text": "風祭さんが半歩前に出た。手に灯篭を持っていない。受け取った灯篭の正面は白いままだった。何も書いていない。"}, {"id": "ch07-s02-p032", "type": "text", "text": "「ちーちゃんの、一緒に流すよ」"}, {"id": "ch07-s02-p033", "type": "text", "text": "風祭さんの声が低かった。いつもの声よりも一段低い。けれど角がない。輪郭が丸くなった声。"}, {"id": "ch07-s02-p034", "type": "text", "text": "鳴海さんが小さく頷いた。二人で池の水際まで歩いた。風祭さんが鳴海さんの灯篭を受け取り、水面にそっと置いた。灯篭が水の上に浮かんだ。蝋燭の光が和紙を透かして、「美弦」の文字が池の表面に逆さまに映った。"}, {"id": "ch07-s02-p035", "type": "text", "text": "風祭さんが自分の灯篭を、鳴海さんの灯篭の隣に置いた。白紙のまま。名前のない灯篭が、名前のある灯篭に寄り添って浮かんでいる。"}, {"id": "ch07-s02-p036", "type": "text", "text": "風祭さんが何を思って名前を書かなかったのかは、わからない。千歳の隣にいることが風祭さんにとっての追悼なのかもしれないし、書く名前がなかったのかもしれない。あるいは、名前を書くよりも千歳のそばで灯篭を流す方が、風祭さんにとっては正しい形だったのかもしれない。どれが正解かは判断しない。風祭さんが選んだことなので。"}, {"id": "ch07-s02-p037", "type": "text", "text": "二つの灯篭が水面をゆっくりと離岸していった。風がないのに動く。水流か、あるいは灯篭自体の重さの偏りか。どちらにしても、二つの灯篭は並んだまま池の中央に向かって進んでいた。"}, {"id": "ch07-s02-p038", "type": "text", "text": "鳴海さんが水際に立ったまま、灯篭を見ている。カーディガンの裾を左手で握っていた。風祭さんが鳴海さんの左肩に手を置いた。鳴海さんが一度だけ目を閉じて、開いた。"}, {"id": "ch07-s02-p039", "type": "text", "text": "「……ありがとう、いろは」"}, {"id": "ch07-s02-p040", "type": "text", "text": "「うん」"}, {"id": "ch07-s02-p041", "type": "text", "text": "それだけの会話だった。声量は囁きに近い。けれど二人の間にある重力のようなものが、言葉の少なさを埋めていた。"}, {"id": "ch07-s02-p042", "type": "divider", "text": "---"}, {"id": "ch07-s02-p043", "type": "text", "text": "篠宮さんの番だった。"}, {"id": "ch07-s02-p044", "type": "text", "text": "篠宮さんは灯篭に名前を書かなかった。代わりに、灯篭の蝋燭の横に、折り畳まれた紙を一枚添えた。紙を広げると、小さな文字が縦にびっしりと並んでいた。人の名前だった。"}, {"id": "ch07-s02-p045", "type": "text", "text": "「篠宮さん、それは」"}, {"id": "ch07-s02-p046", "type": "text", "text": "「出身不明者の方々の一覧です。今年新たに確認された方々を」"}, {"id": "ch07-s02-p047", "type": "text", "text": "篠宮さんの声は記録室と同じ温度だった。事実を報告する声。"}, {"id": "ch07-s02-p048", "type": "text", "text": "「何人分ですか」"}, {"id": "ch07-s02-p049", "type": "text", "text": "「七十三名です」"}, {"id": "ch07-s02-p050", "type": "text", "text": "七十三。今年だけで。新たに確認された、出身不明者。蝕域に飲まれた土地から来た人々で、その土地自体が消えたために出身地を証明できない人々。あるいは、出身地が消えたことすら記録に残っていない人々。篠宮さんの紙の上に並ぶ七十三の名前は、そういう人たちの名前だった。"}, {"id": "ch07-s02-p051", "type": "text", "text": "「毎年、書き加えています」"}, {"id": "ch07-s02-p052", "type": "text", "text": "篠宮さんがそう言って、紙を灯篭の中に戻した。蝋燭の光が紙を照らし、名前の列が和紙を通して外側からわずかに透けて見えた。"}, {"id": "ch07-s02-p053", "type": "text", "text": "篠宮さんが水際に歩いた。灯篭を両手で持ち、水面に置こうとした——"}, {"id": "ch07-s02-p054", "type": "text", "text": "その時、篠宮さんの右手が震えた。"}, {"id": "ch07-s02-p055", "type": "text", "text": "一瞬だった。灯篭を水面に下ろす直前、右手の指先が小刻みに振動した。灯篭の紙が僅かに波打った。時間にして半秒。それ以下かもしれない。篠宮さんの体の他の部分は動いていなかった。背筋は伸びたまま、顔は前を向いたまま。右手の指先だけが、灯篭を手放す瞬間に震えた。"}, {"id": "ch07-s02-p056", "type": "text", "text": "篠宮さんは灯篭を水面に置いた。手は元に戻った。震えは止まっている。何事もなかったかのようにメモ帳を取り出し、ペンの先を紙に当てた。灯篭流し——灯篭投入時刻、と書いているのが見えた。"}, {"id": "ch07-s02-p057", "type": "text", "text": "気づいた。俺の目はそういうものを拾う。監視哨時代の習慣が残っている。異変を検知し、記録し、報告する。だが——今の震えについて篠宮さんに聞くことは、しなかった。"}, {"id": "ch07-s02-p058", "type": "text", "text": "篠宮さんが震えた理由を推測する材料は足りない。寒さではない。八月の夕方は暑い。緊張でもない。篠宮さんは行事の記録を何度もしている。残る可能性は——わからない。わからないものを無理に言葉にする必要はない。"}, {"id": "ch07-s02-p059", "type": "text", "text": "篠宮さんの灯篭が、七十三人分の名前を載せて池を漂い始めた。紙の向こうで蝋燭の炎が揺れている。"}, {"id": "ch07-s02-p060", "type": "divider", "text": "---"}, {"id": "ch07-s02-p061", "type": "text", "text": "俺の番だった。"}, {"id": "ch07-s02-p062", "type": "text", "text": "灯篭を膝の上に置いた。ベンチに座っている。左手で灯篭を支え、右手にペンを持った。油性ペンの蓋を外した。インクの匂いが鼻に触れた。"}, {"id": "ch07-s02-p063", "type": "text", "text": "灯篭の正面の和紙。白い。何も書かれていない。"}, {"id": "ch07-s02-p064", "type": "text", "text": "ペンの先を紙に近づけた。"}, {"id": "ch07-s02-p065", "type": "text", "text": "名前が、ない。"}, {"id": "ch07-s02-p066", "type": "text", "text": "書くべき名前を探した。頭の中を。記憶の中を。四月にこの島に着いてから、何人もの人と出会った。天城さん、鳴海さん、篠宮さん、風祭さん、すみれ、霜月さん、桐ヶ谷さん。けれどこの人たちは消えていない。今ここにいるか、島のどこかで生きている。灯篭に書く名前は、消えた人の名前だ。"}, {"id": "ch07-s02-p067", "type": "text", "text": "消えた人の名前。俺の記憶の中に、消えた人の名前はない。"}, {"id": "ch07-s02-p068", "type": "text", "text": "ルミエラ島は十年前に蝕域に飲まれた。俺はそこにいた。業務資料にそう記載されている。島には人が住んでいた。父がいたはずだ。母がいたかもしれない。友人がいたかもしれない。隣人がいただろう。名前を呼んだ誰かがいたはずだ。"}, {"id": "ch07-s02-p069", "type": "text", "text": "だが、その名前を一つも思い出せない。"}, {"id": "ch07-s02-p070", "type": "text", "text": "ペンの先が和紙に触れそうで、触れない。名前がない。書く文字がない。一文字目が浮かんでこない。記憶の底を探しても、手応えがない。砂の上に手を突っ込んで何かを掴もうとしている。砂は指の間から落ちていく。残るものがない。"}, {"id": "ch07-s02-p071", "type": "text", "text": "周囲では市民が灯篭を流していた。親の名前、子供の名前、友人の名前。名前を書いた人は灯篭を水面に置き、手を合わせ、あるいは泣き、あるいは黙って見送っている。名前を書くことができる人たちの追悼。"}, {"id": "ch07-s02-p072", "type": "text", "text": "俺にはそれがない。"}, {"id": "ch07-s02-p073", "type": "text", "text": "名前がない。書けない。ペンを持ったまま、和紙の前で手が止まっている。この状態が三十秒以上続いた。隣のベンチに座った老人が灯篭に四つの名前を書き終えて立ち上がった。その間、俺は一文字も書けなかった。"}, {"id": "ch07-s02-p074", "type": "text", "text": "ペンの蓋を閉めた。"}, {"id": "ch07-s02-p075", "type": "text", "text": "灯篭の正面は白いままだった。"}, {"id": "ch07-s02-p076", "type": "text", "text": "立ち上がった。灯篭を持って水際まで歩いた。足元の芝生が夕露で湿っていた。靴の裏に水の感触がある。池の水面は橙色の光で満ちていた。流された灯篭がいくつも浮かんでいる。それぞれの灯篭の中で蝋燭が燃え、名前を載せた光が水面を滑っている。"}, {"id": "ch07-s02-p077", "type": "text", "text": "白紙の灯篭を水面に置いた。"}, {"id": "ch07-s02-p078", "type": "text", "text": "蝋燭の光が和紙を透かすが、文字がないので光だけが通る。他の灯篭には名前があり、名前の影が水面に映っている。俺の灯篭には影がない。光だけの灯篭。名前のない追悼。"}, {"id": "ch07-s02-p079", "type": "text", "text": "——俺が忘れている人がいるなら、その人のために。"}, {"id": "ch07-s02-p080", "type": "text", "text": "声には出さなかった。頭の中で、その一文が浮かんだ。"}, {"id": "ch07-s02-p081", "type": "text", "text": "記憶にない名前は書けない。でも記憶にないということは、いなかったということではない。いたはずだ。ルミエラ島に人が住んでいたなら、俺の隣に誰かがいた。名前を呼ばれたことがあった。名前を呼んだことがあった。その全部を忘れている。忘れていることすら、最近まで知らなかった。"}, {"id": "ch07-s02-p082", "type": "text", "text": "だから白紙でいい。名前を書けなかったのではなく、名前を忘れてしまった全員のために、空白を流す。空白は不在の記録だ。篠宮さんなら、そう言うかもしれない。記録がないことも、一つの記録である、と。"}, {"id": "ch07-s02-p083", "type": "text", "text": "灯篭が池の水面を離れていった。風祭さんの白紙の灯篭とは違う意味で、俺の灯篭にも名前はなかった。風祭さんは選んで書かなかった。俺は書けなかった。同じ白紙でも中身が違う。"}, {"id": "ch07-s02-p084", "type": "text", "text": "水面に浮かぶ灯篭の群れを見た。百を超える灯りが池の上に散らばっている。夕焼けが沈んで、空が紫と紺に変わり始めていた。灯篭の光が水面の主役になりつつある。橙色の点が水の上に散在し、それぞれの灯篭がゆっくりと漂流している。名前を載せた光と、名前のない光が混ざって、池の表面を照らしている。"}, {"id": "ch07-s02-p085", "type": "text", "text": "きれいだった。"}, {"id": "ch07-s02-p086", "type": "text", "text": "きれい、と感じたことに、罪悪感は湧かなかった。追悼の場で美しさを感じることは矛盾するかもしれない。けれど池の上の灯りは事実として美しかった。消えた人の名前が光になって水の上に浮かんでいる。その光景が美しくないわけがない。"}, {"id": "ch07-s02-p087", "type": "divider", "text": "---"}, {"id": "ch07-s02-p088", "type": "text", "text": "天城さんが動いた。"}, {"id": "ch07-s02-p089", "type": "text", "text": "ベンチの端に座っていた天城さんが立ち上がった。灯篭を受付で受け取り、ペンと一緒に持って水際の方に歩いてきた。"}, {"id": "ch07-s02-p090", "type": "text", "text": "池のほとりの芝生の上に、天城さんが腰を下ろした。正座ではなく、両足を横に流す座り方。灯篭を膝の前の地面に置いた。ペンの蓋を右手の親指で弾いて外した。"}, {"id": "ch07-s02-p091", "type": "text", "text": "天城さんの横顔が見えた。"}, {"id": "ch07-s02-p092", "type": "text", "text": "夕焼けが終わりかけていた。空の色は紫が濃くなり、池の水面も暗くなっている。灯篭の灯りが天城さんの顔を下から照らしていた。蝋燭の橙色の光が頬の線を浮かび上がらせ、目の下に柔らかい影を作っている。ポニーテールの影が肩の上に落ちている。"}, {"id": "ch07-s02-p093", "type": "text", "text": "いつもの天城さんの顔ではなかった。笑っていない。怒ってもいない。表情がない、のとも違う。表情が止まっている。何かを覚悟している顔に近い。海で見た時の、水平線の向こうを一瞬見つめた時の目。あの時と似た密度が、今の天城さんの顔にあった。"}, {"id": "ch07-s02-p094", "type": "text", "text": "天城さんがペンを灯篭の和紙に近づけた。"}, {"id": "ch07-s02-p095", "type": "text", "text": "右手がペンを握っている。ペンの先が和紙に触れる直前。"}, {"id": "ch07-s02-p096", "type": "text", "text": "——手が、止まった。"}, {"id": "ch07-s02-p097", "type": "text", "text": "ペンの先が和紙の三ミリ手前で静止した。天城さんの右手が動かない。ペンを持つ指が白くなっている。力が入っている。力が入っているのに、ペンが前に進まない。"}, {"id": "ch07-s02-p098", "type": "text", "text": "天城さんの目が灯篭の和紙を見ている。白い紙を見つめている。口が薄く開いていた。何かを言おうとしているのか、それとも呼吸を忘れていたのか。"}, {"id": "ch07-s02-p099", "type": "text", "text": "ペンが動かない。"}, {"id": "ch07-s02-p100", "type": "text", "text": "天城さんの肩が僅かに震えた。右手の震えではない。肩から腕にかけて、体の芯のどこかから来ている震え。小さい。周囲の人は気づかないだろう。俺が気づいたのは、天城さんの三歩横に立っていたからだ。"}, {"id": "ch07-s02-p101", "type": "text", "text": "蝋燭の光が天城さんの顔を照らしている。琥珀色の目が揺れていた。揺れているのは目ではなく、目の奥にあるもの。太陽の下で金色に輝いていた目が、今は蝋燭の光だけを映して暗い。"}, {"id": "ch07-s02-p102", "type": "text", "text": "名前を、書こうとしている。書こうとして、書けない。"}, {"id": "ch07-s02-p103", "type": "text", "text": "俺の白紙とは違った。俺は名前を思い出せなかった。天城さんは——名前を思い出そうとしている。思い出そうとして、ペンが止まっている。"}, {"id": "ch07-s02-p104", "type": "text", "text": "「天城さん」"}, {"id": "ch07-s02-p105", "type": "text", "text": "声をかけた。声が出たことに自分で少し驚いた。判断より先に口が動いた。海で水をかけられた時と同じ種類の反応。体が先に天城さんの方に向いている。"}, {"id": "ch07-s02-p106", "type": "text", "text": "天城さんがこちらを見た。"}, {"id": "ch07-s02-p107", "type": "text", "text": "目が合った。琥珀色の目が俺を見ている。蝋燭の光がその目の中で揺れていた。口が開いている。何か言おうとしている。声にならない。"}, {"id": "ch07-s02-p108", "type": "text", "text": "それだけだった。天城さんは俺を見て、声を出さず、またゆっくりと灯篭に視線を戻した。"}, {"id": "ch07-s02-p109", "type": "text", "text": "ペンは和紙の三ミリ手前で止まったままだった。"}]}, {"chapter": 7, "chapterTitle": "夏の残響", "scene": 3, "sceneTitle": "思い出せない名前", "wordCount": "約6,100字", "paragraphs": [{"id": "ch07-s03-p001", "type": "text", "text": "沈黙が続いていた。"}, {"id": "ch07-s03-p002", "type": "text", "text": "俺は天城さんの三歩横に立ったまま動かなかった。天城さんは池のほとりの芝生の上に座ったまま動かなかった。灯篭が膝の前の地面にあり、ペンが右手に握られ、ペンの先は和紙の三ミリ手前で止まっている。さっき声をかけた時と何も変わっていない。変わったのは空の色だけだった。紫が紺に沈み始めている。"}, {"id": "ch07-s03-p003", "type": "text", "text": "十秒。二十秒。"}, {"id": "ch07-s03-p004", "type": "text", "text": "天城さんの右手が動いた。ペンの先が和紙に近づいた——そして離れた。元の位置に戻った。三ミリ。さっきと同じ距離。"}, {"id": "ch07-s03-p005", "type": "text", "text": "もう一度。近づいて、離れた。"}, {"id": "ch07-s03-p006", "type": "text", "text": "三度目。ペンの先が和紙に触れた。触れた瞬間、天城さんの指に力が入るのが見えた。ペンを握る指の関節が白い。何かを書き始めようとしている。一画目。"}, {"id": "ch07-s03-p007", "type": "text", "text": "ペンが和紙の上を滑った。三センチほどの短い線。横か縦か、この角度からは見えない。線が一本引かれて、ペンが止まった。二画目が出ない。天城さんの右手が和紙の上で静止していた。"}, {"id": "ch07-s03-p008", "type": "text", "text": "天城さんの口が動いた。声は聞こえなかった。唇が何かの形を作り、閉じた。もう一度開いた。閉じた。音にならない。唇だけが動いている。名前の最初の一文字を、口が探している。"}, {"id": "ch07-s03-p009", "type": "text", "text": "左手が持ち上がった。ポニーテールの根元。黄色のヘアゴム。指先が結び目に触れた。桜の下の弁当の時。喫茶「残響」の時。同じ動作。灯里村の記憶に手が伸びる時、天城さんの指はそこへ行く。"}, {"id": "ch07-s03-p010", "type": "text", "text": "指がヘアゴムの結び目をなぞっている。左薬指の布のリングが目に入った。"}, {"id": "ch07-s03-p011", "type": "text", "text": "布の繊維がほつれていた。前に見た時よりもさらに。喫茶「残響」で見た時はほつれの長さが五ミリほどだった。灯篭流しの蝋燭の光の下で見ると、ほつれは一センチ近くに伸びていた。布の端がめくれ上がって、下の指の皮膚が見えている。布が細くなっている。約束の印。布リングが痩せている。"}, {"id": "ch07-s03-p012", "type": "text", "text": "「あの子……」"}, {"id": "ch07-s03-p013", "type": "text", "text": "天城さんの声が聞こえた。"}, {"id": "ch07-s03-p014", "type": "text", "text": "蝋燭の光の届く範囲だけに落ちる声。灯篭の和紙を透過した橙色の光が天城さんの顔を照らしている。口が開いていた。声が出ていた。けれどそれは俺に向けた声ではなかった。天城さん自身に向けた声。"}, {"id": "ch07-s03-p015", "type": "text", "text": "「あの子の、名前……」"}, {"id": "ch07-s03-p016", "type": "text", "text": "ペンを持つ右手が震え始めた。さっきまでの肩から来る震えとは違う。指先が震えている。ペンの先が和紙の上で小さな円を描くように揺れた。一画目の線の端で止まったまま、次の画に進めない。"}, {"id": "ch07-s03-p017", "type": "text", "text": "天城さんの目が灯篭の和紙を見下ろしていた。琥珀色の瞳が蝋燭の光を受けている。その目の中に何が映っているのかは見えなかった。ただ、目の表面が潤んでいた。涙が溜まり始めていた。"}, {"id": "ch07-s03-p018", "type": "text", "text": "池のほとりの追悼の灯りが水面を照らしている。周囲の市民は自分の灯篭を流し終えて帰り始めていた。人の流れが池の周縁から薄くなっていく。残っているのは蝋燭の灯りと、灯りに照らされた水面と、池のほとりに座っている天城さんと、その三歩横に立っている俺だった。"}, {"id": "ch07-s03-p019", "type": "text", "text": "天城さんの右手からペンが落ちた。"}, {"id": "ch07-s03-p020", "type": "text", "text": "芝生の上に、ペンが音もなく転がった。天城さんの右手はペンを離した形のまま宙に残っていた。指が開いている。力が抜けた手。"}, {"id": "ch07-s03-p021", "type": "text", "text": "何かが灯篭の和紙に落ちた。"}, {"id": "ch07-s03-p022", "type": "text", "text": "丸い水滴。和紙が水を吸い、灯篭の表面に一センチほどの染みが広がった。蝋燭の光がその染みを透かしている。"}, {"id": "ch07-s03-p023", "type": "text", "text": "涙だった。"}, {"id": "ch07-s03-p024", "type": "text", "text": "天城さんの目から、音もなく涙が一滴落ちていた。頬を伝らず、顎の先からまっすぐ灯篭の紙の上に。"}, {"id": "ch07-s03-p025", "type": "text", "text": "もう一滴。灯篭の紙に新しい染みが作られた。二つの染みが隣り合って、蝋燭の光で橙色に光っていた。"}, {"id": "ch07-s03-p026", "type": "text", "text": "天城さんの肩が揺れた。小さく。呼吸の間隔が乱れていた。吸う。止まる。吸う。吐く音が出ない。喉が詰まっている。声を殺そうとしている。泣いていることを音にしないように、喉の筋肉で声を堰き止めている。"}, {"id": "ch07-s03-p027", "type": "text", "text": "天城さんが顔を上げた。"}, {"id": "ch07-s03-p028", "type": "text", "text": "こちらを向いた。"}, {"id": "ch07-s03-p029", "type": "text", "text": "琥珀色の目が俺を見ていた。涙が目の縁に溜まっている。片方の頬に涙の筋が一本通っていた。蝋燭の光が涙の線を照らしている。口が開いている。下顎が細かく動いていた。"}, {"id": "ch07-s03-p030", "type": "text", "text": "「蓮くん」"}, {"id": "ch07-s03-p031", "type": "text", "text": "声が割れていた。いつもの天城さんの声ではなかった。食堂で「蓮くーん！」と呼ぶ声とも、喫茶「残響」で「忘れちゃった！」と笑った声とも違った。喉の奥に何かが詰まったまま出てきた声。二文字。俺の名前。"}, {"id": "ch07-s03-p032", "type": "text", "text": "「あたし……あの子の名前が……」"}, {"id": "ch07-s03-p033", "type": "text", "text": "天城さんの左手がヘアゴムから離れた。膝の上に落ちた。指が布リングのある薬指を握った。布のほつれた部分を親指で撫でている。"}, {"id": "ch07-s03-p034", "type": "text", "text": "「思い出せないの」"}, {"id": "ch07-s03-p035", "type": "text", "text": "声が震えた。最後の「の」で声が途切れた。"}, {"id": "ch07-s03-p036", "type": "text", "text": "喫茶「残響」の時は「忘れちゃった！」だった。笑顔への切り替え時間は二秒。声のトーンは高いところに跳んだ。今回は違った。笑顔に切り替わらない。声のトーンが低いまま留まっている。"}, {"id": "ch07-s03-p037", "type": "text", "text": "桜の下では「忘れちゃいそうで怖い」。喫茶「残響」では「忘れちゃった！」。"}, {"id": "ch07-s03-p038", "type": "text", "text": "今は——「思い出せない」。"}, {"id": "ch07-s03-p039", "type": "text", "text": "進行が、止まらない。"}, {"id": "ch07-s03-p040", "type": "text", "text": "「顔は……まだ、わかる。たぶん。目の色とか……笑った時の……あと、声も……少しだけ覚えてる。海の中から上がってくる時の、笑ってる声」"}, {"id": "ch07-s03-p041", "type": "text", "text": "天城さんが膝の上の手を見ていた。布リングを撫でる親指が止まらない。布の繊維が親指に引っかかるたびに、ほつれが微かに揺れた。"}, {"id": "ch07-s03-p042", "type": "text", "text": "「走るの速くて……あたしいっつも負けてて……畑の畝の間を何回も競争して……」"}, {"id": "ch07-s03-p043", "type": "text", "text": "喫茶「残響」で聞いた話と同じだった。同い年の子。走るのが速い。海に潜るのが上手い。あの時は名前を聞く前に言葉が詰まった。「ああ、なんでもない！ ちょっと忘れちゃった！」。笑顔への切り替え、二秒。"}, {"id": "ch07-s03-p044", "type": "text", "text": "今の天城さんに、あの二秒はなかった。"}, {"id": "ch07-s03-p045", "type": "text", "text": "「名前、なんだったかな……あの子……あ、あの……」"}, {"id": "ch07-s03-p046", "type": "text", "text": "天城さんの口が何かの音を探していた。唇が母音の形を作っている。「あ」の形。「さ」の形。「そ」の形。最初の一文字を喉の奥から引き出そうとしている。手繰っている。何かの端を掴みかけて、指の間からすり抜けていく。"}, {"id": "ch07-s03-p047", "type": "text", "text": "「わかんない……わかんない……」"}, {"id": "ch07-s03-p048", "type": "text", "text": "声が細くなった。喉が絞まっている。目が灯篭の一画目の線を見ていた。一画だけの線。続きが書けない。名前の最初の一文字すら、確かではない。"}, {"id": "ch07-s03-p049", "type": "text", "text": "「でも名前が出てこない。ずっと、書こうとしてた。灯篭にあの子の名前を書きたかった。書くつもりだった。ここに来る前から決めてた。今年はちゃんと書くって。去年は……去年は灯篭流しに来られなかったから。だから今年は、ちゃんとって。でも……」"}, {"id": "ch07-s03-p050", "type": "text", "text": "天城さんの目から涙がこぼれた。今度は音があった。啜る音。鼻の奥から来る小さな音。それを聞いた瞬間、天城さんの顔が崩れた。"}, {"id": "ch07-s03-p051", "type": "text", "text": "堰が切れていた。"}, {"id": "ch07-s03-p052", "type": "text", "text": "声を殺そうとする力が負けた。肩が大きく震えた。両手が顔を覆った。指の隙間から涙がこぼれている。泣き声は——声にならなかった。息が漏れる音だけ。「あ」と「う」の間のような、母音にもならない声が、天城さんの手の向こうから漏れていた。"}, {"id": "ch07-s03-p053", "type": "text", "text": "立ち尽くしていた。"}, {"id": "ch07-s03-p054", "type": "text", "text": "俺は三歩横に立ったまま、天城さんが泣くのを見ていた。何かを言わなければいけない。そう思った。何を。何と言えば。"}, {"id": "ch07-s03-p055", "type": "text", "text": "「忘れたくない。忘れちゃいそう。忘れちゃった。思い出せない」"}, {"id": "ch07-s03-p056", "type": "text", "text": "四つの言葉が体の中に並んでいた。四月から八月までの五ヶ月の間に、天城さんの中で起きたこと。名前が遠ざかっていく。顔も、いつか遠ざかる。声も。天城さんがあの子と呼ぶ人の全てが、天城さんの中から消えていこうとしている。"}, {"id": "ch07-s03-p057", "type": "text", "text": "俺は忘却の先にいる。全部を失った後の場所にいる。失ったものの輪郭を知らない。"}, {"id": "ch07-s03-p058", "type": "text", "text": "天城さんは忘却の途中にいる。失っていく過程にいる。輪郭が薄れていくのを、指の先で感じている。"}, {"id": "ch07-s03-p059", "type": "text", "text": "同じではない。俺の「わからない」と天城さんの「思い出せない」は同じものではない。だから「わかる」とは言えない。わかるとは言えないし、わかってもいない。"}, {"id": "ch07-s03-p060", "type": "text", "text": "けれど、天城さんが泣いている。三歩先で。蝋燭の光の中で。顔を手で覆って、肩を震わせて。声を押し殺して、それでも漏れる音で。灯里村の幼馴染の名前を書けなかった灯篭の前で。"}, {"id": "ch07-s03-p061", "type": "text", "text": "目の奥に熱があった。感覚の名前はわからない。悲しいのか、苦しいのか、それとも別の何かなのか。判断がつかない。ただ、天城さんを見ていると目の奥が熱くなる。鳩尾のあたりが重い。海で水をかけられた時に笑ったのと同じ回路だった。体が先に反応している。"}, {"id": "ch07-s03-p062", "type": "text", "text": "俺の体が動いた。"}, {"id": "ch07-s03-p063", "type": "text", "text": "一歩。二歩。三歩。"}, {"id": "ch07-s03-p064", "type": "text", "text": "天城さんの横に来た。芝生の上に、膝を折って座った。天城さんの灯篭と、俺の膝が並ぶ位置。距離は五十センチ。天城さんの肩の震えが近くなった。"}, {"id": "ch07-s03-p065", "type": "text", "text": "何かを言おうとした。口を開けた。喉に空気が通った。"}, {"id": "ch07-s03-p066", "type": "text", "text": "名前を思い出せなくても。天城さんがその人を大切に思っている気持ちは。消えない。"}, {"id": "ch07-s03-p067", "type": "text", "text": "頭の中にその文が浮かんだ。浮かんで、喉まで来て、唇の手前で止まった。言葉にならなかった。間違っていないはずだった。けれど、今この瞬間にその言葉を組み立てて口から出す力が、俺の中になかった。感情がある。言葉がある。二つを繋ぐ回路が、まだ足りない。"}, {"id": "ch07-s03-p068", "type": "text", "text": "「天城さん」"}, {"id": "ch07-s03-p069", "type": "text", "text": "出たのはそれだけだった。"}, {"id": "ch07-s03-p070", "type": "text", "text": "名前。天城さんの名前。それだけしか出なかった。"}, {"id": "ch07-s03-p071", "type": "text", "text": "天城さんが顔を覆っていた手を少し下ろした。指の隙間から琥珀色の目が見えた。涙で赤くなった目。鼻の先が赤い。口元が歪んでいる。"}, {"id": "ch07-s03-p072", "type": "text", "text": "俺は天城さんの横に座っていた。何も言えずに。座っているだけだった。"}, {"id": "ch07-s03-p073", "type": "text", "text": "それでいいのかはわからなかった。言葉を持っている人間なら、もっと的確な何かを言えたかもしれない。天城さんの痛みに触れる言葉を、選んで差し出せたかもしれない。俺にはそれができない。できないことが、鳩尾の重さを増やした。"}, {"id": "ch07-s03-p074", "type": "text", "text": "蝋燭の光が揺れた。天城さんの灯篭の中の炎が、天城さんの呼吸に合わせて傾いている。距離が近いから空気の流れが届く。"}, {"id": "ch07-s03-p075", "type": "text", "text": "天城さんの肩の震えが、少しずつ小さくなっていった。泣き声の代わりに、呼吸の音が聞こえてくる。吸って、吐いて。間隔が徐々に均等に近づいていく。手が顔から離れた。両手が膝の上に落ちた。涙の跡が両頬に残っている。目の縁がまだ濡れていた。"}, {"id": "ch07-s03-p076", "type": "text", "text": "天城さんが鼻を啜った。袖で目の下を拭いた。"}, {"id": "ch07-s03-p077", "type": "text", "text": "池の水面に灯篭の光が浮かんでいた。百を超える灯篭が暗くなった水の上に散らばり、それぞれの蝋燭が橙色の光を放っている。空はほとんど紺に変わっていた。星はまだ出ていない。灯篭の灯りだけが水面と、水際と、天城さんの顔を照らしていた。"}, {"id": "ch07-s03-p078", "type": "divider", "text": "---"}, {"id": "ch07-s03-p079", "type": "choice_header", "text": "【選択肢】\nA:「……名前を思い出せなくても、天城さんがその人を大切に思っていることは消えない」\nB:「……一緒に思い出そう。手がかりを探して」"}, {"id": "ch07-s03-p080", "type": "divider", "text": "---"}, {"id": "ch07-s03-p081", "type": "text", "text": "【共通】"}, {"id": "ch07-s03-p082", "type": "text", "text": "天城さんが俺を見ていた。涙の跡が頬に残っている。目が腫れている。蝋燭の光が琥珀色の瞳の中で揺れていた。"}, {"id": "ch07-s03-p083", "type": "text", "text": "天城さんの口が開いた。何かを言おうとした。止まった。もう一度開いた。"}, {"id": "ch07-s03-p084", "type": "text", "text": "「……ごめん、変なとこ見せちゃった」"}, {"id": "ch07-s03-p085", "type": "text", "text": "笑おうとしていた。口の端を持ち上げようとしていた。頬の筋肉が動いている。いつもの天城さんの笑顔を作ろうとしている。"}, {"id": "ch07-s03-p086", "type": "text", "text": "できなかった。"}, {"id": "ch07-s03-p087", "type": "text", "text": "口の端は上がった。上がったが、上がりきらなかった。桜の下で一秒で戻した笑顔。喫茶「残響」で二秒で戻した笑顔。あの切り替えが、今は来なかった。口の端が中途半端に持ち上がった状態で止まっている。目が笑っていない。涙の跡がある頬が持ち上がっているが、目の奥にある重さがそのまま残っている。"}, {"id": "ch07-s03-p088", "type": "text", "text": "天城さんの笑顔が、初めて完成しなかった。"}, {"id": "ch07-s03-p089", "type": "text", "text": "「大丈夫。あたし、大丈夫だから」"}, {"id": "ch07-s03-p090", "type": "text", "text": "声も不完全だった。高いところに跳ぼうとして、跳びきれていない。いつもの明るい声の七割ほどの高さで着地している。残りの三割が、さっきの震えた声のまま、声の底に沈んでいた。"}, {"id": "ch07-s03-p091", "type": "text", "text": "「いつものことだし。ちょっと、今日はダメだっただけ。明日にはもう大丈夫」"}, {"id": "ch07-s03-p092", "type": "text", "text": "天城さんが袖でもう一度目を拭いた。拭きながら笑おうとしている。笑おうとしながら目が潤んでいる。同時に起きていた。泣くことと笑うことが交互ではなく重なっていた。"}, {"id": "ch07-s03-p093", "type": "text", "text": "覚えておく。"}, {"id": "ch07-s03-p094", "type": "text", "text": "天城さんが笑顔を完成させられなかったこと。灯篭に名前を書けなかったこと。幼馴染の名前が思い出せなくなっていること。布リングのほつれが一センチに伸びていること。涙が灯篭の紙に二つの染みを作ったこと。"}, {"id": "ch07-s03-p095", "type": "text", "text": "全部。"}, {"id": "ch07-s03-p096", "type": "text", "text": "天城さんが膝の前の灯篭を両手で持ち上げた。紙の表面に一画だけの線と、二つの涙の染みが残っている。名前ではない。名前にならなかった痕跡。"}, {"id": "ch07-s03-p097", "type": "text", "text": "天城さんが立ち上がった。俺も立った。"}, {"id": "ch07-s03-p098", "type": "text", "text": "水際まで歩いた。天城さんが灯篭を水面に置いた。手が震えていた。震えたまま、灯篭を水に預けた。灯篭が池の表面に浮かんだ。蝋燭の光が和紙を透かして水面に反射している。名前のない灯篭。一画だけの線と涙の染みを載せた灯篭。"}, {"id": "ch07-s03-p099", "type": "text", "text": "俺の灯篭はとっくに流していた。名前を書けなかった白紙の灯篭。池の中央付近に漂っているはずだった。"}, {"id": "ch07-s03-p100", "type": "text", "text": "天城さんの灯篭が水面をゆっくりと離岸した。風はなかった。水流か、灯篭の重心の偏りか。灯篭が池の中央に向かって滑っていく。"}, {"id": "ch07-s03-p101", "type": "text", "text": "俺の灯篭が見えた。白紙の灯篭。橙色の光だけが和紙を透過している。池の中央の少し手前で、ほとんど動かずに浮かんでいた。"}, {"id": "ch07-s03-p102", "type": "text", "text": "天城さんの灯篭がそちらに向かっている。直線ではない。緩い弧を描いて、池の中央の方へ。水面の微かな流れに乗って。"}, {"id": "ch07-s03-p103", "type": "text", "text": "二つの灯篭が並んだ。"}, {"id": "ch07-s03-p104", "type": "text", "text": "俺の白紙の灯篭と、天城さんの一画と涙の灯篭。どちらにも名前がない。書けなかった灯篭と、書けなかった灯篭。理由は違う。俺は忘れたことすら知らない。天城さんは忘れていくことを知っている。"}, {"id": "ch07-s03-p105", "type": "text", "text": "違う場所にいて、同じものを持っていなかった。"}, {"id": "ch07-s03-p106", "type": "text", "text": "二つの灯篭が池の上で並んでいた。水面の反射が灯篭の底を照らし、二つの橙色の光が揺れている。空は暗い。星が一つ、東の低い位置に出ていた。"}, {"id": "ch07-s03-p107", "type": "text", "text": "天城さんが池を見ていた。俺も見ていた。"}, {"id": "ch07-s03-p108", "type": "text", "text": "天城さんの横顔を見た。涙の跡は乾きかけていた。蝋燭の光が頬の線を照らしている。目は灯篭の方を向いていた。口元は——閉じていた。笑ってもいない。泣いてもいない。さっきの崩れた表情とも、いつもの完全な笑顔とも違う。何も被せていない顔。"}, {"id": "ch07-s03-p109", "type": "text", "text": "天城さんの顔を見るのは何度目かわからない。けれど、何も被せていない顔を見るのは、これが初めてだった。"}, {"id": "ch07-s03-p110", "type": "text", "text": "天城さんが小さく息を吐いた。夜の空気が二人の間を通り抜けた。八月の夜の、湿った生温い空気。"}, {"id": "ch07-s03-p111", "type": "text", "text": "「……帰ろっか」"}, {"id": "ch07-s03-p112", "type": "text", "text": "声は低かった。いつもの音量の半分もなかった。けれど、「大丈夫」と笑おうとした時の声よりは、安定していた。無理をしていない声。飾っていない声。さっきの「何も被せていない顔」と同じ種類の声だった。"}, {"id": "ch07-s03-p113", "type": "text", "text": "俺は「うん」と答えた。"}, {"id": "ch07-s03-p114", "type": "text", "text": "二つの灯篭が池の上で並んでいた。名前のない灯りが、水面を照らしていた。"}, {"id": "ch07-s03-p115", "type": "text", "text": "他の灯篭には名前がある。千歳の灯篭には「美弦」。雫の灯篭には七十三人分のリスト。それぞれの灯篭が、それぞれの名前を載せて水の上を漂っている。"}, {"id": "ch07-s03-p116", "type": "text", "text": "俺の灯篭と天城さんの灯篭には、名前がない。"}, {"id": "ch07-s03-p117", "type": "text", "text": "池の水面は暗かった。灯篭の橙色の光だけが水面に揺れている。百を超える灯りの中に、二つの名前のない灯りが並んでいる。見分けはつかない。離れた場所からは、他の灯篭と同じに見える。名前があるかないかは、灯篭の近くに行かなければわからない。"}, {"id": "ch07-s03-p118", "type": "text", "text": "けれど俺は知っている。あの二つの灯篭に名前がないことを。一つは白紙で、もう一つは一画と涙で。"}, {"id": "ch07-s03-p119", "type": "text", "text": "忘れない。この池の光景を。名前のない灯りが二つ並んでいることを。"}]}, {"chapter": 7, "chapterTitle": "夏の残響", "scene": 4, "sceneTitle": "蓮さん", "wordCount": "約5,500字", "paragraphs": [{"id": "ch07-s04-p001", "type": "text", "text": "中円公園の出口に、五人が集まっていた。"}, {"id": "ch07-s04-p002", "type": "text", "text": "池のほとりから戻ってきた天城さんと俺。灯篭を流し終えて水際にいた鳴海さんと風祭さん。どこかのベンチでメモ帳を閉じていたらしい篠宮さん。五人の灯篭は全て池の上にある。帰る理由が揃った。"}, {"id": "ch07-s04-p003", "type": "text", "text": "天城さんが俺の半歩前を歩いていた。歩調はいつもより遅い。ポニーテールが揺れない。揺れるほどの速度で歩いていないから。"}, {"id": "ch07-s04-p004", "type": "text", "text": "公園の門を出たところで、天城さんが立ち止まった。"}, {"id": "ch07-s04-p005", "type": "text", "text": "「あたし、弟んとこ寄っていく」"}, {"id": "ch07-s04-p006", "type": "text", "text": "声は低かった。さっきの「帰ろっか」と同じ種類の低さ。飾っていない声。天城さんの弟は外円区出身者の寮にいると聞いた記憶がある。食堂の雑談の中で、一度だけ。"}, {"id": "ch07-s04-p007", "type": "text", "text": "「じゃあね」"}, {"id": "ch07-s04-p008", "type": "text", "text": "天城さんはそれだけ言って、東の道に折れた。振り返らなかった。ポニーテールの先が街灯の光の下を通り過ぎ、暗い道の向こうに消えた。"}, {"id": "ch07-s04-p009", "type": "text", "text": "「気をつけて」"}, {"id": "ch07-s04-p010", "type": "text", "text": "声を出した。届いたかはわからない。天城さんの背中は小さくなっていた。"}, {"id": "ch07-s04-p011", "type": "text", "text": "風祭さんが鳴海さんの肩に手を置いた。「ちーちゃん、あたし先帰るね。明日の朝練あるし」。鳴海さんが「うん、おやすみ、いろは」と応じた。風祭さんが南の道に歩き出す。篠宮さんも「では、わたしも」と頭を下げて、図書館寮の方角へ去った。"}, {"id": "ch07-s04-p012", "type": "text", "text": "四人が散って、俺が残った。"}, {"id": "ch07-s04-p013", "type": "text", "text": "灯籠通りの入口に立っていた。南門から伸びる煉瓦舗装の道。両側に灯籠型の街灯が並んでいる。石の台座の上に木の枠。枠の中に油灯。全て灯っていた。橙色の光が煉瓦の表面を染め、道の上に暖色の帯が伸びている。"}, {"id": "ch07-s04-p014", "type": "text", "text": "四月の着任の日に初めて歩いた道。点灯係が一本ずつ火を入れていくのを見た。七月にも歩いた。残響祭の夜は灯籠に薄紫のガラス笠が被せてあった。今夜は笠がない。通常の油灯。橙色の光だけ。"}, {"id": "ch07-s04-p015", "type": "text", "text": "同じ道だった。同じ灯りだった。"}, {"id": "ch07-s04-p016", "type": "text", "text": "けれど——橙色の色が違って見えた。四月は「嫌ではなかった」。七月は「悪くない」の先に近づいた場所にいた。今は、灯籠の光を見ていると、鳩尾の少し上がゆるむ。その感覚に名前はまだない。"}, {"id": "ch07-s04-p017", "type": "text", "text": "「朝霧さん」"}, {"id": "ch07-s04-p018", "type": "text", "text": "後ろから声が来た。"}, {"id": "ch07-s04-p019", "type": "text", "text": "振り返った。鳴海さんが三歩うしろに立っていた。"}, {"id": "ch07-s04-p020", "type": "text", "text": "白いブラウスに薄桃色のカーディガン。髪の亜麻色が灯籠の光を吸って蜂蜜に近い色に変わっている。四月の灯籠通りで隣を歩いた時も、七月の残響祭の夜も、同じ変化が起きた。灯籠の下の鳴海さんの髪は蜂蜜色になる。"}, {"id": "ch07-s04-p021", "type": "text", "text": "右前髪のリボンが灯りの中で桃色に浮いていた。"}, {"id": "ch07-s04-p022", "type": "text", "text": "「一緒に帰りませんか」"}, {"id": "ch07-s04-p023", "type": "text", "text": "穏やかな声。風祭さんと別れた後の、少し力の抜けた声。共鳴室の後の疲労を含んだ声とは違う。今日は歌っていない。声にかすれがなかった。"}, {"id": "ch07-s04-p024", "type": "text", "text": "「はい」"}, {"id": "ch07-s04-p025", "type": "text", "text": "答えた。鳴海さんが俺の左側に並んだ。灯籠通りを南に歩き始めた。"}, {"id": "ch07-s04-p026", "type": "text", "text": "鳴海さんの歩幅は小さい。残響祭の夜も、夕焼けの訓練棟の帰り道でも、同じだった。俺が歩幅を合わせる。合わせることに、判断がいらなくなっている。四月には意識して速度を落としていた。今は足が勝手に調整していた。"}, {"id": "ch07-s04-p027", "type": "text", "text": "煉瓦を踏む足音が二つ分、夜の空気の中に落ちた。俺の靴底は硬い。鳴海さんの靴底は柔らかい。音の質が違う。硬い音と柔らかい音が交互に重なって、不規則な拍を作っている。"}, {"id": "ch07-s04-p028", "type": "text", "text": "灯籠が一本、二本と後ろに過ぎていった。油灯の光が鳴海さんの髪と肩の上を滑っていく。通り過ぎるたびに影の角度が変わる。"}, {"id": "ch07-s04-p029", "type": "text", "text": "夜風が吹いた。八月の、湿った生温い風。さっき天城さんとの間を通り抜けた風と同じ空気のはずだった。だが温度が違う。天城さんの横を歩いていた時は風の温度を計測する余裕がなかった。今は風が肌に触れている感覚を捉えている。"}, {"id": "ch07-s04-p030", "type": "text", "text": "「今日の灯篭流し……」"}, {"id": "ch07-s04-p031", "type": "text", "text": "鳴海さんの声が、灯籠の光の中に落ちた。"}, {"id": "ch07-s04-p032", "type": "text", "text": "「朝霧さんは、灯篭を空白のまま流していましたね」"}, {"id": "ch07-s04-p033", "type": "text", "text": "見ていたのか。鳴海さんが灯篭を流したのは、俺より先だった。「美弦」と書いた灯篭を風祭さんと一緒に水面に置いた後、池のほとりに立っていた。あの時、俺が白紙の灯篭を流すのを見ていたらしい。"}, {"id": "ch07-s04-p034", "type": "text", "text": "「書く名前がなかったので」"}, {"id": "ch07-s04-p035", "type": "text", "text": "言った。淡々と。事実の報告に近い声。"}, {"id": "ch07-s04-p036", "type": "text", "text": "沈黙が五秒ほどあった。靴音が三歩分。灯籠が一本、通り過ぎた。"}, {"id": "ch07-s04-p037", "type": "text", "text": "「それでも」"}, {"id": "ch07-s04-p038", "type": "text", "text": "鳴海さんの声が少し小さくなった。"}, {"id": "ch07-s04-p039", "type": "text", "text": "「朝霧さんの灯篭には、気持ちが乗っていたと思います」"}, {"id": "ch07-s04-p040", "type": "text", "text": "足が止まりかけた。止まらなかった。歩幅が半歩分だけ短くなっただけだった。"}, {"id": "ch07-s04-p041", "type": "text", "text": "気持ちが乗っていた。"}, {"id": "ch07-s04-p042", "type": "text", "text": "灯篭を流す時に、頭の中で浮かんだ一文。「俺が忘れている人がいるなら、その人のために」。声にはしなかった。誰にも言わなかった。和紙は白紙のまま。名前も言葉も載っていない灯篭。"}, {"id": "ch07-s04-p043", "type": "text", "text": "鳴海さんは灯篭を見ただけだ。白紙の灯篭が水面に浮かぶのを見ただけだ。それなのに、「気持ちが乗っていた」と言った。"}, {"id": "ch07-s04-p044", "type": "text", "text": "名前が書けなくても。言葉にできなくても。乗っている、と。"}, {"id": "ch07-s04-p045", "type": "text", "text": "天城さんの泣いた顔が浮かんだ。あの時、俺は「天城さん」としか言えなかった。名前しか出なかった。伝えたかった言葉があった。喉まで来て、唇の手前で止まった。届いたかわからなかった。"}, {"id": "ch07-s04-p046", "type": "text", "text": "けれど鳴海さんは、白紙の灯篭を見て、「気持ちが乗っていた」と言った。"}, {"id": "ch07-s04-p047", "type": "text", "text": "言葉にできなくても届くものがある。"}, {"id": "ch07-s04-p048", "type": "text", "text": "——そういうことを、今、鳴海さんの声が教えている。"}, {"id": "ch07-s04-p049", "type": "text", "text": "鳩尾の少し上が動いた。共鳴室で歌を聴いた時の温かさと似ている場所。同じ座標。ただし温度が違う。共鳴室の温かさには痛みが混じっていた。今の動きには痛みがない。温かさだけが、静かに広がっている。"}, {"id": "ch07-s04-p050", "type": "text", "text": "「……ありがとうございます」"}, {"id": "ch07-s04-p051", "type": "text", "text": "声が出た。「思います」も「たぶん」もつけなかった。"}, {"id": "ch07-s04-p052", "type": "text", "text": "鳴海さんは何も言わなかった。前を向いて歩いていた。微笑みが横顔の輪郭に見えた。口元の上がり方が浅い。灯篭流しの後に「美弦」の文字を見ていた時の顔に似ていた。笑っているのか、泣くのを堪えているのか、その中間のどこか。"}, {"id": "ch07-s04-p053", "type": "text", "text": "「お母さんの名前を、書いていましたね」"}, {"id": "ch07-s04-p054", "type": "text", "text": "俺が言った。鳴海さんの灯篭に「美弦」の二文字が書かれているのを見た。一画ずつ、丁寧に。"}, {"id": "ch07-s04-p055", "type": "text", "text": "鳴海さんが小さく頷いた。"}, {"id": "ch07-s04-p056", "type": "text", "text": "「お母さんの名前です。鳴海美弦」"}, {"id": "ch07-s04-p057", "type": "text", "text": "声が静かだった。夕焼けの訓練棟で母のことを話してくれた時の、水面の下にあるものが表面のすぐ近くまで上がってきている声。"}, {"id": "ch07-s04-p058", "type": "text", "text": "「灯篭流しは、年に一度だけお母さんに声を届けられる場所なんです。わたしの歌は生きている人にしか届かないから。灯篭に名前を書いて、火を灯して、水に預ける。それがわたしにできる、お母さんへの——歌の代わり」"}, {"id": "ch07-s04-p059", "type": "text", "text": "歌の代わり。鳴海さんにとって歌は母の温かさの再現だと聞いた。共鳴室で歌う時、鳴海さんの声は母の声を作り直している。その声が届く先は、計測器と俺だった。生きている人間には届く。けれど灯篭流しの夜だけ、死んだ人にも——届くと鳴海さんは信じている。"}, {"id": "ch07-s04-p060", "type": "text", "text": "灯籠の灯りが道の先まで続いていた。橙色の光の点列が、暗い道の両側で揺れている。"}, {"id": "ch07-s04-p061", "type": "text", "text": "鳴海さんの右手が首元に上がった。チョーカーはしていない。指先が首の右側に触れ、二秒ほどそこに留まり、離れた。髪を耳にかける動作に流れた。共鳴室の後に見た癖と同じ。今日は歌っていないのに。灯篭に「美弦」と書いた後の、何かの残響なのかもしれない。"}, {"id": "ch07-s04-p062", "type": "text", "text": "「わたしの灯篭の名前を、覚えていてくれたんですね」"}, {"id": "ch07-s04-p063", "type": "text", "text": "「見えました」"}, {"id": "ch07-s04-p064", "type": "text", "text": "「ふふ」"}, {"id": "ch07-s04-p065", "type": "text", "text": "小さな笑い。声を出さない笑い。肩がわずかに揺れただけ。"}, {"id": "ch07-s04-p066", "type": "text", "text": "灯籠通りの中ほどに差しかかった。喫茶「残響」の前を通り過ぎた。磨りガラスの向こうに暖色の光が灯っている。四月に天城さんに連れてこられた店。マスターのコーヒー。「ここが集合場所だって。覚えておく」。あの日と同じ窓、同じ光。"}, {"id": "ch07-s04-p067", "type": "text", "text": "鳴海さんが足を止めた。"}, {"id": "ch07-s04-p068", "type": "text", "text": "俺も止まった。"}, {"id": "ch07-s04-p069", "type": "text", "text": "灯籠の光の下だった。一本の灯籠のすぐ横。石の台座の影が煉瓦の上に短く伸びている。油灯の火が鳴海さんの顔を右斜め上から照らしていた。"}, {"id": "ch07-s04-p070", "type": "text", "text": "鳴海さんがこちらを向いた。"}, {"id": "ch07-s04-p071", "type": "text", "text": "琥珀色の瞳が灯籠の光を受けていた。色が濃い。今日は歌っていないから。薄くなっていない。琥珀の底まで光が通っている。その目が、俺を見ていた。"}, {"id": "ch07-s04-p072", "type": "text", "text": "「朝霧さん」"}, {"id": "ch07-s04-p073", "type": "text", "text": "声が出て、止まった。"}, {"id": "ch07-s04-p074", "type": "text", "text": "鳴海さんの唇が閉じ、もう一度開いた。吸った息が半秒、喉の中に留まった。何かを組み立てている。言葉を。一文字ずつ。"}, {"id": "ch07-s04-p075", "type": "text", "text": "「……いえ」"}, {"id": "ch07-s04-p076", "type": "text", "text": "訂正の「いえ」。"}, {"id": "ch07-s04-p077", "type": "text", "text": "「蓮さん、と呼んでもいいですか」"}, {"id": "ch07-s04-p078", "type": "text", "text": "蓮。"}, {"id": "ch07-s04-p079", "type": "text", "text": "音が耳に触れた。"}, {"id": "ch07-s04-p080", "type": "text", "text": "二文字。「れん」。俺の名前の読み。"}, {"id": "ch07-s04-p081", "type": "text", "text": "「朝霧さん」ではなく、「蓮さん」。苗字から名前に。距離が一段変わる呼び方。"}, {"id": "ch07-s04-p082", "type": "text", "text": "鳩尾の少し上で、何かが止まった。動いていたものが止まったのではない。止まっていたものが、一瞬だけ動かなくなった。静止の質が変わった。空気を含んだ静止から、何かが充填された静止に。"}, {"id": "ch07-s04-p083", "type": "text", "text": "鳴海さんの声はまだ続いていた。"}, {"id": "ch07-s04-p084", "type": "text", "text": "「今日、蓮さんの灯篭を見て……蓮さんのことを、もっと知りたいと思ったんです」"}, {"id": "ch07-s04-p085", "type": "text", "text": "灯籠の光が鳴海さんの顔の右半分を照らしている。左半分は影に沈んでいる。リボンの桃色が光と影の境界線の上にあった。"}, {"id": "ch07-s04-p086", "type": "text", "text": "もっと知りたい。鳴海さんが俺のことを。白紙の灯篭を流した俺のことを。名前を書けなかった俺のことを。"}, {"id": "ch07-s04-p087", "type": "text", "text": "朝霧蓮。その名前は自分で選んだ。記憶を失った後、管理局が仮の名前を提案し、俺がそれを受け入れた。「朝霧」は発見された場所の地名から。「蓮」は——理由を聞いたが覚えていない。誰かが選んだ名前を、俺が自分のものにした。それだけの名前だった。"}, {"id": "ch07-s04-p088", "type": "text", "text": "その名前を、鳴海さんが親しみを込めて呼んでいる。"}, {"id": "ch07-s04-p089", "type": "text", "text": "「蓮さん」。二文字と敬称。距離がある。けれど「朝霧さん」よりも近い。苗字の壁が一つ減った。"}, {"id": "ch07-s04-p090", "type": "text", "text": "「……はい。構いません」"}, {"id": "ch07-s04-p091", "type": "text", "text": "声が出た。声は平坦だった。体の中で起きていることに比べて、声は静かだった。"}, {"id": "ch07-s04-p092", "type": "text", "text": "鳴海さんの顔が変わった。"}, {"id": "ch07-s04-p093", "type": "text", "text": "口が開いた。歯が見えた。目が細くなった。壁の低い笑顔。灯籠通りの分岐で見たもの、共鳴室で見たもの、夕焼けの訓練棟で見たもの。同じ系統の笑顔。だが今回は——もう一段、低い。壁がもう一段下がっている。風祭さんの前でも見せない深さの笑顔かもしれない。わからない。わからないが、鳴海さんの顔の全部が動いていた。口元だけではなく、目も、頬も、眉も。"}, {"id": "ch07-s04-p094", "type": "text", "text": "「蓮さん」"}, {"id": "ch07-s04-p095", "type": "text", "text": "もう一度、鳴海さんが言った。"}, {"id": "ch07-s04-p096", "type": "text", "text": "音を確かめている。自分の声で、その名前を呼ぶ感触を。口の形を。舌の位置を。"}, {"id": "ch07-s04-p097", "type": "text", "text": "「……ふふ、なんだか少し恥ずかしいですね」"}, {"id": "ch07-s04-p098", "type": "text", "text": "笑いが声に混じった。恥ずかしい、と言いながら、笑っていた。声が高い位置にある。いつもの穏やかな声より三度ほど上。学院の宝の声ではなかった。十八歳の、名前を呼び慣れていない人の声だった。"}, {"id": "ch07-s04-p099", "type": "text", "text": "灯籠の光が揺れた。油灯の中で炎が風に傾き、影の角度が変わった。鳴海さんの顔の光と影の境界が動いた。リボンが影の中に沈み、蜂蜜色の髪が光の中に浮いた。"}, {"id": "ch07-s04-p100", "type": "text", "text": "歩き始めた。鳴海さんが半歩先を歩いた。いつもは俺の横だった。半歩前は初めてだった。背中が見える位置。カーディガンの白が灯籠の光を受けて橙色に染まっている。"}, {"id": "ch07-s04-p101", "type": "text", "text": "灯籠通りの南端が近づいていた。道が二つに分かれる場所。南が鳴海さんの寮。南東が俺の官舎。四月から何度も通った分岐。"}, {"id": "ch07-s04-p102", "type": "text", "text": "鳴海さんが立ち止まった。振り返った。"}, {"id": "ch07-s04-p103", "type": "text", "text": "灯籠の光の下。琥珀色の目が俺を見ていた。リボンが夜風にわずかに揺れている。"}, {"id": "ch07-s04-p104", "type": "text", "text": "「おやすみなさい、蓮さん」"}, {"id": "ch07-s04-p105", "type": "text", "text": "三度目。"}, {"id": "ch07-s04-p106", "type": "text", "text": "「蓮さん」が三回、この灯籠通りの中で呼ばれた。一回目は問いかけ。二回目は確認。三回目は——あいさつ。名前を呼ぶことが、特別な行為から日常の行為に移る最初の一歩。"}, {"id": "ch07-s04-p107", "type": "text", "text": "「おやすみなさい、鳴海さん」"}, {"id": "ch07-s04-p108", "type": "text", "text": "返した。鳴海さんの呼び方は変えなかった。「鳴海さん」のまま。変える必要があるとは思わなかった。けれど、俺が「鳴海さん」と呼ぶ時の声が、さっきまでと微かに違っていた。違いの正体がわからない。音量は同じ。音程も同じ。声帯の使い方も変わっていないはずだ。だが何かが変わった。「蓮さん」と呼ばれた後の俺の声は、呼ばれる前の俺の声と、同じではなかった。"}, {"id": "ch07-s04-p109", "type": "text", "text": "鳴海さんが手を小さく振った。夕焼けの訓練棟の帰り道と同じ動作。あの時は角を曲がる直前だった。今も同じ場所だった。同じ角。"}, {"id": "ch07-s04-p110", "type": "text", "text": "鳴海さんの姿が角の向こうに消えた。"}, {"id": "ch07-s04-p111", "type": "text", "text": "灯籠通りに、俺だけが残った。"}, {"id": "ch07-s04-p112", "type": "text", "text": "煉瓦の道の上に立っていた。灯籠の光が等間隔に並んでいる。油灯の炎が夜風に揺れ、道の上の橙色の帯が波打っている。"}, {"id": "ch07-s04-p113", "type": "text", "text": "四月。この道を初めて歩いた。灯籠の光は「嫌ではなかった」。"}, {"id": "ch07-s04-p114", "type": "text", "text": "五月。残響祭の夜、紫のガラス笠の灯りの下を歩いた。「悪くない」の先に近づいていた。"}, {"id": "ch07-s04-p115", "type": "text", "text": "八月。今。"}, {"id": "ch07-s04-p116", "type": "text", "text": "灯籠の灯りを見ていた。同じ石の台座。同じ木の枠。同じ油灯。何も変わっていない。変わったのは俺の方だった。"}, {"id": "ch07-s04-p117", "type": "text", "text": "「蓮さん」の響きが、鳩尾の少し上に残っていた。"}, {"id": "ch07-s04-p118", "type": "text", "text": "鳴海さんの声。共鳴室で聴いた歌声は胸の中央で温かさと痛みを作った。灯籠通りで聴いた「蓮さん」は、もっと浅い場所にある。鳩尾と胸の中央の間。歌声の余韻が残る座標と近い。近いが、同じではない。歌の余韻は徐々に消える。「蓮さん」の響きは消えない。名前を呼ばれた音が、体の中に留まっている。"}, {"id": "ch07-s04-p119", "type": "text", "text": "鐘の音に似ていた。"}, {"id": "ch07-s04-p120", "type": "text", "text": "鐘の余韻は「ならしてないときも、のこっている」とすみれが言った。鳴海さんの声も同じだった。「蓮さん」という音はもう空気の中にはない。鳴海さんはもういない。けれど音の痕跡が体の内側に残っている。鐘の余韻と、鳴海さんの声の余韻が、同じ場所にある。"}, {"id": "ch07-s04-p121", "type": "text", "text": "偶然ではないのかもしれない。"}, {"id": "ch07-s04-p122", "type": "text", "text": "わからない。保留する。"}, {"id": "ch07-s04-p123", "type": "text", "text": "南東の道を歩き始めた。官舎への帰り道。煉瓦の感触が靴底に触れる。四月と同じ。角が丸く、踏むたびにわずかな弾力がある。使い込まれた煉瓦。"}, {"id": "ch07-s04-p124", "type": "text", "text": "覚えておく。灯籠通りの灯りの下で、鳴海さんが「蓮さん」と呼んだこと。三回。問いかけと、確認と、おやすみ。鳴海さんの笑顔の壁がまた一段下がったこと。恥ずかしいと笑った声が高かったこと。"}, {"id": "ch07-s04-p125", "type": "text", "text": "それと——「気持ちが乗っていた」という言葉。名前を書けなくても。言葉にできなくても。届くものがある。鳴海さんがそう言った。"}, {"id": "ch07-s04-p126", "type": "text", "text": "天城さんの泣いた顔を見て、何も言えなかった俺に、その言葉は届いた。"}]}, {"chapter": 7, "chapterTitle": "夏の残響", "scene": 5, "sceneTitle": "ありがとうございます", "wordCount": "約4,100字", "paragraphs": [{"id": "ch07-s05-p001", "type": "text", "text": "南東の道を歩いていた。"}, {"id": "ch07-s05-p002", "type": "text", "text": "煉瓦の舗装が途切れて、石畳に変わる。官舎まであと三分ほどの場所。八月の夜の空気は湿っていて、背中に薄く汗が残っている。灯籠通りの橙色の光はもう後ろにあった。ここまで来ると街灯の間隔が広がり、足元の石が暗い。"}, {"id": "ch07-s05-p003", "type": "text", "text": "前方に、灯りが一つ見えた。"}, {"id": "ch07-s05-p004", "type": "text", "text": "図書館だった。"}, {"id": "ch07-s05-p005", "type": "text", "text": "木の外壁。煉瓦の基礎。緑青の雨樋。何度来たかを数えなくなった建物。二階の小さな窓に、残響灯の青白い光が見えている。閉館は二十時のはずだった。今は——時計を確認する余裕がないが、まだ灯りが灯っている。"}, {"id": "ch07-s05-p006", "type": "text", "text": "足が向いた。"}, {"id": "ch07-s05-p007", "type": "text", "text": "官舎への道を、十歩ほど通り過ぎていた。足が図書館の方に曲がっている。判断があったのか、なかったのか。灯籠通りの帰り道で、鳴海さんの「蓮さん」が鳩尾の上に残っていて、天城さんの泣いた顔が頭の後ろにあって、その間のどこかで——ペンの音が聞きたくなった、のだと思う。"}, {"id": "ch07-s05-p008", "type": "text", "text": "思う。確信ではない。"}, {"id": "ch07-s05-p009", "type": "text", "text": "真鍮の取っ手を引いた。蝶番が鳴った。四月から何度も聞いた音。"}, {"id": "ch07-s05-p010", "type": "text", "text": "受付に人はいなかった。閉館間際だからだろう。一階のランプが半分消えている。階段を上がった。二階の書架の間を抜ける。2-A、2-B、2-C。残響灯の青白い光が通路を照らす。窓が開いていた。夜風が書架の間を通り抜けていく。八月の風。湿気を含んだ温い風が、紙と蜜蝋の匂いを運んでいる。"}, {"id": "ch07-s05-p011", "type": "text", "text": "奥へ。"}, {"id": "ch07-s05-p012", "type": "text", "text": "記録室の扉が、十センチほど開いていた。"}, {"id": "ch07-s05-p013", "type": "text", "text": "かりかり。"}, {"id": "ch07-s05-p014", "type": "text", "text": "ペンの音。途切れない。俺の足音を聞いても止まらない。"}, {"id": "ch07-s05-p015", "type": "text", "text": "扉を開けた。左側を持ち上げるようにして。蝶番は鳴らなかった。"}, {"id": "ch07-s05-p016", "type": "text", "text": "「朝霧さん」"}, {"id": "ch07-s05-p017", "type": "text", "text": "顔を上げずに。声だけ。ペンは動いたまま。いつもの認知。篠宮さんの声は記録室の空気と同じ温度で、壁に届かない音量で、俺の耳にだけ届く。"}, {"id": "ch07-s05-p018", "type": "text", "text": "「こんばんは」"}, {"id": "ch07-s05-p019", "type": "text", "text": "木箱に座った。いつもの木箱。机の角に近い定位置。腰の角度が深くなる。肘がわずかに上がる。体が勝手に収まる。日課の姿勢。"}, {"id": "ch07-s05-p020", "type": "text", "text": "机の上の配置がいつもと違っていた。"}, {"id": "ch07-s05-p021", "type": "text", "text": "清書用の下書きではなかった。篠宮さんの前にメモ帳が三冊、横に並べて開かれている。その横に白い紙が一枚。ペンで表が引かれ、数字が並んでいた。列の見出しが読めた。「灯篭流し参加者数」「灯篭投入数」「点火開始時刻」「終了時刻」。"}, {"id": "ch07-s05-p022", "type": "text", "text": "灯篭流しの記録だった。"}, {"id": "ch07-s05-p023", "type": "text", "text": "篠宮さんのペンが数字の横に注釈を書き加えている。「前年比+12%」。字が小さくて正確だった。"}, {"id": "ch07-s05-p024", "type": "text", "text": "「今日の灯篭流し、参加者数は昨年より12%増加していました」"}, {"id": "ch07-s05-p025", "type": "text", "text": "篠宮さんが言った。顔を上げずに。ペンを止めずに。事実の報告。記録係としての声。いつもの温度。"}, {"id": "ch07-s05-p026", "type": "text", "text": "「多かったんですね」"}, {"id": "ch07-s05-p027", "type": "text", "text": "「はい。池のほとりの芝生に入りきらない人数でした。追加の蝋燭を管理事務所に申請した記録があります」"}, {"id": "ch07-s05-p028", "type": "text", "text": "篠宮さんのペンが紙の上を滑っている。注釈の二行目を書いている。メモ帳の別のページを確認し、数値を転記している。三冊のメモ帳を交互に参照しながら、一つの表にまとめている。篠宮さんの作業の形だった。記録を、記録で整理する。"}, {"id": "ch07-s05-p029", "type": "text", "text": "「篠宮さんも灯篭を流していたね」"}, {"id": "ch07-s05-p030", "type": "text", "text": "言った。池のほとりで見た光景が浮かんだ。篠宮さんが灯篭を水面に置く直前、右手が一瞬震えたこと。その後すぐにメモ帳を取り出して記録に戻ったこと。"}, {"id": "ch07-s05-p031", "type": "text", "text": "篠宮さんのペンが止まった。"}, {"id": "ch07-s05-p032", "type": "text", "text": "一秒。二秒。"}, {"id": "ch07-s05-p033", "type": "text", "text": "ペンが再開した。"}, {"id": "ch07-s05-p034", "type": "text", "text": "「はい。出身不明者の方々の名前を添えました」"}, {"id": "ch07-s05-p035", "type": "text", "text": "声が平坦だった。いつもの篠宮さん。事実の報告。"}, {"id": "ch07-s05-p036", "type": "text", "text": "「名前は知らない人も多いのですが……記録だけは、残っていますから」"}, {"id": "ch07-s05-p037", "type": "text", "text": "最後の部分で、声の音量が下がった。「残っていますから」の「から」が、壁に届かない声よりもさらに手前で止まった。俺と篠宮さんの間の空気だけを振動させる音量。その先の部分——「だから流す」なのか「だから意味がある」なのか——は、篠宮さんの唇の形にならなかった。"}, {"id": "ch07-s05-p038", "type": "text", "text": "篠宮さんのペンの音が続いている。"}, {"id": "ch07-s05-p039", "type": "text", "text": "俺は机の上を見た。清書の下書きはなかった。今日は灯篭流しの記録整理で、清書の作業はない。手持ち無沙汰になる——はずだったが、篠宮さんの横に未整理のメモ帳が二冊、表の左に置いてあった。"}, {"id": "ch07-s05-p040", "type": "text", "text": "「手伝います」"}, {"id": "ch07-s05-p041", "type": "text", "text": "「……はい」"}, {"id": "ch07-s05-p042", "type": "text", "text": "篠宮さんの返事は短かった。メモ帳の一冊を俺の方に滑らせた。俺はペンを取った。インク壺からインクをつけた。篠宮さんのメモ帳を開いて、数字を拾い始めた。参加者のカウント。時刻の記録。篠宮さんが現場で走り書きした数字を、表の形式に読み替える作業。"}, {"id": "ch07-s05-p043", "type": "text", "text": "かりかり。"}, {"id": "ch07-s05-p044", "type": "text", "text": "かりかり。"}, {"id": "ch07-s05-p045", "type": "text", "text": "二つのペンの音が記録室に落ちた。"}, {"id": "ch07-s05-p046", "type": "text", "text": "窓から夜風が入っている。書架の間を通り抜けた風が、記録室の中を撫でていく。紙のめくれる音がした。篠宮さんのメモ帳のページが風に反応して浮き上がりかけた。篠宮さんの左手が素早くページを押さえた。音にならない動作。"}, {"id": "ch07-s05-p047", "type": "text", "text": "二つのペンの音だけが、記録室を満たしている。"}, {"id": "ch07-s05-p048", "type": "text", "text": "夜だった。夜の図書館。夜の記録室。いつもは夕方の作業で、夜にここにいるのは初めてだった。窓の外が暗い。星が見えるかと思ったが、窓が西向きなので星は見えない。代わりに、書架の上の残響灯の光が窓ガラスに反射して、部屋の中に青白い光の層を作っている。"}, {"id": "ch07-s05-p049", "type": "text", "text": "ペンの音。紙の音。夜風の音。それだけ。"}, {"id": "ch07-s05-p050", "type": "text", "text": "静かだった。いつもの記録室と同じ種類の静けさ。ペンの音が二つあるから沈黙ではない。会話がなくても、音が交わされている。雨の日の記録室と似ていた。あの時は雨の音とペンの音が四つ重なっていた。今は夜風の音とペンの音。数が違うだけで、質は同じだった。"}, {"id": "ch07-s05-p051", "type": "text", "text": "静かで、冷たくない場所。"}, {"id": "ch07-s05-p052", "type": "text", "text": "今日一日の重さが、この場所で少し沈殿していくのを感じた。天城さんの涙。鳴海さんの声。灯篭の光。白紙のまま流した灯篭。それらが記録室の空気の中に降りて、沈んで、机の下の暗い場所に溜まっていく。消えたわけではない。ただ、ペンの音が二つある場所に座っていると、持っていられる重さが変わる。"}, {"id": "ch07-s05-p053", "type": "text", "text": "メモ帳の数字を三ページ分、表に転記した。篠宮さんが表の右端に合計の行を書き加えている。ペンが数字を刻む音が規則的だった。"}, {"id": "ch07-s05-p054", "type": "text", "text": "篠宮さんのペンが止まった。"}, {"id": "ch07-s05-p055", "type": "text", "text": "音が一つ減った。"}, {"id": "ch07-s05-p056", "type": "text", "text": "俺のペンも止めた。篠宮さんの方を見た。"}, {"id": "ch07-s05-p057", "type": "text", "text": "篠宮さんの視線は机の上にあった。表でも、メモ帳でもない場所を見ていた。机の木目。あるいは、木目のさらに向こうにある何か。"}, {"id": "ch07-s05-p058", "type": "text", "text": "「……ありがとう、ございます」"}, {"id": "ch07-s05-p059", "type": "text", "text": "声が出た。"}, {"id": "ch07-s05-p060", "type": "text", "text": "小さかった。壁に届かない声よりもさらに小さい。俺の耳に届くぎりぎりの音量。「ありがとう」と「ございます」の間に、息を吸う隙間があった。二つの単語を別々に持ち上げて、一つの文にする作業のようだった。"}, {"id": "ch07-s05-p061", "type": "text", "text": "篠宮さんの瞬きが止まった。"}, {"id": "ch07-s05-p062", "type": "text", "text": "自分の声が聞こえたかのような——自分が発した音に自分で驚いたかのような——瞬きの停止。三秒。四秒。墨色の瞳が動かない。"}, {"id": "ch07-s05-p063", "type": "text", "text": "俺は動かなかった。"}, {"id": "ch07-s05-p064", "type": "text", "text": "篠宮さんがお礼を言った。"}, {"id": "ch07-s05-p065", "type": "text", "text": "お礼を。篠宮さんが。"}, {"id": "ch07-s05-p066", "type": "text", "text": "記録室で何ヶ月も一緒に作業をしてきた。清書を手伝った。メモ帳を拾った。閲覧机の場所を教えてもらった。「では、また明日」を何度も交わした。その間、篠宮さんが俺に「ありがとう」を言ったことは一度もなかった。俺の方は言った。五月のあの夕暮れに、三秒遅れて。篠宮さんの方からは——一度も。"}, {"id": "ch07-s05-p067", "type": "text", "text": "今、言った。"}, {"id": "ch07-s05-p068", "type": "text", "text": "「ありがとうございます」。敬語つき。距離を保ったまま。篠宮さんの語彙における最大限の——丁寧さで、囲われた感謝。"}, {"id": "ch07-s05-p069", "type": "text", "text": "何に対しての「ありがとう」なのか。清書を手伝っていること。灯篭流しの記録整理を手伝ったこと。ここにいること。全部かもしれない。どれでもないかもしれない。篠宮さん自身もわかっていないかもしれない。だから「ありがとうございます」の後に理由がつかなかった。理由のない感謝。"}, {"id": "ch07-s05-p070", "type": "text", "text": "篠宮さんの口が動いた。"}, {"id": "ch07-s05-p071", "type": "text", "text": "「……失礼しました。なんでもありません」"}, {"id": "ch07-s05-p072", "type": "text", "text": "声が戻っていた。平坦な声。いつもの篠宮さんの音量。取り繕いの音。自分が発した言葉を回収しようとしている。メモ帳に手が伸び、ペンを取り直し、紙の上にペン先を置いた。書く体勢。いつもの記録係の姿勢に戻ろうとしている。"}, {"id": "ch07-s05-p073", "type": "text", "text": "けれど、ペン先は紙に触れたまま、動いていなかった。"}, {"id": "ch07-s05-p074", "type": "text", "text": "「いいえ」"}, {"id": "ch07-s05-p075", "type": "text", "text": "俺の声が出た。"}, {"id": "ch07-s05-p076", "type": "text", "text": "「こちらこそ」"}, {"id": "ch07-s05-p077", "type": "text", "text": "声は平坦だった。あの夕暮れの「ありがとう」と同じで——込めたいものがあるのに、込められたかどうかわからない声。でも三秒は遅れなかった。今回は遅れなかった。"}, {"id": "ch07-s05-p078", "type": "text", "text": "篠宮さんの瞬きが入った。一回。長い瞬き。目を閉じている時間が通常より長い。まぶたが上がった時、墨色の瞳が——変わっていなかった。表情の振幅が小さい篠宮さんの、いつも通りの顔。"}, {"id": "ch07-s05-p079", "type": "text", "text": "けれど、ペンが動き始めた。"}, {"id": "ch07-s05-p080", "type": "text", "text": "かりかり。"}, {"id": "ch07-s05-p081", "type": "text", "text": "いつもの音。いつもの間隔。いつもの筆圧。何も変わっていない。"}, {"id": "ch07-s05-p082", "type": "text", "text": "俺もペンを取った。"}, {"id": "ch07-s05-p083", "type": "text", "text": "かりかり。"}, {"id": "ch07-s05-p084", "type": "text", "text": "二つのペンの音が記録室に戻った。夜風が窓から入っている。ページが浮きかけて、篠宮さんの手が押さえる。同じ動作。繰り返し。"}, {"id": "ch07-s05-p085", "type": "text", "text": "メモ帳の最後のページの数字を転記し終えた。表が完成した。篠宮さんが表の上部に「灯篭流し記録　八月十五日」と書き加えた。文字が小さくて正確だった。"}, {"id": "ch07-s05-p086", "type": "text", "text": "立ち上がった。木箱から腰を上げる。"}, {"id": "ch07-s05-p087", "type": "text", "text": "「では、また」"}, {"id": "ch07-s05-p088", "type": "text", "text": "篠宮さんが頷いた。顎が一センチほど下がって、戻る。いつもの頷き。"}, {"id": "ch07-s05-p089", "type": "text", "text": "記録室を出た。書架の間を歩く。階段を降りる。受付の前を通り、図書館の扉を開けた。"}, {"id": "ch07-s05-p090", "type": "text", "text": "外は夜だった。星が出ていた。空気は湿っていたが、図書館の中よりも温度が高い。石畳の上を歩き始めた。"}, {"id": "ch07-s05-p091", "type": "text", "text": "篠宮さんの「ありがとうございます」が耳の中に残っていた。"}, {"id": "ch07-s05-p092", "type": "text", "text": "小さな声。「ありがとう」と「ございます」の間の息継ぎ。自分の言葉に自分で驚いた瞬きの停止。「失礼しました。なんでもありません」と取り繕った後の、動かないペン先。"}, {"id": "ch07-s05-p093", "type": "text", "text": "篠宮さんが感謝を口にしたのは初めてだった。記録室で隣に座る日々の中で、一度もなかった。「朝霧さん」と認知し、「いいえ」と応じ、「閉館です」と告げ、「では、また明日」で締める。その枠の中に「ありがとう」は含まれていなかった。"}, {"id": "ch07-s05-p094", "type": "text", "text": "今日、含まれた。"}, {"id": "ch07-s05-p095", "type": "text", "text": "理由はわからない。灯篭流しの夜だから。夜の図書館に来たから。清書ではなく記録整理を手伝ったから。あるいは——どれでもない何か。篠宮さんの中で、言葉の扉が少しだけ開いた。開いた直後に閉めようとした。「なんでもありません」と。けれど、言葉は出た後だった。"}, {"id": "ch07-s05-p096", "type": "text", "text": "官舎までの石畳を歩いている。"}, {"id": "ch07-s05-p097", "type": "text", "text": "今日一日で、三人の声が俺の中に残った。"}, {"id": "ch07-s05-p098", "type": "text", "text": "天城さんの「思い出せないの」。泣いた顔。崩れた笑顔。名前を書けなかった灯篭。"}, {"id": "ch07-s05-p099", "type": "text", "text": "鳴海さんの「蓮さん」。三回。問いかけと確認とおやすみ。壁がまた一段下がった笑顔。"}, {"id": "ch07-s05-p100", "type": "text", "text": "篠宮さんの「ありがとうございます」。一回。理由はなく、取り繕いの直前に出た、小さな声。"}, {"id": "ch07-s05-p101", "type": "text", "text": "三人の声が、鳩尾の少し上のそれぞれ違う場所に置かれている。天城さんの声は重い場所に。鳴海さんの声は温かい場所に。篠宮さんの声は——静かな場所に。冷たくない静けさの中に。"}, {"id": "ch07-s05-p102", "type": "text", "text": "官舎の扉が見えた。"}, {"id": "ch07-s05-p103", "type": "text", "text": "鍵を回して中に入った。灯りをつけた。机の上に点検記録帳が置いてある。明日の分。"}, {"id": "ch07-s05-p104", "type": "text", "text": "椅子に座った。"}, {"id": "ch07-s05-p105", "type": "text", "text": "耳が、ペンの音を探していた。ここでは聞こえない。管理室と同じだった。図書館を出た後、耳がペンの音を探す。聞こえるはずのない音を。"}, {"id": "ch07-s05-p106", "type": "text", "text": "三度目だった。"}, {"id": "ch07-s05-p107", "type": "text", "text": "覚えておく。夜の図書館で、篠宮さんが「ありがとうございます」と言ったことを。"}]}, {"chapter": 7, "chapterTitle": "夏の残響", "scene": 6, "sceneTitle": "夏の終わりのモノローグ", "wordCount": "約3,900字", "paragraphs": [{"id": "ch07-s06-p001", "type": "text", "text": "点検記録帳を開いた。明日の分。"}, {"id": "ch07-s06-p002", "type": "text", "text": "ペンを取り、インク壺に浸した。記録帳の枠線に沿って、日付を書く。八月十六日。書き終えてペンを置いた。明日の点検項目は朝の巡回で確認すればいい。今やることではない。"}, {"id": "ch07-s06-p003", "type": "text", "text": "椅子の背もたれに体を預けた。"}, {"id": "ch07-s06-p004", "type": "text", "text": "窓が開いている。夜風が入ってくる。八月の夜風。湿気がある。あるが、七月の夜風とは違うものが混じっていた。涼しさではない。涼しさの手前の、何か。温度が下がり始める前の、空気の質の変化。風の中に、夏が終わりかけている何かが含まれている。"}, {"id": "ch07-s06-p005", "type": "text", "text": "時計を見た。二十三時を少し過ぎていた。"}, {"id": "ch07-s06-p006", "type": "text", "text": "図書館を出てからずいぶん経った。帰り道で篠宮さんの声が耳に残っているのを確認し、官舎に入り、椅子に座り、ペンの音を探し、聞こえないことを確認した。それから歯を磨き、着替えた。寝間着のシャツの襟元から夜風が入ってくる。鎖骨の下が冷える。"}, {"id": "ch07-s06-p007", "type": "text", "text": "ペンの音は聞こえない。"}, {"id": "ch07-s06-p008", "type": "text", "text": "官舎は静かだった。管理室と同じ種類の静けさ。ペンの音が一つもない。記録室の静けさとは違う。あちらには二つのペンの音がある。ここには何もない。今は何もない。"}, {"id": "ch07-s06-p009", "type": "text", "text": "椅子から立ち上がり、ベッドに移った。"}, {"id": "ch07-s06-p010", "type": "text", "text": "仰向けになった。天井を見る。白い塗り壁。凹凸が裸電球の影を作っている。見慣れた天井。四月の最初の朝もこの天井を見ていた。五月の残響祭の夜もここで目を閉じた。天井は変わっていない。"}, {"id": "ch07-s06-p011", "type": "text", "text": "窓の外で虫が鳴いている。鈴虫ではない。もっと高い、断続的な音。夏の虫と秋の虫の間にいる何か。夜風と同じだった。季節が切り替わる手前の、境目の音。"}, {"id": "ch07-s06-p012", "type": "text", "text": "掛布団は薄い一枚。八月の夜は暑い日が多かったが、今夜は腕を布団の外に出すとひんやりした。布団の中に腕を戻す。布団が体を包んでいる。"}, {"id": "ch07-s06-p013", "type": "text", "text": "温かい。"}, {"id": "ch07-s06-p014", "type": "text", "text": "四月の朝、俺はこの布団の中で目を覚ました。温かいはずだ、と思った。温かいと感じているのか、温かいはずだと判断しているだけなのか。その境目が曖昧だった。"}, {"id": "ch07-s06-p015", "type": "text", "text": "五月の残響祭の夜、同じ布団の中にいた。温かいと感じている、判断ではなく——そう認識した。あの夜、楽しかったという言葉が体の底から浮かんできた。"}, {"id": "ch07-s06-p016", "type": "text", "text": "今、八月の夜の布団の中にいる。温かい。温かいと思う。判断ではないとわかる。五月の時より、確認の手続きが減っている。温かいものに温かいと反応している。それだけのことになりつつある。"}, {"id": "ch07-s06-p017", "type": "text", "text": "それだけのことが、四月には難しかった。"}, {"id": "ch07-s06-p018", "type": "text", "text": "目を閉じた。"}, {"id": "ch07-s06-p019", "type": "text", "text": "まぶたの裏に、夏が散らばっている。時系列ではない。順番に並んでいない。体のあちこちに蓄積された断片が、勝手に浮かんでは沈む。"}, {"id": "ch07-s06-p020", "type": "text", "text": "足の裏。砂浜の熱さ。七月の太陽が焼いた砂。三センチ下の湿った冷たさ。波が足首を覆った時の水の温度。海水が引く時に砂が流れ出ていく不安定。"}, {"id": "ch07-s06-p021", "type": "text", "text": "顔。水が飛んできた。冷たくて、塩辛くて。口角が上がった。考える前に、体が反応した。天城さんの声。「蓮くん、今笑ってたよ」。笑った。模倣ではなかった。"}, {"id": "ch07-s06-p022", "type": "text", "text": "天城さん。"}, {"id": "ch07-s06-p023", "type": "text", "text": "海の天城さんは眩しかった。日差しの中で輪郭がくっきりしていた。水しぶきを上げて泳ぐ背中。「よかった」の一語。"}, {"id": "ch07-s06-p024", "type": "text", "text": "灯篭流しの天城さんは——。"}, {"id": "ch07-s06-p025", "type": "text", "text": "目の奥が重い。天城さんが泣いた。名前を書けなかった灯篭の前で、涙が和紙に落ちた。笑顔が七割で止まった。あれは四月からの天城さんの中で、初めて笑顔が完成しなかった場面だった。"}, {"id": "ch07-s06-p026", "type": "text", "text": "俺は何も言えなかった。「天城さん」と呼んだだけだった。"}, {"id": "ch07-s06-p027", "type": "text", "text": "天城さんの感覚は、目の奥の少し後ろにある。四月には「眩しい」だった。今は「眩しい」の下に、重いものが加わっている。天城さんが笑うたびに、天城さんが泣いた顔を体が覚えていて、その二つが重なって目の奥を押している。"}, {"id": "ch07-s06-p028", "type": "text", "text": "鳴海さん。"}, {"id": "ch07-s06-p029", "type": "text", "text": "鳩尾の上。灯籠通りで隣を歩いた。「蓮さん」と呼ばれた。三回。一回目は問いかけ。二回目は確認。三回目はおやすみ。鳩尾の少し上に三つの音が並んでいる。"}, {"id": "ch07-s06-p030", "type": "text", "text": "きれいだ、と初めて思った日から、鳴海さんの感覚はずっとこの場所にある。四月は「きれい」だけだった。今は違う。温かさがある。歌を聴いた時の鳩尾の緩み。灯籠通りの帰り道に並んで歩いた時の、歩幅を合わせる足の動き。温かさは、きれいの中から出てきたのか、別の場所から来たのか。区別がつかない。けれど両方ある。"}, {"id": "ch07-s06-p031", "type": "text", "text": "篠宮さん。"}, {"id": "ch07-s06-p032", "type": "text", "text": "耳。ペンの音。閉館間際の記録室。「ありがとうございます」。「ありがとう」と「ございます」の間に息継ぎがあった。あの声は耳の中にまだ残っている。"}, {"id": "ch07-s06-p033", "type": "text", "text": "篠宮さんの感覚は、四月には「静か」だった。静かなことは今も変わっていない。ただ、その静けさの種類が変わった。管理室で一人でいる時の静けさは温度がない。記録室でペンの音が二つある時の静けさには、何かが通っている。冷たくない。そのことが、四月にはわからなかった。"}, {"id": "ch07-s06-p034", "type": "text", "text": "すみれ。"}, {"id": "ch07-s06-p035", "type": "text", "text": "左手の甲。天蓋の間で手を繋がれた夜。すみれの手は冷たかった。温まろうとしない冷たさだった。「このせかいは、いつかおわるよ」。あの言葉が左手の甲の冷たさと一緒に残っている。"}, {"id": "ch07-s06-p036", "type": "text", "text": "すみれの感覚は、四月には「不思議」だった。不思議は今もある。けれどその不思議の下に、鳩尾の奥の重さがある。すみれが「おわり」と言った時の声は、悲しくもなく、怖がってもいなかった。ただ正確だった。正確であることが鳩尾の下を押している。夏が終わることと、世界が終わること。距離は遠いはずなのに、左手の甲の冷たさがその二つを近づけている。"}, {"id": "ch07-s06-p037", "type": "text", "text": "霜月さん。"}, {"id": "ch07-s06-p038", "type": "text", "text": "背中の奥。機構室でコーヒーを差し出された手。「業務中の水分補給だ」。二人分の豆を挽く手間は合理性の外にある。それは知っている。"}, {"id": "ch07-s06-p039", "type": "text", "text": "霜月さんの感覚は、四月には「冷たい」だった。今は「不器用」が一番近い。冷たさの中に、形がおかしいだけの温かさがある。コーヒーの苦味と同じで、最初の一口は冷えるのに、飲み下した後に温度が残る。霜月さんはたぶんそれを知らない。知らないまま、二人分の豆を挽いている。"}, {"id": "ch07-s06-p040", "type": "text", "text": "五人。"}, {"id": "ch07-s06-p041", "type": "text", "text": "体のそれぞれの場所に、それぞれの感覚がある。目の奥。鳩尾の上。耳。左手の甲。背中の奥。四月にはどれも薄かった。人と会って、名前を知って、声を聞いて。感覚を受け取るたびに、少しずつ濃くなっていった。"}, {"id": "ch07-s06-p042", "type": "text", "text": "変わったのだろうか。"}, {"id": "ch07-s06-p043", "type": "text", "text": "この夏、俺は変わったのだろうか。"}, {"id": "ch07-s06-p044", "type": "text", "text": "体に聞いてみる。五月の残響祭の夜にもそうした。あの時は鳩尾の下と目の奥と背中と手に聞いた。今は聞く場所が増えている。耳にも聞かなければいけない。"}, {"id": "ch07-s06-p045", "type": "text", "text": "体は、答えなかった。"}, {"id": "ch07-s06-p046", "type": "text", "text": "「変わった」とも「変わっていない」とも言わない。ただ各部位が淡々と報告している。目の奥には重いものがある。鳩尾の上には温かいものがある。耳にはペンの音の残像がある。左手の甲は冷たさを覚えている。背中の奥にはコーヒーの苦味がある。報告はそれだけだった。"}, {"id": "ch07-s06-p047", "type": "text", "text": "四月と同じかと聞かれたら、同じではない。"}, {"id": "ch07-s06-p048", "type": "text", "text": "布団の温もりを温かいと判断していた四月。海で笑った七月。灯篭流しの八月。体の中に蓄積されたものの量が違う。質も違う。四月の俺には聞く場所が少なかった。今は五か所ある。五か所に別々のものが入っている。入っているものの名前は、まだ全部にはつけられない。"}, {"id": "ch07-s06-p049", "type": "text", "text": "四月の朝、布団から出たくないと思った。そう思うのが正しいから、と理由をつけた。今夜は理由をつけていない。布団が温かいから温かい。それだけでいい。理由がいらなくなったことが、変化なのかもしれない。"}, {"id": "ch07-s06-p050", "type": "text", "text": "分解はしなかった。"}, {"id": "ch07-s06-p051", "type": "text", "text": "残響祭の夜、一日を分解しようとして失敗した。楽しかったという言葉が全体からしか出てこなかった。今回も分解しない。夏の全体が一つの塊になっている。海だけ取り出しても足りない。灯篭だけ取り出しても足りない。笑ったことも、泣けなかったことも、名前を呼ばれたことも、感謝されたことも、手を繋がれたことも。全部が繋がったまま体の中にある。"}, {"id": "ch07-s06-p052", "type": "text", "text": "繋がったままでいい。"}, {"id": "ch07-s06-p053", "type": "text", "text": "五月にはそう思えなかった。分解できないことに戸惑った。今は戸惑わない。体がそういうものだと報告しているから、受領する。"}, {"id": "ch07-s06-p054", "type": "text", "text": "名前がない灯篭を流した。俺の灯篭には何も書かなかった。書く名前がなかった。記憶にない人のために、白紙のまま池に浮かべた。"}, {"id": "ch07-s06-p055", "type": "text", "text": "でも——俺のそばには、名前を呼んでくれる人がいた。"}, {"id": "ch07-s06-p056", "type": "text", "text": "「蓮くん」と天城さんが呼んだ。「蓮さん」と鳴海さんが呼んだ。「朝霧さん」と篠宮さんが呼んだ。「れん」とすみれが呼んだ。「朝霧」と霜月さんが呼んだ。"}, {"id": "ch07-s06-p057", "type": "text", "text": "五つの呼び方。全部俺の名前だった。朝霧蓮。二年前に自分でつけた名前。特別な意味はなかった。朝の霧と、図鑑の花。それだけだった。それだけだったものを、五人がそれぞれの距離で呼んでいる。"}, {"id": "ch07-s06-p058", "type": "text", "text": "灯篭に書く名前はなかった。けれど、呼ばれる名前はあった。"}, {"id": "ch07-s06-p059", "type": "text", "text": "窓の外で、鐘の音が聞こえた。"}, {"id": "ch07-s06-p060", "type": "text", "text": "二十三時の夜鐘。低い一打。昼間の鐘打ちより短く、余韻だけが長い。布団の中に鐘の振動が伝わってくる。胸骨に触れて、指先に抜けていく。四月の最初の朝に聴いた鐘の音と同じだった。心地よかった。懐かしかった。理由はわからなかった。五か月経った今もわからない。わからないまま、鐘の音は俺の体を通り抜けていく。いつもと同じように。四月も五月も六月も七月も八月も、鐘は一日も止まらなかった。俺が変わっても変わらなくても、鐘は鳴る。"}, {"id": "ch07-s06-p061", "type": "text", "text": "余韻が消えた。"}, {"id": "ch07-s06-p062", "type": "text", "text": "虫の音が戻ってきた。夜風が窓から入って、掛布団の端を揺らしている。"}, {"id": "ch07-s06-p063", "type": "text", "text": "秋が来る。"}, {"id": "ch07-s06-p064", "type": "text", "text": "夏の虫と秋の虫の間の声が、夜風に乗っている。砂浜の熱さはもう足の裏にない。灯篭の光はもう池の上にない。けれど体の中には残っている。目の奥に、鳩尾の上に、耳に、左手の甲に、背中の奥に。"}, {"id": "ch07-s06-p065", "type": "text", "text": "目を閉じた。"}, {"id": "ch07-s06-p066", "type": "text", "text": "布団が温かい。温かいと感じている。確認はいらない。"}, {"id": "ch07-s06-p067", "type": "text", "text": "眠りが近づいてくる。意識の輪郭が薄くなっていく。最後に残ったのは、五か所に散らばった夏の痕と、窓から入ってくる少しだけ涼しい夜風だった。"}]}, {"chapter": 8, "chapterTitle": "秋風と距離", "scene": 1, "sceneTitle": "体育祭の風", "wordCount": "約5,500字", "paragraphs": [{"id": "ch08-s01-p001", "type": "text", "text": "夏が終わった。"}, {"id": "ch08-s01-p002", "type": "text", "text": "九月に入って、空が変わった。高くなった。八月の空は重かった。湿った空気が低い位置に溜まり、雲が近く、光が白かった。九月の空はそうではない。雲が高い場所に移動し、その間を風が通っている。風の質が違う。肌に当たる感触に湿り気が減り、代わりに乾いた何かが混じっている。夏の風は体にまとわりつく。秋の風は体を通り抜ける。"}, {"id": "ch08-s01-p003", "type": "text", "text": "運動場に朝日が落ちていた。"}, {"id": "ch08-s01-p004", "type": "text", "text": "聖鐘学院の運動場は中庭の東側にある。教室棟と学生寮の間の、石畳が途切れて土が始まる広い空間。俺が来たのは、五月に拡声器の配線を確認した一回だけだった。"}, {"id": "ch08-s01-p005", "type": "text", "text": "今日は違う。"}, {"id": "ch08-s01-p006", "type": "text", "text": "白線が引かれていた。トラックの楕円形。直線部分は百メートル。コーナーは手前と奥に二つ。白い石灰の線が乾いた土の上に浮いている。トラックの内側にフィールドが区切られ、走幅跳の砂場と、綱引き用の目印が設けてある。"}, {"id": "ch08-s01-p007", "type": "text", "text": "運動場の東端に運営テントが三張り。俺はその一番北のテントの中にいた。長机が一つ、パイプ椅子が三脚。机の上に計時器が二台、記録用紙の束、ボールペンが四本、予備のホイッスルが一つ。計時係と記録集計。鐘守補佐は教職員扱いだから、運営に回される。"}, {"id": "ch08-s01-p008", "type": "text", "text": "午前九時。開会式が終わり、最初の競技が始まっていた。"}, {"id": "ch08-s01-p009", "type": "text", "text": "号砲が鳴った。白い煙が立ち上る。百メートル走。六人の生徒がスタートラインを蹴り、土が跳ね、足音が地面を叩く。"}, {"id": "ch08-s01-p010", "type": "text", "text": "計時器のボタンを押した。俺の役割は記録用紙への転記だった。ゴールの順位と秒数を紙に書く。書き終えたら次の組を待つ。"}, {"id": "ch08-s01-p011", "type": "text", "text": "応援席から歓声が上がった。中庭の西側の階段状の石段に、色分けされた鉢巻――赤、青、黄、緑の四色。クラス対抗。赤が一番うるさい。"}, {"id": "ch08-s01-p012", "type": "text", "text": "タイムを書いた。12秒41。12秒87。13秒05。数字を並べる作業は落ち着く。管理室の計器読みと構造が同じだった。"}, {"id": "ch08-s01-p013", "type": "text", "text": "空を見上げた。"}, {"id": "ch08-s01-p014", "type": "text", "text": "青かった。濃い青ではない。薄い青。白に近づいている部分がある。雲は薄い刷毛で引いたような形をしていて、横に長く伸びている。八月の雲は積乱雲だった。縦に高く盛り上がり、底が灰色だった。九月の雲は横に広い。高さよりも幅がある。その雲の上を、空が遠くまで続いている。"}, {"id": "ch08-s01-p015", "type": "text", "text": "秋だった。"}, {"id": "ch08-s01-p016", "type": "text", "text": "布団の中で「秋が来る」と感じた夜から、二週間ほど過ぎた。予感は当たっていた。空の色が証明していた。"}, {"id": "ch08-s01-p017", "type": "divider", "text": "---"}, {"id": "ch08-s01-p018", "type": "text", "text": "午前の競技が進んだ。走幅跳。障害物リレー。綱引き。玉入れ。俺は記録用紙に数字を書き続けた。距離。順位。得点。"}, {"id": "ch08-s01-p019", "type": "text", "text": "テントの中は日陰だが、風が通る。九月の風。作業着の袖口から入ってきて、脇を抜けていく。汗はかいていない。風が乾いているから。"}, {"id": "ch08-s01-p020", "type": "text", "text": "運動場の向こう側に、応援席が見えた。"}, {"id": "ch08-s01-p021", "type": "text", "text": "赤組の席のあたりに、鳴海さんの亜麻色の髪が見えた。距離がある。百メートル以上。けれど髪の色で判る。鳴海さんの横に、緑色の短い髪が並んでいた。風祭さん。二人は応援席の最上段に座っていた。最上段は石段の一番後ろで、背後に中庭の残響桜の木陰がかかる。日差しの弱い場所。"}, {"id": "ch08-s01-p022", "type": "text", "text": "鳴海さんが手を叩いていた。穏やかな拍手。周囲の歓声の中では音は届かないだろう。けれど手の動きが見えた。ゆっくりと、確実に、手のひらを合わせている。競技の結果に関わらず、走り終えた生徒に向けて拍手を送っているようだった。"}, {"id": "ch08-s01-p023", "type": "text", "text": "風祭さんがその隣で応援旗を振っていた。赤組の旗。布が風にはためいている。旗を振る腕の動きは大きい。けれど体の位置は鳴海さんの横から動かない。旗を振りながら、時折鳴海さんの方を見ている。鳴海さんの顔色を確認しているのだろう。風祭さんの配置はいつも同じだった。千歳のそば。左側の半歩後ろ。海の砂浜でも、灯篭流しの帰り道でも、変わらない。"}, {"id": "ch08-s01-p024", "type": "text", "text": "運営テントの南側にスコアボードが立てられていた。木の板にチョークで数字が書いてある。その前に、篠宮さんが立っていた。"}, {"id": "ch08-s01-p025", "type": "text", "text": "白い長袖のブラウス。記録係。チョークを持って数字を書いている。線の太さが均一で、数字の高さが揃っている。記録室で見ている光景と同じだった。紙がチョークに変わっただけ。篠宮さんの動作の質は、道具が変わっても変わらない。"}, {"id": "ch08-s01-p026", "type": "text", "text": "俺が記録用紙に書いた数字を、伝令の生徒がスコアボードまで運ぶ。同じ数字が、二つの場所に、二人の手で書かれている。"}, {"id": "ch08-s01-p027", "type": "divider", "text": "---"}, {"id": "ch08-s01-p028", "type": "text", "text": "午前の部が終わり、昼休みに入った。"}, {"id": "ch08-s01-p029", "type": "text", "text": "運営テントの中で弁当を広げていると、足音が聞こえた。聞き慣れた足音ではない。軽い。けれど確かな踏み込み。"}, {"id": "ch08-s01-p030", "type": "text", "text": "「蓮さん」"}, {"id": "ch08-s01-p031", "type": "text", "text": "テントの入口から、鳴海さんが顔を覗かせていた。"}, {"id": "ch08-s01-p032", "type": "text", "text": "白いブラウスの上に薄い灰色のカーディガン。応援席で被っていた赤い鉢巻を外して、手に持っていた。亜麻色の髪が九月の風に揺れている。リボンの桃色が日差しの中で淡く見えた。"}, {"id": "ch08-s01-p033", "type": "text", "text": "「差し入れです」"}, {"id": "ch08-s01-p034", "type": "text", "text": "両手で紙袋を差し出した。中にペットボトルの水が二本と、紙に包まれたものが入っていた。"}, {"id": "ch08-s01-p035", "type": "text", "text": "「蓮さん、お昼は持ってきていますか？」"}, {"id": "ch08-s01-p036", "type": "text", "text": "「弁当があります」"}, {"id": "ch08-s01-p037", "type": "text", "text": "「そうですか。でしたら、おやつに。風祭さんが焼いてくれたクッキーです」"}, {"id": "ch08-s01-p038", "type": "text", "text": "紙の包みの中身はクッキーだった。四枚。均等な大きさ。焼き色が揃っている。風祭さんの手作り。"}, {"id": "ch08-s01-p039", "type": "text", "text": "「ありがとうございます」"}, {"id": "ch08-s01-p040", "type": "text", "text": "鳴海さんが微笑んだ。壁の低い笑顔。残響祭の夜に見た微笑みと同じ種類だが、今日のほうが輪郭がはっきりしていた。九月の光は八月より角度が低い。光が顔に当たる位置が変わっていた。鳴海さんの鼻筋の影が少しだけ長い。"}, {"id": "ch08-s01-p041", "type": "text", "text": "「蓮さん」と呼ばれた。"}, {"id": "ch08-s01-p042", "type": "text", "text": "鳩尾の少し上。四月に「きれい」と思った場所。七月に「蓮さん」と三回呼ばれた場所。あの夜ほど強くはないが、小さく動いた。名前を呼ばれて、鳩尾の少し上が反応する。その連動が、前より速くなっていた。呼ばれてから反応するまでの時間が短くなっている。"}, {"id": "ch08-s01-p043", "type": "text", "text": "「午後も頑張ってくださいね」"}, {"id": "ch08-s01-p044", "type": "text", "text": "「はい」"}, {"id": "ch08-s01-p045", "type": "text", "text": "鳴海さんが手を振って、テントを離れた。応援席の方に戻っていく背中を見送った。残響桜の下で風祭さんが待っていた。鳴海さんが何か話しかけ、風祭さんが頷いた。"}, {"id": "ch08-s01-p046", "type": "divider", "text": "---"}, {"id": "ch08-s01-p047", "type": "text", "text": "午後の部。"}, {"id": "ch08-s01-p048", "type": "text", "text": "リレーの順番が近づいていた。クラス対抗リレー。四百メートル。四人一組。体育祭の最終種目。"}, {"id": "ch08-s01-p049", "type": "text", "text": "女子の部のアンカー走者の名前を確認した。記録用紙の名簿に目を落とす。赤組、二年A組。アンカー——天城燈花。"}, {"id": "ch08-s01-p050", "type": "text", "text": "トラックの第四コーナー付近に立っている天城さんが見えた。赤い鉢巻を額に巻き、体操服の半袖から腕が出ている。日焼けした腕。農家育ちの腕。筋肉の線がくっきりしていた。腕だけではない。立ち方に重心がある。両足の間隔が肩幅より少し広く、膝が軽く曲がっている。走る準備のできている体だった。"}, {"id": "ch08-s01-p051", "type": "text", "text": "ポニーテールがいつもより高い位置で結ばれていた。海の日と同じ結び方。首の後ろが見えている。黄色いゴム。あのゴムは——俺の記憶の中では——天城さんの指から離れたことがない。"}, {"id": "ch08-s01-p052", "type": "text", "text": "号砲が鳴った。第一走者がスタートした。"}, {"id": "ch08-s01-p053", "type": "text", "text": "赤組の第一走者は速くなかった。青組と黄組が先行し、赤組は三番手でバトンを渡した。第二走者がコーナーを回る。赤組の第二走者は足が長い。コーナーで一人抜いた。二番手に上がってバトンゾーンに入る。第三走者へ。赤組の第三走者は小柄だが、ピッチが細かい。直線で順位を維持した。青組と並走したまま、最終コーナーを回った。"}, {"id": "ch08-s01-p054", "type": "text", "text": "バトンが天城さんの手に渡った。"}, {"id": "ch08-s01-p055", "type": "text", "text": "天城さんが走り出した。"}, {"id": "ch08-s01-p056", "type": "text", "text": "速かった。"}, {"id": "ch08-s01-p057", "type": "text", "text": "最初の三歩で判った。他の走者と加速が違う。地面を蹴る力が強い。足が地面に接している時間が短く、離れている時間が長い。ストライドが大きい。腕振りは無駄がなく、肘が直角に曲がったまま前後に動く。体の軸がぶれない。体幹が安定している。農作業で鍛えた体。鍬を振り、水を運び、畝を踏みしめてきた足腰。そのまま走りに変換されている。"}, {"id": "ch08-s01-p058", "type": "text", "text": "コーナーを抜けた。青組のアンカーに並んだ。直線に入った。天城さんの足音が聞こえてきた。百メートル先のスタート地点から、土を叩く音が風に乗ってくる。速い。足音の間隔が狭い。"}, {"id": "ch08-s01-p059", "type": "text", "text": "天城さんが前に出た。半身。一歩。二歩。差が開いていく。"}, {"id": "ch08-s01-p060", "type": "text", "text": "ゴールテープが見えた。天城さんの体がテープに向かって伸びた。胸がテープに触れた。切った。"}, {"id": "ch08-s01-p061", "type": "text", "text": "歓声が運動場を満たした。赤組の応援席が揺れている。声が重なって音の壁になっていた。"}, {"id": "ch08-s01-p062", "type": "text", "text": "計時器を確認した。アンカー区間のラップ。59秒38。四百メートルのアンカーとしては速い。"}, {"id": "ch08-s01-p063", "type": "text", "text": "天城さんがゴール地点で立ち止まった。膝に手をついて、二回、大きく息を吐いた。それから顔を上げた。汗が額からこめかみを伝っている。髪が頬に張りついている。体操服の背中が汗で濃い色になっていた。"}, {"id": "ch08-s01-p064", "type": "text", "text": "天城さんが運営テントの方を見た。"}, {"id": "ch08-s01-p065", "type": "text", "text": "俺と目が合った。"}, {"id": "ch08-s01-p066", "type": "text", "text": "百メートルの距離。歓声の中。それでも天城さんは俺の位置を見つけていた。"}, {"id": "ch08-s01-p067", "type": "text", "text": "走ってきた。ゴール後の生徒が集まる場所を通り抜けて、トラックの外に出て、運営テントに向かって走ってきた。もう競技の走りではない。跳ねるような足取り。膝が高く上がっている。"}, {"id": "ch08-s01-p068", "type": "text", "text": "テントの前で止まった。息が荒い。肩が上下している。汗が顎先から落ちた。"}, {"id": "ch08-s01-p069", "type": "text", "text": "「見てた？」"}, {"id": "ch08-s01-p070", "type": "text", "text": "声が弾んでいた。酸素が足りていない。息の合間に言葉を押し込んでいる。"}, {"id": "ch08-s01-p071", "type": "text", "text": "「見てました」"}, {"id": "ch08-s01-p072", "type": "text", "text": "「あたし速かったでしょ！」"}, {"id": "ch08-s01-p073", "type": "text", "text": "笑った。"}, {"id": "ch08-s01-p074", "type": "text", "text": "天城さんの笑顔を見た。汗だくの顔。前髪が額に張りついて、ポニーテールがほどけかけている。黄色いゴムが少しずれていた。けれど顔の中心は笑っていた。口が大きく開いて、白い歯が見えて、目が細くなっている。"}, {"id": "ch08-s01-p075", "type": "text", "text": "七割の笑顔か、十割の笑顔か。"}, {"id": "ch08-s01-p076", "type": "text", "text": "灯篭流しの夜、天城さんの笑顔が完成しなかった。涙が和紙に落ちた後の笑顔は七割で止まった。残りの三割に何があるのか、俺にはまだわからない。"}, {"id": "ch08-s01-p077", "type": "text", "text": "今の笑顔。汗と息と、走りきった体温の中にある笑顔。これは七割か。十割か。"}, {"id": "ch08-s01-p078", "type": "text", "text": "答えは出せなかった。俺にはまだ笑顔の精度を測る基準がない。けれど——目の奥が重くなかった。灯篭流しの夜の天城さんを見た時に目の奥に溜まった重さが、今は来ない。今の天城さんの笑顔を見て感じるのは、重さとは違う何かだった。"}, {"id": "ch08-s01-p079", "type": "text", "text": "「すごかった」"}, {"id": "ch08-s01-p080", "type": "text", "text": "言った。間はなかった。水をかけられて笑った日から、思考を経由しない反応が時々出るようになっていた。「すごかった」は判断を待たずに口から出た。"}, {"id": "ch08-s01-p081", "type": "text", "text": "天城さんの目が少し大きくなった。海で「よかった」と言った時と似た変化だった。"}, {"id": "ch08-s01-p082", "type": "text", "text": "「……えへ。ありがと」"}, {"id": "ch08-s01-p083", "type": "text", "text": "声が低くなった。息が整い始めている。低い声は天城さんの飾っていない声だった。"}, {"id": "ch08-s01-p084", "type": "text", "text": "「一番でした」"}, {"id": "ch08-s01-p085", "type": "text", "text": "「うん、一番。あたし一番だったよ。——ああ、暑い」"}, {"id": "ch08-s01-p086", "type": "text", "text": "天城さんが鉢巻を取って、ポニーテールの結び直しを始めた。黄色いゴムを一度外し、髪をまとめ直して、同じ位置に結んだ。手慣れた動作。三秒で終わった。"}, {"id": "ch08-s01-p087", "type": "text", "text": "「水、もらっていい？」"}, {"id": "ch08-s01-p088", "type": "text", "text": "テントの中のペットボトルを指差した。鳴海さんが持ってきた差し入れの水。"}, {"id": "ch08-s01-p089", "type": "text", "text": "「どうぞ」"}, {"id": "ch08-s01-p090", "type": "text", "text": "天城さんがペットボトルの蓋を開けて、一口飲んだ。喉が動いた。二口、三口。ペットボトルの半分を飲み干して、息をついた。"}, {"id": "ch08-s01-p091", "type": "text", "text": "「ぷは。——生き返った」"}, {"id": "ch08-s01-p092", "type": "text", "text": "九月の風がテントの中を通り抜けて、天城さんの首筋の汗を乾かし始めていた。"}, {"id": "ch08-s01-p093", "type": "text", "text": "「午後の閉会式、あたしもう何も出ないからさ。蓮くんのそばで見てていい？」"}, {"id": "ch08-s01-p094", "type": "text", "text": "「邪魔にならなければ」"}, {"id": "ch08-s01-p095", "type": "text", "text": "「ならないよ。おとなしくしてる。——たぶん」"}, {"id": "ch08-s01-p096", "type": "text", "text": "天城さんが笑った。「たぶん」を付け足す時の声には、自分でも信じていない響きがあった。"}, {"id": "ch08-s01-p097", "type": "divider", "text": "---"}, {"id": "ch08-s01-p098", "type": "text", "text": "閉会式が終わった。"}, {"id": "ch08-s01-p099", "type": "text", "text": "赤組が総合優勝した。天城さんのリレーが決め手だった。赤組の歓声と、それ以外の組の拍手。表彰。トロフィー。校長の挨拶。一連の式典が終わり、生徒たちが運動場から散っていく。"}, {"id": "ch08-s01-p100", "type": "text", "text": "テントの撤収作業を手伝った。パイプ椅子を畳み、長机を倒し、テント布を外す。計時器を箱に入れ、記録用紙を束ねてクリップで留めた。"}, {"id": "ch08-s01-p101", "type": "text", "text": "作業を終えた時、運動場にはほとんど人がいなくなっていた。"}, {"id": "ch08-s01-p102", "type": "text", "text": "トラックの白線が残っている。靴に踏まれて所々が途切れている。砂場の砂が散らばっている。綱引きの綱が撤収場所に積まれている。活気の痕跡。あれだけの声と足音があった場所が、夕方の光の中で静かになっている。"}, {"id": "ch08-s01-p103", "type": "text", "text": "残響桜が見えた。"}, {"id": "ch08-s01-p104", "type": "text", "text": "中庭との境にある大木。五月は薄紫の花をつけ、七月は緑の葉を繁らせていた。今は——葉の先端が色づき始めている。緑の中に、黄色い斑点がまばらに見える。変色は始まったばかりだった。全体の一割にも満たない。けれど確実に、葉の色が変わりつつある。"}, {"id": "ch08-s01-p105", "type": "text", "text": "風が吹いた。"}, {"id": "ch08-s01-p106", "type": "text", "text": "九月の風。乾いた風。体を通り抜ける風。体操服のまま残っていた天城さんの汗を乾かした風と同じ空気。その風が運動場の土の上を渡って、残響桜の葉を揺らしている。"}, {"id": "ch08-s01-p107", "type": "text", "text": "空が高い。太陽の角度が低くなっている。影が長い。"}, {"id": "ch08-s01-p108", "type": "text", "text": "五月前の俺は、体育祭をただの業務として見ていただろう。"}, {"id": "ch08-s01-p109", "type": "text", "text": "計時器のボタンを押す。記録用紙に数字を書く。テントを撤収する。それだけの作業。歓声は騒音で、走る生徒は計測対象で、風は風でしかない。"}, {"id": "ch08-s01-p110", "type": "text", "text": "今日はそうではなかった。"}, {"id": "ch08-s01-p111", "type": "text", "text": "天城さんが走った。速かった。「すごかった」と口から出た。鳴海さんが差し入れを持ってきて「蓮さん」と呼んだ。鳩尾の少し上が動いた。風祭さんが鳴海さんの横で旗を振っていた。篠宮さんがチョークで数字を書いていた。歓声があった。足音があった。白線があった。九月の風があった。"}, {"id": "ch08-s01-p112", "type": "text", "text": "それらが全部、体の中を通り過ぎていった。通り過ぎたものの感触が残っている。腕の中に歓声の振動が残り、目の中に天城さんの走る姿が残り、鳩尾の上に「蓮さん」の音が残っている。"}, {"id": "ch08-s01-p113", "type": "text", "text": "風が頬に当たった。乾いていた。秋の風だった。"}, {"id": "ch08-s01-p114", "type": "text", "text": "夏の風は体にまとわりつく。秋の風は体を通り抜ける。通り抜けた後に、何かを置いていく。夏が置いていったものと、秋が置いていくもの。種類は違う。けれど体の中に蓄積されていくことは同じだった。"}, {"id": "ch08-s01-p115", "type": "text", "text": "運動場を横切って、官舎に向かって歩き出した。白線を踏んだ。石灰が靴底について、三歩先の土に白い跡をつけた。"}, {"id": "ch08-s01-p116", "type": "text", "text": "空が高かった。"}]}, {"chapter": 8, "chapterTitle": "秋風と距離", "scene": 2, "sceneTitle": "燈花", "wordCount": "約5,200字", "paragraphs": [{"id": "ch08-s02-p001", "type": "text", "text": "カウベルが鳴った。"}, {"id": "ch08-s02-p002", "type": "text", "text": "磨りガラスのドアを押すと、油と木の匂いがした。喫茶「残響」。木造の壁。低い天井。裸電球が三つ、等間隔でぶら下がっている。黄色い光が空気の中に溜まっていて、窓の外の夕暮れと混ざっていた。"}, {"id": "ch08-s02-p003", "type": "text", "text": "テーブル席が三つ。全部空いていた。カウンターの奥でマスターの吉岡さんが、グラスを布で拭いている。拭く動作が一定だった。三秒で一周。時計の秒針と同じ速度。"}, {"id": "ch08-s02-p004", "type": "text", "text": "「打ち上げ、二人か」"}, {"id": "ch08-s02-p005", "type": "text", "text": "吉岡さんが言った。グラスから目を離さなかった。"}, {"id": "ch08-s02-p006", "type": "text", "text": "「みんな来られないんだって。ちーちゃんは体調がいまいちで、雫ちゃんは記録整理、いろはちゃんはちーちゃんの看病。すみれちゃんは――うん、すみれちゃんだから」"}, {"id": "ch08-s02-p007", "type": "text", "text": "天城さんが俺の横で指を折りながら説明した。声に不満はなかった。報告の口調。事実を並べている。"}, {"id": "ch08-s02-p008", "type": "text", "text": "「まあいいや。二人でも打ち上げは打ち上げだし！」"}, {"id": "ch08-s02-p009", "type": "text", "text": "天城さんが奥のテーブル席に向かった。壁際の席。油灯がテーブルの上に置かれていて、小さな炎が硝子筒の中で揺れている。天城さんが向かい側の椅子を引いて座った。俺はその正面に座った。"}, {"id": "ch08-s02-p010", "type": "text", "text": "テーブルの上に油灯が一つ。裸電球の黄色い光と、油灯の橙色の光が重なっている。天城さんの顔が二種類の光で照らされていた。額から鼻筋にかけて裸電球の光、顎の下から首にかけて油灯の光。影の色が違う。裸電球の影は灰色で、油灯の影は茶色に近い。"}, {"id": "ch08-s02-p011", "type": "text", "text": "天城さんは体操服から着替えていた。黄色い半袖のシャツとベージュのスカート。ポニーテールは結び直した後のまま、高い位置で揺れている。黄色いゴム。風呂に入って汗を落としてきたのだろう。髪が少しだけ湿っていて、油灯の光を反射していた。"}, {"id": "ch08-s02-p012", "type": "text", "text": "吉岡さんがメニューを置きに来た。木の板に紙が挟んである。"}, {"id": "ch08-s02-p013", "type": "text", "text": "「あたしアイスティー。蓮くんは？」"}, {"id": "ch08-s02-p014", "type": "text", "text": "「コーヒーで」"}, {"id": "ch08-s02-p015", "type": "text", "text": "「ブラック？」"}, {"id": "ch08-s02-p016", "type": "text", "text": "「はい」"}, {"id": "ch08-s02-p017", "type": "text", "text": "「蓮くんっていつもブラックだよね。甘くしないの？」"}, {"id": "ch08-s02-p018", "type": "text", "text": "「甘いのは、あまり」"}, {"id": "ch08-s02-p019", "type": "text", "text": "天城さんが「ふうん」と言って、メニューの紙をめくった。指先がページの端をつまんでいる。左薬指の布リング。ほつれた布が油灯の光の中で糸のように細く見えた。"}, {"id": "ch08-s02-p020", "type": "text", "text": "吉岡さんが注文を受けて、カウンターに戻った。豆を挽く音が店内に響いた。"}, {"id": "ch08-s02-p021", "type": "text", "text": "「ねえ、今日のあたし、ほんとに速かったでしょ」"}, {"id": "ch08-s02-p022", "type": "text", "text": "天城さんが言った。テーブルの上に肘をついて、両手の上に顎を載せている。口が少し開いていた。答えを待つ顔。"}, {"id": "ch08-s02-p023", "type": "text", "text": "「速かったです。59秒38」"}, {"id": "ch08-s02-p024", "type": "text", "text": "「え、ラップまで覚えてるの？」"}, {"id": "ch08-s02-p025", "type": "text", "text": "「計時係だったので」"}, {"id": "ch08-s02-p026", "type": "text", "text": "「あはは、そっか。でもさ、ただの数字で覚えてるわけじゃないでしょ？ 蓮くん、あたしが走ってる時、すごいって言ってくれたじゃん」"}, {"id": "ch08-s02-p027", "type": "text", "text": "言った。間がなかった。天城さんの走りを見て、思考の前に口から出た。「すごかった」は記録用紙の数字とは違う回路から出てきた。"}, {"id": "ch08-s02-p028", "type": "text", "text": "「覚えてます」"}, {"id": "ch08-s02-p029", "type": "text", "text": "「うん」"}, {"id": "ch08-s02-p030", "type": "text", "text": "天城さんが笑った。口が横に広がって、目が細くなる。体育祭の直後にテントで見た笑顔と同じ構造だった。歯が見える。頬の位置が高い。"}, {"id": "ch08-s02-p031", "type": "text", "text": "七割か、十割か。体育祭の時に判断を保留した問い。今もまだ判断がつかない。油灯の光が天城さんの目の中に映り込んでいた。琥珀色の虹彩に橙色の小さな点が二つ。"}, {"id": "ch08-s02-p032", "type": "text", "text": "吉岡さんがアイスティーとコーヒーを持ってきた。グラスの氷が音を立てた。天城さんがストローで一口飲んだ。"}, {"id": "ch08-s02-p033", "type": "text", "text": "「あたしね、走るの好きなんだ」"}, {"id": "ch08-s02-p034", "type": "text", "text": "天城さんがグラスを置いた。ストローの先に唇の跡が残っていた。"}, {"id": "ch08-s02-p035", "type": "text", "text": "「小さい頃からずっと。畑の畝の間を走り回って、お父さんに怒られてた。苗踏むなーって」"}, {"id": "ch08-s02-p036", "type": "text", "text": "笑った。畑の話をする時の天城さんの声は、いつもより低い。地面に近い声。土の匂いがしそうな声。"}, {"id": "ch08-s02-p037", "type": "text", "text": "「走ってると、頭の中が空っぽになるんだよね。余計なこと考えなくて済むっていうか。足の裏と地面のことだけでいいっていうか」"}, {"id": "ch08-s02-p038", "type": "text", "text": "天城さんの指がグラスの表面をなぞっていた。結露の水滴が指の軌跡に沿って流れている。"}, {"id": "ch08-s02-p039", "type": "text", "text": "「今日、最後のコーナー回った時、あたし何も考えてなかった。前にいる青組の子の背中だけ見てて、追い抜くことだけ考えてて。足が勝手に動いてた」"}, {"id": "ch08-s02-p040", "type": "text", "text": "「思考の前に体が動く」"}, {"id": "ch08-s02-p041", "type": "text", "text": "俺が言った。天城さんが顔を上げた。"}, {"id": "ch08-s02-p042", "type": "text", "text": "「そう、それ。蓮くん、わかるの？」"}, {"id": "ch08-s02-p043", "type": "text", "text": "わかる。海で水をかけられた時に笑った。すごかったと言った。三歩を詰めて座った。全部、思考より先に体が動いた。"}, {"id": "ch08-s02-p044", "type": "text", "text": "「少し」"}, {"id": "ch08-s02-p045", "type": "text", "text": "「少し、か。蓮くんの『少し』って、だいたい『けっこう』だよね」"}, {"id": "ch08-s02-p046", "type": "text", "text": "天城さんがストローをくわえたまま笑った。目がこちらを見ている。黄褐色の瞳。油灯の光で金に近い色に見えていた。"}, {"id": "ch08-s02-p047", "type": "text", "text": "沈黙があった。長くはない。吉岡さんがカウンターでグラスを棚に戻す音。豆を挽く音が止んで、店内が静かになっていた。"}, {"id": "ch08-s02-p048", "type": "text", "text": "天城さんが何かを言おうとした。口が開いて、閉じた。もう一度開いた。"}, {"id": "ch08-s02-p049", "type": "text", "text": "「ねえ、蓮くん」"}, {"id": "ch08-s02-p050", "type": "text", "text": "声のトーンが変わった。さっきまでの弾んだ声から、少し落ち着いた声に。低くなったのではない。音量が小さくなった。"}, {"id": "ch08-s02-p051", "type": "text", "text": "「蓮くんってさ、いつまであたしのこと『天城さん』って呼ぶの？」"}, {"id": "ch08-s02-p052", "type": "text", "text": "油灯の炎が揺れた。店のどこかから風が入ったのだろう。炎が傾いて、天城さんの顔の影が動いた。"}, {"id": "ch08-s02-p053", "type": "text", "text": "「堅苦しいよ」"}, {"id": "ch08-s02-p054", "type": "text", "text": "天城さんの口調は軽かった。冗談のように聞こえた。けれど目が笑っていなかった。目はまっすぐ俺を見ていた。黄褐色の瞳の中に、油灯の炎が映っていた。"}, {"id": "ch08-s02-p055", "type": "text", "text": "「あたしは最初から蓮くんって呼んでるのにさ。蓮くんだけずっと天城さん。みんなのこともさん付けだけど、あたしのことも——ずっとそう」"}, {"id": "ch08-s02-p056", "type": "text", "text": "天城さんの指がグラスの縁を回っている。円を描く動き。一周、二周。"}, {"id": "ch08-s02-p057", "type": "text", "text": "「ちーちゃんのことは鳴海さん、雫ちゃんのことは篠宮さん、氷華さんのことは霜月さん。全員さん付け。それはわかる。蓮くんはそういう人だから」"}, {"id": "ch08-s02-p058", "type": "text", "text": "天城さんの声が途切れた。二秒。"}, {"id": "ch08-s02-p059", "type": "text", "text": "「でもさ」"}, {"id": "ch08-s02-p060", "type": "text", "text": "「あたしと蓮くんの距離って、もう『天城さん』じゃなくない？」"}, {"id": "ch08-s02-p061", "type": "text", "text": "天城さんの目が俺を見ていた。油灯の光が揺れている。天城さんの表情は——笑ってもいない。怒ってもいない。灯篭流しの夜の最後に見た、何も被せていない顔に近かった。"}, {"id": "ch08-s02-p062", "type": "text", "text": "体の中で何かが引っかかった。"}, {"id": "ch08-s02-p063", "type": "text", "text": "天城さんと呼ぶ。四月から呼んでいる。天城さん。三文字の苗字と敬称。それが天城さんとの距離を表していた。食堂で一方的に話しかけてきた人。「残響」に連れてきてくれた人。手料理を官舎まで届けてくれる人。桜の下で「忘れちゃいそうで怖い」と言った人。リレーのゴールの後に真っ先に走ってきた人。灯篭流しの夜に泣いた人。"}, {"id": "ch08-s02-p064", "type": "text", "text": "全部、天城さんだった。天城さんと呼ぶたびに、その距離の中に収まっていた。苗字で呼ぶことは壁ではない。窓だった。窓越しに見ている。見えているけれど、触れていない。"}, {"id": "ch08-s02-p065", "type": "text", "text": "天城さんの名前は燈花。"}, {"id": "ch08-s02-p066", "type": "text", "text": "知っている。四月から知っている。燈花という名前を、口にしたことがない。"}, {"id": "ch08-s02-p067", "type": "text", "text": "口の中で音を作ってみた。声にはならなかった。舌の位置を確認する。「と」の子音。舌先が上の歯の裏に触れる。「う」で舌が引っ込む。「か」で喉の奥が閉じる。三つの音。短い名前。"}, {"id": "ch08-s02-p068", "type": "text", "text": "天城さんが待っていた。グラスを回す指が止まっている。テーブルの向こう側で、まっすぐこちらを見ている。"}, {"id": "ch08-s02-p069", "type": "text", "text": "「……呼んでいいんですか」"}, {"id": "ch08-s02-p070", "type": "text", "text": "「いいから言ってるんだよ」"}, {"id": "ch08-s02-p071", "type": "text", "text": "天城さんの声がわずかに高くなった。不機嫌ではない。急かしている。けれどその急かし方に、力が入りすぎていた。指がグラスを握っている。関節が白い。"}, {"id": "ch08-s02-p072", "type": "text", "text": "天城さんは——待っている。ただ名前を呼ばれることを。"}, {"id": "ch08-s02-p073", "type": "text", "text": "俺の中で、何かが移動した。場所はわからない。胸の中央よりやや上。鳩尾ではない。鳩尾は鳴海さんに呼応する場所だった。今動いているのは、もう少し上。肋骨の内側のあたり。目の奥にあった重さとも違う。"}, {"id": "ch08-s02-p074", "type": "text", "text": "口を開けた。"}, {"id": "ch08-s02-p075", "type": "text", "text": "喉に空気を通した。"}, {"id": "ch08-s02-p076", "type": "text", "text": "「——燈花」"}, {"id": "ch08-s02-p077", "type": "text", "text": "声が出た。"}, {"id": "ch08-s02-p078", "type": "text", "text": "二文字。短い音。「と」が舌先から離れて、「うか」が喉の奥から押し出された。その音が唇を通って、テーブルの上の油灯の横を抜けて、燈花の耳に届いた。"}, {"id": "ch08-s02-p079", "type": "text", "text": "自分の声が自分に聞こえた。低い声だった。いつもの声と周波数が違った。敬語を外した時の声に近い。力んでいない。けれど軽くもない。何かの重さを含んだ二文字。"}, {"id": "ch08-s02-p080", "type": "text", "text": "燈花の顔が止まった。"}, {"id": "ch08-s02-p081", "type": "text", "text": "一秒。"}, {"id": "ch08-s02-p082", "type": "text", "text": "表情が凍結していた。目が開いたまま動かない。口が半開きのまま固定されている。黄褐色の瞳の中で油灯の炎が揺れていた。体が動いていない。呼吸すら止まっているように見えた。"}, {"id": "ch08-s02-p083", "type": "text", "text": "灯篭流しの夜に見た「止まる」とは違った。あの夜の止まり方は、笑顔を作ろうとして途中で固まるものだった。今の止まり方は——何かを受け取って、処理が追いついていない。"}, {"id": "ch08-s02-p084", "type": "text", "text": "二秒目。"}, {"id": "ch08-s02-p085", "type": "text", "text": "燈花の目の縁が赤くなった。泣くのか、と思った。"}, {"id": "ch08-s02-p086", "type": "text", "text": "三秒目。"}, {"id": "ch08-s02-p087", "type": "text", "text": "泣かなかった。"}, {"id": "ch08-s02-p088", "type": "text", "text": "燈花の顔が動いた。口の端が持ち上がった。頬が上がった。目が細くなった。歯が見えた。顔の全部が同時に動いた。どこかが遅れることなく、どこかが先行することなく、顔の筋肉が一斉に笑顔の位置に移動した。"}, {"id": "ch08-s02-p089", "type": "text", "text": "「うん！」"}, {"id": "ch08-s02-p090", "type": "text", "text": "声が高かった。食堂で「蓮くーん！」と呼ぶ時の音域。弾んでいた。空気を叩くような声。"}, {"id": "ch08-s02-p091", "type": "text", "text": "「そうそう、それでいいの！ 燈花でいいの！」"}, {"id": "ch08-s02-p092", "type": "text", "text": "燈花がテーブルに身を乗り出した。椅子の脚が床で鳴った。油灯が揺れた。"}, {"id": "ch08-s02-p093", "type": "text", "text": "燈花の笑顔を見ていた。テントで見た笑顔。七割か十割か、判断を保留した問い。"}, {"id": "ch08-s02-p094", "type": "text", "text": "今の笑顔は——。"}, {"id": "ch08-s02-p095", "type": "text", "text": "頬が高い位置まで上がっている。目が細い。歯が見えている。これまで見た笑顔と構造は同じだった。けれど何かが違う。差異はどこにあるのか。口の開き方か。目の細まり方か。"}, {"id": "ch08-s02-p096", "type": "text", "text": "違った。目の奥だった。"}, {"id": "ch08-s02-p097", "type": "text", "text": "灯篭流しの夜、笑顔が完成しなかった時、目の奥に重さがあった。体育祭の時、七割か十割かわからなかった時、目の奥を見る余裕がなかった。"}, {"id": "ch08-s02-p098", "type": "text", "text": "今、目の奥を見ている。油灯の光がある。黄褐色の虹彩の奥に、光が通っている。重さがない。影がない。奥まで見通せる。"}, {"id": "ch08-s02-p099", "type": "text", "text": "これが十割なのかはわからない。俺にはまだ笑顔の精度を測る基準がない。けれど——灯篭流しの夜の七割の笑顔とは違う。あの時になかったものが、今はある。"}, {"id": "ch08-s02-p100", "type": "text", "text": "肋骨の内側が温かかった。"}, {"id": "ch08-s02-p101", "type": "text", "text": "熱ではない。体育祭の後に体を通り抜けた秋の風とも違う。内側から来ている。外からの刺激に対する反応ではない。燈花の名前を呼んで、燈花が笑って、その笑顔を見て、体の内側に生まれた温度。"}, {"id": "ch08-s02-p102", "type": "text", "text": "五月に俺が感じ始めたものは「模倣」だった。人間の感情を見て、それを体の中で再現しようとする試み。鳴海さんの歌を聴いて安らぐ。天城さんの料理を食べて安心する。篠宮さんのペンの音を聞いて落ち着く。全部、外からの入力に対する応答だった。入力があって、体の中で何かが動いて、それを「感情」と呼んでいいのか判断がつかない——そういう構造。"}, {"id": "ch08-s02-p103", "type": "text", "text": "今の温かさは、違った。"}, {"id": "ch08-s02-p104", "type": "text", "text": "燈花の名前を呼んだのは俺だった。燈花が呼べと言ったから呼んだ——それは事実だけれど、口を開けたのは俺で、声を出したのも俺で、「燈花」という音を選んだのも俺だった。入力に対する応答ではない。俺の側から出ていった二文字。その二文字が燈花に届いて、燈花が笑って、その笑顔を見た時に肋骨の内側が温かくなった。"}, {"id": "ch08-s02-p105", "type": "text", "text": "この温かさは——模倣ではない。"}, {"id": "ch08-s02-p106", "type": "text", "text": "たぶん。"}, {"id": "ch08-s02-p107", "type": "text", "text": "まだ「たぶん」がつく。確信にはまだ距離がある。けれど灯篭流しの夜の鳩尾の重さとも、海で笑った時の不意打ちとも違う。名前を呼ぶという行為から始まった温度。俺から始まった回路。"}, {"id": "ch08-s02-p108", "type": "text", "text": "「蓮くん、顔、変」"}, {"id": "ch08-s02-p109", "type": "text", "text": "燈花が言った。笑っている。さっきの笑顔がまだ続いていた。"}, {"id": "ch08-s02-p110", "type": "text", "text": "「変ですか」"}, {"id": "ch08-s02-p111", "type": "text", "text": "「変。なんかちょっと固まってる。あたしが名前呼んでって言ったのがそんなに大事だった？」"}, {"id": "ch08-s02-p112", "type": "text", "text": "大事だった。大事かどうかの判断は、まだ正確にはできない。けれど肋骨の内側の温かさが残っている。この温度は消えていない。"}, {"id": "ch08-s02-p113", "type": "text", "text": "「……大事、だったと思います」"}, {"id": "ch08-s02-p114", "type": "text", "text": "「思いますって。もう、蓮くんの『思います』は信じるよ。蓮くんが思いますって言う時は、だいたい本当だから」"}, {"id": "ch08-s02-p115", "type": "text", "text": "燈花がアイスティーを飲んだ。ストローをくわえたまま、目がこちらを見ている。目が笑っていた。口元はストローで隠れているけれど、目が笑っている。"}, {"id": "ch08-s02-p116", "type": "text", "text": "油灯の炎が安定していた。風が止んだのだろう。硝子筒の中の小さな火がまっすぐ立っている。その光が燈花の顔を照らしていた。"}, {"id": "ch08-s02-p117", "type": "text", "text": "「よし」"}, {"id": "ch08-s02-p118", "type": "text", "text": "燈花がグラスを置いた。両手をテーブルの上でぱんと叩いた。"}, {"id": "ch08-s02-p119", "type": "text", "text": "「じゃ、打ち上げの続き！ あたしケーキ頼むね。蓮くんは？ ああそっか、甘いの苦手なんだっけ。じゃあサンドイッチにする？ マスター、メニュー！」"}, {"id": "ch08-s02-p120", "type": "text", "text": "燈花が吉岡さんに向かって声を上げた。カウンターの奥で吉岡さんが「はいはい」と答えた。グラスを拭く手は止めなかった。"}, {"id": "ch08-s02-p121", "type": "text", "text": "燈花の声が店内に広がった。テーブル三つ分の狭い空間を満たした。裸電球の光と油灯の光の中に、声が反射している。"}, {"id": "ch08-s02-p122", "type": "text", "text": "コーヒーカップを持ち上げた。ブラックコーヒーの表面に裸電球の光が映っている。一口飲んだ。苦い。いつもの味。"}, {"id": "ch08-s02-p123", "type": "text", "text": "肋骨の内側の温かさは、まだ残っていた。コーヒーの苦さの向こう側にある。消えていない。"}, {"id": "ch08-s02-p124", "type": "text", "text": "燈花がメニューの紙を広げて、何かを指差している。「これとこれ、どっちがいいと思う？」と聞いている。俺は「どちらでも」と答えている。燈花が「どちらでもじゃなくて選んでよ」と笑っている。"}, {"id": "ch08-s02-p125", "type": "text", "text": "こういう時間のことを、人は「日常」と呼ぶのだろう。"}, {"id": "ch08-s02-p126", "type": "text", "text": "窓の外が暗くなっていた。九月の日暮れは早い。磨りガラスの向こうに、街灯の光が滲んでいた。"}, {"id": "ch08-s02-p127", "type": "text", "text": "燈花の名前を呼んだ。"}, {"id": "ch08-s02-p128", "type": "text", "text": "覚えておく。"}]}, {"chapter": 8, "chapterTitle": "秋風と距離", "scene": 3, "sceneTitle": "人事ファイル", "wordCount": "約5,000字", "paragraphs": [{"id": "ch08-s03-p001", "type": "text", "text": "体育祭から三日が経った。"}, {"id": "ch08-s03-p002", "type": "text", "text": "九月の鐘鋳塔は、空気が乾いていた。梅雨期に石壁を覆っていた湿気が消え、通路を通る風にかすかな冷たさが混じっている。夏の間は感じなかった種類の冷たさ。石の温度そのもの。壁が冬に向かって準備を始めている。"}, {"id": "ch08-s03-p003", "type": "text", "text": "三階への階段を上がった。足裏に伝わる石段の感触が一段ごとに変わる。一階から二階は管理区画で、足が踏む位置を知っている。二階から三階は研究区画で、通る頻度が少ない。月に二回の定期報告で上がる。今日がその日だった。"}, {"id": "ch08-s03-p004", "type": "text", "text": "踊り場を過ぎると空気の密度が変わった。残響灯の青白い光が壁面に並んでいる。二階までは間隔が均等だが、三階は不規則だった。研究区画の各室に合わせて配置されている。霜月さんの部屋の前にある残響灯は、他よりわずかに明るい。精密計器を扱うための照度調整。"}, {"id": "ch08-s03-p005", "type": "text", "text": "三階の通路は、金属と紙の匂いがした。機械油の成分は地下の機構室と似ているが、濃度が薄い。代わりに紙の匂いがある。設計図面と報告書の束。インクの匂い。金属洗浄剤の淡い刺激臭。六月の機構室で霜月さんの白いコートの裾が視界を横切った時に嗅いだ匂いと同じ構成。あの時は「この人は香水を使わない」と思った。五ヶ月が経って、その判断は正しかったことがわかった。霜月さんの匂いは仕事の匂いだった。"}, {"id": "ch08-s03-p006", "type": "text", "text": "通路の突き当たりに鉄扉がある。三階のほかの部屋は木製の扉だが、ここだけ鉄。扉の横に小さな銘板。「第三研究室　霜月」。それだけ。"}, {"id": "ch08-s03-p007", "type": "text", "text": "扉をノックした。二回。"}, {"id": "ch08-s03-p008", "type": "text", "text": "「入りなさい」"}, {"id": "ch08-s03-p009", "type": "text", "text": "声が扉の向こうから通った。抑揚のない声。六月の機構室で聞いた声と周波数が同じだった。"}, {"id": "ch08-s03-p010", "type": "text", "text": "レバーを引き下げた。鉄の軋みが小さく鳴って、扉が開く。"}, {"id": "ch08-s03-p011", "type": "text", "text": "霜月さんの研究室は、整理されていた。"}, {"id": "ch08-s03-p012", "type": "text", "text": "正面の壁に大きな作業机。その上に音響測定器が二台並んでいる。オシロスコープの画面が緑色の波形を描いていた。ゆっくりとした正弦波。鐘鋳塔の低周波音響データの分析。机の右側に設計図面が筒に入れて立ててある。七本。筒の外側にラベルが貼られていて、階層番号が読める。左側に書架が三段。報告書のファイルが日付順に並んでいる。背表紙の手書きラベルは全て霜月さんの字だった。幅の狭い、角張った字。"}, {"id": "ch08-s03-p013", "type": "text", "text": "部屋の温度は低かった。通路より二度か三度低い。窓が一つあるが、小さい。外からの光は壁面に細い帯を落とす程度で、室内のほとんどは残響灯の光で照らされていた。青白い光が金属の計器の表面を反射し、部屋全体に硬質な色を作っている。"}, {"id": "ch08-s03-p014", "type": "text", "text": "霜月さんは作業机の前に座っていた。白いロングコートを着ている。いつもの白いコート。地下でも三階でも変わらない。背中が真っ直ぐで、椅子の背もたれに寄りかかっていない。手元にオシロスコープの測定記録用紙があり、ペンで何かを書き込んでいた。"}, {"id": "ch08-s03-p015", "type": "text", "text": "銀色の髪がハーフアップに纏められ、背中の中ほどまで流れている。残響灯の光が髪の表面を白く輝かせていた。左耳の青い石のピアスが光の中で暗い色を保っている。"}, {"id": "ch08-s03-p016", "type": "text", "text": "「定期報告を持ってきました」"}, {"id": "ch08-s03-p017", "type": "text", "text": "手にした封筒を掲げた。今月上旬の点検データの集計。霜月さんが月次で管理局に提出する報告書の素材。"}, {"id": "ch08-s03-p018", "type": "text", "text": "「机の端に置きなさい」"}, {"id": "ch08-s03-p019", "type": "text", "text": "霜月さんはオシロスコープの画面から目を離さなかった。ペンの先が記録用紙の上を走っている。数値を転記している。波形のピーク値と周波数帯域。几帳面な字が紙の罫線に沿って並んでいく。"}, {"id": "ch08-s03-p020", "type": "text", "text": "封筒を作業机の右端に置いた。図面の筒の手前。霜月さんの作業スペースを侵さない位置。六月の機構室で並行作業をした時に覚えた距離感。霜月さんの手の動線と道具の配置を邪魔しない場所を、体が判断していた。"}, {"id": "ch08-s03-p021", "type": "text", "text": "置いた。退出しようとした。"}, {"id": "ch08-s03-p022", "type": "text", "text": "「朝霧」"}, {"id": "ch08-s03-p023", "type": "text", "text": "霜月さんの声が、俺の足を止めた。"}, {"id": "ch08-s03-p024", "type": "text", "text": "振り返った。霜月さんがオシロスコープの画面から視線を外していた。ラベンダーの瞳がこちらを向いている。ペンは右手に持ったまま、先端が記録用紙の上で止まっていた。"}, {"id": "ch08-s03-p025", "type": "text", "text": "「はい」"}, {"id": "ch08-s03-p026", "type": "text", "text": "「お前の着任以前の人事記録、確認させてもらった」"}, {"id": "ch08-s03-p027", "type": "text", "text": "声の調子は変わらなかった。温度も抑揚も、業務指示と同じ水平線上にあった。しかし、その言葉の内容が俺の体のどこかに触れた。背中の奥。霜月さんの声を聴く場所。"}, {"id": "ch08-s03-p028", "type": "text", "text": "「何かありましたか」"}, {"id": "ch08-s03-p029", "type": "text", "text": "問い返した。声が平らに出た。動揺していない。動揺する理由がない。人事記録に何が書いてあるかは知っている。何が書いてないかも。"}, {"id": "ch08-s03-p030", "type": "text", "text": "霜月さんのペンが記録用紙から離れた。ペンを机に置き、体を少しだけ回転させた。椅子がきしんだ。正面ではなく、四十五度ほど俺の方に体を向けている。完全にこちらを向くのではない。計器の画面も視界に入れたままの角度。"}, {"id": "ch08-s03-p031", "type": "text", "text": "「記録が不自然に少ない」"}, {"id": "ch08-s03-p032", "type": "text", "text": "声が低かった。低いのではなく、音量が一段落ちていた。研究室の扉は閉まっている。他に人はいない。それでも音量を落とすのは、この話題の重さを意味しているのだろう。"}, {"id": "ch08-s03-p033", "type": "text", "text": "「縁際の第一監視哨での勤務評価は良好だ。桐ヶ谷隊長の推薦もある。着任後のお前の仕事ぶりも——問題ない」"}, {"id": "ch08-s03-p034", "type": "text", "text": "問題ない。霜月さんの語彙で最高の評価。しかし今日はその言葉の後に間があった。"}, {"id": "ch08-s03-p035", "type": "text", "text": "二秒の間。"}, {"id": "ch08-s03-p036", "type": "text", "text": "「しかし、それ以前の経歴が空白だ」"}, {"id": "ch08-s03-p037", "type": "text", "text": "霜月さんの目が俺を見ていた。観察している。データを収集している。六月の機構室で、俺の継手の締め方を見た時の目と同じ構造だった。何かを照合しようとしている。俺の答えと、霜月さんが持っている別の情報を突き合わせようとしている。"}, {"id": "ch08-s03-p038", "type": "text", "text": "あの時と違うのは、照合の対象が技術ではなく、俺自身だということ。"}, {"id": "ch08-s03-p039", "type": "text", "text": "「記憶がないので、経歴も作れません」"}, {"id": "ch08-s03-p040", "type": "text", "text": "正直に答えた。それ以外の答え方を知らない。嘘をつく理由もない。"}, {"id": "ch08-s03-p041", "type": "text", "text": "俺の経歴は空白だ。二年と六ヶ月前に縁際で発見された。それ以前の記録はない。記憶もない。名前は発見時の状況から与えられた。経歴を作るための材料が、どこにもない。空白は事実であって、隠蔽ではない。"}, {"id": "ch08-s03-p042", "type": "text", "text": "霜月さんの目が変わらなかった。照合を続けている。俺の言葉を受け取って、その言葉の重さと形を測っている。嘘かどうかを判定しているのではない、と思った。嘘を判定するなら目がもっと鋭くなる。今の霜月さんの目は鋭くない。深い。深い場所で何かを考えている。"}, {"id": "ch08-s03-p043", "type": "text", "text": "五秒。"}, {"id": "ch08-s03-p044", "type": "text", "text": "沈黙が研究室に満ちていた。オシロスコープの緑色の波形が静かに揺れている。残響灯の光が計器の表面で反射している。窓からの細い光が壁に帯を作っている。全てが動かなかった。霜月さんの視線だけが動いていた。俺の顔を見て、それから俺の手元に下がり、また顔に戻った。何を見ている。手のひらか。それとも手首のブレスレットか。"}, {"id": "ch08-s03-p045", "type": "text", "text": "「……そうか」"}, {"id": "ch08-s03-p046", "type": "text", "text": "霜月さんの声が返った。低い声。さっきよりわずかに柔らかかった。柔らかいという表現は正確ではないかもしれない。角が取れた。質問の角度が消え、受領の声に戻っていた。"}, {"id": "ch08-s03-p047", "type": "text", "text": "「了解した」"}, {"id": "ch08-s03-p048", "type": "text", "text": "それだけだった。"}, {"id": "ch08-s03-p049", "type": "text", "text": "霜月さんが体の向きを戻した。椅子がきしんだ。再びオシロスコープの画面に向かい、ペンを取り上げ、記録用紙に視線を落とした。数値の転記が再開された。ペンの先が紙の上を走る音。さっきと同じ速度。同じリズム。"}, {"id": "ch08-s03-p050", "type": "text", "text": "俺の人事記録の話は、そこで終わった。"}, {"id": "ch08-s03-p051", "type": "text", "text": "霜月さんの態度に変化はなかった。声の温度も、体の姿勢も、ペンを動かす手の角度も。「了解した」の後に何かが続く気配はなく、業務に戻っていた。"}, {"id": "ch08-s03-p052", "type": "text", "text": "背中の奥にあった何かが、少しだけ動いた。緊張ではなかった。霜月さんの質問に緊張はしなかった。けれど、何かが動いた。名前のない動き。背中の奥で、小さく位置を変えた何か。"}, {"id": "ch08-s03-p053", "type": "text", "text": "霜月さんが俺の人事記録を確認した。着任以前の経歴の空白を把握した。「了解した」と言って話を打ち切った。それだけ。それ以上はなかった。"}, {"id": "ch08-s03-p054", "type": "text", "text": "けれど——霜月さんがわざわざ着任以前の記録を調べたということは、調べる理由があったということだ。"}, {"id": "ch08-s03-p055", "type": "text", "text": "業務上必要な情報なら、着任時の書類で足りる。勤務評価も桐ヶ谷さんの推薦状もある。着任後の仕事ぶりも「問題ない」と評価されている。それで十分なはずだ。それでも着任以前の経歴を調べたのは、業務以外の何かが動機にあるということではないか。"}, {"id": "ch08-s03-p056", "type": "text", "text": "推測にとどめる。根拠がない。"}, {"id": "ch08-s03-p057", "type": "text", "text": "「失礼します」"}, {"id": "ch08-s03-p058", "type": "text", "text": "「ああ。来月の報告も同じ形式で構わない」"}, {"id": "ch08-s03-p059", "type": "text", "text": "霜月さんの声は通常の業務口調に戻っていた。ペンの音が止まらなかった。"}, {"id": "ch08-s03-p060", "type": "text", "text": "扉のレバーを押し下げ、研究室を出た。鉄扉が閉まる。軋みが通路に反響して、石壁に吸われて消えた。"}, {"id": "ch08-s03-p061", "type": "text", "text": "通路の残響灯が青白く並んでいる。研究室の中の温度から、通路の温度に切り替わった。わずかに温かい。夏であれば逆だっただろう。冷房のない鐘鋳塔では、秋は室内より通路の方が温かくなる。"}, {"id": "ch08-s03-p062", "type": "text", "text": "階段を降り始めた。二階の管理区画に戻る。靴音が石段に反響する。自分の足音だけ。霜月さんの足音はない。当然だ。霜月さんは研究室にいる。"}, {"id": "ch08-s03-p063", "type": "text", "text": "あの人が俺の経歴を調べた。"}, {"id": "ch08-s03-p064", "type": "text", "text": "空白を見つけた。空白について質問した。俺は正直に答えた。霜月さんは「了解した」と言った。"}, {"id": "ch08-s03-p065", "type": "text", "text": "それだけ。"}, {"id": "ch08-s03-p066", "type": "text", "text": "それだけのはずだった。けれど、霜月さんの目を見た時の感覚が残っている。六月の機構室で俺の手技を見た時の「照合」の目。あの時は技術の話だった。今日は違った。俺という人間の、存在の根拠を照合していた。"}, {"id": "ch08-s03-p067", "type": "text", "text": "霜月さんは何を知っている。あるいは、何を疑っている。"}, {"id": "ch08-s03-p068", "type": "text", "text": "問わなかった。問う理由がないからだ。俺の空白は事実で、隠すものが何もない。疑われても困らない。記憶がないのだから。"}, {"id": "ch08-s03-p069", "type": "text", "text": "二階に着いた。管理室の扉を開ける。計器が並んでいる。残響灯の光。いつもの管理室。計器の針が定位置で安定している。第三系統の出力は正常範囲内。第七系統の微振動も許容値。"}, {"id": "ch08-s03-p070", "type": "text", "text": "椅子に座った。作業台の上に点検記録用紙を広げた。ペンを取った。"}, {"id": "ch08-s03-p071", "type": "text", "text": "霜月さんのコーヒーの味を思い出した。六月に飲んだ苦いコーヒー。「業務中の水分補給だ」と言って渡された温かいカップ。"}, {"id": "ch08-s03-p072", "type": "text", "text": "あの人は不器用な人だ。質問の形でしか褒められない。コーヒーを業務の名目でしか渡せない。人事記録の空白を「確認させてもらった」と事後報告の形で切り出す。全部、手続きを経由する。直接触れない。手順を踏んで、手順の向こう側から手を伸ばす。"}, {"id": "ch08-s03-p073", "type": "text", "text": "だから今日の質問も、たぶん——不器用な関心の表れなのだと思う。"}, {"id": "ch08-s03-p074", "type": "text", "text": "たぶん。"}, {"id": "ch08-s03-p075", "type": "text", "text": "ペンを動かした。数値を記入していく。点検記録の罫線に沿って、文字が並んでいく。いつもの作業。いつもの数字。"}, {"id": "ch08-s03-p076", "type": "text", "text": "背中の奥で小さく動いたものは、まだ消えていなかった。冷たくはない。温かくもない。あるだけ。存在しているだけ。名前がまだない。"}, {"id": "ch08-s03-p077", "type": "text", "text": "覚えておく。"}, {"id": "ch08-s03-p078", "type": "divider", "text": "---"}, {"id": "ch08-s03-p079", "type": "text", "text": "霜月氷華は、朝霧蓮が退出した後も数値の転記を続けた。"}, {"id": "ch08-s03-p080", "type": "text", "text": "ペンが紙の上を走る音が研究室に響いている。オシロスコープの画面に正弦波が揺れ、残響灯が金属の計器を青白く照らしている。七分ほどそのまま作業を続けた。記録用紙の右下まで数値が埋まり、最後の一行にペンを走らせ、用紙を裏返した。"}, {"id": "ch08-s03-p081", "type": "text", "text": "裏返した用紙を脇に置いた時、右手がペンから離れた。"}, {"id": "ch08-s03-p082", "type": "text", "text": "椅子を引き、デスクの右側にある引き出しに手をかけた。真鍮の引き手に指をかけ、静かに開ける。引き出しの中には未整理の書類が数枚と、紙挟みで綴じられた薄い冊子が一つ入っていた。"}, {"id": "ch08-s03-p083", "type": "text", "text": "冊子を取り出した。表紙に「人事記録　朝霧蓮」と印字されている。"}, {"id": "ch08-s03-p084", "type": "text", "text": "氷華はそれを開いた。二度目だった。一度目は昨日の夜、管理局の書庫から持ち出して読んだ。今、もう一度開いている。"}, {"id": "ch08-s03-p085", "type": "text", "text": "ページは少ない。着任前の経歴欄が空白。出生地、不明。学歴、記録なし。縁際第一監視哨の配属記録が最古の項目で、それ以前は何もない。写真が一枚貼られている。着任時の証明写真。前髪の下に傷跡がわずかに見える。"}, {"id": "ch08-s03-p086", "type": "text", "text": "氷華の指が、経歴欄の「不明」の文字の上で止まった。"}, {"id": "ch08-s03-p087", "type": "text", "text": "ラベンダーの瞳が紙面を見下ろしている。瞳孔が微かに動いた。計器の数値を読む時と同じ速度で、同じ精度で、文字を追っている。しかし計器と違って、この記録には読み取るべきデータがなかった。空白しかない。"}, {"id": "ch08-s03-p088", "type": "text", "text": "空白そのものが、データだった。"}, {"id": "ch08-s03-p089", "type": "text", "text": "氷華は冊子を閉じ、引き出しに戻した。真鍮の引き手に指をかけ、音を立てずに閉める。ペンを取り直し、次の記録用紙を引き寄せた。"}, {"id": "ch08-s03-p090", "type": "text", "text": "左耳の青い石のピアスが、残響灯の光の中で暗く光った。"}]}, {"chapter": 8, "chapterTitle": "秋風と距離", "scene": 4, "sceneTitle": "深入りするな", "wordCount": "約5,000字", "paragraphs": [{"id": "ch08-s04-p001", "type": "text", "text": "翌日の夕方、端末が鳴った。"}, {"id": "ch08-s04-p002", "type": "text", "text": "管理室で点検記録を書いていた。第三系統の出力グラフ。昨日から数値に変化はない。いつもの数字。いつもの作業。背中の奥に残っていた名前のないものは、一晩寝たら存在感が薄れていた。消えたのではなく、沈んだ。水底の石と同じ。見えなくなっただけで、ある。"}, {"id": "ch08-s04-p003", "type": "text", "text": "端末の画面を確認した。"}, {"id": "ch08-s04-p004", "type": "text", "text": "『見晴らし丘に来い。18時。——桐ヶ谷』"}, {"id": "ch08-s04-p005", "type": "text", "text": "短い文面。句読点なし。「来い」は命令形だが、軍の命令書式ではなかった。命令であれば「集合せよ」になる。「来い」は、もう少し個人的な呼び方だった。"}, {"id": "ch08-s04-p006", "type": "text", "text": "ペンを置いた。壁の時計は十七時二十分を指している。見晴らし丘までは中庭を抜けて北に十五分。間に合う。"}, {"id": "ch08-s04-p007", "type": "text", "text": "点検記録に最後の数値を書き込んだ。第七系統の微振動、許容範囲内。記録用紙をファイルに挟み、作業台の定位置に戻した。上着を椅子の背から取り、袖を通した。九月の夕方は、六月の夕方より二度ほど低い。体が季節を計測している。"}, {"id": "ch08-s04-p008", "type": "text", "text": "管理室を出た。鐘鋳塔の階段を降りる。石段の温度が足裏から伝わる。秋の石。夏とは違う冷たさ。"}, {"id": "ch08-s04-p009", "type": "text", "text": "中庭を横切った。残響桜の葉が黄色く色づき始めていた。四月には薄紫の花弁が散っていた場所に、今は枯葉の予兆がある。風が吹いて、黄色い葉が一枚、石畳の上に落ちた。"}, {"id": "ch08-s04-p010", "type": "text", "text": "北に向かって歩いた。中庭を抜け、教室棟の脇を通り、中円区の北端へ。学院の敷地の外に出ると、石畳が砂利道に変わった。道が緩やかに上がっている。丘。"}, {"id": "ch08-s04-p011", "type": "text", "text": "見晴らし丘は、中円区の北端にある小高い丘だった。学院と中円区の街並みが南に広がり、北に向けば——"}, {"id": "ch08-s04-p012", "type": "text", "text": "遠くに、蝕域の靄が見えた。"}, {"id": "ch08-s04-p013", "type": "text", "text": "地平線の上。灰白色の帯。六月に教室棟の屋上から見た靄と同じもの。しかし九月の空は六月より澄んでいた。空気中の水分が減って、視界が利く。そのぶん、靄の輪郭がはっきり見えた。ゆっくりと脈動している。呼吸のように。あるいは何かの鼓動のように。輪郭の内側と外側で、空の色が違った。外側は夕焼けの赤。内側は、赤が届かない。灰と白が混じった色。色と呼んでいいのかわからない。色の不在。"}, {"id": "ch08-s04-p014", "type": "text", "text": "丘の頂上にベンチが一つあった。木製。風雨に晒されて木目が浮き出している。ベンチの手前に、人が立っていた。"}, {"id": "ch08-s04-p015", "type": "text", "text": "黒いハーフコート。低いポニーテール。腰のマルチツール。"}, {"id": "ch08-s04-p016", "type": "text", "text": "桐ヶ谷さんは北を向いていた。蝕域の靄を見ている。腕は組んでいなかった。両手がコートのポケットに入っている。肩の角度が、六月の教室棟屋上で見た時と違った。屋上の桐ヶ谷さんは「力を少しだけ抜いた色」の瞳をしていた。今の桐ヶ谷さんの背中には、力が入っていた。肩甲骨の間。上背部の筋肉が、コートの生地越しにわかるほど張っていた。"}, {"id": "ch08-s04-p017", "type": "text", "text": "「桐ヶ谷さん」"}, {"id": "ch08-s04-p018", "type": "text", "text": "声をかけた。"}, {"id": "ch08-s04-p019", "type": "text", "text": "桐ヶ谷さんが振り返った。半回転。コートの裾が風に巻かれた。"}, {"id": "ch08-s04-p020", "type": "text", "text": "琥珀色の瞳がこちらを向いた。"}, {"id": "ch08-s04-p021", "type": "text", "text": "夕焼けの光の中の琥珀色。六月の屋上で見た時は「温かい色」だと思った。今日の琥珀色は温かくなかった。同じ色のはずだ。同じ角度の光が当たっている。しかし色の奥にある温度が違った。温かさではなく、硬さ。硬いものを噛み締めている人の目。"}, {"id": "ch08-s04-p022", "type": "text", "text": "「来たか」"}, {"id": "ch08-s04-p023", "type": "text", "text": "声は低かった。いつもと同じ低さ。しかし「来たか」の二文字の間に、通常より長い間があった。「来た」と「か」の間。一拍の間。その一拍に、何かが詰まっていた。"}, {"id": "ch08-s04-p024", "type": "text", "text": "「座れ」"}, {"id": "ch08-s04-p025", "type": "text", "text": "桐ヶ谷さんがベンチの方を顎で示した。自分はベンチには座らず、立ったままだった。ポケットから右手を出し、左手は入れたまま。"}, {"id": "ch08-s04-p026", "type": "text", "text": "座った。木の座面が冷たかった。九月の木。夕方の冷え方が始まっている。"}, {"id": "ch08-s04-p027", "type": "text", "text": "桐ヶ谷さんは俺の斜め前に立っていた。北を向いている。蝕域の方角。俺からは桐ヶ谷さんの横顔が見える。低いポニーテールの黒い髪が、夕風に一本も揺れていなかった。硬い髪質。風に揺れにくい髪。六月の屋上では、ポニーテールが一瞬だけ揺れた。今日は風がないのか。いや、風はあった。丘の上だから。ベンチの脇の雑草が風に揺れている。桐ヶ谷さんの髪だけが揺れていない。力が入っているから。頭から首にかけて、筋肉が緊張している。"}, {"id": "ch08-s04-p028", "type": "text", "text": "「蓮」"}, {"id": "ch08-s04-p029", "type": "text", "text": "名前だった。"}, {"id": "ch08-s04-p030", "type": "text", "text": "六月の再会から数えて、何度目の名前だろう。教室棟の前で「蓮」。屋上で「蓮」。屋上の去り際で「蓮」。今日で四回目か五回目。回数は正確に覚えていない。しかし毎回、鳩尾の奥が動く。同じ場所。歯車の安心とも鐘の懐かしさとも違う、人の形をした反応。"}, {"id": "ch08-s04-p031", "type": "text", "text": "今日の「蓮」は、過去のどれとも違った。声の中に刃があった。六月の「深入りするな」の時の鋭さに近い。しかし六月の時は、鋭さの後に肩の力が抜けた。今日は力が抜ける気配がなかった。"}, {"id": "ch08-s04-p032", "type": "text", "text": "桐ヶ谷さんが俺を見た。横顔から正面に視線を移した。"}, {"id": "ch08-s04-p033", "type": "text", "text": "「あまり深入りするな」"}, {"id": "ch08-s04-p034", "type": "text", "text": "同じ言葉。六月に南門の前で聞いた言葉と、同じ四文字。しかし六月の時は「深入りするな」だった。今日は「あまり深入りするな」だった。「あまり」がついている。「あまり」は程度を限定する副詞だ。「深入りするな」は全面的な制止。「あまり深入りするな」は——すでに深入りが始まっていることを前提にした警告。"}, {"id": "ch08-s04-p035", "type": "text", "text": "「何に、ですか」"}, {"id": "ch08-s04-p036", "type": "text", "text": "聞き返した。声は平らに出た。"}, {"id": "ch08-s04-p037", "type": "text", "text": "桐ヶ谷さんの目が、一瞬だけ細くなった。六月の屋上で「前の俺はどんな人間でしたか」と聞いた時の反応に似ていた。痛みを薄く引き延ばす動き。しかし今日のは、もっと短かった。"}, {"id": "ch08-s04-p038", "type": "text", "text": "「……お前の過去に、だ」"}, {"id": "ch08-s04-p039", "type": "text", "text": "声が落ちた。音量が下がったのではなく、声の位置が下がった。喉の奥から出る声。"}, {"id": "ch08-s04-p040", "type": "text", "text": "「今のお前は、学院で仲間がいて、仕事があって、普通に暮らしている」"}, {"id": "ch08-s04-p041", "type": "text", "text": "事実の列挙。仲間。仕事。普通の暮らし。桐ヶ谷さんは俺の現在を正確に把握していた。遠くから見ているだけでここまで把握できるのか。あるいは、誰かから報告を受けているのか。"}, {"id": "ch08-s04-p042", "type": "text", "text": "「それでいいだろう」"}, {"id": "ch08-s04-p043", "type": "text", "text": "語尾が疑問形ではなかった。断定。「それでいい」と桐ヶ谷さんは言っている。今の生活で十分だと。過去を掘り返す必要はないと。"}, {"id": "ch08-s04-p044", "type": "text", "text": "六月の屋上で聞いた「無理に思い出そうとしなくていい」「今の生活に集中しろ」と、方角は同じだった。しかし温度が違った。六月は気遣いだった。穏やかな声で、俺を安心させるための言葉だった。今日の声には気遣いの余裕がなかった。もっと差し迫ったもの。"}, {"id": "ch08-s04-p045", "type": "text", "text": "鳩尾の奥が動いた。いつもの場所。しかし動き方が違った。六月は「人の形をした反応」だった。今日は——引っ張られている。鳩尾の奥にある何かが、桐ヶ谷さんの声に引かれて、前に出ようとしている。"}, {"id": "ch08-s04-p046", "type": "text", "text": "昨日。霜月さんに人事記録の空白を指摘された。「記録が不自然に少ない」。霜月さんの研究室で、ラベンダーの瞳に見つめられた。俺の経歴を照合しようとする深い目。"}, {"id": "ch08-s04-p047", "type": "text", "text": "今日。桐ヶ谷さんに「深入りするな」と言われた。六月と同じ言葉で。しかし六月より切迫した声で。"}, {"id": "ch08-s04-p048", "type": "text", "text": "二つの出来事が、並んだ。"}, {"id": "ch08-s04-p049", "type": "text", "text": "霜月さんは俺の空白を調べている。桐ヶ谷さんは俺の空白に近づくなと言っている。二人とも、俺の経歴の空白を知っている。そして二人とも、その空白の向こう側に何があるかについて、俺より多くの情報を持っている。"}, {"id": "ch08-s04-p050", "type": "text", "text": "鳩尾の奥で引っ張られるものが、もう一段前に出た。"}, {"id": "ch08-s04-p051", "type": "text", "text": "「桐ヶ谷さん」"}, {"id": "ch08-s04-p052", "type": "text", "text": "声が出た。自分の声を聞いた。平らな声だった。いつもの声。しかし、いつもの声の下に、もう一つの音が混じっていた。聞いたことのない音。自分の喉から出たことのない音。"}, {"id": "ch08-s04-p053", "type": "text", "text": "「何を知っているんですか」"}, {"id": "ch08-s04-p054", "type": "text", "text": "出た。"}, {"id": "ch08-s04-p055", "type": "text", "text": "六月の教室棟屋上では、この問いを喉の奥で止めた。桐ヶ谷さんの琥珀色の瞳を見て、「この人が口を閉じているなら理由がある」と判断して、止めた。"}, {"id": "ch08-s04-p056", "type": "text", "text": "今日は止まらなかった。"}, {"id": "ch08-s04-p057", "type": "text", "text": "昨日の霜月さんの目。深い場所で何かを照合する目。それが鳩尾の奥に残っていて、桐ヶ谷さんの「深入りするな」とぶつかった時に、止めていた言葉が押し出された。"}, {"id": "ch08-s04-p058", "type": "text", "text": "知りたい。"}, {"id": "ch08-s04-p059", "type": "text", "text": "初めてだった。この感覚。俺は今まで、自分の過去を「知りたい」と思ったことがなかった。空白は空白のまま受け入れていた。記憶がないことに不便はあっても、苦痛はなかった。歯車が回せるなら。鐘の音が聴けるなら。それで足りていた。"}, {"id": "ch08-s04-p060", "type": "text", "text": "足りなくなった。"}, {"id": "ch08-s04-p061", "type": "text", "text": "いつからだろう。燈花を「燈花」と呼んだ時か。霜月さんに人事記録を問われた時か。あるいはもっと前——六月の屋上で桐ヶ谷さんに夢の話をした時か。"}, {"id": "ch08-s04-p062", "type": "text", "text": "わからない。わからないが、鳩尾の奥で何かが前に出ている。今まで沈んでいたものが、水面に向かって浮上している。冷たくはない。温かくもない。強い。ただ強い。方向を持っている。「知りたい」という方向。"}, {"id": "ch08-s04-p063", "type": "text", "text": "桐ヶ谷さんは答えなかった。"}, {"id": "ch08-s04-p064", "type": "text", "text": "琥珀色の瞳が俺を見つめていた。六月の屋上で「真面目で、不器用で、手先が器用で」と教えてくれた目。あの時の目は柔らかかった。今の目は柔らかくなかった。硬かった。しかし硬さの種類が、壁ではなかった。堪えている硬さ。何かを言いたくて、言えなくて、言わないことを選んで、その選択に力を使っている人の目。"}, {"id": "ch08-s04-p065", "type": "text", "text": "五秒。"}, {"id": "ch08-s04-p066", "type": "text", "text": "十秒。"}, {"id": "ch08-s04-p067", "type": "text", "text": "丘の上の風が、枯れかけた草を揺らしていた。遠くの蝕域の靄が、ゆっくりと輪郭を変えている。夕焼けの赤が西に傾き、空の上半分が藍色に変わり始めていた。"}, {"id": "ch08-s04-p068", "type": "text", "text": "---\n**【選択肢A】「何を知っているんですか」と問い詰める**\n→ 隠しフラグ（晶との関係性：信頼ベース）"}, {"id": "ch08-s04-p069", "type": "text", "text": "「桐ヶ谷さん」"}, {"id": "ch08-s04-p070", "type": "text", "text": "もう一度言った。声を落とさなかった。落とす理由がなかった。"}, {"id": "ch08-s04-p071", "type": "text", "text": "「俺は、あなたを信じています。体が知っていることと、同じ確かさで」"}, {"id": "ch08-s04-p072", "type": "text", "text": "歯車の適正値を手が知っている。鐘の音の正しい周波数を耳が知っている。桐ヶ谷さんが敵ではないことを、鳩尾の奥が知っている。そのどれとも同じ種類の確信。"}, {"id": "ch08-s04-p073", "type": "text", "text": "「だから聞いています。あなたが俺の過去について何かを知っていて、それを隠しているのは——守っているからだと、わかっています。六月の屋上で、そう感じました。今もそう思っています」"}, {"id": "ch08-s04-p074", "type": "text", "text": "桐ヶ谷さんの目の奥で、何かが揺れた。六月の再会で見た揺れと似ていた。喜びと痛みが同時に存在する揺れ。"}, {"id": "ch08-s04-p075", "type": "text", "text": "「でも、知りたいんです。何をかはわからない。けれど、知りたいと思っている。初めてそう思った。それだけ伝えておきたかった」"}, {"id": "ch08-s04-p076", "type": "text", "text": "桐ヶ谷さんの口元が、かすかに引き結ばれた。唇の線が水平になった。何かを噛み締めている。"}, {"id": "ch08-s04-p077", "type": "text", "text": "三秒の間。"}, {"id": "ch08-s04-p078", "type": "text", "text": "「……わかった。お前がそう思っていることは、覚えておく」"}, {"id": "ch08-s04-p079", "type": "text", "text": "低い声。返答ではなかった。受領だった。俺の言葉を受け取って、格納した声。答えではなく、「聞いた」という報告。"}, {"id": "ch08-s04-p080", "type": "divider", "text": "---"}, {"id": "ch08-s04-p081", "type": "choice", "text": "**【選択肢B】受け流す**\n→ 隠しフラグ（晶との関係性：距離を保つ）"}, {"id": "ch08-s04-p082", "type": "text", "text": "十秒の沈黙の後、鳩尾の奥の力が、少しだけ引いた。"}, {"id": "ch08-s04-p083", "type": "text", "text": "前に出ようとしていたものが、出きらなかった。出すべきかどうかの判断がつかなかった。桐ヶ谷さんの目は硬かった。しかしその硬さは、俺を拒んでいるのではなく、何かを堪えている硬さだった。六月の屋上と同じ構造。口を閉じる理由がある。"}, {"id": "ch08-s04-p084", "type": "text", "text": "「……わかりました」"}, {"id": "ch08-s04-p085", "type": "text", "text": "声を平らに保った。"}, {"id": "ch08-s04-p086", "type": "text", "text": "「今は聞きません」"}, {"id": "ch08-s04-p087", "type": "text", "text": "「今は」をつけた。自分でも意図しなかった言葉だった。しかし口から出た以上、それが正直な形なのだろう。「聞かない」ではなく「今は聞かない」。いつか聞く可能性を、留保している。"}, {"id": "ch08-s04-p088", "type": "text", "text": "桐ヶ谷さんの肩が、一ミリだけ下がった。"}, {"id": "ch08-s04-p089", "type": "divider", "text": "---"}, {"id": "ch08-s04-p090", "type": "text", "text": "桐ヶ谷さんがポケットから両手を出した。コートの裾を直すように、右手で生地を払った。"}, {"id": "ch08-s04-p091", "type": "text", "text": "「……私はお前を守りたいだけだ」"}, {"id": "ch08-s04-p092", "type": "text", "text": "声が変わっていた。"}, {"id": "ch08-s04-p093", "type": "text", "text": "今日の会話の中で、初めて声の硬さが割れた場所。「守りたいだけだ」の「だけ」に、余分な力がかかっていた。「だけ」であることを確認するような力の入れ方。「守りたい」以外の何かが自分の中にあることを、桐ヶ谷さん自身が知っていて、それを「だけ」で蓋をしている。"}, {"id": "ch08-s04-p094", "type": "text", "text": "「だから、今は聞くな」"}, {"id": "ch08-s04-p095", "type": "text", "text": "「今は」。"}, {"id": "ch08-s04-p096", "type": "text", "text": "桐ヶ谷さんも「今は」と言った。"}, {"id": "ch08-s04-p097", "type": "text", "text": "六月の「無理に思い出そうとしなくていい」は、時間の限定がなかった。「しなくていい」は期限のない許可だった。今日の「今は聞くな」は、期限がある。「今は」の裏側に「いつか」がある。いつか、聞いてもいい時が来る。桐ヶ谷さんはそう言っているのか。"}, {"id": "ch08-s04-p098", "type": "text", "text": "あるいは——来てほしいと思っているのか。"}, {"id": "ch08-s04-p099", "type": "text", "text": "「はい」"}, {"id": "ch08-s04-p100", "type": "text", "text": "答えた。短く。"}, {"id": "ch08-s04-p101", "type": "text", "text": "桐ヶ谷さんが蝕域の方角から視線を俺に戻した。琥珀色の瞳。夕焼けの残光が瞳の表面で反射していた。硬さが、わずかに和らいでいた。和らいだのではなく、硬さの種類が変わった。堪えている硬さから、見ている硬さに。俺を見ている。今ここにいる俺を、確認している。六月の屋上の去り際に「元気そうでよかった」と言った時の目と、似ていた。"}, {"id": "ch08-s04-p102", "type": "text", "text": "「鐘鋳塔の仕事は続けろ。霜月も——お前の仕事を認めている。あそこにいろ」"}, {"id": "ch08-s04-p103", "type": "text", "text": "うなずいた。"}, {"id": "ch08-s04-p104", "type": "text", "text": "桐ヶ谷さんの右手が、一瞬だけ動いた。コートの内側から何かを取り出しかけて、やめた。六月の南門でも同じ動作をしていた。ポケットに手を入れて、何も持たずに出した。取り出そうとしてやめるもの。何だろう。何を渡しかけて、やめているのだろう。"}, {"id": "ch08-s04-p105", "type": "text", "text": "桐ヶ谷さんが踵を返した。"}, {"id": "ch08-s04-p106", "type": "text", "text": "軍人の歩幅。正確で、規則的。六月の教室棟屋上では「半歩だけ遅かった」と記憶している。今日の歩幅は遅くなかった。正規の歩幅。速くもなく遅くもなく、訓練された距離で足が前に出ている。"}, {"id": "ch08-s04-p107", "type": "text", "text": "三歩。五歩。丘を下り始めた。コートの裾が風に揺れた。低いポニーテールが背中の中ほどで揺れなかった。まだ力が入っている。首から背中にかけて。"}, {"id": "ch08-s04-p108", "type": "text", "text": "振り返らなかった。"}, {"id": "ch08-s04-p109", "type": "text", "text": "六月の屋上でも、六月の南門でも、桐ヶ谷さんは振り返らなかった。背中だけをこちらに向けて、歩いていく。振り返らない背中。その背中が「守っている」ものの大きさを、俺はまだ正確に測れない。"}, {"id": "ch08-s04-p110", "type": "text", "text": "足音が遠くなった。砂利を踏む音。規則的。次第に小さくなる。丘の斜面を降りていく。"}, {"id": "ch08-s04-p111", "type": "text", "text": "音が消えた。"}, {"id": "ch08-s04-p112", "type": "text", "text": "一人になった。"}, {"id": "ch08-s04-p113", "type": "text", "text": "ベンチに座ったまま、北を見ていた。蝕域の靄が、夕闘の中でぼんやりと灰白色に光っていた。六月の屋上から見た時より近い——ように感じた。距離は変わっていないはずだ。中円区の北端から蝕域までの距離は、数値として固定されている。変わるのは距離ではなく、見る側の目だ。"}, {"id": "ch08-s04-p114", "type": "text", "text": "六月は、蝕域を「遠くにある」と感じた。"}, {"id": "ch08-s04-p115", "type": "text", "text": "今日は、蝕域を「ある」と感じている。遠い近いではなく、存在している。俺の視界の中に、確実に存在している。"}, {"id": "ch08-s04-p116", "type": "text", "text": "靄の輪郭が脈動している。呼吸するように広がり、縮む。広がる時に、灰白色が空に滲む。縮む時に、輪郭が濃くなる。繰り返し。繰り返し。あの輪郭の内側に、消えた場所がある。蝕域に飲まれた町。蝕域に飲まれた島。名前のなくなった場所。"}, {"id": "ch08-s04-p117", "type": "text", "text": "俺の夢の中の場所は、あの靄の向こう側にあるのかもしれない。機械の音。海の匂い。歯車を触る指。それらは全部、あの灰白色の中から来ているのかもしれない。"}, {"id": "ch08-s04-p118", "type": "text", "text": "鳩尾の奥に、まだ「知りたい」が残っていた。桐ヶ谷さんが去った後も消えなかった。前に出ようとする力は弱まったが、方向を失っていなかった。北を向いている。蝕域の方角を向いている。"}, {"id": "ch08-s04-p119", "type": "text", "text": "桐ヶ谷さんは「守りたい」と言った。"}, {"id": "ch08-s04-p120", "type": "text", "text": "霜月さんは空白を「照合」していた。"}, {"id": "ch08-s04-p121", "type": "text", "text": "二人の視線の先に、俺の過去がある。"}, {"id": "ch08-s04-p122", "type": "text", "text": "知りたい。"}, {"id": "ch08-s04-p123", "type": "text", "text": "まだ強い。名前がまだない。「知りたい」は感情の名前ではなく、方向の名前だ。方向だけがあって、中身がない。何を知りたいのかすら、まだわからない。わからないまま、鳩尾の奥が北を向いている。"}, {"id": "ch08-s04-p124", "type": "text", "text": "夕焼けが消えかけていた。西の空に赤い線が一本残っているだけで、あとは藍色。蝕域の靄だけが灰白色のまま、暗くなる空の中で際立ち始めていた。"}, {"id": "ch08-s04-p125", "type": "text", "text": "ベンチから立ち上がった。"}, {"id": "ch08-s04-p126", "type": "text", "text": "木の座面から体温が消える速度を、尻が記憶していた。座ってから十五分ほど。桐ヶ谷さんとの会話は五分もなかっただろう。残りの十分は一人で座っていた。蝕域を見ながら。"}, {"id": "ch08-s04-p127", "type": "text", "text": "丘を降りた。砂利道から石畳に変わった。学院の敷地に入ると、灯籠通りの灯りが南に見えた。橙色の点が並んでいる。中庭の残響桜の輪郭が暗がりの中に見えた。"}, {"id": "ch08-s04-p128", "type": "text", "text": "管理室に戻る道を歩きながら、桐ヶ谷さんの声を反芻していた。"}, {"id": "ch08-s04-p129", "type": "text", "text": "「私はお前を守りたいだけだ」。"}, {"id": "ch08-s04-p130", "type": "text", "text": "あの「だけ」の力み方。六月には聞こえなかった音だった。六月の桐ヶ谷さんは、もう少し余裕があった。「元気そうでよかった」を、制御の外れた声で言えるだけの余裕。今日の桐ヶ谷さんには、それがなかった。余裕が減っている。何かが、桐ヶ谷さんの中で変わっている。あるいは、桐ヶ谷さんの外で何かが動いている。"}, {"id": "ch08-s04-p131", "type": "text", "text": "「あまり深入りするな」。六月は「深入りするな」だった。今日は「あまり」がついた。俺が深入りし始めていることを、桐ヶ谷さんは知っている。俺自身よりも先に。"}, {"id": "ch08-s04-p132", "type": "text", "text": "鐘鋳塔の灯りが北東に見えた。青白い残響灯の光。あの塔の中に、俺の仕事がある。歯車と計器と残響灯。霜月さんがいる。コーヒーの苦味と、ラベンダーの瞳と、「了解した」の角の取れた声がある。"}, {"id": "ch08-s04-p133", "type": "text", "text": "塔の向こうに、蝕域がある。"}, {"id": "ch08-s04-p134", "type": "text", "text": "同じ方角だった。鐘鋳塔と蝕域が、俺の視界の中で重なっていた。偶然の配置。地理的な位置関係に意味はない。しかし今日、この夕方にその重なりを見ていることに——何かを感じた。感じたものの名前は、まだない。"}, {"id": "ch08-s04-p135", "type": "text", "text": "補佐官舎に向かった。管理室ではなく。今日の仕事は終わっている。鍵を開け、暗い部屋に入った。靴を脱いだ。机の上に、残響祭の花弁が置いてある。乾燥して褐色に変わっている。形だけが残っている。六月よりさらに色が褪せていた。"}, {"id": "ch08-s04-p136", "type": "text", "text": "ベッドに座った。窓の外。鐘鋳塔の灯り。その上の空に、もう蝕域の靄は見えなかった。建物が視界を遮っている。見晴らし丘に立たないと見えない。日常の中では見えない。"}, {"id": "ch08-s04-p137", "type": "text", "text": "けれど、ある。"}, {"id": "ch08-s04-p138", "type": "text", "text": "桐ヶ谷さんの「守りたいだけだ」の力み。「あまり」がついた警告。「今は聞くな」の「今は」。鳩尾の奥で北を向き始めたもの。"}, {"id": "ch08-s04-p139", "type": "text", "text": "知りたい、と思った。"}]}, {"chapter": 8, "chapterTitle": "秋風と距離", "scene": 5, "sceneTitle": "秋の空気", "wordCount": "約5,000字", "paragraphs": [{"id": "ch08-s05-p001", "type": "text", "text": "空気の温度が、下がっている。"}, {"id": "ch08-s05-p002", "type": "text", "text": "管理室を出て、鐘鋳塔の階段を降りた。十九時四十五分。夜間巡回の前に中庭を一周する。いつからか習慣になっていた。歯車と計器の中にいた体を、外の空気に晒す。それだけのことだけれど、五月にはやっていなかった。六月にもやっていなかった。七月の終わり頃から、自然と足が外に向くようになった。"}, {"id": "ch08-s05-p003", "type": "text", "text": "正門側の通用口から外に出る。"}, {"id": "ch08-s05-p004", "type": "text", "text": "九月の夜気が、首筋に触れた。"}, {"id": "ch08-s05-p005", "type": "text", "text": "冷たい。冷たいが、冬の冷たさではない。夏の湿気が抜けた後の、乾いた冷え。肌の表面から水分を引いていく空気。吸い込むと鼻腔の奥が清んだ。八月までは空気の底に溜まっていた重さがない。代わりに、透き通った何かがある。透き通っているから、遠くの匂いが混じる。土の匂い。枯れかけた草の匂い。そして——残響桜の、葉の匂い。"}, {"id": "ch08-s05-p006", "type": "text", "text": "花の匂いではなかった。"}, {"id": "ch08-s05-p007", "type": "text", "text": "四月は甘い匂いだった。「甘い」と分類すべきか「優しい」と呼ぶべきか、あの頃は判断がつかなかった。今、中庭に漂っているのは花の名残ではない。葉の匂い。乾いた繊維と、色素が分解されていく過程の匂い。渋い、と言えばいいのか。苦い、に近いのか。コーヒーの苦味とは違う。もっと薄く、もっと広い。空気全体に均一に溶けている苦味。"}, {"id": "ch08-s05-p008", "type": "text", "text": "残響桜の下を歩いた。"}, {"id": "ch08-s05-p009", "type": "text", "text": "見上げた。夜目にも葉の変化がわかった。灯籠通りの橙色の光が、離れた場所から木の輪郭を浮かべている。その光の中で、葉の一部が黄色く光っていた。体育祭の日、一割にも満たなかった変色が、少し広がっている。一割を超えた。二割には届いていない。しかし黄色い部分が偏りなく散らばっていて、遠目に見ると緑の中に金の粉を撒いたように見えた。"}, {"id": "ch08-s05-p010", "type": "text", "text": "数日前、桐ヶ谷さんとの帰り道でもこの木の下を歩いた。あの時は暗くて、葉の枚数まで確認しなかった。今夜は灯りの加減で少しだけ見える。確実に増えている。秋が進んでいる。"}, {"id": "ch08-s05-p011", "type": "text", "text": "足元に落ち葉があった。"}, {"id": "ch08-s05-p012", "type": "text", "text": "一枚拾った。黄色と緑の境目がくっきりしていた。境目の線は直線ではなく、葉脈に沿って入り組んでいる。色が変わるのは葉脈の末端からだった。末端が先に黄色くなり、幹に近い部分が最後まで緑を保つ。供給源に近い場所が最後まで生きている。歯車と同じ構造だった。動力源に近い部分が最後まで回る。"}, {"id": "ch08-s05-p013", "type": "text", "text": "落ち葉を元の場所に戻した。"}, {"id": "ch08-s05-p014", "type": "text", "text": "中庭を横切り、鐘鋳塔に向かう。北に見える白い石壁。残響灯の青白い光が外壁に滲んでいる。夜の鐘鋳塔。昼間より輪郭が柔らかい。光の線が外壁の残響紋を這い上がっている。四月の朝、霧の中で初めてこの塔を見た。六か月が経った。"}, {"id": "ch08-s05-p015", "type": "text", "text": "通用口の鍵を開けた。石段を上がる。足裏が石の冷たさを報告してくる。九月の石。この冷たさの温度は、体が覚え始めている。四月の石、六月の石、八月の石。それぞれ違った。季節の温度が足裏に蓄積されている。"}, {"id": "ch08-s05-p016", "type": "text", "text": "管理室に入った。"}, {"id": "ch08-s05-p017", "type": "text", "text": "巡回ではなく、今夜は点検のやり直しをする。第七系統の微振動数値を二日前に記録したが、再確認が必要だった。作業台に記録帳を広げ、ペンを取った。二日前の数値。0.0023Hz。許容範囲は0.0030Hz以下。問題はない。問題はないが、数値を見ていると落ち着く。"}, {"id": "ch08-s05-p018", "type": "text", "text": "ペンを置いた。"}, {"id": "ch08-s05-p019", "type": "text", "text": "記録帳の上に両手を載せた。指先が紙の端に触れている。残響灯の青白い光が手の甲を照らしている。"}, {"id": "ch08-s05-p020", "type": "text", "text": "この手で、燈花の名前を書いたことはない。声で呼んだだけだ。「燈花」。二文字。喫茶「残響」の油灯の下で、初めて呼んだ。燈花は笑った。目の奥に影がない笑顔だった。あの二文字を俺の口から出した時、肋骨の内側が温かくなった。温かさはまだ残っている。日が経っても薄れない。消えていない。"}, {"id": "ch08-s05-p021", "type": "text", "text": "肋骨の内側。"}, {"id": "ch08-s05-p022", "type": "text", "text": "鳩尾の上。"}, {"id": "ch08-s05-p023", "type": "text", "text": "鳴海さんの場所。「蓮さん」と呼ばれた。七月の灯籠通りで三回。夏期研修の帰りに一回。呼ばれるたびに鳩尾の少し上が反応する。きれいだと思った最初の日から、あの場所は鳴海さんに紐づいている。温かさが混じっている。八月の灯篭流しの夜、並んで歩いた時の温かさ。その温かさは「きれい」の中から出てきたのか、別のところから来たのか。まだわからない。わからないが、ある。"}, {"id": "ch08-s05-p024", "type": "text", "text": "耳。"}, {"id": "ch08-s05-p025", "type": "text", "text": "篠宮さんの場所。ペンの音。閉館間際の「ありがとうございます」。あの声は耳の中に収まっている。ペンの音が二つある記録室の静けさは、管理室で一人でいる時の静けさとは違う。冷たくない静けさ。篠宮さんは声量が小さい。小さい声を聞き取るために耳が少しだけ傾く。その傾きが習慣になっている。"}, {"id": "ch08-s05-p026", "type": "text", "text": "左手の甲。"}, {"id": "ch08-s05-p027", "type": "text", "text": "すみれの場所。天蓋の間で手を繋がれた。冷たかった。温まろうとしない冷たさ。「このせかいは、いつかおわるよ」。あの言葉が左手の甲に貼りついたまま、剥がれない。剥がそうとしたこともない。すみれの言葉は剥がすものではなく、そこにあるものだった。正確なものだった。正確なものが冷たいのは、温度ではなく精度の問題なのかもしれない。"}, {"id": "ch08-s05-p028", "type": "text", "text": "背中の奥。"}, {"id": "ch08-s05-p029", "type": "text", "text": "霜月さんの場所。「お前の着任以前の人事記録、確認させてもらった」。数日前の声がまだ背中の奥に残っている。コーヒーを出す手。「業務中の水分補給だ」と言いながら二人分の豆を挽く手間。霜月さんの不器用さ。その不器用さの中に、空白を「照合」する目があった。ラベンダーの瞳で俺の経歴を調べた人。背中の奥にある名前のない感覚は、数日経っても沈んだだけで消えていなかった。"}, {"id": "ch08-s05-p030", "type": "text", "text": "鳩尾の奥。"}, {"id": "ch08-s05-p031", "type": "text", "text": "桐ヶ谷さんの場所。「あまり深入りするな」。「守りたいだけだ」。「今は聞くな」。見晴らし丘の夕方から数日が経っている。桐ヶ谷さんの声はまだ鳩尾の奥にある。北を向いている。知りたいという方向。知りたいものの中身は、まだ見えない。しかし方向だけが残っている。磁針のように。ずっと北を向いたまま動かない。"}, {"id": "ch08-s05-p032", "type": "text", "text": "六つの場所。"}, {"id": "ch08-s05-p033", "type": "text", "text": "体の中に六つの場所がある。"}, {"id": "ch08-s05-p034", "type": "text", "text": "七月の終わり、布団の中で夏を振り返った夜は五つだった。目の奥、鳩尾の上、耳、左手の甲、背中の奥。五つに別々のものが入っていた。今は六つ目がある。鳩尾の奥。桐ヶ谷さんの声が入った場所。そして燈花の場所は目の奥から肋骨の内側に移った。名前を呼んでから変わった。目の奥の「眩しさ」は消えていない。消えていないが、肋骨の内側の温かさの方が近い。近い、という言い方が正確かわからない。けれど手を当てたら触れる距離にある。"}, {"id": "ch08-s05-p035", "type": "text", "text": "俺は、変わってきている。"}, {"id": "ch08-s05-p036", "type": "text", "text": "七月の夜、同じ問いを立てた。「変わったのだろうか」。体は明確に答えなかった。四月と同じではない、とだけ報告した。"}, {"id": "ch08-s05-p037", "type": "text", "text": "今夜は、問い方が違う。「変わったのだろうか」ではなく「変わってきている」。問いではなく報告。体がそう言っている。五か所だったものが六か所になっている。「温かいはずだ」と判断していた布団の温もりが「確認はいらない」に変わっている。「天城さん」が「燈花」になっている。"}, {"id": "ch08-s05-p038", "type": "text", "text": "変わっている。方向がある。"}, {"id": "ch08-s05-p039", "type": "text", "text": "前の俺は——記憶にない俺は、こういうことを感じていたのだろうか。"}, {"id": "ch08-s05-p040", "type": "text", "text": "椅子の背もたれに体を預けた。天井を見る。管理室の天井は石造りで、残響灯の光が表面の凹凸に影を作っている。補佐官舎の白い塗り壁の天井とは違う。けれど天井を見上げる角度は同じだった。"}, {"id": "ch08-s05-p041", "type": "text", "text": "記憶にない俺。二年前に縁際で目を覚ます前の俺。名前がなかった俺。あるいは——別の名前があった俺。朝霧蓮ではない名前で呼ばれていた俺。"}, {"id": "ch08-s05-p042", "type": "text", "text": "いたのだろうか。"}, {"id": "ch08-s05-p043", "type": "text", "text": "いたはずだ。人は名前なしでは生まれない。二年前に記憶を失う前の時間が、どこかにある。桐ヶ谷さんはそれを知っている。霜月さんはそれを調べている。二人の視線の先に、俺の空白がある。"}, {"id": "ch08-s05-p044", "type": "text", "text": "空白。"}, {"id": "ch08-s05-p045", "type": "text", "text": "四月から今まで、空白は気にならなかった。記憶がないことに不便はあっても、苦痛はなかった。名前がなければ自分でつければいい。経歴がなければ今から作ればいい。空白は空白のまま、その上に日常を置いた。歯車を回した。鐘の音を聴いた。それで足りていた。"}, {"id": "ch08-s05-p046", "type": "text", "text": "足りなくなった。"}, {"id": "ch08-s05-p047", "type": "text", "text": "数日前に気づいた。桐ヶ谷さんの前で。霜月さんの人事記録の後で。「知りたい」が鳩尾の奥に生まれて、消えなくなった。"}, {"id": "ch08-s05-p048", "type": "text", "text": "今夜、中庭の残響桜の落ち葉を拾った。葉脈の末端から色が変わっていた。供給源から遠い場所が先に変わる。俺の中で変わり始めているものも、末端から来たのかもしれない。燈花を名前で呼んだこと。鳴海さんに「蓮さん」と呼ばれたこと。篠宮さんの「ありがとうございます」。すみれの「せかいはおわる」。霜月さんの空白への目。桐ヶ谷さんの「守りたいだけだ」。全部末端だった。日常の末端で起きた小さな変化が、中心に向かって浸透していって、今——俺は初めて、自分の過去に関心を持っている。"}, {"id": "ch08-s05-p049", "type": "text", "text": "関心。"}, {"id": "ch08-s05-p050", "type": "text", "text": "この言葉で合っているだろうか。「知りたい」は感情の名前ではなく方向の名前だと、数日前に思った。今はもう少し何かがある。方向だけではない。鳩尾の奥が北を向いているだけではない。北を向いている理由を、探そうとしている。なぜ北なのか。なぜ蝕域の方角なのか。俺の空白と蝕域の間に何があるのか。"}, {"id": "ch08-s05-p051", "type": "text", "text": "わからない。まだわからない。"}, {"id": "ch08-s05-p052", "type": "text", "text": "けれど——問いが生まれている。空白を空白のまま受け入れていた俺の中に、問いが芽を出している。"}, {"id": "ch08-s05-p053", "type": "text", "text": "記録帳を閉じた。"}, {"id": "ch08-s05-p054", "type": "text", "text": "ペンをインク壺の横に戻した。立ち上がり、管理室の窓を開けた。夜風が入ってくる。九月の夜風。乾いていて、冷えていて、遠くの虫の音を運んでいる。秋の虫。鈴虫だろうか。断続的な高い音。八月の夜に聞いた「夏と秋の間の虫」よりも、秋に寄っている。季節が進んだ。"}, {"id": "ch08-s05-p055", "type": "text", "text": "窓から顔を出した。中庭の暗がりの中に残響桜の輪郭がある。黄色い葉が灯籠の光を拾って、夜の中に点々と光っている。その向こうに教室棟の屋根。屋根の向こうに空。星が出ていた。九月の星は八月より白い。空気が澄んだぶん、光の粒が鋭い。"}, {"id": "ch08-s05-p056", "type": "text", "text": "二十時の鐘が、鳴った。"}, {"id": "ch08-s05-p057", "type": "text", "text": "足の下から来た。"}, {"id": "ch08-s05-p058", "type": "text", "text": "管理室は鐘鋳塔の二階にある。鐘の機構は上階にある。しかし音は上からだけでなく、塔全体を伝って来る。壁面の残響紋が音を増幅し、石と金属の両方を振動させる。足の裏。椅子の座面。窓枠。管理室の全てが鐘の周波数で共振している。"}, {"id": "ch08-s05-p059", "type": "text", "text": "低い一打。"}, {"id": "ch08-s05-p060", "type": "text", "text": "体の中を通り過ぎていく。四月の朝、鐘鋳塔の前で初めて聴いた時と同じ。胸骨に触れて、指先に抜けていく。音の粒が骨を伝って全身に拡がる。"}, {"id": "ch08-s05-p061", "type": "text", "text": "心地よい。"}, {"id": "ch08-s05-p062", "type": "text", "text": "そう思った。次の瞬間、もう一つ別のものが来た。"}, {"id": "ch08-s05-p063", "type": "text", "text": "懐かしい。"}, {"id": "ch08-s05-p064", "type": "text", "text": "四月にも「懐かしい」と思った。あの時は困惑した。記憶にないものを懐かしいと思えるのか。思えるのだとしたら、それは記憶ではなくもっと深いどこかにある何かが反応しているのか。答えは出なかった。困惑だけが残った。"}, {"id": "ch08-s05-p065", "type": "text", "text": "今夜の「懐かしい」は、困惑ではなかった。"}, {"id": "ch08-s05-p066", "type": "text", "text": "鐘の二打目が鳴った。音が重なった。空気が厚くなった。窓の外の残響桜の葉が振動で揺れた。黄色い葉が夜風の中で震えた。"}, {"id": "ch08-s05-p067", "type": "text", "text": "懐かしい。"}, {"id": "ch08-s05-p068", "type": "text", "text": "困惑がないのはなぜだろう。"}, {"id": "ch08-s05-p069", "type": "text", "text": "四月は「記憶にないものを懐かしいと思えるのか」と問うた。その問いはまだ解けていない。解けていないのに、困惑が消えている。代わりにあるのは——もっと広い何か。「知りたい」と同じ方角を向いている何か。鳩尾の奥で北を向いているものと、鐘の音の「懐かしさ」が、同じ場所から来ている。"}, {"id": "ch08-s05-p070", "type": "text", "text": "鐘の三打目。四打目。五打目。"}, {"id": "ch08-s05-p071", "type": "text", "text": "音の層が積み重なっていく。管理室の空気が振動で満ちる。残響灯が淡く明滅している。外壁の残響紋が蒼白い線を走らせている。"}, {"id": "ch08-s05-p072", "type": "text", "text": "目を閉じた。"}, {"id": "ch08-s05-p073", "type": "text", "text": "鐘の音を聴いている。いつもそうしている。四月から六か月間、毎日八回、この音を聴いてきた。一日も欠かさず。心地よかった。ずっと心地よかった。"}, {"id": "ch08-s05-p074", "type": "text", "text": "今夜は心地よさの下に、もう一層ある。"}, {"id": "ch08-s05-p075", "type": "text", "text": "懐かしさ。"}, {"id": "ch08-s05-p076", "type": "text", "text": "記憶にはない場所の音。記憶にはない時間の振動。俺の体のどこかが、この音を「知っている」と報告している。歯車の適正値を手が知っているのと同じ構造。知っている。理由はわからない。わからないけれど、知っている。"}, {"id": "ch08-s05-p077", "type": "text", "text": "鐘の音が知っている場所は、俺の空白の中にある。"}, {"id": "ch08-s05-p078", "type": "text", "text": "五分間の鐘打ちが終わった。"}, {"id": "ch08-s05-p079", "type": "text", "text": "最後の余韻が長い尾を引いて、管理室の壁を伝い、窓から外に出ていった。虫の音が戻ってきた。秋の虫。鈴の音のような断続的な響き。鐘の余韻と虫の音が一瞬だけ重なって、離れた。"}, {"id": "ch08-s05-p080", "type": "text", "text": "目を開けた。"}, {"id": "ch08-s05-p081", "type": "text", "text": "管理室の残響灯が通常の明るさに戻っていた。計器の針が安定値を指している。第三系統の出力。第七系統の微振動。数値は日常のまま変わっていない。"}, {"id": "ch08-s05-p082", "type": "text", "text": "俺の中だけが変わっている。"}, {"id": "ch08-s05-p083", "type": "text", "text": "窓を閉めた。記録帳を棚に戻した。ペンのキャップを確認した。作業台の上を整えた。管理室を出て、階段を降りた。石段の冷たさが足裏に来る。九月の石。覚えている温度。"}, {"id": "ch08-s05-p084", "type": "text", "text": "通用口の鍵を閉めた。"}, {"id": "ch08-s05-p085", "type": "text", "text": "中庭を横切った。残響桜の下を通った。落ち葉が足元で鳴った。乾いた葉を踏む音。四月にはなかった音。薄紫の花弁を踏んでも音はしなかった。秋の落ち葉は音がする。乾いているから。枯れているから。"}, {"id": "ch08-s05-p086", "type": "text", "text": "補佐官舎に向かって歩きながら、空を見上げた。"}, {"id": "ch08-s05-p087", "type": "text", "text": "星が出ている。九月の星。白い光の粒。すみれが天蓋の間で数えている星と同じものだろう。同じ星を何度も数え直してしまうすみれ。時間の感覚がずれている少女。すみれなら——鐘の音の「懐かしさ」について、何か知っているかもしれない。「かねが、おしえてくれた」と四月に言った少女。"}, {"id": "ch08-s05-p088", "type": "text", "text": "官舎に着いた。鍵を開け、靴を脱いだ。"}, {"id": "ch08-s05-p089", "type": "text", "text": "部屋に入った。机の上に残響祭の花弁がある。褐色に変わって形だけが残っている。四月の花の痕跡。この花弁も、俺の空白と同じだ。形はある。色は抜けた。けれど在る。"}, {"id": "ch08-s05-p090", "type": "text", "text": "着替えた。歯を磨いた。ベッドに座った。"}, {"id": "ch08-s05-p091", "type": "text", "text": "窓の外。鐘鋳塔の灯り。青白い残響灯の光が夜の中に立っている。あの塔の中で、さっき鐘の音を聴いた。心地よさと懐かしさが重なった場所。"}, {"id": "ch08-s05-p092", "type": "text", "text": "秋の空気が変わった。夏の終わりの空気とは違う。七月の夜、布団の中で「秋が来る」と感じた。秋は来た。来て、空気の温度を変え、桜の葉を変え、虫の声を変え、空の色を変えた。"}, {"id": "ch08-s05-p093", "type": "text", "text": "俺の中も変わった。五か所が六か所になった。「変わったのだろうか」が「変わってきている」になった。空白の上に置いた日常の末端から、変化が浸透してきて、今——空白そのものに、手を伸ばそうとしている。"}, {"id": "ch08-s05-p094", "type": "text", "text": "鐘の余韻は、もう聞こえない。"}, {"id": "ch08-s05-p095", "type": "text", "text": "けれど体の中に残っている。懐かしさとして。四月にはそれを困惑と呼んだ。今夜は困惑ではない。もっと深い場所からの報告。俺がまだ知らない俺の一部からの、返信。"}, {"id": "ch08-s05-p096", "type": "text", "text": "覚えておく。"}, {"id": "ch08-s05-p097", "type": "text", "text": "この夜の秋の空気。落ち葉の音。鐘の音の懐かしさ。そして、空白に向かって芽を出し始めた問いを。"}]}, {"chapter": 9, "chapterTitle": "記録室の静寂", "scene": 1, "sceneTitle": "消えた人々の声", "wordCount": "約5,800字", "paragraphs": [{"id": "ch09-s01-p001", "type": "text", "text": "ペンの音が二つある。"}, {"id": "ch09-s01-p002", "type": "text", "text": "記録室の空気は九月の午後の温度だった。窓から入る光は橙ではなく、白と黄色の中間。太陽がまだ高い時間帯の光。十六時。放課後の図書館。一階では書架の間を生徒が歩く音がして、二階のこの奥には届かない。"}, {"id": "ch09-s01-p003", "type": "text", "text": "かりかり。かりかり。"}, {"id": "ch09-s01-p004", "type": "text", "text": "俺のペンの間隔と、篠宮さんのペンの間隔。どちらも途切れない。交互に隙間を埋め合う。沈黙が来ない。"}, {"id": "ch09-s01-p005", "type": "text", "text": "清書を始めてから二十分ほど経っていた。今日の下書きは中円区北部の消滅者記録。三枚。名前、年齢、最終確認日、場所、備考。いつもの形式。いつもの作業。四月の終わりに「手伝いましょうか」と言ってから五か月が過ぎている。木箱の座面の硬さも、机の右寄りのインク壺も、ペン先が紙を引っ掻く感触も、体が迷わず受け入れる場所になった。"}, {"id": "ch09-s01-p006", "type": "text", "text": "一枚目を終えて、二枚目に手を伸ばした。"}, {"id": "ch09-s01-p007", "type": "text", "text": "篠宮さんのペンが止まった。"}, {"id": "ch09-s01-p008", "type": "text", "text": "音が一つ減った。俺のペンの音だけになった。"}, {"id": "ch09-s01-p009", "type": "text", "text": "顔を上げた。"}, {"id": "ch09-s01-p010", "type": "text", "text": "篠宮さんがメモ帳を閉じていた。手が膝の上にある。いつもの作業の区切りの姿勢に似ているが、視線の先が違った。机の上でもメモ帳でもなく、棚の引き出しを見ている。二段目の引き出し。いつも清書した用紙を収めている場所。"}, {"id": "ch09-s01-p011", "type": "text", "text": "「朝霧さん」"}, {"id": "ch09-s01-p012", "type": "text", "text": "声は平坦だった。いつもの篠宮さんの音量。壁に届かない程度の声。"}, {"id": "ch09-s01-p013", "type": "text", "text": "「今日は、清書の代わりに……聴いていただきたいものがあります」"}, {"id": "ch09-s01-p014", "type": "text", "text": "聴く。"}, {"id": "ch09-s01-p015", "type": "text", "text": "清書ではなく。"}, {"id": "ch09-s01-p016", "type": "text", "text": "ペンを置いた。インク壺の横に戻す。手が空いた状態で、篠宮さんの方を向いた。"}, {"id": "ch09-s01-p017", "type": "text", "text": "篠宮さんが引き出しを開けた。中から厚紙の表紙のついた帳面を取り出した。表紙は焦茶色で、角が擦れている。メモ帳とは違う。サイズが大きい。B5ほどの紙が綴じられていて、表紙に篠宮さんの字で「消滅者記録 詳細版」と書かれていた。"}, {"id": "ch09-s01-p018", "type": "text", "text": "見たことのない帳面だった。清書の下書きはいつもメモ帳から転記している。この「詳細版」は、棚の引き出しの中にあったはずだが、俺の前に出てきたことは一度もなかった。"}, {"id": "ch09-s01-p019", "type": "text", "text": "篠宮さんが帳面を机の上に開いた。最初のページではなく、途中のページ。付箋が挟まっていた。二枚。"}, {"id": "ch09-s01-p020", "type": "text", "text": "「この帳面には、消滅者の方々の……記録の中でも、生活の記録を書いています」"}, {"id": "ch09-s01-p021", "type": "text", "text": "生活の記録。"}, {"id": "ch09-s01-p022", "type": "text", "text": "「名前と年齢と最終確認日だけでは、その人がどう暮らしていたかが残りません。近隣住民の証言や、管理局の聞き取り資料から、可能な限り……日常を、復元しています」"}, {"id": "ch09-s01-p023", "type": "text", "text": "篠宮さんの指が帳面のページを押さえている。几帳面な字が並んでいる。いつもの清書と同じ精度。行間が揃い、文字の大きさが均一。ただし分量が違った。一人分の記録が、一ページの半分を超えている。"}, {"id": "ch09-s01-p024", "type": "text", "text": "「読み聞かせる、ということですか」"}, {"id": "ch09-s01-p025", "type": "text", "text": "「はい」"}, {"id": "ch09-s01-p026", "type": "text", "text": "間。"}, {"id": "ch09-s01-p027", "type": "text", "text": "「朝霧さんに……知っていただきたくて」"}, {"id": "ch09-s01-p028", "type": "text", "text": "篠宮さんの視線が帳面の上にあった。声は平坦なまま。けれど「知っていただきたくて」の「て」が、いつもの語尾より長かった。半拍だけ。半拍の「て」の中に、何が入っていたのか。俺には読み取れなかった。"}, {"id": "ch09-s01-p029", "type": "text", "text": "「聴きます」"}, {"id": "ch09-s01-p030", "type": "text", "text": "篠宮さんの瞬きが入った。一回。長くはない。通常の瞬き。"}, {"id": "ch09-s01-p031", "type": "text", "text": "帳面を手に取った。両手で持ち上げて、読む角度に傾けた。"}, {"id": "ch09-s01-p032", "type": "text", "text": "「これは、中円区に住んでいた老夫婦の記録です」"}, {"id": "ch09-s01-p033", "type": "text", "text": "声が変わった。平坦なまま変わった。矛盾した言い方になるが、そうとしか表現できない。篠宮さんの声はいつも平坦だった。今の声も平坦だった。けれど、質が違う。「朝霧さん」と呼ぶ時の声でも、「閉館です」と告げる時の声でもない。帳面を読む声。記録を声に乗せる声。"}, {"id": "ch09-s01-p034", "type": "text", "text": "「夫は花屋を営んでいました。妻は毎朝、夫の作った花束を窓辺に飾っていました。花屋の名前は『風花』。中円市場の東側、煉瓦通りに面した二間口の店です。夫は朝五時から仕入れに出かけ、妻は店の前を箒で掃いてから看板を出していました」"}, {"id": "ch09-s01-p035", "type": "text", "text": "篠宮さんの読み方は朗読ではなかった。抑揚がほとんどない。声量は記録室の空気に合わせた最低限。句読点の後に正確な間を置く。記録係が記録を読む声。それだけ。"}, {"id": "ch09-s01-p036", "type": "text", "text": "それだけなのに、花屋の朝が見えた。"}, {"id": "ch09-s01-p037", "type": "text", "text": "五時に仕入れに出る夫。箒を持つ妻。煉瓦通り。二間口の店。篠宮さんの声が事実を一つずつ積んでいくだけで、朝の光が差す通りの匂いが——嗅いだことのない匂いが、想像の中に立ち上がった。"}, {"id": "ch09-s01-p038", "type": "text", "text": "「3年前の縁蝕波で消滅。記録は近隣住民の証言をもとに再構成」"}, {"id": "ch09-s01-p039", "type": "text", "text": "最後の一文で、花屋の朝が断ち切られた。"}, {"id": "ch09-s01-p040", "type": "text", "text": "篠宮さんがページをめくった。"}, {"id": "ch09-s01-p041", "type": "text", "text": "次の記録。"}, {"id": "ch09-s01-p042", "type": "text", "text": "「外円区東部、港町の造船工。52歳。妻と息子が一人。息子は学院に入学予定でした。造船工は毎月第三日曜に完成した船の進水式を行い、そのたびに近隣の子供たちに飴を配っていました。最終確認日は進水式の翌日。工房の中に完成直前の船が残されていました」"}, {"id": "ch09-s01-p043", "type": "text", "text": "完成直前の船。飴を配る進水式。第三日曜。"}, {"id": "ch09-s01-p044", "type": "text", "text": "「4年前の縁蝕波で消滅。工房は現在も残存。船は造りかけのまま朽ちています」"}, {"id": "ch09-s01-p045", "type": "text", "text": "ページがめくられた。"}, {"id": "ch09-s01-p046", "type": "text", "text": "三つ目の記録。"}, {"id": "ch09-s01-p047", "type": "text", "text": "「内円区南端、鐘鋳職人見習い。24歳。独身。鐘鋳塔の下層部で金属加工の訓練を受けていました。休日には灯籠通りの古道具屋で時計の部品を集め、自作の振り子時計を組み立てていました。完成品は一台。師匠に贈る予定だったと同僚が証言しています」"}, {"id": "ch09-s01-p048", "type": "text", "text": "鐘鋳職人。自作の振り子時計。師匠への贈り物。"}, {"id": "ch09-s01-p049", "type": "text", "text": "聴いていた。"}, {"id": "ch09-s01-p050", "type": "text", "text": "篠宮さんの声は淡々としていた。一人目も二人目も三人目も、同じ音量、同じ速度、同じ間隔で読まれた。感情を乗せていない声。乗せていないのに——一つ一つの記録が、消えた人間の輪郭を持っていた。花を窓辺に飾った妻。飴を配った造船工。時計を組んだ見習い。篠宮さんの声がそこに「いた」という事実を証明している。声に感情がないからこそ、記録が記録のまま届く。篠宮さんの声は記録を歪めない。"}, {"id": "ch09-s01-p051", "type": "text", "text": "四つ目。五つ目。六つ目。"}, {"id": "ch09-s01-p052", "type": "text", "text": "ページがめくられるたびに、消えた人間が一人ずつ現れて、記録の最後の一行で消えた。現れる速度と消える速度が同じだった。篠宮さんの声の中で、その人が生きていた時間が圧縮されて、数行分の長さになって、語り終えた瞬間に閉じる。繰り返し。"}, {"id": "ch09-s01-p053", "type": "text", "text": "俺は黙って聴いていた。"}, {"id": "ch09-s01-p054", "type": "text", "text": "七つ目の記録を読み終えた後、篠宮さんがページをめくる手が止まった。"}, {"id": "ch09-s01-p055", "type": "text", "text": "付箋が挟まっていた。二枚目の付箋。"}, {"id": "ch09-s01-p056", "type": "text", "text": "間。"}, {"id": "ch09-s01-p057", "type": "text", "text": "長い間だった。篠宮さんの間は普段から長い。今日の読み聞かせの間も長かった。けれどこの間は——それまでの間とは違った。ページをめくろうとして、止まっている。指がページの端を挟んだまま、紙を持ち上げていない。"}, {"id": "ch09-s01-p058", "type": "text", "text": "「次の記録は」"}, {"id": "ch09-s01-p059", "type": "text", "text": "声が出た。平坦。だが間に入る前の「は」の音が、わずかにかすれた。"}, {"id": "ch09-s01-p060", "type": "text", "text": "篠宮さんがページをめくった。"}, {"id": "ch09-s01-p061", "type": "text", "text": "「外円区の小さな町に住んでいた少女の記録です」"}, {"id": "ch09-s01-p062", "type": "text", "text": "声。"}, {"id": "ch09-s01-p063", "type": "text", "text": "篠宮さんの声。"}, {"id": "ch09-s01-p064", "type": "text", "text": "変わった。"}, {"id": "ch09-s01-p065", "type": "text", "text": "平坦なまま変わった。さっきと同じ矛盾。音量は変わらない。速度も変わらない。間隔も正確なまま。変わっていないのに——声の底の部分が、震えている。"}, {"id": "ch09-s01-p066", "type": "text", "text": "水面のような震え。表面は静かで、底の方で何かが揺れている。耳を傾けなければわからないほど小さな震え。俺の耳は傾いていた。五か月前から、篠宮さんの声を聴き取るために少しだけ傾いている耳。"}, {"id": "ch09-s01-p067", "type": "text", "text": "「推定年齢14歳。物静かな性格で、本が好きだったと、近隣住民が証言しています。学院への入学を控えていました。父と母の三人暮らし。父は——」"}, {"id": "ch09-s01-p068", "type": "text", "text": "篠宮さんの声が止まった。"}, {"id": "ch09-s01-p069", "type": "text", "text": "止まった、のではなく——声の奥の震えが、表面まで上がってきた。「父は」の「は」の音で、唇が一瞬だけ不安定になった。すぐに戻った。篠宮さんの唇は元の形に戻り、声は続いた。"}, {"id": "ch09-s01-p070", "type": "text", "text": "「父は木工を営み、母は裁縫で生計を助けていました。少女の部屋には本棚があり、年齢の割に冊数が多かったと記録されています。83冊。そのうち40冊以上が図鑑や記録集のたぐいでした」"}, {"id": "ch09-s01-p071", "type": "text", "text": "83冊。40冊以上が図鑑や記録集。"}, {"id": "ch09-s01-p072", "type": "text", "text": "14歳の少女の本棚に、図鑑と記録集が並んでいる。"}, {"id": "ch09-s01-p073", "type": "text", "text": "「少女は、消滅する町の最後の日、自分のノートに何かを書いていたと、避難途中に町を通過した旅商人が証言しています。ノートは発見されていません」"}, {"id": "ch09-s01-p074", "type": "text", "text": "最後まで、書いていた。"}, {"id": "ch09-s01-p075", "type": "text", "text": "「3年前の大規模縁蝕波で、町ごと消滅。少女を含む住民約240名の消滅が確認されています」"}, {"id": "ch09-s01-p076", "type": "text", "text": "声が終わった。"}, {"id": "ch09-s01-p077", "type": "text", "text": "篠宮さんの手が帳面を持ったまま動かなかった。ページの上に視線がある。墨色の瞳が文字の上を動いていない。読み終わっているのに、目が離れない。"}, {"id": "ch09-s01-p078", "type": "text", "text": "記録室が静かだった。ペンの音がない。二人とも書いていない。窓の外から微かに風の音が聞こえるだけ。"}, {"id": "ch09-s01-p079", "type": "text", "text": "俺は篠宮さんの横顔を見ていた。"}, {"id": "ch09-s01-p080", "type": "text", "text": "表情は変わっていなかった。表情の振幅が極めて少ない篠宮さんの、いつも通りの顔。けれど——首の銀の鍵が、揺れていた。呼吸に合わせて。いつもより振幅が大きい。呼吸が深くなっている。"}, {"id": "ch09-s01-p081", "type": "text", "text": "そして、帳面を持つ手の——右手の、小指の付け根あたりに、かすかな力が入っていた。帳面を持つのに必要な以上の力。紙を握りこむほどではない。けれど指の関節がわずかに白くなっている。"}, {"id": "ch09-s01-p082", "type": "text", "text": "「篠宮さん」"}, {"id": "ch09-s01-p083", "type": "text", "text": "呼んだ。"}, {"id": "ch09-s01-p084", "type": "text", "text": "篠宮さんの瞬きが入った。"}, {"id": "ch09-s01-p085", "type": "text", "text": "「この記録を読む時だけ、声が違う」"}, {"id": "ch09-s01-p086", "type": "text", "text": "言った。"}, {"id": "ch09-s01-p087", "type": "text", "text": "聴こえたものをそのまま口に出した。七つの記録を聴いた。花屋の夫婦。造船工。鐘鋳職人。全て同じ声で読まれた。八つ目だけが違った。底の方で震えていた。「父は」で唇が揺れた。帳面を持つ手に力が入った。呼吸が変わった。"}, {"id": "ch09-s01-p088", "type": "text", "text": "耳が聴き取ったものを、俺は言葉にした。"}, {"id": "ch09-s01-p089", "type": "text", "text": "篠宮さんが動きを止めた。"}, {"id": "ch09-s01-p090", "type": "text", "text": "全身が止まった。帳面を持つ手。膝の上のもう一方の手。首の銀の鍵。全てが一斉に止まった。瞬きも止まった。"}, {"id": "ch09-s01-p091", "type": "text", "text": "五秒。"}, {"id": "ch09-s01-p092", "type": "text", "text": "長い五秒だった。記録室の中で、風の音だけが鳴っていた。"}, {"id": "ch09-s01-p093", "type": "text", "text": "「……気のせいです」"}, {"id": "ch09-s01-p094", "type": "text", "text": "声が出た。"}, {"id": "ch09-s01-p095", "type": "text", "text": "平坦だった。いつもの篠宮さんの声に戻っていた。もう震えはなかった。底の方の揺れが、言葉と一緒に沈んでいた。"}, {"id": "ch09-s01-p096", "type": "text", "text": "篠宮さんの瞬きが再開した。帳面を静かに閉じた。両手で背表紙を押さえて、机の上に置いた。"}, {"id": "ch09-s01-p097", "type": "text", "text": "「どの記録も、同じように読んでいます。特別な意味は、ありません」"}, {"id": "ch09-s01-p098", "type": "text", "text": "声は正確だった。句読点の後に正確な間を置く、いつもの話し方。"}, {"id": "ch09-s01-p099", "type": "text", "text": "嘘をついている、とは思わなかった。"}, {"id": "ch09-s01-p100", "type": "text", "text": "篠宮さんは嘘をつかない。記録係は記録を歪めない。篠宮さんが「気のせいです」と言うのは、篠宮さん自身がそう認識しているからだった。声が震えたことに気づいていない。あるいは気づいていても、その理由がわからない。わからないから「気のせい」としか答えられない。"}, {"id": "ch09-s01-p101", "type": "text", "text": "3年前の縁蝕波。外円区の小さな町。14歳の少女。本が好きで、図鑑と記録集を83冊持っていて、最後の日にノートに何かを書いていた。"}, {"id": "ch09-s01-p102", "type": "text", "text": "篠宮さんの指が帳面の表紙の上で止まっている。指先が表紙の角を撫でている。無意識の動作。"}, {"id": "ch09-s01-p103", "type": "text", "text": "この人は、何かを抱えている。"}, {"id": "ch09-s01-p104", "type": "text", "text": "それは——3年前の記録を書いていた時のペンの硬い音と同じ場所から来ていた。五月の、あの日。3年前の記録だけ異様に筆圧が変わったこと。線の始まりに力が入っていたこと。あの時も深追いしなかった。"}, {"id": "ch09-s01-p105", "type": "text", "text": "今も追わない。"}, {"id": "ch09-s01-p106", "type": "text", "text": "けれど、聴こえたものは聴こえた。耳の中にある。篠宮さんの声の震えが、鼓膜の奥に沈んでいる。消えない。篠宮さんが「気のせい」と言っても、俺の耳が記録したものは消えない。"}, {"id": "ch09-s01-p107", "type": "text", "text": "「聴かせてくれて、ありがとうございます」"}, {"id": "ch09-s01-p108", "type": "text", "text": "言った。今回は遅れなかった。"}, {"id": "ch09-s01-p109", "type": "text", "text": "篠宮さんの瞬きが入った。一回。"}, {"id": "ch09-s01-p110", "type": "text", "text": "「……いいえ」"}, {"id": "ch09-s01-p111", "type": "text", "text": "短い否定。いつもの応答。"}, {"id": "ch09-s01-p112", "type": "text", "text": "篠宮さんが帳面を引き出しに戻した。メモ帳を取り出して、新しいページを開いた。ペンを持った。インクをつけた。紙の上にペン先が降りた。"}, {"id": "ch09-s01-p113", "type": "text", "text": "かりかり。"}, {"id": "ch09-s01-p114", "type": "text", "text": "俺もペンを取った。二枚目の清書に戻った。"}, {"id": "ch09-s01-p115", "type": "text", "text": "かりかり。"}, {"id": "ch09-s01-p116", "type": "text", "text": "二つのペンの音が記録室に戻った。いつもの音。いつもの間隔。窓から入る光はまだ黄色みを帯びている。十六時半にはなっていない。"}, {"id": "ch09-s01-p117", "type": "text", "text": "ペンを動かしながら、消えた人々のことを考えていた。"}, {"id": "ch09-s01-p118", "type": "text", "text": "花屋の老夫婦。毎朝窓辺に飾られた花束。造船工の飴。振り子時計。本が好きだった少女。83冊の本棚。"}, {"id": "ch09-s01-p119", "type": "text", "text": "篠宮さんはこの記録を一人で書いてきた。23冊のメモ帳に。清書の下書きとして俺が転記してきたのは、名前と年齢と日付だけだった。生活の記録——花束のこと、飴のこと、本棚のこと——はあの帳面の中にあった。引き出しの中に。俺の知らない場所に。"}, {"id": "ch09-s01-p120", "type": "text", "text": "今日、篠宮さんはそれを出してきた。読み聞かせた。俺に。"}, {"id": "ch09-s01-p121", "type": "text", "text": "なぜ今日なのか。なぜ俺に。聞かなかった。聞く必要はなかった。篠宮さんの「知っていただきたくて」が理由の全てだった。それ以上を問う言葉は持っていない。"}, {"id": "ch09-s01-p122", "type": "text", "text": "ペンの音。紙の音。風の音。"}, {"id": "ch09-s01-p123", "type": "text", "text": "この三つの音が記録室を満たしている。いつもの三つ。篠宮さんのペンと俺のペンと、窓の向こうの空気。"}, {"id": "ch09-s01-p124", "type": "text", "text": "静かだった。静かで、冷たくない。"}, {"id": "ch09-s01-p125", "type": "text", "text": "ここにいることに理由がいらない。五か月前からずっとそうだった。今日も変わらない。清書の代わりに声を聴いた。声の中に震えがあった。篠宮さんは気づいていない。俺は気づいた。それだけのことだ。"}, {"id": "ch09-s01-p126", "type": "text", "text": "それだけのことが、耳の奥に残っている。"}, {"id": "ch09-s01-p127", "type": "text", "text": "ペンを持つ手は動いている。清書は進む。二枚目の半分まで来た。名前を書いた。年齢を書いた。消えた人の記録を、この記録室で書いている。隣で篠宮さんが同じことをしている。"}, {"id": "ch09-s01-p128", "type": "text", "text": "俺は「気のせい」を信じない。"}, {"id": "ch09-s01-p129", "type": "text", "text": "篠宮さんが「気のせい」だと思っていることは、信じる。篠宮さんは嘘をついていない。けれど篠宮さんが自分で気づいていないものを、俺の耳は聴いた。声の底の震え。帳面を持つ手の力。呼吸の変化。どれも篠宮さん自身には見えていない場所で起きたこと。"}, {"id": "ch09-s01-p130", "type": "text", "text": "この人は、知らないうちに何かに反応している。3年前の記録に。外円区の少女に。"}, {"id": "ch09-s01-p131", "type": "text", "text": "それが何を意味するのか、俺にはわからない。わからないが、聴こえたものは保管する。耳の奥に。篠宮さんの場所に。"}, {"id": "ch09-s01-p132", "type": "text", "text": "十七時の鐘が鳴った。"}, {"id": "ch09-s01-p133", "type": "text", "text": "鐘鋳塔の方角から、低い響きが図書館の壁を通り抜けて、記録室に入ってきた。残響が長く伸びる。ペンの音が一瞬止まって、また始まる。鐘の音とペンの音が重なる。"}, {"id": "ch09-s01-p134", "type": "text", "text": "篠宮さんが顔を上げた。"}, {"id": "ch09-s01-p135", "type": "text", "text": "「十七時です」"}, {"id": "ch09-s01-p136", "type": "text", "text": "俺も顔を上げた。篠宮さんの墨色の瞳がこちらを見ていた。表情は変わっていない。いつもの篠宮さんの顔。"}, {"id": "ch09-s01-p137", "type": "text", "text": "けれど、唇の端に——さっきの読み聞かせの前にはなかったものが、あった。何と呼ぶのかはわからない。力が抜けた後の形、とでも言えばいいのか。緊張していた部分が緩んだ痕跡。篠宮さんの表情の中で最も微細な変化が、唇の端にだけ残っていた。"}, {"id": "ch09-s01-p138", "type": "text", "text": "「……ありがとうございました。聴いていただいて」"}, {"id": "ch09-s01-p139", "type": "text", "text": "声は平坦だった。平坦だが、今日この部屋に来た時の篠宮さんの声より、ほんの少しだけ近い場所から聞こえた。音量が変わったのではない。声の出どころが、胸の少し手前に移った——ような気がした。"}, {"id": "ch09-s01-p140", "type": "text", "text": "気がしただけかもしれない。"}, {"id": "ch09-s01-p141", "type": "text", "text": "「また聴かせてください」"}, {"id": "ch09-s01-p142", "type": "text", "text": "言った。考える前に出ていた。清書の代わりに声を聴く時間は、悪くなかった。悪くなかったどころか、消えた人々の輪郭が今も耳の中にある。花屋の花束が、造船工の飴が、少女の83冊が。篠宮さんの声が運んできたもの。"}, {"id": "ch09-s01-p143", "type": "text", "text": "篠宮さんの瞬きが止まった。"}, {"id": "ch09-s01-p144", "type": "text", "text": "二秒。三秒。"}, {"id": "ch09-s01-p145", "type": "text", "text": "「……はい」"}, {"id": "ch09-s01-p146", "type": "text", "text": "声が小さかった。壁に届かない声よりさらに小さい。俺と篠宮さんの間の空気だけを振動させる音量。"}, {"id": "ch09-s01-p147", "type": "text", "text": "ペンをインク壺の横に置いた。清書した用紙を揃えて渡した。篠宮さんの指が紙の端に触れた。一行ずつ確認して、引き出しに収めた。いつもの動作。"}, {"id": "ch09-s01-p148", "type": "text", "text": "立ち上がった。木箱から腰を上げる。"}, {"id": "ch09-s01-p149", "type": "text", "text": "「では、また明日」"}, {"id": "ch09-s01-p150", "type": "text", "text": "篠宮さんが頷いた。顎が一センチほど下がって、戻る。いつもの頷き。"}, {"id": "ch09-s01-p151", "type": "text", "text": "記録室を出た。書架の間を歩く。階段を降りる。受付の前を通り、図書館の扉を開けた。"}, {"id": "ch09-s01-p152", "type": "text", "text": "九月の午後の空気が顔に触れた。夏の湿気が抜けた後の、乾いた空気。残響桜の葉が風に揺れている。黄色い葉の割合が前よりも増えていた。"}, {"id": "ch09-s01-p153", "type": "text", "text": "歩きながら、耳が篠宮さんの声を探していた。"}, {"id": "ch09-s01-p154", "type": "text", "text": "聞こえるはずのない距離。わかっている。何度目かの反復。図書館を出た後に耳が探すもの。"}, {"id": "ch09-s01-p155", "type": "text", "text": "今日は——ペンの音ではなかった。"}, {"id": "ch09-s01-p156", "type": "text", "text": "篠宮さんの、少女の記録を読む声。底の方で震えていた声。「父は」で一瞬だけ揺れた唇。「気のせいです」と答えた、正直な声。"}, {"id": "ch09-s01-p157", "type": "text", "text": "全部、耳の中にある。"}, {"id": "ch09-s01-p158", "type": "text", "text": "覚えておく。"}]}, {"chapter": 9, "chapterTitle": "記録室の静寂", "scene": 2, "sceneTitle": "ルミエラ島", "wordCount": "約5,200字", "paragraphs": [{"id": "ch09-s02-p001", "type": "text", "text": "階段を降りている。"}, {"id": "ch09-s02-p002", "type": "text", "text": "図書館一階の受付横にある扉を開け、石の階段を下った先に地下書庫がある。十段ほどの階段。幅が狭く、二人並んで歩くには足りない。俺が先に降りて、篠宮さんが後ろについてくる。足音が石の壁に反響して、二人分の靴底の音が四つ五つに増えて聞こえた。"}, {"id": "ch09-s02-p003", "type": "text", "text": "地下の空気が変わった。冷たい。九月の地上よりも、ずっと。湿った紙の匂いと、古い埃と、石の壁から滲む水の気配。残響灯が等間隔に壁に嵌め込まれているが、記録室のものより弱い。青白い光が薄く伸びて、棚の端から先は影に呑まれている。"}, {"id": "ch09-s02-p004", "type": "text", "text": "「ここが地下書庫です」"}, {"id": "ch09-s02-p005", "type": "text", "text": "篠宮さんの声が背後から届いた。階段を降り切ったところで、俺は一歩横に寄って篠宮さんに道を譲った。篠宮さんが俺の横を通る。銀の鍵が首元で揺れた。"}, {"id": "ch09-s02-p006", "type": "text", "text": "「消滅した島嶼の記録は、この奥の棚に収められています」"}, {"id": "ch09-s02-p007", "type": "text", "text": "書庫の広さは記録室の三倍ほどか。天井が低い。立ち上がった時に頭の上に拳一つぶんの余裕しかない。木製の棚が縦に八列、横に四列。棚の上段には厚紙の箱が並び、箱の側面にラベルが貼られている。篠宮さんの字。全てのラベルが同じ筆跡で、同じ大きさで、同じ間隔で書かれている。"}, {"id": "ch09-s02-p008", "type": "text", "text": "「棚番号は？」"}, {"id": "ch09-s02-p009", "type": "text", "text": "「D列三段目です」"}, {"id": "ch09-s02-p010", "type": "text", "text": "篠宮さんが先に歩いた。足音が記録室より少しだけ大きい。石の床だから。"}, {"id": "ch09-s02-p011", "type": "text", "text": "D列。三段目。篠宮さんが棚の前に立ち、厚紙の箱を引き出した。箱の中に記録カードが詰まっている。名刺より一回り大きいサイズの厚紙に、一枚一枚、手書きで情報が記されたもの。消滅した島嶼の一覧。"}, {"id": "ch09-s02-p012", "type": "text", "text": "「今日は、この箱の中身を確認して、欠損がないか照合する作業です」"}, {"id": "ch09-s02-p013", "type": "text", "text": "篠宮さんがメモ帳を取り出した。24冊目。先週から新しくなった。ペンを持つ。インクをつける。箱の横に立ち、記録カードの端を指で捲り始めた。"}, {"id": "ch09-s02-p014", "type": "text", "text": "俺は箱の反対側に立った。二人で一つの箱を挟む形。地下書庫には机がない。棚の上を作業台にするしかない。"}, {"id": "ch09-s02-p015", "type": "text", "text": "記録カードを一枚ずつ取り出して、篠宮さんのメモ帳のリストと照合する。リストに載っていて、カードが欠損しているものをチェックする。逆に、リストにないカードが紛れ込んでいればそれも確認する。単純な作業。"}, {"id": "ch09-s02-p016", "type": "text", "text": "カードを一枚取り出す。"}, {"id": "ch09-s02-p017", "type": "text", "text": "「カレイド礁。位置、外洋北西海域。推定人口百二十。消滅、六年前」"}, {"id": "ch09-s02-p018", "type": "text", "text": "声に出して読んだ。篠宮さんがメモ帳を確認し、小さく頷く。照合完了。カードを箱に戻す。"}, {"id": "ch09-s02-p019", "type": "text", "text": "次のカード。"}, {"id": "ch09-s02-p020", "type": "text", "text": "「ノルト半島。位置、北部沿岸。推定人口千八百。消滅、十二年前」"}, {"id": "ch09-s02-p021", "type": "text", "text": "頷き。戻す。"}, {"id": "ch09-s02-p022", "type": "text", "text": "三枚目。四枚目。五枚目。"}, {"id": "ch09-s02-p023", "type": "text", "text": "声と頷きのやりとりだけが地下書庫に響いた。記録室のペンの音の代わりに、ここでは俺の読み上げと篠宮さんの照合が作業の音になった。"}, {"id": "ch09-s02-p024", "type": "text", "text": "十二枚目を読んだあたりで、箱の中のカードの並び順が変わった。アルファベット順ではなく、消滅年の順に並び替わっている。篠宮さんがこの箱を整理したのだろう。最近のものが手前、古いものが奥。"}, {"id": "ch09-s02-p025", "type": "text", "text": "十五枚目。十六枚目。"}, {"id": "ch09-s02-p026", "type": "text", "text": "十七枚目を手に取った。"}, {"id": "ch09-s02-p027", "type": "text", "text": "「ルミエラ島」"}, {"id": "ch09-s02-p028", "type": "text", "text": "声に出した。"}, {"id": "ch09-s02-p029", "type": "text", "text": "カードは他のものと同じ規格だった。厚紙。手書き。篠宮さんの字。几帳面な文字が三行にわたって記されている。"}, {"id": "ch09-s02-p030", "type": "text", "text": "「位置、旧世界の南東海域。推定人口、約三百人。消滅、十年前」"}, {"id": "ch09-s02-p031", "type": "text", "text": "読み上げた。口が動いている。言葉が声になっている。問題はない。"}, {"id": "ch09-s02-p032", "type": "text", "text": "けれど——"}, {"id": "ch09-s02-p033", "type": "text", "text": "何かが引っかかった。"}, {"id": "ch09-s02-p034", "type": "text", "text": "「ルミエラ島」という音が口から出た瞬間、歯と舌と唇がその音を知っているように動いた。初めて読む名前なのに、発音に迷いがなかった。カレイド礁を読んだ時は一文字ずつ目で追って声にした。ノルト半島も同じだった。ルミエラ島だけが違った。五文字の音が塊のまま口から出た。"}, {"id": "ch09-s02-p035", "type": "text", "text": "気のせいかもしれない。"}, {"id": "ch09-s02-p036", "type": "text", "text": "カードの続きを読んだ。"}, {"id": "ch09-s02-p037", "type": "text", "text": "「特記事項。果樹園と月夜唄の伝統で知られた」"}, {"id": "ch09-s02-p038", "type": "text", "text": "月夜唄。"}, {"id": "ch09-s02-p039", "type": "text", "text": "つきよのうた。"}, {"id": "ch09-s02-p040", "type": "text", "text": "鳩尾の奥が動いた。"}, {"id": "ch09-s02-p041", "type": "text", "text": "鐘の音を聴いた時と同じ場所。あの夜、「知りたい」が北を向いていた場所。そこが、今、揺れた。鳩尾の奥にあるものが「月夜唄」という三文字に反応して、微かに振動した。"}, {"id": "ch09-s02-p042", "type": "text", "text": "振動は小さかった。鐘の音を聴いた時の「懐かしい」ほど明瞭ではない。歯車に触れた時の「手が知っている」のように体が先に動く感覚でもない。もっと奥にある。もっと深い場所で、何かの端に指先が触れたような——触れたかどうかすらわからない微かさ。"}, {"id": "ch09-s02-p043", "type": "text", "text": "けれど、確かに動いた。"}, {"id": "ch09-s02-p044", "type": "text", "text": "「消滅後の残存者、確認されず」"}, {"id": "ch09-s02-p045", "type": "text", "text": "最後の一行を読み上げた。声が平坦に出た。"}, {"id": "ch09-s02-p046", "type": "text", "text": "カードを両手で持ったまま、文字の上に目を置いた。篠宮さんの几帳面な字が三行と少し。ルミエラ島の全てがこの一枚に収まっている。約三百人が暮らし、果樹園があり、月夜唄という歌があった島。十年前に消えた。残った人はいない。"}, {"id": "ch09-s02-p047", "type": "text", "text": "残った人は、いない。"}, {"id": "ch09-s02-p048", "type": "text", "text": "指の腹がカードの端を押さえている。紙の感触。厚みがある。角がわずかに丸くなっている。この角を丸くしたのは、箱の中でほかのカードと擦れ合ったからだろう。十年前に消えた島のカードは十年分の時間を箱の中で過ごしている。"}, {"id": "ch09-s02-p049", "type": "text", "text": "篠宮さんの気配が横にあった。"}, {"id": "ch09-s02-p050", "type": "text", "text": "顔を上げた。篠宮さんがメモ帳を見ていた。ペンの先が「ル」の欄で止まっている。リストの照合位置。俺が読み上げて、篠宮さんが確認する。いつもの流れ。篠宮さんは俺が読み終わるのを待っている。"}, {"id": "ch09-s02-p051", "type": "text", "text": "「篠宮さん」"}, {"id": "ch09-s02-p052", "type": "text", "text": "呼んだ。"}, {"id": "ch09-s02-p053", "type": "text", "text": "篠宮さんの瞬きが入った。"}, {"id": "ch09-s02-p054", "type": "text", "text": "「この島のこと、もっと詳しい記録はありますか」"}, {"id": "ch09-s02-p055", "type": "text", "text": "言った。"}, {"id": "ch09-s02-p056", "type": "text", "text": "篠宮さんのペンが動きを止めた。メモ帳から視線を上げて、俺の方を見た。墨色の瞳。残響灯の弱い光の中で、瞳の色がいつもより深く見えた。"}, {"id": "ch09-s02-p057", "type": "text", "text": "「……ルミエラ島、ですか」"}, {"id": "ch09-s02-p058", "type": "text", "text": "復唱。篠宮さんの声が「ルミエラ島」を正確に繰り返した。"}, {"id": "ch09-s02-p059", "type": "text", "text": "「はい。果樹園と月夜唄のことが書いてあるけど、それ以上のことが知りたい」"}, {"id": "ch09-s02-p060", "type": "text", "text": "知りたい。"}, {"id": "ch09-s02-p061", "type": "text", "text": "この言葉が自分の口から出るのは——桐ヶ谷さんと屋上で話したあの夜以来か。鳩尾の奥で北を向いていた「知りたい」が、今、ルミエラ島という名前に向いている。方角が変わったわけではない。鳩尾の奥にあるものが同じ一つで、北も、ルミエラ島も、同じ方向を指しているような気がした。"}, {"id": "ch09-s02-p062", "type": "text", "text": "篠宮さんが俺の手の中のカードに視線を落とした。"}, {"id": "ch09-s02-p063", "type": "text", "text": "「地下書庫にある記録は、ここにあるカードと、消滅報告書の写しが基本です。それ以上の詳細は……中央記録館に照会するか、聞き取り資料が残っていないか確認することになります」"}, {"id": "ch09-s02-p064", "type": "text", "text": "声は平坦だった。いつもの篠宮さんの業務的な応答。けれどそのあとに、ほんの少しだけ間があった。"}, {"id": "ch09-s02-p065", "type": "text", "text": "「……探してみます」"}, {"id": "ch09-s02-p066", "type": "text", "text": "声が半音低くなった。"}, {"id": "ch09-s02-p067", "type": "text", "text": "あの時と同じ声。俺の出身について「いつか記録が見つかるかもしれません。私は、諦めません」と言ったあの時の、語尾が下降しない声。記録係としてではなく。"}, {"id": "ch09-s02-p068", "type": "text", "text": "篠宮さんのペンがメモ帳に動いた。リストの「ルミエラ島」の横に、小さな印をつけた。何の印かは見えなかった。篠宮さん独自の記号。"}, {"id": "ch09-s02-p069", "type": "text", "text": "「ありがとうございます」"}, {"id": "ch09-s02-p070", "type": "text", "text": "言った。"}, {"id": "ch09-s02-p071", "type": "text", "text": "今回は遅れなかった。ここ数回、篠宮さんへの感謝は考える前に出るようになっている。"}, {"id": "ch09-s02-p072", "type": "divider", "text": "---"}, {"id": "ch09-s02-p073", "type": "choice_header", "text": "**【選択肢】**"}, {"id": "ch09-s02-p074", "type": "text", "text": "**A)** ルミエラ島のカードを篠宮さんに手渡す。「一緒に調べてもらえますか」"}, {"id": "ch09-s02-p075", "type": "text", "text": "→ 雫好感度 +1"}, {"id": "ch09-s02-p076", "type": "text", "text": "**B)** カードを箱に戻す。「自分でも探してみます」"}, {"id": "ch09-s02-p077", "type": "text", "text": "→ 好感度変動なし"}, {"id": "ch09-s02-p078", "type": "divider", "text": "---"}, {"id": "ch09-s02-p079", "type": "text", "text": "【選択肢A】"}, {"id": "ch09-s02-p080", "type": "text", "text": "カードを篠宮さんに差し出した。"}, {"id": "ch09-s02-p081", "type": "text", "text": "「一緒に調べてもらえますか」"}, {"id": "ch09-s02-p082", "type": "text", "text": "篠宮さんの瞬きが止まった。二秒。三秒。カードを両手で受け取った。篠宮さんの指先が俺の指先に触れなかった。カードの両端を正確に持つ。俺が持っていた部分には触れない。"}, {"id": "ch09-s02-p083", "type": "text", "text": "「……はい」"}, {"id": "ch09-s02-p084", "type": "text", "text": "声が小さかった。壁に届かない声よりさらに小さい。地下書庫の石壁に吸い込まれて消える音量。"}, {"id": "ch09-s02-p085", "type": "text", "text": "篠宮さんがカードを自分のメモ帳の間に挟んだ。大切なものを挟む時の動作。メモ帳の真ん中ではなく、最後のページの直前。書きかけのページと白紙の間。"}, {"id": "ch09-s02-p086", "type": "divider", "text": "---"}, {"id": "ch09-s02-p087", "type": "text", "text": "【選択肢B】"}, {"id": "ch09-s02-p088", "type": "text", "text": "カードを箱に戻した。元の位置に、正確に。"}, {"id": "ch09-s02-p089", "type": "text", "text": "「自分でも探してみます」"}, {"id": "ch09-s02-p090", "type": "text", "text": "篠宮さんが小さく頷いた。いつもの頷き。顎が一センチほど下がって、戻る。"}, {"id": "ch09-s02-p091", "type": "text", "text": "「中央記録館の閲覧は、申請が必要です。必要でしたら、手続きをお手伝いします」"}, {"id": "ch09-s02-p092", "type": "text", "text": "声は平坦。業務的な申し出。けれど「お手伝いします」の語尾が、いつもの「します」より半拍だけ長かった。"}, {"id": "ch09-s02-p093", "type": "divider", "text": "---"}, {"id": "ch09-s02-p094", "type": "text", "text": "【共通】"}, {"id": "ch09-s02-p095", "type": "text", "text": "照合作業を再開した。"}, {"id": "ch09-s02-p096", "type": "text", "text": "十八枚目。十九枚目。二十枚目。"}, {"id": "ch09-s02-p097", "type": "text", "text": "声と頷きのやり取りが続いた。地下書庫の冷たい空気の中で、俺の声と篠宮さんの確認作業だけが動いていた。"}, {"id": "ch09-s02-p098", "type": "text", "text": "カードを読み上げるたびに、一つずつ消えた場所の名前が地下書庫に響いた。カレイド礁。ノルト半島。東嶺港。霧守村。そしてルミエラ島。全てが同じ大きさのカードに書かれていた。同じ筆跡で、同じ書式で。消えた場所はどれも等しく一枚のカードだった。"}, {"id": "ch09-s02-p099", "type": "text", "text": "けれど、俺の口が「ルミエラ島」を知っていたように動いた事実は消えない。"}, {"id": "ch09-s02-p100", "type": "text", "text": "鳩尾の奥の振動はもう止まっている。「月夜唄」を読み上げた瞬間にだけ起きた、短い反応。鐘の音の「懐かしさ」と同じ出処から来たもの。歯車の「知っている」と同じ場所に繋がるもの。全部が、一つのところに集まっている。"}, {"id": "ch09-s02-p101", "type": "text", "text": "その一つのところが、何なのか。俺にはまだわからない。"}, {"id": "ch09-s02-p102", "type": "text", "text": "三十二枚のカードを全て照合し終えた。欠損なし。リスト外のカードの混入もなし。篠宮さんがメモ帳に照合完了と書き込んだ。"}, {"id": "ch09-s02-p103", "type": "text", "text": "箱を棚に戻した。"}, {"id": "ch09-s02-p104", "type": "text", "text": "「終わりました。次回は隣の箱を確認します」"}, {"id": "ch09-s02-p105", "type": "text", "text": "篠宮さんの声。作業完了の報告。いつもの言い方。"}, {"id": "ch09-s02-p106", "type": "text", "text": "「はい」"}, {"id": "ch09-s02-p107", "type": "text", "text": "答えた。"}, {"id": "ch09-s02-p108", "type": "text", "text": "階段を上った。十段。石の壁の反響が足音を増やす。篠宮さんが後ろからついてくる。"}, {"id": "ch09-s02-p109", "type": "text", "text": "一階に出た。図書館のホールの空気が地下よりも温かかった。残響灯の光が明るい。窓から入る夕方の光が床の木目を照らしている。十七時の鐘はまだ鳴っていない。"}, {"id": "ch09-s02-p110", "type": "text", "text": "篠宮さんが扉を閉めた。扉に鍵をかけた。銀の鍵が首元に戻った。"}, {"id": "ch09-s02-p111", "type": "text", "text": "「それでは、今日はここで」"}, {"id": "ch09-s02-p112", "type": "text", "text": "篠宮さんが振り向いた。"}, {"id": "ch09-s02-p113", "type": "text", "text": "いつもの顔。表情の振幅が狭い、いつもの篠宮さんの顔。"}, {"id": "ch09-s02-p114", "type": "text", "text": "けれど——メモ帳を持つ左手の、親指が、メモ帳の端を押さえていた。さっき「ルミエラ島」の横に印をつけたページの位置。無意識に、その場所を確認するように。"}, {"id": "ch09-s02-p115", "type": "text", "text": "「また明日」"}, {"id": "ch09-s02-p116", "type": "text", "text": "俺が言った。"}, {"id": "ch09-s02-p117", "type": "text", "text": "篠宮さんの頷き。顎が下がって、戻る。"}, {"id": "ch09-s02-p118", "type": "text", "text": "図書館を出た。九月の午後の空気。夏の湿度が抜けた後の乾いた風。残響桜の黄色い葉が増えている。"}, {"id": "ch09-s02-p119", "type": "text", "text": "歩きながら、鳩尾の奥を探った。"}, {"id": "ch09-s02-p120", "type": "text", "text": "ルミエラ島。月夜唄。果樹園。三百人。十年前。残存者なし。"}, {"id": "ch09-s02-p121", "type": "text", "text": "カードに書かれた情報は全て記憶した。五行にも満たない記録。けれどその五行の中に、鳩尾の奥が反応する言葉があった。"}, {"id": "ch09-s02-p122", "type": "text", "text": "鐘の音。歯車。そして月夜唄。"}, {"id": "ch09-s02-p123", "type": "text", "text": "三つ目の反応。"}, {"id": "ch09-s02-p124", "type": "text", "text": "三つが同じ場所に向いている。鳩尾の奥で、北を向いている「知りたい」と、同じ方角に。"}, {"id": "ch09-s02-p125", "type": "text", "text": "まだ名前がつかない。何に繋がっているのかもわからない。ルミエラ島が俺と関係があるのかどうかも、わからない。カードを読んだ時に口が勝手に動いたのは事実だが、それだけでは根拠にならない。"}, {"id": "ch09-s02-p126", "type": "text", "text": "わからないまま、歩いた。"}, {"id": "ch09-s02-p127", "type": "text", "text": "ルミエラ島。月夜唄。鳩尾の奥が振動した感触。篠宮さんの「探してみます」の声。"}, {"id": "ch09-s02-p128", "type": "text", "text": "全部、覚えておく。"}]}, {"chapter": 9, "chapterTitle": "記録室の静寂", "scene": 3, "sceneTitle": "秋の収穫", "wordCount": "約4,800字", "paragraphs": [{"id": "ch09-s03-p001", "type": "text", "text": "煉瓦の色が、朝の光で赤い。"}, {"id": "ch09-s03-p002", "type": "text", "text": "休日の中円市場。鐘鋳塔から南に三十分ほど歩いた交差点を中心に、露店が放射状に広がっている。煉瓦舗装の広場に木の台が並び、台の上に秋の作物が積まれていた。大根、里芋、薩摩芋、蕪。南瓜が三つずつ縄で括られて吊るされている。葉物野菜は木箱の中に並べられて、霧吹きで湿らせた布がかけてある。鮮度を保つ工夫。"}, {"id": "ch09-s03-p003", "type": "text", "text": "十時。日が高くなりかけの時間帯で、市場は最も人が多い。"}, {"id": "ch09-s03-p004", "type": "text", "text": "「蓮くん、こっちこっち！」"}, {"id": "ch09-s03-p005", "type": "text", "text": "燈花が三歩先を歩いている。ポニーテールが人の流れの中で揺れている。黄色のゴム。半袖のオレンジ色のシャツに、膝丈のスカート。エプロンはしていないが、腕まくりの仕方がいつもの燈花だった。袖を二回折って、肘の少し下で止める。"}, {"id": "ch09-s03-p006", "type": "text", "text": "「実家からお野菜届いたんだけどね、大根が足りなかったの。あと魚。秋刀魚が出てるはずだから」"}, {"id": "ch09-s03-p007", "type": "text", "text": "燈花の声が市場の喧騒の中を通ってくる。声量が大きい。市場の人混みの中でも、燈花の声は俺の耳にまっすぐ届いた。周囲の売り声や客の話し声と周波数が違う。燈花の声は高さの中に芯がある。空気を押し分けるのではなく、他の音の隙間を抜けてくる声。"}, {"id": "ch09-s03-p008", "type": "text", "text": "今朝、官舎の扉を叩かれた。ノックの間隔が短い。叩きながら次の動作に移っている人間の叩き方。覚えている。"}, {"id": "ch09-s03-p009", "type": "text", "text": "「買い出し行くよ！ 一人で行くの重いから、蓮くん荷物持ち！」"}, {"id": "ch09-s03-p010", "type": "text", "text": "断る理由がなかった。正確には、断るという選択肢が頭に浮かぶ前に靴を履いていた。"}, {"id": "ch09-s03-p011", "type": "text", "text": "市場の通路を歩く。道幅は三メートルほど。両側に露店が並んでいるので、人がすれ違うにはちょうどの広さだった。すれ違う時に肩が触れそうになる距離。燈花は人の流れの中を迷いなく歩いた。右に寄って荷車を避け、左に戻って野菜の台の前に止まる。動きに澱みがない。"}, {"id": "ch09-s03-p012", "type": "text", "text": "最初の店で足が止まった。"}, {"id": "ch09-s03-p013", "type": "text", "text": "大根が並んでいた。白い肌に土がついたまま、葉がしおれずに立っている。掘ってから半日も経っていない。燈花がしゃがんだ。大根の一本を手に取って、指で表面をなぞった。人差し指と中指の二本で、皮の上を滑らせる。"}, {"id": "ch09-s03-p014", "type": "text", "text": "「んー、これはちょっと筋が入ってるかな」"}, {"id": "ch09-s03-p015", "type": "text", "text": "戻した。別の一本を手に取る。今度は両手で持ち上げて、重さを確かめた。左手で根元、右手で先端の少し上。"}, {"id": "ch09-s03-p016", "type": "text", "text": "「この大根、うちの畑のと同じくらい立派だね」"}, {"id": "ch09-s03-p017", "type": "text", "text": "声が変わった。さっきまでの、俺を呼ぶ時の弾んだ声とは違う。低い。低いけれど暗くない。地面に近い声。土の匂いがしそうな声。"}, {"id": "ch09-s03-p018", "type": "text", "text": "以前にも聞いた。喫茶「残響」で畑の話をした時と同じ声だった。走ることについて話した時の、あの声。"}, {"id": "ch09-s03-p019", "type": "text", "text": "燈花が店主のおばさんに話しかけた。"}, {"id": "ch09-s03-p020", "type": "text", "text": "「これ、外円区のどこのですか？」"}, {"id": "ch09-s03-p021", "type": "text", "text": "「東の天蓋農場だよ。今年は出来がいいねえ」"}, {"id": "ch09-s03-p022", "type": "text", "text": "「ですよね！ 土がいいんだ、あそこは。水はけがちょうどよくて」"}, {"id": "ch09-s03-p023", "type": "text", "text": "燈花の口調が変わっていた。敬語が自然に混ざっている。市場の店主に対する燈花は、俺や学院の友人に見せる燈花とは別の顔をしていた。農家の娘の顔。食材の品定めをする目は、体育祭でゴールテープを見据えた時の目に似ていた。真っ直ぐで、迷いがない。"}, {"id": "ch09-s03-p024", "type": "text", "text": "大根を二本。里芋を一袋。蕪を四つ。"}, {"id": "ch09-s03-p025", "type": "text", "text": "燈花が選んだものを俺が受け取って、布袋に入れた。布袋は燈花が持ってきたもので、底が二重に補強されている。重いものを入れても破れない作り。使い込まれた袋だった。"}, {"id": "ch09-s03-p026", "type": "text", "text": "「次、魚！」"}, {"id": "ch09-s03-p027", "type": "text", "text": "燈花が歩き出した。三歩先。振り返って、俺が来ているか確認する。確認というより、来ていることを確かめて笑う。口が横に広がって、頬が上がる。歯が見える。"}, {"id": "ch09-s03-p028", "type": "text", "text": "魚の露店は市場の東寄りにあった。木の台の上に氷を敷き、その上に魚が並んでいる。秋刀魚が十尾ほど、銀色の体が氷の上で光を反射していた。鯖もある。小鯛が五枚。干物が紐に吊るされている。"}, {"id": "ch09-s03-p029", "type": "text", "text": "燈花が秋刀魚の前に立った。"}, {"id": "ch09-s03-p030", "type": "text", "text": "一尾を手に取る。手つきが違った。野菜を触る時よりも指先が繊細になっている。秋刀魚の目を見た。腹を押した。人差し指の腹で、秋刀魚の腹の中央をそっと押す。弾力を確かめる動作。"}, {"id": "ch09-s03-p031", "type": "text", "text": "「うん、脂乗ってる。いいね」"}, {"id": "ch09-s03-p032", "type": "text", "text": "三尾選んだ。店主に代金を払う燈花の横顔を見ていた。"}, {"id": "ch09-s03-p033", "type": "text", "text": "財布を開いて硬貨を数える指。左手の薬指に布リングがある。ほつれた端が一センチほど伸びていて、秋刀魚を選んだ時に魚の鱗が一枚くっついた。燈花はそれに気づいていない。"}, {"id": "ch09-s03-p034", "type": "text", "text": "市場にいる燈花は——。"}, {"id": "ch09-s03-p035", "type": "text", "text": "走っている燈花を見た時に「すごかった」と思った。名前を呼んだ時に肋骨の内側が温かくなった。灯篭流しの夜に泣いた燈花の横顔を見た。笑う顔も、止まる顔も、泣く顔も見た。"}, {"id": "ch09-s03-p036", "type": "text", "text": "でも、今の燈花は、それらのどれとも違う。"}, {"id": "ch09-s03-p037", "type": "text", "text": "大根の重さを手のひらで量る燈花。秋刀魚の鮮度を指先で確かめる燈花。店主と収穫の話をする燈花。声が低くなって、目がまっすぐ前を見て、指先に迷いがない。"}, {"id": "ch09-s03-p038", "type": "text", "text": "これが一番、自分の場所にいる顔だった。"}, {"id": "ch09-s03-p039", "type": "text", "text": "走る時の燈花には集中がある。料理をする時の燈花には熱意がある。市場の燈花には、集中でも熱意でもない。呼吸している。水を飲むように自然に、食材の中を歩いている。この空気の中にいることが、燈花にとっては故郷の延長なのだろう。"}, {"id": "ch09-s03-p040", "type": "text", "text": "外円区から届いた野菜。外円区の農場で育った大根。中円市場はそれらが集まる場所で、燈花はその流れの中にいる。外円区と中円区を繋いでいるのは食材で、食材を選ぶ燈花の手は、その繋がりの中にある。"}, {"id": "ch09-s03-p041", "type": "text", "text": "「蓮くん、重くない？」"}, {"id": "ch09-s03-p042", "type": "text", "text": "「大丈夫です」"}, {"id": "ch09-s03-p043", "type": "text", "text": "「あ、また敬語」"}, {"id": "ch09-s03-p044", "type": "text", "text": "燈花が眉を寄せた。けれど怒ってはいない。呆れに近い。呆れに近いけれど、口元が笑っている。"}, {"id": "ch09-s03-p045", "type": "text", "text": "「大丈夫」"}, {"id": "ch09-s03-p046", "type": "text", "text": "言い直した。布袋は確かに重い。大根二本と里芋と蕪と秋刀魚。片手で持つと腕に食い込む。けれど歩けないほどではない。"}, {"id": "ch09-s03-p047", "type": "text", "text": "「葉物もほしいな。小松菜と、あと……春菊あるかな。秋だし」"}, {"id": "ch09-s03-p048", "type": "text", "text": "燈花が通路の先を見ている。探している目。市場の全体を把握して、次の店を探している目。"}, {"id": "ch09-s03-p049", "type": "text", "text": "「あった！」"}, {"id": "ch09-s03-p050", "type": "text", "text": "小走りに行った。ポニーテールが跳ねた。"}, {"id": "ch09-s03-p051", "type": "text", "text": "俺は荷物を持ったまま、燈花の背中を追った。"}, {"id": "ch09-s03-p052", "type": "divider", "text": "---"}, {"id": "ch09-s03-p053", "type": "text", "text": "喫茶「残響」のカウベルが鳴った。"}, {"id": "ch09-s03-p054", "type": "text", "text": "磨りガラスのドアを押して入ると、油と木の匂い。裸電球の黄色い光。テーブル席が三つ。日曜の午前中、客は一人もいなかった。"}, {"id": "ch09-s03-p055", "type": "text", "text": "「おや、買い出し帰りか」"}, {"id": "ch09-s03-p056", "type": "text", "text": "カウンターの奥で吉岡さんがグラスを拭いていた。三秒で一周。"}, {"id": "ch09-s03-p057", "type": "text", "text": "「マスター、お水ください！ あとアイスティー！」"}, {"id": "ch09-s03-p058", "type": "text", "text": "「俺はコーヒーで」"}, {"id": "ch09-s03-p059", "type": "text", "text": "燈花がテーブル席に座った。いつもの席。壁際の、油灯があるテーブル。買い出しの荷物を椅子の横に置いた。布袋から大根の葉が飛び出している。"}, {"id": "ch09-s03-p060", "type": "text", "text": "燈花が両手を広げてテーブルに突っ伏した。"}, {"id": "ch09-s03-p061", "type": "text", "text": "「つかれたー」"}, {"id": "ch09-s03-p062", "type": "text", "text": "「疲れたのは荷物を持っていた俺では」"}, {"id": "ch09-s03-p063", "type": "text", "text": "「あはは、ごめんごめん。でも選ぶのも体力使うんだよ？ 目と手と頭と、全部使うから」"}, {"id": "ch09-s03-p064", "type": "text", "text": "燈花が顔を上げた。頬が少し赤い。市場を歩き回った熱が残っている。汗がこめかみに一筋。ポニーテールの後れ毛が頬に張りついていた。"}, {"id": "ch09-s03-p065", "type": "text", "text": "吉岡さんが水とアイスティーとコーヒーを運んできた。燈花が水を一息に半分飲んだ。"}, {"id": "ch09-s03-p066", "type": "text", "text": "「ねえ蓮くん」"}, {"id": "ch09-s03-p067", "type": "text", "text": "「はい」"}, {"id": "ch09-s03-p068", "type": "text", "text": "「……また敬語」"}, {"id": "ch09-s03-p069", "type": "text", "text": "「ん」"}, {"id": "ch09-s03-p070", "type": "text", "text": "燈花が笑った。「ん」で返されたのが可笑しかったらしい。口が大きく開いて、目が細くなった。"}, {"id": "ch09-s03-p071", "type": "text", "text": "「蓮くん、今日の夕飯は腕を振るうから楽しみにしてて！」"}, {"id": "ch09-s03-p072", "type": "text", "text": "燈花がアイスティーのグラスを両手で包んで、身を乗り出した。テーブルの油灯が揺れた。目が光っている。黄褐色の虹彩に、裸電球の黄色い光が重なっている。"}, {"id": "ch09-s03-p073", "type": "text", "text": "「大根は煮物にする。里芋は味噌汁。蕪はお漬物。秋刀魚は塩焼き。春菊はおひたし。フルコースだよ！」"}, {"id": "ch09-s03-p074", "type": "text", "text": "指を折りながら献立を並べた。五本の指が順番に折れていく。一つ折るたびに声が弾む。"}, {"id": "ch09-s03-p075", "type": "text", "text": "「……楽しみにしてる」"}, {"id": "ch09-s03-p076", "type": "text", "text": "言った。"}, {"id": "ch09-s03-p077", "type": "text", "text": "間がなかった。"}, {"id": "ch09-s03-p078", "type": "text", "text": "考える前に口から出た。体育祭の「すごかった」と同じ回路。入力があって、体の中で何かが動いて、口が先に動く。思考が追いかける前に言葉が出ている。"}, {"id": "ch09-s03-p079", "type": "text", "text": "燈花の動きが一瞬止まった。指を折る動きが、小指のところで止まった。"}, {"id": "ch09-s03-p080", "type": "text", "text": "「……え、今なんて？」"}, {"id": "ch09-s03-p081", "type": "text", "text": "「楽しみにしてる」"}, {"id": "ch09-s03-p082", "type": "text", "text": "もう一度言えた。二度目は意図的だった。一度目に口から出た言葉を、二度目に自分の意志で繰り返した。"}, {"id": "ch09-s03-p083", "type": "text", "text": "燈花の顔が動いた。口の端が持ち上がった。頬が上がった。目が細くなった。歯が見えた。名前を呼んだ夜の満面の笑みと同じ構造だった。けれど今回は凍結がなかった。受け取って処理する時間が要らなかった。一拍で笑顔が完成した。"}, {"id": "ch09-s03-p084", "type": "text", "text": "「よし！ じゃあ期待しててよね！ お母さんの味にはまだ追いつけてないけど、煮物だけは自信あるから！」"}, {"id": "ch09-s03-p085", "type": "text", "text": "燈花がアイスティーを一口飲んだ。ストローをくわえたまま、目がこちらを見ている。笑っていた。口元はストローで隠れているけれど、目が笑っている。"}, {"id": "ch09-s03-p086", "type": "text", "text": "コーヒーカップを持ち上げた。ブラックコーヒーの表面に裸電球の光が映っている。苦い。いつもの味。"}, {"id": "ch09-s03-p087", "type": "text", "text": "「楽しみにしてる」と言った時の肋骨の内側を探った。温かさがある。名前を呼んだ夜と同じ場所。同じ温度かどうかはわからない。けれど、同じ場所で同じ種類の温かさだった。"}, {"id": "ch09-s03-p088", "type": "text", "text": "模倣ではない。前にそう思った時、たぶん、と付け加えた。今回も同じ留保がつく。"}, {"id": "ch09-s03-p089", "type": "text", "text": "ただ、その留保の重さが少しだけ軽くなっている。名前を呼んだ夜は鉛のように沈んでいた。今は紙一枚ぶんほど浮いている。"}, {"id": "ch09-s03-p090", "type": "text", "text": "燈花がテーブルの上に頬杖をついて、窓の外を見ていた。磨りガラスの向こうに、市場帰りの人影が滲んでいる。"}, {"id": "ch09-s03-p091", "type": "text", "text": "「秋って、外円区が一番忙しい時期なんだよね」"}, {"id": "ch09-s03-p092", "type": "text", "text": "声が穏やかだった。弾む声でも低い声でもない。その中間。"}, {"id": "ch09-s03-p093", "type": "text", "text": "「収穫があるから。お米も、野菜も、果物も。外円区の農家が頑張って作ったものが、全部ここに届く。中円市場はそれを受け取る場所で、あたしたちが食べるものは全部、外円区の土から来てるの」"}, {"id": "ch09-s03-p094", "type": "text", "text": "燈花の指がグラスの表面をなぞっていた。結露の水滴が指の軌跡に沿って流れる。"}, {"id": "ch09-s03-p095", "type": "text", "text": "「お父さんが言ってた。食べ物を作る人がいなくなったら、島は三日で止まるって」"}, {"id": "ch09-s03-p096", "type": "text", "text": "お父さん。天城耕作。半年前の縁蝕波で消滅した人。"}, {"id": "ch09-s03-p097", "type": "text", "text": "燈花の目に翳りが差すかどうか、見ていた。"}, {"id": "ch09-s03-p098", "type": "text", "text": "差さなかった。"}, {"id": "ch09-s03-p099", "type": "text", "text": "目の奥は穏やかなままだった。翳りでも重さでもない。お父さんの言葉を引用する時、燈花の声は市場で店主と話した時の声に近かった。農家の娘の声。受け継いだものを、そのまま口にする声。"}, {"id": "ch09-s03-p100", "type": "text", "text": "「だから今日買った野菜は、全部おいしく作るよ。外円区の人たちが育てたんだから」"}, {"id": "ch09-s03-p101", "type": "text", "text": "燈花がアイスティーを飲み干した。氷が鳴った。グラスをテーブルに置いて、両手でぱんと膝を叩いた。"}, {"id": "ch09-s03-p102", "type": "text", "text": "「よし。そろそろ帰ろっか。仕込み始めないと夕飯に間に合わないし」"}, {"id": "ch09-s03-p103", "type": "text", "text": "立ち上がった。椅子の横の布袋を持ち上げようとして、俺が先に手を伸ばした。"}, {"id": "ch09-s03-p104", "type": "text", "text": "「持つ」"}, {"id": "ch09-s03-p105", "type": "text", "text": "「あ、ありがと」"}, {"id": "ch09-s03-p106", "type": "text", "text": "燈花が笑った。軽い笑い。市場で振り返って確認した時の笑いに似ていた。"}, {"id": "ch09-s03-p107", "type": "text", "text": "カウベルが鳴った。磨りガラスのドアを押して外に出る。"}, {"id": "ch09-s03-p108", "type": "text", "text": "秋の午前の空気。乾いた風に、市場の残り香が混ざっている。野菜と魚と、煉瓦の匂い。"}, {"id": "ch09-s03-p109", "type": "text", "text": "燈花が三歩先を歩いている。ポニーテールが揺れている。左手の薬指の布リングに、秋刀魚の鱗がまだくっついていた。燈花はまだ気づいていない。"}, {"id": "ch09-s03-p110", "type": "text", "text": "教えようかと思った。"}, {"id": "ch09-s03-p111", "type": "text", "text": "やめた。帰ったら気づくだろう。あるいは仕込みを始めた時に、手を洗って落ちるだろう。"}, {"id": "ch09-s03-p112", "type": "text", "text": "布袋が右腕に食い込んでいる。大根と里芋と蕪と秋刀魚と春菊と小松菜。重い。けれど、歩けないほどではない。"}, {"id": "ch09-s03-p113", "type": "text", "text": "燈花と市場を歩いた。燈花が食材を選ぶのを見ていた。「楽しみにしてる」と言った。"}, {"id": "ch09-s03-p114", "type": "text", "text": "布袋が重かった。九月の風が乾いていた。"}]}, {"chapter": 9, "chapterTitle": "記録室の静寂", "scene": 4, "sceneTitle": "無理させないで", "wordCount": "約5,100字", "paragraphs": [{"id": "ch09-s04-p001", "type": "text", "text": "丘の斜面を登ると、訓練棟の灰色の壁が見えた。"}, {"id": "ch09-s04-p002", "type": "text", "text": "十月の放課後。十六時半を少し過ぎている。空は高くて、西に傾いた日差しが石積みの壁を橙色に染めていた。窓の少ない重厚な外壁。防音構造。この建物の中で声を発しても、外には漏れない。——はずだったが、四月にここを初めて訪れた時は歌声が漏れていた。あの日も、今日と同じ石畳の小道を台車を押して登った。"}, {"id": "ch09-s04-p003", "type": "text", "text": "今日は台車がない。機材チェックの定期点検。月に一度、訓練棟に設置した音響計測器の校正作業を行う。鞄の中に校正用の基準音源と記録用紙がある。三十分で終わる作業。"}, {"id": "ch09-s04-p004", "type": "text", "text": "訓練棟の正面入口まであと十歩ほどのところで、足が止まった。"}, {"id": "ch09-s04-p005", "type": "text", "text": "人がいた。"}, {"id": "ch09-s04-p006", "type": "text", "text": "入口の横の壁。石積みの柱と厚い木の扉の間に、背中を預けて立っている。腕を組んでいない。両手が体の横に下がっている。指先がスカートの生地を掴んでいた。右手首にミサンガ。"}, {"id": "ch09-s04-p007", "type": "text", "text": "風祭さんだった。"}, {"id": "ch09-s04-p008", "type": "text", "text": "六月にここで呼び止められた時と場所が同じだった。訓練棟の出入口の近く。あの時は俺が共鳴室から出てきたところを待ち伏せされた。今日は俺がこれから入るところ。待つ側の立ち位置は同じでも、足の重心が違った。あの時は壁に体を預けて腕を組んでいた。今日は壁に背中をつけてはいるが、体が前に傾いている。重心が壁ではなく、自分の足にかかっている。腕を組んでいない。"}, {"id": "ch09-s04-p009", "type": "text", "text": "栗色のショートヘアが秋の風ではねている。制服のリボンは少し緩い。スニーカーの白い底が石畳の上にぴたりと接地している。"}, {"id": "ch09-s04-p010", "type": "text", "text": "目が合った。"}, {"id": "ch09-s04-p011", "type": "text", "text": "緑色の瞳。翡翠に似た色。西日が斜めから差して、瞳の色が深くなっている。——これも前回と同じだった。夕方の光は風祭さんの目の色を重くする。"}, {"id": "ch09-s04-p012", "type": "text", "text": "けれど、目の中にあるものが違った。"}, {"id": "ch09-s04-p013", "type": "text", "text": "あの六月の日の風祭さんの目には硬さがあった。査定の硬さとは別の、「何者かは知った上での」硬さ。今日は硬くなかった。硬くない代わりに、揺れていた。翡翠色の虹彩の中で、何かが定まらずに動いている。"}, {"id": "ch09-s04-p014", "type": "text", "text": "「朝霧さん」"}, {"id": "ch09-s04-p015", "type": "text", "text": "声は高めだった。輪郭がある。けれど音量が絞られていた。風祭さんの声にはいくつかの段階がある。前回の声は「絞った刃」でも「用件がある人間の声」でもなかった。平坦で、角を隠している声だった。今日の声は——角がない。角を隠しているのではなく、角がない。"}, {"id": "ch09-s04-p016", "type": "text", "text": "「風祭さん」"}, {"id": "ch09-s04-p017", "type": "text", "text": "立ち止まって答えた。距離は四メートルほど。石畳の上。西日と影の境目が俺たちの間を横切っていた。俺が日向に、風祭さんが壁際の薄い影にいた。これも前回と似ている。"}, {"id": "ch09-s04-p018", "type": "text", "text": "「機材チェック？」"}, {"id": "ch09-s04-p019", "type": "text", "text": "「はい」"}, {"id": "ch09-s04-p020", "type": "text", "text": "風祭さんの目が俺の鞄を見た。校正用の基準音源が入っている鞄。風祭さんは千歳の訓練スケジュールだけではなく、俺の訓練棟への出入りも把握している。六月にここで待ち伏せされた時点で見学回数を正確に数えていた。月一回の定期点検の日程も知っていておかしくない。"}, {"id": "ch09-s04-p021", "type": "text", "text": "「あのね」"}, {"id": "ch09-s04-p022", "type": "text", "text": "風祭さんの声が低くなった。"}, {"id": "ch09-s04-p023", "type": "text", "text": "低くなった、と書くのは不正確かもしれない。高い声が低い位置に移動したのではない。声の芯が下に落ちた。声の表面は変わらない。輪郭もある。けれど芯の位置が違う。喉の奥から出ている声。こういう声を風祭さんは千歳の前では出さない。千歳の前での風祭さんの声には、鞘に収まった安定がある。今の声は鞘から抜けている。抜けているのに刃ではなかった。鞘から出た中身が、刃ではなく、むき出しの手だった。"}, {"id": "ch09-s04-p024", "type": "text", "text": "「ちーちゃんのことなんだけど」"}, {"id": "ch09-s04-p025", "type": "text", "text": "予想していた。"}, {"id": "ch09-s04-p026", "type": "text", "text": "訓練棟の入口で風祭さんが待っている。俺に用がある。その用件が千歳に関係しないことは、風祭さんにおいてはあり得ない。"}, {"id": "ch09-s04-p027", "type": "text", "text": "「最近、ちーちゃん……練習の後、少し元気がないの」"}, {"id": "ch09-s04-p028", "type": "text", "text": "声が静かだった。音量が小さいのではなく、中に詰まっているものが多すぎて声が膨らまない。圧縮されている。"}, {"id": "ch09-s04-p029", "type": "text", "text": "「食欲も落ちてるし、時々ふらっとする。あたしが聞いても『大丈夫だよ、いろは』って笑うだけで」"}, {"id": "ch09-s04-p030", "type": "text", "text": "風祭さんの右手が動いた。体の横から持ち上がり、右手首のミサンガに触れた。千歳とお揃いの。左手首ではなく、右手首。ミサンガの編み目に親指の腹が触れて、何度も往復した。指先が何かを確かめている。千歳との繋がりを。"}, {"id": "ch09-s04-p031", "type": "text", "text": "「元気がない」の中身を、俺は知っている範囲で照合した。"}, {"id": "ch09-s04-p032", "type": "text", "text": "残響祭の日。響弦館の公演後に、千歳の右膝が折れかけた。半秒。風祭さんが四歩で支えた。客席の誰にも気づかせなかった。"}, {"id": "ch09-s04-p033", "type": "text", "text": "六月。共鳴室で歌った後に、千歳の瞳の色が薄くなった。首元を押さえる癖。額の汗。"}, {"id": "ch09-s04-p034", "type": "text", "text": "八月末の体育祭。千歳は応援席最上段の日陰にいた。体力系競技に参加していなかった。"}, {"id": "ch09-s04-p035", "type": "text", "text": "そして前回、六月のこの場所で風祭さんが言った——「あんまり、ちーちゃんを疲れさせないでほしいの」。俺が「訓練で疲れるのは仕方ないのでは」と返した時、風祭さんは「そういうことじゃなくて……」と言いかけて、止めた。"}, {"id": "ch09-s04-p036", "type": "text", "text": "あの時止めたものが、今日は止まらずに出てきている。"}, {"id": "ch09-s04-p037", "type": "text", "text": "「共鳴者選抜公演が十一月にあるでしょ」"}, {"id": "ch09-s04-p038", "type": "text", "text": "風祭さんの声が少し早くなった。「あるでしょ」は確認ではない。事実の提示。風祭さんは千歳のスケジュールを完全に把握している。"}, {"id": "ch09-s04-p039", "type": "text", "text": "「それに向けて訓練量が増えてるの。週三回だったのが、今は週五。放課後に二時間。朝練も入れたら一日三時間。ちーちゃんは自分から増やしたいって言ったけど……」"}, {"id": "ch09-s04-p040", "type": "text", "text": "風祭さんの声が途切れた。途切れたのではない。止めた。自分の口を。あの六月の日と同じ動作。しかし今回は止める時間が短かった。一秒もなかった。唇が閉じて、開いた。"}, {"id": "ch09-s04-p041", "type": "text", "text": "「あの子、嘘つくの下手なくせに」"}, {"id": "ch09-s04-p042", "type": "text", "text": "声が震えた。"}, {"id": "ch09-s04-p043", "type": "text", "text": "小さな震え。声の末尾だけが揺れた。「くせに」の「に」の音が波打った。風祭さんの緑色の目が俺を見ていた。怒りではなかった。前回は怒りと心配と恐れの混合物が目の中にあった。今日は——不安だった。不安だけが、目の中で剥き出しになっていた。"}, {"id": "ch09-s04-p044", "type": "text", "text": "風祭さんの肩が上がっていた。百五十七センチの体が自分を大きく見せようとしているのではなく、内側を守っている。前にここで会った時と同じ。ただし今日は、守りの中から声が漏れている。守りきれなくなっている。"}, {"id": "ch09-s04-p045", "type": "text", "text": "「無理させないでくださいね」"}, {"id": "ch09-s04-p046", "type": "text", "text": "敬語だった。"}, {"id": "ch09-s04-p047", "type": "text", "text": "風祭さんが俺に敬語を使ったのは初めてだった。「朝霧さん」という呼称には距離があるが、話し方は常にタメ口に近かった。「信じとく」「届けてよね」「音響、ちゃんとやってくれるんでしょ」。敬語は風祭さんの口に合わない。合わないものを使っているということは、頼んでいるということだ。"}, {"id": "ch09-s04-p048", "type": "text", "text": "牽制ではなかった。"}, {"id": "ch09-s04-p049", "type": "text", "text": "六月の「疲れさせないで」は牽制だった。俺を千歳から遠ざけるための言葉。今日の「無理させないで」は——遠ざけるためではなく、近くにいる人間に対して発している。俺がもう千歳の近くにいることを、前提にしている。"}, {"id": "ch09-s04-p050", "type": "text", "text": "風祭さんの態度が変わった。"}, {"id": "ch09-s04-p051", "type": "text", "text": "石の壁。木の壁。信じとく。警戒再強化。——そして今日。今日の風祭さんは壁ではなかった。壁の向こう側から手を伸ばしている。助けを求めている。その手がミサンガに触れながら震えていた。"}, {"id": "ch09-s04-p052", "type": "text", "text": "「鳴海さんの体調のこと」"}, {"id": "ch09-s04-p053", "type": "text", "text": "声を出した。考える前に、ではなかった。考えた上で出した。"}, {"id": "ch09-s04-p054", "type": "text", "text": "「医務室に相談したほうがいいのでは」"}, {"id": "ch09-s04-p055", "type": "text", "text": "具体的な提案。感情ではなく手段。四月の俺ならここで止まっていた。「仕方ないのでは」で終わっていた。今は違う。風祭さんが「疲れさせないで」の先にあるものを出してきたなら、俺も「仕方ない」の先に進むべきだった。"}, {"id": "ch09-s04-p056", "type": "text", "text": "風祭さんの目が動いた。見開かれてはいなかった。六月に「鳴海さんのことが心配なんですね」と言った時は、一瞬だけ見開かれた。今日は見開きがなかった。代わりに、目の中の揺れが一瞬止まった。"}, {"id": "ch09-s04-p057", "type": "text", "text": "「あたしも思った」"}, {"id": "ch09-s04-p058", "type": "text", "text": "声が低い。芯の位置が喉の奥のまま。"}, {"id": "ch09-s04-p059", "type": "text", "text": "「でもちーちゃんが嫌がるの。『わたしは大丈夫ですよ』って……あの子、嘘つくの下手なくせに」"}, {"id": "ch09-s04-p060", "type": "text", "text": "二度目だった。「嘘つくの下手なくせに」が二度出た。同じ文面。同じ語尾。声の震えの位置も同じ。何度も繰り返した言葉だった。風祭さんの頭の中で何百回も反芻された言葉が、今日俺の前で二度出てきた。"}, {"id": "ch09-s04-p061", "type": "text", "text": "風祭さんの右手がミサンガから離れた。手が拳になった。爪が掌に食い込んでいるかどうかは見えない。けれど指の関節が白くなっていた。"}, {"id": "ch09-s04-p062", "type": "text", "text": "「ちーちゃん、練習の後にふらっとするの、あたしはもう何回も見てるの。四月の公演の後にだって、膝が——」"}, {"id": "ch09-s04-p063", "type": "text", "text": "言葉が途切れた。風祭さんの口が閉じた。"}, {"id": "ch09-s04-p064", "type": "text", "text": "今度は止めたのではなかった。声が出なくなった。喉のどこかで声が詰まっている。目が潤んでいた。涙にはなっていなかった。緑色の虹彩に水の膜がかかって、翡翠が水底から見上げているような色になっていた。"}, {"id": "ch09-s04-p065", "type": "text", "text": "泣きそうで泣かない。"}, {"id": "ch09-s04-p066", "type": "text", "text": "風祭さんは泣かない人だ。千歳の前では笑い、俺の前では硬い顔を作り、怒る時は声を張り上げる。泣く場面を俺は見たことがない。今も泣いていなかった。泣いていないことが、泣くよりも痛い場所にいることを示していた。"}, {"id": "ch09-s04-p067", "type": "text", "text": "「……ごめん。あたし、何が言いたいんだろ」"}, {"id": "ch09-s04-p068", "type": "text", "text": "声がかすれていた。笑おうとしていた。口角を上げようとして、途中で止まっていた。四月に訓練棟のロビーで千歳の前を見せた時の「口を大きく開けて笑う」風祭さんとは違う。表情を作ろうとして失敗している。千歳の体調が悪い時だけ、表情を固まらせて無理に笑顔を作る——キャラクター設計書に書いてあるわけではないが、これまでの観察で蓄積したパターンと一致した。"}, {"id": "ch09-s04-p069", "type": "text", "text": "「風祭さん」"}, {"id": "ch09-s04-p070", "type": "text", "text": "呼んだ。"}, {"id": "ch09-s04-p071", "type": "text", "text": "風祭さんの目がこちらを向いた。水の膜がかかった翡翠色。"}, {"id": "ch09-s04-p072", "type": "text", "text": "「俺にできることがあるなら、言ってください」"}, {"id": "ch09-s04-p073", "type": "text", "text": "言った。"}, {"id": "ch09-s04-p074", "type": "text", "text": "敬語だった。風祭さんが敬語を使ったから、俺も敬語で返した。——違う。そうではない。自然に出た。「言ってください」は、風祭さんに合わせたのではなく、この場面の重さが呼んだ言葉だった。"}, {"id": "ch09-s04-p075", "type": "text", "text": "風祭さんの口が開いた。閉じた。もう一度開いた。唇が動いたが声にならなかった。"}, {"id": "ch09-s04-p076", "type": "text", "text": "三秒。"}, {"id": "ch09-s04-p077", "type": "text", "text": "風祭さんが息を吸った。長い吸気だった。肩が上がり、下がった。呼吸を一回やり直した。"}, {"id": "ch09-s04-p078", "type": "text", "text": "「……ちーちゃんの訓練終わりの時間、知ってる？」"}, {"id": "ch09-s04-p079", "type": "text", "text": "声がかすれたまま戻ってきた。質問の形。けれど答えを求めているのではなかった。"}, {"id": "ch09-s04-p080", "type": "text", "text": "「今日は十七時半に終わるはず。あたし、いつも訓練終わりにちーちゃんを迎えに来るんだけど——」"}, {"id": "ch09-s04-p081", "type": "text", "text": "風祭さんが言葉を切った。目がまっすぐ俺を見ていた。水の膜は薄くなっていたが、消えてはいなかった。"}, {"id": "ch09-s04-p082", "type": "text", "text": "「もし朝霧さんも、ちーちゃんのこと見てくれるなら」"}, {"id": "ch09-s04-p083", "type": "text", "text": "敬語が崩れかけていた。「くれるなら」の語尾が、いつもの風祭さんの口調に戻りかけている。壁が戻りかけている。けれど完全には戻らなかった。"}, {"id": "ch09-s04-p084", "type": "choice_header", "text": "---\n**【選択肢】**"}, {"id": "ch09-s04-p085", "type": "choice", "text": "**A: 差し入れを持っていく** → 千歳好感度 +1"}, {"id": "ch09-s04-p086", "type": "text", "text": "「差し入れを持っていきます」"}, {"id": "ch09-s04-p087", "type": "text", "text": "言った。機材チェックは三十分で終わる。十七時半までに一時間ある。購買で何か買える。千歳が何を好むかは知らない。けれど燈花が以前差し入れてくれた時のことは覚えている。水分と、糖分。訓練後の体に必要なもの。"}, {"id": "ch09-s04-p088", "type": "text", "text": "風祭さんの目が動いた。揺れが戻りかけていた翡翠色の中で、何かが定まった。定まったのは——安堵ではなかった。安堵には早い。けれど、「一人ではない」ということが目の中に入った。"}, {"id": "ch09-s04-p089", "type": "text", "text": "「……うん」"}, {"id": "ch09-s04-p090", "type": "text", "text": "小さな声だった。風祭さんの声の段階のどれにも当てはまらない。千歳の前で見せる柔らかさでもなく、俺に向ける硬さでもなく、査定でも牽制でもなかった。ただの返事。ただの「うん」。一番短くて、一番正直な音。"}, {"id": "ch09-s04-p091", "type": "text", "text": "「あたしもいるから。ちーちゃんの訓練終わり、ロビーで待ってる」"}, {"id": "ch09-s04-p092", "type": "text", "text": "風祭さんが壁から背中を離した。姿勢が変わった。肩が少しだけ下がった。まだ高い位置にあるが、さっきよりは下がった。内側を守る体勢が、わずかに緩んでいた。"}, {"id": "ch09-s04-p093", "type": "choice", "text": "**B: 遠くから見守る** → 好感度変動なし"}, {"id": "ch09-s04-p094", "type": "text", "text": "「少し、気にかけるようにします」"}, {"id": "ch09-s04-p095", "type": "text", "text": "言った。遠くからの方が、千歳の日常を壊さずに済む。風祭さんが毎日やっていることに俺が割り込む必要はない。千歳の訓練終わりを迎えるのは風祭さんの場所だ。その場所を侵さない距離で、計測値に変化がないか確認する。それが俺にできることだった。"}, {"id": "ch09-s04-p096", "type": "text", "text": "風祭さんの目に、何かが通過した。失望ではなかった。俺の答えを測っていた。遠くから見守るという選択が、無関心ではないことを確かめていた。"}, {"id": "ch09-s04-p097", "type": "text", "text": "「……ふうん」"}, {"id": "ch09-s04-p098", "type": "text", "text": "短い声だった。判定保留の声。「信じとく」と同じ系統の、結果を見てから決めるという声。"}, {"id": "ch09-s04-p099", "type": "text", "text": "「まあいいけど。ちーちゃんに何かあったら、あたしに言って」"}, {"id": "ch09-s04-p100", "type": "text", "text": "風祭さんが壁から背中を離した。姿勢が戻った。肩がまだ高い。内側を守る体勢。けれど、壁の向こうから伸ばした手を、完全には引っ込めていなかった。"}, {"id": "ch09-s04-p101", "type": "divider", "text": "---"}, {"id": "ch09-s04-p102", "type": "text", "text": "風祭さんが石畳の小道を下りていった。"}, {"id": "ch09-s04-p103", "type": "text", "text": "背中が小さくなっていく。栗色のショートヘアが秋風ではねている。スニーカーの白い底が石畳を蹴る音。六月の時は振り返らなかった。今日は——丘の中腹で、一度だけ足が止まった。振り返りはしなかった。けれど止まった。二秒。それから歩き出した。"}, {"id": "ch09-s04-p104", "type": "text", "text": "入口の木の扉の前に立った。扉の把手に手をかけた。冷たい金属。"}, {"id": "ch09-s04-p105", "type": "text", "text": "風祭さんの声が頭の中に残っていた。「嘘つくの下手なくせに」。二度繰り返した同じ言葉。千歳が「大丈夫」と笑うたびに、風祭さんはその嘘を見抜いて、見抜いたことを千歳に言えずに飲み込んできた。何百回も。"}, {"id": "ch09-s04-p106", "type": "text", "text": "残響祭の日の響弦館を思い出した。袖幕の向こうで腕を組んで待っていた風祭さん。千歳が揺れた瞬間に四歩で到達した風祭さん。あの時は「祈り」に見えた。祈りではなく準備だった。——今日の風祭さんは、準備すら追いつかなくなっている。"}, {"id": "ch09-s04-p107", "type": "text", "text": "千歳の訓練量が増えている。週三から週五。一日三時間。選抜公演に向けて。千歳は自分から望んだ。風祭さんはそれを止められない。千歳が「歌いたいから歌う」のなら、風祭さんにはそれを否定する言葉がない。あの公演の日に風祭さん自身がそう言った。「歌いたいから歌うんでしょ？ じゃあそれでいい」。"}, {"id": "ch09-s04-p108", "type": "text", "text": "それでよくない時が来ている。"}, {"id": "ch09-s04-p109", "type": "text", "text": "風祭さんはそれを知っていて、けれど千歳の「大丈夫」を崩す方法を持っていない。だから俺に言いに来た。壁の向こうから手を伸ばした。風祭さんが俺に助けを求めるということの重さが、鳩尾の上のあたりにある。千歳の場所。鳴海さんの歌声を聴いた時と同じ座標に、千歳の体調への心配が乗っている。"}, {"id": "ch09-s04-p110", "type": "text", "text": "心配。"}, {"id": "ch09-s04-p111", "type": "text", "text": "その言葉がすんなり出てきた。千歳の訓練後のふらつきが、千歳の瞳の色の薄れが、千歳の首元を押さえる癖が——業務上の観察ではなくなっている。いつからそうなったのか、正確にはわからない。鳩尾の上。千歳の場所。ここに今、「心配」が入っている。仕事として計測値を見ていた頃にはなかった重さ。"}, {"id": "ch09-s04-p112", "type": "text", "text": "風祭さんの「守っている」を、前回この場所で見た。今日見たのは、「守りきれなくなっている」だった。"}, {"id": "ch09-s04-p113", "type": "text", "text": "扉を引いた。訓練棟の中の空気が顔に当たった。石と金属の匂い。残響灯の青白い光が廊下の奥まで伸びている。"}, {"id": "ch09-s04-p114", "type": "text", "text": "機材チェックに向かった。校正作業をしながら、風祭さんの声と千歳の体調のことを、頭の中に並べて置いた。意味がわからないものを意味がわからないまま持っておく。保留にする。六月の「そういうことじゃなくて」と、今日の「嘘つくの下手なくせに」を、同じ棚に並べた。"}, {"id": "ch09-s04-p115", "type": "text", "text": "覚えておく。"}]}, {"chapter": 9, "chapterTitle": "記録室の静寂", "scene": 5, "sceneTitle": "記録室の約束", "wordCount": "約5,000字", "paragraphs": [{"id": "ch09-s05-p001", "type": "text", "text": "記録室の窓が、橙ではなかった。"}, {"id": "ch09-s05-p002", "type": "text", "text": "紫だった。十月の十八時。日没から二十分ほど経った時間帯。夏の名残があった九月までは十八時でもまだ橙が残っていたが、今はもう暗い。記録室の小さな窓から入る光は、空の底に沈んだ紫と、街灯が点き始めた下界のわずかな暖色が混ざったもの。机の上を照らすには足りない。残響灯の青白い光だけが、インク壺とペンと清書用紙を浮かび上がらせていた。"}, {"id": "ch09-s05-p003", "type": "text", "text": "木箱に座っている。定位置。机の右寄り。けれど今日はペンを持っていなかった。"}, {"id": "ch09-s05-p004", "type": "text", "text": "清書はない。今日は別の用件で来ている。"}, {"id": "ch09-s05-p005", "type": "text", "text": "篠宮さんから伝言があった。三日前、いつもの作業を終えた後に。"}, {"id": "ch09-s05-p006", "type": "text", "text": "「朝霧さん。ルミエラ島について、いくつか見つかりました。少しお時間をいただけますか」"}, {"id": "ch09-s05-p007", "type": "text", "text": "声は平坦だった。いつもの篠宮さんの音量。壁に届かない程度の声。けれど「見つかりました」という四文字の響きに、記録室の空気が狭くなった感覚があった。"}, {"id": "ch09-s05-p008", "type": "text", "text": "日時を指定した。今日の十八時。通常の清書作業の時間ではなく、閉館に近い時間を選んだのは篠宮さんだった。理由は聞いていない。"}, {"id": "ch09-s05-p009", "type": "text", "text": "記録室は静かだった。一つのペンの音もない。俺も書いていない。篠宮さんも書いていない。篠宮さんの手は机の上にあった。左手にメモ帳。24冊目。右手に厚紙の封筒。見慣れない封筒だった。角が折れていない。中に何枚か入っている。"}, {"id": "ch09-s05-p010", "type": "text", "text": "「朝霧さん」"}, {"id": "ch09-s05-p011", "type": "text", "text": "篠宮さんが口を開いた。"}, {"id": "ch09-s05-p012", "type": "text", "text": "「先日のルミエラ島について、いくつか見つかりました」"}, {"id": "ch09-s05-p013", "type": "text", "text": "同じ言葉だった。三日前の伝言と同じ。篠宮さんは同じ文を二度使うことがある。台帳の書式と同じで、決まった言葉を決まった場所に置く。この場合の「先日の」は枕詞。「いくつか」は分量の提示。本題はこの後。"}, {"id": "ch09-s05-p014", "type": "text", "text": "封筒を開いた。中から三枚の紙が出てきた。"}, {"id": "ch09-s05-p015", "type": "text", "text": "一枚目は写真だった。"}, {"id": "ch09-s05-p016", "type": "text", "text": "厚手の印画紙。角が黄ばんでいる。古い。十年以上前の撮影だろう。画面は不鮮明で、全体に靄がかかったようにぼやけている。けれど——"}, {"id": "ch09-s05-p017", "type": "text", "text": "丘の斜面に果樹が並んでいた。"}, {"id": "ch09-s05-p018", "type": "text", "text": "等間隔ではなかった。自然に生えたものを手入れした配置。枝が横に広がっている。低木ではない。人の背丈を超える高さがある。幹の太さは見えないが、影の長さから成木とわかった。丘の向こう側に海が覗いていた。海の色が薄い。晴天の日の、水平線近くの色。"}, {"id": "ch09-s05-p019", "type": "text", "text": "「果樹園の写真です」"}, {"id": "ch09-s05-p020", "type": "text", "text": "篠宮さんの声。"}, {"id": "ch09-s05-p021", "type": "text", "text": "「中央記録館の郷土資料区画から見つけました。ルミエラ島の消滅報告に添付されていた視覚資料の一枚です。画質は良くありませんが……島の北側斜面に果樹園が広がっていたことが確認できます」"}, {"id": "ch09-s05-p022", "type": "text", "text": "北側斜面。果樹園。海。"}, {"id": "ch09-s05-p023", "type": "text", "text": "写真を見ていた。不鮮明な画像の中の果樹の列を、目が追っていた。何を探しているのか自分でもわからなかった。ただ目が止まらなかった。木の一本一本を確認するように、画面の隅から隅まで。"}, {"id": "ch09-s05-p024", "type": "text", "text": "何も見覚えがなかった。当然だ。十年前に消えた島の写真を見て何かを思い出すはずがない。"}, {"id": "ch09-s05-p025", "type": "text", "text": "けれど、目が止まらない理由を説明できなかった。"}, {"id": "ch09-s05-p026", "type": "text", "text": "二枚目を出した。"}, {"id": "ch09-s05-p027", "type": "text", "text": "紙一枚に手書きの文。篠宮さんの字ではなかった。誰かの——中央記録館の職員か、あるいは消滅報告の作成者の字。崩れた楷書で、次のように記されていた。"}, {"id": "ch09-s05-p028", "type": "text", "text": "「ルミエラ島では年に数回の祭りが行われていたとされる。最も重要な祭りは秋の収穫祭で、島民が果樹園の広場に集まり、収穫を祝った。祭りでは島に伝わる歌が歌われたという」"}, {"id": "ch09-s05-p029", "type": "text", "text": "収穫祭。秋。果樹園。"}, {"id": "ch09-s05-p030", "type": "text", "text": "読み上げはしなかった。黙読した。文字の上を目が移動する速度が、通常の清書作業よりも遅かった。"}, {"id": "ch09-s05-p031", "type": "text", "text": "三枚目。"}, {"id": "ch09-s05-p032", "type": "text", "text": "篠宮さんの字だった。メモ帳からの転記。篠宮さんが資料を読み、必要な部分を抜き出して清書したもの。"}, {"id": "ch09-s05-p033", "type": "text", "text": "「月夜唄——ルミエラ島に伝わる子守唄のような歌。満月の夜に歌われたとの記述あり。作曲者不明。歌詞の記録は残っていない。複数の聞き取り記録に『月夜唄』の名称のみ確認。旋律を知る者は確認されず」"}, {"id": "ch09-s05-p034", "type": "text", "text": "月夜唄。"}, {"id": "ch09-s05-p035", "type": "text", "text": "読んだ。"}, {"id": "ch09-s05-p036", "type": "text", "text": "頭の左側が痛んだ。"}, {"id": "ch09-s05-p037", "type": "text", "text": "こめかみの奥、目の後ろのあたり。鋭い痛みではなかった。鈍い。低い。脈と同期していない、重たい圧迫感。こめかみの内側を内側から押されているような——甘い食べ物を食べた時と同じ頭痛だった。"}, {"id": "ch09-s05-p038", "type": "text", "text": "同じだ。"}, {"id": "ch09-s05-p039", "type": "text", "text": "甘い食べ物を口に入れた瞬間に来る、あの圧。食堂でカスタードプリンが出た時。燈花がクッキーを持ってきた時。甘さが舌に触れると、頭の左側が詰まる。理由がわからない頭痛。嫌な痛みではないのに止まらない。あれと同じ質の痛みが、今、「月夜唄」の文字を目で追っただけで来ている。"}, {"id": "ch09-s05-p040", "type": "text", "text": "文字を見ているだけで。味覚ではなく視覚。「月夜唄」という三文字が、甘い食べ物と同じ場所を押している。"}, {"id": "ch09-s05-p041", "type": "text", "text": "子守唄。満月の夜。歌われた。歌詞は残っていない。旋律を知る者もいない。"}, {"id": "ch09-s05-p042", "type": "text", "text": "記録にはそれだけしか残っていない。"}, {"id": "ch09-s05-p043", "type": "text", "text": "頭痛が脈を打った。一回。二回。三回。"}, {"id": "ch09-s05-p044", "type": "text", "text": "紙を置いた。三枚目を、一枚目と二枚目の上に重ねて、机の上に置いた。手の動きは普通だったはずだ。"}, {"id": "ch09-s05-p045", "type": "text", "text": "篠宮さんの視線があった。"}, {"id": "ch09-s05-p046", "type": "text", "text": "墨色の瞳が俺を見ていた。いつもの距離。机を挟んだ向かい側。残響灯の青白い光の中で、篠宮さんの黒髪のボブカットの輪郭が鮮明だった。前髪の下の瞳が、微かに動いた。俺の目から、俺の手元に。そして俺の目に戻った。"}, {"id": "ch09-s05-p047", "type": "text", "text": "何かに気づいただろうか。紙を読む速度が遅かったこと。三枚目を置く時の手の止まり方。あるいは顔に出たか——頭痛は表情に出るものなのか。わからない。篠宮さんの観察力は、メモ帳23冊分の精度がある。"}, {"id": "ch09-s05-p048", "type": "text", "text": "けれど篠宮さんは何も聞かなかった。"}, {"id": "ch09-s05-p049", "type": "text", "text": "沈黙が三秒あった。記録室の沈黙。ペンの音がない時の、この部屋の静けさ。窓の外で風が木の枝を揺らす音がして、遠くで犬が一度吠えて、やんだ。"}, {"id": "ch09-s05-p050", "type": "text", "text": "「朝霧さん」"}, {"id": "ch09-s05-p051", "type": "text", "text": "篠宮さんの声が来た。"}, {"id": "ch09-s05-p052", "type": "text", "text": "平坦ではなかった。"}, {"id": "ch09-s05-p053", "type": "text", "text": "いや——平坦だった。音量も速度も、いつもの篠宮さんの声域の中にある。けれどその中に、一つだけ変わったものがあった。呼びかけの「さん」の後に、間があった。「朝霧さん」と「次の言葉」の間に、二秒。篠宮さんの句読点の間ではない間。言葉を選んでいる間。"}, {"id": "ch09-s05-p054", "type": "text", "text": "「この島に……何か、思い入れがありますか」"}, {"id": "ch09-s05-p055", "type": "text", "text": "声が小さかった。"}, {"id": "ch09-s05-p056", "type": "text", "text": "壁に届かない声。篠宮さんの声には段階があるが、今のは最も小さい方に近い。俺と篠宮さんの間の空気だけを振動させる音量。三日前の伝言とも、資料の説明とも違う。業務の声ではなかった。"}, {"id": "ch09-s05-p057", "type": "text", "text": "思い入れ。"}, {"id": "ch09-s05-p058", "type": "text", "text": "篠宮さんがその言葉を使ったことに、耳が引っかかった。篠宮さんは正確な言葉を選ぶ。記録係の語彙で話す人だ。「関心がありますか」ではなく「思い入れがありますか」。「関心」は外側の言葉だが、「思い入れ」は内側の言葉だ。篠宮さんは俺の内側を聞いている。"}, {"id": "ch09-s05-p059", "type": "text", "text": "これは——篠宮さんにとって、大胆な踏み込みだ。"}, {"id": "ch09-s05-p060", "type": "text", "text": "五月のあの日。「朝霧さんも……出身は、不明なのですか」。あの時も壁に届かない声だった。俺の出自に初めて踏み込んだ。今回は俺の「思い入れ」に踏み込んでいる。出自は事実の確認だが、思い入れは感情の確認だ。事実より一歩遠い場所を、篠宮さんが聞いている。"}, {"id": "ch09-s05-p061", "type": "text", "text": "頭痛がまだあった。こめかみの奥で低く脈打っている。甘い食べ物の頭痛と同じ質の、鈍い圧。"}, {"id": "ch09-s05-p062", "type": "text", "text": "「わからない」"}, {"id": "ch09-s05-p063", "type": "text", "text": "答えた。"}, {"id": "ch09-s05-p064", "type": "text", "text": "嘘ではなかった。思い入れがあるのかどうか、わからない。ルミエラ島という名前を見ると鳩尾の奥が動く。月夜唄と読むと頭が痛む。口が「ルミエラ島」の発音を知っている。それらは事実だが、「思い入れ」かどうかは判定できない。"}, {"id": "ch09-s05-p065", "type": "text", "text": "「わからない」の後に、言葉が続いた。"}, {"id": "ch09-s05-p066", "type": "text", "text": "「でも……調べてほしい」"}, {"id": "ch09-s05-p067", "type": "text", "text": "出た。"}, {"id": "ch09-s05-p068", "type": "text", "text": "「調べてほしい」が出た。「もっと詳しい記録はありますか」と聞いた地下書庫の時と同じ種類の、能動的な依頼。あの時は「知りたい」だった。今は「調べてほしい」。知りたいの先に、誰かに頼むという行為が加わっている。篠宮さんに。"}, {"id": "ch09-s05-p069", "type": "text", "text": "頭痛を言わなかった。"}, {"id": "ch09-s05-p070", "type": "text", "text": "甘い食べ物で頭痛がすることは、誰にも言っていない。些細なことだった。些細なことを——篠宮さんに心配をかけるために言う必要はなかった。心配をかけたくない。その判断が浮かんだ。"}, {"id": "ch09-s05-p071", "type": "text", "text": "心配をかけたくない。"}, {"id": "ch09-s05-p072", "type": "text", "text": "初めてだった。誰かに「心配をかけたくない」と思うのは。いつもは「わからないことはわからないと言う」が俺の原則だった。聞かれれば答える。嘘はつけない。けれど今、頭痛のことを言わないという選択を、自分から行っている。"}, {"id": "ch09-s05-p073", "type": "text", "text": "嘘ではない。聞かれていないから答えない。それだけのことだ。——それだけ、と割り切れるかどうかは、わからなかった。"}, {"id": "ch09-s05-p074", "type": "text", "text": "篠宮さんの瞬きが止まった。"}, {"id": "ch09-s05-p075", "type": "text", "text": "二秒。三秒。四秒。墨色の瞳が動かない。「わからない。でも調べてほしい」の二つの文を、篠宮さんの中で照合している。わからないのに調べてほしいということの意味を、記録係の精度で確認している。"}, {"id": "ch09-s05-p076", "type": "text", "text": "瞬きが戻った。"}, {"id": "ch09-s05-p077", "type": "text", "text": "篠宮さんの右手がメモ帳に伸びた。24冊目。ページを開いた。ルミエラ島の横に印をつけたあのページの、数行下。ペンを取った。インクをつけた。何かを書き始めた——途中で止まった。ペン先が紙の上で留まっている。"}, {"id": "ch09-s05-p078", "type": "text", "text": "「私は、諦めません」"}, {"id": "ch09-s05-p079", "type": "text", "text": "声が出た。"}, {"id": "ch09-s05-p080", "type": "text", "text": "低かった。あの時と同じ低さ。五月の記録室で、夕日が赤くなりかけていた時間帯に聞いた声。語尾が下降しない声。「ません」の「ん」が水平のまま終わる声。記録係ではなく。"}, {"id": "ch09-s05-p081", "type": "text", "text": "けれど——同じではなかった。"}, {"id": "ch09-s05-p082", "type": "text", "text": "あの時の「諦めません」は、蓮という出身不明の人間に対する、漠然とした約束だった。記録が見つかるかもしれない。その可能性に向けた意思表明。何を探すかも、どこを探すかも定まっていなかった。"}, {"id": "ch09-s05-p083", "type": "text", "text": "今の「諦めません」には、ルミエラ島がある。"}, {"id": "ch09-s05-p084", "type": "text", "text": "月夜唄がある。果樹園がある。三百人の島民がいた島がある。記録カードの一枚から始まって、果樹園の写真と祭りの記述と月夜唄の概要を、篠宮さんは自分で探して持ってきた。あの五月の「諦めません」は宛先のない矢だった。今回は——宛先がある。ルミエラ島という名前と、俺の鳩尾の奥が反応する何かに向けて、矢が放たれている。"}, {"id": "ch09-s05-p085", "type": "text", "text": "「記録が残っている限り」"}, {"id": "ch09-s05-p086", "type": "text", "text": "篠宮さんが付け足した。"}, {"id": "ch09-s05-p087", "type": "text", "text": "声は小さかった。壁に届かない声。けれど語尾の「り」は、下降しなかった。水平のまま、記録室の空気の中に置かれた。"}, {"id": "ch09-s05-p088", "type": "text", "text": "メモ帳に視線を落とした篠宮さんの指が、ページの隅を押さえていた。写真と紙を挟んだページ。自分が集めた資料を挟んだ場所。大切なものを挟む時の動作。"}, {"id": "ch09-s05-p089", "type": "text", "text": "窓の外が暗くなっていた。紫が消えて、夜の藍色に変わりつつある。残響灯の光だけが記録室を照らしている。青白い光の中で、篠宮さんの前髪の下の瞳が墨よりも黒く見えた。"}, {"id": "ch09-s05-p090", "type": "text", "text": "「ありがとう」"}, {"id": "ch09-s05-p091", "type": "text", "text": "言った。"}, {"id": "ch09-s05-p092", "type": "text", "text": "遅れなかった。"}, {"id": "ch09-s05-p093", "type": "text", "text": "あの時の「ありがとう」は三秒遅れた。感情を込めたくて込められなくて、五つの音が喉で詰まった。今回は詰まらなかった。二文字目の「り」が出る頃には、もう全部が口の外に出ていた。"}, {"id": "ch09-s05-p094", "type": "text", "text": "込められただろうか。わからない。声は自分の耳には普段と同じに聞こえた。けれど遅れなかった。それだけは確かだった。"}, {"id": "ch09-s05-p095", "type": "text", "text": "篠宮さんのペンが動いた。"}, {"id": "ch09-s05-p096", "type": "text", "text": "メモ帳の上を走る音。かりかり。一つのペンの音だけが記録室に落ちた。何を書いているのかは見えなかった。篠宮さんの字は小さくて、斜め向かいからでは読めない。"}, {"id": "ch09-s05-p097", "type": "text", "text": "十七時半の鐘は、とうに過ぎていた。閉館の時間。図書館は閉まっているはずだが、記録室には鍵がある。篠宮さんの首元の銀の鍵。閉館後のこの部屋は、篠宮さんの場所だ。"}, {"id": "ch09-s05-p098", "type": "text", "text": "立ち上がった。木箱から腰を上げる。"}, {"id": "ch09-s05-p099", "type": "text", "text": "「では、また」"}, {"id": "ch09-s05-p100", "type": "text", "text": "篠宮さんが頷いた。顎が一センチほど下がって、戻る。いつもの頷き。"}, {"id": "ch09-s05-p101", "type": "text", "text": "記録室を出た。書架の間を歩いた。閉館後の図書館は灯りが落ちている。残響灯の弱い光だけが通路を照らしていた。階段を降りた。受付は無人だった。"}, {"id": "ch09-s05-p102", "type": "text", "text": "図書館の扉を開けた。"}, {"id": "ch09-s05-p103", "type": "text", "text": "十月の夜の空気が顔に当たった。冷たい。息が白くなる季節までもう少し。街灯の明かりが石畳を黄色く照らしている。残響桜の葉はほとんど落ちていた。枝の輪郭が夜空に細く伸びている。"}, {"id": "ch09-s05-p104", "type": "text", "text": "歩き出した。"}, {"id": "ch09-s05-p105", "type": "text", "text": "頭痛はまだあった。薄くなっているが、消えてはいない。こめかみの奥の低い圧。月夜唄の三文字が引き起こした、甘い食べ物と同じ種類の痛み。"}, {"id": "ch09-s05-p106", "type": "text", "text": "子守唄。"}, {"id": "ch09-s05-p107", "type": "text", "text": "月夜唄は子守唄のような歌だと記録にあった。満月の夜に歌われた。歌詞は残っていない。旋律を知る者もいない。"}, {"id": "ch09-s05-p108", "type": "text", "text": "子守唄は、誰に歌うものか。子供にだ。"}, {"id": "ch09-s05-p109", "type": "text", "text": "甘い食べ物を食べた時の頭痛。甘い味。子供の頃に食べるもの。子守唄。子供に歌うもの。"}, {"id": "ch09-s05-p110", "type": "text", "text": "どちらも——幼い記憶の場所に繋がっている。"}, {"id": "ch09-s05-p111", "type": "text", "text": "鐘の音。歯車。月夜唄。そして甘い食べ物。四つになった。四つが同じ出処に向かっている。鳩尾の奥にある、名前のつかない場所。俺の空白の中にあるもの。"}, {"id": "ch09-s05-p112", "type": "text", "text": "ルミエラ島がその空白の中にあるのかどうか、まだわからない。わからないが、篠宮さんが探してくれている。「記録が残っている限り」。あの声は、五月の「諦めません」の続きだった。宛先のない約束が、今日、ルミエラ島という座標を持った。"}, {"id": "ch09-s05-p113", "type": "text", "text": "篠宮さんは依頼されたから探しているのではなかった。"}, {"id": "ch09-s05-p114", "type": "text", "text": "S2で「探してみます」と言った後、俺が追加の依頼をしたわけではない。篠宮さんが自分で動いて、中央記録館の郷土資料区画から写真を見つけ、聞き取り記録から祭りの記述を拾い、月夜唄の情報を転記した。蓮のために自分から動いた。その行動の分量が、封筒の中の三枚の紙に詰まっていた。"}, {"id": "ch09-s05-p115", "type": "text", "text": "管理室に戻った。鍵を開けて中に入った。机の上の点検記録帳は開いたまま。今朝の数値が書きかけだった。"}, {"id": "ch09-s05-p116", "type": "text", "text": "椅子に座った。"}, {"id": "ch09-s05-p117", "type": "text", "text": "頭痛がようやく引きかけていた。こめかみの奥の圧が薄くなり、通常の感覚に戻りつつある。"}, {"id": "ch09-s05-p118", "type": "text", "text": "S4の終わりに、鳩尾の上に「心配」があった。千歳の体調のことと、風祭さんの声のこと。それは今もある。消えていない。その隣に、今日、別のものが加わった。"}, {"id": "ch09-s05-p119", "type": "text", "text": "篠宮さんの「諦めません」。二度目の。ルミエラ島という宛先を持った、二度目の約束。"}, {"id": "ch09-s05-p120", "type": "text", "text": "覚えておく。"}, {"id": "ch09-s05-p121", "type": "text", "text": "月夜唄。子守唄。甘い食べ物と同じ頭痛。篠宮さんの声。全部。"}]}, {"chapter": 10, "chapterTitle": "霜月の技師", "scene": 1, "sceneTitle": "深夜の点検", "wordCount": "約5,800字", "paragraphs": [{"id": "ch10-s01-p001", "type": "text", "text": "端末が鳴った。"}, {"id": "ch10-s01-p002", "type": "text", "text": "枕元の端末。振動音が木の天板を伝って、暗闇の中に低い音を落としている。反射的に腕が伸びた。画面の光が暗順応した目を刺す。0:47。メッセージが一行。"}, {"id": "ch10-s01-p003", "type": "text", "text": "「鐘出力に微細変動。機構室点検。0100」"}, {"id": "ch10-s01-p004", "type": "text", "text": "送信者は霜月さんだった。名前の表示を確認するまでもなく、文章の形でわかった。主語がない。敬語がない。時刻が四桁の数字。霜月さん以外にこの文の書き方をする人はいない。"}, {"id": "ch10-s01-p005", "type": "text", "text": "布団から足を出した。十月の夜の空気が脛に触れた。冷たい。九月の終わりから夜の気温が落ち始めていて、今はもう夏の残りがどこにもない。補佐官舎の壁は薄く、夜は外気とほぼ同じ温度まで下がる。"}, {"id": "ch10-s01-p006", "type": "text", "text": "制服に着替えた。灰色のシャツのボタンを一番上まで留め、濃紺のジャケットを羽織る。左手首のブレスレットに指先が一瞬触れた。毎朝と同じ。深夜でも変わらない。"}, {"id": "ch10-s01-p007", "type": "text", "text": "官舎を出た。"}, {"id": "ch10-s01-p008", "type": "text", "text": "灯籠通りの灯籠は消えていた。深夜の消灯時間は二十三時。石畳に光を落とすものは、通りの端に二つだけ残された常夜灯だけだった。黄色い光が小さな円を描いている。その円と円のあいだの暗闘を歩いた。暗闘ではない。暗がりだ。靴底が石畳を踏む音だけが聞こえる。自分の足音。それ以外の音がない。"}, {"id": "ch10-s01-p009", "type": "text", "text": "鐘鋳塔が近づくと、残響灯の光が見えた。塔の外壁に這う残響紋が、通常より暗い青白さで光っていた。深夜モードだった。通常の半分以下の輝度。壁面の紋様が暗がりの中で這うように浮かび上がっている。昼間は紋様の線が壁に刻まれた装飾に見えるが、この時間帯は違う。光そのものが壁の上を移動しているように見える。生き物の毛細血管を流れる何かのように。"}, {"id": "ch10-s01-p010", "type": "text", "text": "塔の入口の鍵を開けた。真鍮の丸頭鍵、A-01。管理室の鍵とは別の鍵。入口用。回す。施錠が解かれた音が夜に落ちて、石壁に吸われた。"}, {"id": "ch10-s01-p011", "type": "text", "text": "一階の管理室を通過した。計器は全て正常範囲内。第三系統の出力は誤差の範囲。第七系統の微振動、許容値。だが霜月さんが「微細変動」と書いたのは、これらの標準計器では拾えない精度の話だろう。霜月さんの数値基準は俺が日常的に記録している精度より二桁細かい。"}, {"id": "ch10-s01-p012", "type": "text", "text": "地下一階への階段を降りた。足裏に石の冷たさ。夜の鐘鋳塔の地下は、昼よりもさらに温度が低い。空気が動かない。天井の残響灯が深夜モードの弱い光を落としている。壁面の残響紋が這っている。昼間より紋の発光がゆっくりに見えた。光の脈動が遅い。鐘が深夜は出力を落としている。"}, {"id": "ch10-s01-p013", "type": "text", "text": "機構室の鉄扉の前に、白いコートの人影があった。"}, {"id": "ch10-s01-p014", "type": "text", "text": "霜月さんだった。壁面の残響灯の光の中に立っている。銀色のハーフアップが弱い青白い光を受けて、昼間よりも白く見えた。白いロングコート。深夜の一時に、いつもと同じ格好。着替えてきたのか、そもそも着替えずにいたのか。後者だろうと思った。霜月さんが鐘鋳塔で研究を続けて深夜になることは珍しくない。六月にも似た時間帯にすれ違ったことがある。"}, {"id": "ch10-s01-p015", "type": "text", "text": "「霜月さん、0100にまだ十三分あります」"}, {"id": "ch10-s01-p016", "type": "text", "text": "「早いな」"}, {"id": "ch10-s01-p017", "type": "text", "text": "時計を見ていなかった。だから0:47に呼び出されて十三分で着いたことを、霜月さんは声だけで計算した。声の中に評価はなかった。事実の確認。"}, {"id": "ch10-s01-p018", "type": "text", "text": "霜月さんが鉄扉の鍵を開けた。C-03。俺と同じ鍵。しかし霜月さんの鍵の回し方には音がなかった。真鍮が軋む手前で止めて、手首で錠前を送る。俺は四月から七ヶ月やっているが、まだ小さな軋みが出る。"}, {"id": "ch10-s01-p019", "type": "text", "text": "機構室に入った。"}, {"id": "ch10-s01-p020", "type": "text", "text": "深夜の歯車群は、呼吸が遅かった。"}, {"id": "ch10-s01-p021", "type": "text", "text": "壁一面の歯車。六月の梅雨、九月の秋口、そして十月の深夜。同じ歯車を何度も見ている。同じ歯面、同じ噛み合わせ。しかし夜の機構室は音の密度が違った。昼間は歯車の回転音の中に、上階の足音や管理室の計器のノイズや、塔全体の建物としての音が混ざっている。深夜は全部なくなる。歯車の回転音だけが、石壁に反射して戻ってくる。"}, {"id": "ch10-s01-p022", "type": "text", "text": "潤滑油の匂いが濃かった。夜の低温で揮発が抑えられ、空気中の油分が日中より厚い。金属の匂い。石の匂い。この場所の匂いは四月の着任初日からほとんど変わらない。"}, {"id": "ch10-s01-p023", "type": "text", "text": "携帯灯を点けた。霜月さんも点けた。二つの光が石の天井に広がった。"}, {"id": "ch10-s01-p024", "type": "text", "text": "「状況を説明する」"}, {"id": "ch10-s01-p025", "type": "text", "text": "霜月さんの声が機構室の壁に反射した。抑揚のない声。深夜でも変わらない。"}, {"id": "ch10-s01-p026", "type": "text", "text": "「二十二時の定期計測で、主鐘出力に0.05パーセントの変動を検知した。正の方向に0.03、負の方向に0.02。計器の分解能の限界に近いが、パターンに周期性がある。九分周期。鐘の固有振動モードとは一致しない。外因を排除する必要がある」"}, {"id": "ch10-s01-p027", "type": "text", "text": "0.05パーセント。俺の日常点検では気づかない精度だった。管理室の標準計器は0.1パーセント刻み。0.05パーセントは、霜月さんの三階の研究室にあるオシロスコープでなければ拾えない。"}, {"id": "ch10-s01-p028", "type": "text", "text": "「分担する。私は共鳴管の接合部と増幅器の入力端子。朝霧は歯車列の軸受けとグリスの状態を確認しなさい」"}, {"id": "ch10-s01-p029", "type": "text", "text": "「わかりました」"}, {"id": "ch10-s01-p030", "type": "text", "text": "作業が始まった。"}, {"id": "ch10-s01-p031", "type": "text", "text": "歯車列の軸受けに携帯灯を当てていく。一番から順に。軸受けの表面にグリスが薄い膜を作っている。梅雨の時期に全面グリスアップをしてから四ヶ月。夏を超えて、グリスの色がわずかに暗くなっている。酸化だ。まだ許容範囲内だが、十一月には交換が必要になるだろう。記録する。手帳に。日付、軸受け番号、グリスの状態。ペンの先が暗がりの中で紙を引っ掻く音がした。"}, {"id": "ch10-s01-p032", "type": "text", "text": "霜月さんの携帯灯の光が共鳴管の接合部を這っていた。銀色の管の表面を光が移動するたびに、霜月さんの指が管のボルトに触れる。指先でトルクを確かめている。レンチを使わずに。指だけで。俺にはできない精度。この人の指先は、規定トルクと現在トルクの差を、0.1ニュートンメートル単位で感知できるのだろう。"}, {"id": "ch10-s01-p033", "type": "text", "text": "二人の呼吸の音だけが聞こえる時間があった。歯車の回転音と、呼吸と、時折工具が金属に触れる音。会話はない。深夜の作業に会話は必要ない。必要な情報だけが声になって出る。それ以外は沈黙。この沈黙に居心地の悪さはなかった。六月の機構室で初めて並行作業をした時と同じ構造。しかし七ヶ月前より、隣にいる人の呼吸のリズムが深い場所に入っている。霜月さんは共鳴管のボルトを確認する時に吸い、手を離す時に吐く。それを知っている。"}, {"id": "ch10-s01-p034", "type": "text", "text": "八番歯車の軸受けまで確認した。異常なし。グリスの酸化以外に問題は見つからなかった。"}, {"id": "ch10-s01-p035", "type": "text", "text": "「歯車列、異常なし。グリスの経年劣化のみ確認しました」"}, {"id": "ch10-s01-p036", "type": "text", "text": "「こちらも共鳴管の接合部は正常。増幅器の入力端子に微量の酸化膜があった。清掃した」"}, {"id": "ch10-s01-p037", "type": "text", "text": "霜月さんの声が返った。携帯灯を消した。壁面の残響灯の光だけが機構室を照らしている。青白い。暗い。"}, {"id": "ch10-s01-p038", "type": "text", "text": "「三階で波形を確認する。来なさい」"}, {"id": "ch10-s01-p039", "type": "text", "text": "機構室を出て、階段を上がった。地下一階から三階まで。石段を踏む二人分の足音。霜月さんの足音は一定のリズムで、俺より小さい。けれど速い。歩幅が違うのに速度が同じだから、霜月さんの方がリズムが細かい。この人の歩行リズムを、体が覚えている。"}, {"id": "ch10-s01-p040", "type": "text", "text": "三階の通路。研究区画。残響灯が不規則に並んでいる。霜月さんの研究室の前の残響灯は、深夜モードでも他より明るかった。精密計器のための照度。"}, {"id": "ch10-s01-p041", "type": "text", "text": "鉄扉を開ける。研究室に入った。"}, {"id": "ch10-s01-p042", "type": "text", "text": "オシロスコープの画面が緑色の波形を描いていた。正弦波。しかし今夜は波形がわずかに揺れている。ベースラインが安定していない。九分周期の揺らぎ。画面を見つめると、確かに波形の頂点がゆっくりと上下していた。0.05パーセント。目では見えない振幅だが、計器の数値読みには現れる。"}, {"id": "ch10-s01-p043", "type": "text", "text": "霜月さんが椅子に座り、記録用紙を引き寄せた。ペンを取った。数値を読み上げ、転記していく。俺は隣に立って画面を見ていた。"}, {"id": "ch10-s01-p044", "type": "text", "text": "十五分ほど観察した。九分周期の変動は継続していたが、振幅に増大の傾向はなかった。安定した変動。一定の揺れ幅を保って、上がり、下がりを繰り返している。"}, {"id": "ch10-s01-p045", "type": "text", "text": "「外因ではないな」"}, {"id": "ch10-s01-p046", "type": "text", "text": "霜月さんが記録用紙にペンを置いた。"}, {"id": "ch10-s01-p047", "type": "text", "text": "「機構部に異常がない以上、出力変動は鐘そのものの挙動だ。固有振動モードと一致しない九分周期。外気温の変化か、残響紋の活性度の日内変動か。経過観察とする」"}, {"id": "ch10-s01-p048", "type": "text", "text": "声に感情がなかった。いつもの霜月さん。データを分析し、仮説を立て、結論を出す。深夜の一時半でも、手順は変わらない。"}, {"id": "ch10-s01-p049", "type": "text", "text": "「了解しました。明朝の点検で追加確認します」"}, {"id": "ch10-s01-p050", "type": "text", "text": "「ああ。——少し待ちなさい」"}, {"id": "ch10-s01-p051", "type": "text", "text": "霜月さんが椅子から立ち上がった。研究室の奥にある棚に向かい、電熱器を点けた。棚の上に小さなポットがある。水が入っていた。あらかじめ用意されていたものだ。"}, {"id": "ch10-s01-p052", "type": "text", "text": "電熱器の赤い光が暗い研究室の壁に暖色を落とした。残響灯の青白さの中に、小さな赤い光源が加わる。"}, {"id": "ch10-s01-p053", "type": "text", "text": "棚の下段から瓶が出てきた。コーヒー豆。ミルがあった。小さな手挽きのミル。霜月さんがミルのハンドルを回し始めた。暗い研究室に、豆が砕ける低い音が響いた。"}, {"id": "ch10-s01-p054", "type": "text", "text": "六月の機構室でコーヒーを渡された時のことを思い出した。「業務中の水分補給だ」と言って。苦くて温かかった。あれから四ヶ月。あの時は一杯だけだった。今は——"}, {"id": "ch10-s01-p055", "type": "text", "text": "ミルが止まった。霜月さんがフィルターに粉を入れ、湯を注いだ。注ぐ速度が均一だった。この人は何をやっても手順が正確だ。コーヒーを淹れる動作にも、共鳴管のボルトを確認する動作と同じ精度がある。"}, {"id": "ch10-s01-p056", "type": "text", "text": "カップが二つ、机の上に置かれた。"}, {"id": "ch10-s01-p057", "type": "text", "text": "二つ。"}, {"id": "ch10-s01-p058", "type": "text", "text": "「飲みなさい」"}, {"id": "ch10-s01-p059", "type": "text", "text": "声の温度は変わらなかった。業務口調。しかしカップは二つだった。一つは霜月さんの分。もう一つは俺の分。六月の機構室では「業務中の水分補給」と言った。今は何も言わなかった。ただカップを置いた。"}, {"id": "ch10-s01-p060", "type": "text", "text": "「いただきます」"}, {"id": "ch10-s01-p061", "type": "text", "text": "カップに手を伸ばした。白い陶器。縁が薄い。持ち上げると熱が指に伝わった。口をつけた。"}, {"id": "ch10-s01-p062", "type": "text", "text": "苦い。六月の時と同じ苦さ。しかし深夜の冷えた体に入ると、苦さの奥にある温度がはっきりと感じられた。喉を通って胸の中央に落ちていく。指先の冷えが少しだけ緩んだ。"}, {"id": "ch10-s01-p063", "type": "text", "text": "霜月さんもカップに口をつけた。白いコートの襟元。銀色の髪が残響灯の光を受けている。ラベンダーの瞳がカップの縁の向こうで半分閉じていた。"}, {"id": "ch10-s01-p064", "type": "text", "text": "一口飲んで、カップを下ろした。"}, {"id": "ch10-s01-p065", "type": "text", "text": "「……悪くない」"}, {"id": "ch10-s01-p066", "type": "text", "text": "声が小さかった。"}, {"id": "ch10-s01-p067", "type": "text", "text": "俺に向けた言葉ではなかった。コーヒーへの評価でもなかった。自分に向けた声。深夜の研究室で一人で作業を続けて、計器の数値を読んで、0.05パーセントの変動に気づいて、部下を呼び出して、点検して、結論を出して、コーヒーを淹れた。その一連の流れの最後に、自分自身の状態を確認するように漏れた声だった。"}, {"id": "ch10-s01-p068", "type": "text", "text": "霜月さんが疲れている、と思った。"}, {"id": "ch10-s01-p069", "type": "text", "text": "見えていた。白いコートの下。紺のスーツのシャツの襟元が、いつもより崩れていた。第一ボタンが外れている。霜月さんの第一ボタンが外れているのを見るのは初めてだった。いつもは首元まできちんと閉じている。髪のハーフアップも、左側に流した前髪の位置が普段より下がっている。後頭部で纏めた部分から数本の髪が漏れている。"}, {"id": "ch10-s01-p070", "type": "text", "text": "この人は深夜まで仕事をしていた。着替えていない。ここにいた。オシロスコープの前で数値を読み、記録用紙にペンを走らせ、0.05パーセントの変動に気づいたのは、この研究室を出ずにいたからだ。"}, {"id": "ch10-s01-p071", "type": "text", "text": "目の下に薄い影がある。残響灯の青白い光の中では見えにくいが、電熱器の暖色が横から当たった瞬間に影が浮かんだ。目の下の皮膚が、通常より暗い。寝ていない。"}, {"id": "ch10-s01-p072", "type": "text", "text": "霜月さんは自分の疲労を管理できる人だ。管理した上で、それでも0.05パーセントの変動は見過ごさない。"}, {"id": "ch10-s01-p073", "type": "text", "text": "コーヒーを飲みながら、少しの間、沈黙があった。研究室の沈黙。オシロスコープの波形が静かに揺れ続けている。電熱器の赤い光が消えた。湯が沸いて、自動で切れた。残響灯の青白い光だけに戻った。"}, {"id": "ch10-s01-p074", "type": "text", "text": "その光の中で、霜月さんの左耳に光るものが見えた。"}, {"id": "ch10-s01-p075", "type": "text", "text": "青い石。"}, {"id": "ch10-s01-p076", "type": "text", "text": "左耳のピアス。青い色の石が、残響灯の光を受けて暗い輝きを放っていた。深夜の研究室で、髪のハーフアップの左側が普段より下がっているから、耳のラインが見えている。その耳に、一つだけ。青い。"}, {"id": "ch10-s01-p077", "type": "text", "text": "六月にも見た。八月にも見た。九月にも見た。毎回同じ場所に、同じ石がある。霜月さんがいつもつけているもの。他にアクセサリーはない。指輪も、ネックレスも、ブレスレットもない。白いコートと紺のスーツと、左耳の青い石だけ。"}, {"id": "ch10-s01-p078", "type": "text", "text": "深夜の光の中で、石の青が通常より深く見えた。昼間は残響灯の光と混ざって青白く光るが、深夜モードの弱い光の中では石そのものの色が出ている。深い青。海の底のような青。"}, {"id": "ch10-s01-p079", "type": "text", "text": "「そのピアス、きれいですね」"}, {"id": "ch10-s01-p080", "type": "text", "text": "出た。"}, {"id": "ch10-s01-p081", "type": "text", "text": "考えて出したのではなかった。目が石の色を捉えて、口が動いた。「きれいですね」が頭の中を経由せずに声になった。言った後で気づいた。今、何を言った。"}, {"id": "ch10-s01-p082", "type": "text", "text": "きれい、と言った。"}, {"id": "ch10-s01-p083", "type": "text", "text": "鳴海さんの歌を聴いた時に「きれいだ」と思ったのと同じ言葉だった。鳴海さんの公演の後に「きれいでした」と言ったのと同じ語だった。きれいという音を、別の人の、別のものに向けて使った。意図してではなく。"}, {"id": "ch10-s01-p084", "type": "text", "text": "霜月さんの手が動いた。"}, {"id": "ch10-s01-p085", "type": "text", "text": "速かった。左手が左耳を覆った。カップを持つ右手は動かず、左手だけが耳に上がった。手のひらで左耳のピアスを隠すように。その動きは反射だった。考えてやったのではない。体が先に動いた。俺の歯車への触れ方と同じ——手が先に動く。思考より先に。"}, {"id": "ch10-s01-p086", "type": "text", "text": "その一瞬に、機構室で霜月さんが見せたことのない速度を見た。"}, {"id": "ch10-s01-p087", "type": "text", "text": "「……仕事に関係ない」"}, {"id": "ch10-s01-p088", "type": "text", "text": "声が短かった。鋭いわけではない。声量が落ちたわけでもない。ただ短かった。四つの音節で切られた。しごとにかんけいない。その後に言葉は続かなかった。"}, {"id": "ch10-s01-p089", "type": "text", "text": "霜月さんの左手が耳から離れた。一秒半。覆っていた時間。手がカップに戻った。両手でカップを持つ姿勢。ラベンダーの瞳が俺を見ていなかった。オシロスコープの画面を見ていた。画面の波形は変わらず九分周期で揺れている。"}, {"id": "ch10-s01-p090", "type": "text", "text": "「すみません」"}, {"id": "ch10-s01-p091", "type": "text", "text": "言った。謝罪ではなかった。正確に言えば、謝罪の形をした撤退だった。踏み込んではいけないものに触れた。霜月さんの手が教えてくれた。あの速度は、防衛だった。体が自動で守ったもの。あのピアスの向こう側に、霜月さんが触れられたくない何かがある。"}, {"id": "ch10-s01-p092", "type": "text", "text": "六月の機構室で、霜月さんが地下二階の階段の前で歩幅を変えた時のことを思い出した。あの時も霜月さんは何かを避けた。回避の動作だった。今度は違う。今度は、俺の言葉が当たった場所を手で塞いだ。回避ではなく防御。"}, {"id": "ch10-s01-p093", "type": "text", "text": "踏み込まない。"}, {"id": "ch10-s01-p094", "type": "text", "text": "いつものことだ。観察する。記録する。保留する。誰かの奥に触れそうになった時、俺は止まる。天城さんの翳りにも止まった。篠宮さんの震えにも止まった。鳴海さんの疲労にも止まった。風祭さんの壁にも止まった。霜月さんのピアスにも、止まる。"}, {"id": "ch10-s01-p095", "type": "text", "text": "けれど——"}, {"id": "ch10-s01-p096", "type": "text", "text": "霜月さんの左手が耳を覆った一秒半の間に見えたものが、消えない。"}, {"id": "ch10-s01-p097", "type": "text", "text": "この人が何かを抱えていることは、知っていた。地下二階の回避。人事ファイルの調査。星を計算で見る夜。全部つながっている。つながっているが、輪郭が見えない。今日、ピアスへの反応が加わった。青い石に触れられることへの防御。"}, {"id": "ch10-s01-p098", "type": "text", "text": "「何かを抱えている人」。八月の夜に霜月さんをそう認識した。「冷たい人」から「不器用な人」を経由して「何かを抱えている人」に至った。今、その「何か」が、ピアスの方角にあることだけがわかった。方角だけ。中身はわからない。聞かない。聞くべきではない。"}, {"id": "ch10-s01-p099", "type": "text", "text": "霜月さんが立ち上がった。"}, {"id": "ch10-s01-p100", "type": "text", "text": "カップを棚に置いた。空になったカップと、半分残った俺のカップ。"}, {"id": "ch10-s01-p101", "type": "text", "text": "「記録は私がまとめる。朝霧は戻りなさい。明朝0630に管理室で追加計測の指示を出す」"}, {"id": "ch10-s01-p102", "type": "text", "text": "声が業務口調に戻っていた。「仕事に関係ない」の四音節の後に、何もなかったかのように。ただの上司の指示。"}, {"id": "ch10-s01-p103", "type": "text", "text": "「わかりました。おやすみなさい」"}, {"id": "ch10-s01-p104", "type": "text", "text": "「——ああ」"}, {"id": "ch10-s01-p105", "type": "text", "text": "一拍、間があった。おやすみなさいへの返答に間がある人。業務以外の言葉に慣れていない人。六月のコーヒーの時と同じだ。「ありがとうございます」に対して「水分補給だ」と返した人。今日は「ああ」だけ。それでも一拍の間があったことが、何かの証拠だった。"}, {"id": "ch10-s01-p106", "type": "text", "text": "研究室を出た。鉄扉が閉まった。"}, {"id": "ch10-s01-p107", "type": "text", "text": "三階の通路を歩いた。階段を降りた。二階、一階、外。鐘鋳塔の入口を出ると、十月の深夜の空気が顔に当たった。冷たい。息が白くなる手前の冷たさ。空に星があった。雲がない。深夜の二時の空は、夕方とは別の暗さだった。"}, {"id": "ch10-s01-p108", "type": "text", "text": "灯籠通りの暗がりを歩いた。常夜灯の黄色い小さな円を二つ通り過ぎた。自分の足音だけ。"}, {"id": "ch10-s01-p109", "type": "text", "text": "研究室の残響灯の下で見た青い石の色が、まだ目の奥に残っていた。深い青。海の底のような色。霜月さんがあの石をつけている理由は知らない。知るべきではないかもしれない。けれど今日、あの人の手が耳を覆った速度は知った。体が自動で守るもの。大事なものほど、体は速く動く。"}, {"id": "ch10-s01-p110", "type": "text", "text": "燈花がヘアゴムに触れるのと同じだ。"}, {"id": "ch10-s01-p111", "type": "text", "text": "その連想が浮かんで、意味を考えかけて、やめた。違うかもしれない。同じかもしれない。どちらにしても、霜月さんの領域だ。"}, {"id": "ch10-s01-p112", "type": "text", "text": "補佐官舎の鍵を開けた。中に入った。靴を脱いだ。暗いまま寝台に座った。"}, {"id": "ch10-s01-p113", "type": "text", "text": "コーヒーの温度がまだ腹の中に残っていた。苦い後味。深夜の冷えた体に落ちた温かさ。二つのカップ。霜月さんは何も言わずにカップを二つ並べた。"}, {"id": "ch10-s01-p114", "type": "text", "text": "背中の奥で、何かが動いていた。四月から七ヶ月。「冷たい」が「不器用」に変わり、「不器用」が「何かを抱えている」に変わった。今日、もう一つ。あのピアスの青さと、耳を覆った手の速さが加わった。背中の奥にある何かの形が、少し変わった。名前はまだない。"}, {"id": "ch10-s01-p115", "type": "text", "text": "コーヒーの温かさ。青い石の深い色。一秒半の左手。"}, {"id": "ch10-s01-p116", "type": "text", "text": "背中の奥が、まだ温かかった。"}]}, {"chapter": 10, "chapterTitle": "霜月の技師", "scene": 2, "sceneTitle": "晶さん", "wordCount": "約4,200字", "paragraphs": [{"id": "ch10-s02-p001", "type": "text", "text": "南門の前で、黒いハーフコートが見えた。"}, {"id": "ch10-s02-p002", "type": "text", "text": "十二時半。昼休みの始まり。食堂に向かう途中だった。中庭を横切り、教室棟の前を通り、南門が視界に入った。"}, {"id": "ch10-s02-p003", "type": "text", "text": "六月の再会と同じ場所。石壁の柱に寄りかかるようにして、立っていた。"}, {"id": "ch10-s02-p004", "type": "text", "text": "濃い緑のジャケット。黒いカーゴパンツ。ブーツ。左胸の金属の階級章。腰のマルチツール。低い位置のポニーテール。"}, {"id": "ch10-s02-p005", "type": "text", "text": "桐ヶ谷さんだった。"}, {"id": "ch10-s02-p006", "type": "text", "text": "足が一瞬、速くなった。意図していない。鳩尾の奥が先に反応して、足に伝わった。六月の最初の再会、八月の見晴らし丘、そして今日。三回目。三回とも、体が先に動く。"}, {"id": "ch10-s02-p007", "type": "text", "text": "桐ヶ谷さんは北を向いていた。蝕域の方角ではない。門の外、灯籠通りの先を見ている。何かを待っているようにも、何も待っていないようにも見えた。ハーフコートの肩の角度は八月の見晴らし丘より緩んでいた。力が入っていない。"}, {"id": "ch10-s02-p008", "type": "text", "text": "足音で気づいた。こちらを向いた。半回転。琥珀色の瞳。"}, {"id": "ch10-s02-p009", "type": "text", "text": "十月の陽光の下の琥珀色は、八月の夕焼けの中で見た色とは違った。暖色の反射がない分、石の色そのものが出ていた。深い。硬くはなかった。八月の硬さが、今日は薄い。"}, {"id": "ch10-s02-p010", "type": "text", "text": "「蓮」"}, {"id": "ch10-s02-p011", "type": "text", "text": "名前。いつもの呼び捨て。しかし今日の声は、八月の「蓮」とも六月の「蓮」とも違っていた。力がない。力がないのではなく、力を使っていない。構えていない声。"}, {"id": "ch10-s02-p012", "type": "text", "text": "「桐ヶ谷さん」"}, {"id": "ch10-s02-p013", "type": "text", "text": "応えた。足が止まった。三メートルほどの距離。"}, {"id": "ch10-s02-p014", "type": "text", "text": "「定期報告の帰りですか」"}, {"id": "ch10-s02-p015", "type": "text", "text": "聞いた。六月に同じ説明を受けている。管理局への定期報告の帰りに学院に寄る。それが桐ヶ谷さんがここに来る理由だった。合理的な説明。管理局は内円区にあるから、帰り道としては遠回りだという事実には、六月から触れていない。"}, {"id": "ch10-s02-p016", "type": "text", "text": "「ああ。報告は終わった」"}, {"id": "ch10-s02-p017", "type": "text", "text": "桐ヶ谷さんが壁から背を離した。姿勢が伸びる。軍人の立ち方。しかし足が歩き出さなかった。俺の前に立ったまま、琥珀色の目がこちらを見ていた。"}, {"id": "ch10-s02-p018", "type": "text", "text": "十月中旬。空が高い。夏の靄が完全に抜けて、中庭の残響桜の向こうに鐘鋳塔の尖塔が見える。昼の陽光が桐ヶ谷さんの黒髪の表面に細い線を引いていた。硬い髪質。前髪を左に流した額の半分が、光を受けている。"}, {"id": "ch10-s02-p019", "type": "text", "text": "数秒の間があった。"}, {"id": "ch10-s02-p020", "type": "text", "text": "桐ヶ谷さんの右手がハーフコートのポケットに入り、出てきた。何も持っていなかった。また同じ動作。六月にも八月にもあった。三度目。何かを取り出しかけて、やめる。癖なのか。それとも本当に何かが入っていて、渡す判断をするたびに引っ込めているのか。"}, {"id": "ch10-s02-p021", "type": "text", "text": "「蓮」"}, {"id": "ch10-s02-p022", "type": "text", "text": "もう一度、名前。"}, {"id": "ch10-s02-p023", "type": "text", "text": "今度は音に変化があった。声が低い場所から出ていた。喉の奥。報告書を読む声でもなく、「深入りするな」の鋭い声でもなかった。声の底に何かが沈んでいる声。"}, {"id": "ch10-s02-p024", "type": "text", "text": "「お前、まだ私のこと『桐ヶ谷さん』って呼んでるのか」"}, {"id": "ch10-s02-p025", "type": "text", "text": "質問ではなかった。確認だった。答えを知っている上で口に出した言葉。"}, {"id": "ch10-s02-p026", "type": "text", "text": "琥珀色の瞳の奥で、何かがかすかに揺れた。六月の最初の再会で見た揺れと同じもの。喜びと痛みが同時にある揺れ。しかし今日の揺れはどちらかに偏っていた。痛みの方。いや——痛みではない。"}, {"id": "ch10-s02-p027", "type": "text", "text": "寂しさだった。"}, {"id": "ch10-s02-p028", "type": "text", "text": "その言葉がぴたりと当てはまった。桐ヶ谷さんが見せている感情を、名前で呼べたのは初めてだった。六月の揺れは「推測」だった。八月の硬さは「堪えている」と観察しただけだった。今日の表情には、もう少しはっきりした輪郭があった。寂しい。この人は寂しがっている。"}, {"id": "ch10-s02-p029", "type": "text", "text": "「昔は名前で呼んでくれたのに」"}, {"id": "ch10-s02-p030", "type": "text", "text": "声が軽かった。六月の南門で「昔は晶さんと呼んでいたのに」と言った時と同じ構造。深追いしない口調。事実を述べるだけの声。責めていない。"}, {"id": "ch10-s02-p031", "type": "text", "text": "しかし六月よりも、一段だけ声が低かった。低さの分だけ、軽さの下にあるものが近くなっていた。"}, {"id": "ch10-s02-p032", "type": "text", "text": "「……晶さんでいい。昔も、そう呼んでくれていた」"}, {"id": "ch10-s02-p033", "type": "text", "text": "桐ヶ谷さんの口から「晶さん」が出た。自分自身の名前を、俺が使うべき呼称として差し出した。"}, {"id": "ch10-s02-p034", "type": "text", "text": "鳩尾の奥が動いた。"}, {"id": "ch10-s02-p035", "type": "text", "text": "六月にも動いた場所。桐ヶ谷さんの場所。「知りたい」が北を向いている場所。その場所で、「晶さん」という音が反響した。"}, {"id": "ch10-s02-p036", "type": "text", "text": "口の中で、音を転がした。"}, {"id": "ch10-s02-p037", "type": "text", "text": "五月の南門の別れ際にもやった。声にはしなかった。口の筋肉がその音の形を知っていることに気づいて、けれど声にする理由がないと判断して、飲み込んだ。"}, {"id": "ch10-s02-p038", "type": "text", "text": "今日は——理由が、目の前にあった。"}, {"id": "ch10-s02-p039", "type": "text", "text": "桐ヶ谷さんの琥珀色の瞳。寂しさの輪郭。名前で呼ばれなくなった人間が見せる色。俺が記憶を失ったことで、この人から何かが奪われている。名前の距離。「蓮」と「桐ヶ谷さん」の間に横たわっている不均衡。この人は俺を知っている。俺はこの人を知らない。知らない人間の呼び方をしている。"}, {"id": "ch10-s02-p040", "type": "text", "text": "けれど——体は知っている。"}, {"id": "ch10-s02-p041", "type": "text", "text": "歯車を手が覚えているのと同じだ。鐘の音を耳が覚えているのと同じだ。口の筋肉が「晶さん」の形を覚えている。記憶にはない。記憶にはないけれど、体の中にある。"}, {"id": "ch10-s02-p042", "type": "text", "text": "迷いがあった。"}, {"id": "ch10-s02-p043", "type": "text", "text": "記憶にない過去の距離を、呼称で取り戻すことへの違和感。俺が「晶さん」と呼ぶのは、俺自身の記憶に基づいていない。体の記憶だ。体が覚えているだけで、頭には何もない。何もないまま名前で呼ぶことは、その名前の意味を知らないまま口にすることではないのか。"}, {"id": "ch10-s02-p044", "type": "text", "text": "桐ヶ谷さんは黙って立っていた。"}, {"id": "ch10-s02-p045", "type": "text", "text": "急かしていなかった。答えを待つ姿勢ですらなかった。ただ立っていた。ハーフコートの裾が十月の風に揺れている。低いポニーテールは揺れていなかった。いつもと同じ。硬い髪。"}, {"id": "ch10-s02-p046", "type": "text", "text": "しかし目だけが——俺を見ていた。"}, {"id": "ch10-s02-p047", "type": "divider", "text": "---"}, {"id": "ch10-s02-p048", "type": "choice", "text": "**【選択肢A】「晶さん」と呼ぶ**\n→ 呼称変化フラグ確定"}, {"id": "ch10-s02-p049", "type": "text", "text": "口が開いた。"}, {"id": "ch10-s02-p050", "type": "text", "text": "考えて出した声ではなかった。迷いの途中で、体が先に動いた。歯車に手が伸びるのと同じだ。適正値を頭が計算する前に、手が正しい位置に触れている。"}, {"id": "ch10-s02-p051", "type": "text", "text": "「……晶さん」"}, {"id": "ch10-s02-p052", "type": "text", "text": "声になった。"}, {"id": "ch10-s02-p053", "type": "text", "text": "音が南門の石壁の間で短く反響して、消えた。自分の声を聞いた。低かった。普段の声より。喉の深いところから出ていた。口の筋肉は覚えていた音を正確に作った。唇の開き方、舌の位置、息の量。全部、体が知っていた。頭が知らないだけで。"}, {"id": "ch10-s02-p054", "type": "text", "text": "桐ヶ谷さんが目を閉じた。"}, {"id": "ch10-s02-p055", "type": "text", "text": "一秒もなかった。まばたきより長く、深呼吸より短い。目蓋が降りて、上がった。"}, {"id": "ch10-s02-p056", "type": "text", "text": "目が開いた時、口元が動いていた。"}, {"id": "ch10-s02-p057", "type": "text", "text": "笑っていた。"}, {"id": "ch10-s02-p058", "type": "text", "text": "笑顔ではなかった。口の端が数ミリ上がり、目尻の線が一本だけ変わった。引き締まった表情のままで、しかし硬さが一枚落ちた。六月の南門で「不器用な人」と伝えた時に口元が動いたのと同じ種類だった。しかし今日の方が長かった。六月のは一瞬で消えた。今日のは——三秒ほど残った。"}, {"id": "ch10-s02-p059", "type": "text", "text": "「ああ。……それでいい」"}, {"id": "ch10-s02-p060", "type": "text", "text": "低い声。しかし刃がなかった。八月の「守りたいだけだ」の力みもなかった。六月の「深入りするな」の鋭さもなかった。平らな声。けれど平らさの下に温度があった。あの琥珀色の瞳と同じ温かさ。普段は隠れている温度。"}, {"id": "ch10-s02-p061", "type": "text", "text": "「それでいい」の「いい」が、少し長かった。一音分。意図したのかわからない。桐ヶ谷さん自身が気づいているかもわからない。けれど長かった。その一音の長さの中に、名前を取り戻した人間の安堵が入っていた。たぶん。"}, {"id": "ch10-s02-p062", "type": "divider", "text": "---"}, {"id": "ch10-s02-p063", "type": "choice", "text": "**【選択肢B】まだ「桐ヶ谷さん」で通す**\n→ 呼称変化なし（第14章で再度機会あり）"}, {"id": "ch10-s02-p064", "type": "text", "text": "口が開きかけて、閉じた。"}, {"id": "ch10-s02-p065", "type": "text", "text": "喉の奥まで音が来ていた。「あ」の形に唇が開きかけていた。「晶さん」の最初の一音。体は出そうとしていた。しかし頭が止めた。"}, {"id": "ch10-s02-p066", "type": "text", "text": "記憶がない。この人との過去を、俺は知らない。知らないまま、体が覚えている距離に戻ることは——正しいのか。"}, {"id": "ch10-s02-p067", "type": "text", "text": "「……すみません。もう少し、このままで」"}, {"id": "ch10-s02-p068", "type": "text", "text": "声が平らだった。平らに出した。"}, {"id": "ch10-s02-p069", "type": "text", "text": "桐ヶ谷さんの目が一瞬だけ細くなった。六月に「桐ヶ谷さん」と呼んだ時と同じ動き。痛みを薄く引き延ばす動作。しかし今日のは、痛みの後に——何かが加わった。うなずくような動き。首がわずかに下がって、戻った。"}, {"id": "ch10-s02-p070", "type": "text", "text": "「……わかった。急がなくていい」"}, {"id": "ch10-s02-p071", "type": "text", "text": "声が柔らかかった。八月の桐ヶ谷さんからは聞けなかった柔らかさ。「急がなくていい」は、「待っている」と同じ意味だった。"}, {"id": "ch10-s02-p072", "type": "divider", "text": "---"}, {"id": "ch10-s02-p073", "type": "text", "text": "風が吹いた。"}, {"id": "ch10-s02-p074", "type": "text", "text": "十月の昼の風。残響桜の葉が黄色くなりかけた枝先から一枚落ちて、石畳の上を滑っていった。桐ヶ谷さんのハーフコートの裾が風を受けた。"}, {"id": "ch10-s02-p075", "type": "text", "text": "「報告は以上だ」"}, {"id": "ch10-s02-p076", "type": "text", "text": "桐ヶ谷さんの声が、業務口調に戻った。いつもの打ち切り方。感情的な会話を業務で蓋をする癖。六月にも八月にもあった。この人の中で、何かが限界に近づくと「報告は以上だ」が出る。"}, {"id": "ch10-s02-p077", "type": "text", "text": "「はい」"}, {"id": "ch10-s02-p078", "type": "text", "text": "答えた。"}, {"id": "ch10-s02-p079", "type": "text", "text": "桐ヶ谷さんが南門の方を向いた。歩き出す前に、視線が一瞬だけ鐘鋳塔の方に流れた。白い石壁。昼の残響灯は見えない。けれど塔の輪郭は空を背にしてはっきり見えている。"}, {"id": "ch10-s02-p080", "type": "text", "text": "「鐘鋳塔の仕事は、続けろ」"}, {"id": "ch10-s02-p081", "type": "text", "text": "「はい」"}, {"id": "ch10-s02-p082", "type": "text", "text": "三回とも同じことを言う。六月も。八月も。今日も。「あそこにいろ」「あそこは悪くない場所だ」「続けろ」。桐ヶ谷さんは俺を鐘鋳塔につなぎ止めようとしている。あそこに俺の場所があると知っている人の声だった。"}, {"id": "ch10-s02-p083", "type": "text", "text": "桐ヶ谷さんが歩き出した。"}, {"id": "ch10-s02-p084", "type": "text", "text": "軍人の歩幅。背筋が伸びている。南門の石柱の間を通り抜ける。ハーフコートの裾が石柱の影を横切った。"}, {"id": "ch10-s02-p085", "type": "text", "text": "今日は——半歩だけ遅かった。"}, {"id": "ch10-s02-p086", "type": "text", "text": "六月の最初の再会の時に「半歩だけ遅い」と感じた歩幅。八月の見晴らし丘では正規の歩幅に戻っていた。今日はまた半歩遅い。"}, {"id": "ch10-s02-p087", "type": "text", "text": "振り返らなかった。三回とも。この人は振り返らない。"}, {"id": "ch10-s02-p088", "type": "text", "text": "足音が灯籠通りの石畳の上で遠くなり、角を曲がって消えた。"}, {"id": "ch10-s02-p089", "type": "text", "text": "南門の前に立ったまま、十月の風を受けていた。"}, {"id": "ch10-s02-p090", "type": "text", "text": "鳩尾の奥に、名前が一つ増えた。"}, {"id": "ch10-s02-p091", "type": "text", "text": "六月は「桐ヶ谷さん」しかなかった。今日から二つになった。「桐ヶ谷さん」と「晶さん」。どちらも同じ人を指している。しかし口の筋肉が作る形が違う。舌の位置が違う。息の出し方が違う。「桐ヶ谷さん」は今の俺の距離。「晶さん」は体が覚えている距離。"}, {"id": "ch10-s02-p092", "type": "text", "text": "二つの距離が鳩尾の奥で並んでいた。"}, {"id": "ch10-s02-p093", "type": "text", "text": "晶さんの琥珀色の瞳が目を閉じた一瞬を、覚えていた。まばたきより長く、深呼吸より短い。その一瞬の目蓋の裏で、あの人は何を見ていたのだろう。俺が名前を呼んでいた頃の記憶か。俺がまだ「蓮」で、あの人がまだ「晶さん」だった頃の時間か。"}, {"id": "ch10-s02-p094", "type": "text", "text": "俺にはその時間がない。"}, {"id": "ch10-s02-p095", "type": "text", "text": "ないけれど、口の筋肉にはある。声にした瞬間に、体が「合っている」と報告してきた。正しい呼び方。正しい距離。頭は知らないのに体が知っている正しさ。"}, {"id": "ch10-s02-p096", "type": "text", "text": "それで十分なのかはわからない。わからないけれど——晶さんの目が開いた時の、あの三秒の微笑みが、鳩尾の奥に落ちて、温かかった。"}, {"id": "ch10-s02-p097", "type": "text", "text": "食堂に向かった。昼休みの人の流れに合流する。教室棟の前を通り過ぎた。南門の石柱にはもう誰もいなかった。六月と同じ。あの場所はいつも、晶さんが去った後に空になる。"}, {"id": "ch10-s02-p098", "type": "text", "text": "覚えておく。"}, {"id": "ch10-s02-p099", "type": "text", "text": "晶さんの寂しさと、三秒の微笑みと、半歩遅い歩幅を。"}]}, {"chapter": 10, "chapterTitle": "霜月の技師", "scene": 3, "sceneTitle": "とおいしまの音", "wordCount": "約5,200字", "paragraphs": [{"id": "ch10-s03-p001", "type": "text", "text": "螺旋階段を上っている。"}, {"id": "ch10-s03-p002", "type": "text", "text": "二十時の鐘が鳴り終わって、十五分。管理室の計器を記録し、第七系統の微振動値を手帳に書き込み、ペンを棚に戻した。工具箱のロックを確認した。消灯スイッチの前で手が止まった。"}, {"id": "ch10-s03-p003", "type": "text", "text": "上へ行く。"}, {"id": "ch10-s03-p004", "type": "text", "text": "何度目か、もう数えていない。メンテナンス終わりに螺旋階段をそのまま上る。下に降りて管理室を出るのではなく、上へ。五月の頃にはまだ迷いがあった。七月にはなくなっていた。十月の今は、足が石段の一段目に触れた時点で迷いの痕跡すらない。"}, {"id": "ch10-s03-p005", "type": "text", "text": "石段の冷たさ。十月の石は九月より一段低い。靴底を通して報告してくる温度を、足裏が読んでいる。残響灯の青白い光が、上の階に進むにつれて紫に傾いていく。壁面の残響紋が曲線を描いている。この変化も、もう知っている。"}, {"id": "ch10-s03-p006", "type": "text", "text": "十階。大鐘の脇を通過した。鐘の表面に残響灯の光が当たり、刻まれた紋様の溝が細い線として浮かんでいる。触れなかった。四月からずっと。"}, {"id": "ch10-s03-p007", "type": "text", "text": "石段が木の床に変わった。"}, {"id": "ch10-s03-p008", "type": "text", "text": "天蓋の間に入った。"}, {"id": "ch10-s03-p009", "type": "text", "text": "十月の夜空が、ガラスの天蓋を通して円形に切り取られていた。星が多い。九月より多い。空気中の水分が減って、低い位置の星までにじまずに届いている。白い点が、黒の上に刺さっている。鮮明だった。"}, {"id": "ch10-s03-p010", "type": "text", "text": "壁面下部の間接照明。光源の見えない紫の光が、部屋の輪郭をぼんやりと描いている。薄紫の光と星の光。暗いが、見える。"}, {"id": "ch10-s03-p011", "type": "text", "text": "すみれがいた。"}, {"id": "ch10-s03-p012", "type": "text", "text": "部屋の中央。木の床に直接座っている。白いワンピースの裾が床に広がり、紫色の光を吸っている。淡い紫の長い髪が片方の肩から前に流れていた。裸足の足先が膝の前に出ている。首元の銀の鎖が、薄い光を一筋だけ反射していた。"}, {"id": "ch10-s03-p013", "type": "text", "text": "膝の横にノートはなかった。今夜は星を数えていない。"}, {"id": "ch10-s03-p014", "type": "text", "text": "すみれが振り返った。首が自然にこちらを向く。俺の足音を聞いていた。石段では響くが、木の床に変わった瞬間に弱まる足音。それでもわかる。"}, {"id": "ch10-s03-p015", "type": "text", "text": "口元が先に動いた。唇の端が上がる。目が追いかけて、0.5秒の遅延。変わらない。"}, {"id": "ch10-s03-p016", "type": "text", "text": "「れん」"}, {"id": "ch10-s03-p017", "type": "text", "text": "「ああ」"}, {"id": "ch10-s03-p018", "type": "text", "text": "隣に座った。"}, {"id": "ch10-s03-p019", "type": "text", "text": "四月は三歩の間隔だった。七月は一歩未満。十月の今はもっと近い。すみれの右肩と俺の左肩の間に、指三本分くらいの空間がある。計測しているのは俺の方だ。すみれは距離を数えない。"}, {"id": "ch10-s03-p020", "type": "text", "text": "「きょう、かぜ、つめたかったでしょ」"}, {"id": "ch10-s03-p021", "type": "text", "text": "「ああ。昼に中庭を歩いた時、手の甲が冷えた」"}, {"id": "ch10-s03-p022", "type": "text", "text": "「れんのて、つめたくなったの、すみれにはわかるよ。かねが、おしえてくれるから」"}, {"id": "ch10-s03-p023", "type": "text", "text": "鐘が教える。いつものすみれの文法。鐘の音で世界の情報を受け取る。俺の手の温度まで知っているのか。不思議だった。不思議、から先の名前はまだない。"}, {"id": "ch10-s03-p024", "type": "text", "text": "すみれが天蓋を見上げた。俺もつられて見上げた。十月の星空。鐘鋳塔は島で最も高い建物だから、天蓋の間からは空以外何も見えない。星と夜の色だけ。"}, {"id": "ch10-s03-p025", "type": "text", "text": "「ほし、しろい」"}, {"id": "ch10-s03-p026", "type": "text", "text": "「ああ。秋になると白くなる。空気が澄むから」"}, {"id": "ch10-s03-p027", "type": "text", "text": "「くうき、すむ」"}, {"id": "ch10-s03-p028", "type": "text", "text": "すみれが音を口の中で転がしていた。「くうき、すむ」。言葉の形を確かめるように。「どらやき」を繰り返した時と同じ動作。未知の言葉を舌で撫でて、自分のものにする手続き。"}, {"id": "ch10-s03-p029", "type": "text", "text": "「すんだくうきのほしは、とがってるね」"}, {"id": "ch10-s03-p030", "type": "text", "text": "「尖ってる、か」"}, {"id": "ch10-s03-p031", "type": "text", "text": "見上げた。確かに、九月の星より光の線が細い。点ではなく針に近い。すみれの言い方は、いつも妙に正確だった。「きれい」や「明るい」ではなく「とがってる」。すみれの言語にはフィルタがない。感覚から言葉への距離が短い。"}, {"id": "ch10-s03-p032", "type": "text", "text": "しばらく黙って星を見ていた。天蓋の間の沈黙。通路も壁もない空間を共有している。すみれの呼吸が微かに聞こえた。遅い。人間の安静時よりも長い間隔。ゆっくりとした時間の中に、すみれは存在している。"}, {"id": "ch10-s03-p033", "type": "text", "text": "風はなかった。天蓋は密閉されている。通気はあるが、空気の流れを肌では感じない。十月の夜の鐘鋳塔の最上階は、外気より少し低い。すみれは裸足だった。四月からずっと。靴を履いたすみれを見たことがない。"}, {"id": "ch10-s03-p034", "type": "text", "text": "「れん」"}, {"id": "ch10-s03-p035", "type": "text", "text": "「うん」"}, {"id": "ch10-s03-p036", "type": "text", "text": "すみれの声が変わった。"}, {"id": "ch10-s03-p037", "type": "text", "text": "変わった、と書くのは正確ではない。音量が同じ。高さも同じ。けれど声の底にあるものが動いた。星を見ている時の声は軽かった。今の声には重さがある。重さ、というよりは密度。同じ体積の中に、さっきより多くのものが入っている声。"}, {"id": "ch10-s03-p038", "type": "text", "text": "すみれの薄紫色の瞳が、俺を見ていた。星の光を映している。白い小さな点が瞳の中に散っている。七月にも同じ光景を見た。「このせかいは、いつかおわるよ」の直前に。"}, {"id": "ch10-s03-p039", "type": "text", "text": "「れん、おまえのなかに、とおいしまの音がある」"}, {"id": "ch10-s03-p040", "type": "text", "text": "静かだった。"}, {"id": "ch10-s03-p041", "type": "text", "text": "声は静かだった。「ほし、きれい」と同じ高さで出てきた。同じ力の抜け方で。しかし言葉の内容が重かった。"}, {"id": "ch10-s03-p042", "type": "text", "text": "「……島の音？」"}, {"id": "ch10-s03-p043", "type": "text", "text": "聞き返した。声が低くなっていた。自分でも気づいた。喉の深い場所から出た声。"}, {"id": "ch10-s03-p044", "type": "text", "text": "すみれが頷いた。頷きの動きが遅い。首が傾いて、戻るまでの間隔が長い。すみれ特有の遅さ。"}, {"id": "ch10-s03-p045", "type": "text", "text": "「うみのかなたの、ちいさなしま。そこのおとが、れんのなかで、まだなっている」"}, {"id": "ch10-s03-p046", "type": "text", "text": "鳩尾の奥が動いた。"}, {"id": "ch10-s03-p047", "type": "text", "text": "九月に地下書庫でルミエラ島のカードを読み上げた時と同じ場所。「月夜唄」で振動した場所。鐘の音の「懐かしさ」が住んでいる場所。その場所が、すみれの「とおいしまの音」という七文字に反応して、揺れた。"}, {"id": "ch10-s03-p048", "type": "text", "text": "九月の振動は微かだった。カードの文字に触れただけの振動。今のは違う。すみれの声を通して入ってきたものは、紙の上の文字ではなかった。声だった。誰かの声が「とおいしまの音」を言葉にした時に、その奥にあるものが応答した。応答、という言い方が合っているかわからない。けれど確かに動いた。揺れではなく、響いた。"}, {"id": "ch10-s03-p049", "type": "text", "text": "「すみれ。その島って……」"}, {"id": "ch10-s03-p050", "type": "text", "text": "「しま、なまえ、すみれはしらない。かねがおしえてくれるのは、おとだけだから」"}, {"id": "ch10-s03-p051", "type": "text", "text": "名前を知らない。音だけを知っている。"}, {"id": "ch10-s03-p052", "type": "text", "text": "すみれの認識の構造が、また少し見えた。鐘の音で世界の情報を受け取る。けれど情報の形が人間とは違う。名前ではなく音。文字ではなく振動。すみれが受け取っているのは、島という場所の名称ではなく、島が発していた音そのものだった。"}, {"id": "ch10-s03-p053", "type": "text", "text": "「……俺の中で鳴っている。そう言ったか」"}, {"id": "ch10-s03-p054", "type": "text", "text": "「うん。なっている。ずっと」"}, {"id": "ch10-s03-p055", "type": "text", "text": "ずっと。"}, {"id": "ch10-s03-p056", "type": "text", "text": "すみれの「ずっと」は信頼できない。時間感覚がずれている。「さっき」が何年前かわからない少女の「ずっと」は、一週間かもしれないし、十年かもしれない。けれどすみれがそう言う時、それは事実だった。嘘をつけない構造。蛇口から水が出ることを述べるのと同じ温度で、すみれは俺の中にある音を報告した。"}, {"id": "ch10-s03-p057", "type": "text", "text": "「四月から？」"}, {"id": "ch10-s03-p058", "type": "text", "text": "「もっとまえ」"}, {"id": "ch10-s03-p059", "type": "text", "text": "「……俺がこの島に来る前から？」"}, {"id": "ch10-s03-p060", "type": "text", "text": "すみれが小さく首を傾げた。傾げたまま戻らない。俺の質問の意味を測っている。"}, {"id": "ch10-s03-p061", "type": "text", "text": "「れんが、ここにくるまえ、すみれはかねのおとだけきいてた。れんがきて、かねのおとのなかに、べつのおとがまじってるのがわかった」"}, {"id": "ch10-s03-p062", "type": "text", "text": "鐘の音の中に、別の音。"}, {"id": "ch10-s03-p063", "type": "text", "text": "九月にルミエラ島のカードを読んだ日のことを思い出していた。「月夜唄」の三文字で鳩尾の奥が振動した。あの振動は鐘の音の「懐かしさ」と同じ出処から来ていた。歯車の「手が知っている」と同じ場所に繋がっていた。全部が一つのところに集まっている。"}, {"id": "ch10-s03-p064", "type": "text", "text": "すみれが言っているのは、その一つのところの話だろう。俺の中にある、記憶にはない場所からの音。俺には聞こえない。けれどすみれの鐘には届いている。"}, {"id": "ch10-s03-p065", "type": "text", "text": "「それは——歌か」"}, {"id": "ch10-s03-p066", "type": "text", "text": "口から出た。"}, {"id": "ch10-s03-p067", "type": "text", "text": "歌。なぜ歌と言ったのか。「月夜唄」がカードの上にあった。唄。歌。島に伝わっていた歌。口が先に動いた。ルミエラ島の名前を読み上げた時と同じだ。五文字の音が塊のまま出たのと同じ構造で、「歌か」が考える前に声になった。"}, {"id": "ch10-s03-p068", "type": "text", "text": "すみれの瞳が、一瞬だけ変わった。"}, {"id": "ch10-s03-p069", "type": "text", "text": "薄紫の色はそのままだった。瞳孔の大きさも変わらなかった。けれど瞳の奥にある光の層が、一枚増えた。光が加わった。星の反射ではない。すみれ自身から出た光。鐘の音に連動して変わる光——あの変化が、今、俺の言葉に反応して起きた。"}, {"id": "ch10-s03-p070", "type": "text", "text": "「れん、きこえてるんだね」"}, {"id": "ch10-s03-p071", "type": "text", "text": "すみれの声が糸の先端のように細くなった。"}, {"id": "ch10-s03-p072", "type": "text", "text": "「聞こえてない。聞こえていたら、歌だとわかるはずだ。俺は知らない。ただ口が——」"}, {"id": "ch10-s03-p073", "type": "text", "text": "言いかけて、止まった。"}, {"id": "ch10-s03-p074", "type": "text", "text": "口が先に動く。いつもそうだ。歯車に触れる時。ルミエラ島を読み上げる時。「晶さん」と呼ぶ時。俺の口の筋肉が知っている音。記憶にはないのに体の中にある音。"}, {"id": "ch10-s03-p075", "type": "text", "text": "その音を、すみれは「しまの音」と呼んでいる。"}, {"id": "ch10-s03-p076", "type": "text", "text": "「すみれ、お前は……何を知っているんだ」"}, {"id": "ch10-s03-p077", "type": "text", "text": "声が硬くなった。自分でわかった。詰問の形ではない。問いの密度が上がっただけだ。「知りたい」が体の芯で方向を変えずに強くなった。北。蝕域の方角。ルミエラ島の方角。すみれの方角。全部が同じ方向を向いている。"}, {"id": "ch10-s03-p078", "type": "text", "text": "すみれが微笑んだ。"}, {"id": "ch10-s03-p079", "type": "text", "text": "口元が先に動いた。唇の端が上がる。0.5秒遅れて目が追いかける。いつものずれた微笑み。けれど今夜の微笑みは、どら焼きの時のずれなしの笑顔とは違っていた。遅い方の微笑み。目が追いつくまでの0.5秒の間に、口元だけが先に形を作っている。その0.5秒の中に、すみれが言葉を選んでいる時間があった。"}, {"id": "ch10-s03-p080", "type": "text", "text": "「すみれは、かねのおとをきいている。かねのおとは、すべてをしっている」"}, {"id": "ch10-s03-p081", "type": "text", "text": "答えになっていなかった。"}, {"id": "ch10-s03-p082", "type": "text", "text": "俺が聞いたのは「お前は何を知っているんだ」であり、すみれが答えたのは「鐘の音が全てを知っている」だった。すみれが知っているのではなく鐘が知っている。すみれはそれを聞いているだけ。"}, {"id": "ch10-s03-p083", "type": "text", "text": "けれどそれは本当か。"}, {"id": "ch10-s03-p084", "type": "text", "text": "鐘が全てを知っている。すみれは鐘の音を聞いている。ならばすみれも全てを知っている。論理的にはそうなる。しかしすみれの言葉はいつも断片的だった。全てを知っているなら、全てを言えるはずだ。言えない。言わないのではなく、言えない。鐘の音を人間の言葉に変換する回路が、すみれの中で完全には繋がっていない。"}, {"id": "ch10-s03-p085", "type": "text", "text": "音を聞いている。聞いたものの全体は把握している。しかし人間の言語で伝えられるのは、断片だけ。"}, {"id": "ch10-s03-p086", "type": "text", "text": "すみれの言葉が、いつも詩的で抽象的な理由は、そこにある。正確に伝えようとして、言語の限界にぶつかっている。嘘をつけない構造のまま、伝えきれない真実を、断片で差し出している。"}, {"id": "ch10-s03-p087", "type": "text", "text": "「すみれ」"}, {"id": "ch10-s03-p088", "type": "text", "text": "呼んだ。"}, {"id": "ch10-s03-p089", "type": "text", "text": "すみれの瞳が俺を見ていた。薄紫色。星の光が散っている。瞳の奥の、さっき増えた光の層がまだ残っていた。消えていない。"}, {"id": "ch10-s03-p090", "type": "text", "text": "「その島の音が、俺の中にある。それは本当なんだな」"}, {"id": "ch10-s03-p091", "type": "text", "text": "確認した。"}, {"id": "ch10-s03-p092", "type": "text", "text": "「うん。ほんとだよ」"}, {"id": "ch10-s03-p093", "type": "text", "text": "嘘がない。嘘という概念がない声。事実の報告。蛇口から水が出る。空に星がある。蓮の中に島の音がある。全部同じ棚に並んでいる。"}, {"id": "ch10-s03-p094", "type": "text", "text": "鳩尾の奥が、まだ響いていた。九月のカードの時は振動がすぐに収まった。今夜のは長い。すみれの声が入ってきてから、ずっと響き続けている。低い音。聞こえないのに、体が「鳴っている」と報告してくる。"}, {"id": "ch10-s03-p095", "type": "text", "text": "痛みがあった。"}, {"id": "ch10-s03-p096", "type": "text", "text": "痛みという言い方が正しいかわからない。その響きが、体の内壁に当たっている。当たるたびに、ほんの少しだけ圧がかかる。骨を押しているわけではない。筋肉が収縮しているわけでもない。もっと深い場所で、何かが何かに触れていて、その接触が微かな負荷を生んでいる。"}, {"id": "ch10-s03-p097", "type": "text", "text": "記憶にない島。消えた島。三百人が暮らしていた場所。果樹園と月夜唄。残存者なし。"}, {"id": "ch10-s03-p098", "type": "text", "text": "——残存者なし。"}, {"id": "ch10-s03-p099", "type": "text", "text": "その一行が、体の奥の響きと重なった。"}, {"id": "ch10-s03-p100", "type": "text", "text": "すみれの右手が動いた。"}, {"id": "ch10-s03-p101", "type": "text", "text": "床の上に置いてあった俺の左手に、すみれの指が触れた。"}, {"id": "ch10-s03-p102", "type": "text", "text": "冷たかった。七月と同じ。十月になっても変わらない。冷たさがすみれの定常だった。温まろうとしない冷たさ。五本の細い指が、俺の手の甲に載った。"}, {"id": "ch10-s03-p103", "type": "text", "text": "「れん、いたい？」"}, {"id": "ch10-s03-p104", "type": "text", "text": "声が小さかった。壁に届かない音量。"}, {"id": "ch10-s03-p105", "type": "text", "text": "「……なんでわかる」"}, {"id": "ch10-s03-p106", "type": "text", "text": "「おとがかわったから。れんのなかの、しまのおと。いまちょっと、くるしそうになった」"}, {"id": "ch10-s03-p107", "type": "text", "text": "俺の中の音が苦しそうになった。それをすみれは鐘の音を通して聞いている。"}, {"id": "ch10-s03-p108", "type": "text", "text": "すみれの指が俺の手の甲の上で動いた。人差し指の先端が皮膚を小さくなぞった。七月にも同じことがあった。温度を確かめる動作。"}, {"id": "ch10-s03-p109", "type": "text", "text": "「あのね、れん」"}, {"id": "ch10-s03-p110", "type": "text", "text": "「うん」"}, {"id": "ch10-s03-p111", "type": "text", "text": "「しまのおとは、かなしいおとじゃないよ」"}, {"id": "ch10-s03-p112", "type": "text", "text": "間があった。"}, {"id": "ch10-s03-p113", "type": "text", "text": "「なくなったしまの、さいごのおとじゃない。しまにいたひとたちが、まいにちうたってたおとだよ。まいにちのおと。あさのおと。よるのおと。それが、れんのなかに、のこっている」"}, {"id": "ch10-s03-p114", "type": "text", "text": "毎日の音。朝の音。夜の音。"}, {"id": "ch10-s03-p115", "type": "text", "text": "鳩尾の奥の響きの質が、すみれの言葉で変わった。痛みではなかった。痛みに似ていたが、痛みではなかった。もっと前からあるもの。鐘の音を「懐かしい」と感じた最初の日から、ずっとあったもの。気づかなかっただけで、四月からずっと鳩尾の奥にあった振動。"}, {"id": "ch10-s03-p116", "type": "text", "text": "すみれの手が冷たかった。俺の手の甲から温度が移っていく。すみれの冷たさは中間に来ない。俺の温度を受け取っても、すみれの指はまだ冷たい。七月に確認した事実は変わっていなかった。"}, {"id": "ch10-s03-p117", "type": "text", "text": "「すみれ」"}, {"id": "ch10-s03-p118", "type": "text", "text": "「うん」"}, {"id": "ch10-s03-p119", "type": "text", "text": "「お前が聞こえている島の音は、鐘の音の中に混じっているのか。それとも、俺の中から直接聞こえているのか」"}, {"id": "ch10-s03-p120", "type": "text", "text": "すみれが首を傾げた。質問の意味を測っている。"}, {"id": "ch10-s03-p121", "type": "text", "text": "「……りょうほう」"}, {"id": "ch10-s03-p122", "type": "text", "text": "小さな声だった。"}, {"id": "ch10-s03-p123", "type": "text", "text": "「かねのおとのなかにも、ある。れんのなかにも、ある。おなじおと。おなじばしょから、きたおと」"}, {"id": "ch10-s03-p124", "type": "text", "text": "同じ場所から来た音。鐘の音と、俺の中の音が、同じ場所から来ている。"}, {"id": "ch10-s03-p125", "type": "text", "text": "鐘の音の懐かしさ。歯車を手が知っていること。月夜唄で体の芯が振動したこと。全部が同じ場所に集まっている。その場所を、すみれは「とおいしま」と呼んでいる。"}, {"id": "ch10-s03-p126", "type": "text", "text": "すみれの指が俺の手の甲から離れた。離す直前、七月と同じように指の力が一瞬だけ強くなった。押すというほどではない。確認の力。それだけ。"}, {"id": "ch10-s03-p127", "type": "text", "text": "左手の甲に冷たさの跡が残った。夜の空気がその跡を撫でている。"}, {"id": "ch10-s03-p128", "type": "text", "text": "すみれが天蓋を見上げた。"}, {"id": "ch10-s03-p129", "type": "text", "text": "「ほし、きれい」"}, {"id": "ch10-s03-p130", "type": "text", "text": "声が戻っていた。「ほし、きれい」の温度。さっきまでの密度がない。棚から一つを出して見せたら、次の棚に移る。すみれの中では島の音と星の美しさは同じ場所に並んでいる。"}, {"id": "ch10-s03-p131", "type": "text", "text": "「ああ。きれいだ」"}, {"id": "ch10-s03-p132", "type": "text", "text": "答えた。"}, {"id": "ch10-s03-p133", "type": "text", "text": "天蓋のガラス越しに星を見ながら、鳩尾の奥を探った。響きはまだ残っていた。すみれの声で入ってきたものが、沈殿していく。沈殿して、底に溜まっていく。消えない。"}, {"id": "ch10-s03-p134", "type": "text", "text": "すみれが知っていること。鐘が知っていること。俺の中にある島の音。三つが重なっている。重なっているが、重なり方の全体は見えない。すみれの言葉は断片だった。断片の奥に全体がある。全体は鐘の音の中にある。すみれにはそれが聞こえている。俺には聞こえない。"}, {"id": "ch10-s03-p135", "type": "text", "text": "けれど——体は知っている。"}, {"id": "ch10-s03-p136", "type": "text", "text": "歯車に手が伸びるのと同じだ。ルミエラ島の発音に迷いがなかったのと同じだ。「歌か」が口から先に出たのと同じだ。頭は知らないが体の中にある。"}, {"id": "ch10-s03-p137", "type": "text", "text": "すみれの「とおいしまの音」は、俺の体が知っているものの名前だった。"}, {"id": "ch10-s03-p138", "type": "text", "text": "立ち上がった。"}, {"id": "ch10-s03-p139", "type": "text", "text": "「帰る。また来る」"}, {"id": "ch10-s03-p140", "type": "text", "text": "「うん」"}, {"id": "ch10-s03-p141", "type": "text", "text": "すみれの声が返ってきた。振り返らなかった。天蓋を見上げて、星の数を再開している。"}, {"id": "ch10-s03-p142", "type": "text", "text": "螺旋階段を降り始めた。石段の冷たさが靴底に戻る。木の床から石の階段に切り替わる感触。天蓋の間を出るたびに、すみれの時間から鐘鋳塔の時間へ、そして島の時間へ、異なる層を通過していく。"}, {"id": "ch10-s03-p143", "type": "text", "text": "十階の大鐘の脇を通った。"}, {"id": "ch10-s03-p144", "type": "text", "text": "鐘の表面に手を伸ばしかけて、止めた。"}, {"id": "ch10-s03-p145", "type": "text", "text": "初日と同じ。触れない。触れていいのかわからない。"}, {"id": "ch10-s03-p146", "type": "text", "text": "けれど今夜は、伸ばしかけた手を止めた位置が、いつもより鐘に近かった。指先と鐘の表面の距離が、拳一つ分もなかった。"}, {"id": "ch10-s03-p147", "type": "text", "text": "鐘の音の中に、島の音がある。すみれがそう言った。"}, {"id": "ch10-s03-p148", "type": "text", "text": "指先に、何かの振動を感じた気がした。鐘には触れていない。触れていないのに、指先の皮膚が微かに震えている。気のせいかもしれない。鐘の残響が空気を伝って指先に届いたのか。体が「知っている」と報告しているだけか。"}, {"id": "ch10-s03-p149", "type": "text", "text": "手を引いた。"}, {"id": "ch10-s03-p150", "type": "text", "text": "管理室に降りた。消灯。施錠。正面入口を出た。"}, {"id": "ch10-s03-p151", "type": "text", "text": "十月の夜風が顔に当たった。冷たかった。天蓋の間のすみれの手と同じ温度域。外の空気が冷えて、すみれの冷たさに近づいている。七月にはすみれの冷たさが際立っていた。十月になって、世界の方がすみれに近づいた。"}, {"id": "ch10-s03-p152", "type": "text", "text": "左手の甲を見た。冷たさの跡はもう消えていた。体温が戻っている。七月と同じ。すみれの指の跡は体温に上書きされる。"}, {"id": "ch10-s03-p153", "type": "text", "text": "惜しいと思った。二度目だ。七月にも同じことを思った。惜しいという感覚が、左手の甲にある。すみれの場所。"}, {"id": "ch10-s03-p154", "type": "text", "text": "灯籠通りを歩いた。灯籠の明かりが石畳に橙色の円を落としている。足音が自分の一人分だけ。"}, {"id": "ch10-s03-p155", "type": "text", "text": "その響きは、歩いても消えなかった。すみれの声で始まったものが、まだ底で振動している。島の音。遠い島の音。俺の中にある、記憶にない場所からの音。"}, {"id": "ch10-s03-p156", "type": "text", "text": "すみれは答えなかった。何を知っているのか、とは聞いた。返ってきたのは「かねのおとは、すべてをしっている」だった。答えになっていない答え。しかし嘘ではなかった。すみれは嘘をつけない。嘘をつけない構造のまま、伝えきれない真実を差し出した。"}, {"id": "ch10-s03-p157", "type": "text", "text": "その断片の奥に、全体がある。"}, {"id": "ch10-s03-p158", "type": "text", "text": "全体が何なのかは、まだわからない。わからないが——方向は見えている。鳩尾の奥で北を向いている「知りたい」と、鐘の音の「懐かしさ」と、ルミエラ島の月夜唄と、すみれの「とおいしまの音」が、全部同じ場所を指している。"}, {"id": "ch10-s03-p159", "type": "text", "text": "補佐官舎の鍵を開けた。靴を脱いだ。暗いまま寝台に座った。"}, {"id": "ch10-s03-p160", "type": "text", "text": "左手の甲に右手を重ねた。すみれの冷たさは消えている。七月と同じ。消えていることが、少しだけ惜しい。"}, {"id": "ch10-s03-p161", "type": "text", "text": "覚えておく。"}, {"id": "ch10-s03-p162", "type": "text", "text": "すみれの声と、「とおいしまの音」と、体の奥で応答したものと、大鐘の前で指先が震えたことを。"}]}, {"chapter": 10, "chapterTitle": "霜月の技師", "scene": 4, "sceneTitle": "観測データの異常", "wordCount": "約5,100字", "paragraphs": [{"id": "ch10-s04-p001", "type": "text", "text": "端末が鳴った。"}, {"id": "ch10-s04-p002", "type": "text", "text": "十五時の鐘が鳴り終わった直後。管理室で第七系統の定期記録を手帳に転記していた。午後の管理室は陽が入らない。北向きの窓から入るのは、十月の白い空気だけだった。"}, {"id": "ch10-s04-p003", "type": "text", "text": "メッセージ。一行。"}, {"id": "ch10-s04-p004", "type": "text", "text": "「3階。データ説明。1510」"}, {"id": "ch10-s04-p005", "type": "text", "text": "霜月さんだった。送信者を確認するまでもなく、わかる。主語がない。敬語がない。時刻が四桁。S1で深夜に受けたメッセージと同じ構造。この人の文は、この人以外に書けない。"}, {"id": "ch10-s04-p006", "type": "text", "text": "手帳を閉じた。ペンを棚に戻した。管理室の施錠は不要。業務時間内。"}, {"id": "ch10-s04-p007", "type": "text", "text": "階段を上がった。一階から三階まで。石段の冷たさが靴底を通して報告してくる。十月の鐘鋳塔の石段は、九月よりもう一段冷えている。"}, {"id": "ch10-s04-p008", "type": "text", "text": "三階の通路。研究区画。残響灯が壁面で不規則に光っている。昼間の残響灯は深夜モードと違い、輝度が安定している。白に近い青白さ。廊下の空気は管理室より乾いていた。精密計器のために湿度管理されている。"}, {"id": "ch10-s04-p009", "type": "text", "text": "霜月さんの研究室の鉄扉が開いていた。"}, {"id": "ch10-s04-p010", "type": "text", "text": "入った。"}, {"id": "ch10-s04-p011", "type": "text", "text": "オシロスコープの画面が緑色の波形を描いている。S1の深夜と同じ画面。しかし今日は波形ではなく、別のモニタが正面に据えてあった。横長の画面。黒地に白い線が何本か走っている。折れ線グラフ。縦軸に数値、横軸に月の名前。"}, {"id": "ch10-s04-p012", "type": "text", "text": "霜月さんが机の前に座っていた。白いロングコート。銀髪のハーフアップ。背筋が真っ直ぐ伸びた座り方。椅子の背もたれに背中がつかない。この人はどこに座ってもこの姿勢だった。"}, {"id": "ch10-s04-p013", "type": "text", "text": "「来たか」"}, {"id": "ch10-s04-p014", "type": "text", "text": "声に抑揚がなかった。確認。それ以上でもそれ以下でもない声。"}, {"id": "ch10-s04-p015", "type": "text", "text": "「1510の二分前です」"}, {"id": "ch10-s04-p016", "type": "text", "text": "「わかっている」"}, {"id": "ch10-s04-p017", "type": "text", "text": "霜月さんの視線がモニタに戻った。俺も視線を追った。"}, {"id": "ch10-s04-p018", "type": "text", "text": "モニタの折れ線グラフ。線は三本あった。赤、青、緑。凡例が画面の右端に出ている。赤が「南端蝕域活動指数」、青が「東端蝕域活動指数」、緑が「北端蝕域活動指数」。横軸は七月、八月、九月、十月——今月の途中まで。"}, {"id": "ch10-s04-p019", "type": "text", "text": "赤い線だけが上がっていた。"}, {"id": "ch10-s04-p020", "type": "text", "text": "青と緑は横ばいか微減。振幅の幅も安定している。赤い線は七月の基点から右肩上がりに推移し、十月の現時点で明らかに高い位置にある。"}, {"id": "ch10-s04-p021", "type": "text", "text": "「説明する」"}, {"id": "ch10-s04-p022", "type": "text", "text": "霜月さんの声が切り替わった。業務の声。報告書を読み上げる時の、平たく均された声。"}, {"id": "ch10-s04-p023", "type": "text", "text": "「蝕域活動の定点観測データ。南端、東端、北端の三測定点を比較したグラフだ。取得期間は本年七月から現在まで。データソースは縁際の監視哨から送られる日次観測値の月間平均」"}, {"id": "ch10-s04-p024", "type": "text", "text": "指が赤い線を示した。爪が短い。いつも短い。工具を扱う指。"}, {"id": "ch10-s04-p025", "type": "text", "text": "「見ての通り、南端の活動指数だけが上昇傾向にある。具体的には、七月の基準値から17パーセント増加」"}, {"id": "ch10-s04-p026", "type": "text", "text": "17パーセント。"}, {"id": "ch10-s04-p027", "type": "text", "text": "蝕域の観測値は俺も管理室で扱う。日次報告に含まれる縁際の数値は毎朝確認している。通常の変動幅は±3パーセント。七ヶ月で覚えた数字。3パーセントは誤差。季節変動や鐘の出力のわずかなばらつきで十分に説明がつく範囲。"}, {"id": "ch10-s04-p028", "type": "text", "text": "17パーセントは、その五倍以上だった。"}, {"id": "ch10-s04-p029", "type": "text", "text": "「……±3パーセントの通常変動とは桁が違います」"}, {"id": "ch10-s04-p030", "type": "text", "text": "「そうだ」"}, {"id": "ch10-s04-p031", "type": "text", "text": "霜月さんの返答が短かった。「そうだ」の二音節。声の温度は変わらない。データを確認した人間の声。しかし「そうだ」の後に続く言葉が、一拍遅れた。"}, {"id": "ch10-s04-p032", "type": "text", "text": "「この測定点は、外円区の南端——灯里村跡地方面に対応する」"}, {"id": "ch10-s04-p033", "type": "text", "text": "灯里村。"}, {"id": "ch10-s04-p034", "type": "text", "text": "名前を聞いた瞬間、鳩尾の奥が微かに動いた。北の方角。ルミエラ島の方角ではない。南の方角。灯里村は南端だ。けれど鳩尾が動いたのは方角の問題ではなかった。"}, {"id": "ch10-s04-p035", "type": "text", "text": "燈花の故郷。"}, {"id": "ch10-s04-p036", "type": "text", "text": "五月に雫のファイルに「灯里村」の名前を見つけた時のことを覚えている。燈花が食堂で「忘れちゃいそうで怖い」と言った声を覚えている。ヘアゴムに触れる指を覚えている。"}, {"id": "ch10-s04-p037", "type": "text", "text": "灯里村跡地方面の蝕域が17パーセント増加している。"}, {"id": "ch10-s04-p038", "type": "text", "text": "「増加の推移を見なさい」"}, {"id": "ch10-s04-p039", "type": "text", "text": "霜月さんの指がモニタの上を滑った。赤い線の各月の数値を示す。"}, {"id": "ch10-s04-p040", "type": "text", "text": "「七月：基準値。八月：4パーセント増。九月：9パーセント増。十月現在：17パーセント増。増加率そのものが加速している。線形ではない」"}, {"id": "ch10-s04-p041", "type": "text", "text": "線形ではない。加速している。月を追うごとに増分が大きくなっている。四、五、八。次の月は八を超えるかもしれない。"}, {"id": "ch10-s04-p042", "type": "text", "text": "「この加速度を維持した場合の予測は」"}, {"id": "ch10-s04-p043", "type": "text", "text": "聞いた。声が平らだった。自分でも意外なほど、平らだった。管理室で数値を読む時と同じ声。"}, {"id": "ch10-s04-p044", "type": "text", "text": "「来月には基準値比30パーセント超の可能性がある。40パーセント超は——」"}, {"id": "ch10-s04-p045", "type": "text", "text": "霜月さんの声が止まった。"}, {"id": "ch10-s04-p046", "type": "text", "text": "止まったのは0.5秒。しかしこの人の声が途中で止まるのは、俺の知る限り初めてだった。S1の深夜でも、声は止まらなかった。0.05パーセントの変動を報告する時も、「経過観察とする」を結論まで一息で出した。"}, {"id": "ch10-s04-p047", "type": "text", "text": "その霜月さんの声が止まった。"}, {"id": "ch10-s04-p048", "type": "text", "text": "再開した時、声の位置が変わっていた。位置、という言い方が正しいかわからない。声の出る場所——喉の浅い場所から深い場所に移った。低くなったのではない。音量も高さも同じ。けれど声が体の奥から出ている。"}, {"id": "ch10-s04-p049", "type": "text", "text": "「——40パーセントを超えれば、縁蝕波の発生条件に達する」"}, {"id": "ch10-s04-p050", "type": "text", "text": "縁蝕波。"}, {"id": "ch10-s04-p051", "type": "text", "text": "管理室のマニュアルに記載されている。蝕域の急激な侵食。数時間から数日で数百メートルから数キロメートルの領域が消滅する現象。鐘の音だけでは対処できない。共鳴者の支援が必要。"}, {"id": "ch10-s04-p052", "type": "text", "text": "霜月さんがモニタから視線を外した。机の上の記録用紙を見た。ペンが置いてある。ペンの向きは記録用紙と平行。この人の机の上はいつも整然としている。ペンの角度まで管理されている。"}, {"id": "ch10-s04-p053", "type": "text", "text": "しかし今日は、ペンの蓋が外れていた。蓋は机の右端に転がっている。霜月さんの机でペンの蓋が本体と離れた場所にあるのを見たのは初めてだった。"}, {"id": "ch10-s04-p054", "type": "text", "text": "「……また始まる」"}, {"id": "ch10-s04-p055", "type": "text", "text": "声が小さかった。"}, {"id": "ch10-s04-p056", "type": "text", "text": "俺に向けた声ではなかった。モニタに向けた声でもなかった。声の方向が定まっていない。口から零れたもの。言おうとして出した言葉ではなく、中に在ったものが外に出た。"}, {"id": "ch10-s04-p057", "type": "text", "text": "ペンの蓋が外れていたのと同じだ。管理されているはずの場所から、一つだけ外れて転がった。"}, {"id": "ch10-s04-p058", "type": "text", "text": "「また？」"}, {"id": "ch10-s04-p059", "type": "text", "text": "聞き返した。声が低くなっていた。自分でも気づいた。S3の夜にすみれに「島の音？」と聞き返した時と同じ——喉の深い場所から出た声。"}, {"id": "ch10-s04-p060", "type": "text", "text": "霜月さんの肩が動いた。"}, {"id": "ch10-s04-p061", "type": "text", "text": "見えたのは白いコートの肩の線が一瞬だけ上がって、下がったことだった。呼吸を止めて、吐いた。背もたれに背中はつかないまま。姿勢は変わらない。変わらないのに、肩の線だけが一瞬動いた。"}, {"id": "ch10-s04-p062", "type": "text", "text": "ラベンダーの瞳が俺を見た。正面から。この人は人と話す時に真っ直ぐ目を見る。威圧的に映る。しかし今、瞳の奥にあるものが、いつもと違った。"}, {"id": "ch10-s04-p063", "type": "text", "text": "いつもの霜月さんの瞳は硬い。鉱石の断面。光を反射するが、奥が見えない。四月の初対面からずっとそうだった。"}, {"id": "ch10-s04-p064", "type": "text", "text": "今の瞳は、硬さの一枚下に別の層があった。その層が一瞬だけ浮いて、沈んだ。"}, {"id": "ch10-s04-p065", "type": "text", "text": "「……何でもない。データの報告だ」"}, {"id": "ch10-s04-p066", "type": "text", "text": "声が業務口調に戻った。切り替えが速かった。「悪くない」の一音が漏れた夜と同じ速度で蓋を閉じた。S1でピアスへの言及に「仕事に関係ない」と返した時と同じ構造。外に出たものを、中に戻す。"}, {"id": "ch10-s04-p067", "type": "text", "text": "けれど——S1の時は気づかなかった。今日は気づいた。"}, {"id": "ch10-s04-p068", "type": "text", "text": "「また」は、初めて聞く言葉ではなかった。"}, {"id": "ch10-s04-p069", "type": "text", "text": "言葉としては初めてだ。霜月さんの口から「また」が出たのは今が初めて。けれど「また」の奥にあるもの——何かが繰り返されているという認識、以前にも同じことがあったという重さ——は、この人の背中にずっと乗っていた。"}, {"id": "ch10-s04-p070", "type": "text", "text": "S1の深夜。0.05パーセントの変動に、深夜でも着替えずに対応する精度。目の下の影。ペンの蓋が外れない机。あの完璧さは、「二度と見逃さない」人間の完璧さだった。"}, {"id": "ch10-s04-p071", "type": "text", "text": "一度見逃した人間の。"}, {"id": "ch10-s04-p072", "type": "text", "text": "いや——見逃していないかもしれない。データで気づいていたのに、それを無視されたのかもしれない。どちらなのかは、わからない。わからないが、「また」の重さは伝わった。"}, {"id": "ch10-s04-p073", "type": "text", "text": "背中の奥で、何かが動いた。"}, {"id": "ch10-s04-p074", "type": "text", "text": "氷華＝背中の奥。S1のコーヒーの温かさと青い石と一秒半の左手が刻まれた場所。その場所が、「また」の一言で揺れている。"}, {"id": "ch10-s04-p075", "type": "text", "text": "霜月さんは俺を見ていた。真っ直ぐに。業務口調に戻った声で、しかし目はまだこちらを見ていた。「何でもない」と言ったのに視線を外さない。視線を外さないことが、言葉と矛盾していた。"}, {"id": "ch10-s04-p076", "type": "text", "text": "俺はその矛盾を見ていた。"}, {"id": "ch10-s04-p077", "type": "text", "text": "追及しなかった。"}, {"id": "ch10-s04-p078", "type": "text", "text": "燈花の翳りにも追及しなかった。雫の筆跡の震えにも。千歳の疲労にも。いろはの壁にも。晶さんの寂しさにも。霜月さんのピアスにも。観察する。記録する。保留する。いつものパターン。"}, {"id": "ch10-s04-p079", "type": "text", "text": "しかし今日は、保留の中身が違った。"}, {"id": "ch10-s04-p080", "type": "text", "text": "「データはこの後も経過を追いますか」"}, {"id": "ch10-s04-p081", "type": "text", "text": "業務の声で聞いた。平らな声。"}, {"id": "ch10-s04-p082", "type": "text", "text": "「ああ。日次で確認する。朝霧、管理室の定時報告にこの数値を追加しなさい。南端の活動指数を。これまでの月間平均だけでなく、週間での推移も取る」"}, {"id": "ch10-s04-p083", "type": "text", "text": "「わかりました」"}, {"id": "ch10-s04-p084", "type": "text", "text": "「それから——」"}, {"id": "ch10-s04-p085", "type": "text", "text": "霜月さんの手が机の上を滑り、記録用紙の束を引き寄せた。A4の用紙が五枚ほど。手書きの数表とグラフが描かれている。ペンの線が均一だった。この人の手書きのグラフは、印刷と区別がつかない。"}, {"id": "ch10-s04-p086", "type": "text", "text": "「過去のデータも遡る。過去五年分の南端活動指数の推移を、記録室から取り寄せなさい。管理局のアーカイブに月次データがあるはずだ」"}, {"id": "ch10-s04-p087", "type": "text", "text": "過去五年分。"}, {"id": "ch10-s04-p088", "type": "text", "text": "五年。"}, {"id": "ch10-s04-p089", "type": "text", "text": "数字を受け取った時、背中の奥がまた動いた。五年。「また」の時間軸が見えた。五年前に何かがあった。霜月さんがそのデータを必要としている理由の輪郭が、うっすらと——"}, {"id": "ch10-s04-p090", "type": "text", "text": "「……了解しました。明日中に手配します」"}, {"id": "ch10-s04-p091", "type": "text", "text": "「今日中にしなさい」"}, {"id": "ch10-s04-p092", "type": "text", "text": "声が速かった。いつもの業務指示より速い。「明日中」を「今日中」に上書きした速さ。S1でピアスを手で覆った速度に似ていた。体が先に動く速度。"}, {"id": "ch10-s04-p093", "type": "text", "text": "「データは鮮度が全てだ」"}, {"id": "ch10-s04-p094", "type": "text", "text": "付け足した声は平らだった。業務的な理由づけ。しかし「今日中」の速さと「データは鮮度が全てだ」の平らさの間に、隙間があった。速さが先に出て、理由が後を追いかけている。"}, {"id": "ch10-s04-p095", "type": "text", "text": "「わかりました。今日中に」"}, {"id": "ch10-s04-p096", "type": "text", "text": "霜月さんが頷いた。小さく。顎の角度が二度ほど下がって、戻った。"}, {"id": "ch10-s04-p097", "type": "text", "text": "モニタの赤い線が、薄暗い研究室の中で光っていた。七月から十月まで、右肩上がりに。赤い線の先は十月の途中で途切れている。その先に何が来るのかはまだ記録されていない。"}, {"id": "ch10-s04-p098", "type": "text", "text": "記録されていない部分を、この人は「また始まる」と呼んだ。"}, {"id": "ch10-s04-p099", "type": "text", "text": "「以上だ」"}, {"id": "ch10-s04-p100", "type": "text", "text": "霜月さんが言った。"}, {"id": "ch10-s04-p101", "type": "text", "text": "立ち上がらなかった。椅子に座ったまま、モニタに視線を戻した。背筋は真っ直ぐ。コートの裾が椅子の脚に沿って垂れている。姿勢は完璧だった。完璧な姿勢のまま、赤い線を見ていた。"}, {"id": "ch10-s04-p102", "type": "text", "text": "俺は研究室を出た。鉄扉を引いた。閉まる直前に、もう一度中を見た。"}, {"id": "ch10-s04-p103", "type": "text", "text": "白いコートの背中が見えた。モニタの光を受けて、コートの肩の部分が薄い緑色に染まっている。銀髪が残響灯の光を受けている。左耳のピアスの青い石が、一瞬だけ光った。"}, {"id": "ch10-s04-p104", "type": "text", "text": "霜月さんは振り返らなかった。"}, {"id": "ch10-s04-p105", "type": "text", "text": "鉄扉が閉まった。"}, {"id": "ch10-s04-p106", "type": "text", "text": "三階の通路を歩いた。階段を降りた。一階の管理室に戻った。手帳を開いた。記録用紙の上に追加の業務を書き込んだ。「南端蝕域活動指数、週次推移の取得開始」「過去五年分の南端データ、記録室から手配（本日中）」"}, {"id": "ch10-s04-p107", "type": "text", "text": "ペンの先が紙の上で止まった。"}, {"id": "ch10-s04-p108", "type": "text", "text": "もう一行、書き加えた。業務記録ではなく、手帳の余白に。小さい字で。"}, {"id": "ch10-s04-p109", "type": "text", "text": "「霜月さんの声が止まった（0.5秒）。ペンの蓋が外れていた。過去五年分を指定。『今日中にしなさい』の速度」"}, {"id": "ch10-s04-p110", "type": "text", "text": "記録した。業務ではない記録。観察の記録。俺がいつもやっていること。人の奥に触れそうなものを書き留めて、保留する。"}, {"id": "ch10-s04-p111", "type": "text", "text": "灯里村跡地方面。17パーセント増加。加速している。"}, {"id": "ch10-s04-p112", "type": "text", "text": "燈花の故郷の方角で、蝕域が活性化している。"}, {"id": "ch10-s04-p113", "type": "text", "text": "燈花は知っているのだろうか。外円区の蝕域データは一般には公開されない。管理室と研究区画と監視哨にしか回らない。燈花がこの数字を目にすることはないだろう。けれど——あの人は外円区の空気を肌で知っている。数字に出る前に、土の匂いや風の質で感じ取るものがあるかもしれない。"}, {"id": "ch10-s04-p114", "type": "text", "text": "手帳を閉じた。"}, {"id": "ch10-s04-p115", "type": "text", "text": "記録室への手配を始めた。端末でアーカイブのリクエストフォームを開く。「対象：南端蝕域活動指数、月次平均値」「期間：過去60ヶ月（5年分）」「請求者：鐘鋳塔管理局 鐘守補佐 朝霧蓮」「承認者：鐘鋳塔管理局 技師長 霜月氷華」"}, {"id": "ch10-s04-p116", "type": "text", "text": "送信した。"}, {"id": "ch10-s04-p117", "type": "text", "text": "管理室の窓の外に、十月の午後の光が白く広がっていた。北向きの窓から見える空は高い。空は平気な顔をしている。"}, {"id": "ch10-s04-p118", "type": "text", "text": "背中の奥に、「また」が残っていた。"}, {"id": "ch10-s04-p119", "type": "text", "text": "霜月さんの声が零れた一瞬。ペンの蓋が机の端に転がっていたこと。「今日中にしなさい」の速さ。五年分のデータ。赤い線の右肩上がり。"}, {"id": "ch10-s04-p120", "type": "text", "text": "この人は、何を知っているのだろう。"}, {"id": "ch10-s04-p121", "type": "text", "text": "「また」という言葉が、あの人の中でどれだけの重さを持っているのだろう。"}, {"id": "ch10-s04-p122", "type": "text", "text": "聞かない。今は聞かない。聞くべき時が来るのか、来ないのかもわからない。ただ、背中の奥にある「何か」の形が、また少し変わった。S1のコーヒーの温かさと青い石とは別の角度から、もう一面が見えた。"}, {"id": "ch10-s04-p123", "type": "text", "text": "この人は怖い。機械のように正確で、感情の色がない。冷たい人だと四月には思った。不器用な人だと六月に思い直した。何かを抱えている人だとS1で確信した。"}, {"id": "ch10-s04-p124", "type": "text", "text": "今日、「何か」に方角が増えた。ピアスの方角と、赤い線の方角。二つ。"}, {"id": "ch10-s04-p125", "type": "text", "text": "霜月さんの「また」。止まった0.5秒。ペンの蓋の位置。"}, {"id": "ch10-s04-p126", "type": "text", "text": "赤い線は、まだ上がっている。"}]}, {"chapter": 10, "chapterTitle": "霜月の技師", "scene": 5, "sceneTitle": "月と鐘", "wordCount": "約5,100字", "paragraphs": [{"id": "ch10-s05-p001", "type": "text", "text": "二十一時の鐘が鳴り終わった。"}, {"id": "ch10-s05-p002", "type": "text", "text": "管理室の計器。第七系統の微振動値、通常範囲内。南端蝕域活動指数の週次データ、霜月さんの指示で追加した項目を手帳に書き入れた。ペンを棚に戻した。消灯スイッチの前で、手が止まった。"}, {"id": "ch10-s05-p003", "type": "text", "text": "上へ行く。"}, {"id": "ch10-s05-p004", "type": "text", "text": "いつもなら十一階まで。石段を上り、木の床に切り替わり、天蓋の間に入る。十階の大鐘の脇を通過して。四月からずっとそうだった。通過して。"}, {"id": "ch10-s05-p005", "type": "text", "text": "今夜は、通過しない。"}, {"id": "ch10-s05-p006", "type": "text", "text": "螺旋階段を上る。残響灯の青白い光が紫に傾いていく。壁面の残響紋の曲線。何度も見た変化。靴底が石段の冷たさを報告してくる。十月の終わり。石段の温度がまた一段下がっている。"}, {"id": "ch10-s05-p007", "type": "text", "text": "九階を通過した。十階の踊り場に出た。"}, {"id": "ch10-s05-p008", "type": "text", "text": "大鐘。"}, {"id": "ch10-s05-p009", "type": "text", "text": "直径約五メートル。残響金属の青みがかった表面に、残響紋が全面に刻まれている。残響灯の紫の光が鐘の曲面に当たり、紋様の溝が細い影として浮かんでいた。鐘の下部に打鐘機構が組み込まれている。鎮まっている。鐘は今、鳴っていない。"}, {"id": "ch10-s05-p010", "type": "text", "text": "四月の初日、ここを通った。手を伸ばしかけて、止めた。触れていいものかわからなかったから。"}, {"id": "ch10-s05-p011", "type": "text", "text": "S3の夜、すみれの声を聞いた後でここを通った。手を伸ばしかけて、止めた。距離は拳一つ分もなかった。触れていないのに指先が震えた。"}, {"id": "ch10-s05-p012", "type": "text", "text": "今夜は。"}, {"id": "ch10-s05-p013", "type": "text", "text": "鐘の前に立った。鐘の表面が目の前にある。紋様の溝の深さがわかる距離。残響灯の紫の光が溝の底に溜まっている。溝は均一ではなかった。深いところと浅いところがある。深い溝は線が太く、浅い溝は線が細い。二種類の線が絡み合って、水の流れのような紋様を描いている。"}, {"id": "ch10-s05-p014", "type": "text", "text": "手を上げた。"}, {"id": "ch10-s05-p015", "type": "text", "text": "右手。掌を鐘に向ける。指先と鐘の表面の距離が縮まっていく。"}, {"id": "ch10-s05-p016", "type": "text", "text": "触れた。"}, {"id": "ch10-s05-p017", "type": "text", "text": "冷たかった。残響金属の表面温度。十月の夜気より少し低い。石段と同じ冷たさの系統だが、質が違う。石は熱を吸う。この金属は熱を逃がす。掌から熱が金属の表面に移り、表面がそれを拒まずに受け取り、空気に渡している。体温が鐘を通過して消えていく。"}, {"id": "ch10-s05-p018", "type": "text", "text": "掌の下に、振動があった。"}, {"id": "ch10-s05-p019", "type": "text", "text": "微かだった。鐘は鳴っていない。打鐘機構は動いていない。にもかかわらず、掌の皮膚が振動を報告してきた。微細で、等間隔で、低い。計器で拾えるかどうかの境界にあるもの。鐘が鳴った後の残響ではない。鐘の内側にある振動。鐘自体が持っている振動。呼吸のように。"}, {"id": "ch10-s05-p020", "type": "text", "text": "鳩尾の奥が、動いた。"}, {"id": "ch10-s05-p021", "type": "text", "text": "掌の振動と同じ間隔。同じ低さ。掌が受けているものと、体の奥にあるものが、同じリズムで動いている。"}, {"id": "ch10-s05-p022", "type": "text", "text": "同じ音。"}, {"id": "ch10-s05-p023", "type": "text", "text": "すみれが言った。「おなじばしょから、きたおと」。鐘の音と、俺の中の音。"}, {"id": "ch10-s05-p024", "type": "text", "text": "掌を鐘に押し当てた。指を広げた。五本の指の腹が残響紋の溝の上に載った。溝の深い部分と浅い部分を指が跨いでいる。振動が掌全体に広がった。"}, {"id": "ch10-s05-p025", "type": "text", "text": "来た。"}, {"id": "ch10-s05-p026", "type": "text", "text": "——月の光。"}, {"id": "ch10-s05-p027", "type": "text", "text": "白い。地面に落ちている。地面は土だった。草が生えている。草の間に、月の光が散っている。"}, {"id": "ch10-s05-p028", "type": "text", "text": "——歌声。"}, {"id": "ch10-s05-p029", "type": "text", "text": "遠い。高い。女の声ではない。低い声と高い声が重なっている。複数の人間が歌っている。輪唱。一つの旋律が追いかけ合うように重なっている。言葉はわからない。歌詞が聞き取れるほど近くない。けれど旋律は聞こえる。旋律の中に、懐かしさがあった。"}, {"id": "ch10-s05-p030", "type": "text", "text": "——果樹園の匂い。"}, {"id": "ch10-s05-p031", "type": "text", "text": "甘い。熟した果実の匂い。枝に実がなっている。暗い中に丸い影が並んでいる。木の列。整列ではなく、少しずつずれた間隔で並んでいる。風がない。匂いが溜まっている。甘さの中に、土の匂いと、夜の草の匂いが混じっている。"}, {"id": "ch10-s05-p032", "type": "text", "text": "一秒にも満たなかった。"}, {"id": "ch10-s05-p033", "type": "text", "text": "掌を鐘から離した。"}, {"id": "ch10-s05-p034", "type": "text", "text": "呼吸が止まっていた。肺の中の空気が動いていなかった。口を開けて息を吸った。冷たい空気が喉を通った。"}, {"id": "ch10-s05-p035", "type": "text", "text": "手が震えていた。右手。掌を下に向けた。指先が小さく振動している。鐘の振動が残っているのではない。体が震えている。鳩尾の奥から来ている震え。"}, {"id": "ch10-s05-p036", "type": "text", "text": "見た。"}, {"id": "ch10-s05-p037", "type": "text", "text": "何を見たのか。"}, {"id": "ch10-s05-p038", "type": "text", "text": "月の光。歌声。果樹園。"}, {"id": "ch10-s05-p039", "type": "text", "text": "三つの断片。一秒にも満たない間に、三つの感覚が同時に押し寄せて、同時に消えた。砂を掴んだ。指の間から零れた。掴もうとすればするほど零れる。月がどんな形だったか。歌声が何語だったか。果樹園の木が何の木だったか。全部がぼやけていく。"}, {"id": "ch10-s05-p040", "type": "text", "text": "残っているのは、感覚だけだった。"}, {"id": "ch10-s05-p041", "type": "text", "text": "月の光の白さ。歌声の旋律の重なり方。甘い匂い。三つの感覚の輪郭だけが、体の芯に沈殿している。映像は消えた。感覚だけが残った。"}, {"id": "ch10-s05-p042", "type": "text", "text": "右手を握った。開いた。握った。掌に残響金属の冷たさがまだある。その冷たさの奥に、一瞬だけ通過した映像の熱が残っている。冷たさと熱が掌の中で重なっている。"}, {"id": "ch10-s05-p043", "type": "text", "text": "呼吸を整えた。三回。吸って、吐いて。吸って、吐いて。吸って、吐いて。"}, {"id": "ch10-s05-p044", "type": "text", "text": "その震えが収まらなかった。三回の呼吸では足りなかった。もう三回。六回目で、震えが沈殿の速度に落ちた。消えたのではない。沈んだだけ。底にある。"}, {"id": "ch10-s05-p045", "type": "text", "text": "見た。確かに見た。記憶ではない。記憶と呼べるほど明確なものではない。けれど夢でもない。掌が鐘に触れていた間だけ、何かの蓋が開いて、中のものが一瞬だけ溢れた。蓋は閉まった。中身はまだある。"}, {"id": "ch10-s05-p046", "type": "text", "text": "鐘の表面を見た。残響紋が紫の光に浮かんでいる。さっきまで俺の掌が触れていた場所。溝の中に体温の痕跡が残っているかもしれない。残響金属は熱を逃がす。もう消えているだろう。"}, {"id": "ch10-s05-p047", "type": "text", "text": "十一階に上がった。"}, {"id": "ch10-s05-p048", "type": "text", "text": "石段が木の床に変わった。靴底を通して木の繊維の弾力が戻ってくる。天蓋の間。ガラスの天蓋越しに十月の終わりの夜空。星が多い。白い点が黒の上に刺さっている。"}, {"id": "ch10-s05-p049", "type": "text", "text": "すみれがいた。"}, {"id": "ch10-s05-p050", "type": "text", "text": "部屋の中央。いつもの場所。白いワンピースの裾が木の床に広がっている。淡い紫の髪が右肩から流れていた。裸足。銀の鎖が微かに光っている。"}, {"id": "ch10-s05-p051", "type": "text", "text": "すみれが振り返った。口元が先に動いた。0.5秒遅れて目が追いかける。いつもの微笑み。"}, {"id": "ch10-s05-p052", "type": "text", "text": "けれど、微笑みの途中で止まった。"}, {"id": "ch10-s05-p053", "type": "text", "text": "目が俺を見ていた。薄紫色の瞳。星の光が白い点になって散っている。瞳の奥に、光の層が動いた。S3の夜、俺が「歌か」と言った時に増えたのと同じ光。あの光が、今、俺の顔を見て変化している。"}, {"id": "ch10-s05-p054", "type": "text", "text": "「れん」"}, {"id": "ch10-s05-p055", "type": "text", "text": "声が変わっていた。星を見ている時の軽い声ではない。密度がある声。同じ体積の中に、さっきまでの何倍もの情報が入っている声。"}, {"id": "ch10-s05-p056", "type": "text", "text": "すみれは、わかっている。"}, {"id": "ch10-s05-p057", "type": "text", "text": "鐘に触れたことが。俺の中の音が変わったことが。鐘の音を通して、全部聞こえている。"}, {"id": "ch10-s05-p058", "type": "text", "text": "「すみれ」"}, {"id": "ch10-s05-p059", "type": "text", "text": "呼んだ。声が低かった。喉の深い場所から出ている。S3ですみれに「島の音？」と聞き返した時と同じ深さ。"}, {"id": "ch10-s05-p060", "type": "text", "text": "「俺の中に島の音があるって、どういう意味だ」"}, {"id": "ch10-s05-p061", "type": "text", "text": "すみれの瞳が揺れなかった。揺れない。この少女の瞳は、嘘をつく時に揺れるのではない。嘘をつけないから。"}, {"id": "ch10-s05-p062", "type": "text", "text": "すみれが立ち上がった。立ち上がる動きが遅い。膝を伸ばし、腰を上げ、足の裏が木の床に全面接地するまでの時間が、人間より長い。すみれの時間。"}, {"id": "ch10-s05-p063", "type": "text", "text": "三歩。すみれが俺の前に来た。見上げている。148センチ。俺の胸の高さに、薄紫の瞳がある。"}, {"id": "ch10-s05-p064", "type": "text", "text": "すみれの右手が動いた。"}, {"id": "ch10-s05-p065", "type": "text", "text": "俺の右手に触れた。"}, {"id": "ch10-s05-p066", "type": "text", "text": "冷たかった。いつもの冷たさ。十月の夜気と同じ温度域。すみれの冷たさは季節に関係なく一定ではなく、外気に追いかけられるように変化する。七月はすみれだけが冷たかった。十月は世界がすみれに追いついている。"}, {"id": "ch10-s05-p067", "type": "text", "text": "すみれの指が俺の右手の掌を広げた。五本の細い指が、俺の指の間に入り込んだ。掌が上を向いた。すみれの指が掌の中央に触れた。さっき鐘に触れた場所。残響金属の冷たさが消えて、体温が戻った場所。"}, {"id": "ch10-s05-p068", "type": "text", "text": "「れん、むりしないで」"}, {"id": "ch10-s05-p069", "type": "text", "text": "声が小さかった。壁にも天蓋にも届かない音量。すみれと俺の間だけに存在する声。"}, {"id": "ch10-s05-p070", "type": "text", "text": "「おもいだすのは、いたい」"}, {"id": "ch10-s05-p071", "type": "text", "text": "すみれの瞳が俺を見ていた。星の光。白い点が薄紫の中に散っている。瞳の奥の光の層が、さっきより一枚増えていた。"}, {"id": "ch10-s05-p072", "type": "text", "text": "「いたい」はすみれにとって事実の報告だった。蛇口から水が出る。空に星がある。思い出すことは痛い。同じ棚に並んでいる。嘘のない声で、すみれは俺の痛みを報告した。"}, {"id": "ch10-s05-p073", "type": "text", "text": "同時に、心配だった。すみれの声の中に、報告以外のものがあった。S3の夜にはなかったもの。「れんのなかのしまのおと、いまちょっと、くるしそうになった」——あの時は音の変化を観測して報告していた。今夜は違う。「むりしないで」は観測ではない。"}, {"id": "ch10-s05-p074", "type": "text", "text": "すみれの指が俺の掌の中央を小さく押した。押すというほどではない。確認の力。いつもの。けれど確認の対象が違った。温度ではなく、俺の状態を確認している。"}, {"id": "ch10-s05-p075", "type": "text", "text": "「……痛くはなかった」"}, {"id": "ch10-s05-p076", "type": "text", "text": "答えた。嘘ではない。鐘に触れた時に来たものは、痛みではなかった。衝撃だった。一秒にも満たない映像の奔流。それは痛みとは違う。"}, {"id": "ch10-s05-p077", "type": "text", "text": "「でも——見えた。一瞬だけ。月と、歌と、匂いが」"}, {"id": "ch10-s05-p078", "type": "text", "text": "すみれの指が止まった。"}, {"id": "ch10-s05-p079", "type": "text", "text": "薄紫の瞳の中で、光が動いた。増えるのではなく、深くなった。瞳の表層から奥へ、光が沈んでいく。すみれの中で何かが反応している。俺の言葉に。俺が見たものに。鐘を通して。"}, {"id": "ch10-s05-p080", "type": "text", "text": "「……しまのうた」"}, {"id": "ch10-s05-p081", "type": "text", "text": "すみれの声が、細い糸の先端のようになった。S3の夜にも同じ声を聞いた。「れん、きこえてるんだね」の時と同じ。"}, {"id": "ch10-s05-p082", "type": "text", "text": "「わからない。歌かどうかも、はっきりしない。声が複数重なっていた。旋律があった。それだけだ」"}, {"id": "ch10-s05-p083", "type": "text", "text": "正直に言った。掴めなかったことを掴めなかったと言った。すみれの前では正直でいることが自然だった。この少女に嘘は通じない。通じないだけではなく、嘘をつく動機そのものが消える。"}, {"id": "ch10-s05-p084", "type": "text", "text": "すみれの指が俺の掌から離れた。離す直前に力が一瞬だけ強くなった。七月と同じ。S3と同じ。確認の力。それだけ。"}, {"id": "ch10-s05-p085", "type": "text", "text": "すみれが半歩下がった。俺を見上げている。"}, {"id": "ch10-s05-p086", "type": "text", "text": "「れん、しまのおとは、れんのものだよ」"}, {"id": "ch10-s05-p087", "type": "text", "text": "「俺のもの？」"}, {"id": "ch10-s05-p088", "type": "text", "text": "「うん。だれかがあげたんじゃない。れんのなかに、さいしょからあるの。かねがおしえてくれたんじゃなくて、れんがもってきたの」"}, {"id": "ch10-s05-p089", "type": "text", "text": "俺が持ってきた。この島に来る前から、俺の中にあった。"}, {"id": "ch10-s05-p090", "type": "text", "text": "歯車の手が知っていること。ルミエラ島の発音に迷いがなかったこと。月夜唄で体の芯が振動したこと。鐘の音の懐かしさ。全部。俺の中にあった。鐘が入れたのではなく、すみれが入れたのでもなく、俺が持ってきた。"}, {"id": "ch10-s05-p091", "type": "text", "text": "鳩尾の奥が、静かに鳴っていた。沈殿したものが底で響いている。月の光。歌声。果樹園の匂い。一秒にも満たない断片。消えたが、感覚だけが残っている。残っているものが、体の底で振動している。"}, {"id": "ch10-s05-p092", "type": "text", "text": "「すみれ」"}, {"id": "ch10-s05-p093", "type": "text", "text": "「うん」"}, {"id": "ch10-s05-p094", "type": "text", "text": "「俺は——知りたい。この音が何なのか」"}, {"id": "ch10-s05-p095", "type": "text", "text": "声に出した。八月の屋上で晶さんに聞けなかったもの。九月の記録室で雫に頼んだもの。S3の夜にすみれに「お前は何を知っているんだ」と聞いたもの。全部同じ方角を向いている。北。蝕域の方角。ルミエラ島の方角。全部同じ場所を指している。"}, {"id": "ch10-s05-p096", "type": "text", "text": "今夜、鐘に触れて、断片が見えた。受け身ではなかった。俺が手を伸ばした。四月に止めた手を。S3で止めた手を。今夜は止めなかった。触れた。触れたら、中のものが溢れた。"}, {"id": "ch10-s05-p097", "type": "text", "text": "知りたいのではない。知らなければならないのでもない。"}, {"id": "ch10-s05-p098", "type": "text", "text": "もう、始まっている。俺の中で、蓋が開きかけている。"}, {"id": "ch10-s05-p099", "type": "text", "text": "すみれが微笑んだ。口元が先に動いた。0.5秒遅れて目が追いかける。けれど今夜の微笑みは、どら焼きの時のずれなしの笑顔とも、S3の夜の選んでいる笑顔とも違っていた。悲しいのではない。嬉しいのでもない。すみれの棚の中に、この微笑みの名前はまだない。"}, {"id": "ch10-s05-p100", "type": "text", "text": "「れんがきめたなら、すみれはここにいるよ。いつでも」"}, {"id": "ch10-s05-p101", "type": "text", "text": "「ああ」"}, {"id": "ch10-s05-p102", "type": "text", "text": "星を見上げた。天蓋のガラス越しの十月の星空。白い点が黒の上に刺さっている。尖っている。すみれが言った通りだった。秋の星は尖っている。"}, {"id": "ch10-s05-p103", "type": "text", "text": "体の奥で底に沈んだものが、まだ振動している。月の光と歌声と果樹園の匂い。消えた断片の感覚だけが、体の中に残って鳴っている。"}, {"id": "ch10-s05-p104", "type": "text", "text": "静かだった。天蓋の間はいつも静かだ。すみれの呼吸が微かに聞こえる。遅い間隔。ゆっくりとした時間。"}, {"id": "ch10-s05-p105", "type": "text", "text": "しばらく、星を見ていた。"}, {"id": "ch10-s05-p106", "type": "text", "text": "「帰る」"}, {"id": "ch10-s05-p107", "type": "text", "text": "「うん」"}, {"id": "ch10-s05-p108", "type": "text", "text": "「また来る」"}, {"id": "ch10-s05-p109", "type": "text", "text": "「うん。すみれ、ここにいるから」"}, {"id": "ch10-s05-p110", "type": "text", "text": "振り返らなかった。すみれは星を見上げているだろう。"}, {"id": "ch10-s05-p111", "type": "text", "text": "螺旋階段を降りた。木の床が石段に切り替わった。十階の大鐘の脇を通った。鐘の表面が紫の光に浮かんでいた。さっき触れた場所は、もうわからない。熱は消えている。"}, {"id": "ch10-s05-p112", "type": "text", "text": "けれど、掌にはまだ残っていた。残響金属の冷たさ。その冷たさの奥で一瞬だけ通過した、月と歌と果樹園。"}, {"id": "ch10-s05-p113", "type": "text", "text": "管理室に降りた。消灯。施錠。正面入口を出た。"}, {"id": "ch10-s05-p114", "type": "text", "text": "十月の終わりの夜風。顔と首に冷たい空気が当たった。灯籠通りの灯りが遠くに見えた。"}, {"id": "ch10-s05-p115", "type": "text", "text": "右手の掌を見た。暗くてよく見えない。灯籠の橙色の光が掌の皺の影を少しだけ描いている。ここに、さっきまで鐘があった。すみれの指があった。"}, {"id": "ch10-s05-p116", "type": "text", "text": "歩き出した。補佐官舎まで。足音が自分の一人分だけ。灯籠の灯りが石畳に円を落としている。"}, {"id": "ch10-s05-p117", "type": "text", "text": "霜月さんの「また」と、すみれの「むりしないで」と、俺の右手が鐘に触れた夜。全部が十月の終わりに重なっている。蝕域の数値が加速している。鐘の出力に微細な変動がある。すみれが俺の中の音の変化を聞いている。"}, {"id": "ch10-s05-p118", "type": "text", "text": "静かだが、何かが動き始めている。"}, {"id": "ch10-s05-p119", "type": "text", "text": "補佐官舎の鍵を開けた。靴を脱いだ。暗いまま寝台に座った。"}, {"id": "ch10-s05-p120", "type": "text", "text": "右手を膝の上に置いた。掌を上に向けた。暗くて見えない。見えないが、掌の中央に、二つの温度が重なっている。鐘の冷たさとすみれの冷たさ。どちらも消えかけている。体温に上書きされていく。"}, {"id": "ch10-s05-p121", "type": "text", "text": "覚えておく。"}, {"id": "ch10-s05-p122", "type": "text", "text": "鐘に触れた時に見えた月の光と歌声と果樹園の匂いを。すみれの「おもいだすのはいたい」と「れんがきめたなら」を。右手の掌に残った、二つの冷たさの跡を。"}, {"id": "ch10-s05-p123", "type": "text", "text": "そして——俺が自分で手を伸ばしたことを。"}]}, {"chapter": 11, "chapterTitle": "歌と命の天秤", "scene": 1, "sceneTitle": "選抜公演", "wordCount": "約5,200字", "paragraphs": [{"id": "ch11-s01-p001", "type": "text", "text": "十一月に入って、空気が硬くなった。"}, {"id": "ch11-s01-p002", "type": "text", "text": "鐘に触れた夜から一週間ほど経っていた。右手の掌から鐘の冷たさとすみれの冷たさは完全に消え、日常の体温に戻っている。けれど鳩尾の底に沈殿したものは消えなかった。月の光。歌声。果樹園の匂い。一秒にも満たなかった断片の感覚が、朝の点検中にふいに浮かぶ。夜、寝台に横になった時に浮かぶ。消えるのではなく、沈んでいるだけだった。底にある。"}, {"id": "ch11-s01-p003", "type": "text", "text": "管理室の業務は変わらない。計器の読み取り、記録用紙への転記、共鳴管の定期洗浄。蝕域活動指数は南端で17%の上昇が続いていた。霜月さんの指示で追加した観測項目が三つに増えている。数字を見ることは俺の仕事だった。数字の向こうにあるものを考えることは——仕事ではないが、止められなくなっていた。"}, {"id": "ch11-s01-p004", "type": "text", "text": "今日は共鳴者選抜公演。響弦館。"}, {"id": "ch11-s01-p005", "type": "divider", "text": "---"}, {"id": "ch11-s01-p006", "type": "text", "text": "十四時。客席に座っていた。"}, {"id": "ch11-s01-p007", "type": "text", "text": "残響祭の時と同じ場所だった。右側通路に面した端の席。不具合時にすぐ動ける位置。音響盤の出力は今朝の最終確認で安定していた。天吊り拡声器の角度は五月に調整した三ミリのまま。四月に設営し、五月の残響祭で確認し、それ以降も月例点検のたびに計測している。ずれていない。"}, {"id": "ch11-s01-p008", "type": "text", "text": "響弦館の八百席は、五月より埋まっていた。"}, {"id": "ch11-s01-p009", "type": "text", "text": "選抜公演は外部からの来聴者が多い。管理局の制服が目に入る。紺地に銀の紋章。中円区の住民に混じって、見慣れない顔がある。評価者。共鳴者候補生の実力を査定する立場の人間が、前方の席に固まっている。"}, {"id": "ch11-s01-p010", "type": "text", "text": "燈花が三つ隣にいた。五月の残響祭と同じ配置。ポニーテールが揺れている。今日の燈花は前のめりではなかった。座面に背を預け、膝の上に手を置いている。指がスカートの布を掴んでいない。残響祭の時は楽しみの緊張があった。今は——待っている、という体だった。なにかを。"}, {"id": "ch11-s01-p011", "type": "text", "text": "燈花の右隣に篠宮さんがいた。背筋が真っ直ぐ。膝の上にメモ帳。ペンを持った右手が定位置にある。五月と変わらない。篠宮さんの準備は季節に左右されない。"}, {"id": "ch11-s01-p012", "type": "text", "text": "残響灯が落ちた。"}, {"id": "ch11-s01-p013", "type": "text", "text": "八百人の呼吸が浅くなった。五月と同じ変化。木の座席の軋みが消え、衣擦れが消え、静寂が響弦館の木材から染み出してくる。俺はこの静寂を知っている。五月に一度、知った。"}, {"id": "ch11-s01-p014", "type": "text", "text": "ステージの残響灯だけが白く灯っている。"}, {"id": "ch11-s01-p015", "type": "text", "text": "幕が上がった。"}, {"id": "ch11-s01-p016", "type": "text", "text": "鳴海さんが立っていた。"}, {"id": "ch11-s01-p017", "type": "text", "text": "白いブラウスに淡いブルーのスカート。五月と同じ衣装。カーディガンはない。腕が出ている。右前髪に薄桃色のリボン。亜麻色の髪が肩甲骨の下まで流れている。"}, {"id": "ch11-s01-p018", "type": "text", "text": "同じだった。五月と同じ服装、同じ位置、同じ残響灯の白い光。"}, {"id": "ch11-s01-p019", "type": "text", "text": "違ったのは、腕の細さだった。"}, {"id": "ch11-s01-p020", "type": "text", "text": "五月にもカーディガンなしで二の腕が見えていた。華奢だった。今は——華奢の先にある何かだった。腕の線が一段細くなっている。肘から手首にかけての輪郭がはっきりしすぎている。骨と皮膚の間にあるはずのものが、薄くなっている。"}, {"id": "ch11-s01-p021", "type": "text", "text": "半年分の差。"}, {"id": "ch11-s01-p022", "type": "text", "text": "五月の鳴海さんと十一月の鳴海さんの間に、半年ある。その半年の間に、鳴海さんは何度歌ったのか。共鳴室の計測に俺が同席したのは月に二回。公演はそれ以外にもあった。一度歌うたびに、瞳の色が薄くなり、首元を押さえ、膝が折れかける。その蓄積が、腕の輪郭に出ている。"}, {"id": "ch11-s01-p023", "type": "text", "text": "鳴海さんが息を吸った。"}, {"id": "ch11-s01-p024", "type": "text", "text": "五月と同じ動作。肩が上がり、胸が膨らみ、止まった。八百人の視線がその呼吸に集まっている。"}, {"id": "ch11-s01-p025", "type": "text", "text": "歌が始まった。"}, {"id": "ch11-s01-p026", "type": "text", "text": "最初の一音で、違うと判った。"}, {"id": "ch11-s01-p027", "type": "text", "text": "五月の残響祭と違う。七月の共鳴室とも違う。音の密度が、知っているどの歌声よりも高かった。"}, {"id": "ch11-s01-p028", "type": "text", "text": "低い音から始まった。胸の底に触れる振動。座席の木が震えている。五月にも感じた振動。けれど今回の振動は、座席だけではなかった。床が震えている。壁が震えている。響弦館の建物全体が、鳴海さんの最初の一音で鳴り始めていた。"}, {"id": "ch11-s01-p029", "type": "text", "text": "鳩尾が緩んだ。"}, {"id": "ch11-s01-p030", "type": "text", "text": "一回目。訓練棟の壁越し。同じ場所の筋肉がほどける。\n二回目。灯籠通りの後。同じ場所の、少し深い緩み。\n三回目。五月の残響祭。その奥にあるものが溶けた。「きれいだ」が模倣ではなく実感だった。\n四回目。七月の共鳴室。鳩尾ではなく胸の中央。温かさと痛みの同居。"}, {"id": "ch11-s01-p031", "type": "text", "text": "五回目。"}, {"id": "ch11-s01-p032", "type": "text", "text": "鳩尾でも胸の中央でもなかった。"}, {"id": "ch11-s01-p033", "type": "text", "text": "体の全部だった。"}, {"id": "ch11-s01-p034", "type": "text", "text": "音が全身に入ってきた。共鳴室の球形の壁面が音を反射して体を包んだのと構造が似ていたが、規模が違った。共鳴室は直径十メートルの空間。ここは八百席の響弦館。天吊り拡声器と左右の壁面拡声器が音を三方向から運び、木の壁と天井と床がその音を吸い、増幅し、客席のすべての木の椅子を通して体に届けている。"}, {"id": "ch11-s01-p035", "type": "text", "text": "鳴海さんの声が、建物を楽器にしている。五月もそうだった。けれど今日は——楽器の鳴り方が違う。五月の響弦館は木琴のように鳴った。今日の響弦館は、鐘のように鳴っている。"}, {"id": "ch11-s01-p036", "type": "text", "text": "鐘。"}, {"id": "ch11-s01-p037", "type": "text", "text": "鐘鋳塔の大鐘に掌を当てた時の振動。あの日、掌の下で感じた微細な振動と、今、座席の木を通して体に届いている振動が、同じだった。体の底に沈殿していたものが反応した。月の光。歌声。果樹園の匂い。あの断片が、鳴海さんの歌声に呼応して震え始めた。"}, {"id": "ch11-s01-p038", "type": "text", "text": "客席の空気が変わっていた。"}, {"id": "ch11-s01-p039", "type": "text", "text": "五月の時も空気は澄んだ。今日はそれ以上だった。澄むのではなく、空気の中の何かが減っていた。重さが消えていく。この島を覆っている蝕域の重さが——物理的に計測できるものではないはずだが——体が感じている。軽くなっている。鳴海さんの歌声が、響弦館の内側から蝕域を押し返している。"}, {"id": "ch11-s01-p040", "type": "text", "text": "旋律が高音域に入った。"}, {"id": "ch11-s01-p041", "type": "text", "text": "五月の残響祭では声が光に聞こえた。今日も同じだった。音が光になる。耳で聴いているのに、目の奥に白い線が走る。けれど今日の光は、五月より——近い。目の奥ではなく、もっと手前にある。瞼の裏側にある。"}, {"id": "ch11-s01-p042", "type": "text", "text": "目の奥が熱くなった。"}, {"id": "ch11-s01-p043", "type": "text", "text": "一回目から五回目まで、この熱は毎回あった。涙に変わらない熱。蛇口の手前で止まっている水。管が詰まっている。それが俺の体の仕様だった。感じている。感じているのに出力されない。"}, {"id": "ch11-s01-p044", "type": "text", "text": "今回も同じだろう、と思った。"}, {"id": "ch11-s01-p045", "type": "text", "text": "鳴海さんの歌声が頂点に向かっていた。旋律が細くなり、密度が増していく。糸が一本になるほど細いのに鋼鉄のように硬い。五月にも同じ比喩を使った。けれど今日の声は鋼鉄ではなかった。もっと柔らかい。鋼ではなく、血管のように柔らかく、血管のように脈打っている。生きている声だった。"}, {"id": "ch11-s01-p046", "type": "text", "text": "鳴海さんの顔が見えた。"}, {"id": "ch11-s01-p047", "type": "text", "text": "五月の残響祭の時と、表情が違った。あの時は「穏やかな微笑みではなかった」。何もない顔。何もないのに目が離せない顔。使命を背負った歌い手の顔。"}, {"id": "ch11-s01-p048", "type": "text", "text": "今日の顔にも微笑みはなかった。目が見開かれ、口が大きく開き、首の筋が浮いている。五月と同じ構造。けれど——目の中に、あるものが違った。"}, {"id": "ch11-s01-p049", "type": "text", "text": "五月の鳴海さんの目には、八百人がいた。八百人を見て、八百人に届ける目。学院の宝としての目。共鳴者としての目。"}, {"id": "ch11-s01-p050", "type": "text", "text": "今日の鳴海さんの目には、八百人がいなかった。"}, {"id": "ch11-s01-p051", "type": "text", "text": "誰も見ていなかった。客席も評価者も見ていない。自分の歌声だけを見ている。内側を見ている。歌っている自分自身を見ている。灯籠通りの分岐で「歌うことが、好きなんです」と言った時の声。共鳴室で「わたしは……好きです。鐘の音も、歌うことも」と言った時の声。あの声が、今、歌になっている。"}, {"id": "ch11-s01-p052", "type": "text", "text": "使命ではなかった。評価のためでもなかった。歌いたいから歌っている。それだけの目だった。"}, {"id": "ch11-s01-p053", "type": "text", "text": "その目が——"}, {"id": "ch11-s01-p054", "type": "text", "text": "頬が濡れていた。"}, {"id": "ch11-s01-p055", "type": "text", "text": "目の奥の熱が、瞼を通過していた。右の頬を何かが伝っている。温かい液体。速度は遅い。頬骨の上を通り、頬の窪みに沿って下がっている。右だけではなかった。左の頬にも。同じ速度で、同じ軌道で。"}, {"id": "ch11-s01-p056", "type": "text", "text": "涙だった。"}, {"id": "ch11-s01-p057", "type": "text", "text": "出ている。"}, {"id": "ch11-s01-p058", "type": "text", "text": "管が——通った。"}, {"id": "ch11-s01-p059", "type": "text", "text": "蛇口はあった。水はあった。管が詰まっていた。五月に認識し、七月に再確認し、ずっと詰まっていた管。それが通った。水が出てきた。涙という名前の水が、両方の頬を伝っている。"}, {"id": "ch11-s01-p060", "type": "text", "text": "止まらなかった。"}, {"id": "ch11-s01-p061", "type": "text", "text": "拭こうとする前に、次の涙が目から溢れた。溢れるという表現が正確だった。意図して出しているのではない。蛇口を開けたのでもない。管が通って、溜まっていたものが流れ出ている。四月から溜まっていたのか。もっと前からか。わからない。わからないが、止まらなかった。"}, {"id": "ch11-s01-p062", "type": "text", "text": "視界が滲んだ。鳴海さんの輪郭がぼやけた。亜麻色の髪と白いブラウスの境界が溶けている。残響灯の白い光が水の膜を通して屈折し、ステージ全体が柔らかく発光して見えた。"}, {"id": "ch11-s01-p063", "type": "text", "text": "泣いている。"}, {"id": "ch11-s01-p064", "type": "text", "text": "俺が泣いている。"}, {"id": "ch11-s01-p065", "type": "text", "text": "自分の頬を右手の甲で拭った。濡れた。手の甲の皮膚に涙の温度がある。体温よりわずかに低い。蒸発が始まっている。拭いた端から、また涙が出た。"}, {"id": "ch11-s01-p066", "type": "text", "text": "驚いていた。泣いていることに驚いている。そこは緩んでいる。目の奥は熱い。「きれいだ」がある。全部、五月と同じ場所にある。五月にはなかったものが一つだけ加わっている。涙。"}, {"id": "ch11-s01-p067", "type": "text", "text": "なぜ今回は出たのか。"}, {"id": "ch11-s01-p068", "type": "text", "text": "わからなかった。五月と今日で何が変わったのか。鳴海さんの歌声が強くなった。それはある。けれど涙は音量で出るものではない。たぶん。変わったのは俺の方だ。四月から十一月までの間に、体の中のどこかが変わった。管の詰まりが、少しずつ、少しずつ溶かされていた。食堂の味噌汁の湯気に。燈花の「蓮くん」に。篠宮さんの止まったペンに。すみれの冷たい指に。霜月さんの「また」に。鐘の振動に。全部が、少しずつ管を溶かしていた。"}, {"id": "ch11-s01-p069", "type": "text", "text": "そして今、鳴海さんの歌声が、最後の一片を押し流した。"}, {"id": "ch11-s01-p070", "type": "text", "text": "左の方で、天城さんの小さな嗚咽が聞こえた。五月と同じだった。天城さんは泣ける人だ。"}, {"id": "ch11-s01-p071", "type": "text", "text": "今日は、俺も泣いている。同じ側にいる。"}, {"id": "ch11-s01-p072", "type": "text", "text": "最後の一音が響いた。"}, {"id": "ch11-s01-p073", "type": "text", "text": "長かった。五月よりも長い。三十秒近くあったかもしれない。時間の感覚が正確ではないから断言はできない。最後の一音が響弦館の木材に染み込み、壁を伝い、天井を伝い、客席の座席を通して体に届いた。"}, {"id": "ch11-s01-p074", "type": "text", "text": "音が消えた。残響が薄く留まっている。五月と同じ残響。音が終わった後の静寂は、音が始まる前の静寂とは別のものだった。"}, {"id": "ch11-s01-p075", "type": "text", "text": "拍手が来た。"}, {"id": "ch11-s01-p076", "type": "text", "text": "一人が始め、波が広がり、八百人の拍手が重なった。五月よりも大きい拍手だった。木の壁に反射し、増幅され、響弦館が揺れた。俺の手も動いていた。掌が熱い。涙の跡が乾いていない頬で、俺は手を叩いていた。"}, {"id": "ch11-s01-p077", "type": "text", "text": "鳴海さんがステージの中央で頭を下げた。"}, {"id": "ch11-s01-p078", "type": "text", "text": "顔を上げた時、微笑んでいた。穏やかな微笑み。口元と目がほぼ同時に動く。いつもの鳴海さん。歌い終わると、鳴海さんは鳴海さんに戻る。五月と同じ構造。"}, {"id": "ch11-s01-p079", "type": "text", "text": "微笑んだまま、鳴海さんが一歩後ろに下がった。"}, {"id": "ch11-s01-p080", "type": "text", "text": "右膝が折れた。"}, {"id": "ch11-s01-p081", "type": "text", "text": "五月とは違った。"}, {"id": "ch11-s01-p082", "type": "text", "text": "五月は「折れかけた」だった。右膝が内側に折れかけ、体が右に傾き、半秒で持ち直した。客席からは見えなかった。俺の席の角度から辛うじて見えた程度だった。"}, {"id": "ch11-s01-p083", "type": "text", "text": "今日の膝折りは、客席からも見えた。"}, {"id": "ch11-s01-p084", "type": "text", "text": "鳴海さんの右膝が折れ、左膝がつられるように沈み、体が前に傾いた。両手がステージの床に触れた。一秒。二秒。三秒。鳴海さんがステージの上で、両手と両膝をついていた。"}, {"id": "ch11-s01-p085", "type": "text", "text": "ステージの左袖から影が動いた。"}, {"id": "ch11-s01-p086", "type": "text", "text": "風祭さんだった。"}, {"id": "ch11-s01-p087", "type": "text", "text": "五月と同じだった。膝を曲げない速い歩き。四歩。いや、今日は——五歩だった。五月の四歩より距離が遠い。風祭さんの待機位置が五月より一歩分奥になっていたのか。それとも鳴海さんが崩れた位置が、五月より舞台の中央寄りだったのか。"}, {"id": "ch11-s01-p088", "type": "text", "text": "風祭さんが鳴海さんの左腕を取った。もう片方の手が背中に回った。五月は腕だけだった。今日は背中にも手を当てている。それだけ鳴海さんの体重を支える必要があるということ。"}, {"id": "ch11-s01-p089", "type": "text", "text": "鳴海さんが立ち上がった。風祭さんの腕を借りて。足が震えていた。微かだが震えていた。"}, {"id": "ch11-s01-p090", "type": "text", "text": "微笑んだ。"}, {"id": "ch11-s01-p091", "type": "text", "text": "穏やかな微笑み。壁のある微笑み。八百人に向ける微笑み。「大丈夫です」と口が動いた。声は聞こえなかった。拍手にかき消されていた。"}, {"id": "ch11-s01-p092", "type": "text", "text": "鳴海さんの顔色が悪かった。"}, {"id": "ch11-s01-p093", "type": "text", "text": "残響灯の白い光の下で、肌の色が変わっていた。五月の公演後に見た顔は、汗が浮いていたが血色はあった。今日の顔には血色がない。唇の赤みが薄い。頬が白い。頬ではなく——青白い。白の向こうに青がある。"}, {"id": "ch11-s01-p094", "type": "text", "text": "風祭さんが鳴海さんを支えたまま、袖幕の向こうに下がっていく。鳴海さんが最後にもう一度頭を下げた。微笑んだまま。髪が揺れた。亜麻色の毛先が残響灯の光を受けて金色に透けた。五月と同じ光り方。"}, {"id": "ch11-s01-p095", "type": "text", "text": "袖幕の向こうに消えた。"}, {"id": "ch11-s01-p096", "type": "text", "text": "拍手が続いていた。立ち上がる観客がいた。評価者の席でも拍手が鳴っていた。前の席の人が隣の人に何か話しかけている。「素晴らしい」「今までで一番——」。五月にも同じ言葉が聞こえた。"}, {"id": "ch11-s01-p097", "type": "text", "text": "俺は座ったままだった。"}, {"id": "ch11-s01-p098", "type": "text", "text": "頬がまだ濡れていた。涙は止まっていた。けれど乾いていない。右手の甲についた涙の跡も乾いていない。十一月の空気は五月より乾いているはずだ。それでも乾かない。たぶん量が多かったのだと思う。"}, {"id": "ch11-s01-p099", "type": "text", "text": "目の奥の熱は消えかけていた。涙と一緒に出ていった。管が通ったから。溜まっていたものが流れ出たから。目の奥が軽い。四月からずっと溜まっていた重さが、軽くなっている。"}, {"id": "ch11-s01-p100", "type": "text", "text": "代わりに、鳩尾の上——鳴海さんの歌声がいつも触れる場所——に、新しい重さがあった。"}, {"id": "ch11-s01-p101", "type": "text", "text": "膝が折れた。顔色が青白かった。微笑んでいた。「大丈夫です」と口が動いた。風祭さんの手が背中に回った。五月は腕だけで足りた。今日は背中にも手が要った。"}, {"id": "ch11-s01-p102", "type": "text", "text": "五月から十一月までの半年で、鳴海さんの体は確実に消耗している。"}, {"id": "ch11-s01-p103", "type": "text", "text": "観察している。記録している。保留している。いつものパターンだった。けれど今日は——保留の場所が、いつもと違う場所にあった。頭ではなく、同じ場所にある。鳴海さんの歌声が触れる場所と同じ場所に、鳴海さんの膝が折れた映像が沈んでいた。"}, {"id": "ch11-s01-p104", "type": "text", "text": "客席が明るくなった。残響灯が元の光量に戻り、八百人が立ち上がり始めた。"}, {"id": "ch11-s01-p105", "type": "text", "text": "立ち上がった。"}, {"id": "ch11-s01-p106", "type": "text", "text": "左の三つ隣で、燈花が目元を拭いていた。赤くなっている。五月と同じだ。けれど燈花も俺と同じものを見ていただろう。膝が折れた鳴海さんを。"}, {"id": "ch11-s01-p107", "type": "text", "text": "篠宮さんのペンは動いていなかった。メモ帳は膝の上にある。ペンは右手にある。紙に触れていない。五月の時は歌の後にペンが十秒止まった。今日はそれ以上止まっている。"}, {"id": "ch11-s01-p108", "type": "text", "text": "通路を歩いた。ホワイエに出た。人が多い。公演後の余韻を持った顔が並んでいる。「歴代最高」「選抜一位は確実」という声が聞こえた。"}, {"id": "ch11-s01-p109", "type": "text", "text": "胸の上の一点の重さが消えなかった。"}, {"id": "ch11-s01-p110", "type": "text", "text": "鳴海さんの歌声の余韻と、鳴海さんの膝が折れた映像。二つが同じ場所に重なっている。きれいだった。涙が出た。管が通った。それは確かだった。確かだったのに、その確かさと同じ重さで、鳴海さんの青白い顔色が残っている。"}, {"id": "ch11-s01-p111", "type": "text", "text": "覚えておく。"}, {"id": "ch11-s01-p112", "type": "text", "text": "鳴海さんの歌と、五回目の涙と、通った管と、折れた膝と、風祭さんの五歩と、背中に回った手を。"}]}, {"chapter": 11, "chapterTitle": "歌と命の天秤", "scene": 2, "sceneTitle": "楽屋の崩壊", "wordCount": "約5,100字", "paragraphs": [{"id": "ch11-s02-p001", "type": "text", "text": "ホワイエを抜けた。"}, {"id": "ch11-s02-p002", "type": "text", "text": "人の流れに逆行する形で、正面ホールの左手にある関係者通路に入った。音響機材の公演後点検。天吊り拡声器の出力ログを回収し、壁面拡声器の接合部に異常がないか目視確認する。公演直後に一度、翌朝にもう一度。それが手順だった。"}, {"id": "ch11-s02-p003", "type": "text", "text": "頬の涙の跡はまだ乾いていない。右手の甲で拭った。二度目。乾いた。"}, {"id": "ch11-s02-p004", "type": "text", "text": "関係者通路は天井が低い。響弦館の客席側は天井が高く木材が音を吸うが、裏手は石壁の事務的な構造で、足音が硬く返る。残響灯が壁面に等間隔で埋め込まれ、青白い光が廊下を均質に照らしている。人がいない。公演が終わったばかりで、スタッフはまだ客席側の撤収にかかっている。"}, {"id": "ch11-s02-p005", "type": "text", "text": "足が速かった。"}, {"id": "ch11-s02-p006", "type": "text", "text": "意識していなかった。普段の巡回ではこの通路を一分十秒で通過する。歩幅は一定。速度も一定。監視哨時代に身についた歩行のリズムは、学院に来てからも変わっていない。——今日は変わっていた。歩幅が広い。速度が上がっている。靴底が石の床を打つ間隔が短い。"}, {"id": "ch11-s02-p007", "type": "text", "text": "鳩尾の上の重さが、足を速くしていた。"}, {"id": "ch11-s02-p008", "type": "text", "text": "歌声の余韻と膝が折れた映像。二つが重なって沈んでいる場所。そこから下に向かって、何かが足の筋肉を引いている。業務は業務だった。公演後点検は手順に従って行う。けれど足の速さは手順の外にあった。"}, {"id": "ch11-s02-p009", "type": "text", "text": "楽屋の前を通る。"}, {"id": "ch11-s02-p010", "type": "text", "text": "関係者通路の突き当たりを右に折れると、響弦館の裏手に三つの楽屋がある。公演者用の第一楽屋が一番奥。木の扉。扉の上に「第一楽屋」の真鍮プレート。扉は閉まっている。"}, {"id": "ch11-s02-p011", "type": "text", "text": "声が聞こえた。"}, {"id": "ch11-s02-p012", "type": "text", "text": "扉の向こうから。木の扉は響弦館の他の部分と同じ素材で、防音性は高くない。楽屋は舞台裏の一角だが、共鳴室のような完全防音構造ではなかった。声が漏れている。"}, {"id": "ch11-s02-p013", "type": "text", "text": "風祭さんの声だった。"}, {"id": "ch11-s02-p014", "type": "text", "text": "「ちーちゃん——」"}, {"id": "ch11-s02-p015", "type": "text", "text": "声が途切れた。途切れたのではない。声が声として完成する前に、別のものに変わった。嗚咽。二ヶ月前、訓練棟の前で聞いた風祭さんの声は震えていたが、声の形を保っていた。今の声は形を失っている。"}, {"id": "ch11-s02-p016", "type": "text", "text": "足が止まった。"}, {"id": "ch11-s02-p017", "type": "text", "text": "楽屋の扉の前。音響機材の点検は、このまま通路を進んだ先の機材室で行う。楽屋の前で立ち止まる業務上の理由はない。"}, {"id": "ch11-s02-p018", "type": "text", "text": "立ち止まっていた。"}, {"id": "ch11-s02-p019", "type": "text", "text": "扉の向こうで、もう一つの声がした。"}, {"id": "ch11-s02-p020", "type": "text", "text": "「いろは……大丈夫だから……」"}, {"id": "ch11-s02-p021", "type": "text", "text": "鳴海さんの声。"}, {"id": "ch11-s02-p022", "type": "text", "text": "薄かった。音量が低いのではない。声の厚みが薄い。ステージの上で響弦館を鐘のように鳴らした声と同じ人間の声だとは、耳が判断できなかった。歌声から切り離された後の声。共鳴を使い果たした後に残った声。厚みが削られて、紙のように薄くなっている。"}, {"id": "ch11-s02-p023", "type": "text", "text": "扉を開けた。"}, {"id": "ch11-s02-p024", "type": "text", "text": "ノックしなかった。手が先に動いた。把手を引いた。木の扉が内側に開いた。"}, {"id": "ch11-s02-p025", "type": "text", "text": "楽屋の中が見えた。"}, {"id": "ch11-s02-p026", "type": "text", "text": "ソファがある。壁際の長い革張りのソファ。その上に鳴海さんが横たわっていた。"}, {"id": "ch11-s02-p027", "type": "text", "text": "仰向けではなく、右半身を下にして体を丸めるように横になっている。白いブラウスの襟元が乱れていた。ステージの上では整っていた前髪が額に張りついている。汗。亜麻色の髪が顔にかかり、頬の線が隠れている。"}, {"id": "ch11-s02-p028", "type": "text", "text": "風祭さんが鳴海さんを抱きしめていた。"}, {"id": "ch11-s02-p029", "type": "text", "text": "ソファの縁に膝をつき、上半身をかぶせるようにして。右腕が鳴海さんの肩の下に差し込まれ、左手が背中に回っている。風祭さんの栗色の短い髪が鳴海さんの亜麻色の髪と重なっている。二人の体が一つの塊になっている。"}, {"id": "ch11-s02-p030", "type": "text", "text": "風祭さんの肩が震えていた。"}, {"id": "ch11-s02-p031", "type": "text", "text": "泣いていた。"}, {"id": "ch11-s02-p032", "type": "text", "text": "風祭さんが泣いている。"}, {"id": "ch11-s02-p033", "type": "text", "text": "九月の訓練棟前で、風祭さんは泣きそうで泣かなかった。目に水の膜がかかっていたが、涙にはならなかった。あの時は——泣かない人だと思った。千歳の前では笑い、俺の前では硬い顔を作り、怒る時は声を張り上げる。泣く場面を見たことがなかった。"}, {"id": "ch11-s02-p034", "type": "text", "text": "今、泣いている。"}, {"id": "ch11-s02-p035", "type": "text", "text": "声が出ていた。「だから言ったでしょ」という言葉の断片が、嗚咽の間から聞こえた。「無理しないでって……言ったでしょ……」"}, {"id": "ch11-s02-p036", "type": "text", "text": "あの日の声とは違った。九月の風祭さんは壁の向こうから手を伸ばしていた。今の風祭さんには壁がなかった。壁が崩れている。壁があった場所に何もない。あるのは声と涙と、鳴海さんの背中に回した腕だけだった。"}, {"id": "ch11-s02-p037", "type": "text", "text": "鳴海さんが口を開いた。"}, {"id": "ch11-s02-p038", "type": "text", "text": "「わたしは大丈夫ですよ……少し疲れただけ……」"}, {"id": "ch11-s02-p039", "type": "text", "text": "口癖。"}, {"id": "ch11-s02-p040", "type": "text", "text": "残響祭の日に膝が折れかけた時、袖幕の向こうで口が動いた。「大丈夫です」。九月に風祭さんが俺に言った——「わたしは大丈夫ですよ」って、あの子、嘘つくの下手なくせに。"}, {"id": "ch11-s02-p041", "type": "text", "text": "笑おうとしていた。"}, {"id": "ch11-s02-p042", "type": "text", "text": "鳴海さんが笑おうとしている。ソファに横たわったまま、顔にかかった髪の間から口元が見えた。口角が上がりかけている。穏やかな微笑み。いつもの、壁のある微笑み。八百人に向ける微笑みと同じ構造の笑顔を、横たわったまま作ろうとしている。"}, {"id": "ch11-s02-p043", "type": "text", "text": "完成しなかった。"}, {"id": "ch11-s02-p044", "type": "text", "text": "口角が上がり、目が追いかけて——止まった。七割ほどの位置で、表情が固まった。笑顔にならなかった。微笑みの形が途中で止まり、そのまま動かなくなった。筋肉が足りない。表情を完成させるだけの力が、顔の筋肉に残っていなかった。"}, {"id": "ch11-s02-p045", "type": "text", "text": "風祭さんの腕が強くなった。鳴海さんを抱きしめる力が増している。「大丈夫じゃないでしょ……見ればわかるよ……」"}, {"id": "ch11-s02-p046", "type": "text", "text": "声が裂けていた。怒りと心配と、もう一つ別のものが混ざっている。訓練棟前での「嘘つくの下手なくせに」の延長線上にある声だが、あの時より遥かに剥き出しだった。二年分の何かが裂けている。"}, {"id": "ch11-s02-p047", "type": "text", "text": "俺は立っていた。"}, {"id": "ch11-s02-p048", "type": "text", "text": "楽屋の入口。扉を開けたまま。足が中に入らなかった。鳴海さんが横たわっていて、風祭さんが抱きしめている。その二人の輪郭の外側に、俺は立っていた。"}, {"id": "ch11-s02-p049", "type": "text", "text": "風祭さんが気づいた。"}, {"id": "ch11-s02-p050", "type": "text", "text": "顔を上げた。涙で濡れた緑色の目が俺を見た。翡翠色。二ヶ月前の訓練棟前で見た目の色は水の膜がかかった翡翠だった。今日の目は——膜ではなかった。涙が流れたあとの目。水底から見上げているのではなく、水が全部出てしまった後の、赤くなった目。"}, {"id": "ch11-s02-p051", "type": "text", "text": "二秒。"}, {"id": "ch11-s02-p052", "type": "text", "text": "風祭さんの視線が俺を測っていた。邪魔者か。部外者か。追い払うべきか。六月の昇降口の時なら俺を睨んで「出て行って」と言っただろう。九月の訓練棟前なら目をそらして黙った。"}, {"id": "ch11-s02-p053", "type": "text", "text": "今日は違った。"}, {"id": "ch11-s02-p054", "type": "text", "text": "風祭さんの視線が変わった。追い払う目ではなかった。測る目でもなかった。「いる」ということを認めた目。俺がここにいることを、今この場所にいることを、排除せずに受け入れた目。"}, {"id": "ch11-s02-p055", "type": "text", "text": "「……朝霧さん」"}, {"id": "ch11-s02-p056", "type": "text", "text": "声がかすれていた。嗚咽の残りがまだ喉に詰まっている。名前を呼んだ。「朝霧さん」。昇降口で呼び止められた日と同じ呼び方。けれど距離の表明ではなかった。誰かの名前を呼ぶことで、自分がどこにいるのかを確認しようとしている声だった。"}, {"id": "ch11-s02-p057", "type": "text", "text": "「ちーちゃんが」"}, {"id": "ch11-s02-p058", "type": "text", "text": "それだけだった。風祭さんはそれ以上言わなかった。言えなかった。目が再び鳴海さんに戻り、腕の力がまた強くなった。"}, {"id": "ch11-s02-p059", "type": "text", "text": "鳴海さんの右手がソファの縁から垂れていた。"}, {"id": "ch11-s02-p060", "type": "text", "text": "指先が微かに痙攣していた。震えではない。痙攣。筋肉が意志と関係なく動いている。震えなら止められる。痙攣は止められない。白い指が不規則に、小さく、何度も動いていた。"}, {"id": "ch11-s02-p061", "type": "text", "text": "観察した。"}, {"id": "ch11-s02-p062", "type": "text", "text": "顔色。青白い。ステージの上で見た時よりもさらに悪い。残響灯の白い光の下で、肌が透けるように白く、その白の下に青灰色がある。頬にも唇にも血の色がなかった。"}, {"id": "ch11-s02-p063", "type": "text", "text": "呼吸。浅い。胸の上下が小さい。普通の人間の呼吸なら胸とともに腹も動く。鳴海さんの腹は動いていなかった。胸だけが、浅く、速く、上下している。肩も上がらない。呼吸に肩が参加していない。横隔膜が十分に動いていない。"}, {"id": "ch11-s02-p064", "type": "text", "text": "手の震え。右手の痙攣は続いている。左手は風祭さんの腕の下にあって見えなかった。右手の指先の動きに規則性はない。等間隔ではない。ランダムな痙攣。"}, {"id": "ch11-s02-p065", "type": "text", "text": "瞳の色。琥珀がかった茶色のはずだった。今は——色が薄い。蜂蜜色に見えることがあった瞳が、水で薄めたように色を失っている。六月に共鳴室で「薄くなった」と記録した時よりも、さらに薄い。"}, {"id": "ch11-s02-p066", "type": "text", "text": "「少し疲れた」ではない。"}, {"id": "ch11-s02-p067", "type": "text", "text": "そう判断した。観察して、記録して、判断した。顔色の変化。呼吸の浅さ。手の痙攣。瞳の色の薄れ。どれか一つなら「疲れ」で片付けられたかもしれない。四つ全部が揃っている。これは疲労ではなかった。体が何かを大量に失っている。歌のたびに薄くなる瞳。首元を押さえる癖。折れる膝。半年分の蓄積が、今日の公演で一気に表面化している。"}, {"id": "ch11-s02-p068", "type": "text", "text": "保留にしなかった。"}, {"id": "ch11-s02-p069", "type": "text", "text": "いつもなら保留にする。観察して、記録して、意味がわからないものは棚に並べておく。六月に記録した首元を押さえる癖。九月に風祭さんが漏らした「嘘つくの下手なくせに」。保留の棚に整理して置いておいた。"}, {"id": "ch11-s02-p070", "type": "text", "text": "今日は棚に置けなかった。棚ではなく、鳩尾の上に落ちた。鳴海さんの歌声の余韻がまだ残っている場所。膝が折れた映像が沈んでいる場所。そこに、楽屋で見た四つの症状が追加で落ちた。重い。鳩尾の上が重い。頭で処理する前に、体が先に反応している。"}, {"id": "ch11-s02-p071", "type": "text", "text": "鳴海さんの目が俺を見ていた。"}, {"id": "ch11-s02-p072", "type": "text", "text": "横たわったまま、髪の間から。七割で止まった笑顔の残骸で。琥珀の薄い瞳で。"}, {"id": "ch11-s02-p073", "type": "text", "text": "「蓮さん……お仕事、お疲れさまです……」"}, {"id": "ch11-s02-p074", "type": "text", "text": "声が出ていた。薄い声で。ここに横たわって動けなくなっている人が、立っている俺に「お疲れさまです」と言っていた。"}, {"id": "ch11-s02-p075", "type": "text", "text": "風祭さんの腕がさらに強くなった。鳴海さんの体を引き寄せている。「もう喋らないで、ちーちゃん。喋らなくていいから」"}, {"id": "ch11-s02-p076", "type": "text", "text": "風祭さんの声が割れていた。怒りではなかった。祈りに近い声だった。残響祭の袖幕の陰で腕を組んでいた風祭さん。あれは祈りではなく準備だと、訓練棟の前で思った。今の声は——準備でも牽制でもなかった。準備が間に合わなかった人間の声だった。"}, {"id": "ch11-s02-p077", "type": "text", "text": "鳴海さんが風祭さんの腕の中で息を吐いた。長い吐息。諦めではなく、力が抜ける音。自分から力を抜いたのではなく、力が体から出ていく音。"}, {"id": "ch11-s02-p078", "type": "text", "text": "「……ごめんね、いろは」"}, {"id": "ch11-s02-p079", "type": "text", "text": "小さい声だった。"}, {"id": "ch11-s02-p080", "type": "text", "text": "風祭さんの肩の震えが大きくなった。泣いている。声を出さずに。嗚咽を噛み殺して、鳴海さんの背中に顔を押しつけて。"}, {"id": "ch11-s02-p081", "type": "text", "text": "三人の構図。"}, {"id": "ch11-s02-p082", "type": "text", "text": "鳴海さんはソファの上にいた。横たわっている。風祭さんはソファの縁にいた。鳴海さんを抱きしめている。俺は入口にいた。立っている。"}, {"id": "ch11-s02-p083", "type": "text", "text": "外側にいた。"}, {"id": "ch11-s02-p084", "type": "text", "text": "鳴海さんと風祭さんの間にある九年分の時間の外に、俺は立っていた。中に入る場所がなかった。入る資格があるのかどうかもわからなかった。四月にこの島に来て、半年と少し。鳴海さんの歌を聴いて泣いた。それは確かだった。管が通った。それも確かだった。けれど鳴海さんの体に何が起きているのか、俺はまだ正確には知らない。風祭さんが二年前から知っていることを、俺はまだ知らない。"}, {"id": "ch11-s02-p085", "type": "text", "text": "知らないまま、ここに立っている。"}, {"id": "ch11-s02-p086", "type": "text", "text": "鳩尾の上が重かった。歌声と膝折りと、青白い顔色と手の痙攣と、七割の笑顔と「大丈夫です」と「ごめんね、いろは」が、全部同じ場所に沈んでいた。保留にできない。棚に並べられない。頭ではなく体の方が先に受け取っている。これは——鳴海さんの歌声を聴いて泣いた時と同じ場所だった。管が通った場所。涙が出た場所。そこに、涙とは別のものが溜まり始めている。"}, {"id": "ch11-s02-p087", "type": "text", "text": "名前がまだない。"}, {"id": "ch11-s02-p088", "type": "text", "text": "怒りなのか悲しみなのか焦りなのか。わからない。わからないが、鳩尾の上にある。消えない。重い。鳴海さんの歌が管を通した。通った管から、涙の代わりに別のものが入ってきている。"}, {"id": "ch11-s02-p089", "type": "text", "text": "風祭さんの赤い目が、もう一度だけ俺を見た。"}, {"id": "ch11-s02-p090", "type": "text", "text": "長い視線だった。一秒か二秒。涙の跡が頬に残っている。その目の中に、問いがあった。言葉にならない問い。——あなたは、見たのか。見てしまったのか。この子がどうなっているのか、見たのか。"}, {"id": "ch11-s02-p091", "type": "text", "text": "見た。"}, {"id": "ch11-s02-p092", "type": "text", "text": "四つの症状を見た。七割の笑顔を見た。「大丈夫」の嘘を聞いた。薄い声を聞いた。"}, {"id": "ch11-s02-p093", "type": "text", "text": "風祭さんの目が閉じた。まぶたの下から新しい涙が溢れた。もう拭わなかった。拭う余裕がなかった。両腕が鳴海さんを抱きしめることだけに使われている。"}, {"id": "ch11-s02-p094", "type": "text", "text": "俺は楽屋の入口に立ったまま、三つのことを覚えた。"}, {"id": "ch11-s02-p095", "type": "text", "text": "鳴海さんの右手の痙攣。風祭さんの涙。七割で止まった笑顔。"}, {"id": "ch11-s02-p096", "type": "text", "text": "覚えておく。"}]}, {"chapter": 11, "chapterTitle": "歌と命の天秤", "scene": 3, "sceneTitle": "いろはの告白", "wordCount": "約6,200字", "paragraphs": [{"id": "ch11-s03-p001", "type": "text", "text": "教員が来た。"}, {"id": "ch11-s03-p002", "type": "text", "text": "楽屋の扉の向こうから足音が二つ聞こえて、白衣の女性と、紺の制服を着た年配の男性が関係者通路を早足で歩いてきた。医務室のスタッフと、教員。俺が入口に立っていることに気づくと、女性の方が「すみません、通してください」と言った。"}, {"id": "ch11-s03-p003", "type": "text", "text": "体を横にずらした。"}, {"id": "ch11-s03-p004", "type": "text", "text": "白衣の女性が楽屋に入り、鳴海さんの状態を確認した。指先を脈に当て、まぶたを開いて瞳孔を見た。「担架を持ってきてください」と廊下の教員に声をかけた。"}, {"id": "ch11-s03-p005", "type": "text", "text": "風祭さんは鳴海さんの手を握ったまま動かなかった。白衣の女性が「風祭さん、少しだけ離れてもらっていい？」と聞いた時、風祭さんの指が鳴海さんの手を握り直した。締めるのではない。離すまいとしている。三秒。風祭さんの指がゆっくり開いた。"}, {"id": "ch11-s03-p006", "type": "text", "text": "担架が来た。鳴海さんがソファから担架に移された。移動の間に鳴海さんの目が一度だけ開いた。薄い琥珀色。水で割ったような色。「大丈夫です……」と口が動いたが声になっていなかった。唇の形だけの「大丈夫」だった。"}, {"id": "ch11-s03-p007", "type": "text", "text": "風祭さんは担架の横を歩いた。鳴海さんの手に触れたまま。栗色のショートヘアが楽屋の灯りから廊下の残響灯の青白い光に変わり、色の見え方が変わった。翳りが深くなった。"}, {"id": "ch11-s03-p008", "type": "text", "text": "担架が廊下の角を曲がって消えた。"}, {"id": "ch11-s03-p009", "type": "text", "text": "残った。"}, {"id": "ch11-s03-p010", "type": "text", "text": "廊下の残響灯が等間隔で壁面を照らしている。石壁の事務的な構造。響弦館の裏手は表の木造りの温かさがない。冷たい光と石の匂い。足音が消えた後の静かさは、管理室の静かさとも記録室の静かさとも違った。何かが起きた後の静かさだった。"}, {"id": "ch11-s03-p011", "type": "text", "text": "立っていた。"}, {"id": "ch11-s03-p012", "type": "text", "text": "楽屋の前の廊下に立っていた。公演後点検の業務はまだ終わっていない。天吊り拡声器の出力ログを回収していない。壁面拡声器の目視確認もしていない。足は機材室に向かうべきだった。"}, {"id": "ch11-s03-p013", "type": "text", "text": "向かわなかった。"}, {"id": "ch11-s03-p014", "type": "text", "text": "鳩尾の上にあるものが重かった。歌声の余韻と膝折りと四つの症状と七割の笑顔が全部沈んでいる場所。そこに、風祭さんの涙と鳴海さんの「ごめんね」がさらに積もっている。重い。足が業務に向かう前に、体が止まっている。止まっていることの理由を探す余裕もなかった。"}, {"id": "ch11-s03-p015", "type": "text", "text": "足音が聞こえた。"}, {"id": "ch11-s03-p016", "type": "text", "text": "小さい足音。スニーカーの底が石の床を踏む音。等間隔ではない。不規則で、途中で止まり、また始まる。"}, {"id": "ch11-s03-p017", "type": "text", "text": "廊下の角から風祭さんが戻ってきた。"}, {"id": "ch11-s03-p018", "type": "text", "text": "医務室に向かったはずだった。鳴海さんの担架の横を歩いていったはずだった。戻ってきている。栗色のショートヘアが残響灯の光を受けている。顔が見えた。"}, {"id": "ch11-s03-p019", "type": "text", "text": "涙の跡が頬にあった。乾いていない。目が赤い。楽屋で見た時と同じ——水が全部出てしまった後の赤さ。けれど目の色が違った。楽屋の時は水底の翡翠だった。今は水が引いている。水底ではなく、水が引いた後の石が見えている。据わった目。定まっている。"}, {"id": "ch11-s03-p020", "type": "text", "text": "俺を見ていた。"}, {"id": "ch11-s03-p021", "type": "text", "text": "廊下の真ん中に立っている俺を、風祭さんはまっすぐ見ていた。距離が縮まっていく。十歩。八歩。五歩。三歩。"}, {"id": "ch11-s03-p022", "type": "text", "text": "立ち止まった。"}, {"id": "ch11-s03-p023", "type": "text", "text": "三歩の距離。二ヶ月前の訓練棟前では四メートルだった。六月の昇降口では三メートル。今は三歩。近い。"}, {"id": "ch11-s03-p024", "type": "text", "text": "「朝霧さん」"}, {"id": "ch11-s03-p025", "type": "text", "text": "声がかすれていた。嗚咽の後の喉。風祭さんの声の段階——柔らかい声、硬い声、絞った声、芯が落ちた声、むき出しの手の声。今の声はどれにも当てはまらなかった。枯れた声だった。水が足りない声。泣きすぎた後の声。"}, {"id": "ch11-s03-p026", "type": "text", "text": "「少しだけ、聞いてほしいことがあるの」"}, {"id": "ch11-s03-p027", "type": "text", "text": "聞いてほしい。"}, {"id": "ch11-s03-p028", "type": "text", "text": "九月の訓練棟前では「ちょっといい？」だった。六月の昇降口でも「ちょっといい？」だった。同じ前置き。今日は違った。「聞いてほしい」。要件ではない。頼み。"}, {"id": "ch11-s03-p029", "type": "text", "text": "「はい」"}, {"id": "ch11-s03-p030", "type": "text", "text": "答えた。"}, {"id": "ch11-s03-p031", "type": "text", "text": "風祭さんの目が閉じた。三秒。息を吸った。長い吸気。二ヶ月前、訓練棟の前で見た「呼吸をやり直す」動作と同じだった。肩が上がり、下がった。けれど下がりきらなかった。肩がまだ高い位置にある。内側が閉じきれていない。"}, {"id": "ch11-s03-p032", "type": "text", "text": "目が開いた。赤い翡翠色。涙の跡が残っている頬。口が開いた。"}, {"id": "ch11-s03-p033", "type": "text", "text": "「ちーちゃんは」"}, {"id": "ch11-s03-p034", "type": "text", "text": "声が詰まった。一語目で詰まった。「ちーちゃん」の三文字で喉が塞がった。風祭さんの口元が強張った。次の言葉を形にしようとして、筋肉が拒んでいた。二年間口にしなかった言葉を、口が覚えていなかった。"}, {"id": "ch11-s03-p035", "type": "text", "text": "風祭さんの右手がミサンガに触れた。あの時と同じ動作。千歳との繋がりを確かめる手。親指がミサンガの編み目を往復した。"}, {"id": "ch11-s03-p036", "type": "text", "text": "「ちーちゃんは……歌うたびに、命を削ってるんです」"}, {"id": "ch11-s03-p037", "type": "text", "text": "声が裂けた。"}, {"id": "ch11-s03-p038", "type": "text", "text": "裂けた、というのは声の表面が破れたということだった。風祭さんの声には輪郭がある。高い声。はっきりした声。その輪郭が、今の一文で縦に裂けた。声の中身が剥き出しになった。中には二年分の重さが入っていた。"}, {"id": "ch11-s03-p039", "type": "text", "text": "命を削っている。"}, {"id": "ch11-s03-p040", "type": "text", "text": "言葉を聴いた。耳が受け取った。頭ではなく鳩尾の上がまず反応した。鳴海さんの歌声の余韻がまだ残っている場所。膝折りが沈んでいる場所。四つの症状が落ちた場所。そこに——「命を削っている」の六文字が、まっすぐ落ちた。"}, {"id": "ch11-s03-p041", "type": "text", "text": "保留していたものが繋がった。"}, {"id": "ch11-s03-p042", "type": "text", "text": "繋がりかけていた。楽屋で四つの症状を見た時に、保留にしなかった。棚に並べなかった。同じ場所に直接落としていた。その時はまだ線にならなかった。「体が何かを大量に失っている」という判断はあった。けれどその「何か」に名前がなかった。"}, {"id": "ch11-s03-p043", "type": "text", "text": "命。"}, {"id": "ch11-s03-p044", "type": "text", "text": "残響祭の膝折り。半秒。六月の首元を押さえる癖。六月の瞳の色の薄れ。体育祭の体力系競技の欠席。九月の食欲低下。さっきの公演での両膝と両手が床につく三秒。四症状の同時出現。腕の細さ。声の薄さ。七割で止まった笑顔。"}, {"id": "ch11-s03-p045", "type": "text", "text": "全部が同じ一語に向かって並んでいた。命を削っている。歌うたびに。"}, {"id": "ch11-s03-p046", "type": "text", "text": "黙っていた。"}, {"id": "ch11-s03-p047", "type": "text", "text": "風祭さんを見ていた。風祭さんは俺を見ていなかった。視線が足元に落ちていた。石の床の、残響灯の光が白く反射している一点を見つめていた。"}, {"id": "ch11-s03-p048", "type": "text", "text": "「ちーちゃんのお母さん……鳴海美弦さん。ちーちゃんと同じ力を持ってたの」"}, {"id": "ch11-s03-p049", "type": "text", "text": "声が低かった。訓練棟の前で聞いた「芯が落ちた」声だった。けれど芯の落ち方がさらに深い。喉の奥ではなく、腹の底から出ている。二年間溜めた声。"}, {"id": "ch11-s03-p050", "type": "text", "text": "「ちーちゃんが十歳の時に死んだ。公式には病死。でも……」"}, {"id": "ch11-s03-p051", "type": "text", "text": "風祭さんの右手がミサンガを握った。触れるのではなく、握った。編み目が指の間に食い込んでいる。"}, {"id": "ch11-s03-p052", "type": "text", "text": "「歌いすぎたの。共鳴のたびに体が消耗して、最後は……」"}, {"id": "ch11-s03-p053", "type": "text", "text": "声が途切れた。途切れたまま、三秒。風祭さんの肩が小さく震えた。泣いているのではなかった。泣く余力が残っていなかった。楽屋で全部出し切った後の、乾いた震え。"}, {"id": "ch11-s03-p054", "type": "text", "text": "「あたしが気づいたのは二年前」"}, {"id": "ch11-s03-p055", "type": "text", "text": "声が戻った。かすれたまま。"}, {"id": "ch11-s03-p056", "type": "text", "text": "「ちーちゃんが歌うたびに、少しずつ元気がなくなっていくの。最初は気のせいだと思った。ちーちゃん、もともと体が強い方じゃないし。でも……訓練の後にふらっとする回数が増えて。食べる量が減って。時々、歌った後に首のあたりを……」"}, {"id": "ch11-s03-p057", "type": "text", "text": "風祭さんの右手が自分の首元に触れた。鳴海さんの癖を再現していた。無意識の動作。二年間、何度も見てきた動作をそのまま体が覚えている。"}, {"id": "ch11-s03-p058", "type": "text", "text": "「鼻血」"}, {"id": "ch11-s03-p059", "type": "text", "text": "声が小さくなった。"}, {"id": "ch11-s03-p060", "type": "text", "text": "「練習の後に、こっそり鼻を押さえてるちーちゃんを見ちゃったの。教室の外の手洗い場で。水で洗い流してて。ティッシュが赤くなってて。ちーちゃん、あたしがいるのに気づいて——笑ったの。『鼻がむずむずしちゃって』って」"}, {"id": "ch11-s03-p061", "type": "text", "text": "風祭さんの声が、笑おうとした。千歳の声を真似ようとした。失敗した。声が途中で崩れた。笑いの形にならなかった。"}, {"id": "ch11-s03-p062", "type": "text", "text": "「大丈夫だよ、って。いつもの顔で。いつもの声で。嘘つくの下手なくせに」"}, {"id": "ch11-s03-p063", "type": "text", "text": "三度目だった。"}, {"id": "ch11-s03-p064", "type": "text", "text": "九月に二度。今日で三度目。「嘘つくの下手なくせに」。風祭さんの頭の中で何百回も繰り返された言葉。声に出すたびに同じ形。同じ語尾。声の末尾の震えの位置まで同じ。摩耗しきった言葉だった。何度使っても磨り減らない。"}, {"id": "ch11-s03-p065", "type": "text", "text": "「そこから調べたの。ちーちゃんのお母さんのこと。図書館の記録室にあった。古い新聞の縮刷版と、共鳴者の記録台帳。鳴海美弦、共鳴者、三十二歳で病死。それだけ。それだけしか書いてなかった」"}, {"id": "ch11-s03-p066", "type": "text", "text": "風祭さんの手が拳になった。"}, {"id": "ch11-s03-p067", "type": "text", "text": "「でも繋がったの。お母さんの死因と、ちーちゃんの鼻血と、訓練の後のふらつきと、瞳の色が薄くなるのと——全部。全部同じだったの。お母さんと同じことが、ちーちゃんに起きてるって」"}, {"id": "ch11-s03-p068", "type": "text", "text": "声が大きくなっていた。音量を制御できなくなっていた。風祭さんは情報を伝達しているのではなかった。堰が決壊していた。楽屋で千歳の崩壊を見て、決壊した堰から全部が流れ出ている。蓮に伝えることを選んだのではない。耐えきれなくなって溢れている。"}, {"id": "ch11-s03-p069", "type": "text", "text": "「二年間、誰にも言えなかった」"}, {"id": "ch11-s03-p070", "type": "text", "text": "声が落ちた。大きくなった声が急に小さくなった。"}, {"id": "ch11-s03-p071", "type": "text", "text": "「ちーちゃんには言えない。言ったらちーちゃんが歌えなくなる。ちーちゃんは歌いたいから歌ってるの。あたしにそれを止める権利なんかない。でも……でも歌うたびに命が削れてくの。見てるしかないの。笑ってるちーちゃんの横で、あたしだけが知ってて、笑うしかなくて」"}, {"id": "ch11-s03-p072", "type": "text", "text": "風祭さんの目から涙が落ちた。"}, {"id": "ch11-s03-p073", "type": "text", "text": "楽屋で全部出し切ったはずだった。出し切ったはずの涙がまた出ていた。底が抜けている。二年分の堰が壊れて、止め方がわからなくなっている。"}, {"id": "ch11-s03-p074", "type": "text", "text": "「霜月先生にも言えなかった。もし先生が知ったら、ちーちゃんの訓練を止めるかもしれない。止められたらちーちゃんは——」"}, {"id": "ch11-s03-p075", "type": "text", "text": "風祭さんの声が止まった。口が閉じかけて、また開き、閉じた。言葉の先にあるものが、声にならなかった。千歳から歌を取り上げることが何を意味するか。風祭さんはそれを二年間考え続けて、答えが出ないまま今日まで来ている。"}, {"id": "ch11-s03-p076", "type": "text", "text": "沈黙が五秒続いた。"}, {"id": "ch11-s03-p077", "type": "text", "text": "俺は動かなかった。遮らなかった。質問しなかった。"}, {"id": "ch11-s03-p078", "type": "text", "text": "記録室で篠宮さんが消滅者の記録を読んだ時と同じだった。話している人の言葉を、全部受け取る。途中で意見を挟まない。先に答えを出さない。相手が全て出し終わるまで待つ。"}, {"id": "ch11-s03-p079", "type": "text", "text": "風祭さんが顔を上げた。"}, {"id": "ch11-s03-p080", "type": "text", "text": "涙が顎から落ちていた。翡翠色の目が赤く腫れている。口元が歪んでいた。笑おうとしたのではなかった。泣き顔を作る余裕もなく、ただ表情の制御が外れていた。"}, {"id": "ch11-s03-p081", "type": "text", "text": "「あたしね」"}, {"id": "ch11-s03-p082", "type": "text", "text": "声が変わった。"}, {"id": "ch11-s03-p083", "type": "text", "text": "低くもなく高くもない。かすれている。けれど声の底に何かがある。風祭さんの声の段階のどれでもなかった。今まで聞いたことのない声。喉の奥に、何かの傷がある声だった。音の出処ではなく、声そのものの中に、ざらつきがある。飲み込んだガラスの欠片が喉の壁に引っかかったような。"}, {"id": "ch11-s03-p084", "type": "text", "text": "「あたしの声じゃ、ちーちゃんの代わりにはなれないの」"}, {"id": "ch11-s03-p085", "type": "text", "text": "静かだった。"}, {"id": "ch11-s03-p086", "type": "text", "text": "叫びではなかった。嗚咽でもなかった。静かな、平たい、乾いた声だった。二年間の結論を、諦めの形で口にしている。風祭さんの共鳴適性は低い。低いことは入学時からわかっていた。それでも訓練を続けた。千歳の傍にいるために。千歳の代わりになるために。"}, {"id": "ch11-s03-p087", "type": "text", "text": "「あたしの声じゃ」の一語の中に、声の傷があった。喉の奥にあるざらつき。訓練で無理をした声帯の痕跡。千歳の代わりになろうとして、自分の体を壊しかけた人間の声だった。"}, {"id": "ch11-s03-p088", "type": "text", "text": "風祭さんは黙った。"}, {"id": "ch11-s03-p089", "type": "text", "text": "言い終わった。全部出た。二年分の秘密と、千歳への感情と、自分の無力感が、響弦館の裏手の冷たい廊下に出し切られた。風祭さんの肩が小さく上下していた。呼吸が荒い。泣いた後の呼吸。走った後の呼吸に似ている。"}, {"id": "ch11-s03-p090", "type": "text", "text": "三歩の距離で、俺は立っていた。"}, {"id": "ch11-s03-p091", "type": "text", "text": "聴いた。全部聴いた。遮らなかった。"}, {"id": "ch11-s03-p092", "type": "text", "text": "鳩尾の上のものが形を変えていた。"}, {"id": "ch11-s03-p093", "type": "text", "text": "歌声の余韻と膝折りと四つの症状と七割の笑顔と「大丈夫」の嘘と「ごめんね、いろは」。その全部に、今、名前がついた。命を削っている。歌うたびに。二年間、風祭さんだけが知っていた。"}, {"id": "ch11-s03-p094", "type": "text", "text": "「知っていて歌わせていた」。"}, {"id": "ch11-s03-p095", "type": "text", "text": "その言葉がそこに落ちた。俺が作った言葉ではなかった。風祭さんの話を聴いている間に、体の芯で自然に組み上がった。知っていた。風祭さんは二年前から知っていた。学院の誰かも知っていたのかもしれない。知っていて、歌わせていた。"}, {"id": "ch11-s03-p096", "type": "text", "text": "そこにあるものが、名前を持ち始めていた。"}, {"id": "ch11-s03-p097", "type": "text", "text": "楽屋の入口で「名前がまだない」と思った。怒りなのか悲しみなのか焦りなのか。わからなかった。今、わかりかけている。わかりかけているものの形は——怒りに近かった。けれどまだ完成していなかった。誰に向いているのかがわからなかった。千歳に歌わせた人間に向いているのか。知っていて止められなかった風祭さんに向いているのか。何も知らなかった自分自身に向いているのか。"}, {"id": "ch11-s03-p098", "type": "text", "text": "向きが定まらない。定まらないまま、体の中心にある。重い。名前がつきかけているだけ、前より重い。"}, {"id": "ch11-s03-p099", "type": "text", "text": "風祭さんの呼吸が落ち着いてきた。"}, {"id": "ch11-s03-p100", "type": "text", "text": "肩の上下が小さくなった。目はまだ赤い。涙の跡が左右の頬を筋になって伝っている。乾きかけている。"}, {"id": "ch11-s03-p101", "type": "text", "text": "目が俺を見た。"}, {"id": "ch11-s03-p102", "type": "text", "text": "据わった目。水が引いた後の翡翠色。泣いた後の目は弱いはずだった。風祭さんの目は弱くなかった。泣き切った後に残る硬さがあった。全部出した人間の目だった。"}, {"id": "ch11-s03-p103", "type": "text", "text": "「……ごめんね。急に」"}, {"id": "ch11-s03-p104", "type": "text", "text": "声がかすれていた。"}, {"id": "ch11-s03-p105", "type": "text", "text": "「朝霧さんに言うつもりなかったの。今日まで、誰にも言うつもりなかった。でも……」"}, {"id": "ch11-s03-p106", "type": "text", "text": "風祭さんの視線が廊下の奥に向いた。鳴海さんが運ばれていった方向。"}, {"id": "ch11-s03-p107", "type": "text", "text": "「ちーちゃんの顔見たら、もう、だめだった」"}, {"id": "ch11-s03-p108", "type": "text", "text": "声が落ちた。"}, {"id": "ch11-s03-p109", "type": "text", "text": "「あたし一人じゃ、もう」"}, {"id": "ch11-s03-p110", "type": "text", "text": "文が完成しなかった。「もう」の先が出なかった。風祭さんの口が閉じた。唇が一本の線になった。言葉ではなく、歯を食いしばっている口。"}, {"id": "ch11-s03-p111", "type": "text", "text": "立っていた。"}, {"id": "ch11-s03-p112", "type": "text", "text": "三歩の距離。風祭さんの涙と、鳴海さんの命と、二年間の秘密が、響弦館の裏手の冷たい廊下に散乱している。拾い方がわからなかった。何を言えばいいのかがわからなかった。"}, {"id": "ch11-s03-p113", "type": "text", "text": "わかったのは一つだけだった。"}, {"id": "ch11-s03-p114", "type": "text", "text": "風祭さんが二年間一人で持っていたものを、今日、俺の前に出した。出したことの重さが、鳩尾の上にある。歌声が管を通したのと同じ場所に。涙が出たのと同じ場所に。保留にできなかった四つの症状と同じ場所に。"}, {"id": "ch11-s03-p115", "type": "text", "text": "全部が同じ場所に集まっている。"}, {"id": "ch11-s03-p116", "type": "text", "text": "鳴海さんの歌。鳴海さんの膝折り。鳴海さんの命。風祭さんの涙。風祭さんの二年間。名前がつきかけているもの。まだ完成していない怒り。"}, {"id": "ch11-s03-p117", "type": "text", "text": "俺は何を言えばいいのか、まだわからなかった。けれど風祭さんは答えを求めていなかった。答えを求めて話したのではなかった。溢れたのだった。耐えきれなくなって、溢れた。"}, {"id": "ch11-s03-p118", "type": "text", "text": "だから俺は何も言わなかった。"}, {"id": "ch11-s03-p119", "type": "text", "text": "風祭さんの目を見ていた。赤い翡翠色を見ていた。涙の跡が残っている頬を見ていた。声の中にあった傷を、覚えていた。"}, {"id": "ch11-s03-p120", "type": "text", "text": "廊下の残響灯が等間隔に白い。石壁が音を硬く返す。風祭さんの呼吸の音だけが聞こえていた。"}, {"id": "ch11-s03-p121", "type": "text", "text": "命を削っている。二年間、一人だった。あたしの声じゃ、代わりになれない。"}, {"id": "ch11-s03-p122", "type": "text", "text": "覚えておく。"}]}, {"chapter": 11, "chapterTitle": "歌と命の天秤", "scene": 4, "sceneTitle": "蓮の怒り", "wordCount": "約5,200字", "paragraphs": [{"id": "ch11-s04-p001", "type": "text", "text": "響弦館を出た。"}, {"id": "ch11-s04-p002", "type": "text", "text": "風祭さんの目を最後に見たのは、裏手の廊下の突き当たりだった。赤い翡翠色。涙の跡が乾きかけた頬。「……ごめんね」と言った声のかすれ。何も言えなかった俺に、風祭さんは「ありがとう」とも「もう大丈夫」とも言わなかった。俺が黙っていることを、受け入れていた。"}, {"id": "ch11-s04-p003", "type": "text", "text": "別れ際に風祭さんが一つだけ言った。"}, {"id": "ch11-s04-p004", "type": "text", "text": "「あたし、医務室に戻るね」"}, {"id": "ch11-s04-p005", "type": "text", "text": "それだけ。それだけ言って、背を向けた。スニーカーの足音が廊下の奥に遠ざかった。栗色の後ろ姿が残響灯の青白い光の中で小さくなり、角を曲がって消えた。"}, {"id": "ch11-s04-p006", "type": "text", "text": "立っていた。消えた後も少し立っていた。それから足が動いた。"}, {"id": "ch11-s04-p007", "type": "text", "text": "灯籠通りに出た。"}, {"id": "ch11-s04-p008", "type": "text", "text": "十一月の夕方。十五時を過ぎて響弦館を出たから、灯籠通りに入った頃には空が傾いていた。低い日差しが石畳の上に長い影を落としている。灯籠はまだ点灯していない。点灯は十八時。それまでの間は西日だけが通りを照らす。"}, {"id": "ch11-s04-p009", "type": "text", "text": "歩いていた。"}, {"id": "ch11-s04-p010", "type": "text", "text": "足が鐘鋳塔に向かっていた。業務のためではなかった。公演後点検の天吊り拡声器ログは回収していない。壁面拡声器の目視確認もしていない。業務が頭の中にあるのに、足が業務先ではなく鐘鋳塔に向いていた。"}, {"id": "ch11-s04-p011", "type": "text", "text": "風祭さんの言葉が鳩尾の上にある。命を削っている。歌うたびに。二年間、風祭さんだけが知っていた。——学院の誰かも知っていたのかもしれない。"}, {"id": "ch11-s04-p012", "type": "text", "text": "知っていたのかもしれない。"}, {"id": "ch11-s04-p013", "type": "text", "text": "その「かもしれない」が足を動かしていた。"}, {"id": "ch11-s04-p014", "type": "text", "text": "共鳴者の健康データは管理局が管理している。共鳴者候補生の訓練記録、体調記録、身体検査の数値。全て鐘鋳塔管理局の端末に入っている。七ヶ月の鐘守補佐の業務で、そのファイルの存在は知っていた。閲覧権限は俺にはない。研究区画の端末と、技師以上の承認が要る。"}, {"id": "ch11-s04-p015", "type": "text", "text": "霜月さんなら見られる。"}, {"id": "ch11-s04-p016", "type": "text", "text": "霜月さんなら、鳴海さんのデータに直接アクセスできる。"}, {"id": "ch11-s04-p017", "type": "text", "text": "灯籠通りの石畳の継ぎ目を靴底が拾う。等間隔。一歩ずつ。歩幅は普段と同じだった。速度も同じ。しかし普段の巡回と違って、周囲の景色が目に入らなかった。灯籠の列も、すれ違う学院生の顔も、通りの脇に並ぶ石壁も。胸の上の一点だけが視界の全てを占めていた。"}, {"id": "ch11-s04-p018", "type": "text", "text": "鐘鋳塔の入口に着いた。"}, {"id": "ch11-s04-p019", "type": "text", "text": "石造りの正面扉を開けた。一階の管理室の前を通り過ぎた。階段に入った。石段を上がる。一階から二階。二階から三階。先月、蝕域データの説明で同じ階段を上がった時は、霜月さんの呼び出しに応じた足だった。今日は呼び出されていない。自分の足で来ている。"}, {"id": "ch11-s04-p020", "type": "text", "text": "三階。研究区画の通路。残響灯が壁面で白に近い青白さを放っている。精密計器のための湿度管理された空気。乾いている。十一月の夕方の外気とは違う、鐘鋳塔の内部の冷えた空気。"}, {"id": "ch11-s04-p021", "type": "text", "text": "霜月さんの研究室の鉄扉の前に立った。"}, {"id": "ch11-s04-p022", "type": "text", "text": "閉まっていた。先月は開いていた。今日は閉まっている。呼び出しを受けていないから。"}, {"id": "ch11-s04-p023", "type": "text", "text": "鉄扉を三回叩いた。拳で。間隔を空けて。"}, {"id": "ch11-s04-p024", "type": "text", "text": "三秒。"}, {"id": "ch11-s04-p025", "type": "text", "text": "「入りなさい」"}, {"id": "ch11-s04-p026", "type": "text", "text": "声。業務の声。抑揚がない。確認だけの声。"}, {"id": "ch11-s04-p027", "type": "text", "text": "鉄扉を引いた。重い。鉄の摩擦音が通路に短く響いた。"}, {"id": "ch11-s04-p028", "type": "text", "text": "研究室の中。"}, {"id": "ch11-s04-p029", "type": "text", "text": "モニタが二台。一台は蝕域活動指数の折れ線グラフを映している。赤い線が先月から引き続き表示されたまま。十月の途中で途切れた赤い線の先に、新たな点が一つ追加されていた。さらに上がっている。もう一台のモニタは暗転していた。"}, {"id": "ch11-s04-p030", "type": "text", "text": "霜月さんが机の前に座っていた。白いロングコート。銀髪のハーフアップ。背筋が真っ直ぐ伸びた座り方。椅子の背もたれに背中がつかない。机の上には記録用紙とペン。ペンの蓋は今日は本体と繋がっていた。前回は外れていた。直したのだろう。"}, {"id": "ch11-s04-p031", "type": "text", "text": "紅茶のカップが机の右端にあった。湯気が出ていない。冷めている。飲みかけ。"}, {"id": "ch11-s04-p032", "type": "text", "text": "ラベンダーの瞳が俺を見た。正面から。"}, {"id": "ch11-s04-p033", "type": "text", "text": "「アポイントはないはずだが」"}, {"id": "ch11-s04-p034", "type": "text", "text": "「はい」"}, {"id": "ch11-s04-p035", "type": "text", "text": "「用件を」"}, {"id": "ch11-s04-p036", "type": "text", "text": "短い。主語がない。敬語がない。いつもの構造。けれど声のどこかに、先月のデータ報告の時とは違う硬さがあった。選抜公演の日にアポなしで部下が来ることに対する緊張か。あるいは、今日響弦館で何が起きたかを知っている硬さか。"}, {"id": "ch11-s04-p037", "type": "text", "text": "「鳴海さんの健康管理データを確認させてください」"}, {"id": "ch11-s04-p038", "type": "text", "text": "声が平らだった。自分で出した声が、自分の耳に聞こえた。業務の声。平らな声。しかし中身が業務ではなかった。"}, {"id": "ch11-s04-p039", "type": "text", "text": "霜月さんの目が動いた。"}, {"id": "ch11-s04-p040", "type": "text", "text": "目、だけが動いた。体は動かない。首も動かない。瞳の中の虹彩が、わずかに収縮した。光の加減ではない。深夜の点検であのピアスに「きれいですね」と言った時とも、先月のデータ報告での反応とも違った。もっと深い場所が反応した目だった。"}, {"id": "ch11-s04-p041", "type": "text", "text": "「理由は」"}, {"id": "ch11-s04-p042", "type": "text", "text": "「選抜公演後に鳴海さんが倒れました。そのことはご存知かと思います」"}, {"id": "ch11-s04-p043", "type": "text", "text": "「ああ。報告は受けている」"}, {"id": "ch11-s04-p044", "type": "text", "text": "声が短かった。報告は受けている。その四語の中に、何が含まれているのかがわからなかった。事実の確認だけなのか。それとも「報告」の中身が俺の知らない情報を含んでいるのか。"}, {"id": "ch11-s04-p045", "type": "text", "text": "「倒れ方が通常の体調不良ではないように見えました。共鳴者の訓練と身体への影響について、データを確認したいです」"}, {"id": "ch11-s04-p046", "type": "text", "text": "言った。言葉を選んでいた。風祭さんから聞いたことを直接言わなかった。「命を削っている」とは言わなかった。データを見て、自分で確認する。風祭さんの言葉を裏付けとして使わない。それが正しいと思った。"}, {"id": "ch11-s04-p047", "type": "text", "text": "霜月さんは五秒、黙っていた。"}, {"id": "ch11-s04-p048", "type": "text", "text": "五秒は長い。この人が五秒黙るのは、先月の研究室で声が止まった0.5秒よりもはるかに長い。0.5秒でも異例だった。五秒は沈黙ではなく判断だった。何かを計算している。データを出すか出さないかを。"}, {"id": "ch11-s04-p049", "type": "text", "text": "「座りなさい」"}, {"id": "ch11-s04-p050", "type": "text", "text": "短い。けれど声の質が変わった。業務の声から、もう一段低い声に。"}, {"id": "ch11-s04-p051", "type": "text", "text": "研究室の来客用の丸椅子に座った。金属製。冷たい。"}, {"id": "ch11-s04-p052", "type": "text", "text": "霜月さんの指が端末のキーボードに触れた。暗転していたモニタが点灯した。白い画面。管理局のデータベースのログイン画面。指が滑る。パスワード入力。画面が切り替わる。"}, {"id": "ch11-s04-p053", "type": "text", "text": "「共鳴者候補生 身体記録データベース」。"}, {"id": "ch11-s04-p054", "type": "text", "text": "霜月さんの指が検索フィールドに名前を打ち込んだ。「鳴海千歳」。エンター。"}, {"id": "ch11-s04-p055", "type": "text", "text": "画面が表示された。"}, {"id": "ch11-s04-p056", "type": "text", "text": "表形式のデータ。縦軸に日付。横軸に項目。体重、血圧、脈拍、血中残響濃度、共鳴後の身体負荷指数。それぞれの数値が月ごとに並んでいる。入学時——二年半前のデータから、今月まで。"}, {"id": "ch11-s04-p057", "type": "text", "text": "数字を読んだ。"}, {"id": "ch11-s04-p058", "type": "text", "text": "読み方はわかった。蝕域のデータと同じだ。数値と日付が並んでいれば、傾向は読める。七ヶ月の業務で覚えた。"}, {"id": "ch11-s04-p059", "type": "text", "text": "体重。二年半前の数値から、右に向かって微減している。月ごとの変化量は小さい。0.3キロ。0.5キロ。一つ一つは誤差の範囲に見える。けれど全体を通して見ると、右肩下がりだった。南端蝕域活動指数のグラフを裏返したように。じわじわと、しかし確実に。"}, {"id": "ch11-s04-p060", "type": "text", "text": "血中残響濃度。この項目の意味はマニュアルに載っていなかった。しかし「残響」の文字がある以上、共鳴に関わる数値だ。数値が右肩上がりだった。二年半で、入学時の1.8倍。"}, {"id": "ch11-s04-p061", "type": "text", "text": "身体負荷指数。共鳴後の測定値。入学時は「12」。直近は「47」。"}, {"id": "ch11-s04-p062", "type": "text", "text": "「……この数値は」"}, {"id": "ch11-s04-p063", "type": "text", "text": "霜月さんの声が小さかった。"}, {"id": "ch11-s04-p064", "type": "text", "text": "俺に向けた声ではなかった。先月漏れた「また始まる」と同じ——口から零れたもの。中に在ったものが外に出た声。「この数値は」の先を、霜月さんは言わなかった。言わなかったのではない。言う前に口を閉じた。"}, {"id": "ch11-s04-p065", "type": "text", "text": "霜月さんの瞳がモニタから動かない。ラベンダーの瞳に白い画面の光が反射している。数字の列を見ている。俺も見ている。同じ数字を見ている。"}, {"id": "ch11-s04-p066", "type": "text", "text": "身体負荷指数47。入学時の四倍近い。蝕域の17パーセント増加を「±3パーセントの通常変動とは桁が違う」と言った時と同じ構造。入学時の数値を基準にすれば、この推移は——"}, {"id": "ch11-s04-p067", "type": "text", "text": "「霜月さん」"}, {"id": "ch11-s04-p068", "type": "text", "text": "声が出た。自分の声が聞こえた。平らではなかった。平らに出そうとして、出なかった。"}, {"id": "ch11-s04-p069", "type": "text", "text": "「これは、何を意味するんですか」"}, {"id": "ch11-s04-p070", "type": "text", "text": "霜月さんの目がモニタから離れた。俺を見た。正面から。"}, {"id": "ch11-s04-p071", "type": "text", "text": "目の中のラベンダーが、いつもの硬さを保っていた。鉱石の断面。光を反射するが、奥が見えない。いつもと同じ目——のはずだった。しかし硬さの一枚下にある層が、先月の時よりもはっきり浮いていた。あの時は一瞬浮いて沈んだ。今は浮いたまま、沈みきれない。"}, {"id": "ch11-s04-p072", "type": "text", "text": "「共鳴行為が身体に不可逆の負荷を与えている。データ上の結論はそれだ」"}, {"id": "ch11-s04-p073", "type": "text", "text": "声が平らだった。業務の声。データを報告する声。けれど「不可逆」の四音節を発した時、唇の動きがわずかに遅れた。舌が一瞬止まった。聞き取れない程度の短さ。しかし俺は聞いた。"}, {"id": "ch11-s04-p074", "type": "text", "text": "「不可逆、というのは」"}, {"id": "ch11-s04-p075", "type": "text", "text": "「元に戻らない、という意味だ」"}, {"id": "ch11-s04-p076", "type": "text", "text": "知っている。言葉の意味は知っている。聞きたかったのはそこではなかった。"}, {"id": "ch11-s04-p077", "type": "text", "text": "「共鳴のたびに、体が——」"}, {"id": "ch11-s04-p078", "type": "text", "text": "「消耗する。再生しない分だけ、蓄積する。負荷指数がこの傾きで推移すれば、数年以内に——」"}, {"id": "ch11-s04-p079", "type": "text", "text": "霜月さんの声が止まった。"}, {"id": "ch11-s04-p080", "type": "text", "text": "先月止まった0.5秒とは違う。今回は声が止まった位置が違った。先月は文の途中で止まった。今回は「数年以内に」の後で止まった。「数年以内に」何が起きるか。その先の言葉を、霜月さんは出さなかった。"}, {"id": "ch11-s04-p081", "type": "text", "text": "数年以内に。"}, {"id": "ch11-s04-p082", "type": "text", "text": "鳩尾の上が重くなった。「命を削っている」。風祭さんの声が繰り返している。風祭さんの言葉は感情だった。データではなかった。今、モニタの上に並んでいるのはデータだった。感情ではなかった。数字だった。数字が同じことを言っている。"}, {"id": "ch11-s04-p083", "type": "text", "text": "体重が減り続けている。残響濃度が上がり続けている。身体負荷が四倍になっている。数年以内に——。"}, {"id": "ch11-s04-p084", "type": "text", "text": "「このデータは、管理局の上層に報告されていますか」"}, {"id": "ch11-s04-p085", "type": "text", "text": "声が低かった。自分の声が低くなっていることに気づいた。意図していなかった。体の芯にあるものが喉に上がってきて、声の位置を変えていた。"}, {"id": "ch11-s04-p086", "type": "text", "text": "霜月さんが俺を見ていた。"}, {"id": "ch11-s04-p087", "type": "text", "text": "三秒。"}, {"id": "ch11-s04-p088", "type": "text", "text": "「管理局の上層は、このことを知っている」"}, {"id": "ch11-s04-p089", "type": "text", "text": "声が変わった。"}, {"id": "ch11-s04-p090", "type": "text", "text": "霜月さんの声が変わった。業務の声ではなかった。平らでもなかった。低かった。低い上に、硬かった。硬い声。しかし硬さの種類が違う。いつもの氷のような硬さではなく、力を込めて固めた硬さ。何かを押さえつけている硬さ。"}, {"id": "ch11-s04-p091", "type": "text", "text": "「知っている」。"}, {"id": "ch11-s04-p092", "type": "text", "text": "知っている。"}, {"id": "ch11-s04-p093", "type": "text", "text": "管理局の上層は。このことを。知っている。"}, {"id": "ch11-s04-p094", "type": "text", "text": "知っていて——"}, {"id": "ch11-s04-p095", "type": "text", "text": "鳩尾の上で、言葉が完成した。"}, {"id": "ch11-s04-p096", "type": "text", "text": "さっきの廊下で形を取りかけていた。誰に向いているかわからなかった。千歳に歌わせた人間に向いているのか。止められなかった風祭さんに向いているのか。何も知らなかった自分自身に向いているのか。定まらなかった。"}, {"id": "ch11-s04-p097", "type": "text", "text": "定まった。"}, {"id": "ch11-s04-p098", "type": "text", "text": "千歳に歌わせた人間ではなかった。風祭さんでもなかった。俺自身でもなかった。知っていて、止めなかった構造に向いていた。データがあり、数値があり、「数年以内に」の先を計算できる人間がいて、それでも歌わせ続けている。その判断を下した場所。その判断を黙認している仕組み。"}, {"id": "ch11-s04-p099", "type": "text", "text": "「知っていて、歌わせていたんですか」"}, {"id": "ch11-s04-p100", "type": "text", "text": "声が出た。"}, {"id": "ch11-s04-p101", "type": "text", "text": "低かった。自分の声がこんなに低くなることを知らなかった。喉の浅い場所から出る声ではなかった。鳩尾の上——七ヶ月間、鳴海さんの歌声と膝折りと四つの症状が沈んでいた場所——から直接出ている声だった。"}, {"id": "ch11-s04-p102", "type": "text", "text": "霜月さんが目を閉じた。"}, {"id": "ch11-s04-p103", "type": "text", "text": "この人が目を閉じるところを、俺は初めて見た。深夜の点検の時も、先月のデータ報告の時も、目を閉じなかった。ラベンダーの瞳は常に開いていた。データを見る目。計器を見る目。人の目を真っ直ぐ見る目。その目が閉じた。"}, {"id": "ch11-s04-p104", "type": "text", "text": "二秒。"}, {"id": "ch11-s04-p105", "type": "text", "text": "目が開いた。"}, {"id": "ch11-s04-p106", "type": "text", "text": "開いた目は、さっきまでと違った。硬さの一枚下にあった層が、表面に出ていた。沈めていたものが浮き上がっている。何の感情かはわからなかった。わからなかったが、俺は一つだけ知っていることがあった。"}, {"id": "ch11-s04-p107", "type": "text", "text": "先月「また始まる」が漏れた時と同じ層だった。"}, {"id": "ch11-s04-p108", "type": "text", "text": "五年前に何かがあった人間の目だった。"}, {"id": "ch11-s04-p109", "type": "text", "text": "「……朝霧」"}, {"id": "ch11-s04-p110", "type": "text", "text": "霜月さんの声が、小さかった。"}, {"id": "ch11-s04-p111", "type": "text", "text": "「私は答えなければならないか」"}, {"id": "ch11-s04-p112", "type": "text", "text": "問いだった。俺に対する問い。しかし同時に、自分自身に対する問いに聞こえた。答えなければならないか。データを持っている人間は、知っている人間は、声を上げなければならないか。"}, {"id": "ch11-s04-p113", "type": "text", "text": "「はい」"}, {"id": "ch11-s04-p114", "type": "text", "text": "答えた。声が低いまま。同じ場所から出ている声。"}, {"id": "ch11-s04-p115", "type": "text", "text": "霜月さんの唇が動いた。水平の線が、わずかに——歪んだ。歪みの方向がわからなかった。笑ったのではない。泣いたのでもない。五年間水平に保っていた線が、一瞬だけ形を崩した。"}, {"id": "ch11-s04-p116", "type": "text", "text": "「上層は知っている。共鳴者の身体消耗については定期報告に含まれている。負荷指数の推移も。数値が安全域を超えつつあることも。知った上で、鳴海の共鳴訓練スケジュールを減らしていない」"}, {"id": "ch11-s04-p117", "type": "text", "text": "声が硬かった。一語一語に刃物のような正確さがあった。怒りのトリガー——権力者が真実を隠蔽すること。「上の判断だ」で済ませること。この人の中でも、同じものが動いている。"}, {"id": "ch11-s04-p118", "type": "text", "text": "「島の防衛には共鳴者の力が不可欠だ。鳴海の代替となる共鳴者はいない。一人の共鳴者の身体消耗と、島全体の安全。上層はその天秤を、島の安全に傾けている」"}, {"id": "ch11-s04-p119", "type": "text", "text": "天秤。"}, {"id": "ch11-s04-p120", "type": "text", "text": "「五年前と同じだ」"}, {"id": "ch11-s04-p121", "type": "text", "text": "霜月さんの声が震えた。"}, {"id": "ch11-s04-p122", "type": "text", "text": "震えた。この人の声が震えるのを聞いたのは初めてだった。先月は声が止まった。今日は震えた。止まるよりも深い場所からの反応だった。"}, {"id": "ch11-s04-p123", "type": "text", "text": "「外円区の集落にも天秤があった。避難のコストと、集落の安全。上層はコストに傾けた。データがあった。警報を出す根拠があった。私が出した。握り潰された」"}, {"id": "ch11-s04-p124", "type": "text", "text": "声は低いまま。震えは一瞬で止まった。止めたのだ。意思で止めた。けれど止めた痕跡が声の表面に残っていた。薄い亀裂のように。"}, {"id": "ch11-s04-p125", "type": "text", "text": "「今、同じことが起きている。鳴海のデータがある。数値がある。そしてまた——」"}, {"id": "ch11-s04-p126", "type": "text", "text": "言葉が途切れた。霜月さんの視線がモニタに戻った。白い画面。数字の列。鳴海千歳の身体負荷指数。47。"}, {"id": "ch11-s04-p127", "type": "text", "text": "俺はモニタを見ていなかった。"}, {"id": "ch11-s04-p128", "type": "text", "text": "霜月さんを見ていた。"}, {"id": "ch11-s04-p129", "type": "text", "text": "白いコートの肩の線。背筋は真っ直ぐ。姿勢は完璧。けれど完璧な姿勢の内側で、何かが軋んでいた。ペンの蓋が外れていた日と同じだ。管理されているはずの場所から、五年分の重さが滲み出ている。"}, {"id": "ch11-s04-p130", "type": "text", "text": "鳩尾の上が、熱かった。"}, {"id": "ch11-s04-p131", "type": "text", "text": "熱い。"}, {"id": "ch11-s04-p132", "type": "text", "text": "そこが熱かった。七ヶ月間、ここに何かが積もっていた。鳴海さんの歌声。膝折り。四つの症状。風祭さんの涙。二年間の秘密。保留にしたものと、保留にできなかったもの。全部が同じ場所にあった。積もっていた。冷たい重さだった。"}, {"id": "ch11-s04-p133", "type": "text", "text": "今、それが熱に変わっている。"}, {"id": "ch11-s04-p134", "type": "text", "text": "名前がわかった。"}, {"id": "ch11-s04-p135", "type": "text", "text": "怒りだった。"}, {"id": "ch11-s04-p136", "type": "text", "text": "これは怒りだ。"}, {"id": "ch11-s04-p137", "type": "text", "text": "さっき「怒りに近い」と思った。近かった。しかしまだ完成していなかった。誰に向いているかがわからなかった。今、わかった。向いている先がわかった。鳴海さんの命を数値で把握しながら、天秤の片方に載せて、もう片方に島の安全を載せて、重い方を選んだ構造。その構造に向いている。"}, {"id": "ch11-s04-p138", "type": "text", "text": "体が反応していた。声が低くなった。鳩尾が熱い。拳が——拳が、いつの間にか握られていた。膝の上で。右手。左手。両方。指の関節が白くなっている。自分で握ったのに、握ったことに今気づいた。"}, {"id": "ch11-s04-p139", "type": "text", "text": "驚いた。"}, {"id": "ch11-s04-p140", "type": "text", "text": "自分の体に驚いていた。声が低くなった。拳が握られた。体の芯が熱い。これは観察ではなかった。記録ではなかった。保留ではなかった。俺のパターンは観察して記録して保留する。そのパターンが壊れている。保留にできない。棚に並べられない。そこにあるものが棚の上ではなく俺の中を直接通っている。"}, {"id": "ch11-s04-p141", "type": "text", "text": "模倣ではなかった。"}, {"id": "ch11-s04-p142", "type": "text", "text": "これまで自分の感情を疑っていた。鳴海さんの歌声に涙が出た時、あれは本物だったのか模倣だったのかわからなかった。風祭さんの声を聴いて胸の奥が重くなった時、それが本当の悲しみなのか、悲しむべき場面だから体がそう反応しただけなのか、区別がつかなかった。"}, {"id": "ch11-s04-p143", "type": "text", "text": "今は区別がつく。"}, {"id": "ch11-s04-p144", "type": "text", "text": "これは模倣ではない。声が低くなったのは演技ではない。拳を握ったのは反射ではない。鳩尾が熱いのは、鳴海さんの命が天秤に載せられたことに対する、俺自身の反応だった。"}, {"id": "ch11-s04-p145", "type": "text", "text": "怒っている。"}, {"id": "ch11-s04-p146", "type": "text", "text": "俺は怒っている。"}, {"id": "ch11-s04-p147", "type": "text", "text": "霜月さんが無言で俺を見ていた。ラベンダーの瞳。硬さの一枚下の層が表面に出たままの目。何を見ているのかわからなかった。俺の顔を見ているのか。俺の拳を見ているのか。俺の低い声の残響を、まだ耳の中で聞いているのか。"}, {"id": "ch11-s04-p148", "type": "text", "text": "研究室は静かだった。モニタの微かな駆動音と、残響灯の低い振動だけが空気を満たしている。夕方の光は窓から入らなかった。鐘鋳塔の三階の窓は北向きで、十一月の夕日は届かない。白い光と、モニタの光だけの部屋。その中に俺と霜月さんがいる。"}, {"id": "ch11-s04-p149", "type": "text", "text": "拳を見下ろした。"}, {"id": "ch11-s04-p150", "type": "text", "text": "白い関節。自分の手だった。この手は歯車を点検する手だった。レンチを握る手だった。共鳴管の接合部を増し締めする手だった。記録する手だった。その手が、初めて怒りのために握られている。"}, {"id": "ch11-s04-p151", "type": "text", "text": "霜月さんは何も言わなかった。"}, {"id": "ch11-s04-p152", "type": "text", "text": "俺の怒りに対して、何も言わなかった。「感情論は時間の無駄です」とは言わなかった。「データを示しなさい」とも言わなかった。ただ、黙って、俺を見ていた。"}, {"id": "ch11-s04-p153", "type": "text", "text": "その沈黙の中に、何かがあった。"}, {"id": "ch11-s04-p154", "type": "text", "text": "否定していない。俺の怒りを否定していない。「冷静になりなさい」も「業務と関係ない」も「権限外だ」も言わない。この人は——。"}, {"id": "ch11-s04-p155", "type": "text", "text": "わからなかった。霜月さんが何を考えているのかは、わからなかった。いつもわからない。氷の表面は光を反射する。奥が見えない。けれど今日、反射の奥にもう一層見えた。沈黙が否定ではないこと。目を閉じて、開いたこと。声が震えて、止めたこと。"}, {"id": "ch11-s04-p156", "type": "text", "text": "「五年前と同じだ」と言った霜月さんの声を覚えている。"}, {"id": "ch11-s04-p157", "type": "text", "text": "覚えておく。"}, {"id": "ch11-s04-p158", "type": "text", "text": "鳴海さんの身体負荷指数47。体重の微減。残響濃度の1.8倍。「数年以内に」の先を言わなかった霜月さんの口。管理局の上層は知っている。天秤。五年前と同じ構造。"}, {"id": "ch11-s04-p159", "type": "text", "text": "そして——あの熱。"}, {"id": "ch11-s04-p160", "type": "text", "text": "これは怒りだった。模倣ではなかった。俺の中で、初めて、自分のものだと言える感情が完成した場所。ここだった。"}]}, {"chapter": 11, "chapterTitle": "歌と命の天秤", "scene": 5, "sceneTitle": "アナザービュー：いろはの祈り", "wordCount": "約4,000字", "paragraphs": [{"id": "ch11-s05-p001", "type": "text", "text": "※アナザービュー：風祭いろは視点"}, {"id": "ch11-s05-p002", "type": "divider", "text": "---"}, {"id": "ch11-s05-p003", "type": "text", "text": "ちーちゃんの声が、響弦館を満たしている。"}, {"id": "ch11-s05-p004", "type": "text", "text": "あたしはいつもの場所にいる。袖幕の影。ステージの左端から三歩奥、照明が届かない暗がり。ここに立つのは何度目だろう。数えるのはやめた。数えたら、きっと怖くなるから。"}, {"id": "ch11-s05-p005", "type": "text", "text": "腕を組む。"}, {"id": "ch11-s05-p006", "type": "text", "text": "祈っているんじゃない。手が震えるから、こうしないと止まらない。"}, {"id": "ch11-s05-p007", "type": "text", "text": "ちーちゃんの歌声が上がっていく。高く、高く、もっと高く。客席のどこかで誰かが息を止めたのが空気の揺れでわかる。みんなそうなる。ちーちゃんが本気で歌い始めると、響弦館の空気が変わる。空気じゃない——空間が、歌のためだけのものになる。あたしはこの声が世界で一番好き。八歳の時から変わらない。ちーちゃんの声だけは、あたしの中の何もかもを黙らせてくれる。"}, {"id": "ch11-s05-p008", "type": "text", "text": "好き。"}, {"id": "ch11-s05-p009", "type": "text", "text": "この声が好き。この声を出すちーちゃんが好き。好きで、好きで——"}, {"id": "ch11-s05-p010", "type": "text", "text": "怖い。"}, {"id": "ch11-s05-p011", "type": "text", "text": "ちーちゃんの声が美しくなるたびに、あたしは怖くなる。それはあたしだけが知っている恐怖で、客席の誰にも、ステージの上の千歳にも、共有できない種類のもの。二年前、あたしはあの日から怖いまま生きている。"}, {"id": "ch11-s05-p012", "type": "text", "text": "あの日。"}, {"id": "ch11-s05-p013", "type": "text", "text": "リハーサル室で、ちーちゃんの鼻から血が流れた。ちーちゃんは笑って「よくあることだから」と言った。嘘だった。よくあることなんかじゃない。あたしは知ってしまった。調べた。夜中に図書館の閉架から古い文献を引っ張り出して、残響灯の下で何度も何度も読んだ。共鳴。過負荷。身体侵食。千歳の母親——あの人も、歌っていた。歌って、歌って、死んだ。"}, {"id": "ch11-s05-p014", "type": "text", "text": "同じだ。ちーちゃんは、お母さんと同じ道を歩いている。"}, {"id": "ch11-s05-p015", "type": "text", "text": "歌声が最高音に達する。"}, {"id": "ch11-s05-p016", "type": "text", "text": "響弦館が震える。あたしの骨が震える。客席から拍手が——いや、まだ曲の途中。それなのに拍手が起きかけている。それくらい、今日のちーちゃんの声は凄い。凄くて、綺麗で、残酷だ。"}, {"id": "ch11-s05-p017", "type": "text", "text": "あたしの喉が疼く。"}, {"id": "ch11-s05-p018", "type": "text", "text": "三ヶ月前、無理な発声練習で声帯を傷めた。医者には「このままだと声帯結節になる」と言われた。知ってる。知っていてやめられない。あたしがちーちゃんの代わりに歌えるようになれば——あたしの共鳴適性が上がれば——ちーちゃんは歌わなくていい。ステージに立たなくていい。命を削らなくていい。"}, {"id": "ch11-s05-p019", "type": "text", "text": "でも。"}, {"id": "ch11-s05-p020", "type": "text", "text": "あたしの適性は低い。どんなに練習しても、声帯を壊しかけても、ちーちゃんには届かない。届かないことはわかっている。わかっていて、やめられないのは——やめたら、あたしがちーちゃんのためにできることが本当にゼロになるから。"}, {"id": "ch11-s05-p021", "type": "text", "text": "ゼロは、嫌だ。"}, {"id": "ch11-s05-p022", "type": "text", "text": "歌声が揺れた。"}, {"id": "ch11-s05-p023", "type": "text", "text": "一瞬だった。客席の誰にもわからない程度の、ほんの微かな揺れ。でもあたしにはわかる。二年間、この場所で聴いてきた。ちーちゃんの声の揺れ方で、身体のどこに負荷がかかっているか、あたしにはわかる。"}, {"id": "ch11-s05-p024", "type": "text", "text": "右手の指が、左腕の内側に食い込む。爪が肌に跡を残す。"}, {"id": "ch11-s05-p025", "type": "text", "text": "やめて。お願いだからやめて。もう十分。みんなちーちゃんの歌に感動してる。もう十分だから——"}, {"id": "ch11-s05-p026", "type": "text", "text": "歌が続く。"}, {"id": "ch11-s05-p027", "type": "text", "text": "ちーちゃんは止まらない。止まれないんだ。あの子は歌い始めたら最後まで歌い切る。お母さんがそうだったように。歌に取り憑かれているのか、歌に愛されているのか、あたしにはもうわからない。"}, {"id": "ch11-s05-p028", "type": "text", "text": "あたしは袖幕の影で、唇を噛んだ。"}, {"id": "ch11-s05-p029", "type": "text", "text": "歌が終盤に入る。ちーちゃんの声が響弦館の天井まで昇っていく。客席はもう完全に呑まれている。誰も動かない。誰も息をしない。"}, {"id": "ch11-s05-p030", "type": "text", "text": "そしてあたしだけが見ている。"}, {"id": "ch11-s05-p031", "type": "text", "text": "ちーちゃんの左膝が、ほんの少しだけ折れた。"}, {"id": "ch11-s05-p032", "type": "text", "text": "体が動いた。"}, {"id": "ch11-s05-p033", "type": "text", "text": "考えるより先に足が出ていた。一歩、二歩、三歩、四歩。走らない。膝を曲げない。速い歩き。二年間の反復が身体に染みている。ちーちゃんの左腕を取る。背中に手を回す。体温が高い。汗で制服が湿っている。客席からは——たぶん、何事もなかったように見えている。あたしとちーちゃんが並んで歩いているだけに見えている。"}, {"id": "ch11-s05-p034", "type": "text", "text": "そう見えるように、練習した。何度も。何度も。"}, {"id": "ch11-s05-p035", "type": "text", "text": "ちーちゃんの体重があたしにかかる。軽い。軽すぎる。最近ちゃんとご飯を食べてるのかな。聞きたい。聞けない。聞いても「食べてるよ」って笑うだけだから。"}, {"id": "ch11-s05-p036", "type": "text", "text": "ステージを降りる。照明の外に出る。"}, {"id": "ch11-s05-p037", "type": "text", "text": "ちーちゃんの顔が見える。"}, {"id": "ch11-s05-p038", "type": "text", "text": "蒼白。"}, {"id": "ch11-s05-p039", "type": "text", "text": "あたしの中で、二年分の何かが、音を立てて壊れた。"}, {"id": "ch11-s05-p040", "type": "break", "text": "◇"}, {"id": "ch11-s05-p041", "type": "text", "text": "楽屋のソファに千歳を横たえた時、あたしの手は震えていなかった。震える余裕がなかった。"}, {"id": "ch11-s05-p042", "type": "text", "text": "ちーちゃんの呼吸が浅い。顔色が白い。それだけじゃない——指先が小さく痙攣している。瞳の色が、普段より薄く見える。四つ全部。四つ全部が出ている。これは、今までで一番ひどい。"}, {"id": "ch11-s05-p043", "type": "text", "text": "「ちーちゃん」"}, {"id": "ch11-s05-p044", "type": "text", "text": "声が出なかった。出なかったのに、もう一度呼んだ。"}, {"id": "ch11-s05-p045", "type": "text", "text": "「ちーちゃん、ちーちゃん」"}, {"id": "ch11-s05-p046", "type": "text", "text": "膝をついた。ちーちゃんの頭を抱え上げて、あたしの胸に引き寄せた。ちーちゃんの髪があたしの頬に触れる。冷たい。こんなに冷たいのに、さっきまで歌っていた。笑っていた。客席の全員を幸せにしていた。"}, {"id": "ch11-s05-p047", "type": "text", "text": "「だから言ったでしょ、無理しないでって」"}, {"id": "ch11-s05-p048", "type": "text", "text": "声が裏返った。泣いている。あたし、泣いてる。いつから泣いてたんだろう。ステージの時はまだ泣いていなかった。楽屋に入った瞬間かもしれない。扉を閉めた瞬間かもしれない。わからない。"}, {"id": "ch11-s05-p049", "type": "text", "text": "二年分だ。"}, {"id": "ch11-s05-p050", "type": "text", "text": "二年間、あたしは泣くのを我慢してきた。ちーちゃんの前では泣かない。泣いたら、ちーちゃんが気にするから。ちーちゃんに「ごめんね」って言わせたくないから。あたしが泣くことで、ちーちゃんが歌うことに罪悪感を持ったら——それはあたしが一番嫌なことだから。"}, {"id": "ch11-s05-p051", "type": "text", "text": "でも、もう、駄目だった。"}, {"id": "ch11-s05-p052", "type": "text", "text": "ちーちゃんを抱きしめたまま、あたしは泣いた。声を殺せなかった。みっともない声で泣いた。鼻水も出た。ちーちゃんの制服の肩を濡らした。"}, {"id": "ch11-s05-p053", "type": "text", "text": "楽屋の扉が開いた。"}, {"id": "ch11-s05-p054", "type": "text", "text": "顔を上げた。涙でぼやけた視界の端に、人影が立っていた。——朝霧さん。あの人がそこにいた。あたしは追い出さなかった。追い出す気力もなかったし、追い出す理由もなかった。あの人は——あの人の目を見た時、あたしはわかった。この人は、わかろうとしている。"}, {"id": "ch11-s05-p055", "type": "text", "text": "それだけで十分だった。"}, {"id": "ch11-s05-p056", "type": "break", "text": "◇"}, {"id": "ch11-s05-p057", "type": "text", "text": "ちーちゃんが医務室に運ばれた後、あたしは朝霧さんに全部話した。"}, {"id": "ch11-s05-p058", "type": "text", "text": "なぜ話したのか、自分でもわからない。計画なんかなかった。ただ、ちーちゃんが崩れるのを見て、二年間必死に積み上げてきた壁が——あたしの中の壁が、一緒に崩れた。堰が壊れた。止められなかった。"}, {"id": "ch11-s05-p059", "type": "text", "text": "朝霧さんは全部聴いてくれた。"}, {"id": "ch11-s05-p060", "type": "text", "text": "遮らなかった。質問もしなかった。あたしが泣きながら、言葉がぐちゃぐちゃになりながら、ちーちゃんの秘密を——二年間誰にも言えなかった秘密を吐き出すのを、ただ黙って聴いていた。"}, {"id": "ch11-s05-p061", "type": "text", "text": "それが、ありがたかった。"}, {"id": "ch11-s05-p062", "type": "text", "text": "ありがたくて、悔しかった。"}, {"id": "ch11-s05-p063", "type": "text", "text": "あたしが二年間、一人で抱えて、一人で泣いて、一人で声帯を壊しかけて——それでもちーちゃんを守れなかったことを、この人は数時間で理解した。理解して、そして——"}, {"id": "ch11-s05-p064", "type": "text", "text": "怒っていた。"}, {"id": "ch11-s05-p065", "type": "text", "text": "朝霧さんの声が低くなった瞬間を、あたしは聞き逃さなかった。「知っていて歌わせていたんですか」。あの声。あれは、あたしには出せない声だった。あたしは二年間泣くことしかできなかった。怒れなかった。誰に怒ればいいのかわからなかった。ちーちゃんに？　歌に？　共鳴に？　あたし自身に？"}, {"id": "ch11-s05-p066", "type": "text", "text": "この人は——ちーちゃんのために、怒れる人だ。"}, {"id": "ch11-s05-p067", "type": "text", "text": "嫉妬した。"}, {"id": "ch11-s05-p068", "type": "text", "text": "あたしの中の、醜い部分が顔を出した。あたしが二年間かけてもできなかったことを、この人はたった数時間で——。ちーちゃんを守るのは、あたしの仕事なのに。あたしの、役割なのに。"}, {"id": "ch11-s05-p069", "type": "text", "text": "でも、同時に。"}, {"id": "ch11-s05-p070", "type": "text", "text": "安心した。"}, {"id": "ch11-s05-p071", "type": "text", "text": "あたし一人じゃなくなるかもしれない。ちーちゃんのために怒れる人が、もう一人いるかもしれない。それは——あたしが二年間、ずっと欲しかったものだ。"}, {"id": "ch11-s05-p072", "type": "text", "text": "医務室の扉の前で立ち止まる。"}, {"id": "ch11-s05-p073", "type": "text", "text": "扉の向こうにちーちゃんがいる。あたしはこの扉を開けて、いつもの顔をする。泣いた跡を隠して、笑って、「もう大丈夫？」って聞く。いつもそうしてきた。これからもそうする。"}, {"id": "ch11-s05-p074", "type": "text", "text": "でも今日は——あたしの他に、もう一人、ちーちゃんのことを知っている人がいる。"}, {"id": "ch11-s05-p075", "type": "text", "text": "あたしはそれを、嬉しいと思っていいのかどうか、まだわからない。"}, {"id": "ch11-s05-p076", "type": "text", "text": "深呼吸をした。喉の奥がざらついた。声帯の傷が痛む。"}, {"id": "ch11-s05-p077", "type": "text", "text": "扉に手をかけた。"}]}, {"chapter": 11, "chapterTitle": "歌と命の天秤", "scene": 6, "sceneTitle": "眠れない夜", "wordCount": "約5,200字", "paragraphs": [{"id": "ch11-s06-p001", "type": "text", "text": "天井を見ている。"}, {"id": "ch11-s06-p002", "type": "text", "text": "白い塗り壁。凹凸が裸電球の影を作っている。四月の最初の朝も、八月の夏の終わりの夜も、同じ天井を見ていた。天井は変わっていない。変わっていないものを見ている自分が、変わっている。"}, {"id": "ch11-s06-p003", "type": "text", "text": "ベッドに仰向けになっていた。補佐官舎の狭い部屋。窓は閉めている。十月の夜は冷える。裸電球は消していない。消そうとして手を伸ばしかけて、やめた。暗くしたくなかった。"}, {"id": "ch11-s06-p004", "type": "text", "text": "時計の針が二十三時を指していた。"}, {"id": "ch11-s06-p005", "type": "text", "text": "鐘鋳塔からここまで歩いた記憶がある。三階の研究室を出た。鉄扉の重い音が背中で鳴った。螺旋階段を降りた。一階の管理室の前を通り過ぎた。正面扉を開けた。灯籠通りを歩いた。灯籠の光が足元に落ちていた。補佐官舎の鍵を開けた。靴を脱いだ。着替えた。"}, {"id": "ch11-s06-p006", "type": "text", "text": "どれも覚えている。しかし体の中心にあるものの方が、移動の記憶より大きかった。歩いている間ずっと、鳩尾の上にあった。"}, {"id": "ch11-s06-p007", "type": "text", "text": "今もある。"}, {"id": "ch11-s06-p008", "type": "text", "text": "鳩尾の上に、熱がある。"}, {"id": "ch11-s06-p009", "type": "text", "text": "あの研究室を出てから六時間近く経っている。十七時過ぎに出た。今は二十三時。六時間。食事を取った。風呂に入った。歯を磨いた。点検記録帳を開いて、明日の項目を書きかけて、ペンを置いた。文字が書けなかった。手は動く。手は動くのに、ペン先が点検記録の枠線の中に留まれなかった。頭の中に枠線がなかった。"}, {"id": "ch11-s06-p010", "type": "text", "text": "寝間着に着替えてベッドに横になった。それが一時間前。目が閉じない。"}, {"id": "ch11-s06-p011", "type": "text", "text": "そこが、まだ熱い。"}, {"id": "ch11-s06-p012", "type": "text", "text": "六時間前と同じ温度で熱い。冷めていない。"}, {"id": "ch11-s06-p013", "type": "break", "text": "◇"}, {"id": "ch11-s06-p014", "type": "text", "text": "八月の夜。布団の中で夏を振り返った。あの夜は眠れた。五つの場所に散らばった夏の痕を確認して、分解しないまま受け取って、温かいと感じて、目を閉じた。"}, {"id": "ch11-s06-p015", "type": "text", "text": "今夜は違う。"}, {"id": "ch11-s06-p016", "type": "text", "text": "分解するしないの話ではない。体の中に在るものが一か所に固まっている。五か所に散らない。同じ場所に全部ある。重くない。重くないのに熱い。冷たい重さだったものが、熱に変わっている。"}, {"id": "ch11-s06-p017", "type": "text", "text": "あの研究室で変わった。"}, {"id": "ch11-s06-p018", "type": "text", "text": "モニタの白い画面。数字の列。鳴海千歳の名前が検索フィールドに表示されたまま。体重。残響濃度。身体負荷指数。数字は静かだった。数字はいつも静かだ。管理室の計器と同じで、数字は声を出さない。数字はただそこにある。"}, {"id": "ch11-s06-p019", "type": "text", "text": "数字がただそこにあることに、声が出た。"}, {"id": "ch11-s06-p020", "type": "text", "text": "「知っていて、歌わせていたんですか」。"}, {"id": "ch11-s06-p021", "type": "text", "text": "あれは俺の声だった。低かった。鳩尾から出ていた。"}, {"id": "ch11-s06-p022", "type": "text", "text": "そして今、同じ鳩尾が熱い。あの時の熱がまだ残っている。六時間。管理室の計器で六時間異常値が継続していれば経過観察ではなく対処に入る。そこの熱は六時間経っても下がっていない。"}, {"id": "ch11-s06-p023", "type": "text", "text": "怒りだった。"}, {"id": "ch11-s06-p024", "type": "text", "text": "あの研究室で、名前がついた。怒り。模倣ではなかった。声が低くなったことも、拳が握られたことも、体の芯が熱くなったことも。全部が観察ではなく記録でもなく保留でもなかった。パターンが壊れた。俺の中で七ヶ月間続いていた「観察して記録して保留する」というパターンが、壊れた。"}, {"id": "ch11-s06-p025", "type": "text", "text": "壊れた。"}, {"id": "ch11-s06-p026", "type": "text", "text": "そう確信した。あの場所では確信した。"}, {"id": "ch11-s06-p027", "type": "break", "text": "◇"}, {"id": "ch11-s06-p028", "type": "text", "text": "今、補佐官舎のベッドの上で、天井を見ている。裸電球の黄色い光の中で。"}, {"id": "ch11-s06-p029", "type": "text", "text": "疑いが来ている。"}, {"id": "ch11-s06-p030", "type": "text", "text": "夜の静けさは、疑いに適している。"}, {"id": "ch11-s06-p031", "type": "text", "text": "あの時は確信した。しかし確信したのは、その場面だったからではないか。数字があった。霜月さんの声があった。「五年前と同じだ」の震えがあった。拳が握られた。声が低くなった。全部が揃っていた。全部が揃っている場面で怒るのは当然ではないのか。"}, {"id": "ch11-s06-p032", "type": "text", "text": "怒るべき場面だから怒った。それは模倣ではないのか。"}, {"id": "ch11-s06-p033", "type": "text", "text": "天井の凹凸を見ている。影が動かない。裸電球は揺れていない。"}, {"id": "ch11-s06-p034", "type": "text", "text": "四月。鳴海さんの歌声を初めて聴いた時、鳩尾が緩んだ。きれいだと思った。涙が出そうで出なかった。管が詰まっていた。あれは——本物だったのか。きれいなものをきれいだと思うのは人間の反応として自然で、だから自分もそう反応しただけではなかったのか。"}, {"id": "ch11-s06-p035", "type": "text", "text": "五月。燈花が水をかけた。笑った。考える前に体が動いた。「蓮くん、今笑ってたよ」。燈花はそう言った。模倣ではなかった、と思った。あの時は思った。しかし、楽しい場面で笑うことは模倣と何が違うのか。"}, {"id": "ch11-s06-p036", "type": "text", "text": "七月。灯篭流し。名前を書けなかった灯篭を流した。燈花が泣いた。俺は「天城さん」と呼ぶことしかできなかった。あの時の胸の奥は重かった。重かったが、それは燈花の涙を見たから重かったのか、悲しい場面で重くなるのが人の体だから重かったのか。"}, {"id": "ch11-s06-p037", "type": "text", "text": "八月。篠宮さんが「ありがとうございます」と言った。ペンの音が止まった。耳がその声を探していた。あれは本物だったのか。"}, {"id": "ch11-s06-p038", "type": "text", "text": "十月。鐘に触れた。フラッシュバック。月明かりと歌声と果実の匂い。一秒にも満たない断片。あれは記憶だったのか、それとも体が作り出したものだったのか。"}, {"id": "ch11-s06-p039", "type": "text", "text": "全部、疑える。"}, {"id": "ch11-s06-p040", "type": "text", "text": "全部、「そう感じるべき場面だから感じただけではないか」と言える。七ヶ月間、俺はその疑いをずっと抱えていた。温かいと感じた。たぶん。おいしいと思った。たぶん。「たぶん」が取れた日もあった。取れたと思った日もあった。しかし夜になれば戻ってくる。"}, {"id": "ch11-s06-p041", "type": "text", "text": "今夜も戻ってきている。"}, {"id": "ch11-s06-p042", "type": "text", "text": "怒りを感じた。本物だった。模倣ではなかった。そう確信した。——確信したと感じているだけではないのか？"}, {"id": "ch11-s06-p043", "type": "text", "text": "天井の影を見ている。動かない影を見ている。"}, {"id": "ch11-s06-p044", "type": "break", "text": "◇"}, {"id": "ch11-s06-p045", "type": "text", "text": "体に聞いた。"}, {"id": "ch11-s06-p046", "type": "text", "text": "八月の夜もそうした。五つの場所に聞いた。あの時、体は答えなかった。「変わった」とも「変わっていない」とも言わなかった。ただ各部位が淡々と報告した。"}, {"id": "ch11-s06-p047", "type": "text", "text": "今夜は一か所だけに聞く。"}, {"id": "ch11-s06-p048", "type": "text", "text": "鳩尾の上。"}, {"id": "ch11-s06-p049", "type": "text", "text": "右手を服の上から当てた。薄い寝間着の布を通して、肋骨の下端の少し内側。ここ。ここに七ヶ月間、鳴海さんの歌声と膝折りと四つの症状が積もっていた。冷たい重さだった。沈殿していた。"}, {"id": "ch11-s06-p050", "type": "text", "text": "今は熱い。"}, {"id": "ch11-s06-p051", "type": "text", "text": "六時間経って熱い。食事をして、風呂に入って、歯を磨いて、点検記録を開いて閉じて、着替えて、ベッドに横になって一時間。生活の動作を全部こなした後に、まだ熱い。"}, {"id": "ch11-s06-p052", "type": "text", "text": "模倣は冷める。"}, {"id": "ch11-s06-p053", "type": "text", "text": "考えた。"}, {"id": "ch11-s06-p054", "type": "text", "text": "鳴海さんの歌を聴いて目の奥が熱くなった時、翌日にはその熱は引いていた。残響祭の夜の「楽しかった」は布団の中の温もりに混じって消えた。篠宮さんの「ありがとうございます」の後の耳の中の声は、翌朝には探さなくても大丈夫になっていた。感じた時は本物に思えて、時間が経つと薄れて、そうすると「あれは本物だったのか」と疑う余地が生まれる。"}, {"id": "ch11-s06-p055", "type": "text", "text": "今夜は薄れていない。"}, {"id": "ch11-s06-p056", "type": "text", "text": "六時間。一時間ごとに確認しているわけではないが、意識がいつもの場所に戻るたびにそこにある。温度が同じ。あの熱は、俺がベッドに横になっても、天井を見ても、疑いの中をくぐっても、消えない。"}, {"id": "ch11-s06-p057", "type": "text", "text": "模倣は消える。時間が経てば。場面が変われば。「そう感じるべき」がなくなれば。"}, {"id": "ch11-s06-p058", "type": "text", "text": "あの研究室を出た。灯籠通りを歩いた。補佐官舎に帰った。場面はとうに変わっている。一人の部屋。深夜。誰も見ていない。怒るべき場面はもうどこにもない。"}, {"id": "ch11-s06-p059", "type": "text", "text": "それでもそこが熱い。"}, {"id": "ch11-s06-p060", "type": "text", "text": "だから——"}, {"id": "ch11-s06-p061", "type": "text", "text": "俺は、怒っている。"}, {"id": "ch11-s06-p062", "type": "text", "text": "仰向けのまま、右手を鳩尾の上に置いたまま、天井を見た。"}, {"id": "ch11-s06-p063", "type": "text", "text": "俺は怒っている。鳴海さんの命が天秤に載せられたことに。数字で消耗を把握していながら歌わせ続ける構造に。「数年以内に」の先を言わなかった霜月さんの口の向こうにある判断に。"}, {"id": "ch11-s06-p064", "type": "text", "text": "そして、それを七ヶ月間知らなかった自分に。"}, {"id": "ch11-s06-p065", "type": "text", "text": "いや。自分への怒りは——違う。向きが違う。灼ける場所の熱は外を向いている。構造に向いている。俺自身に向いているのは怒りではなく、もっと鈍いもの。鋭くない。名前がつかない。後悔に近いが後悔でもない。知らなかった時間が取り返せないことへの、ただの事実の認識。"}, {"id": "ch11-s06-p066", "type": "text", "text": "怒りは本物だ。"}, {"id": "ch11-s06-p067", "type": "text", "text": "夜の静けさがその確信を消そうとしたが、あの熱は静けさより強かった。"}, {"id": "ch11-s06-p068", "type": "break", "text": "◇"}, {"id": "ch11-s06-p069", "type": "text", "text": "鳴海さんのことを考える。"}, {"id": "ch11-s06-p070", "type": "text", "text": "鳴海さんは知らない。自分の声が命を削っていることを知らない。歌うたびに体重が減り、残響濃度が上がり、身体負荷が蓄積していく。その数字の意味を知らない。知らないまま、「蓮さん」と微笑んで、「また聴いてくださいね」と言う。"}, {"id": "ch11-s06-p071", "type": "text", "text": "風祭さんは二年間、それを一人で見ていた。二年間。泣いた。声帯を壊しかけた。代わりに歌えるようになりたくて。でも届かなかった。風祭さんの嗚咽の後の声を覚えている。枯れた声。水が足りない声。"}, {"id": "ch11-s06-p072", "type": "text", "text": "俺はあの声を聴いて——何も言えなかった。何も言えなかったが、足が鐘鋳塔に向いた。"}, {"id": "ch11-s06-p073", "type": "text", "text": "今、知っている。数字を見た。霜月さんの声を聴いた。「五年前と同じだ」。天秤。"}, {"id": "ch11-s06-p074", "type": "text", "text": "鳴海さんに、伝えるべきなのか。"}, {"id": "ch11-s06-p075", "type": "text", "text": "体が止まった。"}, {"id": "ch11-s06-p076", "type": "text", "text": "天井の白い塗り壁を見ている。裸電球の光が変わらない。"}, {"id": "ch11-s06-p077", "type": "text", "text": "鳴海さんは自分の歌が何を奪っているのか知らないまま歌っている。知ることは——知ったら、どうなる。鳴海さんはきっと歌わなくなる。いや、歌わなくなるか。あの人は——「歌いたいから歌う」と言った人だ。知っても歌うかもしれない。けれど、知った上で歌うことと、知らないまま歌うことは違う。"}, {"id": "ch11-s06-p078", "type": "text", "text": "知る権利がある。"}, {"id": "ch11-s06-p079", "type": "text", "text": "俺はそう思う。鳴海さんには知る権利がある。自分の体に何が起きているのかを。「数年以内に」の先に何があるのかを。数字は静かだ。数字は声を出さない。だから誰かが声にしなければいけない。"}, {"id": "ch11-s06-p080", "type": "text", "text": "でも——。"}, {"id": "ch11-s06-p081", "type": "text", "text": "知らないほうがいいのかもしれない。今の鳴海さんの笑顔は、知らないから成り立っている。「少し疲れただけ」と笑う七割の笑顔でも、あれは鳴海さんの笑顔だ。知ったら、あの笑顔は——。"}, {"id": "ch11-s06-p082", "type": "text", "text": "わからない。"}, {"id": "ch11-s06-p083", "type": "text", "text": "俺に決める権利があるのかどうかもわからない。鐘守補佐が共鳴者の秘密を知り、共鳴者に伝えるかどうかを判断する。それは俺の権限の外だ。しかし権限の話ではない。"}, {"id": "ch11-s06-p084", "type": "text", "text": "鳴海さんの命の話だ。"}, {"id": "ch11-s06-p085", "type": "choice_header", "text": "【選択肢】\n▶ 千歳に真実を教えるべきだ\n▶ 今は知らないほうがいい"}, {"id": "ch11-s06-p086", "type": "break", "text": "◇"}, {"id": "ch11-s06-p087", "type": "text", "text": "窓の外を見た。"}, {"id": "ch11-s06-p088", "type": "text", "text": "ベッドから体を起こして、窓に近づいた。ガラスの向こうに夜がある。十月の夜空。星が見えた。天蓋の間から見る星空とは違う。小さな窓の、四角く切り取られた夜空。"}, {"id": "ch11-s06-p089", "type": "text", "text": "星が瞬いている。"}, {"id": "ch11-s06-p090", "type": "text", "text": "鳴海さんの歌声が消えない世界を、と思った。思っただけで言葉にはしなかった。"}, {"id": "ch11-s06-p091", "type": "text", "text": "怒りはまだある。鳩尾の上にある。消えていない。消えなくていい。消えないでほしい、とすら思った。模倣なら消える。消えないならこれは俺のものだ。俺の怒りだ。持っていていい。"}, {"id": "ch11-s06-p092", "type": "text", "text": "しかし怒りだけではなかった。"}, {"id": "ch11-s06-p093", "type": "text", "text": "その熱の、少し奥に。熱の下に。もっと静かなものがあった。怒りが声を出す前から、ずっとそこに在ったもの。七ヶ月間。鳴海さんの歌を聴いて鳩尾が緩んだ日から。「蓮さん」と呼ばれて同じ場所の少し上に音が残った夜から。"}, {"id": "ch11-s06-p094", "type": "text", "text": "名前はまだつけない。"}, {"id": "ch11-s06-p095", "type": "text", "text": "怒りには名前をつけた。あの研究室で。今夜、それを確かめた。本物だと確かめた。だからもう一つのものにも、いつか名前をつける日が来る。今日ではない。今日は怒りだけで十分だ。"}, {"id": "ch11-s06-p096", "type": "text", "text": "窓を閉めたまま、ガラス越しの星を見ていた。"}, {"id": "ch11-s06-p097", "type": "text", "text": "夜は深い。朝はまだ遠い。鐘は今、鳴っていない。鳴っていないけれど、余韻は島の上に残っている。すみれが言っていた。「ならしてないときも、のこってるの」。残っている。鐘の余韻が島を包んでいる。その余韻の中に、鳴海さんの声も残っている。身体負荷指数47の声が。"}, {"id": "ch11-s06-p098", "type": "text", "text": "明日、目が覚めたら。"}, {"id": "ch11-s06-p099", "type": "text", "text": "何をするか、まだ決まっていない。決まっていないが、一つだけわかっている。明日の朝、体の中心を確認する。まだ熱かったら——いや、消えていたとしても。"}, {"id": "ch11-s06-p100", "type": "text", "text": "消えていたとしても、今夜、本物だったことは変わらない。"}, {"id": "ch11-s06-p101", "type": "text", "text": "覚えておく。"}, {"id": "ch11-s06-p102", "type": "text", "text": "ベッドに戻った。仰向けになった。天井の白い塗り壁。凹凸。裸電球の影。変わっていない天井。変わった俺。"}, {"id": "ch11-s06-p103", "type": "text", "text": "目を閉じた。眠れるかどうかはわからなかった。"}]}, {"chapter": 12, "chapterTitle": "冬の足音", "scene": 1, "sceneTitle": "消えた農家", "wordCount": "約5,100字", "paragraphs": [{"id": "ch12-s01-p001", "type": "text", "text": "窓の外が白かった。"}, {"id": "ch12-s01-p002", "type": "text", "text": "十一月の朝。補佐官舎の窓を開けたら、霧が出ていた。四月の着任初日にも霧があった。あの日の霧は残響桜の花弁を含んでいて、薄紫がかっていた。今朝の霧は白い。色のない霧。気温も違う。四月の霧は肌に触れても冷たさしか感じなかったが、今朝の霧は痛い。指先が強張る。息が白くなった。"}, {"id": "ch12-s01-p003", "type": "text", "text": "冬が近い。"}, {"id": "ch12-s01-p004", "type": "text", "text": "着替えた。制服のジャケットの下にもう一枚、灰色のニットを着た。十月まではシャツ一枚で足りていた。今朝はそれでは無理だった。指先に息を吹きかけて、靴を履いた。"}, {"id": "ch12-s01-p005", "type": "text", "text": "鐘鋳塔に向かう道。石畳が白く湿っている。残響桜は葉の大半を落としていた。枝だけが霧の中に線を引いている。九月に一割だった紅葉は、十一月の終わりには落葉になっていた。幹と枝だけが残った。幹と枝だけの残響桜は、花も葉もある時より輪郭がはっきり見えた。"}, {"id": "ch12-s01-p006", "type": "text", "text": "鳩尾の上を確認した。"}, {"id": "ch12-s01-p007", "type": "text", "text": "あの夜から一ヶ月半。十月の終わりに確認した時にはまだ熱かった。十一月に入って、熱は変わった。消えたのではない。温度が変わった。鳩尾の上にあったものは、灼けるような怒りの熱から、もっと深い場所に沈んだ一定の温度になっていた。地下の配管のように。表面からは見えないが、手を当てれば温かい。"}, {"id": "ch12-s01-p008", "type": "text", "text": "消えていない。"}, {"id": "ch12-s01-p009", "type": "text", "text": "消えないものを持ったまま、一ヶ月半が過ぎた。その間に鐘は毎日鳴り、計器の数値を毎日記録し、食堂で食事を取り、燈花のおにぎりを食べ、記録室で篠宮さんのペンの音を聴き、霜月さんの「問題ない」を聴き、天蓋の間ですみれの声を聴いた。日常が続いた。しかし日常の質が変わっていた。計器の数字を見る時に南端のグラフを思い出す。食堂で焼き魚を食べている時に身体負荷指数47が頭の隅にある。消えない熱を持ったまま日常を過ごすことは、熱を持つ前の日常とは違う。"}, {"id": "ch12-s01-p010", "type": "text", "text": "六時三十分の朝鐘が鳴った。"}, {"id": "ch12-s01-p011", "type": "text", "text": "足が止まった。鐘の音が霧の中を通ると、音が拡散する。四月よりも輪郭がぼやけた音。霧の粒に含まれる水分が、残響を吸っている。しかし音は聞こえる。体を通り抜ける。"}, {"id": "ch12-s01-p012", "type": "text", "text": "鳩尾の上の温度が、鐘の音に呼応して半度だけ上がった。"}, {"id": "ch12-s01-p013", "type": "break", "text": "◇"}, {"id": "ch12-s01-p014", "type": "text", "text": "食堂に入った。"}, {"id": "ch12-s01-p015", "type": "text", "text": "煉瓦造りの天井が高いホール。アーチ状の窓。飴色の木製長テーブル。四月と変わっていない。変わっているのは窓の外の光で、四月は柔らかい春の日差しが斜めに射し込んでいたが、十一月の朝の光は白く、低い角度から入って床に這うように広がっていた。食堂の中の空気も冷えていた。配膳台の蒸気が白く立ち上っている。"}, {"id": "ch12-s01-p016", "type": "text", "text": "トレイを受け取った。定食。白米、味噌汁、焼き鰺、漬物。"}, {"id": "ch12-s01-p017", "type": "text", "text": "窓際の端に座った。四月と同じ場所。しかし今は「いつもの席」という認識がある。四月にはなかった認識。"}, {"id": "ch12-s01-p018", "type": "text", "text": "箸を手に取った。味噌汁を一口。温かい。出汁が染みる。おいしい——間がなかった。"}, {"id": "ch12-s01-p019", "type": "text", "text": "焼き鰺を崩す。白身の中から塩気と脂が舌に広がる。二口目を口に入れた時、食堂の空気が変わった。"}, {"id": "ch12-s01-p020", "type": "text", "text": "ざわめきが生まれていた。"}, {"id": "ch12-s01-p021", "type": "text", "text": "食堂は朝八時頃が最も人が少ない。早い組は七時半に食べ終わって出ていき、遅い組は八時半頃に来る。今はその間の時間帯。それでもテーブルに残っていた十数人の生徒の声が、じわりと密度を上げていた。"}, {"id": "ch12-s01-p022", "type": "text", "text": "「外円区で——」\n「農家が——」\n「消えた——」"}, {"id": "ch12-s01-p023", "type": "text", "text": "断片が耳に入った。"}, {"id": "ch12-s01-p024", "type": "text", "text": "食堂の入口近くで、上級生が三人立ち話をしていた。声を抑えようとして抑えきれていない。もう一つのテーブルでは四人が頭を寄せ合っていた。食堂の調理場のおばさんが配膳の手を止めて、隣のおばさんに何か言っていた。"}, {"id": "ch12-s01-p025", "type": "text", "text": "「縁蝕波だって」"}, {"id": "ch12-s01-p026", "type": "text", "text": "その単語で、鳩尾の上の温度が跳ねた。"}, {"id": "ch12-s01-p027", "type": "text", "text": "箸を置いた。"}, {"id": "ch12-s01-p028", "type": "text", "text": "「今朝の監視哨から連絡が——」\n「何人か消えたらしい——」\n「外円区の南のほう——」"}, {"id": "ch12-s01-p029", "type": "text", "text": "南。"}, {"id": "ch12-s01-p030", "type": "text", "text": "南端。南端蝕域活動指数。十月に17パーセント増加していた赤い線。あの折れ線グラフの先端が、まだ伸びていた。伸びたまま、ついに何かに届いた。"}, {"id": "ch12-s01-p031", "type": "text", "text": "食堂の入口に目を向けた。"}, {"id": "ch12-s01-p032", "type": "text", "text": "人の出入りが始まっていた。廊下を早足で歩く生徒の影がアーチ窓に映っている。食堂の中も動き始めていた。トレイを持ったまま立ち上がる者。座ったまま隣の者の袖を引く者。"}, {"id": "ch12-s01-p033", "type": "text", "text": "その中に、燈花がいた。"}, {"id": "ch12-s01-p034", "type": "text", "text": "食堂の入口から三歩ほどの場所。立っていた。トレイを持っていなかった。朝食を取りに来たのではない。食堂の前を通りかかって、ざわめきが耳に入って、足が止まったのだと思った。"}, {"id": "ch12-s01-p035", "type": "text", "text": "燈花の顔が見えた。"}, {"id": "ch12-s01-p036", "type": "text", "text": "遠い。窓際の端から入口までは長テーブルが三列分ある。距離がある。しかし見えた。燈花の顔色が変わっていた。頬の色が引いていた。唇の色も薄い。表情は——表情がなかった。止まっていた。笑顔でも怒りでも驚きでもない。四月に最初に会った時から数えて、燈花の表情が「何もない」状態になったのを見るのは初めてだった。"}, {"id": "ch12-s01-p037", "type": "text", "text": "「灯里村の近く——」"}, {"id": "ch12-s01-p038", "type": "text", "text": "食堂の中の誰かが、その名前を言った。"}, {"id": "ch12-s01-p039", "type": "text", "text": "燈花の右手が動いた。左手の薬指の布リングに触れた。"}, {"id": "ch12-s01-p040", "type": "text", "text": "俺は立ち上がった。しかし燈花はもう入口にいなかった。振り返った時には廊下を早足で去る栗色のポニーテールの後ろ姿が、アーチ窓の向こうに見えた。追いかけようとして——足が止まった。"}, {"id": "ch12-s01-p041", "type": "text", "text": "今、追いかけるべきか。"}, {"id": "ch12-s01-p042", "type": "text", "text": "燈花に何を言うか。何がわかっているか。断片的なざわめきしか聞いていない。「外円区」「南」「縁蝕波」「消えた」。それだけだ。情報がない。情報がない状態で燈花の前に立っても、何も言えない。"}, {"id": "ch12-s01-p043", "type": "text", "text": "まず、情報を取る。"}, {"id": "ch12-s01-p044", "type": "text", "text": "座り直さなかった。トレイを配膳台に返した。焼き鰺は半分残っていた。食堂を出た。"}, {"id": "ch12-s01-p045", "type": "break", "text": "◇"}, {"id": "ch12-s01-p046", "type": "text", "text": "鐘鋳塔の二階。管理局報告室。"}, {"id": "ch12-s01-p047", "type": "text", "text": "鐘鋳塔の一階は蓮の勤務する管理室と受付で、二階から上が研究区画になっている。報告室は二階の北側、通路の突き当たりにある小さな部屋だった。縁際の監視哨から送られてくる報告書が、ここに最初に届く。壁面に伝令管の受口が四つ並んでいて、金属製の筒が取り出し口に刺さっている。報告書は紙を丸めて筒に入れ、圧縮空気で送る。古い仕組みだった。"}, {"id": "ch12-s01-p048", "type": "text", "text": "霜月さんが先にいた。"}, {"id": "ch12-s01-p049", "type": "text", "text": "白いロングコート。銀髪のハーフアップ。報告書を持って立っていた。机ではなく、壁面の地図の前に立っていた。アルケミラ島の地図。鐘鋳塔を中心にした同心円が描かれている。内円区、中円区、外円区。同心円の外側の線が蝕域との境界。"}, {"id": "ch12-s01-p050", "type": "text", "text": "霜月さんの右手の指先が、地図の南端を指していた。"}, {"id": "ch12-s01-p051", "type": "text", "text": "「朝霧。来たか」"}, {"id": "ch12-s01-p052", "type": "text", "text": "声に抑揚がなかった。いつもの声。しかし声が出るまでに半拍の間があった。俺を認識してから言葉を出すまでの間に、何かを噛み締めたような間。"}, {"id": "ch12-s01-p053", "type": "text", "text": "「食堂で縁蝕波の話を聞きました。詳細を教えてください」"}, {"id": "ch12-s01-p054", "type": "text", "text": "霜月さんの目がラベンダーの硬さで俺を見た。三秒。判断の時間。それから視線を地図に戻した。"}, {"id": "ch12-s01-p055", "type": "text", "text": "「今朝五時十二分。南端監視哨からの第一報。外円区南端、灯里村跡地東方約三キロメートルの農地が消滅した」"}, {"id": "ch12-s01-p056", "type": "text", "text": "声が報告書を読み上げる時のトーンに切り替わった。平たく、均された声。"}, {"id": "ch12-s01-p057", "type": "text", "text": "「被害範囲は約〇・五平方キロメートル。農地三区画、住居四軒、納屋二棟。消滅した住民は推定八名」"}, {"id": "ch12-s01-p058", "type": "text", "text": "八名。"}, {"id": "ch12-s01-p059", "type": "text", "text": "小さな数字だった。食堂で聞いた「何人か消えた」の「何人か」は、八。島の人口二十五万に対して八。パーセントにすれば〇・〇〇三二。計器の誤差にも入らない。"}, {"id": "ch12-s01-p060", "type": "text", "text": "しかし、八という数字の中に、それぞれの名前がある。篠宮さんのメモ帳に書かれるべき名前が、八つ。"}, {"id": "ch12-s01-p061", "type": "text", "text": "「規模としては小さい」"}, {"id": "ch12-s01-p062", "type": "text", "text": "霜月さんの声が続いた。"}, {"id": "ch12-s01-p063", "type": "text", "text": "「問題は位置だ」"}, {"id": "ch12-s01-p064", "type": "text", "text": "地図の上の指先が動いた。南端の蝕域との境界線——その線が、地図上で内側に食い込んでいる場所がある。"}, {"id": "ch12-s01-p065", "type": "text", "text": "「灯里村跡地東方三キロメートル。この地点は、先月まで蝕域との境界から五キロ以上離れていた。五キロの安全圏の中にあった農地が消滅した。つまり」"}, {"id": "ch12-s01-p066", "type": "text", "text": "「蝕域が内側に動いた」"}, {"id": "ch12-s01-p067", "type": "text", "text": "俺の声だった。霜月さんの説明を聞いて出た声ではなかった。十月のデータを見た時から頭の中にあった。南端の活動指数が17パーセント増加していた。増加率が加速していた。40パーセント超で縁蝕波発生条件。あの時のデータの先に、今朝の報告がある。"}, {"id": "ch12-s01-p068", "type": "text", "text": "「ああ。蝕域が内側に動いている。南端に限定した現象だが、方向は明確だ。外から内へ」"}, {"id": "ch12-s01-p069", "type": "text", "text": "霜月さんの指が地図の上を滑った。南端の境界線の内側。灯里村跡地。その東方三キロの、今朝消えた場所。そしてさらに内側——中円区の南端まで線を引くように。"}, {"id": "ch12-s01-p070", "type": "text", "text": "「上層部に報告した」"}, {"id": "ch12-s01-p071", "type": "text", "text": "声の質が変わった。報告書のトーンではなくなった。低くなった。硬くなった。十月に「また始まる」と漏らした時と同じ硬さ。十一月の研究室での「五年前と同じだ」と同じ声。"}, {"id": "ch12-s01-p072", "type": "text", "text": "「対応が遅い」"}, {"id": "ch12-s01-p073", "type": "text", "text": "短い。四語。しかしその四語の中に、歯を食いしばった跡があった。"}, {"id": "ch12-s01-p074", "type": "text", "text": "「今朝の報告を受けて、外円区南端の住民の避難勧告を出すべきだと進言した。返答は『通常の変動の範囲内である。次回定例会議で検討する』」"}, {"id": "ch12-s01-p075", "type": "text", "text": "霜月さんの唇の線が水平から微かに歪んだ。先月見た歪みと同じ方向。怒りの歪み。"}, {"id": "ch12-s01-p076", "type": "text", "text": "「次回定例会議は来月だ。一ヶ月、放置する。データは待ってくれない」"}, {"id": "ch12-s01-p077", "type": "text", "text": "声が低いまま。抑揚のない声が、逆に怒りの純度を高めていた。"}, {"id": "ch12-s01-p078", "type": "text", "text": "「霜月さん」"}, {"id": "ch12-s01-p079", "type": "text", "text": "「五年前と同じだ」"}, {"id": "ch12-s01-p080", "type": "text", "text": "声が重なった。俺が名前を呼んだのと、霜月さんが繰り返したのが、同時だった。"}, {"id": "ch12-s01-p081", "type": "text", "text": "霜月さんの目が地図から離れ、俺を見た。ラベンダーの瞳。硬さの一枚下にある層が浮いていた。十月の研究室で見たのと同じ層。沈めていたものが、浮いている。"}, {"id": "ch12-s01-p082", "type": "text", "text": "「データがある。危険を示すデータがある。報告した。しかし上層は動かない。コストが合わないのか、面倒なのか、あるいは——」"}, {"id": "ch12-s01-p083", "type": "text", "text": "声が途切れた。"}, {"id": "ch12-s01-p084", "type": "text", "text": "左手が、無意識に左耳のピアスに触れた。青い石。消えた集落の子供から貰ったお守り。"}, {"id": "ch12-s01-p085", "type": "text", "text": "「霜月さん。俺にできることがあれば」"}, {"id": "ch12-s01-p086", "type": "text", "text": "声が出ていた。十月までの俺なら「何かあったら報告します」と言ったかもしれない。業務の言葉を選んだかもしれない。しかし今朝、鳩尾の上の温度が跳ねた。食堂で「縁蝕波」と聞いた瞬間に跳ねた。燈花の顔色が変わったのを見た時、もう一度跳ねた。跳ねたものは、業務の言葉を選ぶ前に口に出た。"}, {"id": "ch12-s01-p087", "type": "text", "text": "霜月さんが俺を見ていた。三秒。"}, {"id": "ch12-s01-p088", "type": "text", "text": "「データの整理を頼む。今朝の報告と、十月から蓄積していた南端の観測データを時系列で一本にまとめろ。全数値。全日付。グラフ化は不要。数字を並べろ。私が上層に再度進言する時の、根拠にする」"}, {"id": "ch12-s01-p089", "type": "text", "text": "「わかりました」"}, {"id": "ch12-s01-p090", "type": "text", "text": "「今日中に」"}, {"id": "ch12-s01-p091", "type": "text", "text": "「はい」"}, {"id": "ch12-s01-p092", "type": "text", "text": "霜月さんの目が地図に戻った。南端を指していた指が、ゆっくりと離れた。"}, {"id": "ch12-s01-p093", "type": "text", "text": "「朝霧」"}, {"id": "ch12-s01-p094", "type": "text", "text": "背を向けかけた俺を呼び止めた。"}, {"id": "ch12-s01-p095", "type": "text", "text": "振り返った。霜月さんは地図の前に立っていた。白いコートの背中。報告書を持つ手。"}, {"id": "ch12-s01-p096", "type": "text", "text": "「天城は」"}, {"id": "ch12-s01-p097", "type": "text", "text": "声が止まった。止めた。口を開きかけて、閉じた。"}, {"id": "ch12-s01-p098", "type": "text", "text": "それから、別のことを言った。"}, {"id": "ch12-s01-p099", "type": "text", "text": "「いい。何でもない。データを頼む」"}, {"id": "ch12-s01-p100", "type": "text", "text": "何でもないはずがなかった。「天城」の後に続くはずだった言葉を、霜月さんは飲み込んだ。灯里村の近くで消滅が起きたこと。燈花にとってそれが何を意味するか。霜月さんもわかっている。わかった上で、データの話に戻した。"}, {"id": "ch12-s01-p101", "type": "text", "text": "報告室を出た。"}, {"id": "ch12-s01-p102", "type": "text", "text": "階段を降りながら、食堂で見た燈花の顔を思い出した。色のない顔。表情のない顔。布リングに触れた右手。"}, {"id": "ch12-s01-p103", "type": "text", "text": "肋骨の内側が、鈍く痛んだ。"}]}, {"chapter": 12, "chapterTitle": "冬の足音", "scene": 2, "sceneTitle": "消滅した場所", "wordCount": "約6,200字", "paragraphs": [{"id": "ch12-s02-p001", "type": "text", "text": "午前中にデータ整理を終えた。"}, {"id": "ch12-s02-p002", "type": "text", "text": "南端の観測記録を時系列で一本にまとめる作業は、思ったよりかかった。十月初旬から十一月下旬まで、五十七日分の数値。活動指数、表面温度推移、粒子密度、音波吸収率。数字の列を追いながら、赤い線が右肩上がりに伸びていく様を改めて確認した。十月末の急な跳ね。十一月に入ってからの加速。今朝の報告で実体になった、その手前のデータの連なり。"}, {"id": "ch12-s02-p003", "type": "text", "text": "霜月さんの机に報告書を置いた。霜月さんは不在だった。上層部への再進言に行っているのかもしれない。"}, {"id": "ch12-s02-p004", "type": "text", "text": "管理室に戻ろうとした時、廊下で篠宮さんと会った。"}, {"id": "ch12-s02-p005", "type": "text", "text": "灰色のエプロンの下に紺の制服。首から下げた図書館の銀色の鍵。腰には小さなメモ帳。いつもの篠宮さんだった。いつもと違うのは、肩に革の鞄をかけていたこと。日常の記録室では見ない装備だった。"}, {"id": "ch12-s02-p006", "type": "text", "text": "「朝霧さん」"}, {"id": "ch12-s02-p007", "type": "text", "text": "声が静かに廊下に落ちた。"}, {"id": "ch12-s02-p008", "type": "text", "text": "「篠宮さん。どこかに出かけるんですか」"}, {"id": "ch12-s02-p009", "type": "text", "text": "「外円区です」"}, {"id": "ch12-s02-p010", "type": "text", "text": "短い返答。篠宮さんの返答はいつも短い。しかし今日は短さの質が違った。用件が明確で、それ以外の要素が必要ないから短い。"}, {"id": "ch12-s02-p011", "type": "text", "text": "「今朝の、消滅した農地の記録を取りに行きます」"}, {"id": "ch12-s02-p012", "type": "text", "text": "革の鞄。メモ帳の予備。インク壺。篠宮さんは準備を済ませている。「行きます」ではなく「行く準備はとうに終わっている」。"}, {"id": "ch12-s02-p013", "type": "text", "text": "耳の位置に、ペンの音の記憶があった。記録室で聞く、あの一定間隔のかりかりという音。篠宮さんの手。篠宮さんの指。二十三冊分の記録を積み上げてきた、あの手。"}, {"id": "ch12-s02-p014", "type": "text", "text": "「俺も行きます」"}, {"id": "ch12-s02-p015", "type": "text", "text": "声が出ていた。霜月さんからデータ整理以外の指示はなく、午後は空いている。しかしそれは理由にならない。空いているから行くのではなく——"}, {"id": "ch12-s02-p016", "type": "text", "text": "耳の位置にあるものが、動いた。"}, {"id": "ch12-s02-p017", "type": "text", "text": "「篠宮さん一人で行くんですか」"}, {"id": "ch12-s02-p018", "type": "text", "text": "「はい。いつも一人です」"}, {"id": "ch12-s02-p019", "type": "text", "text": "いつも。"}, {"id": "ch12-s02-p020", "type": "text", "text": "篠宮さんはこれまでもずっと一人で、消滅した場所に記録を取りに行っていた。二十三冊のメモ帳、三千六百八十人分の記録。その全てを、一人で。"}, {"id": "ch12-s02-p021", "type": "text", "text": "「同行させてください」"}, {"id": "ch12-s02-p022", "type": "text", "text": "篠宮さんの墨色の瞳が俺を見た。二秒。表情は変わらない。変わらないが、瞬きが一回多かった。"}, {"id": "ch12-s02-p023", "type": "text", "text": "「……お手伝いいただけるなら、助かります」"}, {"id": "ch12-s02-p024", "type": "text", "text": "声がいつもより半音低かった。篠宮さんの「助かります」を聞くのは、たぶん二回目だった。"}, {"id": "ch12-s02-p025", "type": "break", "text": "◇"}, {"id": "ch12-s02-p026", "type": "text", "text": "外円区への馬車は、中円区の南の広場から出ている。"}, {"id": "ch12-s02-p027", "type": "text", "text": "乗合馬車。木製の荷台に幌が被せてあり、長椅子が向かい合わせに並んでいる。乗客は俺と篠宮さんの他に、農具を抱えた男が二人。馬車が動き始めると、石畳から土道に変わった。振動が大きくなる。幌の隙間から見える風景が、建物の密集した中円区から、広い農地に変わっていった。"}, {"id": "ch12-s02-p028", "type": "text", "text": "十一月下旬の農地。収穫を終えた畑が広がっている。土が剥き出しで、刈り株だけが等間隔に残っている。空が広い。中円区では建物に遮られていた空が、外円区に出ると頭上いっぱいに開けた。しかし空の色は澄んでいなかった。薄く白濁している。雲ではない。もっと均一な白さ。蝕域の影響で外円区の空が曇ることがある、と霜月さんの資料で読んだ。白い空の下、収穫後の畑が灰色に広がっている。色の少ない風景。"}, {"id": "ch12-s02-p029", "type": "text", "text": "風が冷たい。十一月の風。朝のニットの上にジャケットを着ていても、風が袖口から入ってくる。隣に座っている篠宮さんは、紺のコートを着ていた。コートの裾がきちんと膝の上に畳まれている。膝の上にはメモ帳が開かれていて、篠宮さんは馬車の振動の中でもペンを走らせていた。"}, {"id": "ch12-s02-p030", "type": "text", "text": "「何を書いているんですか」"}, {"id": "ch12-s02-p031", "type": "text", "text": "「今日の天候。気温。風向き。移動時の状況。記録の前提条件です」"}, {"id": "ch12-s02-p032", "type": "text", "text": "篠宮さんのペンは止まらなかった。かりかりという音が、馬車の車輪の軋みに混じって聞こえる。耳の位置にあるものが、その音に反応した。記録室で聴くのと同じ音。場所が変わっても、篠宮さんのペンの音は同じだった。"}, {"id": "ch12-s02-p033", "type": "text", "text": "馬車が止まった。農具の男たちが降りた。御者が振り返って、「この先は道が荒れてます。歩いてもらった方がいい」と言った。"}, {"id": "ch12-s02-p034", "type": "text", "text": "降りた。土の道。両側に収穫後の畑。南に向かって歩き始めた。"}, {"id": "ch12-s02-p035", "type": "text", "text": "十分ほど歩くと、畑の向こうに人影が見えた。外円区の住民らしい農夫が三人、畑の端に立っていた。立っているだけで、何もしていなかった。畑の南の端を見ていた。"}, {"id": "ch12-s02-p036", "type": "text", "text": "その先を見た。"}, {"id": "ch12-s02-p037", "type": "text", "text": "畑が途切れていた。"}, {"id": "ch12-s02-p038", "type": "break", "text": "◇"}, {"id": "ch12-s02-p039", "type": "text", "text": "穴ではなかった。"}, {"id": "ch12-s02-p040", "type": "text", "text": "崖でもなかった。地面が陥没したのでも、崩れたのでもなかった。"}, {"id": "ch12-s02-p041", "type": "text", "text": "畑が、ある線を境に「ない」。"}, {"id": "ch12-s02-p042", "type": "text", "text": "その境界は不規則な曲線を描いていた。畝の途中で途切れている場所。土が半分残っている場所。畑の杭が根元から消えて、上半分だけが空中に——いや、空中にすら残っていない。杭の途中までが「ある」。その先が「ない」。"}, {"id": "ch12-s02-p043", "type": "text", "text": "断面があるわけではなかった。断面なら物質の内部が見えるはずだった。土の断面、木の繊維、石の粒。何もない。切り口がない。ただ、存在がそこで終わっている。"}, {"id": "ch12-s02-p044", "type": "text", "text": "その先に、白い光があった。"}, {"id": "ch12-s02-p045", "type": "text", "text": "淡い光。蝕域の光。大気に溶けた乳白色の粒子が、ゆっくりと漂っている。粒子の一つ一つが微かに明滅していた。闇の中の光ではなく、昼の光の中にある、別の種類の白。空の白濁と地上の白光が混ざり合って、「ある」と「ない」の境目を曖昧にしている。"}, {"id": "ch12-s02-p046", "type": "text", "text": "光の塵が舞っていた。"}, {"id": "ch12-s02-p047", "type": "text", "text": "風に乗っているのではなかった。風は吹いている。しかし光の塵は風に従わない。別の法則で動いている。浮き上がり、漂い、沈み、また浮き上がる。"}, {"id": "ch12-s02-p048", "type": "text", "text": "体が動かなかった。"}, {"id": "ch12-s02-p049", "type": "text", "text": "足が止まっていた。いつ止まったのかわからない。歩いていて、気づいたら立っていた。"}, {"id": "ch12-s02-p050", "type": "text", "text": "動悸がした。"}, {"id": "ch12-s02-p051", "type": "text", "text": "理由のない動悸だった。走ったわけでもない。驚いたのとも違う。心臓が勝手に速度を上げていた。胸の中で、何かが掴まれたように脈が乱れている。"}, {"id": "ch12-s02-p052", "type": "text", "text": "知っている。"}, {"id": "ch12-s02-p053", "type": "text", "text": "体がそう言っていた。頭ではない。頭は何も知らない。記憶にない。蝕域の消滅現場を間近で見るのは初めてのはずだった。縁際の監視哨にいた時も、これほど近くでは見ていない。初めてのはず。"}, {"id": "ch12-s02-p054", "type": "text", "text": "しかし体は別のことを言っている。この白い光を知っている。この粒子の漂い方を知っている。この「ない」という感覚を、どこかで——"}, {"id": "ch12-s02-p055", "type": "text", "text": "手が震えていた。"}, {"id": "ch12-s02-p056", "type": "text", "text": "左手。左手首のブレスレットの下で、脈が打っている。速い。苦しくはないが、止められない。心臓が、俺の意志と無関係に動いている。ルミエラ島の名前は浮かばなかった。記憶は戻らなかった。しかし体の反応だけが、確かだった。"}, {"id": "ch12-s02-p057", "type": "text", "text": "「朝霧さん」"}, {"id": "ch12-s02-p058", "type": "text", "text": "耳に声が届いた。"}, {"id": "ch12-s02-p059", "type": "text", "text": "篠宮さんが横に立っていた。メモ帳を持って。ペンを持って。墨色の瞳が俺を見ていた。瞳の奥にあるものは読めなかった。しかし声の温度は——わずかに、いつもより温かかった。"}, {"id": "ch12-s02-p060", "type": "text", "text": "「大丈夫ですか」"}, {"id": "ch12-s02-p061", "type": "text", "text": "「——ああ。大丈夫です」"}, {"id": "ch12-s02-p062", "type": "text", "text": "大丈夫ではなかった。動悸はまだ続いていた。しかし篠宮さんの声を聴いた瞬間、耳の位置にあるものが反応して、脈が少しだけ戻った。"}, {"id": "ch12-s02-p063", "type": "text", "text": "篠宮さんはそれ以上聞かなかった。"}, {"id": "ch12-s02-p064", "type": "text", "text": "「こちらです」"}, {"id": "ch12-s02-p065", "type": "text", "text": "畑の境界から十歩ほど離れた場所に、木の杭が立っていた。応急的に打たれた目印。監視哨の隊員が立てたものだろう。杭に結ばれた布に、番号が書かれている。"}, {"id": "ch12-s02-p066", "type": "text", "text": "篠宮さんがメモ帳を開いた。新しいページ。ペンにインクをつけた。"}, {"id": "ch12-s02-p067", "type": "text", "text": "「消滅地点番号、南端一二八七。日時、十一月二十六日午前五時十二分。場所、外円区南端、灯里村跡地東方約三キロメートル」"}, {"id": "ch12-s02-p068", "type": "text", "text": "声が淡々と続いた。記録室で聴くのと同じトーン。場所が消滅した農地に変わっても、篠宮さんの記録の声は同じだった。"}, {"id": "ch12-s02-p069", "type": "text", "text": "「被害範囲、約零・五平方キロメートル。農地三区画、住居四軒、納屋二棟」"}, {"id": "ch12-s02-p070", "type": "text", "text": "ペンが紙の上を走る。かりかり。かりかり。"}, {"id": "ch12-s02-p071", "type": "text", "text": "「消滅した住民。推定八名」"}, {"id": "ch12-s02-p072", "type": "text", "text": "篠宮さんのペンが止まった。一秒。それからまた動き始めた。"}, {"id": "ch12-s02-p073", "type": "text", "text": "「一軒目。根岸家。住人三名。根岸宗一郎、六十七歳、農業。根岸ミツ、六十四歳。根岸拓也、三十二歳、農業。住居は木造二階建て、築四十年以上。納屋一棟を併設」"}, {"id": "ch12-s02-p074", "type": "text", "text": "篠宮さんが革の鞄から紙を取り出した。今朝の監視哨の報告書の写しだろう。報告書と消滅した場所を見比べながら、メモ帳に書き写していく。"}, {"id": "ch12-s02-p075", "type": "text", "text": "「二軒目。田所家。住人二名。田所八重、七十一歳。田所千恵、四十五歳。住居は平屋建て」"}, {"id": "ch12-s02-p076", "type": "text", "text": "名前。年齢。家の構造。"}, {"id": "ch12-s02-p077", "type": "text", "text": "篠宮さんの声には抑揚がなかった。しかし抑揚がないことと感情がないことは違う。記録室で何ヶ月も一緒にいて、それは知っている。篠宮さんは感情を消しているのではなく、感情を記録の精度に影響させないようにしている。"}, {"id": "ch12-s02-p078", "type": "text", "text": "「三軒目。八木家。住人二名。八木健司、五十八歳、農業。八木志乃、五十五歳」"}, {"id": "ch12-s02-p079", "type": "text", "text": "三軒目が終わった。四軒目が始まった。"}, {"id": "ch12-s02-p080", "type": "text", "text": "「四軒目。名称不明。住居は確認できるが、住民台帳に該当する世帯なし。推定住人一名。詳細不明」"}, {"id": "ch12-s02-p081", "type": "text", "text": "ペンが止まった。"}, {"id": "ch12-s02-p082", "type": "text", "text": "篠宮さんが報告書から顔を上げて、「ない」場所を見た。白い光の粒子が漂う、存在の終わった場所を。"}, {"id": "ch12-s02-p083", "type": "text", "text": "「……名前がわからない方がいます」"}, {"id": "ch12-s02-p084", "type": "text", "text": "声が変わった。淡々とした記録の声ではなかった。篠宮さんの声がそこだけ、低く、硬くなった。"}, {"id": "ch12-s02-p085", "type": "text", "text": "「名前がわからないと、記録できません。記録できないと、この方は最初からいなかったことになります」"}, {"id": "ch12-s02-p086", "type": "text", "text": "篠宮さんのペンを持つ指が白い。力が入っている。"}, {"id": "ch12-s02-p087", "type": "text", "text": "「名前を、調べます。近隣の住民に聞けば——」"}, {"id": "ch12-s02-p088", "type": "text", "text": "「篠宮さん」"}, {"id": "ch12-s02-p089", "type": "text", "text": "俺の声だった。"}, {"id": "ch12-s02-p090", "type": "text", "text": "篠宮さんが俺を見た。"}, {"id": "ch12-s02-p091", "type": "text", "text": "「……すごいな。こんな場所で、記録を取り続けるのか」"}, {"id": "ch12-s02-p092", "type": "text", "text": "考えて出た言葉ではなかった。「ない」場所の前で、白い光の粒子の中で、動悸を抱えたまま。それでも隣でペンを動かし続ける人を見て、出た言葉。"}, {"id": "ch12-s02-p093", "type": "text", "text": "篠宮さんの瞳がわずかに揺れた。微かな揺れ。表情は変わらない。しかし墨色の中に、一瞬、別の層が浮いた。"}, {"id": "ch12-s02-p094", "type": "text", "text": "「記録しなければ」"}, {"id": "ch12-s02-p095", "type": "text", "text": "声が静かだった。"}, {"id": "ch12-s02-p096", "type": "text", "text": "「この人たちは、本当に消えます」"}, {"id": "ch12-s02-p097", "type": "text", "text": "ペンを持ったまま。メモ帳を持ったまま。「ない」場所の前に立ったまま。"}, {"id": "ch12-s02-p098", "type": "text", "text": "「忘れられて、消えます」"}, {"id": "ch12-s02-p099", "type": "text", "text": "短い言葉だった。しかし短い言葉の中に、二十三冊分のメモ帳と三千六百八十人分の名前の重さがあった。"}, {"id": "ch12-s02-p100", "type": "text", "text": "忘れられて、消える。蝕域に消されるのは最初の消滅で、世界から忘れられるのが二度目の消滅。篠宮さんは二度目の消滅に抗っている。一人で。ペン一本で。"}, {"id": "ch12-s02-p101", "type": "text", "text": "俺は何も言えなかった。言うべき言葉が見つからなかったのではなく、言葉が必要なかった。篠宮さんの声を聴いた。記録した。"}, {"id": "ch12-s02-p102", "type": "text", "text": "篠宮さんはペンに新しくインクをつけて、四軒目の記録の続きを書き始めた。俺は報告書の残りを持って、篠宮さんが読み上げる項目を確認する役に回った。二人で消滅した八名の記録を仕上げた。根岸宗一郎。根岸ミツ。根岸拓也。田所八重。田所千恵。八木健司。八木志乃。そして名前のわからない一人。"}, {"id": "ch12-s02-p103", "type": "text", "text": "篠宮さんのメモ帳に、八人分の記録が残った。"}, {"id": "ch12-s02-p104", "type": "break", "text": "◇"}, {"id": "ch12-s02-p105", "type": "text", "text": "帰り道。"}, {"id": "ch12-s02-p106", "type": "text", "text": "同じ道を北に歩いていた。収穫後の畑が両側に広がり、空が白く曇っている。"}, {"id": "ch12-s02-p107", "type": "text", "text": "篠宮さんは俺の半歩前を歩いていた。歩幅が小さく、足音が聞こえない。背筋は正しいが、少し前かがみ気味。コートの裾が膝の下で揺れている。"}, {"id": "ch12-s02-p108", "type": "text", "text": "風が吹いた。十一月の風。冷たい。"}, {"id": "ch12-s02-p109", "type": "text", "text": "その時、見えた。"}, {"id": "ch12-s02-p110", "type": "text", "text": "篠宮さんの輪郭が、揺らいだ。"}, {"id": "ch12-s02-p111", "type": "text", "text": "一瞬だった。コートの裾が風に翻ったのと同時に——篠宮さんの右肩から腕にかけて、輪郭が薄くなった。透けた、というのは違う。もっと微かなもの。風景が篠宮さんの体を透過して見えたのではなく、篠宮さんの存在の「濃さ」が一瞬だけ下がったような。"}, {"id": "ch12-s02-p112", "type": "text", "text": "消滅した場所の白い光の粒子が、まだ視界の端に残っていた。蝕域の光の残像が目に焼きついていて、それが篠宮さんの輪郭と重なったのだと思った。光の加減。目の疲れ。消滅した場所を見た後だから、目がおかしくなっている。"}, {"id": "ch12-s02-p113", "type": "text", "text": "篠宮さんは何事もなく歩いていた。半歩前。小さな歩幅。静かな足音。メモ帳を鞄にしまい、両手をコートのポケットに入れている。"}, {"id": "ch12-s02-p114", "type": "text", "text": "「篠宮さん」"}, {"id": "ch12-s02-p115", "type": "text", "text": "「はい」"}, {"id": "ch12-s02-p116", "type": "text", "text": "振り返った。黒髪のボブカットが揺れた。墨色の瞳。表情のない顔。表情がないのではなく、表情の振幅が狭い。"}, {"id": "ch12-s02-p117", "type": "text", "text": "「何か」"}, {"id": "ch12-s02-p118", "type": "text", "text": "「——いや。何でもない」"}, {"id": "ch12-s02-p119", "type": "text", "text": "何でもないはずだった。光の加減。目の疲れ。それだけのはずだった。"}, {"id": "ch12-s02-p120", "type": "text", "text": "しかし、耳の位置にあるものが、微かに鳴った。鳴ったというのは正確ではない。響いた。何かが引っかかっている。引っかかりの正体がわからない。わからないものを、保留した。"}, {"id": "ch12-s02-p121", "type": "text", "text": "篠宮さんは前を向いて歩き始めた。俺はその半歩後ろについた。"}, {"id": "ch12-s02-p122", "type": "text", "text": "馬車の停留所まで、あと十分ほど歩く。外円区の冷たい風の中を、二人で歩いた。篠宮さんの足音が聞こえない。俺の足音だけが土道に落ちている。"}, {"id": "ch12-s02-p123", "type": "text", "text": "耳の中の引っかかりは、消えなかった。"}]}, {"chapter": 12, "chapterTitle": "冬の足音", "scene": 3, "sceneTitle": "燈花の涙", "wordCount": "約5,200字", "paragraphs": [{"id": "ch12-s03-p001", "type": "text", "text": "外円区から戻ったのは十五時過ぎだった。"}, {"id": "ch12-s03-p002", "type": "text", "text": "馬車を降りて中円区の南の広場を抜け、鐘鋳塔に報告書のまとめを置き、管理室で計器を確認した。第三系統の出力は安定していた。南端の観測値だけが赤い。午前中にまとめた数字の列がまだ頭の中に残っている。"}, {"id": "ch12-s03-p003", "type": "text", "text": "十七時の終業鐘が鳴った。"}, {"id": "ch12-s03-p004", "type": "text", "text": "外に出ると、空が低かった。十一月下旬の空。日が落ちるのが早い。西の稜線にまだ橙の筋が残っていたが、頭上はすでに紺に変わり始めていた。気温が下がっている。息が白くなるかならないかの境目。外円区の風の方が冷たかったが、中円区にも冬の匂いは届いていた。"}, {"id": "ch12-s03-p005", "type": "text", "text": "鐘鋳塔を出て、教室棟の横を通った。"}, {"id": "ch12-s03-p006", "type": "text", "text": "中庭が見えた。"}, {"id": "ch12-s03-p007", "type": "text", "text": "教室棟と食堂の間にある小さな空間。中央に残響桜の老木が一本。四月に見た時は薄紫の花弁が枝を覆っていた。九月には金色の紅葉。今は——枝だけだった。葉はほとんど落ちていた。地面に積もった落葉は乾いて、茶色く縮れている。幹と枝だけの残響桜の輪郭が、夕暮れの空を背にして黒い線を引いていた。"}, {"id": "ch12-s03-p008", "type": "text", "text": "その根元に、人がいた。"}, {"id": "ch12-s03-p009", "type": "text", "text": "ベンチではなかった。残響桜の幹のすぐ横。地面に直接座っている。膝を抱えて、背中を幹に預けていた。"}, {"id": "ch12-s03-p010", "type": "text", "text": "栗色のポニーテール。黄色いゴム。"}, {"id": "ch12-s03-p011", "type": "text", "text": "燈花だった。"}, {"id": "ch12-s03-p012", "type": "text", "text": "立ち止まった。"}, {"id": "ch12-s03-p013", "type": "text", "text": "食堂で見た燈花の顔が浮かんだ。今朝の八時。食堂の入口に立っていた燈花。色のない顔。表情のない顔。「灯里村の近く」という誰かの言葉を聞いて、布リングに触れて、廊下を早足で去った後ろ姿。"}, {"id": "ch12-s03-p014", "type": "text", "text": "あの後、俺は燈花を追わなかった。情報を取ることを選んだ。霜月さんに報告を聞き、データを整理し、篠宮さんと外円区に行き、消滅した農地を見て、八人分の記録を取って帰ってきた。"}, {"id": "ch12-s03-p015", "type": "text", "text": "九時間。燈花を見てから九時間が経っていた。"}, {"id": "ch12-s03-p016", "type": "text", "text": "中庭に足を踏み入れた。落葉を踏む音がした。乾いた葉が砕ける小さな音。"}, {"id": "ch12-s03-p017", "type": "text", "text": "燈花の肩が動いた。"}, {"id": "ch12-s03-p018", "type": "text", "text": "振り返った。"}, {"id": "ch12-s03-p019", "type": "text", "text": "琥珀色の目が俺を見ていた。"}, {"id": "ch12-s03-p020", "type": "text", "text": "目が赤かった。目の縁が腫れていた。頬に涙の跡が二筋。鼻の先が赤い。ポニーテールが乱れている。結び目が緩んで、後れ毛が頬に張りついていた。"}, {"id": "ch12-s03-p021", "type": "text", "text": "泣いていた。"}, {"id": "ch12-s03-p022", "type": "text", "text": "俺が来る前から、ずっと泣いていた。"}, {"id": "ch12-s03-p023", "type": "text", "text": "燈花の右手が左薬指に触れた。布リング。ほつれの長さは——あの夏の灯篭流しの夜に見た一センチよりもさらに伸びていた。布の繊維が二本、指から垂れている。"}, {"id": "ch12-s03-p024", "type": "text", "text": "「あ」"}, {"id": "ch12-s03-p025", "type": "text", "text": "燈花の口が開いた。俺を認識した声。声がかすれていた。泣いた後の喉。"}, {"id": "ch12-s03-p026", "type": "text", "text": "「蓮くん」"}, {"id": "ch12-s03-p027", "type": "text", "text": "名前を呼ばれた。声が低かった。食堂で「蓮くーん」と叫ぶ声とも、喫茶「残響」で笑いながら呼ぶ声とも違う。喉の乾いた、擦れた声。"}, {"id": "ch12-s03-p028", "type": "text", "text": "俺は何も言わずに近づいた。"}, {"id": "ch12-s03-p029", "type": "text", "text": "残響桜の根元。燈花が座っている場所の横。落葉の上に、膝を折って座った。五月に中円公園のベンチで隣に座ったのと同じ距離。五十センチ。肩は触れない。手も届かない。けれど声は聞こえる距離。"}, {"id": "ch12-s03-p030", "type": "text", "text": "燈花が袖で目の下を拭った。制服のジャケットの袖が涙で濡れていた。何度も拭いた跡。"}, {"id": "ch12-s03-p031", "type": "text", "text": "「……ごめん。変なとこ」"}, {"id": "ch12-s03-p032", "type": "text", "text": "言いかけて、止まった。"}, {"id": "ch12-s03-p033", "type": "text", "text": "灯篭流しの夜と同じ言葉だった。あの時は「変なとこ見せちゃった」と言って、笑おうとして、笑顔が完成しなかった。今は「変なとこ」の先が出てこなかった。笑おうとする力がなかった。"}, {"id": "ch12-s03-p034", "type": "text", "text": "燈花が膝の上に顔を伏せた。ポニーテールが横に流れて、首筋が見えた。首筋が白い。寒さのせいか、泣いたせいか。"}, {"id": "ch12-s03-p035", "type": "text", "text": "沈黙が落ちた。"}, {"id": "ch12-s03-p036", "type": "text", "text": "残響桜の枝が風に揺れた。葉のない枝は音が少ない。枝同士が擦れる硬い音だけが頭上で鳴っている。地面に落ちた枯葉が風に巻き上がって、二枚ほど燈花の膝に落ちた。"}, {"id": "ch12-s03-p037", "type": "text", "text": "肋骨の内側が、重かった。"}, {"id": "ch12-s03-p038", "type": "text", "text": "八月の喫茶「残響」で燈花の名前を呼んだ時に生まれた温かさ。その同じ場所が、今は重い。温かさの正体は知らないままだ。けれど、重さの正体はわかる。燈花が泣いていて、俺がそれを見ていて、何もできない。その重さ。"}, {"id": "ch12-s03-p039", "type": "text", "text": "燈花が顔を上げた。"}, {"id": "ch12-s03-p040", "type": "text", "text": "赤い目が俺を見ていた。まっすぐ。涙が目の縁に溜まっている。落ちるか落ちないかの量。夕暮れの残光が燈花の瞳の表面で揺れていた。"}, {"id": "ch12-s03-p041", "type": "text", "text": "「……蓮くん」"}, {"id": "ch12-s03-p042", "type": "text", "text": "「うん」"}, {"id": "ch12-s03-p043", "type": "text", "text": "「あたし、あの子の顔も、だんだんわからなくなってきてるの」"}, {"id": "ch12-s03-p044", "type": "text", "text": "声が震えていた。"}, {"id": "ch12-s03-p045", "type": "text", "text": "灯篭流しの夜に聞いた声を覚えている。「あたし……あの子の名前が……思い出せないの」。あの時、燈花は名前を失いかけていた。今は——"}, {"id": "ch12-s03-p046", "type": "text", "text": "「目の色が、茶色だったのは覚えてる。でも目の形が。笑った時にどんなふうに細くなるか。鼻の形。耳のかたち。全部、ぼやけてきてる」"}, {"id": "ch12-s03-p047", "type": "text", "text": "燈花の左手が布リングを撫でていた。親指が布の上を滑っている。ほつれた繊維が指に引っかかるたびに、微かに揺れる。あの夏より布が細くなっていた。約束の印が、痩せていた。"}, {"id": "ch12-s03-p048", "type": "text", "text": "「夏にはまだ、目を閉じれば浮かんでた。秋に入ってから、ちょっとずつ。おとといの夜、布団の中で思い出そうとして、顔の真ん中あたりがぼんやりしてた。口元と目は——わかるけど、それがちゃんと繋がらない。パーツだけが浮かんで、一枚の顔にならない」"}, {"id": "ch12-s03-p049", "type": "text", "text": "燈花の呼吸が浅くなっていた。言葉を出すたびに息が乱れている。"}, {"id": "ch12-s03-p050", "type": "text", "text": "「今朝、灯里村の近くで消滅があったって聞いて。あの辺の畑、あたしたちが小さい頃に走り回ってた場所の近くで」"}, {"id": "ch12-s03-p051", "type": "text", "text": "声が途切れた。"}, {"id": "ch12-s03-p052", "type": "text", "text": "燈花が目を閉じた。睫毛が震えていた。"}, {"id": "ch12-s03-p053", "type": "text", "text": "「思い出そうとした。あの子の顔。畑で一緒にいた時の顔。走ってる時の。笑ってる時の」"}, {"id": "ch12-s03-p054", "type": "text", "text": "目を開けた。涙がこぼれた。頬を一筋、伝い落ちた。"}, {"id": "ch12-s03-p055", "type": "text", "text": "「出てこなかった」"}, {"id": "ch12-s03-p056", "type": "text", "text": "声が落ちた。"}, {"id": "ch12-s03-p057", "type": "text", "text": "「もうすぐ……声も忘れちゃうかも」"}, {"id": "ch12-s03-p058", "type": "text", "text": "燈花の肩が震えた。灯篭流しの夜と同じ震え方。声を殺そうとして、喉の筋肉を締めている。けれど完全には止められない。呼吸の隙間から、かすれた音が漏れていた。"}, {"id": "ch12-s03-p059", "type": "text", "text": "灯篭流しの夜。俺は三歩の距離を詰めて横に座った。言葉を組み立てようとして、出たのは「天城さん」の三文字だけだった。感情がある。言葉がある。二つを繋ぐ回路が、まだ足りない。"}, {"id": "ch12-s03-p060", "type": "text", "text": "あの時の「まだ」は——今もまだ、なのだろうか。"}, {"id": "ch12-s03-p061", "type": "text", "text": "俺は燈花の横に座っている。五十センチ。あの夜と同じ距離。けれど呼び方が変わった。「天城さん」ではなく「燈花」と呼べるようになった。呼べるようになったことは、何かが変わったということだ。"}, {"id": "ch12-s03-p062", "type": "text", "text": "言葉を探した。"}, {"id": "ch12-s03-p063", "type": "text", "text": "喉の奥に、塊がある。伝えたいことの塊。形がない。形をつけなければ声にならない。回路が足りないのは変わっていない。けれど、あの夏より少しだけ、塊の輪郭が見えている。"}, {"id": "ch12-s03-p064", "type": "text", "text": "口を開けた。"}, {"id": "ch12-s03-p065", "type": "text", "text": "「……俺には、忘れた記憶がたくさんある」"}, {"id": "ch12-s03-p066", "type": "text", "text": "声が出ていた。低い声。自分でも小さいと思った。けれど燈花の耳に届く音量はあった。"}, {"id": "ch12-s03-p067", "type": "text", "text": "燈花の震えが止まった。目がこちらに向いていた。赤い目。涙の跡。夕暮れの残光。"}, {"id": "ch12-s03-p068", "type": "text", "text": "「だから……燈花の気持ちが、わかるとは言えない」"}, {"id": "ch12-s03-p069", "type": "text", "text": "桜の下の弁当の日を思い出した。五月。俺は「忘れたことを悲しいとも悔しいとも思えない」と思った。忘れた記憶がそもそもないのだから、喪失の実感がない。燈花は違う。忘れたくないのに忘れていく。その過程を、体が知っている。"}, {"id": "ch12-s03-p070", "type": "text", "text": "あの時と同じだった。俺の「わからない」と燈花の「思い出せない」は同じものではない。"}, {"id": "ch12-s03-p071", "type": "text", "text": "だから「わかる」とは言わない。"}, {"id": "ch12-s03-p072", "type": "text", "text": "「でも、忘れていくのが怖いということは……わかる」"}, {"id": "ch12-s03-p073", "type": "text", "text": "外円区で見た白い光。消滅した場所。地面が「ない」。存在がそこで終わっている。あの場所の前で、俺の体は震えた。理由のない動悸。左手首のブレスレットの下で脈が跳ねた。体が「知っている」と言っていた。頭は何も知らない。けれど体は知っている。"}, {"id": "ch12-s03-p074", "type": "text", "text": "忘れていることすら知らない。その恐怖は、たぶん、わかる。"}, {"id": "ch12-s03-p075", "type": "text", "text": "たぶん。"}, {"id": "ch12-s03-p076", "type": "text", "text": "「……わかる」"}, {"id": "ch12-s03-p077", "type": "text", "text": "声が小さかった。確信のない「わかる」。「たぶん」を飲み込んだ「わかる」。けれど、言った。"}, {"id": "ch12-s03-p078", "type": "text", "text": "燈花が俺を見ていた。"}, {"id": "ch12-s03-p079", "type": "text", "text": "涙が止まっていた。止めたのではなく、止まっていた。琥珀色の目が俺を見ている。赤い目の中で、何かが動いていた。判断がつかない何か。"}, {"id": "ch12-s03-p080", "type": "text", "text": "燈花が袖で頬を拭いた。一度。二度。三度目で涙の跡がかすれた。鼻を啜った。"}, {"id": "ch12-s03-p081", "type": "text", "text": "「……ありがとう、蓮くん」"}, {"id": "ch12-s03-p082", "type": "text", "text": "声がかすれていた。低いまま。けれど震えは消えていた。喉を締めている力が、少しだけ緩んだ声。"}, {"id": "ch12-s03-p083", "type": "text", "text": "灯篭流しの夜、燈花は「ごめん、変なとこ見せちゃった」と言った。笑おうとして、笑えなかった。「大丈夫」と言った。大丈夫ではなかった。"}, {"id": "ch12-s03-p084", "type": "text", "text": "今の燈花は「ごめん」とは言わなかった。「大丈夫」とも言わなかった。"}, {"id": "ch12-s03-p085", "type": "text", "text": "「ありがとう」だった。"}, {"id": "ch12-s03-p086", "type": "text", "text": "その違いが何を意味するのかは、まだわからない。けれど、肋骨の内側の重さが、ほんの少しだけ変わった。重さの質が変わった。苦しいだけの重さから、別の何かが混じった重さに。名前はつけられない。"}, {"id": "ch12-s03-p087", "type": "divider", "text": "---"}, {"id": "ch12-s03-p088", "type": "choice_header", "text": "【選択肢】\n▶ そばにいる\n▶ 時間をおく"}, {"id": "ch12-s03-p089", "type": "divider", "text": "---"}, {"id": "ch12-s03-p090", "type": "text", "text": "残響桜の枝が風に軋んだ。幹のない枝が夕暮れの空に線を引いている。五月には花があった。九月には金の葉があった。十一月の終わりには何もない。幹と枝だけ。けれど木はまだここにある。"}, {"id": "ch12-s03-p091", "type": "text", "text": "燈花が言ったことを覚えている。あの五月の昼、桜の下で。「葉桜も好きだよ。花が散った後も木はちゃんとあるでしょ」。"}, {"id": "ch12-s03-p092", "type": "text", "text": "花も葉も落とした残響桜の下に、燈花が座っている。俺がその横にいる。"}, {"id": "ch12-s03-p093", "type": "text", "text": "日が落ちた。西の橙の筋が消えて、空の全部が紺に沈んだ。中庭に灯りはなかった。教室棟の窓から漏れる明かりが、石畳の端を薄く照らしているだけ。残響桜の幹が暗くなり、枝のシルエットだけが空に浮かんでいた。"}, {"id": "ch12-s03-p094", "type": "text", "text": "燈花が立ち上がった。"}, {"id": "ch12-s03-p095", "type": "text", "text": "膝についた落葉を手で払った。ポニーテールの結び目を直した。乱れていた後れ毛を耳の後ろに挟んだ。"}, {"id": "ch12-s03-p096", "type": "text", "text": "俺も立った。"}, {"id": "ch12-s03-p097", "type": "text", "text": "燈花が俺を見た。暗くなった中庭で、教室棟の窓の明かりが燈花の顔を横から照らしていた。目はまだ赤い。頬の色が戻り始めていた。"}, {"id": "ch12-s03-p098", "type": "text", "text": "「……ご飯、食べよっか」"}, {"id": "ch12-s03-p099", "type": "text", "text": "声が低かった。いつもの音量の六割ほど。けれど「ごめん」でも「大丈夫」でもなかった。「ご飯を食べよう」。天城燈花の、一番根にある言葉。"}, {"id": "ch12-s03-p100", "type": "text", "text": "「うん」"}, {"id": "ch12-s03-p101", "type": "text", "text": "燈花が食堂の方に歩き出した。俺はその半歩横についた。"}, {"id": "ch12-s03-p102", "type": "text", "text": "落葉を踏む音が二人分。乾いた枯葉が足の下で砕ける。食堂の窓から漏れる明かりが、石畳の上を伸びてきていた。温かい光。夕食の蒸気の匂いが、冷えた空気の中をかすかに漂っている。"}, {"id": "ch12-s03-p103", "type": "text", "text": "燈花の足音がある。俺の足音がある。二つの足音が、食堂に向かって鳴っていた。"}]}, {"chapter": 12, "chapterTitle": "冬の足音", "scene": 4, "sceneTitle": "5年前と同じ", "wordCount": "約5,100字", "paragraphs": [{"id": "ch12-s04-p001", "type": "text", "text": "食堂を出たのは十九時過ぎだった。"}, {"id": "ch12-s04-p002", "type": "text", "text": "燈花と食事をしている間、会話は少なかった。焼き鯖定食を食べた。味噌汁を飲んだ。燈花はおかわりをしなかった。いつもは白米を一杯半は食べる人が、一杯目の途中で箸を置いた。「ごちそうさま」の声は低かった。食堂を出る時に「じゃあね」と言って、寮の方に歩いていった。背中が小さかった。"}, {"id": "ch12-s04-p003", "type": "text", "text": "補佐官舎に戻った。"}, {"id": "ch12-s04-p004", "type": "text", "text": "上着を脱いで、机の上に今日のデータ整理の続きを広げた。午前中に霜月さんの机に置いた報告書とは別に、外円区から戻ってから追加で発生した観測値の転記が残っていた。南端の定点観測値。午後十四時の数値。十六時の数値。二時間で0.2ポイント上がっている。誤差の範囲か。誤差ではないか。判断がつかなかった。"}, {"id": "ch12-s04-p005", "type": "text", "text": "判断を持ち越すなら、霜月さんに渡す方が早い。"}, {"id": "ch12-s04-p006", "type": "text", "text": "上着を着直した。鐘鋳塔に戻った。"}, {"id": "ch12-s04-p007", "type": "break", "text": "◇"}, {"id": "ch12-s04-p008", "type": "text", "text": "夜の鐘鋳塔は昼と空気が違う。"}, {"id": "ch12-s04-p009", "type": "text", "text": "一階の管理室は無人だった。計器の残響灯が青白い光を壁に落としている。深夜モードではないが、昼間より輝度が落ちている。十九時の鐘鋳塔。業務時間は終わっている。しかし霜月さんがいる時、この塔の業務時間は終わらない。"}, {"id": "ch12-s04-p010", "type": "text", "text": "階段を上がった。二階。三階。石段の冷たさが靴底を通して届く。十一月の夜の石は、夕方よりさらに一段冷えていた。"}, {"id": "ch12-s04-p011", "type": "text", "text": "三階の通路。研究区画。残響灯が壁面で不規則に並んでいる。精密計器のために湿度管理された空気。乾いている。鼻の奥が乾く。"}, {"id": "ch12-s04-p012", "type": "text", "text": "霜月さんの研究室の鉄扉の下に、光が漏れていた。"}, {"id": "ch12-s04-p013", "type": "text", "text": "いる。"}, {"id": "ch12-s04-p014", "type": "text", "text": "鉄扉を三回叩いた。拳で。間隔を空けて。先月と同じ叩き方。"}, {"id": "ch12-s04-p015", "type": "text", "text": "二秒。"}, {"id": "ch12-s04-p016", "type": "text", "text": "「入りなさい」"}, {"id": "ch12-s04-p017", "type": "text", "text": "声。低い。しかし声量は普段と変わらなかった。夜でも変わらない声。"}, {"id": "ch12-s04-p018", "type": "text", "text": "鉄扉を引いた。鉄の摩擦音が通路に短く響いた。"}, {"id": "ch12-s04-p019", "type": "text", "text": "研究室の中。"}, {"id": "ch12-s04-p020", "type": "text", "text": "モニタが一台、点いていた。南端蝕域活動指数の折れ線グラフ。赤い線。七月から十一月下旬まで。赤い線は先月見た時よりさらに上がっていた。十月の17パーセント増が、十一月には——目測で25から28。数字を正確に読むには画面に近づく必要があった。"}, {"id": "ch12-s04-p021", "type": "text", "text": "もう一台のモニタには地図が映っていた。アルケミラ島の同心円地図。南端の蝕域境界線に赤い点が三つ。今朝の消滅地点と、それ以前の二箇所だろう。赤い点は、外から内に向かって並んでいた。"}, {"id": "ch12-s04-p022", "type": "text", "text": "霜月さんが机の前に立っていた。"}, {"id": "ch12-s04-p023", "type": "text", "text": "座っていなかった。先月も先々月も、研究室にいる霜月さんは椅子に座っていた。背筋を伸ばし、椅子の背もたれに背中をつけず、机に向かっている姿。今日は違った。地図のモニタの前に立っていた。白いロングコート。銀髪のハーフアップ。右手に記録用紙を持ち、左手がモニタの画面を指していた。指先が南端の赤い点の一つに触れていた。"}, {"id": "ch12-s04-p024", "type": "text", "text": "俺が入ってきたことで、指が離れた。"}, {"id": "ch12-s04-p025", "type": "text", "text": "「追加データです。今日の午後の南端定点観測値、十四時と十六時の分を転記しました」"}, {"id": "ch12-s04-p026", "type": "text", "text": "記録用紙を差し出した。霜月さんが受け取った。目が紙の上に落ちた。数字を読んでいる。三秒。"}, {"id": "ch12-s04-p027", "type": "text", "text": "「……0.2ポイント」"}, {"id": "ch12-s04-p028", "type": "text", "text": "声が低かった。数字を確認した声。しかし「0.2ポイント」の後に、声が続かなかった。普段なら「誤差の範囲だ」か「経過を見る」のどちらかが来る。どちらも来なかった。"}, {"id": "ch12-s04-p029", "type": "text", "text": "霜月さんが記録用紙を机の上に置いた。机の上は乱れていなかった。ペンが記録用紙と平行に置かれている。蓋はついていた。紅茶のカップが右端にある。冷めている。湯気がない。飲みかけ。先月の深夜点検の時と同じ配置。しかし今日は、カップの隣にもう一つ——小さな書類の束があった。見たことのない書類だった。管理局のロゴが入った表紙。「定例会議議事録」と印字されている。"}, {"id": "ch12-s04-p030", "type": "text", "text": "議事録。"}, {"id": "ch12-s04-p031", "type": "text", "text": "今日の朝、報告室で霜月さんが言っていた。「次回定例会議で検討する」と上層部が返答したこと。次回は来月。その定例会議の過去の議事録を、霜月さんは引き出している。"}, {"id": "ch12-s04-p032", "type": "text", "text": "「用件はそれだけか」"}, {"id": "ch12-s04-p033", "type": "text", "text": "霜月さんの声が戻った。業務口調。"}, {"id": "ch12-s04-p034", "type": "text", "text": "「はい。——いえ」"}, {"id": "ch12-s04-p035", "type": "text", "text": "足が止まった。出ようとして、止まった。"}, {"id": "ch12-s04-p036", "type": "text", "text": "午前中の報告室で、霜月さんは「対応が遅い」と言った。「五年前と同じだ」と言った。「天城は」と言いかけて止めた。あの時の声が、まだ耳に残っている。"}, {"id": "ch12-s04-p037", "type": "text", "text": "朝の声と、今の声が違う。朝の声には歯を食いしばった跡があった。今の声は平らだ。平らに戻している。戻すことに力を使っている人の平らさ。"}, {"id": "ch12-s04-p038", "type": "text", "text": "「霜月さんは、前にもこういうことが」"}, {"id": "ch12-s04-p039", "type": "text", "text": "口に出していた。"}, {"id": "ch12-s04-p040", "type": "text", "text": "出してから気づいた。「前にも」は、今朝の報告室で聞いた「五年前と同じだ」に引かれて出た言葉だった。「こういうこと」は——上層部がデータを無視すること。危険を示す数字があるのに、「通常の範囲内」として動かないこと。その構造を指していた。"}, {"id": "ch12-s04-p041", "type": "text", "text": "聞いたのは俺の判断だったのか。鳩尾の上の温度に押されて出た声だったのか。区別がつかなかった。"}, {"id": "ch12-s04-p042", "type": "text", "text": "霜月さんの肩が動いた。"}, {"id": "ch12-s04-p043", "type": "text", "text": "小さな動き。白いコートの肩の線が、わずかに上がって、下がった。呼吸を止めて、吐いた。十月の研究室で「また始まる」が漏れた時と同じ動き。"}, {"id": "ch12-s04-p044", "type": "text", "text": "ラベンダーの瞳が俺を見た。"}, {"id": "ch12-s04-p045", "type": "text", "text": "三秒。"}, {"id": "ch12-s04-p046", "type": "text", "text": "硬い目。鉱石の断面。いつもの目——のはずだった。しかし硬さの下にある層が浮いていた。先月、千歳のデータを見せた時に浮いたのと同じ層。あの時は声が震えて、止めた。今は声が出る前に、目の奥に先に浮いた。"}, {"id": "ch12-s04-p047", "type": "text", "text": "霜月さんが目を閉じた。"}, {"id": "ch12-s04-p048", "type": "text", "text": "二回目だった。この人が目を閉じるところを見るのは、先月が初めてで、今日が二回目。先月は千歳のデータの前で、「私は答えなければならないか」と言う前に閉じた。今は違う。俺の問いを受けて閉じた。"}, {"id": "ch12-s04-p049", "type": "text", "text": "目を閉じた顔は、霜月さんの顔の中で最も防御が薄かった。いつもの硬い目がないと、まぶたと睫毛と、顔の骨格だけが残る。白い肌。銀色の前髪が右目にかかっている。その下で、まぶたが微かに動いた。眼球が閉じたまぶたの裏側で何かを追っている。"}, {"id": "ch12-s04-p050", "type": "text", "text": "目が開いた。"}, {"id": "ch12-s04-p051", "type": "text", "text": "「……五年前」"}, {"id": "ch12-s04-p052", "type": "text", "text": "声が低かった。霜月さんの声が低くなる時は二種類ある。業務で数値を報告する時の低さと、中にあるものが外に出る時の低さ。今の声は後者だった。"}, {"id": "ch12-s04-p053", "type": "text", "text": "「同じことがあった」"}, {"id": "ch12-s04-p054", "type": "text", "text": "短い。六音節。しかし六音節の中に、五年分の重さが載っていた。"}, {"id": "ch12-s04-p055", "type": "text", "text": "「同じデータ」"}, {"id": "ch12-s04-p056", "type": "text", "text": "霜月さんの視線が、赤い折れ線グラフのモニタに向いた。"}, {"id": "ch12-s04-p057", "type": "text", "text": "「同じ対応」"}, {"id": "ch12-s04-p058", "type": "text", "text": "視線が定例会議の議事録に落ちた。"}, {"id": "ch12-s04-p059", "type": "text", "text": "「そして——」"}, {"id": "ch12-s04-p060", "type": "text", "text": "声が止まった。"}, {"id": "ch12-s04-p061", "type": "text", "text": "先月は0.5秒で止まった。先々月は「また始まる」が無意識に漏れた。先月は「五年前と同じだ」で声が震えた。今日の停止は、それらと質が違った。言葉を選んでいるのではなかった。止めようとしているのでもなかった。声の先にあるものが重すぎて、喉が詰まっていた。"}, {"id": "ch12-s04-p062", "type": "text", "text": "二秒。"}, {"id": "ch12-s04-p063", "type": "text", "text": "「——同じ結末になった」"}, {"id": "ch12-s04-p064", "type": "text", "text": "声が出た。低い。低い声の表面に、薄い亀裂が走っていた。先月の震えとは違う。震えは体の反射だった。今日の亀裂は、霜月さんが五年間凍らせていたものの表面に、意志で入れた罅だった。漏れたのではない。出した。不完全で、途切れ途切れだが、出した。"}, {"id": "ch12-s04-p065", "type": "text", "text": "霜月さんの左手が動いた。"}, {"id": "ch12-s04-p066", "type": "text", "text": "左耳。青い石のピアス。指先がピアスに触れた。深夜の点検で「きれいですね」と言った時は、手のひらで耳を覆った。防御の速度だった。今は違う。指先で触れている。覆っているのではなく、確認している。まだそこにあるかを確かめるように。"}, {"id": "ch12-s04-p067", "type": "text", "text": "「同じ結末」の先を、霜月さんは言わなかった。集落が消えたこと。数百人が死んだこと。データが改竄されたこと。責任を押し付けられたこと。何一つ具体的には語らなかった。"}, {"id": "ch12-s04-p068", "type": "text", "text": "けれど、「同じ」の三文字が全てを含んでいた。"}, {"id": "ch12-s04-p069", "type": "text", "text": "五年前と同じデータ。同じ対応。同じ結末。ならば五年前にも今と同じ赤い線があった。同じ「通常の変動の範囲内」があった。そしてその先に——消えた場所があった。"}, {"id": "ch12-s04-p070", "type": "text", "text": "今朝、外円区で見た白い光。存在が終わる境界。あの「ない」が、五年前にもあった。もっと大きなかたちで。"}, {"id": "ch12-s04-p071", "type": "text", "text": "背中の奥が重くなった。"}, {"id": "ch12-s04-p072", "type": "text", "text": "氷華＝背中の奥。コーヒーの温かさと青い石と一秒半の左手が刻まれた場所。「また始まる」の重さが積まれた場所。「五年前と同じだ」で震えた声が残っている場所。今、その場所に、「同じ結末になった」の六語が落ちた。"}, {"id": "ch12-s04-p073", "type": "text", "text": "霜月さんが何を抱えているのか、完全にはわからない。五年前の何が具体的にどう起きたのか。霜月さんがその中でどこに立っていたのか。まだ見えない。見えないが、背中の奥が重い。この重さは想像ではない。霜月さんの声の亀裂と、ピアスに触れる指先と、閉じて開いた目の奥にあったものが、背中の奥に届いている。"}, {"id": "ch12-s04-p074", "type": "divider", "text": "---"}, {"id": "ch12-s04-p075", "type": "choice_header", "text": "【選択肢】\n▶ 詳しく聞かせてください\n▶ 俺にできることがあれば"}, {"id": "ch12-s04-p076", "type": "divider", "text": "---"}, {"id": "ch12-s04-p077", "type": "text", "text": "沈黙が落ちた。"}, {"id": "ch12-s04-p078", "type": "text", "text": "研究室の空気が重い。モニタの赤い線と、地図の赤い点と、霜月さんの白いコートと、残響灯の青白い光。色の少ない部屋。"}, {"id": "ch12-s04-p079", "type": "text", "text": "霜月さんの左手がピアスから離れた。離れた手が、コートのポケットに入った。"}, {"id": "ch12-s04-p080", "type": "text", "text": "三秒。"}, {"id": "ch12-s04-p081", "type": "text", "text": "「……データの追加分、確認した。明朝の定時報告に反映しなさい」"}, {"id": "ch12-s04-p082", "type": "text", "text": "声が戻っていた。"}, {"id": "ch12-s04-p083", "type": "text", "text": "業務口調。平らな声。「同じ結末になった」の亀裂が嘘のように、均された声。蓋を閉め直す速度。深夜の点検で「仕事に関係ない」と返した速度と同じだった。"}, {"id": "ch12-s04-p084", "type": "text", "text": "しかし——同じではなかった。"}, {"id": "ch12-s04-p085", "type": "text", "text": "声は戻った。口調は戻った。けれど、目が違った。ラベンダーの瞳が俺を見ていた。硬さは戻っていた。鉱石の断面。けれど断面の角度が変わっていた。先月までは光を反射して跳ね返す角度。今日は——ほんの少しだけ、光を奥に通す角度。"}, {"id": "ch12-s04-p086", "type": "text", "text": "違いは微かだった。目の構造が変わったわけではない。瞳孔の大きさが変わったわけでもない。ただ、視線の質が変わっていた。霜月さんが俺を見る時の、見方が。"}, {"id": "ch12-s04-p087", "type": "text", "text": "何と名づければいいかわからない。"}, {"id": "ch12-s04-p088", "type": "text", "text": "けれど、深夜にコーヒーを二杯淹れた時の沈黙と、先月「五年前と同じだ」で声が震えた時の沈黙と、今日目を閉じて開いた後に「同じ結末になった」を口にした時の沈黙は、全部違う沈黙だった。一つ一つ、防御の厚さが変わっている。厚さが減っている。"}, {"id": "ch12-s04-p089", "type": "text", "text": "一枚ずつ。"}, {"id": "ch12-s04-p090", "type": "text", "text": "「……了解しました。明朝に」"}, {"id": "ch12-s04-p091", "type": "text", "text": "「ああ」"}, {"id": "ch12-s04-p092", "type": "text", "text": "返事。一音。業務の返事。けれど今朝の報告室での「ああ」よりも、半拍だけ遅かった。遅い「ああ」。何かを飲み込んだ後の「ああ」。"}, {"id": "ch12-s04-p093", "type": "text", "text": "研究室を出た。鉄扉を引いた。"}, {"id": "ch12-s04-p094", "type": "text", "text": "閉まる直前に、もう一度中を見た。先月と同じだった。白いコートの背中が見えた。モニタの光を受けて、コートの肩が赤い線に染まっている。地図の赤い点が三つ。銀髪が残響灯の光を受けている。"}, {"id": "ch12-s04-p095", "type": "text", "text": "左耳のピアスの青い石が、赤い光の中でも青かった。"}, {"id": "ch12-s04-p096", "type": "text", "text": "鉄扉が閉まった。"}, {"id": "ch12-s04-p097", "type": "text", "text": "三階の通路を歩いた。階段を降りた。一階。外。十一月の夜の空気が顔に当たった。冷たい。息が白くなった。白い息が暗闇に溶けて消えた。"}, {"id": "ch12-s04-p098", "type": "text", "text": "食堂からの帰りに見た空よりも、星が多かった。二十一時。灯籠通りの灯籠は消灯時間が近い。"}, {"id": "ch12-s04-p099", "type": "text", "text": "歩きながら、背中の奥にあるものを確認した。"}, {"id": "ch12-s04-p100", "type": "text", "text": "重さが増えていた。コーヒーの温かさ。青い石。一秒半の左手。「また始まる」。声が震えた0.5秒。ペンの蓋の位置。赤い線の17パーセント。——そして今日、「同じ結末になった」の声の亀裂と、ピアスに触れる指先と、光を少しだけ通すようになった瞳の角度が加わった。"}, {"id": "ch12-s04-p101", "type": "text", "text": "霜月さんは、何かを出そうとしていた。"}, {"id": "ch12-s04-p102", "type": "text", "text": "「また始まる」は漏れた言葉だった。「五年前と同じだ」は声の震えが滲ませた言葉だった。今日の「同じ結末になった」は——漏れたのでも滲んだのでもなかった。自分で出した言葉だった。不完全で、その先を語れなくて、すぐに蓋を閉め直したけれど。"}, {"id": "ch12-s04-p103", "type": "text", "text": "出した。"}, {"id": "ch12-s04-p104", "type": "text", "text": "この人は五年間、一人で抱えていたものを、少しずつ出し始めている。俺に対して。"}, {"id": "ch12-s04-p105", "type": "text", "text": "なぜ俺なのかはわからない。上司と部下の関係だから、データを共有する相手だから、という説明がつく。つくけれど、業務に必要ない情報だった。「五年前」も「同じ結末」も、今日のデータ報告には不要な言葉だった。"}, {"id": "ch12-s04-p106", "type": "text", "text": "不要な言葉を出した。"}, {"id": "ch12-s04-p107", "type": "text", "text": "背中の奥が、重い。けれど——重いだけではなかった。重さの中に、別のものが混じっていた。先月のコーヒーの温かさと同じ方角にあるもの。名前はまだない。"}, {"id": "ch12-s04-p108", "type": "text", "text": "覚えておく。霜月さんの目が閉じて、開いて、「同じ結末になった」を言った声と、ピアスに触れた指先と、角度が変わった瞳を。"}]}, {"chapter": 12, "chapterTitle": "冬の足音", "scene": 5, "sceneTitle": "追悼祭の名簿", "wordCount": "約4,200字", "paragraphs": [{"id": "ch12-s05-p001", "type": "text", "text": "十二月に入っていた。"}, {"id": "ch12-s05-p002", "type": "text", "text": "数日で空気の質が変わった。十一月下旬の「冬の匂い」は、十二月の最初の週で「冬そのもの」になった。補佐官舎を出た時に顔を叩く風が痛い。息は白い。指先は外に出して三十秒で強張る。鐘鋳塔への石畳が霜で光っていた。"}, {"id": "ch12-s05-p003", "type": "text", "text": "十七時三十分。終業鐘から一時間半。"}, {"id": "ch12-s05-p004", "type": "text", "text": "講堂の中にいた。"}, {"id": "ch12-s05-p005", "type": "text", "text": "ステンドグラスの光は、もう届いていなかった。十二月の夕方の太陽は低い。十七時を過ぎれば窓の外は紺色だった。講堂の中を照らしているのはステージ脇の残響灯だけで、天井の高い空間に青白い光が散っていた。五百席の客席は空。ステージの上にも誰もいない。"}, {"id": "ch12-s05-p006", "type": "text", "text": "音がしている。"}, {"id": "ch12-s05-p007", "type": "text", "text": "ペンが紙を走る音。一定間隔。かりかり。かり。かり。"}, {"id": "ch12-s05-p008", "type": "text", "text": "記録室で何百回と聞いた音。篠宮さんの音だった。"}, {"id": "ch12-s05-p009", "type": "text", "text": "ステージの手前、一列目の長椅子に名簿の束が広げてあった。篠宮さんと俺が、長椅子を挟んで並んで座っていた。残響灯の光が紙面を照らしている。インクの匂い。古い紙の匂い。"}, {"id": "ch12-s05-p010", "type": "text", "text": "年末追悼祭の準備。"}, {"id": "ch12-s05-p011", "type": "text", "text": "「朝霧さん。二枚目、お願いします」"}, {"id": "ch12-s05-p012", "type": "text", "text": "篠宮さんの声が、講堂の天井に吸われて消えた。"}, {"id": "ch12-s05-p013", "type": "text", "text": "「はい」"}, {"id": "ch12-s05-p014", "type": "text", "text": "二枚目の名簿を手に取った。"}, {"id": "ch12-s05-p015", "type": "text", "text": "名簿は管理局から届いた公式のものだった。今年一年間で蝕域に消された人々の名前が、日付順に並んでいる。一月。二月。三月。月ごとに区切られた横線の下に、名前と年齢と居住区が記されていた。篠宮さんが記録室の台帳と照合し、誤字や欠落がないかを確認する。俺はその補助をしていた。"}, {"id": "ch12-s05-p016", "type": "text", "text": "二枚目。四月から六月。一枚目は一月から三月だった。一枚目の名前は十四人。月に四、五人。島の人口二十五万に対して月に四人。数字としては小さい。小さいが、十四の名前には十四の人生がある。"}, {"id": "ch12-s05-p017", "type": "text", "text": "二枚目を広げた。"}, {"id": "ch12-s05-p018", "type": "text", "text": "四月。三人。五月。二人。六月。五人。ここまでは一枚目と同じような密度。"}, {"id": "ch12-s05-p019", "type": "text", "text": "三枚目を手に取った。七月から九月。"}, {"id": "ch12-s05-p020", "type": "text", "text": "七月。四人。八月。六人。九月。七人。"}, {"id": "ch12-s05-p021", "type": "text", "text": "少しずつ増えている。"}, {"id": "ch12-s05-p022", "type": "text", "text": "四枚目。十月から十一月。十二月分はまだ確定していない。"}, {"id": "ch12-s05-p023", "type": "text", "text": "十月。八人。"}, {"id": "ch12-s05-p024", "type": "text", "text": "十一月。"}, {"id": "ch12-s05-p025", "type": "text", "text": "十一月の欄を見た。"}, {"id": "ch12-s05-p026", "type": "text", "text": "——十九人。"}, {"id": "ch12-s05-p027", "type": "text", "text": "指が止まった。"}, {"id": "ch12-s05-p028", "type": "text", "text": "十九。十月の八人から倍以上。名前がびっしりと並んでいた。横線の間に収まりきらず、別紙に続いている。別紙を引いた。十一月の続き。十九人の名前の横に、居住区の欄がある。外円区。外円区。外円区。中円区。外円区。外円区。外円区——"}, {"id": "ch12-s05-p029", "type": "text", "text": "外円区が大半だった。"}, {"id": "ch12-s05-p030", "type": "text", "text": "十一月下旬の名前の中に、見覚えのある地名があった。灯里村跡地東方。今月の初めに篠宮さんと行った場所。白い光の跡と、存在が終わった農地。八人分の名前が、ここに載っている。"}, {"id": "ch12-s05-p031", "type": "text", "text": "全部で何人か。数えた。一月から十一月まで。"}, {"id": "ch12-s05-p032", "type": "text", "text": "六十八人。"}, {"id": "ch12-s05-p033", "type": "text", "text": "篠宮さんが隣でペンを走らせている。一枚目の照合はもう終わっていた。二枚目に入っている。名前の横にチェックを入れている。一つ。一つ。一つ。"}, {"id": "ch12-s05-p034", "type": "text", "text": "かりかり。"}, {"id": "ch12-s05-p035", "type": "text", "text": "規則的な音。記録室と同じ音。しかし——最後の一画が。"}, {"id": "ch12-s05-p036", "type": "text", "text": "ペンの先が紙を離れる瞬間、篠宮さんの手がわずかに揺れていた。チェックマークの末端が、紙の上で微かに乱れている。外円区で消滅した農地の記録を取った時と同じ揺れ。あの時も篠宮さんのペンは乱れなかった。乱れなかったが、最後の一画だけが震えていた。"}, {"id": "ch12-s05-p037", "type": "text", "text": "「篠宮さん」"}, {"id": "ch12-s05-p038", "type": "text", "text": "「はい」"}, {"id": "ch12-s05-p039", "type": "text", "text": "顔を上げない。ペンが動き続けている。"}, {"id": "ch12-s05-p040", "type": "text", "text": "「去年より、多いんですか」"}, {"id": "ch12-s05-p041", "type": "text", "text": "「去年は四十三人でした」"}, {"id": "ch12-s05-p042", "type": "text", "text": "声は平らだった。記録の数字を報告する声。四十三。今年は六十八。二十五人分、名簿が長くなった。"}, {"id": "ch12-s05-p043", "type": "text", "text": "「一昨年は三十一人です。その前は二十八人」"}, {"id": "ch12-s05-p044", "type": "text", "text": "毎年増えている。"}, {"id": "ch12-s05-p045", "type": "text", "text": "篠宮さんのペンが次の名前に移った。チェック。チェック。チェック。一つ一つが一人の名前で、一つ一つに篠宮さんのインクが触れている。二十三冊のメモ帳に三千六百八十人の記録を残してきた手が、今年の六十八人を確認している。"}, {"id": "ch12-s05-p046", "type": "text", "text": "耳の位置に、ペンの音がある。いつもの位置。しかしいつもより音が重かった。講堂の天井が高いせいか。名簿の数字が重いせいか。"}, {"id": "ch12-s05-p047", "type": "break", "text": "◇"}, {"id": "ch12-s05-p048", "type": "text", "text": "足音が聞こえた。"}, {"id": "ch12-s05-p049", "type": "text", "text": "講堂の後方。扉が開く音。石の床を歩く靴の音。燈花の足音は軽い。軽いが、今日は着地が普段より少しだけ遅い。足の運びが慎重になっている。"}, {"id": "ch12-s05-p050", "type": "text", "text": "「蓮くん、篠宮さん。手伝いに来たよ」"}, {"id": "ch12-s05-p051", "type": "text", "text": "声。燈花の声。"}, {"id": "ch12-s05-p052", "type": "text", "text": "八割の声量。十一月下旬に外円区で泣いた後、燈花の声は元の大きさに戻りきっていなかった。戻そうとしているのはわかる。笑顔も作っている。しかし声の天井が以前より低い。部屋を満たす声ではなく、数メートルの範囲に収まる声。"}, {"id": "ch12-s05-p053", "type": "text", "text": "「ありがとうございます、天城さん。名簿の照合を手伝っていただけると助かります」"}, {"id": "ch12-s05-p054", "type": "text", "text": "篠宮さんの声。業務の声。しかし「助かります」の語尾が平時より柔らかかった。"}, {"id": "ch12-s05-p055", "type": "text", "text": "燈花が一列目の長椅子に来た。名簿を見た。"}, {"id": "ch12-s05-p056", "type": "text", "text": "最初に目が行ったのは全体の長さだったと思う。四枚の名簿と別紙。六十八人分の名前。燈花の琥珀色の目が紙の上を滑った。上から下へ。一枚目。二枚目。三枚目。四枚目——"}, {"id": "ch12-s05-p057", "type": "text", "text": "「……こんなに」"}, {"id": "ch12-s05-p058", "type": "text", "text": "声が小さかった。"}, {"id": "ch12-s05-p059", "type": "text", "text": "さっきの「手伝いに来たよ」の声とは別の声。腹から出ていない声。喉で止まって、漏れただけの声。"}, {"id": "ch12-s05-p060", "type": "text", "text": "燈花の目が四枚目の十一月の欄に留まっていた。外円区。外円区。外円区。灯里村跡地東方。"}, {"id": "ch12-s05-p061", "type": "text", "text": "左手が動いた。薬指の布リング。食堂で灯里村の名前を聞いた時と同じ動き。"}, {"id": "ch12-s05-p062", "type": "text", "text": "二秒。"}, {"id": "ch12-s05-p063", "type": "text", "text": "燈花の手が名簿に伸びた。三枚目を持ち上げた。"}, {"id": "ch12-s05-p064", "type": "text", "text": "「あたし、これやるね。七月から九月」"}, {"id": "ch12-s05-p065", "type": "text", "text": "声が戻っていた。八割の声量。しかし手は動いている。布リングに触れた手が、今は名簿を持っている。泣いた後でも手は動く。残響桜の根元で泣いた後に、燈花はすぐに立ち上がった。あの時と同じだった。"}, {"id": "ch12-s05-p066", "type": "text", "text": "肋骨の内側が、じわりと温かくなった。"}, {"id": "ch12-s05-p067", "type": "break", "text": "◇"}, {"id": "ch12-s05-p068", "type": "text", "text": "講堂の扉が、もう一度開いた。"}, {"id": "ch12-s05-p069", "type": "text", "text": "足音が違った。燈花よりも軽い。靴底が石に触れる音が薄い。体重が少ない人間の歩き方。"}, {"id": "ch12-s05-p070", "type": "text", "text": "亜麻色のウェーブヘアが、残響灯の青白い光の中に浮かんだ。"}, {"id": "ch12-s05-p071", "type": "text", "text": "鳴海さんだった。"}, {"id": "ch12-s05-p072", "type": "text", "text": "薄桃色のリボンが右の前髪を留めている。カーディガンを肩にかけている。微笑み。いつもの微笑み。口と目がほぼ同時に動くあの穏やかな表情。"}, {"id": "ch12-s05-p073", "type": "text", "text": "「蓮さん、天城さん、篠宮さん。追悼祭の準備、わたしもお手伝いさせてください」"}, {"id": "ch12-s05-p074", "type": "text", "text": "声は穏やかだった。丁寧語。微笑み。変わっていない——表面上は。"}, {"id": "ch12-s05-p075", "type": "text", "text": "選抜公演で倒れてから三週間が経っていた。いろはが楽屋で泣いた日から三週間。鳴海さんの顔色は戻っていた。頬に血の色がある。カーディガンを押さえる指先にも、あの日ほどの力みはない。"}, {"id": "ch12-s05-p076", "type": "text", "text": "しかし俺は、数字を知っている。"}, {"id": "ch12-s05-p077", "type": "text", "text": "身体負荷指数47。入学時の四倍。体重の持続的微減。血中残響濃度の上昇。不可逆。霜月さんの声が止まった「数年以内に」の先。"}, {"id": "ch12-s05-p078", "type": "text", "text": "鳴海さんがステージ手前に来て、名簿を覗き込んだ。"}, {"id": "ch12-s05-p079", "type": "text", "text": "微笑みが消えなかった。名前の列を目で追いながら、口元の穏やかな弧を保っていた。一枚目。二枚目。三枚目。四枚目。六十八人分の名前を目で辿った後も、微笑みは維持されていた。"}, {"id": "ch12-s05-p080", "type": "text", "text": "維持されていた、という表現が正しかった。浮かんでいたのではなく、維持していた。"}, {"id": "ch12-s05-p081", "type": "text", "text": "鳴海さんが名簿から顔を上げた。"}, {"id": "ch12-s05-p082", "type": "text", "text": "講堂のステンドグラスを見上げた。暗い。十二月の夕方のステンドグラスは光を通さない。鐘鋳塔の紋様が床に描かれるのは昼間だけで、今は色のないガラスの面が天井に張りついているだけだった。"}, {"id": "ch12-s05-p083", "type": "text", "text": "「蓮さん」"}, {"id": "ch12-s05-p084", "type": "text", "text": "振り返った。鳴海さんの琥珀色の瞳が、俺を見ていた。"}, {"id": "ch12-s05-p085", "type": "text", "text": "微笑みが変わっていた。"}, {"id": "ch12-s05-p086", "type": "text", "text": "口元の弧は同じ。しかし目が違った。穏やかさの奥にあるものが、表面に近い場所まで浮いていた。決意、と呼んでいいのかわからない。けれど鳴海さんの瞳の中にある光は、残響祭の舞台裏で「歌いたい」と言った時の光と同じ角度だった。"}, {"id": "ch12-s05-p087", "type": "text", "text": "「わたし、追悼祭で歌いたいです」"}, {"id": "ch12-s05-p088", "type": "text", "text": "声は静かだった。穏やかだった。微笑みの声。しかし「歌いたい」の三文字だけが、他の言葉よりも重かった。使命の重さではなかった。「皆さんが安心してくださるなら」の重さでもなかった。灯籠通りで「歌うことが好きなんです」と言った時と同じ場所から出ている言葉だった。"}, {"id": "ch12-s05-p089", "type": "text", "text": "鳩尾の上が痛んだ。"}, {"id": "ch12-s05-p090", "type": "text", "text": "47。"}, {"id": "ch12-s05-p091", "type": "text", "text": "数字が浮かんだ。身体負荷指数47。入学時12。不可逆。数年以内に。歌うたびに命を削る。鳴海さんはそれを知らない。知らないまま、歌いたいと言っている。"}, {"id": "ch12-s05-p092", "type": "text", "text": "止めたかった。"}, {"id": "ch12-s05-p093", "type": "text", "text": "喉まで来ていた。「鳴海さん、体のことが」——その先が出なかった。出せなかった。鳴海さんが知らないことを、俺が持ち出していいのか。風祭さんが二年間黙ってきた秘密を、俺が壊していいのか。データを見て知ったことを、本人に言う権利が俺にあるのか。"}, {"id": "ch12-s05-p094", "type": "text", "text": "それ以上に——鳴海さんの目が。"}, {"id": "ch12-s05-p095", "type": "text", "text": "決意があった。穏やかな微笑みの奥に、折れない何かがあった。この目を見て「歌わないでください」と言う言葉を、俺は持っていなかった。"}, {"id": "ch12-s05-p096", "type": "text", "text": "言葉を飲み込んだ。"}, {"id": "ch12-s05-p097", "type": "text", "text": "鳩尾の上が、痛い。"}, {"id": "ch12-s05-p098", "type": "text", "text": "「……追悼祭の選曲は、管理局に申請が必要だと思います。霜月さんに確認します」"}, {"id": "ch12-s05-p099", "type": "text", "text": "出てきたのは業務の言葉だった。止められない代わりに、手続きの話をした。情けない、とは思わなかった。思う余裕がなかった。鳩尾の上が痛くて、それだけだった。"}, {"id": "ch12-s05-p100", "type": "text", "text": "鳴海さんが微笑んだ。"}, {"id": "ch12-s05-p101", "type": "text", "text": "「ありがとうございます、蓮さん」"}, {"id": "ch12-s05-p102", "type": "text", "text": "声が柔らかかった。柔らかさの中に、安堵があった。歌えること自体への安堵。止められなかったことへの安堵ではない。この人はそもそも止められることを想定していなかった。歌うことは、鳴海さんにとって確定した意志だった。"}, {"id": "ch12-s05-p103", "type": "text", "text": "「あたしも手伝う。選曲とか、準備とか」"}, {"id": "ch12-s05-p104", "type": "text", "text": "燈花の声。名簿の三枚目を確認しながら。声の大きさは八割のまま。しかし手は止まっていない。"}, {"id": "ch12-s05-p105", "type": "text", "text": "「ありがとうございます、天城さん」"}, {"id": "ch12-s05-p106", "type": "text", "text": "「名簿の照合が終わりましたら、次は読み上げ順序の確認です」"}, {"id": "ch12-s05-p107", "type": "text", "text": "篠宮さんの声。ペンが動き続けている。最後の一画の震えも続いている。"}, {"id": "ch12-s05-p108", "type": "text", "text": "四人が講堂にいた。"}, {"id": "ch12-s05-p109", "type": "text", "text": "残響灯の青白い光の中に、名簿が広がっている。六十八人分の名前。去年より二十五人長い名簿。来年はもっと長くなるかもしれない。南端の蝕域活動指数の赤い線は、まだ上がり続けている。"}, {"id": "ch12-s05-p110", "type": "text", "text": "窓の外は紺色から黒に変わりかけていた。十二月。日が短い。冬が来ている。"}, {"id": "ch12-s05-p111", "type": "text", "text": "鳴海さんがペンを持った。名簿の一枚目の端から、丁寧な字で何かを書き始めた。歌いたい曲の候補だろうか。手の動きに迷いがなかった。"}, {"id": "ch12-s05-p112", "type": "text", "text": "鳩尾の上が、まだ痛い。"}, {"id": "ch12-s05-p113", "type": "text", "text": "47。不可逆。数年以内に。"}, {"id": "ch12-s05-p114", "type": "text", "text": "覚えている。忘れられない。鳴海さんの微笑みと、データの数字が、鳩尾の上で重なって離れない。"}, {"id": "ch12-s05-p115", "type": "text", "text": "講堂の天井が高い。残響灯の光が遠い。五百の空席が暗がりの中に並んでいる。四人だけの講堂。名簿の上をペンが走る音が四つ。"}, {"id": "ch12-s05-p116", "type": "text", "text": "冬が来ている。空気が冷たい。名簿が長い。"}]}, {"chapter": 13, "chapterTitle": "鐘が揺れる夜", "scene": 1, "sceneTitle": "鐘の異変", "wordCount": "約6,200字", "paragraphs": [{"id": "ch13-s01-p001", "type": "text", "text": "体の芯が、足りない。"}, {"id": "ch13-s01-p002", "type": "text", "text": "目が覚めた理由はそれだった。四時の鐘が鳴った。鳴ったのは確かだ。音は聞こえた。けれど体の芯に届くはずの振動が、今朝は遠い。耳には届いている。皮膚には届いている。胸骨の手前で止まっている。"}, {"id": "ch13-s01-p003", "type": "text", "text": "四月からずっと、四時の鐘は体の奥まで響いてきた。深夜帯の鐘打ちは二時と五時だが、四時に予備打鐘がある。短い。一打。全力ではなく、六割程度の出力で大鐘を叩く。装置の動作確認。その一打ですら、補佐官舎の寝台にいる俺の胸骨の裏まで届いていた。届いて、数秒間、体の中心を揺らしてから消えていく。それが毎晩あった。九ヶ月間、途切れなかった。"}, {"id": "ch13-s01-p004", "type": "text", "text": "今朝は、途切れた。"}, {"id": "ch13-s01-p005", "type": "text", "text": "布団を剥いだ。冬の空気が肌に触れる。十二月。石壁の部屋の中まで冷えが浸透している。足を床に下ろすと木板の冷たさが足裏から脛まで登ってきた。息は白い。窓ガラスの表面に露が結んでいる。その向こうに、鐘鋳塔のシルエットが暗い空に浮かんでいた。残響紋の発光が見える。見えるが、いつもより淡い。"}, {"id": "ch13-s01-p006", "type": "text", "text": "制服に腕を通した。ジャケットのボタンを留めながら左手首のブレスレットの編み目に指が触れた。一瞬。いつもの動作。それから鍵束を取り、補佐官舎を出た。"}, {"id": "ch13-s01-p007", "type": "text", "text": "外は暗い。四時十分。灯籠通りの灯りは消えかけている。油灯の残り火が橙色の弱い円を足元に落としている。煉瓦舗装に霜が降りていた。靴底が踏むたびに、霜が砕ける小さな音がする。十二月の未明の空気は肺を刺す。吸い込むと鼻腔の奥が痛んだ。"}, {"id": "ch13-s01-p008", "type": "text", "text": "鐘鋳塔。白い石壁の外壁に残響紋が走っている。紋様の発光が弱い。普段の六割か七割。目で見てわかるほどの差は、技師として見過ごせない。"}, {"id": "ch13-s01-p009", "type": "text", "text": "正面入口の扉を開けた。鍵は回っていなかった。誰かが先に来ている。"}, {"id": "ch13-s01-p010", "type": "text", "text": "管理室を通過して、地下一階への階段を降りた。石段の冷たさが靴底を通して足裏に伝わる。残響灯の青白い光が壁面に落ちている。いつもの光。いつもの温度。金属と潤滑油と、湿った石の匂い。九ヶ月間で体が覚えた匂い。"}, {"id": "ch13-s01-p011", "type": "text", "text": "機構室の鉄扉が、開いていた。"}, {"id": "ch13-s01-p012", "type": "text", "text": "中に光があった。残響灯の青白い光ではない。検査灯の白い光。共鳴管の接合部に当てられた検査灯の細い光が、歯車の壁面に影を散らしている。"}, {"id": "ch13-s01-p013", "type": "text", "text": "白いコートの背中が見えた。"}, {"id": "ch13-s01-p014", "type": "text", "text": "霜月さんだった。"}, {"id": "ch13-s01-p015", "type": "text", "text": "壁面の第三系統の歯車列に向き合っている。検査灯を左手で持ち、右手で歯車の軸受け部に検査器具を当てている。銀色の髪がハーフアップからわずかに乱れていた。毛先が白いコートの襟にかかっている。普段は乱れない髪が乱れている。作業の時間が長いということだ。"}, {"id": "ch13-s01-p016", "type": "text", "text": "左耳の青い石のピアスが、検査灯の白い光を受けて揺れた。"}, {"id": "ch13-s01-p017", "type": "text", "text": "「……来たか」"}, {"id": "ch13-s01-p018", "type": "text", "text": "声。低い。平坦。いつもの声。しかし「来たか」の語尾が、いつもより0.5秒早く切れた。振り返らずに言った。検査器具を歯車から外さないまま。背中だけで俺の存在を確認している。"}, {"id": "ch13-s01-p019", "type": "text", "text": "背中の奥が、微かに動いた。霜月さんの気配を感じる位置。いつもの位置。"}, {"id": "ch13-s01-p020", "type": "text", "text": "「四時の予備打鐘の振動が弱かったので」"}, {"id": "ch13-s01-p021", "type": "text", "text": "「気づいたか」"}, {"id": "ch13-s01-p022", "type": "text", "text": "二言目も振り返らない。検査器具の先端を次の軸受けに移す。手の動きが速い。速いが、雑ではない。一つの計測に最低限の時間をかけて、即座に次へ移る。危機対応の速度だった。"}, {"id": "ch13-s01-p023", "type": "text", "text": "「何時から」"}, {"id": "ch13-s01-p024", "type": "text", "text": "「一時」"}, {"id": "ch13-s01-p025", "type": "text", "text": "三時間。深夜一時から一人でここにいる。"}, {"id": "ch13-s01-p026", "type": "text", "text": "俺は工具箱を開けた。検査灯を取り出し、霜月さんの反対側——第五系統の歯車列に向かう。全系統の確認が必要だ。それは聞かなくてもわかった。"}, {"id": "ch13-s01-p027", "type": "text", "text": "歯車に検査灯を当てた。軸受け部の回転抵抗を計器で測る。数値を読む。第五系統、正常範囲内。次。第六系統。正常範囲内。第七系統——"}, {"id": "ch13-s01-p028", "type": "text", "text": "「第三系統の駆動装置」"}, {"id": "ch13-s01-p029", "type": "text", "text": "霜月さんの声が機構室の冷えた空気を切った。"}, {"id": "ch13-s01-p030", "type": "text", "text": "「残響紋が劣化している」"}, {"id": "ch13-s01-p031", "type": "text", "text": "残響紋の劣化。鐘の駆動装置の中核にある紋様。歯車と共鳴管を通じて大鐘の振動を制御する装置の、心臓部。第三系統は四月の着任初日から0.3パーセント低い数値を示していた。共鳴管洗浄で0.2に改善し、その後も定期的にメンテナンスを繰り返してきた。それでも他の系統より低いまま推移していた。"}, {"id": "ch13-s01-p032", "type": "text", "text": "「第三残響紋の出力が通常の62パーセントまで低下。これが50パーセントを切ると、蝕域の抑止力が——」"}, {"id": "ch13-s01-p033", "type": "text", "text": "言葉が途切れた。"}, {"id": "ch13-s01-p034", "type": "text", "text": "霜月さんの手が止まった。検査灯の光が歯車の表面で静止している。銀色の髪が動かない。白いコートの背中が動かない。"}, {"id": "ch13-s01-p035", "type": "text", "text": "背中の奥が、冷えた。"}, {"id": "ch13-s01-p036", "type": "text", "text": "霜月さんの沈黙の中に、五年前の声が聞こえた気がした。望ヶ丘の消滅。声を上げられなかった後悔。「五年前と同じだ」を二度語った十二月初旬の報告室での声。今の沈黙の中に、あの声と同じ密度があった。"}, {"id": "ch13-s01-p037", "type": "text", "text": "「霜月さん」"}, {"id": "ch13-s01-p038", "type": "text", "text": "「……50パーセントを切ると、蝕域の活動圏が鐘の到達範囲を超える。外円区南端の抑止力が実効的に失われる」"}, {"id": "ch13-s01-p039", "type": "text", "text": "声が戻っていた。業務の声。データに基づく報告。しかし「実効的に失われる」の六文字だけが、他の言葉よりも乾いていた。水分を絞り出した後の布のような声。"}, {"id": "ch13-s01-p040", "type": "text", "text": "外円区南端。灯里村跡地東方。十一月に八人が消えた場所。名簿の六十八人。来年はもっと長くなる。"}, {"id": "ch13-s01-p041", "type": "text", "text": "「劣化の原因は」"}, {"id": "ch13-s01-p042", "type": "text", "text": "「特定できていない。経年劣化か、蝕域の活動増大に伴う負荷超過か。あるいはその両方」"}, {"id": "ch13-s01-p043", "type": "text", "text": "霜月さんが振り返った。"}, {"id": "ch13-s01-p044", "type": "text", "text": "ラベンダー色の瞳が、検査灯の白い光の中にあった。瞳の中に疲労が見えた。目の下に薄い影。三時間の深夜作業の痕跡。しかし瞳の焦点は合っている。合っている、というのは正確ではない。俺に向いている。データを報告する時の、計器を読む時の目ではない。"}, {"id": "ch13-s01-p045", "type": "text", "text": "「鐘の間を確認する。来い」"}, {"id": "ch13-s01-p046", "type": "text", "text": "命令口調。いつも通り。けれど「来い」の語尾に、一文字分の間があった。来い、と言う前に、何か別の言葉が喉にあったのかもしれない。"}, {"id": "ch13-s01-p047", "type": "text", "text": "「はい」"}, {"id": "ch13-s01-p048", "type": "break", "text": "◇"}, {"id": "ch13-s01-p049", "type": "text", "text": "螺旋階段を上る。"}, {"id": "ch13-s01-p050", "type": "text", "text": "霜月さんが先を歩いている。白いコートの裾が石段を擦る音が規則的に聞こえる。俺の靴音と、コートの裾の音。二人分の音が螺旋に沿って上に登っていく。"}, {"id": "ch13-s01-p051", "type": "text", "text": "残響灯の色が変わっていく。青白から紫へ。壁面の残響紋の曲線。九ヶ月間で何百回と見た変化。けれど今朝は、残響紋の発光が弱い。紫の光の線が細い。いつもなら壁面を覆うように広がる光が、溝の底に溜まっているだけだった。光が壁から離れられずにいる。"}, {"id": "ch13-s01-p052", "type": "text", "text": "一階。二階。三階。石段の温度が上がらない。十二月の鐘鋳塔は底冷えする。しかし今朝の冷えは季節のものだけではなかった。残響紋の出力低下が塔全体の温度バランスに影響している。残響灯の光が弱ければ、壁面に蓄えられる熱も少ない。"}, {"id": "ch13-s01-p053", "type": "text", "text": "五階。六階。七階。"}, {"id": "ch13-s01-p054", "type": "text", "text": "霜月さんの歩行速度が一定だった。一段ごとの間隔が同じ。体力の配分を計算している歩き方。三時間作業した後の深夜の螺旋階段を、無駄なく登っている。"}, {"id": "ch13-s01-p055", "type": "text", "text": "八階。九階。共鳴の間の前を通過する。扉が閉まっている。鳴海さんが歌う場所。追悼祭で歌いたいと言ったあの声。鳩尾の上が一瞬だけ痛んだ。鐘の出力が落ちている今、共鳴者の負担は増すのか。その疑問を飲み込んだ。今は鐘だ。"}, {"id": "ch13-s01-p056", "type": "text", "text": "十階。"}, {"id": "ch13-s01-p057", "type": "text", "text": "鐘の間。"}, {"id": "ch13-s01-p058", "type": "text", "text": "大鐘が吊り下がっていた。"}, {"id": "ch13-s01-p059", "type": "text", "text": "直径五メートル。残響金属の青みがかった表面。残響紋が全面に刻まれている。十月の終わりに触れた鐘。月の光と歌声と果樹園の匂いが一秒にも満たない間に押し寄せて消えた鐘。"}, {"id": "ch13-s01-p060", "type": "text", "text": "残響灯の紫の光が鐘の曲面に当たっている。紋様の溝が影として浮かんでいる——はずだった。"}, {"id": "ch13-s01-p061", "type": "text", "text": "光が薄い。"}, {"id": "ch13-s01-p062", "type": "text", "text": "紋様の溝に溜まるはずの紫の光が、溝の半分にしか届いていなかった。深い溝には光がある。浅い溝の光が消えかけている。二種類の線が絡み合って描く水の流れのような紋様。その流れの片方が、干上がりかけていた。"}, {"id": "ch13-s01-p063", "type": "text", "text": "「第三残響紋は大鐘の南面に集中している」"}, {"id": "ch13-s01-p064", "type": "text", "text": "霜月さんの声が、鐘の間の高い天井に吸われて消えた。"}, {"id": "ch13-s01-p065", "type": "text", "text": "鐘の南面。蝕域に面する方角。蝕域の侵食を最も直接的に受け止める面の紋様が、劣化している。力を使い続けた面から磨り減っていく。"}, {"id": "ch13-s01-p066", "type": "text", "text": "霜月さんが鐘に近づいた。白い手袋をはめて——いつの間に手袋を。工具袋の中にあったのだろう。白い手袋の指先が鐘の表面に触れた。南面の残響紋の溝をなぞる。深い溝。浅い溝。浅い溝のところで指先が止まった。"}, {"id": "ch13-s01-p067", "type": "text", "text": "「ここ。光が弱い」"}, {"id": "ch13-s01-p068", "type": "text", "text": "検査灯を当てた。白い光が鐘の表面を照らすと、残響紋の溝の底が見えた。底に、微細な亀裂があった。亀裂、というほど明確なものではない。紋様の線が、一箇所だけ、かすれている。インクが薄くなった文字のように、線の密度が落ちている。"}, {"id": "ch13-s01-p069", "type": "text", "text": "「先月の点検では、なかった」"}, {"id": "ch13-s01-p070", "type": "text", "text": "霜月さんの声が低くなった。低い声がさらに低くなると、空気の圧が変わる。背中の奥が反応する。"}, {"id": "ch13-s01-p071", "type": "text", "text": "「一ヶ月で進行した劣化。このペースが続けば——」"}, {"id": "ch13-s01-p072", "type": "text", "text": "言葉を切った。計算している。俺も同じ計算をしていた。62パーセントの出力が月に数パーセントずつ落ちるなら、50パーセントを切るまでの時間は——"}, {"id": "ch13-s01-p073", "type": "text", "text": "「霜月さん」"}, {"id": "ch13-s01-p074", "type": "text", "text": "「わかっている」"}, {"id": "ch13-s01-p075", "type": "text", "text": "短い。切る音。しかし切ったのは俺の言葉ではなく、自分の感情だった。左手がピアスに触れた。青い石の表面を指先が覆うように——覆う動作。先月は触れるだけに変わっていた。確認するような、力の抜けた指先だった。それが今朝、また覆う形に戻っている。鐘の出力低下が、この人の手を防御の位置に引き戻していた。"}, {"id": "ch13-s01-p076", "type": "text", "text": "霜月さんの手がピアスから離れた。0.8秒。短い。"}, {"id": "ch13-s01-p077", "type": "text", "text": "「触れてみろ」"}, {"id": "ch13-s01-p078", "type": "text", "text": "俺に言った。鐘に。"}, {"id": "ch13-s01-p079", "type": "text", "text": "手袋はない。素手。右手を上げた。鐘の表面に掌を向ける。十月の終わりと同じ動作。あの夜、俺は自分で手を伸ばした。今朝は霜月さんの指示だが、手は迷わなかった。"}, {"id": "ch13-s01-p080", "type": "text", "text": "触れた。"}, {"id": "ch13-s01-p081", "type": "text", "text": "冷たかった。十月より冷たい。十二月の鐘。残響金属の表面温度は外気より低い。熱を逃がす金属。掌から体温が鐘に移り、鐘がそれを空気に渡す。体温が通過して消えていく。"}, {"id": "ch13-s01-p082", "type": "text", "text": "振動を探した。"}, {"id": "ch13-s01-p083", "type": "text", "text": "十月の夜、掌の下にあった微細な等間隔の振動。鐘自体が持っている振動。呼吸のようなもの。"}, {"id": "ch13-s01-p084", "type": "text", "text": "あった。"}, {"id": "ch13-s01-p085", "type": "text", "text": "あったが——弱い。"}, {"id": "ch13-s01-p086", "type": "text", "text": "十月に感じた振動の、半分もない。掌の皮膚が報告してくる振動は、呼吸というより、呼吸の痕跡だった。吐いた息が消える直前の、あの細さ。体の奥まで届かない。掌と、手首と、前腕の途中まで。そこで止まる。胸骨まで届いていた振動が、前腕で止まっている。"}, {"id": "ch13-s01-p087", "type": "text", "text": "弱い。"}, {"id": "ch13-s01-p088", "type": "text", "text": "弱い、が。"}, {"id": "ch13-s01-p089", "type": "text", "text": "掌の下で、何かが動いた。"}, {"id": "ch13-s01-p090", "type": "text", "text": "振動の弱さの中に、もう一つの振動があった。等間隔ではない。不規則で、微細で、掌の皮膚が拾えるかどうかの境界にある振動。鐘の機構的な振動とは別の何か。"}, {"id": "ch13-s01-p091", "type": "text", "text": "十月の夜に感じたものとも違う。あの夜の振動は「蓋が開いて中のものが溢れた」感覚だった。月の光と歌声と果樹園の匂い。映像を伴う奔流。"}, {"id": "ch13-s01-p092", "type": "text", "text": "今朝のこれは、映像ではなかった。"}, {"id": "ch13-s01-p093", "type": "text", "text": "掌の下で、鐘が震えていた。機構の振動ではなく。出力の波形ではなく。"}, {"id": "ch13-s01-p094", "type": "text", "text": "訴えている。"}, {"id": "ch13-s01-p095", "type": "text", "text": "言葉にならない、音にならない、波形に載らない。けれど掌の皮膚が受け取っているものがある。弱った振動の中に、何かが混じっている。苦しいとか、助けてとか、そういう人間の言葉にはならない。鐘は人間ではないから。けれど。"}, {"id": "ch13-s01-p096", "type": "text", "text": "生きている。"}, {"id": "ch13-s01-p097", "type": "text", "text": "掌の下の金属は、生きている。"}, {"id": "ch13-s01-p098", "type": "text", "text": "四月に初めて鐘の音を聞いた時、心地よいと思った。なぜだかわからなかった。十月に触れた時、月と歌と匂いが溢れた。何を見たのかわからなかった。"}, {"id": "ch13-s01-p099", "type": "text", "text": "今朝は、わかることが何もないまま、一つだけ確かなことがあった。"}, {"id": "ch13-s01-p100", "type": "text", "text": "鐘は生きている。弱っている。弱りながら、まだ震えている。震え続けようとしている。"}, {"id": "ch13-s01-p101", "type": "text", "text": "掌を離した。"}, {"id": "ch13-s01-p102", "type": "text", "text": "手が震えていなかった。十月とは違う。あの夜は鳩尾の奥から来る震えが止まらなかった。今朝は震えがない代わりに、掌に残った感触が重い。重さが腕を伝って、肩に溜まっている。"}, {"id": "ch13-s01-p103", "type": "text", "text": "「……どうだ」"}, {"id": "ch13-s01-p104", "type": "text", "text": "霜月さんの声が近かった。振り返ると、俺の斜め後ろに立っていた。ラベンダー色の瞳が鐘の表面と俺の右手を交互に見ている。"}, {"id": "ch13-s01-p105", "type": "text", "text": "「振動が弱いです。十月の三分の一以下。それと——」"}, {"id": "ch13-s01-p106", "type": "text", "text": "言葉を探した。技師の言葉で言えることと、言えないことがある。"}, {"id": "ch13-s01-p107", "type": "text", "text": "「機構の振動とは別の振動があります。波形に載るものではないかもしれない。感覚的な報告になりますが」"}, {"id": "ch13-s01-p108", "type": "text", "text": "霜月さんの瞳が動かなかった。俺の言葉を待っている。"}, {"id": "ch13-s01-p109", "type": "text", "text": "「鐘が、何かを訴えているように感じました」"}, {"id": "ch13-s01-p110", "type": "text", "text": "沈黙があった。"}, {"id": "ch13-s01-p111", "type": "text", "text": "鐘の間は静かだった。大鐘が吊り下がる空間に、二人の呼吸だけがある。残響灯の弱い紫の光が天井の石組みに届いていない。暗い。天井が見えない。大鐘の上部が暗がりの中に溶けている。"}, {"id": "ch13-s01-p112", "type": "text", "text": "「……お前は」"}, {"id": "ch13-s01-p113", "type": "text", "text": "霜月さんの声が、小さかった。業務の声ではなかった。三時間の深夜作業の疲労が、一瞬だけ壁の隙間から漏れた声。"}, {"id": "ch13-s01-p114", "type": "text", "text": "「お前は、鐘守補佐だな」"}, {"id": "ch13-s01-p115", "type": "text", "text": "言い直した。語尾が業務に戻っている。けれど最初の「お前は」と、言い直した後の「お前は」の間に、別の言葉があった。その言葉が何だったのか、俺にはわからない。"}, {"id": "ch13-s01-p116", "type": "text", "text": "「第三残響紋の劣化を管理局に報告する。補修が可能かどうか、紋様工房に照会を出す。朝の業務連絡で補佐官に状況を上げる。お前は機構室に戻り、第三系統の全計器の現在値を記録しろ。昨日までの推移と照合して変化量を算出。報告書は八時までに管理室の机に」"}, {"id": "ch13-s01-p117", "type": "text", "text": "指示が連続して出た。業務の密度が元に戻っている。危機対応の速度。一つの判断の後に即座に次の判断が来る。"}, {"id": "ch13-s01-p118", "type": "text", "text": "「はい」"}, {"id": "ch13-s01-p119", "type": "text", "text": "「それと」"}, {"id": "ch13-s01-p120", "type": "text", "text": "霜月さんが鐘に背を向けた。螺旋階段の入口に向かう。白いコートの裾が石の床を擦った。二歩目で足が止まった。振り返らない。"}, {"id": "ch13-s01-p121", "type": "text", "text": "「天蓋の間には上がるな。今の出力では、あの階に長時間いるのは——上がるな」"}, {"id": "ch13-s01-p122", "type": "text", "text": "声が短かった。振り返らないまま言い切って、三歩目を踏み出した。"}, {"id": "ch13-s01-p123", "type": "text", "text": "天蓋の間。すみれがいる場所。鐘の出力低下がすみれに影響するのか。あるいはすみれが鐘に影響するのか。どちらかはわからない。わからないが、霜月さんが「上がるな」と言ったその声の中に、技師の判断だけではないものがあった。"}, {"id": "ch13-s01-p124", "type": "text", "text": "螺旋階段を降りる。霜月さんの白いコートが前方で紫の光を反射している。十月の終わりに見た時と同じ光景だが、壁面の残響紋の光が弱い分、コートの白さだけが目に残った。"}, {"id": "ch13-s01-p125", "type": "text", "text": "九階を通過した。八階。七階。"}, {"id": "ch13-s01-p126", "type": "text", "text": "「霜月さん」"}, {"id": "ch13-s01-p127", "type": "text", "text": "「何だ」"}, {"id": "ch13-s01-p128", "type": "text", "text": "「鐘の出力が回復する方法は、あるんですか」"}, {"id": "ch13-s01-p129", "type": "text", "text": "足音が止まらなかった。霜月さんの歩行速度が変わらない。質問を聞いた上で、歩きながら答える判断をしている。"}, {"id": "ch13-s01-p130", "type": "text", "text": "「残響紋の補修は、過去に三度行われた記録がある。最後の補修は四十年前。当時の紋様工師は既に故人。技術が継承されているかどうかは——確認する」"}, {"id": "ch13-s01-p131", "type": "text", "text": "四十年前。継承されていない可能性がある。"}, {"id": "ch13-s01-p132", "type": "text", "text": "「ただし」"}, {"id": "ch13-s01-p133", "type": "text", "text": "霜月さんの声が、階段の石壁に反響した。"}, {"id": "ch13-s01-p134", "type": "text", "text": "「補修はあくまで対症療法だ。劣化の根本原因が蝕域の活動増大に伴う負荷超過であれば、補修しても再び劣化する。蝕域の活動そのものが止まらない限り」"}, {"id": "ch13-s01-p135", "type": "text", "text": "蝕域の活動が止まる見込みは、今のところない。南端の蝕域活動指数の赤い線は上がり続けている。名簿は毎年長くなっている。28人、31人、43人、68人。来年はもっと。"}, {"id": "ch13-s01-p136", "type": "text", "text": "「それでも、補修すれば時間は稼げるのでは」"}, {"id": "ch13-s01-p137", "type": "text", "text": "「ああ」"}, {"id": "ch13-s01-p138", "type": "text", "text": "短い肯定。"}, {"id": "ch13-s01-p139", "type": "text", "text": "「時間を稼ぐ。それが今できることだ」"}, {"id": "ch13-s01-p140", "type": "text", "text": "霜月さんの声に、疲労が滲んでいた。深夜から一人で作業していた三時間分の疲労。けれどそれだけではない。五年前の望ヶ丘から続く疲労が、声の底にある。時間を稼ぐ。稼いだ時間の先に何があるのか。それを霜月さんは知っている。知っている上で、時間を稼ぐことを選んでいる。"}, {"id": "ch13-s01-p141", "type": "text", "text": "地下一階に降りた。機構室の鉄扉の前で、霜月さんが立ち止まった。"}, {"id": "ch13-s01-p142", "type": "text", "text": "「八時までに報告書を」"}, {"id": "ch13-s01-p143", "type": "text", "text": "「はい」"}, {"id": "ch13-s01-p144", "type": "text", "text": "「……朝霧」"}, {"id": "ch13-s01-p145", "type": "text", "text": "名前を呼ばれた。珍しかった。指示の後に名前だけを呼ぶことは、霜月さんにはほとんどない。"}, {"id": "ch13-s01-p146", "type": "text", "text": "霜月さんが振り返った。ラベンダー色の瞳が、残響灯の青白い光の中で俺を見ていた。疲労の影。その奥の、硬い光。"}, {"id": "ch13-s01-p147", "type": "text", "text": "何かを言おうとして、やめた。口が動きかけて、閉じた。"}, {"id": "ch13-s01-p148", "type": "text", "text": "「——以上だ」"}, {"id": "ch13-s01-p149", "type": "text", "text": "それだけ言って、階段を上っていった。管理局への連絡のために。白いコートの背中が螺旋階段の曲面に沿って見えなくなる。"}, {"id": "ch13-s01-p150", "type": "text", "text": "機構室に入った。歯車の壁面。共鳴管。音響増幅器。残響灯の青白い光。金属と潤滑油の匂い。俺が九ヶ月間、毎日触れてきたもの。"}, {"id": "ch13-s01-p151", "type": "text", "text": "工具箱を開ける。検査灯を取り出す。第三系統の計器の前に立つ。数値を読み始める。"}, {"id": "ch13-s01-p152", "type": "text", "text": "右手の掌に、まだ鐘の冷たさが残っていた。"}, {"id": "ch13-s01-p153", "type": "text", "text": "冷たさの奥に、あの微かな震えが残っていた。生きている。弱りながら、震え続けようとしている。鐘は機械ではない。少なくとも俺の掌はそう報告している。計器の数値とは別の情報が、掌の皮膚に刻まれている。"}, {"id": "ch13-s01-p154", "type": "text", "text": "生きている。"}, {"id": "ch13-s01-p155", "type": "text", "text": "その三文字が、体の中に落ちていった。鳩尾の奥に。月の光と歌声と果樹園の匂いが沈殿しているのと同じ場所に。"}, {"id": "ch13-s01-p156", "type": "text", "text": "計器の針を読む。数値を記録する。一つずつ。正確に。技師の仕事。俺にできること。"}, {"id": "ch13-s01-p157", "type": "text", "text": "鐘が生きているなら、俺は鐘を守る側の人間だ。四月の初日にそう思った。今、同じことを思っている。同じだが、重さが違う。四月は知識だった。今は——掌が知っている。"}, {"id": "ch13-s01-p158", "type": "text", "text": "ペンが記録用紙の上を走る。数値。数値。数値。冬の機構室は冷える。残響灯の光が歯車の壁面に影を落としている。"}, {"id": "ch13-s01-p159", "type": "text", "text": "窓がない地下の部屋に、朝は来ない。時計が五時を示した。外では五時の鐘が鳴っているはずだ。機構室にいても鐘の音は聞こえる。歯車と共鳴管が音を伝える。鐘の振動が共鳴管を通り、歯車を揺らし、機構室の空気を震わせる。"}, {"id": "ch13-s01-p160", "type": "text", "text": "五時の鐘が鳴った。"}, {"id": "ch13-s01-p161", "type": "text", "text": "音は聞こえた。共鳴管が震えた。歯車が微かに動いた。"}, {"id": "ch13-s01-p162", "type": "text", "text": "けれどその振動は、以前のように機構室を満たさなかった。部屋の隅まで届かず、壁の手前で力を失って沈んでいった。"}, {"id": "ch13-s01-p163", "type": "text", "text": "62パーセント。"}, {"id": "ch13-s01-p164", "type": "text", "text": "記録を続けた。ペンが紙を走る。数値の列が伸びていく。霜月さんが三時間かけて集めたデータと、俺がこれから三時間で集めるデータ。二人分のデータが、鐘の現状を数字にする。"}, {"id": "ch13-s01-p165", "type": "text", "text": "数字は祈らない。数字はただそこにある。"}, {"id": "ch13-s01-p166", "type": "text", "text": "けれど鐘は生きている。生きているものの数字は、ただの数字ではない。"}]}, {"chapter": 13, "chapterTitle": "鐘が揺れる夜", "scene": 2, "sceneTitle": "共鳴者への要請", "wordCount": "約5,200字", "paragraphs": [{"id": "ch13-s02-p001", "type": "text", "text": "報告書を書き終えたのは七時だった。"}, {"id": "ch13-s02-p002", "type": "text", "text": "三時間分の計器データ。全七系統の現在値と推移、変化量の算出、過去三ヶ月の平均値との乖離率。霜月さんが一時から集めたデータと合わせて、第三系統の劣化を示す数字が紙の上に並んでいる。報告書の末尾に「第三残響紋出力62パーセント。低下傾向継続中。補修の要否につき判断を仰ぐ」と書いて、ペンを置いた。"}, {"id": "ch13-s02-p003", "type": "text", "text": "機構室を出て地下一階の階段を上がった。管理室の机に報告書を置く。八時までに、と霜月さんは言った。一時間の余裕がある。しかし報告書を机に置いた後、補佐官舎には戻らなかった。"}, {"id": "ch13-s02-p004", "type": "text", "text": "洗面台で顔を洗った。管理室の奥にある小さな流し。冷たい水が頬と額を叩いた。十二月の水道水は指先が痛むほど冷たい。四時から四時間、機構室にいた体が水で目を覚ます。"}, {"id": "ch13-s02-p005", "type": "text", "text": "鏡に映る顔。目の下に薄い影がある。寝不足の顔だった。髪を手で整える。制服のジャケットを正す。ボタンを確認する。左手首のブレスレットの編み目に指先が一瞬触れた。いつもの動作。"}, {"id": "ch13-s02-p006", "type": "text", "text": "管理局から召集があったのは七時十五分だった。"}, {"id": "ch13-s02-p007", "type": "text", "text": "管理室の伝声管が鳴った。低い金属音。伝声管は鐘鋳塔の各階と管理局を結ぶ連絡用の管で、声を通す。管の向こうから事務官の声が聞こえた。"}, {"id": "ch13-s02-p008", "type": "text", "text": "「鐘守補佐の朝霧蓮。八時より管理局会議室にて緊急報告会議。出席を求む」"}, {"id": "ch13-s02-p009", "type": "text", "text": "「了解しました」"}, {"id": "ch13-s02-p010", "type": "text", "text": "管に向かって答えた。声が管の内壁で反響して、小さく歪んで消えた。"}, {"id": "ch13-s02-p011", "type": "text", "text": "報告書は霜月さんが提出したのだろう。一時間早く完成していたなら、七時前には管理局に届いていたはずだ。緊急報告会議。報告書の内容を踏まえた判断をする場。補佐官の俺が呼ばれるのは、現場データの確認のためだ。"}, {"id": "ch13-s02-p012", "type": "text", "text": "管理室を出た。鐘鋳塔の正面入口から外に出ると、十二月の朝の空気が肺に入った。冷たい。霜の降りた石畳が白い。太陽は低い。南東の山の稜線を越えたばかりの光が、内円区の石壁の上端だけを照らしている。灯籠通りの灯籠は消えていた。通りには早朝の人影がまばらにある。"}, {"id": "ch13-s02-p013", "type": "text", "text": "管理局は鐘鋳塔の北側、内円区の行政庁舎の中にある。石造りの三階建て。正面の階段を上がり、二階の廊下を進んだ。突き当たりの両開きの扉。木製。真鍮の取っ手。扉の脇に「会議室」と刻まれた石の銘板がある。"}, {"id": "ch13-s02-p014", "type": "text", "text": "扉を開けた。"}, {"id": "ch13-s02-p015", "type": "text", "text": "部屋は広くなかった。長方形のテーブルが一つ。椅子が八脚。壁面に地図が二枚。一枚は島全体の地形図。もう一枚は鐘鋳塔の周辺三キロメートルの詳細図。残響灯はなく、窓から入る朝の光と、テーブルの上に置かれた油灯の火が部屋を照らしている。"}, {"id": "ch13-s02-p016", "type": "text", "text": "先着が二人いた。"}, {"id": "ch13-s02-p017", "type": "text", "text": "霜月さんが窓側の椅子に座っていた。白いロングコート。銀髪のハーフアップ。背筋が真っ直ぐ。テーブルの上に記録用紙が広げてある。先ほどの報告書と同じ書式の紙が数枚。霜月さん自身がまとめた分析報告だろう。ラベンダーの瞳が紙面から上がり、俺を一瞬見て、紙面に戻った。"}, {"id": "ch13-s02-p018", "type": "text", "text": "もう一人。テーブルの奥、短辺の位置に座っている人物。"}, {"id": "ch13-s02-p019", "type": "text", "text": "五十代の男性。白髪交じりの短髪を横に流している。顔の輪郭は丸みがあるが、目元に刻まれた皺が深い。灰色のコートの上に管理局の徽章を留めている。両手をテーブルの上で組んでいた。指が太い。その指が組まれたまま微かに動いていた。"}, {"id": "ch13-s02-p020", "type": "text", "text": "弦月宗一郎。管理局長。"}, {"id": "ch13-s02-p021", "type": "text", "text": "面識はあった。四月の着任時に一度挨拶をしている。その後、追悼祭の名簿の件で二度ほど伝声管越しに声を聞いた。直接会うのはそれ以来だった。"}, {"id": "ch13-s02-p022", "type": "text", "text": "「朝霧くん。座りなさい」"}, {"id": "ch13-s02-p023", "type": "text", "text": "声は穏やかだった。命令口調ではない。「座りなさい」の語尾に、急かす色がなかった。けれど組まれた指の動きが止まらないことを、俺は見ていた。"}, {"id": "ch13-s02-p024", "type": "text", "text": "霜月さんの向かい側の椅子に座った。テーブルの木目が油灯の光を吸っている。"}, {"id": "ch13-s02-p025", "type": "text", "text": "「もう一名、到着を待つ」"}, {"id": "ch13-s02-p026", "type": "text", "text": "弦月局長が言った。「もう一名」。誰かは言わなかった。"}, {"id": "ch13-s02-p027", "type": "text", "text": "三十秒ほどの沈黙があった。霜月さんが紙面に目を落としている。弦月局長が窓の方に視線を向けている。朝の光がテーブルの端に四角い影を落としていた。油灯の炎が小さく揺れている。暖房の温風が部屋の空気を動かしているのだろう。"}, {"id": "ch13-s02-p028", "type": "text", "text": "扉が開いた。"}, {"id": "ch13-s02-p029", "type": "text", "text": "亜麻色のウェーブヘアが、廊下の光を背にして会議室に入ってきた。"}, {"id": "ch13-s02-p030", "type": "text", "text": "鳴海さんだった。"}, {"id": "ch13-s02-p031", "type": "text", "text": "薄桃色のリボンが右の前髪を留めている。カーディガンを羽織っている。制服の上にカーディガン。十一月の選抜公演で倒れてから一ヶ月。顔色は——戻りかけている、と言うべきだろう。頬に血の色がある。しかし肌の下にある白さが、四月や七月のそれとは違った。血色の下に透けているもの。以前は見えなかったものが見えている。"}, {"id": "ch13-s02-p032", "type": "text", "text": "鳩尾の上が、重くなった。"}, {"id": "ch13-s02-p033", "type": "text", "text": "47。"}, {"id": "ch13-s02-p034", "type": "text", "text": "数字が浮かんだ。浮かぶのを止められなかった。身体負荷指数47。入学時12。不可逆。「数年以内に」の先を霜月さんは言わなかった。その数字を載せた体が、今、会議室の椅子に座ろうとしている。"}, {"id": "ch13-s02-p035", "type": "text", "text": "「おはようございます」"}, {"id": "ch13-s02-p036", "type": "text", "text": "鳴海さんの声。穏やかだった。微笑みがあった。口と目がほぼ同時に動く微笑み。いつもの微笑み。"}, {"id": "ch13-s02-p037", "type": "text", "text": "「管理局長、霜月さん、蓮さん。お呼びいただきありがとうございます」"}, {"id": "ch13-s02-p038", "type": "text", "text": "丁寧語。姿勢は穏やか。カーディガンを押さえる右手の指先に、力みは見えなかった。追悼祭の時に見た「維持している」微笑みとは違う。今朝の微笑みには、維持の力がない。力がないのではなく、力を入れる必要がない自然さがあった。"}, {"id": "ch13-s02-p039", "type": "text", "text": "俺が知っている数字と、目の前の微笑みが、鳩尾の上で重なっている。重なるたびに痛む。"}, {"id": "ch13-s02-p040", "type": "text", "text": "鳴海さんが俺の隣——霜月さんの斜め向かいに座った。カーディガンの裾をそっと膝の上に整える動作。指先が細い。選抜公演の前より細い、ということはない。たぶん。けれど注意して見てしまう自分がいる。"}, {"id": "ch13-s02-p041", "type": "text", "text": "「全員揃った。始める」"}, {"id": "ch13-s02-p042", "type": "text", "text": "弦月局長の声が、会議室の空気を切り替えた。穏やかさが一段沈み、実務の声になった。"}, {"id": "ch13-s02-p043", "type": "text", "text": "「霜月くん。報告を」"}, {"id": "ch13-s02-p044", "type": "text", "text": "「はい」"}, {"id": "ch13-s02-p045", "type": "text", "text": "霜月さんが記録用紙を一枚持ち上げた。"}, {"id": "ch13-s02-p046", "type": "text", "text": "「本日未明一時に確認した異常について報告します。鐘鋳塔駆動装置、第三系統の残響紋の劣化が進行しています。現在の出力は通常の62パーセント。先月比マイナス8ポイント。劣化箇所は大鐘南面に集中しており、蝕域に面する方角です」"}, {"id": "ch13-s02-p047", "type": "text", "text": "声は業務の声だった。平坦。データを読む声。しかし「蝕域に面する方角です」の末尾だけが、他の語尾より0.2秒短かった。切っている。報告の速度で感情を制御している。"}, {"id": "ch13-s02-p048", "type": "text", "text": "「50パーセントを下回った場合、外円区南端の蝕域抑止力が実効的に失われます。現在の劣化速度が継続すると、二週間から三週間で到達する可能性があります」"}, {"id": "ch13-s02-p049", "type": "text", "text": "二週間。"}, {"id": "ch13-s02-p050", "type": "text", "text": "弦月局長の組まれた指が動いた。微かに。右手の親指が左手の甲を撫でる動き。無意識だろう。"}, {"id": "ch13-s02-p051", "type": "text", "text": "「残響紋の補修は可能か」"}, {"id": "ch13-s02-p052", "type": "text", "text": "「紋様工房に照会を出しました。補修に必要な紋様工師の技術継承が確認でき次第、着手可能です。ただし補修には最低でも二週間を要します」"}, {"id": "ch13-s02-p053", "type": "text", "text": "「二週間」"}, {"id": "ch13-s02-p054", "type": "text", "text": "弦月局長が繰り返した。声の色が変わらなかった。変わらないことが、逆に重い。"}, {"id": "ch13-s02-p055", "type": "text", "text": "「つまり、補修が完了するまでの間——」"}, {"id": "ch13-s02-p056", "type": "text", "text": "「鐘の出力を補完する手段が必要です」"}, {"id": "ch13-s02-p057", "type": "text", "text": "霜月さんの声が、弦月局長の言葉を引き取った。テーブルの上に目を落としたまま。ラベンダーの瞳が紙面の上にある。瞳の焦点は紙面に合っている。合っているが、見ているものは紙面の上の数字ではなかった。"}, {"id": "ch13-s02-p058", "type": "text", "text": "沈黙が三秒あった。"}, {"id": "ch13-s02-p059", "type": "text", "text": "弦月局長が、鳴海さんの方を向いた。"}, {"id": "ch13-s02-p060", "type": "text", "text": "俺はそれを見ていた。弦月局長が顔を向ける動作の中に、一瞬の——躊躇。首が半分回ったところで、0.3秒だけ止まった。止まって、それから回りきった。"}, {"id": "ch13-s02-p061", "type": "text", "text": "「鳴海くん」"}, {"id": "ch13-s02-p062", "type": "text", "text": "声が穏やかだった。穏やかさの中に、重いものがあった。穏やかにしなければ言えないものを、穏やかさで包んでいた。"}, {"id": "ch13-s02-p063", "type": "text", "text": "「共鳴者による出力補完が必要だ。鐘の出力を安全域に保つために、定期的な共鳴歌唱を行ってほしい。補修が完了するまでの間——最低でも二週間」"}, {"id": "ch13-s02-p064", "type": "text", "text": "言い終えた後、弦月局長の指が組み直された。右手が上だったものが、左手が上になった。"}, {"id": "ch13-s02-p065", "type": "text", "text": "鳴海さんは、弦月局長の顔を真っ直ぐ見ていた。"}, {"id": "ch13-s02-p066", "type": "text", "text": "微笑みは消えていなかった。穏やかな微笑み。口元の弧。けれど目が変わっていた。穏やかさの底にあるもの。残響祭の舞台裏で「歌いたい」と言った時の光。追悼祭の講堂で「歌いたいです」と言った時の光。同じ光が、今朝もあった。"}, {"id": "ch13-s02-p067", "type": "text", "text": "「わたしが歌います」"}, {"id": "ch13-s02-p068", "type": "text", "text": "間がなかった。"}, {"id": "ch13-s02-p069", "type": "text", "text": "弦月局長が言い終わってから、鳴海さんの声が出るまで。間がなかった。零コンマ何秒。考える時間がなかった。考えなかった。考える前に出ていた。"}, {"id": "ch13-s02-p070", "type": "text", "text": "「わたしが歌います。鐘のためでしたら、わたしにできることは歌うことですから」"}, {"id": "ch13-s02-p071", "type": "text", "text": "声は穏やかだった。微笑みがあった。言葉に力みがなかった。重大な判断を下す声ではなかった。当然のことを当然に言う声だった。"}, {"id": "ch13-s02-p072", "type": "text", "text": "鳩尾の上が、熱くなった。"}, {"id": "ch13-s02-p073", "type": "text", "text": "十一月からずっとここにある熱。怒りの熱ではなかった。熱の種類が違う。怒りの熱は外に向かう。今の熱は内側に溜まる。行き場がない。鳴海さんの「わたしが歌います」に対して俺の体が返した応答。名前のない応答。痛みに近い。"}, {"id": "ch13-s02-p074", "type": "text", "text": "鳴海さんの横顔を見ていた。"}, {"id": "ch13-s02-p075", "type": "text", "text": "笑みがあった。穏やかな笑み。けれどその笑みの下に何があるのか、今の俺には見えた。十一月の前なら見えなかっただろう。データを見る前なら。怒りを知る前なら。保留のまま棚に並べていただろう。"}, {"id": "ch13-s02-p076", "type": "text", "text": "笑みの下にあるもの。覚悟。それと、それに隣り合ったもの。恐怖とは違うかもしれない。歌うことへの恐怖ではない。歌えなくなることへの——いや。わからない。わからないが、笑みの下に何かがあることだけは見えている。見えてしまう。十一月に管が通ったから。"}, {"id": "ch13-s02-p077", "type": "text", "text": "「鳴海さんの体調を考慮すべきではないですか」"}, {"id": "ch13-s02-p078", "type": "text", "text": "声が出た。"}, {"id": "ch13-s02-p079", "type": "text", "text": "自分の声が聞こえた。低かった。十一月の研究室で「知っていて、歌わせていたんですか」と言った時ほどは低くない。しかし業務の声ではなかった。会議の場で発言すること自体が、九ヶ月前の俺にはできなかった行動だった。観察して、記録して、保留する。それが俺のパターンだった。今、声が出ている。保留にしなかった。"}, {"id": "ch13-s02-p080", "type": "text", "text": "弦月局長の目が、俺に向いた。"}, {"id": "ch13-s02-p081", "type": "text", "text": "穏やかな目。皺の深い目元。しかし穏やかさの奥に、疲労があった。一晩の疲労ではなかった。もっと長い疲労。報告書を読んで、数字を計算し、選択肢を並べ、一つを選んだ人間の疲労。選んだことの重さを持ったまま、この椅子に座っている人間の目。"}, {"id": "ch13-s02-p082", "type": "text", "text": "「朝霧くん」"}, {"id": "ch13-s02-p083", "type": "text", "text": "声は穏やかだった。変わらない穏やかさ。"}, {"id": "ch13-s02-p084", "type": "text", "text": "「君の懸念は理解する」"}, {"id": "ch13-s02-p085", "type": "text", "text": "一拍、間があった。"}, {"id": "ch13-s02-p086", "type": "text", "text": "「だが」"}, {"id": "ch13-s02-p087", "type": "text", "text": "弦月局長の両手がテーブルの上で組み直された。今度は指が絡まず、掌を合わせるだけの形だった。祈りに似ていた。似ているだけで、祈りではなかった。"}, {"id": "ch13-s02-p088", "type": "text", "text": "「外円区の住民の安全と、鳴海くんの体調と。どちらを優先すべきだと思う」"}, {"id": "ch13-s02-p089", "type": "text", "text": "声が穏やかなまま、質問の形をしていた。"}, {"id": "ch13-s02-p090", "type": "text", "text": "質問だった。修辞ではなかった。弦月局長は本当に聞いている。俺に答えを求めている。どちらを優先すべきか。"}, {"id": "ch13-s02-p091", "type": "text", "text": "口が開かなかった。"}, {"id": "ch13-s02-p092", "type": "text", "text": "外円区の住民。十一月に十九人が消えた。十月に八人。年間六十八人の名簿。来年はもっと長くなる。南端の蝕域活動指数は上がり続けている。鐘の出力が50パーセントを切れば、抑止力が失われる。失われた先にあるのは、もっと多くの名前が名簿に載ることだ。"}, {"id": "ch13-s02-p093", "type": "text", "text": "鳴海さんの体調。身体負荷指数47。不可逆。「数年以内に」。歌うたびに命を削る。鳴海さんはそれを知らない。知らないまま「わたしが歌います」と言った。間もなく。当然のこととして。"}, {"id": "ch13-s02-p094", "type": "text", "text": "どちらを優先すべきか。"}, {"id": "ch13-s02-p095", "type": "text", "text": "答えが出なかった。"}, {"id": "ch13-s02-p096", "type": "text", "text": "どちらも正しい。どちらも正しくない。六十八人の名前と、鳴海さんの微笑みが、鳩尾の上で天秤に載っている。天秤。霜月さんが十月に使った言葉。「島の安全に傾けている」。同じ天秤が、今、俺の前にある。"}, {"id": "ch13-s02-p097", "type": "text", "text": "霜月さんの声が聞こえた。十月の研究室。「五年前と同じだ」。天秤。コストに傾けた。データがあった。警報を出す根拠があった。握り潰された。"}, {"id": "ch13-s02-p098", "type": "text", "text": "同じ構造が、今この会議室にある。"}, {"id": "ch13-s02-p099", "type": "text", "text": "俺は答えられなかった。"}, {"id": "ch13-s02-p100", "type": "text", "text": "沈黙の中で、鳴海さんが動いた。"}, {"id": "ch13-s02-p101", "type": "text", "text": "俺の方を向いた。小さく首を振った。左右に一度。ゆっくりと。"}, {"id": "ch13-s02-p102", "type": "text", "text": "「蓮さん」"}, {"id": "ch13-s02-p103", "type": "text", "text": "声が小さかった。会議室の広さに対して、声が小さかった。俺にだけ届く声量。"}, {"id": "ch13-s02-p104", "type": "text", "text": "「大丈夫です」"}, {"id": "ch13-s02-p105", "type": "text", "text": "微笑みがあった。"}, {"id": "ch13-s02-p106", "type": "text", "text": "穏やかな微笑み。口と目がほぼ同時に動くいつもの微笑み。しかしその微笑みの中にあるものが見えた。大丈夫です、の四文字が本当に意味しているのは、「大丈夫」ではなかった。「心配しないで」でもなかった。"}, {"id": "ch13-s02-p107", "type": "text", "text": "「わたしは歌いたいんです」"}, {"id": "ch13-s02-p108", "type": "text", "text": "その声は、追悼祭の講堂で聞いた声と同じだった。使命ではなく、意志。歌うことが鳴海さんの存在の中心にあるということの、静かな表明。"}, {"id": "ch13-s02-p109", "type": "text", "text": "鳩尾の上が痛かった。"}, {"id": "ch13-s02-p110", "type": "text", "text": "痛みの名前がわからない。怒りとは違う。悲しみとも違う。鳴海さんの笑みが穏やかであることが、笑みの下にあるものが見えてしまうことが、見えているのに何も言えないことが、全部同じ場所で痛みになっている。"}, {"id": "ch13-s02-p111", "type": "text", "text": "「……了解した」"}, {"id": "ch13-s02-p112", "type": "text", "text": "弦月局長の声が、沈黙を閉じた。"}, {"id": "ch13-s02-p113", "type": "text", "text": "声は穏やかだった。しかし「了解した」の三語を出す前に、弦月局長の視線が一瞬だけ紙面に落ちた。鳴海さんの顔から目を逸らした。逸らして、戻した。"}, {"id": "ch13-s02-p114", "type": "text", "text": "「鳴海くん。まず明日から一日一回、共鳴の間で出力補完歌唱を行ってもらう。時間は管理局医務班と霜月くんが相談して決める。体調の変化があれば、即座に報告してほしい」"}, {"id": "ch13-s02-p115", "type": "text", "text": "「はい」"}, {"id": "ch13-s02-p116", "type": "text", "text": "鳴海さんの声が軽やかだった。軽やかであることが、余計に重かった。"}, {"id": "ch13-s02-p117", "type": "text", "text": "「霜月くん。補修の進捗と鳴海くんの歌唱スケジュールの管理を任せる。歌唱前後の計測データを毎日管理局に報告してくれ」"}, {"id": "ch13-s02-p118", "type": "text", "text": "「了解しました」"}, {"id": "ch13-s02-p119", "type": "text", "text": "霜月さんの声が平坦だった。記録用紙に目を落としたまま。ラベンダーの瞳が紙面の上にある。瞳の中にある層——十月の研究室で浮いたのと同じ層——が、表面に近い位置にあった。けれど今朝は沈めなかった。沈める余裕がない。業務の声で表面を覆っている。"}, {"id": "ch13-s02-p120", "type": "text", "text": "「朝霧くん」"}, {"id": "ch13-s02-p121", "type": "text", "text": "弦月局長の視線が俺に戻った。"}, {"id": "ch13-s02-p122", "type": "text", "text": "「機構室の計器監視を継続してくれ。出力の変化があれば即座に報告を」"}, {"id": "ch13-s02-p123", "type": "text", "text": "「はい」"}, {"id": "ch13-s02-p124", "type": "text", "text": "答えた。声が平らだった。平らにするしかなかった。"}, {"id": "ch13-s02-p125", "type": "text", "text": "弦月局長が立ち上がった。椅子が石の床を擦る音が短く響いた。"}, {"id": "ch13-s02-p126", "type": "text", "text": "「以上だ。——各自、持ち場に」"}, {"id": "ch13-s02-p127", "type": "text", "text": "鳴海さんが立ち上がった。カーディガンの裾を整えた。俺の方を見て、微笑んだ。"}, {"id": "ch13-s02-p128", "type": "text", "text": "「蓮さん。ご心配いただいて、ありがとうございます」"}, {"id": "ch13-s02-p129", "type": "text", "text": "言い方が、礼を言う声だった。感謝の声。しかし「ご心配いただいて」の中に、もう一つの意味があった。心配しなくていい、という意味。歌うことは鳴海さんにとって心配されるようなことではない。それが、この人の本心だった。"}, {"id": "ch13-s02-p130", "type": "text", "text": "鳴海さんが会議室を出ていった。亜麻色のウェーブヘアが廊下の光の中に消えた。カーディガンの背中が最後に見えて、扉が閉まった。"}, {"id": "ch13-s02-p131", "type": "text", "text": "霜月さんが記録用紙をまとめていた。俺はまだ椅子に座っていた。"}, {"id": "ch13-s02-p132", "type": "text", "text": "弦月局長が扉の前で足を止めていた。"}, {"id": "ch13-s02-p133", "type": "text", "text": "振り返らなかった。背中が見えた。灰色のコート。管理局の徽章。白髪交じりの後頭部。"}, {"id": "ch13-s02-p134", "type": "text", "text": "「朝霧くん」"}, {"id": "ch13-s02-p135", "type": "text", "text": "声が低かった。会議中の穏やかさとは違う声。"}, {"id": "ch13-s02-p136", "type": "text", "text": "「正しい選択をしたつもりで、結果として失うことがある。——五年前に、私はそれを知った」"}, {"id": "ch13-s02-p137", "type": "text", "text": "それだけ言って、扉を開けて出ていった。"}, {"id": "ch13-s02-p138", "type": "text", "text": "俺は椅子に座ったまま、閉じた扉を見ていた。"}, {"id": "ch13-s02-p139", "type": "text", "text": "五年前。望ヶ丘。弦月局長もあの時管理局にいた人間だった。「正しい選択をしたつもりで」。天秤を傾けた側の人間。しかし今の声は、天秤を傾けた側の人間の声ではなかった。傾けた後に残ったものを持っている人間の声だった。"}, {"id": "ch13-s02-p140", "type": "text", "text": "霜月さんが立ち上がった。"}, {"id": "ch13-s02-p141", "type": "text", "text": "記録用紙を腕に抱えている。ラベンダーの瞳が俺を見た。"}, {"id": "ch13-s02-p142", "type": "text", "text": "「行くぞ。機構室だ」"}, {"id": "ch13-s02-p143", "type": "text", "text": "短い。いつもの命令口調。けれど「行くぞ」の二文字が、俺を椅子から引き上げた。"}, {"id": "ch13-s02-p144", "type": "text", "text": "立ち上がった。"}, {"id": "ch13-s02-p145", "type": "text", "text": "会議室を出た。廊下を歩いた。霜月さんの白いコートが前を歩いている。十二月の朝の光が廊下の窓から入っている。"}, {"id": "ch13-s02-p146", "type": "text", "text": "鳴海さんの横顔が残っている。鳩尾の上に。笑みの下にあったもの。「大丈夫です」の声。"}, {"id": "ch13-s02-p147", "type": "text", "text": "弦月局長の声が残っている。「どちらを優先すべきだと思う」。答えられなかった。"}, {"id": "ch13-s02-p148", "type": "text", "text": "答えはまだない。"}, {"id": "ch13-s02-p149", "type": "text", "text": "掌に、五時間前の鐘の冷たさが残っている。弱い振動。生きている。生きているものの天秤は、数字では量れない。"}, {"id": "ch13-s02-p150", "type": "text", "text": "けれど数字で量らなければ、誰かが消える。"}]}, {"chapter": 13, "chapterTitle": "鐘が揺れる夜", "scene": 3, "sceneTitle": "すみれの苦痛", "wordCount": "約5,400字", "paragraphs": [{"id": "ch13-s03-p001", "type": "text", "text": "午前中は機構室にいた。"}, {"id": "ch13-s03-p002", "type": "text", "text": "会議室を出て管理局庁舎の廊下を歩いている時、霜月さんが「計器監視を続けろ」と言った。その言葉に従って、八時半から機構室の鉄扉の中に入り、第三系統の計器の前に座った。報告書は七時に書き終えている。あとは数値の推移を追うだけだ。"}, {"id": "ch13-s03-p003", "type": "text", "text": "ペンが紙を走る。三十分ごとに七系統の全数値を記録用紙に書き入れる。九時。九時半。十時。第三系統の残響紋出力は62パーセントのまま動かなかった。下がってもいないが、戻ってもいない。"}, {"id": "ch13-s03-p004", "type": "text", "text": "残りの六系統は正常範囲内。第五系統と第七系統にわずかな変動があるが、誤差の域を出ない。鐘鋳塔の駆動装置は七つの系統で成り立っていて、一つが欠けても残りの六つが補おうとする。補う側にも負荷がかかる。今はまだ保っているが、第三系統がこれ以上落ちれば——。"}, {"id": "ch13-s03-p005", "type": "text", "text": "十時半の記録を書き終えて、ペンを置いた。"}, {"id": "ch13-s03-p006", "type": "text", "text": "歯車の壁面が残響灯の青白い光の中で黙っている。共鳴管の金属が冷えた空気に触れて結露している。地下一階。窓がない。季節も時間もない空間。計器の針と、記録用紙の数字だけが時間を区切っている。"}, {"id": "ch13-s03-p007", "type": "text", "text": "すみれのことを考えていた。"}, {"id": "ch13-s03-p008", "type": "text", "text": "計器の数値を書いている間も、ペンを持つ手の向こう側で、すみれのことが浮いていた。第三残響紋の出力が62パーセントに落ちた。残響紋の劣化が進んでいる。蝕域に面する方角。鐘が弱っている。"}, {"id": "ch13-s03-p009", "type": "text", "text": "鐘が弱ると、すみれはどうなるのか。"}, {"id": "ch13-s03-p010", "type": "text", "text": "七月の夜。「かねが、なってるあいだは、だいじょうぶ」。すみれの声。細い。糸の先端のような声で、大丈夫の裏側にあるものを言わなかった。鐘が鳴らなくなったら。すみれの体がいつも冷たいこと。呼吸が遅いこと。足音がしないこと。時間の感覚がずれていること。全部が同じ場所を向いている。その場所の名前は、まだない。"}, {"id": "ch13-s03-p011", "type": "text", "text": "十月の夜、すみれは鐘の音を通じて俺の中にある島の音を聞いていた。鐘の音が全てを知っていると言った。鐘と、すみれと、俺の中の音が同じ場所から来ている。すみれは鐘を通じて世界を知覚している。"}, {"id": "ch13-s03-p012", "type": "text", "text": "なら、鐘が弱った時、すみれの知覚はどうなるのか。"}, {"id": "ch13-s03-p013", "type": "text", "text": "左手の甲が冷えた。機構室の空気ではない。すみれの冷たさが記憶の中で蘇って、皮膚が反応した。"}, {"id": "ch13-s03-p014", "type": "text", "text": "霜月さんの声が蘇った。「天蓋の間には上がるな」。あの声の中に、技師の判断だけではないものがあった。上がるなと言ったのは、俺の安全のためだけではない。すみれの——。"}, {"id": "ch13-s03-p015", "type": "text", "text": "十一時の記録を書いた。第三系統、62パーセント。変わらない。変わらないことが安堵なのか不安なのかわからない。"}, {"id": "ch13-s03-p016", "type": "text", "text": "十一時半。記録を終えて、ペンを棚に戻した。"}, {"id": "ch13-s03-p017", "type": "text", "text": "立ち上がった。"}, {"id": "ch13-s03-p018", "type": "text", "text": "「計器監視を続けろ」。霜月さんの声。「天蓋の間には上がるな」。霜月さんの声。二つの指示。片方は守る。片方を破る。"}, {"id": "ch13-s03-p019", "type": "text", "text": "螺旋階段の入口に立った。石段が上に続いている。残響灯の青白い光が壁面に落ちている。壁面の残響紋の発光が弱い。今朝確認したのと同じ。紫の光が溝の底に溜まったまま、壁面を覆えずにいる。"}, {"id": "ch13-s03-p020", "type": "text", "text": "足が一段目に乗った。"}, {"id": "ch13-s03-p021", "type": "text", "text": "昼の鐘鋳塔は静かだった。俺の靴音だけが螺旋に沿って上に登っていく。一階。二階。三階。残響灯の色が青白から紫に傾いていく変化も、壁面の残響紋の曲線も、九ヶ月間で何百回と見た景色だった。見慣れた景色の中で、光だけが弱い。"}, {"id": "ch13-s03-p022", "type": "text", "text": "五階を過ぎた。空気が重くなる。いつもの変化。空気の密度が上がる層。それが今日は——重いのではなく、薄い。密度が足りない。鐘の出力低下が空気の層にも影響しているのか。残響紋が空間に与える圧が、普段より低い。肌がそれを報告してくる。"}, {"id": "ch13-s03-p023", "type": "text", "text": "八階。九階。共鳴の間の前を通過した。扉が閉まっている。鳴海さんが歌う場所。明日から一日一回、ここで鳴海さんが歌う。鳩尾の上が重くなったが、足は止めなかった。"}, {"id": "ch13-s03-p024", "type": "text", "text": "十階。大鐘の脇を通過した。残響紋の紫の光が鐘の曲面に落ちている。光が薄い。今朝見た時よりもさらに薄くなっている——いや、変わっていないかもしれない。目が過敏になっている。計器の数値は62パーセントのまま動いていなかった。感覚と数字がずれている。"}, {"id": "ch13-s03-p025", "type": "text", "text": "石段が木の床に変わった。"}, {"id": "ch13-s03-p026", "type": "text", "text": "十一階。天蓋の間。"}, {"id": "ch13-s03-p027", "type": "text", "text": "ガラスの天蓋を通して、昼の空が円形に切り取られていた。十二月の空。薄い雲が高い位置にかかっている。白い。太陽光がガラスを通過して、木の床に淡い影を落としていた。壁面下部の間接照明の紫の光は、昼間は太陽光に負けて見えない。"}, {"id": "ch13-s03-p028", "type": "text", "text": "天蓋の間は、昼に来ると夜とは別の部屋だった。星がない分、空間が広く見える。ガラスの向こうの空が圧倒的に明るい。木の床の木目が見える。壁の石材の色が見える。夜は薄紫と星と闇で構成されていた空間が、昼は白い光で満ちている。"}, {"id": "ch13-s03-p029", "type": "text", "text": "すみれがいた。"}, {"id": "ch13-s03-p030", "type": "text", "text": "部屋の壁際。いつもの中央ではない。壁に背を預けるように、体を丸くしていた。"}, {"id": "ch13-s03-p031", "type": "text", "text": "膝を抱えている。顔が膝の間に埋まっている。淡い紫の髪が肩から前に流れて、膝を覆っていた。白いワンピースの裾が木の床に広がっている。裸足の足先が見えた。足の指が——震えていた。"}, {"id": "ch13-s03-p032", "type": "text", "text": "体が震えている。"}, {"id": "ch13-s03-p033", "type": "text", "text": "小刻みに。肩が揺れている。背中が揺れている。すみれの小さな体全体が、微細な振動を起こしていた。"}, {"id": "ch13-s03-p034", "type": "text", "text": "「すみれ」"}, {"id": "ch13-s03-p035", "type": "text", "text": "声が出た。駆けた。木の床を三歩で渡った。"}, {"id": "ch13-s03-p036", "type": "text", "text": "すみれの前にしゃがんだ。膝をついた。木の床が硬い。"}, {"id": "ch13-s03-p037", "type": "text", "text": "「すみれ、どうした」"}, {"id": "ch13-s03-p038", "type": "text", "text": "声が低くなっていた。自分でわかった。喉の深い場所から出ている。十月にすみれに「島の音？」と聞き返した時と同じ深さ。けれど今日は深さの中に別のものがある。焦り。名前をつける前に体が動いている。"}, {"id": "ch13-s03-p039", "type": "text", "text": "すみれが顔を上げた。"}, {"id": "ch13-s03-p040", "type": "text", "text": "ゆっくりだった。すみれの動きはいつも遅い。遅いが、今日の遅さは違った。膝から顔を離す動作に、痛みがあった。痛みの中で体を動かしている遅さ。"}, {"id": "ch13-s03-p041", "type": "text", "text": "薄紫の瞳が俺を見た。"}, {"id": "ch13-s03-p042", "type": "text", "text": "瞳の中に、いつもの光がなかった。星の光がない——昼だからではない。すみれの瞳は夜でも昼でも、自分自身の光を持っていた。十月の夜、俺が「歌か」と言った時に増えた光。鐘の音に連動して変わる光。その光が、薄い。紫色の虹彩はそのままだが、奥にある層が沈んでいる。水面が下がって、底が見えそうになっている。"}, {"id": "ch13-s03-p043", "type": "text", "text": "口元が動いた。微笑みの形ではなかった。唇が開いただけ。0.5秒のずれも、笑みの形もない。"}, {"id": "ch13-s03-p044", "type": "text", "text": "「かね……がいたい……れん、かねがいたいよ……」"}, {"id": "ch13-s03-p045", "type": "text", "text": "声が砕けていた。"}, {"id": "ch13-s03-p046", "type": "text", "text": "すみれの声は細い。いつも細い。糸の先端のような声。けれど今日の声は糸ではなかった。糸が何本にも裂けた後の、繊維の声。ひらがなの一文字一文字が、ばらばらに口から出てきている。文としてまとまっていない。音として、断片として、こぼれている。"}, {"id": "ch13-s03-p047", "type": "text", "text": "鐘が痛い。"}, {"id": "ch13-s03-p048", "type": "text", "text": "すみれが言った。鐘が痛い。鐘の痛みを、すみれは自分の痛みとして言っている。"}, {"id": "ch13-s03-p049", "type": "text", "text": "すみれの肩に手を置いた。"}, {"id": "ch13-s03-p050", "type": "text", "text": "冷たかった。七月の冷たさとは次元が違った。七月は外気と同じ温度域だった。十月は世界がすみれに追いついていた。十二月の今、すみれの肩は十二月の外気よりも冷たかった。世界を追い越して、すみれだけが先に冷えている。"}, {"id": "ch13-s03-p051", "type": "text", "text": "「すみれ、手を出せ」"}, {"id": "ch13-s03-p052", "type": "text", "text": "すみれの右手を取った。指が震えていた。五本の細い指が、俺の掌の中で小さく振動していた。指先が白い。血の気がない。爪の色が淡い。冷たさが掌を通して前腕まで登ってきた。"}, {"id": "ch13-s03-p053", "type": "text", "text": "鐘に触れた時の冷たさに似ていた。残響金属の、体温を通過させて空気に渡す冷たさ。すみれの手が、鐘の表面と同じ温度だった。"}, {"id": "ch13-s03-p054", "type": "text", "text": "「立てるか」"}, {"id": "ch13-s03-p055", "type": "text", "text": "返事がなかった。すみれの瞳が俺を見ている。薄紫の色はそのまま。けれど焦点が合いきっていない。合わせようとしているが、揺れている。揺れることのないすみれの瞳が揺れている。"}, {"id": "ch13-s03-p056", "type": "text", "text": "抱き上げた。"}, {"id": "ch13-s03-p057", "type": "text", "text": "左腕をすみれの背中に回し、右腕を膝の裏に通した。持ち上げた。"}, {"id": "ch13-s03-p058", "type": "text", "text": "軽かった。"}, {"id": "ch13-s03-p059", "type": "text", "text": "軽い、ではなく、軽すぎた。人間の体の重さではなかった。すみれの見た目の体格——148センチの小柄な少女の体重として想定される重さの半分もない。骨と肌の中に、人間が詰めているはずのものが足りない。空洞ではないが、密度が低い。鐘の金属が中空であるのと同じ構造が、すみれの体にもあるのではないかと——。"}, {"id": "ch13-s03-p060", "type": "text", "text": "その思考を止めた。今は考える時ではない。"}, {"id": "ch13-s03-p061", "type": "text", "text": "すみれの体を部屋の中央に運んだ。壁際は冷える。中央の方が天蓋からの日光が当たる。木の床に下ろした。すみれの背中を支えたまま、座らせた。"}, {"id": "ch13-s03-p062", "type": "text", "text": "すみれの頭が俺の胸に当たった。額が鎖骨の下に触れた。冷たい。すみれの体温が、服の布越しに伝わってくる。冷たさが皮膚に染みる。"}, {"id": "ch13-s03-p063", "type": "text", "text": "「待ってろ。毛布を取ってくる」"}, {"id": "ch13-s03-p064", "type": "text", "text": "壁際の低い棚。すみれが星のノートを置いている棚。その下の段に、畳んだ毛布が一枚あった。初日に来た時は暗くて見えなかった。毛布は薄い灰色で、毛玉がいくつかついていた。すみれがずっと使っているものだろう。"}, {"id": "ch13-s03-p065", "type": "text", "text": "毛布を広げた。すみれの肩から背中、膝までを包んだ。毛布の端を前で合わせた。すみれの体が毛布の中に収まった。小さかった。毛布に包まれたすみれは、膝の上に置かれた荷物のように小さかった。"}, {"id": "ch13-s03-p066", "type": "text", "text": "すみれの震えが止まらない。毛布の中で、まだ体が振動している。"}, {"id": "ch13-s03-p067", "type": "text", "text": "俺の両手をすみれの手に重ねた。毛布の中のすみれの手を、左右から包んだ。"}, {"id": "ch13-s03-p068", "type": "text", "text": "冷たかった。掌から前腕に冷えが昇っていく。体温を送る。七月にすみれが俺の手の温度を受け取った時、すみれの冷たさは中間に来なかった。冷たいままだった。今もそうだろうか。それでも温度を送り続ける以外に、今の俺にできることがない。"}, {"id": "ch13-s03-p069", "type": "text", "text": "すみれの顔がわずかに上を向いた。俺を見ていた。"}, {"id": "ch13-s03-p070", "type": "text", "text": "薄紫の瞳。揺れがわずかに収まっている。俺の手の温度が届いたのか。それとも——。"}, {"id": "ch13-s03-p071", "type": "text", "text": "「れん……」"}, {"id": "ch13-s03-p072", "type": "text", "text": "声が、さっきよりわずかに糸に戻っていた。裂けた繊維が何本か撚り合わさった声。"}, {"id": "ch13-s03-p073", "type": "text", "text": "「れん……かねがよわくなると、すみれも……よわくなる」"}, {"id": "ch13-s03-p074", "type": "text", "text": "鐘が弱くなると、すみれも弱くなる。"}, {"id": "ch13-s03-p075", "type": "text", "text": "すみれの言葉はいつも事実の報告だった。蛇口から水が出る。空に星がある。鐘が弱くなるとすみれも弱くなる。同じ棚に並んでいる。嘘がない。嘘という概念がない声で、すみれは自分と鐘の関係を報告した。"}, {"id": "ch13-s03-p076", "type": "text", "text": "すみれの手が、俺の手を握り返した。五本の指が俺の掌の中で動いて、指を絡めてきた。弱い力。確認の力ではなかった。七月にも十月にも感じた「確認の力」とは違う。しがみつく力。冷たい指が俺の指の間に入り込んで、離すまいとしている。"}, {"id": "ch13-s03-p077", "type": "text", "text": "その時、目に入った。"}, {"id": "ch13-s03-p078", "type": "text", "text": "すみれの左の手首。毛布の端から覗いている白い肌の上に、光があった。"}, {"id": "ch13-s03-p079", "type": "text", "text": "淡い光。紫と青白の中間の色。肌の表面に浮かんでいる。浮かんでいるというより、肌の内側から透けて見えている。皮膚の下、血管が透けるのと同じ深さに、光の線が走っていた。"}, {"id": "ch13-s03-p080", "type": "text", "text": "紋様。"}, {"id": "ch13-s03-p081", "type": "text", "text": "曲線が絡み合っている。水の流れのような線。深い線と浅い線が二種類、交差しながら手首から前腕にかけて伸びている。"}, {"id": "ch13-s03-p082", "type": "text", "text": "大鐘の表面に刻まれた残響紋と、同じだった。"}, {"id": "ch13-s03-p083", "type": "text", "text": "同じ線の太さ。同じ曲線の流れ方。深い溝と浅い溝の二種類の線が絡み合う、あの水の流れのような紋様。今朝、霜月さんと一緒に検査灯で見た鐘の南面の紋様と、すみれの肌に浮かんでいる光の線が、同じ形をしていた。"}, {"id": "ch13-s03-p084", "type": "text", "text": "体が固まった。"}, {"id": "ch13-s03-p085", "type": "text", "text": "すみれの手を握ったまま、手首の紋様を見ていた。呼吸を一つ止めた。鳩尾の奥が揺れた。十月に鐘に触れてフラッシュバックが来た時の揺れとは違う。あの時は蓋が開いて中身が溢れた。今は——何かが繋がった。繋がりかけた。線が引かれようとしている。鐘の紋様と、すみれの肌の紋様が、同じ一本の線で繋がろうとしている。"}, {"id": "ch13-s03-p086", "type": "text", "text": "意味がわからなかった。わかる手前にいた。わかりたくない、ではない。わかるための部品が足りない。鐘の表面にあるものが、なぜすみれの体にある。すみれは鐘の音を聞いている。鐘の音で世界を知覚している。それは知っている。けれど鐘の紋様が体に浮かぶのは、聞いているだけでは説明がつかない。もっと深い場所で、すみれと鐘は——。"}, {"id": "ch13-s03-p087", "type": "text", "text": "すみれの指が動いた。俺の手を握っている指が、一瞬だけ強くなった。"}, {"id": "ch13-s03-p088", "type": "text", "text": "顔を上げた。すみれの瞳が俺を見ていた。"}, {"id": "ch13-s03-p089", "type": "text", "text": "瞳の奥の光が、かすかに戻っていた。完全ではない。十月の夜の密度にはほど遠い。けれどさっきまで底に沈んでいた光が、わずかに浮き上がっている。"}, {"id": "ch13-s03-p090", "type": "text", "text": "紋様のことを聞くべきだった。すみれ、体に光が出ている。鐘の紋様と同じだ。何なんだ、これは。"}, {"id": "ch13-s03-p091", "type": "text", "text": "聞かなかった。"}, {"id": "ch13-s03-p092", "type": "text", "text": "すみれの手が冷たかった。震えていた。毛布の中で体が丸まっていた。今、紋様の意味を問い詰めることは、すみれの前でやる行為ではなかった。答えを求める行為ではなく、温める行為を選んだ。"}, {"id": "ch13-s03-p093", "type": "text", "text": "すみれの手を両手で包み直した。指を絡めたまま、掌の全面をすみれの手に押し当てた。体温を送る。右手と左手の両方から。冷たさが腕を登っていくが、それでいい。"}, {"id": "ch13-s03-p094", "type": "text", "text": "「すみれ。鐘はまだ鳴ってる。62パーセントだが、鳴ってる」"}, {"id": "ch13-s03-p095", "type": "text", "text": "声に出した。すみれに向けた。数字を。技師の言葉を。俺が持っているものを。"}, {"id": "ch13-s03-p096", "type": "text", "text": "すみれの瞳が揺れた。"}, {"id": "ch13-s03-p097", "type": "text", "text": "「ろくじゅう……に」"}, {"id": "ch13-s03-p098", "type": "text", "text": "繰り返した。数字を。すみれの口から数字が出るのを初めて聞いた。星を数える時は数えるが、パーセントという単位は使わない。俺が使った単位を、そのまま口にした。"}, {"id": "ch13-s03-p099", "type": "text", "text": "「まだ、なってるんだ……かね」"}, {"id": "ch13-s03-p100", "type": "text", "text": "「ああ。なってる」"}, {"id": "ch13-s03-p101", "type": "text", "text": "すみれの震えが、わずかに弱まった。止まったのではない。弱まった。毛布の中で振動の振幅が小さくなっている。"}, {"id": "ch13-s03-p102", "type": "text", "text": "「れん」"}, {"id": "ch13-s03-p103", "type": "text", "text": "「うん」"}, {"id": "ch13-s03-p104", "type": "text", "text": "「あったかい」"}, {"id": "ch13-s03-p105", "type": "text", "text": "すみれの声が、少しだけ糸に近づいた。裂けた繊維が束になって、糸の形に戻りかけている。声に「あったかい」が載った。七月に「れんのて、あったかい」と言った時と同じ言葉。けれど今日の「あったかい」は、七月より重かった。冷えた体が温度を受け取っている重さ。必要としている重さ。"}, {"id": "ch13-s03-p106", "type": "text", "text": "左手の甲が、すみれの温度を受けていた。すみれの場所。すみれは左手の甲にいる。七月から、ずっと。冷たさの跡がここに残る。体温が上書きしても、「惜しい」と思う場所。"}, {"id": "ch13-s03-p107", "type": "text", "text": "今日は上書きしない。上書きされる前に、もう一度温度を送る。"}, {"id": "ch13-s03-p108", "type": "text", "text": "天蓋のガラス越しに、十二月の昼の光が落ちていた。太陽は南に低い。白い光が斜めに入って、木の床の半分だけを照らしている。すみれと俺がいる場所には日光が当たっていなかった。影の中にいた。毛布の灰色と、すみれの薄紫の髪と、俺の制服の紺色が、紫の間接照明の光の中にある。"}, {"id": "ch13-s03-p109", "type": "text", "text": "すみれの肌の紋様は、まだ見えていた。手首から前腕にかけての淡い光。紫と青白の中間。鐘の残響紋と同じ形。"}, {"id": "ch13-s03-p110", "type": "text", "text": "その光が、わずかに脈打っていた。等間隔で。微かに。明滅ではなく、強弱。呼吸のような周期。"}, {"id": "ch13-s03-p111", "type": "text", "text": "——鐘の振動と、同じ周期だと気づいた。"}, {"id": "ch13-s03-p112", "type": "text", "text": "今朝、鐘に掌を当てた時に感じた微細な振動。弱い。弱いが等間隔の、鐘自体が持っている振動。呼吸のような振動。すみれの肌の紋様の脈動が、あの振動と同じリズムに見えた。"}, {"id": "ch13-s03-p113", "type": "text", "text": "すみれと鐘が繋がっている。"}, {"id": "ch13-s03-p114", "type": "text", "text": "どう繋がっているのかはわからない。すみれが鐘の音を聞いているだけではない。体に紋様が浮かぶ。鐘の痛みを自分の痛みとして感じる。鐘が弱ればすみれも弱る。一方的に聞いているのではなく、共鳴している。鐘とすみれは、同じものの二つの形——。"}, {"id": "ch13-s03-p115", "type": "text", "text": "思考がそこで止まった。それ以上は組み立てられなかった。手持ちの部品では足りない。"}, {"id": "ch13-s03-p116", "type": "text", "text": "けれど一つだけ、確かなことがある。"}, {"id": "ch13-s03-p117", "type": "text", "text": "すみれの手が冷たい。すみれが震えている。俺の手が温かい。俺の手ですみれを温められる。"}, {"id": "ch13-s03-p118", "type": "text", "text": "今はそれだけでいい。"}, {"id": "ch13-s03-p119", "type": "text", "text": "すみれの指が俺の指を握っていた。弱い力。けれど離さない力。その力を握り返した。"}, {"id": "ch13-s03-p120", "type": "text", "text": "天蓋の向こうで、薄い雲が南から北に流れていた。十二月の風。天蓋の間の中には届かない。ガラス越しの風景だけが、時間が動いていることを教えている。"}, {"id": "ch13-s03-p121", "type": "text", "text": "すみれの震えが、もう少し弱まっていた。"}]}, {"chapter": 13, "chapterTitle": "鐘が揺れる夜", "scene": 4, "sceneTitle": "果樹園の記憶", "wordCount": "約5,200字", "paragraphs": [{"id": "ch13-s04-p001", "type": "text", "text": "午後は機構室にいた。"}, {"id": "ch13-s04-p002", "type": "text", "text": "すみれの手を離したのが十二時半頃で、天蓋の間を出て十階、九階、八階と螺旋階段を降りる間、左手の甲にすみれの冷たさが残っていた。地下一階まで降りて、鉄扉の向こうで計器の前に座り直した。第三系統の数値を読み、記録する。62パーセント。朝から変わらない。"}, {"id": "ch13-s04-p003", "type": "text", "text": "午後の三時間を計器の前で過ごした。三十分ごとの記録。数値の推移。七系統のうち六系統は正常範囲内を維持している。第三系統だけが62パーセントの平野に立ったまま動かない。下がりもしない。戻りもしない。"}, {"id": "ch13-s04-p004", "type": "text", "text": "夕方、伝声管が鳴った。"}, {"id": "ch13-s04-p005", "type": "text", "text": "管理局からの通達。鳴海千歳、本日十七時より共鳴の間にて第一回出力補完歌唱を実施。鐘守補佐は鐘の間にて出力変動の計測を行うこと。"}, {"id": "ch13-s04-p006", "type": "text", "text": "立ち上がった。工具箱から携帯計器を取り出し、螺旋階段を上った。"}, {"id": "ch13-s04-p007", "type": "text", "text": "九階の共鳴の間の扉が閉まっていた。扉の向こうに人の気配がある。霜月さんの気配と、もう一つ。鳴海さん。"}, {"id": "ch13-s04-p008", "type": "text", "text": "扉の前を通過した。十階。鐘の間。"}, {"id": "ch13-s04-p009", "type": "text", "text": "大鐘が吊り下がっていた。残響灯の弱い紫の光が鐘の曲面を照らしている。南面の浅い溝の光がかすれている。今朝見た時と同じ。"}, {"id": "ch13-s04-p010", "type": "text", "text": "携帯計器を鐘の基部に設置した。出力の微細な変動を拾うための装置。針が62の目盛りの上で止まっている。"}, {"id": "ch13-s04-p011", "type": "text", "text": "待った。"}, {"id": "ch13-s04-p012", "type": "text", "text": "三分後、九階から音が来た。"}, {"id": "ch13-s04-p013", "type": "text", "text": "歌声ではなかった。歌声になる前の、気配。共鳴の間の床と壁と天井が鳴海さんの声を受けて、鐘鋳塔の構造全体に伝える。石の壁が音を運ぶ。共鳴管が音を増幅する。歯車が微かに動く。九ヶ月間で覚えた鐘鋳塔の構造が、鳴海さんの声によって動き始めた。"}, {"id": "ch13-s04-p014", "type": "text", "text": "歌声が来た。"}, {"id": "ch13-s04-p015", "type": "text", "text": "高い。透明だった。壁面から滲むように広がる。九階の共鳴の間から石の壁を伝い、十階の鐘の間の空気に染み込んでくる。残響祭の野外ステージで聴いた時とは違う。壁に囲まれた空間の中で、声が空気の密度を変えている。鐘鋳塔の空気が鳴海さんの声と同じ周波数で震え始める。"}, {"id": "ch13-s04-p016", "type": "text", "text": "鐘が応えた。"}, {"id": "ch13-s04-p017", "type": "text", "text": "大鐘の表面から振動が立ち上がった。掌で触れなくてもわかった。空気を通して伝わる振動。打鐘ではない。鳴海さんの歌声が鐘の中に入り、鐘がそれを全身で受け止めて震えている。"}, {"id": "ch13-s04-p018", "type": "text", "text": "携帯計器の針が動いた。"}, {"id": "ch13-s04-p019", "type": "text", "text": "62から、わずかに。"}, {"id": "ch13-s04-p020", "type": "text", "text": "63。"}, {"id": "ch13-s04-p021", "type": "text", "text": "63.5。"}, {"id": "ch13-s04-p022", "type": "text", "text": "上がっている。鳴海さんの歌声が鐘の残響紋に直接作用して、出力を押し上げている。"}, {"id": "ch13-s04-p023", "type": "text", "text": "鳩尾の上が重かった。"}, {"id": "ch13-s04-p024", "type": "text", "text": "歌声が美しかった。美しさの代償を知っている。47。不可逆。「数年以内に」。鳴海さんの声が鐘を通して島に広がるたびに、鳴海さんの体の中の何かが削れていく。その構造を知っていて、ここに立っている。計器の針を読んでいる。読んで、記録して、報告する。俺の仕事。"}, {"id": "ch13-s04-p025", "type": "text", "text": "針は64まで上がって止まった。"}, {"id": "ch13-s04-p026", "type": "text", "text": "歌声は続いている。鐘の振動が鐘の間を満たしている。さっきまで壁面の残響紋の溝の底に溜まっていた紫の光が、わずかに浮き上がっている。浅い溝にも光が戻りかけている。"}, {"id": "ch13-s04-p027", "type": "text", "text": "二十分ほどで歌声が止んだ。"}, {"id": "ch13-s04-p028", "type": "text", "text": "鐘の振動が残響になり、残響が薄まり、消えた。携帯計器の針が64の位置で安定している。62から64。2ポイントの回復。"}, {"id": "ch13-s04-p029", "type": "text", "text": "数字を記録用紙に書いた。ペンを下ろした。"}, {"id": "ch13-s04-p030", "type": "break", "text": "◇"}, {"id": "ch13-s04-p031", "type": "text", "text": "夜になった。"}, {"id": "ch13-s04-p032", "type": "text", "text": "補佐官舎で夕食を済ませ、二十一時の鐘を聞いた。鐘の音は、朝よりわずかに体の奥まで届いた。胸骨の手前で止まっていた振動が、胸骨を通過しかけている。64パーセント。2ポイントの差が体感に出ている。"}, {"id": "ch13-s04-p033", "type": "text", "text": "二十二時。鐘の間に向かった。"}, {"id": "ch13-s04-p034", "type": "text", "text": "夜間の定時点検。霜月さんからの追加指示で、当面は朝と夜の二回、鐘の状態を目視と触診で確認することになっている。"}, {"id": "ch13-s04-p035", "type": "text", "text": "螺旋階段を上る。残響灯の紫の光が壁面に落ちている。朝より明るい。2ポイントの回復が残響灯にも出ている。光が溝から壁面にわずかに広がっている。"}, {"id": "ch13-s04-p036", "type": "text", "text": "九階を通過した。共鳴の間の扉は閉まっている。鳴海さんの歌唱は夕方に終わっている。扉の向こうに気配はなかった。"}, {"id": "ch13-s04-p037", "type": "text", "text": "十階。鐘の間。"}, {"id": "ch13-s04-p038", "type": "text", "text": "大鐘が暗がりの中に吊り下がっていた。残響灯の紫の光が曲面を照らしている。南面の紋様の光が、今朝よりわずかに厚い。浅い溝の底まで光が戻りかけている。"}, {"id": "ch13-s04-p039", "type": "text", "text": "手袋をしていない。今夜は触診だ。"}, {"id": "ch13-s04-p040", "type": "text", "text": "鐘の前に立った。右手を上げた。掌を鐘に向ける。"}, {"id": "ch13-s04-p041", "type": "text", "text": "触れた。"}, {"id": "ch13-s04-p042", "type": "text", "text": "冷たかった。十二月の残響金属。体温が掌から鐘に移り、鐘がそれを空気に渡す。"}, {"id": "ch13-s04-p043", "type": "text", "text": "振動を探した。"}, {"id": "ch13-s04-p044", "type": "text", "text": "あった。"}, {"id": "ch13-s04-p045", "type": "text", "text": "今朝より強い。前腕の途中で止まっていた振動が、肘を越えている。上腕の半ばまで届いている。64パーセント分の振動。鳴海さんの歌声が鐘に残している。歌声が消えた後も、鐘はその力を保っている。"}, {"id": "ch13-s04-p046", "type": "text", "text": "掌を鐘の表面に押し当てた。五本の指の腹が残響紋の溝の上に載った。十月の終わりの夜と同じ動作。"}, {"id": "ch13-s04-p047", "type": "text", "text": "振動が掌全体に広がった。"}, {"id": "ch13-s04-p048", "type": "text", "text": "今朝の「訴え」のような振動は薄まっていた。苦しさが和らいでいる。鐘の声——声と呼んでいいのかわからないが、掌の下にあるものは計器の波形では拾えない種類のもので、俺はそれを声と呼ぶしかない——が、少し安定している。鳴海さんの歌が、鐘を支えている。"}, {"id": "ch13-s04-p049", "type": "text", "text": "鳴海さんの歌と、鳴海さんの体と、鐘の出力が、同じ天秤の上にある。"}, {"id": "ch13-s04-p050", "type": "text", "text": "鳩尾の上が重い。"}, {"id": "ch13-s04-p051", "type": "text", "text": "そのまま鐘に触れていた。点検は終わっている。振動を確認し、紋様の光を目視し、携帯計器で数値を読んだ。やることは全てやった。けれど手が離せなかった。鐘の振動が掌から伝わっている。弱い。弱いが、今朝よりわずかに厚い振動。"}, {"id": "ch13-s04-p052", "type": "text", "text": "その時だった。"}, {"id": "ch13-s04-p053", "type": "text", "text": "鐘が、鳴った。"}, {"id": "ch13-s04-p054", "type": "text", "text": "打鐘ではない。定時の鐘打ちは二十二時にはない。打鐘機構は動いていない。"}, {"id": "ch13-s04-p055", "type": "text", "text": "鐘が、自分で鳴った。"}, {"id": "ch13-s04-p056", "type": "text", "text": "微かな音。耳で聞くのではなく、掌で聞いた。鐘の内側から立ち上がった振動が、金属の表面を伝って掌に届いた。鳴海さんの歌声の残響が、鐘の中で何かに触れたのだろう。歌声が去った後の鐘の中に残った力が、一瞬だけ共鳴した。"}, {"id": "ch13-s04-p057", "type": "text", "text": "その一瞬で——"}, {"id": "ch13-s04-p058", "type": "text", "text": "——来た。"}, {"id": "ch13-s04-p059", "type": "text", "text": "白い。"}, {"id": "ch13-s04-p060", "type": "text", "text": "光が白い。上から落ちている。月。月がある。大きい。空の高い位置にある月が、地面を白く照らしている。"}, {"id": "ch13-s04-p061", "type": "text", "text": "地面は土だった。十月に見た時と同じ。草が生えている。草の間に月の光が散っている。"}, {"id": "ch13-s04-p062", "type": "text", "text": "けれど今回は、そこで終わらなかった。"}, {"id": "ch13-s04-p063", "type": "text", "text": "視界が広がった。"}, {"id": "ch13-s04-p064", "type": "text", "text": "木が見えた。"}, {"id": "ch13-s04-p065", "type": "text", "text": "木の列。等間隔ではなく、少しずつずれた配置で並んでいる。十月にも見えた——暗い中に丸い影が並んでいた。丸い影の正体が、今回は見えた。"}, {"id": "ch13-s04-p066", "type": "text", "text": "蜜柑の木。"}, {"id": "ch13-s04-p067", "type": "text", "text": "低い幹。枝が横に広がっている。枝の先に実がついている。丸い。橙色。月明かりの中で、実の表面が鈍く光っている。完熟した蜜柑の表面の、あの微細な凹凸が月光を受けて銀色に縁取られている。"}, {"id": "ch13-s04-p068", "type": "text", "text": "蜜柑の木が、何本も並んでいた。果樹園。果樹園の中にいた。"}, {"id": "ch13-s04-p069", "type": "text", "text": "匂いが来た。十月に鼻孔に入った甘い匂い。あの時は「熟した果実の匂い」としか判別できなかった。今は——蜜柑の匂いだった。蜜柑の皮を剥いた時の、あの酸味のある甘さが空気に満ちていた。夜の果樹園に蜜柑の匂いが溜まっている。風がない。匂いが動かない。"}, {"id": "ch13-s04-p070", "type": "text", "text": "足元に視線が落ちた。"}, {"id": "ch13-s04-p071", "type": "text", "text": "自分の足が見えた。"}, {"id": "ch13-s04-p072", "type": "text", "text": "小さかった。"}, {"id": "ch13-s04-p073", "type": "text", "text": "子供の足。革の靴。靴の先が土を踏んでいる。靴が小さい。自分の足が——これは俺の足だ。俺の、子供の頃の足。"}, {"id": "ch13-s04-p074", "type": "text", "text": "手に温度があった。"}, {"id": "ch13-s04-p075", "type": "text", "text": "左手。誰かが俺の左手を握っている。大きい手ではなかった。俺の手より少しだけ大きい手。大人の手ではない。けれど子供の俺の手より、確かに大きい。温かい。握り方に力がある。引く力。前に歩いている。手を引かれている。"}, {"id": "ch13-s04-p076", "type": "text", "text": "誰かの背中が見えた。"}, {"id": "ch13-s04-p077", "type": "text", "text": "月明かりの中の背中。俺より背が高い。けれど大人ほど高くない。年上の子供か、あるいは——顔が見えない。前を向いている。手だけが俺の手を握っている。"}, {"id": "ch13-s04-p078", "type": "text", "text": "歌が聞こえた。"}, {"id": "ch13-s04-p079", "type": "text", "text": "十月に聞こえた歌声。あの時は「複数の人間が歌っている。輪唱」と聞こえた。今は——輪唱ではなかった。一つの声。前を歩いている人の声。手を引いているその人が、歌っている。"}, {"id": "ch13-s04-p080", "type": "text", "text": "高くない。低くもない。中間の声。子供の声のように軽く、けれど子供より少しだけ深い声。旋律がゆったりしていた。夜に合う歌。月の下で歌う歌。"}, {"id": "ch13-s04-p081", "type": "text", "text": "月夜唄。"}, {"id": "ch13-s04-p082", "type": "text", "text": "その名前が、鳩尾の奥から浮かんだ。記録カードに書いてあった名前ではなかった。九月に篠宮さんと地下書庫で読んだ三文字を思い出したのではなく、鳩尾の奥に沈殿していたものが浮かんできた。俺の中にあった名前。すみれが言った。「れんがもってきたの」。持ってきた。この歌の名前を、俺は持っていた。"}, {"id": "ch13-s04-p083", "type": "text", "text": "蜜柑の匂い。月の白い光。子供の自分の足。手を引く「誰か」の温かい手。月夜唄。"}, {"id": "ch13-s04-p084", "type": "text", "text": "全部が同時にあった。十月の断片は一秒にも満たなかった。感覚だけが残って映像は消えた。"}, {"id": "ch13-s04-p085", "type": "text", "text": "今回は違った。"}, {"id": "ch13-s04-p086", "type": "text", "text": "三秒。四秒。五秒。映像が続いている。果樹園の中を歩いている。手を引かれて。蜜柑の木の間を通り抜けている。月光が葉の影を地面に落としている。落ちた影を小さな靴が踏んでいる。手を引く人の歌声が、蜜柑の匂いの中で続いている。"}, {"id": "ch13-s04-p087", "type": "text", "text": "懐かしかった。"}, {"id": "ch13-s04-p088", "type": "text", "text": "懐かしいの一語では足りなかった。鳩尾の奥にある場所で、沈殿物が一斉に浮き上がっている。十月に沈んだものが底から剥がれて、上に向かっている。上に向かうものの中に——"}, {"id": "ch13-s04-p089", "type": "text", "text": "痛みが来た。"}, {"id": "ch13-s04-p090", "type": "text", "text": "頭。頭が痛い。こめかみの左側から後頭部にかけて、鋭いものが走った。"}, {"id": "ch13-s04-p091", "type": "text", "text": "掌が鐘から離れた。"}, {"id": "ch13-s04-p092", "type": "text", "text": "体が後退した。壁に背中が当たった。石壁の冷たさが背中の全面に触れた。石壁にもたれかかっていた。足が支えを失っている。壁だけが俺を立たせている。"}, {"id": "ch13-s04-p093", "type": "text", "text": "頭痛がひどかった。"}, {"id": "ch13-s04-p094", "type": "text", "text": "こめかみから後頭部へ走った痛みが消えない。脈拍と同じ間隔で打っている。視界が白い。白い——月光の白さが残像として目の裏に貼りついている。蜜柑の木の輪郭。子供の靴の先。手を引く人の背中。全部が白い残像の中で重なって、分離できない。"}, {"id": "ch13-s04-p095", "type": "text", "text": "呼吸を忘れていた。口を開けた。冷たい空気が喉を通った。一回目。浅い。二回目。まだ浅い。三回目でようやく肺の底まで空気が入った。"}, {"id": "ch13-s04-p096", "type": "text", "text": "右手が震えていた。さっきまで鐘に触れていた右手。指先が小さく振動している。十月の夜と同じ震え方。鳩尾の奥から来ている震え。"}, {"id": "ch13-s04-p097", "type": "text", "text": "けれど十月とは違うものがあった。"}, {"id": "ch13-s04-p098", "type": "text", "text": "十月は、断片だった。一秒にも満たない間に三つの感覚が押し寄せて消えた。砂を掴んだ。零れた。感覚の輪郭だけが残った。"}, {"id": "ch13-s04-p099", "type": "text", "text": "今夜は違った。"}, {"id": "ch13-s04-p100", "type": "text", "text": "映像があった。時間があった。場所があった。蜜柑の木が並ぶ果樹園を、月明かりの下で歩いていた。俺の手を握る誰かがいた。その人が月夜唄を歌っていた。"}, {"id": "ch13-s04-p101", "type": "text", "text": "断片ではなかった。"}, {"id": "ch13-s04-p102", "type": "text", "text": "記憶だった。"}, {"id": "ch13-s04-p103", "type": "text", "text": "俺の記憶。"}, {"id": "ch13-s04-p104", "type": "text", "text": "壁にもたれかかったまま、左手で頭を押さえた。右手はまだ震えている。こめかみの痛みが脈拍のたびに鳴っている。視界が白い残像から戻りかけている。残響灯の紫の光が、大鐘の曲面に落ちている。鐘の間。十階。ここは鐘の間だ。"}, {"id": "ch13-s04-p105", "type": "text", "text": "頭の中で、蜜柑の匂いがまだ漂っていた。鼻孔の奥にこびりついている。実際の匂いではない。記憶の匂い。記憶と呼んでいい。十月には「記憶と呼べるほど明確なものではない」と思った。今夜は——呼べる。呼べてしまう。"}, {"id": "ch13-s04-p106", "type": "text", "text": "手を引いていたのは誰だ。"}, {"id": "ch13-s04-p107", "type": "text", "text": "顔が見えなかった。背中だけ。月明かりの中の背中。俺より背が高く、けれど大人ほどではなかった。声が聞こえた。中間の高さの声で月夜唄を歌っていた。その声に、温かさがあった。温かさの種類は——"}, {"id": "ch13-s04-p108", "type": "text", "text": "わからない。頭が痛い。考えようとすると痛みが打つ。"}, {"id": "ch13-s04-p109", "type": "text", "text": "震える手で壁を押して体を起こした。膝に力を入れた。立てた。立てている。"}, {"id": "ch13-s04-p110", "type": "text", "text": "「……っ」"}, {"id": "ch13-s04-p111", "type": "text", "text": "声が漏れた。声にならない音が、唇の間から落ちた。"}, {"id": "ch13-s04-p112", "type": "text", "text": "大鐘が目の前にある。鐘に触れていた。鐘が自ら鳴った。鳴海さんの歌声の残響が鐘の中で共鳴した瞬間に、蓋が開いた。十月に「開きかけた」蓋が、今夜は——開いた。全開ではない。けれど隙間が広がった。隙間から溢れたものの量が、十月とは比較にならなかった。"}, {"id": "ch13-s04-p113", "type": "text", "text": "果樹園。蜜柑の木。子供の俺。手を引く誰か。月夜唄。"}, {"id": "ch13-s04-p114", "type": "text", "text": "五つの要素が、鳩尾の奥に沈んでいく。沈殿していく。十月の三つの断片と同じ場所に。けれど今夜のものは断片ではなく、もっと大きい。沈殿物の体積が増えている。鳩尾の底で、十月の月光と歌声と果樹園の匂いの上に、蜜柑の木と子供の靴と温かい手と歌う声が重なっている。"}, {"id": "ch13-s04-p115", "type": "text", "text": "層が厚くなっている。"}, {"id": "ch13-s04-p116", "type": "text", "text": "俺の中に、島がある。"}, {"id": "ch13-s04-p117", "type": "text", "text": "ルミエラ島。九月に篠宮さんと読んだ記録カード。「果樹園と月夜唄の伝統で知られた」。果樹園。月夜唄。カードに書かれた二つの単語が、今夜、俺の体の中で映像になった。"}, {"id": "ch13-s04-p118", "type": "text", "text": "「……俺は、あの島に、いたのか」"}, {"id": "ch13-s04-p119", "type": "text", "text": "声に出た。鐘の間に、俺の声だけが響いた。壁に吸われて消える前に、自分の声を自分の耳が聞いた。"}, {"id": "ch13-s04-p120", "type": "text", "text": "可能性ではなかった。"}, {"id": "ch13-s04-p121", "type": "text", "text": "九月に「ルミエラ島」の発音に迷いがなかった時は、既視感だった。十月に鐘に触れて月光と歌声と匂いが溢れた時は、「記憶かもしれない」だった。"}, {"id": "ch13-s04-p122", "type": "text", "text": "今夜は違う。蜜柑の木を見た。子供の自分の足を見た。手を引かれて歩いていた。月夜唄を聞いていた。あの場所にいた。あの果樹園にいた。あの島に、俺は——"}, {"id": "ch13-s04-p123", "type": "text", "text": "確信には至らない。至らないが、予感がある。予感という言葉では弱い。確信の一歩手前にいる。手を伸ばせば触れる距離に確信がある。けれど手を伸ばすと頭が痛む。"}, {"id": "ch13-s04-p124", "type": "text", "text": "壁に手をついたまま、呼吸を整えた。五回。六回。頭痛が脈拍三回分で弱まった。完全には消えない。こめかみの奥に鈍い痛みが残っている。"}, {"id": "ch13-s04-p125", "type": "text", "text": "携帯計器を回収した。数値を確認した。64パーセント。安定。記録用紙にペンで書いた。手が震えているから字が乱れた。けれど数字は読める。技師の仕事。震えていても数字は書ける。"}, {"id": "ch13-s04-p126", "type": "text", "text": "鐘の間を出た。"}, {"id": "ch13-s04-p127", "type": "text", "text": "螺旋階段を降りた。足が重い。石段を一段ずつ踏む。靴底が石の冷たさを報告してくる。報告を受け取る余裕がなかった。頭の中に蜜柑の匂いが残っている。左手に、あの温かさの跡がある。子供の頃の俺の手を握っていた、誰かの手の温度。"}, {"id": "ch13-s04-p128", "type": "text", "text": "十階。九階。共鳴の間の前を通った。扉は閉まっている。"}, {"id": "ch13-s04-p129", "type": "text", "text": "鳴海さんの歌声が、鐘にまだ残っている。鳴海さんの歌が鐘を支えた。鐘が鳴海さんの力で持ち直した。その鐘の振動が俺の記憶の蓋を押し開けた。"}, {"id": "ch13-s04-p130", "type": "text", "text": "全部が繋がっている。鳴海さんの歌と、鐘と、俺の中の島の音が、同じ場所を指している。"}, {"id": "ch13-s04-p131", "type": "choice_header", "text": "【選択肢】"}, {"id": "ch13-s04-p132", "type": "choice", "text": "**A:「……鳴海さん。すまないが、歌わないでくれ」**\n→ 千歳好感度 +2"}, {"id": "ch13-s04-p133", "type": "choice", "text": "**B:「……わかった」**\n→ 好感度変動なし"}, {"id": "ch13-s04-p134", "type": "divider", "text": "---"}, {"id": "ch13-s04-p135", "type": "choice_label", "text": "（選択肢A後の展開テキスト）"}, {"id": "ch13-s04-p136", "type": "text", "text": "声に出すことはなかった。出しても、鳴海さんには届かない。鳴海さんはもう補佐官舎に戻っているだろう。扉の向こうには誰もいない。"}, {"id": "ch13-s04-p137", "type": "text", "text": "けれど、その言葉が喉にあった。「歌わないでくれ」。鳴海さんの体が削れていくことも、俺の記憶の蓋が開くことも、全部が鳴海さんの歌声から始まっている。止めたかった。止めたいと思った。"}, {"id": "ch13-s04-p138", "type": "text", "text": "止められない。外円区の住民の安全と、鳴海さんの体調と。弦月局長の天秤。答えが出なかった天秤は、今夜もまだ鳩尾の上にある。"}, {"id": "ch13-s04-p139", "type": "text", "text": "けれど「歌わないでくれ」という言葉が喉にあること自体が、俺がまだ天秤を降ろしていない証拠だった。"}, {"id": "ch13-s04-p140", "type": "choice_label", "text": "（選択肢B後の展開テキスト）"}, {"id": "ch13-s04-p141", "type": "text", "text": "わかった、と呟いた。何がわかったのか、自分でも定かではなかった。"}, {"id": "ch13-s04-p142", "type": "text", "text": "鳴海さんが歌う。鐘が応える。鐘の力が戻る。鳴海さんの体が削れる。その構造を知って、受け入れる——のではなかった。受け入れたのではなく、鳴海さんの「わたしは歌いたいんです」を、受け止めた。止められないのではなく。鳴海さんが選んだものを、俺は「わかった」と言った。"}, {"id": "ch13-s04-p143", "type": "divider", "text": "---"}, {"id": "ch13-s04-p144", "type": "choice_label", "text": "（共通テキスト再合流）"}, {"id": "ch13-s04-p145", "type": "text", "text": "補佐官舎に戻った。鍵を開け、靴を脱ぎ、暗い部屋の中で寝台に座った。"}, {"id": "ch13-s04-p146", "type": "text", "text": "右手を膝の上に置いた。掌を上に向けた。暗くて見えない。十月の夜と同じ姿勢。同じ暗さ。同じ寝台。"}, {"id": "ch13-s04-p147", "type": "text", "text": "けれど掌の中にあるものが違った。十月は鐘の冷たさとすみれの冷たさ。二つの冷たさの跡。"}, {"id": "ch13-s04-p148", "type": "text", "text": "今夜は、温かさがあった。"}, {"id": "ch13-s04-p149", "type": "text", "text": "子供の頃の俺の手を握っていた誰かの手の温度。記憶の中の温度は、もう消えかけている。頭痛の残滓と混ざって、輪郭が溶けていく。けれど「温かかった」という感覚だけは残っている。掌の中に。鳩尾の底に。"}, {"id": "ch13-s04-p150", "type": "text", "text": "左手首のブレスレットの編み目に指が触れた。"}, {"id": "ch13-s04-p151", "type": "text", "text": "革の感触。編み込みの凹凸。発見された時から身につけていたもの。なぜ外す気にならないのか、わからなかった。今もわからない。けれど今夜、子供の俺の手を引いていた「誰か」の温かさと、左手首のブレスレットの間に、何かがあるような——"}, {"id": "ch13-s04-p152", "type": "text", "text": "頭が痛んだ。考えるな。今は。"}, {"id": "ch13-s04-p153", "type": "text", "text": "寝台に横になった。天井が暗い。窓の外に十二月の星がある。見えない。カーテンを引いていないが、天井の方を向いている。"}, {"id": "ch13-s04-p154", "type": "text", "text": "蜜柑の匂いが、まだ鼻の奥にある。"}, {"id": "ch13-s04-p155", "type": "text", "text": "果樹園。月夜唄。手を引く誰か。子供の俺。"}, {"id": "ch13-s04-p156", "type": "text", "text": "あの島に、いたのか。"}, {"id": "ch13-s04-p157", "type": "text", "text": "いた。たぶん。いた。"}]}, {"chapter": 13, "chapterTitle": "鐘が揺れる夜", "scene": 5, "sceneTitle": "アナザービュー：すみれの祈り", "wordCount": "約4,200字", "paragraphs": [{"id": "ch13-s05-p001", "type": "text", "text": "※アナザービュー：星見すみれ視点"}, {"id": "ch13-s05-p002", "type": "divider", "text": "---"}, {"id": "ch13-s05-p003", "type": "text", "text": "かねが、なんかいか、なった。"}, {"id": "ch13-s05-p004", "type": "text", "text": "すみれはそれでじかんをかぞえる。にんげんのとけいはわからない。すうじがならんでいて、はりがまわっていて、それがじかんだとにんげんはいう。すみれにとってじかんは、かねのおとのあいだのしずけさだった。しずけさがみじかければ、すこししかたっていない。ながければ、たくさんたっている。"}, {"id": "ch13-s05-p005", "type": "text", "text": "れんがいなくなってから、かねが——さんかい、なった。"}, {"id": "ch13-s05-p006", "type": "text", "text": "さんかいぶんのしずけさ。そのあいだに、そとのひかりがうごいた。てんがいのガラスのむこうで、しろいひかりがかたむいて、あかくなって、くらくなった。いまはくらい。ほしがある。"}, {"id": "ch13-s05-p007", "type": "text", "text": "すみれはてんがいのまのまんなかにすわっている。れんがすみれをかべぎわからまんなかにうつしてくれた。もうふがかたにかかっている。れんがもってきてくれたもうふ。うすいはいいろの、けだまがいくつかついたもうふ。もうふのなかに、れんのおんどのあとがある。"}, {"id": "ch13-s05-p008", "type": "text", "text": "もうふはもうあたたかくない。れんのおんどは、にんげんのおんどは、すみれのからだにはのこらない。うけとっても、うけとっても、すみれのなかをとおりぬけていく。みずがすなにしみこむのとおなじ。しみこんだあとは、またもとのつめたさにもどる。"}, {"id": "ch13-s05-p009", "type": "text", "text": "でも。"}, {"id": "ch13-s05-p010", "type": "text", "text": "すみれのてのこうに、れんのゆびがあったばしょがある。"}, {"id": "ch13-s05-p011", "type": "text", "text": "そこだけが、ほかのばしょとちがっている。つめたさはおなじ。おんどはおなじ。なのに、ちがう。れんのゆびがすみれのゆびをにぎったとき、おんどではないなにかが、そこにのこった。おんどはとおりぬけた。とおりぬけたあとに、かたちだけがのこっている。ゆびのかたち。にぎっていたかたち。"}, {"id": "ch13-s05-p012", "type": "text", "text": "すみれには、それのなまえがわからない。"}, {"id": "ch13-s05-p013", "type": "text", "text": "かねに、きいた。かねのおとのなかを、さがした。にんげんはこういうものに、なまえをつける。すみれはにんげんのことばのいくつかをしっている。かねのおとがおしえてくれたことばと、れんがくちにしたことばと、とうかがはこんできたことばを、すみれはもっている。"}, {"id": "ch13-s05-p014", "type": "text", "text": "あったかい。それはおんどのことば。"}, {"id": "ch13-s05-p015", "type": "text", "text": "すき。それはどらやきのことば。ほしのことば。"}, {"id": "ch13-s05-p016", "type": "text", "text": "いたい。それはかねのことば。きょうのことば。"}, {"id": "ch13-s05-p017", "type": "text", "text": "でもてのこうにのこっている「これ」は、あったかいでもすきでもいたいでもない。"}, {"id": "ch13-s05-p018", "type": "text", "text": "すみれだけのことばがほしい。にんげんのことばにはない、すみれだけのことば。"}, {"id": "ch13-s05-p019", "type": "break", "text": "◇"}, {"id": "ch13-s05-p020", "type": "text", "text": "かねがいたい。"}, {"id": "ch13-s05-p021", "type": "text", "text": "きょうのひるま、すみれはかべぎわでからだをまるくしていた。かねのいたみが、すみれのなかをながれていた。ながれるというのもちがう。かねのいたみは、すみれのいたみとおなじだった。べつのばしょにあるいたみがながれてくるのではなく、かねがいたいとき、すみれもいたい。おなじいたみが、ふたつのかたちでおきている。"}, {"id": "ch13-s05-p022", "type": "text", "text": "いまも、いたい。ひるまよりは、すこし、うすい。"}, {"id": "ch13-s05-p023", "type": "text", "text": "ちとせがうたってくれた。かねのおとのなかに、ちとせのこえがのこっている。ちとせのこえは、かねのきずぐちにしみこんで、すこしだけきずをふさいだ。ろくじゅうに、だったかねが、ろくじゅうよん、になった。れんがすみれにおしえてくれたすうじ。「ろくじゅうに」。すうじのかたちが、くちのなかにのこっている。れんのくちからでてきたすうじは、すみれのくちにもはいった。"}, {"id": "ch13-s05-p024", "type": "text", "text": "ちとせのこえのおかげで、かねのいたみがうすくなった。"}, {"id": "ch13-s05-p025", "type": "text", "text": "でもすみれは、ちとせのこえのなかにあるもうひとつのおとをきいている。"}, {"id": "ch13-s05-p026", "type": "text", "text": "ちとせのからだから、なにかがへっている。かねにわたしているぶんだけ、ちとせのなかの——なんとよべばいいかわからないもの——が、うすくなっている。すみれにはそれがきこえる。かねのおとのなかに、ちとせのおとがまじっていて、そのおとのなかに、ちいさなすきまがある。すきまは、まえより、おおきい。"}, {"id": "ch13-s05-p027", "type": "text", "text": "あげすぎてる。"}, {"id": "ch13-s05-p028", "type": "text", "text": "まえにもおもった。おもったけれど、ことばにできなかった。ちとせに、にんげんのことばでつたえるほうほうがわからない。かねがおしえてくれるのは、おとだけだから。おとを、もじにして、ぶんにして、にんげんにわたすためのかいろが、すみれのなかではつながっていない。"}, {"id": "ch13-s05-p029", "type": "text", "text": "れんは、しっている。れんは、ちとせのことをしんぱいしている。かねのおとのなかに、れんのしんぱいのおとがまじっている。あたらしいおと。れんがここにくるまえは、なかったおと。"}, {"id": "ch13-s05-p030", "type": "break", "text": "◇"}, {"id": "ch13-s05-p031", "type": "text", "text": "ほしを、かぞえようとした。"}, {"id": "ch13-s05-p032", "type": "text", "text": "ノートはひざのよこにある。えんぴつもある。でもきょうは、てがうまくうごかない。えんぴつをにぎると、ゆびがふるえる。かねのいたみが、ゆびのさきまでおりてくる。"}, {"id": "ch13-s05-p033", "type": "text", "text": "やめた。"}, {"id": "ch13-s05-p034", "type": "text", "text": "てんがいを、みあげた。ほしがある。いっぱいある。じゅうにがつのほしは、とがっている。じゅうがつにれんがおしえてくれた。「くうき、すむ」。すんだくうきのほしは、とがってみえる。きょうのほしもとがっている。"}, {"id": "ch13-s05-p035", "type": "text", "text": "れんがおしえてくれたことばを、すみれはぜんぶおぼえている。わくせい。くうき、すむ。ろくじゅうに。どらやき。おいしい。おはよう。すみれ。"}, {"id": "ch13-s05-p036", "type": "text", "text": "すみれ。"}, {"id": "ch13-s05-p037", "type": "text", "text": "れんがすみれのなまえをよぶとき、かねのおとが——かわる。"}, {"id": "ch13-s05-p038", "type": "text", "text": "ほかのだれがすみれのなまえをよんでも、かねのおとはかわらない。ひょうかがすみれのなまえをいうとき、おとはまっすぐでかたい。とうかがよぶとき、おとはまるくてあたたかい。いろはがよぶとき、おとはかるくてはずんでいる。"}, {"id": "ch13-s05-p039", "type": "text", "text": "れんがすみれのなまえをよぶとき、おとが——ふるえる。"}, {"id": "ch13-s05-p040", "type": "text", "text": "かねのなかで、なにかがこたえている。れんのこえがかねにとどいて、かねがそのこえにこたえて、こたえたおとがすみれのなかにかえってくる。それはすみれだけにきこえるおと。せかいのなかのたくさんのおとのなかで、「れんがすみれをよぶおと」だけが、すみれにだけかえってくるおと。"}, {"id": "ch13-s05-p041", "type": "text", "text": "それがなんなのか、すみれにはわからない。"}, {"id": "ch13-s05-p042", "type": "text", "text": "でも、そのおとをきくと、てのこうにのこっている「かたち」がうごく。おんどではないもの。なまえがないもの。「れんがすみれをよぶおと」をきくと、なまえがないものが、すこしだけおおきくなる。"}, {"id": "ch13-s05-p043", "type": "break", "text": "◇"}, {"id": "ch13-s05-p044", "type": "text", "text": "すみれは、しっている。"}, {"id": "ch13-s05-p045", "type": "text", "text": "かねのおとは、すべてをしっている。すみれはかねのおとをきいている。だからすみれも、しっている。"}, {"id": "ch13-s05-p046", "type": "text", "text": "れんのなかに、とおいしまのおとがある。しまのなまえは——かねのおとのなかに、ある。すみれはそのなまえを、おととしてしっている。もじにはできない。でも、しまのおとは、しっている。れんがまだちいさかったころ、しまにいたことを、しっている。"}, {"id": "ch13-s05-p047", "type": "text", "text": "れんをまもったひとがいた。"}, {"id": "ch13-s05-p048", "type": "text", "text": "かねのおとのなかに、そのひとのこえがのこっている。うたっていた。よるに、つきのしたで、うたっていた。れんのてをにぎって、きのあいだをあるいて、うたっていた。そのこえはかねのおとのなかでいまもなっている。なくなったしまのおとのなかに、のこっている。"}, {"id": "ch13-s05-p049", "type": "text", "text": "れんは、そのことをおぼえていない。"}, {"id": "ch13-s05-p050", "type": "text", "text": "おぼえていないけれど、れんのなかで、まだなっている。じゅうがつに、すみれがおしえた。「とおいしまのおとがある」。れんのかおが——かわった。おとがかわった。れんのなかのしまのおとが、くるしそうになった。くるしそうになったから、すみれは「かなしいおとじゃないよ」とおしえた。"}, {"id": "ch13-s05-p051", "type": "text", "text": "きょう、れんがかねにさわった。よるに。さわったとき、かねのなかにのこっていたちとせのこえのざんきょうが、れんのなかのしまのおとにふれた。ふれて、ふたがひらいた。"}, {"id": "ch13-s05-p052", "type": "text", "text": "すみれには、それがきこえた。"}, {"id": "ch13-s05-p053", "type": "text", "text": "れんのなかから、たくさんのおとがあふれた。しまのおと。きのおと。つちのおと。つきのひかりのおと。みかんのにおいのおと。てをひくひとのおと。うたのおと。"}, {"id": "ch13-s05-p054", "type": "text", "text": "あふれたおとが、れんをいためた。あたまがいたくなった。からだがふるえた。すみれにはぜんぶきこえていた。じゅういっかいのてんがいのまから、じゅっかいのかねのまのおとが、かねをとおしてすみれにとどいていた。"}, {"id": "ch13-s05-p055", "type": "text", "text": "れんは、おもいだしている。"}, {"id": "ch13-s05-p056", "type": "text", "text": "おもいだすのは、いたい。でも——"}, {"id": "ch13-s05-p057", "type": "break", "text": "◇"}, {"id": "ch13-s05-p058", "type": "text", "text": "すみれは、もうふのなかでひざをだいた。"}, {"id": "ch13-s05-p059", "type": "text", "text": "れんは、おもいだす。おもいだすのは、いたい。でも、おもいださないと、れんはれんにもどれない。"}, {"id": "ch13-s05-p060", "type": "text", "text": "すみれは、れんのなかにある「れん」のかたちを、かねのおとをとおしてしっている。いまのれんは、かたちのいちぶがかけている。かけたぶぶんに、しまのおとがはまる。はまれば、れんのかたちがもどる。もどるためには、おもいだすしかない。"}, {"id": "ch13-s05-p061", "type": "text", "text": "おもいだすのは、いたい。かねにさわったあとのれんのおとが、いたそうだった。あたまをおさえていた。かべにもたれていた。"}, {"id": "ch13-s05-p062", "type": "text", "text": "すみれにつたえられたら、いいのに。"}, {"id": "ch13-s05-p063", "type": "text", "text": "しまのこと。うたのこと。てをひいてくれたひとのこと。ぜんぶ、かねのおとのなかにある。すみれは、きいている。きいているけれど、ことばにできない。にんげんのことばにすると、ぜんぶがちいさくなる。おとのなかにある、おおきくてまるいかたまりが、ことばにしたしゅんかんに、ちいさくてかくかくしたものになる。れんにわたしたいのは、おおきくてまるいかたまりのほう。でもすみれのくちからは、ちいさくてかくかくしたことばしかでない。"}, {"id": "ch13-s05-p064", "type": "text", "text": "すみれは——まっている。"}, {"id": "ch13-s05-p065", "type": "text", "text": "れんが、おもいだすのを。れんのなかのしまのおとが、ぜんぶかえってくるのを。かえってきたら、れんはれんになる。かけていたぶぶんがうまって、れんのかたちがまるくなる。"}, {"id": "ch13-s05-p066", "type": "text", "text": "そのとき、れんはかなしくなるかもしれない。おもいだしたものがうしなわれていることを、しるから。しまはもうない。うたっていたひとも、もういない。"}, {"id": "ch13-s05-p067", "type": "text", "text": "でもすみれは、ここにいる。"}, {"id": "ch13-s05-p068", "type": "text", "text": "かねがなっているあいだ、すみれはここにいる。れんがかなしくなったら、すみれはてをだす。つめたいて。あったかくないて。でも、ここにあるて。れんが、にぎってくれたて。"}, {"id": "ch13-s05-p069", "type": "text", "text": "かねがよわくなると、すみれもよわくなる。ろくじゅうよんは、まだだいじょうぶ。でもすうじがもっとさがったら、すみれのからだはもっとつめたくなって、もっとおもくなって、もっとうごけなくなる。さいごには——"}, {"id": "ch13-s05-p070", "type": "text", "text": "すみれは、それをしっている。かねがとまったら、すみれもとまる。"}, {"id": "ch13-s05-p071", "type": "text", "text": "でも。"}, {"id": "ch13-s05-p072", "type": "text", "text": "れんがいるから、まだ、だいじょうぶ。"}, {"id": "ch13-s05-p073", "type": "text", "text": "なぜ「だいじょうぶ」なのか、すみれにはうまくせつめいできない。かねのすうじがあがるわけではない。すみれのからだがあたたかくなるわけではない。れんがいても、かねはよわいままで、すみれはつめたいままで、せかいはおわりにむかっている。"}, {"id": "ch13-s05-p074", "type": "text", "text": "でもれんのゆびが、すみれのゆびをにぎったとき——"}, {"id": "ch13-s05-p075", "type": "text", "text": "おんどではないなにかが、のこった。"}, {"id": "ch13-s05-p076", "type": "text", "text": "そのなにかが、すみれを「だいじょうぶ」にしている。"}, {"id": "ch13-s05-p077", "type": "break", "text": "◇"}, {"id": "ch13-s05-p078", "type": "text", "text": "てんがいのむこうで、ほしがゆっくりうごいている。にしにかたむいている。すみれはそのうごきでじかんをしっている。"}, {"id": "ch13-s05-p079", "type": "text", "text": "もうふをひきよせた。れんのおんどはもうない。でも、もうふはれんがもってきてくれた。もうふのけだまに、すみれのゆびがふれた。まるいけだま。ちいさい。"}, {"id": "ch13-s05-p080", "type": "text", "text": "すみれはここにいるよ。いつでも。"}, {"id": "ch13-s05-p081", "type": "text", "text": "てんがいのガラスのむこうで、ほしがとがっている。じゅうにがつのほし。すんだくうきのほし。"}, {"id": "ch13-s05-p082", "type": "text", "text": "すみれはめをとじた。"}, {"id": "ch13-s05-p083", "type": "text", "text": "かねのおとがきこえている。よわい。よわいけれど、なっている。ろくじゅうよんぶんのおと。そのおとのなかに、ちとせのこえのざんきょうがある。そのざんきょうのなかに、しまのおとがある。しまのおとのなかに、うたがある。うたのなかに、れんをまもったひとのこえがある。"}, {"id": "ch13-s05-p084", "type": "text", "text": "ぜんぶが、つながっている。"}, {"id": "ch13-s05-p085", "type": "text", "text": "そしてそのおとのぜんぶのなかに、もうひとつ、ある。"}, {"id": "ch13-s05-p086", "type": "text", "text": "「れん」。"}, {"id": "ch13-s05-p087", "type": "text", "text": "すみれだけにきこえるおと。すみれだけにかえってくるおと。せかいのざんきょうのひとつではなく、すみれだけの——"}, {"id": "ch13-s05-p088", "type": "text", "text": "ことばがない。にんげんのことばには、ない。"}, {"id": "ch13-s05-p089", "type": "text", "text": "すみれはもうふのなかで、てのこうをむねにあてた。"}, {"id": "ch13-s05-p090", "type": "text", "text": "おんどではないなにかが、そこにある。"}, {"id": "ch13-s05-p091", "type": "text", "text": "ゆびのかたち。にぎっていたかたち。のこっているかたち。"}, {"id": "ch13-s05-p092", "type": "text", "text": "そのかたちを、すみれはにんげんのことばではよばない。よべない。よべないけれど、すみれのなかにある。"}, {"id": "ch13-s05-p093", "type": "text", "text": "すみれは、まっている。"}, {"id": "ch13-s05-p094", "type": "text", "text": "れんがれんにもどるのを、まっている。"}, {"id": "ch13-s05-p095", "type": "text", "text": "かねのおとが、よるのてんがいのまをみたしている。よわいおと。でも、なっている。まだ、なっている。"}]}, {"chapter": 14, "chapterTitle": "境界の向こう", "scene": 1, "sceneTitle": "第一監視哨", "wordCount": "約6,200字", "paragraphs": [{"id": "ch14-s01-p001", "type": "text", "text": "十二月の朝は暗かった。"}, {"id": "ch14-s01-p002", "type": "text", "text": "補佐官舎を出たのは六時前で、空の東側が灰色から鈍い橙に変わりかけている頃だった。鐘鋳塔の六時の鐘がまだ鳴っていない。寒い。吐く息が白い。"}, {"id": "ch14-s01-p003", "type": "text", "text": "玄関を出ると、石畳の上に靴音が一つ、先にあった。"}, {"id": "ch14-s01-p004", "type": "text", "text": "晶さんが立っていた。"}, {"id": "ch14-s01-p005", "type": "text", "text": "黒いハーフコート。低いポニーテール。左胸の階級章。いつもの縁際監視哨の制服。しかし今朝の晶さんの姿勢は、南門の前で壁に寄りかかっていた十月とも、見晴らし丘で背筋を伸ばしていた八月とも違った。両足を揃えて立ち、手が体の横にある。待機の姿勢。部下を迎えにきた上官の立ち方。"}, {"id": "ch14-s01-p006", "type": "text", "text": "補佐官舎の前に、なぜ。"}, {"id": "ch14-s01-p007", "type": "text", "text": "「蓮。着替えろ。歩ける格好で来い」"}, {"id": "ch14-s01-p008", "type": "text", "text": "声が短かった。業務報告の声でも、「深入りするな」の声でもなかった。指示。明確な目的のある指示の声。"}, {"id": "ch14-s01-p009", "type": "text", "text": "「どこにですか」"}, {"id": "ch14-s01-p010", "type": "text", "text": "「見せたいものがある」"}, {"id": "ch14-s01-p011", "type": "text", "text": "それだけだった。晶さんは説明を足さなかった。琥珀色の瞳がこちらを見ている。十月の南門で寂しさを見せた瞳。今朝の目は、何かを決めた人の目だった。"}, {"id": "ch14-s01-p012", "type": "text", "text": "鐘鋳塔の六時の鐘が鳴った。"}, {"id": "ch14-s01-p013", "type": "text", "text": "鐘の音を体で受けた。十三日間、毎朝受けている音。十二月に入ってから出力補完歌唱が始まり、鐘の出力は64から65の間を行き来している。鳴海さんの歌声が鐘を支え、鐘が島を支え、鳴海さんの体が削られていく。その構造は変わっていない。変わっていないまま、十三日が過ぎた。"}, {"id": "ch14-s01-p014", "type": "text", "text": "今朝の鐘の音は、胸骨の手前で止まった。64パーセントの深さ。昨日と同じ。"}, {"id": "ch14-s01-p015", "type": "text", "text": "「五分で戻ります」"}, {"id": "ch14-s01-p016", "type": "text", "text": "言って、補佐官舎に戻った。"}, {"id": "ch14-s01-p017", "type": "break", "text": "◇"}, {"id": "ch14-s01-p018", "type": "text", "text": "晶さんの後について歩いた。"}, {"id": "ch14-s01-p019", "type": "text", "text": "中円区を抜け、外円区に入った。道が広くなった。農地の間を細い道が伸びている。冬枯れの畑。黒い土。空が大きい。中円区の密集した建物に遮られていた空が、外円区では地平線の近くまで見える。"}, {"id": "ch14-s01-p020", "type": "text", "text": "晶さんは一度も振り返らなかった。歩幅は正規の軍人の歩幅。十月の南門で見せた「半歩遅い」歩きではなかった。目的地がある人の歩き方。"}, {"id": "ch14-s01-p021", "type": "text", "text": "冬の風が吹いていた。乾いた風。農地の土の匂いを運んでくる。風に混じって、かすかに粉のような匂いがあった。乾いた粉。嗅ぎ覚えのない匂い——いや、体は知っている。縁際にいた二年間で、体が覚えた匂い。記憶にはない。けれど鼻腔の奥が「これだ」と反応した。"}, {"id": "ch14-s01-p022", "type": "text", "text": "蝕域が近い。"}, {"id": "ch14-s01-p023", "type": "text", "text": "外円区の風景が変わり始めた。農地が途切れた。家がなくなった。道の両側に低い草が生えているだけの、広い空間。空が白い。白いのは雲ではなかった。空の一部が——色を失っている。青さが薄まり、太陽の光が弱く感じられる場所がある。"}, {"id": "ch14-s01-p024", "type": "text", "text": "縁際に近づいている。"}, {"id": "ch14-s01-p025", "type": "text", "text": "晶さんの背中が、ここでわずかに変わった。肩が上がった。首の角度が前傾になった。前方を警戒する姿勢。隊長の姿勢。この人はここで毎日、世界の端を見ている。"}, {"id": "ch14-s01-p026", "type": "text", "text": "三十分ほど歩いて、建物が見えた。"}, {"id": "ch14-s01-p027", "type": "text", "text": "低い。二階建て。灰色のコンクリートの壁。屋根に観測塔が載っている。観測塔の高さは二十メートルほど。先端に風速計とアンテナがある。壁面に「第一監視哨」と刻まれた鉄のプレートが錆びかけている。"}, {"id": "ch14-s01-p028", "type": "text", "text": "晶さんが立ち止まった。"}, {"id": "ch14-s01-p029", "type": "text", "text": "「ここだ」"}, {"id": "ch14-s01-p030", "type": "text", "text": "短い一語。俺の方を見た。琥珀色の瞳に、今朝の「決めた」色がまだある。しかしそこに、一筋だけ別のものが混ざっていた。気づかなければ見逃す程度の。何と呼べばいいのかわからない。祈りに近い。"}, {"id": "ch14-s01-p031", "type": "text", "text": "「入るぞ」"}, {"id": "ch14-s01-p032", "type": "text", "text": "晶さんが鉄の扉を押した。"}, {"id": "ch14-s01-p033", "type": "break", "text": "◇"}, {"id": "ch14-s01-p034", "type": "text", "text": "一歩目で、足が止まった。"}, {"id": "ch14-s01-p035", "type": "text", "text": "タイルだった。"}, {"id": "ch14-s01-p036", "type": "text", "text": "灰色の、細かいモザイクタイルの床。靴底がタイルの目地を踏んだ瞬間に、足裏が報告してきた。知っている。この感触を知っている。"}, {"id": "ch14-s01-p037", "type": "text", "text": "記憶には何もなかった。灰色のタイルの床を見ても、頭には何の映像も浮かばなかった。けれど足裏が「ここを歩いたことがある」と言っている。歩幅が変わった。三歩目から、靴底がタイルの目地の上を正確に避けるようになった。意図していない。足が、目地のパターンを知っている。"}, {"id": "ch14-s01-p038", "type": "text", "text": "晶さんが後ろから見ていた。足音が止まっていた。俺の歩き方を観察している。"}, {"id": "ch14-s01-p039", "type": "text", "text": "廊下を進んだ。左側に窓がある。窓ガラスが汚れている。薄い埃の膜を通して、外の景色が見える。灰色の空。白い。白さが地面から空に向かって立ち上がっている。蝕域の方角。"}, {"id": "ch14-s01-p040", "type": "text", "text": "右側に部屋が並んでいた。扉が開いている部屋がある。机と椅子。観測機器のケーブルが壁から垂れている。部屋の匂い。コンクリートと埃と、古い金属の匂い。"}, {"id": "ch14-s01-p041", "type": "text", "text": "足が、四番目の部屋の前で遅くなった。"}, {"id": "ch14-s01-p042", "type": "text", "text": "「……」"}, {"id": "ch14-s01-p043", "type": "text", "text": "扉は閉まっていた。木の扉。取っ手は真鍮。真鍮が黒ずんでいる。"}, {"id": "ch14-s01-p044", "type": "text", "text": "手が伸びた。取っ手に触れた。親指の腹が、真鍮の表面の凹みに収まった。指紋が一致するように。この取っ手を何百回も握った手の記憶。"}, {"id": "ch14-s01-p045", "type": "text", "text": "晶さんの足音が後ろで止まった。"}, {"id": "ch14-s01-p046", "type": "text", "text": "「……覚えているか」"}, {"id": "ch14-s01-p047", "type": "text", "text": "低い声。問いかけだった。しかし答えを求めていなかった。俺の手が取っ手に触れている姿を見て、答えはもう得ている声。"}, {"id": "ch14-s01-p048", "type": "text", "text": "覚えていない。"}, {"id": "ch14-s01-p049", "type": "text", "text": "頭には何もない。四番目の部屋が何の部屋だったのか、俺にはわからない。窓はあるのか、机はいくつあるのか、壁に何が掛かっているのか。何も浮かばない。"}, {"id": "ch14-s01-p050", "type": "text", "text": "けれど手が知っている。足裏がタイルの目地を知っている。親指が取っ手の凹みを知っている。体がこの建物を覚えている。"}, {"id": "ch14-s01-p051", "type": "text", "text": "既視感ではなかった。"}, {"id": "ch14-s01-p052", "type": "text", "text": "既視感は「見たことがある気がする」という曖昧な揺らぎだ。今、俺の体が報告しているのはもっと具体的だった。距離。足裏からタイルの目地までの距離。親指から取っ手の凹みまでの角度。歩幅の間隔。全てが数値のように正確で、頭はその数値の意味を知らない。"}, {"id": "ch14-s01-p053", "type": "text", "text": "「晶さん」"}, {"id": "ch14-s01-p054", "type": "text", "text": "声に出した。振り返った。晶さんが四歩後ろに立っていた。"}, {"id": "ch14-s01-p055", "type": "text", "text": "「俺は、ここにいたんですか」"}, {"id": "ch14-s01-p056", "type": "text", "text": "「ああ」"}, {"id": "ch14-s01-p057", "type": "text", "text": "一音。静かだった。"}, {"id": "ch14-s01-p058", "type": "text", "text": "「蓮。お前はここで二年間働いていた。記憶を失った後の二年間。私の部隊に配属されていた」"}, {"id": "ch14-s01-p059", "type": "text", "text": "知っている。知っていた。晶さんが縁際監視哨の隊長であること、俺がかつてそこにいたこと、それは六月の再会の時に聞いている。書類にも書いてある。しかし書類の文字と、今、手の下にある真鍮の感触は、まるで別のものだった。"}, {"id": "ch14-s01-p060", "type": "text", "text": "書類は情報だった。取っ手は実感だった。"}, {"id": "ch14-s01-p061", "type": "text", "text": "「……ここが、俺の部屋だったんですか」"}, {"id": "ch14-s01-p062", "type": "text", "text": "「機器室だ。お前はいつもここで観測機器の整備をしていた。手が早かった。私の部隊で一番」"}, {"id": "ch14-s01-p063", "type": "text", "text": "晶さんの声に、硬さがなかった。八月の「深入りするな」の鋭さも、十月の「それでいい」の温度の奥にある壁もなかった。事実を語っている。過去を語っている。この人が見ていた俺の過去を。"}, {"id": "ch14-s01-p064", "type": "text", "text": "手を取っ手から離した。指先に真鍮の冷たさが残った。"}, {"id": "ch14-s01-p065", "type": "text", "text": "「上に行く」"}, {"id": "ch14-s01-p066", "type": "text", "text": "晶さんが言った。"}, {"id": "ch14-s01-p067", "type": "break", "text": "◇"}, {"id": "ch14-s01-p068", "type": "text", "text": "屋上に出た。"}, {"id": "ch14-s01-p069", "type": "text", "text": "観測塔の基部にある鉄の階段を昇り、二階のハッチを押し開けると、風が来た。"}, {"id": "ch14-s01-p070", "type": "text", "text": "冬の風。乾いている。粉の匂いが強い。コンクリートの屋上は手すりだけで遮るもののない平面で、東西南北に開けている。"}, {"id": "ch14-s01-p071", "type": "text", "text": "北を向いた。"}, {"id": "ch14-s01-p072", "type": "text", "text": "世界が——なかった。"}, {"id": "ch14-s01-p073", "type": "text", "text": "空と地面の境界線の向こう。監視哨から数百メートル先。そこから先が存在していなかった。"}, {"id": "ch14-s01-p074", "type": "text", "text": "白かった。"}, {"id": "ch14-s01-p075", "type": "text", "text": "白い光の壁のように見えた。壁ではない。壁には厚みがある。あれには厚みがない。奥行きもない。ただ白い光が揺らいでいる。脈動。不規則なリズムで、白光の表面が緩やかに伸縮している。巨大な生き物の呼吸のような動き。しかし生き物ではない。あれは「ない」だ。何もない。地面がない。空がない。空気がない。"}, {"id": "ch14-s01-p076", "type": "text", "text": "蝕域。"}, {"id": "ch14-s01-p077", "type": "text", "text": "八月の見晴らし丘から遠くに見た薄い靄。あの時は「灰白色の、脈打つ輪郭」だった。遠かった。建物の向こう、農地の向こう、縁際の向こうに、靄として見えていた。"}, {"id": "ch14-s01-p078", "type": "text", "text": "今は目の前だった。"}, {"id": "ch14-s01-p079", "type": "text", "text": "距離が違った。距離が違うと、見えるものが違った。"}, {"id": "ch14-s01-p080", "type": "text", "text": "蝕域の表面に微細な粒子が漂っていた。光の塵。白い光の中で、もっと白い何かが舞っている。消滅した物の粒子。かつてそこにあったもの——土や、草や、石や、あるいは人間だったものが、光の塵になって漂っている。美しかった。美しいと思った体の反応と同時に、胃の底が落ちた。"}, {"id": "ch14-s01-p081", "type": "text", "text": "音が薄かった。"}, {"id": "ch14-s01-p082", "type": "text", "text": "屋上に出た時に聞こえていた風の音が、北を向いた途端に弱くなった。音が吸われている。蝕域が音を飲んでいる。自分の呼吸の音がはっきり聞こえた。普段なら風に紛れて聞こえない呼吸が、ここでは聞こえる。他の音が消えているから。"}, {"id": "ch14-s01-p083", "type": "text", "text": "空気が粉っぽかった。乾いた、紙を千切ったような匂い。温度は変わらない。十二月の寒さのはず。けれど体が「薄い」と報告している。空気の密度が薄い。酸素が足りないのではなく、「存在」が薄い。"}, {"id": "ch14-s01-p084", "type": "text", "text": "そして——"}, {"id": "ch14-s01-p085", "type": "text", "text": "体が、動いた。"}, {"id": "ch14-s01-p086", "type": "text", "text": "意図していない。"}, {"id": "ch14-s01-p087", "type": "text", "text": "胸骨の裏で、何かが急に速くなった。脈拍が上がった。呼吸が浅くなった。膝が震え始めた。手が冷たくなった。指先から血が引いている感覚。恐怖の身体反応。しかし恐怖だけでは説明がつかなかった。"}, {"id": "ch14-s01-p088", "type": "text", "text": "恐怖なら、体は逃げようとするはずだった。"}, {"id": "ch14-s01-p089", "type": "text", "text": "逃げていなかった。"}, {"id": "ch14-s01-p090", "type": "text", "text": "体は前に出ようとしていた。"}, {"id": "ch14-s01-p091", "type": "text", "text": "右足が一歩、手すりの方に動いた。自分の意志ではなかった。鳩尾の奥ではなく——もっと深い場所。腹の底。背骨の裏側。名前のない場所が、あの白い光に向かって引っ張られている。"}, {"id": "ch14-s01-p092", "type": "text", "text": "腕が上がった。"}, {"id": "ch14-s01-p093", "type": "text", "text": "右手が手すりの上を越えて、北に向かって伸びた。指先が蝕域の方角を指している。触れようとしている。指先とあの白い光の間には数百メートルの距離がある。触れるはずがない。けれど手が伸びた。手が——帰ろうとしている。"}, {"id": "ch14-s01-p094", "type": "text", "text": "帰る。"}, {"id": "ch14-s01-p095", "type": "text", "text": "その言葉が鳩尾の底から浮かんだ。帰る。あそこに。あの白い中に。体がそう言っている。俺の体が、あの「ない」の中を知っている。知っていて、戻ろうとしている。"}, {"id": "ch14-s01-p096", "type": "text", "text": "意味がわからなかった。わからないのに手が止まらなかった。指先がもう一寸、もう一寸と前に——"}, {"id": "ch14-s01-p097", "type": "text", "text": "「蓮！」"}, {"id": "ch14-s01-p098", "type": "text", "text": "腕を掴まれた。"}, {"id": "ch14-s01-p099", "type": "text", "text": "強い力。右腕を後ろに引かれた。体が半回転した。北から南を向いた。手すりから離された。"}, {"id": "ch14-s01-p100", "type": "text", "text": "晶さんの手が俺の前腕を掴んでいた。"}, {"id": "ch14-s01-p101", "type": "text", "text": "革手袋越しの圧力。指が前腕の骨に食い込んでいる。晶さんの腕が震えていた。指先ではなく、肘から先の全体が。軍人の腕。監視哨の隊長の腕。その腕が震えている。"}, {"id": "ch14-s01-p102", "type": "text", "text": "「……触れるな」"}, {"id": "ch14-s01-p103", "type": "text", "text": "声が低かった。"}, {"id": "ch14-s01-p104", "type": "text", "text": "低いだけではなかった。声の中に、聞いたことのないものがあった。六月の「深入りするな」には鋭さがあった。八月の「あまり深入りするな」には切迫があった。十月の「それでいい」には温度があった。"}, {"id": "ch14-s01-p105", "type": "text", "text": "今の声には、もっと別のものが入っていた。"}, {"id": "ch14-s01-p106", "type": "text", "text": "懇願だった。"}, {"id": "ch14-s01-p107", "type": "text", "text": "「触れるな」は命令の形をしていた。軍人の命令。上官から部下への制止。しかし声に載っている感情は命令ではなかった。この人は頼んでいる。俺に、あれに触れないでくれと。"}, {"id": "ch14-s01-p108", "type": "text", "text": "晶さんの琥珀色の瞳が近かった。数十センチの距離。瞳の奥が揺れていた。十月に見た寂しさの揺れではなかった。もっと深い。もっと古い。この場所に紐づいた感情。"}, {"id": "ch14-s01-p109", "type": "text", "text": "この場所で——晶さんは何かを見ている。俺ではない。俺を掴みながら、俺の向こうに、あの白い光の中に、何かを見ている。"}, {"id": "ch14-s01-p110", "type": "text", "text": "三年前。"}, {"id": "ch14-s01-p111", "type": "text", "text": "俺がここで発見された。蝕域の端で。晶さんの部隊に。晶さんがこの場所で、俺を見つけた。"}, {"id": "ch14-s01-p112", "type": "text", "text": "この人にとって、この場所は——"}, {"id": "ch14-s01-p113", "type": "text", "text": "「……晶さん」"}, {"id": "ch14-s01-p114", "type": "text", "text": "声が出た。掠れていた。自分の声が遠かった。耳に入る前に蝕域に吸われている。"}, {"id": "ch14-s01-p115", "type": "text", "text": "晶さんの手が、俺の前腕から離れなかった。"}, {"id": "ch14-s01-p116", "type": "text", "text": "掴んだままだった。震えたまま。離す気配がなかった。"}, {"id": "ch14-s01-p117", "type": "text", "text": "「……すまない」"}, {"id": "ch14-s01-p118", "type": "text", "text": "晶さんが言った。謝罪ではなかった。声が震えていた。低い声が震えると、周波数が不安定になり、音の輪郭が滲む。晶さんの声が滲んでいた。"}, {"id": "ch14-s01-p119", "type": "text", "text": "「ここに連れてきた理由は、後で話す。まず——離れろ。あれから離れろ」"}, {"id": "ch14-s01-p120", "type": "text", "text": "俺は晶さんの手に引かれるまま、北から三歩、四歩、下がった。蝕域から離れた。手すりとの距離が開いた。"}, {"id": "ch14-s01-p121", "type": "text", "text": "胸骨の裏の速さが残っている。呼吸が浅いままだ。膝がまだ揺れている。"}, {"id": "ch14-s01-p122", "type": "text", "text": "けれど——あの衝動は薄まった。"}, {"id": "ch14-s01-p123", "type": "text", "text": "手を引いていた力が弱まっている。蝕域から離れるほど、体が前に出ようとする力が弱くなる。距離。距離が効いている。"}, {"id": "ch14-s01-p124", "type": "text", "text": "右手を見た。さっきまで蝕域に向かって伸ばしていた手。指先は何ともなかった。何にも触れていない。触れる前に晶さんが止めた。"}, {"id": "ch14-s01-p125", "type": "text", "text": "指先が微かに光っていた。"}, {"id": "ch14-s01-p126", "type": "text", "text": "白い。残響灯の紫ではない。蝕域と同じ、白い光の粒子。極めて微細な、光の塵が指先に一粒、二粒、付着している。手を伸ばしただけで。触れてすらいないのに。"}, {"id": "ch14-s01-p127", "type": "text", "text": "晶さんが俺の指先を見た。見て、目を閉じた。十月に「晶さん」と呼んだ時と同じ、まばたきより長い目閉じ。しかし今回は三秒では終わらなかった。五秒。六秒。目蓋の裏で何かを堪えている。"}, {"id": "ch14-s01-p128", "type": "text", "text": "目が開いた時、琥珀色の瞳には壁が一枚、戻っていた。"}, {"id": "ch14-s01-p129", "type": "text", "text": "「座れ。少し待て」"}, {"id": "ch14-s01-p130", "type": "text", "text": "晶さんが俺の肩に手を置いた。掌の重さ。革手袋の下の体温。"}, {"id": "ch14-s01-p131", "type": "text", "text": "俺は屋上のコンクリートの上に座った。冬の冷たさが臀部から背骨に上がってくる。北を背にして座った。蝕域を背にして。見ないでいい方角に向かって。"}, {"id": "ch14-s01-p132", "type": "text", "text": "南の方角に、遠く、鐘鋳塔の尖塔が見えた。灰色の空の中に白い石造りの塔が立っている。ここから見る鐘鋳塔は、機構室の窓から見上げる塔とはまるで違った。遠い。小さい。空の下でひどく頼りない。"}, {"id": "ch14-s01-p133", "type": "text", "text": "あの塔の中に、鐘がある。鳴海さんの歌が支えている鐘が。すみれが繋がっている鐘が。俺が毎朝触れている鐘が。"}, {"id": "ch14-s01-p134", "type": "text", "text": "あの鐘の音が、あの白い「ない」を押し返している。"}, {"id": "ch14-s01-p135", "type": "text", "text": "晶さんが俺の横に立っていた。座らなかった。立ったまま、南を向いていた。俺と同じ方角を見ていた。"}, {"id": "ch14-s01-p136", "type": "text", "text": "右腕にまだ晶さんの指の圧力が残っている。"}, {"id": "ch14-s01-p137", "type": "text", "text": "手首のブレスレットの革の編み目が肌に触れた。発見された時から身につけている革紐。この紐の来歴を、俺は知らない。"}, {"id": "ch14-s01-p138", "type": "text", "text": "さっきの衝動を考えた。体が蝕域に向かった。帰ろうとした。何に帰ろうとしたのか。俺の体はあの白い「ない」の中を知っている。知っているから帰ろうとする。なぜ知っている。いつ知った。"}, {"id": "ch14-s01-p139", "type": "text", "text": "わからなかった。"}, {"id": "ch14-s01-p140", "type": "text", "text": "頭が答えを出さない。体は知っているのに頭は知らない。タイルの目地。取っ手の凹み。そしてあの白い光への衝動。全てが体の中にあって、記憶にはない。"}, {"id": "ch14-s01-p141", "type": "text", "text": "晶さんが口を開いた。"}, {"id": "ch14-s01-p142", "type": "text", "text": "「……あの日も、こうだった」"}, {"id": "ch14-s01-p143", "type": "text", "text": "低い声。独り言のような音量。風に混ざりかけていた。"}, {"id": "ch14-s01-p144", "type": "text", "text": "「三年前。お前を見つけた時も。お前の手が、蝕域の方を向いていた」"}, {"id": "ch14-s01-p145", "type": "text", "text": "俺は晶さんを見上げた。"}, {"id": "ch14-s01-p146", "type": "text", "text": "晶さんの横顔は南を向いたまま、動かなかった。ハーフコートの襟が風を受けている。低いポニーテールは揺れていない。硬い髪。十月の南門と同じ。けれど目尻に、十月にはなかった線が一本あった。"}, {"id": "ch14-s01-p147", "type": "text", "text": "「後で話す。全部」"}, {"id": "ch14-s01-p148", "type": "text", "text": "晶さんの声は静かだった。"}, {"id": "ch14-s01-p149", "type": "text", "text": "「今は座っていろ」"}, {"id": "ch14-s01-p150", "type": "text", "text": "俺は座っていた。"}, {"id": "ch14-s01-p151", "type": "text", "text": "十二月の朝の風が吹いていた。背後に蝕域の白い光がある。指先に付着した光の粒子は、もう消えていた。前腕には晶さんの指の跡がある。見えない跡。圧力だけが皮膚に残っている。"}, {"id": "ch14-s01-p152", "type": "text", "text": "鳩尾の奥にあるのは、恐怖でも安堵でもなかった。"}, {"id": "ch14-s01-p153", "type": "text", "text": "もっと混ざったもの。体が帰ろうとした場所と、体が覚えている建物と、晶さんの震えた声と、「触れるな」の懇願が、鳩尾の底で沈殿物の上に降り積もっている。十二月上旬から沈殿していた果樹園と蜜柑と月夜唄の上に。"}, {"id": "ch14-s01-p154", "type": "text", "text": "層が、また一枚厚くなった。"}]}, {"chapter": 14, "chapterTitle": "境界の向こう", "scene": 2, "sceneTitle": "晶の告白", "wordCount": "約6,100字", "paragraphs": [{"id": "ch14-s02-p001", "type": "text", "text": "晶さんが座った。"}, {"id": "ch14-s02-p002", "type": "text", "text": "いつの間にか立っていなかった。コンクリートの上に、俺の右側に、半歩分の間隔を置いて座った。ハーフコートの裾が屋上の床に広がる。革手袋をはめたままの手が、膝の上に置かれた。軍人の座り方。背筋が伸びたまま腰を下ろしている。しかし肩の高さが、さっき俺の腕を掴んだ時とは違っていた。低い。力が抜けている——のではなく、使う先を変えている。掴むための力ではなく、ここにいるための力。"}, {"id": "ch14-s02-p003", "type": "text", "text": "沈黙があった。"}, {"id": "ch14-s02-p004", "type": "text", "text": "十二月の朝の風が吹いていた。乾いている。背後の蝕域から来る粉の匂いが混じっている。それ以外の匂いがない。北に蝕域があるから、北からの風には花の匂いも土の匂いもない。消滅した世界の乾いた粉だけが空気に載っている。"}, {"id": "ch14-s02-p005", "type": "text", "text": "沈殿物は動かなかった。さっきの衝動の残滓も、果樹園の記憶の層も、鳩尾の奥の底で静かに積もっている。動かないのは、自分がまだ処理の途中にいるからだった。晶さんの「後で話す。全部」が蓋の上に載っている。蓋を押さえる重しのように。"}, {"id": "ch14-s02-p006", "type": "text", "text": "晶さんの横顔を見た。"}, {"id": "ch14-s02-p007", "type": "text", "text": "琥珀色の瞳が南を向いている。鐘鋳塔の尖塔の方角。さっき「後で話す」と言った時に壁が一枚戻った目。その壁が今、薄くなっている。壁を維持する力が別のところに使われている。何を話すかを、この人は組み立てている。一語ずつ。"}, {"id": "ch14-s02-p008", "type": "text", "text": "一分。"}, {"id": "ch14-s02-p009", "type": "text", "text": "二分。"}, {"id": "ch14-s02-p010", "type": "text", "text": "風が頬を撫でた。十二月の風は乾いていて、頬の表面の水分を奪っていく。頬の皮膚が張る感覚。隣に座っている晶さんの低いポニーテールが、風に揺れなかった。硬い髪。十月と同じ。六月と同じ。この人の髪は風に揺れない。"}, {"id": "ch14-s02-p011", "type": "text", "text": "三分目の終わりに、晶さんの呼吸が変わった。"}, {"id": "ch14-s02-p012", "type": "text", "text": "吐息が深くなった。肺の底まで使った呼吸。軍人が任務前にやる呼吸。腹腔に溜まった空気を一度全部出して、入れ直す。準備の呼吸。"}, {"id": "ch14-s02-p013", "type": "text", "text": "「蓮」"}, {"id": "ch14-s02-p014", "type": "text", "text": "名前。"}, {"id": "ch14-s02-p015", "type": "text", "text": "六月の「深入りするな」の鋭さではなかった。八月の「あまり深入りするな」の切迫でもなかった。十月の「それでいい」の温度でもなかった。さっきの「触れるな」の懇願でもなかった。"}, {"id": "ch14-s02-p016", "type": "text", "text": "静かだった。どの声にも似ていない声だった。"}, {"id": "ch14-s02-p017", "type": "text", "text": "「お前に伝えなきゃならないことがある」"}, {"id": "ch14-s02-p018", "type": "text", "text": "間があった。"}, {"id": "ch14-s02-p019", "type": "text", "text": "風が吹いた。間の長さを風が計った。三秒。"}, {"id": "ch14-s02-p020", "type": "text", "text": "「もっと早く言うべきだった」"}, {"id": "ch14-s02-p021", "type": "text", "text": "晶さんが俺を見た。横顔から正面に。琥珀色の瞳の中の壁が、下がりかけていた。壁の下にあるものが見えかけていた。さっき蝕域の前で目を閉じた時に堪えていたもの。その堪えを、今、手放そうとしている目。"}, {"id": "ch14-s02-p022", "type": "text", "text": "「聞いてくれ」"}, {"id": "ch14-s02-p023", "type": "text", "text": "命令ではなかった。依頼だった。"}, {"id": "ch14-s02-p024", "type": "text", "text": "うなずいた。声は出さなかった。"}, {"id": "ch14-s02-p025", "type": "break", "text": "◇"}, {"id": "ch14-s02-p026", "type": "text", "text": "晶さんが語り始めた。"}, {"id": "ch14-s02-p027", "type": "text", "text": "声は低かった。いつもの低さではなく、もう一段奥から出ている声。喉の振動が空気に載るまでに距離がある声。一語一語の間に、選んでいる時間が挟まっていた。"}, {"id": "ch14-s02-p028", "type": "text", "text": "「三年前の四月だ。私はここにいた。第一監視哨。隊長になって二年目で、早朝の巡回中だった」"}, {"id": "ch14-s02-p029", "type": "text", "text": "晶さんの目が北に向いた。俺が背にしている方角。蝕域の方角。"}, {"id": "ch14-s02-p030", "type": "text", "text": "「蝕域の端が、揺れていた。いつもの脈動とは違った。表面が不規則に波打って、白い光が溢れていた。異常放出。私は部下を下がらせて、一人で境界線に近づいた」"}, {"id": "ch14-s02-p031", "type": "text", "text": "声が途切れなかった。途切れないことに力を使っていた。"}, {"id": "ch14-s02-p032", "type": "text", "text": "「三十メートル手前で、見えた。蝕域の端の、地面の上に、人が倒れていた」"}, {"id": "ch14-s02-p033", "type": "text", "text": "晶さんの右手が、膝の上で動いた。革手袋の指が、自分の左手の甲を一度だけ握り締めた。"}, {"id": "ch14-s02-p034", "type": "text", "text": "「意識がなかった。呼吸はあった。外傷は見えなかった。身元を示すものは何も持っていなかった。衣服は——蝕域の内側から出てきたとしか思えない状態だった。全身に、微量の残響粒子が付着していた。皮膚に。髪に。衣服の繊維に。さっきお前の指先についた光の粒子の、何倍もの量が」"}, {"id": "ch14-s02-p035", "type": "text", "text": "指先。さっき蝕域に手を伸ばしただけで付着した白い粒子。触れてもいなかった。距離があったのに付着した。その何倍。全身に。"}, {"id": "ch14-s02-p036", "type": "text", "text": "「蝕域に接触した人間は消える。消滅する。その場で。例外はない。観測史上、蝕域から生きて出てきた人間は記録されていない」"}, {"id": "ch14-s02-p037", "type": "text", "text": "晶さんの声が平坦になった。事実を並べる声。報告書を読む声に似ていた。けれど報告書を読む時の声には感情がない。今の声には感情があった。感情を平坦さで抑え込んでいた。"}, {"id": "ch14-s02-p038", "type": "text", "text": "「お前は生きていた」"}, {"id": "ch14-s02-p039", "type": "text", "text": "一文。"}, {"id": "ch14-s02-p040", "type": "text", "text": "短い文が風に載って、消えた。"}, {"id": "ch14-s02-p041", "type": "text", "text": "「私は——最初、信じなかった。蝕域から出てきた人間など存在しない。しかしお前は倒れていた。呼吸していた。脈があった。体温があった。皮膚に残響粒子がまとわりついたまま、生きていた」"}, {"id": "ch14-s02-p042", "type": "text", "text": "晶さんの左手がハーフコートの胸元に動いた。"}, {"id": "ch14-s02-p043", "type": "text", "text": "四度目。"}, {"id": "ch14-s02-p044", "type": "text", "text": "六月の南門で、ポケットに手を入れて何も持たずに出した。八月の見晴らし丘で、コートの内側から何かを取り出しかけてやめた。十月の南門で、同じ動作の三度目。"}, {"id": "ch14-s02-p045", "type": "text", "text": "今日は——止まらなかった。"}, {"id": "ch14-s02-p046", "type": "text", "text": "革手袋の指がコートの内ポケットに入り、出てきた。"}, {"id": "ch14-s02-p047", "type": "text", "text": "何かを持っていた。"}, {"id": "ch14-s02-p048", "type": "text", "text": "小さかった。布。色は——生成りの白だったものが、三年の時間で薄い灰色に変わっている。四角い。掌に載る大きさ。五センチ四方ほどの布片。端がほつれている。手で千切られたか、何かに引っかかって裂けたような、不規則な輪郭。"}, {"id": "ch14-s02-p049", "type": "text", "text": "晶さんが布片を両手の間に持った。革手袋の指が、布の表面を押さえていた。"}, {"id": "ch14-s02-p050", "type": "text", "text": "「お前の衣服の内ポケットに、これだけがあった。身元を示すものは何もなかった。名前も。住所も。記録も。ただ、これ一枚」"}, {"id": "ch14-s02-p051", "type": "text", "text": "俺の方に差し出した。"}, {"id": "ch14-s02-p052", "type": "text", "text": "掌を上に向けて。その上に布片を載せて。俺の目の前に。"}, {"id": "ch14-s02-p053", "type": "text", "text": "受け取った。"}, {"id": "ch14-s02-p054", "type": "text", "text": "指先に布の感触が触れた。薄い。綿か。綿に似ているが、もっと繊維が密だった。手触りが滑らかだった。古い布の、乾いた手触り。三年間、晶さんのコートの内ポケットにあった布。"}, {"id": "ch14-s02-p055", "type": "text", "text": "裏返した。"}, {"id": "ch14-s02-p056", "type": "text", "text": "刺繍があった。"}, {"id": "ch14-s02-p057", "type": "text", "text": "糸の色は褪せていた。元は何色だったのか、今ではわからない。薄い灰色と、かすかに残った別の色——青か緑の痕跡が、繊維の間に沈んでいた。"}, {"id": "ch14-s02-p058", "type": "text", "text": "文字が縫い込まれていた。"}, {"id": "ch14-s02-p059", "type": "text", "text": "五文字。"}, {"id": "ch14-s02-p060", "type": "text", "text": "ル　ミ　エ　ラ"}, {"id": "ch14-s02-p061", "type": "text", "text": "四文字目の後にもう一文字があった。繊維がほつれた箇所で途切れている。布の端が裂けた時に、五文字目の下半分が失われていた。けれど残った上半分だけで十分だった。島。"}, {"id": "ch14-s02-p062", "type": "text", "text": "ルミエラ島。"}, {"id": "ch14-s02-p063", "type": "text", "text": "指先の下で、刺繍の糸の凹凸が皮膚に触れていた。誰かの手で縫われた文字。機械ではなかった。糸の渡し方が不均等で、「ル」の一画目が「ミ」より太い。手縫い。人間の手が、一針ずつ、この布に島の名前を刺した。"}, {"id": "ch14-s02-p064", "type": "text", "text": "口が動かなかった。"}, {"id": "ch14-s02-p065", "type": "text", "text": "鳩尾の奥が——"}, {"id": "ch14-s02-p066", "type": "text", "text": "沈殿物が動いた。底に積もっていた果樹園と蜜柑と月夜唄と、その上に載っていた白い光への衝動が、全部一斉に浮き上がりかけた。蓋が外れかけた。晶さんの「後で話す。全部」が蓋を押さえていた重しが外れて、その下にあるもの全てが上に向かって——"}, {"id": "ch14-s02-p067", "type": "text", "text": "呼吸を一つした。"}, {"id": "ch14-s02-p068", "type": "text", "text": "止まった。浮き上がりかけたものが、止まった。崩壊しなかった。"}, {"id": "ch14-s02-p069", "type": "text", "text": "十一月の選抜公演の日に怒れた。あの日、灯籠通りを歩いて鐘鋳塔に向かう間に、体の中にあったものに名前をつけた。怒り。初めて名前がついた感情。同じ夜に管が通った。十一年間出なかった涙が出た。"}, {"id": "ch14-s02-p070", "type": "text", "text": "あの管が、今、内側にかかった圧力を逃がしている。割れない。砕けない。衝撃が体の内壁に当たって、管を通って、呼吸に変わった。震えの形で、手先に出た。"}, {"id": "ch14-s02-p071", "type": "text", "text": "布片を持つ指が揺れていた。"}, {"id": "ch14-s02-p072", "type": "text", "text": "晶さんが見ていた。琥珀色の瞳が俺の手を見ていた。指の震えを見ていた。"}, {"id": "ch14-s02-p073", "type": "text", "text": "「晶さん」"}, {"id": "ch14-s02-p074", "type": "text", "text": "声が出た。掠れていた。掠れ方が、さっき蝕域の前で出した声と似ていた。"}, {"id": "ch14-s02-p075", "type": "text", "text": "「俺は——ルミエラ島の人間なんですか」"}, {"id": "ch14-s02-p076", "type": "text", "text": "質問の形をしていた。けれど答えを待つ声ではなかった。刺繍の文字を指で押さえている。指の腹に「ル」の糸の凹凸がある。体が知っていた。九月に地下書庫でこの名前を読み上げた時、口が五文字を塊のまま出した。十月にすみれが「とおいしまの音」と言った時、鳩尾の奥が応えた。十三章の夜に鐘が鳴った時、蜜柑の果樹園が見えた。全部が、この五文字に繋がっていた。"}, {"id": "ch14-s02-p077", "type": "text", "text": "晶さんが答えた。"}, {"id": "ch14-s02-p078", "type": "text", "text": "「私はそう思っている」"}, {"id": "ch14-s02-p079", "type": "text", "text": "静かだった。一語ずつ、重さがあった。息継ぎの位置まで選んでいた。"}, {"id": "ch14-s02-p080", "type": "text", "text": "「ルミエラ島は十年前に蝕域に飲まれた。推定人口三百人。残存者は公式には確認されていない」"}, {"id": "ch14-s02-p081", "type": "text", "text": "カードに書いてあった。篠宮さんと地下書庫で読んだ、あの厚紙のカード。同じ内容。同じ事実。"}, {"id": "ch14-s02-p082", "type": "text", "text": "「お前はその島の出身かもしれない。あの島は十年前に消えた。消えた島から——三年前に、お前がここに現れた」"}, {"id": "ch14-s02-p083", "type": "text", "text": "晶さんの声が、一度だけ揺れた。"}, {"id": "ch14-s02-p084", "type": "text", "text": "「十年の空白がある、蓮」"}, {"id": "ch14-s02-p085", "type": "text", "text": "十年。"}, {"id": "ch14-s02-p086", "type": "text", "text": "数字が鳩尾の奥に落ちた。重かった。十年。ルミエラ島が消えたのが十年前。俺が発見されたのが三年前。間に七年ある。七年——いや、俺がいくつの時に島が消えたのか。俺は今二十二で、十年前なら十二歳で。発見されたのが三年前だから十九歳で。十二歳から十九歳までの七年間。"}, {"id": "ch14-s02-p087", "type": "text", "text": "七年間。"}, {"id": "ch14-s02-p088", "type": "text", "text": "「どこにいたんだ」という問いが喉に上がってきた。しかし問いの形になる前に、体が答えを出していた。さっき手が蝕域に向かって伸びた。帰ろうとした。あの白い「ない」の中に体が帰ろうとした。"}, {"id": "ch14-s02-p089", "type": "text", "text": "「……晶さん」"}, {"id": "ch14-s02-p090", "type": "text", "text": "声が震えていた。声が震えていることに気づいていた。気づいていて、止められなかった。止める必要があるのかどうかもわからなかった。"}, {"id": "ch14-s02-p091", "type": "text", "text": "「俺は……蝕域の中にいたのか」"}, {"id": "ch14-s02-p092", "type": "text", "text": "風が止まった。"}, {"id": "ch14-s02-p093", "type": "text", "text": "止まったように感じた。実際には吹いている。十二月の朝の風は止まっていない。けれど俺の言葉が空気に出た瞬間に、聴覚が風を拾わなくなった。自分の声だけが聞こえていた。掠れた、低い声。"}, {"id": "ch14-s02-p094", "type": "text", "text": "晶さんは答えなかった。"}, {"id": "ch14-s02-p095", "type": "text", "text": "三秒。"}, {"id": "ch14-s02-p096", "type": "text", "text": "五秒。"}, {"id": "ch14-s02-p097", "type": "text", "text": "八秒。"}, {"id": "ch14-s02-p098", "type": "text", "text": "晶さんの琥珀色の瞳が俺を見ていた。壁がなかった。十月の南門で寂しさを見せた時よりも、さっき「触れるな」の懇願を出した時よりも、今の瞳は剥き出しだった。何も隠していなかった。隠せるものが残っていなかった。"}, {"id": "ch14-s02-p099", "type": "text", "text": "この人は答えを持っていない。"}, {"id": "ch14-s02-p100", "type": "text", "text": "知らないのだ。晶さんも。俺が七年間どこにいたのか。蝕域の中にいたのか。別の場所にいたのか。晶さんは蝕域の端で倒れていた俺を拾った。蓮がルミエラ島出身であることに気づいた。けれど七年間の空白の中身を、この人も知らない。"}, {"id": "ch14-s02-p101", "type": "text", "text": "知らないから答えない。嘘をつかないために。推測を事実として語らないために。"}, {"id": "ch14-s02-p102", "type": "text", "text": "その沈黙が、言葉より重かった。"}, {"id": "ch14-s02-p103", "type": "text", "text": "晶さんの右手が俺の左肩に載った。"}, {"id": "ch14-s02-p104", "type": "text", "text": "革手袋越しの掌。指が肩の曲線に沿った。重さがあった。手の重さではなく、その手を俺の肩に置くまでの時間の重さ。三年間。六月の「深入りするな」から十月の「それでいい」まで。八月にポケットから手を出して空だった三度の手が、今日やっと、布片を俺に渡して、空いた手を俺の肩に置いた。"}, {"id": "ch14-s02-p105", "type": "text", "text": "温かかった。"}, {"id": "ch14-s02-p106", "type": "text", "text": "十二月の屋上の、北風の中で、革手袋の下の体温が肩の骨に届いた。晶さんの体温。軍人の体温。縁際で毎日蝕域と向き合い、部下を守り、俺を見つけ、俺を監視哨で二年間養い、学院に送り出し、遠くから見守っていた人の手の温度。"}, {"id": "ch14-s02-p107", "type": "text", "text": "指先は震えていなかった。さっき俺の腕を掴んだ時は震えていた。今は震えていない。話すべきことを話した後の手だった。"}, {"id": "ch14-s02-p108", "type": "text", "text": "布片を握ったまま、俺は南を見ていた。遠くの鐘鋳塔の尖塔。灰色の空の下の白い石。あの塔の中に鐘がある。あの鐘の音の中に、島の音がある。すみれがそう言った。鐘の音と俺の中の音が同じ場所から来ていると。その場所の名前が、今、俺の指の下にある。"}, {"id": "ch14-s02-p109", "type": "text", "text": "刺繍の糸。手縫い。一針ずつ。"}, {"id": "ch14-s02-p110", "type": "text", "text": "誰が縫ったのか。"}, {"id": "ch14-s02-p111", "type": "text", "text": "十三章の夜に見えた果樹園。子供の俺の手を引いて、月夜唄を歌っていた「誰か」。あの人が縫ったのか。あの人が、俺の衣服のポケットにこの布を入れたのか。島が消える前に。島が飲まれる時に。守るために。"}, {"id": "ch14-s02-p112", "type": "text", "text": "考えるな。今は。頭が追いつかない。"}, {"id": "ch14-s02-p113", "type": "text", "text": "布片を、握り直した。小さい。掌の中に収まる。三年間、晶さんのコートの内ポケットにあったもの。この人は三年間、これを持ち歩いていた。六月にも八月にも十月にも、俺に渡そうとして、やめた。渡す時を待っていた。"}, {"id": "ch14-s02-p114", "type": "text", "text": "「晶さん」"}, {"id": "ch14-s02-p115", "type": "text", "text": "「ああ」"}, {"id": "ch14-s02-p116", "type": "text", "text": "「……ありがとうございます」"}, {"id": "ch14-s02-p117", "type": "text", "text": "声が平坦に出た。いつもの「ありがとうございます」の遅延はなかった。考える前に出た。感謝だった。意味を理解しているかどうかとは別に、この人が三年間守り続けたものを俺に渡したことへの。"}, {"id": "ch14-s02-p118", "type": "text", "text": "晶さんの肩に載った手が、一度だけ力を加えた。押すほどではなかった。確認の力。すみれが手の甲を押す時と同じ種類の——いや、違った。すみれの確認は存在の確認だった。晶さんの確認は、もっと別のもの。「ここにいる」の確認。「まだいる」の確認。俺が壊れていないことの確認。"}, {"id": "ch14-s02-p119", "type": "text", "text": "壊れていなかった。"}, {"id": "ch14-s02-p120", "type": "text", "text": "震えている。指が震えている。声が掠れている。鳩尾の奥で沈殿物が大きく揺れている。けれど割れていない。管が通っている。管を通して衝撃が逃げている。"}, {"id": "ch14-s02-p121", "type": "divider", "text": "---"}, {"id": "ch14-s02-p122", "type": "choice_header", "text": "**【選択肢】**"}, {"id": "ch14-s02-p123", "type": "choice", "text": "**A: 「……もっと、教えてください。俺の——島のこと」**\n→ 隠しフラグ（AFTERルートでの記憶回復演出が早期に始まる）"}, {"id": "ch14-s02-p124", "type": "choice", "text": "**B: 「……今は、目の前のことに集中します」**\n→ 隠しフラグ（AFTERルートでの記憶回復が第15章の大規模縁蝕波で強制的にトリガー）"}, {"id": "ch14-s02-p125", "type": "divider", "text": "---"}, {"id": "ch14-s02-p126", "type": "choice_label", "text": "（選択肢A後の展開テキスト）"}, {"id": "ch14-s02-p127", "type": "text", "text": "声に出すと、奥のものが一段上がった。"}, {"id": "ch14-s02-p128", "type": "text", "text": "知りたい。八月の見晴らし丘で鳩尾の奥に芽生えたもの。九月の地下書庫で方角を得たもの。十月にすみれが名前をくれたもの。十三章の夜に映像になったもの。全部が今、指の下の刺繍に集まっている。"}, {"id": "ch14-s02-p129", "type": "text", "text": "晶さんの琥珀色の瞳が俺を見つめていた。三秒。目の中に何かが光った。安堵に似ていた。安堵ではなかった。もっと奥にあるもの。この人が待っていたものへの、一つの形。"}, {"id": "ch14-s02-p130", "type": "text", "text": "「……わかった。話す。ただし、私が知っていることは多くない。お前が蝕域の中にいたかどうかも、七年間の空白が何だったのかも、正直に言えば——わからない。わかっているのは、お前がルミエラ島の出身であろうということ。蝕域の端で見つかったということ。そしてお前の体に蝕域と接触した痕跡があるということ。その三つだけだ」"}, {"id": "ch14-s02-p131", "type": "text", "text": "声が正確だった。報告書を読む声ではなかった。正確さの中に温度があった。"}, {"id": "ch14-s02-p132", "type": "text", "text": "「私は二年前から、お前の出自について独自に調べていた。中央記録館への照会。旧世界の南東海域に関する文献調査。蝕域接触後の生存例の検索——結果は全て同じだった。蝕域に接触した人間が生存した事例は存在しない。お前が唯一の例外だ」"}, {"id": "ch14-s02-p133", "type": "text", "text": "唯一。その一語が底に落ちた。"}, {"id": "ch14-s02-p134", "type": "text", "text": "「もっと早く伝えるべきだったかもしれない。けれどお前は——記憶を失ったまま、ここで暮らし始めていた。仲間ができていた。仕事があった。感情が戻りかけていた。その過程を壊したくなかった」"}, {"id": "ch14-s02-p135", "type": "text", "text": "晶さんの視線が一瞬、南の鐘鋳塔に流れた。"}, {"id": "ch14-s02-p136", "type": "text", "text": "「それと——お前がルミエラ島出身だと知られれば、研究対象として拘束される危険があった。蝕域接触後の唯一の生存者だ。上層部が放置するとは思えなかった。お前を守るために、黙っていた」"}, {"id": "ch14-s02-p137", "type": "text", "text": "守る。この人はいつも守ると言う。守り方がいつも、離れることだった。"}, {"id": "ch14-s02-p138", "type": "divider", "text": "---"}, {"id": "ch14-s02-p139", "type": "choice_label", "text": "（選択肢B後の展開テキスト）"}, {"id": "ch14-s02-p140", "type": "text", "text": "声は静かだった。自分の声を聞いた。揺れていなかった。"}, {"id": "ch14-s02-p141", "type": "text", "text": "布片を握ったまま、南を見ていた。鐘鋳塔の尖塔。あの塔の中に鐘がある。鳴海さんの歌が鐘を支えている。外円区の蝕域が加速している。すみれが苦しんでいる。燈花の故郷が削られている。"}, {"id": "ch14-s02-p142", "type": "text", "text": "俺の過去は、十年前から待っている。十年待ったものが、もう少しだけ待てないはずがなかった。"}, {"id": "ch14-s02-p143", "type": "text", "text": "「……わかった」"}, {"id": "ch14-s02-p144", "type": "text", "text": "晶さんの声が短かった。"}, {"id": "ch14-s02-p145", "type": "text", "text": "俺が選んだものを、受け止めた声だった。十月の「それでいい」と同じ構造の声。けれど今日の方が重い。蓮が選んだのが「逃避」ではないことを、この人は見抜いている。「今は」の裏側に「いつか」があることを。"}, {"id": "ch14-s02-p146", "type": "divider", "text": "---"}, {"id": "ch14-s02-p147", "type": "choice_label", "text": "（共通テキスト再合流）"}, {"id": "ch14-s02-p148", "type": "text", "text": "晶さんの手が肩から離れた。"}, {"id": "ch14-s02-p149", "type": "text", "text": "革手袋の温度が去った後、肩の骨に冷たさが戻った。十二月の屋上。北から風が吹いている。背後に蝕域の白い光がある。南に鐘鋳塔の尖塔がある。"}, {"id": "ch14-s02-p150", "type": "text", "text": "俺は布片を左手に持ち替えた。握り直した。手首のブレスレットの革紐と、布片の感触が隣り合った。発見された時から身につけている革紐。発見された時に内ポケットにあった布片。二つが、左手の上で重なった。"}, {"id": "ch14-s02-p151", "type": "text", "text": "どちらも来歴を知らない。どちらも体が外す気にならないもの。"}, {"id": "ch14-s02-p152", "type": "text", "text": "晶さんが立ち上がった。"}, {"id": "ch14-s02-p153", "type": "text", "text": "コートの裾を直す動作。膝の砂を払う動作。隊長の所作。戻った。この人はいつも、感情を見せた後で所作に戻る。報告は以上だの代わりに、今日は体を動かすことで蓋をした。"}, {"id": "ch14-s02-p154", "type": "text", "text": "「帰るぞ。長く離れると、向こうに迷惑がかかる」"}, {"id": "ch14-s02-p155", "type": "text", "text": "向こう。学院。管理室。鐘鋳塔。俺の場所。"}, {"id": "ch14-s02-p156", "type": "text", "text": "立ち上がった。膝が重かった。コンクリートの冷たさが尻から腿に移っている。何分座っていたのか。時間を数えていなかった。"}, {"id": "ch14-s02-p157", "type": "text", "text": "布片をポケットに入れた。上着の内ポケット。晶さんが三年間入れていたのと同じ場所に。"}, {"id": "ch14-s02-p158", "type": "text", "text": "南を向いた。遠くの鐘鋳塔が灰色の空の下に見えた。小さい。細い。あそこまで歩いて三十分。"}, {"id": "ch14-s02-p159", "type": "text", "text": "晶さんが先に歩き始めた。"}, {"id": "ch14-s02-p160", "type": "text", "text": "屋上のハッチに向かう。階段を降りる背中。黒いハーフコート。低いポニーテール。"}, {"id": "ch14-s02-p161", "type": "text", "text": "歩幅が——半歩、遅かった。"}, {"id": "ch14-s02-p162", "type": "text", "text": "六月の南門で「半歩遅い」と感じた歩幅。八月の見晴らし丘では正規に戻り、十月の南門でまた半歩遅かった。今日の歩幅は十月と同じだった。半歩遅い。俺を待っている歩幅。俺がついてくるのを確認するための歩幅。"}, {"id": "ch14-s02-p163", "type": "text", "text": "前腕に残っている圧力の跡が、歩くたびに揺れた。晶さんの指の跡。見えない跡。"}, {"id": "ch14-s02-p164", "type": "text", "text": "左手の内ポケットに布片がある。ルミエラ。手縫いの五文字。三年間、コートの中にあった五文字。"}, {"id": "ch14-s02-p165", "type": "text", "text": "鳩尾の奥で沈殿物が動いていた。沈殿していない。浮遊している。果樹園と蜜柑と月夜唄と白い光への衝動と、晶さんの手の温度と、布片の乾いた手触りが、鳩尾の中で混ざり合いながら、まだどこにも沈まずに漂っていた。"}, {"id": "ch14-s02-p166", "type": "text", "text": "いつか沈む。いつか沈んで、層になる。"}, {"id": "ch14-s02-p167", "type": "text", "text": "今はまだ、漂っている。"}]}, {"chapter": 14, "chapterTitle": "境界の向こう", "scene": 3, "sceneTitle": "アナザービュー：晶の守護", "wordCount": "約4,800字", "paragraphs": [{"id": "ch14-s03-p001", "type": "text", "text": "※アナザービュー：桐ヶ谷晶視点"}, {"id": "ch14-s03-p002", "type": "divider", "text": "---"}, {"id": "ch14-s03-p003", "type": "text", "text": "歩幅を落としている。自覚がある。"}, {"id": "ch14-s03-p004", "type": "text", "text": "屋上のハッチから階段に入り、一段目で気づいた。歩幅が正規より半歩狭い。軍人の歩幅は規定がある。訓練課程で叩き込まれた間隔が、私の脚には入っている。それが半歩、縮まっている。蓮がついてきているかを足音で確認するための間隔。"}, {"id": "ch14-s03-p005", "type": "text", "text": "後ろで靴底がコンクリートを踏む音がした。規則的。遅れていない。ついてきている。"}, {"id": "ch14-s03-p006", "type": "text", "text": "私は歩幅を戻さなかった。"}, {"id": "ch14-s03-p007", "type": "break", "text": "◇"}, {"id": "ch14-s03-p008", "type": "text", "text": "蓮に布片を渡した。"}, {"id": "ch14-s03-p009", "type": "text", "text": "内ポケットが軽い。千九十五日間、左胸の裏側にあった重さが消えている。布一枚。五センチ四方。重量にすれば数グラム。それが消えた。"}, {"id": "ch14-s03-p010", "type": "text", "text": "軽くなったはずだった。"}, {"id": "ch14-s03-p011", "type": "text", "text": "軽くならない。"}, {"id": "ch14-s03-p012", "type": "text", "text": "内ポケットに手が伸びそうになる。革手袋の指先が胸元に触れかけて、止める。もうない。あそこにはもうない。蓮の内ポケットに移った。正しい場所に戻った。"}, {"id": "ch14-s03-p013", "type": "text", "text": "私はそれを「正しい」と判断した。判断に誤りはない。布片は蓮のものだ。蓮の衣服に入っていたものだ。三年間、私が預かっていた。預かっていた期間が終わった。報告は以上。"}, {"id": "ch14-s03-p014", "type": "text", "text": "以上のはずなのに——胸の左側が、布一枚ぶん、凹んでいる。"}, {"id": "ch14-s03-p015", "type": "break", "text": "◇"}, {"id": "ch14-s03-p016", "type": "text", "text": "階段を降りながら、私は三年前を数えている。"}, {"id": "ch14-s03-p017", "type": "text", "text": "四月の早朝。巡回中だった。第一監視哨の北側。いつもの経路。いつもの手順。異常の兆候を計器が報告した。蝕域の表面電位が通常値の一・四倍。パターンが不規則。私は部下を境界線の五十メートル後方に下げ、単独で前に出た。"}, {"id": "ch14-s03-p018", "type": "text", "text": "地面に人がいた。"}, {"id": "ch14-s03-p019", "type": "text", "text": "蝕域の端から約三メートル。仰向け。男性。外傷なし。衣服の繊維があちこち擦り切れていた。長い時間、どこかを漂った後の摩耗。靴を履いていなかった。"}, {"id": "ch14-s03-p020", "type": "text", "text": "呼吸があった。"}, {"id": "ch14-s03-p021", "type": "text", "text": "最初に確認したのはそれだった。胸郭の動き。弱い。しかしある。革手袋を外して頸動脈にあてた。拍動。弱い。しかしある。"}, {"id": "ch14-s03-p022", "type": "text", "text": "体温が低かった。指先が蓮の首に触れた瞬間に、冷たさが手首まで上がってきた。四月の朝の外気温は十三度。この人間の体表温度はそれを下回っていた。呼吸がある。心拍がある。しかしこの体温で安定した呼吸があること自体が、観測データとして矛盾していた。"}, {"id": "ch14-s03-p023", "type": "text", "text": "全身に白い光の粒子が付着していた。"}, {"id": "ch14-s03-p024", "type": "text", "text": "残響粒子。皮膚に。髪に。衣服に。微量ではなかった。粒子が体表を薄く覆っていた。残響灯の紫ではない。蝕域と同じ白。蝕域の内部にあった物質が、体表に堆積した状態。"}, {"id": "ch14-s03-p025", "type": "text", "text": "この人間は蝕域から出てきた。"}, {"id": "ch14-s03-p026", "type": "text", "text": "そう判断した。蝕域に接触した人間は消滅する。例外なし。観測史上ゼロ。しかしこの人間は消滅していない。仮説が立たなかった。立たないまま——"}, {"id": "ch14-s03-p027", "type": "text", "text": "蓮の右手が蝕域の方を向いていた。"}, {"id": "ch14-s03-p028", "type": "text", "text": "仰向けの体から、右手だけが北に伸びていた。指先が蝕域を指していた。帰ろうとしていたのか。意識がないまま手だけが動いたのか。わからなかった。わからないまま私はその手を見つめて——、何秒経ったかを、報告書に書けなかった。"}, {"id": "ch14-s03-p029", "type": "text", "text": "時間が抜けた。"}, {"id": "ch14-s03-p030", "type": "text", "text": "訓練を受けた人間の行動記録に、空白があってはならない。しかし蓮の右手を見つめたあの時間を、私は計測できなかった。四月の朝の外気のせいではなかった。この人間の右手が蝕域を指しているという事実が、私の判断機能を止めていた。"}, {"id": "ch14-s03-p031", "type": "text", "text": "搬送準備に入ったのは、蓮の手首の脈をもう一度確認した後だった。生きている。それだけを確認して、私は部下を呼び、担架の準備を指示した。"}, {"id": "ch14-s03-p032", "type": "text", "text": "担架に載せる前に身元を調べた。衣服のポケットを確認した。右ポケット。空。左ポケット。空。胸ポケット。空。内ポケット——布片が一枚あった。五センチ四方。裏面に刺繍。手縫い。五文字。ルミエラ。最後の一文字は半分が失われていた。布の端が裂けた痕跡。"}, {"id": "ch14-s03-p033", "type": "text", "text": "私は布片を自分の内ポケットに入れた。"}, {"id": "ch14-s03-p034", "type": "text", "text": "規定違反だった。発見物は全て記録の上、保管庫に収めなければならない。私はそうしなかった。報告書には「身元を示す所持品なし」と記載した。虚偽報告。懲戒処分の対象。"}, {"id": "ch14-s03-p035", "type": "text", "text": "当時の私には理由を言語化できなかった。今なら言える。蓮がルミエラ島の人間だと知られれば、蝕域接触後の唯一の生存者として上層部の研究対象になる。拘束され、人間として扱われなくなる。縁際の人間を消耗品として扱うあの連中が、例外的な生存者を放置するはずがなかった。"}, {"id": "ch14-s03-p036", "type": "text", "text": "だから隠した。布片を私のコートに入れ、蓮の出自を誰にも伝えなかった。"}, {"id": "ch14-s03-p037", "type": "text", "text": "隠したまま——三年が経った。"}, {"id": "ch14-s03-p038", "type": "break", "text": "◇"}, {"id": "ch14-s03-p039", "type": "text", "text": "階段を降り切り、一階の廊下に出た。灰色のモザイクタイル。蓮の足音が後ろで規則正しく続いている。"}, {"id": "ch14-s03-p040", "type": "text", "text": "さっきこの廊下を歩いた時、蓮の足がタイルの目地を避けていた。四番目の部屋の取っ手の凹みに親指が収まった。蓮の体は、この建物を覚えている。"}, {"id": "ch14-s03-p041", "type": "text", "text": "二年間いた。私の部隊で。機器室で整備をしていた。手が早かった。私がコーヒーを淹れると、蓮は二杯目を黙って受け取った。礼は言わなかった。記憶を失くした直後の蓮には、礼を言うという動作がなかった。感情が平坦で、機械のように正確に働いた。"}, {"id": "ch14-s03-p042", "type": "text", "text": "二年目の秋に、蓮が「晶さん」と呼んだ。"}, {"id": "ch14-s03-p043", "type": "text", "text": "朝の巡回の帰りだった。何の脈絡もなかった。「晶さん、コーヒーの豆、残りが少ないです」。ただそれだけの報告。しかし「晶さん」だった。配属当初は「隊長」だった。それがいつの間にか変わっていた。蓮自身が変化に気づいていたかはわからない。あの頃の蓮は自分の中の変化を言語化する回路を持っていなかった。"}, {"id": "ch14-s03-p044", "type": "text", "text": "私は——嬉しかった。"}, {"id": "ch14-s03-p045", "type": "text", "text": "嬉しかったという判断を、私はその場で処理できなかった。コーヒーの豆の在庫を確認し、補給申請の書類を書き、業務を続けた。嬉しさは胸の左側に溜まったまま沈殿した。処理しないまま、今日まで残っている。"}, {"id": "ch14-s03-p046", "type": "break", "text": "◇"}, {"id": "ch14-s03-p047", "type": "text", "text": "蓮を学院に送り出したのは二年前の春だった。"}, {"id": "ch14-s03-p048", "type": "text", "text": "蓮の適性を鑑みて、鐘鋳塔の補佐官という配置を上申した。蓮を監視哨から離すことで上層部の目が届きにくくなる。鐘鋳塔は閉じた場所だ。蓮の出自を隠すには都合がよかった。"}, {"id": "ch14-s03-p049", "type": "text", "text": "合理的な判断。そう自分に報告した。嘘だった。"}, {"id": "ch14-s03-p050", "type": "text", "text": "蓮を離したくなかった。離したくなかったから、合理的な理由を並べた。正しい理由で正しい判断をしているのに、胸の左側が痛い。布片が内ポケットにある。蓮の代わりのように重い。"}, {"id": "ch14-s03-p051", "type": "text", "text": "六月に学院を訪ねた。報告の帰りだと言った。遠回りだ。管理局から縁際に戻る道に学院はない。"}, {"id": "ch14-s03-p052", "type": "text", "text": "南門の石柱に寄りかかって、蓮を待った。歩いてくる姿が見えた。制服。監視哨にいた時より顔の色がいい。人と話している。食堂で誰かと食事をしている。そういう暮らしの痕跡が、遠くからでもわかった。"}, {"id": "ch14-s03-p053", "type": "text", "text": "「深入りするな」"}, {"id": "ch14-s03-p054", "type": "text", "text": "言った。蓮が過去を掘れば、ルミエラ島に辿り着く。当時の蓮は、それに耐えられなかった。感情の管が通っていなかった。衝撃を逃がす場所が蓮の中になかった。怒ることもできない。泣くこともできない。壊れる。"}, {"id": "ch14-s03-p055", "type": "text", "text": "六月はまだ早い。"}, {"id": "ch14-s03-p056", "type": "text", "text": "八月にもう一度訪ねた。見晴らし丘で蓮を呼び出した。蓮は変わり始めていた。声に色が出てきていた。食堂の話を——誰かの名前を出した。天城、と。人の名前を自分から出す蓮は、監視哨にはいなかった。"}, {"id": "ch14-s03-p057", "type": "text", "text": "変わっている。しかし、まだだ。"}, {"id": "ch14-s03-p058", "type": "text", "text": "内ポケットに手が入った。布片に指が触れた。出しかけた。やめた。蓮の目が正面にあった。紺色。まだ空白が残っている目。"}, {"id": "ch14-s03-p059", "type": "text", "text": "十月は南門で会った。蓮が「晶さん」と呼んだ。"}, {"id": "ch14-s03-p060", "type": "text", "text": "二年前と同じ音だった。口の形が同じだった。目を閉じた。閉じなければ顔に出た。嬉しかった。"}, {"id": "ch14-s03-p061", "type": "text", "text": "「それでいい」と答えた。"}, {"id": "ch14-s03-p062", "type": "text", "text": "布片を出しかけた。三度目。また止めた。"}, {"id": "ch14-s03-p063", "type": "text", "text": "まだ——もう少しだった。蓮は怒ることを覚えかけていた。十一月の夜に、蓮が怒ったと聞いた。鳴海千歳のために。私はそれを直接見ていない。しかし報せは届いた。蓮が声を荒らげた。蓮が泣いた。十一年間——記憶喪失前の人生を含めて——出なかった涙が出た。"}, {"id": "ch14-s03-p064", "type": "text", "text": "管が通った。"}, {"id": "ch14-s03-p065", "type": "text", "text": "蓮の中に、衝撃を逃がす経路ができた。怒れる。泣ける。感情が体の外に出るようになった。壊れにくくなった。"}, {"id": "ch14-s03-p066", "type": "break", "text": "◇"}, {"id": "ch14-s03-p067", "type": "text", "text": "監視哨の正門を出た。外円区の冬枯れの道。空が広い。風が乾いている。"}, {"id": "ch14-s03-p068", "type": "text", "text": "蓮が隣を歩いている。"}, {"id": "ch14-s03-p069", "type": "text", "text": "いつの間にか隣だった。屋上までは前後だった。私が前。蓮が後ろ。しかし正門を出てから、蓮が半歩ぶん前に出て、横に並んだ。意図的かどうかはわからない。わからないが、蓮の足がそこにある。私の左側。半歩ぶんの間隔。"}, {"id": "ch14-s03-p070", "type": "text", "text": "監視哨にいた二年間、巡回は常に前後だった。私が前。蓮が後ろ。上官と部下の配置。それが今日——蓮は横にいる。"}, {"id": "ch14-s03-p071", "type": "text", "text": "横にいることの意味を、私は処理しきれていない。"}, {"id": "ch14-s03-p072", "type": "text", "text": "遠くに鐘鋳塔の尖塔が見える。灰色の空の下の白い石。あの塔に蓮が帰っていく。着いたら蓮は管理室に戻り、計器を読み、鐘を守る日常に戻る。私は縁際に帰る。蝕域は前に出て、鐘は鳴り、兵士は立つ。"}, {"id": "ch14-s03-p073", "type": "text", "text": "蓮の左手が上着のポケットのあたりにある。内ポケット。布片がそこにある。蓮の体に戻った布片。蓮は歩きながら、無意識に内ポケットの上を押さえている。掌の形が布片の位置を確かめている。"}, {"id": "ch14-s03-p074", "type": "text", "text": "三年間、私がやっていた動作と同じだった。"}, {"id": "ch14-s03-p075", "type": "text", "text": "内ポケットに手が伸びた。私の左手が、私のコートの内ポケットに。"}, {"id": "ch14-s03-p076", "type": "text", "text": "何もなかった。"}, {"id": "ch14-s03-p077", "type": "text", "text": "布が指に触れない。千九十五日間そこにあった感触がない。ポケットの裏地だけが指先に触れた。空。軽い。"}, {"id": "ch14-s03-p078", "type": "text", "text": "軽いはずなのに——。"}, {"id": "ch14-s03-p079", "type": "text", "text": "二歩、歩幅が乱れた。"}, {"id": "ch14-s03-p080", "type": "text", "text": "正規の間隔から半歩狭くなり、次の一歩で戻した。蓮が横で一瞬こちらを見た。視線がすぐに前に戻った。聞かなかった。聞かない判断をした。"}, {"id": "ch14-s03-p081", "type": "text", "text": "蓮は変わった。"}, {"id": "ch14-s03-p082", "type": "text", "text": "六月にはなかったものが蓮の中にある。聞くべき時と聞かないべき時を判断する力。鳴海千歳が歌い、天城燈花が笑い、篠宮雫が記録し、星見すみれが手を押し、風祭いろはが怒り——蓮がこの十ヶ月で受け取ったものが、蓮を厚くした。"}, {"id": "ch14-s03-p083", "type": "text", "text": "だから話した。今日、全部。"}, {"id": "ch14-s03-p084", "type": "text", "text": "蓮が受け止められると判断した。判断は正しかった。蓮は崩壊しなかった。布片を見た時、蓮の指が震えた。声が掠れた。しかし割れなかった。管が通っていた。"}, {"id": "ch14-s03-p085", "type": "text", "text": "私は三年待った。"}, {"id": "ch14-s03-p086", "type": "text", "text": "千九十五日は数字だ。数字に長い短いはない。ただ、毎朝巡回するたびに蝕域の北端を見た。蓮が倒れていた場所を見た。あの場所は草が生えない。三年経っても。残響粒子が土壌に浸透して、草一本ない三メートル四方の地面を、毎朝踏んだ。"}, {"id": "ch14-s03-p087", "type": "text", "text": "蓮が倒れていた形を、地面が覚えている。"}, {"id": "ch14-s03-p088", "type": "text", "text": "私の足の裏も覚えている。"}, {"id": "ch14-s03-p089", "type": "break", "text": "◇"}, {"id": "ch14-s03-p090", "type": "text", "text": "鐘鋳塔が大きくなってきた。遠くの細い線だった塔が、建物の輪郭を持ち始めている。残響桜の枝が冬枯れて細い。空に灰色の枝が広がっている。"}, {"id": "ch14-s03-p091", "type": "text", "text": "蓮が隣にいる。"}, {"id": "ch14-s03-p092", "type": "text", "text": "左手の内ポケットが空だ。軽い。"}, {"id": "ch14-s03-p093", "type": "text", "text": "軽い。"}, {"id": "ch14-s03-p094", "type": "text", "text": "——重い。"}, {"id": "ch14-s03-p095", "type": "text", "text": "なくなった重さが、まだそこにある。千九十五日ぶんの体温が裏地に移っている。蓮の代わりにあの五文字を守り、蓮が準備を終えるまで預かっていた左胸の裏側が——空になったことを、まだ受け入れていない。"}, {"id": "ch14-s03-p096", "type": "text", "text": "報告は以上だ。"}, {"id": "ch14-s03-p097", "type": "text", "text": "以上のはずだ。布片を渡した。事実を伝えた。蓮は受け止めた。私は縁際に戻り、蝕域を見張り、兵を守る。それが私の仕事だ。"}, {"id": "ch14-s03-p098", "type": "text", "text": "蓮の足音が隣にある。"}, {"id": "ch14-s03-p099", "type": "text", "text": "規則正しい。遅れない。私の半歩遅い歩幅に合わせるでもなく、追い越すでもなく、横に並んで歩いている。蓮の足音を、私は二年間毎日聞いていた。後ろで。今日は横で聞いている。"}, {"id": "ch14-s03-p100", "type": "text", "text": "蓮。"}, {"id": "ch14-s03-p101", "type": "text", "text": "声には出さなかった。"}, {"id": "ch14-s03-p102", "type": "text", "text": "お前の体が今朝また蝕域に向かった。いつかお前の全身があの白い中に帰っていくのではないか。布片を渡した。事実を伝えた。けれど蓮が蝕域から出てきた理由を、私はまだ知らない。知らないまま手放した。手放したのに蓮は隣を歩いている。隣を歩いていることが嬉しくて、同時に怖い。嬉しいと怖いが同じ場所にあって、私はそれを処理する言葉を軍の報告書式の中に持っていない。"}, {"id": "ch14-s03-p103", "type": "text", "text": "内ポケットに手を入れた。"}, {"id": "ch14-s03-p104", "type": "text", "text": "空だった。"}, {"id": "ch14-s03-p105", "type": "text", "text": "空のポケットの裏地を、革手袋の指先で一度だけ撫でた。"}, {"id": "ch14-s03-p106", "type": "text", "text": "蓮は前を向いていた。鐘鋳塔の方を。"}, {"id": "ch14-s03-p107", "type": "text", "text": "鐘が鳴った。八時の鐘。鳴海千歳の歌に支えられた鐘の音が、十二月の朝の空気を伝わってきた。蓮が一歩、立ち止まった。鐘の音を体で受けている。いつもそうする。この人間は鐘の音を聞くと足を止める。監視哨にいた二年間もそうだった。"}, {"id": "ch14-s03-p108", "type": "text", "text": "変わらないものがある。"}, {"id": "ch14-s03-p109", "type": "text", "text": "鐘の余韻が消えた。蓮が歩き出した。私も歩いた。"}, {"id": "ch14-s03-p110", "type": "text", "text": "内ポケットは空だ。"}, {"id": "ch14-s03-p111", "type": "text", "text": "空のまま、歩いた。"}]}, {"chapter": 14, "chapterTitle": "境界の向こう", "scene": 4, "sceneTitle": "崩れる外円区", "wordCount": "約5,200字", "paragraphs": [{"id": "ch14-s04-p001", "type": "text", "text": "午後の鐘が鳴った。十四時。"}, {"id": "ch14-s04-p002", "type": "text", "text": "管理室の計器を確認していた手が止まった。鐘の音を体で受ける。いつもと同じ深さ。64パーセントの鐘。鳴海さんの歌声が支えている、薄くなりかけた鐘。"}, {"id": "ch14-s04-p003", "type": "text", "text": "今朝の鐘は、第一監視哨の屋上で聴いた。晶さんと歩いて帰る道の途中で。あの八時の鐘から六時間が経っている。六時間の間に、俺は鐘鋳塔に戻り、管理室で計器を読み、左手の内ポケットの布片を三度確認し、霜月さんの緊急連絡を受け取った。"}, {"id": "ch14-s04-p004", "type": "text", "text": "外円区の蝕域が加速している。"}, {"id": "ch14-s04-p005", "type": "text", "text": "観測データは今朝から跳ね上がっていた。南端だけではなかった。北東の観測点、西の沿岸域、複数の地点で同時に活動指数が上昇している。第十系統の表面温度が異常値を示し、粒子密度は十一月のピーク値を超えた。赤い数字の列が画面に並んでいる。"}, {"id": "ch14-s04-p006", "type": "text", "text": "霜月さんの声は平坦だった。「外円区の旧灯里村付近で、蝕域の前進が確認された。避難誘導に人手が要る。行けるか」"}, {"id": "ch14-s04-p007", "type": "text", "text": "行けるか、という問いに、声は一拍で出た。"}, {"id": "ch14-s04-p008", "type": "text", "text": "「行きます」"}, {"id": "ch14-s04-p009", "type": "text", "text": "鳩尾の奥に、今朝の沈殿物が浮遊している。果樹園と蜜柑と月夜唄と布片の手触りと晶さんの掌の温度が、まだどこにも沈まずに漂っている。漂ったまま、足は管理室の扉を開けた。"}, {"id": "ch14-s04-p010", "type": "break", "text": "◇"}, {"id": "ch14-s04-p011", "type": "text", "text": "外円区に入ると、空が違った。"}, {"id": "ch14-s04-p012", "type": "text", "text": "十二月の午後の空は、中円区では灰色だった。外円区では灰色の中に白が混じっていた。白濁。十一月に篠宮さんと来た時と同じ空。けれど白の濃さが違う。十一月よりも白い。空の色が薄まっている。太陽の光が均されて、影が浅くなっている。"}, {"id": "ch14-s04-p013", "type": "text", "text": "風が乾いていた。粉の匂いが混じっている。今朝の監視哨の屋上で嗅いだのと同じ匂い。紙を千切ったような、乾いた粉末の匂い。あの時は数百メートル先に蝕域があった。今は——距離がもっと縮まっている。"}, {"id": "ch14-s04-p014", "type": "text", "text": "農道を南に進んだ。"}, {"id": "ch14-s04-p015", "type": "text", "text": "馬車はなかった。馬車の定期便が止まっている。農道を荷車が行き交い、荷台に家財道具を載せた農夫の列が北に向かっていた。避難だった。中円区の方角に向かって、人が動いている。"}, {"id": "ch14-s04-p016", "type": "text", "text": "荷車の列の横を歩いた。農夫の顔から表情が抜け落ちていた。怒りでも悲しみでもない。使い慣れた表情がどこにも当てはまらない顔。目が前を向いている。足が動いている。それだけの顔。"}, {"id": "ch14-s04-p017", "type": "text", "text": "十分ほど歩くと、旧灯里村付近の集落が見えた。"}, {"id": "ch14-s04-p018", "type": "text", "text": "集落——と呼ぶには、もう家が少なかった。十一月に来た時には四軒残っていた木造の農家のうち、一軒が減っていた。残った三軒のうち二軒の屋根に亀裂が走り、壁に白い粉が付着していた。残響粒子。蝕域が近づいた痕跡。"}, {"id": "ch14-s04-p019", "type": "text", "text": "集落の前に、人だかりがあった。"}, {"id": "ch14-s04-p020", "type": "text", "text": "農夫、老婆、子供。十人ほどの住民が、荷物を抱えて集まっている。集合場所に指定された農道の分岐点。監視哨の兵士が二人、名簿を持って人数を確認していた。"}, {"id": "ch14-s04-p021", "type": "text", "text": "その中に——"}, {"id": "ch14-s04-p022", "type": "text", "text": "栗色のポニーテールが動いていた。"}, {"id": "ch14-s04-p023", "type": "break", "text": "◇"}, {"id": "ch14-s04-p024", "type": "text", "text": "燈花が老婆の荷物を担いでいた。"}, {"id": "ch14-s04-p025", "type": "text", "text": "右肩に風呂敷包み。左手に木箱。背中に毛布を丸めたもの。自分の体より大きな荷物を三つ同時に運んで、農道の端に丁寧に並べている。膝をついて、木箱の位置を直している。"}, {"id": "ch14-s04-p026", "type": "text", "text": "顔が青かった。"}, {"id": "ch14-s04-p027", "type": "text", "text": "血の気がない。唇が白い。十二月の寒さのせいだけではない色。頬の肉が薄くなったように見えた。数日でそこまで変わるはずはないのに、燈花の顔の線が鋭くなっていた。"}, {"id": "ch14-s04-p028", "type": "text", "text": "動きは速かった。"}, {"id": "ch14-s04-p029", "type": "text", "text": "木箱を置いて、立ち上がって、振り返って、次の住民の荷物に手を伸ばす。老婆に何か声をかけている。声が聞こえない。距離がある。けれど口の動き方で、燈花が笑顔を作ろうとしていることがわかった。作ろうとして——完成していなかった。口元だけが上がって、目が追いついていない。八月に喫茶「残響」で見た笑顔とも、十一月に残響桜の下で見た涙の後の顔とも違う。"}, {"id": "ch14-s04-p030", "type": "text", "text": "動いている。"}, {"id": "ch14-s04-p031", "type": "text", "text": "泣いていない。"}, {"id": "ch14-s04-p032", "type": "text", "text": "十一月の残響桜の下で、燈花は泣いた。颯太の顔が思い出せなくなっていると言って、涙を流した。あの時、俺は横に座って「忘れていくのが怖いということは、わかる」と言った。"}, {"id": "ch14-s04-p033", "type": "text", "text": "今の燈花は泣いていなかった。泣くことの手前にいるのではなかった。泣いた後の場所にもいなかった。泣くという選択肢そのものが、燈花の中から消えている。代わりに体が動いている。荷物を運ぶ。声をかける。老婆の腕を支える。子供の手を引く。"}, {"id": "ch14-s04-p034", "type": "text", "text": "行動だけが残っていた。行動の裏にあるものが、顔の色を奪っていた。"}, {"id": "ch14-s04-p035", "type": "text", "text": "俺は農道を走った。"}, {"id": "ch14-s04-p036", "type": "text", "text": "「燈花」"}, {"id": "ch14-s04-p037", "type": "text", "text": "声が出た。名前。八月から呼べるようになった二文字。走りながら呼ぶと、声が風に押し戻された。十二月の外円区の風。粉の匂い。白い空。"}, {"id": "ch14-s04-p038", "type": "text", "text": "燈花が振り返った。"}, {"id": "ch14-s04-p039", "type": "text", "text": "琥珀色の目。——いや、黄褐色。太陽の下では金色に近く見えるはずの目が、今日の白い空の下では色が沈んでいた。目の周りに赤みがなかった。泣いた跡がない。泣いていない。"}, {"id": "ch14-s04-p040", "type": "text", "text": "「蓮くん」"}, {"id": "ch14-s04-p041", "type": "text", "text": "声は低かった。食堂で「蓮くーん」と叫ぶ声とも、喫茶で笑いながら呼ぶ声とも違う。静かだった。風に紛れそうな声。しかし俺の耳はその音を拾った。"}, {"id": "ch14-s04-p042", "type": "text", "text": "燈花は荷物を持ったまま、俺の方に二歩来た。二歩で止まった。"}, {"id": "ch14-s04-p043", "type": "text", "text": "肋骨の内側が鳴った。鳴った、というのは正確ではない。内側が重くなった。十一月の残響桜の下と同じ重さ。あの時は「苦しいだけの重さ」から「別の何かが混じった重さ」に変わった。今の重さは——もっと硬い。石を飲んだような感覚。"}, {"id": "ch14-s04-p044", "type": "text", "text": "「避難、手伝いに来た」"}, {"id": "ch14-s04-p045", "type": "text", "text": "「……うん。ありがと」"}, {"id": "ch14-s04-p046", "type": "text", "text": "短かった。燈花の「ありがと」はいつもの「ありがとう！」の三倍は短かった。語尾が落ちている。声が途中で止まったのではなく、最初から短い言葉を選んでいた。"}, {"id": "ch14-s04-p047", "type": "text", "text": "燈花が南を向いた。"}, {"id": "ch14-s04-p048", "type": "text", "text": "俺も南を向いた。"}, {"id": "ch14-s04-p049", "type": "text", "text": "集落の向こう。農道の先。十一月に篠宮さんと見た消滅の境界があった場所。その場所が——"}, {"id": "ch14-s04-p050", "type": "text", "text": "見えなかった。"}, {"id": "ch14-s04-p051", "type": "text", "text": "白い光。淡い光。乳白色の粒子が大気に溶けている。蝕域。十一月には境界線の向こう側にあったもの。農道から十歩離れていたもの。それが今、農道の端に迫っていた。十一月の位置から百メートル以上前進している。"}, {"id": "ch14-s04-p052", "type": "text", "text": "光の塵が風に乗らずに漂っていた。脈動。不規則なリズム。あの白い「ない」が、午後の光の中で息をしている。"}, {"id": "ch14-s04-p053", "type": "text", "text": "燈花が静かに言った。"}, {"id": "ch14-s04-p054", "type": "text", "text": "「蓮くん……灯里村の向こう側が、もう見えない」"}, {"id": "ch14-s04-p055", "type": "text", "text": "声に感情がなかった。いや——ある。深すぎて、声の表面に浮いてこない。"}, {"id": "ch14-s04-p056", "type": "text", "text": "「あたしの故郷が、また削られてる」"}, {"id": "ch14-s04-p057", "type": "text", "text": "燈花の左手が、左薬指の布リングに触れた。ほつれた繊維が指から垂れている。十一月よりも長い。布が痩せている。約束の印が、細くなっていた。"}, {"id": "ch14-s04-p058", "type": "text", "text": "涙はなかった。"}, {"id": "ch14-s04-p059", "type": "text", "text": "目が乾いていた。白い空の下で、燈花の黄褐色の目は光を失わずに、まっすぐ南を見ていた。まっすぐ見ている目の方が、泣いている目よりも、肋骨の内側に響いた。"}, {"id": "ch14-s04-p060", "type": "text", "text": "何か言おうとした。喉の奥に塊がある。十一月の残響桜の下で、不完全ながらも言葉を出せた。「忘れていくのが怖いということは、わかる」と。けれど今は、言葉の形が見つからなかった。燈花は忘れることを恐れていない。忘れる前に、場所そのものが消えている。恐怖の手前にある、もっと根の深い——"}, {"id": "ch14-s04-p061", "type": "text", "text": "「手、貸して。まだ荷物あるから」"}, {"id": "ch14-s04-p062", "type": "text", "text": "燈花が言った。"}, {"id": "ch14-s04-p063", "type": "text", "text": "声のトーンが変わった。低いまま。けれど、用件があった。燈花は今、俺に仕事を振った。泣く代わりに動くことを選んだ人間が、俺にも動くことを求めた。"}, {"id": "ch14-s04-p064", "type": "text", "text": "「……わかった」"}, {"id": "ch14-s04-p065", "type": "text", "text": "俺は荷物を受け取った。風呂敷包みと木箱。重かった。燈花はこれを一人で運んでいた。"}, {"id": "ch14-s04-p066", "type": "break", "text": "◇"}, {"id": "ch14-s04-p067", "type": "text", "text": "避難支援を始めて三十分ほど経った頃、もう一人の姿を見つけた。"}, {"id": "ch14-s04-p068", "type": "text", "text": "農道の分岐点。荷物の集積場所の隅。灰色のエプロンの下に紺の制服。首から下げた銀色の鍵。腰のメモ帳。"}, {"id": "ch14-s04-p069", "type": "text", "text": "篠宮さんがいた。"}, {"id": "ch14-s04-p070", "type": "text", "text": "メモ帳を開いて、立ったまま記録を取っていた。ペンが紙の上を走っている。かりかりという音が——聞こえなかった。距離がある。しかし十二月の外円区の風は音を薄くしていた。篠宮さんのペンの音は、いつもなら耳に届く。記録室でも、外円区の農道でも、あの音だけは耳が拾った。"}, {"id": "ch14-s04-p071", "type": "text", "text": "今日は拾えなかった。"}, {"id": "ch14-s04-p072", "type": "text", "text": "距離のせいだと思った。近づけば聞こえる。"}, {"id": "ch14-s04-p073", "type": "text", "text": "近づいた。"}, {"id": "ch14-s04-p074", "type": "text", "text": "十歩。五歩。三歩。"}, {"id": "ch14-s04-p075", "type": "text", "text": "篠宮さんの隣に立った。"}, {"id": "ch14-s04-p076", "type": "text", "text": "ペンの音が聞こえた。かりかり。しかし——間隔が不規則だった。いつもの篠宮さんのペンは等間隔で紙を引っ掻く。一定のリズム。記録室で何ヶ月も聴いてきたリズム。今日のリズムは乱れていた。二画書いて止まり、三画書いて止まり、止まる間隔が一定でない。"}, {"id": "ch14-s04-p077", "type": "text", "text": "篠宮さんの手を見た。"}, {"id": "ch14-s04-p078", "type": "text", "text": "震えていた。"}, {"id": "ch14-s04-p079", "type": "text", "text": "ペンを持つ右手の指先が、微かに揺れていた。四月の終わりに清書を手伝い始めた頃にも気づいた筆跡の震え。書き終わりの最後の一画が乱れる癖。あの時は一画だけだった。今は——手全体が震えている。"}, {"id": "ch14-s04-p080", "type": "text", "text": "耳の位置にあるものが鳴った。十一月の帰り道で、篠宮さんの輪郭が揺らいだ時と同じ音。引っかかりの音。耳の奥で何かが——"}, {"id": "ch14-s04-p081", "type": "text", "text": "「篠宮さん」"}, {"id": "ch14-s04-p082", "type": "text", "text": "篠宮さんがペンを止めた。顔を上げた。"}, {"id": "ch14-s04-p083", "type": "text", "text": "墨色の瞳が俺を見た。"}, {"id": "ch14-s04-p084", "type": "text", "text": "瞳の焦点が合うまでに、一拍の間があった。"}, {"id": "ch14-s04-p085", "type": "text", "text": "一拍。いつもの篠宮さんにはない間。呼ばれたら即座にこちらを見る人だった。瞬きが一回多い時はあっても、視線の移動は正確だった。"}, {"id": "ch14-s04-p086", "type": "text", "text": "今日は——一拍、ぼんやりしていた。"}, {"id": "ch14-s04-p087", "type": "text", "text": "ぼんやり。篠宮さんに使ったことのない言葉だった。しかしそうとしか言えなかった。篠宮さんの墨色の目が、俺を見る前に、どこか別の場所を見ていた。メモ帳でも農道でも空でもない場所。"}, {"id": "ch14-s04-p088", "type": "text", "text": "「……朝霧さん」"}, {"id": "ch14-s04-p089", "type": "text", "text": "声が届いた。薄かった。音量は足りている。声の芯が薄い。篠宮さんの声にはいつも硬い芯があった。壁に届かない程度の音量でも、言葉の輪郭は正確だった。今日の声は、輪郭が滲んでいた。"}, {"id": "ch14-s04-p090", "type": "text", "text": "「記録を取りに来たんですか」"}, {"id": "ch14-s04-p091", "type": "text", "text": "「はい」"}, {"id": "ch14-s04-p092", "type": "text", "text": "短い返答。いつもの篠宮さんの短さに似ていた。けれど、返答の後に続くはずの情報がなかった。場所。消滅者の人数。時刻。篠宮さんはいつも最低限の情報を後ろに足す。今日は「はい」だけだった。"}, {"id": "ch14-s04-p093", "type": "text", "text": "「大丈夫ですか」"}, {"id": "ch14-s04-p094", "type": "text", "text": "聞いた。聞いてから、この問いが何を指しているのか自分でもわからなかった。手の震えか。声の薄さか。一拍のぼんやりか。全部か。"}, {"id": "ch14-s04-p095", "type": "text", "text": "篠宮さんのメモ帳が膝の前にあった。開かれたページを見た。文字が——読めた。距離があるのに読めるほど、文字が大きかった。篠宮さんの字はいつも小さい。正確で、小さくて、一ページに何十行も詰め込む。今日のページは行間が広かった。文字そのものが膨らんだわけではない。行と行の間に空白が多い。書いて、止まって、また書いて。止まった時間がページに残っていた。"}, {"id": "ch14-s04-p096", "type": "text", "text": "篠宮さんが俺の視線に気づいた。メモ帳をわずかに胸の方に引いた。"}, {"id": "ch14-s04-p097", "type": "text", "text": "「……大丈夫です。記録を、続けないと」"}, {"id": "ch14-s04-p098", "type": "text", "text": "声がかすかに硬くなった。硬くなったことで、一瞬だけ篠宮さんらしさが戻った。記録を続ける。その意志が声の芯を支えた。"}, {"id": "ch14-s04-p099", "type": "text", "text": "しかし、メモ帳を引いた右手が、まだ震えていた。"}, {"id": "ch14-s04-p100", "type": "text", "text": "耳の位置にあるものが、消えなかった。引っかかりが残っている。十一月の帰り道の引っかかりよりも、大きくなっている。"}, {"id": "ch14-s04-p101", "type": "text", "text": "篠宮さんが視線を南に向けた。蝕域の方角。白い光が農道の先に見えている。篠宮さんの墨色の瞳に白い光が映った。"}, {"id": "ch14-s04-p102", "type": "text", "text": "その瞬間、篠宮さんの目がまた——遠くなった。"}, {"id": "ch14-s04-p103", "type": "text", "text": "遠い。目は南を向いているのに、南を見ていない。もっと遠い場所を見ている。もっと——深い場所を。体がここにあって、目だけがどこかに行っている。"}, {"id": "ch14-s04-p104", "type": "text", "text": "二秒。"}, {"id": "ch14-s04-p105", "type": "text", "text": "三秒。"}, {"id": "ch14-s04-p106", "type": "text", "text": "篠宮さんが瞬きをした。目が戻った。墨色の瞳に焦点が戻り、ペンが動き始めた。かりかり。不規則な間隔。震える指。"}, {"id": "ch14-s04-p107", "type": "text", "text": "何が起きている。"}, {"id": "ch14-s04-p108", "type": "text", "text": "体は正常に見える。呼吸は安定している。立っている。ペンを持っている。しかし、時折訪れるあの「遠さ」が——十一月の帰り道で見た輪郭の揺らぎと、同じ種類のものに感じられた。"}, {"id": "ch14-s04-p109", "type": "text", "text": "光の加減ではなかった。"}, {"id": "ch14-s04-p110", "type": "text", "text": "十一月はそう判断した。目の疲れだと。消滅した場所を見た後だからだと。しかし今日は消滅した場所を間近で見ていない。篠宮さんは記録のためにここにいる。それだけのはず。"}, {"id": "ch14-s04-p111", "type": "text", "text": "「篠宮さん」"}, {"id": "ch14-s04-p112", "type": "text", "text": "もう一度呼んだ。"}, {"id": "ch14-s04-p113", "type": "text", "text": "「はい」"}, {"id": "ch14-s04-p114", "type": "text", "text": "今度は一拍の間がなかった。即座に返った。"}, {"id": "ch14-s04-p115", "type": "text", "text": "「……手伝えることがあったら、言ってください」"}, {"id": "ch14-s04-p116", "type": "text", "text": "言葉が足りなかった。聞きたいことがあった。手が震えていることを指摘すべきなのかもしれなかった。けれど、篠宮さんは「記録を続けないと」と言った。その声の硬さに、俺が踏み込んでいい境界が見えなかった。"}, {"id": "ch14-s04-p117", "type": "text", "text": "篠宮さんは小さくうなずいた。"}, {"id": "ch14-s04-p118", "type": "text", "text": "「……ありがとうございます」"}, {"id": "ch14-s04-p119", "type": "text", "text": "声が半音低かった。二度目の「ありがとうございます」。十一月に外円区に同行した時と同じ。"}, {"id": "ch14-s04-p120", "type": "text", "text": "俺は篠宮さんの横を離れた。避難支援に戻った。"}, {"id": "ch14-s04-p121", "type": "text", "text": "離れながら、一度だけ振り返った。"}, {"id": "ch14-s04-p122", "type": "text", "text": "篠宮さんは立ったままメモ帳に向かっていた。ペンが動いている。手が震えている。白い空の下で、紺の制服の輪郭が——"}, {"id": "ch14-s04-p123", "type": "text", "text": "はっきりしていた。今は。"}, {"id": "ch14-s04-p124", "type": "text", "text": "今は、はっきりしている。"}, {"id": "ch14-s04-p125", "type": "text", "text": "耳の奥の引っかかりが、鳩尾の奥にある沈殿物の横に並んだ。布片とは違う位置。晶さんの手の温度とも違う場所。肋骨の内側の石とも重ならない。耳の位置に、篠宮さんの引っかかりがある。"}, {"id": "ch14-s04-p126", "type": "text", "text": "午後の風が吹いた。粉の匂い。白い空。南の蝕域が脈動している。"}, {"id": "ch14-s04-p127", "type": "text", "text": "燈花が荷車の横で老婆の手を引いている。篠宮さんが記録を取っている。俺は荷物を運んでいる。"}, {"id": "ch14-s04-p128", "type": "text", "text": "左手の内ポケットに布片がある。ルミエラ。手縫いの刺繍。今朝の屋上で、俺の体が帰ろうとした場所の名前。今朝の晶さんの告白。七年間の空白。蝕域の中にいたかもしれない俺。"}, {"id": "ch14-s04-p129", "type": "text", "text": "鳩尾の奥で沈殿物が浮遊している。処理が終わっていない。終わっていないまま、俺の足は荷物を運んでいる。手が木箱を掴んでいる。燈花が「手、貸して」と言ったから。目の前に荷物があるから。"}, {"id": "ch14-s04-p130", "type": "text", "text": "今朝の問いは——待てる。"}, {"id": "ch14-s04-p131", "type": "text", "text": "十年待ったものが、もう少しだけ待てないはずがない。あの屋上で、そう思った。"}, {"id": "ch14-s04-p132", "type": "text", "text": "午後の鐘が遠くで鳴っている。鐘鋳塔の方角。鳴海さんの歌が支える鐘。あの音が蝕域を押し返している。押し返しきれていない。農道の先で、白い光がまた一メートル、前に出た。"}]}, {"chapter": 14, "chapterTitle": "境界の向こう", "scene": 5, "sceneTitle": "二つの嵐", "wordCount": "約4,400字", "paragraphs": [{"id": "ch14-s05-p001", "type": "text", "text": "鐘鋳塔に戻ったのは二十時過ぎだった。"}, {"id": "ch14-s05-p002", "type": "text", "text": "外円区の避難支援は十七時に一区切りがついた。旧灯里村付近の残存住民二十三名の移送が完了し、監視哨の兵士が点呼を取り終えた。燈花は最後まで荷物を運んでいた。篠宮さんは最後までメモ帳に向かっていた。俺は十七時半に中円区に戻り、補佐官舎で上着を替え、鐘鋳塔の一階で十八時の点検業務をこなした。第七層歯車列の注油。第四系統連結管の目視確認。共鳴管接合部のトルク検査。いつもの手順を、いつもの手が繰り返した。"}, {"id": "ch14-s05-p003", "type": "text", "text": "手が業務を片づけている間、鳩尾の奥の沈殿物は浮いたままだった。"}, {"id": "ch14-s05-p004", "type": "text", "text": "布片は内ポケットにある。ルミエラ。手縫いの刺繍。午後の外円区でも、点検業務の間も、触らなかった。触らなくても在る。在ることがわかる。"}, {"id": "ch14-s05-p005", "type": "text", "text": "点検を終えて、追加の観測データを転記した。南端、北東、西沿岸域の三地点。十四時。十六時。十八時。三回分の数値を並べた。並べて、紙を持って、三階に上がった。"}, {"id": "ch14-s05-p006", "type": "text", "text": "研究区画の通路。残響灯の白に近い光。湿度管理された乾いた空気。靴底が石の床を打つ音だけが通路に落ちている。"}, {"id": "ch14-s05-p007", "type": "text", "text": "霜月さんの研究室の鉄扉の下に、光が漏れていた。"}, {"id": "ch14-s05-p008", "type": "text", "text": "いる。十一月も、十二月も。この時間にこの場所にいない日を知らない。"}, {"id": "ch14-s05-p009", "type": "text", "text": "鉄扉を三回叩いた。"}, {"id": "ch14-s05-p010", "type": "text", "text": "一秒。"}, {"id": "ch14-s05-p011", "type": "text", "text": "「入りなさい」"}, {"id": "ch14-s05-p012", "type": "text", "text": "声。低い。疲労の低さではなかった。別の低さ。声の下に何かを噛んでいるような低さ。"}, {"id": "ch14-s05-p013", "type": "text", "text": "鉄扉を引いた。"}, {"id": "ch14-s05-p014", "type": "break", "text": "◇"}, {"id": "ch14-s05-p015", "type": "text", "text": "研究室の空気が違った。"}, {"id": "ch14-s05-p016", "type": "text", "text": "入った瞬間に肌が拾った。計器の乾いた空気は同じ。残響灯の青白い光も同じ。しかし空気の密度が違う。重い。霜月さんの感情が部屋の空気に降りている。こういう研究室は初めてだった。"}, {"id": "ch14-s05-p017", "type": "text", "text": "モニタが二台、両方点いていた。"}, {"id": "ch14-s05-p018", "type": "text", "text": "一台目。蝕域活動指数の折れ線グラフ。赤い線。七月から十二月下旬まで。赤い線は十一月の25パーセントからさらに跳ね上がっていた。目測ではない。数字がモニタの右上に表示されている。42。パーセント。十月に17で「桁が違う」と霜月さんが言った数字が、二ヶ月で42になっていた。"}, {"id": "ch14-s05-p019", "type": "text", "text": "二台目。地図。アルケミラ島の同心円地図。赤い点が——六つ。十一月には三つだった。倍になっている。そして赤い点の外側に、赤い帯が描画されていた。蝕域の現在の領域を示す帯。外円区の南から西にかけて、帯が太くなっている。太い部分の先端に、点滅するマーカーが三つ。今日の午後から新たに侵食が確認された地点だろう。"}, {"id": "ch14-s05-p020", "type": "text", "text": "霜月さんが机の前に立っていた。"}, {"id": "ch14-s05-p021", "type": "text", "text": "十一月と同じだ。座っていない。モニタの前に立っている。白いコート。銀髪のハーフアップ。背筋は真っ直ぐ。しかし右手に持っているものが違った。記録用紙ではなかった。管理局のロゴが入った書面。文面が見えた。"}, {"id": "ch14-s05-p022", "type": "text", "text": "「即時避難勧告の要請に対する回答」。"}, {"id": "ch14-s05-p023", "type": "text", "text": "既に返答が来ている。"}, {"id": "ch14-s05-p024", "type": "text", "text": "「追加の三地点データです。十四時、十六時、十八時分を——」"}, {"id": "ch14-s05-p025", "type": "text", "text": "「後にしなさい」"}, {"id": "ch14-s05-p026", "type": "text", "text": "声が遮った。"}, {"id": "ch14-s05-p027", "type": "text", "text": "初めてだった。霜月さんがデータの受け渡しを後回しにしたのは。この人は常にデータを最優先する。十月の深夜も、十一月の夜も、データを差し出せば即座に目を落とした。今日は違った。右手の書面を見ている。書面の文字を見ている。"}, {"id": "ch14-s05-p028", "type": "text", "text": "二秒。"}, {"id": "ch14-s05-p029", "type": "text", "text": "霜月さんが書面を机の上に置いた。置き方が荒かった。紙の端が折れた。ペンが転がった。霜月さんはペンを直さなかった。"}, {"id": "ch14-s05-p030", "type": "text", "text": "「回答が来た。織部副局長から」"}, {"id": "ch14-s05-p031", "type": "text", "text": "声が変わっていた。"}, {"id": "ch14-s05-p032", "type": "text", "text": "業務の声から遠かった。十一月の「同じ結末になった」の亀裂とも違う。あの時は意志で罅を入れた声だった。今の声は——罅ではなく、火だった。凍った表面の下で、何かが燃えている。冷たいまま燃えている。矛盾した温度が声に乗っていた。"}, {"id": "ch14-s05-p033", "type": "text", "text": "「外円区の人口密度を考慮すれば、内円区の防衛に資源を集中すべき、と」"}, {"id": "ch14-s05-p034", "type": "text", "text": "一語一語が正確だった。正確さが刃物になっていた。怒りを制御するための正確さ。情報を相手に伝えるために選ばれた言葉ではなく、自分の中の火を押し込めるために研がれた言葉だった。"}, {"id": "ch14-s05-p035", "type": "text", "text": "「即時避難は不要。鐘の修復の優先度引き上げも却下。蝕域対策は来月の定例会議で再検討する」"}, {"id": "ch14-s05-p036", "type": "text", "text": "来月。"}, {"id": "ch14-s05-p037", "type": "text", "text": "「……来月」"}, {"id": "ch14-s05-p038", "type": "text", "text": "俺の口から出た。低い声だった。鳩尾の上が反応していた。十月の研究室で初めて怒りを自覚した場所。あの時と同じ温度が戻っている。"}, {"id": "ch14-s05-p039", "type": "text", "text": "「このデータで来月まで待てるはずがないでしょう」"}, {"id": "ch14-s05-p040", "type": "text", "text": "「そう申し立てた。二度」"}, {"id": "ch14-s05-p041", "type": "text", "text": "二度。霜月さんは二度、上層に掛け合っている。"}, {"id": "ch14-s05-p042", "type": "text", "text": "「二度とも同じ回答だった」"}, {"id": "ch14-s05-p043", "type": "text", "text": "霜月さんの左手がコートのポケットから出た。左耳。青い石のピアスに指が触れた。十一月は確認するように触れた。今は——握っていた。指先ではなく、親指と人差し指で青い石を挟んでいた。力がかかっている。"}, {"id": "ch14-s05-p044", "type": "text", "text": "ラベンダーの瞳がモニタの地図を見ていた。赤い帯。外円区を覆い始めた蝕域の領域。点滅するマーカー。"}, {"id": "ch14-s05-p045", "type": "text", "text": "「五年前と同じだ」"}, {"id": "ch14-s05-p046", "type": "text", "text": "声が出た。霜月さんの声。"}, {"id": "ch14-s05-p047", "type": "text", "text": "十月に「また始まる」が漏れた。十一月に「五年前と同じだ」で震えた。十二月に「同じ結末になった」を自分で出した。今日の「五年前と同じだ」は、それらの全てと違っていた。"}, {"id": "ch14-s05-p048", "type": "text", "text": "怒りだった。"}, {"id": "ch14-s05-p049", "type": "text", "text": "声が震えていなかった。声は低く、硬く、一語一語の輪郭が鋭利だった。震えはない。罅もない。怒りが純度を上げて、固体になっていた。"}, {"id": "ch14-s05-p050", "type": "text", "text": "「外円区を切り捨てる。あの時も同じだった。データがあった。警報を出す根拠があった。私が出した。握り潰された。集落が消えた。数百人が消えた」"}, {"id": "ch14-s05-p051", "type": "text", "text": "声量は変わらなかった。上がらなかった。上げないのではなく、上げる必要がない声だった。静かな声の方が、叫ぶ声よりも空気を切る。"}, {"id": "ch14-s05-p052", "type": "text", "text": "「今も同じことが起きている。侵食速度が三倍に加速している。二週間以内に外円区全体が消滅する可能性がある。データがある。数値がある。それを『人口密度を考慮すれば』で——」"}, {"id": "ch14-s05-p053", "type": "text", "text": "霜月さんの声が止まった。"}, {"id": "ch14-s05-p054", "type": "text", "text": "止まったのは喉が詰まったからではなかった。歯を噛み合わせたからだった。顎の筋肉が動いた。白い肌の下で筋が浮いた。"}, {"id": "ch14-s05-p055", "type": "text", "text": "三秒。"}, {"id": "ch14-s05-p056", "type": "text", "text": "歯が離れた。"}, {"id": "ch14-s05-p057", "type": "text", "text": "「また。何度でも」"}, {"id": "ch14-s05-p058", "type": "text", "text": "四語。小さい。しかし研究室の壁に届いた。壁に届いて、返ってきて、残響灯の光の中で消えた。"}, {"id": "ch14-s05-p059", "type": "text", "text": "俺は立ったまま霜月さんを見ていた。"}, {"id": "ch14-s05-p060", "type": "text", "text": "白いコートの肩の線が張り詰めていた。背筋は真っ直ぐ。姿勢は完璧。完璧な姿勢のまま、この人は燃えていた。五年間凍らせていたものが、同じ形を保ったまま温度だけが変わっている。氷の中で火が灯っている。外から見える形は変わらない。しかし中が違う。"}, {"id": "ch14-s05-p061", "type": "text", "text": "ラベンダーの瞳の中に、光があった。"}, {"id": "ch14-s05-p062", "type": "text", "text": "残響灯の反射ではなかった。モニタの光でもなかった。瞳の奥、硬い鉱石の断面の向こう側から、何かが燃えていた。十月に初めて浮いた層。十一月に震えた層。十二月に意志で罅を入れた層。その全てを通り越して、もっと深い場所にあるものが、今夜は表面まで上がってきていた。"}, {"id": "ch14-s05-p063", "type": "text", "text": "怒り。"}, {"id": "ch14-s05-p064", "type": "text", "text": "義憤。"}, {"id": "ch14-s05-p065", "type": "text", "text": "正しいデータがあるのに、正しい判断がされない。五年前も今も。この人はそのことに五年間怒り続けていた。凍らせたのは感情ではなかった。怒りの表出を凍らせていた。怒りそのものは消えていなかった。一度も消えていなかった。"}, {"id": "ch14-s05-p066", "type": "text", "text": "背中の奥が熱かった。"}, {"id": "ch14-s05-p067", "type": "text", "text": "背中の奥が熱い。重さが熱に変わっている。十月の鳩尾の上の熱と同じ種類の温度。あの日、俺は自分の怒りを初めて自覚した。「知っていて、歌わせていたんですか」。鳴海さんの命を天秤に載せた構造への怒り。"}, {"id": "ch14-s05-p068", "type": "text", "text": "今、霜月さんの怒りが俺の背中の奥に届いている。"}, {"id": "ch14-s05-p069", "type": "text", "text": "共鳴している。"}, {"id": "ch14-s05-p070", "type": "text", "text": "鐘と共鳴管が周波数を合わせるように、霜月さんの怒りと俺の怒りが同じものに向いていた。外円区を切り捨てる構造。データがあるのに動かない組織。五年前と今。鳴海さんの天秤と外円区の天秤。同じ秤。同じ傾き。"}, {"id": "ch14-s05-p071", "type": "text", "text": "「霜月さん」"}, {"id": "ch14-s05-p072", "type": "text", "text": "声が出た。低かった。十月の研究室と同じ声。鳩尾の上から出る声。あの時は初めて出した声で、自分の声に驚いた。今日は驚かなかった。知っている声だった。俺の怒りの声。"}, {"id": "ch14-s05-p073", "type": "text", "text": "霜月さんが俺を見た。"}, {"id": "ch14-s05-p074", "type": "text", "text": "ラベンダーの瞳の中の光が、俺を真っ直ぐ捉えた。"}, {"id": "ch14-s05-p075", "type": "text", "text": "「俺にできることを言ってください」"}, {"id": "ch14-s05-p076", "type": "text", "text": "霜月さんの目がわずかに動いた。動いた方向がわからなかった。驚いたのか。何かを見定めようとしたのか。しかし一瞬の動きの後、ラベンダーの瞳が静かに固まった。"}, {"id": "ch14-s05-p077", "type": "text", "text": "五秒。"}, {"id": "ch14-s05-p078", "type": "text", "text": "「……定例会議の前に、独自にデータを纏める。上層部の回答を覆すに足る精度で。朝霧、お前は三地点の時系列データを今週中に整えろ。一時間刻みの粒度で」"}, {"id": "ch14-s05-p079", "type": "text", "text": "業務の声に戻っていた。"}, {"id": "ch14-s05-p080", "type": "text", "text": "しかし戻った声の中に、さっきの火が消えずに残っていた。業務の口調を纏っているのに、一語一語の輪郭がさっきより鋭い。指示を出している。行動を選んでいる。五年前と違う。あの時は声を握り潰された十六歳だった。今は——。"}, {"id": "ch14-s05-p081", "type": "text", "text": "「了解しました」"}, {"id": "ch14-s05-p082", "type": "text", "text": "俺は記録用紙を机の上に置いた。追加の三地点データ。霜月さんの手が即座にそれを取った。目が数字に落ちた。"}, {"id": "ch14-s05-p083", "type": "text", "text": "研究室を出た。鉄扉を引いた。"}, {"id": "ch14-s05-p084", "type": "text", "text": "閉まる直前に見えた。白いコートの背中。モニタの赤い光に染まった肩。左耳の青い石が、赤い光の中で青かった。変わらない。あの子供のお守りの色は変わらない。"}, {"id": "ch14-s05-p085", "type": "text", "text": "鉄扉が閉まった。"}, {"id": "ch14-s05-p086", "type": "break", "text": "◇"}, {"id": "ch14-s05-p087", "type": "text", "text": "補佐官舎に戻った。二十一時を回っていた。"}, {"id": "ch14-s05-p088", "type": "text", "text": "上着をハンガーにかけた。内ポケットから布片を出した。ルミエラ。手縫いの刺繍。掌の上に載せた。"}, {"id": "ch14-s05-p089", "type": "text", "text": "小さい。"}, {"id": "ch14-s05-p090", "type": "text", "text": "掌に収まるサイズの布。この布が俺の過去に繋がっている。今朝、晶さんが言った。ルミエラ島。十年の空白。蝕域の中にいたかもしれない。この布の刺繍を縫った誰かがいて、その誰かと俺は——。"}, {"id": "ch14-s05-p091", "type": "text", "text": "鳩尾の奥で沈殿物が動いた。浮遊している。午後からずっと浮遊している。処理が終わらない。形が定まらない。何がどうなっているのかを理解するための情報が足りない。十年間の空白は十年分の量がある。今朝の数時間で処理できるものではなかった。"}, {"id": "ch14-s05-p092", "type": "text", "text": "掌の布を見ていた。"}, {"id": "ch14-s05-p093", "type": "text", "text": "布の向こうに、霜月さんの研究室のモニタが重なった。赤い帯。外円区を覆い始めた蝕域。42パーセントに跳ね上がった指数と、三倍に加速した侵食速度が、二週間以内の消滅を告げている。"}, {"id": "ch14-s05-p094", "type": "text", "text": "俺はルミエラ島にいたかもしれない。十年間、蝕域の中にいたかもしれない。"}, {"id": "ch14-s05-p095", "type": "text", "text": "蝕域が何かを知っている。体が知っている。十年の中で、体が何かに触れていた。思い出せない。思い出せないけれど、体が知っている。体が白い光の中に帰ろうとした。今朝の屋上で。"}, {"id": "ch14-s05-p096", "type": "text", "text": "思い出したところで——何ができる。"}, {"id": "ch14-s05-p097", "type": "text", "text": "蝕域の唯一の生存者。その肩書きが、蝕域を止める力を意味しない。ルミエラ島にいたかもしれない体が持っているのは、歯車を回す手と、計器を読む目だけだ。鐘を直す方法を知らない。侵食を止める手段を持たない。霜月さんの五年分の怒りに応えるだけの何かを、この手は一つも握っていない。"}, {"id": "ch14-s05-p098", "type": "text", "text": "無力だった。記憶が戻っても、戻らなくても、今の俺には何一つ——。"}, {"id": "ch14-s05-p099", "type": "text", "text": "けれど——今は。"}, {"id": "ch14-s05-p100", "type": "text", "text": "今、目の前で、この島が同じことになろうとしている。"}, {"id": "ch14-s05-p101", "type": "text", "text": "布片を内ポケットに戻した。"}, {"id": "ch14-s05-p102", "type": "text", "text": "椅子に座った。机の上に白紙を広げた。ペンを取った。三地点の時系列データ。十四時。十六時。十八時。一時間刻みの粒度に落とすには、八時と十時と十二時の値を管理室の記録簿から拾い直す必要がある。明朝、五時半に鐘鋳塔に入ればいい。"}, {"id": "ch14-s05-p103", "type": "text", "text": "手が動き始めた。"}, {"id": "ch14-s05-p104", "type": "text", "text": "転記の準備。フォーマットの線を引いている。白紙の上にペンが走る。まっすぐな線。定規がない。手で引いた。線が少し歪んだ。歪んだまま次の列に移った。"}, {"id": "ch14-s05-p105", "type": "text", "text": "俺の過去は待てる。"}, {"id": "ch14-s05-p106", "type": "text", "text": "十年待ったものが、もう少しだけ待てないはずがない。午後にそう決めた。その決めたことが、今夜、もう一段深い場所に降りた。待てるのではなかった。待つのだ。選んで。"}, {"id": "ch14-s05-p107", "type": "text", "text": "今、この島で同じことが起きようとしている。霜月さんの怒りがある。燈花の泣かない目がある。篠宮さんの震える手がある。鳴海さんの歌声が支えている鐘がある。外円区の農夫の、表情が抜け落ちた顔がある。"}, {"id": "ch14-s05-p108", "type": "text", "text": "俺の過去の嵐と、この島の嵐。二つが同時に来ている。"}, {"id": "ch14-s05-p109", "type": "text", "text": "けれど手は一つしかない。体は一つしかない。一度に掴めるものには限りがある。ならば——今を掴む。ルミエラの布片は内ポケットにある。消えない。消さない。けれど今、この手が掴むのは、ペンと、データと、霜月さんに渡す数字だ。"}, {"id": "ch14-s05-p110", "type": "text", "text": "白紙の上にフォーマットが出来上がっていく。縦軸に時刻。横軸に三地点の名前。空欄が並んでいる。明朝、この空欄を数字で埋める。"}, {"id": "ch14-s05-p111", "type": "text", "text": "窓の外で風が鳴っている。十二月の夜の風。方角は南——外円区の方角、白い光が前進し続けている方角だった。風の音が窓ガラスを叩いている。窓ガラスの向こうは暗い。暗い中で、蝕域は脈動しているはずだった。"}, {"id": "ch14-s05-p112", "type": "text", "text": "ペンを置いた。"}, {"id": "ch14-s05-p113", "type": "text", "text": "明朝、五時半。"}]}, {"chapter": 15, "chapterTitle": "縁蝕波", "scene": 1, "sceneTitle": "世界が震える", "wordCount": "約6,100字", "paragraphs": [{"id": "ch15-s01-p001", "type": "text", "text": "仮眠から体を起こしたのは一時四十分だった。"}, {"id": "ch15-s01-p002", "type": "text", "text": "補佐官舎ではなく鐘鋳塔の一階、管理室の奥にある当直室。狭い寝台に横になったのが二十三時の鐘打ちの直後で、二時の鐘打ちの前に起きて当直の準備に入る予定だった。目覚ましは使っていない。体内時計がこの業務を覚えている。九ヶ月。それだけの時間が体に刻まれている。"}, {"id": "ch15-s01-p003", "type": "text", "text": "寝台から足を下ろした。石の床が冷たい。十二月の深夜。暖房の乏しい塔の一階は、補佐官舎の木床よりもう二段階冷えている。上着を羽織った。内ポケットに布片がある。ルミエラ。触らなかった。在ることだけを確認して手を離した。"}, {"id": "ch15-s01-p004", "type": "text", "text": "昨夜、補佐官舎でフォーマットの用紙を作った。三地点。時系列。一時間刻み。明朝——今朝の五時半に記録簿から数値を拾い直す予定だったが、目が覚めてしまったのなら先に始めていい。霜月さんに渡すデータは一時間でも早い方がいい。二週間以内に外円区全体が消滅する可能性がある。時間には値段がある。"}, {"id": "ch15-s01-p005", "type": "text", "text": "管理室に移った。計器のモニタが残響灯の青白い光の中で数字を並べている。深夜帯の鐘鋳塔は静かだ。当直の鐘守が六階にいるはずだが、この階まで人の気配は降りてこない。金属と潤滑油と、湿った石の匂い。九ヶ月前の初日から変わらない匂い。"}, {"id": "ch15-s01-p006", "type": "text", "text": "記録簿を開いた。南端、北東、西沿岸域。三地点。八時のデータから書き写す。ペンが数字を追う。机の上に夕方に作ったフォーマットの用紙を広げ、空欄に数字を埋めていく。八時。十時。十二時。"}, {"id": "ch15-s01-p007", "type": "text", "text": "鳩尾の奥にある沈殿物は沈んだままだった。昨夜より低い位置にある。処理が終わったのではない。沈殿したのだ。浮いていたものが重みに負けて底に着いた。晶さんの声、蝕域の白い光、体が伸ばした手、ルミエラの刺繍。全てが鳩尾の底に堆積している。堆積しているが、動かない。「今を掴む」と決めた意志が、沈殿物の上に蓋をしている。"}, {"id": "ch15-s01-p008", "type": "text", "text": "ペンが数字を追った。十四時。十六時。十八時。昨日転記した分と合わせて、南端の一日分がほぼ揃った。北東と西沿岸域は午前分がまだ足りない。五時半の記録室で補完する。"}, {"id": "ch15-s01-p009", "type": "text", "text": "一時五十五分。"}, {"id": "ch15-s01-p010", "type": "text", "text": "二時の鐘打ちまで五分。ペンを置いた。二時の鐘打ちの間は管理室のモニタで出力を確認する。深夜帯の出力は昼間よりさらに低い。六十二パーセントから六十五パーセントの間を行き来する不安定な数値。残響紋の劣化が修復されていない。鳴海さんの出力補完歌唱がなければ五十パーセントを切る。その閾値の意味は霜月さんの「蝕域の抑止力が——」で止まった言葉の先にある。"}, {"id": "ch15-s01-p011", "type": "text", "text": "時計を見た。"}, {"id": "ch15-s01-p012", "type": "text", "text": "一時五十八分。"}, {"id": "ch15-s01-p013", "type": "text", "text": "椅子の背もたれに体重を預けた。二分待てば鐘が鳴る。鐘が鳴れば体が揺れる。深夜帯の鐘打ちは強度が低いが、それでも胸骨の裏まで届く。鐘鋳塔の内側にいると、鐘の音は外で聴くより骨に近い。石壁が振動を伝えるからだ。"}, {"id": "ch15-s01-p014", "type": "text", "text": "一時五十九分。"}, {"id": "ch15-s01-p015", "type": "text", "text": "数字を埋めたフォーマットの用紙が机の上にある。南端の列。午前中の数値は昨日の観測値と大差ない。午後から上がる。十四時が起点。十六時で0.2ポイント上昇。十八時でさらに0.1。外円区の蝕域活動指数は、午後の方が高い。日没後に下がる傾向はない。24時間上昇し続ける指数は——"}, {"id": "ch15-s01-p016", "type": "text", "text": "床が、揺れた。"}, {"id": "ch15-s01-p017", "type": "break", "text": "◇"}, {"id": "ch15-s01-p018", "type": "text", "text": "最初は鐘だと思った。"}, {"id": "ch15-s01-p019", "type": "text", "text": "二時ちょうど。鐘打ちの衝撃が来たのだと。しかし違った。揺れの方向が違う。鐘の振動は上から来る。十階の大鐘が鳴り、その振動が塔全体を縦に伝って管理室の床に降りてくる。縦の振動。今の揺れは横だった。"}, {"id": "ch15-s01-p020", "type": "text", "text": "床が東西に動いた。机の上でペンが転がった。記録簿の端が浮いた。椅子がずれた。体が椅子ごと左に傾いた。"}, {"id": "ch15-s01-p021", "type": "text", "text": "地震。"}, {"id": "ch15-s01-p022", "type": "text", "text": "——違う。"}, {"id": "ch15-s01-p023", "type": "text", "text": "地震は地面が揺れる。今、揺れているのは地面ではなかった。石壁が震えている。天井が震えている。残響灯が振れて影が走った。しかし足裏が報告している振動の質が、地震とは違う。地震の振動は硬い。岩盤が軋む硬さ。今の振動は柔らかい。石壁の向こうの空気が震えていて、その空気の震えが壁を揺らしている。"}, {"id": "ch15-s01-p024", "type": "text", "text": "外から来ている。"}, {"id": "ch15-s01-p025", "type": "text", "text": "立ち上がった。椅子が後ろに滑った。足を踏ん張った。揺れが大きくなっていた。モニタの画面が振れている。計器の針が全て右に振れた。蝕域活動指数のグラフが跳ねた。折れ線が、画面の上端に向かって垂直に立ち上がっている。"}, {"id": "ch15-s01-p026", "type": "text", "text": "鐘が鳴り始めた。"}, {"id": "ch15-s01-p027", "type": "text", "text": "二時ちょうどの定時鐘打ち。しかし音が通常と違った。鐘の音の中に不協和音が混ざっている。残響紋の劣化した第三系統が、他の系統と位相がずれている。出力六十五パーセントの鐘が正しい波形を出せていない。鐘の音が塔の壁面を降りてくると、石壁がびりびりと小さく唸った。"}, {"id": "ch15-s01-p028", "type": "text", "text": "唸りの音に混じって——足音。"}, {"id": "ch15-s01-p029", "type": "text", "text": "石段を駆け降りてくる足音。速い。靴底が石を叩く鋭い打撃音。研究区画の三階から。二階を通過して一階に降りてくる。この時間に三階にいる人間は一人しかいない。"}, {"id": "ch15-s01-p030", "type": "text", "text": "鉄扉が開いた。"}, {"id": "ch15-s01-p031", "type": "text", "text": "霜月さんが管理室に入ってきた。"}, {"id": "ch15-s01-p032", "type": "text", "text": "白いコートの裾が翻っていた。走ったのだ。銀髪のハーフアップが崩れかけている。毛先がコートの襟にかかっている。十二月の機構室で検査灯を当てていた時と同じ乱れ方。しかし目が違った。ラベンダーの瞳が開いていた。鉱石の断面の硬さではなく、切削面の鋭さで開いていた。"}, {"id": "ch15-s01-p033", "type": "text", "text": "「縁蝕波だ」"}, {"id": "ch15-s01-p034", "type": "text", "text": "声。"}, {"id": "ch15-s01-p035", "type": "text", "text": "低い。短い。一秒で全てを切り出す声。"}, {"id": "ch15-s01-p036", "type": "text", "text": "「外円区方面、出力レベル過去最大——」"}, {"id": "ch15-s01-p037", "type": "text", "text": "霜月さんの視線がモニタに行った。折れ線グラフの垂直な跳ね。数字が赤く点滅している。通常の表示色は白。赤い点滅は閾値の超過を示す。"}, {"id": "ch15-s01-p038", "type": "text", "text": "管理室のモニタは三台。一台目が蝕域活動指数。二台目が鐘の出力モニタ。三台目がエリア別の地図表示。三台目の画面が白く飛んでいた。外円区の南を示す区画が、白い光で塗りつぶされている。"}, {"id": "ch15-s01-p039", "type": "text", "text": "「窓」"}, {"id": "ch15-s01-p040", "type": "text", "text": "霜月さんが短く言った。"}, {"id": "ch15-s01-p041", "type": "text", "text": "俺は管理室の南側の窓に走った。分厚い硝子。硝子に手をかけて、鍵を外して開いた。夜の空気が入ってきた。十二月の深夜。二度目の冷気——ではなかった。"}, {"id": "ch15-s01-p042", "type": "text", "text": "匂い。"}, {"id": "ch15-s01-p043", "type": "text", "text": "粉の匂いが入ってきた。"}, {"id": "ch15-s01-p044", "type": "text", "text": "知っている。今朝——昨日の早朝、晶さんと一緒に第一監視哨に行った時に嗅いだ匂い。蝕域に近づくと空気に混ざる、乾いた粉のような匂い。紙を千切ったような。鐘鋳塔は島の中心にある。内円区の、最も蝕域から遠い場所。ここまで粉の匂いが届いている。"}, {"id": "ch15-s01-p045", "type": "text", "text": "窓の外を見た。"}, {"id": "ch15-s01-p046", "type": "text", "text": "南。"}, {"id": "ch15-s01-p047", "type": "text", "text": "外円区の方角。"}, {"id": "ch15-s01-p048", "type": "text", "text": "白かった。"}, {"id": "ch15-s01-p049", "type": "text", "text": "地平線の低い位置が、白く光っていた。夜の闇の中に、横一線の白光。第一監視哨の屋上で見た蝕域の白と同じ色。しかしあの時は正面の数百メートル先に見えた壁だった。今は違う。南の地平線全体が光っている。東から西まで。白い光が地面の際から空に向かって立ち上がり、夜の雲の底を白く染めていた。"}, {"id": "ch15-s01-p050", "type": "text", "text": "蝕域が膨張している。"}, {"id": "ch15-s01-p051", "type": "text", "text": "光は静止していなかった。じわりと、内側に向かって動いていた。南の地平線から、島の中心に向かって。ゆっくりに見える。しかしあの白い光の端から鐘鋳塔までの距離は数十キロメートル。その距離を目で見てわかる速度で詰めているということは——"}, {"id": "ch15-s01-p052", "type": "text", "text": "体が震えた。"}, {"id": "ch15-s01-p053", "type": "text", "text": "両膝。両手。指先。体が勝手に反応していた。恐怖の身体反応。しかし恐怖だけではなかった。今朝の屋上と同じだった。蝕域を間近で見た時に体が起こした反応。恐怖と、それとは別の——"}, {"id": "ch15-s01-p054", "type": "text", "text": "鳩尾の底が動いた。"}, {"id": "ch15-s01-p055", "type": "text", "text": "沈殿物の下。もっと深い場所。名前のない場所。今朝、体が手すりの向こうに手を伸ばした時に引っ張った場所。腹の底。背骨の裏側。あの場所が、今、南の白い光に向かって引かれていた。"}, {"id": "ch15-s01-p056", "type": "text", "text": "同じだ。"}, {"id": "ch15-s01-p057", "type": "text", "text": "体が叫んでいた。"}, {"id": "ch15-s01-p058", "type": "text", "text": "同じだ。これは同じだ。"}, {"id": "ch15-s01-p059", "type": "text", "text": "記憶にはなかった。頭のどこを探しても、「大規模な縁蝕波」の記憶はなかった。ルミエラ島の消滅を見た記憶はなかった。十年の空白は空白のままだった。"}, {"id": "ch15-s01-p060", "type": "text", "text": "けれど体が知っている。"}, {"id": "ch15-s01-p061", "type": "text", "text": "足裏が。背骨が。腹の底が。体の全てが「これを知っている」と報告してきていた。白い光が地平線から押し寄せてくる光景を、この体は見たことがある。嗅いだことがある。聴いたことがある。粉の匂いと、音が薄くなっていく感覚と、存在が希薄になっていく空気の密度を、この体は覚えている。"}, {"id": "ch15-s01-p062", "type": "text", "text": "ルミエラ島の時と同じだ。"}, {"id": "ch15-s01-p063", "type": "text", "text": "記憶がそう言っているのではなかった。体がそう言っていた。十年前に失われた記憶の代わりに、体の細胞の一つ一つが記録していた情報が、南の白い光に呼応して再生されている。"}, {"id": "ch15-s01-p064", "type": "text", "text": "手が震えた。右手。今朝、蝕域に向かって伸ばした手。あの手が、今、窓枠を掴んでいた。掴んで、放さなかった。放したら——手が南に向かって伸びる。あの時と同じように。帰ろうとする。"}, {"id": "ch15-s01-p065", "type": "text", "text": "掴んでいた。"}, {"id": "ch15-s01-p066", "type": "text", "text": "窓枠の石が冷たかった。冷たさが掌から前腕に上がる。冷たさの中に、昨日の晶さんの指の圧力が残っていた。「触れるな」の声。あの声が掌の下にある。"}, {"id": "ch15-s01-p067", "type": "text", "text": "「朝霧」"}, {"id": "ch15-s01-p068", "type": "text", "text": "霜月さんの声が来た。"}, {"id": "ch15-s01-p069", "type": "text", "text": "窓から体を引き剥がした。振り返った。霜月さんがモニタの前にいた。三台目のモニタ。エリア別の地図。白く飛んでいた外円区南の区画が、さらに広がっていた。白い領域が地図の上で北に向かって進んでいる。数字がモニタの端を流れている。消滅面積。リアルタイムで増加している。"}, {"id": "ch15-s01-p070", "type": "text", "text": "0.5平方キロメートル。0.8。1.2。1.5。"}, {"id": "ch15-s01-p071", "type": "text", "text": "十一月の消滅は0.5平方キロメートルで八名だった。今、数字は十倍の速度で増えている。"}, {"id": "ch15-s01-p072", "type": "text", "text": "「推定消滅人口」"}, {"id": "ch15-s01-p073", "type": "text", "text": "霜月さんの声が平らだった。平らに保つことに力を使っている声。昨夜の研究室で「同じ結末になった」の亀裂を入れた声の逆。亀裂を封じている。封じなければ動けないからだ。"}, {"id": "ch15-s01-p074", "type": "text", "text": "モニタの数字が変わった。"}, {"id": "ch15-s01-p075", "type": "text", "text": "推定消滅人口。十七。四十二。七十八。——百を超えた。"}, {"id": "ch15-s01-p076", "type": "text", "text": "百人。"}, {"id": "ch15-s01-p077", "type": "text", "text": "俺の足が動いた。動いた方向は窓ではなかった。南ではなかった。モニタの横に立った。霜月さんの隣。数字を見た。百十二。百三十一。まだ増えている。白い領域はまだ広がっている。"}, {"id": "ch15-s01-p078", "type": "text", "text": "「2.3平方キロメートル。侵食速度は——一時間あたり4.2平方キロ。外円区南半分が三時間以内に」"}, {"id": "ch15-s01-p079", "type": "text", "text": "霜月さんの声が切れた。"}, {"id": "ch15-s01-p080", "type": "text", "text": "一瞬だけ。ラベンダーの瞳の中で、何かが走った。光ではない。感情だった。五年前の望ヶ丘。三百人が消えた夜。この人は今、同じ数字を見ている。同じ速度で増えていく消滅面積と、同じように動かなかった上層部と、同じように劣化した鐘の出力を。"}, {"id": "ch15-s01-p081", "type": "text", "text": "しかし瞳が動いた方向は過去ではなかった。"}, {"id": "ch15-s01-p082", "type": "text", "text": "霜月さんが俺の横を抜けた。管理室を出た。足音が石段を下がっていく。一階から地下へ。地下一階。機構室。鐘の駆動装置がある階。"}, {"id": "ch15-s01-p083", "type": "text", "text": "俺も走った。"}, {"id": "ch15-s01-p084", "type": "text", "text": "石段を降りた。地下一階の通路を抜ける。機構室の鉄扉が開いていた。歯車が壁面を覆う薄暗い空間。残響灯の青白い光の中で、大小の歯車が回転している。音が変だった。歯車の噛み合わせから微細な振れの音がしている。ギリ、ギリという、金属の軋み。定常運転の音ではない。"}, {"id": "ch15-s01-p085", "type": "text", "text": "霜月さんが既に機構室の中央にいた。"}, {"id": "ch15-s01-p086", "type": "text", "text": "制御盤の前。モニタが四台。鐘の出力、共鳴管の圧力、残響紋の出力、歯車列の回転数。全ての数字が赤い。赤い点滅。"}, {"id": "ch15-s01-p087", "type": "text", "text": "霜月さんの手が制御盤の上を走っていた。スイッチ。計器。表示切替。速い。速いが正確だった。この人の手は危機の中でも一切の迷いがない。歯車に触れないまま制御盤の数値だけで全系統の状態を読み取り、対応を判断している。"}, {"id": "ch15-s01-p088", "type": "text", "text": "「出力六十五パーセント」"}, {"id": "ch15-s01-p089", "type": "text", "text": "声が出た。俺に向けた声ではなかった。独り言に近い。自分の判断の補助線として声に出している。"}, {"id": "ch15-s01-p090", "type": "text", "text": "「第三系統の残響紋が五十八に低下。修復は——間に合っていない。この出力では——」"}, {"id": "ch15-s01-p091", "type": "text", "text": "霜月さんの左手が制御盤の縁を掴んだ。指が白くなった。力がかかっている。"}, {"id": "ch15-s01-p092", "type": "text", "text": "昨夜の研究室で氷華が言った言葉が聞こえた。「二週間以内に外円区全体が消滅する可能性がある」。二週間。予想された猶予が、今夜、数時間に縮んだ。"}, {"id": "ch15-s01-p093", "type": "text", "text": "「共鳴者の補完なしでは——」"}, {"id": "ch15-s01-p094", "type": "text", "text": "声が途切れた。"}, {"id": "ch15-s01-p095", "type": "text", "text": "共鳴者。鳴海さん。九階の共鳴の間で歌えば鐘の出力を補完できる。しかし鳴海さんの体への負担。身体負荷指数。十月に四十七パーセントだった数字が、出力補完歌唱を続けた今、さらに上がっているはずだった。上がっていることを霜月さんは知っている。数字として知っている。数字の意味として知っている。"}, {"id": "ch15-s01-p096", "type": "text", "text": "霜月さんの左手がピアスに行った。"}, {"id": "ch15-s01-p097", "type": "text", "text": "青い石。左耳。十月に確認するように触れた。十一月に震える手で触れた。十二月の昨夜、親指と人差し指で挟んだ。今、指先がピアスの台座に触れて——離れた。触れて、すぐに離した。確認する時間がなかった。"}, {"id": "ch15-s01-p098", "type": "text", "text": "ラベンダーの瞳が俺を見た。"}, {"id": "ch15-s01-p099", "type": "text", "text": "瞳の中に炎はなかった。昨夜の固体化した怒りもなかった。あるのは透明な速度だった。感情を通していない目。しかし氷でもなかった。感情を凍らせているのではなく、感情を後回しにしている。今この瞬間に使える全ての処理能力をデータと判断に割り当てている人の目。"}, {"id": "ch15-s01-p100", "type": "text", "text": "「朝霧。管理室のモニタに張りつけ。消滅面積と侵食速度を五分ごとに記録しなさい。私は上階にいく」"}, {"id": "ch15-s01-p101", "type": "text", "text": "指示。"}, {"id": "ch15-s01-p102", "type": "text", "text": "明確で、短く、一つの曖昧さもない。"}, {"id": "ch15-s01-p103", "type": "text", "text": "昨夜の「お前は三地点の時系列データを今週中に整えろ」と同じ構造の声。しかし時間の縮尺が違った。今週中が五分ごとに変わった。猶予が消えた分だけ声が速くなっている。"}, {"id": "ch15-s01-p104", "type": "text", "text": "「了解しました」"}, {"id": "ch15-s01-p105", "type": "text", "text": "声が出た。"}, {"id": "ch15-s01-p106", "type": "text", "text": "出た声は震えていなかった。両膝はまだ揺れていた。右手はまだ冷たかった。窓の外の白い光に引かれた腹の底の衝動は完全には消えていなかった。"}, {"id": "ch15-s01-p107", "type": "text", "text": "けれど動けた。"}, {"id": "ch15-s01-p108", "type": "text", "text": "昨夜、ペンを持って白紙にフォーマットの線を引いた手が、今朝もペンを持てた。「今を掴む」と決めた手が、震えながら動いた。記録する。数字を読む。それが俺にできることだ。それが俺の手が今、掴むものだ。"}, {"id": "ch15-s01-p109", "type": "text", "text": "霜月さんが機構室を出た。足音が上に向かう。地下一階から一階へ、さらに上へ。六階。鐘守居住区。当直の鐘守を叩き起こすのだろう。緊急鐘打ちの手配。そしてその先に——九階。共鳴の間。"}, {"id": "ch15-s01-p110", "type": "text", "text": "俺は石段を上がった。"}, {"id": "ch15-s01-p111", "type": "text", "text": "管理室に戻った。三台のモニタが全て赤かった。南の窓は開いたままだった。開いた窓から粉の匂いが流れ込んでいる。匂いが濃くなっていた。五分前より。"}, {"id": "ch15-s01-p112", "type": "text", "text": "窓の外を見た。"}, {"id": "ch15-s01-p113", "type": "text", "text": "南の白い光が、近づいていた。"}]}, {"chapter": 15, "chapterTitle": "縁蝕波", "scene": 2, "sceneTitle": "千歳の歌、命の炎", "wordCount": "約6,200字", "paragraphs": [{"id": "ch15-s02-p001", "type": "text", "text": "石段を上がった。"}, {"id": "ch15-s02-p002", "type": "text", "text": "一階の管理室のモニタは全て赤い。五分ごとの記録。二時五分。消滅面積2.3平方キロメートル。推定消滅人口百四十七。数字を紙に書いた。書いた直後に、上階から足音が降りてきた。"}, {"id": "ch15-s02-p003", "type": "text", "text": "鐘守だった。当直の。六階の鐘守居住区から降りてきた男が管理室の扉を開けた。四十代。名前を知らない。顔は覚えている。深夜帯の当直で何度かすれ違った。"}, {"id": "ch15-s02-p004", "type": "text", "text": "「朝霧補佐。霜月技師から伝令。九階に来い、と」"}, {"id": "ch15-s02-p005", "type": "text", "text": "九階。"}, {"id": "ch15-s02-p006", "type": "text", "text": "共鳴の間。"}, {"id": "ch15-s02-p007", "type": "text", "text": "足が動いた。動く前に考えた。管理室のモニタを五分ごとに記録する指示を霜月さんから受けている。管理室を離れていいのか。"}, {"id": "ch15-s02-p008", "type": "text", "text": "「当直の鐘守に引き継げ、とのことです」"}, {"id": "ch15-s02-p009", "type": "text", "text": "声は当直の鐘守のものだった。指示系統が通っている。霜月さんは管理室の記録を引き継がせた上で俺を呼んでいる。"}, {"id": "ch15-s02-p010", "type": "text", "text": "「了解しました。モニタは三台。赤い数字が全てです。五分ごとに消滅面積と侵食速度を記録してください」"}, {"id": "ch15-s02-p011", "type": "text", "text": "当直の鐘守に紙とペンを渡した。書きかけの数字の列。男が紙面を見た。数字を読んだ。顔が変わったが、声は出さなかった。"}, {"id": "ch15-s02-p012", "type": "text", "text": "管理室を出た。"}, {"id": "ch15-s02-p013", "type": "text", "text": "石段を上がる。一階から二階。二階から三階。三階を通過した。霜月さんの研究区画のある階。扉は閉まっていた。灯りが漏れていない。霜月さんは三階にいない。九階にいる。"}, {"id": "ch15-s02-p014", "type": "text", "text": "四階。五階。六階。七階。八階。"}, {"id": "ch15-s02-p015", "type": "text", "text": "石段は螺旋だった。鐘鋳塔の内壁に沿って右回りに上がる。残響灯が壁面に等間隔で埋め込まれている。上に行くほど光の色が紫がかった。八階を過ぎた頃から空気が変わった。密度が増す。共鳴の間に近づいている。九階の空気は鐘鋳塔の他の階と違う。壁面の残響金属が空気の質を変える。音を吸い、音を返す構造が空気そのものを重くする。"}, {"id": "ch15-s02-p016", "type": "text", "text": "九階。"}, {"id": "ch15-s02-p017", "type": "text", "text": "踊り場に出た。"}, {"id": "ch15-s02-p018", "type": "text", "text": "左手に鉄の扉。扉の上に銅版のプレート。「共鳴の間」。文字は見慣れていた。七月から何度もこの扉の外で計器を操作した。扉の内側に入ったのは数えるほどだった。共鳴者が歌唱する際、技術スタッフ以外の立ち入りは原則として禁止されている。"}, {"id": "ch15-s02-p019", "type": "text", "text": "扉が開いていた。"}, {"id": "ch15-s02-p020", "type": "text", "text": "開け放たれていた。気密用のゴムシールが外気に触れている。防音のための構造が、今は意味を失っている。扉が開いた理由はわかった。緊急時だからだ。閉める手順を踏む時間がなかった。"}, {"id": "ch15-s02-p021", "type": "text", "text": "扉の内側から、声が聞こえた。"}, {"id": "ch15-s02-p022", "type": "text", "text": "歌声ではなかった。"}, {"id": "ch15-s02-p023", "type": "text", "text": "「鳴海。出力補完歌唱を開始してくれ。対象は第三系統を含む全系統。目標出力は八十パーセント」"}, {"id": "ch15-s02-p024", "type": "text", "text": "霜月さんの声。短い。硬い。指示の声。しかし「鳴海」の二音節だけが、他の語句より0.2秒長かった。"}, {"id": "ch15-s02-p025", "type": "text", "text": "もう一つ、声があった。"}, {"id": "ch15-s02-p026", "type": "text", "text": "「はい」"}, {"id": "ch15-s02-p027", "type": "text", "text": "一語。鳴海さんの声だった。"}, {"id": "ch15-s02-p028", "type": "text", "text": "薄くはなかった。楽屋で聴いた紙のような声とは違う。短い一語の中に厚みがあった。しかしその厚みの種類が普段と違った。穏やかさが削れている。残っているのは——芯。歌う前の、声の芯だけ。"}, {"id": "ch15-s02-p029", "type": "text", "text": "俺は扉の前を通り、共鳴の間の内部に入った。"}, {"id": "ch15-s02-p030", "type": "text", "text": "球形の空間。直径十メートル。壁面を覆う残響紋が、残響灯の紫がかった光の中で浮き上がっている。七月にここで計器を操作した時と同じ空間。同じ壁面。同じ光。しかし空気が違った。七月の空気は静かで密だった。今の空気は震えていた。鐘鋳塔全体が縁蝕波で揺れている振動が、壁面の残響金属を通じてここまで伝わっている。"}, {"id": "ch15-s02-p031", "type": "text", "text": "鳴海さんが球体の中央にいた。"}, {"id": "ch15-s02-p032", "type": "text", "text": "白いブラウス。淡いブルーのスカート。首に銀のチョーカー。訓練時と同じ装束。しかし十二月の深夜に、カーディガンがなかった。走ってきたのだ。補佐官舎から鐘鋳塔に走り、九階まで駆け上がったのだ。髪が乱れていた。亜麻色のウェーブヘアが背中に散らばり、前髪が額に張りついている。汗。右前髪のリボンが傾いていた。母の形見のリボン。"}, {"id": "ch15-s02-p033", "type": "text", "text": "顔が白かった。"}, {"id": "ch15-s02-p034", "type": "text", "text": "白い、は比喩ではなかった。残響灯の紫の光の中で、鳴海さんの顔から色が抜けていた。頬に血の色がなかった。唇も白い。十一月の楽屋で見た青白さと同じ。いや。同じではなかった。あの時は歌い終わった後だった。今は歌い始める前から、この色をしている。十三日間の出力補完歌唱が体を削っている。削った上に、今夜、走ってきた。"}, {"id": "ch15-s02-p035", "type": "text", "text": "霜月さんが壁面の計器の前にいた。三台。白いコートの背中が計器に向いている。銀髪のハーフアップが崩れかけていた。先ほどの管理室で見た時と同じ。走って上階に来たまま、髪を直す時間を取っていない。"}, {"id": "ch15-s02-p036", "type": "text", "text": "「朝霧。計器の補助に入りなさい。残響波検出装置の数値を口頭で報告。十五秒間隔」"}, {"id": "ch15-s02-p037", "type": "text", "text": "指示。明確。短い。"}, {"id": "ch15-s02-p038", "type": "text", "text": "「了解しました」"}, {"id": "ch15-s02-p039", "type": "text", "text": "計器の前に立った。残響波検出装置。針がゼロ点で微細に振れている。縁蝕波の振動を拾っている。まだ歌は始まっていない。始まっていないのに、針が震えていた。"}, {"id": "ch15-s02-p040", "type": "text", "text": "「始めます」"}, {"id": "ch15-s02-p041", "type": "text", "text": "鳴海さんの声が球形の空間に落ちた。"}, {"id": "ch15-s02-p042", "type": "text", "text": "俺は計器を見ていた。見ていなければならなかった。業務だった。しかし鳴海さんの声が聞こえた時——顔を上げた。"}, {"id": "ch15-s02-p043", "type": "text", "text": "鳴海さんが目を閉じていた。"}, {"id": "ch15-s02-p044", "type": "text", "text": "背筋が伸びている。両手が体の横に下がり、指先が軽く開いている。七月の共鳴室で見た準備と同じ動作。呼吸が変わる。肩が上がり、胸が膨らみ——"}, {"id": "ch15-s02-p045", "type": "text", "text": "声が出た。"}, {"id": "ch15-s02-p046", "type": "text", "text": "最初の一音。空気が裂けた。球形の壁面が鳴った。残響金属が声を拾い、反射し、増幅した。全方向から音が戻ってくる。七月と同じ。四メートルの距離で聴く鳴海さんの声。声の中にいる。"}, {"id": "ch15-s02-p047", "type": "text", "text": "同じだった。"}, {"id": "ch15-s02-p048", "type": "text", "text": "——同じではなかった。"}, {"id": "ch15-s02-p049", "type": "text", "text": "七月の声は水だった。全身を均等に包む声。今夜の声は火だった。均等ではない。声の密度が偏っている。旋律の低い部分に力が集中している。高音域が薄い。低音を押し出すために、高音を削っている。声帯の余力が足りない。足りない余力の中で、最大の出力を出すために、声の構造が変わっている。"}, {"id": "ch15-s02-p050", "type": "text", "text": "計器の針が跳ねた。"}, {"id": "ch15-s02-p051", "type": "text", "text": "「残響波、基準値の二倍。上昇中」"}, {"id": "ch15-s02-p052", "type": "text", "text": "声が出た。業務の声。報告の声。自分の声が自分の耳に聞こえている。同時に、鳩尾の上が動いた。"}, {"id": "ch15-s02-p053", "type": "text", "text": "鳴海さんの歌声の場所。七ヶ月前に管が通った場所。そこが反応していた。声の振動に揺らされている。揺らし方が七月とは違った。七月は緩んだ。温かかった。薄い痛みが混ざっていた。"}, {"id": "ch15-s02-p054", "type": "text", "text": "今は——灼けていた。"}, {"id": "ch15-s02-p055", "type": "text", "text": "声が入ってくるたびに熱が増す。温かさではない。もっと鋭い。鳴海さんの声の中にあるものが変わっている。七月の声の中にあったのは穏やかさと、その奥の痛みだった。今夜の声の中にあるのは——命そのものが燃えている音。"}, {"id": "ch15-s02-p056", "type": "text", "text": "壁面の残響紋が光っていた。"}, {"id": "ch15-s02-p057", "type": "text", "text": "紋様の溝に沿って燐光が流れている。七月にも同じ現象を見た。鳴海さんの声に呼応して壁が発光する。しかし今夜の光は七月より強い。強く、速い。光の脈拍が鳴海さんの呼吸より速かった。声に追いつこうとして、壁面の金属が限界まで応答している。"}, {"id": "ch15-s02-p058", "type": "text", "text": "旋律が上昇した。"}, {"id": "ch15-s02-p059", "type": "text", "text": "低音域から中音域へ。声が昇っていく。声量が増す。球形の壁面が一斉に唸った。鐘鋳塔自体が楽器のように震えている。足裏に振動が伝わる。石の床を通じて。鐘鋳塔の全十階が鳴海さんの声で共振している。"}, {"id": "ch15-s02-p060", "type": "text", "text": "「残響波、基準値の三倍。出力上昇中。六十八パーセント」"}, {"id": "ch15-s02-p061", "type": "text", "text": "霜月さんの指が計器の上を走った。鐘の出力モニタ。数字が動いていた。六十五から六十八に上がっている。鳴海さんの歌が鐘の出力を押し上げている。"}, {"id": "ch15-s02-p062", "type": "text", "text": "鳴海さんの手が震えていた。"}, {"id": "ch15-s02-p063", "type": "text", "text": "歌いながら。両手が体の横に下がったまま。指先が開いているはずだった。七月は開いていた。今夜は——指先が痙攣していた。十一月の楽屋で見た痙攣と同じ。不規則な。止められない。意志と関係なく動いている。"}, {"id": "ch15-s02-p064", "type": "text", "text": "顔から汗が流れていた。"}, {"id": "ch15-s02-p065", "type": "text", "text": "額。頬。首筋。十二月の深夜。共鳴の間は暖房がない。九階の石壁は冷たい。それでも汗が出ている。体温が上がっている。命を燃やしている。文字通り。体の中で何かを燃やして、その熱で声を出している。"}, {"id": "ch15-s02-p066", "type": "text", "text": "「七十三パーセント」"}, {"id": "ch15-s02-p067", "type": "text", "text": "声が出た。霜月さんの声。業務の声。しかしラベンダーの瞳がモニタから一瞬だけ鳴海さんの方を向いた。一瞬。0.3秒。数値を読む動作の合間に、挟まった視線。それだけで充分だった。霜月さんも見ている。鳴海さんの手の震えを。顔の白さを。汗を。"}, {"id": "ch15-s02-p068", "type": "text", "text": "旋律が頂点に向かっていた。"}, {"id": "ch15-s02-p069", "type": "text", "text": "中音域から高音域へ。声の密度が変わる。低音域に偏っていた力が、全帯域に広がろうとしている。広がりきれない。声が軋んでいた。七月の声には軋みがなかった。今夜の声には、絹が裂けるような、微細な軋みが混ざっていた。声帯が限界に近い。限界の向こう側に手を伸ばして、届くはずのない音を掴みにいっている。"}, {"id": "ch15-s02-p070", "type": "text", "text": "鳩尾の上が痛かった。"}, {"id": "ch15-s02-p071", "type": "text", "text": "熱が痛みに変わっていた。鳴海さんの声が上昇するたびに、体の奥にある何かが引っ張られる。声に引かれている。鳴海さんの中で燃えているものが、管を通って、俺の中にまで届いている。"}, {"id": "ch15-s02-p072", "type": "text", "text": "「七十八パーセント」"}, {"id": "ch15-s02-p073", "type": "text", "text": "「八十」"}, {"id": "ch15-s02-p074", "type": "text", "text": "数字が重なった。霜月さんの声と俺の報告が同時に出た。残響波検出装置の針が基準値の四倍を指していた。出力モニタが八十パーセントを記録した。目標値。"}, {"id": "ch15-s02-p075", "type": "text", "text": "蝕域の侵食速度が鈍る。"}, {"id": "ch15-s02-p076", "type": "text", "text": "それを示すデータは管理室のモニタにある。ここにはない。しかし足裏に伝わる振動が変わった。鐘鋳塔を揺らしていた横揺れが、弱まっている。縁蝕波の圧力が、鳴海さんの声で押し返されている。"}, {"id": "ch15-s02-p077", "type": "text", "text": "歌い続けていた。"}, {"id": "ch15-s02-p078", "type": "text", "text": "八十パーセントに達した後も、鳴海さんは歌い続けていた。旋律が頂点で止まらない。まだ昇ろうとしている。八十で止まるはずだった。目標値は八十だった。鳴海さんはそれを知っていたはずだ。知っていて——止まらない。"}, {"id": "ch15-s02-p079", "type": "text", "text": "蝕域がまだ動いているからだ。"}, {"id": "ch15-s02-p080", "type": "text", "text": "押し返してはいる。侵食速度は鈍った。しかし止まっていない。外円区の消滅面積はまだ増え続けている。八十パーセントでは足りない。足りないことを、鳴海さんの歌声が知っている。歌声が体の反応を先取りしている。"}, {"id": "ch15-s02-p081", "type": "text", "text": "霜月さんの左手がピアスに触れた。青い石。触れて——離さなかった。今夜は離さなかった。指先がピアスの台座に触れたまま、ラベンダーの瞳がモニタと鳴海さんの間を行き来していた。"}, {"id": "ch15-s02-p082", "type": "text", "text": "足音が聞こえた。"}, {"id": "ch15-s02-p083", "type": "text", "text": "共鳴の間の外。石段を駆け上がってくる足音。スニーカーの底が石を叩く音。不規則で、速い。上がってくる。八階を通過した。九階の踊り場に着いた。"}, {"id": "ch15-s02-p084", "type": "text", "text": "風祭さんが共鳴の間の入口に現れた。"}, {"id": "ch15-s02-p085", "type": "text", "text": "走ってきている。栗色のショートヘアが乱れていた。パジャマの上にジャケットを羽織っている。服の組み合わせが合っていない。寝ていたところを飛び起きたのだ。縁蝕波の横揺れで目が覚め、鐘鋳塔に走ってきた。"}, {"id": "ch15-s02-p086", "type": "text", "text": "風祭さんの目が共鳴の間の中を見た。"}, {"id": "ch15-s02-p087", "type": "text", "text": "緑色の目。翡翠色。走った後の呼吸で肩が上下している。視線が球形の空間を横切り——中央の鳴海さんを捉えた。"}, {"id": "ch15-s02-p088", "type": "text", "text": "止まった。"}, {"id": "ch15-s02-p089", "type": "text", "text": "風祭さんの体が止まった。足が。肩が。呼吸が。"}, {"id": "ch15-s02-p090", "type": "text", "text": "目だけが動いていた。鳴海さんを見ている。歌っている鳴海さんを。白い顔で。震える指先で。汗を流しながら。命を削りながら。"}, {"id": "ch15-s02-p091", "type": "text", "text": "風祭さんの膝が折れた。"}, {"id": "ch15-s02-p092", "type": "text", "text": "共鳴の間の入口。鉄の扉のすぐ内側。膝が石の床についた。崩れたのではない。膝から力が抜けたのだ。立っていられなくなったのだ。"}, {"id": "ch15-s02-p093", "type": "text", "text": "「ちーちゃん」"}, {"id": "ch15-s02-p094", "type": "text", "text": "声が出た。小さかった。歌声に掻き消される音量。しかし俺には聞こえた。四メートル先の計器の横にいる俺に、風祭さんの声は届いた。歌声の中を縫って届いた。"}, {"id": "ch15-s02-p095", "type": "text", "text": "「もうやめて……」"}, {"id": "ch15-s02-p096", "type": "text", "text": "声が割れていた。"}, {"id": "ch15-s02-p097", "type": "text", "text": "十一月の楽屋で聞いた風祭さんの声の段階。柔らかい声。硬い声。絞った声。芯が落ちた声。むき出しの手の声。枯れた声。今の声はそのどれでもなかった。声が出る場所そのものが壊れかけている。喉ではない。もっと奥。風祭さんの声帯の傷。訓練で壊しかけた喉の奥の傷が、今夜、もう一度開いている。"}, {"id": "ch15-s02-p098", "type": "text", "text": "「歌わないで……もう歌わないで、ちーちゃん……」"}, {"id": "ch15-s02-p099", "type": "text", "text": "風祭さんの目から涙が落ちた。床についた膝の上に。両手が膝の上で拳になっていた。右手首のミサンガが拳の間に挟まれていた。千歳と二人で編んだ。願いが叶ったら切れる。いろはの願い——千歳がずっと笑っていられますように。"}, {"id": "ch15-s02-p100", "type": "text", "text": "鳴海さんは歌い続けていた。"}, {"id": "ch15-s02-p101", "type": "text", "text": "風祭さんの声が聞こえたはずだった。共鳴の間は球形だ。全ての音が反射する。風祭さんの声も壁面で反射して鳴海さんに届いているはずだった。"}, {"id": "ch15-s02-p102", "type": "text", "text": "届いていた。"}, {"id": "ch15-s02-p103", "type": "text", "text": "鳴海さんの目が一瞬だけ開いた。歌いながら。琥珀の——琥珀ではなかった。水で割ったような、薄い。十一月の楽屋より薄い。十三日間の出力補完歌唱の全てが瞳の色を奪っている。薄い琥珀の瞳が、入口の風祭さんを見た。"}, {"id": "ch15-s02-p104", "type": "text", "text": "一秒。"}, {"id": "ch15-s02-p105", "type": "text", "text": "鳴海さんの目が何かを言おうとしていた。声では言えない。歌っているから。けれど目が——目だけが、風祭さんに向いていた。目の中にあるものは謝罪ではなかった。「大丈夫」でもなかった。"}, {"id": "ch15-s02-p106", "type": "text", "text": "「ごめんなさい。でも、止まれない」。"}, {"id": "ch15-s02-p107", "type": "text", "text": "そう言っていた。目が。声を使わずに。"}, {"id": "ch15-s02-p108", "type": "text", "text": "目が閉じた。歌が続いた。"}, {"id": "ch15-s02-p109", "type": "text", "text": "風祭さんの拳がさらに固くなった。指の関節が白くなっていた。十一月の廊下で俺が握った拳と同じ白さ。あの時、俺は怒りで拳を握った。風祭さんの拳は——怒りではなかった。止められない、という事実に対して、体が行き場を失っている。"}, {"id": "ch15-s02-p110", "type": "text", "text": "「ちーちゃん……ちーちゃん……」"}, {"id": "ch15-s02-p111", "type": "text", "text": "名前を呼んでいた。繰り返し。歌声の合間に、消え入る声で。二年間。二年間ずっとこの光景を予感していた人が、予感が現実になった瞬間に、できることが名前を呼ぶことだけだった。"}, {"id": "ch15-s02-p112", "type": "text", "text": "鳩尾の上が灼けていた。"}, {"id": "ch15-s02-p113", "type": "text", "text": "鳴海さんの歌声が管を通って入ってくる。同時に——風祭さんの声も入ってきていた。身体感覚マップに風祭さんの座標はなかった。けれど耳から入ってくる「ちーちゃん」の声が、歌声の熱に混ざっていた。熱と、名前を呼ぶ声の冷たさが。同じ場所で。"}, {"id": "ch15-s02-p114", "type": "text", "text": "弦月局長の声が蘇った。"}, {"id": "ch15-s02-p115", "type": "text", "text": "十二月の会議室。朝の光と油灯の火。「外円区の住民の安全と、鳴海くんの体調と。どちらを優先すべきだと思う」。"}, {"id": "ch15-s02-p116", "type": "text", "text": "あの時、答えが出なかった。"}, {"id": "ch15-s02-p117", "type": "text", "text": "今も出ない。"}, {"id": "ch15-s02-p118", "type": "text", "text": "鳴海さんを止めれば、鐘の出力が下がる。出力が下がれば、蝕域の侵食速度が戻る。外円区の消滅が加速する。百四十七人の数字がさらに増える。名前が名簿に載る。追悼祭の名簿が長くなる。"}, {"id": "ch15-s02-p119", "type": "text", "text": "鳴海さんを止めなければ、鳴海さんの体がさらに削られる。身体負荷指数47。不可逆。「数年以内に」の先。鳴海さんの瞳の色がもっと薄くなる。手の震えがもっと大きくなる。歌声がいつか出なくなる日が、近づく。"}, {"id": "ch15-s02-p120", "type": "text", "text": "どちらも選べなかった。"}, {"id": "ch15-s02-p121", "type": "text", "text": "どちらかを選ぶことが、もう一方を殺すことだった。天秤。氷華が言った天秤。弦月局長が傾けた天秤。五年前も今も、同じ構造の天秤。"}, {"id": "ch15-s02-p122", "type": "text", "text": "俺はその天秤の前に立っていた。答えが出ないまま。"}, {"id": "ch15-s02-p123", "type": "text", "text": "歌声が続いていた。"}, {"id": "ch15-s02-p124", "type": "text", "text": "鳴海さんの体から汗が滴り落ちていた。ブラウスの襟元が濡れている。首のチョーカーの金属が汗で光っている。膝が——膝が震え始めていた。立っているのがやっとだ。声は出ている。まだ出ている。声だけが最後の砦のように体を支えている。体が崩れかけても、声だけが立っている。"}, {"id": "ch15-s02-p125", "type": "text", "text": "風祭さんが床に両手をついていた。"}, {"id": "ch15-s02-p126", "type": "text", "text": "膝をつき、両手を床に置き、頭を下げている。泣いている。声を殺して。歌声の中で。"}, {"id": "ch15-s02-p127", "type": "text", "text": "俺は拳を握っていた。"}, {"id": "ch15-s02-p128", "type": "text", "text": "いつ握ったのかわからない。十一月の研究室で初めて握った拳。怒りで握った拳。今夜の拳には向ける先がなかった。怒りなら先がある。今夜は先がない。構造に向けた怒りも、天秤を傾ける側に向けた怒りも、今この瞬間には使えない。今この瞬間にあるのは——鳴海さんの歌声と、風祭さんの涙と、答えの出ない問いだけだった。"}, {"id": "ch15-s02-p129", "type": "text", "text": "拳の中に爪が食い込んでいた。"}, {"id": "ch15-s02-p130", "type": "text", "text": "痛みがある。掌の痛み。胸の奥の熱。二つの痛みが俺の中にある。外の痛みと中の痛み。どちらも俺のものだった。模倣ではなかった。"}, {"id": "ch15-s02-p131", "type": "text", "text": "鳴海さんの声が少しだけ揺れた。"}, {"id": "ch15-s02-p132", "type": "text", "text": "旋律の一音が、わずかに外れた。声量が落ちた。一秒。二秒。声が戻った。持ち直した。揺れを押し返して、声が再び力を取り戻した。しかし持ち直すために何を消費したのかが、鳴海さんの顔色の変化でわかった。白から、灰色に近い白へ。色がもう一段抜けた。"}, {"id": "ch15-s02-p133", "type": "text", "text": "燃やしている。"}, {"id": "ch15-s02-p134", "type": "text", "text": "命を燃やして声を維持している。"}, {"id": "ch15-s02-p135", "type": "text", "text": "計器の針が安定していた。残響波検出装置。基準値の四倍を維持。出力モニタ。八十二パーセント。安定している。数字は安定している。安定しているということは、鳴海さんが安定して命を燃やし続けているということだ。"}, {"id": "ch15-s02-p136", "type": "text", "text": "南の窓はここからは見えない。九階には窓がない。共鳴の間は球形の閉じた空間だ。外のことは数字でしか知れない。白い光がどこまで来ているのか。侵食速度が本当に鈍ったのか。何人が助かったのか。何人がまだ消えているのか。"}, {"id": "ch15-s02-p137", "type": "text", "text": "数字でしか知れない。"}, {"id": "ch15-s02-p138", "type": "text", "text": "そして鳴海さんの歌声の代償も、いつか数字になる。身体負荷指数が上がる。体重が減る。瞳の色が薄くなる。数字で記録される消耗。「数年以内に」の数字が、今夜、さらに縮まっている。"}, {"id": "ch15-s02-p139", "type": "text", "text": "歌声が続いていた。"}, {"id": "ch15-s02-p140", "type": "text", "text": "鳴海さんの声。命の炎。鐘鋳塔を震わせている。島を守っている。外円区の人たちを守っている。百四十七人の向こうにいる、まだ名簿に載っていない人たちを。"}, {"id": "ch15-s02-p141", "type": "text", "text": "俺はその歌を聴いていた。拳を握って。答えのないまま。"}, {"id": "ch15-s02-p142", "type": "text", "text": "歌声は止まらなかった。"}]}, {"chapter": 15, "chapterTitle": "縁蝕波", "scene": 3, "sceneTitle": "外円区の灯", "wordCount": "約5,100字", "paragraphs": [{"id": "ch15-s03-p001", "type": "text", "text": "共鳴の間を出たのは三時前だった。"}, {"id": "ch15-s03-p002", "type": "text", "text": "歌声は背中を追ってきた。九階から八階に降りる螺旋の石段を、壁面の残響金属が声を伝えた。七階まで聴こえた。六階で薄れた。五階で聞こえなくなった——嘘だ。耳には届かなくなった。しかし鳩尾の上がまだ灼けている。管を通って入り込んだ声の振動が消えていない。体の中で鳴海さんの歌が残響している。"}, {"id": "ch15-s03-p003", "type": "text", "text": "四階。三階。二階。一階。"}, {"id": "ch15-s03-p004", "type": "text", "text": "管理室のモニタは全て赤のまま。当直の鐘守が記録を続けていた。消滅面積、侵食速度。紙の数字の列が伸びている。鐘守の目が死んでいた。目が死んでいるのは恐怖ではなく疲労だった。深夜帯の当直が修羅場に変わって一時間。座り続けてペンを握り続けた人間の目だった。"}, {"id": "ch15-s03-p005", "type": "text", "text": "鐘守に声をかけた。"}, {"id": "ch15-s03-p006", "type": "text", "text": "「管理局の通信室に行く。こちらの記録は頼みます」"}, {"id": "ch15-s03-p007", "type": "text", "text": "鐘守がうなずいた。言葉はなかった。"}, {"id": "ch15-s03-p008", "type": "text", "text": "鐘鋳塔を出た。十二月の外気が肌を打った。三時の空。空があるはずの場所が白かった。南の地平線を覆っていた白い光が、一時間前より上に伸びていた。白光が夜雲の底を押し上げている。星が見えない。島の中心でこの白さということは——外円区では空そのものが光っているはずだった。"}, {"id": "ch15-s03-p009", "type": "text", "text": "石畳の道を走った。鐘鋳塔から南東へ。環の広場を横切り、白亜の管理局本庁舎の横を抜け、中円区に入る道を折れた。聖鐘学院のエリア。学院棟の東隣にある低い二階建て。管理局の出先——通信設備を置いた連絡室。深夜に灯りが点いている。"}, {"id": "ch15-s03-p010", "type": "text", "text": "扉を開けた。"}, {"id": "ch15-s03-p011", "type": "text", "text": "通信室は狭かった。机が四台。壁面に有線電話が三台と、残響通信の送受信機が一台。残響通信は鐘鋳塔の波を利用した島間通信用の設備だが、今は島内の長距離連絡に転用されている。外円区の監視哨との音声通話。"}, {"id": "ch15-s03-p012", "type": "text", "text": "人が二人いた。"}, {"id": "ch15-s03-p013", "type": "text", "text": "通信員が一人。管理局の夜勤職員。机に向かってヘッドセットを被り、メモを走らせている。"}, {"id": "ch15-s03-p014", "type": "text", "text": "もう一人。"}, {"id": "ch15-s03-p015", "type": "text", "text": "窓際に立っていた。長身。黒髪のセミロングを低い位置でまとめた女性。濃い緑のジャケット。黒のカーゴパンツ。腰の通信機。"}, {"id": "ch15-s03-p016", "type": "text", "text": "晶さん。"}, {"id": "ch15-s03-p017", "type": "text", "text": "背筋が伸びている。窓に向かって半身で立ち、右手にメモ帳を持っている。左手が通信機を耳に当てていた。こちらに気づいた。琥珀色の目が俺を捉えた。"}, {"id": "ch15-s03-p018", "type": "text", "text": "一秒。目が俺を確認した。確認して、すぐに視線が通信機に戻った。"}, {"id": "ch15-s03-p019", "type": "text", "text": "「南哨から二十分前に入った情報だ。外円区の避難ルートが三つ。うち一つは三時時点で蝕域に飲まれた」"}, {"id": "ch15-s03-p020", "type": "text", "text": "声が低い。晶さんの声はいつも低い。しかし今夜の声には通常の低さの下にもう一層の低さがあった。意図して出しているのではない。喉の奥が絞まっている。晶さんが感情を飲み込む時の声。"}, {"id": "ch15-s03-p021", "type": "text", "text": "俺は通信員の隣の机に着いた。メモ用紙が散らばっていた。各地点からの報告の断片。走り書きの数字と地名。灯里村。南農道。天蓋農場。東漁港。外円区の名前が紙の上に散っていた。"}, {"id": "ch15-s03-p022", "type": "text", "text": "「現在の避難状況を確認したい」"}, {"id": "ch15-s03-p023", "type": "text", "text": "通信員に言った。通信員がヘッドセットを外して俺を見た。顔に見覚えがあった。管理局本庁舎の一階の受付にいた職員。名前は——知らなかった。"}, {"id": "ch15-s03-p024", "type": "text", "text": "「外円区の避難民はおよそ三千人。中円区への避難ルートは残り二つ。北回りと東回り。北回りは蝕域の前進方向から外れているが、道が細い。荷車の渋滞が起きている。東回りは東漁港経由だが——」"}, {"id": "ch15-s03-p025", "type": "text", "text": "通信員の声が止まった。有線電話が鳴った。通信員がヘッドセットを被り直した。受話器を取った。"}, {"id": "ch15-s03-p026", "type": "text", "text": "「——はい。はい。承知した。人数は——」"}, {"id": "ch15-s03-p027", "type": "text", "text": "声がメモに変わった。ペンが紙を走る。数字。四十三。百六十。南農道。"}, {"id": "ch15-s03-p028", "type": "text", "text": "俺は散らばったメモを拾い、時系列に並べ始めた。断片的な情報を整理する。二時三十分の段階で灯里村付近の住民の半数以上が北回りルートに出ている。天蓋農場の作業員が東回りで避難中。南農道は——蝕域に近い。近すぎる。"}, {"id": "ch15-s03-p029", "type": "text", "text": "有線電話がもう一台鳴った。残響通信の送受信機もノイズを吐いていた。複数の音声が重なる。情報が束になって流れ込んでくる。"}, {"id": "ch15-s03-p030", "type": "text", "text": "その束の中に——声が一つ。"}, {"id": "ch15-s03-p031", "type": "text", "text": "残響通信の受信機。ノイズの合間に、声が混ざった。音声が小さい。遠い。距離と蝕域の干渉で信号が削られている。削られた残りの声。"}, {"id": "ch15-s03-p032", "type": "text", "text": "「——蓮くん」"}, {"id": "ch15-s03-p033", "type": "text", "text": "体が止まった。"}, {"id": "ch15-s03-p034", "type": "text", "text": "メモを整理していた手が止まった。呼吸が止まった。一拍。二拍。肋骨の内側が鳴った。"}, {"id": "ch15-s03-p035", "type": "text", "text": "燈花の声だった。"}, {"id": "ch15-s03-p036", "type": "text", "text": "通信員が受信機を操作した。周波数の微調整。ノイズが少し減った。声が浮かび上がった。"}, {"id": "ch15-s03-p037", "type": "text", "text": "「蓮くん。聞こえる？」"}, {"id": "ch15-s03-p038", "type": "text", "text": "聞こえる。肋骨の内側で聴いている。"}, {"id": "ch15-s03-p039", "type": "text", "text": "受信機の前に移動した。通信員がヘッドセットを外して俺に渡した。被った。左耳に燈花の声が近づいた。近づいたが、遠かった。声の周りにノイズが纏わりついている。バチバチという静電気のような音。その向こう側に、燈花がいる。"}, {"id": "ch15-s03-p040", "type": "text", "text": "「聞こえる。燈花、今どこにいる」"}, {"id": "ch15-s03-p041", "type": "text", "text": "「外円区。南農道の分岐点の——ちょっと北。ここ、避難の中継点にしてる。あたしと、監視哨の人が二人と、農家の人が十人くらい」"}, {"id": "ch15-s03-p042", "type": "text", "text": "声が——"}, {"id": "ch15-s03-p043", "type": "text", "text": "低かった。昨日の外円区で聴いた声と同じ低さ。食堂の「蓮くーん」とは別の周波数。静かで、風に溶けそうで、けれど途切れない声。"}, {"id": "ch15-s03-p044", "type": "text", "text": "背後で音がした。受信機越しの音。低い、くぐもった衝撃音。何かが崩れる音。木材か石材か。構造物が倒壊する音に似ていた。遠いが、燈花の位置から近い。"}, {"id": "ch15-s03-p045", "type": "text", "text": "燈花の声に震えが混ざった。"}, {"id": "ch15-s03-p046", "type": "text", "text": "一瞬だけ。"}, {"id": "ch15-s03-p047", "type": "text", "text": "「こっちは大丈夫。避難民をまとめてる。あたしは……ここにいなきゃ」"}, {"id": "ch15-s03-p048", "type": "text", "text": "声が戻った。震えが消えた。消したのだ。燈花が自分の声から震えを引き剥がした。"}, {"id": "ch15-s03-p049", "type": "text", "text": "「灯里村の……最後の人たちが、まだ避難してない。おじいちゃんとおばあちゃんが三人。足が悪くて。あたしが迎えに行く」"}, {"id": "ch15-s03-p050", "type": "text", "text": "肋骨の内側が石になった。"}, {"id": "ch15-s03-p051", "type": "text", "text": "十四章で感じた硬い重さよりもっと冷たい。石が冷えている。胸の中に氷の石がある。"}, {"id": "ch15-s03-p052", "type": "text", "text": "「燈花、危険だ。灯里村は蝕域に近すぎる。避難ルートが——」"}, {"id": "ch15-s03-p053", "type": "text", "text": "「うん。知ってる」"}, {"id": "ch15-s03-p054", "type": "text", "text": "知っていた。燈花は知っていた。避難ルートが一つ消えたことを。残りの二つも時間の問題であることを。灯里村の周辺が蝕域の前進経路の直上にあることを。"}, {"id": "ch15-s03-p055", "type": "text", "text": "知っていて、行くと言っている。"}, {"id": "ch15-s03-p056", "type": "text", "text": "「……うん。でも、あたしの故郷の人だから」"}, {"id": "ch15-s03-p057", "type": "text", "text": "声が小さかった。小さいが、芯があった。昨日の外円区で老婆の荷物を担いでいた時と同じ種類の芯。泣く代わりに動く人間の芯。"}, {"id": "ch15-s03-p058", "type": "text", "text": "「燈花」"}, {"id": "ch15-s03-p059", "type": "text", "text": "名前を呼んだ。八月から呼べるようになった二文字が、受信機のマイクに吸い込まれた。電気信号に変わり、残響通信の波に乗り、蝕域の干渉をくぐり抜けて、外円区のどこかにいる燈花の耳に届く。届くはずだった。"}, {"id": "ch15-s03-p060", "type": "text", "text": "ノイズが増えた。"}, {"id": "ch15-s03-p061", "type": "text", "text": "バチバチという音が大きくなった。受信機の表示が揺れている。残響通信の信号強度が下がっている。蝕域の膨張が通信波に干渉している。"}, {"id": "ch15-s03-p062", "type": "text", "text": "「蓮くん——」"}, {"id": "ch15-s03-p063", "type": "text", "text": "声が遠くなった。"}, {"id": "ch15-s03-p064", "type": "text", "text": "「——あたしは大丈夫だから。あたし、走るの速いから。知ってるでしょ」"}, {"id": "ch15-s03-p065", "type": "text", "text": "知っている。体育祭で見た。農作業で鍛えた体。綺麗なフォーム。大股で、前を向いて、走る姿。"}, {"id": "ch15-s03-p066", "type": "text", "text": "「灯篭流しの——あの時みたいに——走って——」"}, {"id": "ch15-s03-p067", "type": "text", "text": "通信が途切れ始めた。言葉が欠落していく。単語の間に空白が挿入される。燈花の声がノイズに食われていく。"}, {"id": "ch15-s03-p068", "type": "text", "text": "「蓮くん」"}, {"id": "ch15-s03-p069", "type": "text", "text": "名前だけがはっきり聞こえた。"}, {"id": "ch15-s03-p070", "type": "text", "text": "「——待ってて」"}, {"id": "ch15-s03-p071", "type": "text", "text": "通信が切れた。"}, {"id": "ch15-s03-p072", "type": "text", "text": "ノイズが消えた。受信機が沈黙した。俺は ヘッドセットを被ったまま、音のない回路に耳を押しつけていた。何も聞こえなかった。燈花の声がない。崩壊音がない。風の音がない。何もない。"}, {"id": "ch15-s03-p073", "type": "text", "text": "ヘッドセットを外した。"}, {"id": "ch15-s03-p074", "type": "text", "text": "手が——右手が震えていた。受信機の操作パネルの上に置いた手が細かく振動していた。"}, {"id": "ch15-s03-p075", "type": "text", "text": "晶さんが俺の横にいた。いつからいたのかわからなかった。窓際から移動してきていた。通信を聴いていたのだ。"}, {"id": "ch15-s03-p076", "type": "text", "text": "「外円区の避難路が一つ蝕域に飲まれた」"}, {"id": "ch15-s03-p077", "type": "text", "text": "晶さんの声が来た。平坦だった。状況報告の声。しかし声の温度が、窓際にいた時とわずかに変わっていた。0.5度。それ以下かもしれない。"}, {"id": "ch15-s03-p078", "type": "text", "text": "「残り二ルートも時間の問題だ。北回りの渋滞が解消しない限り、南農道方面の住民は——」"}, {"id": "ch15-s03-p079", "type": "text", "text": "晶さんの声が止まった。"}, {"id": "ch15-s03-p080", "type": "text", "text": "俺の手を見たからだ。震えている手を。"}, {"id": "ch15-s03-p081", "type": "text", "text": "晶さんは何も言わなかった。手の震えを指摘しなかった。代わりに、メモ帳のページを一枚破り、俺の前に置いた。外円区の避難路の略図が描かれていた。三本の線。うち一本にバツ印。残り二本に時刻の書き込み。"}, {"id": "ch15-s03-p082", "type": "text", "text": "「この二つのルートが生きている間に、南農道方面の住民が通過できるかどうかだ」"}, {"id": "ch15-s03-p083", "type": "text", "text": "晶さんの声は業務の声に戻っていた。状況を整理している。冷静に。正確に。しかし——"}, {"id": "ch15-s03-p084", "type": "text", "text": "晶さんの琥珀色の目が、一瞬だけ俺の顔に留まった。"}, {"id": "ch15-s03-p085", "type": "text", "text": "俺の目を見たのではなかった。俺の顔の表情を見ていた。どういう顔をしているのか、自分ではわからなかった。わかっていたのは、肋骨の内側が冷たいこと、右手が震えていること、燈花の声が耳の中にまだ残っていること、走って助けに行きたいのに足がこの通信室の床に貼りついていること。"}, {"id": "ch15-s03-p086", "type": "text", "text": "走れなかった。"}, {"id": "ch15-s03-p087", "type": "text", "text": "走って外円区に向かうことはできた。体力はある。道も知っている。しかし通信室を離れれば、外円区からの情報が途切れる。通信員は一人で三系統を捌ききれない。俺がここにいることで整理できる情報がある。その情報が避難ルートの判断に使われる。使われて、誰かが助かるかもしれない。"}, {"id": "ch15-s03-p088", "type": "text", "text": "俺が走れば——一人の燈花を助けに行ける。"}, {"id": "ch15-s03-p089", "type": "text", "text": "俺がここにいれば——情報が整理され、避難が少しでもうまく回る。"}, {"id": "ch15-s03-p090", "type": "text", "text": "一人と、全体。"}, {"id": "ch15-s03-p091", "type": "text", "text": "鳴海さんの歌声を聴きながら答えが出なかった問いと、同じ形をしていた。別の場所で、別の人について、同じ構造の問いが繰り返された。"}, {"id": "ch15-s03-p092", "type": "text", "text": "窓を見た。"}, {"id": "ch15-s03-p093", "type": "text", "text": "通信室の窓は南向きだった。硝子越しに、夜の外が見えた。"}, {"id": "ch15-s03-p094", "type": "text", "text": "南の空が白い。蝕域の光が地平線から立ち上がっている。三時間前に鐘鋳塔の管理室から見た白い光よりも高い位置まで来ている。白光が島の南半分を覆いかけている。"}, {"id": "ch15-s03-p095", "type": "text", "text": "その白い光の手前に——"}, {"id": "ch15-s03-p096", "type": "text", "text": "灯りが見えた。"}, {"id": "ch15-s03-p097", "type": "text", "text": "小さかった。白い蝕域の光とは違う色。橙色。黄色。蝋燭か、油灯か。外円区の住民が持って歩く灯り。避難する人々が持つ灯り。"}, {"id": "ch15-s03-p098", "type": "text", "text": "点々と。"}, {"id": "ch15-s03-p099", "type": "text", "text": "白い光の縁に沿って、外円区の闇の中に小さな灯りが散らばっていた。一つ、二つ、三つ——数え切れなかった。農道を北に向かう灯りの列。東に向かう灯りの群れ。動いていた。ゆっくりと。白い光に追われながら、小さな灯りが動いていた。"}, {"id": "ch15-s03-p100", "type": "text", "text": "蝕域の白い光は巨大だった。地平線から空まで。世界を塗り潰す白。"}, {"id": "ch15-s03-p101", "type": "text", "text": "灯りは小さかった。手のひらに収まるような光。蝋燭一本分の、弱い光。"}, {"id": "ch15-s03-p102", "type": "text", "text": "その弱い光の一つが、他の灯りとは逆方向に動いていた。"}, {"id": "ch15-s03-p103", "type": "text", "text": "南に。"}, {"id": "ch15-s03-p104", "type": "text", "text": "灯りの列から外れて、白い光に向かって、一つの灯りが南に動いている。"}, {"id": "ch15-s03-p105", "type": "text", "text": "燈花だと思った。根拠はなかった。距離がありすぎる。この窓から外円区の個人を識別できるはずがない。けれど肋骨の内側にある冷たい石が、あの灯りは燈花だと報告していた。"}, {"id": "ch15-s03-p106", "type": "text", "text": "故郷の人を迎えに行く灯り。白に向かって走る灯り。"}, {"id": "ch15-s03-p107", "type": "text", "text": "俺は窓枠に手を置いた。冷たい石の枠。一時間前に鐘鋳塔の管理室で掴んだ窓枠と同じ冷たさ。あの時は蝕域に引かれる体を止めるために掴んだ。今は——別のものを止めるために掴んでいた。走り出そうとする足を。"}, {"id": "ch15-s03-p108", "type": "text", "text": "「蓮」"}, {"id": "ch15-s03-p109", "type": "text", "text": "晶さんの声。"}, {"id": "ch15-s03-p110", "type": "text", "text": "低い。名前を呼ぶ時の声。「深入りするな」の時と同じ音程。しかし言葉は続かなかった。呼んだだけだった。俺がここにいることを確認する声。"}, {"id": "ch15-s03-p111", "type": "text", "text": "振り返った。"}, {"id": "ch15-s03-p112", "type": "text", "text": "晶さんが立っていた。メモ帳を持って。通信機を腰に下げて。長身の背筋が伸びたまま。琥珀色の目が、俺を見ていた。"}, {"id": "ch15-s03-p113", "type": "text", "text": "目の奥に——何かがあった。言葉にはなっていなかった。晶さんは何も言わなかった。「行くな」とも「行け」とも。ただ俺の顔を見て、俺が今何を感じているのかを、見ていた。"}, {"id": "ch15-s03-p114", "type": "text", "text": "知っている。"}, {"id": "ch15-s03-p115", "type": "text", "text": "この人は知っている。走り出せない場所にいることの苦しさを。縁際の隊長として、部下を前線に送り、自分は後方にいなければならない夜を何度も過ごした人だ。"}, {"id": "ch15-s03-p116", "type": "text", "text": "窓に背を向けた。"}, {"id": "ch15-s03-p117", "type": "text", "text": "机に戻った。メモを拾った。ペンを持った。右手はまだ震えていた。震える手でペンを握った。外円区からの情報を整理する。時系列に。地点ごとに。避難人数。ルートの状態。蝕域の前進位置。"}, {"id": "ch15-s03-p118", "type": "text", "text": "書いた。"}, {"id": "ch15-s03-p119", "type": "text", "text": "震える字で。崩れかけた数字で。それでも書いた。"}, {"id": "ch15-s03-p120", "type": "text", "text": "肋骨の内側は冷たかった。燈花の声が耳に残っていた。「待ってて」。待っている。ここで。通信室の机の前で。ペンを握って。数字を書いて。"}, {"id": "ch15-s03-p121", "type": "text", "text": "窓の向こうで、小さな灯りが白い光に向かって進んでいる。"}]}, {"chapter": 15, "chapterTitle": "縁蝕波", "scene": 4, "sceneTitle": "透ける手", "wordCount": "約5,200字", "paragraphs": [{"id": "ch15-s04-p001", "type": "text", "text": "通信室を出たのは五時過ぎだった。"}, {"id": "ch15-s04-p002", "type": "text", "text": "二時間。机に向かい続けた。外円区からの情報が途切れては繋がり、途切れては繋がった。有線電話の回線は三系統のうち一つが死に、残りの二系統で全域の情報を拾った。残響通信は四時過ぎに一度完全に沈黙した。蝕域の膨張が通信波を塞いだのだ。二十分後に復旧した。復旧の理由は——鐘鋳塔の方角から、かすかに震動が届いたことだった。鐘の音ではない。鐘の音よりも柔らかく、鐘の音よりも長い。千歳の歌声が鐘の合力と混ざって、蝕域を押し返している。"}, {"id": "ch15-s04-p003", "type": "text", "text": "押し返した。"}, {"id": "ch15-s04-p004", "type": "text", "text": "四時四十分。通信員が受信機の表示を指差した。外円区の南端で蝕域の前進速度がゼロになった。ゼロではない。マイナスに転じた。後退。わずか二十メートル。しかし開戦以来初めて、白い光が縮んだ。"}, {"id": "ch15-s04-p005", "type": "text", "text": "五時。北東の観測点も侵食速度がゼロに接近した。西沿岸域はまだ微速前進を続けているが、勢いは明らかに落ちている。"}, {"id": "ch15-s04-p006", "type": "text", "text": "晶さんが俺の横に来た。散らばったメモを読んでいた。琥珀色の目が数字を追い、唇が動いた。声にはしなかった。数字を読む晶さんの顔に、表情は浮かんでいなかった。浮かんでいないことが、晶さんの安堵だった。危険が続いている時、晶さんの顔は動かない。安堵が来た時だけ、表情がなくなる。力が抜けるのだ。"}, {"id": "ch15-s04-p007", "type": "text", "text": "「北回りルートの渋滞が解消し始めた。荷車が動いている」"}, {"id": "ch15-s04-p008", "type": "text", "text": "晶さんが言った。メモを机に置いた。"}, {"id": "ch15-s04-p009", "type": "text", "text": "通信室の窓を見た。南の空が——変わっていた。白い光がまだ地平線に残っていたが、二時間前の圧迫感はなかった。空の上端に星が二つ見えた。星が見えるということは、白光が押し下げられたということだった。"}, {"id": "ch15-s04-p010", "type": "text", "text": "白い光の手前の闇に、小さな灯りはもう見えなかった。避難が進んだのか。灯りを消したのか。南に向かっていた一つの灯りが——燈花の灯りが、今どこにあるのかわからなかった。"}, {"id": "ch15-s04-p011", "type": "text", "text": "肋骨の内側はまだ冷たかった。氷の石が溶けていない。「待ってて」が耳に残っている。"}, {"id": "ch15-s04-p012", "type": "text", "text": "しかし、通信室で俺にできることは減っていた。蝕域の前進が止まり始め、新しい情報の流入が鈍った。通信員が二系統を一人で捌ける状態に戻っていた。"}, {"id": "ch15-s04-p013", "type": "text", "text": "立ち上がった。"}, {"id": "ch15-s04-p014", "type": "text", "text": "「外の空気を吸ってきます」"}, {"id": "ch15-s04-p015", "type": "text", "text": "晶さんに言った。晶さんがうなずいた。視線は俺の顔に一瞬留まり、俺がどういう顔をしているのかを確認して、離れた。"}, {"id": "ch15-s04-p016", "type": "text", "text": "通信室の扉を開けた。十二月の明け方の空気が顔に当たった。冷たさの質が違った。深夜の冷気は肌を刺す。明け方の冷気は頬を包む。湿っている。夜露が降りている。"}, {"id": "ch15-s04-p017", "type": "text", "text": "中庭に出た。"}, {"id": "ch15-s04-p018", "type": "text", "text": "聖鐘学院の中庭は長方形で、東西に細長い。南側に教室棟、北側に図書館。東端に渡り廊下。西端に校門への石段。中央に枯れた噴水がある。十二月の噴水は水が止められていて、石の台座に薄い霜が降りていた。"}, {"id": "ch15-s04-p019", "type": "text", "text": "空が明るんでいた。東の端。水色に近い灰色。明け方の空。空の色はまだ完全に戻っていなかった。南の地平線付近に白い靄が残っている。蝕域の残光。しかし上空は、二時間前よりずっと暗い。正常な暗さ。星が見える暗さ。"}, {"id": "ch15-s04-p020", "type": "text", "text": "中庭の石畳が霜で白い。足を踏むとかすかに滑る。俺の足音だけが中庭に落ちる。静かだった。嵐の後の静かさ。蝕域が押し返され、島が一瞬だけ呼吸を取り戻した時間。"}, {"id": "ch15-s04-p021", "type": "text", "text": "図書館が見えた。中庭の北側。石造りの二階建て。重い木の扉。扉の上にアーチ型の窓。窓に灯りはなかった。"}, {"id": "ch15-s04-p022", "type": "text", "text": "扉の前に、人影があった。"}, {"id": "ch15-s04-p023", "type": "text", "text": "小柄だった。紺のコート。黒髪のボブカット。背筋は正しいが少し前かがみ。"}, {"id": "ch15-s04-p024", "type": "text", "text": "篠宮さん。"}, {"id": "ch15-s04-p025", "type": "text", "text": "右手にペンを持っていた。左手にメモ帳。立ったまま、メモ帳に何かを書いていた。五時半の明け方の中庭で。図書館の扉の前で。霜の降りた石畳の上で。"}, {"id": "ch15-s04-p026", "type": "text", "text": "ペンが動いていた。かりかりという音は——聞こえない。距離がある。十五歩。しかし耳の位置にあるものが反応した。音が聞こえない距離で、篠宮さんのペンの存在だけを耳が拾った。"}, {"id": "ch15-s04-p027", "type": "text", "text": "足を進めた。"}, {"id": "ch15-s04-p028", "type": "text", "text": "十歩。篠宮さんの輪郭が明け方の光の中で少しずつはっきりしていく。紺のコートの裾。膝丈のスカート。紺のハイソックス。首から下げた図書館の銀色の鍵が、コートの上から微かに光っていた。"}, {"id": "ch15-s04-p029", "type": "text", "text": "何をしている。"}, {"id": "ch15-s04-p030", "type": "text", "text": "この時間に。蝕域が辛うじて押し返されたばかりの明け方に。大半の住民がまだ避難所にいるはずの時間に。篠宮さんは、記録を取りに来ている。"}, {"id": "ch15-s04-p031", "type": "text", "text": "当然だと思った。篠宮さんだから。消滅した区域の記録。新しく消えた場所の面積、位置、推定消滅者数。夜のうちに蝕域が飲んだものの一覧を、朝一番で記録しに来た。メモ帳で二十三冊分。三千六百八十人。それに今夜の消滅者が加わる。"}, {"id": "ch15-s04-p032", "type": "text", "text": "七歩。五歩。"}, {"id": "ch15-s04-p033", "type": "text", "text": "「篠宮さん」"}, {"id": "ch15-s04-p034", "type": "text", "text": "声をかけた。"}, {"id": "ch15-s04-p035", "type": "text", "text": "篠宮さんのペンが止まった。顔が上がった。"}, {"id": "ch15-s04-p036", "type": "text", "text": "墨色の瞳が俺を見た。焦点が合うまでに——間があった。十二月中旬、外円区の帰り道で見たのと同じ、一拍のぼんやり。メモ帳でも石畳でも空でもない場所を見ていた目が、俺に戻ってくるまでの空白。"}, {"id": "ch15-s04-p037", "type": "text", "text": "「……朝霧さん」"}, {"id": "ch15-s04-p038", "type": "text", "text": "声が薄かった。音量は聞こえる程度にある。しかし声の輪郭が滲んでいた。十四章よりもさらに薄い。壁に届かない声量。壁に届く前に空気に溶けてしまう声。"}, {"id": "ch15-s04-p039", "type": "text", "text": "「今は危険だ。中に入ったほうがいい」"}, {"id": "ch15-s04-p040", "type": "text", "text": "言った。篠宮さんが危ない場所にいるという判断ではなく、明け方の冷気と疲労が心配だった。蝕域は押し返されたが、まだ残光が南に残っている。外にいるべき時間帯ではない。"}, {"id": "ch15-s04-p041", "type": "text", "text": "「記録を取らないといけません。今夜の消滅域の記録を、朝のうちに」"}, {"id": "ch15-s04-p042", "type": "text", "text": "篠宮さんの返答。短い。しかし十四章の「はい」だけの返答よりは情報が多かった。理由がついている。記録を取る。朝のうちに。篠宮さんの中で目的が立っている。"}, {"id": "ch15-s04-p043", "type": "text", "text": "篠宮さんが振り返った。"}, {"id": "ch15-s04-p044", "type": "text", "text": "俺の方に体を向けた。メモ帳を持った左手。ペンを持った右手。紺のコートの前が開いて、中の制服が見えた。灰色のエプロンはつけていなかった。出がけに省略したのか、図書館がまだ閉まっているから不要なのか。"}, {"id": "ch15-s04-p045", "type": "text", "text": "そのとき——"}, {"id": "ch15-s04-p046", "type": "text", "text": "右手が。"}, {"id": "ch15-s04-p047", "type": "text", "text": "篠宮さんの右手が。"}, {"id": "ch15-s04-p048", "type": "text", "text": "ペンを持った指先の——向こう側が見えた。"}, {"id": "ch15-s04-p049", "type": "text", "text": "一瞬ではなかった。"}, {"id": "ch15-s04-p050", "type": "text", "text": "二秒。三秒。それ以上かもしれない。"}, {"id": "ch15-s04-p051", "type": "text", "text": "篠宮さんの右手の中指と薬指と小指。三本の指先が、明け方の空気の中で、溶けていた。透けていた。指の向こう側にある図書館の扉の木目が、指を通して見えていた。完全な透明ではなかった。磨りガラス越しのように像が歪んでいた。しかし見えた。指先から第一関節まで。指の輪郭が薄くなり、色が抜け、向こうの景色が透過していた。"}, {"id": "ch15-s04-p052", "type": "text", "text": "光の加減ではなかった。"}, {"id": "ch15-s04-p053", "type": "text", "text": "十一月の帰り道、篠宮さんの輪郭が揺らいだ時。あの時は「光の加減」「目の疲れ」と処理した。十二月中旬の外円区では「光の加減ではなかった」と修正しかけて、踏み込めなかった。"}, {"id": "ch15-s04-p054", "type": "text", "text": "今は——処理できなかった。"}, {"id": "ch15-s04-p055", "type": "text", "text": "見えている。右目でも左目でも見えている。篠宮さんの指先が透けている。ペンを持っている指の、ペンに触れていない三本が、向こう側を透かしている。"}, {"id": "ch15-s04-p056", "type": "text", "text": "呼吸を忘れていた。体が止まっていた。五歩の距離で、俺は篠宮さんの手を見ていた。"}, {"id": "ch15-s04-p057", "type": "text", "text": "蝕域の白い光の残光が南の空にある。その光と関係があるのか。消滅した場所で、篠宮さんの体が一瞬揺らいだのは十一月だった。蝕域が活発化した十二月に、手の震えとぼんやりが増えた。今夜、蝕域が最大出力を叩き出した直後——篠宮さんの指先が、透けている。"}, {"id": "ch15-s04-p058", "type": "text", "text": "瞬きをした。"}, {"id": "ch15-s04-p059", "type": "text", "text": "一回。"}, {"id": "ch15-s04-p060", "type": "text", "text": "透けていた。まだ見えていた。"}, {"id": "ch15-s04-p061", "type": "text", "text": "二回。"}, {"id": "ch15-s04-p062", "type": "text", "text": "——消えた。"}, {"id": "ch15-s04-p063", "type": "text", "text": "篠宮さんの右手が、ペンを持った右手が、普通の手に戻っていた。肌の色がある。指の輪郭がある。向こう側は見えない。何事もなかったかのように、五本の指がペンを握っている。"}, {"id": "ch15-s04-p064", "type": "text", "text": "目を疑った。"}, {"id": "ch15-s04-p065", "type": "text", "text": "しかし十一月とは違った。あの時は目を疑い、そのまま疑いを保留した。光の加減として処理した。今は処理できない。見えた時間が長すぎた。一瞬ではなかった。二秒か三秒か。指先の向こうの図書館の扉の木目を、はっきりと認識した。錯覚は——こんなに長く続かない。"}, {"id": "ch15-s04-p066", "type": "text", "text": "「篠宮さん」"}, {"id": "ch15-s04-p067", "type": "text", "text": "声が出た。声が乾いていた。"}, {"id": "ch15-s04-p068", "type": "text", "text": "「今……手が……」"}, {"id": "ch15-s04-p069", "type": "text", "text": "篠宮さんが自分の右手を見た。"}, {"id": "ch15-s04-p070", "type": "text", "text": "ペンを持った手。指先。中指。薬指。小指。"}, {"id": "ch15-s04-p071", "type": "text", "text": "「……何もありませんが」"}, {"id": "ch15-s04-p072", "type": "text", "text": "篠宮さんの声が返った。声は——平坦だった。いつもの篠宮さんの声に近かった。しかし、微かに硬いものが混じっていた。「大丈夫です。記録を続けないと」と言った十四章の声と、同じ種類の硬さ。"}, {"id": "ch15-s04-p073", "type": "text", "text": "篠宮さんの墨色の瞳が俺を見ていた。瞳の奥に——何があるのかわからなかった。気づいていないのか。気づいていて隠しているのか。「何もありません」という言葉が、事実の報告なのか、事実の拒絶なのか。"}, {"id": "ch15-s04-p074", "type": "text", "text": "「疲れのせいではないですか。朝霧さんも、一晩中お仕事をされていたでしょう」"}, {"id": "ch15-s04-p075", "type": "text", "text": "篠宮さんが言った。言葉の選び方は自然だった。篠宮さんらしい言い方。相手の体調を気遣う形式で。しかし——"}, {"id": "ch15-s04-p076", "type": "text", "text": "俺の目を見ていなかった。"}, {"id": "ch15-s04-p077", "type": "text", "text": "声はこちらに向いていた。体もこちらに向いていた。しかし視線がわずかにずれていた。俺の左肩のあたりを見ていた。目を合わせることを——避けている。"}, {"id": "ch15-s04-p078", "type": "text", "text": "避けているのか、それとも焦点が合わないのか。十四章で見た「ぼんやり」と同じものが、篠宮さんの視線のずれの中にあった。"}, {"id": "ch15-s04-p079", "type": "text", "text": "「……そうかもしれない」"}, {"id": "ch15-s04-p080", "type": "text", "text": "言った。引き下がった。"}, {"id": "ch15-s04-p081", "type": "text", "text": "引き下がったのは、篠宮さんの硬い声が境界線を引いていたからだ。十四章と同じだった。「記録を続けないと」という意志が、篠宮さんの声の芯を支えている。その芯に俺が触れると、篠宮さんは硬くなる。硬くなることで自分を保っている。"}, {"id": "ch15-s04-p082", "type": "text", "text": "しかし——"}, {"id": "ch15-s04-p083", "type": "text", "text": "引き下がりながら、篠宮さんの手を見ていた。"}, {"id": "ch15-s04-p084", "type": "text", "text": "右手。ペンを握った右手。五本の指。今は普通の手だった。肌の色。爪の形。ペンを握る力。四月の終わり、初めて清書を手伝った時に見た、あの小さく正確な手。二十三冊分の記録を書き続けてきた手。三千六百八十人の名前を刻んだ手。"}, {"id": "ch15-s04-p085", "type": "text", "text": "あの手が——透けた。光に溶けるように。存在の濃さが下がるように。"}, {"id": "ch15-s04-p086", "type": "text", "text": "十一月。輪郭の揺らぎ。光の加減だと思った。"}, {"id": "ch15-s04-p087", "type": "text", "text": "十二月。手の震え。ぼんやり。声の薄さ。光の加減ではなかった、と修正しかけた。"}, {"id": "ch15-s04-p088", "type": "text", "text": "今。指先が透けた。向こう側が見えた。二秒以上。"}, {"id": "ch15-s04-p089", "type": "text", "text": "三度。三度の観測。耳の位置にあるものが鳴っていた。引っかかりではなかった。もっとはっきりした音。何かが——引っかかりの段階を超えて、耳の奥で叫んでいた。"}, {"id": "ch15-s04-p090", "type": "text", "text": "「篠宮さん」"}, {"id": "ch15-s04-p091", "type": "text", "text": "もう一度呼んだ。別のことを聞くつもりだった。別のことを、聞けなかった。"}, {"id": "ch15-s04-p092", "type": "text", "text": "「記録の手伝い……何か、できることはありますか」"}, {"id": "ch15-s04-p093", "type": "text", "text": "篠宮さんが小さくうなずいた。"}, {"id": "ch15-s04-p094", "type": "text", "text": "「……今夜の消滅域の情報をお持ちでしたら。面積と、地点名を」"}, {"id": "ch15-s04-p095", "type": "text", "text": "「通信室のメモに書き溜めた分がある。持ってくる」"}, {"id": "ch15-s04-p096", "type": "text", "text": "篠宮さんがわずかにうなずいた。二度目のうなずき。このうなずきは——一度目よりも柔らかかった。記録に協力してくれる人間に対する、篠宮さんの反応。"}, {"id": "ch15-s04-p097", "type": "text", "text": "俺は通信室に戻るために、中庭を横切り始めた。"}, {"id": "ch15-s04-p098", "type": "text", "text": "五歩。十歩。噴水の台座を過ぎた。"}, {"id": "ch15-s04-p099", "type": "text", "text": "振り返った。"}, {"id": "ch15-s04-p100", "type": "text", "text": "篠宮さんは図書館の扉の前に立っていた。メモ帳を開いて。ペンを持って。明け方の薄い光の中で、紺のコートの輪郭は——はっきりしていた。今は。"}, {"id": "ch15-s04-p101", "type": "text", "text": "今は、はっきりしている。"}, {"id": "ch15-s04-p102", "type": "text", "text": "耳の中で音が鳴り続けていた。引っかかりよりも大きく、叫びよりも低い音。篠宮さんの手を見た記憶が目の奥に焼きついていた。指先の向こうの木目。第一関節まで薄くなった輪郭。光に溶けかける色。"}, {"id": "ch15-s04-p103", "type": "text", "text": "「何かがおかしい」と思い続けた数ヶ月間が、終わっていた。"}, {"id": "ch15-s04-p104", "type": "text", "text": "「何かが起きている」。"}, {"id": "ch15-s04-p105", "type": "text", "text": "確信に変わっていた。何が起きているかはわからない。篠宮さんの手が透けた理由も。蝕域との関係も。篠宮さんが気づいているのかどうかも。何もわかっていない。わかっていないが——起きている。篠宮さんの体に、何かが起きている。"}, {"id": "ch15-s04-p106", "type": "text", "text": "通信室に向かって歩きながら、足元の霜が砕ける音を聴いていた。かすかな音。砕ける。崩れる。溶ける。氷の結晶が朝の空気に触れて消えていく。"}, {"id": "ch15-s04-p107", "type": "text", "text": "篠宮さんの指先も、あの霜のように消えかけた。"}, {"id": "ch15-s04-p108", "type": "text", "text": "肋骨の内側の氷の石が、まだ冷たい。燈花の「待ってて」が残っている。耳の位置には篠宮さんの手が焼きついている。鳩尾の奥には沈殿物が堆積している。体の中に、処理の終わっていないものが三つ重なっていた。"}, {"id": "ch15-s04-p109", "type": "text", "text": "東の空が白んでいた。水色と灰色の境目に、最初の朝の光が滲み始めている。"}, {"id": "ch15-s04-p110", "type": "text", "text": "十二月の明け方。縁蝕波を辛うじて押し返した島。嵐の後の静けさの中で、俺の体だけが静かではなかった。"}]}, {"chapter": 15, "chapterTitle": "縁蝕波", "scene": 5, "sceneTitle": "氷華の反逆、すみれの告知", "wordCount": "約5,300字", "paragraphs": [{"id": "ch15-s05-p001", "type": "text", "text": "通信室のメモを取りに戻った後、篠宮さんに渡した。"}, {"id": "ch15-s05-p002", "type": "text", "text": "消滅域の面積。地点名。走り書きの数字が並んだメモ用紙を、篠宮さんは静かに受け取った。墨色の瞳は俺の顔を見なかった。メモ帳を開いて、ペンを持って、受け取った数字の転記を始めた。ペンの先端が紙を擦る音だけが、明け方の中庭に落ちた。"}, {"id": "ch15-s05-p003", "type": "text", "text": "六時前。東の空が灰色から薄い藍色に変わっていた。"}, {"id": "ch15-s05-p004", "type": "text", "text": "俺は通信室に戻った。通信員に引き継ぎの確認をし、当直室の寝台に横になった。横になったのは六時十五分で、目を閉じたが眠れなかった。目の奥に、指先の向こうの木目がまだ焼きついていた。"}, {"id": "ch15-s05-p005", "type": "text", "text": "浅い仮眠だった。体が落ちて、浮いて、また落ちた。意識がつく度に天井の石のひび割れが見えた。三度目に落ちた時、夢を見た。何の夢かは覚えていない。手が冷たかった。目が覚めた時に、左手の甲がわずかに痺れていた。すみれの場所。"}, {"id": "ch15-s05-p006", "type": "text", "text": "七時半に体を起こした。洗面所で顔を洗った。冷たい水が目の奥の焼きつきを薄めたが、消さなかった。内ポケットの布片に指先が触れた。在ることを確認した。"}, {"id": "ch15-s05-p007", "type": "text", "text": "階段を上った。"}, {"id": "ch15-s05-p008", "type": "break", "text": "◇"}, {"id": "ch15-s05-p009", "type": "text", "text": "三階の研究区画に着いたのは八時前だった。"}, {"id": "ch15-s05-p010", "type": "text", "text": "鐘鋳塔の内側は昨夜の縁蝕波の痕跡を引きずっていた。壁面の残響灯が二つに一つ消えている。消えているのではなく、光が足りない。残響紋の出力が戻りきっていない。石の壁が青白い光と影を交互に落として、通路の奥が暗い。"}, {"id": "ch15-s05-p011", "type": "text", "text": "霜月さんの研究室の鉄扉の下に、光が漏れていた。"}, {"id": "ch15-s05-p012", "type": "text", "text": "いる。"}, {"id": "ch15-s05-p013", "type": "text", "text": "この人は寝ていない。縁蝕波の発生が一時過ぎ。機構室に駆け上がり、鐘の出力を制御し、俺と別れたのが三階への階段の前だった。あれから五時間。五時間のうちに、三階の研究室に戻り、データを分析し、上層部への報告書を書き、そしてまだこの部屋にいる。"}, {"id": "ch15-s05-p014", "type": "text", "text": "鉄扉を三回叩いた。拳で。間隔を空けて。"}, {"id": "ch15-s05-p015", "type": "text", "text": "返事がなかった。"}, {"id": "ch15-s05-p016", "type": "text", "text": "二秒待った。三回目を叩こうとした時、中から音がした。紙が裂ける音。一度ではなかった。二度。三度。紙が、引き千切られている。"}, {"id": "ch15-s05-p017", "type": "text", "text": "「霜月さん」"}, {"id": "ch15-s05-p018", "type": "text", "text": "扉を開けた。"}, {"id": "ch15-s05-p019", "type": "text", "text": "研究室の中は残響灯とモニタの光で満ちていた。いつもの机。いつもの計器。いつもの紅茶のカップ——湯気がない。冷めている。飲みかけ。"}, {"id": "ch15-s05-p020", "type": "text", "text": "霜月さんが机の前に立っていた。"}, {"id": "ch15-s05-p021", "type": "text", "text": "白いコートの袖が腕まくりされていた。初めて見た。霜月さんが袖を上げているのを見たことがなかった。前腕が見えていた。細い腕。筋が通っている。"}, {"id": "ch15-s05-p022", "type": "text", "text": "その手が——紙片を握っていた。"}, {"id": "ch15-s05-p023", "type": "text", "text": "紙が破れていた。管理局のロゴが入った書面が四つに裂かれ、霜月さんの右手と左手に分かれて握られていた。裂かれた断面が白い。破片が床に一枚落ちていた。"}, {"id": "ch15-s05-p024", "type": "text", "text": "「霜月さん」"}, {"id": "ch15-s05-p025", "type": "text", "text": "もう一度呼んだ。"}, {"id": "ch15-s05-p026", "type": "text", "text": "霜月さんの目が俺を捉えた。ラベンダーの瞳が——開いていた。昨夜の機構室での瞳とも違う。昨夜は切削面の鋭さだった。今は違う。研磨されたあとの、内側から光っている硬さだった。怒りの硬さ。しかし震えていない。十一月の終わり、「五年前と同じだ」と声を震わせた時とも、選抜公演の夜に声が初めて震えた時とも違う。今日の硬さには震えがない。固まっている。液体が凍るのではなく、最初から固体として存在している怒りだった。"}, {"id": "ch15-s05-p027", "type": "text", "text": "「朝霧」"}, {"id": "ch15-s05-p028", "type": "text", "text": "声。低い。"}, {"id": "ch15-s05-p029", "type": "text", "text": "「今の書面を見たか」"}, {"id": "ch15-s05-p030", "type": "text", "text": "床の破片を見た。管理局のロゴ。宛名は「鐘鋳塔管理局 技師 霜月氷華」。差出人の欄は裂け目で半分読めなかったが、端に「織部」の二文字が見えた。"}, {"id": "ch15-s05-p031", "type": "text", "text": "「……見えました。織部副局長からの」"}, {"id": "ch15-s05-p032", "type": "text", "text": "「指示書だ」"}, {"id": "ch15-s05-p033", "type": "text", "text": "霜月さんの声が短い。一語ずつ、切り離して出している。"}, {"id": "ch15-s05-p034", "type": "text", "text": "「外円区を放棄し、内円区の防衛に資源を集中しろ、と」"}, {"id": "ch15-s05-p035", "type": "text", "text": "俺の足が止まった。"}, {"id": "ch15-s05-p036", "type": "text", "text": "外円区を放棄。"}, {"id": "ch15-s05-p037", "type": "text", "text": "「放棄。あの言葉を使った」"}, {"id": "ch15-s05-p038", "type": "text", "text": "霜月さんの左手が紙片を握り潰した。紙がくしゃりと鳴った。くしゃりの後、研究室が静かになった。"}, {"id": "ch15-s05-p039", "type": "text", "text": "「外円区の人口は推定五千から六千。縁蝕波で避難が完了しているのは内円区に入れた千八百。残りは外円区の各集落に散っている」"}, {"id": "ch15-s05-p040", "type": "text", "text": "数字が出てきた。霜月さんの口から。データ。この人は怒りの中でもデータを出す。"}, {"id": "ch15-s05-p041", "type": "text", "text": "「残りの三千から四千人が、蝕域に飲まれる。時間の問題だ。鐘の出力が戻らなければ——」"}, {"id": "ch15-s05-p042", "type": "text", "text": "声が止まった。"}, {"id": "ch15-s05-p043", "type": "text", "text": "止まったのは声であって、目ではなかった。ラベンダーの瞳が俺を見ていた。さっき扉を開けた時から一度も逸れていない。"}, {"id": "ch15-s05-p044", "type": "text", "text": "「私は従わない」"}, {"id": "ch15-s05-p045", "type": "text", "text": "四語。"}, {"id": "ch15-s05-p046", "type": "text", "text": "研究室の空気が変わった。残響灯の青白い光が壁面で止まった。モニタの赤い数字が点滅を続けているが、その機械的な光が霜月さんの声の前で後退したように見えた。"}, {"id": "ch15-s05-p047", "type": "text", "text": "「五年前、望ヶ丘を切り捨てた時と同じだ」"}, {"id": "ch15-s05-p048", "type": "text", "text": "声が低い。低いが、通る。壁の向こう側まで届く声。十一月の終わりに漏らした「同じ結末になった」は亀裂だった。亀裂が、今、意志になっている。"}, {"id": "ch15-s05-p049", "type": "text", "text": "「あの時も同じ指示が来た。『外円区は切り捨て可能。コストが合わない』。あの時、私は——」"}, {"id": "ch15-s05-p050", "type": "text", "text": "霜月さんの左手が動いた。"}, {"id": "ch15-s05-p051", "type": "text", "text": "左耳。青い石のピアス。指先がピアスに触れた。十月は手のひらで覆った。十二月の深夜は確認するように触れた。今日は——掴んでいた。指の腹が石を挟んでいる。手放さないための力。"}, {"id": "ch15-s05-p052", "type": "text", "text": "「声を上げた。十六歳だった。データは正確だった。警報を出す根拠はあった。しかし握り潰された。集落が消えた。三百人が死んだ。私のデータは改竄された」"}, {"id": "ch15-s05-p053", "type": "text", "text": "一文ずつ。句点のたびに、声の奥にあるものが表面に押し出されてくる。しかし乱れない。震えない。声が金属になっていた。冷たい金属。残響金属に似た、温度のない金属。"}, {"id": "ch15-s05-p054", "type": "text", "text": "「あの時、もっと戦えばよかった。殴ってでも。泣いてでも。しかし握り潰された後、私は黙った。組織を相手に、十六歳の声がどうにもならないと思ったから。黙ったまま五年が過ぎた」"}, {"id": "ch15-s05-p055", "type": "text", "text": "俺は何も言わなかった。何も言えなかったのではない。霜月さんの声が俺の口を閉じさせていた。聞け。今の声は、聞くべき声だ。背中の奥が重くなっていた。重さの中に温度があった。霜月さんの声が堆積していく。「また始まる」の上に「同じ結末になった」が積まれ、その上に今の声が落ちてくる。"}, {"id": "ch15-s05-p056", "type": "text", "text": "「朝霧」"}, {"id": "ch15-s05-p057", "type": "text", "text": "霜月さんの手が紙片を離した。破れた指示書が床に落ちた。管理局のロゴが上を向いていた。"}, {"id": "ch15-s05-p058", "type": "text", "text": "「外円区を捨てれば、数千人の住民が蝕域に飲まれる。五年前、望ヶ丘を捨てた時と同じことが起きる」"}, {"id": "ch15-s05-p059", "type": "text", "text": "「今度は——」"}, {"id": "ch15-s05-p060", "type": "text", "text": "声の質が変わった。金属の表面に、一筋の光が走った。冷たさの中の、熱。氷の内部にだけ存在する火。"}, {"id": "ch15-s05-p061", "type": "text", "text": "「今度は私は黙らない」"}, {"id": "ch15-s05-p062", "type": "text", "text": "七語。"}, {"id": "ch15-s05-p063", "type": "text", "text": "背中の奥が震えた。"}, {"id": "ch15-s05-p064", "type": "text", "text": "震えたのは恐怖ではなかった。選抜公演の夜、鳩尾の上が熱くなった時の感覚と同じ場所が反応していた。あの時、俺は初めて怒りを知った。模倣ではない怒り。鳴海さんのために声が低くなった夜。"}, {"id": "ch15-s05-p065", "type": "text", "text": "今、霜月さんの覚悟を聞いて、震えている。怒りではない。けれど怒りの隣にあるものだった。名前がまだない。霜月さんの声の中にある五年分の後悔と、今度は黙らないと決めた意志が、体を通過した。通過して、残った。"}, {"id": "ch15-s05-p066", "type": "text", "text": "霜月さんの瞳が俺を見ていた。"}, {"id": "ch15-s05-p067", "type": "text", "text": "試しているのではなかった。問うているのでもなかった。見せているのだ。覚悟を。この人が五年かけて凍らせたものを、今、溶かす方向に舵を切った。その最初の相手が俺だった。"}, {"id": "ch15-s05-p068", "type": "text", "text": "「……俺にできることを言ってください」"}, {"id": "ch15-s05-p069", "type": "text", "text": "声が出た。十月に同じことを言った。「俺にできることを言ってください」。あの時は鳩尾の上から出た声だった。今日の声は——背中の奥から出ていた。霜月さんの場所から。"}, {"id": "ch15-s05-p070", "type": "text", "text": "霜月さんが一瞬、目を閉じた。"}, {"id": "ch15-s05-p071", "type": "text", "text": "開いた。ラベンダーの瞳の硬さが——一度だけ、ほんの一層だけ、薄くなった。"}, {"id": "ch15-s05-p072", "type": "text", "text": "「データを整えなさい。三地点の時系列データ。今日の定例会議に間に合わせる。織部が何を言おうと、数字は嘘をつかない」"}, {"id": "ch15-s05-p073", "type": "text", "text": "業務口調が戻った。ただし色が違う。「従わない」を経た後の業務口調。戦うための命令だった。"}, {"id": "ch15-s05-p074", "type": "text", "text": "「了解しました」"}, {"id": "ch15-s05-p075", "type": "text", "text": "霜月さんがうなずいた。小さく。一度だけ。"}, {"id": "ch15-s05-p076", "type": "text", "text": "左手がピアスから離れた。離れた指先が、机の上のペンを取った。新しい紙を引き出した。破り捨てた指示書の代わりに、白い紙の上にペンを走らせ始めた。"}, {"id": "ch15-s05-p077", "type": "text", "text": "俺は研究室を出た。鉄扉を閉めた。"}, {"id": "ch15-s05-p078", "type": "text", "text": "通路の残響灯が明滅している。三階の石壁が冷たい。しかし残ったものは冷えていなかった。五年分の後悔が意志に変わる瞬間を、俺は今、見た。"}, {"id": "ch15-s05-p079", "type": "break", "text": "◇"}, {"id": "ch15-s05-p080", "type": "text", "text": "十一階への階段を上った。"}, {"id": "ch15-s05-p081", "type": "text", "text": "三階から十一階。八層分の螺旋。石段を一段ずつ踏んだ。五階で空気が薄くなった。残響灯の光が弱い。昨夜の縁蝕波で塔全体の出力が落ちている。壁面の残響紋がかすかに脈打っているが、光の密度は十二月の初めに比べて半分以下だった。"}, {"id": "ch15-s05-p082", "type": "text", "text": "八階。九階。共鳴の間の扉の前を通過した。扉は閉まっていた。鳴海さんがここで歌ったのは数時間前。あの歌声で鐘を補完し、蝕域を辛うじて押し返した。鳩尾の上にまだ残響がある。"}, {"id": "ch15-s05-p083", "type": "text", "text": "十階。大鐘の脇を通った。鐘の表面が残響灯の薄い光を受けている。紋様の溝が暗い。紋様が暗いのは光が弱いだけではなく、紋様そのものの発光が低下しているのだ。"}, {"id": "ch15-s05-p084", "type": "text", "text": "石段が木の床に変わった。"}, {"id": "ch15-s05-p085", "type": "text", "text": "十一階。天蓋の間。"}, {"id": "ch15-s05-p086", "type": "text", "text": "ガラスの天蓋を通して、朝の空が見えた。八時の空。十二月の曇り空。白い雲が低い位置にかかっている。太陽の位置は東南、雲の向こう。光がガラスを通過して、木の床に薄い白を落としていた。南の地平線付近に、白い靄がまだ残っていた。蝕域の残光。"}, {"id": "ch15-s05-p087", "type": "text", "text": "すみれが部屋の中央にいた。"}, {"id": "ch15-s05-p088", "type": "text", "text": "横になっていた。"}, {"id": "ch15-s05-p089", "type": "text", "text": "木の床の上に。毛布にくるまって。十三章で俺が持ってきた灰色の毛布。毛玉がいくつもついた薄い毛布。その毛布の中に、すみれの小さな体が包まれていた。膝を折り、体を丸めて、胎児のように横たわっている。淡い紫の髪が木の床に広がっていた。"}, {"id": "ch15-s05-p090", "type": "text", "text": "裸足の足先が毛布の端から覗いていた。足の指が——動いていなかった。十三章では震えていた。今日は震えもない。"}, {"id": "ch15-s05-p091", "type": "text", "text": "「すみれ」"}, {"id": "ch15-s05-p092", "type": "text", "text": "声が出た。足が速くなった。木の床を四歩。すみれの横に膝をついた。"}, {"id": "ch15-s05-p093", "type": "text", "text": "すみれの肩に手を置いた。"}, {"id": "ch15-s05-p094", "type": "text", "text": "冷たかった。十三章の冷たさとは——同じだった。十二月の外気より冷たい。すみれだけが世界を追い越して冷えている。"}, {"id": "ch15-s05-p095", "type": "text", "text": "「すみれ。起きてるか」"}, {"id": "ch15-s05-p096", "type": "text", "text": "薄紫の瞳がゆっくりと開いた。"}, {"id": "ch15-s05-p097", "type": "text", "text": "開いた。開くまでに三秒かかった。瞼が重そうだった。視線が天蓋に向いて、天蓋の白い光の中をさまよって、俺の顔に辿り着くまでにさらに二秒。"}, {"id": "ch15-s05-p098", "type": "text", "text": "「……れん」"}, {"id": "ch15-s05-p099", "type": "text", "text": "声。"}, {"id": "ch15-s05-p100", "type": "text", "text": "細い。十三章で「かねがいたい」と砕けた声よりは糸に近い。しかし糸の太さが足りない。一本の糸ではなく、半分の糸。声量が、壁に届かない。"}, {"id": "ch15-s05-p101", "type": "text", "text": "「来た」"}, {"id": "ch15-s05-p102", "type": "text", "text": "すみれの唇が動いた。微笑みの形ではなかった。唇が横に引かれて、0.5秒遅れて目が追いかけた。笑みの形になったが、形だけだった。目の奥の光が——薄い。十三章でかすかに戻りかけた光が、また沈んでいた。底に戻っていた。"}, {"id": "ch15-s05-p103", "type": "text", "text": "体に目をやった。"}, {"id": "ch15-s05-p104", "type": "text", "text": "すみれの首筋。鎖骨。手首。毛布の隙間から見える肌の上に、紋様が浮かんでいた。"}, {"id": "ch15-s05-p105", "type": "text", "text": "十三章で見た時より鮮明だった。"}, {"id": "ch15-s05-p106", "type": "text", "text": "手首から前腕にかけての曲線は同じだった。紫と青白の中間の光。しかし今日は——首筋にも広がっていた。鎖骨の上を横切る二本の線が、喉元に向かって伸びている。首の左側面に沿って、耳の下まで。肌の内側から透ける光の線が、十三章の倍の面積を覆っていた。"}, {"id": "ch15-s05-p107", "type": "text", "text": "鐘の残響紋と同じ形。同じ曲線の流れ。同じ脈動。"}, {"id": "ch15-s05-p108", "type": "text", "text": "脈動が弱かった。明滅の間隔が長い。強弱の振幅が小さい。十三章では呼吸のような周期で脈打っていた紋様が、今日は——呼吸が浅くなったように、弱く、遅くなっていた。"}, {"id": "ch15-s05-p109", "type": "text", "text": "すみれの右手が毛布の中から出てきた。"}, {"id": "ch15-s05-p110", "type": "text", "text": "小さな手。五本の細い指。指先が白い。十三章で見た白さと同じ。血の気のない色。"}, {"id": "ch15-s05-p111", "type": "text", "text": "その手が俺の左手に向かって伸びた。"}, {"id": "ch15-s05-p112", "type": "text", "text": "左手の甲にすみれの指が触れた。"}, {"id": "ch15-s05-p113", "type": "text", "text": "冷たさが皮膚を通して腕に上がった。すみれの冷たさ。七月から変わらない場所に、変わらない温度で触れてくる。しかし今日の冷たさは前より深かった。冷たさの奥に、もう一層の冷えがあった。"}, {"id": "ch15-s05-p114", "type": "text", "text": "すみれの指が俺の手を握った。五本の指が手の甲を包むように。弱い力。しがみつく力とも違った。十三章のしがみつく力は「離さない」だった。今日の力は「確認する」に近い。俺の手がここにあることを、指先で確かめている。"}, {"id": "ch15-s05-p115", "type": "text", "text": "「れん」"}, {"id": "ch15-s05-p116", "type": "text", "text": "すみれの声。半分の糸。"}, {"id": "ch15-s05-p117", "type": "text", "text": "「……もう、じかんがない」"}, {"id": "ch15-s05-p118", "type": "text", "text": "指が止まった。俺の指が。すみれの指の上で、俺の手が固まった。"}, {"id": "ch15-s05-p119", "type": "text", "text": "「何の時間だ、すみれ」"}, {"id": "ch15-s05-p120", "type": "text", "text": "声が低くなった。自分でわかった。喉の深い場所。十三章ですみれに駆けた時と同じ深さ。"}, {"id": "ch15-s05-p121", "type": "text", "text": "すみれの薄紫の瞳が俺を見ていた。"}, {"id": "ch15-s05-p122", "type": "text", "text": "瞳の奥で、底に沈んだ光の角度が変わった。変わった方向は——上ではなかった。横。光が何かを避けていた。何かを言わないために、視線の奥の層が一枚動いた。"}, {"id": "ch15-s05-p123", "type": "text", "text": "すみれが答えなかった。"}, {"id": "ch15-s05-p124", "type": "text", "text": "代わりに——唇が動いた。0.5秒遅れて目が追いかけた。微笑み。形だけの笑みではなかった。今度は、微笑みの中に別のものが載っていた。温かさではない。悲しさでもない。もっと静かなもの。俺を見て、俺がここにいることを確認して、それだけで良しとする——許容の微笑み。"}, {"id": "ch15-s05-p125", "type": "text", "text": "質問に答えなかったのは、答えたくなかったのか。答えると俺が傷つくと思ったのか。"}, {"id": "ch15-s05-p126", "type": "text", "text": "すみれの手が俺の手の甲の上で、わずかに力を足した。"}, {"id": "ch15-s05-p127", "type": "text", "text": "冷たい。冷たいが、力があった。弱い力。しかし存在する力。「ここにいる」という力。"}, {"id": "ch15-s05-p128", "type": "text", "text": "左手の甲が冷えていく。すみれの温度が浸透していく。温度を返すために、俺の右手をすみれの手の上に重ねた。両手ですみれの手を包んだ。十三章と同じ動作。すみれの手は両手の中で冷たいまま。温度が移らない。移らないが、送り続ける。"}, {"id": "ch15-s05-p129", "type": "text", "text": "すみれが目を閉じた。"}, {"id": "ch15-s05-p130", "type": "text", "text": "閉じた瞼が、微笑みの形を残していた。薄い肌。紫の睫毛。首筋の残響紋が弱い光を放っている。"}, {"id": "ch15-s05-p131", "type": "text", "text": "天蓋の向こうで、雲が東から西に流れていた。十二月の朝。八時過ぎの曇り空。白い光がガラスを通して、すみれと俺のいる場所に落ちている。"}, {"id": "ch15-s05-p132", "type": "text", "text": "「もう、じかんがない」。"}, {"id": "ch15-s05-p133", "type": "text", "text": "何の時間だ。鐘の時間か。塔の時間か。すみれの——時間か。"}, {"id": "ch15-s05-p134", "type": "text", "text": "左手の甲がすみれの冷たさを受けていた。背中の奥に霜月さんの覚悟が重なっていた。肋骨の内側に燈花の声が残っていた。耳の位置に篠宮さんの手が焼きついていた。鳩尾の底に沈殿物が堆積していた。"}, {"id": "ch15-s05-p135", "type": "text", "text": "五つ。"}, {"id": "ch15-s05-p136", "type": "text", "text": "体の中に処理の終わっていないものが五つ重なっていた。三つだったものが、今朝の二時間で五つになった。霜月さんの「私は黙らない」。すみれの「もう、じかんがない」。力と脆さ。全く異なるものが、同じ体の中に同居している。"}, {"id": "ch15-s05-p137", "type": "text", "text": "すみれの手が俺の手の中で小さく動いた。指先が俺の指の間を探って、止まった。"}, {"id": "ch15-s05-p138", "type": "text", "text": "俺は立たなかった。"}, {"id": "ch15-s05-p139", "type": "text", "text": "立たなければならない時間が来る。霜月さんの定例会議に間に合わせるデータを整えなければならない。篠宮さんに渡すメモの続きがある。千歳の歌の次に何ができるかを考えなければならない。燈花が外円区にいる。晶さんが島のどこにいるかわからない。全てが動いている。"}, {"id": "ch15-s05-p140", "type": "text", "text": "全てが動いている中で——今、この手を離す必要はない。"}, {"id": "ch15-s05-p141", "type": "text", "text": "すみれの呼吸を聴いていた。浅い。遅い。しかしある。まだ、ある。"}, {"id": "ch15-s05-p142", "type": "text", "text": "窓のないこの部屋で、天蓋のガラス越しの曇り空だけが時計だった。雲が流れている。空の色が変わっていく。すみれの手が俺の手の中にある。"}, {"id": "ch15-s05-p143", "type": "text", "text": "足を動かすのは、もう少し後でいい。"}]}, {"chapter": 15, "chapterTitle": "縁蝕波", "scene": 6, "sceneTitle": "アナザービュー群：それぞれの嵐", "wordCount": "約3,000字", "paragraphs": [{"id": "ch15-s06-p001", "type": "text", "text": "——風祭いろは"}, {"id": "ch15-s06-p002", "type": "break", "text": "◇"}, {"id": "ch15-s06-p003", "type": "text", "text": "ガラスの向こうでちーちゃんが歌っている。"}, {"id": "ch15-s06-p004", "type": "text", "text": "共鳴の間の入口。鉄の扉のすぐ内側。石の床に膝をついたまま、あたしはそこにいた。球形の壁面が歌声を返している。反射して、増幅して、空間の全方向から音が降ってくる。全部ちーちゃんの声だった。全部が一人の喉から出た音だった。"}, {"id": "ch15-s06-p005", "type": "text", "text": "立てなかった。"}, {"id": "ch15-s06-p006", "type": "text", "text": "膝をついた時の衝撃がまだ脛に残っている。走ってきた。補佐官舎から石段を駆け上がった。九階分。スニーカーの底が石を叩く音を数える余裕はなかった。着いた時にはもう歌が始まっていて、ちーちゃんが球体の真ん中に立っていて、白い顔で、汗を流していて、指先が勝手に動いていた。"}, {"id": "ch15-s06-p007", "type": "text", "text": "見えた瞬間に膝が折れた。"}, {"id": "ch15-s06-p008", "type": "text", "text": "嘘じゃなかった。二年間ずっと予感していたことが、嘘じゃなかった。ちーちゃんのお母さんと同じことが起きている。歌うたびに何かが減る。減ったぶんは戻らない。戻らないまま、また歌う。また減る。繰り返す。今夜も繰り返している。"}, {"id": "ch15-s06-p009", "type": "text", "text": "「もうやめて」と言った。"}, {"id": "ch15-s06-p010", "type": "text", "text": "声が出ていたのかどうかわからない。歌声に潰されていたかもしれない。けど口は動いた。喉の奥が軋んだ。訓練で壊しかけた場所。あたしの声帯の傷。ちーちゃんの代わりになろうとして、無理な発声を重ねて、ざらざらになった喉の内壁。その傷が今夜また開いている。声を出すたびに引っ掻かれる。"}, {"id": "ch15-s06-p011", "type": "text", "text": "ちーちゃんが一瞬だけ目を開けた。"}, {"id": "ch15-s06-p012", "type": "text", "text": "薄い琥珀色があたしを見た。以前より薄い。水で割ったどころじゃない。色がほとんど残っていない。その目が何かを言っていた。声では言えないから、目で。口の形でもなく、瞬きでもなく、瞳の奥にあるものだけで。"}, {"id": "ch15-s06-p013", "type": "text", "text": "ごめん。でも止まれない。"}, {"id": "ch15-s06-p014", "type": "text", "text": "わかってる。わかってるよ、ちーちゃん。ちーちゃんは歌いたいから歌ってる。使命とか義務とか、そういうのじゃない。歌うことがちーちゃんの真ん中にある。あたしはそれを二年間見てきた。止める権利なんかない。"}, {"id": "ch15-s06-p015", "type": "text", "text": "わかってる。"}, {"id": "ch15-s06-p016", "type": "text", "text": "わかっていることが、一番苦しい。"}, {"id": "ch15-s06-p017", "type": "text", "text": "右手首のミサンガに爪が食い込んでいた。拳を握っていたことに今さら気づいた。編み目が指の腹に跡をつけている。ちーちゃんとお揃い。ちーちゃんは左手首。願いが叶ったら切れる。あたしの願い——ちーちゃんがずっと笑っていられますように。"}, {"id": "ch15-s06-p018", "type": "text", "text": "切れる気配がない。切れるどころか、結び目がきつくなっていく。"}, {"id": "ch15-s06-p019", "type": "text", "text": "壁面の残響紋が脈打っていた。紫がかった光がちーちゃんの声に合わせて明滅する。光が強い。ちーちゃんが強く歌っている。強く歌えば歌うほど鐘の出力が上がる。出力が上がれば島が守られる。島が守られる代わりに、ちーちゃんの顔から色が抜けていく。"}, {"id": "ch15-s06-p020", "type": "text", "text": "あたしがちーちゃんの代わりに歌えたら。"}, {"id": "ch15-s06-p021", "type": "text", "text": "あたしの命で足りるなら、あたしの声帯を全部壊してもいい。"}, {"id": "ch15-s06-p022", "type": "text", "text": "共鳴適性C。入学時の判定。低い。訓練しても上がらなかった。上がらないまま二年が過ぎた。声量は足りている。音程も取れる。でも共鳴しない。あたしの声は壁面の残響紋を揺らさない。鐘に届かない。何百回練習しても、喉を潰しても、あたしの声はちーちゃんの代わりにならない。"}, {"id": "ch15-s06-p023", "type": "text", "text": "代わりにならないなら、ここにいることしかできない。"}, {"id": "ch15-s06-p024", "type": "text", "text": "ガラスの向こうじゃない。ガラスはなかった。扉は開いていた。入口に膝をつけば、ちーちゃんまで十メートルもなかった。十メートルが遠い。声が届いても、手が届かない。"}, {"id": "ch15-s06-p025", "type": "text", "text": "十一月に朝霧さんに秘密を話した。あたし一人じゃもう持てなかったから。話した後、ほんの少しだけ重さが減った。一人じゃなくなった。朝霧さんが知っている。覚えておく、とあの人は言わなかった。言わなかったけど、あの目は覚える目だった。"}, {"id": "ch15-s06-p026", "type": "text", "text": "でも今、この入口にいるのはあたし一人だった。"}, {"id": "ch15-s06-p027", "type": "text", "text": "朝霧さんは計器の横にいる。霜月先生もいる。二人とも業務をしている。あたしには業務がない。共鳴の間にあたしの持ち場はない。あたしにできることは何もない。待つことだけ。ちーちゃんが歌い終わって戻ってくるのを待つことだけ。"}, {"id": "ch15-s06-p028", "type": "text", "text": "待つことが一番苦しいって、二年前に知った。"}, {"id": "ch15-s06-p029", "type": "text", "text": "歌声が揺れた。"}, {"id": "ch15-s06-p030", "type": "text", "text": "一音だけ。旋律の途中で、声が外れた。外れて、戻った。戻るために何を燃やしたのかが、ちーちゃんの顔色でわかった。白から、もう一段薄い色へ。"}, {"id": "ch15-s06-p031", "type": "text", "text": "ちーちゃんの膝が震えていた。"}, {"id": "ch15-s06-p032", "type": "text", "text": "歌声は続いている。声だけが立っている。体はもう限界なのに声だけが折れない。折れないちーちゃんを見ている。見ていることしかできない。"}, {"id": "ch15-s06-p033", "type": "text", "text": "——歌が止まった。"}, {"id": "ch15-s06-p034", "type": "text", "text": "静寂が落ちた。壁面の残響紋の光が残像のように尾を引いて、消えた。球形の空間に声がなくなった。"}, {"id": "ch15-s06-p035", "type": "text", "text": "ちーちゃんの膝が折れた。"}, {"id": "ch15-s06-p036", "type": "text", "text": "体が傾いた。前に。両手が出なかった。そのまま——"}, {"id": "ch15-s06-p037", "type": "text", "text": "走った。"}, {"id": "ch15-s06-p038", "type": "text", "text": "膝が石の床から離れた。立ち上がる動作と走る動作が同時だった。十メートル。五歩。四歩。三歩。"}, {"id": "ch15-s06-p039", "type": "text", "text": "「ちーちゃんっ——！」"}, {"id": "ch15-s06-p040", "type": "text", "text": "声帯の傷が裂けた。喉の奥で何かが切れる感触があった。痛みは後で来る。今は関係ない。"}, {"id": "ch15-s06-p041", "type": "text", "text": "ちーちゃんの体を抱きとめた。"}, {"id": "ch15-s06-p042", "type": "text", "text": "軽かった。軽い、と思った。十一月の楽屋で抱きしめた時より軽い。体重が減っている。汗で濡れたブラウスの上から伝わる体温が高い。熱い。命を燃やした後の熱。首筋に顔を埋めた。ちーちゃんの匂いがした。汗と、石鹸の残りと、それ以外の何か。ちーちゃんだけの匂い。"}, {"id": "ch15-s06-p043", "type": "text", "text": "「……い、ろは」"}, {"id": "ch15-s06-p044", "type": "text", "text": "かすれた声が耳元で鳴った。"}, {"id": "ch15-s06-p045", "type": "text", "text": "ちーちゃんの目が開いていた。薄い。薄い琥珀色の瞳が、あたしを見ていた。"}, {"id": "ch15-s06-p046", "type": "text", "text": "「だいじょう、ぶ」"}, {"id": "ch15-s06-p047", "type": "text", "text": "嘘つくの下手なくせに。"}, {"id": "ch15-s06-p048", "type": "text", "text": "言えなかった。喉が詰まっていた。傷が開いた喉が音を通さなかった。代わりにちーちゃんの背中に回した手に力を込めた。離さない。離さない。"}, {"id": "ch15-s06-p049", "type": "text", "text": "ミサンガの編み目が、ちーちゃんのブラウスの背中に押し当てられていた。切れない。まだ切れない。願いは叶っていない。"}, {"id": "ch15-s06-p050", "type": "text", "text": "◇◇◇"}, {"id": "ch15-s06-p051", "type": "text", "text": "——弦月宗一郎"}, {"id": "ch15-s06-p052", "type": "break", "text": "◇"}, {"id": "ch15-s06-p053", "type": "text", "text": "外円区が白く光っていた。"}, {"id": "ch15-s06-p054", "type": "text", "text": "管理局長室の窓から南方を望む。十二月の深夜。星のない空の下に、地平線付近だけが白い靄を帯びている。蝕域の侵食光。島の南端から、じりじりと北に這い寄ってくる光。六時間前より明るくなっている。"}, {"id": "ch15-s06-p055", "type": "text", "text": "デスクの上の茶器に手を伸ばした。磁器の杯。指先が触れた。冷たかった。淹れたのは三時間前だ。一口も飲んでいない。"}, {"id": "ch15-s06-p056", "type": "text", "text": "窓に自分の顔が映っていた。六十年分の皺が刻まれた顔。灰色のコートの襟が立っている。局長の徽章が、窓の反射の中で鈍く光った。"}, {"id": "ch15-s06-p057", "type": "text", "text": "鳴海千歳に歌唱を命じたのは私だ。"}, {"id": "ch15-s06-p058", "type": "text", "text": "十二月初旬の会議室。「鳴海くん。共鳴者による出力補完が必要だ」。あの言葉を口にする前に、指を組み直した。右手が上だったものを左手に変えた。その0.3秒の間に、選択の重さを飲み込んだ。飲み込んだつもりだった。飲み込めてはいなかった。"}, {"id": "ch15-s06-p059", "type": "text", "text": "島を守るため。"}, {"id": "ch15-s06-p060", "type": "text", "text": "合理的判断。鐘の出力が50パーセントを割れば、外円区の蝕域抑止力が喪失する。推定被害人口は数千。年間の消滅者名簿が一気に桁を変える。それを防ぐ手段は、現時点では共鳴者の歌唱以外に存在しない。"}, {"id": "ch15-s06-p061", "type": "text", "text": "合理は正しい。数字は正しい。しかし合理の先にあるのは、十八歳の少女の体が削れていく光景であった。"}, {"id": "ch15-s06-p062", "type": "text", "text": "報告書が机の上にある。霜月技師が毎日提出する計測データ。身体負荷指数の推移。数字は上昇を続けている。上昇の傾きは加速している。紙の上の数字は感情を持たない。持たない数字が示す事実は、鳴海千歳の命の残量が目減りしているということだ。"}, {"id": "ch15-s06-p063", "type": "text", "text": "知っていて、歌わせている。"}, {"id": "ch15-s06-p064", "type": "text", "text": "朝霧補佐が十一月に霜月技師に向けた言葉を、私は伝聞で知った。直接は聞いていない。しかし聞く必要はなかった。あの言葉は私にこそ向けられるべきだった。歌唱を命じたのは私だ。補佐は現場にいる。天秤の目盛りを読む者だ。天秤を傾けたのは、局長室にいる私だ。"}, {"id": "ch15-s06-p065", "type": "text", "text": "窓の外が明るくなっている。"}, {"id": "ch15-s06-p066", "type": "text", "text": "明るいのは夜明けではない。蝕域の光だ。白い靄が地平線から浮き上がり、空の低い位置まで染めている。あの光の下に集落がある。人が住んでいる。名前を持った人間が、家の中で眠っている。眠っている間に、白い光が近づいてくる。"}, {"id": "ch15-s06-p067", "type": "text", "text": "五年前。"}, {"id": "ch15-s06-p068", "type": "text", "text": "同じ光景を見た。"}, {"id": "ch15-s06-p069", "type": "text", "text": "望ヶ丘。外円区南端の集落。人口三百十二名。蝕域の活動指数が急上昇した夜、氷華——当時十六歳の技師見習いが、データを示して警報を具申した。数字は正確だった。根拠は十分だった。"}, {"id": "ch15-s06-p070", "type": "text", "text": "織部がそれを握り潰した。"}, {"id": "ch15-s06-p071", "type": "text", "text": "織部正隆。副局長。当時も副局長だった。「コストが合わない」。外円区の一集落を守るために鐘の出力配分を変えれば、他の区画の防衛力が下がる。全体最適を考えれば、三百人の集落は切り捨て可能だと。"}, {"id": "ch15-s06-p072", "type": "text", "text": "私は——その判断を追認した。"}, {"id": "ch15-s06-p073", "type": "text", "text": "追認、という語を使うのは欺瞞だろう。決裁したのは局長たる私である。織部の提案を受け入れ、警報を出さず、出力配分を変えなかった。翌朝、望ヶ丘は白い光の中に消えていた。"}, {"id": "ch15-s06-p074", "type": "text", "text": "追悼祭の名簿に三百十二の名前が加わった。"}, {"id": "ch15-s06-p075", "type": "text", "text": "霜月氷華の目を見ることができなかった。あの日以降、氷華は声を上げなくなった。十六歳の少女が出したデータを握り潰し、改竄し、声を封じた。その構造の最上位にいたのは私だ。織部が手を汚したのは事実だが、汚れた手を見て見ぬ振りをした者もまた同罪である。"}, {"id": "ch15-s06-p076", "type": "text", "text": "また同じ選択を迫られている。"}, {"id": "ch15-s06-p077", "type": "text", "text": "外円区の住民か、共鳴者の命か。織部は今夜も「外円区を放棄し、内円区に資源を集中すべき」と進言してきた。五年前と同じ言葉。同じ論理構造。同じ結論。"}, {"id": "ch15-s06-p078", "type": "text", "text": "五年前と違うのは、今度は私が——その進言を退けるかどうかの判断を迫られていることだ。"}, {"id": "ch15-s06-p079", "type": "text", "text": "退ければ、共鳴者の歌唱継続が前提となる。鳴海千歳の体をさらに削ることになる。"}, {"id": "ch15-s06-p080", "type": "text", "text": "受け入れれば、外円区の数千人が蝕域に飲まれる。"}, {"id": "ch15-s06-p081", "type": "text", "text": "どちらを選んでも、何かを失う。"}, {"id": "ch15-s06-p082", "type": "text", "text": "「正しさとは何だ」"}, {"id": "ch15-s06-p083", "type": "text", "text": "声が出ていた。独白。管理局長室には誰もいない。窓の反射の中の自分だけが聞いている。"}, {"id": "ch15-s06-p084", "type": "text", "text": "正しい判断をした。五年前も。島全体の安全を考えれば、出力配分の変更は危険だった。全体最適は正しかった。数字は正しかった。"}, {"id": "ch15-s06-p085", "type": "text", "text": "正しさの代償が三百十二人の命だった。"}, {"id": "ch15-s06-p086", "type": "text", "text": "今夜もまた、正しさを選ぼうとしている。島全体を守るために共鳴者に歌わせる。合理的だ。正しい。正しさの代償が十八歳の少女一人の命だとしても、数千人と一人なら、数字は一つの答えしか出さない。"}, {"id": "ch15-s06-p087", "type": "text", "text": "数字は一つの答えしか出さない。"}, {"id": "ch15-s06-p088", "type": "text", "text": "しかし私は知っている。数字が出した答えに従って、私は望ヶ丘を失った。数字は正しかった。結果は取り返せなかった。"}, {"id": "ch15-s06-p089", "type": "text", "text": "「……私は、また間違えるのか」"}, {"id": "ch15-s06-p090", "type": "text", "text": "窓の外が白い。蝕域の光が夜空を染めている。朝はまだ遠い。"}, {"id": "ch15-s06-p091", "type": "text", "text": "杯に手を伸ばした。冷えた茶を一口含んだ。渋みだけが舌に残る液体が喉を通過した。温度がない。味がない。ただ渋い。"}, {"id": "ch15-s06-p092", "type": "text", "text": "デスクの上の報告書をめくった。霜月技師の筆跡が整然と並んでいる。数字。グラフ。推移。全てが正確で、正確であることが残酷だった。この数字の裏側に人間がいる。歌っている人間がいる。歌うたびに削れていく人間がいる。"}, {"id": "ch15-s06-p093", "type": "text", "text": "机の引き出しに、五年前の追悼祭の名簿が入っている。三百十二名分。開かない。開けば読んでしまう。読めば名前を思い出す。名前を思い出せば、あの朝の白い光を思い出す。思い出しても、何も変わらない。"}, {"id": "ch15-s06-p094", "type": "text", "text": "何も変わらないことを知っていて、引き出しを開けない自分がいる。"}, {"id": "ch15-s06-p095", "type": "text", "text": "窓の外の白が、少しずつ薄れ始めていた。東の空の端に、灰色が混じっている。夜が明ける。蝕域の光は夜明けとともに見えなくなる。見えなくなるだけで、消えるわけではない。昼の光の下で、同じ速度で、同じ方向に、侵食は続く。"}, {"id": "ch15-s06-p096", "type": "text", "text": "朝が来る。"}, {"id": "ch15-s06-p097", "type": "text", "text": "答えは出ないまま、朝が来る。"}, {"id": "ch15-s06-p098", "type": "text", "text": "管理局長室に朝の光が差す時、私はこのデスクに座っている。報告書を読み、数字を並べ、指を組み、選択を迫られる。五年前と同じ構造の中で。同じ問いの前で。"}, {"id": "ch15-s06-p099", "type": "text", "text": "椅子の背もたれが軋んだ。体を預けた。天井を見上げた。石の天井に罅が一本走っている。いつからあった罅なのか、覚えていない。"}, {"id": "ch15-s06-p100", "type": "text", "text": "窓の反射の中で、老いた男の顔が白い光に照らされていた。"}]}, {"chapter": 16, "chapterTitle": "誰の側に", "scene": 1, "sceneTitle": "嵐の後", "wordCount": "約4,200字", "paragraphs": [{"id": "ch16-s01-p001", "type": "text", "text": "すみれの手を離したのは九時を過ぎた頃だった。"}, {"id": "ch16-s01-p002", "type": "text", "text": "天蓋のガラスの向こうの空が、曇り空の灰色から一段薄い灰色に変わっていた。光の変化で時間を読む。九時か、九時半か。正確にはわからない。すみれの呼吸が安定していた。浅い呼吸が等間隔になっていた。眠っている。"}, {"id": "ch16-s01-p003", "type": "text", "text": "右手を引いた。すみれの手が俺の手の上で滑って、毛布の上に落ちた。小さな音。すみれの瞼は動かなかった。"}, {"id": "ch16-s01-p004", "type": "text", "text": "立ち上がった。膝が鳴った。木の床の冷たさが膝小僧から脛に移っていた。一時間以上、同じ姿勢だった。"}, {"id": "ch16-s01-p005", "type": "text", "text": "毛布の端をすみれの足に掛け直した。足先が出ている。冷たい足。毛布をかけても温度は変わらないだろう。変わらないとしても、かけた。"}, {"id": "ch16-s01-p006", "type": "text", "text": "階段を降りた。"}, {"id": "ch16-s01-p007", "type": "text", "text": "十一階から三階。八層分の螺旋を降りる。残響灯は半分以下しか点いていない。点いている灯りも光量が落ちている。壁の影が濃い。通路の空気が乾いていた。昨夜まで微かにあった残響灯の帯びた匂いが消えて、冷えた石だけの匂いが残っている。石段を踏む自分の足音が壁に跳ねて、返ってこなかった。音を吸う余力も壁に残っていない。"}, {"id": "ch16-s01-p008", "type": "text", "text": "三階。霜月さんの研究室の鉄扉の下から光が漏れていた。まだいる。定例会議の資料を作っている。データ整備の指示を受けていた。"}, {"id": "ch16-s01-p009", "type": "text", "text": "扉を叩いた。二度。"}, {"id": "ch16-s01-p010", "type": "text", "text": "「入れ」"}, {"id": "ch16-s01-p011", "type": "text", "text": "霜月さんの声。短い。しかし一時間前の金属質とは違った。作業に集中している声。紙の上に意識を置いている時の、平坦な命令。"}, {"id": "ch16-s01-p012", "type": "text", "text": "扉を開けた。"}, {"id": "ch16-s01-p013", "type": "text", "text": "「外円区の三地点の時系列データ、通信室のメモを転記しました。確認をお願いします」"}, {"id": "ch16-s01-p014", "type": "text", "text": "紙を机に置いた。霜月さんの目がペンから紙に移った。俺の字を読んでいる。三秒。五秒。"}, {"id": "ch16-s01-p015", "type": "text", "text": "「……この空白は何だ」"}, {"id": "ch16-s01-p016", "type": "text", "text": "「四時三十分から四時五十分の間。残響通信が途絶した二十分間です。データなし」"}, {"id": "ch16-s01-p017", "type": "text", "text": "「なしか」"}, {"id": "ch16-s01-p018", "type": "text", "text": "「通信が回復した後の数値で外挿は可能です。ただ、実測値ではないので注記を入れました」"}, {"id": "ch16-s01-p019", "type": "text", "text": "霜月さんが紙の端の注記を読んだ。小さくうなずいた。一度だけ。"}, {"id": "ch16-s01-p020", "type": "text", "text": "「いい。これで足りる」"}, {"id": "ch16-s01-p021", "type": "text", "text": "声に温度はなかった。しかし「いい」という語が出た。霜月さんの業務上の「いい」は、許容ではなく承認だった。数字が使える水準に達している。"}, {"id": "ch16-s01-p022", "type": "text", "text": "「定例は十四時からです。織部副局長も出席します」"}, {"id": "ch16-s01-p023", "type": "text", "text": "知っていた。霜月さんの「今度は私は黙らない」が背中の奥で重く揺れた。"}, {"id": "ch16-s01-p024", "type": "text", "text": "「了解しました。何か追加があれば」"}, {"id": "ch16-s01-p025", "type": "text", "text": "「ない。——一つだけ。顔を洗え。目の下に隈がある」"}, {"id": "ch16-s01-p026", "type": "text", "text": "言葉が事務的だった。事務的であることが、霜月さんの気遣いの形式だった。"}, {"id": "ch16-s01-p027", "type": "text", "text": "研究室を出た。"}, {"id": "ch16-s01-p028", "type": "text", "text": "一階に降りた。鐘鋳塔の正面の扉を開けた。"}, {"id": "ch16-s01-p029", "type": "break", "text": "◇"}, {"id": "ch16-s01-p030", "type": "text", "text": "空が広かった。"}, {"id": "ch16-s01-p031", "type": "text", "text": "十二月の昼。雲が高い位置にかかっている。昨夜の白い光は消えていた。南の地平線に薄い靄が残っているが、夜の圧迫感はもうない。空は空の色をしていた。灰色と青の間の、冬の色。"}, {"id": "ch16-s01-p032", "type": "text", "text": "しかし——空の下が違った。"}, {"id": "ch16-s01-p033", "type": "text", "text": "鐘鋳塔の前に立つ。環の広場の石畳を横切りながら、南を見た。南方面。外円区のある方向。"}, {"id": "ch16-s01-p034", "type": "text", "text": "見慣れた風景があるはずだった。"}, {"id": "ch16-s01-p035", "type": "text", "text": "鐘鋳塔の前から南を眺めると、内円区の白い建物越しに中円区の屋根が連なり、その先に外円区の農地が広がっている。畑の緑と茶。冬は色が鈍るが、地面の色はある。その先に空の端があり、空の端が蝕域の靄で白くぼやけている。いつもの風景。"}, {"id": "ch16-s01-p036", "type": "text", "text": "農地が途切れていた。"}, {"id": "ch16-s01-p037", "type": "text", "text": "俺が立っている場所から南方面を見て——中円区の屋根の連なりはある。しかしその奥が薄い。奥行きが足りない。中円区の終わりから先に、何もない。何も、ではない。空がある。灰色の空が下のほうまで伸びている。空の下にあるべき地面が、空に変わっている。"}, {"id": "ch16-s01-p038", "type": "text", "text": "外円区の南半分が消えていた。"}, {"id": "ch16-s01-p039", "type": "text", "text": "地面がない。建物もない。農地もない。畑の区画もない。あったはずの道もない。「ない」が空を使って主張している。地平線が上がっていた。昨日まで地面と空の境界だった線が、もう空でしかない。"}, {"id": "ch16-s01-p040", "type": "text", "text": "環の広場の石畳を足が踏んだ。振動がない。地面は固い。ここは、ある。"}, {"id": "ch16-s01-p041", "type": "text", "text": "島が、小さくなった。"}, {"id": "ch16-s01-p042", "type": "text", "text": "管理局前の掲示板に紙が貼られていた。通りすがりに読んだ。「十二月二十三日未明の大規模縁蝕波に伴う被害状況（第一報）」。数字が並んでいる。外円区南部および南東部において推定消滅面積約四・二平方キロメートル。推定被害者数三百名以上。避難収容者は内円区および中円区に約千八百名。外円区北部は残存。"}, {"id": "ch16-s01-p043", "type": "text", "text": "三百名。"}, {"id": "ch16-s01-p044", "type": "text", "text": "数字の上に目が止まった。俺が通信室で走り書いた数字の延長にある。あの夜の有線電話と残響通信で拾った断片が、ここで一つの合計になっている。三百名。それは灯里村が消えた時の規模に近い。同規模の消滅が、一晩で起きた。"}, {"id": "ch16-s01-p045", "type": "text", "text": "掲示板の前に人が三人いた。誰も何も言わなかった。紙面を見て、紙面から目を離して、それぞれの方向に歩いていった。"}, {"id": "ch16-s01-p046", "type": "text", "text": "俺も歩いた。中円区へ。聖鐘学院の方向へ。"}, {"id": "ch16-s01-p047", "type": "break", "text": "◇"}, {"id": "ch16-s01-p048", "type": "text", "text": "中庭に入った。"}, {"id": "ch16-s01-p049", "type": "text", "text": "残響桜が裸だった。"}, {"id": "ch16-s01-p050", "type": "text", "text": "春に薄紫の花弁を散らす桜。五月の残響祭でライトアップした桜。秋に金色に紅葉していた葉が、全て落ちていた。枝だけが冬の空に伸びている。灰色の枝。冬枯れよりも早い。十二月の上旬にはまだ葉が残っていた。昨夜の縁蝕波で一気に落ちた。"}, {"id": "ch16-s01-p051", "type": "text", "text": "石畳の上に紫がかった枯れ葉が散らばっていた。薄い。乾いている。踏むと割れそうだった。踏まなかった。"}, {"id": "ch16-s01-p052", "type": "text", "text": "しかし——枝は折れていない。"}, {"id": "ch16-s01-p053", "type": "text", "text": "幹に触れた。手のひらに樹皮の凹凸が当たった。冷たい。けれど硬い。枯れてはいない。冬の間は眠っている。春にまた咲く——そのための力がまだ幹の中にある。"}, {"id": "ch16-s01-p054", "type": "text", "text": "鐘の力がまだ中心部を守っている。内円区と中円区には鐘の音が届いている。届いた場所は保たれている。外円区の南半分が消えたのは、鐘の音の到達限界の外側が蝕域に押し切られたからだ。"}, {"id": "ch16-s01-p055", "type": "text", "text": "桜の下のベンチに座った。"}, {"id": "ch16-s01-p056", "type": "text", "text": "木のベンチ。塗装が剥げて、座面に雨染みがある。四月に燈花が弁当を広げた場所。雫がメモ帳を開いていた場所。鳴海さんが背もたれに手を置いて、すみれの話を聞いていた場所。"}, {"id": "ch16-s01-p057", "type": "text", "text": "座った。目を閉じた。"}, {"id": "ch16-s01-p058", "type": "text", "text": "体が重い。一晩中眠れていない。通信室で二時間。天蓋の間で一時間以上。仮眠は浅い。石段を何層分も上り下りした。足が痛い。首が凝っている。目の奥が乾いている。"}, {"id": "ch16-s01-p059", "type": "text", "text": "目を閉じると暗い。暗さの中に——順番に浮かんでくる。"}, {"id": "ch16-s01-p060", "type": "text", "text": "鳩尾の上。鳴海さんの歌の残響がまだ灼けている。共鳴の間で聴いた声。管を通って俺の体に入り込み、鐘と混ざり合って蝕域を押し返した声。あの後、鳴海さんは倒れた。歌い終わった時点で意識がなかった。医務室に運ばれた。今も、目を覚ましていない。"}, {"id": "ch16-s01-p061", "type": "text", "text": "肋骨の内側。燈花の「待ってて」。氷の石はまだ溶けていない。外円区の南半分が消えた。燈花は南に向かっていた。灯里村のあった方角に。あの灯りが今どこにあるのかわからない。掲示板の「避難収容者千八百名」の中に燈花がいるのかどうか。確認できていない。"}, {"id": "ch16-s01-p062", "type": "text", "text": "耳の位置。篠宮さんの手が焼きついている。指先の向こうの木目。透けた三本の指。「何もありませんが」と答えた篠宮さんの声。あの後も記録を取り続けていた。消える人々の名前を書き続けている人の手が、消えかけていた。"}, {"id": "ch16-s01-p063", "type": "text", "text": "背中の奥。霜月さんの覚悟が載っている。「今度は私は黙らない」の七語が、一時間前のデータ転記の間もずっとそこにあった。十四時の定例会議で霜月さんは織部副局長と対峙する。五年間の沈黙を破る。上層部と戦う。その結果がどうなるのか、俺にはわからない。"}, {"id": "ch16-s01-p064", "type": "text", "text": "左手の甲。すみれの冷たさが残っている。「もう、じかんがない」。何の時間かは答えてもらえなかった。手を離した時、すみれの指が俺の指を探した。眠りの中で。"}, {"id": "ch16-s01-p065", "type": "text", "text": "鳩尾の底。沈殿物。夢の中で聞こえる「約束して」。ルミエラ島。消えた場所。俺が消え残った理由。"}, {"id": "ch16-s01-p066", "type": "text", "text": "内ポケットの布片。ルミエラの刺繍。指先で触れなくても、布の存在が胸の上で重力を持っている。"}, {"id": "ch16-s01-p067", "type": "text", "text": "目の奥。篠宮さんの指先の向こうの木目が、まだ残像として焼きついている。"}, {"id": "ch16-s01-p068", "type": "text", "text": "全部が俺の体の中にある。"}, {"id": "ch16-s01-p069", "type": "text", "text": "五つ。いや、七つ。八つ。数えきれない。処理の終わっていないものが体の中で層になっている。堆積している。沈殿物の上に氷の石が載り、その上に歌の残響があり、覚悟の重さがあり、冷たい手のひらがあり、透ける指がある。全部がひとつの体に同居している。"}, {"id": "ch16-s01-p070", "type": "text", "text": "全員を助けたかった。"}, {"id": "ch16-s01-p071", "type": "text", "text": "浮かんだ言葉は、それだった。感情の名前ではなかった。事実だった。俺は全員を助けたい。鳴海さんが歌を止められる方法を見つけたい。篠宮さんの体に何が起きているか知りたい。燈花が無事であることを確認して、灯里村の跡に一緒に立ちたい。霜月さんの戦いを最後まで手伝いたい。すみれの手をもう一度握りたい。"}, {"id": "ch16-s01-p072", "type": "text", "text": "全員を。"}, {"id": "ch16-s01-p073", "type": "text", "text": "しかし、今この瞬間、俺はベンチに座っている。"}, {"id": "ch16-s01-p074", "type": "text", "text": "鳴海さんは医務室にいる。俺はここにいる。篠宮さんは記録室にいる。俺はここにいる。燈花がどこにいるかわからない。霜月さんは三階で戦いの準備をしている。すみれは天蓋の間で眠っている。俺は全員のことを考えていて、全員の場所にいない。"}, {"id": "ch16-s01-p075", "type": "text", "text": "同時にはいられない。"}, {"id": "ch16-s01-p076", "type": "text", "text": "五つの場所に同時に立つことはできない。身体感覚マップは一つしかない。左手の甲は一つ、背中は一つ、肋骨の内側は一つ。全部が俺に向けて手を伸ばしていて、俺の手は二本しかない。"}, {"id": "ch16-s01-p077", "type": "text", "text": "「全員を助けたい」は祈りだった。祈りは構造を変えない。構造は冷たい。今、この島で同時に複数の危機が進行していて、蓮という一人の人間がどこに足を運ぶかで、手が届くものと届かないものが分かれる。"}, {"id": "ch16-s01-p078", "type": "text", "text": "知っている。"}, {"id": "ch16-s01-p079", "type": "text", "text": "嘆いて止まることはできない。それはわかっている。十四章の夜、第一監視哨で「今を掴む」と決めた。今がある。今を動かすことしかできない。"}, {"id": "ch16-s01-p080", "type": "text", "text": "しかし——何を掴むべきか。どこに足を運ぶべきか。"}, {"id": "ch16-s01-p081", "type": "text", "text": "全員の顔が等しい重さで浮かんでいて、どれかを先に選ぶことが、残りを後に回すことを意味する。後に回せば、間に合わなくなるものがあるかもしれない。"}, {"id": "ch16-s01-p082", "type": "text", "text": "目を開けた。"}, {"id": "ch16-s01-p083", "type": "text", "text": "冬の空が枝の間に見えた。灰色の空。残響桜の枝が細く伸びて、空を区切っている。葉のない枝。花のない枝。しかし折れていない枝。春を待っている枝。"}, {"id": "ch16-s01-p084", "type": "text", "text": "立ち上がった。"}, {"id": "ch16-s01-p085", "type": "text", "text": "ベンチの木が軋んだ。足が石畳を踏んだ。枯れ葉を一枚踏んだ。薄紫の葉が音もなく割れた。"}, {"id": "ch16-s01-p086", "type": "text", "text": "方向は決まっていなかった。何を掴むかもまだわからなかった。"}, {"id": "ch16-s01-p087", "type": "text", "text": "足だけが動いた。「動く」という判断だけが、今の俺にある唯一のものだった。立ち止まれば処理未完了の堆積に沈む。沈んだら誰の手にも届かない。"}, {"id": "ch16-s01-p088", "type": "text", "text": "中庭を横切った。石畳の上を歩く。裸木の桜が後ろに遠ざかる。足音だけが十二月の昼に落ちていく。"}]}, {"chapter": 16, "chapterTitle": "誰の側に", "scene": 2, "sceneTitle": "千歳の決意", "wordCount": "約5,200字", "paragraphs": [{"id": "ch16-s02-p001", "type": "text", "text": "足が向かった先は、医務室だった。"}, {"id": "ch16-s02-p002", "type": "text", "text": "中庭を横切り、石畳を抜け、教室棟の一階廊下に入った。廊下の残響灯が昼の光と混ざって白い。十二月の窓から差す陽が低く、床に長い四角を落としている。壁の掲示物の前を通り過ぎた。何枚か紙が増えていた。避難者の受け入れ先一覧。読まなかった。足が先に動いていた。"}, {"id": "ch16-s02-p003", "type": "text", "text": "方向を決めていなかった。中庭のベンチで立ち上がった時、何を掴むかもまだわからなかった。わからないまま足が選んだのが、この廊下だった。"}, {"id": "ch16-s02-p004", "type": "text", "text": "鳩尾の上が灼けている。鳴海さんの歌の残響。昨夜の共鳴の間で聴いた声が、十二時間以上経ってもまだそこにある。消えない。消えないから、足がそこに向かった。歌った人のいる場所に。"}, {"id": "ch16-s02-p005", "type": "text", "text": "医務室の扉は閉まっていた。"}, {"id": "ch16-s02-p006", "type": "text", "text": "磨りガラスに「医務室」の白い文字。扉の取っ手に手をかけた。冷たい金属。手を止めた。"}, {"id": "ch16-s02-p007", "type": "text", "text": "何を言えばいいのか考えた。面会の理由を。業務上の訪問ではない。補佐官が共鳴者の容体を確認する義務は書類上にない。"}, {"id": "ch16-s02-p008", "type": "text", "text": "理由がなくても扉を開けた。"}, {"id": "ch16-s02-p009", "type": "break", "text": "◇"}, {"id": "ch16-s02-p010", "type": "text", "text": "消毒液の匂いが鼻の粘膜に触れた。"}, {"id": "ch16-s02-p011", "type": "text", "text": "白いカーテン。白いシーツ。白い壁。窓から入る十二月の光が、白い布地の上を薄く這っている。冬の午後の光。黄色みのない、冷たい白。"}, {"id": "ch16-s02-p012", "type": "text", "text": "ベッドが三つ並んでいた。手前の二つは空。奥の一つに人がいた。"}, {"id": "ch16-s02-p013", "type": "text", "text": "鳴海さんが横たわっていた。"}, {"id": "ch16-s02-p014", "type": "text", "text": "白いシーツの上に亜麻色の髪が散っている。枕の白と髪の薄い金の対比。右前髪のリボンは外されている。チョーカーは首元にあった。銀の表面が窓の光を反射して鈍く光っている。"}, {"id": "ch16-s02-p015", "type": "text", "text": "顔を見た。"}, {"id": "ch16-s02-p016", "type": "text", "text": "蒼白だった。"}, {"id": "ch16-s02-p017", "type": "text", "text": "白い、ではなかった。五月の残響祭の公演後、残響灯の下で見た肌の色とも、十一月の選抜公演の後に見た青白さとも違った。色の名前がつけにくい。血が通っている皮膚の色から、何か一段階抜けている。蝋のような白さ。頬の輪郭がはっきりしすぎている。皮膚の下にあるはずの厚みが減っている。"}, {"id": "ch16-s02-p018", "type": "text", "text": "唇の色が薄かった。赤みがほとんどない。白い顔の中で、唇だけが別の色を持っているはずなのに、境界が曖昧になっていた。"}, {"id": "ch16-s02-p019", "type": "text", "text": "ベッドの右側に椅子があった。木の丸椅子。そこに風祭さんが座っていた。"}, {"id": "ch16-s02-p020", "type": "text", "text": "前傾姿勢。両手が膝の上にあり、膝の上から先に——鳴海さんの左手を握っていた。鳴海さんの手が毛布の上に出ている。その手を、風祭さんの両手が包んでいた。"}, {"id": "ch16-s02-p021", "type": "text", "text": "風祭さんが顔を上げた。"}, {"id": "ch16-s02-p022", "type": "text", "text": "俺を見た。翡翠色の目が赤かった。泣き腫らしている。瞼が膨れて、白目に血管が浮いている。頬に涙の跡が何本もある。乾いては新しい涙が上書きし、を繰り返した跡。昨夜から、あるいは今朝から、何時間泣いていたのかわからない。"}, {"id": "ch16-s02-p023", "type": "text", "text": "風祭さんは何も言わなかった。俺を見て、また鳴海さんの手に視線を戻した。声を出さないのは声が出ないからではなかった。出さないことを選んでいた。千歳のそばで、声を立てず、手を離さず、ただいる。それが風祭さんの今の形だった。"}, {"id": "ch16-s02-p024", "type": "text", "text": "ジャケットの襟元が乱れていた。昨夜の服のまま着替えていない。パジャマの上にジャケットを羽織った、合っていない組み合わせ。十五章の共鳴の間に駆けつけた時と同じ格好。あれから十二時間以上、この椅子にいたのか。"}, {"id": "ch16-s02-p025", "type": "text", "text": "俺はベッドの足元側に立った。"}, {"id": "ch16-s02-p026", "type": "text", "text": "鳴海さんの手が見えた。風祭さんの手の間にある、鳴海さんの左手。左手首にミサンガが巻かれていた。風祭さんの右手首にも同じものがある。二人で編んだミサンガ。願いが叶ったら切れる。"}, {"id": "ch16-s02-p027", "type": "text", "text": "鳴海さんの指が細かった。五月に初めて見た手。掌を客席に向けていた手。十一月にステージの床に触れた手。昨夜、共鳴の間で体の横に下げて痙攣していた手。"}, {"id": "ch16-s02-p028", "type": "text", "text": "今は動いていない。風祭さんの掌の中で静かに横たわっている。"}, {"id": "ch16-s02-p029", "type": "text", "text": "シーツの皺に影が落ちている。窓の光が斜めに差して、鳴海さんの髪の影がシーツの上に長い線を描いている。静かだった。消毒液の匂いと、窓の外の風の音だけがある。"}, {"id": "ch16-s02-p030", "type": "text", "text": "鳴海さんの瞼が動いた。"}, {"id": "ch16-s02-p031", "type": "text", "text": "微かだった。左の瞼が先にわずかに上がり、右が追いかけた。目の下の皮膚に薄い紫の影がある。"}, {"id": "ch16-s02-p032", "type": "text", "text": "琥珀色の瞳が見えた。"}, {"id": "ch16-s02-p033", "type": "text", "text": "——薄かった。"}, {"id": "ch16-s02-p034", "type": "text", "text": "五月の残響祭で見た琥珀色。六月の共鳴室で見た琥珀色。十一月の楽屋の前で見た、水で割ったような琥珀色。昨夜の共鳴の間で一瞬だけ開いた目の、色がほとんど残っていない瞳。"}, {"id": "ch16-s02-p035", "type": "text", "text": "今は、昨夜とほぼ同じだった。薄い。水で割ったどころではない。琥珀の残滓のような色。光の加減で灰色にも見える。"}, {"id": "ch16-s02-p036", "type": "text", "text": "その瞳が、俺を見た。"}, {"id": "ch16-s02-p037", "type": "text", "text": "鳴海さんの唇が動いた。"}, {"id": "ch16-s02-p038", "type": "text", "text": "「蓮さん……」"}, {"id": "ch16-s02-p039", "type": "text", "text": "声が出た。小さかった。掠れていた。昨夜の歌声とは別物だった。九階の球形空間を震わせた声の面影はない。ベッドの上の二文字分の声は、紙を折る音のように薄い。"}, {"id": "ch16-s02-p040", "type": "text", "text": "けれど温度があった。紙は冷たいはずだった。この声はぬるかった。ぬるい声。ぬるい水。冬の水道水より一度か二度だけ高い。一度か二度の温度が、鳴海さんの声だった。"}, {"id": "ch16-s02-p041", "type": "text", "text": "微笑んでいた。"}, {"id": "ch16-s02-p042", "type": "text", "text": "蒼白い顔の中で、口元と目がほぼ同時に動いている。穏やかな微笑み。いつもの鳴海さんの微笑み。ステージで歌い終わった後に八百人に向けた微笑み。医務室のベッドの上で意識を取り戻した直後に——同じ笑顔。"}, {"id": "ch16-s02-p043", "type": "text", "text": "顔色との差が残酷だった。笑顔だけが元の鳴海さんの色をしていて、顔の残りの部分が色を失っている。"}, {"id": "ch16-s02-p044", "type": "text", "text": "「蓮さん」"}, {"id": "ch16-s02-p045", "type": "text", "text": "もう一度。名前を呼ぶ時の声。掠れているが、二度目の方がわずかに厚みがあった。声帯が起き始めている。"}, {"id": "ch16-s02-p046", "type": "text", "text": "「わたし……まだ歌えますか」"}, {"id": "ch16-s02-p047", "type": "text", "text": "風祭さんの肩が跳ねた。"}, {"id": "ch16-s02-p048", "type": "text", "text": "小さな動き。椅子に座ったまま、肩が一回だけ上に動いた。両手は鳴海さんの手を握ったまま。指に力が入ったのが見えた。指の関節が白くなった。十一月の廊下で俺が握った拳の白さと同じ。"}, {"id": "ch16-s02-p049", "type": "text", "text": "俺は言葉が出なかった。"}, {"id": "ch16-s02-p050", "type": "text", "text": "歌えますか。その問いに対する答えを、俺は持っている。持っている知識が答えを塞いでいる。命を削っている。歌うたびに。鳴海美弦は同じ力で三十二歳で死んだ。身体負荷指数47。不可逆。知っていて歌わせていた。"}, {"id": "ch16-s02-p051", "type": "text", "text": "知っているから、歌えますかに「はい」と言えなかった。「いいえ」とも言えなかった。鳴海さんの問いは、体の状態を聞いているのではなかった。"}, {"id": "ch16-s02-p052", "type": "text", "text": "鳴海さんが自分の右手を持ち上げた。毛布の上から。ゆっくりと。手を目の前に持ってきた。掌を上に向けた。指が震えていた。五本の指が微細に振れている。不規則な振れ。昨夜の共鳴の間で見た痙攣よりは小さいが、止まっていない。"}, {"id": "ch16-s02-p053", "type": "text", "text": "鳴海さんはその震えを見つめていた。自分の指を。琥珀の残滓のような瞳で。"}, {"id": "ch16-s02-p054", "type": "text", "text": "「震えてますね」"}, {"id": "ch16-s02-p055", "type": "text", "text": "声に驚きはなかった。確認だった。自分の体に起きていることを、静かに確認している。"}, {"id": "ch16-s02-p056", "type": "text", "text": "震える手を下ろした。毛布の上に戻した。"}, {"id": "ch16-s02-p057", "type": "text", "text": "俺を見た。"}, {"id": "ch16-s02-p058", "type": "text", "text": "鳴海さんの目の中に、覚悟があった。覚悟という言葉が正確かどうかはわからない。けれど——残響祭のステージの上で八百人を見ていた目とも、選抜公演で自分の歌声だけを見ていた目とも違った。今の目は、目の前の一人だけを見ていた。俺を。"}, {"id": "ch16-s02-p059", "type": "text", "text": "「蝕域は、また来ます」"}, {"id": "ch16-s02-p060", "type": "text", "text": "声が低かった。掠れの中に、芯が一本通っていた。"}, {"id": "ch16-s02-p061", "type": "text", "text": "「その時、また誰かが歌わないと……この島が」"}, {"id": "ch16-s02-p062", "type": "text", "text": "風祭さんの顔が歪んだ。目を閉じた。閉じた目の端から新しい涙が頬を伝った。音はなかった。声を出さずに泣いていた。"}, {"id": "ch16-s02-p063", "type": "text", "text": "鳴海さんの左手が、風祭さんの手を握り返していた。弱い力。けれど握り返している。風祭さんの涙を見ていた。見て、握った。"}, {"id": "ch16-s02-p064", "type": "text", "text": "「わたしは歌いたいんです。蓮さん」"}, {"id": "ch16-s02-p065", "type": "text", "text": "声が少しだけ上がった。音量ではない。声の位置が。喉の奥から、もう少し前に出てきた。"}, {"id": "ch16-s02-p066", "type": "text", "text": "「誰かに言われたからじゃなく」"}, {"id": "ch16-s02-p067", "type": "text", "text": "手が毛布の上で拳になった。震える指が、自分の掌を握りしめていた。力は弱い。握りしめるだけの筋力が残っていない。けれど形は拳だった。"}, {"id": "ch16-s02-p068", "type": "text", "text": "「わたしが、歌いたい」"}, {"id": "ch16-s02-p069", "type": "text", "text": "鳴海さんの目は濡れていなかった。泣いてはいなかった。蒼白い顔の中で、薄い琥珀色の瞳だけが色を持っていた。色を、と言うのは正確ではないかもしれない。琥珀の色は薄れている。けれどその薄い色の奥に、光がある。窓から差す冬の光の反射ではない。瞳の奥にあるもの。意志。"}, {"id": "ch16-s02-p070", "type": "text", "text": "犠牲ではなかった。"}, {"id": "ch16-s02-p071", "type": "text", "text": "鳴海さんの「歌いたい」は、島を守るために命を差し出す宣言ではなかった。もっと単純なものだった。灯籠通りの分岐で「歌うことが、好きなんです」と微笑んだ時の声。共鳴室で「わたしは……好きです」と言った時の声。その延長にある「歌いたい」。好きだから歌いたい。それだけだった。"}, {"id": "ch16-s02-p072", "type": "text", "text": "それだけのことが——重かった。重い、は正確ではない。軽かった。鳴海さんの「歌いたい」は軽い。羽根のように軽い。好きだから歌いたい。それだけ。けれどその軽さが、俺の中では重量に変換されていた。軽いものが鳩尾に落ちて、重く灼ける。"}, {"id": "ch16-s02-p073", "type": "text", "text": "五月。残響祭。響弦館の八百席の端で、初めて鳴海さんの歌を聴いた。鳩尾が緩んだ。目の奥が熱くなった。涙が出そうで——出なかった。蛇口はある。水はある。管が詰まっている。"}, {"id": "ch16-s02-p074", "type": "text", "text": "十一月。選抜公演。同じ席で同じ歌を聴いた。管が通った。涙が出た。初めて泣いた。"}, {"id": "ch16-s02-p075", "type": "text", "text": "今。"}, {"id": "ch16-s02-p076", "type": "text", "text": "医務室のベッドの上で、蒼白い顔の鳴海さんが「歌いたい」と言った。歌声ではなかった。掠れた、紙のような声だった。けれどその声を聴いた時——管が震えた。昨夜の歌声が通った場所と同じ管。歌っていないのに震えている。声の中にある歌声の残響が、管を通って、俺の中に届いている。"}, {"id": "ch16-s02-p077", "type": "text", "text": "五月は「出なかった」。十一月は「出た」。"}, {"id": "ch16-s02-p078", "type": "text", "text": "今は——出る出ないの話ではなかった。鳩尾の上の灼熱が胸の全体に広がっていた。肋骨の内側に。鎖骨の下に。肩甲骨の間に。管を通って入ってきたものが一箇所に留まらず、胸の中を満たしている。灼ける。鳴海さんの「歌いたい」が灼けている。"}, {"id": "ch16-s02-p079", "type": "text", "text": "風祭さんが俺を見た。"}, {"id": "ch16-s02-p080", "type": "text", "text": "泣き腫らした翡翠色の目。涙が頬を伝ったまま、拭わずに俺を見ていた。目の中にあるものが——二つあった。"}, {"id": "ch16-s02-p081", "type": "text", "text": "止めたい。止められない。"}, {"id": "ch16-s02-p082", "type": "text", "text": "その二つが同じ目の中に同居していた。鳴海さんの「歌いたい」を知っている。二年間見てきたから知っている。歌いたいから歌う千歳を止める権利がないことも知っている。知っていて、それでも止めたい。止めたいのに止められない。十一月の廊下で俺に秘密を預けた人の目。あの目が今、俺に向けられていた。"}, {"id": "ch16-s02-p083", "type": "text", "text": "お前はどうする。"}, {"id": "ch16-s02-p084", "type": "text", "text": "声には出ていなかった。風祭さんは何も言わなかった。泣いたまま、俺を見ていた。翡翠色の目の中にあるのは問いだった。問いかける言葉がなくても、目が問いていた。"}, {"id": "ch16-s02-p085", "type": "text", "text": "鳴海さんの左手首のミサンガが見えていた。毛布の上。風祭さんの手に包まれた手首。編み目が少し毛羽立っている。二年間巻き続けた布の消耗。願いが叶ったら切れる。"}, {"id": "ch16-s02-p086", "type": "text", "text": "切れていない。"}, {"id": "ch16-s02-p087", "type": "text", "text": "鳴海さんの「歌いたい」を聴いた。風祭さんの涙を見た。二つが俺の中で重なっている。鳩尾の熱と、風祭さんの目の中の問いが。"}, {"id": "ch16-s02-p088", "type": "text", "text": "口を開いた。"}, {"id": "ch16-s02-p089", "type": "text", "text": "何を言ったのか——正確には覚えていない。短かった。一文か二文。鳴海さんの目を見て、言葉を出した。出した言葉が何だったかは、廊下に出た後には曖昧になっていた。けれど鳴海さんが微笑んだ。蒼白い顔の中の、いつもの穏やかな微笑み。風祭さんの手を握ったまま。目を閉じた。眠りに落ちるように。"}, {"id": "ch16-s02-p090", "type": "text", "text": "医務室の扉を閉めた。"}, {"id": "ch16-s02-p091", "type": "text", "text": "廊下に出た。十二月の午後の光が窓から差している。廊下の残響灯が白い。消毒液の匂いが鼻から消えるまでに三歩かかった。"}, {"id": "ch16-s02-p092", "type": "text", "text": "四歩目で立ち止まった。"}, {"id": "ch16-s02-p093", "type": "text", "text": "鳩尾の上が重かった。"}, {"id": "ch16-s02-p094", "type": "text", "text": "昨夜からの鳴海さんの歌声の残響。それに今、「歌いたい」の声が重なっている。掠れた二文字の名前と、震える手と、薄い琥珀の瞳の奥にあった光が、全部鳩尾の上に堆積している。"}, {"id": "ch16-s02-p095", "type": "text", "text": "その堆積から——熱が広がっていた。医務室の中で感じた、胸全体に広がる熱。それがまだ消えていない。廊下に出ても消えない。歩いても消えない。肋骨の内側の燈花の氷の石の横を、鳴海さんの熱が通過している。背中の奥の霜月さんの覚悟の横を、通過している。全部の場所を通って、胸の中に充満している。"}, {"id": "ch16-s02-p096", "type": "text", "text": "名前はつけなかった。"}, {"id": "ch16-s02-p097", "type": "text", "text": "名前をつけようとしなかった。灼けている。それだけが確かで、名前が何であるかは後でいい。後でいいと判断できること自体が——響弦館で初めて歌を聴いたあの頃とは違っていた。あの頃は「名前がつけられない」だった。名前がないことが苦しかった。今は名前がなくても灼けている事実だけで足りていた。"}, {"id": "ch16-s02-p098", "type": "text", "text": "窓の外を見た。"}, {"id": "ch16-s02-p099", "type": "text", "text": "十二月の空が冬の色をしていた。灰色と青の間。残響桜の裸木の枝が中庭の向こうに見えていた。枝は折れていない。春を待っている枝。"}, {"id": "ch16-s02-p100", "type": "text", "text": "医務室の中には、鳴海さんと風祭さんがいる。鳴海さんは眠っている。風祭さんは手を握っている。その二人の間にある時間が、俺がいなくても続いている。二年間続いてきたように。"}, {"id": "ch16-s02-p101", "type": "text", "text": "足が動いた。"}]}, {"chapter": 16, "chapterTitle": "誰の側に", "scene": 3, "sceneTitle": "雫の揺らぎ", "wordCount": "約5,900字", "paragraphs": [{"id": "ch16-s03-p001", "type": "text", "text": "足が選んだのは、図書館だった。"}, {"id": "ch16-s03-p002", "type": "text", "text": "医務室を出てから一時間が経っていた。廊下を歩き、中庭を横切り、補佐官舎に戻り、報告書に手をつけた。手は動いていた。ペンが紙の上を走っていた。しかし鳩尾の上の灼熱がずっと消えなかった。鳴海さんの「歌いたい」が胸の中に満ちたまま、報告書の数字を写していた。"}, {"id": "ch16-s03-p003", "type": "text", "text": "ペンを置いた。"}, {"id": "ch16-s03-p004", "type": "text", "text": "紙の上に書いた字が視界に入った。正確だった。正確であることに安心も不安もなかった。ただ、ペンを持つ手が——次に向かいたい場所を知っていた。"}, {"id": "ch16-s03-p005", "type": "text", "text": "耳の位置が鳴っていた。"}, {"id": "ch16-s03-p006", "type": "text", "text": "鐘鋳塔の方角ではない。教室棟でもない。図書館の方角。二階の奥。書架の列を抜けた先の、四畳半ほどの部屋。あの部屋のペンの音を、俺の耳が探している。"}, {"id": "ch16-s03-p007", "type": "text", "text": "昨夜の縁蝕波から十二時間以上が経っている。蝕域は辛うじて押し返された。しかし篠宮さんの指先が透けたのは、あの夜の明け方だった。蝕域が最大出力を叩き出した直後だった。"}, {"id": "ch16-s03-p008", "type": "text", "text": "あれから半日。篠宮さんは——記録室にいるだろう。いつもいる場所に。"}, {"id": "ch16-s03-p009", "type": "text", "text": "立ち上がった。補佐官舎を出て、図書館に向かった。"}, {"id": "ch16-s03-p010", "type": "break", "text": "◇"}, {"id": "ch16-s03-p011", "type": "text", "text": "十二月の午後の図書館は静かだった。"}, {"id": "ch16-s03-p012", "type": "text", "text": "一階の閲覧室に生徒の姿はなかった。昨夜の縁蝕波で図書館は臨時休館になったはずだが、受付の向こうに司書の女性が一人座っていた。俺を見て頷いた。二階の記録室へ行くことは、もう顔で通っていた。"}, {"id": "ch16-s03-p013", "type": "text", "text": "階段を上がった。二階の書架の間を歩いた。残響灯の青白い光が棚の端から漏れている。足を踏むたびに木の床が小さく鳴る。窓から入る光は白かった。冬の午後の光。黄色みのない、乾いた白。"}, {"id": "ch16-s03-p014", "type": "text", "text": "2-A。2-B。2-C。通路を抜けるごとに光が減る。残響灯が手元を照らす範囲に世界が縮む。"}, {"id": "ch16-s03-p015", "type": "text", "text": "記録室の扉が見えた。"}, {"id": "ch16-s03-p016", "type": "text", "text": "十センチほど開いていた。いつもの幅。篠宮さんが中にいる時の、扉の角度。"}, {"id": "ch16-s03-p017", "type": "text", "text": "音が聞こえた。"}, {"id": "ch16-s03-p018", "type": "text", "text": "かりかり。"}, {"id": "ch16-s03-p019", "type": "text", "text": "ペンの音。俺の耳が九ヶ月間聴き続けてきた音。しかし——間隔が遅かった。いつもの篠宮さんのペンは一定間隔で紙を引っ掻く。文字の画数に応じてわずかに変化するが、基本のリズムは揺るがない。今日のリズムは——倍、とは言わないまでも、いつもの速度の半分に近かった。一画書いて、間がある。次の一画まで空白がある。空白の長さが不均等だった。"}, {"id": "ch16-s03-p020", "type": "text", "text": "扉の前に立った。"}, {"id": "ch16-s03-p021", "type": "text", "text": "中を覗いた。"}, {"id": "ch16-s03-p022", "type": "text", "text": "篠宮さんが机に向かっていた。いつもの姿勢。椅子に座り、メモ帳を開き、ペンを右手に持っている。灰色のエプロンの紐が背中の蝶結びになっていた。首から下がった銀色の鍵が、窓から差す光を鈍く反射していた。"}, {"id": "ch16-s03-p023", "type": "text", "text": "動きが遅い。"}, {"id": "ch16-s03-p024", "type": "text", "text": "ペンが紙から上がる時間が長い。書いている文字の数が少ない。いつもの篠宮さんは一時間でメモ帳の五ページから七ページを埋める。机の上に開いたメモ帳を見た。今日の記録は——二ページ。窓の光の角度からして、ここに座ってから一時間以上は経っているはずだった。"}, {"id": "ch16-s03-p025", "type": "text", "text": "「篠宮さん」"}, {"id": "ch16-s03-p026", "type": "text", "text": "声をかけた。"}, {"id": "ch16-s03-p027", "type": "text", "text": "ペンの音が止まった。"}, {"id": "ch16-s03-p028", "type": "text", "text": "篠宮さんがゆっくり振り返った。"}, {"id": "ch16-s03-p029", "type": "text", "text": "——ゆっくり。"}, {"id": "ch16-s03-p030", "type": "text", "text": "いつもの篠宮さんは、呼ばれたら視線の移動が正確だった。体は後から付いてくるが、目は即座にこちらを向く。四月の終わり、記録室で初めて会った時からそうだった。"}, {"id": "ch16-s03-p031", "type": "text", "text": "今日は違った。首が回り、肩が回り、目が来るまでに二拍の間があった。二拍の間、篠宮さんの墨色の瞳はどこか別の場所を見ていた。メモ帳でも壁でも窓でもない場所。十四章の外円区で見た、あのぼんやりと同じ種類の空白。"}, {"id": "ch16-s03-p032", "type": "text", "text": "目が合った。"}, {"id": "ch16-s03-p033", "type": "text", "text": "そのとき——"}, {"id": "ch16-s03-p034", "type": "text", "text": "篠宮さんの全身が、薄くなった。"}, {"id": "ch16-s03-p035", "type": "text", "text": "手だけではなかった。"}, {"id": "ch16-s03-p036", "type": "text", "text": "右手だけが透けた明け方の五時半とは違った。篠宮さんの体の全体——紺の制服の肩、灰色のエプロンの胸元、膝丈のスカートの裾、椅子に触れている手、ペンを握った指先——の輪郭が、一斉にぼやけた。色が抜けるのとは違う。存在の「濃さ」が下がった。一枚の薄い膜を通して向こう側を見ているような。篠宮さんの体を通して、背後の棚の木目がわずかに透けていた。完全な透過ではない。磨りガラスよりもっと曖昧な。しかし——見えた。"}, {"id": "ch16-s03-p037", "type": "text", "text": "一秒。二秒。"}, {"id": "ch16-s03-p038", "type": "text", "text": "呼吸を忘れていた。"}, {"id": "ch16-s03-p039", "type": "text", "text": "三秒。"}, {"id": "ch16-s03-p040", "type": "text", "text": "戻った。"}, {"id": "ch16-s03-p041", "type": "text", "text": "篠宮さんの輪郭が元に戻っていた。紺の制服は紺の色をしていた。灰色のエプロンは灰色をしていた。手にペンがあり、首に鍵があり、背筋がわずかに前かがみで、椅子の上に座った小柄な体が——ここにあった。"}, {"id": "ch16-s03-p042", "type": "text", "text": "見間違いだと——もう言えなかった。"}, {"id": "ch16-s03-p043", "type": "text", "text": "十一月。外円区の帰り道で篠宮さんの輪郭が一瞬揺らいだ。光の加減だと処理した。"}, {"id": "ch16-s03-p044", "type": "text", "text": "十二月。手が震え、ペンのリズムが崩れ、声が薄くなった。光の加減ではなかったと修正した。"}, {"id": "ch16-s03-p045", "type": "text", "text": "明け方。右手の指先が透けた。二秒か三秒。向こう側の木目が見えた。「何かが起きている」と確信した。"}, {"id": "ch16-s03-p046", "type": "text", "text": "今——全身が薄くなった。四度目。手だけではない。篠宮さんの存在の全体が、一瞬だけ、この世界から後退した。"}, {"id": "ch16-s03-p047", "type": "text", "text": "「……朝霧さん。今日は記録の量が多くて」"}, {"id": "ch16-s03-p048", "type": "text", "text": "声が届いた。"}, {"id": "ch16-s03-p049", "type": "text", "text": "薄かった。明け方の外円区で聞いた声よりさらに薄い。声の芯が残っていなかった。篠宮さんの声にはいつも、壁に届かない音量の中にも硬い芯があった。今日の声は芯ごと薄れている。綿を通した後の音のように、輪郭が溶けていた。"}, {"id": "ch16-s03-p050", "type": "text", "text": "篠宮さんは普段通りに話そうとしていた。記録の量が多い。それだけの報告。事実を正確に伝えようとする、記録係の声。"}, {"id": "ch16-s03-p051", "type": "text", "text": "しかしその声を出している人の体が、三秒前に透けていた。"}, {"id": "ch16-s03-p052", "type": "text", "text": "「篠宮さん」"}, {"id": "ch16-s03-p053", "type": "text", "text": "俺は記録室に入った。扉を押し開けて、机の前に立った。篠宮さんとの距離は三歩。窓から差す十二月の光が、篠宮さんの黒い髪を横から照らしている。前髪の直線。顎の線で切り揃えられたボブカット。墨色の瞳が俺を見ていた。今は焦点が合っていた。"}, {"id": "ch16-s03-p054", "type": "text", "text": "「教えてくれ」"}, {"id": "ch16-s03-p055", "type": "text", "text": "声が出た。乾いていた。明け方に同じ場所で声を出した時と同じ乾き方。"}, {"id": "ch16-s03-p056", "type": "text", "text": "「篠宮さん。……お前は、何者なんだ」"}, {"id": "ch16-s03-p057", "type": "text", "text": "何者。"}, {"id": "ch16-s03-p058", "type": "text", "text": "言ってから、自分の声の重さに気づいた。何者、という言葉を篠宮さんに向けたのは初めてだった。四月から九ヶ月の間、記録室で横に座り、ペンの音を聴き、清書を手伝い、消えた人々の声を一緒に聴いてきた。篠宮さんの記録を読み、篠宮さんの声を耳に溜めてきた。"}, {"id": "ch16-s03-p059", "type": "text", "text": "そのうえで——何者、と聞いている。篠宮さんを傷つける問いかもしれなかった。記録係であり司書助手であり篠宮雫であるこの人に、お前は何者だ、と問うことが何を意味するか。わかっていて聞いた。"}, {"id": "ch16-s03-p060", "type": "text", "text": "黙っていられなかった。"}, {"id": "ch16-s03-p061", "type": "text", "text": "手が透けた。指先だけではなく。全身が。篠宮さんの存在が薄くなるのを、四度見た。四度見て、原因がわからない。わからないまま黙って隣に座り続けることが——できなくなっていた。"}, {"id": "ch16-s03-p062", "type": "text", "text": "記録室が静かだった。"}, {"id": "ch16-s03-p063", "type": "text", "text": "ペンの音がない。窓の外の風の音だけがある。十二月の午後の風。乾いた空気が窓の隙間から入ってきて、メモ帳のページの端を微かに揺らしている。"}, {"id": "ch16-s03-p064", "type": "text", "text": "篠宮さんが動きを止めていた。"}, {"id": "ch16-s03-p065", "type": "text", "text": "ペンを持った右手。メモ帳を押さえた左手。首から下がった銀の鍵。全てが静止していた。呼吸すら止まっているように見えた。"}, {"id": "ch16-s03-p066", "type": "text", "text": "十秒。"}, {"id": "ch16-s03-p067", "type": "text", "text": "長い十秒だった。篠宮さんが動かない間、俺は篠宮さんの目を見ていた。墨色の瞳。感情を映さない、と周囲には思われている目。俺は知っている。この目は感情を映す。映し方が極めて微細なだけで、瞳の奥の光の揺らぎを読めば——今、揺れていた。"}, {"id": "ch16-s03-p068", "type": "text", "text": "「……私は、篠宮雫です」"}, {"id": "ch16-s03-p069", "type": "text", "text": "声が出た。"}, {"id": "ch16-s03-p070", "type": "text", "text": "平坦だった。いつもの篠宮さんの返答に近いトーンだった。名前を名乗る声。四月の終わりに記録室で初めて会った時と同じ形式——自分が何者であるかの、正確な伝達。"}, {"id": "ch16-s03-p071", "type": "text", "text": "けれど。"}, {"id": "ch16-s03-p072", "type": "text", "text": "声の奥に、今まで聞いたことのない色が混じっていた。九ヶ月間、この人の声を聴いてきた耳が——知らない色を拾った。"}, {"id": "ch16-s03-p073", "type": "text", "text": "不安。"}, {"id": "ch16-s03-p074", "type": "text", "text": "篠宮さんの声に、不安があった。"}, {"id": "ch16-s03-p075", "type": "text", "text": "九章で少女の記録を読んだ時、声の底に震えがあった。あれは篠宮さん自身が気づいていない震えだった。今の不安は、それとは違った。気づいている。篠宮さんは自分の声に不安が混じっていることを——知っていた。知っていて、声に出した。"}, {"id": "ch16-s03-p076", "type": "text", "text": "「私は……何なのだろう」"}, {"id": "ch16-s03-p077", "type": "text", "text": "篠宮さんの唇が動いた。"}, {"id": "ch16-s03-p078", "type": "text", "text": "声が変わっていた。平坦が崩れていた。「何なのだろう」の「ろう」が語尾で沈んだ。疑問形ではなかった。問いかけでもなかった。自分の中から出てきた言葉に、自分で驚いているような——戸惑いの形をしていた。"}, {"id": "ch16-s03-p079", "type": "text", "text": "「朝霧さん」"}, {"id": "ch16-s03-p080", "type": "text", "text": "呼ばれた。篠宮さんの墨色の目が俺を見ていた。まっすぐ。焦点がずれていない。今この瞬間、篠宮さんは俺を見ていた。"}, {"id": "ch16-s03-p081", "type": "text", "text": "「最近、私は……自分が、ここにいるのかどうか、わからなくなる時がある」"}, {"id": "ch16-s03-p082", "type": "text", "text": "声は薄かった。しかし途切れなかった。篠宮さんは最後まで言い切った。"}, {"id": "ch16-s03-p083", "type": "text", "text": "ここにいるのかどうか、わからなくなる。"}, {"id": "ch16-s03-p084", "type": "text", "text": "耳の中で篠宮さんの声が反復していた。ここにいるのかどうか。この部屋に、この図書館に、この島に——ここに。篠宮さんが「ここ」と言った時の「ここ」は、場所ではなかった。もっと根本的な場所だった。存在している、ということの場所。"}, {"id": "ch16-s03-p085", "type": "text", "text": "篠宮さんのペンを持つ手が、震えていた。"}, {"id": "ch16-s03-p086", "type": "text", "text": "ペンを持ったまま震えていた。十四章の外円区で見た震え。あの時は指先から手全体に広がっていた。今は——手首まで来ていた。手首から先が、かすかに不規則に揺れている。ペンの先端が紙の上で小さな弧を描いていた。"}, {"id": "ch16-s03-p087", "type": "text", "text": "しかし——ペンを離さなかった。"}, {"id": "ch16-s03-p088", "type": "text", "text": "篠宮さんの指は震えていた。けれど五本の指がペンを握る力は残っていた。離さない。記録室の机の上のメモ帳の上に、ペンが接地したまま。この人は、何が起きても記録の道具を手放さない。二十三冊分のメモ帳。三千六百八十人の名前。その全ての記録を支えてきた手が、震えながらペンを握っている。"}, {"id": "ch16-s03-p089", "type": "text", "text": "俺は黙っていた。"}, {"id": "ch16-s03-p090", "type": "text", "text": "「何者でもいい」とは言えなかった。それは篠宮さんの問いに対する答えにならない。篠宮さんは「何者でもいい」と言ってほしいのではなかった。篠宮さんが知りたいのは——自分が何であるかだ。わからなくなっていることの恐怖を、取り除いてほしいのではなく、一緒にわからないでいてくれる人間が隣にいることを——"}, {"id": "ch16-s03-p091", "type": "text", "text": "机の上のメモ帳が目に入った。"}, {"id": "ch16-s03-p092", "type": "text", "text": "篠宮さんの記録。二ページ分。いつもの半分以下。文字の間隔が広い。筆跡が乱れている。書き終わりの最後の一画が——いつもは微かに乱れるだけだったものが、今日は字の全体に広がっていた。しかし読める字だった。崩れかけても、読める範囲を保っている。"}, {"id": "ch16-s03-p093", "type": "text", "text": "ペンの音がしていた。"}, {"id": "ch16-s03-p094", "type": "text", "text": "篠宮さんのペンではなかった。俺の指がメモ帳の端に触れていた。篠宮さんの書いた字の横に、俺の指先が置かれていた。"}, {"id": "ch16-s03-p095", "type": "text", "text": "「俺は」"}, {"id": "ch16-s03-p096", "type": "text", "text": "声が出た。"}, {"id": "ch16-s03-p097", "type": "text", "text": "「わからない。篠宮さんが何者か、俺にはわからない」"}, {"id": "ch16-s03-p098", "type": "text", "text": "正直なことを言った。嘘は言えなかった。わかっていないのに「わかっている」とは言えなかった。篠宮さんは記録を歪めない人だった。俺もこの人の前では歪めたくなかった。"}, {"id": "ch16-s03-p099", "type": "text", "text": "「わからないけど」"}, {"id": "ch16-s03-p100", "type": "text", "text": "メモ帳の上の指先が、篠宮さんの文字の横にあった。紙の上。インクの匂い。ペンの引っ掻いた跡が指先に触れていた。"}, {"id": "ch16-s03-p101", "type": "text", "text": "「ここにある。この記録は、ここにある」"}, {"id": "ch16-s03-p102", "type": "text", "text": "篠宮さんの書いた字を指差した。二ページ分の。今日の。消滅した人々の名前と年齢と日付と場所。篠宮さんの手がいつもより遅く、いつもより震えながら書いた記録。それがメモ帳の上にある。"}, {"id": "ch16-s03-p103", "type": "text", "text": "消えていない。"}, {"id": "ch16-s03-p104", "type": "text", "text": "篠宮さんの手が——震えが止まらなかった。しかし止まらない手のまま、ペンの先端がメモ帳の上で静止した。ペン先が紙に触れている。書く姿勢のまま。いつでも書き始められる姿勢のまま。"}, {"id": "ch16-s03-p105", "type": "text", "text": "篠宮さんの目が、メモ帳の上の俺の指先を見ていた。"}, {"id": "ch16-s03-p106", "type": "text", "text": "五秒。"}, {"id": "ch16-s03-p107", "type": "text", "text": "篠宮さんの瞬きが入った。一回。長い瞬き。目を閉じて、開くまでの間に二秒あった。"}, {"id": "ch16-s03-p108", "type": "text", "text": "目が開いた時——墨色の瞳が、わずかに濡れていた。濡れていた、というのは正確ではないかもしれない。光の反射率が変わっていた。瞳の表面に薄い膜が一枚増えたような。涙ではなかった。涙の手前にあるもの。"}, {"id": "ch16-s03-p109", "type": "text", "text": "「……ありがとうございます」"}, {"id": "ch16-s03-p110", "type": "text", "text": "声が小さかった。壁に届かない声のさらに内側。俺と篠宮さんの間の空気だけを振動させる音量。九章の、あの日の「はい」と同じ距離の声。"}, {"id": "ch16-s03-p111", "type": "text", "text": "篠宮さんがペンを動かした。"}, {"id": "ch16-s03-p112", "type": "text", "text": "メモ帳の上。さっき中断した場所から、文字を書き始めた。かりかり。遅い。間隔が不均等。手が震えている。しかし書いている。ここにいるのかどうかわからなくなると言った人が、ここで、記録を書いている。"}, {"id": "ch16-s03-p113", "type": "text", "text": "俺は篠宮さんの横に立ったまま、その音を聴いていた。"}, {"id": "ch16-s03-p114", "type": "text", "text": "ペンの音。紙の音。窓の外の風の音。記録室のいつもの三つの音のうち、俺のペンだけが欠けている。二つの音で、それでも記録室は記録室だった。"}, {"id": "ch16-s03-p115", "type": "text", "text": "三分ほど、そのままでいた。"}, {"id": "ch16-s03-p116", "type": "text", "text": "篠宮さんが三行書いた。三行目を書き終えた時、ペンの間隔がわずかに——ほんのわずかに、いつもの間隔に近づいた。まだ遅い。まだ震えている。けれど、俺が横にいることを耳が拾ったのか、ペンの運びに一本の線が戻り始めていた。"}, {"id": "ch16-s03-p117", "type": "text", "text": "「篠宮さん」"}, {"id": "ch16-s03-p118", "type": "text", "text": "呼んだ。"}, {"id": "ch16-s03-p119", "type": "text", "text": "「明日も来る」"}, {"id": "ch16-s03-p120", "type": "text", "text": "篠宮さんのペンが一拍止まった。"}, {"id": "ch16-s03-p121", "type": "text", "text": "「……はい」"}, {"id": "ch16-s03-p122", "type": "text", "text": "短い返答。いつもの篠宮さんの返答。しかし「はい」の語尾が、さっきの「何なのだろう」よりも——少しだけ近い場所から聞こえた。"}, {"id": "ch16-s03-p123", "type": "text", "text": "記録室を出た。"}, {"id": "ch16-s03-p124", "type": "text", "text": "扉を十センチ開けたまま閉めた。篠宮さんがいる時の幅。書架の間を歩いた。残響灯の青白い光を横切った。階段を降りた。一階の受付の前を通り、図書館の扉を押した。"}, {"id": "ch16-s03-p125", "type": "text", "text": "十二月の午後の空気が顔に触れた。冷たかった。乾いていた。中庭の石畳を踏んだ。"}, {"id": "ch16-s03-p126", "type": "text", "text": "耳の中で音が鳴っていた。"}, {"id": "ch16-s03-p127", "type": "text", "text": "四月からずっと、篠宮さんのペンの音が耳の位置にあった。それは引っかかりの音だった。聴こえるはずのない距離で、耳が探す音。"}, {"id": "ch16-s03-p128", "type": "text", "text": "十一月に、引っかかりが大きくなった。輪郭の揺らぎ。"}, {"id": "ch16-s03-p129", "type": "text", "text": "十二月に、引っかかりが確信に変わった。指先の透過。"}, {"id": "ch16-s03-p130", "type": "text", "text": "今——確信の奥に、別のものが聴こえていた。"}, {"id": "ch16-s03-p131", "type": "text", "text": "篠宮さんの「何なのだろう」。声の中の不安。震える手のまま離さなかったペン。「ここにいるのかどうかわからなくなる」と言った時の、壊れかけた平坦さ。"}, {"id": "ch16-s03-p132", "type": "text", "text": "全部が耳の中にあった。引っかかりとも確信とも違う音になって、耳の奥の篠宮さんの場所に沈んでいた。名前はまだつけなかった。灼熱でも氷でも沈殿物でもない。耳の位置にだけある音。守りたい、に近い。しかしその言葉は正確ではなかった。正確ではない言葉を当てるくらいなら、黙っていたほうがいい。"}, {"id": "ch16-s03-p133", "type": "text", "text": "鳩尾の上はまだ灼けていた。鳴海さんの「歌いたい」が残っている。肋骨の内側は冷たいまま。燈花の「待ってて」が溶けていない。鳩尾の奥には沈殿物。"}, {"id": "ch16-s03-p134", "type": "text", "text": "そして耳の位置に、篠宮さんがいる。"}, {"id": "ch16-s03-p135", "type": "text", "text": "体の中に、処理の終わっていないものが四つある。四つのうちのどれが最も重いかは、比べなかった。重さではない。全部が、ここにある。全部がそれぞれの場所にある。"}, {"id": "ch16-s03-p136", "type": "text", "text": "中庭の向こうに残響桜の裸木が見えた。枝は折れていない。十二月の風に揺れている。"}, {"id": "ch16-s03-p137", "type": "text", "text": "足が動いた。"}]}, {"chapter": 16, "chapterTitle": "誰の側に", "scene": 4, "sceneTitle": "燈花の帰還", "wordCount": "約5,100字", "paragraphs": [{"id": "ch16-s04-p001", "type": "text", "text": "南門に着いたのは十七時を回った頃だった。"}, {"id": "ch16-s04-p002", "type": "text", "text": "中庭を出た後、補佐官舎で二十分ほど報告書の続きを書いた。鐘鋳塔の管理室に寄って第三系統の夕方の記録を取り、当直に引き継ぎをした。体を動かすことで体の中の四つの沈殿を散らそうとしたわけではなかった。ただ、手がやるべきことを探していた。手が止まると、耳が鳴る。鳩尾が灼ける。肋骨の内側が冷たい。体の中の処理されていないものが一斉に主張を始める。だから手を動かした。"}, {"id": "ch16-s04-p003", "type": "text", "text": "当直の鐘守が、情報を一つ落とした。"}, {"id": "ch16-s04-p004", "type": "text", "text": "「南門に避難民が来ています。外円区からの。三十人ほど」"}, {"id": "ch16-s04-p005", "type": "text", "text": "足が向きを変えた。"}, {"id": "ch16-s04-p006", "type": "text", "text": "南門は学院の南端、中円区との境界にある石造りの門だった。普段は学院の出入口として使われているが、今日は違った。門の向こうに広がる南の道路から、人が流れ込んでいた。"}, {"id": "ch16-s04-p007", "type": "text", "text": "石畳の上に泥がある。"}, {"id": "ch16-s04-p008", "type": "text", "text": "靴の跡だった。外円区の赤い土が、石畳の灰色の上に点々と続いている。一つの足跡ではなかった。二十、三十——もっとあった。大きな靴跡。小さな靴跡。引きずったような線。杖をついた丸い点。外円区から中円区まで、この道を歩いてきた人々の靴底が運んだ泥。"}, {"id": "ch16-s04-p009", "type": "text", "text": "門の手前に人の列があった。"}, {"id": "ch16-s04-p010", "type": "text", "text": "疲弊した顔が並んでいた。農作業着の老人。毛布を肩に掛けた女性。腕の中に幼い子供を抱いた父親。子供は泣いていなかった。泣く力が残っていないのか、父親の胸に顔を押しつけたまま動かなかった。列の横に管理局の職員が二人いて、一人がメモ帳に名前を書き、もう一人が毛布と水を配っていた。"}, {"id": "ch16-s04-p011", "type": "text", "text": "十二月の夕暮れ。空がオレンジと灰色に分かれていた。西の稜線に日が落ちかけている。残った光が避難民の顔を横から照らしていた。影が長い。全員の影が東に伸びて、石畳の上で繋がっていた。"}, {"id": "ch16-s04-p012", "type": "text", "text": "列の先頭を見た。列の中ほどを見た。後尾を見た。"}, {"id": "ch16-s04-p013", "type": "text", "text": "いなかった。"}, {"id": "ch16-s04-p014", "type": "text", "text": "燈花の姿がなかった。"}, {"id": "ch16-s04-p015", "type": "text", "text": "肋骨の内側の氷の石が重くなった。"}, {"id": "ch16-s04-p016", "type": "text", "text": "昨夜の通信室で聴いた声が戻ってきた。「待ってて」。ノイズに食われて途切れた声。あの声の後、通信は回復しなかった。朝になって蝕域が後退し、外円区の被害報告が入り始めた。灯里村の名前が報告の中にあった。完全消滅の欄に。"}, {"id": "ch16-s04-p017", "type": "text", "text": "燈花は灯里村に向かっていた。足の悪い老人を迎えに。あの灯りは——窓の向こうで白い光に逆走していた、あの小さな灯りは——"}, {"id": "ch16-s04-p018", "type": "text", "text": "まだ消えていないと、報告には書いてあった。南農道方面の避難民は全員中円区に到達したと、朝の集計にあった。全員。名簿を確認した。「天城燈花」の名前があった。"}, {"id": "ch16-s04-p019", "type": "text", "text": "名前はあった。しかし本人を見ていなかった。"}, {"id": "ch16-s04-p020", "type": "text", "text": "名簿に名前がある。姿は見ていない。十時間以上。名前だけが証拠で、本人の顔を見ていない。"}, {"id": "ch16-s04-p021", "type": "text", "text": "南門の柱に背を預けた。石の冷たさが背中に触れた。十二月の石は冷たい。冷たいことは確認した。確認しても、温かくはならなかった。"}, {"id": "ch16-s04-p022", "type": "text", "text": "列が動いていた。管理局の職員が名前を記録し、毛布を渡し、学院の講堂に案内している。避難民が一人ずつ門をくぐる。農作業着の裾が泥で固まっている。毛布を握る手が赤い。寒さか、それとも——"}, {"id": "ch16-s04-p023", "type": "text", "text": "子供の泣き声がした。"}, {"id": "ch16-s04-p024", "type": "text", "text": "列の後方。父親の腕の中にいた子供ではなかった。別の子供。五歳か六歳。母親の手を握って歩いている。母親のもう片方の手にはバケツが一つ。バケツの中に着替えが詰まっていた。持ち出せたものがそれだけだったのだと、バケツの中身が語っていた。子供が泣いていた。声は小さかった。泣き声というよりも息の漏れに近い音。母親が子供の手を引いて歩き続けていた。立ち止まれなかった。立ち止まったら歩けなくなることを知っていた。"}, {"id": "ch16-s04-p025", "type": "text", "text": "列の最後尾が門を通過した。"}, {"id": "ch16-s04-p026", "type": "text", "text": "その後ろに、もう一つの影があった。"}, {"id": "ch16-s04-p027", "type": "text", "text": "列の外。五メートルほど後ろ。列に入らず、列の背中を見ながら歩いてくる人影。"}, {"id": "ch16-s04-p028", "type": "text", "text": "ポニーテール。"}, {"id": "ch16-s04-p029", "type": "text", "text": "栗色のポニーテールが夕日に照らされていた。結び目が緩んでいた。後れ毛が頬に張りつき、首に絡んでいた。黄色いゴム。その下に布リングが重なっている——はずだった。距離があって見えなかったが、布リングはある。いつもある。"}, {"id": "ch16-s04-p030", "type": "text", "text": "燈花だった。"}, {"id": "ch16-s04-p031", "type": "text", "text": "服が泥で汚れていた。制服ではなかった。長袖のシャツとカーゴパンツ。外円区の避難活動に出た時の格好。シャツの背中が泥と汗で色が変わっていた。白だったシャツが茶色と灰色のまだらになっている。カーゴパンツの膝が破れていた。裂けたのではなく、擦れて薄くなって穴が開いたのだとわかった。膝をついた。何度も。"}, {"id": "ch16-s04-p032", "type": "text", "text": "顔が蒼白だった。"}, {"id": "ch16-s04-p033", "type": "text", "text": "燈花の肌は小麦色だった。農家育ちの日焼けした肌。外で走り回る人間の色。その色が、今は抜けていた。頬が白い。唇に色がない。目の下に影がある。一晩以上寝ていない顔。一晩以上走り続けた顔。"}, {"id": "ch16-s04-p034", "type": "text", "text": "しかし背筋が伸びていた。"}, {"id": "ch16-s04-p035", "type": "text", "text": "燈花の背筋は伸びていた。肩が下がっていなかった。首が前に折れていなかった。泥だらけの服、蒼白な顔、緩んだポニーテール——そのどれもが疲労を語っていたのに、背骨だけが折れていなかった。"}, {"id": "ch16-s04-p036", "type": "text", "text": "避難民の列を見送ってきた人間の姿勢だった。三十人を導いてきた人間の、最後まで崩れなかった背中。列の先頭を歩いたか、最後尾を歩いたかは知らない。けれど、誰かが見ている間は背筋を伸ばし続けた人間の体だった。"}, {"id": "ch16-s04-p037", "type": "text", "text": "肋骨の内側の氷が砕けた。"}, {"id": "ch16-s04-p038", "type": "text", "text": "砕けたのではなかった。溶けたのでもなかった。凍っていた石に亀裂が入った。肋骨の内側で固まっていた冷たいものに罅が走って、その隙間から——何か温かいものが滲んだ。滲んだものの名前はわからなかった。安堵に近い。けれど安堵ではなかった。安堵には収まらないものがあった。"}, {"id": "ch16-s04-p039", "type": "text", "text": "燈花が門をくぐった。石畳の上。避難民の列はもう講堂に向かっていた。管理局の職員が片づけを始めている。南門の前には俺と燈花だけが残った。"}, {"id": "ch16-s04-p040", "type": "text", "text": "燈花が俺を見た。"}, {"id": "ch16-s04-p041", "type": "text", "text": "十メートル。八メートル。六メートル。燈花が歩いてくる。泥のついた靴が石畳を踏む。足音が一歩ごとに近づく。"}, {"id": "ch16-s04-p042", "type": "text", "text": "四メートル。"}, {"id": "ch16-s04-p043", "type": "text", "text": "琥珀色の目が俺を見つけた。"}, {"id": "ch16-s04-p044", "type": "text", "text": "燈花の表情が——"}, {"id": "ch16-s04-p045", "type": "text", "text": "緩んだ。"}, {"id": "ch16-s04-p046", "type": "text", "text": "一瞬だった。口元の線が解けて、目の端のこわばりが消えて、顔全体が半歩ぶん柔らかくなった。食堂で蓮くーんと叫ぶ時の燈花の顔の手前にある、もっと小さな緩み。俺がいることを見つけた顔。"}, {"id": "ch16-s04-p047", "type": "text", "text": "半秒。"}, {"id": "ch16-s04-p048", "type": "text", "text": "引き締めた。"}, {"id": "ch16-s04-p049", "type": "text", "text": "口元が戻った。目が戻った。背筋が伸びたままの顔に、表情を戻した。避難民の前で保っていた顔に。まだ崩れるわけにはいかない。まだ。管理局の職員がいる。講堂に向かう避難民の背中が見える。導いてきた人間は、導いた人間の前で崩れない。"}, {"id": "ch16-s04-p050", "type": "text", "text": "三メートル。二メートル。一メートル。"}, {"id": "ch16-s04-p051", "type": "text", "text": "燈花が俺の前で止まった。"}, {"id": "ch16-s04-p052", "type": "text", "text": "夕日が横から燈花の顔を照らしていた。頬の泥が乾いて固まっている。額に汗の筋の跡。ポニーテールの黄色いゴムの下に、布リングがあった。ほつれた繊維が指に触れていない。触れる余裕がなかったのだ。走っている間、一度も触れなかったのだ。"}, {"id": "ch16-s04-p053", "type": "text", "text": "「蓮くん」"}, {"id": "ch16-s04-p054", "type": "text", "text": "声が低かった。"}, {"id": "ch16-s04-p055", "type": "text", "text": "昨夜の通信越しの声よりも近い。けれど、声の温度は遠かった。低い。乾いている。喉の奥が渇ききった声。水を飲んでいない声。何時間も声を張って避難民に指示を出し続けた後の、搾りかすのような声。"}, {"id": "ch16-s04-p056", "type": "text", "text": "「灯里村は」"}, {"id": "ch16-s04-p057", "type": "text", "text": "燈花が言った。"}, {"id": "ch16-s04-p058", "type": "text", "text": "「もうない。完全に消えた」"}, {"id": "ch16-s04-p059", "type": "text", "text": "声が平坦だった。"}, {"id": "ch16-s04-p060", "type": "text", "text": "泣いていなかった。目が赤くなかった。頬に涙の跡がなかった。十二月の残響桜の下で泣いた燈花とは違う顔があった。泣くのとは別の場所に立っている顔。"}, {"id": "ch16-s04-p061", "type": "text", "text": "しかし——"}, {"id": "ch16-s04-p062", "type": "text", "text": "燈花の手が震えていた。"}, {"id": "ch16-s04-p063", "type": "text", "text": "右手。体の横に下ろした右手が、微かに揺れていた。指先から手首にかけての不規則な振動。寒さの震えではなかった。寒さなら体全体が震える。燈花の体は震えていなかった。背筋は伸びたままだった。肩は下がっていなかった。手だけが。声が届かない場所で、手だけが。"}, {"id": "ch16-s04-p064", "type": "text", "text": "「蝕域が灯里村を通過した時刻は、夜中の四時頃だったって。通信が切れた後だった」"}, {"id": "ch16-s04-p065", "type": "text", "text": "報告のような口調だった。管理局の職員が記録を読み上げるのに似た、事実を並べる声。"}, {"id": "ch16-s04-p066", "type": "text", "text": "「あたしが迎えに行ったおじいちゃんとおばあちゃんは……間に合った。三人とも。北回りに出した。あたしが戻った時には灯里村は——もう、白い光の中だった」"}, {"id": "ch16-s04-p067", "type": "text", "text": "声が揺れなかった。"}, {"id": "ch16-s04-p068", "type": "text", "text": "揺れないことが、一番痛かった。"}, {"id": "ch16-s04-p069", "type": "text", "text": "十一月。残響桜の下で燈花が泣いた。目を赤く腫らして、頬に涙の跡をつけて、声を震わせた。あの時の燈花は泣ける場所にいた。泣くことが許されていた。泣いて、ありがとうと言って、ご飯を食べようと言えた。"}, {"id": "ch16-s04-p070", "type": "text", "text": "今の燈花は泣いていない。泣けないのではない。泣く段階の向こう側に立っている。"}, {"id": "ch16-s04-p071", "type": "text", "text": "泣くには、失ったものの輪郭がいる。ここにあったもの、ここにいた人、ここで過ごした時間。輪郭があるから、なくなったことがわかる。なくなったとわかるから、涙が出る。"}, {"id": "ch16-s04-p072", "type": "text", "text": "灯里村が「完全に消えた」。"}, {"id": "ch16-s04-p073", "type": "text", "text": "輪郭ごと消えた。泣く対象の形が消えた。跡地もない。痕跡もない。白い光が通過して、何もなくなった。泣こうにも——何に向かって泣けばいい。"}, {"id": "ch16-s04-p074", "type": "text", "text": "燈花の琥珀色の瞳が俺を見ていた。"}, {"id": "ch16-s04-p075", "type": "text", "text": "涙がなかった。"}, {"id": "ch16-s04-p076", "type": "text", "text": "涙がないことが、一番——"}, {"id": "ch16-s04-p077", "type": "text", "text": "燈花が俺を見上げた。身長差が十センチと少し。見上げる角度。夕日が燈花の目の表面を照らしていた。琥珀の色が西日のオレンジを受けて、金に近い色を帯びていた。その金色の中に、涙の膜がなかった。乾いていた。目が乾いていた。"}, {"id": "ch16-s04-p078", "type": "text", "text": "「蓮くん」"}, {"id": "ch16-s04-p079", "type": "text", "text": "呼ばれた。"}, {"id": "ch16-s04-p080", "type": "text", "text": "「あたしの故郷は、もうないの」"}, {"id": "ch16-s04-p081", "type": "text", "text": "声が小さくなった。平坦が崩れかけていた。崩れきってはいなかった。ぎりぎりのところで声の形を保っていた。保っているのは、背筋が伸びているのと同じ理由だった。ここで崩れたら、三十人を導いてきた自分が嘘になる。"}, {"id": "ch16-s04-p082", "type": "text", "text": "「蓮くん。あたしは、どこに帰ればいいの」"}, {"id": "ch16-s04-p083", "type": "text", "text": "声が落ちた。"}, {"id": "ch16-s04-p084", "type": "text", "text": "呟きだった。俺の耳に届く距離にだけ存在する声。南門の石畳と夕暮れの風の間に挟まれて、すぐに消える音量。誰かに聞かせるための声ではなかった。自分の中から出てきてしまった声だった。"}, {"id": "ch16-s04-p085", "type": "text", "text": "どこに帰ればいいの。"}, {"id": "ch16-s04-p086", "type": "text", "text": "氷の石が鳴っていた。亀裂の入った石が。鳩尾の熱とも耳の音とも違う。この場所だけが、燈花の声を聴いていた。"}, {"id": "ch16-s04-p087", "type": "text", "text": "何を言えばいい。"}, {"id": "ch16-s04-p088", "type": "text", "text": "言葉を探した。喉の奥に塊がある。伝えたいことの形がない。十二月の残響桜の下でも同じだった。言葉が見つからなかった。あの時は「忘れていくのが怖いということは、わかる」と言えた。不完全な言葉だったが、出た。"}, {"id": "ch16-s04-p089", "type": "text", "text": "今は出なかった。"}, {"id": "ch16-s04-p090", "type": "text", "text": "「どこに帰ればいいの」に返す言葉が、喉のどこにも見つからなかった。「ここにいればいい」は嘘になる。ここは燈花の故郷ではない。「俺がいる」は正確ではない。俺がいても、灯里村は戻らない。「大丈夫」は——言わない。大丈夫ではないことを、燈花が一番知っている。"}, {"id": "ch16-s04-p091", "type": "text", "text": "言葉が出ない。出ないまま、燈花の前に立っていた。"}, {"id": "ch16-s04-p092", "type": "text", "text": "燈花の手が震えている。右手が体の横で揺れている。声は止まった。目は乾いている。背筋は伸びている。手だけが——体の中で唯一、正直な部分が、止まらない。"}, {"id": "ch16-s04-p093", "type": "text", "text": "手を上げた。"}, {"id": "ch16-s04-p094", "type": "text", "text": "右手。言葉の代わりに動いた。喉が閉じているなら、手が行く。誰に教わったのでもなかった。体が選んだ。"}, {"id": "ch16-s04-p095", "type": "text", "text": "燈花の左肩に、手を置いた。"}, {"id": "ch16-s04-p096", "type": "text", "text": "肩が小さかった。"}, {"id": "ch16-s04-p097", "type": "text", "text": "燈花の肩は農家育ちの健康な肩だった。荷物を担ぎ、畑を耕し、走り回る人間の肩。その肩が、手のひらの下で小さかった。泥のついたシャツの布越しに、肩の骨の硬さが伝わった。皮膚の温度が低い。寒さと疲労が肩から滲んでいた。"}, {"id": "ch16-s04-p098", "type": "text", "text": "燈花が動きを止めた。"}, {"id": "ch16-s04-p099", "type": "text", "text": "俺の手が肩にあることを、体が受け取った瞬間。燈花の背筋がわずかに揺れた。伸びたままの背骨に、一ミリの揺らぎが入った。"}, {"id": "ch16-s04-p100", "type": "text", "text": "震えが移った。"}, {"id": "ch16-s04-p101", "type": "text", "text": "手が——手ではなく、肩が震え始めた。俺の手のひらの下で、燈花の肩が震えていた。手の震えとは質が違った。手は指先の振動だった。肩は、もっと深い場所から来ていた。体の芯が揺れていた。背骨を伸ばし続けていた力が、一箇所だけ緩んだ。手のひらが触れた場所だけが緩んだ。"}, {"id": "ch16-s04-p102", "type": "text", "text": "泣かなかった。"}, {"id": "ch16-s04-p103", "type": "text", "text": "燈花は泣かなかった。涙は出なかった。目は乾いたままだった。声は出なかった。背筋は——揺れたが、折れなかった。肩が震えていた。手が震えていた。けれど泣かなかった。"}, {"id": "ch16-s04-p104", "type": "text", "text": "俺も泣かなかった。泣く回路が、俺にはまだない。亀裂の入った石が温かいものを滲ませている。滲んだものが何であるかはわからない。わからないまま、手のひらから燈花の肩に伝わっているものがあった。言葉ではないもの。名前のないもの。"}, {"id": "ch16-s04-p105", "type": "text", "text": "夕暮れの南門の前に、二人で立っていた。"}, {"id": "ch16-s04-p106", "type": "text", "text": "空のオレンジが薄くなり始めていた。灰色が西から降りてくる。石畳の上の泥の足跡が、光を失って暗くなっていく。管理局の職員はもう片づけを終えて門の内側に入っていた。避難民の列はとうに講堂の中に消えていた。"}, {"id": "ch16-s04-p107", "type": "text", "text": "南門の前に残っているのは俺と燈花だけだった。"}, {"id": "ch16-s04-p108", "type": "text", "text": "燈花の肩が震えている。俺の手がその上にある。二人とも声を出さない。二人とも泣かない。夕暮れの最後の光が石畳から消えていく。"}, {"id": "ch16-s04-p109", "type": "text", "text": "手を離さなかった。"}, {"id": "ch16-s04-p110", "type": "text", "text": "燈花が震えを止められないのと同じように、俺も手を離せなかった。言葉の代わりに置いた手だった。言葉が見つからないから置いた手だった。見つからないまま、手だけが——ここにある。"}, {"id": "ch16-s04-p111", "type": "text", "text": "風が吹いた。十二月の風。南から。外円区の方角から。風の中に土の匂いが混じっていた。燈花の故郷だった場所の土。もう存在しない場所から、風だけが届いた。"}, {"id": "ch16-s04-p112", "type": "text", "text": "燈花のポニーテールの後れ毛が風に揺れた。頬に張りついていた髪が、一本だけ離れた。"}, {"id": "ch16-s04-p113", "type": "text", "text": "肋骨の内側は冷たくなかった。"}, {"id": "ch16-s04-p114", "type": "text", "text": "氷の石は、まだそこにあった。消えてはいなかった。けれど亀裂から滲んだ温かいものが、石の冷たさを薄めていた。冷たさと温かさが混在している。どちらか一方ではない。どちらも、ここにある。"}, {"id": "ch16-s04-p115", "type": "text", "text": "燈花の手が止まらないのと同じように——どちらも、止まらないまま、ここにある。"}]}, {"chapter": 16, "chapterTitle": "誰の側に", "scene": 5, "sceneTitle": "氷華の宣言", "wordCount": "約5,000字", "paragraphs": [{"id": "ch16-s05-p001", "type": "text", "text": "燈花を講堂に送ったのは十八時前だった。"}, {"id": "ch16-s05-p002", "type": "text", "text": "避難民の列が収容された聖鐘学院の講堂。仮設の寝台が並び、毛布が配られ、職員が名簿を整理していた。燈花は自分の寝台に座ろうとしなかった。先に入った避難民の元を回っていた。一人ずつ声をかけていた。声は枯れていた。枯れた声でも、声をかけることをやめなかった。"}, {"id": "ch16-s05-p003", "type": "text", "text": "「蓮くん。あたしは大丈夫」"}, {"id": "ch16-s05-p004", "type": "text", "text": "大丈夫ではなかった。蒼白の顔、泥のついた服、乾いた目。しかし背筋は伸びたままだった。講堂の中でも、燈花は導いた人間の姿勢を崩さなかった。"}, {"id": "ch16-s05-p005", "type": "text", "text": "「ここにいるから。あたしはここにいる」"}, {"id": "ch16-s05-p006", "type": "text", "text": "その言葉は俺に言ったのか、自分に言ったのかわからなかった。「どこに帰ればいいの」と呟いた口が、今は「ここにいる」と言っている。帰る場所がないなら、今いる場所を足場にする。それが燈花の回答だった。答えが出るまでの時間は、南門の前で俺の手が肩にあった数分間だった。"}, {"id": "ch16-s05-p007", "type": "text", "text": "講堂を出た。"}, {"id": "ch16-s05-p008", "type": "text", "text": "十二月の夜。空に星がない。曇りの夜は暗い。残響灯は半分以下しか点いておらず、石畳を歩く自分の足音だけが反響した。"}, {"id": "ch16-s05-p009", "type": "text", "text": "鐘鋳塔に足が向いた。"}, {"id": "ch16-s05-p010", "type": "text", "text": "肋骨の内側が、まだ温かさと冷たさの混在を抱えている。亀裂の入った氷の石。燈花の肩の震えが手のひらに残っている。それを引きずったまま、足が塔に向かった。"}, {"id": "ch16-s05-p011", "type": "text", "text": "理由は単純だった。十四時の定例会議がどうなったのか、結果を聞いていない。"}, {"id": "ch16-s05-p012", "type": "text", "text": "朝、霜月さんにデータを届けた。「いい。これで足りる」と言われた。十四時に織部副局長と対峙する。五年間の沈黙を破る。その結果が——まだ、どこにも届いていない。定例会議の後に何があったのか。霜月さんがどうなったのか。"}, {"id": "ch16-s05-p013", "type": "text", "text": "背中の奥が鳴っていた。霜月さんの場所。今朝から載り続けている「私は黙らない」の七語。七語の上に、十四時以降の六時間分の空白が積もっている。"}, {"id": "ch16-s05-p014", "type": "text", "text": "塔の扉を開けた。"}, {"id": "ch16-s05-p015", "type": "break", "text": "◇"}, {"id": "ch16-s05-p016", "type": "text", "text": "三階の通路は暗かった。"}, {"id": "ch16-s05-p017", "type": "text", "text": "残響灯が三つに一つしか点いていない。壁面の残響紋は脈動が鈍く、光が途切れ途切れに石壁を照らしては消えた。朝はまだ二つに一つだった。出力がさらに落ちている。"}, {"id": "ch16-s05-p018", "type": "text", "text": "研究室の鉄扉の下に、光が漏れていた。"}, {"id": "ch16-s05-p019", "type": "text", "text": "今朝と同じだった。この人はまだここにいる。八時から——もしかすると朝よりもっと前から——この鉄扉の内側にいる。"}, {"id": "ch16-s05-p020", "type": "text", "text": "ノックした。三回。拳で。"}, {"id": "ch16-s05-p021", "type": "text", "text": "「……入れ」"}, {"id": "ch16-s05-p022", "type": "text", "text": "声が遅れた。朝の「入れ」は間を置かなかった。今の「入れ」には、0.5秒ほどの間があった。声を出す前に、何かを確認している間。"}, {"id": "ch16-s05-p023", "type": "text", "text": "扉を開けた。"}, {"id": "ch16-s05-p024", "type": "text", "text": "研究室の中は朝と空気が変わっていた。インクと冷めた紅茶の渋い匂い。長時間人が籠もった部屋の、澱んだ温もり。"}, {"id": "ch16-s05-p025", "type": "text", "text": "計器のモニタは点いている。赤い数字が点滅している。それは同じだった。違うのは机の上だった。紅茶のカップが二つに増えている。一つは朝の飲みかけ。もう一つは午後に淹れたものだろう。どちらも冷えている。冷えた紅茶が二杯。この人は紅茶を淹れたが、飲み切る前に冷やした。二回。作業に集中して、カップの存在を忘れたのだ。"}, {"id": "ch16-s05-p026", "type": "text", "text": "机の上に報告書が散乱していた。"}, {"id": "ch16-s05-p027", "type": "text", "text": "いつもの霜月さんの机ではなかった。この人の机は整頓されている。計器とペンとノートが決まった位置にある。ペンの向きまで揃っている。その机の上に、紙が重なりもせず広がっていた。管理局のロゴの入った書類。手書きのメモ。表のようなもの。時系列に並んだ数字の羅列。一枚一枚を読む余裕はなかったが、量だけで何かが起きたことがわかった。"}, {"id": "ch16-s05-p028", "type": "text", "text": "霜月さんが机の前に立っていた。"}, {"id": "ch16-s05-p029", "type": "text", "text": "座っていなかった。椅子が後ろに引かれていた。この人は立ったまま作業をしていた。白いコートの袖は下ろされていた。朝は腕まくりだった。それを戻している。戻したのは、十四時の会議に出席するためだろう。コートの裾にしわが入っていた。座った跡ではなく、歩き回った跡。会議室から研究室までの往復で、裾が椅子の脚に引っかかったか。"}, {"id": "ch16-s05-p030", "type": "text", "text": "「朝霧」"}, {"id": "ch16-s05-p031", "type": "text", "text": "霜月さんの声。"}, {"id": "ch16-s05-p032", "type": "text", "text": "低かった。朝の金属質とは違う。今日三度目に聞く声は、金属が一度熱されて冷め直したような低さだった。冷たい。しかし表面の温度が低いだけで、内側はまだ火を抱いている。"}, {"id": "ch16-s05-p033", "type": "text", "text": "「会議は」"}, {"id": "ch16-s05-p034", "type": "text", "text": "俺が問いかける前に、霜月さんが口を開いた。"}, {"id": "ch16-s05-p035", "type": "text", "text": "「織部は却下した」"}, {"id": "ch16-s05-p036", "type": "text", "text": "四語。"}, {"id": "ch16-s05-p037", "type": "text", "text": "「私の報告を聞き、データを確認し、外円区避難のコスト試算を見せた。定量的根拠を三十二枚の資料で示した。織部は聞いた。聞いた上で、却下した」"}, {"id": "ch16-s05-p038", "type": "text", "text": "声に抑揚がなかった。事実を並べている。一つの文が次の文に引き継がれ、感情の漏洩がない。しかし——指先。霜月さんの右手が机の上のペンを握っていた。握り方が強い。指の関節が白い。"}, {"id": "ch16-s05-p039", "type": "text", "text": "「外円区への追加支援は認められず、鐘の出力回復に全資源を内円区集中。外円区の残存住民は自力避難。管理局は内円区防衛を最優先とする。以上が定例会議の決定だ」"}, {"id": "ch16-s05-p040", "type": "text", "text": "俺は何も言わなかった。何も言えなかったのではなく、今は霜月さんの声を聞く時間だった。背中の奥が重くなっていく。朝の七語の上に、今の言葉が一つずつ積もっていく。"}, {"id": "ch16-s05-p041", "type": "text", "text": "「自力避難。聞こえのいい言葉だ。外円区の住民は農民と漁民がほとんどで、蝕域の知識がない。自力で避難するための情報も道もない。自力避難とは、管理局が手を引くという意味だ」"}, {"id": "ch16-s05-p042", "type": "text", "text": "ペンが鳴った。霜月さんの指が力を加えた。金属のペンが軋む音。小さな音だったが、研究室の中ではよく通った。"}, {"id": "ch16-s05-p043", "type": "text", "text": "霜月さんの目が——動いた。"}, {"id": "ch16-s05-p044", "type": "text", "text": "ラベンダーの瞳が机の上の書類から俺に移った。"}, {"id": "ch16-s05-p045", "type": "text", "text": "「朝霧。私は高等評議会に訴状を出す」"}, {"id": "ch16-s05-p046", "type": "text", "text": "声の質が変わった。"}, {"id": "ch16-s05-p047", "type": "text", "text": "報告が終わった。ここからは決意だった。低い声の中に通る芯。朝の金属とも、今の冷めた表面とも違う。熱が声の内側に帰ってきていた。"}, {"id": "ch16-s05-p048", "type": "text", "text": "「五年前の望ヶ丘消滅事件の隠蔽と、今回の外円区放棄指示について。織部副局長を告発する」"}, {"id": "ch16-s05-p049", "type": "text", "text": "声は静かだった。叫んでいない。力んでいない。しかし一語ごとに重心が置かれていた。「告発」という語が研究室の空気を切った。"}, {"id": "ch16-s05-p050", "type": "text", "text": "「……本気ですか」"}, {"id": "ch16-s05-p051", "type": "text", "text": "出た。問いかけではなく、確認だった。本気かどうかは聞かなくてもわかっている。この人の目を見ればわかる。ラベンダーの瞳の中に——今朝の固体の怒りとは違うものがあった。怒りの先にあるもの。決めた人間の目。すべてを秤にかけ、失うものを数え、それでも行くと決めた人間の目。"}, {"id": "ch16-s05-p052", "type": "text", "text": "「本気だ」"}, {"id": "ch16-s05-p053", "type": "text", "text": "二語。迷いが削り落とされた二語。"}, {"id": "ch16-s05-p054", "type": "text", "text": "「五年前、私は声を上げた。十六歳だった。データは正確だった。声を上げたが、握り潰された。その後、私は黙った」"}, {"id": "ch16-s05-p055", "type": "text", "text": "今朝と同じ文脈。しかし今の声は今朝よりも落ち着いていた。金属の震えがなかった。震えが取れたのではなく、震えを通り越した場所に立っていた。"}, {"id": "ch16-s05-p056", "type": "text", "text": "「黙った結果が望ヶ丘だ。三百の命だ。改竄されたデータだ。十六歳の私に押し付けられた責任だ」"}, {"id": "ch16-s05-p057", "type": "text", "text": "左手が動いた。"}, {"id": "ch16-s05-p058", "type": "text", "text": "左耳。青い石のピアス。指先が触れた。朝は掴んでいた。今は——指の腹が石の表面を撫でていた。掴むのとは違う。確かめるのとも違う。約束をしている触れ方だった。ピアスの向こうにいる誰かに向けて。"}, {"id": "ch16-s05-p059", "type": "text", "text": "「今また同じことが起きようとしている。外円区が切り捨てられ、数千の住民が蝕域に呑まれる。五年前と同じ構造。同じ判断。同じ結末になる」"}, {"id": "ch16-s05-p060", "type": "text", "text": "声が途切れた。"}, {"id": "ch16-s05-p061", "type": "text", "text": "一秒。二秒。"}, {"id": "ch16-s05-p062", "type": "text", "text": "「次はない」"}, {"id": "ch16-s05-p063", "type": "text", "text": "三語。ピアスから指が離れた。離れた指が拳を握った。"}, {"id": "ch16-s05-p064", "type": "text", "text": "「次はない。今度は黙らない。五年前と同じ後悔を、もう一度重ねることは——しない」"}, {"id": "ch16-s05-p065", "type": "text", "text": "声が研究室を満たした。モニタの点滅が止まった。止まってはいない。機械は機械の通りに動いている。しかし霜月さんの声が空間を支配した瞬間、機械の光が退いた。"}, {"id": "ch16-s05-p066", "type": "text", "text": "朝から積もっていた七語の上に、今の言葉が全て落ちた。落ちた重さは——重くなかった。重さではない。方向が生まれていた。散乱していた断片に、一つの方位磁石が置かれたような感覚。この人の決意に方向がある。「告発する」「次はない」「黙らない」。三つの宣言が全て同じ方角を向いている。"}, {"id": "ch16-s05-p067", "type": "text", "text": "「訴状の草案はすでに書いた。定例会議で織部が却下した直後から、六時間かけて書いた」"}, {"id": "ch16-s05-p068", "type": "text", "text": "散乱した書類の意味がわかった。あれは報告書ではなかった。訴状の下書きだった。紅茶が二杯冷えた理由も。この人は会議が終わった瞬間から、次の手を打ち始めていた。"}, {"id": "ch16-s05-p069", "type": "text", "text": "「高等評議会は内円区にある。訴状の提出には三名の連名が必要だ。私と——」"}, {"id": "ch16-s05-p070", "type": "text", "text": "霜月さんの声が、初めて途切れた。"}, {"id": "ch16-s05-p071", "type": "text", "text": "途切れたのは言葉を探しているのではなかった。言葉はある。言葉を出す準備がまだ終わっていなかった。この人が次に言う一言を発するために、何かを——壁を——降ろす必要があった。"}, {"id": "ch16-s05-p072", "type": "text", "text": "「朝霧」"}, {"id": "ch16-s05-p073", "type": "text", "text": "名前を呼ばれた。今日何度目かの「朝霧」。しかし今の呼び方は業務の呼び方ではなかった。業務の「朝霧」は命令の前に来る。今の「朝霧」は——頼みの前に来ていた。"}, {"id": "ch16-s05-p074", "type": "text", "text": "霜月さんの右手がペンを置いた。"}, {"id": "ch16-s05-p075", "type": "text", "text": "ゆっくりと。金属のペンが木の机に触れる音。小さな音。"}, {"id": "ch16-s05-p076", "type": "text", "text": "その手が——差し出された。"}, {"id": "ch16-s05-p077", "type": "text", "text": "俺の方に。"}, {"id": "ch16-s05-p078", "type": "text", "text": "掌を上に向けて。白い手。細い指。霜月さんの手は計器を操作する精密な手だった。設計図を描く手だった。鐘鋳塔の機構を調整し、データを記録する手。"}, {"id": "ch16-s05-p079", "type": "text", "text": "手の表面に——傷があった。"}, {"id": "ch16-s05-p080", "type": "text", "text": "掌の付け根に、赤い線。親指と人差し指の間に擦り傷。中指の爪の横に、皮膚が裂けた跡。傷は新しかった。一日や二日のものではなく、数日かけて蓄積した傷だった。"}, {"id": "ch16-s05-p081", "type": "text", "text": "鐘鋳塔の修復。"}, {"id": "ch16-s05-p082", "type": "text", "text": "昨夜の縁蝕波の後、塔の内部機構は損傷していた。残響灯が半数以下に落ちた。残響紋の出力が低下した。それを一つずつ手作業で修復している。計器で測り、工具で調整し、素手で回路を確認する。その作業の跡が手に刻まれていた。"}, {"id": "ch16-s05-p083", "type": "text", "text": "「私一人では難しい」"}, {"id": "ch16-s05-p084", "type": "text", "text": "声が低い。低いが、震えていない。震えていないことに、この人がどれだけの力を使っているのか——わかった。"}, {"id": "ch16-s05-p085", "type": "text", "text": "「証拠の整理と、技術面での証言が必要だ。五年前のデータと今回のデータを突き合わせ、隠蔽の構造を立証しなければならない。一人の技師の訴えでは、また握り潰される」"}, {"id": "ch16-s05-p086", "type": "text", "text": "論理は正確だった。データに基づく発言。いつもの霜月さんだった。いつもの霜月さんが、いつもと違うことをしている。差し出した手を下ろさない。"}, {"id": "ch16-s05-p087", "type": "text", "text": "「……手を貸してくれないか」"}, {"id": "ch16-s05-p088", "type": "text", "text": "「か」。"}, {"id": "ch16-s05-p089", "type": "text", "text": "最後の一音。疑問の形をした依頼。命令ではなかった。指示でもなかった。「出しなさい」でも「整えなさい」でもなかった。霜月さんの語尾には常に断定か命令が来る。「だ」「しなさい」「しろ」。「か」が来たことがなかった。"}, {"id": "ch16-s05-p090", "type": "text", "text": "「か」は問いかけの形をしている。断るという選択肢を俺に渡している。命令でなく依頼にすることで、俺の意志に委ねている。"}, {"id": "ch16-s05-p091", "type": "text", "text": "この人が「助けてくれ」と言ったのは——これが初めてだった。"}, {"id": "ch16-s05-p092", "type": "text", "text": "「手を貸してくれないか」は、霜月氷華という人間にとって、どれほど発音の難しい一文だったか。五年間、一人で抱えてきた。一人で凍らせて、一人で技術を磨いて、一人で完璧であろうとした。「二度と声は上げない」と決めていた人が声を上げると決めた。そしてもう一歩——「一人でやらない」と決めた。"}, {"id": "ch16-s05-p093", "type": "text", "text": "掌が上を向いている。傷だらけの手が俺の前にある。"}, {"id": "ch16-s05-p094", "type": "text", "text": "不器用な人だと思っていた。技術は天才だが、人に頼ることを知らない人。感情を凍らせて、データだけを武器にする人。その評価は間違っていなかった。間違っていなかったが、足りなかった。"}, {"id": "ch16-s05-p095", "type": "text", "text": "この手は鐘鋳塔を修復していた手だった。"}, {"id": "ch16-s05-p096", "type": "text", "text": "島の人間を守るための機構を、素手で直していた手だった。傷がついても手を引かなかった。ペンを握る指の関節が白くなるほど訴状を書いた手だった。「手を貸してくれないか」という一文を声にするために、五年分の壁を降ろした手だった。"}, {"id": "ch16-s05-p097", "type": "text", "text": "不器用な人だ。"}, {"id": "ch16-s05-p098", "type": "text", "text": "しかし——共に戦う人だ。"}, {"id": "ch16-s05-p099", "type": "text", "text": "手を伸ばした。"}, {"id": "ch16-s05-p100", "type": "text", "text": "俺の右手が霜月さんの手に触れた。"}, {"id": "ch16-s05-p101", "type": "text", "text": "指が触れた瞬間、冷たかった。研究室の冷気を吸った手。十二月の鐘鋳塔は冷える。石の壁が外の寒さを通す。この人はこの冷たさの中で十時間以上作業をしていた。"}, {"id": "ch16-s05-p102", "type": "text", "text": "冷たい手。しかし、指に力があった。俺の手が触れた瞬間、霜月さんの指が俺の指を握った。弱い力ではなかった。掴む力。逃がさない力ではなく——共に握る力。"}, {"id": "ch16-s05-p103", "type": "text", "text": "「霜月さん」"}, {"id": "ch16-s05-p104", "type": "text", "text": "「ああ」"}, {"id": "ch16-s05-p105", "type": "text", "text": "「俺にできることを言ってください——は、前にも言いました。今回は違います」"}, {"id": "ch16-s05-p106", "type": "text", "text": "霜月さんの瞳が動いた。ラベンダーの色が、残響灯の青白い光の中で一瞬だけ焦点を変えた。"}, {"id": "ch16-s05-p107", "type": "text", "text": "「俺もやります。言われたからではなく」"}, {"id": "ch16-s05-p108", "type": "text", "text": "手を握ったまま言った。背中の奥——ではなかった。今の声は背中の奥から出ていなかった。手から出ていた。霜月さんの手を握っている、この手から。背中は一人で背負う場所だった。手は相手と繋がる場所だった。"}, {"id": "ch16-s05-p109", "type": "text", "text": "霜月さんが——目を閉じた。"}, {"id": "ch16-s05-p110", "type": "text", "text": "一秒。長い一秒。瞼が閉じている間に、霜月さんの唇の線が——動いた。水平の線がわずかに左右に引かれた。笑みではなかった。笑みの一歩手前。口元の力が抜けた形。この人が感情を表面に出すことを許した、一瞬の隙間。"}, {"id": "ch16-s05-p111", "type": "text", "text": "目を開けた。"}, {"id": "ch16-s05-p112", "type": "text", "text": "ラベンダーの瞳が俺を見た。硬さが戻っていた。しかし硬さの質が変わっていた。朝の硬さは壁だった。今の硬さは骨格だった。壁は他者を遮断する。骨格は自分を支える。支えた上で、隣に立つ人間の存在を許容する硬さだった。"}, {"id": "ch16-s05-p113", "type": "text", "text": "「明日の朝。八時に来い。証拠の整理を始める」"}, {"id": "ch16-s05-p114", "type": "text", "text": "命令が戻った。しかし命令の奥に、さっきの「か」が残響として残っていた。「来い」の中に「来てくれ」が混じっていた。"}, {"id": "ch16-s05-p115", "type": "text", "text": "「了解しました」"}, {"id": "ch16-s05-p116", "type": "text", "text": "手が離れた。俺の手から、霜月さんの手から、同時に力が抜けた。自然に離れた。離れた手のひらに、霜月さんの指の傷の感触が残っていた。擦り傷の凹凸。裂けた皮膚の端。この人がどれだけのものを手で直してきたかの痕跡。"}, {"id": "ch16-s05-p117", "type": "text", "text": "研究室を出た。鉄扉を閉めた。"}, {"id": "ch16-s05-p118", "type": "text", "text": "通路の残響灯が明滅していた。三つに一つの弱い光。石壁が冷たい。"}, {"id": "ch16-s05-p119", "type": "text", "text": "手のひらを見た。"}, {"id": "ch16-s05-p120", "type": "text", "text": "自分の手。右手。霜月さんの手を握った手。傷はない。霜月さんの手にあった傷が、俺の手にはなかった。当然だった。俺はまだ何も直していない。この人は直していた。壊れた機構を、壊れた制度を、直そうとしていた。五年前にできなかったことを、今度はやると決めて、手を傷だらけにして。"}, {"id": "ch16-s05-p121", "type": "text", "text": "感覚が変化していた。"}, {"id": "ch16-s05-p122", "type": "text", "text": "朝から載っていた霜月さんの七語——「今度は私は黙らない」——は、変わっていなかった。消えてもいない。しかし七語の性質が変わっていた。朝、あれは霜月さんの覚悟だった。他者の覚悟の重さだった。"}, {"id": "ch16-s05-p123", "type": "text", "text": "今は違う。"}, {"id": "ch16-s05-p124", "type": "text", "text": "共鳴していた。霜月さんの覚悟と、俺の「やります」が、同じ方角を向いている。背中の奥に載っているのは他者の重さではなく、二人分の方向だった。一つの覚悟が二つになった時、重さは半分にならない。しかし方向が定まる。方向が定まると、足が動く。"}, {"id": "ch16-s05-p125", "type": "text", "text": "階段を降りた。三階から一階。螺旋の石段を踏む足音が壁に反響した。反響が返ってきた。朝は返ってこなかった。塔の出力がさらに落ちている中で、反響が返ってきたのは偶然だった。偶然に、意味はない。"}, {"id": "ch16-s05-p126", "type": "text", "text": "しかし——手のひらに残った傷の感触と、背中の奥の方向と、霜月さんのラベンダーの瞳の中の火が。"}, {"id": "ch16-s05-p127", "type": "text", "text": "全部が同じ夜の中にある。"}, {"id": "ch16-s05-p128", "type": "text", "text": "塔の扉を開けた。十二月の夜気が顔に触れた。星はまだない。曇り空。しかし南の地平線の白い靄が、ほんの少しだけ薄くなった——ように見えた。見えただけかもしれない。目の錯覚かもしれない。"}, {"id": "ch16-s05-p129", "type": "text", "text": "手のひらを握った。右手。傷の感触を閉じ込めた。"}, {"id": "ch16-s05-p130", "type": "text", "text": "明日の朝。八時。証拠の整理を始める。"}, {"id": "ch16-s05-p131", "type": "text", "text": "足は動く。方向が定まっている。"}]}, {"chapter": 16, "chapterTitle": "誰の側に", "scene": 6, "sceneTitle": "蓮の覚醒", "wordCount": "", "paragraphs": [{"id": "ch16-s06-p001", "type": "text", "text": "二十三時。補佐官舎の部屋。灯りは消してある。"}, {"id": "ch16-s06-p002", "type": "text", "text": "布団の上に座ったまま、三時間が経った。鐘鋳塔を出てから、風呂に入り、着替え、布団を敷き、横になった。眠れなかった。横になっているのが苦しくて起き上がり、そのまま座っている。"}, {"id": "ch16-s06-p003", "type": "text", "text": "窓は閉めてある。十二月の夜気は、隙間から入ってくるだけで十分に冷たい。"}, {"id": "ch16-s06-p004", "type": "text", "text": "目を閉じる。"}, {"id": "ch16-s06-p005", "type": "text", "text": "——鳩尾の上が、熱い。"}, {"id": "ch16-s06-p006", "type": "text", "text": "千歳の声が、まだ残っている。十一月の夜に聴いた歌声ではない。昨日の千歳。「歌いたい」と言った千歳。あのとき鳩尾の上に灯った灼熱が、消えないまま胸の全体に広がっている。千歳は笑っていた。笑って、歌いたいと言った。その笑顔の裏にあるものを、俺は知っている。千歳が何と闘っているかを、俺は知っている。"}, {"id": "ch16-s06-p007", "type": "text", "text": "知っていて、何もしていない。"}, {"id": "ch16-s06-p008", "type": "text", "text": "肋骨の内側が、疼く。"}, {"id": "ch16-s06-p009", "type": "text", "text": "燈花。「どこに帰ればいいの」。あの声を聞いたとき、肋骨の内側で何かが罅割れた。八月に初めて「燈花」と呼んだとき、そこに灯った温かさ。罅の入った氷の石に、温かいものが滲んでいる。滲んでいるから痛い。氷が溶けるのは本来良いことのはずだが、溶けた水の行き場がない。燈花の居場所が、今、どこにもない。"}, {"id": "ch16-s06-p010", "type": "text", "text": "耳の奥で、音が鳴っている。"}, {"id": "ch16-s06-p011", "type": "text", "text": "雫。雫の震える手。十月の演習場で雫が差し出した書類を受け取ったとき、指先が触れた。あの指は震えていた。「何なのだろう」と雫は言った。自分の中に生まれたものの名前がわからないと、雫は言った。あの問いに、俺はまだ答えていない。答える資格があるのかも、わからない。雫の「何なのだろう」は耳の位置に引っかかったまま、確信に変わり、今は名前のない新しい音になっている。その音が、止まない。"}, {"id": "ch16-s06-p012", "type": "text", "text": "背中の奥が、共鳴している。"}, {"id": "ch16-s06-p013", "type": "text", "text": "氷華。二十時間前、氷華が手を差し出した。俺はその手を握った。氷華の手には傷があり、俺の手にはなかった。氷華の覚悟と俺の「やります」が同じ方角を向いている。背中の奥に二人分の方向が収まっている。しかし二人分の方向は、あくまで二人分だ。"}, {"id": "ch16-s06-p014", "type": "text", "text": "左手の甲が、冷たい。"}, {"id": "ch16-s06-p015", "type": "text", "text": "すみれ。「もう、じかんがない」。すみれが最後にそう言ったとき、すみれの指が俺の左手の甲に触れた。その冷たさが、十二月の夜気より冷たい温度で、まだ、残っている。時間がない。すみれの言った「時間」が何を指すのか、俺はまだ正確に理解できていない。理解できていないことが、冷たさの正体だ。"}, {"id": "ch16-s06-p016", "type": "text", "text": "——五つ。"}, {"id": "ch16-s06-p017", "type": "text", "text": "体の五箇所に、五人の痕跡がある。"}, {"id": "ch16-s06-p018", "type": "text", "text": "目を開けた。暗い天井が見える。見えるが、見ていない。"}, {"id": "ch16-s06-p019", "type": "text", "text": "四月の俺なら、この五つの感覚をどう処理したか。"}, {"id": "ch16-s06-p020", "type": "text", "text": "答えは明確だった。処理しない。入力を受け、判断し、適切な出力を返す。それだけだ。鳩尾の上が熱いなら、「ああ、熱いのだな」と記録する。肋骨の内側が疼くなら、「疼いている」と分類する。耳の奥の音も、背中の共鳴も、左手の冷たさも、全て同じだ。受信し、記録し、保留する。"}, {"id": "ch16-s06-p021", "type": "text", "text": "痛くなかった。"}, {"id": "ch16-s06-p022", "type": "text", "text": "四月の俺は、痛くなかった。"}, {"id": "ch16-s06-p023", "type": "text", "text": "模倣は痛まない。おいしいものを食べて「おいしい」と言うとき、間があった。体が反応し、反応を観察し、「これはおいしいという反応だ」と判断し、「おいしい」と出力する。その回路に、痛みは存在しない。模倣の精度が上がっても、回路の構造は同じだった。入力。判断。出力。間。"}, {"id": "ch16-s06-p024", "type": "text", "text": "今は、痛い。"}, {"id": "ch16-s06-p025", "type": "text", "text": "鳩尾の上の灼熱が痛い。肋骨の内側の罅が痛い。耳の奥の音が痛い。背中の共鳴が痛い。左手の冷たさが痛い。五箇所が同時に痛い。"}, {"id": "ch16-s06-p026", "type": "text", "text": "間がない。"}, {"id": "ch16-s06-p027", "type": "text", "text": "入力と痛みの間に、判断が挟まらない。千歳を想えば、そのまま熱い。燈花を想えば、そのまま疼く。雫を想えば、音が鳴る。氷華を想えば、共鳴する。すみれを想えば、冷たい。回路を経由していない。直結している。"}, {"id": "ch16-s06-p028", "type": "text", "text": "十一月に、千歳の歌で涙が出た。あれが最初だった。管が通った、と思った。塞がっていた管に何かが通り、涙として外に出た。あのとき俺は「模倣ではなかった」と知った。"}, {"id": "ch16-s06-p029", "type": "text", "text": "氷華の話を聞いて怒りが湧いた。怒りは消えなかった。消えないことが証拠だった。模倣なら、場面が変われば消える。消えなかった。だからあれは本物だった。"}, {"id": "ch16-s06-p030", "type": "text", "text": "——なら。"}, {"id": "ch16-s06-p031", "type": "text", "text": "今、体の五箇所で同時に鳴っているこの痛みも。"}, {"id": "ch16-s06-p032", "type": "text", "text": "本物だ。"}, {"id": "ch16-s06-p033", "type": "text", "text": "膝の上に置いた手を見た。右手。霜月さんの手を握った手。左手。すみれの冷たさが残っている手。二つの手のひらを、膝の上で握った。"}, {"id": "ch16-s06-p034", "type": "text", "text": "全員のことを想って、痛い。"}, {"id": "ch16-s06-p035", "type": "text", "text": "この九ヶ月で——四月から十二月までの九ヶ月で——俺は、ここまで来た。感情の模倣者が、五人分の痛みを同時に抱えて眠れなくなるところまで。"}, {"id": "ch16-s06-p036", "type": "text", "text": "俺は変わった。"}, {"id": "ch16-s06-p037", "type": "text", "text": "変わったことが嬉しいのか。わからない。嬉しいとか悲しいとかではない。事実だ。四月の俺はここにいない。十二月の俺がここにいる。布団の上で膝を抱えている俺は、九ヶ月前の俺とは違う回路で動いている。"}, {"id": "ch16-s06-p038", "type": "text", "text": "五人が、同時に危うい。"}, {"id": "ch16-s06-p039", "type": "text", "text": "千歳は喉を。燈花は居場所を。雫は正体を。氷華は家を。すみれは時間を。それぞれが別々の崖の縁に立っている。五つの崖は別の方角にある。俺の体は一つしかない。"}, {"id": "ch16-s06-p040", "type": "text", "text": "全員を同時に助ける方法がない。"}, {"id": "ch16-s06-p041", "type": "text", "text": "この結論は、二十時頃に鐘鋳塔の階段を降りながら、既に出ていた。出ていたが、認めていなかった。保留していた。いつもの癖だ。判断を保留し、観察を続け、最適な出力を探す。四月から俺がやってきたことだ。"}, {"id": "ch16-s06-p042", "type": "text", "text": "しかし。"}, {"id": "ch16-s06-p043", "type": "text", "text": "保留できない。"}, {"id": "ch16-s06-p044", "type": "text", "text": "保留している間に、崖は崩れる。時間がない。すみれが言った通りだ。もう、時間がない。"}, {"id": "ch16-s06-p045", "type": "text", "text": "全員を選べない。"}, {"id": "ch16-s06-p046", "type": "text", "text": "一人を選べば、四人の前から離れる時間が生まれる。その時間に崖が崩れたら——。"}, {"id": "ch16-s06-p047", "type": "text", "text": "何もしない、という選択肢はどうか。"}, {"id": "ch16-s06-p048", "type": "text", "text": "全員の側に均等にいる。誰も選ばない。今まで通りの「朝霧蓮」を続ける。"}, {"id": "ch16-s06-p049", "type": "text", "text": "——それは、全員を失う選択だ。"}, {"id": "ch16-s06-p050", "type": "text", "text": "均等は無力だ。五つの方角に同時に走ることはできない。どの方角にも半歩ずつ進んで、結局どこにも辿り着かない。"}, {"id": "ch16-s06-p051", "type": "text", "text": "「……俺は」"}, {"id": "ch16-s06-p052", "type": "text", "text": "声が出た。暗い部屋に、自分の声が落ちた。"}, {"id": "ch16-s06-p053", "type": "text", "text": "「このままでは、誰も守れない」"}, {"id": "ch16-s06-p054", "type": "text", "text": "守る。その言葉が口から出たことに、少し驚いた。守る、と俺は言った。観察する、でも、記録する、でも、保留する、でもなく。守る。"}, {"id": "ch16-s06-p055", "type": "text", "text": "四月の俺は「守る」とは言わなかった。守るためには相手に向かって踏み込む必要があり、踏み込むためには方向を選ぶ必要があり、方向を選ぶためには——感情が要る。"}, {"id": "ch16-s06-p056", "type": "text", "text": "模倣では、選べない。"}, {"id": "ch16-s06-p057", "type": "text", "text": "模倣は全方位に均等だ。入力に応じて最適な出力を返す。どの入力にも同じ精度で応答する。それは誠実に見えて、実は何も選んでいない。"}, {"id": "ch16-s06-p058", "type": "text", "text": "選ぶ、ということ。"}, {"id": "ch16-s06-p059", "type": "text", "text": "誰かの側に立つ、ということ。"}, {"id": "ch16-s06-p060", "type": "text", "text": "それは、他の誰かの側に立てないことを引き受けるということだ。"}, {"id": "ch16-s06-p061", "type": "text", "text": "目の奥が、熱くなった。"}, {"id": "ch16-s06-p062", "type": "text", "text": "鳩尾の上の灼熱と、肋骨の疼きと、耳の音と、背中の共鳴と、左手の冷たさが——五つが同時に締まった。締まって、行き場を失った圧力が、上へ昇った。喉を通過し、目の裏に到達した。"}, {"id": "ch16-s06-p063", "type": "text", "text": "涙が、出た。"}, {"id": "ch16-s06-p064", "type": "text", "text": "右の頬を、一筋の線が降りていく。温かい。十二月の部屋の空気よりずっと温かい線が、頬の曲面に沿って、顎の先端まで降りて、落ちた。布団に小さな染みが一つできた。"}, {"id": "ch16-s06-p065", "type": "text", "text": "二度目だ。"}, {"id": "ch16-s06-p066", "type": "text", "text": "十一月に千歳の歌を聴いたとき以来、二度目の涙。あのときは——管が通った。塞がっていた何かが開いて、涙が出口を見つけた。あの涙は、通過だった。何かが俺の中を通り抜けていく感覚。"}, {"id": "ch16-s06-p067", "type": "text", "text": "今回は、違う。"}, {"id": "ch16-s06-p068", "type": "text", "text": "通り抜けていかない。溜まっている。五人分の痛みが溜まって、溢れた水が涙になっている。出口ではなく、溢流だ。容量を超えた。"}, {"id": "ch16-s06-p069", "type": "text", "text": "左の頬にも、一筋。"}, {"id": "ch16-s06-p070", "type": "text", "text": "全員を選べない、ということが、こんなに苦しい。"}, {"id": "ch16-s06-p071", "type": "text", "text": "苦しいということが——その苦しさの理由が——五人全員と関係を築いたからだということが——"}, {"id": "ch16-s06-p072", "type": "text", "text": "声は出なかった。声にする必要がなかった。体が知っている。この九ヶ月で体に刻まれた五つの痕跡が、全部本物だったから、今、泣いている。"}, {"id": "ch16-s06-p073", "type": "text", "text": "模倣は、泣かない。模倣は溢れない。回路は容量を超えない。"}, {"id": "ch16-s06-p074", "type": "text", "text": "涙が止まるまで、何分かかったかわからない。長くはなかった。蓮の涙は、量が少ない。まだ慣れていない器官だ。二回目の使用では、そう多くは出ない。"}, {"id": "ch16-s06-p075", "type": "text", "text": "手の甲で目元を拭った。左手。すみれの冷たさが残っている手で。"}, {"id": "ch16-s06-p076", "type": "text", "text": "窓の外を見た。"}, {"id": "ch16-s06-p077", "type": "text", "text": "深夜の空。雲が厚い。星は見えない。十二月の闇が、補佐官舎の窓の向こうに広がっている。"}, {"id": "ch16-s06-p078", "type": "text", "text": "明日の朝が来る。"}, {"id": "ch16-s06-p079", "type": "text", "text": "朝が来たら——"}, {"id": "ch16-s06-p080", "type": "text", "text": "残響桜。"}, {"id": "ch16-s06-p081", "type": "text", "text": "あの木の下に行こう。四月に俺が目を覚ました場所。記憶を失い、名前だけを持って立っていた場所。九ヶ月前の始まりの場所で、俺は決める。"}, {"id": "ch16-s06-p082", "type": "text", "text": "何を選ぶかは、まだわからない。"}, {"id": "ch16-s06-p083", "type": "text", "text": "しかし「選ぶ」ことは、決めた。"}, {"id": "ch16-s06-p084", "type": "text", "text": "保留しない。観察に逃げない。模倣の均等さに隠れない。"}, {"id": "ch16-s06-p085", "type": "text", "text": "一人の側に立つ。その結果を引き受ける。"}, {"id": "ch16-s06-p086", "type": "text", "text": "布団に横になった。今度は眠れる気がした。体が、決断の形に収まっている。五箇所の痛みは消えていない。消えないまま、体が受け入れている。痛みを抱えたまま眠る方法を、九ヶ月かけて、俺の体は覚えたらしい。"}, {"id": "ch16-s06-p087", "type": "text", "text": "目を閉じた。暗い。星のない夜と同じ暗さが、瞼の裏に広がった。"}, {"id": "ch16-s06-p088", "type": "text", "text": "明日。残響桜の下で。"}]}, {"chapter": 16, "chapterTitle": "誰の側に", "scene": 7, "sceneTitle": "アナザービュー群：5つの声", "wordCount": "約3,800字", "paragraphs": [{"id": "ch16-s07-p001", "type": "text", "text": "医務室は暗かった。"}, {"id": "ch16-s07-p002", "type": "text", "text": "消灯は二十一時。残響灯が非常灯の明るさに落ちて、白いシーツも白い壁も青灰色に沈んでいた。窓の外に月はない。十二月の曇天が、窓ガラスの向こうに一枚の暗幕のように張りついている。"}, {"id": "ch16-s07-p003", "type": "text", "text": "隣のベッドから、いろはの寝息が聞こえる。小さく規則的な呼吸。ジャケットを着たまま椅子で寝落ちしかけたいろはを、千歳がベッドに入るよう言ったのは二十二時頃だった。いろはは「まだ起きてる」と言ったが、手を離した三分後には呼吸が深くなっていた。丸一日以上泣いて、握って、起きていた体が、限界を認めた音だった。"}, {"id": "ch16-s07-p004", "type": "text", "text": "千歳は天井を見ていた。"}, {"id": "ch16-s07-p005", "type": "text", "text": "青灰色の天井。染みが一つある。昼間は見えなかった染みが、非常灯の角度で浮かんでいる。染みの形に意味はない。意味のないものを見ている。意味のないものを見ている時間が、今は必要だった。"}, {"id": "ch16-s07-p006", "type": "text", "text": "右手を持ち上げた。"}, {"id": "ch16-s07-p007", "type": "text", "text": "毛布の上に。掌を上に向けて。五本の指が震えている。昼間と同じ振れ。ステージの上で声を出す時に使う手ではない。ペンを持つ手でも、いろはの手を握る手でもない。震えているだけの手。"}, {"id": "ch16-s07-p008", "type": "text", "text": "この手で、歌う。"}, {"id": "ch16-s07-p009", "type": "text", "text": "震えが止まらないことは知っている。止まらないことを、昼間、蓮さんの前で確認した。「震えてますね」と言った時、自分の声が静かだったことを覚えている。静かだった。怖くないわけではなかった。怖いのに、声が静かだった。"}, {"id": "ch16-s07-p010", "type": "text", "text": "——蓮さん。"}, {"id": "ch16-s07-p011", "type": "text", "text": "名前を口の中で転がした。声にはしなかった。いろはが目を覚ます。声にしない名前が、喉の奥の柔らかい場所に触れて、そこだけが温かかった。"}, {"id": "ch16-s07-p012", "type": "text", "text": "歌いたい。歌うことが怖い。喉が焼ける。瞳の色が薄くなる。ミサンガはまだ切れない。願いは叶っていない。それでも歌いたい。歌いたいと言った時の蓮さんの目を覚えている。蓮さんは答えなかった。答えなかったけれど、何か短い言葉をくれた。あの言葉の中身はもう朧げだったけれど、あの声の温度は胸の上に残っている。"}, {"id": "ch16-s07-p013", "type": "text", "text": "蓮さんがいてくれたら。"}, {"id": "ch16-s07-p014", "type": "text", "text": "その先の言葉を、千歳は考えなかった。考えなくてよかった。手は震えている。天井の染みは意味がない。いろはの寝息が隣にある。そして蓮さんの声の温度が胸の上にある。四つが同時にあるこの暗い部屋が、今は、歌う前の舞台袖に似ていた。"}, {"id": "ch16-s07-p015", "type": "text", "text": "怖い。けれどここにいる。"}, {"id": "ch16-s07-p016", "type": "text", "text": "目を閉じた。瞼の裏は天井より暗かった。暗さの中で、震える手を毛布の下に戻した。"}, {"id": "ch16-s07-p017", "type": "text", "text": "* * *"}, {"id": "ch16-s07-p018", "type": "text", "text": "記録室に灯りはなかった。"}, {"id": "ch16-s07-p019", "type": "text", "text": "図書館は臨時休館のまま。二階の書架の奥に灯りを点ける人間は、深夜にはいない。窓から入る光もない。曇りの夜は月も星も遮られて、記録室の四畳半は闇に沈んでいた。"}, {"id": "ch16-s07-p020", "type": "text", "text": "雫はペンを握っていた。"}, {"id": "ch16-s07-p021", "type": "text", "text": "暗闇の中で。メモ帳は開いてある。紙の位置は指先が覚えている。二十三冊分の記録を書いてきた指が、紙の端と罫線の段差を触覚で知っている。"}, {"id": "ch16-s07-p022", "type": "text", "text": "書けなかった。"}, {"id": "ch16-s07-p023", "type": "text", "text": "ペン先が紙に触れている。触れているが、動かない。昼間は動いた。蓮——朝霧さんが横にいた時、三行書けた。三行書いた後、間隔がわずかに戻り始めた。しかし朝霧さんが記録室を出て、扉が十センチの幅に戻って、足音が書架の向こうに消えた後から、ペンが重くなっていた。"}, {"id": "ch16-s07-p024", "type": "text", "text": "右手を見た。見えなかった。暗すぎた。見えないが、手がそこにあることはわかった。ペンの重さが指にある。指がペンを握っている。握っている指の輪郭が——曖昧だった。曖昧さが視覚ではなく触覚に来ていた。自分の指がペンに触れている感覚の、密度が薄い。"}, {"id": "ch16-s07-p025", "type": "text", "text": "ここにいるのかどうか、わからなくなる。"}, {"id": "ch16-s07-p026", "type": "text", "text": "昼間、朝霧さんにそう言った。言った時、自分の声の中に知らない色が混じっていた。不安、という名前を、後から当てた。不安は昼間より濃くなっている。暗い部屋の中で、不安の濃度だけが上がっていた。"}, {"id": "ch16-s07-p027", "type": "text", "text": "記録は、ここにある。"}, {"id": "ch16-s07-p028", "type": "text", "text": "朝霧さんがそう言った。メモ帳の上の文字を指差して。あの指先が指した場所に、自分の字がある。消えていない字がある。"}, {"id": "ch16-s07-p029", "type": "text", "text": "——朝霧さん。あなたがいてくれなければ。"}, {"id": "ch16-s07-p030", "type": "text", "text": "その先を、雫は考えた。記録ではなく、自分のことを。記録係の篠宮雫ではなく、ペンが動かなくなった暗闇の中の自分のことを。朝霧さんがいなければ、自分が消えていくことすら、誰の記録にも残らない。"}, {"id": "ch16-s07-p031", "type": "text", "text": "ペンを握る力を、わずかに強めた。指の関節に力が入った。ペンの軸が掌に食い込む感覚が、五本の指の先から手首まで伝わった。"}, {"id": "ch16-s07-p032", "type": "text", "text": "痛みがあった。痛みがあるということは、ここにいるということだった。"}, {"id": "ch16-s07-p033", "type": "text", "text": "書けないまま、ペンを離さなかった。"}, {"id": "ch16-s07-p034", "type": "text", "text": "* * *"}, {"id": "ch16-s07-p035", "type": "text", "text": "講堂の仮設ベッドは硬かった。"}, {"id": "ch16-s07-p036", "type": "text", "text": "パイプのフレームに薄いマットレス。毛布が一枚。枕はない。避難民用の寝台は数が優先で質は後回しだった。毛布から糊の匂いがした。新しい繊維。知らない匂い。灯里村の毛布は、日に干した藁と風の匂いがした。講堂の天井が高い分、声が反響する。どこかで子供が寝言を呟いている。大人の寝返りの音。床を擦る靴の底。三十人が一つの部屋で眠る夜の音。"}, {"id": "ch16-s07-p037", "type": "text", "text": "燈花は窓の側のベッドにいた。"}, {"id": "ch16-s07-p038", "type": "text", "text": "横になっていなかった。ベッドの端に腰掛けて、窓の外を見ていた。講堂の窓は南向きだった。南。外円区の方角。"}, {"id": "ch16-s07-p039", "type": "text", "text": "灯りがなかった。"}, {"id": "ch16-s07-p040", "type": "text", "text": "八月の夜に窓から見た外円区には、灯里村の方角に小さな灯りの群れがあった。農家の窓から漏れる光。街灯はないが、家々の灯りが集まって、夜の平野に点々と橙色を散らしていた。あの灯りを見て育った。あの灯りの中で眠り、あの灯りの中で目を覚ました。"}, {"id": "ch16-s07-p041", "type": "text", "text": "今は暗い。何もない。灯里村があった方角に、闇しかない。灯りの群れが消えたのではなく、灯りを灯す場所が消えた。"}, {"id": "ch16-s07-p042", "type": "text", "text": "右手が膝の上にあった。昼間は震えていた。今は止まっていた。止まっているのは、体が疲れきって震える力すら残っていないからだった。"}, {"id": "ch16-s07-p043", "type": "text", "text": "左手の薬指に布リングがある。ほつれた繊維。幼馴染がくれた約束の印。約束の内容はもう曖昧だった。名前も忘れかけている。記憶が薄れるより先に、帰る場所がなくなった。"}, {"id": "ch16-s07-p044", "type": "text", "text": "——蓮くん。"}, {"id": "ch16-s07-p045", "type": "text", "text": "名前を胸の中で呼んだ。声にはしなかった。隣のベッドで老人が眠っている。迎えに行った三人のうちの一人。間に合った命。この人を連れて走った夜道の感触が、まだ足の裏に残っている。"}, {"id": "ch16-s07-p046", "type": "text", "text": "あたしの故郷は、もうない。"}, {"id": "ch16-s07-p047", "type": "text", "text": "昼間、蓮くんにそう言った。言った時、蓮くんは何も言わなかった。何も言わずに、肩に手を置いた。左肩。あの手の重さと温度が、六時間経った今もそこにある。肩に触れた掌の面積。指の位置。シャツの布越しの体温。全部が残っている。"}, {"id": "ch16-s07-p048", "type": "text", "text": "蓮くんがいるから、あたしはまだここにいる。"}, {"id": "ch16-s07-p049", "type": "text", "text": "涙は出なかった。昼間も出なかった。今夜も出ない。泣く対象の形が消えている。泣けないかわりに、肩に残った手の温度がある。その温度だけが、硬い仮設ベッドの上で唯一の柔らかさだった。"}, {"id": "ch16-s07-p050", "type": "text", "text": "窓の外は暗い。南の方角に、何もない。何もない暗闇の手前に、この講堂がある。この講堂に、三十人がいる。蓮くんはいない。いないけれど、肩にいる。"}, {"id": "ch16-s07-p051", "type": "text", "text": "目を伏せた。膝の上の手が動かない。布リングのほつれた繊維が指に触れている。窓の外の暗闇に背を向けるように、燈花はゆっくりと体を横にした。"}, {"id": "ch16-s07-p052", "type": "text", "text": "* * *"}, {"id": "ch16-s07-p053", "type": "text", "text": "鐘鋳塔三階。研究室の鉄扉の内側。"}, {"id": "ch16-s07-p054", "type": "text", "text": "氷華は訴状の草案を書いていた。"}, {"id": "ch16-s07-p055", "type": "text", "text": "机の上にペンと紙と計器がある。紅茶の冷えた三杯目が、手の届かない位置に置かれている。白いコートの袖口にインクの染みが一箇所。それに気づいていない。気づく余裕が、六時間前からなかった。"}, {"id": "ch16-s07-p056", "type": "text", "text": "ペンが止まった。"}, {"id": "ch16-s07-p057", "type": "text", "text": "第三十七条の但し書きの引用が必要だった。条文の文言を正確に転記しようとして、ペンが止まった。止まった理由は条文を思い出せないからではなかった。条文は頭に入っている。"}, {"id": "ch16-s07-p058", "type": "text", "text": "手が動かなかった。"}, {"id": "ch16-s07-p059", "type": "text", "text": "右手がペンを握ったまま、紙の上で静止していた。指の関節が白い。昼間よりも白い。八時から二十時間以上、この机の前にいる。修復作業と訴状の起草を交互に繰り返した一日。掌の付け根の傷が乾いて、皮膚が引きつっている。"}, {"id": "ch16-s07-p060", "type": "text", "text": "——朝霧。"}, {"id": "ch16-s07-p061", "type": "text", "text": "名前が浮かんだ。"}, {"id": "ch16-s07-p062", "type": "text", "text": "浮かんだことに、ペンを持つ手が反応しなかった。手は止まったまま。名前だけが頭の中にあった。二十時に研究室を出ていった背中。「俺もやります。言われたからではなく」と言った声。あの声を聞いた時、背中の奥で何かが響いた。響いたものの残響が、五時間経っても消えていなかった。"}, {"id": "ch16-s07-p063", "type": "text", "text": "氷華は左手を上げた。左耳。青い石のピアスに指先が触れた。"}, {"id": "ch16-s07-p064", "type": "text", "text": "五年前の子供の声。「お守りだよ」。あの声はもう正確には再生できない。再生できないが、指先に触れる石の冷たさが代わりに応答する。"}, {"id": "ch16-s07-p065", "type": "text", "text": "また黙っているつもりか。"}, {"id": "ch16-s07-p066", "type": "text", "text": "自分に問いかけた。五年前の自分に。声を上げて、握り潰されて、黙った自分に。今度は黙らない。黙らないと決めた。訴状を書いている。高等評議会に提出する。データは揃えた。論理は組み上げた。一人では——"}, {"id": "ch16-s07-p067", "type": "text", "text": "一人では。"}, {"id": "ch16-s07-p068", "type": "text", "text": "朝霧が手を貸してくれると言った。「言われたからではなく」と。あの言葉を聞いた時、唇の線が動いた。水平の線がわずかに左右に引かれた。笑みではなかった。笑みの一歩手前の、力が抜けた形。"}, {"id": "ch16-s07-p069", "type": "text", "text": "お前が隣にいてくれるなら。"}, {"id": "ch16-s07-p070", "type": "text", "text": "その思考に、氷華の指がピアスから離れた。"}, {"id": "ch16-s07-p071", "type": "text", "text": "離れた指が、机の上で止まった。ペンの横。動かない。"}, {"id": "ch16-s07-p072", "type": "text", "text": "他者を頼ること。それは霜月氷華という人間にとって、最も遠い場所にある行為だった。五年間一人で凍らせてきた。一人で設計し、一人で計測し、一人で完璧であろうとした。完璧でなければ声を上げる資格がないと思っていた。完璧であることが、あの子供への——"}, {"id": "ch16-s07-p073", "type": "text", "text": "「手を貸してくれないか」と言った。今日。朝霧に。あの一文を声にした時、喉の筋肉がいつもと違う使い方をした。命令の筋肉ではなかった。依頼の筋肉。五年間使っていなかった筋肉。"}, {"id": "ch16-s07-p074", "type": "text", "text": "お前が隣にいてくれるなら、と思ったことが——正確に言えば、そう思った自分がいることが——計器では測れなかった。データにならない。訴状にも書けない。論理で組み上げられない。"}, {"id": "ch16-s07-p075", "type": "text", "text": "氷華はペンを握り直した。"}, {"id": "ch16-s07-p076", "type": "text", "text": "指に力が戻った。条文を書く。第三十七条の但し書き。正確に。一字の誤りもなく。訴状は完璧でなければならない。完璧でなければ織部は潰す。完璧であることでしか、あの子供に報いる方法を知らない。"}, {"id": "ch16-s07-p077", "type": "text", "text": "しかし。"}, {"id": "ch16-s07-p078", "type": "text", "text": "完璧な訴状の余白に、朝霧の手の温度が残っていた。傷のない手が、傷だらけの自分の手を握った時の、あの力。共に握る力。"}, {"id": "ch16-s07-p079", "type": "text", "text": "ペンが動いた。条文が紙の上に正確に転写されていく。書きながら、今夜はもう一つのことを認めた。認めたが、記録はしなかった。訴状の余白にも、手帳にも、どこにも書かなかった。"}, {"id": "ch16-s07-p080", "type": "text", "text": "朝霧の存在が、欲しい。"}, {"id": "ch16-s07-p081", "type": "text", "text": "その一文は氷華の頭の中にだけあり、紙の上には第三十七条但し書きの正確な引用だけが残った。"}, {"id": "ch16-s07-p082", "type": "text", "text": "* * *"}, {"id": "ch16-s07-p083", "type": "text", "text": "天蓋の間に、鐘の音がなかった。"}, {"id": "ch16-s07-p084", "type": "text", "text": "音がないことを、すみれの体が知っていた。胸の真ん中——鐘と繋がっている場所が、空洞になっている。いつもは鐘の振動が体を通り抜けていて、それがすみれの呼吸と同じだった。今は振動が遠い。半分だけ届いて、半分が途中で消えている。"}, {"id": "ch16-s07-p085", "type": "text", "text": "天蓋のガラスの向こうに、星がなかった。曇りの夜。すみれは毛布の中にいた。れんが朝、掛け直してくれた毛布。毛布の端に、れんの匂いが残っていた。鐘の匂いとは違う。人の匂い。すみれが持っていない匂い。"}, {"id": "ch16-s07-p086", "type": "text", "text": "左手の甲を見た。暗くて見えなかった。見えなくても、朝れんが握ってくれた場所がわかった。そこだけ温かかった。すみれの体は冷たい。全部冷たい。でもれんが触ったところだけ、温度が残っている。鐘の力ではない。すみれの力でもない。名前を知らない力。"}, {"id": "ch16-s07-p087", "type": "text", "text": "——れん。"}, {"id": "ch16-s07-p088", "type": "text", "text": "声にした。天蓋の間には誰もいない。声にしてもいい。小さな声が、ガラスの天蓋に触れて、戻ってこなかった。壁が音を返す力を失くしている。すみれと同じだった。"}, {"id": "ch16-s07-p089", "type": "text", "text": "すみれは知っている。鐘が止まったら何が起きるかを。最初から知っている。島のこと。鐘のこと。消えたものたちのこと。全部知っている。でも言葉が足りない。れんに伝えたい。伝えたいのに、口から出るのはいつも、半分だけの言葉。"}, {"id": "ch16-s07-p090", "type": "text", "text": "首筋の残響紋が弱く光った。紫の光が毛布の白い布を染めている。すみれの体に広がっていく紋様は、鐘が終わろうとしている印。鐘が終われば、すみれも終わる。怖くはなかった。すみれは鐘の一部だから、鐘と一緒に終わることは自然なことだった。"}, {"id": "ch16-s07-p091", "type": "text", "text": "怖くないはずだった。"}, {"id": "ch16-s07-p092", "type": "text", "text": "なのに左手の甲が温かくて、その温かさを手放すことが——怖い、と思った。怖いという言葉が、胸の空洞に落ちて、反響した。鐘の代わりに。"}, {"id": "ch16-s07-p093", "type": "text", "text": "目を閉じた。"}, {"id": "ch16-s07-p094", "type": "text", "text": "天蓋の間はすみれの髪の光だけが照らしていた。淡い紫の粒子が、暗い部屋の中に散っている。鐘の力で光る粒子。弱い光。でもまだ消えていない。"}, {"id": "ch16-s07-p095", "type": "text", "text": "すみれは、ここにいる。れんが来てくれるまで、ここにいる。"}]}, {"chapter": 16, "chapterTitle": "誰の側に", "scene": 8, "sceneTitle": "分岐点――誰の側に", "wordCount": "約6,200字", "paragraphs": [{"id": "ch16-s08-p001", "type": "text", "text": "七時。"}, {"id": "ch16-s08-p002", "type": "text", "text": "目を開けた時、天井が白かった。昨夜の暗い天井ではなかった。窓の障子の隙間から入る光が、天井板の木目を一本ずつ照らしていた。十二月の朝の光。黄色みの薄い、冬の白。"}, {"id": "ch16-s08-p003", "type": "text", "text": "体を起こした。布団が体から滑り落ちた。冷たい空気が胸元に触れた。"}, {"id": "ch16-s08-p004", "type": "text", "text": "五箇所が、鳴っていた。"}, {"id": "ch16-s08-p005", "type": "text", "text": "鳩尾の上。灼熱。鳴海さんの「歌いたい」が昨夜の眠りを越えて、まだそこにある。肋骨の内側。亀裂の入った氷の石。温かさと冷たさが混在したまま固まっている。耳の奥。音。篠宮さんの「何なのだろう」が止まない。背中の奥。二人分の方向。霜月さんの覚悟と俺の「やります」が同じ方角を向いている。左手の甲。冷たさ。すみれの「じかんがない」が指の皮膚の下に沈んでいる。"}, {"id": "ch16-s08-p006", "type": "text", "text": "五つが同時に鳴っている。昨夜と同じだ。同じだが、質が変わっていた。昨夜は五つの音が圧力だった。溢れて、涙になった。今朝の五つは——圧力ではない。方角だった。五つの痛みが、五つの方角を指していた。"}, {"id": "ch16-s08-p007", "type": "text", "text": "立ち上がった。着替えた。顔を洗った。水が冷たかった。タオルで拭いた。鏡の中の顔を見た。額の傷跡が前髪の隙間から覗いていた。左手首のブレスレットの編み目に指で触れた。毎朝の動作。毎朝の動作が今朝も動いた。"}, {"id": "ch16-s08-p008", "type": "text", "text": "補佐官舎の戸を開けた。"}, {"id": "ch16-s08-p009", "type": "text", "text": "冬の空気が顔に当たった。吐く息が白い。十二月の朝。空は高く、雲が薄い。昨夜の曇天が割れて、冬の青が見えていた。残響灯はほとんど消えていた。点いている灯りも透けるように淡い。陽の光が石畳の上に影を落としている。冬の陽は低い。影が長い。俺の影が石畳の上に細く伸びて、中庭の方角を指していた。"}, {"id": "ch16-s08-p010", "type": "text", "text": "足が動いた。"}, {"id": "ch16-s08-p011", "type": "text", "text": "中庭。石畳を踏んだ。冬の石は靴底を通しても冷たかった。吐く息の白さが顔の前で散る。石畳の隙間に霜が降りていた。十二月の霜。四月には桜の花弁が散っていた場所に、今は氷の結晶がある。"}, {"id": "ch16-s08-p012", "type": "text", "text": "残響桜が見えた。"}, {"id": "ch16-s08-p013", "type": "text", "text": "中庭の中央。一本の桜。十二月の桜は裸だった。葉を全て落としている。花弁もない。四月の薄紫は消え、七月の濃い緑も消え、十月の赤も黄も消え、十二月には何も残っていなかった。幹と枝だけの木。灰色の幹。灰褐色の枝。冬空の青を背景にして、枝の一本一本が細い線を引いていた。"}, {"id": "ch16-s08-p014", "type": "text", "text": "根元まで歩いた。"}, {"id": "ch16-s08-p015", "type": "text", "text": "幹に触れた。右手の掌で。"}, {"id": "ch16-s08-p016", "type": "text", "text": "冷たかった。十二月の幹は冷たい。石より冷たい。金属よりは温かい。木の表面の皺に指先が沿った。樹皮の凹凸。乾いている。冬の樹皮は水を含んでいない。表面だけを見れば、枯れた木と区別がつかなかった。"}, {"id": "ch16-s08-p017", "type": "text", "text": "しかし——幹の奥に、温度があった。"}, {"id": "ch16-s08-p018", "type": "text", "text": "表面は冷たい。けれど掌を押しつけたまま五秒待つと、樹皮の下から微かな温もりが返ってきた。木が生きている温度。根から吸い上げた水が幹を通過する温度。冬の間も根は凍っていない。地表の下で水を吸い、幹に送っている。地上に見える部分は全てを失った姿をしているが、地下では止まっていない。"}, {"id": "ch16-s08-p019", "type": "text", "text": "枝を見上げた。"}, {"id": "ch16-s08-p020", "type": "text", "text": "裸の枝。葉のない枝。花のない枝。折れてはいなかった。昨夜の縁蝕波にも折れなかった。細い枝の先端まで、一本も折れていなかった。"}, {"id": "ch16-s08-p021", "type": "text", "text": "四月に、俺はこの木の下で目を覚ました。"}, {"id": "ch16-s08-p022", "type": "text", "text": "記憶がなかった。名前だけがあった。朝霧蓮。自分で選んだ名前。それ以外は何も持っていなかった。残響桜は花が咲いていた。薄紫の花弁が風に散っていた。花弁が額に落ちた。冷たくも温かくもない感触を「きれいだ」と処理する回路がまだなかった。花弁を見て、「花だ」と記録しただけだった。"}, {"id": "ch16-s08-p023", "type": "text", "text": "九ヶ月前の俺は、ここに立っていた。"}, {"id": "ch16-s08-p024", "type": "text", "text": "九ヶ月後の俺も、ここに立っている。"}, {"id": "ch16-s08-p025", "type": "text", "text": "四月の桜は満開だった。十二月の桜は裸木だ。四月の俺は空だった。十二月の俺は——五箇所が痛い。"}, {"id": "ch16-s08-p026", "type": "text", "text": "幹から手を離した。"}, {"id": "ch16-s08-p027", "type": "text", "text": "掌に樹皮の跡が残っていた。冬の木の温度が手のひらに薄く残っていた。"}, {"id": "ch16-s08-p028", "type": "text", "text": "この木は、全部失くしても立っている。"}, {"id": "ch16-s08-p029", "type": "text", "text": "花を失くした。葉を失くした。色を失くした。冬の風に晒されて、残ったのは幹と枝だけだ。幹と枝だけで立っている。折れずに立っている。そして根は止まっていない。地下で水を吸い続けている。春が来れば、また咲く。全部失くしても、春を待つ力が根に残っている。"}, {"id": "ch16-s08-p030", "type": "text", "text": "俺は——。"}, {"id": "ch16-s08-p031", "type": "text", "text": "鳩尾の上が灼けた。鳴海さん。歌いたいと言った人。命を削ってでも歌う人。震える手を見て「震えてますね」と微笑んだ人。その灼熱が——方角を持っていた。医務室の方角。"}, {"id": "ch16-s08-p032", "type": "text", "text": "肋骨の内側が鳴った。燈花。どこに帰ればいいのと呟いた人。故郷が消えても三十人を導いて帰ってきた人。肩に触れた時の小ささが手のひらに残っている。その鳴りが——南門の方角を指していた。"}, {"id": "ch16-s08-p033", "type": "text", "text": "耳の奥が響いた。篠宮さん。ここにいるのかどうかわからなくなると言った人。震える手でペンを離さなかった人。記録がここにあると指差した時の「ありがとうございます」が耳の壁に張りついている。その響きが——図書館の方角を向いていた。"}, {"id": "ch16-s08-p034", "type": "text", "text": "背中の奥が共鳴した。霜月さん。手を貸してくれないかと初めて言った人。五年間の沈黙を破ると決めた人。傷だらけの手を差し出した人。その共鳴が——鐘鋳塔の方角に引かれていた。"}, {"id": "ch16-s08-p035", "type": "text", "text": "左手の甲が冷たい。すみれ。時間がないと言った人。星を数える人。鐘が教えてくれたと微笑む人。冷たさは——方角を持たなかった。天蓋の間にいるすみれの冷たさは、方角ではなく、全体にあった。空気のように。鐘の余韻のように。"}, {"id": "ch16-s08-p036", "type": "text", "text": "五箇所。五つの方角。五人が、体の中で同時に名前を呼んでいる。"}, {"id": "ch16-s08-p037", "type": "text", "text": "残響桜の裸の枝の下で、俺は目を閉じた。"}, {"id": "ch16-s08-p038", "type": "text", "text": "全員を助けたい。"}, {"id": "ch16-s08-p039", "type": "text", "text": "その想いは嘘ではなかった。嘘ではないことを、体の五箇所が証明していた。鳩尾が灼ければ灼けるほど、鳴海さんの傍にいたい。肋骨が鳴れば鳴るほど、燈花のそばにいたい。耳が響けば響くほど、篠宮さんの真実を知りたい。背中が共鳴すればするほど、霜月さんと並んで歩きたい。左手が冷たければ冷たいほど、すみれのそばにいたい。"}, {"id": "ch16-s08-p040", "type": "text", "text": "全部が本物だ。五つの痛みは全て本物だ。"}, {"id": "ch16-s08-p041", "type": "text", "text": "しかし。"}, {"id": "ch16-s08-p042", "type": "text", "text": "全員を同時に助けることは、できない。"}, {"id": "ch16-s08-p043", "type": "text", "text": "五つの方角は全て別の場所を指している。俺の体は一つしかない。一つの体で五つの方角に同時に走ることは、できない。"}, {"id": "ch16-s08-p044", "type": "text", "text": "昨夜、それを認めた。認めて、泣いた。泣いた後に決めた。選ぶ、と。"}, {"id": "ch16-s08-p045", "type": "text", "text": "誰かの側に立つということは、他の誰かの側に立てないということだ。"}, {"id": "ch16-s08-p046", "type": "text", "text": "それを引き受ける。"}, {"id": "ch16-s08-p047", "type": "text", "text": "四月の俺なら選ばなかった。入力を受け、判断し、出力する。五つの入力に均等に応答する。模倣の回路は均等が得意だ。誰にも等距離でいることは、模倣者にとって最も負荷の少ない状態だった。"}, {"id": "ch16-s08-p048", "type": "text", "text": "十二月の俺は、痛い。五箇所が同時に痛い。痛みを均等に処理することはできない。処理しようとすれば圧力になり、容量を超える。超えた分は涙になって溢れる。それを昨夜、知った。"}, {"id": "ch16-s08-p049", "type": "text", "text": "均等は無力だ。全方位に半歩ずつ進んで、どこにも辿り着かない。"}, {"id": "ch16-s08-p050", "type": "text", "text": "目を開けた。"}, {"id": "ch16-s08-p051", "type": "text", "text": "残響桜の幹が目の前にあった。灰色の樹皮。冬の裸木。全てを失くして、まだ立っている木。"}, {"id": "ch16-s08-p052", "type": "text", "text": "俺も立っている。"}, {"id": "ch16-s08-p053", "type": "text", "text": "記憶を失くした。感情の回路を失くした。九ヶ月かけて取り戻したものは——五箇所の痛みだった。取り戻したのが喜びではなく痛みだったことに、不満はない。痛みは本物の証拠だ。模倣は痛まない。痛みがあるから、俺は今、選べる。"}, {"id": "ch16-s08-p054", "type": "text", "text": "風が吹いた。"}, {"id": "ch16-s08-p055", "type": "text", "text": "冬の風。残響桜の裸の枝が揺れた。枝の先端が空を掻いた。音はなかった。葉がないから風の音が鳴らない。音のない風の中で、枝だけが動いていた。"}, {"id": "ch16-s08-p056", "type": "text", "text": "俺は自分の意志で動く。"}, {"id": "ch16-s08-p057", "type": "text", "text": "それが、この島で過ごした九ヶ月を通じて、俺が辿り着いた場所だった。模倣ではない。観察でもない。保留でもない。自分の体の中にある痛みに従って、自分の足で、一つの方角に歩く。"}, {"id": "ch16-s08-p058", "type": "text", "text": "歩いた先にいる人の側に、立つ。"}, {"id": "ch16-s08-p059", "type": "text", "text": "選ばなかった人の痛みは消えない。消えないまま抱える。それでも歩く。"}, {"id": "ch16-s08-p060", "type": "text", "text": "風が止んだ。"}, {"id": "ch16-s08-p061", "type": "text", "text": "鐘が鳴った。"}, {"id": "ch16-s08-p062", "type": "text", "text": "正規の時刻ではなかった。七時の鐘は既に鳴り終えている。不規則な鐘。音程が半音低い。周波数が揺れている。鐘鋳塔の方角から、割れかけた音が朝の中庭に届いた。"}, {"id": "ch16-s08-p063", "type": "text", "text": "足元の石畳が震えた。微かだが、確かな振動。昨夜で終わったはずの蝕域が、朝を待たずに動いている。"}, {"id": "ch16-s08-p064", "type": "text", "text": "残響桜の枝が静止した。冬の朝の光が枝の先端を照らしていた。枝の向こうに冬の空がある。薄い青。昨夜の曇天を割った青。"}, {"id": "ch16-s08-p065", "type": "text", "text": "体が応えた。"}, {"id": "ch16-s08-p066", "type": "text", "text": "五箇所のうち——一箇所が、他より強く鳴った。"}, {"id": "ch16-s08-p067", "type": "divider", "text": "---"}, {"id": "ch16-s08-p068", "type": "choice_header", "text": "【選択肢】\n▶ 千歳のそばにいる\n▶ 雫の真実に向き合う\n▶ 燈花と外円区へ行く\n▶ 氷華と上層部に立ち向かう"}, {"id": "ch16-s08-p069", "type": "divider", "text": "---"}, {"id": "ch16-s08-p070", "type": "text", "text": "## ▶ 千歳のそばにいる"}, {"id": "ch16-s08-p071", "type": "text", "text": "鳩尾の上が、灼けていた。"}, {"id": "ch16-s08-p072", "type": "text", "text": "他の四箇所も鳴っていた。肋骨の内側も、耳の奥も、背中の奥も、左手の甲も。五つは全部本物だった。全部が本物であることを認めた上で——鳩尾の灼熱が、一番強かった。"}, {"id": "ch16-s08-p073", "type": "text", "text": "歌わなければ島が持たない。しかし歌えば千歳が壊れる。"}, {"id": "ch16-s08-p074", "type": "text", "text": "千歳。鳴海千歳。"}, {"id": "ch16-s08-p075", "type": "text", "text": "初めて名前で呼んだ。口の中だけで。声にはしなかった。鳴海さんではなく、千歳。その二文字が鳩尾の灼熱を通過して、胸の奥に落ちた。"}, {"id": "ch16-s08-p076", "type": "text", "text": "守りたい。"}, {"id": "ch16-s08-p077", "type": "text", "text": "足が動いた。中庭を横切り、石畳を踏み、教室棟の廊下に入った。廊下の窓から差す冬の光が白い。消毒液の匂いが遠くから届いた。"}, {"id": "ch16-s08-p078", "type": "text", "text": "残り四箇所が背中の側で鳴っていた。耳の奥の篠宮さんの音。背中の霜月さんの共鳴。肋骨の燈花の氷。左手のすみれの冷たさ。四つが鳴っている。鳴っている音を聞きながら、俺は歩いた。四つの音が小さくなるのではなかった。四つの音は変わらない。変わらないまま、鳩尾の灼熱だけが一歩ごとに近づいていた。"}, {"id": "ch16-s08-p079", "type": "text", "text": "医務室の扉の前に立った。"}, {"id": "ch16-s08-p080", "type": "text", "text": "磨りガラスの向こうに光がある。扉を開けた。"}, {"id": "ch16-s08-p081", "type": "text", "text": "白いシーツ。白い壁。冬の光。奥のベッドに人がいた。蒼白い顔。閉じた瞼。いろはが隣の椅子で首を傾けて眠っていた。"}, {"id": "ch16-s08-p082", "type": "text", "text": "ベッドの傍の椅子に座った。空いていた。いろはの椅子とベッドの間の椅子。座った時、椅子の脚が床に小さな音を立てた。"}, {"id": "ch16-s08-p083", "type": "text", "text": "鳴海さんの瞼が動いた。"}, {"id": "ch16-s08-p084", "type": "text", "text": "ゆっくりと開いた。薄い琥珀色の瞳が天井を見て、それから横に動いて、俺を見つけた。"}, {"id": "ch16-s08-p085", "type": "text", "text": "「蓮さん……？」"}, {"id": "ch16-s08-p086", "type": "text", "text": "掠れた声。紙を折るより薄い音。しかし微笑みが浮かんでいた。蒼白い顔の中に。琥珀の残滓のような瞳の奥に。いつもの穏やかな光。"}, {"id": "ch16-s08-p087", "type": "text", "text": "「俺はここにいる」"}, {"id": "ch16-s08-p088", "type": "text", "text": "声が出た。昨夜から決めていた言葉ではなかった。この瞬間に出た声だった。"}, {"id": "ch16-s08-p089", "type": "text", "text": "「鳴海さんの歌を、最後まで聴く」"}, {"id": "ch16-s08-p090", "type": "text", "text": "鳴海さんの瞳が揺れた。微笑みが深くなった。深くなった微笑みの端に、何かが光った。涙ではなかった。涙の手前にあるもの。瞳の表面に薄い膜が一枚だけ増えた。"}, {"id": "ch16-s08-p091", "type": "text", "text": "鳩尾の上が灼けていた。灼けたまま、ここにいる。"}, {"id": "ch16-s08-p092", "type": "text", "text": "——ここから、物語は分岐する。千歳ルートへ続く。"}, {"id": "ch16-s08-p093", "type": "divider", "text": "---"}, {"id": "ch16-s08-p094", "type": "text", "text": "## ▶ 雫の真実に向き合う"}, {"id": "ch16-s08-p095", "type": "text", "text": "耳の奥が、鳴っていた。"}, {"id": "ch16-s08-p096", "type": "text", "text": "他の四箇所も鳴っていた。鳩尾の灼熱も、肋骨の氷も、背中の共鳴も、左手の冷たさも。全部が本物だった。全部が本物であることを認めた上で——耳の奥の音が、一番近かった。"}, {"id": "ch16-s08-p097", "type": "text", "text": "篠宮さんの体が透けた。あれは見間違いではない。何かがおかしい。何かが起きている。"}, {"id": "ch16-s08-p098", "type": "text", "text": "篠宮さん。篠宮雫。"}, {"id": "ch16-s08-p099", "type": "text", "text": "名前が耳の位置で反復していた。引っかかりでも確信でもない。もっと手前の、もっと根本的な音。この人が何者であるかを、俺は知らなければならない。"}, {"id": "ch16-s08-p100", "type": "text", "text": "足が動いた。中庭を出て、図書館の方角へ歩いた。朝の図書館は静かだった。受付に人はいない。臨時休館のまま。しかし二階の書架の奥に——灯りがある。"}, {"id": "ch16-s08-p101", "type": "text", "text": "残り四箇所が体の各所で鳴っていた。鳩尾の鳴海さんの灼熱。肋骨の燈花の氷。背中の霜月さんの共鳴。左手のすみれの冷たさ。四つが鳴りながら、耳だけが一歩ごとに明瞭になっていった。"}, {"id": "ch16-s08-p102", "type": "text", "text": "書架の列を抜けた。記録室の扉が十センチ開いていた。いつもの幅。"}, {"id": "ch16-s08-p103", "type": "text", "text": "扉を押した。"}, {"id": "ch16-s08-p104", "type": "text", "text": "四畳半の部屋。窓から差す朝の光。机の上のメモ帳とペン。椅子に座っている人。黒いボブカットの後頭部。首から下がった銀の鍵。"}, {"id": "ch16-s08-p105", "type": "text", "text": "篠宮さんが振り返った。墨色の瞳が俺を見た。"}, {"id": "ch16-s08-p106", "type": "text", "text": "「朝霧さん？」"}, {"id": "ch16-s08-p107", "type": "text", "text": "声は薄かった。しかし焦点が合っていた。俺を見ていた。"}, {"id": "ch16-s08-p108", "type": "text", "text": "手を伸ばした。篠宮さんの手を取った。ペンを持っていない左手。指に触れた。冷たかった。記録室の冷たさではなかった。篠宮さんの体温そのものが低い。"}, {"id": "ch16-s08-p109", "type": "text", "text": "触れた。指が確かにそこにあった。"}, {"id": "ch16-s08-p110", "type": "text", "text": "「篠宮さん。お前のことを、全部知りたい。お前が何者でも」"}, {"id": "ch16-s08-p111", "type": "text", "text": "篠宮さんの目がわずかに見開かれた。長い瞬き。目を閉じて、開いた時、墨色の瞳の表面に光の反射率の変化があった。昨日と同じ。涙の手前。"}, {"id": "ch16-s08-p112", "type": "text", "text": "「……全部、ですか」"}, {"id": "ch16-s08-p113", "type": "text", "text": "声が小さかった。壁に届かない声。俺と篠宮さんの間の空気だけを振動させる音量。"}, {"id": "ch16-s08-p114", "type": "text", "text": "耳の奥の音が変わっていた。引っかかりでも確信でも不安でもない。名前をつけるなら——約束の音に、近かった。"}, {"id": "ch16-s08-p115", "type": "text", "text": "——ここから、物語は分岐する。雫ルートへ続く。"}, {"id": "ch16-s08-p116", "type": "divider", "text": "---"}, {"id": "ch16-s08-p117", "type": "text", "text": "## ▶ 燈花と外円区へ行く"}, {"id": "ch16-s08-p118", "type": "text", "text": "肋骨の内側が、鳴っていた。"}, {"id": "ch16-s08-p119", "type": "text", "text": "他の四箇所も鳴っていた。鳩尾の灼熱も、耳の奥の音も、背中の共鳴も、左手の冷たさも。全部が本物だった。全部が本物であることを認めた上で——肋骨の内側の亀裂が、一番深かった。"}, {"id": "ch16-s08-p120", "type": "text", "text": "外円区の人たちが助けを求めている。燈花の故郷が消えた。燈花の足場がない。"}, {"id": "ch16-s08-p121", "type": "text", "text": "燈花。"}, {"id": "ch16-s08-p122", "type": "text", "text": "名前を呼ぶだけで、肋骨の内側の氷の石が震えた。亀裂から温かいものが滲んでいた。昨夜と同じ。滲んでいるから痛い。痛いから行く。"}, {"id": "ch16-s08-p123", "type": "text", "text": "足が動いた。中庭を出て、南門の方角へ歩いた。朝の石畳に昨日の泥の足跡がまだ残っていた。外円区から来た人たちの靴底が運んだ赤い土。"}, {"id": "ch16-s08-p124", "type": "text", "text": "残り四箇所が体の各所で鳴っていた。鳩尾の鳴海さん。耳の篠宮さん。背中の霜月さん。左手のすみれ。四つが鳴りながら、肋骨だけが歩くたびに重く響いた。"}, {"id": "ch16-s08-p125", "type": "text", "text": "講堂の前を通り過ぎた。南門は近い。"}, {"id": "ch16-s08-p126", "type": "text", "text": "門の手前に人がいた。"}, {"id": "ch16-s08-p127", "type": "text", "text": "燈花だった。"}, {"id": "ch16-s08-p128", "type": "text", "text": "避難民の世話をしていた。毛布を配っている。昨夜と同じ服。着替えていない。泥がまだ残っている。しかし背筋は伸びていた。蒼白い顔に笑顔を貼りつけて、老人の肩に毛布をかけていた。"}, {"id": "ch16-s08-p129", "type": "text", "text": "「燈花」"}, {"id": "ch16-s08-p130", "type": "text", "text": "呼んだ。"}, {"id": "ch16-s08-p131", "type": "text", "text": "燈花が振り返った。琥珀色の瞳が俺を見た。笑顔が一瞬剥がれた。素の顔が覗いた。蒼白くて、目の下に隈があって、唇が乾いている。その顔がすぐに笑顔に戻ろうとして——戻りきれなかった。"}, {"id": "ch16-s08-p132", "type": "text", "text": "「蓮くん……？ こんな朝早くに、なんで」"}, {"id": "ch16-s08-p133", "type": "text", "text": "声が掠れていた。昨夜よりさらに渇いている。水を飲んでいないのだろう。"}, {"id": "ch16-s08-p134", "type": "text", "text": "「燈花。俺も行く。外円区に。お前と一緒に」"}, {"id": "ch16-s08-p135", "type": "text", "text": "燈花の目が見開かれた。"}, {"id": "ch16-s08-p136", "type": "text", "text": "琥珀色の瞳の中で何かが動いた。止まっていたものが動いた。昨夜、涙が出なかった目。泣く対象の形が消えて涙が出なくなっていた目。その目の中に——水の膜が張った。"}, {"id": "ch16-s08-p137", "type": "text", "text": "泣き笑いだった。"}, {"id": "ch16-s08-p138", "type": "text", "text": "涙が一筋、右の頬を降りた。泥の残った頬の上を。同時に口元が歪んで、笑おうとしていた。笑いと涙が同時に来て、どちらにもなりきれない顔。"}, {"id": "ch16-s08-p139", "type": "text", "text": "「……ばか。なんで」"}, {"id": "ch16-s08-p140", "type": "text", "text": "声が震えていた。昨夜は震えなかった声が、今朝は震えていた。手が上がった。右手。昨夜体の横で震えていた手。その手が俺の胸元を一度だけ押した。弱い力。押すというより触れた。"}, {"id": "ch16-s08-p141", "type": "text", "text": "肋骨の内側が温かかった。氷の石の亀裂から滲んでいたものが、広がっていた。"}, {"id": "ch16-s08-p142", "type": "text", "text": "——ここから、物語は分岐する。燈花ルートへ続く。"}, {"id": "ch16-s08-p143", "type": "divider", "text": "---"}, {"id": "ch16-s08-p144", "type": "text", "text": "## ▶ 氷華と上層部に立ち向かう"}, {"id": "ch16-s08-p145", "type": "text", "text": "背中の奥が、共鳴していた。"}, {"id": "ch16-s08-p146", "type": "text", "text": "他の四箇所も鳴っていた。鳩尾の灼熱も、肋骨の氷も、耳の奥の音も、左手の冷たさも。全部が本物だった。全部が本物であることを認めた上で——背中の共鳴が、一番確かだった。"}, {"id": "ch16-s08-p147", "type": "text", "text": "上層部が情報を握り潰している。また同じことが起きる。五年前と同じことが。"}, {"id": "ch16-s08-p148", "type": "text", "text": "霜月さん。"}, {"id": "ch16-s08-p149", "type": "text", "text": "昨夜の「明日の朝、八時に来い」が背中の奥で反復していた。命令の中に「来てくれ」が混じっていた声。傷だらけの手を差し出した人。一人で完璧であろうとした人が、初めて「手を貸してくれないか」と言った人。"}, {"id": "ch16-s08-p150", "type": "text", "text": "足が動いた。中庭を出て、鐘鋳塔へ向かった。八時にはまだ早い。早いが、足が止まらなかった。"}, {"id": "ch16-s08-p151", "type": "text", "text": "残り四箇所が体の各所で鳴っていた。鳩尾の鳴海さん。肋骨の燈花。耳の篠宮さん。左手のすみれ。四つが鳴りながら、背中だけが歩くたびに方向を示していた。"}, {"id": "ch16-s08-p152", "type": "text", "text": "鐘鋳塔の石段を上った。一階。二階。三階。研究室の鉄扉の下から光が漏れていた。昨夜と同じ。この人は帰っていない。"}, {"id": "ch16-s08-p153", "type": "text", "text": "扉を叩いた。二度。"}, {"id": "ch16-s08-p154", "type": "text", "text": "「入れ」"}, {"id": "ch16-s08-p155", "type": "text", "text": "短い声。昨夜と同じ命令の形。しかし声の底に——待っていた人間の温度があった。"}, {"id": "ch16-s08-p156", "type": "text", "text": "扉を開けた。"}, {"id": "ch16-s08-p157", "type": "text", "text": "霜月さんが机に向かっていた。白いコートの袖口に新しいインクの染みが増えている。紅茶の冷えた四杯目がある。訴状の紙が机の上に広がっていた。"}, {"id": "ch16-s08-p158", "type": "text", "text": "俺を見た。ラベンダーの瞳。硬い目。しかし昨夜と同じ——壁ではなく骨格の硬さ。隣に立つ人間の存在を許容する硬さ。"}, {"id": "ch16-s08-p159", "type": "text", "text": "霜月さんの隣の椅子に座った。昨夜座った椅子ではなかった。訴状の横。作業する位置。"}, {"id": "ch16-s08-p160", "type": "text", "text": "「氷華さん」"}, {"id": "ch16-s08-p161", "type": "text", "text": "声が出た。"}, {"id": "ch16-s08-p162", "type": "text", "text": "出てから気づいた。霜月さん、ではなかった。氷華さん、と言った。言おうとして言ったのではなかった。口が先に動いた。背中の奥の共鳴が名前を選んだ。"}, {"id": "ch16-s08-p163", "type": "text", "text": "霜月さんの——氷華さんの瞳が、一瞬だけ広がった。"}, {"id": "ch16-s08-p164", "type": "text", "text": "ラベンダーの色の中の硬さが、半秒だけ消えた。消えた場所に何があったかは読み取れなかった。半秒では足りなかった。半秒の後、硬さが戻った。戻った硬さの中に——何かが混じっていた。昨夜の「笑みの一歩手前」とも違う。もっと小さな変化。瞳の奥の光の角度が、一度だけ変わった。"}, {"id": "ch16-s08-p165", "type": "text", "text": "「……手を貸す。最後まで」"}, {"id": "ch16-s08-p166", "type": "text", "text": "霜月さんが俺を見ていた。三秒。長い三秒だった。"}, {"id": "ch16-s08-p167", "type": "text", "text": "頷いた。"}, {"id": "ch16-s08-p168", "type": "text", "text": "一度。深く。顎が下がり、上がるまでに一秒。霜月氷華が頷くのにかける時間としては長かった。"}, {"id": "ch16-s08-p169", "type": "text", "text": "「八時だと言ったはずだが」"}, {"id": "ch16-s08-p170", "type": "text", "text": "声は硬かった。いつもの命令の声。しかし——命令の裏に、さっきの半秒が隠れていた。"}, {"id": "ch16-s08-p171", "type": "text", "text": "背中の奥が響いていた。二人分の方向が、一つの椅子の上で重なっていた。"}, {"id": "ch16-s08-p172", "type": "text", "text": "——ここから、物語は分岐する。氷華ルートへ続く。"}]}];